[9130] = { ["id"] = 9130, ["name"] = "Goods from Silvermoon City", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3430, ["mapID"] = 94, ["storyline"] = { 9130 }, ["series"] = { 9133, 9134, 9135 }, ["description"] = "Welcome volunteer! We're running low on supplies here, but Silvermoon has promised us materiel assistance. That's where you come in. Take this list over to Skymaster Brightdawn . He'll have further instructions for you on how best to get up to Silvermoon City.", ["objectivesText"] = "Deliver Sathiel's Request to Skymaster Brightdawn in Fairbreeze Village. Progress: Yes, what's this?", ["rewardXP"] = 50, ["rewardItems"] = { 22549 }, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 16261, ["x"] = 0.436, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 44036, ["x"] = 0.44, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 94 }, ["zone"] = { 3430 } }, ["questType"] = "standard" },
[9134] = { ["id"] = 9134, ["name"] = "Skymistress Gloaming", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 9134 }, ["series"] = { 9130, 9133, 9135 }, ["description"] = "It doesn't look as if you have a cart or a beast of burden with you, so I'd better send you back only with what you can carry. If you've spoken with Skymaster Brightdawn at Fairbreeze Village, then you should get this to Sathiel as soon as possible by flying back. Take these goods for final inspection to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate.", ["objectivesText"] = "Bring Sathiel's Goods to Skymistress Gloaming just outside Silvermoon City's Shepherd's Gate. Progress: Wow, that box of goods you have there looks heavy! You want to load that up on one of my flying beauties?", ["rewardXP"] = 50, ["rewardItems"] = { 22550 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 16191, ["x"] = 0.540286, ["y"] = 0.672 } }, ["ends"] = { { ["mapID"] = 94, ["npcID"] = 16192, ["x"] = 0.544, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.540286, ["y"] = 0.672 }, ["mapCandidates"] = { ["npc"] = { 94, 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard" },
[9280] = { ["id"] = 9280, ["name"] = "Replenishing the Healing Crystals", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 11 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6456, ["mapID"] = 97, ["storyline"] = { 9279, 9280, 9283, 9293, 9294, 9303, 9305, 9309, 9311, 9312, 9313, 9314, 9369, 9371, 9409, 9798, 9799, 10302, 10303, 10304, 37444, 37445 }, ["series"] = { 9279, 9369, 9409 }, ["description"] = "Our immediate concern is the depleted state of our healing crystals. We must replenish them quickly! Unfortunately, the only way to do this at this point is to extract the blood from the local vale moths. Their blood will make for a suitable substitute. The moths can be found in many places around the vale, but they are mostly concentrated in the northwest.", ["objectivesText"] = "Acquire 6 Vials of Moth Blood from the nearby Vale Moths and give them to Proenitus at the Crash Site in Ammen Vale . Progress: <name>, have you harvested the necessary moth blood for the healing crystals yet? With survivors scattered all over the vale, time is of the essence!", ["rewardGold"] = 53500, ["rewardXP"] = 250, ["rewardItems"] = { 22889, 24129, 24130, 24131, 131819 }, ["starts"] = { { ["mapID"] = 97, ["npcID"] = 16477, ["x"] = 0.804, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 97, ["npcID"] = 16477, ["x"] = 0.804, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 97, ["source"] = "quest_giver", ["x"] = 0.804, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 97 }, ["zone"] = { 6456 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 468, ["questLines"] = { { ["id"] = 5404, ["name"] = "Ammen Vale", ["orderIndex"] = 1, ["flags"] = 0 } } },
[10588] = { ["id"] = 10588, ["name"] = "The Cipher of Damnation", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 10458, 10480, 10481, 10513, 10514, 10515, 10519, 10521, 10522, 10523, 10527, 10528, 10537, 10540, 10541, 10546, 10547, 10550, 10562, 10563, 10564, 10568, 10569, 10570, 10571, 10572, 10573, 10574, 10575, 10576, 10577, 10578, 10579, 10582, 10583, 10585, 10586, 10587, 10588, 10589, 10595, 10596, 10597, 10598, 10599, 10600, 10601, 10602, 10603, 10604, 10606, 10611, 10612, 10613, 10621, 10622, 10623, 10624, 10625, 10626, 10627, 10628, 10633, 10634, 10635, 10636, 10637, 10639, 10640, 10641, 10642, 10643, 10644, 10645, 10646, 10649, 10650, 10651, 10660, 10661, 10662, 10663, 10664, 10665, 10666, 10667, 10668, 10669, 10670, 10672, 10673, 10676, 10677, 10678, 10679, 10683, 10684, 10685, 10686, 10687, 10688, 10689, 10691, 10692, 10705, 10706, 10707, 10744, 10745, 10750, 10751, 10759, 10760, 10761, 10765, 10766, 10767, 10768, 10769, 10772, 10773, 10774, 10775, 10776, 10777, 10778, 10780, 10782, 10804, 10808, 10811, 10814, 10836, 10837, 10854, 10858, 10866, 10870, 10871, 10872, 11012, 11013, 11014, 11019, 11041, 11049, 11052 }, ["description"] = "How many times has this spell been used in the history of our worlds? Undoubtedly, its power for destruction is unparalleled. What you must do now is take the cipher, now made whole, and read from it at the Altar of Damnation - where the memory of Gul'dan stands. What you will see once the words are uttered are the memories left imprinted upon the land. Stand your ground and await the coming of Cyrukh. You must be victorious, <name>. This land cannot withstand another shattering.", ["objectivesText"] = "Use the Cipher of Damnation at the Altar of Damnation to summon Cyrukh the Firelord . Destroy Cyrukh the Firelord and then speak with Earthmender Torlok , also found at the Altar of Damnation. Progress: Is it done?", ["rewardGold"] = 509400, ["rewardXP"] = 5160, ["rewardItems"] = { 30356, 30657, 31036, 31038, 31062, 31071, 31072, 31073, 31074 }, ["starts"] = { { ["mapID"] = 104, ["npcID"] = 21183, ["x"] = 0.582667, ["y"] = 0.403333 } }, ["ends"] = { { ["mapID"] = 104, ["npcID"] = 21024, ["x"] = 0.422, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.403333 }, ["mapCandidates"] = { ["npc"] = { 104 }, ["zone"] = { 3520 } }, ["questType"] = "group", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 104, ["questLines"] = { { ["id"] = 493, ["name"] = "Shadowmoon Valley", ["orderIndex"] = 100, ["flags"] = 0 } } },
