[11095] = { ["id"] = 11095, ["name"] = "Commander Hobb", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 11095 }, ["series"] = { 11094 }, ["description"] = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared. I want you to let them come, <name>. <Thelis nods.> Yes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb . He is standing guard right outside this building.", ["objectivesText"] = "Give the Dragonmaw Flare to Commander Hobb at the Sanctum of the Stars in Shadowmoon Valley . Progress: <Hobb nods.>", ["rewardItems"] = { 32842 }, ["starts"] = { { ["mapID"] = 104, ["npcID"] = 21955, ["x"] = 0.562, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 104, ["npcID"] = 23434, ["x"] = 0.566, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 104 }, ["zone"] = { 3520 } }, ["questType"] = "standard" },
[11100] = { ["id"] = 11100, ["name"] = "Commander Arcus", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3520, ["mapID"] = 104, ["storyline"] = { 11100 }, ["series"] = { 11099 }, ["description"] = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared. I want you to let them come, <name>. <Ceyla nods.> Yes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus . He is standing guard right outside this building.", ["objectivesText"] = "Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha'tar in Shadowmoon Valley . Progress: <Arcus nods.>", ["rewardItems"] = { 32842 }, ["starts"] = { { ["mapID"] = 104, ["npcID"] = 21402, ["x"] = 0.624667, ["y"] = 0.284667 } }, ["ends"] = { { ["mapID"] = 104, ["npcID"] = 23452, ["x"] = 0.636, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 104, ["source"] = "quest_giver", ["x"] = 0.624667, ["y"] = 0.284667 }, ["mapCandidates"] = { ["npc"] = { 104 }, ["zone"] = { 3520 } }, ["questType"] = "standard" },
[11665] = { ["id"] = 11665, ["name"] = "Crocolisks in the City", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 11665 }, ["description"] = "Hello <lad/lass>. I'm glad you've stopped by to talk to this old man--there's trouble back home. A traveling merchant recently sold a batch of baby crocolisks to some gullible children. Crocolisks are wild beasts, and many have escaped and now lurk in city waterways. Grab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me. I'm anxious to see one.", ["objectivesText"] = "Bring a Baby Crocolisk to Old Man Barlo . You can find him fishing northeast of Shattrath City by Silmyr Lake. Progress: Catch any crocs in the sewers yet?", ["rewardItems"] = { 6365, 6529, 33816, 33818, 34864, 35348, 35349, 35350 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.128 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[11666] = { ["id"] = 11666, ["name"] = "Bait Bandits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 11666 }, ["description"] = "You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests. But here's one you haven't heard of: the blackfin darter . The fish is notoriously crafty and difficult to catch. You have to pull your line at the last possible second, because they nibble at the bait before they take it. Drop your line in the rivers of Terokkar and bring me a blackfin darter . Avoid the lakes, as the blackfin only thrive in moving water.", ["objectivesText"] = "Bring a Blackfin Darter to Old Man Barlo . You can find him fishing northeast of Shattrath City by Silmyr Lake. Progress: How's the fishing today, lad?", ["rewardItems"] = { 19969, 27388, 27422, 27425, 27438, 27511, 30632, 33820, 34861, 34863, 34865, 45190, 45196, 45198, 45200, 45202, 45858, 133755 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.128 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[11667] = { ["id"] = 11667, ["name"] = "The One That Got Away", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 11667 }, ["description"] = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand. They grow their entire lives and are well known as fighters. Years ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped. A fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.", ["objectivesText"] = "Catch the World's Largest Mudfish and bring it to Old Man Barlo . You can find him fishing northeast of Shattrath City by Silmyr Lake. Progress: Tell me you caught him. Please tell me you caught that son of a carp.", ["rewardGold"] = 105000, ["rewardXP"] = 1415, ["rewardItems"] = { 8827, 22578, 24479, 25978, 27422, 27435, 27437, 33820, 34861, 34863, 34868, 45858, 85500 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.128 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[11668] = { ["id"] = 11668, ["name"] = "Shrimpin' Ain't Easy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 11668 }, ["description"] = "There's a lot of big fish in the Zangarmarsh lakes. Ever wonder what they eat? Shrimp. Giant freshwater shrimp . The Rokk tells me the dishes you can make with shrimp are nearly endless. But shrimp are too small to catch with a fishing line. So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.", ["objectivesText"] = "Bring 10 Giant Freshwater Shrimp to Old Man Barlo . You can find him fishing northeast of Shattrath City by Silmyr Lake. Progress: What's the catch of the day, lad?", ["rewardItems"] = { 27422, 34863, 34866, 35313, 35350 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.128 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
[11669] = { ["id"] = 11669, ["name"] = "Felblood Fillet", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["requiredProfessions"] = { "fishing" }, ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3519, ["mapID"] = 108, ["storyline"] = { 11669 }, ["description"] = "This old man is going hunting soon. I'm gonna take down a mammoth shark off the coast of Azshara. The thing is, I need a toxin that'll stay on a spear tip while it's underwater. To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper. Such a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley. Bring me back a whopper and I'll be a happy old man.", ["objectivesText"] = "Bring a Monstrous Felblood Snapper to Old Man Barlo . You can find him fishing northeast of Shattrath City by Silmyr Lake. Progress: The felblood is a marvel of evolution. It can survive in any water and even lava, and fishermen are its only natural predator. Any luck with your prey?", ["rewardItems"] = { 25978, 33820, 34863, 34867, 136377, 180136 }, ["starts"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["ends"] = { { ["mapID"] = 108, ["npcID"] = 25580, ["x"] = 0.386, ["y"] = 0.128 } }, ["coords"] = { ["mapID"] = 108, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.128 }, ["mapCandidates"] = { ["npc"] = { 108 }, ["zone"] = { 3519 } }, ["questType"] = "standard" },
