[12597] = { ["id"] = 12597, ["name"] = "Something for the Pain", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 66, ["mapID"] = 121, ["storyline"] = { 12504, 12505, 12506, 12507, 12508, 12510, 12512, 12514, 12516, 12552, 12553, 12554, 12555, 12557, 12583, 12584, 12596, 12597, 12598, 12599, 12606, 12623, 12627, 12628, 12629, 12630, 12631, 12632, 12633, 12637, 12638, 12642, 12643, 12646, 12647, 12648, 12649, 12653, 12661, 12663, 12664, 12665, 12666, 12667, 12668, 12669, 12672, 12674, 12675, 12676, 12677, 12684, 12685, 12712, 12713, 12721, 12729, 12730, 12740, 12859, 12861, 12883, 12884, 12894, 12901, 12902, 12903, 12904, 12912, 12914, 12916, 12919, 12932, 12933, 12934, 12935, 12936, 12948, 12954 }, ["description"] = "Gritty as my men are, they're still mortal. Wounds and pain diminish their ability to perform their missions. No amount of training changes that simple fact of life. Thankfully, one of our alchemists has developed a recipe for a salve that binds to our bandages and greatly reduces the pain our soldiers experience. The salve requires a special poppy these trolls cultivate just west of here. Go to Drak'Sotra Fields and harvest some of them to keep our stockpiles from running out.", ["objectivesText"] = "Captain Brandon at Drak'Sotra wants you to collect 5 Mature Water-Poppies from Drak'Sotra Fields. Progress: Have you collected the water-poppies, <name>?", ["rewardGold"] = 70225, ["rewardXP"] = 690, ["rewardItems"] = { 38552 }, ["starts"] = { { ["mapID"] = 121, ["npcID"] = 28042, ["x"] = 0.488, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 121, ["npcID"] = 28042, ["x"] = 0.488, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 121, ["source"] = "quest_giver", ["x"] = 0.488, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 121 }, ["zone"] = { 66 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 121, ["questLines"] = { { ["id"] = 536, ["name"] = "Zul'Drak", ["orderIndex"] = 32, ["flags"] = 0 } } },
