[14138] = { ["id"] = 14138, ["name"] = "Taking Care of Business", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["description"] = "With all of the troubles down in the Kaja'mine, Foreman Dampwick 's been going crazy trying to find you. He said something about some 'defiant trolls'. The kaja'mite that our trolls are mining is critical ingredient in Kaja'Cola. That bubbly stuff is making us a fortune, and it's going to get you a promotion to Trade <Prince/Princess>! But first, we have to get production flowing again. You'll find the foreman to the east. Here, give him this as an incentive to get his act together.", ["objectivesText"] = "Deliver Sassy's Incentive to Foreman Dampwick at KTC Headquarters on Kezan . Progress: Um... everything's going great. Yeah. What's that?", ["rewardXP"] = 25, ["rewardItems"] = { 60203 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.582667, ["y"] = 0.767111 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 0, ["flags"] = 0 } } },
[24594] = { ["id"] = 24594, ["name"] = "The Purification of Quel'Delar", ["level"] = 25, ["requiredLevel"] = 25, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4080, ["mapID"] = 122, ["storyline"] = { 24594 }, ["series"] = { 24800 }, ["description"] = "The Sunwell and the end of Quel'Delar's exile await, <name>. You will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming. Instead, remain focused on your task here. Speak to a Warden of the Sunwell to enter the Sunwell Plateau . Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Show the blade to Myralion Sunblaze at Quel'Delar's Rest once it is restored.", ["objectivesText"] = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau . Progress: You have returned from the Sunwell?", ["rewardItems"] = { 49871, 49889 }, ["starts"] = { { ["mapID"] = 122, ["npcID"] = 37527, ["x"] = 0.445, ["y"] = 0.454 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 36642, ["x"] = 0.64, ["y"] = 0.6095 } }, ["coords"] = { ["mapID"] = 122, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.454 }, ["mapCandidates"] = { ["npc"] = { 118, 122 }, ["zone"] = { 4080 } }, ["questType"] = "standard" },
[24952] = { ["id"] = 24952, ["name"] = "Rocket Boot Boost", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4720, ["mapID"] = 174, ["storyline"] = { 14001, 14014, 14019, 14021, 14031, 14233, 14234, 14235, 14236, 14237, 14238, 14239, 14240, 14241, 14242, 14243, 14244, 14248, 14303, 14326, 14445, 14473, 14474, 24671, 24741, 24744, 24816, 24817, 24856, 24858, 24859, 24864, 24868, 24897, 24901, 24924, 24925, 24929, 24937, 24940, 24942, 24945, 24946, 24952, 24954, 24958, 25024, 25058, 25066, 25093, 25098, 25099, 25100, 25109, 25110, 25122, 25123, 25125, 25184, 25200, 25201, 25202, 25203, 25204, 25207, 25213, 25214, 25243, 25244, 25251, 25265, 25267 }, ["series"] = { 24925, 24929, 24937, 24940, 24942, 24954, 24958, 25023, 25024 }, ["description"] = "You need to get those boots down into the caldera to Hobart Grapplehammer . Now that they're infused with the leftover rockin' powder, they should have enough thrust to get you all the way there on one shot. When you're ready, activate the boots. Don't worry, they're automatically set to land you safely. I think.", ["objectivesText"] = "Use the Rockin' Powder Infused Rocket Boots and deliver them to Hobart Grapplehammer . Progress: Well there you are!", ["rewardGold"] = 7150, ["rewardXP"] = 25, ["rewardItems"] = { 52032, 52912, 52936, 52958, 131842 }, ["starts"] = { { ["mapID"] = 174, ["npcID"] = 38738, ["x"] = 0.429667, ["y"] = 0.479 } }, ["ends"] = { { ["mapID"] = 174, ["npcID"] = 38120, ["x"] = 0.502, ["y"] = 0.383 } }, ["coords"] = { ["mapID"] = 174, ["source"] = "quest_giver", ["x"] = 0.429667, ["y"] = 0.479 }, ["mapCandidates"] = { ["npc"] = { 174 }, ["zone"] = { 4720 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 314, ["title"] = "Siren Isle", ["questLineID"] = 571, ["questLineOrder"] = 0 }, { ["id"] = 316, ["title"] = "Dragonflight Intro - Alliance", ["questLineID"] = 571, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 174, ["questLines"] = { { ["id"] = 571, ["name"] = "The Lost Isles", ["orderIndex"] = 43, ["flags"] = 0 } } },
[25473] = { ["id"] = 25473, ["name"] = "Kaja'Cola", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4737, ["mapID"] = 194, ["storyline"] = { 14069, 14070, 14071, 14075, 14109, 14110, 14113, 14115, 14116, 14120, 14121, 14122, 14123, 14124, 14125, 14126, 14138, 14153, 24488, 24502, 24503, 24520, 24567, 25473, 26711, 26712, 28349, 28414, 90869 }, ["series"] = { 14069, 14071, 14075, 24488, 24502, 24503, 24520, 24567, 28349, 28414 }, ["description"] = "Sassy's been riding me to supply some Kaja'cola for the party that's being thrown in your honor later today. Oops, was it supposed to be a surprise? You didn't hear it from me! Anywho, with production down these last few days, this is all that I managed to get made. Would you take it to her?", ["objectivesText"] = "Deliver the Six-Pack of Kaja'Cola to Sassy Hardwrench at KTC Headquarters on Kezan . Progress: <Sassy eyes the six-pack warily, as if she expects it to explode as soon as you hand it to her.> We need more Kaja'Cola than this! I swear I'm going to fire Dampwick if I don't kill him first!", ["rewardGold"] = 5350, ["rewardXP"] = 25, ["rewardItems"] = { 49884, 54453 }, ["starts"] = { { ["mapID"] = 194, ["npcID"] = 34872, ["x"] = 0.6102, ["y"] = 0.7574 } }, ["ends"] = { { ["mapID"] = 194, ["npcID"] = 34668, ["x"] = 0.582667, ["y"] = 0.767111 } }, ["coords"] = { ["mapID"] = 194, ["source"] = "quest_giver", ["x"] = 0.6102, ["y"] = 0.7574 }, ["mapCandidates"] = { ["npc"] = { 194 }, ["zone"] = { 4737 } }, ["questType"] = "standard", ["db2PoiMapID"] = 648, ["db2PoiUiMapID"] = 194, ["questLines"] = { { ["id"] = 5439, ["name"] = "Bilgewater Port", ["orderIndex"] = 3, ["flags"] = 0 } } },
[26393] = { ["id"] = 26393, ["name"] = "A Swift Message", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 1, 32 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 26393 }, ["series"] = { 26394, 26395, 26396 }, ["description"] = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor. His name is Osric Strang. His shop, Limited Immunity, is in the Old Town of Stormwind. Our supply of armor dwindles, and I must contact Osric for more. Can you take him this note? The fastest way to Stormwind is through Bartlett the Brave , our gryphon master. He's just outside of the smithy; bring him my note, and then take a gryphon to Stormwind.", ["objectivesText"] = "Bring Argus' Note to Bartlett the Brave the gryphon master. Progress: You look like you're in a hurry. Well, then you came to the right place!", ["rewardXP"] = 50, ["rewardItems"] = { 58364 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 514, ["x"] = 0.416, ["y"] = 0.655 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 42983, ["x"] = 0.417, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.655 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard" },
[26630] = { ["id"] = 26630, ["name"] = "Looks Like a Tauren Pirate to Me", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 26630 }, ["description"] = "Firallon wants MY head? Now that's interesting. But it's nothing we can't work around. This Yancey character probably doesn't know my face too well. Most non-tauren find us tauren indistinguishable from one another. In fact... most non-tauren find us indistinguishable from... a certain four-legged farm creature. Rikqiz the leatherworker keeps one of these creatures here in Booty Bay, and Narkk is my chief supplier for pirate hats. Get a replacement head and a hat, then return with both.", ["objectivesText"] = "Obtain a Cow Head and an Oversized Pirate Hat , then bring them back to Fleet Master Seahorn . Progress: You should know that most tauren would find this shameful. I find it... amusing.", ["rewardItems"] = { 59146, 59147, 59148 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 2487, ["x"] = 0.413, ["y"] = 0.731 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2487, ["x"] = 0.413, ["y"] = 0.731 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.413, ["y"] = 0.731 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard" },
[26871] = { ["id"] = 26871, ["name"] = "A Rock Amongst Many", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26312, 26313, 26314, 26315, 26326, 26328, 26375, 26376, 26377, 26426, 26436, 26437, 26438, 26439, 26440, 26441, 26507, 26575, 26576, 26577, 26578, 26579, 26580, 26581, 26582, 26583, 26584, 26585, 26656, 26657, 26658, 26659, 26750, 26752, 26827, 26828, 26829, 26831, 26832, 26833, 26869, 26871, 26875, 26971 }, ["series"] = { 26376, 26377, 26426, 26869 }, ["description"] = "<The ground trembles slightly, and the low, familiar voice of Diamant speaks as if from the stone itself.> You've done as I've asked. Turn back and escape the cave in one piece. Don't forget the gemstone.", ["objectivesText"] = "Return to Diamant at Lorthuna's Gate with the Painite Chunk . Progress: You're alive. This is good. Is the gemstone with you?", ["rewardXP"] = 4115, ["rewardItems"] = { 60504, 61427, 61428, 61429, 65907 }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 42467, ["x"] = 0.565, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 544, ["name"] = "Deepholm, The Stone Throne", ["orderIndex"] = 11, ["flags"] = 0 } } },
[26876] = { ["id"] = 26876, ["name"] = "The World Pillar Fragment", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 26244, 26245, 26246, 26247, 26248, 26249, 26250, 26251, 26254, 26255, 26256, 26258, 26259, 26260, 26261, 26409, 26410, 26411, 26413, 26427, 26484, 26499, 26500, 26501, 26502, 26537, 26564, 26591, 26625, 26632, 26755, 26762, 26766, 26768, 26770, 26771, 26791, 26792, 26834, 26835, 26836, 26857, 26861, 26876, 27007, 27010, 27061, 27126, 27135, 27931, 27932, 27933, 27934, 27935, 27936, 27937, 27938 }, ["series"] = { 26766, 26768, 26771, 26857 }, ["description"] = "It is time, <name>. We have spotted Abyssion making his way to the lair. The Twilight's Hammer might've thought the fragment would be safe if a dragon guarded it, but I've met enough dragons to know their one weakness. Pride. Abyssion's not going to run from a fight with us puny mortals. Place the banner of the Earthen Ring in the middle of his lair. Once we defeat him, bring the fragment to Maruut. We need to repair the World Pillar as soon as possible.", ["objectivesText"] = "Place the Earthen Ring Banner in the center of Abyssion's Lair, slay him and obtain the Upper World Pillar Fragment . Progress: <name>! You've returned!", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 60574, 60810, 61472, 61473, 61474 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 44010, ["x"] = 0.645, ["y"] = 0.821 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 43065, ["x"] = 0.495, ["y"] = 0.529 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.821 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 543, ["name"] = "Deepholm, War & Gunships", ["orderIndex"] = 56, ["flags"] = 0 } } },
[27742] = { ["id"] = 27742, ["name"] = "A Little on the Side", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5892, ["mapID"] = 241, ["storyline"] = { 26293, 26294, 26311, 26324, 26335, 26337, 26358, 26361, 26372, 26374, 26388, 26538, 26539, 26540, 26549, 26608, 26619, 26621, 26622, 26784, 26786, 26788, 26798, 26830, 26840, 27177, 27178, 27299, 27300, 27301, 27302, 27303, 27338, 27341, 27366, 27376, 27377, 27378, 27379, 27380, 27433, 27468, 27485, 27486, 27490, 27491, 27492, 27493, 27494, 27495, 27496, 27497, 27498, 27499, 27500, 27501, 27502, 27503, 27504, 27505, 27506, 27507, 27508, 27509, 27514, 27515, 27516, 27537, 27538, 27545, 27564, 27576, 27583, 27584, 27586, 27588, 27590, 27606, 27607, 27608, 27609, 27610, 27611, 27621, 27622, 27636, 27637, 27638, 27639, 27640, 27641, 27642, 27643, 27644, 27645, 27646, 27647, 27648, 27649, 27650, 27651, 27652, 27653, 27654, 27655, 27657, 27658, 27659, 27660, 27661, 27662, 27688, 27689, 27690, 27695, 27696, 27700, 27701, 27702, 27703, 27719, 27720, 27742, 27743, 27744, 27745, 27747, 27750, 27751, 27752, 27753, 27754, 27784, 27786, 27787, 27788, 27798, 27803, 27804, 27805, 27806, 27807, 27808, 27809, 27810, 27811, 27812, 27813, 27814, 27815, 27816, 27817, 27861, 27862, 27863, 27864, 27865, 27866, 27867, 27868, 27929, 27945, 27947, 27951, 27954, 27955, 27999, 28041, 28043, 28090, 28091, 28092, 28093, 28094, 28097, 28101, 28103, 28104, 28107, 28108, 28109, 28123, 28133, 28171, 28173, 28175, 28176, 28191, 28211, 28212, 28215, 28233, 28234, 28238, 28241, 28242, 28243, 28244, 28247, 28248, 28249, 28280, 28281, 28282, 28294, 28346, 28377, 28378, 28379, 28407, 28408, 28409, 28410, 28411, 28413, 28583, 28584, 28586, 28588, 28589, 28590, 28591, 28592, 28593, 28594, 28595, 28596, 28597, 28598, 28599, 28655, 28712, 28758, 28832, 28849, 28885 }, ["series"] = { 27743, 27744, 27745 }, ["description"] = "You know, it's our moral obligation to save all of this Elementium from the shale spiders. Those creepy things eat the stuff! What a waste! So, what do you say? 90/10 my way?", ["objectivesText"] = "Collect 6 Elementium Shards . Progress: How much do you think you can carry?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 62331, 63712, 63713, 63714, 166846 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5892 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 546, ["name"] = "Twilight Highlands", ["orderIndex"] = 228, ["flags"] = 0 } } },
[28162] = { ["id"] = 28162, ["name"] = "Swamp Bait", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28162 }, ["description"] = "Supplies are never easy to find in a place like this, <class>. We have been scouting since we captured the island but things are not looking good. Fortunately, we just received a scouting report that a swamp full of crocs is just west of our base camp here. The hides off those crocs will come in handy for our leatherworkers. Bring back as many as you can.", ["objectivesText"] = "You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad . The crocolisks can be found in the swamp, just west of Baradin Hold. Progress: You cleared out that swamp yet?", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["rewardItems"] = { 63103 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48066, ["x"] = 0.507333, ["y"] = 0.495333 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48066, ["x"] = 0.507333, ["y"] = 0.495333 }, { ["mapID"] = 245, ["npcID"] = 52015, ["x"] = 0.746, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.507333, ["y"] = 0.495333 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28608] = { ["id"] = 28608, ["name"] = "The Shadow Grave", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["requiredRaces"] = { 5 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6454, ["mapID"] = 18, ["storyline"] = { 24959, 24960, 24961, 24970, 24971, 24972, 24973, 25089, 26799, 26800, 26801, 26802, 28608, 28651, 28652, 28653, 28672 }, ["series"] = { 24959, 24960, 24961, 24970, 24971, 24973, 25089, 26799, 26800, 26801, 26802, 28651, 28652, 28653, 28672 }, ["description"] = "I'm pleased to see that you're up and walking around, <name>. You've held up nicely, especially after being dead for so long! Others weren't as lucky. If you wouldn't mind, I need you to fetch my embalming fluid and some twine to stitch up these bodies. You'll find both in the Shadow Grave, the building just behind me. Here, Darnell will join you. He knows the way.", ["objectivesText"] = "Obtain the Thick Embalming Fluid and the Corpse-Stitching Twine from the Shadow Grave in Deathknell . Progress: You will find the items within the Shadow Grave. I believe I left them on my work table.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 64581, 64582 }, ["starts"] = { { ["mapID"] = 18, ["npcID"] = 1568, ["x"] = 0.3, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 1568, ["x"] = 0.3, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 18, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 18 }, ["zone"] = { 6454 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 465, ["questLines"] = { { ["id"] = 5406, ["name"] = "Deathknell", ["orderIndex"] = 1, ["flags"] = 0 } } },
[28658] = { ["id"] = 28658, ["name"] = "Swamp Bait", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28658 }, ["description"] = "Supplies are never easy to find in a place like this, <class>. We have been scouting since we captured the island but things are not looking good. Fortunately, we just received a scouting report that a swamp full of crocs is just west of our base camp here. The hides off those crocs will come in handy for our leatherworkers. Bring back as many as you can.", ["objectivesText"] = "You have been tasked with collecting 8 Crocolisk Hides from the Baradin Crocolisks on Tol Barad . The crocolisks can be found in the swamp, just west of Baradin Hold. Progress: You cleared out that swamp yet?", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["rewardItems"] = { 63103 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48069, ["x"] = 0.5065, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48069, ["x"] = 0.5065, ["y"] = 0.499 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.5065, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28661] = { ["id"] = 28661, ["name"] = "The Imprisoned Archmage", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28661 }, ["description"] = "We have been trying to clear out the Cursed Depths cellblock since we landed on Tol Barad . It seems that everytime we get close, that archmage shows up and pushes us back. Now that we have claimed the island, it's time we take another shot. Head down there and bring me back his staff as proof that you have finished the job.", ["objectivesText"] = "You must kill Archmage Galus and return with his Staff from the Cursed Depths, just east of Baradin Hold. Progress: Have you been able to take out the Archmage?", ["rewardGold"] = 524200, ["rewardXP"] = 4790, ["rewardItems"] = { 63033 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48071, ["x"] = 0.5155, ["y"] = 0.4945 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48071, ["x"] = 0.5155, ["y"] = 0.4945 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.5155, ["y"] = 0.4945 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28664] = { ["id"] = 28664, ["name"] = "Svarnos", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28664 }, ["description"] = "Excellent work on the island capture, <class>. Now that we have claimed the island, we need to make these cellblocks useable for prisoners. D-Block has been especially hard to clear out. Unfortunately it has become overrun with demons of all sorts. We have been able to thin out the demons but a large core hound has broken its way out of its cell and is wreaking havoc down there. I need you to kill him and bring back his collar.", ["objectivesText"] = "You must kill Svarnos in the D-Block and return with his Cursed Collar. Svarnos can be found in the D-Block, just northwest of Baradin Hold. Progress: Is the core hound dead?", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["rewardItems"] = { 63143 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48070, ["x"] = 0.515, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48070, ["x"] = 0.515, ["y"] = 0.495 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28665] = { ["id"] = 28665, ["name"] = "Cursed Shackles", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28665 }, ["description"] = "Have you been down in the D-Block yet, <name>? Every time we clear that infested cellblock out, the demons seem to return rather quickly. We learned that they regenerate from the cursed shackles scattered around the area. That's where you come in to the picture <name>. I need you to retrieve as many of those shackles as you can and bring them back to me. We will destroy them immediately.", ["objectivesText"] = "You have been asked to recover 8 Cursed Shackles from the D-Block, just northwest of Baradin Hold. Progress: Did you find many shackles? Reports mentioned that they were all over the place down there.", ["rewardGold"] = 619600, ["rewardXP"] = 4790, ["rewardItems"] = { 63149 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48070, ["x"] = 0.515, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48070, ["x"] = 0.515, ["y"] = 0.495 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28669] = { ["id"] = 28669, ["name"] = "The Warden", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28669 }, ["description"] = "We have almost finished clearing out the revolting prisoners in the hole, but one last problem remains. The warden. Warden Silva is their master and they will do anything for him. If we take him out, we take them all out. Finish him off and bring me back his keys. We can use those keys to explore deeper into the cellblock and possibly gain access to the water supply here on the island.", ["objectivesText"] = "You must kill Warden Silva in The Hole and return with his keys. The Hole is just southwest of Baradin Hold. Progress: Is the warden dead yet?", ["rewardGold"] = 561800, ["rewardXP"] = 4790, ["rewardItems"] = { 63309 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48062, ["x"] = 0.515, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48062, ["x"] = 0.515, ["y"] = 0.496 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28670] = { ["id"] = 28670, ["name"] = "Food From Below", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "loremaster", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5095, ["mapID"] = 244, ["storyline"] = { 28670 }, ["description"] = "Supplies are running low here in camp, <name>. We have recently learned that the cellblock just southwest of here has a number of rations remaining from years of use. We need you to gather as many of those as you can and bring them back to camp. One more thing, the entire cellblock is overrun with prisoners so be careful.", ["objectivesText"] = "You have been asked to recover 12 Cellblock Rations from The Hole, just southwest of Baradin Hold. Progress: Were you able to recover the rations? Reports mentioned that they could be found all over the place down there.", ["rewardGold"] = 561800, ["rewardXP"] = 4790, ["rewardItems"] = { 63315 }, ["starts"] = { { ["mapID"] = 244, ["npcID"] = 48062, ["x"] = 0.515, ["y"] = 0.496 } }, ["ends"] = { { ["mapID"] = 244, ["npcID"] = 48062, ["x"] = 0.515, ["y"] = 0.496 }, { ["mapID"] = 245, ["npcID"] = 52016, ["x"] = 0.546, ["y"] = 0.811 } }, ["coords"] = { ["mapID"] = 244, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.496 }, ["mapCandidates"] = { ["npc"] = { 244, 245 }, ["zone"] = { 5095 } }, ["questType"] = "standard" },
[28755] = { ["id"] = 28755, ["name"] = "Annals of the Silver Hand", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 28755 }, ["description"] = "Do you know who the Knights of the Silver Hand were? They were the original paladins of the Light, and from their ranks came knights who would later join the Argent Dawn or the Scarlet Crusade. Though many have gone astray, they still possess valuable relics of the Silver Hand. Deep in Stratholme , under the watchful eye of Instructor Galford, volumes of the Annals of the Silver Hand survive. Any volumes you could recover would be a fitting addition to the rededicated Light's Hope Chapel.", ["objectivesText"] = "Recover a lost volume of the Annals of the Silver Hand from Stratholme . Progress: Have you recovered any of the lost histories of the Silver Hand?", ["rewardItems"] = { 13379, 43381, 61379, 65615 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 49856, ["x"] = 0.76, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 49856, ["x"] = 0.76, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "dungeon" },
[29255] = { ["id"] = 29255, ["name"] = "Embergris", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5733, ["storyline"] = { 29255 }, ["description"] = "The Crimson Lasher has developed some cracking blisters on its vines. Without treatment, this condition could be life threatening. Luckily, the Charred Soldiers and Charred Vanquishers in the area produce a waxy substance known as Embergris , which should soothe the Lasher's pain. Bring me some of this substance, and kill those nasty fire elementals while you're at it.", ["objectivesText"] = "Retrieve 5 Embergris from Charred Soldiers and Charred Vanquishers. Progress: The Lasher is growing quite quickly.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 2608, 69722 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29257] = { ["id"] = 29257, ["name"] = "Steal Magmolias", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5733, ["storyline"] = { 29257 }, ["description"] = "We've discovered a new species of flower growing in the Magma Springs to the north. Amazingly, they sustain themselves in pure molten lava! Please go and retrieve some specimens for me. I'm sure that further study of these plants will shed some light on your little friend here. Speaking of which, he seems quite eager to go with you. Let's hope he behaves himself.", ["objectivesText"] = "Collect 8 Magmolias from the Magma Springs to the north. Progress: Fascinating! The more time I spend in the Firelands, the more I see there is an ecosystem at work here.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69725 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[29265] = { ["id"] = 29265, ["name"] = "Fire Flowers", ["level"] = 32, ["requiredLevel"] = 32, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "loremaster", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5733, ["storyline"] = { 29265 }, ["description"] = "My fellow druid, Choluna , has asked us to collect any specimens of plant life that we might find here in the Firelands... ...I don't know whose idea it was to bring scholars to a warfront. Nevertheless, you will already be in the cave - killing things - so be on the lookout for anything growing out of the ground.", ["objectivesText"] = "Obtain 5 Luciferns . Progress: They could be growing anywhere. Keep your eyes open.", ["rewardGold"] = 309800, ["rewardXP"] = 4385, ["rewardItems"] = { 69765 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5733 } }, ["questType"] = "standard" },
[33024] = { ["id"] = 33024, ["name"] = "Is That A Real Measurement?", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 33024 }, ["series"] = { 33018, 33020, 33021, 33022, 33026, 33027, 33107, 33139 }, ["description"] = "Well done, <name>. I can see you're ready to continue exploring the mysteries of Lin's secret ingredient soup. From what I can tell, Lin used Stormstout brew for his soup broth. I think the next steps for you are to create a Noodle Cart of your own and to head to the Stormstout Brewery to collect some sloshes of brew.", ["objectivesText"] = "Create a Noodle Cart Kit and collect 20 Sloshes of Brew from slain alementals in the Stormstout Brewery. Progress: I'm glad it's you and not me. I'm not much of a drinker, myself.", ["rewardGold"] = 1239200, ["rewardXP"] = 9580, ["rewardItems"] = { 42907, 42909, 74833, 74839, 74841, 74845, 74856, 74857, 101630, 103651 }, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "dungeon" },
[33026] = { ["id"] = 33026, ["name"] = "These Aren't Your Fatty Goatsteaks", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5805, ["mapID"] = 376, ["storyline"] = { 33026 }, ["series"] = { 33018, 33020, 33021, 33022, 33024, 33027, 33107, 33139 }, ["description"] = "I'm so excited, <name>. We've nearly mastered all the ingredients for noodle soup! We have plenty of vegetables and spices here, but the Lin family had access to exotic meats not seen in Pandaria for some time. We need some nice, fatty meats. Grandpa used to tell me of ancient turtles living off the shores of the Timeless Isle. Something that lives that long has to have some nice fatty meat on its bones. Create a deluxe noodle cart and gather some fatty turtle steaks and we'll continue.", ["objectivesText"] = "Create a Deluxe Noodle Cart Kit and collect 50 Fatty Turtle Steaks . Progress: I can just taste the soup now!", ["rewardGold"] = 274800, ["rewardXP"] = 5990, ["rewardItems"] = { 74837, 74839, 74841, 74843, 74846, 74847, 74848, 74856, 74859, 74864, 74865, 85500, 101661, 101776 }, ["starts"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 376, ["npcID"] = 64231, ["x"] = 0.535, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 376, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 376 }, ["zone"] = { 5805 } }, ["questType"] = "standard" },
[35168] = { ["id"] = 35168, ["name"] = "Your First Blacksmithing Work Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7078, ["storyline"] = { 35168 }, ["description"] = "Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.", ["objectivesText"] = "Start and collect your first Blacksmithing work order at the Forge. Progress: Yes?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 108257, 109118, 109119, 109124, 112971 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36207] = { ["id"] = 36207, ["name"] = "Waruk the Frostforger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36207 }, ["series"] = { 36205, 36230, 36238 }, ["description"] = "Many say my father was a legendary blacksmith, Waruk the Frostforger they called him. They will tell you tales of his mighty weapons, crafted with nothing more than ice and steel. Waruk the Lieforger, I call him. He promised he wouldn't be gone long, \"I must support our troops!\" he said. Why did he have to go? Why did they let him get captured!? I have no more need for broken tools than I do broken promises. His grave is east of here, you can leave this with the rest of his unwanted belongings.", ["objectivesText"] = "Deliver Waruk's hammer to his grave site. Progress: Greetings <race>, what brings you to this old orc's grave?", ["rewardGold"] = 42450, ["rewardXP"] = 355, ["rewardItems"] = { 114981 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 78989, ["x"] = 0.412, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84494, ["x"] = 0.436, ["y"] = 0.507 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36238] = { ["id"] = 36238, ["name"] = "Mending A Broken Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36238 }, ["series"] = { 36205, 36207, 36230 }, ["description"] = "$p, thank you for avenging my death... but I have just one more favor to ask of you. If you help me see this through, I will forever be in your debt. Take these items and meet me at the forge in Stonefang Outpost. I have imbued them with a portion of my essence, but we still need the aid of another to reforge the hammer. It is time for me to reconcile with Kugra, so that we both may finally find peace....", ["objectivesText"] = "Meet Waruk at Stonefang Outpost. Progress: My father... but, how did you....", ["rewardGold"] = 208560, ["rewardXP"] = 1415, ["rewardItems"] = { 111813, 114988, 115356 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 84494, ["x"] = 0.436, ["y"] = 0.507 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 78989, ["x"] = 0.412, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.507 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36240] = { ["id"] = 36240, ["name"] = "Slow and Steady", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36240 }, ["series"] = { 36239, 36241 }, ["description"] = "Excellent! When you've collected enough herbs from the local wildlife, return to me and I'll craft them into an ink for Master Ardule. The sporebats and giants should have what you're looking for. And remember, be careful!", ["objectivesText"] = "Gather the herbs and return to Sha'la . Progress: Ah, these are just what I was looking for!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 111815, 111923, 114984, 114986, 114989 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84724, ["x"] = 0.578, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84724, ["x"] = 0.578, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36256] = { ["id"] = 36256, ["name"] = "The Arakkoan Enchanter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7004, ["mapID"] = 525, ["storyline"] = { 36256 }, ["series"] = { 36255, 36257, 36260 }, ["description"] = "The arakkoa said it was going to investigate an anomaly in the Cracking Plains that might be related to another armor piece.", ["objectivesText"] = "Find Delath on the edge of the Cracking Plains to the north. Progress: Greetings Enchanter. I can see you are acquainted with the art. Good, good. Perhaps you and I can help each other.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 115350 }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84739, ["x"] = 0.543, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.543, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36266] = { ["id"] = 36266, ["name"] = "The Clothes on Their Backs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36266 }, ["series"] = { 36236, 36262, 36269 }, ["description"] = "Such kindness you have shown me, perhaps I can ask for one more? In our village, we salvage and reuse old cloth to patch clothes and light armor. Sadly, most of my supply was taken or destroyed in the recent attacks. The Shadowmoon cultists might think twice about stealing from us if you were to relieve them of their own resources. If you can collect some ceremonial Shadowmoon robes for me, I will demonstrate some of my favorite tailoring techniques for you.", ["objectivesText"] = "Collect 10 Ceremonial Shadowmoon Robes . Progress: Were you able to get the robes?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 107076, 115013 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84523, ["x"] = 0.582, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84523, ["x"] = 0.582, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36287] = { ["id"] = 36287, ["name"] = "Snatch 'n' Grab", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36287 }, ["series"] = { 36286 }, ["description"] = "We were able to map all of the data from the transponder you recovered! Now our location analyzer is complete! We're just missing a few final pieces, then the real testing begins. One of my pilots mentioned seeing a beached Iron Horde ship over by the shore. If you can salvage some parts we may just be able to get this thing up and running!", ["objectivesText"] = "Search the beach for salvageable parts. Progress: Don't worry. We're just borrowing these from the Iron Horde!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 7298, 109258, 111921, 115279 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84825, ["x"] = 0.608, ["y"] = 0.326 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84825, ["x"] = 0.608, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.326 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36310] = { ["id"] = 36310, ["name"] = "The Arakkoan Enchanter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7078, ["mapID"] = 539, ["storyline"] = { 36310 }, ["series"] = { 36308, 36313, 36315 }, ["description"] = "The arakkoa said it was going to investigate an anomaly along the Forgotten Shore that might be related to another armor piece.", ["objectivesText"] = "Find Delath on the Forgotten Shore to the south. Progress: Greetings Enchanter. I can see you are acquainted with the art. Good, good. Perhaps you and I can help each other.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 115350 }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84966, ["x"] = 0.373, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.373, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 7078 } }, ["questType"] = "standard" },
[36378] = { ["id"] = 36378, ["name"] = "No Pressure, No Diamonds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36378 }, ["series"] = { 36314, 36352, 36380 }, ["description"] = "You wish to understand the secrets of our gems, <race>? In exchange for returning my pendant, I am willing to help. I must warn you, however, that the materials will not be easy to obtain. To the north, you will find magma pools that give birth to living lava creatures. Contained within these, you may find magnificent diamonds. Please return to me with a few of these diamonds...", ["objectivesText"] = "Acquire Lava Diamonds from the Lava Slimes that reside in Frostfire Ridge. Progress: Have you obtained the materials I asked for?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 115445, 115461 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 85106, ["x"] = 0.2, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 85106, ["x"] = 0.2, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.2, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36409] = { ["id"] = 36409, ["name"] = "Restoration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6719, ["mapID"] = 539, ["storyline"] = { 36409 }, ["series"] = { 36408 }, ["description"] = "As mentioned, our larger defense crystals have been drained of power, creating gaps in our defenses. The crystal you brought me is only a reminder of the severity of this situation. It's Shadowmoon magic to blame, I'm sure of it. One of our rangari scouts spotted an orc fleeing north, past Palemoon Village, and into the valley beyond. Go, find this orc, and see if you can't retrieve whatever vessel he's storing the power inside of. If we get it back, I'm sure I can restore the crystals.", ["objectivesText"] = "Retrieve the sample for Artificer Baleera . Progress: The crystal's power pulses as it is carried.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 111814, 115359, 115507, 115516, 128306, 128911, 152668, 169536, 237812 }, ["starts"] = { { ["mapID"] = 539, ["npcID"] = 84830, ["x"] = 0.47, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 539, ["npcID"] = 84830, ["x"] = 0.47, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 539, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 539 }, ["zone"] = { 6719 } }, ["questType"] = "standard" },
[36417] = { ["id"] = 36417, ["name"] = "From Their Cold Dead Hands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 36417 }, ["series"] = { 36301, 36419 }, ["description"] = "Those ogres took all of my hexweave! I kept it hidden at the bottom of my bag. How could they possibly know of its importance? If they discover even a portion of hexweave's properties, it means trouble for us all. <name>, this is a Frostwolf problem. It requires a Frostwolf solution. Will you help me?", ["objectivesText"] = "Collect 10 Damaged Hexweave from Bladespire Ogres. Progress: Well, is it done?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 115590 }, ["starts"] = { { ["mapID"] = 525, ["npcID"] = 84689, ["x"] = 0.204, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 84689, ["x"] = 0.204, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.204, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[36594] = { ["id"] = 36594, ["name"] = "\"Spare\" Parts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7004, ["storyline"] = { 36594 }, ["series"] = { 36589, 36627 }, ["description"] = "I've never seen anything like this before! No problem though, boss man. If it can be used to blow things up, I can get it working again. We are definitely going to need some parts--some sort of ammunition wouldn't hurt either. Sounds like those Iron Horde guys over yonder are no stranger to things that go boom. Take these tools with you and let's see if we can't commandeer us some spare parts!", ["objectivesText"] = "Recover 20 Black Iron Shells and 50 Siege Cannon Parts . Progress: Got the stuff yet boss?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 24423, 24424, 24425, 57489, 57490, 57491, 116430, 116434, 116645, 131250, 131472 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7004 } }, ["questType"] = "standard" },
[36641] = { ["id"] = 36641, ["name"] = "Your First Alchemy Work Order", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7078, ["storyline"] = { 36641 }, ["description"] = "Now that the alchemy lab is complete, we can start producing alchemical catalysts for you. When you have the ingredients, please speak with my assistant to start the first work order.", ["objectivesText"] = "Start and collect your first Alchemy work order at the Alchemy Lab. Progress: Yes?", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 108996, 109124, 116842 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7078 } }, ["questType"] = "standard" },
