[38501] = { ["id"] = 38501, ["name"] = "Hatecoil Hammerwork", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38563, 39699 }, ["description"] = "There may be a way to jump-start our research into leystone. I've heard reports of naga camps down in Azsuna. If they've been in Azsuna for long enough, their smiths have certainly started experimenting with leystone themselves. Be on the lookout for some leystone armor on the naga... ideally something more elaborate than a bracer.", ["objectivesText"] = "Obtain a Masterwork Hatecoil Breastplate and a pair of Masterwork Hatecoil Pauldrons . Progress: I still marvel at how quickly those things can swim in plate armor.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 123971, 123972, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 3, ["flags"] = 0 } } },
[38505] = { ["id"] = 38505, ["name"] = "Engineers: Not COMPLETELY Useless", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38506, 38507, 38513, 38514, 38515, 38563, 39699 }, ["description"] = "Unfortunately, I have no idea how to access any information within this core. But I know someone who does. Head over to \"Like Clockwork\", the engineering shop three doors down from here. Timofey Oshenko owes me a favor. He should be able to extract the memory out of the core.", ["objectivesText"] = "Bring the Ancient Sentry Construct Memory Core to Timofey Oshenko in Dalaran. Progress: You're here from Alard's shop? What does that musclehead want now?", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 123977, 124103, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 4, ["flags"] = 0 } } },
[38519] = { ["id"] = 38519, ["name"] = "Grayheft", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["description"] = "Our tribe regularly crafts legplates out of leystone. I will share our pattern with you... if you do me a favor. My father fell to the drogbar several years ago, and they took his hammer as a trophy. That hammer was in my family for countless generations. Now, it languishes in the hands of the vile drogbar, Kubrul. I would very much like to have it back.", ["objectivesText"] = "Obtain Grayheft, Ancient Hammer of the Highmountain Tauren from Kubrul within the Deep Roads cavern. Progress: I have no patterns for helms or boots. A tauren who cannot survive a few blows to the hoof has no place in battle. Boots are of little use to us. A helm is a coward's armor. I am sorry if this offends you, but it is true. Legplates, however, do play a vital role. I will gladly share this pattern with you, once you bring me my father's hammer.", ["rewardXP"] = 1770, ["rewardItems"] = { 109076, 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124004, 124103, 124436, 124462, 131811, 137680, 141605 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92245, ["x"] = 0.549, ["y"] = 0.845 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92245, ["x"] = 0.549, ["y"] = 0.845 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.845 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 13, ["flags"] = 0 } } },
[38522] = { ["id"] = 38522, ["name"] = "Not Just Weapons and Armor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "You know, we aren't just limited to armorsmithing and weaponsmithing. I regularly make chisels for the scribes, crucibles for the alchemists, and even thimbles for the tailors. They should sew in full plate gauntlets if they're really all that worried about their poor little thumbs. Anyhow, I have a recipe I think an adventurer like you might be interested in. Let's try it out.", ["objectivesText"] = "Craft 4 Hard Leystone Bars and 24 Hard Leystone Nails . Progress: Let's get to work. I think you'll enjoy this.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124417, 124418, 124419, 124420, 124421, 124422, 124423, 124424, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 15, ["flags"] = 0 } } },
[38528] = { ["id"] = 38528, ["name"] = "Leystone's Potential", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38530, 38564, 39680, 39726, 39729, 44449 }, ["description"] = "As I'm sure you've deduced, all of the leystone recipes you know can be improved. By learning to harness leystone's true potential, you can reduce the amount of material you use and still yield an equivalent result. Here, I'll show you. We'll start, as one does, with the humble bracer. This particular piece of armor benefits from the addition of brimstone runes. See for yourself.", ["objectivesText"] = "Use Felsmith Nal'ryssa 's technique to craft a set of Masterwork Leystone Armguards . Progress: Keep it up, <class>.", ["rewardXP"] = 6140, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124449, 124450, 124451, 124454, 124455, 124462, 137680 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 92264, ["x"] = 0.299, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.299, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 26, ["flags"] = 0 } } },
[38532] = { ["id"] = 38532, ["name"] = "Maw of Souls: Hammered By The Storm", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38531, 38533, 38559, 38833 }, ["description"] = "Your hammer looks weak, and would probably break upon striking the Firmament Stone. The vrykul master blacksmiths of old were known for the strength of their hammers. The only way to get our hands on such a hammer would be to go where vrykul go when they die. To the Maw of Souls. The goddess that resides over that realm is named Helya. She hoards the trinkets they bring for her own desires. Defeat her and you may be able to acquire such a hammer.", ["objectivesText"] = "Go to the Maw of Souls and recover an Ancient Vrykul Hammer . Progress: Were you able to get your hands on one?", ["rewardXP"] = 6140, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124025, 124103, 124436, 124462, 136350, 136696, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 29, ["flags"] = 0 } } },
[38564] = { ["id"] = 38564, ["name"] = "A Sweet Bargain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 39680, 39726, 39729, 44449 }, ["description"] = "Reading over this research, I found an interesting method that I'd like you to try. The method would require us to chill the metal to sub-freezing temperatures during the pre-tempering phase. Simple water quenching won't do. Good thing you can't walk two steps in this city without bumping into a frost mage! See if you can recruit one for the shop, <name>.", ["objectivesText"] = "Find a frost mage in Dalaran to chill your quenching trough.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124398, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 21, ["flags"] = 0 } } },
[38728] = { ["id"] = 38728, ["name"] = "The Keystone", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38727, 38765, 38766, 38813, 38819, 39262, 39495, 39515, 39516, 39663 }, ["description"] = "<name>, Brood Queen Tyranna is just ahead in the command chamber. The others already charged in. She has the Sargerite Keystone in her possession. Finally, the object of all our sacrifice is at hand.", ["objectivesText"] = "Kill Brood Queen Tyranna and take the Sargerite Keystone . Then, join the others down-below in the portal chamber. Progress: <name>, are you ready?", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 43189, 43190, 43191, 43192, 124672, 128955, 133310, 184315, 246936, 249400, 251821, 254267, 254579 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 22, ["flags"] = 0 } } },
[38759] = { ["id"] = 38759, ["name"] = "Set Them Free", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 39049, 39050, 40379 }, ["description"] = "Cyana went down to the Molten Shore. She was going to help some of the demon hunters who came in through the gateway ahead of us. Instead, she got herself into trouble. This inquisitor revealed they're being held prisoner by some new type of demon called a 'jailer'. The thing sucks the souls out of its victims. I doubt they can hold out much longer.", ["objectivesText"] = "Several of your demon hunters are in trouble. Get the Soulwrought Key to set them free. Progress: Some of our demon hunters are missing. Did you see them back on the Molten Shore?", ["rewardGold"] = 202200, ["rewardXP"] = 1145, ["rewardItems"] = { 128227, 128952, 133312 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 2, ["flags"] = 0 } } },
[38807] = { ["id"] = 38807, ["name"] = "Infernal Brimstone Analysis", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 39763, 39790, 39817, 39830 }, ["description"] = "In order to mine Infernal Brimstone, we first need to understand the way in which ore comes into being. I currently have three of my apprentices doing research on different ores around the world. Find Forinn Stoneheart in Deepholm, Rhol Landers in Twilight Highlands and Krul Rockhorn in Icecrown and collect any information they've gathered on the ore at those locations.", ["objectivesText"] = "Collect the reports from Mama Diggs ' apprentices in Icecrown, Deepholm and Twilight Highlands. Progress: What's that you've got there, boy?", ["rewardXP"] = 6140, ["rewardItems"] = { 128392, 128396, 128405 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 1, ["flags"] = 0 } } },
[38951] = { ["id"] = 38951, ["name"] = "A Needle Need", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38952, 38953 }, ["description"] = "This shop has almost everything we need. Unfortunately, the quality of your sewing needles is lacking. I do know where you can get better needles. The sprites of Val'sharah are covered with spines which, fortuitously, are perfect for the type of sewing we need. I hate to be such a prickler stickler, but these needles really will make a difference.", ["objectivesText"] = "Obtain 150 Spritethorns . Progress: Your friend thinks these needles will make a difference?", ["rewardGold"] = 28090, ["rewardXP"] = 1415, ["rewardItems"] = { 81404, 87399, 88044, 88045, 88046, 88047, 88048, 88049, 88050, 88051, 88052, 108439, 127042, 198609, 211279, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 7, ["flags"] = 0 } } },
[38952] = { ["id"] = 38952, ["name"] = "Meticulous Precision", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38951, 38953 }, ["description"] = "The needles are sharp, but look at them closely. Some have a curve to them, others have a spur hanging off the side. Look at this one... it's got a ninety-degree crook in it! I have no desire to sew around a corner. Tiffany Cartier in the jewelcrafting shop has a good eye for this sort of thing. Bring these needles to her, and she'll straighten them out.", ["objectivesText"] = "Bring the Spritethorns to Tiffany Cartier in Dalaran. Progress: What's this, <name>?", ["rewardXP"] = 1415, ["rewardItems"] = { 127043 }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 8, ["flags"] = 0 } } },
[38953] = { ["id"] = 38953, ["name"] = "Advanced Needlework", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38951, 38952 }, ["description"] = "You've already learned the patterns for bracers, belts, epaulets, and of course, robes. Unfortunately, your technique was wasteful... you need a better method. That's where our needles come in. Here, I'll show you how to improve the process of these patterns.", ["objectivesText"] = "Make an Embroidered Silkweave Robe on Tanithria's Finishing Bench. You will need to gather the materials in her shop. Progress: Keep your eye on your needlework. Don't lose focus now.", ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 126987, 126992, 126993, 126994, 127037, 127290, 127292, 127359, 127360, 127382 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 9, ["flags"] = 0 } } },
[38955] = { ["id"] = 38955, ["name"] = "Sew Far, Sew Good", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38954 }, ["description"] = "Your tailoring skill really is impressive and, although I don't have my patterns with me, I do have some patterns memorized. One of those patterns is for a simple bag. Follow my lead, <name>.", ["objectivesText"] = "Craft a Silkweave Bag. You will need to gather materials inside the Dalaran tailoring shop. Progress: There's nothing quite like a new bag.", ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 127035, 127037, 127290, 127361, 127681 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 11, ["flags"] = 0 } } },
[38959] = { ["id"] = 38959, ["name"] = "Left Behind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "I do truly want to help you work on your tailoring, but without my patterns or my supplies, there isn't much more I can do save for teaching you what little I remember. If my memory still serves true, you're just missing a good pattern for some gloves and a hood. The first thing I need you to do is grab a few things from where you first met me. Here's what I need...", ["objectivesText"] = "Gather Lyndras' Pinking Shears , his Box of Measuring Tools and his Threading Needles from where you first met him in Azsuna. Progress: I had no clue I'd be magically teleported here, otherwise I would have gathered my things myself.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 74603, 74604, 74605, 88397, 131916, 135525, 135526, 135527, 179508, 179513, 179517, 179532, 179537, 179547, 181405, 181426, 181427, 181428, 181429, 181455, 181477, 181479, 181541, 181735, 181736, 182136, 182657, 182769, 183487, 183488, 184378, 184381, 184382, 184383, 184384, 184519, 204388, 211279, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 15, ["flags"] = 0 } } },
[38960] = { ["id"] = 38960, ["name"] = "Lining Them Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Since you're heading to Azsuna, you may as well gather some lining for our projects. The bears of Azsuna are known for how soft, yet durable their fur is. Hunt them in the woods around Llothien and bring their fur back with you.", ["objectivesText"] = "Gather 15 Bear Furs . Progress: Don't take them for easy prey. They're as vicious as they are cunning.", ["rewardXP"] = 1415, ["rewardItems"] = { 104320, 127047, 128827, 133576, 135538 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 16, ["flags"] = 0 } } },
[38961] = { ["id"] = 38961, ["name"] = "Eye of Azshara: The Depraved Nightfallen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "In order to craft the gloves, we'll require a special item. This will be no easy task to recover it, <name>. The naga of Azsuna are said to be hard at work trying to summon a terrible creature into this world. The creature's heart holds immense energy that we can use to channel into the gloves, making them incredibly powerful. I need... I mean, we need that heart if we are to produce a suitable pair of gloves for someone of your presence.", ["objectivesText"] = "Go to the Eye of Azshara, defeat the Wrath of Azshara and recover the Heart of the Storm . Progress: What were you able to find?", ["rewardXP"] = 1415, ["rewardItems"] = { 126989, 127048 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 18, ["flags"] = 0 } } },
[38963] = { ["id"] = 38963, ["name"] = "The Final Lesson?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 630, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38964, 38965, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Now that we have everything we need, let's work on the hood. After we're finished, we'll move onto the gloves.", ["objectivesText"] = "Create a Handcrafted Silkweave Hood on Tanithria's Finishing Bench. You will need to gather the materials in her shop. Progress: Come now, <name>. Let us sew.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 124437, 126990, 127037, 127290, 127363, 127364, 127367, 127681, 135538 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 93967, ["x"] = 0.6, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 17, ["flags"] = 0 } } },
[38965] = { ["id"] = 38965, ["name"] = "Assault on Violet Hold: Into the Hold", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38966, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "With Lyndras being locked up in Violet Hold, you feel responsible for him and must discover the truth behind his actions. Perhaps if you were able to speak with him, you could find a way to have him released from the hold and put back into your custody. Go into Violet Hold and find out what happened to Lyndras .", ["objectivesText"] = "Go into Violet Hold and find out what happened to Lyndras . Progress: Did you discover what happened to Lyndras ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135556, 141184 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 23, ["flags"] = 0 } } },
[38966] = { ["id"] = 38966, ["name"] = "Secret Silkweaving Methods", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["series"] = { 38956, 38957, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38967, 38968, 38970, 39602, 39605, 39667 }, ["description"] = "Okay, done mourning! Let's look through his stuff. < Tanithria takes a moment to leaf through Lyndras' journal. Her eyes open wide.> Our friend has been keeping secrets from us. Look at this! Every single one of the recipes he's taught us can be improved. Let's start simple, with some bracers. I can supply most of the materials, but you'll have to talk to Alard Schmied in the blacksmithing shop to get this powdered brimstone.", ["objectivesText"] = "Craft some Masterwork Silkweave Bracers . You will need to gather materials from the Dalaran tailoring shop and blacksmithing shop. Progress: These patterns are fascinating. I never knew you could get this kind of result out of simple silks.", ["rewardXP"] = 6140, ["rewardItems"] = { 124437, 127037, 127368, 127370, 127372, 127373, 127382, 127680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 24, ["flags"] = 0 } } },
[38969] = { ["id"] = 38969, ["name"] = "Master of Silkweave", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "While Tytallo is busy exacting withered genocide, it falls on me to take care of the more mundane aspects of training. We're going to need to see how talented you are. Craft an entire set of silkweave armor for me. Leyweaver Mithrogane can provide you with a proper mannequin for displaying it.", ["objectivesText"] = "Purchase a Shal'dorei Mannequin from Leyweaver Mithrogane, then craft an entire set of silkweave armor and place them on the mannequin. Progress: If you wish to learn what we're about to teach you, you need a solid foundation.", ["rewardXP"] = 6140, ["rewardItems"] = { 124437, 127037, 127265, 127266, 127681 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93971, ["x"] = 0.402, ["y"] = 0.696 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93971, ["x"] = 0.402, ["y"] = 0.696 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.696 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 28, ["flags"] = 0 } } },
[38971] = { ["id"] = 38971, ["name"] = "Exotic Textiles", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "I'm risking my life and career to be here, tailor. I've been curious about demonic cloth, and my attempts to obtain some through approved means have been met with resistance. I simply must see this cloth for myself. I don't wish to disrupt Azayna's pact with the demons, but you - you can attack the demons without drawing attention to our guild. I'm particularly interested in a particular demon's set of robes. Bring me a scrap, and I'll teach you what I know.", ["objectivesText"] = "Obtain the Fel Inscribed Shroud . Progress: Probably better that you fight the thing, anyhow. I'm useless with a weapon.", ["rewardXP"] = 6140, ["rewardItems"] = { 127281 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93978, ["x"] = 0.266, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93978, ["x"] = 0.266, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.266, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 30, ["flags"] = 0 } } },
[38974] = { ["id"] = 38974, ["name"] = "Halls of Valor: The Right Question", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7672, ["mapID"] = 634, ["storyline"] = { 38944, 38945, 38946, 38947, 38948, 38949, 38950, 38951, 38952, 38953, 38954, 38955, 38956, 38957, 38958, 38959, 38960, 38961, 38962, 38963, 38964, 38965, 38966, 38967, 38968, 38969, 38970, 38971, 38974, 38975, 39602, 39605, 39667 }, ["description"] = "One might ask what a leyweaver is doing standing over a dead vrykul's body. But such questions only stir up trouble. Instead let us ask what can be learned from those who have passed on. A question like that promotes progress. I assume you're here to learn from me, the pattern for Imbued Silkweave pants, yes? If that's true, then I'll need something from one who has passed on. In the Halls of Valor the great guardian, Hymdall resides. Bring me his loincloth and I will teach you my pattern.", ["objectivesText"] = "Defeat Hymdall in the Halls of Valor and recover his loincloth. Progress: Asking the right questions will get you far.", ["rewardXP"] = 6140, ["rewardItems"] = { 135575 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 93977, ["x"] = 0.655, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93977, ["x"] = 0.655, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7672 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 96, ["name"] = "Legion Tailoring", ["orderIndex"] = 31, ["flags"] = 0 } } },
[39331] = { ["id"] = 39331, ["name"] = "Eye of Azshara: Put a Cork in It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39332 }, ["description"] = "A thought occurred to me recently, <name>. The naga have been known to hoard all manner of potions, so they might have the sort of corks we need. In my educated opinion, I believe the best place to start searching is around the Eye of Azshara! Try not to waste your time in there dealing with the naga's goings on, just look for some replacement corks.", ["objectivesText"] = "Go to the Eye of Azshara and retrieve the Advanced Corks for Deucus Valdera in Dalaran. Progress: The sooner we get my supplies back, the quicker we can get back to real work.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127873, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128335 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 8, ["flags"] = 0 } } },
[39332] = { ["id"] = 39332, ["name"] = "Furbolg Firewater", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39331 }, ["description"] = "Oh! I recognize these corks you brought me, <name>. I recently acquired several from a furbolg tribe in Val'sharah. They need sturdy corks to keep a tight seal on that potent firewater they brew. We need more firewater potions--the corks would make an ideal addition to our alchemy table!", ["objectivesText"] = "Acquire skins of Smolderhide Firewater from the furbolg camp in Val'sharah. Bring them back to Deucus Valdera in Dalaran so he can make use of the corks. Progress: Did you find more firewater potions? I bet it's tempting to take a swig!", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128335 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39335] = { ["id"] = 39335, ["name"] = "Neltharion's Lair: Potent Powder", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39336 }, ["description"] = "I've heard rumors that the ancient drogbar collected powder from the residue of dragon's breath. If it's true that Neltharion's Lair lies somewhere below us, it seems a likely source. Go there and try to find a replacement for my powder.", ["objectivesText"] = "Acquire Precipitating Powder in Neltharion's Lair and bring it to Deucus Valdera in Dalaran. Progress: What have we here?", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127874, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39336] = { ["id"] = 39336, ["name"] = "We Need More Powder!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39335 }, ["description"] = "The substance you brought me appears to be precipitating powder, a highly volatile reagent used by the vrykul in their recipes. There are rumors that a vrykul elder named Katterin has built up quite a store of this powder. A substance this dangerous needs to be in our hands, not hers!", ["objectivesText"] = "Obtain Katterin's Alchemy Kit from Katterin the Blistered in Stormheim. Progress: Let's hope you find the powder we need...", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128345 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 13, ["flags"] = 0 } } },
[39339] = { ["id"] = 39339, ["name"] = "A Fragile Crucible", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39340, 39341 }, ["description"] = "I have customers asking for alchemist stones, but I'm unable to make any until I replace my crucible. In order to create a new one, we'll need a few things, but first we'll need a proper container. Something that can be augmented to withstand a demon's breath. There's a place in Suramar which the Legion has occupied. There surely must be a device there we can take that will be suitable for our needs.", ["objectivesText"] = "Bring the Fragile Demonsbreath Crucible to Deucus Valdera in Dalaran. Progress: I trust you're strong enough to handle a few demons?", ["rewardXP"] = 6140, ["rewardItems"] = { 28725, 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128681 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 17, ["flags"] = 0 } } },
[39350] = { ["id"] = 39350, ["name"] = "Maw of Souls: A Hope in Helheim", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39348, 39349, 39351 }, ["description"] = "For this last ingredient, well... <Alard begins pondering for a moment, then nods his head.> Yes, that's the only way. For this last one, you'll need to go to the land of the damned, Helheim. Well, not there exactly, but aboard the boat that ferries the dead across the Maw of Souls. Upon that boat may be the final ingredient we need. It's called Dragur Dust . Keep an eye out for it. Also, one needs to be quick when adding this ingredient. I'll need something to heighten my reflexes.", ["objectivesText"] = "Retrieve a crate of Dragur Dust from Heroic: Maw of Souls, craft a Flask of the Seventh Demon and return both items to Alard in Dalaran. Progress: Were you able to board the ship? Did you find the dust?", ["rewardXP"] = 6140, ["rewardItems"] = { 3371, 124102, 124103, 124104, 124105, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136819 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 30, ["flags"] = 0 } } },
[39430] = { ["id"] = 39430, ["name"] = "Flasking for a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 650, ["storyline"] = { 39325, 39326, 39327, 39328, 39329, 39330, 39331, 39332, 39333, 39334, 39335, 39336, 39337, 39338, 39339, 39340, 39341, 39342, 39343, 39344, 39345, 39346, 39347, 39348, 39349, 39350, 39351, 39390, 39430, 39431, 39566, 39645, 42081 }, ["series"] = { 39334 }, ["description"] = "You know, this mixing flask didn't suffer terrible damage. I'm positive it can just be repaired. I'm no expert in glass repair, but I've heard of someone who is--a tauren by the name of Barm Stonebreaker . He's a smith by trade, but those who know him say he was born to work glass. Those tauren don't work for free, so you may be in for some work yourself.", ["objectivesText"] = "Seek out Barm Stonebreaker at the Ironhorn Enclave in Highmountain. Progress: You're looking for help? I hope you have something to offer my people in return, <race>.", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 128515, 136673, 136674, 136675 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 97, ["name"] = "Legion Alchemy", ["orderIndex"] = 10, ["flags"] = 0 } } },
[39499] = { ["id"] = 39499, ["name"] = "Well of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7545, ["storyline"] = { 39499 }, ["description"] = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", ["objectivesText"] = "Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Normal difficulty. Progress: Did you manage to find any of those Soul Remnants I mentioned?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 128416 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questType"] = "raid" },
[39500] = { ["id"] = 39500, ["name"] = "Well of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7545, ["storyline"] = { 39500 }, ["description"] = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", ["objectivesText"] = "Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Heroic difficulty. Progress: Did you manage to find any of those Soul Remnants I mentioned?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 128417 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questType"] = "raid" },
[39501] = { ["id"] = 39501, ["name"] = "Well of Souls", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7545, ["storyline"] = { 39501 }, ["description"] = "As you defeat Gul'dan's minions, his hold over this fel citadel weakens, allowing me to teleport you and your allies deeper into the dark halls. If I only I had some Soul Remnants - four of them, let's say - none of this would be necessary, and I could harness that power to send you directly into the upper reaches of the Citadel.", ["objectivesText"] = "Collect 4 Soul Remnants from Gorefiend in Hellfire Citadel on Mythic difficulty. Progress: Did you manage to find any of those Soul Remnants I mentioned?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 128418 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questType"] = "raid" },
[39502] = { ["id"] = 39502, ["name"] = "The Fel Spire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7545, ["storyline"] = { 39502 }, ["description"] = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights. If only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", ["objectivesText"] = "Collect 4 Fel Essences from Mannoroth in Hellfire Citadel on Normal difficulty. Progress: Have you been to the top of the Citadel so that I can send you to the top of the Citadel?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 128419 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questType"] = "raid" },
[39504] = { ["id"] = 39504, ["name"] = "The Fel Spire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7545, ["storyline"] = { 39504 }, ["description"] = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights. If only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", ["objectivesText"] = "Collect 4 Fel Essences from Mannoroth in Hellfire Citadel on Heroic difficulty. Progress: Have you been to the top of the Citadel so that I can send you to the top of the Citadel?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 128420 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questType"] = "raid" },
[39505] = { ["id"] = 39505, ["name"] = "The Fel Spire", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7545, ["storyline"] = { 39505 }, ["description"] = "This would all be so much simpler if we could just teleport directly to the top of the Citadel, where Gul'dan works his dark magic, wouldn't it? But while demonic power fills the halls, my magic cannot penetrate to such heights. If only I had powerful Fel Essences to work with, I could attune my magic to their defenses and bypass them. But the only place you might find such concentrated fel energy would be atop the Citadel itself. What a conundrum....", ["objectivesText"] = "Collect 4 Fel Essences from Mannoroth in Hellfire Citadel on Mythic difficulty. Progress: Have you been to the top of the Citadel so that I can send you to the top of the Citadel?", ["rewardGold"] = 619600, ["rewardXP"] = 1365, ["rewardItems"] = { 128421 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7545 } }, ["questType"] = "raid" },
[39680] = { ["id"] = 39680, ["name"] = "Between the Hammer...", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39726, 39729, 44449 }, ["description"] = "<name>, I fear that my spirit will remain bound to this place unless I am made whole again. Long ago, I discovered a cave near the coast behind Black Rook Hold. I explored the cave only to find an abominable creature that attacked me, causing me to drop my hammer as I fled. I need that hammer back if I am to be at peace.", ["objectivesText"] = "Bring Saris' Hammer back to his shop. Progress: Any luck retrieving my hammer?", ["rewardXP"] = 175, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 128745, 137680 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 18, ["flags"] = 0 } } },
[39699] = { ["id"] = 39699, ["name"] = "Ironhorn Leysmithing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38563 }, ["description"] = "I sense great strength in you, yet you refuse to wield it. We Ironhorn use double the metal of any normal blacksmith to craft our wares. There is also a technique in how you hammer such quantities of leystone that I will instruct you on. Use our scrap metal and hammer out the pieces for a gauntlet. I will weld the pieces together when you are finished.", ["objectivesText"] = "Gather scrap metal around the Ironhorn Enclave. Then use the Greenhoof's Anvil and Forge to craft a Scrapmetal Handguard , a Scrapmetal Palmplate , a Scrapmetal Cuffplate , and 1 Scrapmetal Fingerplates . Progress: I'm waiting, outsider.", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124402, 124403, 124404, 124405, 124406, 124407, 124408, 124409, 124410, 124411, 124436, 124462, 137680 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 92242, ["x"] = 0.552, ["y"] = 0.842 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.842 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39726] = { ["id"] = 39726, ["name"] = "...And the Anvil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39729, 44449 }, ["description"] = "If you truly wish to see my work then you'll have to go and retrieve it as my shop has been raided of everything I've made. The breastplates of the Black Rook soldiers were one of my greatest accomplishments. They're light, yet strong and offer great mobility Relinquish my cursed brethren of their breastplates and bring them back to me. I will explain the finer points of how I made them upon your return.", ["objectivesText"] = "Gather 5 Black Rook Breastplates from the elves of Black Rook Hold. Progress: Have you acquired any breastplates?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 38711, 39015, 39044, 39076, 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124436, 124462, 128751, 137680, 246951 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 96763, ["x"] = 0.4, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 19, ["flags"] = 0 } } },
[39830] = { ["id"] = 39830, ["name"] = "Hellfire Citadel: Hellfire and Brimstone", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredRaces"] = { 2, 3, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38806, 38807, 39763, 39790, 39817, 39830 }, ["series"] = { 38807, 39763, 39790, 39817 }, ["description"] = "When Khadgar's group stormed Hellfire Citadel, they faced many foes that commanded demons, but none more powerful than Archimonde himself. Perhaps there's somethin' on his corpse that can answer the final questions of unlocking the mystery of this brimstone.", ["objectivesText"] = "Gather a group and storm Hellfire Citadel once more. Defeat Archimonde and recover the Infernal Codex . Progress: Don't go alone, lad. That place is teemin' with demons.", ["rewardItems"] = { 136389 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 250, ["name"] = "Legion Mining", ["orderIndex"] = 5, ["flags"] = 0 } } },
[39882] = { ["id"] = 39882, ["name"] = "Darkheart Thicket: The Glamour Has Faded", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7673, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39883, 39884, 39889 }, ["description"] = "I once taught the night elves how to enchant their armor to strengthen themselves against the evils of this land. One elf in particular garnered my favor. Arch-Druid Glaidalis is his name. He now resides in the forest known as the Darkheart Thicket, plotting to undo this world with this awful blight. Before his betrayal, I gave him my book of enchantments to study. I would very much like it back. I trust you with this task, enchanter. Bring my book back to me.", ["objectivesText"] = "Kill Arch-Druid Glaidalis in the Darkheart Thicket and recover Nalamya's Book of Enchantments . Progress: If you're truly a friend in this war, then be my sword and strike down Glaidalis.", ["rewardXP"] = 1415, ["rewardItems"] = { 137211 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7673 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 11, ["flags"] = 0 } } },
[39883] = { ["id"] = 39883, ["name"] = "Cloaked in Tradition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39882, 39884, 39889 }, ["description"] = "You have seen the ways of the tauren of Thunder Totem... speaking with the spirits, gathering from the land, and letting nothing go to waste. These are potent forces crucial to your quest to aid the Broken Isles. Here, take this journal back to your enchanter friend. It contains the lessons I have imparted unto you. Perhaps it will serve to help the greater cause of defeating the Legion.", ["objectivesText"] = "Take Guron's Journal to Nalthanis in Dalaran. Progress: Welcome back, <name>. Did you make contact with the tauren?", ["rewardXP"] = 1415, ["rewardItems"] = { 129176 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 98017, ["x"] = 0.466, ["y"] = 0.604 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.466, ["y"] = 0.604 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 9, ["flags"] = 0 } } },
[39884] = { ["id"] = 39884, ["name"] = "No Longer Worthy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39879, 39880, 39882, 39883, 39889 }, ["description"] = "The elves of Black Rook Hold have decided to turn their backs on us. They stay inside their keep, attacking any outsider who dare try to enter. Such behavior is intolerable... especially after all the help they've received from my folk and the others of this land. I want you to do me a favor, <name>. Take their enchanted sigils and reduce them to dust. Bring me back the dust as proof of your deeds.", ["objectivesText"] = "Kill night elves within the grounds of Black Rook Hold and collect their Enchanted Raven Sigils . Disenchant the sigils and bring back 8 Raven Dust to Nalamya as proof of their defeat. Progress: Their behavior was so odd and sudden. It makes no sense why they'd turn their backs on us. Still, it's inexcusable.", ["rewardXP"] = 1415, ["rewardItems"] = { 137213, 137221 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 98156, ["x"] = 0.544, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 12, ["flags"] = 0 } } },
[39904] = { ["id"] = 39904, ["name"] = "Halls of Valor: Revenge of the Enchantress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39903, 40265 }, ["description"] = "For many centuries, even after death, I was capable of weaving enduring enchantments. But since the theft of my enchanting rod by a greedy king, I can barely sustain the little magic I have left. If you can recover my enchanting rod from the god-king's ghost, I will reward you in kind.", ["objectivesText"] = "Retrieve Tigrid's Enchanting Rod from the Halls of Valor and return it to her in Stormheim. Progress: The rod is an extension of me, and I of it. It would be nice to hold it once more.", ["rewardXP"] = 1415, ["rewardItems"] = { 124440, 128535, 128617, 128618, 128619, 128620, 128621, 128622, 129293, 137235 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 16, ["flags"] = 0 } } },
[39916] = { ["id"] = 39916, ["name"] = "Turnabout Betrayal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39918, 39920, 39921, 40130, 40169 }, ["description"] = "Enchantress Ilanya remembers me? <The satyr pauses to wipe a tear away.> I made a fool's bargain ten millennia ago. I learned of the queen's alliance with the Legion and betrayed my heart to join their side. I was transformed into a monstrosity, only to die in battle against the mortals. Now the Legion returns, but I linger as an impotent spirit. Be my vessel and slay the demons ahead of us. Take their demonic runes and render them to dust.", ["objectivesText"] = "Defeat demons at the Felblaze Ingress. Take their Fel-crusted Runes and disenchant them into 5 Dust of Foul Lies . Return to where you met the Fallen Priestess when you are done. Progress: The death screams of the Legion bring me some semblance of joy.", ["rewardXP"] = 1415, ["rewardItems"] = { 129751, 137286 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98675, ["x"] = 0.638, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.638, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 19, ["flags"] = 0 } } },
[39921] = { ["id"] = 39921, ["name"] = "Neltharion's Lair: Rod of Azure", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39891, 39907, 39916, 39918, 39920, 40130, 40169 }, ["description"] = "Before we can begin though, there is a small favor I need to ask of you. I'm rather ashamed about this matter, to be honest, but it must be done in order for us to work together. When I was summoned to this land, I hadn't been given a chance to collect my things. Most importantly, I left behind my enchanting rod. Instead of retrieving it I believe it would be much simpler to reconstruct it. Here's what we'll need...", ["objectivesText"] = "Retrieve a Skystone Rod from Dargrul the Underking in Neltharion's Lair, a Radiant Zephyrite from Ozruk in The Stonecore and a pile of Ancient Arkhana from Scholomance. Progress: How goes the hunt for the rod components?", ["rewardXP"] = 6140, ["rewardItems"] = { 6218, 88566, 136615, 136616, 136617 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 99420, ["x"] = 0.472, ["y"] = 0.264 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.264 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 27, ["flags"] = 0 } } },
[39937] = { ["id"] = 39937, ["name"] = "Opposites Repel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39936, 39938, 39940, 39941, 39943, 40058, 40059, 40060, 40063 }, ["description"] = "There's a balance that must be struck, <name>, when becoming a demon hunter. In order to maintain that balance, we must infuse ourselves with opposite forces of nature. Fel energy is counteracted by arcane energy. We mark our bodies with arcane runes to keep our fel forces in check. You are a scribe, yes? Then you should have no trouble mixing a suitable ley pigment from the ley dust on the creatures in the ruins up ahead.", ["objectivesText"] = "Collect 10 Ley Dust from the nightfallen and withered in the Ley-Ruins of Zarkhenar, then mix it into a Ley Pigment . Progress: Even though they are opposites, one can not exist without the other.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129105, 129211, 136821, 139417, 139436 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 97736, ["x"] = 0.54, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 7, ["flags"] = 0 } } },
[39945] = { ["id"] = 39945, ["name"] = "Runes Within the Ruins", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39946, 39947, 39951, 40052 }, ["description"] = "Unfortunately, Pallin's codex isn't complete. There are many symbols here that simply cannot be deciphered with what we've learned. Looks like we'll need to go and collect more tablets down in the area that the vrykul call Haustvald.", ["objectivesText"] = "Collect 10 Ancient Vrykul Rune Tablets within Haustvald. Progress: We need those tablets if we're to progress any further in deciphering their language.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129164, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 21, ["flags"] = 0 } } },
[39946] = { ["id"] = 39946, ["name"] = "Right Tool for the Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39945, 39947, 39951, 40052 }, ["description"] = "From what little I have been able to decipher, I know that the tablets are created using a special carving tool. If we had one of those tools, along with a complete codex, we could easily create our own tablet. That would also serve to prove that my deciphering of their language has been successful. Retrieve one of those tools for me, <name>.", ["objectivesText"] = "Acquire a Runic Bone Knife . Progress: The knife is the final key to my research. Any luck finding one?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 90347, 90348, 90349, 90350, 90351, 90352, 90353, 90354, 90355, 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129169, 129211, 139417, 139436 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 97748, ["x"] = 0.692, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.692, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 22, ["flags"] = 0 } } },
[39949] = { ["id"] = 39949, ["name"] = "Once a Scribe Like You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 628, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39948, 39950 }, ["description"] = "These sewers are something of a... \"settling place\" for many who can't cope with the stresses of regular Dalaran life. Take, for example, the target of this particular contract. His name is Inkrot. He was once a scribe like you, but the stresses of dealing with the Professor drove him mad. < Raethan hands you the contract.> This says he's stolen a jewel from Cartier and Co. Bring me the jewel. Whatever else you find on him is yours.", ["objectivesText"] = "Kill Inkrot and obtain the Stolen Shadowruby . Progress: Did he give you much trouble?", ["rewardGold"] = 842700, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 129292, 139417, 139436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 26, ["flags"] = 0 } } },
[39953] = { ["id"] = 39953, ["name"] = "Halls of Valor: Vision of Valor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39957 }, ["description"] = "I think it's time for another field trip, <name>. To the Halls of Valor! The Valarjar are masters of all types of runecraft. Perhaps we can find something useful for a new recipe.", ["objectivesText"] = "Retrieve 5 Valarjar Rune-Sigils from the Halls of Valor. Progress: Did you see any gods while you were there?", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 128712, 128978, 128980, 129028, 129029, 129032, 129034, 129211, 131928, 139417, 139436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 40, ["flags"] = 0 } } },
[39954] = { ["id"] = 39954, ["name"] = "Mass Milling Techniques", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39847, 39931, 39932, 39933, 39934, 39935, 39936, 39937, 39938, 39939, 39940, 39941, 39942, 39943, 39944, 39945, 39946, 39947, 39948, 39949, 39950, 39951, 39952, 39953, 39954, 39955, 39956, 39957, 39959, 39960, 39961, 40052, 40056, 40057, 40058, 40059, 40060, 40061, 40062, 40063, 40064, 40065 }, ["series"] = { 39955, 39956 }, ["description"] = "A number of my previous students have been vocal in their displeasure regarding milling. They find the process \"repetitive\", \"mindless\", and even \"painful\". Have they no respect for the time-honored traditions of inscription? I suppose you count yourself among their number. Am I right? Very well. You've been a fine student so far, so I suppose there's no harm. I have a book about mass milling somewhere around the shop here. Find it, and it's yours.", ["objectivesText"] = "Find The Masterful Miller's Manual in Dalaran's inscription shop. Progress: Try not to make too big a mess.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 124101, 124102, 124103, 124104, 124105, 124106, 128304, 129032, 129034, 136909, 136912, 136915, 136916, 136917, 136918, 136931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 177, ["name"] = "Legion Inscription", ["orderIndex"] = 33, ["flags"] = 0 } } },
[40009] = { ["id"] = 40009, ["name"] = "Arcane Thirst", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39985, 39986, 39987, 40008, 40009, 40123, 42229, 44555, 44672 }, ["series"] = { 39985, 39986, 39987, 40008, 40123, 44555 }, ["description"] = "My people have subsisted on the Nightwell for millennia. Ancient mana is our lifeblood - without it, we become... well, you saw them out there. <Thalyssra holds her flask aloft, gently shaking free the last precious drops.> I'm afraid I have been rather reckless today. Already, my senses are dulling. Without magic to feed upon, I will turn. Please... find me something to feed upon... anything...", ["objectivesText"] = "Enter Shal'Aran and find something to sate Thalyssra's thirst. Progress: <Thalyssra's eyes have dulled and her body is shaking uncontrollably.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 121804, 129979, 136600, 136970, 140234, 141667, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98312, ["x"] = 0.3468, ["y"] = 0.5056 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3468, ["y"] = 0.5056 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 152, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 152, ["name"] = "Nightfall", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40158] = { ["id"] = 40158, ["name"] = "Darkheart Thicket: Demons Be Different", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40156, 40157, 40158, 40159 }, ["series"] = { 40157 }, ["description"] = "Oh yes, I've seen me fair share of demons while in dese lands. And skinnin' dem ain't no easy task. Their hides are tougher than normal animals, fibrous, see? But if you be wantin' to make da most of their skins, den ya need to be practicin' more. There be a creature I've heard of in da Darkheart Thicket whose hide's as tough as a demon's. When ya go ta skin him, try cutting with da grain in one even stroke. Bring me his skin to show me you be picking up on what I'm sayin'.", ["objectivesText"] = "Go to Darkheart Thicket and kill Dresaron. Skin him and bring his hide back to Ske'rit in Suramar. Progress: Any luck on gettin' dat skin?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 124113, 124115, 124116, 130064, 130102, 136578 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98720, ["x"] = 0.305333, ["y"] = 0.334667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.334667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 252, ["name"] = "Legion Skinning", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40185] = { ["id"] = 40185, ["name"] = "Shoulder the Burden", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "During one of our recent battles, my brother, Lohrumn, was slain. His armor was taken by the drogbar. You would honor his memory by retrieving what has been stolen. I will make it worth your while, leatherworker.", ["objectivesText"] = "Obtain Lohrumn's Shoulderguard . Progress: My brother's armor... have you found it?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129976, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 10, ["flags"] = 0 } } },
[40192] = { ["id"] = 40192, ["name"] = "Claw of the Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "Personal experience has taught me to use stronger materials when crafting armor pieces. They last longer, and you don't need quite as many of them. For example, I utilize the claws of the pinerock stalkers. If you acquire some for me, perhaps I can show you how better materials can increase your efficiency.", ["objectivesText"] = "Obtain 100 Stalker Claws . Progress: Their claws are some of the strongest I've ever come across.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 4801, 130070, 130102, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 17, ["flags"] = 0 } } },
[40194] = { ["id"] = 40194, ["name"] = "Reclaimed Cargo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["description"] = "The same ship that my brother was on also carried shipments of exceptional mail armor. Knowing the giants, they probably had no use for them and left them scattered around their caves. If you could recover those shipments and bring them here, I can explain the techniques used to fashion them. That should give you a good idea of how to improve your processes.", ["objectivesText"] = "Obtain 5 Mail Armor Shipments . Progress: Were you able to recover any of the shipments?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 128898, 128899, 130072, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 19, ["flags"] = 0 } } },
[40198] = { ["id"] = 40198, ["name"] = "Rats!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40202 }, ["description"] = "I tell you, <name>, I have the worst luck sometimes. A package recently arrived from Hrul containing leatherworking patterns, and while my back was turned, some filthy rats came in and ran off with them down into the sewers! Probably building nests with them as we speak. Please, <name>, can you go down there and see if you can retrieve any of them?", ["objectivesText"] = "Go into the Underbelly and recover 3 Highmountain Leatherworking Patterns . Progress: I hope they're not too badly damaged.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 60854, 62996, 62997, 62998, 130077, 130078, 141850, 263358, 263359, 263362, 263364 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 25, ["flags"] = 0 } } },
[40199] = { ["id"] = 40199, ["name"] = "Leather Legwork", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40206 }, ["description"] = "Good news, <name>! Langrom's Leather and Links recently delivered a shipment of mail armor to me. It's of the finest quality and I'd love to show it to ye, but it seems I've lost me crowbar and can't open the crate. If ye could run over to their shop and grab an extra one fer me, we can get this crate opened and go over the construction.", ["objectivesText"] = "Get a crowbar for Thanid. Progress: Fer the life of me, I dunna know where I left the blasted thing!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 69777, 128893, 128897, 130081, 132172, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 26, ["flags"] = 0 } } },
[40201] = { ["id"] = 40201, ["name"] = "Playthings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40200, 40241 }, ["description"] = "Ok, so her ideas were a leash, a bed, and a FLAMING HOOP?! It sounds like they want to start a circus or something. Regardless, I love all those ideas and we should get started as soon as you're ready. Why don't you work on making the bed, and I'll work out the details for the flaming hoop.", ["objectivesText"] = "Craft a prototype for the pet bed. Progress: Make sure it's nice and cozy!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 129960, 130090, 130869, 130870, 130872, 130891, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 29, ["flags"] = 0 } } },
[40203] = { ["id"] = 40203, ["name"] = "Strength of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40204, 40205, 40207, 40208, 40209, 40210 }, ["description"] = "As you know, the durability of your armor is only as strong as the materials you use to make them. Long ago, the black dragon, Deathwing once inhabited this very mountain. In his quest for power, his body began to tear and he had creatures make metal scales to stitch his wounds. His natural scales fell to the ground in his lair and have been there ever since. Go retrieve a scale and bring it to me. This will take all your strength to accomplish.", ["objectivesText"] = "Return a scale of Deathwing to Hrul. Progress: True strength isn't determined by how much you can endure, but by continuing to endure when you lack the strength.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 130098, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 31, ["flags"] = 0 } } },
[40204] = { ["id"] = 40204, ["name"] = "Evolution of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40205, 40207, 40208, 40209, 40210 }, ["description"] = "As we make stronger armor, the creatures we battle adapt and learn to defeat us. We in turn create better armor, and they in turn learn to defeat it yet again. For centuries, my people have battled the basilisks of the mesas below. They have adapted to us as thoroughly as we have to them. Go, kill these basilisks and take from them their hides. Return them to me so I may show you how they have evolved.", ["objectivesText"] = "Obtain 5 Basilisk Hides . Progress: Do not fear change, for change is the only way to move forward.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 130100, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 32, ["flags"] = 0 } } },
[40207] = { ["id"] = 40207, ["name"] = "Scales of the Arcane", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40208, 40209, 40210 }, ["description"] = "In my experience, dragon scale has been the strongest material I've ever had the privilege of working with. It's hard, durable and very little can go a long way. I wish to work with it again, <name>. Being in this form, I'm bound to this area, unable to experience the world any longer. I've heard rumor of the blue dragonflight occupying parts of Azsuna. Perhaps you can speak with them and see if they can shed a scale or two.", ["objectivesText"] = "Speak with the blue dragonflight and acquire one of their scales. Progress: To work with dragon scale again would be a great honor.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 130104, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 35, ["flags"] = 0 } } },
[40208] = { ["id"] = 40208, ["name"] = "Eye of Azshara: Scales of the Sea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8040, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40207, 40209, 40210 }, ["description"] = "When we first met, I spoke of the naga, and the armor they're able to craft. No grander armor is worn, however, than by their top warlords. One in particular resides within the Eye of Azshara itself. His name is Warlord Parjesh, and the hauberk he wears is one of legend. Repel his forces, and obtain his armor. Do this, and I will teach you more of the Azsunian way of leatherworking.", ["objectivesText"] = "Go to the Eye of Azshara and obtain Warlord Parjesh's Hauberk . Progress: He will not just hand it over, <name>. You're in for a rough fight.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 130106, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 8040 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 36, ["flags"] = 0 } } },
[40209] = { ["id"] = 40209, ["name"] = "Scales of the Earth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40203, 40204, 40205, 40207, 40208, 40210 }, ["description"] = "While leather armor is strong on its own, integrating scales into the design is what truly sets it apart. The type of scales you use will determine how many you'll need to fully protect the wearer. And one of the strongest type of scales are basilisk scales. A fully matured basilisk has the strongest of course. Near the village of Llothien is a basilisk den. Kill the matriarch and return her scales to me.", ["objectivesText"] = "Obtain the Axetail Basilisk Matriarch Scales . Progress: You may have to fight past a few of her brood to get to her.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 130110, 141850 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 98964, ["x"] = 0.475, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 37, ["flags"] = 0 } } },
[40213] = { ["id"] = 40213, ["name"] = "Hounds Abound", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40212, 40214 }, ["description"] = "I'll invite him to tea. That'll show him! He'll see the leather doll and say, \"When did SHE get here?!\" I mean... sorry, <name>. My mind goes to strange places. You want to know about the demons, the ones with durable hides? Before I was exiled I saw such beasts roaming our cities. Fel hounds, they are called. Slay them and bring me their corpses. We can discuss their hides afterwards.", ["objectivesText"] = "Obtain 5 Fel Hound Corpses . Progress: We met on the lake. It was spring and she wore ley lilies...", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130129, 140327, 141850 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 98969, ["x"] = 0.265333, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.265333, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 42, ["flags"] = 0 } } },
[40222] = { ["id"] = 40222, ["name"] = "The Imp Mother's Tome", ["level"] = 8, ["requiredLevel"] = 8, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7705, ["mapID"] = 672, ["storyline"] = { 38725, 38727, 38728, 38729, 38759, 38765, 38766, 38813, 38819, 39049, 39050, 39262, 39495, 39515, 39516, 39663, 40051, 40077, 40222, 40378, 40379 }, ["series"] = { 38725, 40051 }, ["description"] = "See this giant cave? There's a terrifyingly powerful imp mother inside. But that's not the good part. The good part is what she has. Apparently, she's some kind of keeper of fel secrets. She's in there performing profane Legion rites and scribing them into a book. We need that power! We need her tome!", ["objectivesText"] = "Obtain the Tome of Fel Secrets . Progress: Do you have it?", ["rewardGold"] = 404400, ["rewardXP"] = 1430, ["rewardItems"] = { 128954, 129957, 133314 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7705 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1481, ["db2PoiUiMapID"] = 672, ["questLines"] = { { ["id"] = 90, ["name"] = "The Key to Defeating the Legion", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6059, ["name"] = "Void Elf Demon Hunter Quests", ["orderIndex"] = 16, ["flags"] = 0 } } },
[40265] = { ["id"] = 40265, ["name"] = "A Touch of Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39874, 39875, 39876, 39877, 39878, 39879, 39880, 39881, 39882, 39883, 39884, 39889, 39891, 39903, 39904, 39905, 39906, 39907, 39910, 39914, 39916, 39918, 39920, 39921, 39923, 40048, 40130, 40169, 40265 }, ["series"] = { 39903, 39904 }, ["description"] = "I always took great pride in my home... and my enchantments. Now it seems both have fallen into ruin. I can sense the power of a potent enchanter in you, <name>. If you would but sprinkle a bit of magic dust on my once-enchanted belongings, I'm sure you can bring them to life again.", ["objectivesText"] = "Sprinkle Arkhana on dormant objects in Tigrid's house. Progress: Just the presence of such a vibrant enchanter gives my home the spark of life!", ["rewardGold"] = 322100, ["rewardXP"] = 1415, ["rewardItems"] = { 71076, 124440, 128535, 128617, 128618, 128619, 128620, 128621, 128622, 129293, 137235 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 98367, ["x"] = 0.394, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 175, ["name"] = "Legion Enchanting", ["orderIndex"] = 15, ["flags"] = 0 } } },
[40266] = { ["id"] = 40266, ["name"] = "The Lost Advisor", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "You may as well assist me while you are here. I require a potion to be made, one that will set things right. I must conserve my energy until my task is finished, lest I become like these miserable wretches scrabbling at the cobblestones. There is coin in it for you, since I will not be needing it soon. The harpies around here cannot resist cliffthorn . It is what drew them to Tel'anor in the first place. You should find plenty just outside this building.", ["objectivesText"] = "Collect 8 Cliffthorn . Progress: <Thaedris seems lost in thought as he gazes towards the city of Suramar .>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130108, 140252, 140326, 141673, 141945, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99065, ["x"] = 0.455, ["y"] = 0.407 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.407 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40306] = { ["id"] = 40306, ["name"] = "The Last Chapter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "The next step of my journey requires a tome, but I find that I am still unable to idly sit by as this place continues to fall into disrepair. I will tidy up the memorials while you go fetch me the tome. It is called the Encyclopedia Botanica and you can find it in the library near the main plaza.", ["objectivesText"] = "Find the Encyclopedia Botanica . Progress: Do you have the tome, <race>?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130208, 140252, 140326, 141673, 141945, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99483, ["x"] = 0.472, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40319] = { ["id"] = 40319, ["name"] = "The Final Ingredient", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "The potion is complete, <name>. Soon our journey will be over. There is one last thing I would have you do for me, then you shall have your reward. My wife's bow was kept here, but I have not been able to find it after searching everywhere. There is potent magic in it. I fear one of the restless spirits may have taken it, but it would take a powerful force to pick up an item such as this. Be careful.", ["objectivesText"] = "Find Latara's bow . Progress: What was that? I heard a familiar voice... it couldn't be.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 130255, 140252, 140326, 141673, 141945, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99575, ["x"] = 0.45, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40331] = { ["id"] = 40331, ["name"] = "Bite of the Sashj'tar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "If I had been by Throndyr's side when he fought the naga, he might still be alive. These serpents will regret the day that they decided to slither from their watery hole! Killing them is not enough. No! I will honor Throndyr with a necklace of naga fangs!", ["objectivesText"] = "Collect 8 Sashj'tar Fangs from Sashj'tar naga in Azuregale Bay. Progress: We will slay them all!", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 132244, 140244, 140245, 140254, 141674, 141675, 141946, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99544, ["x"] = 0.69, ["y"] = 0.54 }, { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 4, ["flags"] = 0 } } },
[40334] = { ["id"] = 40334, ["name"] = "Fisherman's Tonic", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40320, 40331, 40332, 40334, 40336, 40907, 40908, 40927, 41034, 41426, 41709 }, ["description"] = "If you detest these serpents as much as we do, I ask that you continue the fight against them. That will mean fighting them in their watery domain. I don't see any gills on you, so we're going to have to concoct an old tonic used by vrykul fishermen. The ingredients are plentiful around here, taken that you do not mind picking through entrails.", ["objectivesText"] = "Collect 4 Axetail Eyes from Axetail Basilisks, a Sashj'tar Air Bladder from Sashj'tar Naga, and a Sample of Siren Blood from Siren Naz'jul in Azuregale Cove. Progress: I will help you collect what we need.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133960, 133961, 133962, 140244, 140245, 140254, 141674, 141675, 141946, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 102334, ["x"] = 0.722, ["y"] = 0.59 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.722, ["y"] = 0.59 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 341, ["name"] = "Jandvik's Jarl", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40346] = { ["id"] = 40346, ["name"] = "Pilfered Provisions", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 40346 }, ["description"] = "The sea giants are sifting through the shipwrecks looking for treasure. Anything of value that can be found would be better off in the hands of the vrykul.", ["objectivesText"] = "Collect 8 Pilfered Provisions from shipwrecks in Azuregale Bay.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130889 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 130893 } },
[40364] = { ["id"] = 40364, ["name"] = "Bubble Trouble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40364, 41606, 41618 }, ["series"] = { 41606 }, ["description"] = "<class>! The sea giants have already eaten half of my kin. We are helpless in these accursed bubbles. I beseech you to get us out of here. Take heed. These bubbles are strong. You will need something that is extremely sharp to pierce them.", ["objectivesText"] = "Collect a piece of Needle Coral and then rescue 5 Captured Vrykul in Azuregale Bay. Progress: Move quickly, <class>! These sea giants have an insatiable appetite!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130944, 140244, 140245, 140254, 141674, 141675, 141946, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104406, ["x"] = 0.75, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5814, ["name"] = "Brytag", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40368] = { ["id"] = 40368, ["name"] = "Turtle Powered", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40348, 40368, 40370 }, ["description"] = "In order to locate and purify the source of the corruption I am going to need an elemental focus. The turtles around here have developed scales that can focus and amplify their innate magics. Bring back some snapper scales and we will have these waters purified in no time!", ["objectivesText"] = "Collect 7 Shimmering Snapper Scales . Progress: Remember, the scales need to be whole to be of any use as a focus.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 69777, 130942, 132184, 140243, 141944, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99788, ["x"] = 0.434, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 688, ["questLines"] = { { ["id"] = 5766, ["name"] = "Cleansing Tel'anor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40469] = { ["id"] = 40469, ["name"] = "Final Preparations", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40401, 40424, 40469, 40470 }, ["series"] = { 40401, 40424 }, ["description"] = "We will need supplies for our trip into Suramar . We cannot exactly stop for refreshments at the gate with you two in tow, can we? The water gardens were a place to socialize and relax. Before the patrols arrived it was rather trivial to hide some mana wine for later retrieval. That's where you come in. Fetch some supplies and bring them to your friend, then meet me at the ruins north of the city. We will be ready to depart soon.", ["objectivesText"] = "Recover 6 stashed supplies . Progress: Did you find the smuggler? What did they say?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132177, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100192, ["x"] = 0.414, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100185, ["x"] = 0.342, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.414, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5820, ["name"] = "A Desperate Journey", ["orderIndex"] = 1, ["flags"] = 0 } } },
