[40532] = { ["id"] = 40532, ["name"] = "Making the Cut", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Deadly Deep Amber. We'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", ["objectivesText"] = "Craft a Deadly Deep Amber using the Tiffany's cutting tool. Progress: Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", ["rewardItems"] = { 132262, 132265, 132268, 132269, 132467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 10, ["flags"] = 0 } } },
