[40534] = { ["id"] = 40534, ["name"] = "Making the Cut", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Seeing as how you've been quite a reliable resource, I'm willing to teach you how to cut a Masterful Queen's Opal. We'll be using my cutting tool to do this, so whenever you're ready, go ahead and sit yourself in front of it.", ["objectivesText"] = "Craft a Masterful Queen's Opal using the Tiffany's cutting tool. Progress: Make sure not to break the raw gem. We don't just have a stockpile of those lying around.", ["rewardItems"] = { 130215, 130216, 130218, 132262, 132267, 132268, 132269, 132467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 12, ["flags"] = 0 } } },
[40535] = { ["id"] = 40535, ["name"] = "Raising the Drogbar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 641, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40536 }, ["description"] = "Word travels fast around Dalaran, <name>. And the latest word is that there's a master jewelcrafter somewhere in Val'sharah. I want you to go down there and find this master. Perhaps they have designs that can help bolster business here at the shop. I've heard the name \"Lasune Starblade\" tied to these rumors. She might be a good place to start looking.", ["objectivesText"] = "Talk to Lasune Starblade in Val'sharah as to the whereabouts of the jewelcrafting master. Progress: Those damned harpies ambushed Jabrul !", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 132446, 132467 }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 100776, ["x"] = 0.454, ["y"] = 0.693333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.693333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 13, ["flags"] = 0 } } },
[40538] = { ["id"] = 40538, ["name"] = "Lapidary Lessons", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "It's good to see you again, <name>. It seems we've both been busy since last we spoke. I have something that you may be interested in. A recent shipment of rare jewels called maelstrom sapphires have finally arrived here at the shop. I came up with a beautiful design for them and would like to show you how to cut them into something useful.", ["objectivesText"] = "Craft a Well-Cut Maelstrom Sapphire using Tiffany's cutting tool. Progress: I'd recommend keeping a steadier hand than usual with these jewels.", ["rewardItems"] = { 132467, 132484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 15, ["flags"] = 0 } } },
[40539] = { ["id"] = 40539, ["name"] = "Hidden Intentions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["description"] = "Word on the street is, yer a reliable resource for getting things done, let's say, discreetly. So here's the job. I need a new set of lock picking tools. But not just any old lock picks will do. I need something special, something that won't break if ye apply too much pressure. I'm thinking a set of diamond lock picks might do the trick. That would be lock picks made out of diamond, not the ones shaped like a diamond. Look, ye in or what?", ["objectivesText"] = "Collect a set of Diamond Lockpicks for Clive Cozen . Progress: Try not to attract too much attention, okay?", ["rewardItems"] = { 132467, 132882, 137624, 137625 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 16, ["flags"] = 0 } } },
[40542] = { ["id"] = 40542, ["name"] = "Eyes of Nashal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40543, 40544, 40546 }, ["description"] = "Deadly eye of prophecy ... a good choice. Before we can cut, though, we need gems. Here stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need. Ascend the statue, take its jeweled eyes, and return them to Jabrul .", ["objectivesText"] = "Obtain 2 Eyes of Nashal . Progress: Jabrul is anxious to see these jewels up close.", ["rewardItems"] = { 130219, 130220, 130222, 132467, 132767, 132769 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 19, ["flags"] = 0 } } },
[40543] = { ["id"] = 40543, ["name"] = "Eyes of Nashal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40542, 40544, 40546 }, ["description"] = "Quick dawnlight ... a good choice. Before we can cut, though, we need gems. Here stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need. Ascend the statue, take its jeweled eyes, and return them to Jabrul .", ["objectivesText"] = "Obtain 2 Eyes of Nashal . Progress: Jabrul is anxious to see these jewels up close.", ["rewardItems"] = { 130219, 130220, 130222, 132467, 132768, 132769 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 20, ["flags"] = 0 } } },
[40544] = { ["id"] = 40544, ["name"] = "Eyes of Nashal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40542, 40543, 40546 }, ["description"] = "Masterful shadowruby ... a good choice. Before we can cut, though, we need gems. Here stands a giant statue of Nashal, an ancient vrykul. Laid in its eye sockets are two of the stones we need. Ascend the statue, take its jeweled eyes, and return them to Jabrul .", ["objectivesText"] = "Obtain 2 Eyes of Nashal . Progress: Jabrul is anxious to see these jewels up close.", ["rewardItems"] = { 130219, 130220, 130222, 132467, 132769 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 21, ["flags"] = 0 } } },
[40546] = { ["id"] = 40546, ["name"] = "Mysteries of Nature", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40542, 40543, 40544 }, ["description"] = "Jabrul wants to show you his special crystals. Nobody knows what they do. Very mysterious. If you want to learn how to make one, Jabrul would be happy to show you. High in the mountains live storm drakes. They blast the cliffs with their lightning breath and sometimes blast so hard, they turn the rock to crystal. Get a piece of that crystal and bring it back to Jabrul .", ["objectivesText"] = "Recover a piece of Dragon Glass . Progress: Got the stone?", ["rewardItems"] = { 124124, 130172, 130175, 130254, 132467, 132820, 140500 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 100499, ["x"] = 0.422, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 22, ["flags"] = 0 } } },
[40547] = { ["id"] = 40547, ["name"] = "To Dalaran, With Love", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40523, 40524, 40525, 40526, 40527, 40528, 40529, 40530, 40531, 40532, 40533, 40534, 40535, 40536, 40538, 40539, 40540, 40541, 40542, 40543, 40544, 40546, 40547, 40556, 42214 }, ["series"] = { 40556 }, ["description"] = "Jabrul was thinking that he'd like to come up to Dalaran and discuss jewel designs with the masters. But Jabrul doesn't know how to get up to it. Jabrul did have an interesting idea that might work. If you mailed Jabrul to Dalaran, then surely he'd arrive safe and sound.", ["objectivesText"] = "Crate up Jabrul and mail him to the Cartier & Co Fine Jewelry shop. Progress: Jabrul is SO anxious!", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 132467, 132823 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 100521, ["x"] = 0.564, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 178, ["name"] = "Legion Jewelcrafting", ["orderIndex"] = 23, ["flags"] = 0 } } },
[40558] = { ["id"] = 40558, ["name"] = "Socket to Me", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["storyline"] = { 40558 }, ["description"] = "You admire the contraption sitting on the counter. There's a button on it, but pressing it seems to warrant no response. Tiffany tells you that it's an old toy box, but the crystal components are all broken. If you were to find new ones, she could repair it and teach you how to make one for yourself.", ["objectivesText"] = "Obtain all 6 components from around the world. Refer to Tiffany's notebook for reference on where to acquire each piece. Progress: You're going to have to travel all over the world for these, I hope you're up to the challenge.", ["rewardItems"] = { 21756, 21760, 82774, 124444, 130178, 130179, 130180, 130181, 130182, 130183, 130251, 132467, 132838, 132839, 132840, 132841, 132842, 132843, 132925, 132976 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[40559] = { ["id"] = 40559, ["name"] = "Black Rook Hold: The Raven's Wisdom", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["storyline"] = { 40559 }, ["description"] = "<name>, I've been hearing a lot of talk about Black Rook Hold from our friend here, about a room which contains volumes of texts on just about every type of craft there is. I'm willing to bet there's a book in there on jewelcrafting that could come in handy for us. Go there and bring me back anything you find. I'll share a sweet new design I came up with you when you return.", ["objectivesText"] = "Go to Black Rook Hold and locate a book on jewelcrafting and bring it to Timothy Jones in Dalaran. Progress: A book, you'll find, is a design for the mind!", ["rewardItems"] = { 132467, 132859 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon" },
[40560] = { ["id"] = 40560, ["name"] = "Maw of Souls: Spiriting Away", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["storyline"] = { 40560 }, ["description"] = "What I'm about to ask you to do is no easy task, <name>. I need you to die. But, you'll be able to come back of course! There's a ship, the Naglfar, that ferries souls from this world to the next. It's said that an ancient treasure called the Ring of the Fallen rests in the bowels of that ship. You know me, <name>, and nothing catches my interest more than a sweet looking ring. Find a way onto that boat and bring me back that ancient treasure.", ["objectivesText"] = "Go to the Maw of Souls and bring back the Ring of the Fallen to Timothy Jones in Dalaran. Progress: The goddess that rules that world won't let you leave without a fight. Be careful in there, <name>.", ["rewardItems"] = { 132467, 132862 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon" },
[40561] = { ["id"] = 40561, ["name"] = "Halls of Valor: Jewel of the Heavens", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["storyline"] = { 40561 }, ["description"] = "Queens and kings wear the best rings! And I've heard that a certain king of gods has made his presence available. In the Halls of Valor, the ruler Odyn has treasures unlike anyone in existence. If you happen to go there, try and... obtain, let's say, one of his rings for me. I doubt he'll just hand it over, so you may have the fight of a lifetime in store.", ["objectivesText"] = "Kill Odyn in the Halls of Valor and bring back his ring to Timothy Jones in Dalaran. Progress: This will easily be the finest piece in my collection.", ["rewardItems"] = { 132467, 132866 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon" },
[40562] = { ["id"] = 40562, ["name"] = "A Personal Touch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["storyline"] = { 40562 }, ["description"] = "<name>, great to see you again. It feels like forever since last we spoke. We've received some information about a group of jewelcrafting nightborne in Suramar that are doing fantastic things with necklaces. I'd like to take a look at some of their gems. And their designs. And... a new loupe might be nice, too. I hear the city inspectors carry them.", ["objectivesText"] = "Obtain a Nightborne Loupe , a Custom Jewelry Order , and 5 Nightborne Jewelry Cases . Progress: Oh, how did I know about the nightborne gems? Well, that's a trade secret. <Sminx gives you a quick wink.>", ["rewardItems"] = { 132867, 139886, 139887 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[40617] = { ["id"] = 40617, ["name"] = "Turn Around, Nighteyes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40617, 41215, 41216, 41230, 41231, 42223, 43582 }, ["series"] = { 41230 }, ["description"] = "Stranger, you must help me! Nighteyes, my old friend... he was scouting ahead and I heard him cry out a warning. I tried to run after him, but in my carelessness I stepped in this trap. He's so close, just on the other side of this ridge. Please find him!", ["objectivesText"] = "Help Lilryia Dawnwind find Nighteyes. Progress: You must find Nighteyes!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 134120, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 100775, ["x"] = 0.618, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5819, ["name"] = "Hunting the Hunters", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40625] = { ["id"] = 40625, ["name"] = "A Different Source", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "I need you to fetch me something. I think I might be on the verge of a breakthrough of a new source of magic, but I require tools. I can no longer access my workshop, but I have seen the smaller demons below using tools. Bring me one of their tools and I can save our people.", ["objectivesText"] = "Find a Fel Deconstructor for Kyrtos . Progress: Did you find anything? I did not exactly get a chance to pack my things before I was exiled.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 132472, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 0, ["flags"] = 0 } } },
[40642] = { ["id"] = 40642, ["name"] = "Power! Get The Power!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "I need more power. I need more! I can control the energies, and they are enough to sustain me. For now. I will not end up withered, like those weaklings. Go out into Felsoul Hold and slay the demons. Bring me their essence and make it quick!", ["objectivesText"] = "Collect 8 Fel Essence for Kyrtos . Progress: Do you have the essence? I must have it!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 136592, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40657] = { ["id"] = 40657, ["name"] = "The Road to Fel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "An early step to understanding how magic works is to understand and study materials made using that magic. That was how I made my breakthrough on warlock soul crystals, after all. The wyrmtongue minions in this pit hammer plates into their structures for support and maintenance. Those will be a good starting point. Fetch me some, my faithful assistant!", ["objectivesText"] = "Gather 10 Fel-Infused Plates for Kyrtos . Progress: I can practically feel the buildings hum with power.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132761, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 2, ["flags"] = 0 } } },
[40659] = { ["id"] = 40659, ["name"] = "Seeing Stars", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 40659 }, ["description"] = "You think those naga are good sport, little rabbit? <Stokalfr chuckles.> I would savor the chance to do battle with one of those barnacle-crusted behemoths. If you want to impress me, bring me the stars from their heads. I might consider you a true <class> then.", ["objectivesText"] = "Collect 4 Sea Stars from Elder Trenchwalkers in Azuregale Bay.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132559 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40674] = { ["id"] = 40674, ["name"] = "Jars for Jandvik", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 40674 }, ["description"] = "Last time we met, <race>, I was in a cage. You risked your life once before for my kin. Are you willing to aid me once again? The serpents' attack has left many of us wounded. I require mending waters to perform my healing rituals. I have seen the serpents use this water. Return any that you find to me.", ["objectivesText"] = "Retrieve 6 Mending Water from the Sashj'tar Ruins.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132747 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40683] = { ["id"] = 40683, ["name"] = "Discovery Requires Experimentation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "I can sense residues of magic all over you. You will be useful. I must study how the demon bodies can handle the fel energies in such large quantities. I have plenty of flesh to sample, but there must be something... Go retrieve some spines from the nearby basilisks so that I may analyze their magical residues. No sense in both of us getting our hands dirty, is there?", ["objectivesText"] = "Collect 8 Felfire Spines from Felfire Basilisks. Progress: I hope you brought enough. I will require more energy before my studies are complete.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133793, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40730] = { ["id"] = 40730, ["name"] = "Redistribution", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "I would imagine you thought I would simply have wine to deliver. < Deline chuckles.> If it were that easy, his people would not be starving. <Her expression becomes serious.> These... loyalists, shall we say, enjoy abundance. They dance to the Magistrix's whims and so they have all that they need. There is no Arcwine shortage. The Magistrix created one to keep us in line. They will not miss a few bottles. They have plenty. Search the square and bring as much as you can carry back.", ["objectivesText"] = "Acquire 20 Bottles of Arcwine . Progress: Did you find enough?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 137295, 140255, 141677, 141951, 141952, 142054, 166970, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107225, ["x"] = 0.512, ["y"] = 0.76 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.76 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40744] = { ["id"] = 40744, ["name"] = "An Ancient Recipe", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40227, 40266, 40300, 40306, 40315, 40319, 40321, 40578, 40744 }, ["description"] = "Suramar is... was... an intellectual's dream. We studied everything in there, from alchemy and the arts to the very nature of magic itself. How could we be so foolish as to accept them in? Look at me, lost in the clouds again when there is much to be done. My work requires some fairly difficult ingredients, <race>. Perhaps you would help me procure them? I am going to need some harpy talons . Crushed into a powder, they will be a potent reagent.", ["objectivesText"] = "Collect 6 Harpy Talons . Progress: Do you have what I require, <race>? We don't have much time to spare.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 132881, 140252, 140326, 141673, 141945, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99065, ["x"] = 0.455, ["y"] = 0.407 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99093, ["x"] = 0.492, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.407 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 339, ["name"] = "Tidying Tel'anor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40763] = { ["id"] = 40763, ["name"] = "Casual Redistribution", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 40763 }, ["description"] = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. I imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine. With the presence of the demons came rationing. There are many who do not have enough to sustain themselves. Bring me as much Arcwine as you can carry. I will see that it gets to the right people.", ["objectivesText"] = "Collect 20 Bottles of Arcwine .", ["rewardItems"] = { 137295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[40798] = { ["id"] = 40798, ["name"] = "Cling to Hope", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40796, 40798 }, ["description"] = "Your kindness has inspired me, friend. I thought I would wander forever among the empty husks of the Withered, but Thalyssra invited me in. I have chosen to remain here with my people and together we will take back Suramar . For now I have but one request. Take this letter to my wife. She should know that I still live, among other things. Give her the hope that you gave me.", ["objectivesText"] = "Deliver a letter to Absolon 's Wife, Noressa . Progress: < Noressa eyes you suspiciously.>", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 139779, 140235, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101848, ["x"] = 0.3675, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 111318, ["x"] = 0.415, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3675, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5816, ["name"] = "Absolon", ["orderIndex"] = 1, ["flags"] = 0 } } },
[40861] = { ["id"] = 40861, ["name"] = "In My Sights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "I used up all me bullets on a wee invention of mine. I call it: Tha Deployable Bullet Dispenser! Oh aye. It shoots in-der-scriminantly wit'out all that messy and time-consumin' \"aiming\" or \"thinkin'\" that us people-folk are wont ta do. We had deployed quite a few of 'em east o' here when this swarm of plants came a'thrashin from tha trees. I didn't 'ave time ta go back an' get me turrets. Would ye mind gettin' them back fer me? Or at least, what's left of 'em?", ["objectivesText"] = "Recover 10 Deployable Bullet Dispenser Parts around Moonrest. Progress: Those mean greenies better not've touched me dispensers!", ["rewardGold"] = 683200, ["rewardXP"] = 1415, ["rewardItems"] = { 132509, 133671, 133672, 133673, 133674, 133978, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 102197, ["x"] = 0.598, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40863] = { ["id"] = 40863, ["name"] = "Always the Last Thing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40856, 40858, 40864 }, ["description"] = "Well, I've worked out all the kinks. Added a few nuts and bolts, and fitted a new housing for the power core. Problem is, none of the batteries I have here seem to work. I think we're gonna have to fashion somethin' new together. I'm gonna need your help, <name>. Let's start by trying a charged gem from the jewelcrafting shop down the way.", ["objectivesText"] = "Find a suitable power source for Didi's design and deliver it to her. Then, see if her new battery actually works. Progress: Hopefully it's not too much trouble finding a suitable power source.", ["rewardItems"] = { 112059, 123919, 132515, 132523, 132524, 132525, 132526, 132528, 132529, 132530, 132531, 133671, 133672, 133673, 133674, 133879, 133880, 133881, 133895, 137691, 137692, 137725, 139495, 141849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 9, ["flags"] = 0 } } },
[40866] = { ["id"] = 40866, ["name"] = "The Shell, You Say?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40867, 40868 }, ["description"] = "I know ol' Hobart sent me down 'ere to acquire 'is precious murloc glass thingies, but I have designs of me own! I've seen those murlocs carrying interesting lookin' shells that would go perfectly into me music box I've been workin on. Ya lead the charge an'a I'll be right behind ya.", ["objectivesText"] = "Slay murlocs to collect 10 of their shells for Fargo Flintlocke . Progress: Jes let me finish up 'ere and I'll be right with yeh.", ["rewardItems"] = { 132982, 133671, 133672, 133673, 133674, 133782, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 12, ["flags"] = 0 } } },
[40867] = { ["id"] = 40867, ["name"] = "Bubble Baubles", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40866, 40868 }, ["description"] = "Ol' Hobart wanted me ta gather up these shiny, glass trinkets the murlocs carry around, but those bloody buggers ain't willin' to jes' hand 'em over! I tried the dip-ler-matic approach, but I don't speak murloc, so I just end up shootin' 'em. Maybe you might have better luck gettin' them baubles.", ["objectivesText"] = "Gather 12 Murloc Trinkets from around their camps. Progress: Any luck? Did yeh try shootin' 'em?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 133671, 133672, 133673, 133674, 133791, 137691, 137692, 137725, 141849 }, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 102198, ["x"] = 0.782, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 13, ["flags"] = 0 } } },
[40870] = { ["id"] = 40870, ["name"] = "Here Comes the BOOM!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, they stole all my fireworks, the little scamps. You didn't see them? I was just on the verge of creating a new module for Reaves when these kids came in here and ran off with my fireworks. I need them back if I'm going to finish what I'm working on. Can you go get them back for me?", ["objectivesText"] = "Get Didi's fireworks back from the children in Dalaran. Progress: If I ever get my hands on those kids...", ["rewardItems"] = { 132528, 133671, 133672, 133673, 133674, 133794, 133934, 133935, 133936, 137691, 137692, 137725, 141849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 16, ["flags"] = 0 } } },
[40873] = { ["id"] = 40873, ["name"] = "Keep Yer Powder Dry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40874, 40875, 40876 }, ["description"] = "So while we've got all tha parts for tha pack again, I'm afraid I'm all outta gunpowder. This is the worst thing ta ever happen ta me. But there's hope. Just o'er to tha north are caves filled with crashed ships. Chances are them sea giants crashed one or two ships with cannons. And cannons mean gunpowder, sweet gunpowder. Search their caves fer sum powder an' bring it on back.", ["objectivesText"] = "Gather 8 Barrels of Gunpowder and return them to Fargo in Azsuna. Progress: Try not ta get it wet, I dunna feel like waitin' fer it ta dry out.", ["rewardItems"] = { 132513, 133798 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 19, ["flags"] = 0 } } },
[40875] = { ["id"] = 40875, ["name"] = "Going to Waste", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7334, ["mapID"] = 630, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["series"] = { 40873, 40874, 40876 }, ["description"] = "Me wee rogue friend Lowping were gnome-napped by them dirty naga when we got 'ere. He's gone! They drug him right oft toward tha cove! But 'ere's tha real issue. He 'ad a schematic on 'im fer one of me greatest inventions. And by \"on 'im,\" I mean I tattooed it to tha top o' his head. FOR SAFETY! When ye find 'im, jes shave 'is head and make a quick copy o' tha design.", ["objectivesText"] = "Find Lowping in the sea giant caves, shave his head, and make a copy of the schematic that's tattooed there. Progress: Poor lad's probably bein' tortured as we speak. Curse them scaley beasts!", ["rewardItems"] = { 132515, 133799 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 102196, ["x"] = 0.43, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7334 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 21, ["flags"] = 0 } } },
[40877] = { ["id"] = 40877, ["name"] = "Halls of Valor: Trigger Happy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "In order to complete my latest invention, I need a special relic known as the Runestone of Vitality . Odyn, king of the Halls of Valor is known to use it to breathe life into his constructs. What I'm asking is no easy task, but I need to take the runestone from Odyn and bring it back to me.", ["objectivesText"] = "Obtain the Runestone of Vitality from Odyn in the Halls of Valor. Progress: I'm glad you're the one going up against a god and not me.", ["rewardItems"] = { 132519, 133802 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 23, ["flags"] = 0 } } },
[40878] = { ["id"] = 40878, ["name"] = "Assault on Violet Hold: Cheating Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "Hobart was showing me a copy of a design you found, and it got me to thinking of a new module for Reaves. Unfortunately I didn't have the materials required to test it. Could you make me a couple Failure Detection Pylons ? I'll also need a plasmatic laser bolt . You should be able to find one in the Violet Hold.", ["objectivesText"] = "Craft 2 Failure Detection Pylons . Go to the Violet Hold and recover a Plasmatic Laser Bolt and return everything to Didi the Wrench in Dalaran. Progress: Just rip the bolt off of one of the prison cells. I'm sure whatever's inside has long since died.", ["rewardItems"] = { 123919, 132515, 132526, 133946, 136632 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 24, ["flags"] = 0 } } },
[40882] = { ["id"] = 40882, ["name"] = "Court of Stars: Revamping the Recoil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 40545, 40854, 40855, 40856, 40858, 40859, 40860, 40861, 40862, 40863, 40864, 40865, 40866, 40867, 40868, 40869, 40870, 40871, 40872, 40873, 40874, 40875, 40876, 40877, 40878, 40879, 40880, 40881, 40882, 46119, 46128 }, ["description"] = "<name>, you'll be very excited to hear that I've been working on a newer, better version of those goggles that Flintlocke rigged up. The ones I've designed have double the power, but unfortunately they also have double the recoil. I'm afraid if you use them, they'll break your neck. But I found a solution. Deep inside Suramar City lies a magical mechanism that will reduce the recoil to practically nothing. Recover that mechanism for me and we're in business!", ["objectivesText"] = "Go into the Court of Stars and recover the Arcanic Compressor for Hobart. Progress: Those elves probably had no idea the quantum mechanical applications that mechanism has!", ["rewardItems"] = { 133671, 133672, 133673, 133674, 133806, 137975 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 176, ["name"] = "Legion Engineering", ["orderIndex"] = 28, ["flags"] = 0 } } },
[40898] = { ["id"] = 40898, ["name"] = "Fresh Meat", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "This crater is infested with felfire basilisks. They may not be the most cunning of creatures, but they are as vile and dangerous as any demon. However, they may yet prove useful to us. Slay the basilisks, but return to me with chunks of their fel-infused flesh. I have plans to make use of their freshly carved flesh...", ["objectivesText"] = "Collect 6 Fresh Fel-Flesh . Progress: Do you have the Fresh Fel-Flesh I require?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 53563, 53564, 53565, 133743, 140239, 141938, 141939, 156996, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40901] = { ["id"] = 40901, ["name"] = "Grimwing the Devourer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "You have my thanks for rescuing me from captivity, <class>. However, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion. If you wish to continue with me, I need proof of your strength. Grimwing the Devourer is the strongest of the felbats and a suitable test of skill. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears. Return to me with her head and I will not doubt your ability.", ["objectivesText"] = "Slay Grimwing the Devourer. Progress: What news do you bring of Grimwing the Devourer?", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 133756, 134065, 141936, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40919] = { ["id"] = 40919, ["name"] = "Fel Bent for Leather", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40625, 40642, 40657, 40683, 40694, 40713, 40919, 42366 }, ["description"] = "Ah, my faithful assistant. I have just the task for you. As you have seen, fel power permeates living tissue and can easily be coaxed out. Also, these damned bats are driving me to my wits' end. There is an opportunity to kill two bats with one blade, it seems. Your blade. Take this crystal. It should rip those hellions from the sky and into your waiting arms. You may as well bring back their hides, if only to shut up that fellow in the corner for a few moments.", ["objectivesText"] = "Collect 50 Felbat Hide Scraps for Kyrtos . Progress: Have you obtained the hides?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133780, 133925, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101076, ["x"] = 0.268, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5818, ["name"] = "Research Gone to Fel", ["orderIndex"] = 5, ["flags"] = 0 } } },
[40929] = { ["id"] = 40929, ["name"] = "Symbols of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "This demon has information that could lead us to those in charge. Unfortunately, he is more fearful of his master than he is of us. We need to change his mind about that. The most powerful Burning Legion soldiers often carry an emblem of their rank and status within the demon army. Seek out the stronger demons in Felsoul Hold, slay them, and return to me with their emblems. We will show this wyrmtongue servant who it is he should fear...", ["objectivesText"] = "Collect 8 Legion Emblems . Progress: Do you have the Legion Emblems ?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133807, 140239, 141938, 141939, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 7, ["flags"] = 0 } } },
[40947] = { ["id"] = 40947, ["name"] = "Special Delivery", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "Verene's child has gone missing. I can guess what happened, but I need to be sure. Most guardsmen use couriers to relay delicate information. In this, magic is strictly the province of high ranking officials. Take this blade. Do not touch the cutting edge. Use it to silently waylay the couriers and collect any correspondence they carry. With any luck, the missives will tell us exactly where to find the girl. We guards know everything, after all. < Silgryn offers you a winning smile.>", ["objectivesText"] = "Acquire 3 Stacks of Letters from Nightborne Couriers using the Nightborne Spellblade . Progress: Were you successful?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 30256, 30257, 30258, 130209, 137299, 137601, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 108411, ["x"] = 0.482, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107997, ["x"] = 0.482, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 3, ["flags"] = 0 } } },
[40967] = { ["id"] = 40967, ["name"] = "Precious Little Left", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "I have not been able to leave the safety of my guardians to search, but there are three tomes of great importance to me and mine. They contain secrets and cantrips that the Nightborne must NOT obtain. <Lothrius raises his hand to your forehead, cementing the names of three tomes into your mind> If we cannot best them, we must preserve all we can. Hurry, <name>.", ["objectivesText"] = "Locate and recover \" Anthology of the Guard \", \" Magical Manifest of the Moon \", and \" Aftermath of the Well \". Progress: Did you locate them?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133882, 133898, 133899, 133900, 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101768, ["x"] = 0.332, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 6, ["flags"] = 0 } } },
[40970] = { ["id"] = 40970, ["name"] = "The Orchestrator of Our Demise", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "Conjurer Thalerian must be stopped. He immediately sought out my father's private study when he arrived and he has not yet emerged. I worry that he may have found a very dangerous item. It is called the Astromancer's Keystone . It is used to manipulate the stronghold's defenses. Such magic was meant to protect the Moon Guard- used for any other purpose and it becomes unspeakably destructive. Retrieve the Keystone. Slay Conjurer Thalerian to get it, if you must.", ["objectivesText"] = "Slay Conjurer Thalerian and acquire the Astromancer's Keystone . Progress: Is it done?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133924, 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 101765, ["x"] = 0.33, ["y"] = 0.309 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103129, ["x"] = 0.3, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.33, ["y"] = 0.309 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 9, ["flags"] = 0 } } },
[40991] = { ["id"] = 40991, ["name"] = "Opening the Test Kitchen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "cooking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["storyline"] = { 40991 }, ["series"] = { 40988, 40989, 40990 }, ["description"] = "I can cook, but I can't really hunt... or even fish, for that matter. If you bring me ingredients, however, I will use them to research new recipes for you. We can start with the few fish I managed to scrounge up. You'll find them in the barrel in the back of the kitchen.", ["objectivesText"] = "Obtain 5 of Nomi's Silver Mackerel , then bring them to Nomi to research. Progress: Mackerel may not be extravagant, but it will fill your belly.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 86425, 124108, 124110, 124117, 124121, 133564, 133578, 133680, 133816, 133827, 133846, 133912 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[41000] = { ["id"] = 41000, ["name"] = "King Forgalash's Burden", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 41000 }, ["description"] = "That sea witch spoke the truth. I witnessed the Tidemistress confer with King Forgalash on several occasions. Kill Forgalash and bring the prow from his shoulder to Fjolrik as proof of his demise. I will meet afterwards in the center of Jandvik. I need to warm myself by its fires.", ["objectivesText"] = "Retrieve Forgalash's Prow from King Forgalash in Forgalash's Den.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133910 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[41014] = { ["id"] = 41014, ["name"] = "Fury Road", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41014 }, ["objectivesText"] = "Obtain a crystal from Shardmaster Ufrogg Unrefined Gems", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 133944, 133947 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Obtain a crystal from Shardmaster Ufrogg", ["amount"] = 1, ["type"] = 0, ["objectID"] = 102689, ["orderIndex"] = 0 }, { ["text"] = "Unrefined Gems", ["amount"] = 100, ["type"] = 1, ["objectID"] = 133947, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[41030] = { ["id"] = 41030, ["name"] = "Sigil Reclamation", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40883, 40949, 40963, 40964, 40965, 40967, 40969, 40970, 40971, 40972, 41030, 41032 }, ["description"] = "The smooth square sigil weighs a fair amount more than its appearance would suggest. Handling it results in an intense tingling sensation in your palm- this is an object of focused, pure power. Such an advantage should not be so easily surrendered to the Nightborne.", ["objectivesText"] = "Collect 7 Moon Guard Sigils . Progress: What is this?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 133675, 140241, 140242, 140329, 141671, 141943, 142054, 237812 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 101767, ["x"] = 0.336, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 342, ["name"] = "Moon Guard Stronghold", ["orderIndex"] = 1, ["flags"] = 1 } } },
[41097] = { ["id"] = 41097, ["name"] = "Shard of Vorgos", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "According to the wyrmtongue servant, there is a portal that will take you into the Burning Legion command ship. However, the portal is locked to those without the keys. The first key shard is held by an Ered'ruin known as Vorgos. He resides within the Fel Breach, which is at the end of the Arcway. Slay Vorgos and place the key shard into its position next to the portal.", ["objectivesText"] = "Collect the Shard of Vorgos . Progress: <The Shard of Vargos pulses in your hand.>", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 134027, 140239, 141605, 141937, 141938, 141939, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 8, ["flags"] = 0 } } },
[41098] = { ["id"] = 41098, ["name"] = "Shard of Kozak", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "The demon leading the operation in Felsoul Hold is an eredar named Azoran. In order to get to him, we will need to open a portal to the Burning Legion command ship. Azoran has a demon jailer in his service known as Kozak the Afflictor. Kozak the Afflictor holds one of the key shards necessary to open a portal to the ship. He can be found in the prison quarters known as the Halls of the Eclipse in the lower portion of Felsoul Hold. Slay Kozak and place his key shard next to the portal.", ["objectivesText"] = "Collect the Shard of Kozak . Progress: <The Shard of Kozak tugs as if it wants to fly into place.>", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 134028, 140239, 141937, 141938, 141939, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 9, ["flags"] = 0 } } },
[41107] = { ["id"] = 41107, ["name"] = "Bad Apples", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41107, 41256, 41258 }, ["description"] = "That fruit over there? That's a pale imitation to what I can grow. But that accursed Daglir somehow manages to gain the favor of the courts, so we must dine on mediocrity! We must teach Daglir a lesson for stealing my crop, but we must be discreet. Outside the shield grows a purple flower called Shadowbloom . Fetch some for me and we'll make sure that he pays dearly for his insolence!", ["objectivesText"] = "Gather 8 Shadowbloom . Progress: I would avoid eating any food until you've washed your hands.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 134014, 141948, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103131, ["x"] = 0.472, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5823, ["name"] = "Fruit of the Doom", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41139] = { ["id"] = 41139, ["name"] = "The Key Is Around Here Somewhere...", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["description"] = "Well aren't ye a sight fer sore eyes! It's no use tryin' to bust open this cage, this one needs a key! Now, I know what yer thinkin', \"How is it possible that the Burnin' Legion could capture a dwarf as mighty as ol' Angus here.\" Ye can rest easy knowin' I let myself be captured. I'm here to rescue a dear friend o' mine, an' gettin' captured was the only way! I had the key in me pocket... but it musta' fell out. It's errm... around here somewhere. A felhunter ate it a wee while back...", ["objectivesText"] = "Find the Reinforced Cage Key . Progress: Did ye find the key?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 134051, 134055, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103204, ["x"] = 0.284, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103204, ["x"] = 0.284, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 0, ["flags"] = 0 } } },
[41140] = { ["id"] = 41140, ["name"] = "Search and Rescue!", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41139, 41140, 41214, 41222, 41309 }, ["description"] = "We've got to find Brambley before it's too late! Ol' Brambley an' I have been fightin' side by side since the Third War. When the Burnin' Legion invaded, we didn't think twice about coming to the Broken Isles. Fightin' is what we do best! During the battle ol' Brambley got caught too deep an' got himself captured. Now we've got to rescue him! Last I saw, the demons were keeping him in a prison cell not far from here... let's go!", ["objectivesText"] = "Find Brambley Morrison. Progress: Have you found the key yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 39648, 39649, 39650, 134080, 141940, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103204, ["x"] = 0.284, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 102365, ["x"] = 0.27, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.284, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5817, ["name"] = "In Search of Brambley", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41148] = { ["id"] = 41148, ["name"] = "Dispensing Compassion", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "There is much you need to learn about our city. First and foremost, Arcwine. It is the vehicle by which we imbibe the Nightwell's energies. Without it, we wither and die. Palace lackeys have seen fit to ration it, thinking this will control us. Keep us quiet, complacent. I would like you to look for those in need near the tavern. You will find many, but those most desperately afflicted by this rationing will be obvious. Take this flask. Revive them. Tend to their suffering.", ["objectivesText"] = "Offer Arcwine to suffering citizens. Progress: Have you served those who suffer?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138308, 140255, 141677, 141951, 141952, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107598, ["x"] = 0.424, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41157] = { ["id"] = 41157, ["name"] = "Corrupted Studies", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 40857, 41157 }, ["series"] = { 40857, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "Stormheim is steeped with artifacts from tha War of the Ancients. Demon artifacts ta be exact. I think these artifacts can clue us into some knowledge about their leader, Sargeras. I've already found some fragments to a titan disc, but need ta find the rest of 'em. I need ya ta dig around Stormheim and see if ye can find any more fragments so we can reassemble the disc.", ["objectivesText"] = "Survey digsites in Stormheim and bring Brann back 200 War of the Ancients Fragments . Progress: With so many demon artifacts buried here, it's a wonder this place is as vibrant as it is.", ["rewardItems"] = { 134082, 136360, 136362 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 321, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41162] = { ["id"] = 41162, ["name"] = "And Into the Fel Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41161, 41162, 41163 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41163, 41164, 41165, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "I found something, <name>. Well, a couple of things actually. First I found an ancient text talking about a demon who harnessed the power of the titan disc I've been searching for. Then I found a device which supposedly is used to summon 'im! Only, it's missin' some pieces from what I can make out. I'm sure if we survey around Azsuna some more, those missin' pieces are sure ta turn up.", ["objectivesText"] = "Survey digsites in Azsuna and find 10 missing Parts of the Infernal Device and bring them back to Brann. Progress: From what I can make out, I think there's only seven or eight parts we need...", ["rewardItems"] = { 134084, 146328 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 327, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41165] = { ["id"] = 41165, ["name"] = "Deciphering Demonology", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41164, 41165, 41166 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41166, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "I found a piece of what appears to be a key to something. I'm certain I can restore it if we can find the other bits. After that, we need to figure out what it's a key to. An' I think I know how to do that. I've been studying some of the artifacts I've found, and they seem to be pointing to a hidden chamber. I jes' need some more artifacts to study.", ["objectivesText"] = "Crate artifacts into 5 Restored Artifacts and find 5 Chamber Key Fragments and bring them to Brann. Progress: How goes the search?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 87399, 109076, 131743, 134085 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 330, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41166] = { ["id"] = 41166, ["name"] = "Dark Secrets", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41164, 41165, 41166 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41167, 41168, 41169, 41170, 41802 }, ["description"] = "I fixed the key and am ready to open the chamber. Meet me there when you have a chance and we'll discover what waits inside together!", ["objectivesText"] = "Meet Brann at the entrance to the secret chamber. Once inside, stay close to Brann in case anything happens. Progress: I always love a good adventure!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 131743, 136397, 136398 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 330, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41168] = { ["id"] = 41168, ["name"] = "The Purple Hills of Eredath", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41167, 41168, 41169 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41169, 41170, 41802 }, ["description"] = "Now that we're re-supplied, we can get back ta work. I found something here that I think ye'll be interested in. It's a page of a book talking about the world of Argus. But before the demons destroyed it. Anyway, it's been me experience that if ye find one of something, there's sure ta be more of it around. Keep lookin' around Val'sharah for more of these pages and bring what ye find back ta me. And take the page I found with ya so ye know what yer lookin' fer.", ["objectivesText"] = "Find the remaining pages of The Purple Hills of Eredath and assemble them into the final book. Return the book to Brann when you have finished. Progress: I can't wait to read the rest of that story.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 134087, 134088, 134089, 146328 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 332, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41169] = { ["id"] = 41169, ["name"] = "Darkheart Thicket: Through the Fog", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41167, 41168, 41169 }, ["series"] = { 40857, 41157, 41158, 41159, 41161, 41162, 41163, 41164, 41165, 41166, 41167, 41168, 41170, 41802 }, ["description"] = "I can't believe that after all that searchin' ye did, it's still missing a chapter! I'm willin' ta bet that those satyrs got a hand on it and took it somewhere. Probably somewhere dark where no one could find it. I've heard rumors of a place, the Darkheart Thicket they call it, where the strongest of the satyrs are. If I had ta guess, I'd say ye need to go there and look around fer it.", ["objectivesText"] = "Obtain the Final Chapter of The Purple Hills of Eredath . Progress: A world of nightmares is nowhere where anyone should have ta go to.", ["rewardItems"] = { 131732, 134090, 134091 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103484, ["x"] = 0.391333, ["y"] = 0.378667 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.391333, ["y"] = 0.378667 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 332, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41176] = { ["id"] = 41176, ["name"] = "Sifting Through the Rubble", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41174, 41175, 41176 }, ["description"] = "Then I believe it's clear what we must do next. Find the jewels. They're bound to be here somewhere in Suramar, so we better start looking. I'll coordinate the search from here, while you and my assistants look for the jewels.", ["objectivesText"] = "Survey different areas around Suramar until you find the 6 missing Jewels of the Crown. Progress: What's the status on the search for the jewels?", ["rewardItems"] = { 60847, 87399, 109076, 128561, 131740, 134114 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 324, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41184] = { ["id"] = 41184, ["name"] = "Tried and True", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41183, 41184, 41185 }, ["description"] = "I have realized through experience that the old methods are usually the best and for good reason. I'm done with alternate means of digging for now, and wish to focus on the right way to do things. That being said, I believe I've found a new powerful artifact and I'll do literally anything to have it. I've uncovered a fragment that appears to be a mold for a key. I now simply need the other pieces.", ["objectivesText"] = "Find the remaining 15 Azsunian Key Mold Pieces and return them to Tae'thelan. Progress: Have you recovered any of the other pieces yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 131744, 134117 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 331, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } } },
[41185] = { ["id"] = 41185, ["name"] = "The Keys to Success", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 630, ["storyline"] = { 41183, 41184, 41185 }, ["description"] = "I'd like you to take the mold to the blacksmith in Dalaran. Alard, I believe his name is. Have him help you forge a new set of keys. I found some writing on the back of the mold that may hold the answer to what these keys unlock. I'll stay here and try to translate the text.", ["objectivesText"] = "Bring the mold to Alard Schmied in Dalaran and have him help you forge a new set of keys. Return to Tae'thelan when you have the finished set. Progress: The key is clearly tied to something here in Azsuna.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 131744, 134832, 134833, 134834, 134835 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 103482, ["x"] = 0.474, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 331, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41188] = { ["id"] = 41188, ["name"] = "Neltharion's Lair: Misdirected", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41186, 41187, 41188 }, ["description"] = "I've been looking into the history of Huln Highmountain, a legendary warrior from the War of the Ancients whom this very land is named after. Allegedly some of his personal effects were carried here after his death and have been lost in time. After some digging around I believe I have discovered the location of one of his artifacts to be in a place called Neltharion's Lair. I'm no fighter, <name>, but you are. Will you go and recover this artifact for me?", ["objectivesText"] = "Go to Neltharion's Lair and recover the Ancient Highmountain Artifact . Progress: If I've followed the clues correctly, then this could lead to one of Huln's weapons.", ["rewardItems"] = { 131733, 134093 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 323, ["name"] = "Legion Archaeology", ["orderIndex"] = 2, ["flags"] = 0 } } },
[41193] = { ["id"] = 41193, ["name"] = "Laying to Rest", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "archaeology" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7731, ["mapID"] = 650, ["storyline"] = { 41192, 41193 }, ["description"] = "If I was able to find a bone fragment in what appeared to be a random location, then that means Eche'ro's bones must be scattered around Highmountain. We must find his remains and give him the proper burial he deserved. Oh, I'm sorry, in case you weren't aware, Eche'ro was Huln Highmountain's mount and companion. He deserves to be honored as Huln once was.", ["objectivesText"] = "Find 600 Bone Fragments of Eche'ro and return them to Lessah in Highmountain. Then observe the burial ceremony Lessah performs. Progress: We must see to it that his remains are given the respect they deserve.", ["rewardGold"] = 929400, ["rewardXP"] = 2615, ["rewardItems"] = { 87399, 124671, 128561, 130904, 131734, 131811, 131900, 134095, 139773, 146326 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7731 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 333, ["name"] = "Legion Archaeology", ["orderIndex"] = 1, ["flags"] = 0 } } },
