[41307] = { ["id"] = 41307, ["name"] = "All That Glitters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["series"] = { 41123, 41466 }, ["description"] = "Now that the shield is down, the older settlements outside the city have been on my mind. Did you know that I helped create the filigree on the arcane lamps that are used throughout the city? A simple task, one of my first... No matter. Nostalgia is the enemy of progress. The lamps are made of material better used in my new works. Those wretched harpies probably have several decorating their nests. Bring back any you find.", ["objectivesText"] = "Retrieve 6 Arcane Glowlamps . Progress: Can you imagine, a Lespin original hiding under a pile of leaves? What a waste.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 136537, 141949, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 1, ["flags"] = 0 } } },
