[41394] = { ["id"] = 41394, ["name"] = "Service with a Smile", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 357, ["mapID"] = 69, ["storyline"] = { 41394 }, ["description"] = "Oh, simple <race>. Simple, simple <race>. I did not 'forget' to sweep up those reins from that foolish cakewalk of a knight they call the Lich King. I simply did not bother, as I already received the mighty steed during my raid last week. <Johnny motions to the horse on his left.> Since you're here and clearly intrigued by my sweltering greatness, won't you take that superfluous stallion to the assistant resort director in town? My coffers could use a bit of extra lining.", ["objectivesText"] = "Sell Invincible's Reins to Gott Weedlespan for Johnny Awesome . Progress: Do not tarry, <class>. The longer you take, the longer until you may dote on me as one of my many admirers.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 3466, 4338, 7912, 45693, 134859, 135463, 135464, 156721, 156833 }, ["starts"] = { { ["mapID"] = 69, ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73 } }, ["ends"] = { { ["mapID"] = 69, ["npcID"] = 52562, ["x"] = 0.686, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 69, ["source"] = "quest_giver", ["x"] = 0.686, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 69 }, ["zone"] = { 357 } }, ["questType"] = "standard" },
[41410] = { ["id"] = 41410, ["name"] = "Dry Powder", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41409, 41410 }, ["description"] = "<name>... I did not expect to see you down here. The Sashj'tar are... rallying against Jandvik. I had a plan to... decimate them using these old powder kegs. The naga proved more formidable to these old bones than I thought. < Fjolrik coughs out some blood.> We haven't much time... to prepare.", ["objectivesText"] = "Collect 5 Sealed Powder Kegs from the shipwrecks in Azuregale Bay. Progress: Move quickly, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135478, 140244, 140245, 140254, 141674, 141675, 141946, 142054, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104586, ["x"] = 0.775, ["y"] = 0.598 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 104586, ["x"] = 0.775, ["y"] = 0.598 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.598 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5821, ["name"] = "Protecting Jandvik", ["orderIndex"] = 0, ["flags"] = 0 } } },
