[41465] = { ["id"] = 41465, ["name"] = "Estate Jewelry: A Braggart's Brooch", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["series"] = { 41320 }, ["description"] = "Amateur merchants worry about losing face from bad products. Masters worry about losing face from bad customers. Naltethis Springblade has grown too bold for his station, and as such has lost much standing in the eyes of the city's elite. I sold this man a brooch, a clasp he wears on his cape. I am careful to only sell to those above my station. My pieces never tarnish, but my name and reputation are much more fragile. Relieve him of my property before he lowers me further.", ["objectivesText"] = "Retrieve Lespin's Brooch from Naltethis Springblade. Progress: That oaf will undo years of hard work. It is so much easier to fall than it is to climb...", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 135508, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 3, ["flags"] = 0 } } },
[41466] = { ["id"] = 41466, ["name"] = "Estate Jewelry: Haute Claw-ture", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["series"] = { 41123, 41307 }, ["description"] = "An amateur merchant looks back on their previous work as a learning experience. A master knows that some things are better left forgotten. I was... vain, centuries ago. Desperate to prove myself, I took on a bold commission. Find him and bring... it... back. You will know what I am talking about when you see it. He resides near the villa south of this courtyard.", ["objectivesText"] = "Find and retrieve Lespin's 'art' from Mornath. Progress: He was so passionate, so driven. I saw his vision, created it to his exact specifications. Beautiful filigree and enamel put to a fearsome weapon...", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 135509, 136577, 140247, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103175, ["x"] = 0.415, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.415, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 4, ["flags"] = 0 } } },
