[41839] = { ["id"] = 41839, ["name"] = "The Taken", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 41839 }, ["series"] = { 41815, 41840, 41841, 41882, 48403 }, ["description"] = "When Mayla's father was taken, so were the corpses of several of our greatest chieftains. The Grey One, even now, is priming Mayla's father to be a vessel for his evil agenda. But the others have already been taken by the necrodark, their corpses now vessels for malevolent drogbar spirits. I will be honest, I do not think my skills could defeat these monstrosities. We need your help!", ["objectivesText"] = "Defeat the Taken Chieftains.", ["rewardGold"] = 309800, ["rewardXP"] = 2090, ["rewardItems"] = { 37206, 37403, 37417, 37482, 197642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[41840] = { ["id"] = 41840, ["name"] = "Ice and Shadow", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41815, 41839, 41841, 41882, 48403 }, ["description"] = "We took down one of the Necrodark. Ebonhorn found that it held a shard of ice infused with shadow essence. Perhaps the villains are using these shards as a kind of talisman. I suggest you deprive them of their trinkets. I know little of such magics, but it seemed that Ebonhorn had a use for them in mind.", ["objectivesText"] = "Collect 20 Shadowice Shards . Progress: Did you find more of the shards?", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 136400 }, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 130423, ["x"] = 0.564, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 105213, ["x"] = 0.57, ["y"] = 0.922667 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 4, ["flags"] = 0 } } },
[41889] = { ["id"] = 41889, ["name"] = "Dazed of the Past", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 39958, 40176, 40177, 40178, 40179, 40180, 40181, 40182, 40183, 40184, 40185, 40186, 40187, 40188, 40189, 40190, 40191, 40192, 40193, 40194, 40195, 40196, 40197, 40198, 40199, 40200, 40201, 40202, 40203, 40204, 40205, 40206, 40207, 40208, 40209, 40210, 40211, 40212, 40213, 40214, 40215, 40241, 40327, 40415, 41889 }, ["series"] = { 40196, 40197 }, ["description"] = "Let's begin crafting this mount armor, shall we?", ["objectivesText"] = "Construct a Stonehide Leather Barding . Progress: I'm quite anxious to see how it turns out.", ["rewardGold"] = 202200, ["rewardXP"] = 1415, ["rewardItems"] = { 130887, 130891, 130894, 130895, 130896, 141850 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 179, ["name"] = "Legion Leatherworking", ["orderIndex"] = 24, ["flags"] = 0 } } },
[41915] = { ["id"] = 41915, ["name"] = "The Master's Legacy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41123, 41146, 41307, 41320, 41465, 41466, 41915 }, ["description"] = "You work for a murderer and a thief. That design he wants? It is called the magistrix cut, and it was perfected by my husband. He was killed by Lespin for his secret. I had him entombed in a small cave north of the city, for we could not make the trip to Tel'anor. Buried with him is a tome that contains the secrets of the design. Retrieve the design and keep it out of his hands!", ["objectivesText"] = "Investigate the Gemcutter's Tomb. Progress: Where is the master?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 135507, 140248, 237812, 247917 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 104394, ["x"] = 0.416, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103181, ["x"] = 0.416, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.416, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5822, ["name"] = "The Master Jeweler", ["orderIndex"] = 6, ["flags"] = 0 } } },
