[42147] = { ["id"] = 42147, ["name"] = "First Contact", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 41762, 41834, 41989, 42079, 42147 }, ["series"] = { 42079 }, ["description"] = "Time to put your new disguise to the test. Your first contact is Vanthir , a merchant from the common district. He is in the Grand Promenade today visiting one of his suppliers. Tell Vanthir to pay me a visit regarding a shipment of dusk lily bulbs. He will understand. Beyond that, we will need time to prepare. You should return to Thalyssra. <Ly'leth hands you a corked bottle of faintly glowing fluid.> Give her this, with my regards. We will call upon you soon.", ["objectivesText"] = "Speak with Vanthir in The Grand Promenade. Progress: Have you made contact with our sympathizers?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137010, 137011, 141947, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 105342, ["x"] = 0.434, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 156, ["questLineOrder"] = 3 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 156, ["name"] = "Masquerade", ["orderIndex"] = 4, ["flags"] = 0 } } },
