[42489] = { ["id"] = 42489, ["name"] = "Thalyssra's Drawers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40727, 40730, 40745, 40746, 40947, 41148, 41877, 41878, 42486, 42487, 42488, 42489, 42722 }, ["description"] = "Thalyssra's ransacked estate still contains a number of items important to Thalyssra. Collect them and return them to her.", ["objectivesText"] = "Search Thalyssra's estate and collect her belongings. Progress: What did you find?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 130209, 138193, 138194, 138195, 140255, 141677, 141951, 141952, 142054, 237812, 248009 }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 200, ["questLineOrder"] = 6 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 200, ["name"] = "The Waning Crescent", ["orderIndex"] = 12, ["flags"] = 0 } } },
[42491] = { ["id"] = 42491, ["name"] = "The Arcway: Long Buried Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42491 }, ["description"] = "Beneath Suramar City is an ancient network of tunnels known as the Arcway. They were abandoned some time ago as part of the cavern became unstable. Since then, who knows? Regardless of what is currently down there, I believe you will find something essential to our continued success. Long ago my people took a thorough survey of the ley lines in and around Suramar . This they would have stored in the library in the Arcway. Find this map for me.", ["objectivesText"] = "Acquire the Suramar Leyline Map from the Arcway. Progress: Did you find it?", ["rewardGold"] = 1239200, ["rewardXP"] = 12280, ["rewardItems"] = { 138394, 140255, 140409, 140421, 140422, 141680, 141955, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115371, ["x"] = 0.37, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon" },
[42725] = { ["id"] = 42725, ["name"] = "Sharing the Wealth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 680, ["storyline"] = { 42725 }, ["description"] = "Lately there have been a disturbing array of changes involving our most precious resource, Arcwine. I imagine Thalyssra has thoroughly educated you about what happens when a Nightborne does not have access to a source of power like Arcwine. With the presence of the demons came rationing. There are many who do not have enough to sustain themselves. Bring me as much Arcwine as you can carry. I will see that it gets to the right people.", ["objectivesText"] = "Collect 20 Bottles of Arcwine .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137295 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Bottles of Arcwine Delivered to Deline", ["amount"] = 20, ["type"] = 1, ["objectID"] = 137295, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[42962] = { ["id"] = 42962, ["name"] = "Secret Correspondence", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 42962 }, ["objectivesText"] = "Acquire 3 Stacks of Letters from Nightborne Couriers using the Nightborne Spellblade .", ["rewardGold"] = 276200, ["rewardXP"] = 6140, ["rewardItems"] = { 137299, 137601 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Stack of Letters", ["amount"] = 3, ["type"] = 1, ["objectID"] = 137601, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[43215] = { ["id"] = 43215, ["name"] = "Tracking Down the Scepter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 43215 }, ["series"] = { 43100, 43153 }, ["description"] = "The logbook contains the latest information on the Scepter of Sargeras. It appears to have been written by an extremely agitated, excited, or psychotic imp and is barely legible. Take this to Calydus for translation.", ["objectivesText"] = "Take the logbook to Calydus in Dreadscar Rift.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 139046 } },
[43314] = { ["id"] = 43314, ["name"] = "Court of Stars: Beware the Fury of a Patient Elf", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43314 }, ["description"] = "An opportunity presents itself, <name>. Ly'leth has arranged to grant you entry into a ball at the Court of Stars . I do not know what we may gain from this venture, but there is one task I must set for you. Advisor Melandrus once called himself my ally. He and I planned Elisande's downfall, but when the moment came I found myself betrayed. The wound his dagger inflicted still aches. I cannot enter Suramar to take my revenge, but you can. Give him a traitor's death, and bring me his spellstone.", ["objectivesText"] = "Enter the Court of Stars dungeon and slay Advisor Melandrus. Collect his Spellstone and return it to Thalyssra. Progress: Is it done?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 140255, 140409, 140421, 140422, 140757, 141680, 141955, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 112146, ["x"] = 0.365, ["y"] = 0.468 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 97140, ["x"] = 0.367333, ["y"] = 0.465333 }, { ["mapID"] = 680, ["npcID"] = 115736, ["x"] = 0.364667, ["y"] = 0.461333 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "dungeon" },
[43331] = { ["id"] = 43331, ["name"] = "Time to Collect", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 39786, 39787, 39789, 39792, 39793, 42483, 43331 }, ["description"] = "Hey there, pal. My sources around here say you had a run-in with the Sixtrigger brothers. I'd imagine you're not very happy with them? Let's just say we're not exactly friends either. So I'll tell you what. How about I let you in on some intel about their current location? Maybe they might have an unfortunate accident, you follow? Oh, and bring some friends. They're not exactly the easiest of targets.", ["objectivesText"] = "Collect Sixtrigger's Key from Rax Sixtrigger in Stormheim . Progress: This seems to be where the Sixtrigger brothers keep their most prized spoils.", ["rewardXP"] = 7675, ["rewardItems"] = { 109076, 124121, 127834, 128832, 132203, 132226, 132240, 133563, 133815, 133942, 133983, 138111, 138123, 138125, 138127, 138129, 138131, 138133, 138135, 139276, 140592, 140593, 140594, 140595, 140596, 140597, 140598, 140599, 140600, 140601 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7541 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 422, ["name"] = "Stormheim", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 5927, ["name"] = "Lock, Stock, and Two Smoking Goblins", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43361] = { ["id"] = 43361, ["name"] = "Fragments of Disaster", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "In the hall beyond rests the bones of the failed arcan'dor. I will take fragments of the crystallized tree and attempt to read them. We must discover the root cause of this destruction. Only then do we have any hope of preventing this disaster from repeating itself.", ["objectivesText"] = "Collect 5 Crystallized Bark . Progress: Do you have the shards?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 139340, 140255, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 684, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43362] = { ["id"] = 43362, ["name"] = "The Stuff of Dreams", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40125, 43360, 43361, 43362, 44152, 44156 }, ["description"] = "This arcan'dor is one of an ancient species. They were not bred, but created. In them the arcane and primitive druidic magics merged into something greater than both. The arcane will soon devour it whole. We can restore balance, but it will require wild magic. Magic trapped in another realm. You must enter the Emerald Dreamway and bring back the essence of life itself. Only then can the arcan'dor find stability and begin to thrive once more.", ["objectivesText"] = "Collect Purified Life Essence from the Emerald Dreamway. Progress: Do you have it?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 139342, 140255, 140444, 237812, 246812, 246815, 246937, 249783, 254267 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 203, ["questLineOrder"] = 9 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 203, ["name"] = "A Growing Crisis", ["orderIndex"] = 5, ["flags"] = 0 } } },
[43563] = { ["id"] = 43563, ["name"] = "Ephemeral Manastorm Projector", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43502, 43562 }, ["description"] = "Oculeth's theory is sound. Reckless, but sound. A small warp-field could trap and excite ambient mana in the conduit, thus creating a manastorm similar to when the arcan'dor fell out of balance. I can build a device to generate the warp-field, but I need materials. Specifically, warp-resistant alloys - such as the armor plating of high-end security constructs in the noble district. Those constructs are deadly. If anyone owes you a favor, now is the time to call it in.", ["objectivesText"] = "Collect 4 Warp-Resistant Plating from Chronarch Defenders. Progress: Without those plates, the E.M.P. would rip itself apart in seconds.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 131811, 133755, 139689, 141253, 141605, 141683, 142401, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 103155, ["x"] = 0.37, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } }, ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 2, ["flags"] = 0 } } },
[43568] = { ["id"] = 43568, ["name"] = "Arcan'dor, Gift of the Ancient Magi", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 43502, 43562, 43563, 43564, 43565, 43567, 43568, 43569 }, ["series"] = { 43567 }, ["description"] = "Thousands of years ago, as the Quel'dorei were just beginning to unravel the mysteries of the arcane, a small enclave of druids met with the first of the elven magi. In the pale moonlight, they formed an order that would seek to bring the arcane into balance - using nature itself as a vessel. Thus the arcan'dor were created. My masters who belonged to this order have long since faded away. Yet their legacy remains. Their gift will mend the spirit of the shal'dorei. Let them eat, and be made whole.", ["objectivesText"] = "Pick the Fruit of the Arcan'dor and share it with Chief Telemancer Oculeth , Arcanist Valtrois , and First Arcanist Thalyssra . Progress: The shal'dorei must eat the fruit of the arcan'dor . It is the only way to free them.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140315, 140445, 237812, 246937 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 107126, ["x"] = 0.2972, ["y"] = 0.4404 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 112146, ["x"] = 0.365, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.2972, ["y"] = 0.4404 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 288, ["title"] = "Nightfallen", ["questLineID"] = 204, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 204, ["name"] = "A Change of Seasons", ["orderIndex"] = 6, ["flags"] = 0 } } },
[43590] = { ["id"] = 43590, ["name"] = "Leyline Feed: Ley Station Moonfall", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["storyline"] = { 43590 }, ["description"] = "<This leyline feed appears to be damaged. The large collector at the top is broken. The broken piece must be around here somewhere. There are rough scuff marks on the floor that appear to be made by something larger than the creatures inside. Much, much larger.>", ["objectivesText"] = "Find the Broken Leydar Dish and repair the leyline feed . Progress: <The feed pulses softly.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 140847, 141652, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "group", ["activities"] = { ["groupFinder"] = { { ["id"] = 423, ["name"] = "Suramar", ["mapID"] = 0, ["difficultyID"] = 0, ["expansion"] = 6, ["maxPlayers"] = 0 } } } },
[43591] = { ["id"] = 43591, ["name"] = "Leyline Feed: Ley Station Aethenar", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["storyline"] = { 43591 }, ["description"] = "<This leyline appears to be damaged and needs repair. Several large chunks of the main column are missing and arcane energy is crackling in the gaps. The elementals nearby seem to pick up debris and absorb it into their bodies as they move around. Maybe they have the missing pieces...>", ["objectivesText"] = "Collect 6 Leyline Feed Fragments and infuse the feed with ancient mana . Progress: <The leyline feed crackles as wild energy escapes the gaps in the column.>", ["rewardXP"] = 6140, ["rewardItems"] = { 140317, 140318, 141652, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7637 } }, ["questType"] = "standard" },
