[44112] = { ["id"] = 44112, ["name"] = "Trading for Dreams", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 44112 }, ["series"] = { 39337, 39338, 39431 }, ["description"] = "From the look of you, I take it you're an alchemist, yes? I'd be willing to trade my services with you for a price that I deem is fair. I have been away from Suramar for some time now. I long for an Ysera's Dream Draught . To concoct it, you'll need some dreamleaf as well as the leaves of a Dreamer's Tear. One grows not to far from here in the clearing of some ruins. Take my flask, make this drink for me, and I'll do as you ask.", ["objectivesText"] = "Use the Nightborne Flask to craft an Ysera's Dream Draught . Progress: < Leyweaver Erenyi seems lost in thought.>", ["rewardXP"] = 1415, ["rewardItems"] = { 124102, 124103, 124106, 124116, 124124, 127834, 127835, 127836, 127837, 127838, 127839, 127840, 127841, 127842, 127843, 127844, 127845, 127846, 127847, 127848, 127849, 127850, 127851, 127901, 127902, 127903, 127904, 127905, 127906, 127907, 127908, 127909, 127910, 127915, 127930, 127932, 127933, 128209, 128304, 136827, 136835, 136836 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 93974, ["x"] = 0.704667, ["y"] = 0.465333 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.704667, ["y"] = 0.465333 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard" },
[44283] = { ["id"] = 44283, ["name"] = "The Emerald Nightmare: Piercing the Veil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8026, ["storyline"] = { 44283 }, ["description"] = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", ["objectivesText"] = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Normal difficulty. Progress: If only Cenarius were with us, we could confront Xavius at once.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 141303, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8026 } }, ["questType"] = "raid" },
[44284] = { ["id"] = 44284, ["name"] = "The Emerald Nightmare: Piercing the Veil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8026, ["storyline"] = { 44284 }, ["description"] = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", ["objectivesText"] = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Heroic difficulty. Progress: If only Cenarius were with us, we could confront Xavius at once.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 141303, 141304, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8026 } }, ["questType"] = "raid" },
[44285] = { ["id"] = 44285, ["name"] = "The Emerald Nightmare: Piercing the Veil", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8026, ["storyline"] = { 44285 }, ["description"] = "The darkness of the Nightmare is like a heavy shroud, warping reality and altering the perception of all living things. As areas of the Dream are cleansed, Xavius's hold weakens, and the way to the heart of the Nightmare will be revealed. But there might be a more direct way... my teacher once spoke of a pure power that could illuminate the darkness of the Nightmare, and allow all paths to become clear. But alas, Cenarius is lost....", ["objectivesText"] = "Collect 4 Essences of Clarity from Cenarius in The Emerald Nightmare on Mythic difficulty. Progress: If only Cenarius were with us, we could confront Xavius at once.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 141303, 141305, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8026 } }, ["questType"] = "raid" },
[44449] = { ["id"] = 44449, ["name"] = "Advanced Quenching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 38499, 38500, 38501, 38502, 38505, 38506, 38507, 38513, 38514, 38515, 38518, 38519, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38531, 38532, 38533, 38534, 38536, 38537, 38538, 38539, 38540, 38541, 38542, 38559, 38563, 38564, 38833, 39680, 39681, 39699, 39702, 39726, 39729, 44449 }, ["series"] = { 38518, 38522, 38523, 38524, 38525, 38526, 38527, 38528, 38530, 38564, 39680, 39726, 39729 }, ["description"] = "Now that we have a frost mage at our disposal, testing this method out should be a cinch. Here are the plans for what I'd like you to make. Get to work and give me the armguards when you're finished.", ["objectivesText"] = "Craft a pair of Hard Leystone Armguards for Alard. Progress: How's that technique coming along?", ["rewardXP"] = 1415, ["rewardItems"] = { 123918, 123919, 123920, 123928, 123929, 123934, 123935, 123957, 124103, 124393, 124394, 124395, 124396, 124397, 124436, 124462, 137680 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 94, ["name"] = "Legion Blacksmithing", ["orderIndex"] = 41, ["flags"] = 0 } } },
[44490] = { ["id"] = 44490, ["name"] = "Grimwing the Devourer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 12 }, ["requiredRaces"] = { 4, 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40297, 40307, 40328, 40412, 40898, 40901, 40929, 41097, 41098, 44489, 44490 }, ["description"] = "You have my thanks for rescuing me from captivity, <name>. However, Azoran is no mere demon. He is a powerful eredar who commands great rank within the Burning Legion. Before we can get to him, there is another that must be destroyed. Grimwing the Devourer is the strongest of the felbats. Place the basilisk flesh upon the altar to the north and slay Grimwing when she appears. Then, return to me with her head. My thirst for vengeance must be quenched.", ["objectivesText"] = "Slay Grimwing the Devourer. Progress: What news do you bring of Grimwing the Devourer?", ["rewardGold"] = 127600, ["rewardXP"] = 7675, ["rewardItems"] = { 133756, 134065, 140239, 141936, 141938, 141939, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 99514, ["x"] = 0.308, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 99890, ["x"] = 0.3, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 340, ["name"] = "Breaking the Lightbreaker", ["orderIndex"] = 4, ["flags"] = 0 } } },
[44741] = { ["id"] = 44741, ["name"] = "Return to Karazhan: The Big Bag Theory", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8443, ["mapID"] = 680, ["storyline"] = { 44741 }, ["description"] = "I'm sure you've heard, <name>, that a bigger bag is always better. I disagree. I believe it's the quality of the bag that makes all the difference. Just look at those tattered things around your person. They make you look... well, quite plain. I'll prove it to you. Allegedly there are some bags in Karazhan that hold an almost infinite amount of items, but the materials required to make such bags are... well, you'll see.", ["objectivesText"] = "Recover a Bag of a Thousand Pockets and a Fel Sinew Bag from Karazhan. Progress: After this lesson, I trust I won't have to prove anything further to you.", ["rewardItems"] = { 114821, 137557, 142122, 143548 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 93969, ["x"] = 0.404, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 8443 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 276, ["name"] = "Legion Tailoring", ["orderIndex"] = 0, ["flags"] = 0 } } },
[44748] = { ["id"] = 44748, ["name"] = "Winged Terrors", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44748 }, ["objectivesText"] = "Felwing Devourers slain", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Felwing Devourers slain", ["amount"] = 10, ["type"] = 0, ["objectID"] = 115056, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[44754] = { ["id"] = 44754, ["name"] = "Waxing Crescent", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44742, 44752, 44753, 44754, 44756, 45262 }, ["description"] = "His captor is familiar to me. He is one of Aluriel's lieutenants and a skilled spell-fencer at that. You will need Silgryn's help to retrieve the key to Vanthir 's prison. Our friend's life hangs in the balance. Even if we manage to wrestle him from the executioner's grasp, he may well Wither before we can act. I need you to take an Arcan'dor fruit to him. They are precious, and few, but for Vanthir this is the only chance he has. Go quickly, and good luck.", ["objectivesText"] = "Rescue Vanthir and give him an Arcan'dor fruit. Progress: < Vanthir shudders violently and stares blankly ahead. He does not seem to be aware of your presence.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142261, 142281, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115557, ["x"] = 0.522, ["y"] = 0.79 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115604, ["x"] = 0.488, ["y"] = 0.67 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.79 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 287, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 287, ["name"] = "Waxing Crescent", ["orderIndex"] = 4, ["flags"] = 0 } } },
