[44830] = { ["id"] = 44830, ["name"] = "Learning From the Dead", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 44743, 44790, 44827, 44829, 44830, 44858, 44859, 44860, 44861, 44862, 44870, 44873, 44874, 44875, 44876, 44928, 45265 }, ["series"] = { 44790 }, ["description"] = "I heard you were traveling to Black Rook Hold. It was once home to the legendary Lord Ravencrest, a brilliant tactician. His knowledge may be exactly what we need to give us an edge against the Duskwatch. While you are at the Rook, keep your eyes peeled for any books that might have survived the ages that outline the Ravencrest's strategems.", ["objectivesText"] = "Recover 5 Books of Tactics from Black Rook Hold in Val'sharah. Progress: How goes the search?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140192, 141605, 142258, 143488, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115499, ["x"] = 0.398, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115499, ["x"] = 0.398, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 283, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 283, ["name"] = "Crafting War", ["orderIndex"] = 10, ["flags"] = 0 } } },
[44834] = { ["id"] = 44834, ["name"] = "Nullified", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 40391, 40632, 41607, 41916, 43810, 43812, 44831, 44834, 44842, 44843, 44844, 44845, 45263, 45316 }, ["series"] = { 44842 }, ["description"] = "The magus in charge of the defenses here is powerful. Perhaps too strong, even for the both of us. Fortunately, the sin'dorei know a thing or two about magic. The mage's barrier is strong, but we are clever. He has somehow channeled enough energy into his staff to power another set of defense portals, but he has left it out of his sight. Bring me the staff and an energy source from one of those constructs. I should be able to create just the thing we need to take that shield out.", ["objectivesText"] = "Obtain the Charged Arcshaper Staff and a Volatile Construct Core for Sendath. Progress: It is really child's play when you consider the magical weaves. I can see the flaws with just a few minutes of study.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142244, 142245, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 115517, ["x"] = 0.464, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 289, ["title"] = "Insurrection", ["questLineID"] = 282, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 282, ["name"] = "An Elven Problem", ["orderIndex"] = 11, ["flags"] = 0 } } },
[44930] = { ["id"] = 44930, ["name"] = "Deadmines: Sea'in Red", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 4 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1581, ["storyline"] = { 44930 }, ["description"] = "Arr, finally! I been stuck up here f'years with naught company but me own thoughts. Tis good to clap me eyes on another swashbuckling soul. Are ye up for a plot of revenge and skullduggery? These meddlin' Defias thugs murdered me and me crew years ago before they took over this cave. I propose a series of counter-murders to bring about balance! Bring me proof ye've dealt with enough of the thieves to clog a bilge pump!", ["objectivesText"] = "Collect 100 Bloodied Defias Bandanas for Captain Bramblebeard . Progress: Revenge is worth waitin' for. Not that I have much in the way of choice.", ["rewardItems"] = { 8492, 10399, 10400, 10401, 10402, 10403, 142273, 142349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1581 } }, ["questType"] = "standard" },
[44959] = { ["id"] = 44959, ["name"] = "Snowfeather Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 44959 }, ["description"] = "<Your snowfeather hatchling keeps getting into your pack and making a mess. It squawks loudly whenever you remove it, and rams you with its head. Maybe you can distract it with a tiny pack of its own?>", ["objectivesText"] = "Buy a Tiny Pack from Susana Averoy in Dalaran for your Snowfeather Hatchling . Progress: <Your snowfeather hatchling looks at you inquisitively.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 137578, 142497, 142501 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[44982] = { ["id"] = 44982, ["name"] = "Direbeak Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 44982 }, ["description"] = "<Your direbeak hatchling puffs up its feathers and growls at you in a display of dominance. It seems unhappy with the results, as you are not cowering in fear. It might like to dress up like a grown-up falcosaur and try again.>", ["objectivesText"] = "Buy a pair of Fake Teeth from Clockwork Assistant in Dalaran for your Direbeak Hatchling . Progress: <Your direbeak hatchling looks at you inquisitively.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142495, 142499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45007] = { ["id"] = 45007, ["name"] = "Sharptalon Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 45007 }, ["description"] = "<Your sharptalon hatchling will instinctively run into the kitchen of any inn you enter and make a mess of the pots and pans. It has a tendency to get into any dishes that are laying about, especially the dirty ones. You may be able to curb this behavior by finding it some silverware of its very own.>", ["objectivesText"] = "Buy a Dirty Spoon from Mel Lynchen in Dalaran for your Sharptalon Hatchling . Progress: <Your sharptalon hatchling looks at you inquisitively.>", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 137580, 142496, 142500 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45008] = { ["id"] = 45008, ["name"] = "Bloodgazer Bonding", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 45008 }, ["description"] = "<Your bloodgazer hatchling seems to love rolling around in flowers. You surmise that an affinity to flowering plants has probably helped the flock locate fruits to consume in the past. It would probably be quite excited to have a special flower of its own!>", ["objectivesText"] = "Buy a Purple Blossom from Aerith Primrose in Dalaran for your Bloodgazer Hatchling . Progress: <Your bloodgazer hatchling looks at you inquisitively.>", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142494, 142498 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45025] = { ["id"] = 45025, ["name"] = "Stealing the Source of Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["description"] = "My prisoner is a chatty one, <name>. He tells me that the Cult of the Green Flame is harnessing fel energy to fuel their efforts of bringing Kanrethad back from banishment. Within their compound they are powering fel crystals that can hold a great amount of fel magic. Without the proper power to perform their ritual, the occultists will have a tough time succeeding in their task. Steal their fel crystals , but don't destroy them. We can always find a use for something so powerful.", ["objectivesText"] = "Collect 5 Fel Crystals . Progress: Have you obtained the fel crystals ?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 142393, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45026] = { ["id"] = 45026, ["name"] = "Expending Fel Energy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 630, ["storyline"] = { 45021, 45024, 45025, 45026, 45027, 45028, 45794, 46020, 46047, 46316 }, ["series"] = { 45027, 45794 }, ["description"] = "Soon Kanrethad's banishment will fade, and he will return to our world. We must keep him, and his power, out of the Legion's hands at any cost. If my old friend is still in there somewhere, perhaps we can bring him back. The crystals you recovered feed on fel energy. We can use the ravenous crystals to siphon away the magic that consumes Kanrethad. But first, their power must be depleted. To do so, you will need to harness the power of the crystals and use their energy to kill demons.", ["objectivesText"] = "Harness the power of the Fel Crystals and expend their energy by killing demons within Faronaar. Progress: Have the crystals been depleted?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 144255, 144256, 237812 }, ["starts"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["ends"] = { { ["mapID"] = 630, ["npcID"] = 115863, ["x"] = 0.304667, ["y"] = 0.445333 } }, ["coords"] = { ["mapID"] = 630, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.445333 }, ["mapCandidates"] = { ["npc"] = { 630 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 5876, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 630, ["questLines"] = { { ["id"] = 5876, ["name"] = "Rebuilding the Council IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45045] = { ["id"] = 45045, ["name"] = "The Vial of Ancient Mana", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 45045 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45043, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "<Upon closer inspection, this vial appears to be filled with moonwell water, well-known for its potent arcane properties.> <Interestingly, it does not seem to have been tainted by its previous owner. Though that should be comforting, it only broods suspicion as to its origin.> <Someone among the Kirin Tor in Dalaran would definitely be interested in this.>", ["objectivesText"] = "Find someone interested in the Vial of Ancient Mana. You suspect that the Kirin Tor in Dalaran are a good place to start.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142378 } },
[45112] = { ["id"] = 45112, ["name"] = "Signs of Madness", ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 71, ["storyline"] = { 45112 }, ["description"] = "<Whoever this buyer is, they seem to have left in a hurry. Acrid fumes sit heavy in the air around you, and a campfire in the center of the area smolders.> <Perhaps something here can point you in the right direction?>", ["objectivesText"] = "Search the Deserted Workshop for information that might lead you to the buyer.", ["rewardItems"] = { 142527 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["questLines"] = { { ["id"] = 291, ["name"] = "Suspicious Munitions", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45145] = { ["id"] = 45145, ["name"] = "Moonfang Family Relics", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 45143, 45145, 45146, 45148, 45149, 46045 }, ["series"] = { 45890, 46259 }, ["description"] = "As promised, here is the crescent key that will open my family's lockboxes, though nothing of value remains. I trust whatever you find you'll deliver to Delas? Our ancestor's things, whatever their worth, should remain in our family.", ["objectivesText"] = "Recover Moonfang family relics from within Shadowfen.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143330, 143331, 143332, 237812 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 119209, ["x"] = 0.668, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 5828, ["questLineOrder"] = 4 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 5828, ["name"] = "Path of the Light IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45185] = { ["id"] = 45185, ["name"] = "Message from the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "I know my brother has been misguided in the past, but I fear that he may have fallen in with an unthinkable evil. He recently began meeting in secret with a dark cult, hidden amongst the people of Dalaran. I travelled here to try to convince him of the error in his ways, but he would not be shaken from his course. Now, he has disappeared. When I last saw him, Raest was staying in a room upstairs. I was unable to find any clues there, but you might fare better.", ["objectivesText"] = "Search the upper room in the Legerdemain Lounge for a clue to Raest Magespear's location. Progress: Have you found something?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 143494, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45187] = { ["id"] = 45187, ["name"] = "Secrets in the Underbelly", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 646, ["storyline"] = { 45182, 45185, 45187, 45188, 45190, 45192, 45193, 45866, 47037, 47039, 47041, 47042 }, ["description"] = "So my brother has gone off to perform some ritual with these cultists? That explains why he left, but still not to where... Wait! This letter mentions some of these \"Nethersworn\" cultists seeking reagents in the Underbelly. Perhaps we still may be able to find them if we hurry!", ["objectivesText"] = "Question the Underbelly Lowlifes in the Underbelly to find more information about Raest Magespear's location. Progress: Any leads, <name>?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 143496, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 116175, ["x"] = 0.575333, ["y"] = 0.272667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.272667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 628, ["questLines"] = { { ["id"] = 312, ["name"] = "Twins Challenge", ["orderIndex"] = 6, ["flags"] = 0 } } },
[45292] = { ["id"] = 45292, ["name"] = "Return to Karazhan: Rebooting the Cleaner", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 45292 }, ["series"] = { 45291, 45293, 45294, 45295 }, ["description"] = "The Guardian Medivh created the Curator to watch over Karazhan, but I fear the unit is behaving erratically. Prolonged periods of operation may have caused a malfunction. Please go up to the Menagerie and disable the Curator . Also, search the area for a box of spare motivator crystals and return to me. Even with my basic knowledge I should be able to replace its motivator, and we can enlist the Curator 's help in cleaning up the tower.", ["objectivesText"] = "Disable the Curator and find the Box of Spare Motivator Crystals. Progress: Did you find the box of spares?", ["rewardGold"] = 1239200, ["rewardXP"] = 12280, ["rewardItems"] = { 142460, 142461, 143549, 143551, 143552, 143555, 143556, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Day of the Dead" },
[45293] = { ["id"] = 45293, ["name"] = "Return to Karazhan: New Shoes", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 45293 }, ["series"] = { 45291, 45292, 45294, 45295 }, ["description"] = "Thus far my Karazhan cleanup project hasn't exactly been a rousing success. Time to try something new. New, as in new shoes... horseshoes , that is! A box of horseshoes was left outside the tower. It's a problem finding a delivery person willing to set foot inside... mortality rates being what they are. If you would, grab the crate and take it to Koren in the stables. Just be careful passing Attumen. The huntsman doesn't take kindly to outsiders.", ["objectivesText"] = "Deliver the Box of 'New' Horseshoes to Koren the Blacksmith in Karazhan. Progress: How did it go?", ["rewardGold"] = 1239200, ["rewardXP"] = 12280, ["rewardItems"] = { 143550, 143551, 143552, 143555, 143556, 237812 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 18255, ["x"] = 0.471, ["y"] = 0.753 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.471, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "dungeon", ["db2QuestSortName"] = "Day of the Dead" },
[45344] = { ["id"] = 45344, ["name"] = "Sampling the Source", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["series"] = { 45343 }, ["description"] = "My companion has fallen terribly ill, as you can see. He must have caught whatever these taurens had. Their entire camp has been wiped out! It appears to be fel in origin, and impervious to all known treatments. I've been working tirelessly to find a cure, but I don't think Roland here has much time left. I could use an extra hand. Some samples from the source should speed things up. Just be sure to avoid direct contact with the contagion. Levitate should be helpful.", ["objectivesText"] = "Collect Contaminated Specimens from pools of Gaseous Fel around the western coast of Highmountain. Progress: Do you have the samples I've requested?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143654, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45345] = { ["id"] = 45345, ["name"] = "Mischievous Sprites", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "It's a little-known secret that the dust sprites use for their various tricks has restorative properties. Some within the alchemy community balk at this claim, but they only refute it because they've never been able to get their hands on the rare ingredient. Sprites often shroud themselves in illusions to avoid detection. The nearby goats have a curious shimmer about them that suggests they may be sprites in disguise. Dispel whatever magic surrounds them to reveal their true form.", ["objectivesText"] = "Use Dispel Magic on Soothoof Hillstriders to reveal Mischievous Sprites and collect their Shimmering Dust . Progress: Have you acquired the Shimmering Dust I so desperately need?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143678, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 739, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45348] = { ["id"] = 45348, ["name"] = "Safekeeping", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 5 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 45342, 45343, 45344, 45345, 45346, 45347, 45348, 45349, 45350, 46034, 46145 }, ["description"] = "It would seem that a delicate balance of holy and shadow magic is the key to curing this contagion. Obviously the remedy will need a bit of work to reduce undesired side effects, like dying. In the meantime, take the counteragent back to Netherlight Temple and keep it safe. I will work diligently on discovering the source of this contagion.", ["objectivesText"] = "Take the Contagion Counteragent to Alonsus Faol in Netherlight Temple. Progress: What do we have here?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 87370, 87371, 87372, 87373, 87374, 87375, 87376, 87377, 87378, 143736, 211279, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 118528, ["x"] = 0.336, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 295, ["title"] = "Priest Order Hall", ["questLineID"] = 5861, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1512, ["db2PoiUiMapID"] = 702, ["questLines"] = { { ["id"] = 5861, ["name"] = "Fulfilling the Prophecy IV", ["orderIndex"] = 5, ["flags"] = 0 } } },
[45381] = { ["id"] = 45381, ["name"] = "The Nighthold: Talisman of the Shal'dorei", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8025, ["storyline"] = { 45381 }, ["description"] = "When the Nighthold was built, my people forged a talisman that allowed access to these halls. With the talisman's power, one could traverse the palace unhindered, taking the fight directly to the magistrix. Using fragments of the Nightwell's power, we could locate the talisman and end this foolish war...", ["objectivesText"] = "Collect 4 Echoes of Time from Elisande in The Nighthold on Normal Difficulty. Progress: Without the talisman we must fight through the city proper.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 141324, 141325, 141326, 143656, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8025 } }, ["questType"] = "raid" },
