[45398] = { ["id"] = 45398, ["name"] = "Harnessing Power", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8529, ["mapID"] = 823, ["storyline"] = { 44775, 44783, 44787, 45103, 45240, 45243, 45331, 45398, 45399, 46050, 46305 }, ["description"] = "These fools are using the power of Rimefang's harness to subjugate the frost wyrms. Their leader, Andjor, sits inside on the back of the broodmother and mocks us. He should breathe no longer.", ["objectivesText"] = "Kill Andjor Dragontamer and retrieve Rimefang's Harness . Progress: This harness will bring us great power!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 143676, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8529 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 302, ["title"] = "Death Knight Order Hall", ["questLineID"] = 5896, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1692, ["db2PoiUiMapID"] = 823, ["questLines"] = { { ["id"] = 5896, ["name"] = "The Four Horsemen IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
