[45552] = { ["id"] = 45552, ["name"] = "Soothing Wounds", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "< D'Bynn 's injuries prevent him from moving.> Perhaps you can forage something nearby that will soothe the manasaber's wounds?", ["objectivesText"] = "Use Manaroot that is foraged from leylines within the Crimson Thicket to soothe D'Bynn 's wounds.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143788, 237812 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 117308, ["x"] = 0.551333, ["y"] = 0.452667 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.551333, ["y"] = 0.452667 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 1, ["flags"] = 0 } } },
[45554] = { ["id"] = 45554, ["name"] = "Taking Control", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 646, ["storyline"] = { 45551, 45552, 45553, 45554, 45555, 45556, 45557, 46048, 46060, 46235 }, ["description"] = "I've been withering away in this cage, prisoner to a wretch called Reyln. He leads a group of nightborne that are using fel magic to corrupt and control the native wildlife. The Burning Legion's reach has already spread too far for my liking. Kill him and recover his control orb, so I can be released from this arcane prison!", ["objectivesText"] = "Kill Torturer Relyn and use his Control Orb to free Nighthuntress Syrene. Progress: Relyn's control orb is the only thing that can break this magical barrier.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 143830, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117246, ["x"] = 0.446, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 293, ["title"] = "Hunter Order Hall", ["questLineID"] = 5851, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 5851, ["name"] = "Watchers in the Wild IV", ["orderIndex"] = 3, ["flags"] = 0 } } },
[45631] = { ["id"] = 45631, ["name"] = "Avocation of Antonidas", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4395, ["storyline"] = { 45631 }, ["description"] = "Archmage, I've found something you may be interested in. An old journal of the late Archmage, Antonidas. In it, he speaks of a project he was working on that I think we may be able to finish. It was a sort of flying disc that could attune itself to the rider's magical attunement. But I need your help tracking down the pieces. From what I could gather, he gave them to trusted friends and allies through the years. Perhaps you could persuade them to give us the pieces.", ["objectivesText"] = "Recover the three discs of Antonidas' unfinished project and return them to Kalec in your order hall. Speak to Archmage John Nicholas in Northrend, at the Purple Parlor about the Tri-Disc of the Arcane . Speak with Khadgar about the Tri-Disc of Fire . And speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost .", ["rewardGold"] = 7150, ["rewardXP"] = 6140, ["rewardItems"] = { 143836, 143837, 143838, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 4395 } }, ["questType"] = "standard" },
