[45724] = { ["id"] = 45724, ["name"] = "Snakes and Stones", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 400, ["mapID"] = 64, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 44800, 45652, 45706 }, ["description"] = "When the demons attacked, they captured two very powerful possessions of mine: my companion Arikara and the Doomstone . While death matters not to Arikara, the Legion surely has ulterior plans for him. And the Doomstone ... such an artifact of power belongs in my hands, not theirs. We must split up to find them. For the world's sake, do be careful. I don't need you clumsily destroying everything.", ["objectivesText"] = "Find either the Doomstone or Arikara on Darkcloud Pinnacle. Progress: Greetings, Farseer. What have you found?", ["rewardGold"] = 208560, ["rewardXP"] = 6140, ["rewardItems"] = { 143860, 237812 }, ["starts"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["ends"] = { { ["mapID"] = 64, ["npcID"] = 120244, ["x"] = 0.397, ["y"] = 0.387 } }, ["coords"] = { ["mapID"] = 64, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.387 }, ["mapCandidates"] = { ["npc"] = { 64 }, ["zone"] = { 400 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 64, ["db2QuestSortName"] = "Proving Grounds", ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45767] = { ["id"] = 45767, ["name"] = "Elemental Cores", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 7 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44800, 45652, 45706, 45723, 45724, 45725, 45763, 45765, 45767, 45769, 45883, 45971, 46057, 46258 }, ["series"] = { 45763, 45971 }, ["description"] = "The eredar here are abusing the power of all of Azeroth's elements, forcing them to their command using their fel magics. They succeed to do this through curiosities the Legion has developed, cores of power that correspond to each element. Do not allow the Legion to continue abusing our world. Kill them and take the sources of their power.", ["objectivesText"] = "Collect 3 Fire Power Cores , 3 Water Power Cores , 3 Earth Power Cores , and 3 Air Power Cores . Progress: Nobody should force the elements to bend to their will. Show the Legion that their understanding is flawed.", ["rewardGold"] = 286500, ["rewardXP"] = 6140, ["rewardItems"] = { 146888, 146889, 146890, 146891, 163476, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117715, ["x"] = 0.605, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 296, ["title"] = "Shaman Order Hall", ["questLineID"] = 5866, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5866, ["name"] = "The Elemental Lords IV", ["orderIndex"] = 8, ["flags"] = 0 } } },
