[45846] = { ["id"] = 45846, ["name"] = "Chilled to the Core", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 267, ["mapID"] = 735, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "The next piece Antonidas made was imbued with frost magic. He wrote about a ritual to channel frost energy into the disc with his fellow Archmage, Cedric, but their combined strengths forced too much energy into the disc. If I recall, Cedric is helping oversee the reconstruction of Dalaran near the crater where Dalaran once resided. Hopefully he knows where to find the disc.", ["objectivesText"] = "Speak with Archmage Cedric near the Dalaran Crater about the Tri-Disc of Frost . Progress: After the devastation that befell Dalaran's original home, who knows where that disc may be.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 142223, 143837, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 267 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 2, ["flags"] = 0 } } },
[45847] = { ["id"] = 45847, ["name"] = "Close to Home", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 8 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7879, ["mapID"] = 735, ["storyline"] = { 45354, 45844, 45845, 45846, 45847 }, ["description"] = "The third piece of the disc was infused with Antonidas' own arcane magic. He did this at the height of his power, but like the other two discs, was unable to finish his work on it. He wrote that he gave the piece to Archmage Celindra ... Isn't she the portal trainer here in Dalaran? She must know where the piece is! Quickly, go speak with her.", ["objectivesText"] = "Speak to Archmage Celindra about the Tri-Disc of the Arcane here in Dalaran. Progress: Did she have it?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 142223, 143838, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7879 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 297, ["title"] = "Mage Order Hall", ["questLineID"] = 297, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1513, ["db2PoiUiMapID"] = 735, ["questLines"] = { { ["id"] = 297, ["name"] = "Class Mount: Mage", ["orderIndex"] = 3, ["flags"] = 0 } } },
