[46074] = { ["id"] = 46074, ["name"] = "Leather to Legendary", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 24, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46081, 46083, 91618, 94847 }, ["description"] = "Let's begin, shall we? I mean, I'll be doing all the work, but you get to watch! <Alard grins a wide smile at you and begins working.>", ["objectivesText"] = "Have Alard upgrade the barding and return with it to Lord Grayson Shadowbreaker at your order hall. Progress: How'd it go? Was Alard able to upgrade the barding?", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 131746, 143503, 143504, 143505, 144294, 147768, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiUiMapID"] = 24, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46081] = { ["id"] = 46081, ["name"] = "Leather to Legendary", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 139, ["storyline"] = { 46081 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["description"] = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this. There is felslate, but that's a probably too tainted for what you're looking to do with this barding. You know, I also like to adorn my pieces with something sparkly, like a jewel. I hear saber's eyes are especially sparkly. Why don't you grab one of those for this as well.", ["objectivesText"] = "Obtain 50 Leystone Ore and 1 Saber's Eye .", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 130245, 144294, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 139 } }, ["questType"] = "standard" },
[46083] = { ["id"] = 46083, ["name"] = "A Few Things First", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 2 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7502, ["mapID"] = 627, ["storyline"] = { 45770, 46069, 46070, 46071, 46074, 46083, 91618, 94847 }, ["series"] = { 45770, 46069, 46070, 46071, 46074, 46081, 91618, 94847 }, ["description"] = "Lately I've been working with the ore of this land, leystone it's called. I've found its qualities to hold remarkable strength and durability. We'll need a lot of it for this. There is felslate, but that's a probably too tainted for what you're looking to do with this barding. You know, I also like to adorn my pieces with something sparkly, like a jewel. I've heard that the elves of Suramar have particularly beautiful ones. Perhaps you could acquire one for this project.", ["objectivesText"] = "Obtain 25 Leystone Ore and a Suramarian Sapphire . Progress: I doubt you'll have a problem getting the leystone, but the sapphire might be a bit harder to acquire.", ["rewardGold"] = 20220, ["rewardXP"] = 770, ["rewardItems"] = { 123918, 124113, 129979, 131746, 136269, 136600, 136970, 140325, 140326, 142436, 143503, 143504, 143505, 144294, 147768, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 292, ["title"] = "Paladin Order Hall", ["questLineID"] = 302, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 302, ["name"] = "Class Mount: Paladin", ["orderIndex"] = 5, ["flags"] = 0 } } },
