[46213] = { ["id"] = 46213, ["name"] = "Crystals Not Included", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["series"] = { 47526, 47771 }, ["description"] = "Turalyon is safe, and we can start to fight back. First things first, we must secure what supplies we can from the crash. Even though we are blessed by the Light, our ships still rely on crystal technology. From powering our defenses to arming our weapons, we will need to collect as much as we can to fight back against the enemy. Venture out into the crash and retrieve what crystals you can. While you are out there, keep an eye out for Y'mera. She was separated from us, and will need help.", ["objectivesText"] = "Collect 10 Argunite Crystals . Progress: I hope you brought backup with you.", ["rewardGold"] = 232300, ["rewardXP"] = 6140, ["rewardItems"] = { 150942, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121519, ["x"] = 0.405, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121578, ["x"] = 0.318, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 3, ["flags"] = 0 } } },
