[46239] = { ["id"] = 46239, ["name"] = "Fel to the Core", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7875, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "While it has become relatively easy for a warlock to open a brief window into the realms of the Legion, a sustained portal requires significantly more power. For this, we will need a power source brimming with fel energy. I know that the commanders of the Legion use powerful fel cores to control their warships. If you can defeat the commander of one of these ships, you should be able to take their core.", ["objectivesText"] = "Collect an Overcharged Fel Core from the commander of a Legion Assault on the Broken Isles. Progress: Do you have the core?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 144443, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7875 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46240] = { ["id"] = 46240, ["name"] = "Give Me Fuel, Give Me Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 9 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["description"] = "A powerful core will not alone be able to power the portal. Like any powerful engine, it will require fuel - though an engine of fel energy must burn life force to thrive. We will need blood potent in magical energy to keep our fel core running and sustain our connection to Xoroth. Fortunately, I have experience in these matters, and I know just the place where we can get some. You'll need a jar or something.", ["objectivesText"] = "Collect 50 Owlbeast Blood from Owlbeasts within Lostlight Grotto in Val'sharah. Progress: Have you bled the owlkin dry?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 144444, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7558 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 4, ["flags"] = 0 } } },
[46242] = { ["id"] = 46242, ["name"] = "The Dreadlord's Calling", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 717, ["storyline"] = { 46237, 46238, 46239, 46240, 46241, 46242, 46243, 94850 }, ["series"] = { 46241 }, ["description"] = "According to the cultist, the leader you seek should be in her tower overseeing the operations in the Dark Stockades.", ["objectivesText"] = "Collect a Xorothian Calling Stone from Zuriwa the Hexxer within the Dark Stockades in the Broken Shore. Progress: I trust you found the stone?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 144445, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 298, ["title"] = "Warlock Order Hall", ["questLineID"] = 315, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1107, ["db2PoiUiMapID"] = 717, ["questLines"] = { { ["id"] = 315, ["name"] = "Class Mount: Warlock", ["orderIndex"] = 6, ["flags"] = 0 } } },
[46319] = { ["id"] = 46319, ["name"] = "You Can't Take the Sky from Me", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7846, ["mapID"] = 747, ["storyline"] = { 46317, 46318, 46319 }, ["description"] = "The Shrine of Aviana has fallen to the demons, and the Idol of Aviana has been stolen. That idol acts as a link between the Druids of the Talon and the powers of flight granted to us by Aviana. The Druids of the Talon have decided to rebuild a new shrine in a more secure location: here in the Dreamgrove. Meanwhile, I'm going to get our idol back. Meet me in Azsuna, near where we've tracked Infazzar to, if you want to help.", ["objectivesText"] = "Deal with Infazzar the Shade, and retrieve the Idol of Aviana. Progress: <Place the Corrupted Idol of Aviana on the pedestal.>", ["rewardGold"] = 331700, ["rewardXP"] = 6140, ["rewardItems"] = { 140394, 142223, 142224, 142225, 142227, 142231, 142232, 143489, 143493, 143502, 143638, 146798, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7846 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 790, ["questLineOrder"] = 10 } }, ["db2LabelIDs"] = { 4785 }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 747, ["questLines"] = { { ["id"] = 790, ["name"] = "Class Mount: Druid", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46344] = { ["id"] = 46344, ["name"] = "Smelly's Luckydo", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 46341, 46342, 46343, 46344, 46346, 46347, 46348, 46349, 46350, 46353 }, ["description"] = "You! Please help! Stupid hozen stole Smelly's luckydo ! Now, Smelly always unlucky. Just turned around and look, pack is on fire. Not going to put fire out because then something ELSE unlucky happen. Maybe something worse! You beat up hozen, yes? Get back luckydo? Smelly will help you, any way he can!", ["objectivesText"] = "Collect 3 parts of Smelly's Luckydo . Progress: Find my luckydo yet? Getting kind of hot here.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147314, 147315, 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 120744, ["x"] = 0.48, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 120744, ["x"] = 0.48, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 299, ["title"] = "Monk Order Hall", ["questLineID"] = 316, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 316, ["name"] = "Class Mount: Monk", ["orderIndex"] = 4, ["flags"] = 0 } } },
[46499] = { ["id"] = 46499, ["name"] = "Spiders, Huh?", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I feel like they're still crawling all over me. I squished one egg and all of a sudden I'm covered head to toe in baby spiders. <Shivers>. That treasure is just sitting there now. The next guy better not be arachnaphlipic... arachnaphonetic? Arachniphant? Afraid of spiders!", ["objectivesText"] = "Look for the rumored treasure in the Creeping Grotto. Progress: I'm always lookin' for more treasure!", ["rewardXP"] = 6140, ["rewardItems"] = { 143559, 146653, 146671, 146955, 146956, 146957, 146958 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46501] = { ["id"] = 46501, ["name"] = "Grave Robbin'", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I am not a grave robber, but is it technically grave robbing if the treasure is sitting on a field of bones? It's not like it's buried or nothin'. I'm just gonna sit this one out, just in case.", ["objectivesText"] = "Look for the rumored treasure in the Soul Ruins. Progress: I'm always lookin' for more treasure!", ["rewardXP"] = 6140, ["rewardItems"] = { 18230, 113364, 146653, 146664, 146955, 146956, 146957, 146958 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 4, ["flags"] = 0 } } },
[46509] = { ["id"] = 46509, ["name"] = "Tomb Raidering", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I said to myself over and over, \"Don't go near the citadel. Don't go near the citadel.\" But what did I do? I went to the citadel. Almost had my hands on that sweet treasure chest before I got chased off by a bunch of crazy demons. I made it out of there with just my helmet and my life!", ["objectivesText"] = "Look for the rumored treasure outside the Tomb of Sargeras. Progress: I'm always lookin' for more treasure!", ["rewardXP"] = 6140, ["rewardItems"] = { 141605, 146653, 146662, 146955, 146956, 146957, 146958 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 3, ["flags"] = 0 } } },
[46510] = { ["id"] = 46510, ["name"] = "Ship Graveyard", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I haven't told you that I was part of the original landing party when we lost almost everything. I don't care what treasure is left there, I'll never go back to that beach. Never.", ["objectivesText"] = "Look for the rumored treasure deep in the Forlorn Depths. Progress: I'm always lookin' for more treasure!", ["rewardXP"] = 6140, ["rewardItems"] = { 141605, 146653, 146663, 146955, 146956, 146957, 146958 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 2, ["flags"] = 0 } } },
[46511] = { ["id"] = 46511, ["name"] = "We're Treasure Hunters", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46499, 46501, 46509, 46510, 46511, 46666 }, ["description"] = "I have a feeling you're just using me for tips on where all the best treasure is. From now on I'm naga tell you anything. Did I say, \"naga\" just then? I meant to say, I'm not gonna to tell you naga. I mean nada! Darn it! Okay. Seems you got me on this one. I'll tell you what, fetch me whatever is in that chest near those naga freaks and I'll make it worth your while.", ["objectivesText"] = "Look for the rumored treasure on the Felrage Strand. Progress: You fetch that treasure yet?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 146653, 146955, 146956, 146957, 146958, 147484, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 119886, ["x"] = 0.409, ["y"] = 0.667 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.667 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 319, ["name"] = "Excavations", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46675] = { ["id"] = 46675, ["name"] = "To Track a Demon", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 11 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 44869, 44877, 44888, 44921, 45425, 45426, 45498, 45528, 45532, 46044, 46674, 46675, 46676, 46677, 46924 }, ["series"] = { 45425, 46677 }, ["description"] = "I took the initiative to scout around before I grabbed that wyrmtongue. It seems like their forces are holed up in a camp in Impsorrow Approach. What I've struggled to figure out, however, is who their commander is and if he's nearby. If he's leading from elsewhere, the troops need to have some commands on them. Let's go see if we can find any... on their dead bodies!", ["objectivesText"] = "Collect 3 Impsorrow Missives from demons in Impsorrow Approach. Progress: Collecting some missives should allow me to figure out the commander's position.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 147282, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120070, ["x"] = 0.435, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 300, ["title"] = "Druid Order Hall", ["questLineID"] = 5886, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 5886, ["name"] = "The Eternal Dream IV", ["orderIndex"] = 10, ["flags"] = 0 } } },
[46678] = { ["id"] = 46678, ["name"] = "The Legend of the Threads", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46678 }, ["description"] = "Tailoring is the noblest of professions because clothing is universal. Most dress with nary a thought. If you analyze the legends, some races stand out from all others. The Nightborne are masters of style! Much of the brilliance is in their materials--in particular their thread and their looms. We will take advantage of both. Before you gather materials, I need to confirm my list. Find the fashion treatise I brought with me. Perhaps I dropped it by the flight master?", ["objectivesText"] = "Bring Eliezer his lost copy of Nights with the Nightborne Progress: I need a copy of Nights with the Nightborne so we can focus our efforts. I probably left it on my flight over.", ["rewardGold"] = 30900, ["rewardXP"] = 770, ["rewardItems"] = { 147281, 147451 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46679] = { ["id"] = 46679, ["name"] = "The Thread of Shadow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46679 }, ["series"] = { 46680, 46682, 46683 }, ["description"] = "Vandros of the Nightborne. There is an elf who knows how to dress. Ever since he was a young noble in the Court of Farondis, Vandros has been known for snappy, fashion forward outfits. I've never been able to see his garments up close but my research tells me that his tailor's technique is not so much in the fabric as it is in the thread. It appears to be spun of the very shadows themselves. You have your methods to obtain it, I'm sure. Get his robes and get the thread.", ["objectivesText"] = "Defeat Advisor Vandros in the Arcway in Mythic difficulty and extract Shadow Thread from his robes. Progress: Vandros maybe be difficult to defeat but we really need that shadow thread from his robes.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146678, 146679 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46680] = { ["id"] = 46680, ["name"] = "The Thread of Starlight", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46680 }, ["series"] = { 46679, 46682, 46683 }, ["description"] = "Melandrus of the Nightborne is First Blade of Elisande. Perhaps you've heard of him? He is a great hero to the Nightborne but, to be absolutely honest, he is a mess with regards to style. His accoutrements are somewhat better and a particular pair or bracers are rather nice. In fact, the thead that binds them will be absolutely perfect for your pending outfits. Why don't you get that for me and we will talk further.", ["objectivesText"] = "Defeat Advisor Melandrus in the Court of Stars and extract Starlight Thread from his bracers. Progress: Did you get the thread from Melandrus' Star-Touched Bracers ?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146680, 146681 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46681] = { ["id"] = 46681, ["name"] = "The Thread of Souls", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46681 }, ["description"] = "Have you ever had a chance to lay eyes on Elisande, Grand Magistrix of the Nightborne? Stunning! Fashion-forward! Nice posture! You'd do well to take a page from her book! In fact, you'd tell well to take the thread from her Suramari Soul Wraps! These hold great symbolic value to her people so it's doubtful she will give them willingly. So be it, take her out and get that thread.", ["objectivesText"] = "Defeat Grand Magistrix Elisande in the Nighthold and extract Soul Thread from her wraps. Progress: Grand Magistrix Elisande's Soul Wraps have the most beautiful thread! I don't meant to be pushy but... I'm waiting.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146682, 146683 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46682] = { ["id"] = 46682, ["name"] = "Drapings of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46682 }, ["series"] = { 46679, 46680, 46683 }, ["description"] = "<name>, we are going to need a high quality cloth to work with. Thankfully, the weaving quality of nightborne craftspeople from long ago was very good. It is a lost art to some degree but I feel like you can take their masterworks and do even more with it. Some of the hostiles in these parts still wear Ancient Imbued Silkweave Armor . Start to unstitch the silkweave cloth from any of that armor that you find on Broken Shore.", ["objectivesText"] = "Obtain 100 Ancient Imbued Silkweave from humanoids in Broken Shore. Progress: Keep your eye out for Ancient Imbued Silkweave . We need a lot of it to start making fabulous things.", ["rewardGold"] = 292100, ["rewardXP"] = 6140, ["rewardItems"] = { 146666, 146684, 146685 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46685] = { ["id"] = 46685, ["name"] = "The Wisp and the Shadow", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46685 }, ["series"] = { 46686, 46687, 46688, 46689 }, ["description"] = "<name>, have you heard of the nightmare lord, Xavius, whose shade haunts Darkheart Thicket? I have heard that this shade is sometimes seen wearing a colorless shroud. This shroud is steeped in powerful magic and the wisp will draw it out for you. If you can fight the shade, take the shroud, and use your skills to dye it, I will show you how to work wonders!", ["objectivesText"] = "Defeat the Shade of Xavius in Darkheart Thicket on Mythic Difficulty and dye his shroud. Progress: Have you obtained and dyed the shroud yet? Make your way to Darkheart Thicket and get it done.", ["rewardGold"] = 315900, ["rewardXP"] = 6140, ["rewardItems"] = { 146686, 146687 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46686] = { ["id"] = 46686, ["name"] = "The Wisp and the Sea", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46686 }, ["series"] = { 46685, 46687, 46688, 46689 }, ["description"] = "Queen Azshara and her handmaidens are the subjects of many a tragic tale. Her power and her hubris lead her badly astray but, even so, her handmaidens are loyal to her to this day. There is power in such a thing. The Wrath of Azshara is an abomination but, truthfully, it is actually one of her handmaidens who willingly gave her life to protect her queen. Few know this. The Ancient Wisp knows this truth and if you take it to battle the Wrath of Azshara, you may find the handmaiden's gloves. Restore them.", ["objectivesText"] = "Retrieve the Waterlogged Handmaiden's Gloves from the Wrath of Azshara on Mythic Difficulty, then treat them. Progress: You need to battle the Wrath of Azshara and find and restore a pair of handmaiden's gloves.", ["rewardGold"] = 63800, ["rewardXP"] = 6140, ["rewardItems"] = { 146688, 146689 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46689] = { ["id"] = 46689, ["name"] = "Wisp-Touched Elderhide", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46689 }, ["series"] = { 46685, 46686, 46687, 46688 }, ["description"] = "Dreadleather, with knowledge carefully reverse-engineered from ancient texts, can be worked into elderhide. It is partly a matter of advanced craftsmanship and partly a simple magic of the earth. With the ancient wisps you caught and the materials you've captured and the research I have done, I have put together a Legendary Tanner's Kit for you. Take it to the heirloom hides of Hrul Sharptooth in Thunder Totem. The wisp will help you use the kit there to create Elderhide.", ["objectivesText"] = "Use the Legendary Tanner's Kit in Hrul Sharptooth's dwelling in Thunder Totem. Progress: Hrul Sharptooth has hides in his dwelling in Thunder Totem. When you approach them, you will be able to use your kit. Bring it back to me for final inspection.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 146712, 146977, 147438 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46690] = { ["id"] = 46690, ["name"] = "The Legend of the Wardenscale", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46690 }, ["description"] = "One of my favorite legends is of the Father of Owls on Isle of the Watchers. It is said that his spirit comes to comfort his creatures during times of trouble. With the Legion's arrival on the Isle of Watchers, many of the owls are being slain so you can find him there. We need to \"borrow\" him for a short time as he has seen many of the battles where famous warriors and villains have worn armor made of Wardenscale. With his spirit, you can identify items we can extract it from and use it for style!", ["objectivesText"] = "Capture the Father of Owls on the Isle of the Watchers. Progress: Have you captured the Father of Owls yet?", ["rewardGold"] = 295000, ["rewardXP"] = 6140, ["rewardItems"] = { 147075, 147116 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46692] = { ["id"] = 46692, ["name"] = "The Owl and the Dreadlord", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46692 }, ["series"] = { 46691, 46693, 46694, 46695 }, ["description"] = "The demon Mephistroth is one of the most powerful of the Nathrezim--the dreadlords. I can see in your eyes that you know what I am going to ask you to do. But it is for your own good! You can't keep wandering the lands looking like you do. Most recently, Mephistroth has been dispatched by the Legion to the Cathedral of Eternal Night. No doubt, he will be wearing some legplates that I believe contain Wardenscale. Take them, shine them up, and bring them to me.", ["objectivesText"] = "Find and restore the Legplates of Mephistroth by defeating him in the Cathedral of Eternal Night in Mythic Difficulty. Progress: Have you defeated Mephistroth and added some shine to his legplates?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146696, 146697 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46693] = { ["id"] = 46693, ["name"] = "The Owl and the Observer", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46693 }, ["series"] = { 46691, 46692, 46694, 46695 }, ["description"] = "I've researched some foul creatures in my time but Viz'aduum the Watcher may top the list. I mean, he is a giant, disgusting, dangerous eyeball! Currently he haunts Karazhan--do you know the place? In Medivh's time, much of our common knowledge was stored there. Alas, the time has passed... I digress. Viz'aduum is in possession of armor from the First War--bracers to be specific--and they are incredibly valuable. It pains me but take them, repair them, and then we must use their wardenscale.", ["objectivesText"] = "Kill Viz'aduum in the Return to Karazhan dungeon on Mythic difficulty, and retrieve and repair the Bracers of the First War. Progress: Have you killed that horrible beast and brought me the Bracers of the First War?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146698, 146699 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46694] = { ["id"] = 46694, ["name"] = "Mail of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46694 }, ["series"] = { 46691, 46692, 46693, 46695 }, ["description"] = "There is some wardenscale scattered here and there in the Broken Isles. Various enemies and local monsters seeking to ape the superior races like ourselves will have picked it up and worn it. The kind we need is amongst the oldest ever made. It is ancient gravenscale . Keep all that you find and and bring it to me. We will harvest what useful bits we can from it.", ["objectivesText"] = "Obtain 100 Ancient Gravenscale from humanoids in Broken Shore. Progress: Do you have the Ancient Gravenscale that we need?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146700, 146701 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46695] = { ["id"] = 46695, ["name"] = "Prime Wardenscale", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46695 }, ["series"] = { 46691, 46692, 46693, 46694 }, ["description"] = "I feel like it is finally time for use to create something truly remarkable. To create the armor that will set you apart from the rest, we need to make the best wardenscale. Find the nightelf, Celea, in Azsuna. She has attuned and sanctified the ground where she waits to focus the magic of our world and only there can you make what we need. Go with speed, <name>.", ["objectivesText"] = "Find Celea in Azsuna and create the Wardenscale where the magic aligns. Progress: Have you found Celea in Azsuna and prepared the Wardenscale beside her? It will only work at that spot. Bring it back to me when you have finished.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 146713, 147209, 147439 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46696] = { ["id"] = 46696, ["name"] = "The Legend of the Four Hammers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46696 }, ["description"] = "<name>, we should be honest with each other before we begin. You are a blacksmith by trade and this a noble profession. Yet I value style and fashion. Heavy armor and weapons create a certain bulkiness in a hero's profile that I think does no service whatsoever to the cut of one's clothes. Fret not--I can at least teach you something about taste in finer materials. Go to Dalaran and find a book translated by my brother about 3 forgotten heroes. We will find the finest metals ever forged!", ["objectivesText"] = "Go to Dalaran and find the Legend of the Four Hammers. Progress: Did you find that dusty old tome of Fafnir's? I have to admit that he may have found something interesting in it.", ["rewardGold"] = 120510, ["rewardXP"] = 3070, ["rewardItems"] = { 147197 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46697] = { ["id"] = 46697, ["name"] = "The Godfighter", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46697 }, ["series"] = { 46698, 46699, 46700, 46701 }, ["description"] = "The Godfighter championed the mortals against what he saw as oppression and abuse by immortal beings. The legends say the gods feared him but he did fall in time. My research shows that the gods he fought were the gods of Stormheim. Odyn, in particular. The Godfighter's shield took so much damage from lightning bolts that it became lightningsteel. After the Godfighter died, Odyn took the shield and melted it down as a trophy. Get that lightningsteel from him and forge a hammer from it.", ["objectivesText"] = "Take White Lightningsteel from Odyn in the Halls of Valor in Mythic difficulty and forge it into a hammer. Progress: Have you taken the white lightningsteel from Odyn and forged it into a hammer?", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 87216, 146667, 146702, 146703 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46700] = { ["id"] = 46700, ["name"] = "Armor of the Ancients", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["requiredClasses"] = { 1, 2, 6 }, ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46700 }, ["series"] = { 46697, 46698, 46699, 46701 }, ["description"] = "It is not just the hammers and my careful research that we need, <name>. We also need a lot of the very highest quality of ancient metal to make the final hammer. Enemies across Broken Shore that are able to wear armor often collect bits of Ancient Demonsteel here and there. Collect enough of it in your battles for our purposes.", ["objectivesText"] = "Obtain 100 Ancient Demonsteel from humanoids in Broken Shore. Progress: Do you have the Ancient Demonsteel that we need?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 146708, 146709 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 120221, ["x"] = 0.412, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard" },
[46727] = { ["id"] = 46727, ["name"] = "Battle for Azeroth: Tides of War", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 46728, 46729, 47098, 47099, 51341, 57766, 58983, 59641, 60362 }, ["description"] = "Champion! An urgent War Council is underway. Your presence is requested in Stormwind Keep.", ["objectivesText"] = "Attend the War Council in Stormwind Keep. Progress: Thank you for coming.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 160326, 178941, 178942 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 49748, ["x"] = 0.62575, ["y"] = 0.5635 }, { ["mapID"] = 84, ["npcID"] = 142930, ["x"] = 0.275, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 120756, ["x"] = 0.835333, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.62575, ["y"] = 0.5635 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 6, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 0, ["flags"] = 0 } } },
[46728] = { ["id"] = 46728, ["name"] = "The Nation of Kul Tiras", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 46727, 46729, 47098, 47099, 51341, 57766, 58983, 59641, 60362 }, ["description"] = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore. Many have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father. Perhaps she feels the time has come to atone for this. Loath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance. Good luck.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 158075, 160326 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 120756, ["x"] = 0.835333, ["y"] = 0.328 }, { ["mapID"] = 84, ["npcID"] = 165395, ["x"] = 0.856, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 120922, ["x"] = 0.655, ["y"] = 0.507 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.835333, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 1, ["flags"] = 0 } } },
[46729] = { ["id"] = 46729, ["name"] = "The Old Knight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 46727, 46728, 47098, 47099, 51341, 57766, 58983, 59641, 60362 }, ["description"] = "These days Cyrus is the Harbormaster, but he used to be one of Daelin Proudmoore's most trusted knights! I lost my mother when the Scourge hit Lordaeron. My father sent me here to be raised away from the war. I don't know much about him... just that he was a Stormwind knight who gave his life fighting the Lich King. Daelin hand-picked Cyrus to raise me and forced him to take a desk job. It's the only reason he wasn't at Theramore. He's probably checking in that other Alliance ship. Let's go!", ["objectivesText"] = "Meet with Cyrus Crestfall . Progress: Sorry, I should have mentioned he can be a bit... long-winded at times.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 158075, 160326 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.731333, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 5, ["flags"] = 0 } } },
[46834] = { ["id"] = 46834, ["name"] = "Khazaduum, First of His Name", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "The Argunite Matrix that powered this part of Eredath was shattered by a hulking beast. We had never seen another like him. He was called Khazaduum and he was a most faithful servant of the Legion. He volunteered to undergo an experimental transformation to become the first of his kind. His arrival was the end of this battle. As a prize he took the Argunite Keystone from the shattered matrix. Take it back and we can finally end this bloodshed.", ["objectivesText"] = "Retrieve the Argunite Keystone from the Echo of Khazaduum. Progress: Please, they should not be made to suffer any longer.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152407, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47098] = { ["id"] = 47098, ["name"] = "Out Like Flynn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8978, ["mapID"] = 895, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 46727, 46728, 46729, 47099, 51341, 57766, 58983, 59641, 60362 }, ["description"] = "I'm relieved you woke up! Having to carry you would have made this job far less appealing. The name's Flynn, and my client in Boralus is paying me a king's bounty to break you out of here. You, my friend, are incarcerated in Tol Dagor. Used to be a legit prison... 'til the Ashvane Trading Company bought it. Now it's Priscilla's own personal fortress, riddled with scum on both sides of the bars. Wasn't hard to bribe my way into this cell. Now we just have to get out. Not to worry. I have a plan!", ["objectivesText"] = "Escape Tol Dagor with Flynn. Progress: Is that the new powder Flynn was talking about? I'll take it for safekeeping.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 52019, 158075, 160326 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.6892, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8978 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47099] = { ["id"] = 47099, ["name"] = "Get Your Bearings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 46727, 46728, 46729, 47098, 51341, 57766, 58983, 59641, 60362 }, ["description"] = "I think a proper introduction is in order! My name is Taelia , member of the Proudmoore Guard and squire of Sir Cyrus Crestfall. < Taelia salutes firmly.> Cyrus asked me and Flynn to break you out of that Ashvane prison and get you settled in here at the market, but he neglected to mention that you're with the Alliance. I must say, it's an honor. Let's get you up to speed.", ["objectivesText"] = "Visit the Ferry Dock, the Snug Harbor Inn, the Tradewinds Counting House, and the Flight Master in Tradewinds Market. Progress: I'll bring you to Cyrus after a brief tour of the market.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 158075, 160326 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.731333, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47101] = { ["id"] = 47101, ["name"] = "Arkhaan's Prayers", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "<As you near the statue, a somber voice fills your mind.> \"You must resist the shadow's pull. Come to me, brothers and sisters. Be whole within the Light. Let Arkhaan show you the way home.\" <The rest of the message is garbled, though the nearby broken seem to be gnawing on pieces of the statue.>", ["objectivesText"] = "Collect 5 Fragmented Prayers . Progress: Did you find anything interesting?", ["rewardGold"] = 70225, ["rewardXP"] = 6140, ["rewardItems"] = { 147763, 237812 }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47102] = { ["id"] = 47102, ["name"] = "The Mysterious Missive", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47102 }, ["series"] = { 47104, 47134, 47182, 47554 }, ["description"] = "<On the body, you find a missive emblazoned with the seal of the Army of the Light. If the messenger was killed to prevent the letter's delivery, its contents must be of great import.>", ["objectivesText"] = "Search near the Xenedar for someone with knowledge of the Sealed Missive . Progress: Our fight goes on, champion. Argus must fall. What is that you've found?", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 147491, 147496, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121260, ["x"] = 0.405, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121519, ["x"] = 0.405, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[47139] = { ["id"] = 47139, ["name"] = "Mark of the Sentinax", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 46244, 46245, 46246, 46247, 46248, 46249, 46250, 46251, 46252, 46286, 46730, 46734, 46769, 46832, 46845, 47137, 47139 }, ["description"] = "The Sentinax rains down terror upon the Broken Shore, unleashing hordes of demons that menace our forces. The fiends seek to stop us from taking the Tomb. They will fail. Lure out the strongest among their vile ranks. Slay them and seize the marks they bear. Make the Legion fear our strength!", ["objectivesText"] = "Collect 50 Marks of the Sentinax . Progress: The Sentinax is well defended, but we will crush everything it sends against us.", ["rewardGold"] = 619600, ["rewardXP"] = 7675, ["rewardItems"] = { 146127, 146903, 146905, 146906, 146907, 146909, 146910, 147356, 147582, 147775, 147891, 147892, 237812 }, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 117873, ["x"] = 0.446, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 117873, ["x"] = 0.446, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.632 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 290, ["title"] = "Legionfall Campaign", ["questLineID"] = 309, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 309, ["name"] = "Legionfall Campaign", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47181] = { ["id"] = 47181, ["name"] = "The Smoking Gun", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8978, ["mapID"] = 895, ["storyline"] = { 47181, 47485, 47486, 47487, 47488, 50531, 50573, 53041 }, ["description"] = "The Ashvane Company doesn't know it yet, but throwing you into Tol Dagor was the biggest mistake they've ever made. That new powder we swiped could be the key to bringing them down. First, how about we give everyone a little demonstration of just how powerful this stuff is? <Flynn loads a pinch of the glittering powder into his pistol.> Go ahead, take a shot at that barrel over there.", ["objectivesText"] = "Fire Flynn's Pistol at the Water Barrel in the Harbormaster's Office. Progress: Don't worry, it won't hurt anyone. I think.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 158065, 158066, 163032, 163034 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.6892, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8978 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 585, ["name"] = "The Ashvane Trading Company", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47182] = { ["id"] = 47182, ["name"] = "Long Overdue", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 886, ["storyline"] = { 47104, 47134, 47182, 47287, 47554 }, ["series"] = { 47102, 47104, 47134, 47554 }, ["description"] = "I have learned much. High Inquisitor Raalgar has moved to a base near the Legion citadel across the mountains. This is where he keeps the Fel Heart of Argus , the source of his immortality, and it is powered by wells leading directly to the core of Argus. He is preparing to attack so you will strike first. Mark the location of the wells and I will rain holy fire upon them with the Vindicaar's guns. With that connection to the fel on Argus broken, Raalgar can be killed and the Fel Heart retrieved.", ["objectivesText"] = "Mark the Argussian Heartwells for the Vindicaar's guns, kill the Legion garrison, and retrieve the Fel Heart of Argus from High Inquisitor Raalgar. Progress: Have you dealt with High Inquisitor Raalgar yet?", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 147906, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 355, ["name"] = "The Legion Jailbreak", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47186] = { ["id"] = 47186, ["name"] = "Sanctum of the Sages", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 47189 }, ["description"] = "Sounds like you'll be working with us for awhile. Cyrus will charter a naval transport between here and Stormwind, but I expect you'll want something a bit faster for day to day use. Head back upstairs and take a left when you get outside. You'll find an old study where the Tidesages used to conduct their magic rituals. Surely your Alliance mages have already sensed its power. Inform them they may open their portals there. The harbor guards will keep the room secure.", ["objectivesText"] = "Speak with a 7th Legion Mage in the Sanctum of the Sages. Progress: The Tidesages abandoned that place months ago when they pulled back to their monasteries. We still don't know why.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 158075, 160326 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 120788, ["x"] = 0.68, ["y"] = 0.22 }, { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 120788, ["x"] = 0.68, ["y"] = 0.22 }, { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 7, ["flags"] = 0 } } },
[47189] = { ["id"] = 47189, ["name"] = "A Nation Divided", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 47186 }, ["description"] = "Kul Tiras must be unified before it can be of any help to the Alliance. Let's get you briefed on the current situation in each of our major territories. Then you can take a look at the map behind me and make the call on where you want to go first.", ["objectivesText"] = "Inspect the Scouting Map in the Harbormaster's Office. Progress: Have you figured out your next move? Use the planning map to help you decide.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 160326 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.731333, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 615, ["name"] = "Mission from the King", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47198] = { ["id"] = 47198, ["name"] = "They Want Us Alive", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47198, 47200, 47201, 47204, 47205, 47229 }, ["description"] = "Blood troll poisons are made to paralyze, not kill. See, dey want us alive. I do not feel good thinking about why. I am making antitoxins as quickly as I can, but I need someone like yourself to get out dere and test dem. Take what I have made so far and see if we can get those soldiers back on their feet.", ["objectivesText"] = "Cure 8 Wounded Captives .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 147833 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121599, ["x"] = 0.604, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121599, ["x"] = 0.604, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 795, ["name"] = "Blood Gate", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47199] = { ["id"] = 47199, ["name"] = "The Blood Gate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 862, ["storyline"] = { 47199 }, ["series"] = { 47200 }, ["description"] = "We just received word that the Northern border is under heavy attack by an army of blood trolls. King Rastakhan has called for reinforcements. You are more familiar with that threat than any of us. Go and do what you can to help them.", ["objectivesText"] = "Journey to the Blood Gate.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121599, ["x"] = 0.604, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9598 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 864, ["name"] = "Blood Gate", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47200] = { ["id"] = 47200, ["name"] = "Ticks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47198, 47200, 47201, 47204, 47205, 47229 }, ["series"] = { 47199 }, ["description"] = "Kill those bloodbellies before dey take off with all of my soldiers! I will have my troops prepare for a flanking charge.", ["objectivesText"] = "Slay 6 Bloodbelly Fliers. Progress: We are losing too many, too quickly.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121599, ["x"] = 0.604, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121599, ["x"] = 0.604, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 795, ["name"] = "Blood Gate", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47201] = { ["id"] = 47201, ["name"] = "Rokhan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47198, 47200, 47201, 47204, 47205, 47229 }, ["description"] = "My scouts have informed me dat your Darkspear shadow hunter, Rokhan , has returned from Nazmir. He is pinned down at de far side of de gate. We need to break dis onslaught with a flanking maneuver. Old Rotana is in position. Mount up and smash through de side of those blood troll ranks. Once down dere, try to find Rokhan . Oh, and $p, be careful. A lot of dark magic is being tossed around down dere.", ["objectivesText"] = "Ride the Old Rotana into the fray and then find Rokhan .", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121599, ["x"] = 0.604, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121601, ["x"] = 0.585, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.604, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 795, ["name"] = "Blood Gate", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47204] = { ["id"] = 47204, ["name"] = "The New Frontline", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47198, 47200, 47201, 47204, 47205, 47229 }, ["series"] = { 47205, 47229 }, ["description"] = "Kill anything ya see dat not a Zandalari!", ["objectivesText"] = "Slay Blood Troll forces.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121601, ["x"] = 0.585, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121601, ["x"] = 0.585, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 795, ["name"] = "Blood Gate", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47205] = { ["id"] = 47205, ["name"] = "Warmother", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47198, 47200, 47201, 47204, 47205, 47229 }, ["series"] = { 47204, 47229 }, ["description"] = "Old Rotana be cursed by da warmother dese vile blood trolls brought with dem. We need to take her down so we can get dis old direhorn back in da field.", ["objectivesText"] = "Slay Warmother Shazraka .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 158653, 162453 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121601, ["x"] = 0.585, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121601, ["x"] = 0.585, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 795, ["name"] = "Blood Gate", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47219] = { ["id"] = 47219, ["name"] = "A Vessel Made Ready", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 10339, 10384, 10385, 10406, 10408, 10437, 10439, 47203, 47217, 47218, 47219, 63855, 63895, 63976, 63977, 63979, 63980, 63982, 63983, 63984, 63985, 85027, 85028, 85029, 85035, 85036 }, ["description"] = "After some consideration, I have decided to allow Alleria another opportunity to pursue her destiny. I suppose you want to know what that means, mortal. < Locus-Walker laughs.> Meet us deep in the Shadowguard camp ahead- my brethren are preparing a summons that will provide adequate energy for Windrunner to begin again. Witness what happens when you harness the Void's power.", ["objectivesText"] = "Defeat Nhal'athoth and collect his heart. Progress: I see the path clearly, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 151088, 152713, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121597, ["x"] = 0.339333, ["y"] = 0.492222 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.339333, ["y"] = 0.492222 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 }, { ["id"] = 268, ["title"] = "Lorewalking: The Ethereals", ["questLineID"] = 5691, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5691, ["name"] = "Lorewalking: Ethereals", ["orderIndex"] = 12, ["flags"] = 0 } } },
[47220] = { ["id"] = 47220, ["name"] = "A Beacon in the Dark", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "That was... an intense experience. <Alleria rubs her forehead.> It is difficult to focus. I need you to return to Velen. Give him this. <She places something cold and dense in your palm.> I feel as though he should have it, though I am not sure why. Tell him all that we have learned. I am sure Romuul will have been watching our progress. With any luck, a beacon is already headed our way.", ["objectivesText"] = "Take the Remnant of Nhal'athoth to Velen on the Vindicaar. Progress: What is this? Such darkness...", ["rewardGold"] = 101100, ["rewardXP"] = 6140, ["rewardItems"] = { 152602, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 121230, ["x"] = 0.357778, ["y"] = 0.541556 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.357778, ["y"] = 0.541556 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 886, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47226] = { ["id"] = 47226, ["name"] = "The Orphaned Hatchling", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "<The surviving hatchling bleats piteously as it gazes at its mother's corpse. It inspects you hopefully and seems to want to follow you. Perhaps you can find someone in Warbeast Kraal who can care for it?>", ["objectivesText"] = "Find someone in Warbeast Kraal who cares for young direhorn.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 122939, ["x"] = 0.659333, ["y"] = 0.413333 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.659333, ["y"] = 0.413333 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47228] = { ["id"] = 47228, ["name"] = "Xibalan Ecology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47228, 47235, 47329, 48317, 48399, 48400, 50043 }, ["description"] = "I had really hoped this area would be more hospitable. The Zandalari have been no help whatsoever in clearing this space for archaeological exploration. Before we can even begin to uncover Xibala's secrets, we must make it safe for those less combat savvy to do their work. You will find the ruins ahead infested with all manner of carnivorous beasts. The few intrepid explorers who ventured within have all failed to return. Local ecology will not stand in the way of progress, <name>. Understand?", ["objectivesText"] = "Slay 8 Xibalan predators.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131582, ["x"] = 0.438, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131582, ["x"] = 0.438, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5403, ["name"] = "Fossil Extraction", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47229] = { ["id"] = 47229, ["name"] = "Bulwark of Torcali", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47198, 47200, 47201, 47204, 47205, 47229 }, ["series"] = { 47204, 47205 }, ["description"] = "We got Old Rotana up on her feet again. Load up an' take her reins. Give us some cover so Talanji can fight her way in from her side.", ["objectivesText"] = "Ride Old Rotana into battle against the blood trolls .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121601, ["x"] = 0.585, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135708, ["x"] = 0.586667, ["y"] = 0.195333 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 795, ["name"] = "Blood Gate", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47235] = { ["id"] = 47235, ["name"] = "Scrying for the Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47228, 47235, 47329, 48317, 48399, 48400, 50043 }, ["description"] = "On behalf of the Horde we seek a relic called the Eye of Xibala. The locals have been no help whatsoever and Miss Tae'shara insists that we use her survey equipment. I abhor guesswork. Instead we shall use a more direct method: scrying. I will mark three locations on your map. I would like you to place a scrying vessel at each of them. I will use their measurements to isolate the relic's location and we will be on our way.", ["objectivesText"] = "Place 3 Scrying Vessels in Xibala.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 143536, 237812 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.413333, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5403, ["name"] = "Fossil Extraction", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47248] = { ["id"] = 47248, ["name"] = "'Til Death Do Us Part", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 47248 }, ["description"] = "I don't know who you are, but I need your help. My precious Valjabu always told me he didn't care dat he took de vows of a priest... we would be together forever. Well, my time came to pass, and I knew I'd not be able to go on without him. I came back and have been waiting in dis spot for... it seems forever, and Valjabu never showed! I've been walking around dis world for far too long. Please, I beg you, bring a memento of my Valjabu back to me!", ["objectivesText"] = "Obtain Valjabu's Tusk Ring . Progress: Did you find Valjabu yet? His urn is around here somewhere.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 150754 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122706, ["x"] = 0.366, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122706, ["x"] = 0.366, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.366, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[47257] = { ["id"] = 47257, ["name"] = "The Bones of Xibala", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 862, ["storyline"] = { 47257 }, ["series"] = { 47329 }, ["description"] = "Far to the south you will find the bones of an ancient creature. This is Xibala, the progenitor, first of the devilsaurs. She was mother to Rezan, mother to all that came after. The Zandalari do not live there, as it belongs to beasts now. I have heard rumors of some of your Horde arriving in search of something among her bones. This is ill advised. Look into it, won't you?", ["objectivesText"] = "Travel to Xibala and speak with Examiner Tae'shara Bloodwatcher .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131582, ["x"] = 0.438, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9598 } }, ["questType"] = "standard" },
[47258] = { ["id"] = 47258, ["name"] = "Prepare for a Siege", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47258 }, ["description"] = "It would seem we must make ready for a siege. For now, return to your Horde in Dazar'alor. Prepare for de coming conflict. Should de forces of Nazmir surge, I will send word.", ["objectivesText"] = "Speak with Baine Bloodhoof .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135890, ["x"] = 0.6, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[47259] = { ["id"] = 47259, ["name"] = "Direhorn Daycare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "Handler Bazkoji had a real gift with de little ones. If dis hatchling is following you, it must mean Bazkoji is dead. I don't have time to find another handler. Are you up to de task? It's a lot of work, and de little ones get attached real fast. If you're going to care for it, it will be a commitment. That baby will be depending on you. I hope you will be up to de task of feeding and protecting it. First things first: food. Dere is plenty of fodder in de pens and river below.", ["objectivesText"] = "Feed your hatchling.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47260] = { ["id"] = 47260, ["name"] = "Side Effects May Include...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47260 }, ["description"] = "<Your direhorn companion hiccoughs repeatedly. Each time, it either shrinks or grows by a perceptible amount. It whines at you in distress. You could use some help.>", ["objectivesText"] = "Speak to Beastlord L'kala in Warbeast Kraal.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141952, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[47261] = { ["id"] = 47261, ["name"] = "How to Train Your Direhorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "I have to get some of whatever you fed your baby! Wow! Now dat it's bigger, it is time to teach it to be a reliable battle companion. Let's see how it does against a tougher challenge, hmm? Talk to Kraal Master B'khor when you are ready to begin.", ["objectivesText"] = "Talk to Kraal Master B'khor and choose to train your direhorn. Progress: How did de training go?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 122009, ["x"] = 0.675333, ["y"] = 0.434667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47272] = { ["id"] = 47272, ["name"] = "Direhorn Growth Hormone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["series"] = { 47418 }, ["description"] = "Nice little critter you got there. Seems a tad too small to be much more than a nuisance though. Wanna help a friend make a profit? There's an abundance of opportunity here, but these trolls won't listen to me! Tell you what, I can make a supplement of sorts that'll make hair grow on your chest! Er, your hatchling's chest! I know direhorn are vegetarians and all, but there's a reason all the biggest predators eat meat! Rapid growth requires protein. LOTS of protein. You interested?", ["objectivesText"] = "Collect 10 Steaming Fresh Carrion . Progress: So? Did you get everything I need?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 150347 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47283] = { ["id"] = 47283, ["name"] = "Chop, Chop!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 47283 }, ["description"] = "Throm-ka, <name>. I'm always looking for someone who thinks they can swing an axe with the best of them. If you can remove that sapling without much trouble, I'm sure we can find a better use for your skills.", ["objectivesText"] = "Pick up a Sturdy Axe , then gather 5 Freshly-Chopped Wood from the nearby Sapling. Progress: Hmm?", ["rewardGold"] = 280900, ["rewardXP"] = 3410, ["rewardItems"] = { 67163, 67180, 67197, 67213, 87399, 108439, 155127, 155128, 155131, 155136, 155139, 155150, 155153, 156514, 156531, 158641, 166846, 166970, 166971, 211279, 242241, 246697 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[47289] = { ["id"] = 47289, ["name"] = "Teddies and Tea", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 44785, 45079, 47289, 47428, 53464, 53465 }, ["description"] = "There's nobody to play with here anymore. But you'll play with me, right <mister/lady>? It's time for tea! Help me find the other guests, please!", ["objectivesText"] = "Gather Mr. Munchykins , Trunksy , and Mayor Striggs for the tea party. Progress: This is going to be the best tea party ever!", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 154874, 154875, 154894, 166808 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 121603, ["x"] = 0.5564, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.5564, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5447, ["name"] = "A Tea Party", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47310] = { ["id"] = 47310, ["name"] = "Naptime", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "Your not-so-little guy is looking a bit ragged after such an exciting day. I bet you both need a rest, hm? Come back later when you're a bit stronger.", ["objectivesText"] = "Stable your direhorn in the Beast Pen. Progress: I bet you and your direhorn need a bit of rest, hm?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47311] = { ["id"] = 47311, ["name"] = "Headbutting 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "Your beast is looking well fed. Good. Try and keep it dat way. Now, next you need to teach your little one to defend itself. Direhorns in de wild are prey for much larger creatures and de young are easy pickings for saurid and their like. Go out into de Savagelands and show your little one how to fend dem off. It's all in de horn, <name>.", ["objectivesText"] = "Assist your hatchling in fighting 12 creatures.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47312] = { ["id"] = 47312, ["name"] = "Queenfeather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "Ah, so you are de one who inherited Bazkoji's herd. What is left of it, anyway. I know what killed him, and I tried to warn him. Queenfeather is a vicious ravasaur, bigger than de rest and smarter as well. Most of de eggs around here are hers. Usually I praise de strength of such a beast, but she has become a nuisance. You will find her guarding her nests in de feeding grounds. Kill her and bring back one of her head feathers as proof dat de deed is done.", ["objectivesText"] = "Slay Queenfeather and claim one of her feathers. Progress: Does Queenfeather still stalk us?", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 160945 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 125486, ["x"] = 0.69, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 125486, ["x"] = 0.69, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47313] = { ["id"] = 47313, ["name"] = "Discreet Discussions", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "General Jakra'zet cannot be trusted. He is up to something, but I do not know what. Any who question his actions earn demselves a trip to de sands. As long as he remains in power, my city will never be safe. Speak to his guards. See what you can find out, but be discreet. We do not want to alert Jakra'zet to our actions.", ["objectivesText"] = "Question Enforcers within Dazar'alor. Progress: It is not safe to ask questions about de general around here.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122817, ["x"] = 0.515, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47314] = { ["id"] = 47314, ["name"] = "Rumors of Exile", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Talanji sent you, didn't she? De princess needs to know dat it is no longer safe to ask such questions so openly. Warguard Rakera spoke out, and no one has heard from her since. Rumor has it she was exiled to Vol'dun .", ["objectivesText"] = "Follow Bladeguard Kaja .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 179384 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122817, ["x"] = 0.515, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122320, ["x"] = 0.5052, ["y"] = 0.314 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47315] = { ["id"] = 47315, ["name"] = "Into the Dunes", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Whatever Rakera uncovered, it was important enough to earn her a death sentence to de sands. We must head into Vol'dun to find her. We cannot let whatever she knows about Jakra'zet die with her in de dunes.", ["objectivesText"] = "Fly into the deserts of Vol'dun and search for Warguard Rakera .", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122320, ["x"] = 0.5052, ["y"] = 0.314 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 130455, ["x"] = 0.66, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.5052, ["y"] = 0.314 }, ["mapCandidates"] = { ["npc"] = { 864, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47316] = { ["id"] = 47316, ["name"] = "Secrets in the Sand", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "I found this journal buried in the sand. Kiro tried to toss it in the fire. \"Our wagon has no space for a diary, Meerah . What practical use does it have?\" Don't tell him I said so, but I think it's fascinating! Can you imagine what kinds of secrets it holds? Quite a few pages are missing, but I bet you can recover them out on the dunes!", ["objectivesText"] = "Recover the journal's missing pages. Progress: What have you found?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 151346 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122583, ["x"] = 0.568, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 130341, ["x"] = 0.549, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 14, ["flags"] = 0 } } },
[47317] = { ["id"] = 47317, ["name"] = "Searching for Survivors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "It is good to see you are safe, but what of de others? Have dey been lost to de sands? You need to head back to de crash site and see if de others survived. I will ask around and see if these fox people can tell us anything about Rakera.", ["objectivesText"] = "Search for survivors near the crash site.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 130341, ["x"] = 0.549, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 130341, ["x"] = 0.549, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 12, ["flags"] = 0 } } },
[47319] = { ["id"] = 47319, ["name"] = "Restorative Venom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "Meerah here found your friend in the dunes. The lightning strike nearly killed her. It might still, without treatment. The wasps within the grove have a painful sting, but their venom also has restorative properties. I can extract what I need from their glands. With an ample amount of venom, we should be able to soothe your friend's wounds.", ["objectivesText"] = "Collect 15 Sandstinger Venom Glands . Progress: Have you brought the glands? We can't heal your friend without them.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160441 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123586, ["x"] = 0.568, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123586, ["x"] = 0.568, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47320] = { ["id"] = 47320, ["name"] = "A Balm to Calm", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "As promised, here is the balm that should remedy your companion's injuries. Apply it liberally to any bits of exposed flesh. Its effects should be felt immediately.", ["objectivesText"] = "Use the Restorative Balm on Bladeguard Kaja .", ["rewardGold"] = 154900, ["rewardXP"] = 2060, ["rewardItems"] = { 150759 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123586, ["x"] = 0.568, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 130341, ["x"] = 0.549, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47321] = { ["id"] = 47321, ["name"] = "Knickknack Takeback", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "Nisha told me you came here in search of an exile. One named Rakera? We don't know her, but we might be able to help you find her. You help us, and we help you. Deal? We survive by scavenging. We trade what we find, but the sethrak that raided our burrows made away with many of our knickknacks . I always knew they were ruthless, but never imagined they'd be so greedy. Take back what the sethrak have taken, and I'll see that you are provided safe passage through the dunes.", ["objectivesText"] = "Collect 6 Knickknacks from sethrak within The Serpent's Maw. Progress: You help us, and we help you. Deal?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 151273, 151278 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123586, ["x"] = 0.568, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123586, ["x"] = 0.568, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 15, ["flags"] = 0 } } },
[47322] = { ["id"] = 47322, ["name"] = "Aided Escape", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47322 }, ["description"] = "The sethrak may be strong, but we're quick. Well, at least Mekaru and I are. We just barely made it back to the wagon with our tails attached. The others weren't so lucky, I guess. We've been waiting a while, and still no sign of them. If you're headed into the thick of it, would you mind looking for our friends?", ["objectivesText"] = "Free Hakasi and Kipp from within The Serpent's Maw. Progress: We abandoned our scavenging as soon as the sethrak showed up. Not all of us made it to safety...", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 155388, 155389, 155390, 155391, 155409, 155410, 155411, 155412 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137631, ["x"] = 0.546, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137631, ["x"] = 0.546, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["startItems"] = { 151342 } },
[47324] = { ["id"] = 47324, ["name"] = "Unlikely Allies", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "I believe this is one of the Keepers' keys! Only Vorrik would know for sure. We need to head to the temple at once. My pterrordax can take us there when you're ready, but we need to hurry.", ["objectivesText"] = "Fly to the Sanctuary of the Devoted.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134533, ["x"] = 0.47, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128687, ["x"] = 0.272, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 609, ["name"] = "The Three Keepers", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 42, ["flags"] = 0 } } },
[47327] = { ["id"] = 47327, ["name"] = "Answering Their Attacks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "The sethrak's attacks on our burrows cannot go unanswered. They need to learn that not all within the desert will give up so easily. The only thing the sethrak understand is blood, so that's the language we'll use to teach them. < Nisha pauses and looks at you, skeptical that you understood her.> I'm saying we need to kill the sethrak here. All of them.", ["objectivesText"] = "Kill sethrak in the Abandoned Burrows. Progress: The sethrak will answer for what they have done.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 130455, ["x"] = 0.66, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47329] = { ["id"] = 47329, ["name"] = "The Bloodwatcher Legacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47228, 47235, 47329, 48317, 48399, 48400, 50043 }, ["series"] = { 47257 }, ["description"] = "Greetings, <name>. I have been sent on behalf of my father, High Examiner Tae'thelan Bloodwatcher, to oversee the extraction of all fossils, relics, and artifacts from this area. My sources inform me that an object that could advance the Horde's cause may be buried beneath this very site. I will require your help extracting it. You see, these nightborne are not precisely good with their hands. Nor do they enjoy getting dirty. Could you be a dear and set a good example?", ["objectivesText"] = "Help Examiner Tae'shara Bloodwatcher recover a Xibalan fossil. Progress: By all means, let us assist young Tae'shara. Such enthusiasm is to be rewarded.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131582, ["x"] = 0.438, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5403, ["name"] = "Fossil Extraction", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47332] = { ["id"] = 47332, ["name"] = "Your Next Move", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 47332, 51770, 51771, 52746, 52749, 53079, 53333 }, ["description"] = "Princess Talanji plans to travel north to Nazmir. The blood trolls there are a threat she believes her father refuses to acknowledge. General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe. You will also need to win over King Rastakhan here in Zuldazar . This city is vast and has many secrets.", ["objectivesText"] = "Choose your next move in Zandalar.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 618, ["name"] = "Mission from the Warchief", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 793, ["name"] = "Zandalar Zone Choice", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47418] = { ["id"] = 47418, ["name"] = "Growing Pains", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["series"] = { 47272 }, ["description"] = "These trolls are missing a real opportunity here! They complain about not having enough beasts to go around, yet have they really tried to mass produce them? Nope! With my Direhorn Growth Hormone , they'll be able to fill these pens to overflowing! Sure, the overcrowding might lead to disease and excess waste issues, but I'm sure those are solvable. Ha ha ha this is gonna be great!", ["objectivesText"] = "Feed the Direhorn Growth Hormone to your hatchling. Progress: Well? Did your hatchling try the DGH yet?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 147897 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47428] = { ["id"] = 47428, ["name"] = "Kitty?", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 44785, 45079, 47289, 47428, 53464, 53465 }, ["description"] = "You have to find our last guest before it's time for tea! Smoochums really likes the woods, I bet we'll find him there!", ["objectivesText"] = "Find Smoochums in Glenbrook Woods.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 88704, 88705, 88706, 88707, 88708 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 121684, ["x"] = 0.568, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.444 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5447, ["name"] = "A Tea Party", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47441] = { ["id"] = 47441, ["name"] = "Pests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 47441 }, ["series"] = { 47442 }, ["description"] = "Let me guess, de saurid stole something of yours as well, eh? Look, I don't have de time to run down every little thing dese ankle-biters snap off with. You want some coin? Help me kill some of dese snappers. Otherwise, leave me be.", ["objectivesText"] = "Slay 8 Thieving Snappers in the Zocalo.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 127665, ["x"] = 0.402, ["y"] = 0.192 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 126334, ["x"] = 0.355, ["y"] = 0.078 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[47442] = { ["id"] = 47442, ["name"] = "Curse of Jani", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 47442 }, ["series"] = { 47441 }, ["description"] = "Thief and killer, know dat ya be standin' before da Patron of Scavengers, da Lord of Thieves, da God of Garbage, Master of Minions, and da Keeper of Secrets. Ya be standin' before me in raiment worth entire kingdoms of gold, bearin' weapons dat cost more than even me most devout and renowned followers will ever earn. I tink now be a good time ta teach ya a lesson. Maybe show ya high and mighty greatness what it means ta be snappin' in da gutters.", ["objectivesText"] = "Survive the Trial of Jani . Progress: You be bitin' that ratmon yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 168970 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 126334, ["x"] = 0.355, ["y"] = 0.078 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 126334, ["x"] = 0.355, ["y"] = 0.078 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.078 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[47485] = { ["id"] = 47485, ["name"] = "The Ashvane Trading Company", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 47181, 47485, 47486, 47487, 47488, 50531, 50573, 53041 }, ["series"] = { 47486, 47488, 47489, 50531, 50573, 53041 }, ["description"] = "So, Ashvane's goons are walking around with a new powder that can blow a galleon clean in half and the military has no idea. We need to find out how much of this powder they have and where it's going. An old buddy of mine works the ferry down by the Ashvane Foundry. He may know something about this. You can take the ferry from Tradewinds Market to Eastpoint Station. Once you get there, look for a man named Cagney . Tell him I sent you. He owes me a favor.", ["objectivesText"] = "Speak with Cagney at Eastpoint Station. Take the ferry from Will Melborne in Tradewinds Market.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 158065, 158066, 163032, 163034 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 122671, ["x"] = 0.774, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 585, ["name"] = "The Ashvane Trading Company", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47486] = { ["id"] = 47486, ["name"] = "Suspicious Shipments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47181, 47485, 47486, 47487, 47488, 50531, 50573, 53041 }, ["series"] = { 47485, 47488, 47489, 50531, 50573, 53041 }, ["description"] = "Normally I wouldn't tell you nothin'... but I'll spill it for Cyrus. Ashvane's onto somethin' big. They got guys workin' round the clock in there. Even brought in some muscle to keep everyone uh... \"motivated.\" I don't know anything about what they're makin', but I know it ain't passin' through here to Boralus. If I were dumb enough to go snooping around in there, I'd look at the goods themselves. See if they got shipping labels. But I ain't that dumb, so you gotta do it.", ["objectivesText"] = "Inspect 5 Marked Goods in the Ashvane Foundry.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 158065, 158066, 163032, 163034 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 122671, ["x"] = 0.774, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 585, ["name"] = "The Ashvane Trading Company", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 12, ["flags"] = 0 } } },
[47487] = { ["id"] = 47487, ["name"] = "Labor Dispute", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47181, 47485, 47486, 47487, 47488, 50531, 50573, 53041 }, ["description"] = "The Ashvane Company has been workin' their people so hard they even tried to strike! The company brought in a bunch of goons to break it up and get everyone back to work. Heard they even shot a couple guys who tried to walk off the job. What say you give 'em a taste of their own brutality while you're in there?", ["objectivesText"] = "Slay 10 Company Watchmen, Company Enforcers , or Company Fusiliers .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 158065, 158066, 163032, 163034 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 122671, ["x"] = 0.774, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 122671, ["x"] = 0.774, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.774, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 585, ["name"] = "The Ashvane Trading Company", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 13, ["flags"] = 0 } } },
[47488] = { ["id"] = 47488, ["name"] = "Small Haulers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47181, 47485, 47486, 47487, 47488, 50531, 50573, 53041 }, ["series"] = { 47485, 47486, 47489, 50531, 50573, 53041 }, ["description"] = "<sniff> They said they would feed us. Said they'd keep us warm. < Olive runs the sleeve of her coat across her nose.> But they were mean! And it was really hard work. And when we tried to rest, they yelled at us! <sniff> I got away, but my friends are still in there.", ["objectivesText"] = "Free 6 Urchin Workers from the Ashvane Foundry.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 158065, 158066, 163032, 163034 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 122672, ["x"] = 0.768, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.768, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 585, ["name"] = "The Ashvane Trading Company", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 14, ["flags"] = 0 } } },
[47489] = { ["id"] = 47489, ["name"] = "Stow and Go", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["series"] = { 47485, 47486, 47488, 50531, 50573, 53041 }, ["description"] = "<Flynn lifts his collar to hide his face and speaks to you under his breath.> You see that ship? I know that ship. Let's just say her captain and I have a little history. It's a smuggling vessel. Our illegal weapons are on there for sure. I'd bet my coat on it... and I love this coat. We need to find out where it's going... How are you in tight spaces?", ["objectivesText"] = "Stow away on The Maiden's Virtue.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 158065, 158066, 163032, 163034, 245271, 252386, 252400, 252403, 252406, 252653, 252654, 252754 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 134166, ["x"] = 0.758, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128377, ["x"] = 0.8555, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 18, ["flags"] = 0 } } },
[47497] = { ["id"] = 47497, ["name"] = "Meet the Goldtusk Gang", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["series"] = { 48327 }, ["description"] = "Greetings, traveler, and welcome to de Goldtusk Inn! Unless you're here to kill us... In which case, get out. Otherwise, sit down and enjoy de mess! I mean, don't mind de mess. EAT DE MESS! No, don't eat de mess. Ignore it! < Rhan'ka turns to the skull with the eyepatch and shouts furiously in Zandalari.> Ha, don't mind him. All exiles are welcome to rest at de Goldtusk Inn, de only luxury lodge in dese harsh dunes. Come, let me introduce you to de staff.", ["objectivesText"] = "Meet the staff of the Goldtusk Inn. Progress: My friends are waiting... Don't be rude.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47498] = { ["id"] = 47498, ["name"] = "Rhan'ka's Lost Friend", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "When you head up to Dead Man's Pass, be sure to say hello to Zulsan. He's my best friend, even if he doesn't want to be near me most of de time. Ha! Seriously, though, he's been up on de cliffs for days. If you find him, convince him to come back down to de inn. We need him to restock our breakfast buffet. Oh, and a completely unrelated question dat has nothing to do with you not being able to find Zulsan and my needing to replace him: How wide is ya head?", ["objectivesText"] = "Find Zulsan in Dead Man's Pass. Progress: Did you find Zulsan yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 150916 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 }, { ["mapID"] = 864, ["npcID"] = 138749, ["x"] = 0.382, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 138749, ["x"] = 0.382, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47499] = { ["id"] = 47499, ["name"] = "The Grinning Idols", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 51057, 51059 }, ["description"] = "Before de curse, we were a loyal crew to a good captain. But de curse corrupted Pirate-King Zem'lan, made him cruel and controlling. Now, he treats us more like slaves than crewmates. Forced to fight and die for his gain, no treasure for ourselves. No speakin' up without punishment. Well, us four, we ain't gonna be his slaves no more. A few of de crew hold onto de idols dat Zem'lan used to curse us. Kill dem and take de idols. I wanna see if we can break dem. Just for fun.", ["objectivesText"] = "Collect the Idol of Binding , Idol of Immortality , and Idol of Sacrifice . Progress: I'd hoped I'd never have to see those idols again.", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["rewardItems"] = { 151021, 153351, 153352, 155456, 159976 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 }, { ["mapID"] = 864, ["npcID"] = 136310, ["x"] = 0.342, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47501] = { ["id"] = 47501, ["name"] = "Dirty Work for Dirty Drinks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "Guests gotta earn their keep at de Goldtusk Inn. What say you help me clear out some scorpids at one of our off-site excursion locations? De delightful Dead Man's Pass! Normally, you'd need to purchase our Warlord Package to be allowed access, but I'll make an exception dis time. I'll even throw in our Scorpid King Package. Unlimited scorpid blood drinks all day, every day! Dere's one catch: we're out of scorpid blood. Bring some back and I'll whip up a batch of drinks for us.", ["objectivesText"] = "Collect 20 Caustic Scorpid Blood from deathsnap scorpids in Dead Man's Pass. Progress: My scorpid blood drinks are famous in de Goldtusk Gang!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 150923 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 }, { ["mapID"] = 864, ["npcID"] = 138749, ["x"] = 0.382, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 138749, ["x"] = 0.382, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47502] = { ["id"] = 47502, ["name"] = "The Great Cranium Caper", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["series"] = { 47638 }, ["description"] = "Sandfury thugs attacked de inn after you left and kidnapped de whole Goldtusk Gang! We gotta get dem back. Man'zul was usually de brains behind our thefts back in Zuldazar, but I'll try to come up with a plan to get dem outta dis mess. < Rhan'ka thinks for awhile.> I got it! You rescue 'em all!", ["objectivesText"] = "Rescue the kidnapped members of the Goldtusk Gang in the Sandfury Hideout. Progress: We nothin' without our gang.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 151218, 151219, 151220, 161176, 161177, 161178, 161179, 161180 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 }, { ["mapID"] = 864, ["npcID"] = 138749, ["x"] = 0.382, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47503] = { ["id"] = 47503, ["name"] = "Gozda'kun the Slaver", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "Dat's it. De Sandfury are officially banned from de Goldtusk Inn! You can't just ransack a place, kidnap its staff, and mock its owner with an assortment of fruits and vegetables and expect to get away with it! We gotta teach those thugs what happens when you mess with de Goldtusk Gang! Gozda'kun de Slaver was bossing around de rest of de Sandfury during de attack. Take him out, and leave some Sandfury behind to spread de word.", ["objectivesText"] = "Kill Gozda'kun the Slaver in the Sandfury Hideout.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 138749, ["x"] = 0.382, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.382, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 4, ["flags"] = 0 } } },
