[47513] = { ["id"] = 47513, ["name"] = "Vol'dun", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "General Jakra'zet detests the Horde and cannot be trusted. As long as he remains in power, the city will never be safe. We are not alone in our suspicions. Speak to Princess Talanji to follow up.", ["objectivesText"] = "Speak with Princess Talanji .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.473333, ["y"] = 0.340667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2AdventureMapPoiID"] = 42, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47527] = { ["id"] = 47527, ["name"] = "Rituals of Heresy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47527 }, ["objectivesText"] = "Disrupt the blood rituals Voodoo Pile smashed", ["rewardGold"] = 573000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Disrupt the blood rituals", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Voodoo Pile smashed", ["amount"] = 10, ["type"] = 2, ["objectID"] = 272401, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[47529] = { ["id"] = 47529, ["name"] = "Supernatural Support", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 47529 }, ["description"] = "The loa can bestow powerful boon's to their followers, aid that can be the difference between victory or defeat in our efforts here. Think carefully which of the two you would like to ask for their blessing. The loa will not give their assistance to those who are currently pledged to another loa.", ["objectivesText"] = "Choose which loa you wish to obtain a blessing from.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[47554] = { ["id"] = 47554, ["name"] = "Intercepting the Legion's Plans", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47104, 47134, 47182, 47287, 47554 }, ["series"] = { 47102, 47104, 47134, 47182 }, ["description"] = "Our scout Skara writes in the missive that she learned of a major Legion initiative. She was after two encoded orders held by Legion troops near us to get the details and this must be when she was killed. The Legion splits their messages into encoded parts so that we cannot read them. Skara also writes that her partner Brae, a codebreaker, was slain trying to reach our lines with a code book that we will need to translate the Legion's orders. It is vital you find the orders and that code book!", ["objectivesText"] = "Search the battlefield for Legion troops and kill them to get their Enigmatic Legion Orders . Retrieve the Army of the Light Code Book to decipher the orders. Progress: Have you found the orders and the code book?", ["rewardGold"] = 154900, ["rewardXP"] = 6140, ["rewardItems"] = { 150993, 150995, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 121519, ["x"] = 0.405, ["y"] = 0.635 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 121519, ["x"] = 0.405, ["y"] = 0.635 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.405, ["y"] = 0.635 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 355, ["name"] = "The Legion Jailbreak", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47564] = { ["id"] = 47564, ["name"] = "Restocking the Buffet", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "Imagine for a moment, $p. You wake up in de Goldtusk Inn after a long day of drinking scorpid blood, slaughtering Sandfury, and sharing jokes with your best friend Zulsan . Ya not fully awake yet, and not feeling ya best. What do you need most at dat exact moment? An all-you-can-eat breakfast buffet, of course! I'm working on it, but I need some fruit to balance out my menu. Luckily, I've seen some in de oasis outside. Bring me some, and I'll give you lifetime access to de buffet.", ["objectivesText"] = "Collect 10 Whistlebloom Juicy Fruit . Progress: Dis buffet is going to be a disaster if we don't get dat fruit!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 151022 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122725, ["x"] = 0.436, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122725, ["x"] = 0.436, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47570] = { ["id"] = 47570, ["name"] = "Hidden Motives", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "I do not understand why the naga would bother attacking a small fishing village. Why waste their time on our simple tribe? The naga seek power and we have none. It makes no sense! They must be after something else entirely... Search Darkwood Shoal and learn of their plans. Whatever the naga are after, it must be quite powerful. Perhaps if we find it first, we can use it against them!", ["objectivesText"] = "Locate the naga invasion plans . Progress: Have you uncovered their plans?", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 157866 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134098, ["x"] = 0.62, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134098, ["x"] = 0.62, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47571] = { ["id"] = 47571, ["name"] = "The Elder's Wisdom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "The naga are searching for a powerful artifact called the Ring of Tides. According to the invasion plans, the ring was lost long ago in a battle with Eraka no Kimbul, the great tiger loa. The temple of Eraka no Kimbul is just to the north. If the loa was strong enough to defeat the naga before, maybe he can do it again! We must let the tribe know what we've found! Take the invasion plans to Elder Kuppaka . He is the oldest, and wisest member of our tribe. He will know what to do.", ["objectivesText"] = "Deliver the Invasion Plans to Elder Kuppaka . Progress: Elder Kuppaka will know what to do.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134098, ["x"] = 0.62, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123063, ["x"] = 0.615333, ["y"] = 0.205333 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47573] = { ["id"] = 47573, ["name"] = "Jungleweb Infestation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "The walls of the temple could provide us with vital protection against the naga, but the temple is overrun with jungle spiders. We'll need to clear out the infestation before the tribe can take refuge at the temple. Venture into the lower ruins and lay waste to the spiders that have nested there.", ["objectivesText"] = "Slay 6 Jungleweb Crawlers and 30 Jungleweb Hatchlings .", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134134, ["x"] = 0.585, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134134, ["x"] = 0.585, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47574] = { ["id"] = 47574, ["name"] = "All Webbed Up", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "The lower ruins of the temple are covered in thick webs and spider egg sacs. Some of our tribesman went down to the lower ruins to clear out the spiders, but they haven't come back. I fear for their safety. Please head into the lower ruins and free our brethren before it's too late.", ["objectivesText"] = "Free 8 Tortaka Tribesman .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134134, ["x"] = 0.585, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134134, ["x"] = 0.585, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47576] = { ["id"] = 47576, ["name"] = "Wrath of the Tiger", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "The Tortaka shall have my protection. Even as we speak, an army of the naga have risen from the depths to attack my temple. How soon the naga have forgotten their previous defeat! They seek to reclaim the Ring of Tides, a powerful artifact that I took as my trophy when I killed Azshara's previous champion, Mepjila. I will send you to the battlefield as my avatar to rain destruction upon the naga. They have forgotten what happens to those who trespass against my followers. Remind them.", ["objectivesText"] = "Defeat the naga invasion. Progress: Send the naga army back to the sea!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 161183, 161184, 161185, 161186, 161187 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123052, ["x"] = 0.566, ["y"] = 0.104 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123052, ["x"] = 0.566, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 10, ["flags"] = 0 } } },
[47577] = { ["id"] = 47577, ["name"] = "They Came From The Sea", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["series"] = { 51772 }, ["description"] = "You are free to rest your weary legs in our camp, but I'm afraid we have little more to offer you. Naga have driven us from our village by the sea. We can no longer fish or hunt crabs. I fear we may not survive long if we cannot take back our lagoon. But taking back the lagoon will not be enough. We must find out why the naga attacked us. What is it they are looking for? Take this ancient scroll and use it summon the spirits of the naga. They will only speak truth while under its spell.", ["objectivesText"] = "Question 8 Naga Spirits.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 121427, 121428, 121429, 121430, 132903, 132904, 132905, 132906, 160585, 237812 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134098, ["x"] = 0.62, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134098, ["x"] = 0.62, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47578] = { ["id"] = 47578, ["name"] = "Mark of the Loa", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "You have proven worthy of my blessing, <name>. This means should you choose me as your loa, you can call upon my power when needed. Commune at my shrine and make your decision. Know that whatever you choose, you will always be welcome within these walls.", ["objectivesText"] = "Commune at Kimbul 's Shrine. Progress: I bestow my blessing upon my followers.", ["rewardGold"] = 154900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123052, ["x"] = 0.566, ["y"] = 0.104 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123052, ["x"] = 0.566, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47580] = { ["id"] = 47580, ["name"] = "The Curse of Mepjila", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "Centuries ago, the sea witch Mepjila attacked my temple with an army of naga invaders. My followers fought bravely, but I arrived too late to save them. I defeated the naga army with ease. But as I closed my jaws around Mepjila, she placed a curse upon the spirits of my followers, locking them in an eternal battle they can never win. This mask will give you the power to enter the spirit realm and end their nightmare. Defeat the spirit of Mepjila and the curse will be broken.", ["objectivesText"] = "Defeat the spirit of Mepjila. Progress: You must break the curse and free the captive souls of my followers.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 151826 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123052, ["x"] = 0.566, ["y"] = 0.104 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123052, ["x"] = 0.566, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.104 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47581] = { ["id"] = 47581, ["name"] = "Blessing of Kimbul", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "The entrance to the temple is sealed by a magical barrier. According to my scrolls, the barrier can only be lowered by one who has gained the Ring of Tides . There is a statue somewhere in the temple grounds with the power to bestow the ring, but the ruins are overrun with jungle spiders. Tulu and I are not strong enough to explore the lower ruins ourselves. If you can gain the Ring of Tides and enter the temple, we may finally be able to face the naga head on!", ["objectivesText"] = "Acquire the Ring of Tides . Progress: The statue is somewhere within the temple ruins.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 155450, 160657 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134133, ["x"] = 0.585, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134133, ["x"] = 0.585, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 7, ["flags"] = 0 } } },
[47583] = { ["id"] = 47583, ["name"] = "Die, Die, Diemetradon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47583, 47584, 47585, 47586, 47587, 47588 }, ["description"] = "We are competing, you and I and these other savages. I find this... amusing. South of here you will find a number of diemetradons. I challenge you, <class>, to slay more of these creatures than I. Do you accept my wager?", ["objectivesText"] = "Slay 8 Venomous Diemetradons .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 123022, ["x"] = 0.675, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5411, ["name"] = "Hunting with Nesingwary", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47584] = { ["id"] = 47584, ["name"] = "A Thorn in the Side", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47583, 47584, 47585, 47586, 47587, 47588 }, ["description"] = "You fools speak of \"big game\" hunting like it is a thing of wonder. Bah! None know big game hunting like my kin. Mastery of the hunt, passed down from parent to child, for generations. I am here to prove it. I wager that you could not slay more than eleven of the ankylodon beasts that wander this region.", ["objectivesText"] = "Slay 12 Ankylodons in the Preserve.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 123026, ["x"] = 0.674, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5411, ["name"] = "Hunting with Nesingwary", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47585] = { ["id"] = 47585, ["name"] = "Predatory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47583, 47584, 47585, 47586, 47587, 47588 }, ["description"] = "<There is a wound in his back, possibly from a knife. It seems more than the wildlife is fighting back out here.>", ["objectivesText"] = "Find 2 more hunters in the Preserves. Progress: You found some dead ones? Did you bring back de loot?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 123118, ["x"] = 0.688, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 123019, ["x"] = 0.674, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5411, ["name"] = "Hunting with Nesingwary", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47586] = { ["id"] = 47586, ["name"] = "Hunting the Hunter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47583, 47584, 47585, 47586, 47587, 47588 }, ["series"] = { 49768, 50466 }, ["description"] = "Your hunter king, Nesingwary, is a mighty fine bit of prey here. I even thought of hunting him myself. But someone else is on his trail now. And dat hunter, he is a dangerous one. If you wish to save your hunter king, you best start tracking quickly. If he made camp, you may be too late already. You cannot paint a target and wonder why you were shot! I believe he was last seen heading west...", ["objectivesText"] = "Track down Hemet Nesingwary .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 246492 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 123019, ["x"] = 0.674, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 138669, ["x"] = 0.634, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5411, ["name"] = "Hunting with Nesingwary", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47587] = { ["id"] = 47587, ["name"] = "Headhunter Jo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47583, 47584, 47585, 47586, 47587, 47588 }, ["description"] = "He said he's hunting you. I'm not the prey, I'm the bait! Behind ye!", ["objectivesText"] = "Slay Headhunter Jo . Progress: He's a sly one!", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 159114, 159115, 159116, 159117, 159118, 159119, 159120, 159121, 159122 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 138669, ["x"] = 0.634, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 138669, ["x"] = 0.634, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5411, ["name"] = "Hunting with Nesingwary", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47588] = { ["id"] = 47588, ["name"] = "King of the Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 47583, 47584, 47585, 47586, 47587, 47588 }, ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 246727 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 5411, ["name"] = "Hunting with Nesingwary", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47638] = { ["id"] = 47638, ["name"] = "Powerful Spirits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["series"] = { 47502 }, ["description"] = "You prove your worth, $p. We be willin' to initiate you into de ranks of de Goldtusk Gang, if you wanna join. De ritual drink is ready. Boiled scorpid blood spiked with bilewing honey! Don't mind de smell, it's mostly delicious. It's not terrible. It won't kill you. Usually. When you are ready to join de Goldtusk Gang, let me know. I'll unite you with de whole gang. It's time you see what we see.", ["objectivesText"] = "Participate in the Goldtusk Gang initiation ritual. Progress: Embrace de spirits.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 8, ["flags"] = 0 } } },
