[47654] = { ["id"] = 47654, ["name"] = "Seat of the Triumvirate: The Crest of Knowledge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 40761, 47100, 47101, 47180, 47183, 47184, 47203, 47217, 47218, 47219, 47220, 47238, 47654 }, ["description"] = "We have all that we need now, <name>. Alleria Windrunner awaits your arrival at the Seat of the Triumvirate . Do not go alone, my friend. You will need allies to recover the Crest of Knowledge ... and endure what L'ura has become. I will prepare the Vindicaar and await your return. Light be with you in that dark place.", ["objectivesText"] = "Slay L'ura and retrieve the Crest of Knowledge . Progress: It is a heavy burden I have placed upon you, <name>. I have faith you will not fail.", ["rewardGold"] = 404400, ["rewardXP"] = 6140, ["rewardItems"] = { 151090, 237812, 246812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 120533, ["x"] = 0.523111, ["y"] = 0.462667 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.523111, ["y"] = 0.462667 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "dungeon", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 368, ["questLineOrder"] = 8 } }, ["db2LabelIDs"] = { 4784 }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 883, ["questLines"] = { { ["id"] = 368, ["name"] = "Shadow of Eredath", ["orderIndex"] = 12, ["flags"] = 0 } } },
[47685] = { ["id"] = 47685, ["name"] = "Gatekeeper's Challenge: Cunning", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "Archimonde expected greatness from his pupils. Only the most imaginative minds, the most adroit of intellects, could ever truly fathom the deepest reaches of our magic. I doubt you can relate. The path to the left will take you to a set of three statues. Use them to collect a Mark of Cunning. To preserve the integrity of this trial, I will not be able to provide hints. If you do, by some miracle, happen to succeed, I will formally recognize your... brilliance.", ["objectivesText"] = "Collect a Fragment of Acuity , Wit, and Guile and combine them into a Mark of Cunning. Progress: Display the Mark of Cunning or leave me alone.", ["rewardGold"] = 151650, ["rewardXP"] = 6140, ["rewardItems"] = { 70161, 116689, 116690, 116691, 116692, 129956, 151126, 151127, 151128, 194057, 194058, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 11, ["flags"] = 0 } } },
[47688] = { ["id"] = 47688, ["name"] = "Invasive Species", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "We should seek out an alternate source of energy just in case I am wrong about the conduits. Luckily enough, I think I know where we can find one. The panthara native to Argus are solitary creatures, but it seems whatever magic the Wakeners possessed has drawn them here in great numbers. This is no time to be gentle with the environment--panthara devour energy to survive. Slay them and see if you cannot reclaim some of the power they have consumed.", ["objectivesText"] = "Collect 30 Partially Digested Arcana . Progress: There is always room for a backup plan. Did you find what we seek?", ["rewardGold"] = 210675, ["rewardXP"] = 6140, ["rewardItems"] = { 151366, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.469333 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47690] = { ["id"] = 47690, ["name"] = "The Defiler's Legacy", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["mapID"] = 882, ["storyline"] = { 46815, 46818, 46834, 46941, 47066, 47685, 47686, 47687, 47688, 47689, 47690, 47882, 47883, 48081, 48107 }, ["description"] = "It seems you are not so easily deterred. Very well. Your deeds qualify you to seek the Sigil. To be clear, I am only permitting you to move on. This does not guarantee your success. The greatest of your challenges lies before you. You must go to the Praetorium and face Archimonde himself. Only by defeating the master of the Conservatory will you be worthy of the Sigil. Few have overcome this obstacle. I hope he does not make too much of a mess of you.", ["objectivesText"] = "Defeat Archimonde and retrieve the Sigil of Awakening . Progress: Archimonde himself... what have we gotten ourselves into?", ["rewardGold"] = 619600, ["rewardXP"] = 6140, ["rewardItems"] = { 151476, 152710, 237812 }, ["starts"] = { { ["mapID"] = 882, ["npcID"] = 124070, ["x"] = 0.598, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 882, ["npcID"] = 123413, ["x"] = 0.608, ["y"] = 0.469333 } }, ["coords"] = { ["mapID"] = 882, ["source"] = "quest_giver", ["x"] = 0.598, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 882 }, ["zone"] = { 8701 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 366, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 882, ["questLines"] = { { ["id"] = 366, ["name"] = "The Crown of the Triumvirate", ["orderIndex"] = 13, ["flags"] = 0 } } },
[47695] = { ["id"] = 47695, ["name"] = "Sound the Alarm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["storyline"] = { 47695 }, ["description"] = "Sirens are nothing but trouble! All they do is capture our men, never to be seen again. How is anybody supposed to get their goods to Boralus quickly with them around? Since you're already going down there... mind culling their numbers a bit?", ["objectivesText"] = "Kill 8 Wailing Sirens in Fogcliff Strand.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[47706] = { ["id"] = 47706, ["name"] = "Hunt for King K'tal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47706 }, ["description"] = "Hunters! Dis challenge be for de King of de Preserves. King K'tal is a mighty predator, smart and fast. Gold and honor await de hunter who brings me de head of de King.", ["objectivesText"] = "Recover the Skull of K'tal . Progress: Good hunting.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 151169 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 123019, ["x"] = 0.674, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "group" },
