[47716] = { ["id"] = 47716, ["name"] = "Searching the Ruins", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47716, 48313, 48314, 48315, 48896, 50539, 50561, 50770 }, ["description"] = "Dese dunes are crawling with assassins. Nowhere is safe, but we must press on. De ruins aren't far from here. Let's continue our search on foot.", ["objectivesText"] = "Find Julwaba within Zul'Ahjin.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134162, ["x"] = 0.47, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 608, ["name"] = "A City of Secrets", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 35, ["flags"] = 0 } } },
[47725] = { ["id"] = 47725, ["name"] = "Tomb of Sargeras: Aegwynn's Path", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8524, ["storyline"] = { 47725 }, ["description"] = "As we sealed the tomb, I entrusted the final piece of Sargeras' prison to the Maiden of Vigilance. If you had it you could move freely throughout the tomb, but I know not what became of the keeper and fear the worst.", ["objectivesText"] = "Collect 4 Fragment of the Guardian's Seal from the Maiden of Vigilance in the Tomb of Sargeras on Normal Difficulty. Progress: Without the power of the seal we cannot bypass my wards.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 151248, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8524 } }, ["questType"] = "raid" },
