[47755] = { ["id"] = 47755, ["name"] = "Captured and Enraptured", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47755, 50002, 50005, 50026, 50059 }, ["description"] = "You gotta help me! Me and my crew were running late on a delivery, so we decided to take a detour through this grotto ahead. Boy... that was a mistake. This place is crawling with sirens! If there's one thing my men like more than women, it's grog! Here, take some. Use it to bring them back to their senses. Might be best to rough 'em up a bit to weaken the enchantment.", ["objectivesText"] = "Free 6 Enthralled Sailors in Fogcliff Strand. Progress: Were you able to free my men? Without them, I'm stranded!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 151135 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 123415, ["x"] = 0.502, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 123415, ["x"] = 0.502, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5437, ["name"] = "A Sirens Song", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47756] = { ["id"] = 47756, ["name"] = "The Libation's Liberation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 47756 }, ["objectivesText"] = "Vilescale Naga defeated Sailors Freed", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Vilescale Naga defeated", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Sailors Freed", ["amount"] = 20, ["type"] = 0, ["objectID"] = 123539, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863 },
