[47870] = { ["id"] = 47870, ["name"] = "Dead Men Tell No Tales", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47870, 47871, 47873, 51810 }, ["series"] = { 51773 }, ["description"] = "I'm an employee of the Ashvane Company. We're number one in the Azerite trade. When I took this job, no one told me it would be a one-way trip! I'd do just about anything to escape these dunes, including working with you. Maybe we can help each other out? I'd be willing to part with the code to the captain's lockbox, if you're willing to help me escape this wretched desert. For my plan to succeed, my expedition party needs to die. Can't have them telling anyone I'm missing...", ["objectivesText"] = "Kill the remaining members of Randall's expedition party.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 160000, 160001, 160002, 160003, 160735, 161168, 161169, 161170, 161171 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 124468, ["x"] = 0.451, ["y"] = 0.846 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 124468, ["x"] = 0.451, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5423, ["name"] = "Ashvane Antics", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47871] = { ["id"] = 47871, ["name"] = "Seafaring Necessities", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47870, 47871, 47873, 51810 }, ["description"] = "She might not be much to look at, but this boat will take me back to Boralus. Before my voyage can begin, I'll need a few seafaring necessities. Luckily, everything I need can be found in the Ashvane encampment.", ["objectivesText"] = "Collect a Seafaring Hat , Nautical Map , and Weathered Spyglass . Progress: Have you had any luck securing those items I asked for?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 151628, 151629, 151631, 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 124468, ["x"] = 0.451, ["y"] = 0.846 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 124468, ["x"] = 0.451, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5423, ["name"] = "Ashvane Antics", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47873] = { ["id"] = 47873, ["name"] = "The Captain's Cache", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47870, 47871, 47873, 51810 }, ["description"] = "Well, I'm sure you've figured it out by now, eh? I never was fixing to abandon the crew, I just wanted to move up the ranks. You've helped me out a great deal in that respect. Speaking of respect, I believe there's the matter of Captain Hartford's lockbox ... Here's the code, courtesy of the fallen captain. Just as I promised. It's all yours! Now, don't go telling anyone about our little arrangement, okay? I wouldn't want something like that to spoil such a profitable partnership!", ["objectivesText"] = "Loot Captain Hartford's cache.", ["rewardXP"] = 2060, ["rewardItems"] = { 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139070, ["x"] = 0.432, ["y"] = 0.908 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.908 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5423, ["name"] = "Ashvane Antics", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47874] = { ["id"] = 47874, ["name"] = "Clearing the Fog", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Did you lead Kaja here? I told her not to come after me. It isn't safe... My mind remains fogged, but de memories are slowly returning. Jakra'zet... de weapon... Come, let us find some fresh air. I will tell you what I've discovered.", ["objectivesText"] = "Follow Warguard Rakera .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["rewardItems"] = { 245417 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 130660, ["x"] = 0.535, ["y"] = 0.916 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 130667, ["x"] = 0.5325, ["y"] = 0.9055 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.916 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 33, ["flags"] = 0 } } },
[47918] = { ["id"] = 47918, ["name"] = "To Serve Krag'wa", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 47918 }, ["description"] = "There are other forces who seek to disturb my frogs. The vile naga attack my shores and drain my frogs of their magic! They seek to use my followers as a feast for their thirst for mana. It must be stopped! A powerful shadow hunter named Narez is currently fighting them. You must go aid her and stop the naga from feasting on my frogs!", ["objectivesText"] = "Meet Shadow Hunter Narez in the Upper Frogmarsh.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 120551, ["x"] = 0.755, ["y"] = 0.566 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 125317, ["x"] = 0.776, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[47919] = { ["id"] = 47919, ["name"] = "Just Say No to Cannibalism", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 47919, 47924, 47925, 47998 }, ["description"] = "Of course the Natha'vor trolls have Shoak! Why would it be easy? I'm sick and tired of running from these trolls. That's why you're going in to end this. The Natha'vor trolls have three powerful troll witch doctors called \"corpse mongers\". Take them out and you'll send the tribe into disarray. Of course, this could all fail spectacularly and make my terrible day even worse.", ["objectivesText"] = "Kill Corpse Mongers Jal'aka, Yon'gi, and Nog'shra", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 124933, ["x"] = 0.518, ["y"] = 0.332 }, { ["mapID"] = 863, ["npcID"] = 125024, ["x"] = 0.558, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 125024, ["x"] = 0.558, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5413, ["name"] = "A Bloody Meal", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47924] = { ["id"] = 47924, ["name"] = "Profanity Filter", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 47919, 47924, 47925, 47998 }, ["description"] = "I hate this place! I just want to go home, but I can't because that oaf, Shoak, is missing. Listen, <race>t, I'll make it worth your while if you help me find that dunce. I've got a way to find Shoak, but of COURSE these stupid totems are blocking my magic! Why wouldn't they? Take this scroll and use its magic to burn these totems. I'm going to look around to see if that bonehead is just sleeping somewhere.", ["objectivesText"] = "Destroy 5 Profane Totems with Kajosh 's scroll of inferno . Progress: You destroy those totems yet?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 151849 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 124666, ["x"] = 0.551, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 124933, ["x"] = 0.518, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.551, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5413, ["name"] = "A Bloody Meal", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47925] = { ["id"] = 47925, ["name"] = "Shoak's on the Menu", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 47919, 47924, 47925, 47998 }, ["description"] = "I don't know what stupid thing Shoak did to get captured by the Natha'vor trolls, we'll find out once you rescue him. I bet they're getting ready to make a meal out of Shoak . You need to work fast and get him out! Shoak 's one of the largest oafs that I know, those trolls won't be happy that you're taking their \"meal\" away.", ["objectivesText"] = "Rescue Shoak from the Natha'vor trolls.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 158955, 158956, 158957, 158958, 158964, 158965, 158966, 158967 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 124933, ["x"] = 0.518, ["y"] = 0.332 }, { ["mapID"] = 863, ["npcID"] = 125024, ["x"] = 0.558, ["y"] = 0.322 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 124737, ["x"] = 0.558, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5413, ["name"] = "A Bloody Meal", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47928] = { ["id"] = 47928, ["name"] = "Offering for the Loa", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "The time has come for you to make contact with the great loa Eraka no Kimbul . I can only imagine what it will be like to be in the presence of such an ancient and powerful deity. You have earned the Ring of Tides, so it must be you that addresses the loa. Please present the loa with this offering from our tribe. Tell him of our plight against the naga. Eraka no Kimbul is our only hope of survival now.", ["objectivesText"] = "Meet with Eraka no Kimbul . Progress: You must meet with the loa. Are you ready?", ["rewardGold"] = 154900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134133, ["x"] = 0.585, ["y"] = 0.118 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123052, ["x"] = 0.566, ["y"] = 0.104 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.118 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 8, ["flags"] = 0 } } },
[47939] = { ["id"] = 47939, ["name"] = "If the Key Fits...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47939 }, ["description"] = "These Ashvane are unreasonable. I've tried to bargain for my release, but they refuse any offer I bring to the table. All they want is whatever's bubbling up in that mine. My kind know better than to go near that stuff. It's volatile. There are prisoners in the mine being forced to extract it. Us in the cages? We're back up. When someone dies in the mines, they just send another in. If you release me, I'll make sure you're rewarded! We just need to find the right key for this cage...", ["objectivesText"] = "Collect 6 Ashvane Trader Keys . Progress: We need to find the right key to open this cage.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 151777, 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128422, ["x"] = 0.476, ["y"] = 0.862 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128422, ["x"] = 0.476, ["y"] = 0.862 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.862 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[47943] = { ["id"] = 47943, ["name"] = "Crab Trapping", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "We are trapped here with little in the way of food and supplies. The territorial sethrak control the land to the west, and the spiteful naga the waters to the east. We are caught between a barren desert and a hostile ocean. If you are headed to the lagoon to face the naga, will you bring us back some crabs to eat? I fear that our tribe will soon perish without food...", ["objectivesText"] = "Catch 8 Clampclaw Clackers. Progress: Do you have a case of crabs?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 151763 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134128, ["x"] = 0.62, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134128, ["x"] = 0.62, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47945] = { ["id"] = 47945, ["name"] = "To Market, To Market", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47945 }, ["description"] = "Thanks heaps for getting us out of that pickle, mainlander. I'd hate to ask, but would you be willing to help with another matter? Even before this curse struck the village, our sausage shipments from Carver's Harbor started slowing down. If we don't get them sausages, I won't be able to feed my family! Can you help an honest sausage merchant out? Carver's Harbor is just down the road from here.", ["objectivesText"] = "Meet Thomas Staughton at Carver's Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 155812, 160009, 160010, 160011, 160012, 160021, 160022, 160023, 160024, 198608 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 128467, ["x"] = 0.555, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[47946] = { ["id"] = 47946, ["name"] = "Save Their Bacon", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47946, 47947, 47948, 47949, 47950 }, ["description"] = "This is going to sound strange, <class>, but some of my workers were turned into pigs! Lucky I was out on an errand, or I'd have been caught too! Now my people are tied up awaiting... processing. <Thomas suppresses the urge to retch.> I can't get past those monsters, but you look like the sort who could. Not sure if this helps, but I coulda sworn I heard some wild cackling coming from the warehouse. Please... save my people!", ["objectivesText"] = "Untie Trevor Hightide , Kyle Sailford , Travis Daybreak and Burke Stevenson .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 103786 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5440, ["name"] = "Carver's Harbor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47947] = { ["id"] = 47947, ["name"] = "Big Bad Wolves", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47946, 47947, 47948, 47949, 47950 }, ["description"] = "Wolves with strange, glowing eyes have taken over the area! I don't know what they are or why they're glowing but it cannot mean anything good. They have to be removed! Please, <class>, slay them before more of my friends are killed.", ["objectivesText"] = "Slay 10 Hexed Howlers in Carver's Harbor.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5440, ["name"] = "Carver's Harbor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[47948] = { ["id"] = 47948, ["name"] = "Pork Chop", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47946, 47947, 47948, 47949, 47950 }, ["description"] = "Roland Hacksaw was the best butcher I've ever worked with... but he's gone insane! He's still processing pigs into sausage! You have to stop him!", ["objectivesText"] = "Slay Roland the Butcher.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 155127, 155128, 155131, 155136, 155139, 155150, 155153, 158641 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5440, ["name"] = "Carver's Harbor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47949] = { ["id"] = 47949, ["name"] = "That's Not My Fetish", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47946, 47947, 47948, 47949, 47950 }, ["description"] = "<The glassy eyes of the pig fetish seem to follow you as you approach. The dark power emanating from the witch's fetish must be what is keeping the workers transformed. Perhaps Thomas Staughton might have some idea what to do with it.>", ["objectivesText"] = "Bring the Pig Fetish to Thomas Staughton . Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 151793 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5440, ["name"] = "Carver's Harbor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[47950] = { ["id"] = 47950, ["name"] = "Cured Ham", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47946, 47947, 47948, 47949, 47950 }, ["description"] = "That foul thing has to be what's keeping my men transformed into pigs. Hmm. Well there isn't too much that can withstand a good cleansing fire! I say we burn it! Toss it into the campfire!", ["objectivesText"] = "Toss the Pig Fetish into the campfire. Progress: Into the flames with that foul thing!", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 151793, 153432 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124786, ["x"] = 0.632, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5440, ["name"] = "Carver's Harbor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47959] = { ["id"] = 47959, ["name"] = "The Warguard's Trail", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "Rakera's journal suggested she moved south. It's de only lead we have. Meerah is headed dat way, and has invited us to travel with her. These vulpera know de desert better than any troll I've ever met. Our chances of survival are highest if we travel together.", ["objectivesText"] = "Travel with Meerah's Caravan in search of Warguard Rakera.", ["rewardGold"] = 154900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 130341, ["x"] = 0.549, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126696, ["x"] = 0.53, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.549, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 16, ["flags"] = 0 } } },
[47960] = { ["id"] = 47960, ["name"] = "Tiragarde Sound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 47960, 47961, 47962 }, ["description"] = "We must convince Katherine Proudmoore to pledge Kul Tiras to the Alliance. Flynn believes the Ashvane Trading Company's new gunpowder is our best lead.", ["objectivesText"] = "Offer to investigate the Ashvane Trading Company.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 158065, 158066, 163032, 163034 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.731333, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 43, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 742, ["name"] = "Kul Tiras", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 9, ["flags"] = 0 } } },
[47961] = { ["id"] = 47961, ["name"] = "Drustvar", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "The stalwart protectors of House Waycrest hold fast along the western border, but recently all contact with them has been lost. We must secure their aid in order to bring Kul Tiras together under the Proudmoore banner.", ["objectivesText"] = "Offer to make contact with House Waycrest.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.731333, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2AdventureMapPoiID"] = 44, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 742, ["name"] = "Kul Tiras", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[47965] = { ["id"] = 47965, ["name"] = "The Ruined Temple", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47570, 47571, 47573, 47574, 47576, 47577, 47578, 47580, 47581, 47928, 47943, 47965 }, ["description"] = "The loa may be our only hope against the naga, but the temple lies abandoned and broken. Two of my tribe have gone ahead to scout the ruins. They may be able to help you make contact with Eraka no Kimbul. If the spirit of the loa remains at the temple, we must find a way for him to hear our plight.", ["objectivesText"] = "Speak with Teekcha .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123063, ["x"] = 0.615333, ["y"] = 0.205333 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134133, ["x"] = 0.585, ["y"] = 0.118 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.615333, ["y"] = 0.205333 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5429, ["name"] = "Kimbul's Wrath", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47968] = { ["id"] = 47968, ["name"] = "Signs and Portents", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "<The bulletin that Mayor White was posting at the time he was struck by the spell indicates that there have been some strange happenings in the town lately. It is likely these events are connected to whatever cast this spell on the village. Perhaps there might be records from other villagers that could shed some light on the source of this magic.>", ["objectivesText"] = "Investigate the villagers' writings in Fallhaven. Progress: <The town's ledger lists a record of the comings and goings of people and goods through the city of Fallhaven.>", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 179385 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 381, ["name"] = "Fallhaven", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 2, ["flags"] = 0 } } },
