[47978] = { ["id"] = 47978, ["name"] = "The Wayward Crone", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "<The ledger indicates that an old woman named Helena Gentle recently took up residence in a house down the road from the town. The villagers' writings point to her being involved somehow with a variety of maladies that struck the village recently. It's possible that she may know what's behind this spell, if it hasn't afflicted her as well.>", ["objectivesText"] = "Confront Helena Gentle in her home outside of Fallhaven.", ["rewardGold"] = 28090, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124922, ["x"] = 0.605, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 381, ["name"] = "Fallhaven", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[47979] = { ["id"] = 47979, ["name"] = "Witch Hunt", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "A curse on the villagers? Oh my, how dreadful! Although, to be honest, there have been some strange happenings around Fallhaven of late. I wonder if these could be culprit? Take a seat and have a spot of tea. I'll tell you all that I know.", ["objectivesText"] = "Listen to Helena Gentle 's story in the Shrouded Foothills.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 124922, ["x"] = 0.605, ["y"] = 0.316 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.316 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 381, ["name"] = "Fallhaven", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47980] = { ["id"] = 47980, ["name"] = "Furious Familiars", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47968, 47978, 47979, 47980, 47981, 47982, 48622 }, ["description"] = "<The wildlife in the foothills appear to be under Helena's spell, and this villager appears to be one of their victims. They must be the cause of the recent disappearances from Fallhaven. Perhaps if their numbers were cut down, they would pose less of a threat to the townspeople.>", ["objectivesText"] = "Kill 10 enthralled animals in the Shrouded Foothills.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125093, ["x"] = 0.608, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 381, ["name"] = "Fallhaven", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47981] = { ["id"] = 47981, ["name"] = "Cracking the Curse", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "<In her haste, it looks like Helena left her spellbook behind. The pages of this book detail the ritual that she used to entrap the villagers of Fallhaven. It seems the effigy holding the spell in the village is protected by smaller ones surrounding the town. If these are destroyed, you may be able to affect the one holding the spell on the townsfolk.>", ["objectivesText"] = "Destroy the 4 Lesser Effigies in the Shrouded Foothills.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 381, ["name"] = "Fallhaven", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 5, ["flags"] = 0 } } },
[47982] = { ["id"] = 47982, ["name"] = "The Final Effigy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "<The effigy's protection has been broken. All that remains is to break the effigy itself.>", ["objectivesText"] = "Destroy the Cursed Effigy in Fallhaven.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 155108, 155109, 155110, 155111, 155121, 155122, 155123, 155124 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124417, ["x"] = 0.558, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 381, ["name"] = "Fallhaven", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 6, ["flags"] = 0 } } },
[47986] = { ["id"] = 47986, ["name"] = "Scars of the Past", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "The Army of the Light's warframes have won countless battles on Argus. Despite their power, not all who descend into the fray return. My modifications to this frame should give us the edge we need, but several critical components are still missing. There are remains of battles past in Nath'raxas that we can still scavenge. If you can find the pieces I need, the Legion will feel our fury yet.", ["objectivesText"] = "Recover an Invocation Array , Vindicator Plating , and a Judgment Core . Progress: Do you have the components?", ["rewardGold"] = 232300, ["rewardXP"] = 6140, ["rewardItems"] = { 151837, 151838, 151839, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124975, ["x"] = 0.608, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124975, ["x"] = 0.608, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 4, ["flags"] = 0 } } },
[47990] = { ["id"] = 47990, ["name"] = "A Touch of Fel", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 47889, 47890, 47891, 47892, 47986, 47987, 47988, 47989, 47990, 47991, 47992, 47993, 47994 }, ["description"] = "Our warframe is almost operational! It just needs a good jolt to revitalize its systems. Warlocks in the pools below infuse pieces of Argus with fel energy to create living siege weapons. If you can extract one, we can use it to jumpstart the warframe's Judgment Core!", ["objectivesText"] = "Collect an Immaculate Felcore . Progress: Remember - immaculate!", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 151851, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 124975, ["x"] = 0.608, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 124975, ["x"] = 0.608, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 353, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["questLines"] = { { ["id"] = 353, ["name"] = "Nath'raxas Assault", ["orderIndex"] = 8, ["flags"] = 0 } } },
