[47998] = { ["id"] = 47998, ["name"] = "Killing Cannibals", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 47919, 47924, 47925, 47998 }, ["description"] = "Shoak and I have had a few run-ins with the Natha'vor trolls. Must be why they wanted to capture that idiot. The women in that tribe actually eat the men... and anyone else they can get their hands on. I'm sure they're getting ready to eat Shoak. Do us all a favor and kill some of those cannibals. The world would be a better place without them.", ["objectivesText"] = "Kill 10 Natha'vor Cannibals . Progress: Well? Did you take care of those cannibals?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 124933, ["x"] = 0.518, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 125024, ["x"] = 0.558, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5413, ["name"] = "A Bloody Meal", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48003] = { ["id"] = 48003, ["name"] = "The Lord's Behest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "Lord Norwington will want to thank you for saving his son himself. Why don't you come to the estate? We're preparing for a festival, and everybody's welcome. We'll go ahead and tell him of all that has happened. See you there!", ["objectivesText"] = "Meet Lord Aldrius Norwington at the Norwington Estate.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127144, ["x"] = 0.544, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 7, ["flags"] = 0 } } },
[48004] = { ["id"] = 48004, ["name"] = "Beginner Equitation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["series"] = { 48005 }, ["description"] = "You may know how to ride already, but you don't know how to ride like a Kul Tiran! We'll let you borrow a horse for the festivities. Take one of our lesson masters, Cooper . He's trained many a beginner in his day! Mount up, get in the ring, and show us what you've got! I'm sure you'll be a quick learner!", ["objectivesText"] = "Mount Cooper and practice your Kul Tiran riding skills. Progress: Kul Tiran riding is a true show of mastery and sport!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48005] = { ["id"] = 48005, ["name"] = "Be Our Guest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["series"] = { 48004 }, ["description"] = "My dear friend <name>, I do hope you enjoy the festival. I throw it every year to bring riders from all over Kul Tiras together for a grand celebration of the sport! In fact, you deserve the whole nine yards. Please, tour the estate at your leisure and partake in the delicious food and drink, introduce yourself to the people. I insist!", ["objectivesText"] = "Tour the estate and partake in the festivities. Progress: Have you taken your tour yet? Take a break from adventuring and relax!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 2562, 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357, 211279, 237812 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48008] = { ["id"] = 48008, ["name"] = "Dangerous Cargo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "By the time I realized what was happening, it was too late. People had been acting strange, but I thought nothing of it. After all, they seemed to still be doing their jobs. While inspecting some of the cargo, this grub jumped out in an attempt to latch onto my face. I managed to take it out, but it was too late. All of the shipments are infected. Take this torch. Destroy them.", ["objectivesText"] = "Burn 5 Infested Cargo . Progress: If I had only noticed sooner, perhaps some of this could be avoided.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125962, ["x"] = 0.376, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125962, ["x"] = 0.376, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 11, ["flags"] = 0 } } },
[48009] = { ["id"] = 48009, ["name"] = "Betrayal of the Guard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "My boys have gotten in too deep. They've given in to whatever dark forces are at work here. Do not hesitate to do what you need to and put them down. They knew what they were signing up for when they picked the wrong side.", ["objectivesText"] = "Kill 10 Mind-Addled Enforcers.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126308, ["x"] = 0.3915, ["y"] = 0.267 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126308, ["x"] = 0.3915, ["y"] = 0.267 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 10, ["flags"] = 0 } } },
[48014] = { ["id"] = 48014, ["name"] = "Clear the Riffraff", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 48014, 48015, 48025, 48026, 49969, 51538 }, ["description"] = "The naga sent their tiny, foul, muck-smelling minions into our camp. They are quite bothersome. If we do nothing, and their numbers continue to grow, they could pose a threat. You look quick and handy. Could you perhaps expunge a few for us?", ["objectivesText"] = "Slay 6 Gilblins at the Scavenger's Strand.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 125047, ["x"] = 0.803, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 125039, ["x"] = 0.792, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.803, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5410, ["name"] = "The Sunken City", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48015] = { ["id"] = 48015, ["name"] = "The Scrolls of Gral", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 48014, 48015, 48025, 48026, 49969, 51538 }, ["series"] = { 49769 }, ["description"] = "These gilblins are ridiculous! They are like a swarm of angry bees, buzzing around. Hmm, maybe not bees. Bees are useful, and make honey, and don't steal things. They ransacked our scrolls. Most were unusable, but there were three that are quite... potent. It would be most unfortunate if those made it back to their masters, the naga. Please clean up their mess and bring back our scrolls.", ["objectivesText"] = "Collect the 3 Tortollan Scrolls. Progress: Ah, <race>. I was always fascinated by your native language.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151852, 151853, 151854, 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 125047, ["x"] = 0.803, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 125041, ["x"] = 0.792, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.803, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5410, ["name"] = "The Sunken City", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48023] = { ["id"] = 48023, ["name"] = "Orders Received", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 48023 }, ["description"] = "We need ta be knowin' who be leadin' da naga in snatchin' all dese cute frogs. Dey got chests around here dat have some kind of scroll dey be readin'. Da ladies be tellin' da men to remember dem orders. Get me some of dem scrolls so we can be seein' who be callin' da shots.", ["objectivesText"] = "Recover 5 Explicit Orders .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 151928 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48025] = { ["id"] = 48025, ["name"] = "Saving for Later", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 48014, 48015, 48025, 48026, 49969, 51538 }, ["description"] = "We need time to recover the artifacts from this place. Time the naga will not let us have. However, we do have a plan. We simply hide what we don't want them to find, and then come back in a decade or two. They will have forgotten about this place by then. Take this illusion scroll and use it to conceal the notable artifacts of power.", ["objectivesText"] = "Conceal the antiquities of Gral. Progress: How is that scroll working out?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151859, 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 125041, ["x"] = 0.792, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 125041, ["x"] = 0.792, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5410, ["name"] = "The Sunken City", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48026] = { ["id"] = 48026, ["name"] = "Beneath the Waves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 48014, 48015, 48025, 48026, 49969, 51538 }, ["series"] = { 51538 }, ["description"] = "Those witches dare! In my temple? Siavass is stretching past the realm of that which she can comprehend. There is a darkness seeking them, and they call to it! Her kind will become no more than a hollow tool to those who may answer. I feel it moving beneath us, around us. I feel it like a tremor through my being. There is a pressure there, it has a weight greater than that of the deepest ocean. We must stop them. They are not welcome here!", ["objectivesText"] = "Slay Summoner Siavass and the Whispering Horror .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 155308, 156871, 159765 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5410, ["name"] = "The Sunken City", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48070] = { ["id"] = 48070, ["name"] = "The Norwington Festival", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48070 }, ["series"] = { 48077, 51199 }, ["description"] = "To whomever receives this invitation, You are cordially invited to the 15th annual Norwington Equestrian and Hunt Festival! People of all walks of life from across Kul Tiras shall gather to delight in life's greatest competitions, equestrianism and hunting, while meeting those of like minds and fine tastes. Hunting events shall start first, led by Abbey Watkins in Foxhollow Woods. They shall be followed by equestrian events at the Norwington Estate. We hope to see you there posthaste!", ["objectivesText"] = "Meet Abbey Watkins at the edge of Foxhollow Woods.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125309, ["x"] = 0.554, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48077] = { ["id"] = 48077, ["name"] = "The Stoat Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["series"] = { 48070, 51199 }, ["description"] = "One of the greatest hunting sports amongst the nobles of Boralus is the stoat hunt. It is a sport of determination, patience, and skill. Do you think you can rise to the challenge? Stoats are agile, sneaky, and sharp. They're next to impossible to catch out in the forest, so the best way to find one is to find its burrow and scare it out. Find their burrows and bring back their pelts. Their fur is soft and much loved amongst the nobles.", ["objectivesText"] = "Collect 5 Soft Stoat Pelts from Faintstep Stoats. Progress: Have you collected enough stoat pelts?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357, 158246, 158247, 158248, 158249, 158276, 158277, 158278, 158279 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125309, ["x"] = 0.554, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125309, ["x"] = 0.554, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48080] = { ["id"] = 48080, ["name"] = "An Element of Danger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "These nobles really think killing weasels is the mark of a good hunter? Ha! It ain't hunting if there isn't a bit of danger involved. There are boars in these woods. That's more our speed out in the mountains! Why don't you kill some of those, then bring me their tusks as proof?", ["objectivesText"] = "Collect 8 Rugged Boar Tusks . Progress: Boars actually present some semblance of challenge to the hunter.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125398, ["x"] = 0.555, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125398, ["x"] = 0.555, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48087] = { ["id"] = 48087, ["name"] = "Equine Retrieval", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["series"] = { 48088 }, ["description"] = "I like the cut of your jib, friend! I'll tell you what. The rest of the partygoers should be arriving any time now. Would you do me the honor of retrieving my favorite horse from the estate on the hill? Imagine, our guests' first impression of you to be on the most regal horse in all of Tiragarde! Wondrous!", ["objectivesText"] = "Retrieve Lord Norwington's favorite horse Rose from his hilltop estate. Progress: <name>! The troggs have invaded!", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127559, ["x"] = 0.525, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 10, ["flags"] = 0 } } },
[48088] = { ["id"] = 48088, ["name"] = "No Party Like a Trogg Party", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["series"] = { 48087 }, ["description"] = "Troggs? At my party? My grandfather pushed them back to that cleft years ago to build this estate. To think that they would attack in such force after all these years? This is just what we needed to make this year's festival the greatest ever! Show us your heroism firsthand, <name>! Mount Cooper and defeat these troggs! Drag them behind you, jab them with your harpoon... whatever it takes!", ["objectivesText"] = "Kill 20 Grimestone troggs in Norwington Estate.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357, 155054, 155062, 155065, 155068, 155070, 155075, 155076, 158294, 158297 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127559, ["x"] = 0.525, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127559, ["x"] = 0.525, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 11, ["flags"] = 0 } } },
[48089] = { ["id"] = 48089, ["name"] = "Mountain Sounds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "Kul Tirans won't go down without a fight! Take this horn. We use it in the mountains to warn each other of danger and lead the charge into battle. Use it to rally our allies against the troggs!", ["objectivesText"] = "Use the Horn of the Mountain to rally 8 Kul Tirans. Progress: We are stronger together!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357, 252392 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125042, ["x"] = 0.521667, ["y"] = 0.280667 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125042, ["x"] = 0.521667, ["y"] = 0.280667 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.521667, ["y"] = 0.280667 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48090] = { ["id"] = 48090, ["name"] = "Krag'wa's Chosen", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48090 }, ["description"] = "Dis be a real mess, <name>. Da naga be drainin' da magic of Krag'wa's frogs ta feed demselves! Dere be three frogs, Krag'wa's champions, dat dey be torturin' as we speak. Take dis potion, it be returnin' da power of dem noble frogs. Dey deserve better dan bein' drained by dese snake bastards. I be stayin' here. Da naga got in some lucky hits on me. All me life, I wanted ta see Krag'wa, and I let meself get hurt by some naga!", ["objectivesText"] = "Rescue Krol'dra the Wise , Wok'grug the Clever , and Wag'shash the Bold .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 158071 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 125317, ["x"] = 0.776, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 125317, ["x"] = 0.776, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[48092] = { ["id"] = 48092, ["name"] = "Vengeance of the Frogs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48092 }, ["description"] = "Da naga here be led by a priestess, Zaldraxia. She be da one dat figured out how ta drain da frogs of their magic. Zaldraxia be stoppin' at nothin' ta drain every frog here. Do what I could not, and kill dis priestess. Show da naga dat Krag'wa ain't a loa ta be takin' lightly. I be prayin' ta Krag'wa for ya success.", ["objectivesText"] = "Defeat Priestess Zaldraxia .", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 125317, ["x"] = 0.776, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 125317, ["x"] = 0.776, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
