[48108] = { ["id"] = 48108, ["name"] = "The Waycrest Daughter", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "You seek House Waycrest? Oh, your timing could not be worse! I had just received a raven regarding Lord Waycrest's daughter, Lucille, shortly before this... curse came upon us. They apprehended her in Fletcher's Hollow and are taking her to trial. They say she is a witch, herself! If she's found guilty, she will surely hang! You must make haste to Hangman's Point. With what you've seen here, maybe you can convince them of her innocence.", ["objectivesText"] = "Meet with Constable Henry Framer at Hangman's Point in Drustvar .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 124417, ["x"] = 0.558, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125394, ["x"] = 0.7, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 7, ["flags"] = 0 } } },
[48109] = { ["id"] = 48109, ["name"] = "The Woods Have Eyes", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "The sooner I can return the lady Waycrest to Highroad Gate the better, but I will honor her wishes if we can assure her safety. There are dark things happening in these lands that you don't fully understand. If we must dally, then there are measures that need be taken. First, the wildlife here can serve as eyes to dark powers. Kill them.", ["objectivesText"] = "Kill 4 Watchful Ravens and 6 Darkmaw Prowlers in the Watchman's Wood. Progress: Has our foe been sufficiently blinded?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125385, ["x"] = 0.696, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125385, ["x"] = 0.696, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48110] = { ["id"] = 48110, ["name"] = "In Case of Ambush", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "There is more to worry about in these woods than simple beasts. Our enemy employs constructs of wicker and bone that can rip a man apart. Fortunately for us, these constructs are not very perceptive. Take these traps and set them up throughout the woods behind us. If our enemies do seek to ambush us here, at least these will slow their minions down.", ["objectivesText"] = "Place 6 traps in the Watcher's Wood. Progress: We must be prepared. Anywhere can harbor an ambush here.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125385, ["x"] = 0.696, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125385, ["x"] = 0.696, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 10, ["flags"] = 0 } } },
[48111] = { ["id"] = 48111, ["name"] = "Trial by Superstition", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "Witchcraft has long lived in the superstitions of the people here. It is only recently that some of these superstitions have become reality. According to tradition, one who is tried for witchcraft is allowed to choose the means by which they are tested from among the requests of her peers. The villagers here no doubt have some strange beliefs of what witches can and cannot do. Speak with them, and see what we can do to prove my innocence.", ["objectivesText"] = "Question 5 Fletcher's Hollow Villagers in Hangman's Point. Progress: What have you learned from the villagers?", ["rewardGold"] = 147500, ["rewardXP"] = 1385, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 11, ["flags"] = 0 } } },
[48113] = { ["id"] = 48113, ["name"] = "A Pungent Solution", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "The first test should be simple enough. While I may not do so often, I am certainly capable of crying. Though to be honest, I've never had to cry on cue. Maybe you could help with that, though. Nearby there is an onion field that belonged to one of the local farmers. It's abandoned, and most of it is dried up by now, but you might be able to find one onion ripe enough in there to cause some tears.", ["objectivesText"] = "Collect a Juicy Onion from Hawthorne's Plot near Hangman's Point. Progress: Have you had any luck at the onion field?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48165] = { ["id"] = 48165, ["name"] = "Harmful If Swallowed", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "This last test I am not looking forward to, but it is certainly better than being set on fire. They say that a witch can't get sick. We will prove to them that I can. A venom comes from the saurolisks nearby that is used by our healers when a child swallows something they shouldn't. When ingested, it will make you immediately ill, emptying the contents of the stomach. You'll need several of their venom glands to get enough venom for an appropriate dose. Removing them intact may prove difficult.", ["objectivesText"] = "Collect 5 Intact Venom Glands from the Shallows Saurolisks near Hangman's Point. Progress: Is the deed done?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 14, ["flags"] = 0 } } },
[48170] = { ["id"] = 48170, ["name"] = "Once Bitten, Twice Shy", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "I am all too familiar with the bloodfly's bite. We had them all over the fields surrounding Waycrest Manor. Though I'm loath to subject myself to them on purpose, if it will help convince these people, I am willing to deal with that nuisance. Find a jar and collect as many bloodflies as you can. They are common in these parts, and shouldn't be hard to find.", ["objectivesText"] = "Find an Empty Jar and use it to catch 6 Hovering Bloodflies near Hangman's Point.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 13, ["flags"] = 0 } } },
[48171] = { ["id"] = 48171, ["name"] = "The Curse of Fletcher's Hollow", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "It's obvious the constable won't be swayed until we discover what happened at Fletcher's Hollow. I know very little myself--only that the village has been overrun by monstrous creatures. I must ask that you travel there in my stead and try to uncover what befell the village. I'm sure Marshal Reade will prevent the constable from harming me while you're away. Do this for me, and I will help you as I can.", ["objectivesText"] = "Speak with Evelyn Pare at the Timbered Strand in Drustvar .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 152587, 152590 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 17, ["flags"] = 0 } } },
[48176] = { ["id"] = 48176, ["name"] = "Big Trouble in Little Tortolla", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 48176 }, ["series"] = { 46846 }, ["description"] = "I received a message asking for a sword hand in Little Tortolla. The Tortollan Seekers there are greatly admired by King Rastakhan and have special privileges assigned to them. Go see what they want and you will have the favor of the King. And $p, be respectful. Tortollans live long enough they can hold your children's children accountable for your actions.", ["objectivesText"] = "Speak with Toki in Little Tortolla.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48179] = { ["id"] = 48179, ["name"] = "Rescue Rangers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48179, 48180, 48182, 48183, 52074, 52075, 53110 }, ["description"] = "We're barely holding off those monsters here. If it hadn't been for the Thornspeakers, we'd surely be dead. I was worried Rebecca hadn't made it! You've brought Rebecca's supplies just in time. We have many injured out in the field, Thornspeaker, ranger, and companion alike. I'll hold the line here. Go into the ruins and heal as many of the wounded as you can!", ["objectivesText"] = "Save 10 injured Thornspeakers , rangers, and pets.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 155466, 155474, 155482, 155490, 158607, 158608, 158609, 158610 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139912, ["x"] = 0.618, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139912, ["x"] = 0.618, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5441, ["name"] = "Drustvar Ruins", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48180] = { ["id"] = 48180, ["name"] = "Really Big Problem", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48179, 48180, 48182, 48183, 52074, 52075, 53110 }, ["description"] = "Hey! Mainlander! I know I'm supposed to be trying to knock over cairns and hauling out lost rangers, but d'you see that massive stone monster? I'm thinking that's gonna be a problem. You look like you know how to handle yourself. Think between the two of us we can take it down?", ["objectivesText"] = "Defeat the Ancient Sentinel .", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 140048, ["x"] = 0.596, ["y"] = 0.619333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.619333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5441, ["name"] = "Drustvar Ruins", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48181] = { ["id"] = 48181, ["name"] = "Nooooope", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48181 }, ["objectivesText"] = "Kill spiders and egg sacs", ["rewardGold"] = 4000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Kill spiders and egg sacs", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896 },
[48182] = { ["id"] = 48182, ["name"] = "Total Cairnage", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48179, 48180, 48182, 48183, 52074, 52075, 53110 }, ["description"] = "My mentor sensed the activation of ancient powers here. We came to stop them but were too late. We banded together with the rangers for mutual protection, but our task remains unfinished. There is a set of ancient cairns here. These help empower the Drust constructs. Destroying them will also help to settle the undead stirring from the land. Destroy the cairns and we'll be able to bring sanity to this place.", ["objectivesText"] = "Destroy the Ancient Cairns. Progress: Power within those cairns does not bode well for anyone in Drustvar .", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5441, ["name"] = "Drustvar Ruins", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48183] = { ["id"] = 48183, ["name"] = "The Hills Are Alive", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48179, 48180, 48182, 48183, 52074, 52075, 53110 }, ["description"] = "The Drust constructs are drawn from the land, but the heart of these constructs is a runic power core . We have been trying to collect and destroy as many of these cores as we can. We know of a way to disrupt the magic in the core. Doing so will prevent more of these monstrosities from being created around the dark hearts and protect the land and all living in this region. Bring me as many Runic Power Cores as you can find and the Thornspeakers will see they are put to good use.", ["objectivesText"] = "Collect 6 Runic Power Cores from Awoken Guardians. Progress: We would appreciate any runic power cores from the Awoken Guardians you might find.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152394 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5441, ["name"] = "Drustvar Ruins", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48184] = { ["id"] = 48184, ["name"] = "Pieces of History", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48184, 48504, 48517, 49890, 49896 }, ["description"] = "There is an opportunity here. Learning more about the Drust can not only help us understand the texts that Lady Lucille found, we might be able to discover greater details about how they and their constructs were finally defeated. Filling in the gaps of history could be key to victory now. This was one of their settlements before it became the place of their final defeat. Let's look for clues in the ruins.", ["objectivesText"] = "Search the ruins for information about the Drust.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 129983, ["x"] = 0.402, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129983, ["x"] = 0.402, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 600, ["name"] = "Gol Osigr", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48195] = { ["id"] = 48195, ["name"] = "Troublesome Troglodytes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "Troggs are base creatures. They barely have any brain process, living mostly on survival instinct alone. They are pests through and through, and need to be dealt with. The fewer of them there are, the better.", ["objectivesText"] = "Kill 8 Grimestone Bullies and 3 Grimestone Throwers in Mistfall Cleft.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127144, ["x"] = 0.544, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127144, ["x"] = 0.544, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48196] = { ["id"] = 48196, ["name"] = "Following Eddie's Trail", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "My life is equestrian. I'm not a fighter. I could maybe take a trogg or two, but not a whole tribe. Please, go into Mistfall Cleft and see if you can find Eddie. Lord Norwington would be furious if something happened to him, and nobody wants to bear witness to that!", ["objectivesText"] = "Follow the trail of Eddie Norwington . Progress: Are... are you here to save me?", ["rewardGold"] = 876300, ["rewardXP"] = 1770, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127144, ["x"] = 0.544, ["y"] = 0.194 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127091, ["x"] = 0.556, ["y"] = 0.145 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.194 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48198] = { ["id"] = 48198, ["name"] = "The Burden of Proof", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "I think we have everything we need to conduct three of the villagers' tests. Let us hope this is enough to convince them. I'm sure Constable Framer is champing at the bit to proceed with his trial, and I would prefer it if you were the one to administer the tests. I may not know you well, but I trust you farther than the constable. Speak with him when you're ready to begin. ...and do me a favor. Make this quick.", ["objectivesText"] = "Administer the tests to prove Lucy Waycrest's innocence in Hangman's Point.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 151934, 151935, 155100, 155101, 155102, 155103, 155570 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 15, ["flags"] = 0 } } },
[48231] = { ["id"] = 48231, ["name"] = "The Seat of the Triumvirate: Armor of the Triumvirate", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48231 }, ["description"] = "This reforged key will grant entry into the armory inside the Seat of the Triumvirate . Locked away inside is the Armor of the Triumvirate , crafted in the days before Sargeras brought ruin to our world. We cannot let this armor be stolen by the Void's forces. Once the armor is in your possession, please bring it to Archivist Ionaa . He has collected our most sacred relics in the cave just up the path. No doubt he would be very glad to receive it.", ["objectivesText"] = "Secure the Armor of the Light and bring it to Archivist Ionaa . Progress: Have you brought me something, <class>?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 152202, 152203, 152204, 152241, 152242, 152243, 152244, 152939, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 125246, ["x"] = 0.568, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125247, ["x"] = 0.562, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "dungeon" },
[48261] = { ["id"] = 48261, ["name"] = "The Power to Reforge", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48261 }, ["description"] = "I forged the key using a pristine argunite crystal. Unfortunately, the only ones remaining are used by the Army of the Light's defenses. Hmm... dendrite clusters might be an alternative. They were used by the elite of Eredath to power simple devices. If enough of the city ruins are still intact, I'd wager the fallen magi or the broken may still have some in their possession. Of course, I would need a great many clusters to reforge the key. It seems you have your work cut out for you.", ["objectivesText"] = "Obtain a stockpile of Dendrite Clusters . Progress: Were you able to find enough clusters?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 152200, 152204, 152241, 152242, 152243, 152244, 152937, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 125246, ["x"] = 0.568, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125246, ["x"] = 0.568, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "standard" },
[48271] = { ["id"] = 48271, ["name"] = "Recovering the Pieces", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 830, ["storyline"] = { 48271 }, ["description"] = "The fragment you found is only one part of the key. I fear the other pieces have fallen into the hands of these ethereal beings you speak of... the Shadowguard. We must recover them all. The Shadowguard leaders and lieutenants in and around the Seat of the Triumvirate may well have the fragments in their possession. Get those key fragments, <name>... any way you have to.", ["objectivesText"] = "Secure the missing key fragments from the ethereals around the Seat of the Triumvirate. Progress: Did you find all the fragments?", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 140394, 152098, 152201, 152204, 152241, 152242, 152243, 152244, 152938, 237812 }, ["starts"] = { { ["mapID"] = 830, ["npcID"] = 125246, ["x"] = 0.568, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 830, ["npcID"] = 125246, ["x"] = 0.568, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 830, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 830 }, ["zone"] = { 8574 } }, ["questType"] = "group" },
[48283] = { ["id"] = 48283, ["name"] = "Standing Accused", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "So you wish to speak with the accused? I see no reason why not. Be quick about it, though. I will not have our trial delayed. This woman will answer for the fate of our village!", ["objectivesText"] = "Speak with Lucy Waycrest in Hangman's Point. Progress: What is your business here, mainlander?", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 151934, 151935 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125394, ["x"] = 0.7, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125385, ["x"] = 0.696, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48286] = { ["id"] = 48286, ["name"] = "Crystal Methods", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 830, ["storyline"] = { 48286 }, ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 129749 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 830, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[48313] = { ["id"] = 48313, ["name"] = "Nature's Remedy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47716, 48313, 48314, 48315, 48896, 50539, 50561, 50770 }, ["description"] = "Your friend doesn't have much time left. The scorpid venom is likely rotting his veins right now. He will certainly meet death without a cure. I will help. The first ingredient I'll need is the root of the prickly plum cactus . Its natural healing properties will make a suitable base for the salve.", ["objectivesText"] = "Harvest 6 Prickly Plum in Zul'Ahjin. Progress: Do you have the prickly plum for the salve?", ["rewardGold"] = 105000, ["rewardXP"] = 4115, ["rewardItems"] = { 152393 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135154, ["x"] = 0.47, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135154, ["x"] = 0.47, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 608, ["name"] = "A City of Secrets", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 37, ["flags"] = 0 } } },
[48314] = { ["id"] = 48314, ["name"] = "Creeping Death", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47716, 48313, 48314, 48315, 48896, 50539, 50561, 50770 }, ["description"] = "Scorposhi venom usually induces a slow, creeping death. It's remarkable that your friend has survived this long. As with most antivenoms, the thing that kills is also the thing that heals. I'll need to extract the venom from several scorpashi stingers to craft the cure. When the extracted poison is mixed with cactus root salve, we will have the antivenom we need to treat his wounds.", ["objectivesText"] = "Collect 7 Scorpashi Stingers in Zul'Ahjin. Progress: Do you have the scorpashi stingers ?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 152397 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135154, ["x"] = 0.47, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135154, ["x"] = 0.47, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 608, ["name"] = "A City of Secrets", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 36, ["flags"] = 0 } } },
[48315] = { ["id"] = 48315, ["name"] = "Hollow, Empty Eyes", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47716, 48313, 48314, 48315, 48896, 50539, 50561, 50770 }, ["description"] = "<Carved into the ancient statue are two eye sockets that look like they once held gems. Perhaps the missing gems can be found within the ruins?>", ["objectivesText"] = "Find the statue's missing gems. Progress: <Carved into the ancient statue are two eye sockets that look like they once held gems.>", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 157864 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 608, ["name"] = "A City of Secrets", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 40, ["flags"] = 0 } } },
[48317] = { ["id"] = 48317, ["name"] = "A Nose for Magic", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47228, 47235, 47329, 48317, 48399, 48400, 50043 }, ["description"] = "I have it! The readings from the ruins are unmistakable. Somewhere to the south and west of the ah... \"foot\", as it were, is a source of great magical energy. It can be nothing but the Eye of Xibala! We will need to place a few more scrying vessels to pinpoint the Eye's exact location. Meet me deeper in the ruins. I will personally oversee this effort.", ["objectivesText"] = "Meet Apprentice Telemancer Astrandis in western Xibala and aid him in his search for the Eye of Xibala.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.413333, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5403, ["name"] = "Fossil Extraction", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48320] = { ["id"] = 48320, ["name"] = "The Best Kill is Overkill", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "I watched you kill those Sandfury earlier, $p. You have blood instinct. I like dat. I bet de others have you hunting frivolous luxuries for de inn. I'll give you an assignment worth your talents. Dis oasis is full of dangerous beasts dat'll scare away guests and harrass my pterrordaxes flying in and out. Kill dem. Once de skies are clear, my pterrordaxes can fly you wherever you want.", ["objectivesText"] = "Kill 15 predators in the Whistlebloom Oasis. Progress: Are de skies clear?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123729, ["x"] = 0.431, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123729, ["x"] = 0.431, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.431, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48321] = { ["id"] = 48321, ["name"] = "Creative Marketing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "De Goldtusk Gang is de best gang in all of Zandalar. I know dat. You know dat. Everyone in de gang knows dat. But we need to make sure dat everyone who sees our inn knows dat too. We need something big... Something like a massive gold tusk! I don't know where we'd find one of those, but I got a plan. Dere's a huge saurolisk in de oasis. Bring me one of its giant bones and I'll take care of de rest.", ["objectivesText"] = "Collect Bloodcrest's Giant Rib in the Whistlebloom Oasis. Progress: If dis doesn't work, we can always be de Bloody Rib Gang.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 153593, 160009, 160010, 160011, 160012, 160021, 160022, 160023, 160024 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 123730, ["x"] = 0.433333, ["y"] = 0.602667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123730, ["x"] = 0.433333, ["y"] = 0.602667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.433333, ["y"] = 0.602667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 11, ["flags"] = 0 } } },
[48322] = { ["id"] = 48322, ["name"] = "A Goldtusk Greeting", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["series"] = { 48335, 48840, 49001 }, ["description"] = "Thanks to you, de Goldtusk Inn has never looked better! We got food, we got beds, we got piles of dead Sandfury nearby. Dis is everything I ever dreamed it be! < Rhan'ka looks out into the oasis.> You hear dat? Sound like we got our first guest of de day! Why don't you greet dis one? Show 'em all de great amenities ya built here!", ["objectivesText"] = "Greet the approaching guest and show them around the Goldtusk Inn. Progress: Our first guest of de day. So exciting! Don't kill 'em!", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48324] = { ["id"] = 48324, ["name"] = "Lost in Zem'lan", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 51775 }, ["description"] = "Legends say that a mountain of treasure sits deep inside the Port of Zem'lan, pillaged from every corner of Azeroth. But it's guarded by unkillable, eternal monsters. No vulpera or exile has ever stolen treasure from the Port of Zem'lan and made it out alive. My caravan was going to be the first. Our scout, Meeki snuck in to figure out a route, but he never came back. It would be wisest for you to leave here and never return. But, if you go into the port, please find Meeki .", ["objectivesText"] = "Find Meeki .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 125904, ["x"] = 0.388, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136287, ["x"] = 0.354, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48326] = { ["id"] = 48326, ["name"] = "This Be Mutiny", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 51060, 51061, 51062 }, ["description"] = "It be time to face Pirate-King Zem'lan and bring dis mutiny to bear, $p. Zem'lan keeps a gong at de top of his treasure isle dat any crew member can ring to challenge him to a fight. I only ever seen one lass brave enough to ring it, and it didn't end well for her. But you and me, we be de scourge of de seven seas, aye? Even mighty Zem'lan be no match for de two of us together. Ring de gong, and let's make Zem'lan pay for cursin' his crew and treatin' us like dogs. Mutiny or de yard arm!", ["objectivesText"] = "Ring the Gong of Zem'lan and kill Pirate-King Zem'lan .", ["rewardGold"] = 929400, ["rewardXP"] = 6175, ["rewardItems"] = { 160013, 160014, 160015, 160016, 161172, 161173, 161174, 161175 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136779, ["x"] = 0.312, ["y"] = 0.849333 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.849333 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48327] = { ["id"] = 48327, ["name"] = "A Strange Delivery", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 47497 }, ["description"] = "The last time our caravan rolled through the Whistlebloom Oasis, we found an odd Zandalari living in a cave. We traded a few things and he paid me upfront to bring him a pineapple. I don't know why. It took me a long time to find one, but a vulpera holds up her end of the trade. I was planning to stop by and drop it off after we finished here. But, thanks to your help, we've got a lot more treasure hunting to do here at the port. If you have time, would you deliver it for me?", ["objectivesText"] = "Deliver the pineapple to Rhan'ka in the Whistlebloom Oasis. Provided item:", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 159677 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 125904, ["x"] = 0.388, ["y"] = 0.772 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 14, ["flags"] = 0 } } },
[48329] = { ["id"] = 48329, ["name"] = "Beaten But Not Broken", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "<Beastbreaker Hakid's crystal-encrusted key looks like it will open the large cage nearby. The pterrordax inside that cage, Scion of Rakjan, is stronger than the other hatchlings you've seen in the Crackling Ridge. He holds his head high and doesn't seem bothered by the myriad scars and fresh wounds that cover his body. If you release him, he'll likely want to return to Rakjan the Unbroken at the top peak of Crackling Ridge.>", ["objectivesText"] = "Free the Scion of Rakjan and lead him to Rakjan the Unbroken .", ["rewardGold"] = 514800, ["rewardXP"] = 4115, ["rewardItems"] = { 158909 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129763, ["x"] = 0.472, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 6, ["flags"] = 0 } }, ["startItems"] = { 158909 } },
[48330] = { ["id"] = 48330, ["name"] = "Zandalari Treasure Trove", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48330, 48331, 48332, 48334, 48335, 49001, 49139 }, ["series"] = { 48332, 49139 }, ["description"] = "We've looted some quality goods already, but the real reward is still ahead. The big chamber in the back of the ruins is filled with powerful artifacts. A treasure trove like that is the sort of thing that can save lives and sell for a fortune out here in Vol'dun . But those specters you killed weren't lying. Their master or king or whatever is very well-protected in there. We'll have to take this one down as a group. Let me know when you're ready to head up to the chamber.", ["objectivesText"] = "Kill Zak'rajan the Undying in his throne room. Progress: I'm glad you're with us on this one.", ["rewardGold"] = 210000, ["rewardXP"] = 5145, ["rewardItems"] = { 155421, 155423, 155427, 155430, 155431, 155432, 155433, 155438, 155445, 160028 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129451, ["x"] = 0.454, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129451, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5425, ["name"] = "Court of Zak'rajan", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48331] = { ["id"] = 48331, ["name"] = "Siphoning Souls", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48330, 48331, 48332, 48334, 48335, 49001, 49139 }, ["series"] = { 48334 }, ["description"] = "< Tacha rummages through her sack of scavenged supplies.> So these golems are powered by Zandalari souls? No problem... I've had to deal with that before... I've got just the tool for it. < Tacha pulls out an eerie Zandalari totem.> Here it is! Found this ol' soulcatcher totem in one of the southern ruins years ago. It's gotten us out of a few jams. Disable the golems and throw down this totem next to it. It'll siphon off the souls. Keep the totem. We'll need it later.", ["objectivesText"] = "Kill 5 Soul-Trapped Guardians and use the Soulcatcher Totem to siphon their souls from their corpse.", ["rewardGold"] = 619600, ["rewardXP"] = 4115, ["rewardItems"] = { 154051 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129450, ["x"] = 0.454, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129450, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5425, ["name"] = "Court of Zak'rajan", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48332] = { ["id"] = 48332, ["name"] = "Ranishu Are Resources", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48330, 48331, 48332, 48334, 48335, 49001, 49139 }, ["series"] = { 48330, 49139 }, ["description"] = "We can't afford to waste resources out here. Over time, we've learned to take anything that looks even remotely useful, and be creative using what we have. I've turned a skull into a boat and a sethrak into a tent flap. I can't spit dust when it comes to magic, but I can mix poisons and potions with the best of 'em. Ranishu stomach acid makes wicked poison, but it's nasty to collect. Don't try to bottle it. Just bring me their stomachs whole and intact. No leaks!", ["objectivesText"] = "Collect 25 Intact Ranishu Stomachs . Progress: It looks like you've still got all your fingers. That's good.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 154713 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129451, ["x"] = 0.454, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129451, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5425, ["name"] = "Court of Zak'rajan", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48334] = { ["id"] = 48334, ["name"] = "They've Got Golems", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48330, 48331, 48332, 48334, 48335, 49001, 49139 }, ["series"] = { 48331 }, ["description"] = "I've sacked countless ruins across Vol'dun . Everything from saurolisk-infested dens to the cursed Port of Zem'lan. I don't say this to brag. I want you to understand that I know what I'm doing. I've survived this long because I take my time, avoid risks, and only take what I need. That's what we'll be doing here today. Omi reported heavy golem activity on her first scouting trip into the ruins. Zandalari golems are formidable. We need to learn what's powering them before we head in.", ["objectivesText"] = "Find a Malfunctioning Golem and discover its power source. Progress: Did you discover the golems' power source?", ["rewardGold"] = 619600, ["rewardXP"] = 4115, ["rewardItems"] = { 159977, 161181 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129450, ["x"] = 0.454, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129450, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5425, ["name"] = "Court of Zak'rajan", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48335] = { ["id"] = 48335, ["name"] = "The Strongest Rope in Vol'dun", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48330, 48331, 48332, 48334, 48335, 49001, 49139 }, ["series"] = { 48322, 48840, 49001 }, ["description"] = "You ever tried tying up a sethrak with vulture string? Won't hold 'em for long. When you really gotta keep something, or someone, tied down, you need sandspinner silk . Thick, pliable, and not as sticky as you'd think. This isn't a tailoring lesson. Omi's scouting report showed a lot of sandspinners inside the ruin courtyard. Get their silk and bring it back to me.", ["objectivesText"] = "Collect 6 Sandspinner Silks . Progress: Don't even bother trying to tear it. You can't do it.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 153699 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129453, ["x"] = 0.454, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129453, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5425, ["name"] = "Court of Zak'rajan", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48347] = { ["id"] = 48347, ["name"] = "Anglepoint Wharf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["series"] = { 48540 }, ["description"] = "HELP WANTED . An unidentified illness has cropped up in Anglepoint Wharf. Those experienced with medicine or healing should report to the Therold Wavestone at their earliest convenience. Citizens are advised against visiting Anglepoint on personal business until further notice. Thank you for your cooperation.", ["objectivesText"] = "Meet Brother Therold at Anglepoint Wharf.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 19, ["flags"] = 0 } } },
[48348] = { ["id"] = 48348, ["name"] = "Stinging Barbs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "The Outrigger hunters exhibit the pinnacle of Kul Tiran brawn. But they would indubitably be unable to succeed in taking down the most impressive of their prey without my own inventions! I present to you, the most ordinary of harpoons. However, with just a tad of gnomish ingenuity, this average weapon can become so much more! All that I need are barbs from the rays in the harbor. Using them, I can fashion a poison that can stun even the most colossal of sea monsters!", ["objectivesText"] = "Collect 4 Venomous Barbs from Barbtail Stingrays. Progress: Be careful with those stingers, <name>! They'd put someone of your frame down easily!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128680, ["x"] = 0.375333, ["y"] = 0.261333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128680, ["x"] = 0.375333, ["y"] = 0.261333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.375333, ["y"] = 0.261333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48352] = { ["id"] = 48352, ["name"] = "A Cure from the Sea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["series"] = { 49292 }, ["description"] = "You may not believe it, but seaweed is one of the most important gifts the sea grants to us. Without it, my tonic shall be useless. I know it is much to ask, but can you go into the harbor and collect some for me? The water is tumultuous in this trying time, but I will give you my blessing.", ["objectivesText"] = "Collect 8 Bunches of Seaweed from Harbor Seaweed. Progress: The sea cannot offer its guidance when it is in such pain. I feel as if one of my senses is blinded.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513, 158258, 158259, 158260, 158261, 160097, 160098, 160099, 160100 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48353] = { ["id"] = 48353, ["name"] = "Pulse of the Wharf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "I am at a loss for ideas, <name>. The tides churn, and I can feel their pain as if it is my own. While I am out of ideas, perhaps the merchants in town may have seen something? They are always watching and gossiping, making them quite good sources of information.", ["objectivesText"] = "Talk to Julian Nichols , Ginger Freelin , and Aaron Gutier in Anglepoint Wharf.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48354] = { ["id"] = 48354, ["name"] = "Tainted Shipments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "If one shipment was compromised, who knows how many of the others are. Nearby, the fishpackers prepare shipments to be sent to the rest of Kul Tiras. We must check the rest of the shipments before this plague can spread!", ["objectivesText"] = "Check 5 Barrels of Fish.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48355] = { ["id"] = 48355, ["name"] = "Evacuate the Premises", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "The people of Anglepoint need me to stand tall, to not panic in the face of the unknown. I will admit to not being the best at this. Even now, the fishpackers are handling the tainted product and preparing it for shipment. They are in great danger, and we cannot allow them to stay in harm's way. We must get them to safety!", ["objectivesText"] = "Evacuate 8 Anglepoint Fishpackers .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 7, ["flags"] = 0 } } },
[48356] = { ["id"] = 48356, ["name"] = "Possessive Headgear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "It is fortunate that we have found Alby. He has filled me in on the situation in the packing district. It's not good, <name>. The workers walk, yes. They work as if nothing is out of the ordinary, yet they are controlled by parasites. Mindstealers that force them to do their bidding. It is they who contaminate the shipments. You must destroy as many of those mindstealers as you can. Free the minds of the possessed!", ["objectivesText"] = "Kill 10 Parasitic Mindstealers controlling Possessed Dockworkers in the Anglepoint Packing District. Progress: Our priority is saving our people. We must do whatever we can.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48365] = { ["id"] = 48365, ["name"] = "The Young Lord Stormsong", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "When the town fell, I got separated from my charge. Lord Stormsong is being held hostage in his own house. I should've been there to protect him. When you go in there, succeed where I failed. Bring him back safely.", ["objectivesText"] = "Kill Brother Conway , then rescue Lord Brannon Stormsong from Anglepoint Packing District.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126308, ["x"] = 0.3915, ["y"] = 0.267 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126308, ["x"] = 0.3915, ["y"] = 0.267 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48366] = { ["id"] = 48366, ["name"] = "Paddle to Safety", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "Perhaps... perhaps I can still help my people. I overheard conversations between the foreman and his men. It sounds as if the source of this corruption comes from the deeper waters, where the Stormriggers do their monster hunting. Please, assist me in investigating this. I can still redeem myself and this operation.", ["objectivesText"] = "Use the Escape Rowboat to travel to Outrigger Post. Progress: I can't sit idly by anymore.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126298, ["x"] = 0.3915, ["y"] = 0.267 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126298, ["x"] = 0.3915, ["y"] = 0.267 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 13, ["flags"] = 0 } } },
[48367] = { ["id"] = 48367, ["name"] = "Those Aren't Fish Eggs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "Corruption has seeped into the sea. Part of our job is to keep the monsters of these parts under control. A cruel magic has taken over many of the beasts. I take the challenge of the hunt with pride, but too many and we are overrun! Monster eggs are scattered across the breeding grounds, pulsing with a dark energy. Get your stompin' boots on.", ["objectivesText"] = "Break 30 Corrupted Eggs in Krakenbane Cove. Progress: Ah, the satisfying squish of a monster egg under your boot. What a feeling!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128679, ["x"] = 0.386, ["y"] = 0.268 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128679, ["x"] = 0.386, ["y"] = 0.268 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 14, ["flags"] = 0 } } },
[48368] = { ["id"] = 48368, ["name"] = "Deep Sea Defilement", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "The sea... I understand its screams now. It is as if a veil has been lifted, revealing the chaos that has taken hold. Corrupting such a vast swath of sea cannot be done with simple spells. The cultists must have erected some sort of structures to channel their dark magics through... You must find and destroy them, <name>. Only then can we hope to restore the waters to balance.", ["objectivesText"] = "Destroy the three Corrupting Pylons in the underwater caves in Krakenbane Cove. Progress: My mind is bursting with the tide's cries. It is almost too much to bear.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 133755, 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 15, ["flags"] = 0 } } },
[48369] = { ["id"] = 48369, ["name"] = "Emergent Strategy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["description"] = "My son went where? Chasing our workers into the woods once again? That boy is too soft-hearted. No matter what I do, he will never be strong enough to take over the family business. I demand he come back this instant. He's got better ways to spend his time than going on wild goose chases for our employees!", ["objectivesText"] = "Find Benjamin Algerson near Fernwood Ridge.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.689333, ["y"] = 0.180667 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48370] = { ["id"] = 48370, ["name"] = "Death in the Depths", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "My own people have fallen to the mad whispers of the voices of the deep, deep sea. Cultists inhabit caves in the ocean, spreading hysteria deeper and deeper into Tiragarde with their mad rituals. We must put an end to them, <name>, before they get even more out of hand.", ["objectivesText"] = "Kill 8 Deepwarden Followers in Krakenbane Cove.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126308, ["x"] = 0.3915, ["y"] = 0.267 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126298, ["x"] = 0.3915, ["y"] = 0.267 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 16, ["flags"] = 0 } } },
[48372] = { ["id"] = 48372, ["name"] = "Eldritch Invocations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "This is my fault, my friend. The leader of these cultists is none other than Director Deepwarden , a man who I once trusted as an advisor and business partner. It seems he did not approve of how I ran our operation... to a ludicrous degree. He gave his humanity for power, using his frustration to overthrow the village from the inside. Who knows what he plans next. I can no longer stand idly by. Take out Deepwarden. Show him that Anglepoint will not fall to his madness.", ["objectivesText"] = "Kill Director Deepwarden in Krakenbane Cove.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126298, ["x"] = 0.3915, ["y"] = 0.267 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126298, ["x"] = 0.3915, ["y"] = 0.267 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 17, ["flags"] = 0 } } },
[48399] = { ["id"] = 48399, ["name"] = "A Dark (Iron) Tide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47228, 47235, 47329, 48317, 48399, 48400, 50043 }, ["description"] = "Their red eyes... flaming beards... dark, dusky skin. These can only be Dark Iron dwarves. I have never seen one before this day. It is my understanding that they have been sent here on an errand for the Alliance. Given my people's allegiance, I believe we are now placed in a position to better demonstrate our loyalty to the Horde. The Dark Iron must die. See that they do not claim so much as an inch more of this beach.", ["objectivesText"] = "Slay 7 Dark Iron dwarves.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.413333, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5403, ["name"] = "Fossil Extraction", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48400] = { ["id"] = 48400, ["name"] = "Grand Theft Telemancy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47228, 47235, 47329, 48317, 48399, 48400, 50043 }, ["description"] = "They must not keep the Eye, <name>. Fortunately I am more than an archaeologist. I am a telemancer. Chief Telemancer Oculeth himself trained the woman who trained my master. I can retrieve the relic with these arts. All you need to do is place a telemancy beacon near the Eye. I can then retrieve both it AND you safely back to camp. The Alliance will find themselves empty-handed. While you're at it, do deliver my \"thanks\" to the individual responsible for snatching the Eye out from under us.", ["objectivesText"] = "Slay Urda Direflame and then place a telemancy beacon near the Eye of Xibala. Progress: Did you find the source of the disruption?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 155310, 158419, 158420, 158421, 158422 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.413333, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5403, ["name"] = "Fossil Extraction", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48402] = { ["id"] = 48402, ["name"] = "A Poisonous Touch", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48402 }, ["description"] = "You... I saw you speak with Zentimo. Please, I don't have much time left... These trolls, they came for our blood. I was already nearly bled dry before this one succumbed to my poison. Search it's body, the blowgun and darts should still be there. Dip the darts into my blood and use them to weaken as many of their number as you can. I will not let my death be in vain! If these trolls want our blood so badly, then they shall have it!", ["objectivesText"] = "Use the blowgun to weaken 5 Bloodhunter trolls.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126039, ["x"] = 0.69, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 120551, ["x"] = 0.755, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[48404] = { ["id"] = 48404, ["name"] = "The Scamps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 48404 }, ["series"] = { 48405 }, ["description"] = "You there! You have legs and a need for money? I wish to hire you. Confounded, despicable, parentless children have been stealing my scrolls again. Those scrolls are dangerous in the wrong hands. What is worse, I believe these junior vagabonds to be organized. Find these street scamps and relieve them of their bounty, and I shall pay you for it.", ["objectivesText"] = "Stop 5 Street Scamps from stealing. Progress: The little rascals are crawling all over these accursed docks.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 125312, ["x"] = 0.56, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 125312, ["x"] = 0.56, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[48405] = { ["id"] = 48405, ["name"] = "Mista Nice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 48405 }, ["series"] = { 48404 }, ["description"] = "I am normally not a violent tortollan, but if there is one thing I cannot abide, it is a scoundrel using children for his own profit. The street scamps appear to be working at the behest of a ring leader. I do believe they call him \" Mista Nice \" though I suspect the name to be sarcastic in nature. I have a scroll here that can let you move among the scamps and see if they lead you back to Mista Nice . If they do, slay him and I shall pay you a bounty.", ["objectivesText"] = "Find and slay Mista Nice . Progress: Any luck finding that voice of corruption for the youth of tomorrow?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 125312, ["x"] = 0.56, ["y"] = 0.888 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 125312, ["x"] = 0.56, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.888 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[48419] = { ["id"] = 48419, ["name"] = "Lured and Allured", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["series"] = { 48505, 48539 }, ["description"] = "Lookin' for a friend from the wreck, eh? If he survived he may have wandered up the path to our camp. Now if he ain't up there toastin' his buns by the fire, well... lotta poor souls fall victim to the song of the sirens. You should check the camp before you go wadin' out into the tideway. Ask our leader, Stabby Jane . She'd know for sure if a new survivor showed up!", ["objectivesText"] = "Search for Flynn Fairwind .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128377, ["x"] = 0.8555, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126158, ["x"] = 0.882667, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.8555, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 19, ["flags"] = 0 } } },
[48421] = { ["id"] = 48421, ["name"] = "Blood in the Tides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48421, 49178, 49218, 49226, 49230 }, ["description"] = "Curse these slimy wenches! Their singin' sets men's hearts afire and their brains adrift. My ship's aground. My cargo's lost. Nothin' for it now but to fight!", ["objectivesText"] = "Slay 8 Wailing Sirens .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348, 155023, 155024, 155025, 155026, 155086 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125342, ["x"] = 0.859, ["y"] = 0.782 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125342, ["x"] = 0.859, ["y"] = 0.782 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.859, ["y"] = 0.782 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48435] = { ["id"] = 48435, ["name"] = "The Spiritwalkers", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 750, ["storyline"] = { 41764, 41799, 41800, 41815, 41840, 41841, 41882, 41884, 48066, 48067, 48079, 48185, 48190, 48403, 48433, 48434, 48435, 49756 }, ["series"] = { 41764, 41799, 41800, 41884, 48185, 48190, 48434 }, ["description"] = "Ebonhorn is in the care of Spiritwalker Graysky. A cure is proving elusive... he has asked for your help. Please speak with him at once, <name>. The spiritwalkers are the keepers of our past. I pray the answer lies somewhere in the ancient truths they hold.", ["objectivesText"] = "Speak with Spiritwalker Graysky at Thunder Totem in Highmountain.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 750, ["questLines"] = { { ["id"] = 377, ["name"] = "Allies of the Horde: Highmountain", ["orderIndex"] = 16, ["flags"] = 0 } } },
[48454] = { ["id"] = 48454, ["name"] = "Evidence of Evil", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 48454 }, ["series"] = { 48452 }, ["description"] = "Jakra'zet refused to patrol dis area. Yazma's spies did not warn us of de evil lurking beneath our city. And Zul did not foresee blood magics festering under our noses. These are serious allegations, and de evidence is in your hands. Present dem to Zolani , Blade of the King. She will know best their meaning and how best to present dem to de king.", ["objectivesText"] = "Speak with Zolani , Blade of the King.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 126148, ["x"] = 0.442, ["y"] = 0.82 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122915, ["x"] = 0.498, ["y"] = 0.465 }, { ["mapID"] = 1165, ["npcID"] = 135441, ["x"] = 0.496, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.82 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[48468] = { ["id"] = 48468, ["name"] = "Bwonsamdi's Deliverance", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48468, 48473, 48478, 48479, 48480 }, ["description"] = "We be havin' a task from Bwonsamdi, da loa a death, ta purge dis place of its undead. Dey be controlled by a monster called Kel'vax. Can ya help? Dere be zombies destroyin' Bwonsamdi's temple over dere, and we no have da strength ta fight 'em all. Take dis torch. Kill dem zombies, den burn them corpses with da torch. It should be deliverin' their souls ta Bwonsamdi. Ya do dat, and we be one step closer ta stoppin Kel'vax.", ["objectivesText"] = "Burn 10 defiled troll corpses with the cremation torch .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 153178 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126080, ["x"] = 0.39, ["y"] = 0.6 }, { ["mapID"] = 863, ["npcID"] = 130481, ["x"] = 0.39, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126080, ["x"] = 0.39, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5414, ["name"] = "Bwonswamdi", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48473] = { ["id"] = 48473, ["name"] = "Respecting the Rites", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48468, 48473, 48478, 48479, 48480 }, ["description"] = "If we be deliverin' Kel'vax's soul ta Bwonsamdi, we need ta be doin' it properly. We need ta be doin' two things. First, dere be torches remainin' around da temple nearby. Light dem with da torch I gave ya. Da torches used ta be our way ta show dat we be deliverin' a spirit ta Bwonsamdi. Kel'vax will be knowin' it be his time. Second, I be needin' special ritual powder dat be deep within da temple. It be da key ta stoppin' Kel'vax. Go now, I be prayin' Bwonsamdi be favorin' us.", ["objectivesText"] = "Light 5 Ritual Torches and recover Shinga Deathwalker 's Ritual Powder . Progress: Light dem torches and get da powder so we be gettin' Bwonsamdi's favor.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 157793 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 130481, ["x"] = 0.39, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126080, ["x"] = 0.39, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5414, ["name"] = "Bwonswamdi", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48474] = { ["id"] = 48474, ["name"] = "Crypt Keepers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48474 }, ["objectivesText"] = "Cemetery cleansed", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cemetery cleansed", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896 },
[48475] = { ["id"] = 48475, ["name"] = "Seeing Spirits", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48475 }, ["description"] = "The spirits in the cemetery are riled up! I'd ask 'em direct but I don't have any of the necessary salve I use to commune with the dead. My family's been making it for ages! The herbs and tools I use to make it are inside, but I can't get over there! Some of those spirits are beyond reason and attack me on sight! Why don't you go collect those herbs, make the salve with my tools, and ask one of the calmer spirits what's going on. Aaron Cresterly is a good spirit to look for.", ["objectivesText"] = "Collect Gravebloom , create and use salve, then find Aaron Cresterly . Progress: Stranger, lend me your aid! I am ensnared in a witch's foul magic and I do not know how much longer I can resist! Destroy the circle binding me!", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 152480 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126210, ["x"] = 0.625, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126225, ["x"] = 0.602, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[48476] = { ["id"] = 48476, ["name"] = "Split Party", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48476 }, ["description"] = "In life my compatriots and I were valiant champions as you are. In death we are potent souls to make the witch's accursed minions even more powerful. With your help I have resisted thus far, but this foul witch pulled brave Bridget from her justly won rest. She is now trapped in one of these macabre constructs. This witch intends to use Bridget to bring death upon the lands she was oathsworn to protect! Free Bridget Fairwater 's soul from the construct which entraps her!", ["objectivesText"] = "Free Bridget Fairwater 's soul.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126225, ["x"] = 0.602, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126240, ["x"] = 0.596, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[48477] = { ["id"] = 48477, ["name"] = "Looking For One More", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48477 }, ["description"] = "Our loathsome foe, 'Sister' Westwood, yet continues her work. After subjugating myself, she set her malicious sights on my companion, fair Mercy. Of us three, Mercy was most kind and possessing of uncommon inner strength, yet I fear for her. Corrupting such a soul would make for a fearsome creature, indeed. Stop the vile ritual before Mercy is taken. Allow the dead their rest. Slay Sister Westwood and free us from her grasp!", ["objectivesText"] = "Slay Sister Westwood .", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126240, ["x"] = 0.596, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126253, ["x"] = 0.595, ["y"] = 0.511 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[48478] = { ["id"] = 48478, ["name"] = "Kel'vax's Home", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48468, 48473, 48478, 48479, 48480 }, ["description"] = "Kel'vax's soul be bound ta three phylacteries, protected by his voodoo. Even if ya destroy him, he just be reformin' in dem. Me old power be returnin' after ya lit dem torches. I be able ta enchant dis powder dat allow ya ta go through Kel'vax's voodoo. Find dese phylacteries and bring 'em ta me. We gonna look Kel'vax in da eye when we destroy 'em. I should warn ya... dis powder might be messin' with ya head. Ya may have some... visions after ya use it. Be careful.", ["objectivesText"] = "Use Shinga Deathwalker 's Spirit Powder to take Kel'vax's Ancient, Repaired, and Pristine Phylacteries . Progress: We need dem phylacteries if we be havin' a chance ta destroy Kel'vax.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 152468, 154130, 154136, 154137, 155341, 155343, 155519, 155521, 158943, 158944, 158945, 158946 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126080, ["x"] = 0.39, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126080, ["x"] = 0.39, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5414, ["name"] = "Bwonswamdi", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48479] = { ["id"] = 48479, ["name"] = "Bones for Protection", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48468, 48473, 48478, 48479, 48480 }, ["description"] = "Kel'vax be havin' powerful voodoo on his side, da kind dat could kill ya instantly if ya not careful. I know how we can be stoppin' dis magic, but we need bones. Lots a them. We be lucky, Kel'vax be havin' a large skeleton army. I need ya ta be goin' out dere and collectin' their bones. Bring 'em ta me and I'll prepare 'em ta be used against his voodoo.", ["objectivesText"] = "Collect 40 Cursed Bones . Progress: Did ya get them bones? We need 'em if we gonna stop Kel'vax's voodoo.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 153346 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126079, ["x"] = 0.39, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126079, ["x"] = 0.39, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5414, ["name"] = "Bwonswamdi", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48480] = { ["id"] = 48480, ["name"] = "The Fall of Kel'vax", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48468, 48473, 48478, 48479, 48480 }, ["description"] = "We be ready ta kill Kel'vax and send his soul ta Bwonsamdi for judgment. Ya should know someting before ya go in. Kel'vax was our son. Dat be why Bwonsamdi chose us ta stop dis madness. I not be knowin' why Kel'vax chose ta forsake everyting we believed in centuries ago... but here we are. Even without his undead, Kel'vax be very powerful. Be prepared... dis be our shot to end him and find our rest.", ["objectivesText"] = "Defeat Kel'vax Deathwalker . Progress: Ya must destroy Kel'vax once and for all!", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126080, ["x"] = 0.39, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126080, ["x"] = 0.39, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5414, ["name"] = "Bwonswamdi", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48492] = { ["id"] = 48492, ["name"] = "Getting a Leg Up", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48492, 48496, 48497, 48498, 48499, 49479 }, ["series"] = { 49477 }, ["description"] = "I seem to be in a bit of a... predicament. My squad was scouting on behalf of Lady Sylvanas when we were ambushed by some snake men calling themselves \"sethrak\". As you can see, my legs have been separated from my body in the ambush. It's just a flesh wound, luckily. Care to help me get re-attached? Then we can get down to this business of vengeance against these sethrak.", ["objectivesText"] = "Recover Chadwick Paxton 's legs.", ["rewardGold"] = 25740, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126289, ["x"] = 0.285333, ["y"] = 0.436667 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.285333, ["y"] = 0.436667 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5418, ["name"] = "Cooking with Sethrak", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48496] = { ["id"] = 48496, ["name"] = "Reuniting the Company", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48492, 48496, 48497, 48498, 48499, 49479 }, ["description"] = "Right, then. First order of business, rescue the remnants of my company. These sethrak kept yelling about expanding their empire and conquering Azeroth as they attacked us. Lovely, really. They killed most of my company and took some hostages. I assume they're being told how grand the sethrak empire is. I'd like the remnants of my company back, if you please. I'll put in a good word with Lady Sylvanas, once this is all over. ...not that someone like you needs it.", ["objectivesText"] = "Rescue the remnants of Chadwick Paxton 's squad.", ["rewardGold"] = 289300, ["rewardXP"] = 2765, ["rewardItems"] = { 155340, 155342, 155520, 155522, 158947, 158948, 158949, 158950 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5418, ["name"] = "Cooking with Sethrak", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48497] = { ["id"] = 48497, ["name"] = "Show of Force", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48492, 48496, 48497, 48498, 48499, 49479 }, ["description"] = "These things called the sethrak think that we're easily handled. That's only because we were ambushed and not ready for a fight. Well, all right, perhaps we were easily handled. But that doesn't mean we won't strike back. Kill as many of those sethrak as you can. I don't know who they are or what they want, but I do know one thing. They signed their death warrants when they attacked my squad and cut me in half.", ["objectivesText"] = "Defeat 10 Sethrak.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5418, ["name"] = "Cooking with Sethrak", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48498] = { ["id"] = 48498, ["name"] = "No Mercy for Sithis", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48492, 48496, 48497, 48498, 48499, 49479 }, ["description"] = "Heh heh... thanks for the rescue! I could use your help in a little plan that I have. The commander of this place is a sethrak called Sithis. He's got this thing called a \" skycaller gem .\" Word is they're looking for some sort of shadow magic in Nazmir to try and really power this thing up. Heh heh... luckily, yours truly has her own shadow magic to do just that! Maybe you do, too. I don't keep up on what powers you keep getting. Get the gem from Sithis and we'll have some REAL fun afterwards.", ["objectivesText"] = "Recover the Skycaller Gem from Fangcaller Sithis. Progress: Do you have Ingrid's gem? Please tell me you do... she's been absolutely insufferable about it.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 154892 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126377, ["x"] = 0.265, ["y"] = 0.379 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.265, ["y"] = 0.379 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5418, ["name"] = "Cooking with Sethrak", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48499] = { ["id"] = 48499, ["name"] = "Return to Dust", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48492, 48496, 48497, 48498, 48499, 49479 }, ["description"] = "It appears the sethrak are quite serious about keeping this gem. I do wonder where they found it in the first place. Hrm... perhaps Lady Sylvanas would be interested in this as well. Something to ponder. Ingrid believes this gem can unleash lightning and shadow magic of, her words not mine, epic proportions. I do believe it would be best for everyone if you tested it out on the small sethrak army currently looking for us.", ["objectivesText"] = "Defeat 20 Enraged Sethrak with the Skycaller Gem . Progress: Would you please hurry and deal with the sethrak? I'd prefer to get everyone's bloodlust dealt with before heading out.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 87361, 87362, 87363, 87364, 87365, 87366, 87367, 87368, 87369, 153519, 211279 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5418, ["name"] = "Cooking with Sethrak", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48504] = { ["id"] = 48504, ["name"] = "Through the Old Roads", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48184, 48504, 48517, 49890, 49896 }, ["description"] = "Lady Waycrest has entrusted me with securing the town of Falconhurst and the services of Master Alchemist Ashton who lives there. However, I have found out no one has heard from Falconhurst in some time. The skies above the forest are impassable, so we must travel the old roads through Drust ruins in the mountains. A small capable party has a better chance to bypass the growing forces of the witches and to help secure Master Alchemist Ashton. To that end, I ask you to assist me.", ["objectivesText"] = "Meet with Inquisitor Cleardawn at Gol Osigr.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 135021, ["x"] = 0.37, ["y"] = 0.504667 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129983, ["x"] = 0.402, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.504667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 600, ["name"] = "Gol Osigr", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48505] = { ["id"] = 48505, ["name"] = "Lovesick and Lost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["series"] = { 48419, 48539 }, ["description"] = "Ugh. My head. My HEART. Feels like a good hangover and a bad breakup put together. On the bright side, I think I know where we are. And where that ship was headed. Freehold. It's a... free town. For, uh... free folk. The only rule is that there are no rules. Lotta guys with peg legs and eye patches and exotic pets. Catch my drift? There's a trail through the hills that'll take us there. Pretty sure I remember the way... Let's get moving. Gotta walk off that damn siren's witchery.", ["objectivesText"] = "Escort Flynn to Freehold.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126158, ["x"] = 0.882667, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.882667, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 20, ["flags"] = 0 } } },
[48515] = { ["id"] = 48515, ["name"] = "Silver Blades", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 48515 }, ["description"] = "<This drust warrior was felled by a silvered blade long ago. This blade is still good despite the ages. Perhaps these weapons could be brought into service of fighting the Drust once more.>", ["objectivesText"] = "Collect 6 Tarnished Blades from the Fallen Defenders.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 34334, 155906 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48516] = { ["id"] = 48516, ["name"] = "Toxic Community", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48516 }, ["description"] = "A traveler? Nobody uses this trail unless they got a death wish. The only thing more poisonous than the marrowflies are the saurolisks that eat 'em all day. That marrowfly toxin is what I'm here for. Y'see, I'm a purveyor of, uh... specialty goods. And my clients are just dyin' for more of my product. Heh. You bring me their stingers, I pay you. Simple as that. You can even find 'em in the saurolisks, if you don't mind gettin' your hands dirty.", ["objectivesText"] = "Gather 50 Toxic Stingers . Progress: You got them stingers?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126511, ["x"] = 0.828, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126511, ["x"] = 0.828, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48517] = { ["id"] = 48517, ["name"] = "Honorable Discharge", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48184, 48504, 48517, 49890, 49896 }, ["description"] = "Some of the spirits on the battlefield are too weary to go on. These were brave Kul Tirans. They have more than earned their rest but their sense of duty holds them here. Order the most weary spirits off the field of battle. Hopefully they will be convinced to rest.", ["objectivesText"] = "Dismiss 10 Weary Spirits from the battlefield.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 129983, ["x"] = 0.402, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 600, ["name"] = "Gol Osigr", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48518] = { ["id"] = 48518, ["name"] = "Save Who We Can", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "These things seem intent on capturing our people... but we're not quite sure what for. The ones in the town might be too tough to reach right now, but we might be able to save some of the woodsmen who work along the strand. Head to the lumber fields just east of here, and see if there's anyone still alive out there. We can shelter them here until we can arrange safe passage out of here.", ["objectivesText"] = "Rally 6 Frightened Woodsmen in the Timbered Strand.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152587, 152590 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 18, ["flags"] = 0 } } },
[48519] = { ["id"] = 48519, ["name"] = "Hope They Can't Swim", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "We've got a small boat docked right across the way there. If we can get these villagers safely on board, they should be able to make it to Fallhaven by river. You're a capable fighter, no doubt. Can I count on you to fend off any attackers while we get them to safety?", ["objectivesText"] = "Defend the villagers as they board the boat in the Timbered Strand. Progress: We can begin evacuating on your mark.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 152587, 152590, 155117, 155118, 155119, 155120, 155158 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 20, ["flags"] = 0 } } },
[48520] = { ["id"] = 48520, ["name"] = "The Three Sisters", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "If you're looking to absolve Miss Waycrest of this mess, you'll need to head into the town. Recently, I've seen some oddly dressed women among the creatures, who seem to be calling the shots. It's likely that they're the key to this whole nightmare, but we can't get in to question them. Their minions don't seem to slow you down, though. If you can get to them, you might be able to find some answers for the both of us. Be careful, though. They likely aren't very friendly.", ["objectivesText"] = "Confront Sister Ashwell , Sister Early , and Sister Mooring in Fletcher's Hollow.", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 152587, 152590 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 21, ["flags"] = 0 } } },
[48521] = { ["id"] = 48521, ["name"] = "Charming the Lifeless", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "<You've seen a charm like this in Fallhaven being used to control a wicker construct. If you can figure out how to use it, you may be able to take control of one of the coven's wicker constructs.>", ["objectivesText"] = "Test the Wicker Charm on Dormant Ravagers in Fletcher's Hollow until you successfully control one. Progress: What's this?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152587, 152590 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 22, ["flags"] = 0 } } },
[48522] = { ["id"] = 48522, ["name"] = "A Revealing Missive", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "<The strange woman possessed a letter from someone calling herself \"Matron Levae\" which appears to have orders to take the town of Fletcher's Hollow. This could be the evidence needed to absolve Lucille Waycrest. Mayor Pare should be interested in seeing this.>", ["objectivesText"] = "Return to Evelyn Pare .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 152587, 152590 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 23, ["flags"] = 0 } }, ["startItems"] = { 152587 } },
[48523] = { ["id"] = 48523, ["name"] = "The Murderous Matron", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "I know that you've got what you came for, but I need to ask you one more favor. This town won't be safe until this Matron Levae is taken care of. According to the letter, she must be holed up in that cave. None of our people have been able to enter it, but I know I've seen their constructs go in! This charm you found might be the key. If you can take control of one of these wicker men and send it after her, we might have a shot!", ["objectivesText"] = "Control the Dormant Ravager to defeat Matron Levae in the Elderstone Mine. Progress: Is she gone?", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 152587, 152590 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 24, ["flags"] = 0 } } },
[48524] = { ["id"] = 48524, ["name"] = "Culling the Coven", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48171, 48518, 48519, 48520, 48521, 48522, 48523, 48524, 48525, 48538, 49295 }, ["description"] = "If the mine really was their objective, I can only imagine they'd have even more forces in there. My men and I may be able to take care of the remnants out here, but if an even bigger force comes out of that mine, we're not going to stand a chance. While you're hunting down the matron with this wicker contraption, do you think you could... you know... soften them up a bit?", ["objectivesText"] = "Kill 25 of Matron Levae's minions in the Elderstone Mine.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152587, 152590 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48525] = { ["id"] = 48525, ["name"] = "Break Them to Splinters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48171, 48518, 48519, 48520, 48521, 48522, 48523, 48524, 48525, 48538, 49295 }, ["objectivesText"] = "Reclaim Fletcher's Hollow", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["rewardItems"] = { 152587, 152590 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Reclaim Fletcher's Hollow", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 7, ["flags"] = 0 } } },
[48527] = { ["id"] = 48527, ["name"] = "Ravenous Landsharks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "Warbeast Kraal is important to de empire. All de beasts dat haul our goods, carry our armies, and fight our wars are born and bred here. If you want Rastakhan's support, you had better impress us. I have some thoughts on where you can start. We have ourselves a diemetradon problem. Usually nothing to worry about, but dey had a big hatching dis year. Now dey're breaking into de pens and eating our eggs. Kill diemetradons, protect our beasts, and we will see about de rest.", ["objectivesText"] = "Kill 9 Ravenous Diemetradon. Progress: Were you able to kill any diemetradon?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 158387, 158388, 158389, 158390, 159764 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48529] = { ["id"] = 48529, ["name"] = "Hungry Mouths To Feed", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "We don't have much in de way of supplies right now. Mojambo and his gang will be back to finish us off, of dat I'm sure. But without food and supplies, dere will be none of us alive for dem to kill. Our cook is looking for someone to help gather supplies so we can feed de camp. Speak with him and see if you can find what he's looking for.", ["objectivesText"] = "Speak with Sezahjin .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126108, ["x"] = 0.436, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48530] = { ["id"] = 48530, ["name"] = "I Heard You Lost the Herd", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "Our herd of alpacas went missing dis morning. It may seem like we have more pressing matters to worry about, but de meat and milk de alpacas provide are essential to our survival. Those alpacas won't survive long on de dunes. Speak with Mugjabu and help him find de alpacas before it's too late!", ["objectivesText"] = "Speak with Mugjabu .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126085, ["x"] = 0.422, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48531] = { ["id"] = 48531, ["name"] = "Mystery Meat", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "Mojambo's gang may be coming to kill us, but we've still got to eat. And when you live in a harsh wasteland, you make do with what you've got. Sometimes fresh meat is hard to find. Dat's how I came up with de idea for my famous mystery meat pie. De secret ingredient is dung beetle, but with enough seasoning you can't even tell! Our food supplies are dangerously low right now. I need someone to go beetle hunting as soon as possible!", ["objectivesText"] = "Collect 8 Dung Beetle Innards . Progress: Do you have de \"mystery ingredient\" for de mystery meat pie?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 152566, 163841, 211279 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126108, ["x"] = 0.436, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126108, ["x"] = 0.436, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48532] = { ["id"] = 48532, ["name"] = "Alpacas Gone Wild", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "Our herd of alpacas escaped dis morning. Dey're out dere wandering de dunes as we speak. Probably for de best, if you ask me. We'll all be dead soon once Mojambo comes back. Since you seem to care so much, take dis alpaca whistle and use it to round dem up. I blow de whistle every day at feeding time, so de alpacas should come running home when dey hear de sound.", ["objectivesText"] = "Round up 6 Alpacas.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 152570 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126085, ["x"] = 0.422, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126085, ["x"] = 0.422, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48533] = { ["id"] = 48533, ["name"] = "Vol'duni Fried Chicken", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "Have you ever tried my delicious Vol'duni fried chicken? Me neither! Probably because dere aren't any chickens in Vol'dun . Dere are plenty of vultures, though. Why don't you see if you can find some tasty vulture meat? De secret to delicious fried chicken is to roast de meat before you fry it, but it only works if de meat is fresh. I've soaked dese arrows in alpaca fat. If you ignite de arrows and shoot down de birds, dey'll start cooking before dey're even dead!", ["objectivesText"] = "Collect 8 Roasted Buzzard . Progress: Do you have de buzzard meat?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 42491, 152571, 152572, 163208 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126108, ["x"] = 0.436, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126108, ["x"] = 0.436, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48534] = { ["id"] = 48534, ["name"] = "Snarltooth's Last Laugh", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "It's not just Mojambo's gang we have to worry about. We also need to keep a watchful eye at night due to frequent hyena attacks. De most dangerous of de hyenas is Snarltooth. He ambushes us at night, laughing maniacally as he slaughters his prey. I need you to slay de beast once and for all! Snarltooth's den is just south of de arena in de Arid Basin.", ["objectivesText"] = "Retrieve Snarltooth's Head . Progress: Did you take care of Snarltooth?", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 152573 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126085, ["x"] = 0.422, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126085, ["x"] = 0.422, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48538] = { ["id"] = 48538, ["name"] = "An Airtight Alibi", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "It'll take us a while to clean up the beasts that are left over, but I'm confident we'll be able to take back Fletcher's Hollow--thanks to you, of course. Here, take this letter to the constable. It should be enough to clear Miss Waycrest's name. I'm sorry you had to witness all of this, mainlander. We are good people, but these are terrible times.", ["objectivesText"] = "Deliver Evelyn Pare 's letter to Constable Henry Framer at Hangman's Point.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 152587, 152590 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125394, ["x"] = 0.7, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 25, ["flags"] = 0 } } },
[48539] = { ["id"] = 48539, ["name"] = "Freehold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["series"] = { 48419, 48505 }, ["description"] = "Well, there she is: Freehold. You can get anything you want there, provided you can pay for it. Whether you pay with gold or steel is up to you. Take a look.", ["objectivesText"] = "Use Flynn's Spyglass. Progress: Look, I'm worldly, but I don't have anything you can catch from my eyes. Just use the spyglass, would ya?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153509, 153680, 153681, 153682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 21, ["flags"] = 0 } } },
[48540] = { ["id"] = 48540, ["name"] = "Aiding the Wharf", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["series"] = { 48347 }, ["description"] = "We have read the tides, and never before have I seen them in such turmoil. They call to the tidesages, begging for help. A debilitating sickness is running rampant amongst the villagers, and it comes from the sea. We are but few. There is only so much we can do! Please, take this list and gather the listed reagents from around the pier while I attempt to calm these folks. I should be able to create a tonic that will help. I hope.", ["objectivesText"] = "Collect a Satchel of Seaweed, a Bundle of Vellum , and some Seal Blubber from around Anglepoint Wharf.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48549] = { ["id"] = 48549, ["name"] = "Grozztok the Blackheart", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "A group of us were dropped off here and left to die. Our first night at camp, I was jolted from sleep by de gurgling cries of my fellow exiles. Jakra'zet sent assassins to our camp, looking for Rakera. Their leader, Grozztok, came for me, but Rakera intervened. She chased him into de dunes, but dat was days ago. If you cross paths with Grozztok, don't hesitate to drive a blade into his black heart.", ["objectivesText"] = "Kill Grozztok within Atul'Aman.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126696, ["x"] = 0.53, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122289, ["x"] = 0.532, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 25, ["flags"] = 0 } } },
[48550] = { ["id"] = 48550, ["name"] = "Stolen Satchels", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47316, 47317, 47319, 47320, 47321, 47959, 48549, 48550, 51574 }, ["description"] = "One within our group spoke of a temple in de mountains dat welcomes exiles, though none are permitted to enter without an offering to their loa. I would have given anything to find some solace in dis wasteland, but now I have nothing, thanks to those thieving assassins. Each of us had a satchel dat carried de last of our possessions. We didn't have much, but it was more than one troll would need. If you search de dunes looking for your friend, could you keep an eye out for our satchels?", ["objectivesText"] = "Collect 5 Weathered Satchels from Sandfury Assassins. Progress: Have you recovered our belongings?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 152660, 155400, 155401, 155402, 155403, 161269, 161271, 161273, 161275 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126696, ["x"] = 0.53, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126696, ["x"] = 0.53, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 606, ["name"] = "Dangers in the Desert", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 17, ["flags"] = 0 } } },
[48551] = { ["id"] = 48551, ["name"] = "Wither Without Water", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48551 }, ["description"] = "The flora in this area weren't always so aggressive. Without water, the thistlevines wither and waste until they become something unrecognizable and angry. Take my watering can and wet the withering thistlevines to prevent them from becoming carnivorous.", ["objectivesText"] = "Use Ranah's Watering Can to water 10 Withered Thistlevines .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 152630 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126814, ["x"] = 0.538, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126814, ["x"] = 0.538, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[48553] = { ["id"] = 48553, ["name"] = "Let it Flow", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48553 }, ["description"] = "The fountains here have seen better days. They're currently incapable of holding water, but we can fix that! You can use my spare tools to repair the cracks. With a little luck and elbow grease, the fountains will be flowing again in no time!", ["objectivesText"] = "Repair the fountains within Withering Gulch. Progress: Getting the fountains working again is my top priority.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 152813 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126814, ["x"] = 0.538, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126814, ["x"] = 0.538, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[48554] = { ["id"] = 48554, ["name"] = "The Source of the Problem", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48554 }, ["description"] = "I checked my work twice when working on this fountain. I made no mistakes. There must be something wrong at the source. The fountain draws water from a modest reservoir above the terrace. Would you mind checking it out?", ["objectivesText"] = "Help Ranah determine the cause of the malfunctioning fountain within the Withering Terrace. Progress: There's no good reason why this fountain should be malfunctioning.", ["rewardGold"] = 257400, ["rewardXP"] = 5145, ["rewardItems"] = { 152813, 155392, 155393, 155394, 155395, 155448, 159975, 163036, 163514, 245263 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126814, ["x"] = 0.538, ["y"] = 0.694 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126814, ["x"] = 0.538, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[48557] = { ["id"] = 48557, ["name"] = "Sowing Saplings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48557 }, ["description"] = "Algerson destroys the forests and leaves nothing remaining! It is up to us to take care of Azeroth, to help her live and grow as she was meant to! Take these seeds, find the soil that calls for them, and help our planet recapture her grace and vitality!", ["objectivesText"] = "Plant seeds in 4 Loamy Soil .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129670, ["x"] = 0.666, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129670, ["x"] = 0.666, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48558] = { ["id"] = 48558, ["name"] = "The Irontide Crew", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["description"] = "You see those salty looking guys in red? That's the Irontide crew. They're the worst of the worst. Cutthroats and brigands, to a man. Irontide wouldn't be guarding the docks if they didn't stand to gain something... Lighten their pockets. See what kinda hardware they've got.", ["objectivesText"] = "Collect 3 Azerite Cutlasses and 2 Horns of Azerite Powder from Irontide Cutthroats and Irontide Trickshots. Progress: What have you found?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153509, 153680, 153681, 153682, 155052, 155058, 155063, 155066, 155071, 155073, 155077, 155080 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 22, ["flags"] = 0 } } },
[48573] = { ["id"] = 48573, ["name"] = "Crocolisk Life", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "I need my shaman mojo back if we are going to kill Urok. He beat me bad de last time I tried to put him down. You help me get my power back, and I help you make Urok dead. Deal? First step, I need you to use dis dagger to absorb what is left of de life force of any crocolisk you kill. When de dagger seems full, come find me. Heh heh, dat's right Sur'jan . Dey gonna help us, den Urok will see who de strongest is!", ["objectivesText"] = "Absorb essence of 8 primal snapjaw corpses with Sur'jan's Ritual Dagger .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152596 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48574] = { ["id"] = 48574, ["name"] = "Pulling Fangs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "I need more things to help me get strong. I need you to get me some saurid teeth . No, Sur'jan , you're not trusting <him/her> TOO much. Just enough. I won't be betrayed again. I need dese teeth for a ritual I'm gonna perform to help me get my power back. Once I'm not so weak, you and I are gonna take down dis undead monster.", ["objectivesText"] = "Recover 40 Saurid Teeth . Progress: You got enough teeth for me?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 152595 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48576] = { ["id"] = 48576, ["name"] = "Safe Flying", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "I'm feeling... stronger! But I need more power before we take down Urok. No, Sur'jan , YOU are scared of Urok more than me. I'm not scared of nothing! You got an attachment to me now after dat ritual. I need you to go kill de skyterrors nearby. Their deaths will fuel my strength. Take my grappling hook. You can drag de skyterrors down from de sky with it, and it'll put de hurt on dem too.", ["objectivesText"] = "Kill 8 Primal Skyterrors .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 152610 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48577] = { ["id"] = 48577, ["name"] = "Terrorizing their Eggs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "Sur'jan , I should be doing dis! What do you mean, I need to recover? Bah, fine. I need more power, and de skyterrors have eggs nearby. I need you to bash some of their eggs to fuel my energy. Those eggs got lots of life force in dem. You destroy dem, and I will feel de energy coming back to me. Come on, Sur'jan , dis will be easy! I can do dis! Hmph... well, you make a good point. You always were de smarter one out of us.", ["objectivesText"] = "Destroy 5 Skyterror eggs .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48578] = { ["id"] = 48578, ["name"] = "There's No Eye in Skyterror", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "There's a real big skyterror dat I name Jarkadiax. I need his tongue... What's dat, Sur'jan ? Not his tongue? His eye? You sure? Hrm. I need his eye for my next ritual. I know what you're thinking. De tongue makes more sense. Dat's what I-- Look, Sur'jan , I still think it's his tongue. We'll see which of us is right! Go get Jarkadiax's eye and bring it back to me for de next ritual.", ["objectivesText"] = "Recover Jarkadiax's Eye . Progress: I need dat eye. You get it yet?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 152600, 155377, 159074 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48581] = { ["id"] = 48581, ["name"] = "A Good Spanking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "Pinky is contained in de direhorn pen for now, but de handlers are having a real hard time with him! Dis calls for some tough love. Will you help dem?", ["objectivesText"] = "Help the handlers subdue Pinky.", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 158408, 158409, 158410, 158411, 158431, 158432, 158433, 158434 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 122009, ["x"] = 0.675333, ["y"] = 0.434667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.675333, ["y"] = 0.434667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 10, ["flags"] = 0 } } },
[48584] = { ["id"] = 48584, ["name"] = "The Blood of My Enemies", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "I feel my power returning, but we aren't done yet. We need more power to kill dis undead Urok. We'll be pushing in to Urok's lair. Dreadticks are swarming in de area. I want you to bring me their blood for de final ritual. Take dis. It's my trusty dreadtick gasser. Throw it in de area, dreadticks sniff it... den DIE! Hahaha! Now get going! ... Sur'jan , you keep telling me to let <him/her> do dis sorta work, but I could do it too! Fine, I'll just work on getting de ritual ready.", ["objectivesText"] = "Collect 45 Coagulated Dreadtick Blood . Progress: You get me dat blood yet?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 152611, 156618 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 7, ["flags"] = 0 } } },
[48585] = { ["id"] = 48585, ["name"] = "Wasteland Survivor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "<The leather has become dry and cracked in the sun, but the supplies inside are mostly intact. It's unknown what gruesome death befell the backpack 's former owner, but supplies like these are in high demand among the outcasts. The desert has claimed many lives... perhaps there are more supplies to be found among the dunes. >", ["objectivesText"] = "Collect 10 Scavenged Supplies . Progress: What do you have for me?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 152601 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48588] = { ["id"] = 48588, ["name"] = "Purge the Infection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48588 }, ["objectivesText"] = "Infected saurolisks and eggs destroyed", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Infected saurolisks and eggs destroyed", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863 },
[48590] = { ["id"] = 48590, ["name"] = "My Head and Shoulders", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "If we're going to fight Urok, I will need my gear back. It was all lost when I was running from Urok de first time. Shut UP, Sur'jan ! I had to ditch it in order to run faster. Bring my gear back to me, and I'll be ready to fight Urok with you.", ["objectivesText"] = "Recover Sur'jan 's head and shoulder gear. Progress: You got my gear?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156619, 156620, 156621 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 8, ["flags"] = 0 } } },
[48591] = { ["id"] = 48591, ["name"] = "Urok's True Death", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "This is it! My power is back; we are ready to put down Urok . He used to be a noble beast, you know. Big, strong. Now Urok is just a mindless undead. It isn't right. We'll put him to rest. I'm going to run up ahead. When you get near Urok , I'll hop out to ambush him. Let's do dis! Shut up, Sur'jan . Of course we're going to win! If we don't, I'll just find another <class> to help me out.", ["objectivesText"] = "Defeat Urok .", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 131872, ["x"] = 0.288, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 131872, ["x"] = 0.288, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.288, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48597] = { ["id"] = 48597, ["name"] = "Saurolisk Escape", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "You cautiously approach a saurolisk tied to a post. It doesn't snap at you, but looks at you with defeat in its eyes. The troggs seem to be keeping these saurolisks against their will. They should be freed before they are abused further.", ["objectivesText"] = "Free 6 Trapped Saurolisks .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126804, ["x"] = 0.56, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127144, ["x"] = 0.544, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48604] = { ["id"] = 48604, ["name"] = "Home Again, Home Again", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 48604 }, ["description"] = "I can't thank you enough for the help here! You showed up just in time. Here is Elijah's sausage order. Don't worry, it's just regular sausage- nothing questionable. Now if you'll excuse me I have to see to my workers.", ["objectivesText"] = "Return to Elijah Eggleton in Fallhaven. Provided item:", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 152629 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48606] = { ["id"] = 48606, ["name"] = "Loaded for Bear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48606 }, ["description"] = "<This glittering cannonball stands out from the others. You notice the familiar sheen of Azerite across the surface. You can't help but notice the nearby cannon, conveniently pointed at the ships loaded with stores of Ashvane Company weapons.>", ["objectivesText"] = "Use the Ashvane Cannon to destroy 6 Ashvane Co. Supplies . Azerite Cannonballs are required to fire the cannon.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152628 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127537, ["x"] = 0.792, ["y"] = 0.764 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.764 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48616] = { ["id"] = 48616, ["name"] = "Bolas and Birds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "Up in the mountains we know the value of a good hunting companion. We use bolas to shoot down our flying prey, then our retrievers go and bring us our kill! You want to take a shot? Nickel can accompany you. Shoot down some of the falcons in the woods. My dog will finish the job.", ["objectivesText"] = "Shoot down 6 Hollowbeak Falcons with the Bola Launcher .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125398, ["x"] = 0.555, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125398, ["x"] = 0.555, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48622] = { ["id"] = 48622, ["name"] = "The Vanishing Lord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "Unfortunately, we don't have any contacts within House Waycrest, so our efforts in Drustvar will have to start from the ground up. We have arranged for a ferry to take you to Fallhaven - a farming village in eastern Drustvar . The mayor there, Cyril White , is a longtime friend of the Proudmoores, and I think he can help us get in touch with someone from the house. I hope you can get to the bottom of their absence, <name>. Their martial might is invaluable to the Kul Tiran fleet.", ["objectivesText"] = "Meet with Cyril White in Fallhaven in Drustvar .", ["rewardGold"] = 25740, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.731333, ["y"] = 0.23 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 381, ["name"] = "Fallhaven", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48653] = { ["id"] = 48653, ["name"] = "A Bejeweled Prison", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 48653 }, ["description"] = "<As you gaze into the strange gem you feel a sudden need to travel into the swamps of Nazmir and return the gem to it's rightful resting place, wherever that may be.>", ["objectivesText"] = "Return the Restored Eye of Eternity to its resting place within the Dreadmire.", ["rewardGold"] = 154900, ["rewardXP"] = 1385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 152655 } },
[48655] = { ["id"] = 48655, ["name"] = "The Chef's Apprentice", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "< Sezahjin rummages through his cooking ingredients in frustration.> Where is Junji ? I sent him to scavenge for vulture eggs, but he hasn't returned. < Sezahjin pauses for a moment.> He was just going on about de size of saurolisk eggs, but those oversized lizards are far too dangerous for a boy! He can't possibly be so foolish... If he has gone to de saurolisk breeding grounds... he may already be dead. Please find him before it's too late!", ["objectivesText"] = "Locate Junji .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126108, ["x"] = 0.436, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 7, ["flags"] = 0 } } },
[48656] = { ["id"] = 48656, ["name"] = "Savage Saurolisks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "Please, help me! I'm trapped in dis box and I can't make it out alone! I came here to collect eggs. I knew it was a bad idea, but I thought I could sneak around and grab de eggs before de saurolisks noticed. I was wrong... I hid underneath dis crate to avoid being eaten! Can you clear out de saurolisks and tell me when it's safe to come out? Please, don't leave me here!", ["objectivesText"] = "Slay 8 Scaleclaw Saurolisks in the Arid Basin. Progress: Are de saurolisks gone yet?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 9, ["flags"] = 0 } } },
[48657] = { ["id"] = 48657, ["name"] = "They Might Be Delicious", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "Saurolisk eggs are de most delicious eggs in de desert! I mean, I've never tried dem myself... but look at de size of them! Dey're huge! Bigger is better, right? If I go back to camp empty handed, Sezahjin is going to kill me! We have to get some of those eggs! You sound a lot older and stronger than I am. Gather up de eggs so we can take dem back for everyone to eat. Don't worry about me, I'll wait for you here. It's not like I'm going anywhere...", ["objectivesText"] = "Gather 10 saurolisk eggs from the Arid Basin. Progress: Do you have de saurolisk eggs ?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 152647, 159978, 159996, 159997, 159998, 159999 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 10, ["flags"] = 0 } } },
[48669] = { ["id"] = 48669, ["name"] = "Urok, Terror of the Wetlands", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48573, 48574, 48576, 48577, 48578, 48584, 48590, 48591, 48669 }, ["description"] = "You! You can help me! I know, Sur'jan , <he/she> looks like a <class>, but I know we can trust <him/her>. Urok, de terror of de wetlands, is undead now. We have to put it down before it tries to destroy dis entire place. Just give me a minute, and you will see dat Urok is bad news. Shhh, Sur'jan , dey gonna see, dey are all gonna see!", ["objectivesText"] = "See Urok, Terror of the Wetlands. Progress: Just give me a chance and you'll see!", ["rewardGold"] = 25740, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126713, ["x"] = 0.3288, ["y"] = 0.7596 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3288, ["y"] = 0.7596 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5417, ["name"] = "Urok, Terror of the Wetlands", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48670] = { ["id"] = 48670, ["name"] = "Runaway Rider", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48003, 48004, 48005, 48077, 48080, 48087, 48088, 48089, 48195, 48196, 48597, 48616, 48670 }, ["description"] = "Lord Norwington demanded I take Eddie out riding in the woods, but I knew it was too soon! I just knew it! We've got to go find him. Meet me across the river!", ["objectivesText"] = "Meet Melissa Kenny near Mistfall Cleft.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127006, ["x"] = 0.555, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127144, ["x"] = 0.544, ["y"] = 0.194 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 591, ["name"] = "The Norwington Estate", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48677] = { ["id"] = 48677, ["name"] = "Wicker Worship", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48677, 48678, 48679, 48682, 48683 }, ["description"] = "Hail, traveler! You look like just the sort who might be able to help me out with a predicament! It's my son Edwin, you see. We were travelling through Drustvar to ply our wares when the damned fool ran off to join some cult here in Autumnvale! Since then we haven't seen a trace of him, and the brown-robed loons won't speak a word of his whereabouts! Could you see if you could persuade them to talk? His poor mother is worried sick!", ["objectivesText"] = "Meet Lord Autumnvale in Autumnvale.", ["rewardGold"] = 28090, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127296, ["x"] = 0.625, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127080, ["x"] = 0.595, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.625, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5448, ["name"] = "Wicker Rituals", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48678] = { ["id"] = 48678, ["name"] = "Questionable Offerings", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48677, 48678, 48679, 48682, 48683 }, ["description"] = "So the traders sent you? As I told them, I only discuss the happenings of our family with those who understand our cause. If you wish to know his whereabouts, you must prove that you do. Behind us are several items gathered for offering to the Wicker Man. Bring us the items you feel will most appease it, so that it might give us its blessing. Choose the correct offerings, and we will know your intent.", ["objectivesText"] = "Bring the correct offerings to the Wicker Man in Autumnvale. Progress: You must bring the correct offerings if you wish to show us your understanding.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127080, ["x"] = 0.595, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127080, ["x"] = 0.595, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5448, ["name"] = "Wicker Rituals", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48679] = { ["id"] = 48679, ["name"] = "Mind the Hives", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48677, 48678, 48679, 48682, 48683 }, ["description"] = "The one called Edwin came to us not long ago, seeking to earn the blessings of the Wicker Man. He wandered off into the hills looking for his own offering. Unfortunately, he managed to disturb one of the nearby beehives, causing the insects to become rather frenzied. That was the last I saw of him, I'm afraid.", ["objectivesText"] = "Find Edwin Maldus in Barbthorn Ridge. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127080, ["x"] = 0.595, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127396, ["x"] = 0.594, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5448, ["name"] = "Wicker Rituals", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48680] = { ["id"] = 48680, ["name"] = "Not the Bees!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48680 }, ["objectivesText"] = "Drive back the Barbthorn Swarm", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["rewardItems"] = { 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Drive back the Barbthorn Swarm", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896 },
[48682] = { ["id"] = 48682, ["name"] = "A Simple Sacrifice", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48677, 48678, 48679, 48682, 48683 }, ["description"] = "You must hurry! Lord Autumnvale brought Edwin off to that cave right when he returned, saying something about \"an offering of blood!\" I think they mean to sacrifice him to appease the Wicker Man! Just what kind of crazy cult is this?!", ["objectivesText"] = "Rescue Edwin Maldus from the Wickerite cultists in Autumnvale. Progress: Help me!", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127396, ["x"] = 0.594, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127418, ["x"] = 0.574667, ["y"] = 0.233333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5448, ["name"] = "Wicker Rituals", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48683] = { ["id"] = 48683, ["name"] = "Changing Seasons", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48677, 48678, 48679, 48682, 48683 }, ["description"] = "I appreciate you saving me again, but we should do something to prevent this from happening to anyone else. So long as that Wicker Man stands, it will attract more like Autumnvale to it. We should destroy it! Are you with me?", ["objectivesText"] = "Burn the Wicker Man in Autumnvale. Progress: The Wicker Man must be destroyed!", ["rewardGold"] = 128700, ["rewardXP"] = 1385, ["rewardItems"] = { 158592, 158594, 158615, 158616, 158617, 158618 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127418, ["x"] = 0.574667, ["y"] = 0.233333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126979, ["x"] = 0.6025, ["y"] = 0.186 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.574667, ["y"] = 0.233333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5448, ["name"] = "Wicker Rituals", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48684] = { ["id"] = 48684, ["name"] = "On the Move", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["series"] = { 48895 }, ["description"] = "Jorak 's wounds have healed enough for him to travel. He has agreed to guide us to de temple. De sooner we leave, de better. Rakera won't survive in dis desert for long.", ["objectivesText"] = "Travel with Meerah's Caravan in search of Warguard Rakera.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187328, 187334, 187336, 187466, 211279, 237812 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122289, ["x"] = 0.532, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127691, ["x"] = 0.528, ["y"] = 0.892 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 18, ["flags"] = 0 } } },
[48715] = { ["id"] = 48715, ["name"] = "Akunda Awaits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "I've spoken to every troll out here, asking if they've seen Rakera. As you might have guessed, Akunda is de only name dey know. Let's hope someone within de temple will be able to tell us something useful.", ["objectivesText"] = "Investigate the Temple of Akunda.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127570, ["x"] = 0.532, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135066, ["x"] = 0.535, ["y"] = 0.916 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 26, ["flags"] = 0 } } },
[48752] = { ["id"] = 48752, ["name"] = "A Need For Coal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48752, 48761 }, ["description"] = "Ah! <name>! Just the person I was hoping to see! I was just getting ready to smelt some monelite down into ingots, but I noticed my coal supply was running low. Well, I mean... I have coal, yes, but I prefer using Ashvane Coal . It puts out less smoke and burns hotter, so I need less of it. If you can get some Ashvane Coal from the Ashvane Foundry south of here, I'd be more than willing to give you a couple pointers for mining monelite. Deal?", ["objectivesText"] = "Collect 9 handfuls of Ashvane Coal . Progress: Have you gone to the foundry yet?", ["rewardItems"] = { 152512, 152513, 152579, 160902, 160905, 161078, 161085, 163836 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 767, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Monelite Deposit - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48753] = { ["id"] = 48753, ["name"] = "Emergency Transplants", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48753, 48754 }, ["description"] = "With everything that's been happening over in Drustvar, there's been a sudden surge of wildlife in the sound. Normally, I wouldn't care, but they've been eating all the riverbud! If things don't improve soon, we could try thinning their numbers so they don't consume everything, but I'll consider that the last resort. Instead, could you go plant some of these seeds to produce additional food for them?", ["objectivesText"] = "Plant 10 Riverbud Seeds in rivermud. Progress: Have you planted the seeds yet?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 752, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Riverbud - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48754] = { ["id"] = 48754, ["name"] = "Breaking The Food Chain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48753, 48754 }, ["description"] = "The extra riverbud you planted has helped, but it's not enough. Some of the local wildlife are consuming the riverbud before they mature. The more riverbud that is eaten, the less we have for our own needs. The largest group of young riverbud consumers are the turtles. If the riverbud becomes a threatened species, we'll need to regulate harvesting it. Instead, go thin the number of the turtles in the area. Do that and I'll teach you everything I know about riverbud.", ["objectivesText"] = "Kill 15 Freshwater Snapper .", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 752, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Riverbud - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48755] = { ["id"] = 48755, ["name"] = "Pollen Punching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["storyline"] = { 48755, 48758, 51312, 51313 }, ["series"] = { 48758 }, ["description"] = "What I think happened is that some creature lapped up all the pollen with it's tongue. While I'm curious as to what creature could have done this, I doubt it matters. I believe we can safely reproduce this without needing any sort of rare or dangerous reagents. Next time you find a siren's sting, simply try wetting your glove so the pollen will stick to it. Water, wine, spit... It shouldn't matter.", ["objectivesText"] = "Collect 12 Heaping Handfuls of Damp Pollen from siren's sting.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 159957, 160035, 160064, 160117, 160301 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 754, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Siren's Pollen - SCS", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48756] = { ["id"] = 48756, ["name"] = "Here In Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48756, 48757 }, ["description"] = "Hey, <name>, how would you feel about doing some legwork for a favor? We have a tradition here in Kul Tiras, that during a celebration, be it funeral, wedding, or birthday, we incorporate star moss into the decorations. We do that so those who are no longer amongst the living can be here in spirit. With the recent fighting, my stores are near empty due to the number of funerals we've had. If you bring me fresh star moss to restock my supply, I'll share a secret on how to get more from each star moss.", ["objectivesText"] = "Harvest 10 Fresh Star Moss . Progress: There was a funeral the other day, seem to be more and more as of late. Any chance you gathered that star moss I asked for?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159830, 159877, 159956, 160035, 160064, 160117, 163834 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 755, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Star Moss - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48757] = { ["id"] = 48757, ["name"] = "Ghost Busting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48756, 48757 }, ["description"] = "I hate to ask this of you, but are you available for some more grunt work? I'd do it myself, but this seems beyond my capabilities. Remember how I told you we use star moss to allow those no longer living to join us for a special day? Yeah, well, sometimes once they show up, they don't want to leave. There is a spirit on the other side that is lashing out, harming those it should be protecting. Take this smoldering star moss and cleanse the area until you find the offender and help them move on.", ["objectivesText"] = "Put the Angry Spirit to rest. Progress: Have you banished the spirit yet?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159833, 159877, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 755, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Star Moss - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48758] = { ["id"] = 48758, ["name"] = "Disgustingly Damp Flower", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48755, 48758, 51312, 51313 }, ["series"] = { 48755 }, ["description"] = "Rummaging for pollen as usual, you use the harvesting technique you learned from the bees. However, when you pull your hand away from the flower, you find that there is no pollen on your gloves. Looking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all within it. Upon closer inspection you see that the flower is filled with a viscous liquid. Could the flower have done this? While unpleasant to touch, you carefully pluck the flower to show Declan.", ["objectivesText"] = "Bring the Disgustingly Damp Flower to Declan Senal . Provided item:", ["rewardItems"] = { 85663, 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 754, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Siren's Pollen - SCS", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 159956 } },
[48759] = { ["id"] = 48759, ["name"] = "Akunda's Bite - Rank 2 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48759 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48760] = { ["id"] = 48760, ["name"] = "Akunda's Bite - Rank 3 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48760 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48761] = { ["id"] = 48761, ["name"] = "Spiderphobia", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48752, 48761 }, ["description"] = "You're no stranger to monster fighting, right? The other day I found a spider just outside my house. Nothing out of the ordinary, except it was the SIZE OF A HORSE! Twenty-five minutes of screaming and pick-axeing later and I had managed to kill it. I spoke with one of the guards, and he said that there was a huge nest of them just over the hill to the northwest. If you can slay them or whatever you do, I'll teach you a secret to mining monelite. Otherwise, I'm going to have to move.", ["objectivesText"] = "Kill 8 Enthralled Mossfangs and 15 Mossfang Egg . Progress: I can't stand spiders. <Myra shudders.> Have you dealt with them yet?", ["rewardItems"] = { 69777, 152512, 152513, 152579, 160905, 161078, 161085 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 767, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Monelite Deposit - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48762] = { ["id"] = 48762, ["name"] = "Meet Sweetflower", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48762, 48763, 51376 }, ["series"] = { 51376, 51446 }, ["description"] = "It looks like you've become familiar with the plants around here. There's a flower that grows in the snowy parts of the continent, but I can't tell you much else about it. Can't stand being cold. However, if you're interested in learning more, I know of someone who may be able to teach you. Her name's Xun Xun Sweetflower , and last I heard she set up shop on the outskirts of Anyport over in Drustvar. Tread carefully, though, that area is crawling with Irontide Raiders.", ["objectivesText"] = "Find Xun Xun Sweetflower in Drustvar.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136141, ["x"] = 0.206, ["y"] = 0.456 }, { ["mapID"] = 896, ["npcID"] = 136269, ["x"] = 0.206, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 756, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Winter's Kiss - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48763] = { ["id"] = 48763, ["name"] = "The Frigid Boon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48762, 48763, 51376 }, ["description"] = "While harvesting this winter's bite, you managed to pluck the flower without breaking any petals, a feat you had not accomplished before. Taking a quick mental note of every detail about yourself and your surroundings, one point sticks out to you. The heat from your breath appears to have made the petals supple enough to bend instead of break. You also believe that this may be a way to prevent the flower from activating its defensive cold blast. If that is the case, it could be extremely useful.", ["objectivesText"] = "Harvest 10 winter's kiss without taking cold damage.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117, 160301, 160550 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 756, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Winter's Kiss - SCS", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 761, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Winter's Kiss - SCS", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 160064 } },
[48764] = { ["id"] = 48764, ["name"] = "Don't Pick a Fight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48764, 48767 }, ["description"] = "Hey, you're not busy, right? I could use your help. Ya see, I was out mining in Stormsong Valley, when this huge, two-headed monstrosity started chasing after me! I ran away, but I was back in Boralus when I realized I dropped my favorite mining pick! I know this may sound stupid, but if you could get it back for me I'd be grateful. You don't need to do something crazy, like fight them. Instead, sneak by them and grab it. I'll show you a trick to mining monelite seams for your troubles.", ["objectivesText"] = "Retrieve Myra's Favorite Mining Pick. Progress: Did you get my mining pick back?", ["rewardItems"] = { 152512, 152513, 152579, 160052, 160904, 160905, 161078, 161085 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 768, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Monelite Seam - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48765] = { ["id"] = 48765, ["name"] = "Aromatic Pollen - Rank 2 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48765 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48766] = { ["id"] = 48766, ["name"] = "Aromatic Pollen - Rank 3 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48766 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48767] = { ["id"] = 48767, ["name"] = "Seams Familiar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48764, 48767 }, ["description"] = "You find a necklace in the shape of an anchor with the name \"Cabot\" etched in a banner. The name immediately brings up Myra Cabot , the mining trainer in Boralus. The condition of the necklace makes it look like it has been well maintained. She probably wants it back.", ["objectivesText"] = "Return the Lost Necklace to Myra Cabot .", ["rewardItems"] = { 152512, 152513, 152579, 153431, 160905, 161078, 161085 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 768, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Monelite Seam - SCS", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 160905 } },
[48768] = { ["id"] = 48768, ["name"] = "Brined Justice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48768, 51568 }, ["description"] = "<name>, I just got word that one of our ships was attacked and a large amount of storm silver stolen! The sacred materials can't be replaced. Once it is blessed by the seapriest, it is buried underwater for a year! From what I heard, a group of pirates followed the ship to see where the metal was buried on the sea floor before killing the crew and taking her cargo. Kill the pirates and get back that metal.", ["objectivesText"] = "Collect 100 Stolen Storm Silver Bars . Progress: Damn those pirates! Have you recovered the bars?", ["rewardItems"] = { 152512, 152513, 152579, 160453, 160905, 161078, 161085 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 770, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Storm Silver Deposit - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48769] = { ["id"] = 48769, ["name"] = "Gathering Mementos", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48769, 51365 }, ["description"] = "I have a task that I can't really trust to anyone else, and I feel you could handle it with the reverence it deserves. An old friend of mine came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship south east of Freehold. I'm not sure if it was pirates, the Horde, or a squall, but she said she didn't want revenge, just closure. If you could get her something to remember him by, I'll tell you everything I know about sea stalks, and you'd have my gratitude.", ["objectivesText"] = "Search through patches of sea weed to find a memento of the lost sailor. Progress: Have you found any of his personal effects?", ["rewardItems"] = { 85500, 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160057, 160064, 160117, 160560 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 753, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Sea Stalk - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48770] = { ["id"] = 48770, ["name"] = "Three Sheets to the Wind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48770, 51380, 51889 }, ["description"] = "Hey, <name>. Now isn't a great time for me. If you're interested in learning, you could talk to Franklin, my old apprentice. He used to be a damn fine miner, but now he's just a washed up drunk. You can find him asleep on the docks. I don't remember what he drinks, but if you bring him something he's sure to at least try it. He'll talk if he likes it. Talk to Harold Atkey, the bartender, he's sells a variety of drinks, I'm sure one of them is his choice.", ["objectivesText"] = "Bring Franklin The Drunk a drink he likes to learn his mining secrets. Progress: <Myra's former apprentice, Franklin drunkenly stares at you.> I ain't talkin'.... 'less you got a drink.", ["rewardItems"] = { 152512, 152513, 152579, 159845, 160905, 161078, 161085, 162574 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 771, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Storm Silver Seam - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48771] = { ["id"] = 48771, ["name"] = "Herb 07 - Rare - Rank 2 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48771 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48772] = { ["id"] = 48772, ["name"] = "Herb 07 - Rare - Rank 3 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48772 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48773] = { ["id"] = 48773, ["name"] = "Papers, Please", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["description"] = "All this legwork will be for nothing if we can't show Katherine hard proof linking the Ashvane Company to the freebooters here in Freehold. Ashvane might have been careful to encrypt their books, but I doubt the dockmaster here has any reason to be so secretive. Check his office and find us something--anything--that connects him to Ashvane.", ["objectivesText"] = "Collect the Dockmaster's Records . Progress: Lady Katherine is as stubborn as a whale shark. She won't buy our story without proof.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153509, 153680, 153681, 153682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 23, ["flags"] = 0 } } },
[48774] = { ["id"] = 48774, ["name"] = "The Beatings Will Continue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48774 }, ["description"] = "Ain't seen you before. You a mercenary? I got some guys need roughin' up. <The grizzled woman spits through a gap where her front tooth should be.> Ever since Harlan started fancyin' himself an admiral, his Irontide guppies been struttin' around like they own the place. Forcin' other crews to swear loyalty to Harlan, beatin' on us what can't defend ourselves. Freehold was never a safe town, but at least it was free. <She runs her tongue along the gap in her teeth.> Bastards.", ["objectivesText"] = "Slay 5 Irontide Ruffians and 2 Irontide Overseers . Progress: Well is you a merc or isn't you? Get to merc'in!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127537, ["x"] = 0.792, ["y"] = 0.764 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127537, ["x"] = 0.792, ["y"] = 0.764 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.764 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48776] = { ["id"] = 48776, ["name"] = "Rig Robbing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48776 }, ["description"] = "I'm out here tryin' to enjoy my break, but I ran outta hooch. Got some grog hidden in the water just off the dock, stashed in a crate tied up to some of the rigging. Do me a favor and fetch it, will ya? Rigging's pretty tangled so you might have to pull in a few lines before you get the right one. I'd do it myself, but if they see me they're gonna force me back to work unloadin' them new weapons.", ["objectivesText"] = "Use the Tangled Rigging to collect the \"Sea Dog\" Grog. Progress: You get my stash?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152667 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127537, ["x"] = 0.792, ["y"] = 0.764 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127537, ["x"] = 0.792, ["y"] = 0.764 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.764 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48778] = { ["id"] = 48778, ["name"] = "Stone Soup", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["storyline"] = { 48778 }, ["description"] = "On the surface of the rock you find carvings of what you make out to be ingredients. If you find the ingredients, perhaps you can make the troggs' soup for yourself.", ["objectivesText"] = "Collect the ingredients for Stone Soup in Mistfall Cleft. Progress: The flavor of the soup doesn't seem quite right. It must be missing ingredients.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 152698, 153357 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["startItems"] = { 152666 } },
[48790] = { ["id"] = 48790, ["name"] = "Stolen Goods", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "It was brought to my attention recently dat many of our supplies went missing overnight. I suspected dat Tongo's crew was behind de theft, but we didn't have de strength or numbers needed to confront dem. I want you to search de hideout for signs of our missing supplies. If dere's anything left when you arrive, bring it back here and I'll make sure you're compensated. If we're going to survive Mojambo's assault we're going to need those stolen supplies back as soon as possible.", ["objectivesText"] = "Recover 6 stolen supplies .", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 158876, 158901, 158902, 158903, 158904, 158905 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 14, ["flags"] = 0 } } },
[48792] = { ["id"] = 48792, ["name"] = "Menace to Society", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48792, 48793, 48804, 48805, 48853 }, ["description"] = "These troggs are a menace to the whole area! They raid camps and caravans and eat the livestock when they come down from their caves. The kids being up there might set them off! Slay some of those troggs before they decide to cause trouble.", ["objectivesText"] = "Kill 10 Bonegnasher troggs. Progress: There are a lot of troggs around. More than I expected to see.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127015, ["x"] = 0.516667, ["y"] = 0.252667 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127157, ["x"] = 0.51, ["y"] = 0.237 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.252667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5443, ["name"] = "Trogg Caves", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48793] = { ["id"] = 48793, ["name"] = "The Adventurer's Society", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48792, 48793, 48804, 48805, 48853 }, ["description"] = "Thank the Light! I was taking care of my grandson and his friends. I told them to play quietly while I took a nap. When I woke up they'd left a note saying they were 'Going on an Expedition'. They think they'll find Titan relics in the trogg caverns! They're too young to fight troggs and I'm too old! My bad knee almost gave out getting here. You look strapping. Find my grandson and the rest of the 'Adventurer's Society'. Send them home!", ["objectivesText"] = "Look for signs of the children. Progress: Hey! You found our stuff!", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152676, 152677, 152685, 152724 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127015, ["x"] = 0.516667, ["y"] = 0.252667 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127157, ["x"] = 0.51, ["y"] = 0.237 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.516667, ["y"] = 0.252667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5443, ["name"] = "Trogg Caves", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48799] = { ["id"] = 48799, ["name"] = "Fuel of a Doomed World", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8701, ["storyline"] = { 48799 }, ["description"] = "There is a rare and precious resource to be found in these wastes, <name>. Argunite was once abundant on Argus. Its magical properties helped eredar civilization thrive. Far better for us to make use of its power than the Legion. Seek out all the pristine argunite you can, champion. Every bit you recover will aid our cause.", ["objectivesText"] = "Collect 50 Pristine Argunite from Invasion Points, Rare encounters, or treasure chests on Argus. Progress: Victory requires every resource we can muster.", ["rewardGold"] = 309800, ["rewardXP"] = 6140, ["rewardItems"] = { 153014, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8701 } }, ["questType"] = "standard" },
[48804] = { ["id"] = 48804, ["name"] = "Mistakes Were Made", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48792, 48793, 48804, 48805, 48853 }, ["description"] = "My friends and I wanna be explorers so we made the Society. There are troggs here, right? So that means there's probably ancient stuff nearby! The books say troggs like shiny things so we pooled some of our allowance and gave them gold so we could dig. It didn't work out like we expected. I escaped but they've got my friends! I've been trying to think about how to get them out. Could you do it? We'll include you in our exploration report as an honorary member!", ["objectivesText"] = "Rescue the Adventurer's Society. Progress: Hey! Are you gonna help my friends?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127157, ["x"] = 0.51, ["y"] = 0.237 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127157, ["x"] = 0.51, ["y"] = 0.237 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.237 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5443, ["name"] = "Trogg Caves", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48805] = { ["id"] = 48805, ["name"] = "Research Recovery", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48792, 48793, 48804, 48805, 48853 }, ["description"] = "<The discarded paper contains a list of the items the Adventurer's Society has found during the course of their 'excavation' here at the Northern Caverns. It is unlikely they actually found relics, but there's no harm in recovering the items the kids found. At the least they're souvenirs of the adventure.>", ["objectivesText"] = "Recover the \"relics\". Progress: Woah! You found our relics! Aren't they neat?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152699, 152703, 152704 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127157, ["x"] = 0.51, ["y"] = 0.237 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.237 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5443, ["name"] = "Trogg Caves", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48808] = { ["id"] = 48808, ["name"] = "Thesis Statement", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["storyline"] = { 48808 }, ["description"] = "My thesis! Those smelly troggs took my thesis paper and fed it to their boars! Can you believe it!? I worked forever on it! Two whole days! If I don't get it back I'm ruined! Absolutely ruined! Please get my thesis paper back for me?", ["objectivesText"] = "Recover Thesis Paper Pages .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152705 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[48823] = { ["id"] = 48823, ["name"] = "Projection Destruction", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48823, 48825, 48854, 48855, 48856, 48857, 48869 }, ["description"] = "Dis lich, Zardrax, be tryin' ta corrupt us ta join his side, <name>. I not be fallin' for it, and I know how ta be stoppin' it. He be gatherin' power from dem mounds of skeletons. We gotta burn 'em ta cut Zardrax off a some power. I be strong in da fire mojo. I can be impartin' some of me connection to da fire to ya ta burn dem mounds. I be stayin' here with Kal'dran. I tink Zardrax be gettin' ta him.", ["objectivesText"] = "Destroy 3 Skeleton Mounds with Da'jul's Fire Mojo . Progress: Ya better get movin' and destroy dem skeleton mounds.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 152727 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5416, ["name"] = "Zardax's Offer", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48825] = { ["id"] = 48825, ["name"] = "Power Denied", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48823, 48825, 48854, 48855, 48856, 48857, 48869 }, ["description"] = "Ah! Oh, it's you, <name>. Zardrax has me on edge, saying we are all doomed, dat dere is no hope. I had a plan to stop him. All we had to do was kill a hexxer, Nana'kwug, who is helping spread Zardrax's power, and steal de fetish she is using. Den you'd give dat fetish to Da'jul and he'd use his voodoo to grant us more power. But it is hopeless now. Maybe we should just side with Zardrax. How can we stop someting as big as dis?", ["objectivesText"] = "Defeat Hexxer Nana'kwug and recover her blood fetish . Progress: Ya got dat fetish yet? Maybe Kal'dran be calmin' down when he sees we be havin' a chance ta survive.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 153482 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 127212, ["x"] = 0.31, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5416, ["name"] = "Zardax's Offer", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48840] = { ["id"] = 48840, ["name"] = "Ruins-Level Marketing", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["series"] = { 48322, 48335, 49001 }, ["description"] = "Now dat de Goldtusk Inn be open for business, we gotta make sure everyone in Vol'dun knows about it! I think we should focus on those wagon-riding vulpera first. Dey don't even have real homes! In fact, I saw a pack of vulpera up at de ruins to de north de other day, and dey barely had anything. Take dem dis coupon and tell dem to stop by for a free first stay.", ["objectivesText"] = "Deliver the Goldtusk Inn coupon to Kenzou . Provided item:", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 159676 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 }, { ["mapID"] = 864, ["npcID"] = 129354, ["x"] = 0.434, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129453, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 13, ["flags"] = 0 } } },
[48846] = { ["id"] = 48846, ["name"] = "Liquid Motivation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "< Zauljin motions for you to come closer. He is clearly drunk.> If I had information concerning Mojambo...<hick!>...how much would dat be worth to you? You don't...<hick!>...believe me? Nobody suspects a drunk. I hear all sorts of things... What do you have to lose? All it will cost is a bottle of...<hick!>... Zanchuli Reserve ! Whaddya say, mon?", ["objectivesText"] = "Bring a bottle of Zanchuli Reserve to Zauljin . Progress: What do you have for me?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 160499 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 125862, ["x"] = 0.432, ["y"] = 0.77 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.77 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 11, ["flags"] = 0 } } },
[48847] = { ["id"] = 48847, ["name"] = "Arming the Tribe", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "We spotted some of Tongo's gang scouting de arena while you were away. It seems dis may be de calm before de storm. We need to get de weapons you brought back from Tongo's hideout into de hands of our fellow outcasts. Mojambo's gang could attack any minute now. We need to be prepared. Take de weapons and get dem to de unarmed members of de tribe. If Mojambo thinks he can raid our home without a fight, he's got another thing coming.", ["objectivesText"] = "Arm 8 Scorched Sands Outcasts. Progress: De time for war is nearly upon us.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 15, ["flags"] = 0 } } },
[48850] = { ["id"] = 48850, ["name"] = "Tongo", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48529, 48530, 48531, 48532, 48533, 48534, 48585, 48655, 48656, 48657, 48790, 48846, 48847, 48850, 51573, 51602, 51668 }, ["description"] = "If Mojambo hired Tongo's gang as reinforcements, we're in even more trouble than we first thought. Tongo is a cruel and sadistic marauder who takes great delight in suffering. His gang is notorious for torturing their prey. We won't be able to defend ourselves against both gangs at once. Our only chance of survival now is to strike first. If you take out Tongo before de ambush, Mojambo will be expecting reinforcements dat never arrive. We may be able to use dat to our advantage...", ["objectivesText"] = "Retrieve Tongo's Head . Progress: Has Tongo been defeated?", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 158875 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5424, ["name"] = "Champion of the Arena", ["orderIndex"] = 12, ["flags"] = 0 } } },
[48852] = { ["id"] = 48852, ["name"] = "Stopping Zardrax", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48852 }, ["objectivesText"] = "Weaken Zardrax's Followers", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Weaken Zardrax's Followers", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863 },
[48853] = { ["id"] = 48853, ["name"] = "Terminal Degree", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48792, 48793, 48804, 48805, 48853 }, ["description"] = "That's everyone but Nigel. He's in the big cave! I bet he went in there to look for relics, but now he's tied up! Would you save him too?", ["objectivesText"] = "Slay Cragg the Stoneshaker and free Nigel Rifthold . Progress: Thanks! Negotiation is a lot harder than Brann's book makes it out to be.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 160262 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127157, ["x"] = 0.51, ["y"] = 0.237 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127015, ["x"] = 0.516667, ["y"] = 0.252667 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.237 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5443, ["name"] = "Trogg Caves", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48854] = { ["id"] = 48854, ["name"] = "Offer of Power", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48823, 48825, 48854, 48855, 48856, 48857, 48869 }, ["description"] = "Ah... a <class>. You must be <name>... I have heard whispers of your name. Maybe you are smarter than dese two. Zuldazar will fall to de blood trolls. You know dis. You can be saved, if you promise to serve me. I can give you more power than you have ever imagined. Listen to what I can offer you...", ["objectivesText"] = "Listen to Zardrax's speech. Progress: Show dis lich what ya be thinkin' of it!", ["rewardGold"] = 25740, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 127216, ["x"] = 0.31, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5416, ["name"] = "Zardax's Offer", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48855] = { ["id"] = 48855, ["name"] = "Humbling the Terrors", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48823, 48825, 48854, 48855, 48856, 48857, 48869 }, ["description"] = "When we first got here, I be findin' a whole buncha problems on da other side a Zardrax's barrow. Dere be dese monstrous zombies walkin' around da area. We gotta take 'em down ta make sure dey don't get ta Zuldazar. I used me voodoo ta be modifyin' dat fetish ya just found. Use dis new fetish ta weaken and kill dem zombies.", ["objectivesText"] = "Defeat 3 Reconstructed Terrors by weakening them with the Modified Blood Fetish .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 153483 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5416, ["name"] = "Zardax's Offer", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48856] = { ["id"] = 48856, ["name"] = "Conduit Interruption", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48823, 48825, 48854, 48855, 48856, 48857, 48869 }, ["description"] = "Dere be skeletons dat be funnelin' blood magic inta Zardrax's barrow. Me guess be Zardrax created dem ta help gather more power. Ya gotta kill dese skeletons if ya want any shot at killin' dis lich. He should be gettin' weaker if he not be havin' dem as a source a power. I be stayin' here in da meantime ta be watchin' our backs, no tellin' if dere be blood trolls comin' ta attack us.", ["objectivesText"] = "Defeat 8 Zardrax Conduits .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5416, ["name"] = "Zardax's Offer", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48857] = { ["id"] = 48857, ["name"] = "All Hope is Lost", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48823, 48825, 48854, 48855, 48856, 48857, 48869 }, ["description"] = "I am not doing dis anymore! You and Da'jul are WRONG! Dere is no stopping Zardrax! I am leaving, and you cannot stop me. Zardrax will save us all from destruction and give us new power!", ["objectivesText"] = "Calm down Kal'dran . Progress: Did ya find where Kal'dran ran off ta?", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 127212, ["x"] = 0.31, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5416, ["name"] = "Zardax's Offer", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48869] = { ["id"] = 48869, ["name"] = "Payback's a Lich", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48823, 48825, 48854, 48855, 48856, 48857, 48869 }, ["description"] = "We can't be focusin' on da loss of Kal'dran. He be givin' up hope, and dat be someting we not gonna do. Dis be da time ta strike at Zardrax. His power be waning. Go inta da heart of his barrow and destroy him, once and for all. Dat should show dem blood trolls who dey messin' with! I'd help ya, but I be weakened from da blood trolls dat be attackin' me when ya were gone. Don't worry 'bout me, I can still be handlin' dem animals if dey come back.", ["objectivesText"] = "Defeat Zardrax the Empowerer . Progress: We need ta destroy Zardrax. Dis be our chance!", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 155374, 155375, 155378 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.31, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5416, ["name"] = "Zardax's Offer", ["orderIndex"] = 6, ["flags"] = 0 } } },
[48871] = { ["id"] = 48871, ["name"] = "Rescue the Relics", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48871 }, ["series"] = { 50535, 50536 }, ["description"] = "According to the information you brought us, we should be adding those relics to our collection. Explore the ruins and see if you can find any of these \"tokens of affection\" the sethrak may have left for their Keepers. Better we find hands that will cherish them, than ones that will destroy. Plus, add a little time, and anything becomes interesting... to the right people.", ["objectivesText"] = "Collect 8 Ahjani Relics in Zul'Ahjin. Progress: Did you find the relics?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 152787 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134148, ["x"] = 0.472, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134148, ["x"] = 0.472, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[48872] = { ["id"] = 48872, ["name"] = "Expedite the Excavation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48872 }, ["series"] = { 50596 }, ["description"] = "Everywhere we go, there they are. Sethrak. And it's never the ones you want to see. It seems they are looking for some key. With this new information, I do not think they are looking in the right place. Really, as entertaining as it is to confound them, we need to wrap up our work here and move on. If you could remove some of them, it would greatly help our crew!", ["objectivesText"] = "Slay 12 Sethrak in the Ruins. Progress: I need to mark this down. How many sethrak have you killed?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134164, ["x"] = 0.474, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134164, ["x"] = 0.474, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[48873] = { ["id"] = 48873, ["name"] = "A Grizzly End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48873, 48874, 48879, 48909, 49039, 49066, 49072 }, ["description"] = "This lodge serves as the largest supplier of furs and leather to Boralus. <Kennings puffs out his chest a bit.> And as its proprietor, it is my duty to ensure every request is met on time. With recent delays, I've decided to take a trip out here to see if the Holtons need my assistance. We could use any available hands! Take this knife and bring back some pelts from the bears in the nearby pass.", ["objectivesText"] = "Skin 6 Monstrous Grizzlies . Progress: I see that Lord Kennings ' idea of assistance hasn't changed since his last visit.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152800, 152801 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127646, ["x"] = 0.758, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127161, ["x"] = 0.758, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5433, ["name"] = "A Mountain Retreat", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48874] = { ["id"] = 48874, ["name"] = "Pardon Our Rust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48873, 48874, 48879, 48909, 49039, 49066, 49072 }, ["description"] = "The traps we've set up in the field require routine maintenance checks. Some of them are fairly old and will spring at incorrect times. If only we could get more funding for these sort of supplies. <The huntmistress glances towards Lord Kennings.> While you're out hunting, could you reset any sprung ones that you find?", ["objectivesText"] = "Arm 5 Bear Traps.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127161, ["x"] = 0.758, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127161, ["x"] = 0.758, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5433, ["name"] = "A Mountain Retreat", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48879] = { ["id"] = 48879, ["name"] = "A Hunt for Hawk Eggs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48873, 48874, 48879, 48909, 49039, 49066, 49072 }, ["description"] = "Before Alanna sends us on our grand hunt, there is something more immediate demanding our attention... I'm absolutely famished! No good man can hunt on an empty stomach. There are hawks in the area, which means that there are also hawk eggs . I'm not sure how well they'll do in an omelet, but I'm always one for a culinary adventure! Good <class>, could you bring back a few before we get started?", ["objectivesText"] = "Gather 12 Hawk Eggs . Progress: Have you found enough eggs yet? You know what those small goblins say, time is money!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152817 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127646, ["x"] = 0.758, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127646, ["x"] = 0.758, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5433, ["name"] = "A Mountain Retreat", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48880] = { ["id"] = 48880, ["name"] = "Mean Gulls", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48880, 48881, 48882, 48883, 48904 }, ["description"] = "Must... catch... Need more... The gulls... they bite... scratch... take... I need them gone... but... I must... catch...", ["objectivesText"] = "Kill 10 Territorial River Gulls near Mudfish Lodge.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5446, ["name"] = "A Fishing Shack", ["orderIndex"] = 0, ["flags"] = 0 } } },
[48881] = { ["id"] = 48881, ["name"] = "The Reel Deal", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48880, 48881, 48882, 48883, 48904 }, ["description"] = "<These fishing rods must have been left behind when Art moved from the beach. Most of them seem to have bites. Maybe you should reel them up and see what's hooked?>", ["objectivesText"] = "Reel in 5 Fishing Rods in Snapclaw Shore.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 152868 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5446, ["name"] = "A Fishing Shack", ["orderIndex"] = 3, ["flags"] = 0 } } },
[48882] = { ["id"] = 48882, ["name"] = "I Like Fish Guts and I Cannot Lie", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48880, 48881, 48882, 48883, 48904 }, ["description"] = "<It looks like some of the fish the gulls have been stealing from Art are still intact. He'd probably be happy to get the innards from these as well.>", ["objectivesText"] = "Collect 9 Mudfish Innards from Intact Mudfish near Mudfish Lodge. Progress: What's... this?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152845 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5446, ["name"] = "A Fishing Shack", ["orderIndex"] = 2, ["flags"] = 0 } } },
[48883] = { ["id"] = 48883, ["name"] = "Big Gulls Won't Die", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48880, 48881, 48882, 48883, 48904 }, ["description"] = "Still one more... takes my bait... my fish... My finger... Kill him... you will be... rewarded...", ["objectivesText"] = "Kill Brinebeak in Mudfish Lodge. Progress: Must... catch...", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 7307, 19803, 19969, 152845, 152868, 155459, 155468, 155476, 155484, 160578 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5446, ["name"] = "A Fishing Shack", ["orderIndex"] = 4, ["flags"] = 0 } } },
[48887] = { ["id"] = 48887, ["name"] = "Cleanse the Mind", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "If you wish to invite Akunda into your mind, it can't be bogged down by fear or regret. Meditate at de Shrine of Thunder and confront whatever demons linger in de dark recesses of your mind.", ["objectivesText"] = "Meditate at the Shrine of Thunder and confront your inner demons . Progress: Some who meditate at de shrine hear de voice of de loa himself, though most only hear silence or de sounds of their failings.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 95566 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 22, ["flags"] = 0 } } },
[48888] = { ["id"] = 48888, ["name"] = "It Springs Eternal", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Water is a sacred resource in dese dunes, but those within dis temple never know thirst. Akunda commands de storm, allowing de nearby spring to never run empty. Unfortunately, our eternal water source attracts a variety of animals dat are a plague upon our temple. Rid de valley of their presence before you return.", ["objectivesText"] = "Kill Redrock Scavengers and Redrock Howlers near The Eternal Spring.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 23, ["flags"] = 0 } } },
[48889] = { ["id"] = 48889, ["name"] = "Repairing the Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Dis explains why de loa has been silent. Akunda himself has forgotten who he is! Someone or something must be abusing his power. We won't know how to help without speaking to de loa. I can perform a ritual dat may repair Akunda 's mind, but it is not without risk.", ["objectivesText"] = "Protect Meijani while she repairs Akunda 's mind.", ["rewardGold"] = 442560, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127989, ["x"] = 0.525333, ["y"] = 0.792667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 138382, ["x"] = 0.522, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.792667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 30, ["flags"] = 0 } } },
[48894] = { ["id"] = 48894, ["name"] = "Trial of Truth", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Those within our temple have left their past lives behind. They devote themselves entirely to Akunda. Dis final test is perhaps de most important. Dis is de moment of truth. You will speak your name, as you will be known from dis day forth.", ["objectivesText"] = "Speak your name to Akunda the Exalted .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127966, ["x"] = 0.532, ["y"] = 0.911 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 24, ["flags"] = 0 } } },
[48895] = { ["id"] = 48895, ["name"] = "The Perfect Offering", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["series"] = { 48684 }, ["description"] = "Dis offering is all dat I have to my name, but it wouldn't be right for me to use it for myself when I know your friend is in danger. She saved my life, now I can save hers. Take de offering. Don't make me ask twice.", ["objectivesText"] = "Deliver the offering to Akunda the Exalted at the Temple of Akunda. Progress: Do you come bearing gifts to our loa?", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 152894 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127691, ["x"] = 0.528, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 19, ["flags"] = 0 } } },
[48896] = { ["id"] = 48896, ["name"] = "Knowledge of the Past", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47716, 48313, 48314, 48315, 48896, 50539, 50561, 50770 }, ["description"] = "An old friend of mine came to de sands willingly to gain knowledge of de past. If anyone can locate dis weapon, it would be Julwaba. Last I heard, she planned to excavate de ruins surrounding de great pyramid.", ["objectivesText"] = "Travel with Meerah's Caravan in search of Julwaba. Progress: How did Jarka'zet's men know where we'd be?", ["rewardGold"] = 241020, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 130667, ["x"] = 0.5325, ["y"] = 0.9055 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.5325, ["y"] = 0.9055 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 608, ["name"] = "A City of Secrets", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 34, ["flags"] = 0 } } },
[48898] = { ["id"] = 48898, ["name"] = "Lucky Charm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48898 }, ["description"] = "My daddy would never admit it, but he's really superstitious. I don't think he'll ever feel safe on a horse unless he has a lucky charm! I heard about a fox somewhere around here that's been eating a lot of chickens, and escaping everybody trying to catch him. I bet he's really lucky! Maybe if you got his tail and gave it to my dad, he'd feel lucky too!", ["objectivesText"] = "Collect Lucktail's Tail from Lucktail in Rockskip Falls. Progress: Tails are real lucky, <name>. I think this one will give my dad heaps of courage!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 152848 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127586, ["x"] = 0.511, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127586, ["x"] = 0.511, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.511, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48899] = { ["id"] = 48899, ["name"] = "Safety First", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48899 }, ["description"] = "The connection between horse and rider is fascinating to me, and I will never truly understand until I experience it. But, well, you know... armor! How could I possibly even think to mount one of these beauties without some proper protection? I saw some waterfalls nearby. There must be shells near the banks of its pools! Would you entertain an old Tortollan by collecting some for his safety?", ["objectivesText"] = "Collect 8 Durable Seashells in Rockskip Falls. Progress: Protection, yes. Can't put yourself in a dangerous situation without the proper protection!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 152847 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127492, ["x"] = 0.512, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127492, ["x"] = 0.512, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48902] = { ["id"] = 48902, ["name"] = "Monstrous Energy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48902 }, ["description"] = "Have you ever heard about eel juice? I don't know if it's safe for <race>s like you, but tortollans love it! It gives us a burst of energy, and puts a spring in the step of even the oldest tortollan. I saw some eels to the north of the estate when we were traveling. Can you go collect some of their venom for my dad?", ["objectivesText"] = "Collect 6 Pulsating Extract from Venomscale Slitherers in Rockskip Falls. Progress: My dad will be so excited when he sees his favorite drink!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 152849 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127586, ["x"] = 0.511, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127586, ["x"] = 0.511, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.511, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48903] = { ["id"] = 48903, ["name"] = "The Perfect Horse, of Course", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48903 }, ["description"] = "With all that you've collected for me... I guess it is time to mount, isn't it? Hoo! I haven't felt such nerves for three hundred years! Would you mind assisting me in finding a suitable equine partner? I could not trust myself to make the decision alone!", ["objectivesText"] = "Assist Majo in choosing and mounting a horse. Progress: My dad thinks horses can have lots of personalities, just like us. We gotta find him the perfect horse for his first ride!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 155082, 158229, 158267 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127492, ["x"] = 0.512, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48904] = { ["id"] = 48904, ["name"] = "Take the Bait", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48880, 48881, 48882, 48883, 48904 }, ["description"] = "The bait... almost gone now... must catch... The crabs... find them... get more...", ["objectivesText"] = "Collect 15 Snapclaw Meat from Snapclaw crabs in Snapclaw Shore. Progress: Almost gone...", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 152865 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127558, ["x"] = 0.718, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5446, ["name"] = "A Fishing Shack", ["orderIndex"] = 1, ["flags"] = 0 } } },
[48905] = { ["id"] = 48905, ["name"] = "Unappreciated Scrolls", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["storyline"] = { 48905 }, ["description"] = "Since you're here in Natha'vor, you might as well help out the rest of the pilgrimage with a problem. These trolls have stolen several of our scrolls. Why they would, I have no idea, I doubt they're smart enough to even read. I want you to get them back. I'm not young anymore, I can't just be casting magic off the top of my head! Especially healing magic... which I'm sure Shoak is going to need when you rescue his dumb shell.", ["objectivesText"] = "Recover 8 Tortollan Scrolls .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152864 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[48909] = { ["id"] = 48909, ["name"] = "Noble Responsibilities", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48873, 48874, 48879, 48909, 49039, 49066, 49072 }, ["description"] = "From the state of this body, I would say a beast with formidable claws or fangs ravaged this camp. You say the trail leads westward? This camp usually houses more than one of Alanna's hunters. I wonder if they are tracking the beast down as well. Hurry it up! I don't want to spend the day waiting around. Track our dangerous quarry!", ["objectivesText"] = "Track and kill the murdering monster.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 155089, 158280, 158281, 158282, 158283 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127481, ["x"] = 0.708, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127161, ["x"] = 0.758, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5433, ["name"] = "A Mountain Retreat", ["orderIndex"] = 5, ["flags"] = 0 } } },
[48913] = { ["id"] = 48913, ["name"] = "Monalite Deposit - Rank 1 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 48913 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
