[48934] = { ["id"] = 48934, ["name"] = "Mark of the Damned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48934 }, ["objectivesText"] = "Corrupted Spirits disrupted Ancient Spirits slain", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Corrupted Spirits disrupted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Ancient Spirits slain", ["amount"] = 34, ["type"] = 0, ["objectID"] = 123039, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863 },
[48939] = { ["id"] = 48939, ["name"] = "Show Me What You've Got", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48939 }, ["description"] = "It looks like you understand the basics. Now it's time to put everything together. Head for the ring. Once you hear the starting pistol, you will have one minute to score as high as possible. Gnolls are worth one point. Run 'em through with the harpoon! If you see a paper zeppelin, bag it with your bolas for fifty points! Leaping fences gives you style. Style gives you more points when you skewer gnolls or down zeppelins. It's super important, so don't forget to keep jumping fences!", ["objectivesText"] = "Mount Cooper to begin your show and score at least 150 points. Progress: Kul Tiran riding is a true show of mastery and sport!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 151913, 152109, 152642, 152643, 152670, 152671, 152675, 152678, 153357 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48941] = { ["id"] = 48941, ["name"] = "A Slight Detour", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "If this coven is drawing its power from these ancient ruins, then I may just know of something that could help us fight back. Meet me at the first fork along the Highroad Pass. There is something there I want you to see.", ["objectivesText"] = "Meet with Lucille Waycrest at Highroad Pass in Drustvar .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 153053, 159748 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 26, ["flags"] = 0 } } },
[48942] = { ["id"] = 48942, ["name"] = "Yeti to Rumble", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "It would seem that the guard have been lax in patrolling the Highroad Pass. The mountain yetis have taken advantage of their absence, and now lie directly in our path. I am no soldier, <class>, so I will need to ask that you take care of them while I try to sneak past. If we can drive them off the road, at least it will make the pass safe again for travelers.", ["objectivesText"] = "Kill 8 Chillfur Yetis in Alpine Rise. Progress: We should drive the yetis back from the road. Having a major trade route cut off by monsters isn't going to help our fight against the coven.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 153053, 159748 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.4416, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 27, ["flags"] = 0 } } },
[48943] = { ["id"] = 48943, ["name"] = "Salvage Rights", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "This poor trader was set upon by the yetis. There's nothing we can do for him now, but we would be remiss to let his supplies be laid to waste by these brutes. See if you can find any supplies worth salvaging. You can use Bella as a pack horse. Don't worry, she's a brave mare. She won't spook easily.", ["objectivesText"] = "Recover the Wrapped Supplies, Cask of Salted Fish, Hardened Lockbox, and Bucket of Grain from Alpine Rise. Progress: Have you found anything salvageable?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 153053, 159748 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.4416, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 28, ["flags"] = 0 } } },
[48944] = { ["id"] = 48944, ["name"] = "Unlocking History", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "I'm sure you're wondering why I've brought you here. Located somewhere inside this cottage is a hidden door. If we can find a way to access it, the answer to your questions, and possibly our survival against the coven, should lie beyond. Help me search for it, <class>.", ["objectivesText"] = "Find the secret passageway in the Forgotten Lodge. Progress: The opening must be here somewhere...", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 153053 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.4416, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 30, ["flags"] = 0 } } },
[48945] = { ["id"] = 48945, ["name"] = "The Ruins of Gol Var", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "What lies beyond are more ruins, much like those the coven sought. However, these ruins served a different purpose, one that established the legacy of House Waycrest thousands of years ago. Let us head inside, and I will explain.", ["objectivesText"] = "Escort Lucille Waycrest into Gol Var. Progress: Just a little further...", ["rewardGold"] = 929400, ["rewardXP"] = 4150, ["rewardItems"] = { 153053 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.4416, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 31, ["flags"] = 0 } } },
[48946] = { ["id"] = 48946, ["name"] = "The Order of Embers", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "The Order of Embers was the name given to those who took up these arms against the Drust. Using the tools and methods uncovered by the scholars, they were able to counter the Drust's magic, and ensure our victory in the war. If the coven wants to use the Drust's magic against us, then we'll use the order's weapons against them. The knowledge of the order rests here, but without a hand to wield it, it will do us no good. Will you be that hand, <class>? Will you revive the Order of Embers?", ["objectivesText"] = "Take the Tome of Silver and Ash in Gol Var. Progress: What say you?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 153053 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.4416, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 32, ["flags"] = 0 } } },
[48947] = { ["id"] = 48947, ["name"] = "Gol Koval", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48947 }, ["description"] = "A group of hunters went up into the hills awhile ago and we haven't heard back from them. My niece is up there and it isn't like her to be out of touch for so long! Would you please find her? She was headed towards Gol Koval.", ["objectivesText"] = "Find Rebecca Hale in Gol Koval.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127743, ["x"] = 0.694667, ["y"] = 0.435333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125457, ["x"] = 0.645, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.694667, ["y"] = 0.435333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[48948] = { ["id"] = 48948, ["name"] = "The North Pass Caverns", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48948 }, ["description"] = "Please, you must help! My grandson got lost around the caves to the north, and I'm so afraid that the troggs might have got him! My husband went after him, but he's getting on in years, and I fear he imagines himself tougher than he really is. Could you help them? You should be able to catch up with Thaddeus along the northern road.", ["objectivesText"] = "Find Thaddeus Rifthold near the North Pass Caverns.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 128457, ["x"] = 0.552, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127015, ["x"] = 0.516667, ["y"] = 0.252667 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[48949] = { ["id"] = 48949, ["name"] = "Weeds of the Mire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 48949 }, ["description"] = "<Magura weakly opens her eyes as you approach.> Help me... weak... can't heal... <Magura struggles to raise an arm to point towards a nearby plant.> Graveweed... help... more... please...", ["objectivesText"] = "Collect 6 sprigs of Graveweed from the Dreadmire.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152895 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[48958] = { ["id"] = 48958, ["name"] = "Ritual Interruption", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8899, ["mapID"] = 885, ["storyline"] = { 48958 }, ["objectivesText"] = "Banish the Everburning Doombringer", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 152465 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8899 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Banish the Everburning Doombringer", ["amount"] = 1, ["type"] = 0, ["objectID"] = 127811, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 885, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[48963] = { ["id"] = 48963, ["name"] = "Diversionary Tactics", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "Our destination is that cottage up ahead. I know it doesn't look like much, but a great deal of history is hidden inside. First, though, we'll need to deal with that massive yeti camped just outside. I'd hate to ask it of you, but I'll need you to draw his attention so I can slip inside. Once you've taken care of him, I'll meet you within.", ["objectivesText"] = "Defeat Frostmange in Alpine Rise. Progress: I'll meet you inside, <class>.", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 153053, 159748 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.4416, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 29, ["flags"] = 0 } } },
[48965] = { ["id"] = 48965, ["name"] = "Settle the Score", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48965 }, ["description"] = "A year ago I lost my daughter to the largest boar in the forest. I have tracked him since, trading blows back and forth. But this time... Let's just say I don't have much time left. All I wish for is vengeance. Please <class>, avenge us so that my soul can leave this plane and join my daughter, wherever she may be.", ["objectivesText"] = "Kill Chartusk in Foxhollow Woods. Progress: Though my lifeblood drains, all I yearn for is vengeance.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 39676, 39678, 39679, 39680 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127803, ["x"] = 0.582, ["y"] = 0.254 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127803, ["x"] = 0.582, ["y"] = 0.254 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.254 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[48986] = { ["id"] = 48986, ["name"] = "Take the High Road", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48986, 49443, 49803, 49804, 49805, 49806, 49807 }, ["description"] = "Let us continue to Arom's Stand. It will take some time to parse the knowledge of the tome and train more inquisitors for our cause. If the order's weapons are as effective against the coven as they were against the Drust, we may stand a chance of rescuing my family and restoring this land to its former glory. I will make my way there on foot. Until we meet again, <class>.", ["objectivesText"] = "Meet with Lucille Waycrest at Arom's Stand in Drustvar .", ["rewardGold"] = 28090, ["rewardItems"] = { 156515, 156518, 156532, 163607 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.4416, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 597, ["name"] = "Arom's Stand", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 33, ["flags"] = 0 } } },
[48987] = { ["id"] = 48987, ["name"] = "Valley of Sorrows", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Your friend's memories are gone. Dat is Akunda's gift to us. He takes away our painful memories, but a lot more than dat has gone missing lately. I can't even remember what I had for breakfast, and it's getting worse by de day. Something's not right. Meijani and I had a plan. We were going to do... something... in de Valley of Sorrows. It's where Akunda keeps de forgotten memories. If you're looking for answers, finding Meijani is de best place to start.", ["objectivesText"] = "Find Meijani in the Valley of Sorrows.", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127980, ["x"] = 0.535, ["y"] = 0.914 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127989, ["x"] = 0.525333, ["y"] = 0.792667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.914 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 27, ["flags"] = 0 } } },
[48988] = { ["id"] = 48988, ["name"] = "Memory Breach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "De memories of Akunda's followers rest within dis valley. Most are best left forgotten, but dey may be our only chance to find out what happened to Akunda. Look back upon de memories here. See if you can find any clues about what happened to our loa. Be warned. Dis task is not for de weak. What you witness in dese memories can't be unseen.", ["objectivesText"] = "Look for clues within Unwanted Memories. Progress: Peer into de memories. See what you can find.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127989, ["x"] = 0.525333, ["y"] = 0.792667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127989, ["x"] = 0.525333, ["y"] = 0.792667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.792667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 28, ["flags"] = 0 } } },
[48991] = { ["id"] = 48991, ["name"] = "Vile Infestation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Redemption must be earned. We do good works to show Akunda we are worthy of his blessing. De ranishu are a plague upon these lands. Dey devour everything in sight, with no regard for taste or texture. If dey go unchecked, those vile pests will eat their way straight to de temple. Rid de mesa of their presence. Show Akunda you are worthy of his gift.", ["objectivesText"] = "Slay 12 ranishu in Redrock Mesa.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 21, ["flags"] = 0 } } },
[48992] = { ["id"] = 48992, ["name"] = "Sacred Remains", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Dis area was once a lush jungle, home to many great and powerful thunder lizards. De bones of those ancient and powerful creatures are still buried around de temple. Great power lingers within those ancient remains... you will need such power to call upon Akunda. Search de area and return to me with de ancient bones of de thunder lizards.", ["objectivesText"] = "Collect 6 Sacred Remains . Progress: Have you found de ancient bones?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 153028 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 20, ["flags"] = 0 } } },
[48993] = { ["id"] = 48993, ["name"] = "Powerful Conductors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Akunda offers us a chance to start anew. Through a sacred ritual, de loa enters our mind and removes de memories dat cause us pain. If you seek Akunda's blessing, den you must first prepare for de ritual. De pests dat feed on de wildlife here have antennae dat are great conductors for magic. De larger, de better. Their leader's antennae should do de trick. He's easily three times de size of de normal ranishu.", ["objectivesText"] = "Retrieve Rorgog's Antennae . Progress: Do you have de antennae?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 153029, 155451, 159979 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127992, ["x"] = 0.532, ["y"] = 0.902 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.902 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 13, ["flags"] = 0 } } },
[48996] = { ["id"] = 48996, ["name"] = "Ending the Madness", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Akunda the Exalted is not who he seems. He poisoned the eternal spring, sickening all who drank from it. Even I was not immune to his abhorrent alchemy. Now he drains my power, abusing my gift to wipe the minds of all who might try to stop him. We will not let him succeed. What little power I have left, I will lend to you. Use it to call the storm and end the madness that has taken over my temple.", ["objectivesText"] = "Defeat Akunda the Exalted .", ["rewardGold"] = 842700, ["rewardXP"] = 6175, ["rewardItems"] = { 155385, 155386, 155387, 155404, 155405, 155406, 155407, 155408 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 138382, ["x"] = 0.522, ["y"] = 0.798 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128152, ["x"] = 0.532, ["y"] = 0.915 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 31, ["flags"] = 0 } } },
[49001] = { ["id"] = 49001, ["name"] = "Inconvenient Spirits", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48330, 48331, 48332, 48334, 48335, 49001, 49139 }, ["series"] = { 48322, 48335, 48840 }, ["description"] = "The sethrak have oppressed vulpera like me for countless generations. You can't fight 'em. Trust me, $pr. My caravan tried. I took that beating as a lesson, and then I found a new pack to run with. Here, we keep our distance from the sethrak and scavenge ruins like this one for anything valuable we can use or trade. You want in? We could use a fourth. This one's protected by nasty spirits that keep harassing us. Take them out and you're in.", ["objectivesText"] = "Kill 8 Tortured Spirits . Progress: I've never met a spirit that made my day better.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129453, ["x"] = 0.454, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129453, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5425, ["name"] = "Court of Zak'rajan", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49002] = { ["id"] = 49002, ["name"] = "Forced Grounding", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "<This is one of the spears that Faithless trappers use to pull pterrordaxes to the ground. It has a long chain attached to its base. With good aim, you could use it to pull a Faithless pterrordax rider to the ground so you could fight them.>", ["objectivesText"] = "Use the Faithless Trapper's Spear to pull Fangcaller Hrillik 's pterrordax down from the sky above you, and kill him. Progress: <Rakjan lifts his head proudly.>", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 137663, 154893, 161166, 161167 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129763, ["x"] = 0.472, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49003] = { ["id"] = 49003, ["name"] = "Vengeance From Above", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["series"] = { 49141 }, ["description"] = "Emperor Korthek hides deep in his stolen temple below ground. We must create such chaos that he has no choice but to emerge to face us. The vulpera riot is a good start, but it will not be enough. Alone, they are no match for the Faithless army. Thankfully, they are not alone. We will ride the mighty Rakjan through the skies. While you throw lightning bombs, I'll use my charged staff to blast the Faithless armies below. Let us hope that is enough to lure out Korthek. I am eager to finish this.", ["objectivesText"] = "Ride Rakjan the Unbroken and kill Faithless.", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135110, ["x"] = 0.476, ["y"] = 0.377 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135111, ["x"] = 0.52, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.377 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 55, ["flags"] = 0 } } },
[49005] = { ["id"] = 49005, ["name"] = "Shattered and Broken", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Something is terribly wrong. Unwanted memories have been released from their magical confines. Akunda's power is supposed to keep dem sealed away... De physical manifestation of our most haunting memories have no place in dis world. Dey must be destroyed.", ["objectivesText"] = "Kill Fractured and Distorted Memories .", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 155455, 161268, 161270, 161272, 161274 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127989, ["x"] = 0.525333, ["y"] = 0.792667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 127989, ["x"] = 0.525333, ["y"] = 0.792667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.525333, ["y"] = 0.792667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 607, ["name"] = "The Warguard's Fate", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 29, ["flags"] = 0 } } },
[49013] = { ["id"] = 49013, ["name"] = "A Jolt of Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49013 }, ["description"] = "I have you to thank for removing that usurper. My strength is returning, unfortunately, the damage to my children has already been done. They are weak and dying. I need you to restore them. My blessing will give you power over the storms. Use it to save my children, as you have saved me.", ["objectivesText"] = "Use the Blessing of Akunda to revive Stormhide Lizards.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Stormhide Lizards revived", ["amount"] = 6, ["type"] = 0, ["objectID"] = 134743, ["orderIndex"] = 0 }, { ["text"] = "Ranishu killed", ["amount"] = 8, ["type"] = 0, ["objectID"] = 133565, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[49028] = { ["id"] = 49028, ["name"] = "A Sweater for Rupert", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49028 }, ["description"] = "The nights are cold in this area, and I am worried my poor dog will freeze to death. I wish to sew him a sweater, but I have no materials to make one with. I would pay anyone who brings me a pair of porcupine quills and four raccoon tails. - Kolta", ["objectivesText"] = "Collect Kolta 's materials. Progress: Is there something you need from me?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152800, 152986, 152988 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127217, ["x"] = 0.766, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49032] = { ["id"] = 49032, ["name"] = "Antorus, the Burning Throne: Dark Passage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8638, ["storyline"] = { 49032 }, ["description"] = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks. If we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", ["objectivesText"] = "Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Normal Difficulty. Progress: Without the runes, we must face Sargeras' army head on.", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 152902, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8638 } }, ["questType"] = "raid" },
[49036] = { ["id"] = 49036, ["name"] = "Best In Show", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49036 }, ["description"] = "Now that the troggs have been taken care of, let's get on with the real show! You've more than proven yourself as a capable rider - ready to get back in the ring and go big? See if you can beat three hundred points!", ["objectivesText"] = "Mount Cooper to begin your show and score at least 300 points. Progress: Some people say you cannot simply ride the horse - you must BECOME the horse. That's poppycock. Just ride the horse.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 158220 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49039] = { ["id"] = 49039, ["name"] = "The Start of a Monster Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48873, 48874, 48879, 48909, 49039, 49066, 49072 }, ["description"] = "This is the closest I've been to a dead body, how exciting! What do you think murdered him? Regardless, it is my duty to ensure the safety of individuals under my employ. With a combination of my wit and bravery, and your practical skills, we should be able to track it down. This will be a tale for the ages! Let's start with looking around the camp, see if you can find any clues.", ["objectivesText"] = "Investigate the camp wreckage. Progress: Did you find anything? I'm still caught up in examining this poor fellow.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 153010 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127481, ["x"] = 0.708, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127481, ["x"] = 0.708, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5433, ["name"] = "A Mountain Retreat", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49040] = { ["id"] = 49040, ["name"] = "Fond Farewells", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49040 }, ["description"] = "Dis is where we part ways, <name>. I'm going to take de name Akunda, and start a new life here. When you find Rakera, and I know you will, give her my thanks. She saved my life, and I'm going to make sure to live a life dat was worth saving. If you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.", ["objectivesText"] = "Deliver Jorak 's Note to B'wizati in Zuldazar. Progress: What is dis?", ["rewardGold"] = 280900, ["rewardXP"] = 2060, ["rewardItems"] = { 153016 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 127691, ["x"] = 0.528, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 127664, ["x"] = 0.402, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 864, 1165 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[49059] = { ["id"] = 49059, ["name"] = "The Bones of Xibala", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 49059 }, ["series"] = { 49274, 49276 }, ["description"] = "Our allies in the Explorers' League have alerted us to an exciting find. They have set up camp in the Xibala region of Zuldazar . Make your way to the camp and help them uncover anything that may advance our cause.", ["objectivesText"] = "Travel to Xibala and meet with Acadia Chistlestone.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49060] = { ["id"] = 49060, ["name"] = "Xibalan Ecology", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49060 }, ["description"] = "I want to take me boys out and really dig our picks in, but every scout I've sent into the ruins just came back half mauled to death. Some didn't come back at all. From what I can tell, the ruins are home to more'n just these spiky grass-eaters. Do you think you could be a peach an' thin their numbers a bit? I'd caution ye against tamperin' with the local ecology an' all, but in the interest of not gettin' eaten I think I'll let ye make the call.", ["objectivesText"] = "Slay 12 Xibalan predators.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131777, ["x"] = 0.412, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131777, ["x"] = 0.412, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49066] = { ["id"] = 49066, ["name"] = "Encase of Emergency", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48873, 48874, 48879, 48909, 49039, 49066, 49072 }, ["description"] = "The cliffs here are well known for the crystal clear ice which forms at their base, and even more so for the elementals that are responsible for such. The hunters in my lodge use shards from the primal bodies to keep their stock frozen for transport. More importantly, think of how useful it could be for making and serving drinks! Let's see if we can't find some elementals and gather shards from them.", ["objectivesText"] = "Collect 20 Pristine Ice Chunks from ice elementals. Progress: I've heard that destroying some of the larger ice structures in the area angers them, so do what you do best and destroy any that you come across!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 153020 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127481, ["x"] = 0.708, ["y"] = 0.62 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127646, ["x"] = 0.758, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5433, ["name"] = "A Mountain Retreat", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49069] = { ["id"] = 49069, ["name"] = "WANTED: Ol' Frostclaw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49069 }, ["description"] = "Old Frostclaw has once again been spotted near the edge of the pass. Hunters in the area are advised to keep caution. This larger than average bear has killed four people to date, I'd hate for you to make it a fifth. Any individual who kills the beast will be rewarded, regardless of their occupation. -Alanna <Below the huntmistress' signature is a child's drawing of a bear with the words \"Ol' Frostclaw\" above it.>", ["objectivesText"] = "Slay Old Frostclaw . Progress: Is this about the wanted sign? You better hurry, a good number of hunters are after it as well.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 158242, 158243, 158244, 158245, 158272, 158273, 158274, 158275 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127161, ["x"] = 0.758, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[49072] = { ["id"] = 49072, ["name"] = "Westward Noble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48873, 48874, 48879, 48909, 49039, 49066, 49072 }, ["description"] = "While I am loath to involve you in this further, I don't have the men to afford an escort for Lord Kennings . If he gets hurt, we'll all be out of a job. Can you make sure he at least made it to the west camp?", ["objectivesText"] = "Find Lord Kennings .", ["rewardGold"] = 280900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 127161, ["x"] = 0.758, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127481, ["x"] = 0.708, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5433, ["name"] = "A Mountain Retreat", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49073] = { ["id"] = 49073, ["name"] = "Ritualistic Denial", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 49073 }, ["description"] = "I can't believe we're dealing with a death loa, a DEAD loa, and blood trolls. This isn't what I had planned today! Look, some of the other tortollans have said there are some blood rituals going on. They were spooked and started heading for the coast when they saw it. Take this scroll and read it near any blood rituals . It should cause it to disperse. Be careful with my scroll! It's old and they don't make them like they used to.", ["objectivesText"] = "Disrupt 3 blood rituals with Kisha's scroll of purging .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 153025 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49075] = { ["id"] = 49075, ["name"] = "Antorus, the Burning Throne: Dark Passage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8638, ["storyline"] = { 49075 }, ["description"] = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks. If we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", ["objectivesText"] = "Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Heroic Difficulty. Progress: Without the runes, we must face Sargeras' army head on.", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 152906, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8638 } }, ["questType"] = "raid" },
[49076] = { ["id"] = 49076, ["name"] = "Antorus, the Burning Throne: Dark Passage", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8638, ["storyline"] = { 49076 }, ["description"] = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks. If we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", ["objectivesText"] = "Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Mythic Difficulty. Progress: Without the runes, we must face Sargeras' army head on.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 152907, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8638 } }, ["questType"] = "raid" },
[49123] = { ["id"] = 49123, ["name"] = "Killer Crawgs", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["storyline"] = { 49123 }, ["description"] = "You heard Torga. We need to be taking de fight to de blood trolls if we want to stop dis herald of G'huun. De blood trolls have monstrous crawgs in a camp nearby. We destroy dem, we weaken de blood trolls! De rest of us will move ahead to find out what else de blood trolls have planned around dis place.", ["objectivesText"] = "Kill 12 Blood Crawgs or their riders.", ["rewardGold"] = 331700, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[49124] = { ["id"] = 49124, ["name"] = "Tortollan Rescue", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["storyline"] = { 49124 }, ["description"] = "If Torga wants us to help you kill the herald of G'huun, then I guess we'll help. First, we need to rescue our people. I found out that the blood trolls are draining the blood of our friends nearby and then feeding them to crawgs! This is no way for a tortollan to die, not after hundred of years gathering stories on Azeroth. Take this scroll. It'll purge whatever blood magic the blood trolls using on my friends. Be careful with my scroll! I want it back in one piece.", ["objectivesText"] = "Rescue 6 Tortollan Captives from the blood trolls using Lashk's Scroll of Purging .", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 153049 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[49133] = { ["id"] = 49133, ["name"] = "Antorus, the Burning Throne: The Heart of Argus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8638, ["storyline"] = { 49133 }, ["description"] = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance. If we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", ["objectivesText"] = "Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Normal Difficulty. Progress: Have you located the sigils?", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 152908, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8638 } }, ["questType"] = "raid" },
[49134] = { ["id"] = 49134, ["name"] = "Antorus, the Burning Throne: The Heart of Argus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8638, ["storyline"] = { 49134 }, ["description"] = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance. If we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", ["objectivesText"] = "Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Heroic Difficulty. Progress: Have you located the sigils?", ["rewardGold"] = 561800, ["rewardXP"] = 7675, ["rewardItems"] = { 152909, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8638 } }, ["questType"] = "raid" },
[49135] = { ["id"] = 49135, ["name"] = "Antorus, the Burning Throne: The Heart of Argus", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8638, ["storyline"] = { 49135 }, ["description"] = "Hatuun tells me that after Argus fell, Sargeras ordered a temple of darkness to be built deep within the planet's core. Little is known of it, for only the titan's most devoted acolytes are given sigils that permit entrance. If we lay claim to these sigils, they could be infused into the Vindicaar. This would allow our forces to stage a direct assault upon the fetid heart of Argus.", ["objectivesText"] = "Collect 4 Sigils of the Dark Titan from Aggramar in Antorus, the Burning Throne on Mythic Difficulty. Progress: Have you located the sigils?", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 152910, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8638 } }, ["questType"] = "raid" },
[49138] = { ["id"] = 49138, ["name"] = "Captain Gulnaku's Treasure", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["storyline"] = { 49138 }, ["description"] = "<This map is poorly drawn and covered in stains, but appears to identify three possible locations where a pirate captain may have buried treasure around the Port of Zem'lan. The treasure could be at any of the three locations. At the bottom of the map, someone scrawled an order: Set traps!>", ["objectivesText"] = "Search for Captain Gulnaku's treasure chest. Progress: <It's firmly locked. You'll need the captain's key to open this.>", ["rewardGold"] = 607600, ["rewardXP"] = 5145, ["rewardItems"] = { 153419, 163633 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "standard", ["startItems"] = { 153359 } },
[49139] = { ["id"] = 49139, ["name"] = "An Army's Arsenal", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48330, 48331, 48332, 48334, 48335, 49001, 49139 }, ["series"] = { 48330, 48332 }, ["description"] = "It's my job to scout out the ruins to identify threats and figure out the best way in. Two storehouses contain the majority of the valuable weaponry in the ruins. Unfortunately, they're guarded by specters, powerful Zandalari spirits bound to this place. I... we need those weapons. Take out the specters so I... we can get to them.", ["objectivesText"] = "Kill the specters of Mugabu and Jam'jen, so Omi can ransack the storehouses.", ["rewardGold"] = 619600, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129451, ["x"] = 0.454, ["y"] = 0.462 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129451, ["x"] = 0.454, ["y"] = 0.462 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.462 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5425, ["name"] = "Court of Zak'rajan", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49141] = { ["id"] = 49141, ["name"] = "Diplomacy and Dominance", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["series"] = { 49003 }, ["description"] = "May I entrust you with my staff, $p? I do not offer this lightly, so do not accept it lightly either. We will need every advantage when we face Emperor Korthek, and I've identified an opportunity to increase the power at our disposal. The Faithless maintain a series of suppression spires on the ridge above us to subjugate the pterrordax. My staff can drain power from the spires to bolster its own potency. Meanwhile, I will recruit a much-needed ally for the next stage of our mission.", ["objectivesText"] = "Use Vorrik's Staff to drain power from 6 Faithless Suppression Spires.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 160510 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135172, ["x"] = 0.4524, ["y"] = 0.3524 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135110, ["x"] = 0.476, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.4524, ["y"] = 0.3524 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 53, ["flags"] = 0 } }, ["startItems"] = { 154895 } },
[49143] = { ["id"] = 49143, ["name"] = "Essence of the Light Mother", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8574, ["mapID"] = 831, ["storyline"] = { 40238, 46213, 47431, 47508, 47526, 47541, 47652, 47653, 47743, 47754, 47771, 48559, 49143 }, ["description"] = "This is a crucial moment, <name>. Our campaign must not lose momentum. Though she has fallen, I still sense Xe'ra's presence all around us. The Light that shone within her heart can yet be a source of strength for our cause. No doubt the loss of Xe'ra has deeply wounded Turalyon. I will do what I can to ease his troubled spirit while you gather the vestiges of the naaru that remain.", ["objectivesText"] = "Collect 3 Vestiges of Light . Progress: Though Xe'ra is gone, her essence can still aid us in our struggle.", ["rewardGold"] = 70225, ["rewardXP"] = 770, ["rewardItems"] = { 153125, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8574 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 291, ["title"] = "Shadows of Argus", ["questLineID"] = 348, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1669, ["db2PoiUiMapID"] = 831, ["questLines"] = { { ["id"] = 348, ["name"] = "The Light Mother", ["orderIndex"] = 11, ["flags"] = 0 } } },
[49178] = { ["id"] = 49178, ["name"] = "My Favorite Things", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48421, 49178, 49218, 49226, 49230 }, ["description"] = "It's tough out here. Pirates. Deadly monsters. Hungry Sam 's seemingly endless battle with indigestion. Nothing sets the nerves at ease like an old keepsake. Somethin' to remind you of home. Somethin' to keep you going. Ask around the camp. Find out what folks might have lost out there in the tideways. If you can bring any of it back, it'd be a mighty kind gesture. Me? Oh... I had a locket... Never mind, it's too small, you'd never find it. It's nothing. Don't worry about it.", ["objectivesText"] = "Ask Friendly Pete , Hungry Sam and Handy Bill about their missing keepsakes, then collect those items from the Wailing Tideway. Progress: We've all lost something in the tides. Some more than others.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49181] = { ["id"] = 49181, ["name"] = "Glimmering Locket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49181 }, ["description"] = "<A glint of metal catches your eye among the gently bobbing flotsam. Digging into the tangled seaweed, you discover a locket of simple, yet sturdy design. Opening the locket reveals a hand-drawn picture of a woman with fiery red bangs. Her arm is around a woman with short-cropped auburn hair, and the two are proudly displaying warm smiles for the artist.>", ["objectivesText"] = "Return the Glimmering Locket to Stabby Jane . Progress: Hm? What's that you've got there?", ["rewardGold"] = 221280, ["rewardXP"] = 1415, ["rewardItems"] = { 153184 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49218] = { ["id"] = 49218, ["name"] = "The Castaways", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48421, 49178, 49218, 49226, 49230 }, ["description"] = "I see the sirens have made another catch. You're lucky they haven't stripped your bones yet. If you need to trade supplies or just warm yourself by the fire, there's a camp up the hill behind me. Everyone there washed up in the tides, just like you. Figure we've got folks from at least four or five shipwrecks now. All banded together, just tryin' to survive. Talk to Stabby Jane . Don't worry about her nickname, she's actually real nice.", ["objectivesText"] = "Speak with Stabby Jane at Castaway Point.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128377, ["x"] = 0.8555, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.8555, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49223] = { ["id"] = 49223, ["name"] = "The Long Con", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49223 }, ["description"] = "Hello again my young friend! I have good news. Our mutual acquaintance Carentan -- the man who scammed us in Freehold -- has finally come out of hiding. I have been communicating with him in letters delivered by various middlemen and even completed a few proxy trades to earn his trust. In our last correspondence, he agreed to meet for an in-person trade. He thinks he is meeting with a Ms. Pixy Spindlespark, gnomish hairdresser with a weakness for poached furs. But he'll be meeting you instead.", ["objectivesText"] = "Slay Carentan . Progress: Don't let him get away this time!", ["rewardGold"] = 929400, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 129940, ["x"] = 0.722667, ["y"] = 0.095467 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 129940, ["x"] = 0.722667, ["y"] = 0.095467 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.722667, ["y"] = 0.095467 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "group" },
[49225] = { ["id"] = 49225, ["name"] = "Chasing the Leader", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49225, 49229, 49232, 49233, 49234, 49260 }, ["series"] = { 50700, 51151 }, ["description"] = "The locals and the league have been working together tae reclaim relics in this here cave up the hill. But it seems that we've angered the previous residents. I think the marines can keep the expedition safe fer now, but I dinna how long they can keep it up. We need yer help before things go south! Find Hilde Firebreaker , the leader of our expedition. She ran back into the cave fer somethin' or another.", ["objectivesText"] = "Find Hilde Firebreaker .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128381, ["x"] = 0.626, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5432, ["name"] = "Cave Diving", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49226] = { ["id"] = 49226, ["name"] = "Silencing the Sisters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48421, 49178, 49218, 49226, 49230 }, ["description"] = "The sirens in this tideway have drawn countless ships to their doom. Wiping them out would be a boon to all seafaring folk. But you can't very well kill all of them. Only a fool would try that. The real dangerous ones are the elders. The \"sisters\" as they're known. Bigger, smarter, and stronger than the younger ones. Their voices carry far out to sea and bring in all the big \"catches.\" I managed to track two of them to a den at the northern end of the tideway, but I can't take them alone.", ["objectivesText"] = "Slay Patheope and Nolpe . Progress: Sirens can be handled with relative ease. The older ones take a bit more work.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49227] = { ["id"] = 49227, ["name"] = "The Master Key", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49227 }, ["description"] = "None of the keys you found were the right fit! We're going to need another plan... I've heard that Overseer Morrison has a master key that can open any lock in the compound. It's dangerous, but I need you to get that key for me! You'll find her running the mining operation inside the cave. Once you get the key, make sure you rescue any vulpera captives that you find. Once you've rescued my friends, meet me back here and release me. Good luck!", ["objectivesText"] = "Obtain Morrison's Master Key and use it to free 8 Vulpera Captives. Progress: You keep your end of the bargain, and I'll keep mine.", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["rewardItems"] = { 153420, 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128422, ["x"] = 0.476, ["y"] = 0.862 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128422, ["x"] = 0.476, ["y"] = 0.862 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.862 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[49229] = { ["id"] = 49229, ["name"] = "The Ruins Fought Back", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49225, 49229, 49232, 49233, 49234, 49260 }, ["description"] = "Something set off a trap in the cave, and then the ruins themselves came tae life. I expect that most of our lads still in that cave aren't in fightin' form. Could ye clear out some of the livin' ruins tae help them escape?", ["objectivesText"] = "Kill 6 Ancient Protectors .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128381, ["x"] = 0.626, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128381, ["x"] = 0.626, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.626, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5432, ["name"] = "Cave Diving", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49230] = { ["id"] = 49230, ["name"] = "Local Flavor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48421, 49178, 49218, 49226, 49230 }, ["description"] = "I'm STARVING. Not actually starving, like when I first got here, but you know... Emotionally starving. Haven't had any luck with the oysters lately, and seaweed soup really upsets my guts. If I eat any more of that stuff, I think the other castaways might actually feed me to the sharks. How about them tidelurkers? They look pretty juicy. Bet you could steam those up real nice. Can you get me some? I'm not much of a hunter. But I'll share it with you!", ["objectivesText"] = "Gather 5 Juicy Lurker Tails . Progress: <Sam's stomach growls audibly.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152514, 153185, 153186, 153187, 153348, 154888, 202268 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128228, ["x"] = 0.854, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128228, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49232] = { ["id"] = 49232, ["name"] = "Salvaging a Disaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8956, ["mapID"] = 895, ["storyline"] = { 49225, 49229, 49232, 49233, 49234, 49260 }, ["description"] = "Birch and I are helping out the expedition with field studies. I'm not much of a fighter, but I can't make another mistake, they might demote me! Could you recover some of the relics we packed up in boxes around the cave?", ["objectivesText"] = "Gather 6 Drust Relics . Progress: Did you find enough relics?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 153349 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8956 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5432, ["name"] = "Cave Diving", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49233] = { ["id"] = 49233, ["name"] = "I'm a Druid, Not a Priest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8956, ["mapID"] = 895, ["storyline"] = { 49225, 49229, 49232, 49233, 49234, 49260 }, ["description"] = "The remains of previous trespassers also arose when we set off the main trap. Cranklefuse here has been demanding that I help them, and while I can't say I'm too familiar with turning the undead, I believe I have found a solution. I've modified my staff to remove their curse. Take it and see if you can't help them.", ["objectivesText"] = "Free 5 cursed raiders. Progress: Have you tried out that staff yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 153350 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8956 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5432, ["name"] = "Cave Diving", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49234] = { ["id"] = 49234, ["name"] = "A Marine Out of Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49225, 49229, 49232, 49233, 49234, 49260 }, ["description"] = "A giant one of those stone creatures killed quite a few marines while we were trying to evacuate the cave. It didn't chase us too far, but ignoring it outright is too big of a risk. It needs to fall!", ["objectivesText"] = "Kill the Awakened Guardian .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 158250, 158251, 158252, 158253, 158254, 158255, 158256, 158257 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130101, ["x"] = 0.628, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130101, ["x"] = 0.628, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5432, ["name"] = "Cave Diving", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49239] = { ["id"] = 49239, ["name"] = "Dress to Impress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["description"] = "Freehold used to be open to anyone, but now it seems the Irontide Raiders have declared themselves the owners. They're locking the place down and turning away anyone who isn't part of the crew. Fortunately, they're also hiring. Put this on. Don't think about where it came from. We'll pose as new recruits, get in, gather some information, and be back in Boralus in time for supper! Cyrus may be salty, but he's a decent cook.", ["objectivesText"] = "Put on the Irontide Hat and enter Freehold with Flynn.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153355, 153509, 153680, 153681, 153682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 24, ["flags"] = 0 } } },
[49242] = { ["id"] = 49242, ["name"] = "Quill or Be Quilled", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48198, 48283, 49242 }, ["description"] = "Oh, hello there. Sorry, we don't get many mainlanders in these parts. This plot was my husband Sam's farm. He used to tend to the onion fields every day before the curse befell Glenbrook and took him with it. With my husband gone, this farm is all I have left, and these quillrats are making sure I don't get even that. I'd hate to bother a perfect stranger, but could you help quell this infestation?", ["objectivesText"] = "Kill 6 Territorial Quillrats in Hawthorne's Plot. Progress: These quillrats are truly a menace!", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 128494, ["x"] = 0.668, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 128494, ["x"] = 0.668, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 382, ["name"] = "Hangman's Point", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49259] = { ["id"] = 49259, ["name"] = "And Justice For All", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48941, 48942, 48943, 48944, 48945, 48946, 48963, 49259 }, ["description"] = "Thank you for helping to redeem me in the eyes of my people, <class>. I am in your debt, and I will be sure to let my father know. In the mean time, I think we should find out what this Heartsbane Coven is, and what they are doing in our lands. I hope the marshal will be able to enlighten us. First thing's first, though. Care to undo these ropes? They're starting to chafe.", ["objectivesText"] = "Leave Hangman's Point with Lucille Waycrest . Progress: Shall we?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 21395, 21396, 21397, 33271, 39770, 39776, 39778, 39818, 39833, 57829, 118154, 118155, 118156, 118157, 153053, 155126, 155130, 155143, 155148, 155152, 155583, 155584, 156976, 158646, 158647, 159536, 174294, 177055, 178158, 179945, 191604, 197661, 197662, 197663, 197664, 211279, 225946, 237812 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 125380, ["x"] = 0.697, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.697, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 384, ["name"] = "Alpine Rise", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 16, ["flags"] = 0 } } },
[49260] = { ["id"] = 49260, ["name"] = "Backup While I Pack Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8956, ["mapID"] = 895, ["storyline"] = { 49225, 49229, 49232, 49233, 49234, 49260 }, ["description"] = "I came in here tae try an' reclaim as many relics as possible. Sneakin' in was easy, but I'm worried about things noticin' me while I pack up. Mind watching me back while I get the relics stored in a safe place in my bag?", ["objectivesText"] = "Protect Archaeologist Firebreaker.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8956 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5432, ["name"] = "Cave Diving", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49261] = { ["id"] = 49261, ["name"] = "Crabby Crew Stew", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49261 }, ["description"] = "Shouldn't you be in the mines? Look, I won't tell Morrison if you won't. I wouldn't want to be stuck in those mines, either. We could use a hand out here, though. The crew is getting crabby. We've been eating nothing but slop and the occasional rat for weeks. I hear one of the deckhands makes a marvelous crab stew. Can I count on you to secure the meat?", ["objectivesText"] = "Collect Lumpy Crab Meat from Sand Scuttlers. Progress: It'll be nice to eat something other than rat for a change.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 151627, 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128618, ["x"] = 0.445, ["y"] = 0.882 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128618, ["x"] = 0.445, ["y"] = 0.882 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.882 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[49262] = { ["id"] = 49262, ["name"] = "Gang Bustin'", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49262 }, ["description"] = "It's difficult to run a tight ship when you're so far from home. The crew has a tendency to get restless when they've been landlocked for too long. I've heard reports of deckhands sneakin' around and stealin' supplies. If the crew thinks they can steal from our employer on my watch, they've got another thing comin'! I need someone to crack down on these shady deals and send a message to the crew. Thievin' won't be tolerated!", ["objectivesText"] = "Confront 8 Shady Deckhands. Progress: We murder mutineers 'round here.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128618, ["x"] = 0.445, ["y"] = 0.882 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128618, ["x"] = 0.445, ["y"] = 0.882 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.882 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[49268] = { ["id"] = 49268, ["name"] = "Sharks in the Water", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "Recently a large gam of sharks has moved into the shallower water in the harbor. I have dealt with minor illnesses before that were caused by creatures carrying foreign contaminants to shore. Perhaps the sharks have brought something in from the deeper waters? Cull some of the sharks that have wandered too close to the pier. I shall read the tides for any changes.", ["objectivesText"] = "Kill 6 Invading Dreadmaws .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49274] = { ["id"] = 49274, ["name"] = "Morgrum's Survey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49274 }, ["series"] = { 49059, 49276 }, ["description"] = "Oi. Since yer hands are already dirty, what do ye say we make a deal? To give it to ye straight, there's a relic here called the Breath of Xibala. I don't know who Xibala is or why the Alliance wants its breath, but there's a hefty sum of gold in it fer me if we deliver. That means there's somethin' in it for you, too, if ye get my meanin'. I started a survey with me equipment but haven't got me results yet. Go on out into the ruins an' give the boxes you see a little kick to hurry things along.", ["objectivesText"] = "Check on Excavator Morgrum Emberflint 's survey equipment in the Ruins of Xibala. Progress: I'll be countin' me own gold if ye don't want to lend a hand.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.429333, ["y"] = 0.732667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49276] = { ["id"] = 49276, ["name"] = "The Thrill of Exploration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49276 }, ["series"] = { 49059, 49274 }, ["description"] = "Name's Acadia, Acadia Chistlestone ! I represent the interests of the Explorers' League at this site. Where there's dirt to be turned, we're happy to do the digging! <Acadia's smile falters.> These Dark Iron, though, they're keen on delving deeper and faster than I'm comfortable with. Since you're a strong, capable member of the Alliance, do you think you could ah... lead by example? Go on, there's a fresh fossil here that could use some attention.", ["objectivesText"] = "Help Acadia Chistlestone recover a Xibalan fossil. Progress: Acadia tells me you're in charge, now. We'll see about that.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131777, ["x"] = 0.412, ["y"] = 0.714 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.714 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49282] = { ["id"] = 49282, ["name"] = "Morgrum's Extended Survey", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49282 }, ["series"] = { 49428 }, ["description"] = "I've looked over the readings my little boxes gave an' I think I know where to look next. The Ashes of Xibala are practically mine. Ye'll want to meet me in the middle of the ruins, under that big ol' leerin' skull on the mountainside, to continue my survey. Readin' these contraptions is hard work, an' I don't think we'll be alone up there. Think ye can watch me back?", ["objectivesText"] = "Assist Excavator Morgrum Emberflint with a survey.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.429333, ["y"] = 0.732667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49283] = { ["id"] = 49283, ["name"] = "Who Seeks the Seekers?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49283 }, ["series"] = { 49284 }, ["description"] = "Let me tell you, Zandalar is filled to the brim with ancient secrets. It's quite fascinating. We heard tales of a region, to the southeast, where ships were losing their way. Some even vanished! Raku, along with a team of particularly curious Seekers, has been exploring a cove near there for some time. Shipwrecks and mysteries, what isn't to like? We should have heard back by now. We tortollans may not be fast, but we are reliable. Will you check on them, and make sure they are well?", ["objectivesText"] = "Locate the Seekers down the coast, to the southeast, and speak to Batu .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 128909, ["x"] = 0.575333, ["y"] = 0.924667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 129586, ["x"] = 0.705, ["y"] = 0.651 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.575333, ["y"] = 0.924667 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[49284] = { ["id"] = 49284, ["name"] = "Perfect Tidings", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49284, 49285, 49286, 49287, 49288, 49289, 51407 }, ["series"] = { 49283 }, ["description"] = "Your timing is most convenient, <class>. Our team had a check-in planned for this place, two days past. None have yet returned. I did not want to be brash and send word to the city too soon. However, I cannot leave this place empty, nor can I abandon young Koba. Take this scroll. See who, or what, you can find. Bring back those you can.", ["objectivesText"] = "Use the attuned Scroll of the Missing to track and find the lost explorers.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 154704, 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 129586, ["x"] = 0.705, ["y"] = 0.651 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 128889, ["x"] = 0.736, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.651 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5409, ["name"] = "Dreadpearl Tidings", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 153516 } },
[49285] = { ["id"] = 49285, ["name"] = "Tiny Treasures", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49284, 49285, 49286, 49287, 49288, 49289, 51407 }, ["description"] = "My adults are in the field doing some research. So I stay here, patiently waiting, as they told me to do. These monsters came and took my special treasures! They took my best friend in the whole world, my slug, Spitzy ! They took them all. They ran far. I do not move fast... Could you please get them back, and find my family?", ["objectivesText"] = "Collect all of Koba 's treasures. Progress: My hatchling... if they laid a finger on him...", ["rewardXP"] = 1415, ["rewardItems"] = { 156865, 156866, 156869, 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 128888, ["x"] = 0.702, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133417, ["x"] = 0.736, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5409, ["name"] = "Dreadpearl Tidings", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49286] = { ["id"] = 49286, ["name"] = "Caged Wisdom", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49284, 49285, 49286, 49287, 49288, 49289, 51407 }, ["description"] = "Oh, hello, friend. It seems there is more here than for what we prepared. We sought. We found. We studied... and then we were taken. There are naga here. We did not expect this. There is a nasty fellow in this cave. If you could get the key from him, it would help us greatly. No need to fret, we'll wait here.", ["objectivesText"] = "Take the key from Sli'thrus. Progress: Were we asking too much?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 154708, 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 128889, ["x"] = 0.736, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 128889, ["x"] = 0.736, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.736, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5409, ["name"] = "Dreadpearl Tidings", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49287] = { ["id"] = 49287, ["name"] = "Lost Chelonians", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49284, 49285, 49286, 49287, 49288, 49289, 51407 }, ["description"] = "Tidemistress Nazesh has been channeling on a rock they found in one of the pools above. She has been trying for days. They grow desperate. The rest of my team was taken and locked up in cages. They want secrets from us that we do not know. When they realize we tortollan cannot be coerced, I expect the naga will do something most dire. Release the Seekers. We will thwart the naga plans together.", ["objectivesText"] = "Rescue tortollans captured by the Nazeshi.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 128889, ["x"] = 0.736, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 128925, ["x"] = 0.752, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.736, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5409, ["name"] = "Dreadpearl Tidings", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49288] = { ["id"] = 49288, ["name"] = "Scrollhunters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49284, 49285, 49286, 49287, 49288, 49289, 51407 }, ["description"] = "When they captured us, they took everything we had - including our wonderful scrolls! Those naga witches are building storms. They try to hide what they do here, and seek power for their queen. We see past their madness, they are driven for a purpose. Retrieve our work from the Nazeshi Tempest-Wielders, else they may use them for nefarious gains.", ["objectivesText"] = "Collect 5 Seeker scrolls. Progress: I really need to invest in some more scroll cases...", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 153022, 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 128889, ["x"] = 0.736, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 128925, ["x"] = 0.752, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.736, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5409, ["name"] = "Dreadpearl Tidings", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49289] = { ["id"] = 49289, ["name"] = "A Special Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49284, 49285, 49286, 49287, 49288, 49289, 51407 }, ["description"] = "Tidemistress Nazesh is right up this hill, <name>. There is something there. Something Azshara wants very badly. The naga must not succeed. If you can get a little piece of that stone, though, bring it back for us. Take this scroll with you, it will help you in your fight. It is time we push her forces, back into the waves for good.", ["objectivesText"] = "Defeat Tidemistress Nazesh and discover why the naga were sent here. Progress: What have you found?", ["rewardXP"] = 1770, ["rewardItems"] = { 156871, 157539, 157543, 157554, 158440, 158441, 158442, 158443, 159151 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 128925, ["x"] = 0.752, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 128925, ["x"] = 0.752, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5409, ["name"] = "Dreadpearl Tidings", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49290] = { ["id"] = 49290, ["name"] = "Aged to Perfection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49290 }, ["series"] = { 49407 }, ["description"] = "Greetings, young one. I am Roko . I trade in specialty goods and exotic wares. < Roko pulls a small wooden cask from beneath his shell.> This bourbon is one hundred years old. I know, because I bought it one hundred years ago. A man in Freehold is prepared to trade me a rare scroll for this, but alas I am barred from entering. It seems this town is not so \"free\" anymore. If you can get in, perhaps you could make the trade on my behalf? I would be in your debt.", ["objectivesText"] = "Deliver the Hundred Year Bourbon to Carentan in Freehold. Progress: Are you with the Irontide? I've already paid you people! Leave me alone!", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 153507 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128702, ["x"] = 0.796, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128903, ["x"] = 0.768, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.796, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49292] = { ["id"] = 49292, ["name"] = "Algae Shakes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["series"] = { 48352 }, ["description"] = "Now that I have properly developed my tonic, it is of utmost importance that we dispense it amongst the ill at once. Please, take this tankard and distribute the remedy to the sick. I will try to calm the rest.", ["objectivesText"] = "Dispense the Cleansing Tonic to 6 Nauseated Villagers in Anglepoint Wharf.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125922, ["x"] = 0.3952, ["y"] = 0.2676 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3952, ["y"] = 0.2676 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49295] = { ["id"] = 49295, ["name"] = "Clear-Cutting", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "We've managed to hold this hill, but the wicker creatures have moved in to surround us. We're not going to be able to move into the town if we don't get them off our flanks. This is where you come in, <class>. See if you can clear out some of their numbers in the lumber fields. That way, when we move in, we only need to worry about one front.", ["objectivesText"] = "Kill 8 Curseformed Familiars in the Timbered Strand.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 152587, 152590 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 126310, ["x"] = 0.7, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 383, ["name"] = "Fletcher's Hollow", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 19, ["flags"] = 0 } } },
[49299] = { ["id"] = 49299, ["name"] = "Enemy Within", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "I won't sugarcoat it, kid. It's a madhouse here. The leadership has fallen, selling their own souls as well as the souls of the workers to some darker forces. I will not give in. Overseer Bates surrendered the guard in his hunger for power. Show him that he is a fool.", ["objectivesText"] = "Kill Overseer Bates . Progress: After the guard fell, it was easy to get to everybody else.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 160083, 160084, 160085, 160086, 160093, 160094, 160095, 160096 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125962, ["x"] = 0.376, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125962, ["x"] = 0.376, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 12, ["flags"] = 0 } } },
