[49302] = { ["id"] = 49302, ["name"] = "The Deadliest Catch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48008, 48009, 48347, 48348, 48352, 48353, 48354, 48355, 48356, 48365, 48366, 48367, 48368, 48370, 48372, 48540, 49268, 49292, 49299, 49302 }, ["description"] = "Oi! No time to waste! Seems Deepwarden had one more thing up his sleeve... and it's the catch of the day! This'll be a hunt for the ages, and I won't let ya miss out. Okri will fly you out to the wall. Get ready!", ["objectivesText"] = "Accompany Okri to the sea gate, then kill Viq'Goth . Progress: I've never seen a monster with such dark energy. We can't let it get through!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152401, 152585, 152586, 153486, 153513, 155053, 155057, 155059, 155064, 155072, 155079, 158295, 158296, 158298 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128679, ["x"] = 0.386, ["y"] = 0.268 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126298, ["x"] = 0.3915, ["y"] = 0.267 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.268 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 592, ["name"] = "The Shadow Over Anglepoint", ["orderIndex"] = 18, ["flags"] = 0 } } },
[49314] = { ["id"] = 49314, ["name"] = "Hunting Zardrax", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49314 }, ["description"] = "<name>, maybe you be helpin' me wit' sometin'. Talanji said dat Shadow Hunter Da'jul and her retainer, Kal'dran, ran off ta hunt down a lich named Zardrax. They be goin' off ta a place called Burial Mound. I be worried dey be in over dere heads. Can ya check ta see if dey be needin' help? We can't be losin' any of our allies in dis place.", ["objectivesText"] = "Find Shadow Hunter Da'jul in Burial Mound.", ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122795, ["x"] = 0.396, ["y"] = 0.438 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 127215, ["x"] = 0.31, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
