[49327] = { ["id"] = 49327, ["name"] = "Push Them Back!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "The faithless are laying siege to our home. This isn't the first time they've attacked, nor will it be the last, but we must protect the temple! Do whatever you can to disrupt their siege and push them back.", ["objectivesText"] = "Disrupt the Faithless assault on the Sanctuary of the Devoted.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128696, ["x"] = 0.272, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128696, ["x"] = 0.272, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 609, ["name"] = "The Three Keepers", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 45, ["flags"] = 0 } } },
[49333] = { ["id"] = 49333, ["name"] = "Building Our Arsenal", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49333 }, ["description"] = "Our fight against the faithless is an uphill battle we're bound to lose. We are outnumbered and out armed. What few weapons we have aren't enough to outfit the entire temple. With a few more spears and daggers, we might stand a chance fighting them off until our loa can be returned to us.", ["objectivesText"] = "Collect 20 Sethrak Weapons from within the Temple Incursion. Progress: We need weapons, <name>.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 153556 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128691, ["x"] = 0.322, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128691, ["x"] = 0.322, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[49334] = { ["id"] = 49334, ["name"] = "A Powerful Prisoner", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "It appears the Faithless broke through our defenses while I was away. They must be after Vorrik 's key. It's the only reason they would have taken him alive. Please, <name>. You must secure our leader's safe return.", ["objectivesText"] = "Find Vorrik and free him from his captors.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 155454, 155457 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128687, ["x"] = 0.272, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129519, ["x"] = 0.275333, ["y"] = 0.525333 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 609, ["name"] = "The Three Keepers", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 43, ["flags"] = 0 } } },
[49335] = { ["id"] = 49335, ["name"] = "Skycaller Slaughter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49335 }, ["description"] = "Some among the faithless are gifted with the ability to command the storm. They call themselves skycallers, and they use their magic to summon great spires that turn the earth into sand. Skycallers are the only ones capable of summoning these spires. If you kill the skycallers, you also kill the sethrak's ability to expand their warcamps.", ["objectivesText"] = "Kill 6 Sethrak Skycallers at the Temple Incursion.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128691, ["x"] = 0.322, ["y"] = 0.482 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128691, ["x"] = 0.322, ["y"] = 0.482 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.322, ["y"] = 0.482 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[49340] = { ["id"] = 49340, ["name"] = "The Keepers' Keys", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Serrik mentioned you might have uncovered something of significance at Zul'Ahjin? We don't have much time, I'm afraid. What is it you have found?", ["objectivesText"] = "Speak to Vorrik and uncover the significance of Sulthis' Stone.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129519, ["x"] = 0.275333, ["y"] = 0.525333 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128694, ["x"] = 0.2692, ["y"] = 0.5252 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.275333, ["y"] = 0.525333 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 609, ["name"] = "The Three Keepers", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 46, ["flags"] = 0 } } },
