[49366] = { ["id"] = 49366, ["name"] = "Aid the Wounded", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["series"] = { 50934 }, ["description"] = "<This Zandalari appears to be barely holding on. There is a broken dart lying on the ground next to him. He appears to have dropped this bottle before he collapsed. You grab the vial. Could it be some kind of antidote?>", ["objectivesText"] = "Treat the wounded Zandalari.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 153676, 156566, 198048, 200454, 204075, 204732, 204733, 204745, 204762, 204764, 204765, 204766, 204770, 204772, 204773, 204775, 204778, 204779, 204780, 204785, 204786, 204898, 204901 }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 129165, ["x"] = 0.632, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49370] = { ["id"] = 49370, ["name"] = "Rescue the Chronicler", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["description"] = "Just ahead, Chronicler Jabari is being held in a cage, waiting to become a sacrifice. One by one, I see dem taken away, I hear de screams. Blood drained to feed blood magic, and what was left... was food for a beast. He is de only one left, and I don't have de strength to save him yet. Get Jabari out of dere, so we can return to Princess Talanji.", ["objectivesText"] = "Release Chronicler Jabari .", ["rewardGold"] = 128700, ["rewardXP"] = 1385, ["rewardItems"] = { 156566 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 129165, ["x"] = 0.632, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 129164, ["x"] = 0.6105, ["y"] = 0.5085 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49376] = { ["id"] = 49376, ["name"] = "Just One Thing", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["series"] = { 49378 }, ["description"] = "You are just in time! Chance be high dat my blood was de next to spill. It is my fault we stopped here. Our team wanted to head back. Crawgs are de trouble, you see. De sanguinous birth of dese young be corrupted by cruel training. They are quite impressionable and dey will follow with just a little enticement. Capture the attention of one of de little squirmy ones nearby. We will see if my theory is correct.", ["objectivesText"] = "Capture a crawgling .", ["rewardGold"] = 154900, ["rewardXP"] = 1385, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49377] = { ["id"] = 49377, ["name"] = "Off With Her Head", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["description"] = "Warmother Nagla is driving her forces with a brutality and strength we did not expect. Blood trolls desecrate all dey touch, and are preparing to wreak havoc on all dat remain. As dey say, \"cut off de head, and de beast will be dead\". I will have her head as a trophy to show dat our brothers were avenged!", ["objectivesText"] = "Bring back the head of Warmother Nagla. Progress: Does she still live?", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 153572, 156566, 159089, 159090, 159091, 159092, 159093, 159094, 159095, 159096 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 129165, ["x"] = 0.632, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 129165, ["x"] = 0.632, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49378] = { ["id"] = 49378, ["name"] = "Earn Their Trust", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["series"] = { 49376 }, ["description"] = "If de young one can be taught to trust, dere is a chance for dis species. Dey may have been born of bad blood, but is dat what makes dem monsters? If you can build his confidence, a mighty ally he could one day be. A little care could be de thing, and don't forget food! I think some blood trolls may be extra tasty.", ["objectivesText"] = "Feed the crawgling .", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156566 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 129164, ["x"] = 0.6105, ["y"] = 0.5085 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 129164, ["x"] = 0.6105, ["y"] = 0.5085 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.6105, ["y"] = 0.5085 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49379] = { ["id"] = 49379, ["name"] = "Crawg Free Zone", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["description"] = "Crawgs dat have been battle trained are already set in their ways. Cleansing dem from de camp may be de only way to give de young ones a chance.", ["objectivesText"] = "Kill 5 Battle Crawgs .", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 156566 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 129164, ["x"] = 0.6105, ["y"] = 0.5085 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 129164, ["x"] = 0.6105, ["y"] = 0.5085 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.6105, ["y"] = 0.5085 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49380] = { ["id"] = 49380, ["name"] = "Bad Juju", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["description"] = "Look, between you and me, dere is no way we will drag my friend outta here without what got us into dis mess. We saw three orbs in dis camp. Dey are filled with de power of blood magic and are used in dirty rituals. Blood is drained from \"volunteers\" to corrupt de tadpoles of Krag'wa into vicious crawgs. If dis is a possible fate for children of loa, we must end it. Take dis vial and bleed de orbs dry. De chronicler will need to do research.", ["objectivesText"] = "Drain the blood orbs.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 153678, 156566 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 129165, ["x"] = 0.632, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 129165, ["x"] = 0.632, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49382] = { ["id"] = 49382, ["name"] = "It Seems You've Made a Friend", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49366, 49370, 49376, 49377, 49378, 49379, 49380, 49382 }, ["description"] = "Dis young one has bonded with you. Bring him to Krag'wa. See if dere is anything to be done to heal him of de corruption.", ["objectivesText"] = "Seek out Krag'wa.", ["rewardXP"] = 2765, ["rewardItems"] = { 156566 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 129164, ["x"] = 0.6105, ["y"] = 0.5085 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 120551, ["x"] = 0.755, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.6105, ["y"] = 0.5085 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5420, ["name"] = "Crawgling Conundrum", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49393] = { ["id"] = 49393, ["name"] = "The Roughnecks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "NEW JOB OPPORTUNITIES! Do you seek danger? Beasts in great quantities? Perilous adventure? Do you also prefer the rugged outdoors to the dainty frilly froo-froo estate life? Well, you might be cutout to be a ROUGHNECK, suppliers of all gryphon mounts in Kul Tiras. Inquire at the Roughneck Camp in Westwind Weald about this exciting new opportunity. Applicants must NOT be afraid of heights, feathers, and/or death.", ["objectivesText"] = "Speak with Tagart at the Roughneck Camp.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49394] = { ["id"] = 49394, ["name"] = "Hold Still", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "If you want to be a Roughneck, you're going to have to pass a few... trials. Every one of us has done 'em, so I don't want to hear any whining. Take these clippers and get me some goat fur . You have to clip 'em while they're alive, because thems the rules. Oh, and cover your bits when you do it, they like to kick.", ["objectivesText"] = "Use the Goat Shears on 6 Gentle Goats. Progress: Got the fur?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 153596, 155681 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49395] = { ["id"] = 49395, ["name"] = "The Bears and the Bees", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Hey, while you're out, would you grab some honey for me and the boys? Plenty of hives out in the woods, but I'd be careful if you don't want to dirty your delicate house cat hands. Bears out here tend to get pretty vicious when they smell honey.", ["objectivesText"] = "Kill 8 Scruffhide Bears and gather 6 Sticky Bee Honey from nearby Beehives. Progress: Bears giving you trouble?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 153595 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49398] = { ["id"] = 49398, ["name"] = "Raise a Glass!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["description"] = "Pleased to meet you. Name's Venrik . I been scrapin' out a living here in Freehold for years. Flynn used to be a regular back when he... well I shouldn't say too much. A man's past is his own. I'll help the two of you out, but first I demand that you let me give you a proper Freehold welcome: A drink!", ["objectivesText"] = "Order a drink from Venrik and drink it. Progress: What'sa matter? Cat got yer tongue?", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153509, 153599, 153600, 153601, 153680, 153681, 153682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128927, ["x"] = 0.772, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128927, ["x"] = 0.772, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 25, ["flags"] = 0 } } },
[49399] = { ["id"] = 49399, ["name"] = "The Big Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["series"] = { 49401, 49404, 49405, 49869, 52431 }, ["description"] = "So the Irontide Raiders are bringing the various outlaw crews together for a big job using weapons provided by the Ashvane Company. Something tells me they're not going fishing. We should see if members of the smaller crews are carrying any notes or orders. I trust you can handle it? I need to lay low and catch up with Venrik . If anyone else were to recognize me, the odds of them offering a friendly drink are precisely zero.", ["objectivesText"] = "Collect Bilge Rat Orders , Cutwater Corsair Orders , and Blacktooth Brawler Orders. Progress: Find anything?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153509, 153680, 153681, 153682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128927, ["x"] = 0.772, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 27, ["flags"] = 0 } } },
[49400] = { ["id"] = 49400, ["name"] = "Recruiting Efforts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["description"] = "The captain of the Irontide Raiders, Harlan Sweete, has it in his tiny head that he's in charge of Freehold now. He's been forcing the smaller crews to pledge their loyalty, and littering the whole town with his damn recruiting posters. Do me a favor and take down any of them posters you find. Just don't let them catch ya doin' it, or it's a long walk off a short plank.", ["objectivesText"] = "Tear down 6 Irontide Recruiting Posters . Progress: Makes me sick seein' those damn posters all over this town.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 155081, 155083, 158284, 158285, 158286, 158287 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128927, ["x"] = 0.772, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128927, ["x"] = 0.772, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 9, ["flags"] = 0 } } },
[49401] = { ["id"] = 49401, ["name"] = "Rodrigo's Roost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["series"] = { 49399, 49404, 49405, 49869, 52431 }, ["description"] = "We should check in with Cyrus and Taelia before we get in too deep. <Flynn pens a note on a scrap of parchment and tucks it into a small courier bag.> This is all of the evidence we've gathered so far linking the Ashvane Trading Company to the weapons and pirates here in Freehold. Take it to Rodrigo , on the rooftop just behind this tavern. He raises parrots that make great messengers. Some are even big enough to ride! Rodrigo 's a few planks short of a poop deck, but he's trustworthy!", ["objectivesText"] = "Speak with Rodrigo in Freehold. Progress: Talk to Rodrigo and send that evidence off to Taelia.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153509, 153680, 153681, 153682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126620, ["x"] = 0.792, ["y"] = 0.802 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.802 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 26, ["flags"] = 0 } } },
[49402] = { ["id"] = 49402, ["name"] = "Flew the Coop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49402 }, ["series"] = { 49403 }, ["description"] = "Yes, yes, you can ride the pretties. They like it! They're good pretties. They like helping! Do you like helping, too? Maybe you can help me! Some of the loud men came here and threatened me. They don't scare me! But they made the pretties fly away. If you see any of my pretties out there, please feed this to them! It's my special treat. I know it will make them come home.", ["objectivesText"] = "Feed 6 Runaway Macaws . Progress: Did you find any pretties? Oh, they must be so hungry out there.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 154878 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129098, ["x"] = 0.77, ["y"] = 0.828 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129098, ["x"] = 0.77, ["y"] = 0.828 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.77, ["y"] = 0.828 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49403] = { ["id"] = 49403, ["name"] = "Rodrigo's Revenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49403 }, ["series"] = { 49402 }, ["description"] = "The loud men are mean, but you seem nice! Want to have fun fun? The pretties love my special biscuits, but it makes them full full. Then they have to... go. You know? Let's prank the mean men! Fly fly on the pretties and make them go.", ["objectivesText"] = "Drop Vile Bombardment on 100 pirates in Freehold. Progress: Go! Go! Go!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 163036 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129098, ["x"] = 0.77, ["y"] = 0.828 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129098, ["x"] = 0.77, ["y"] = 0.828 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.77, ["y"] = 0.828 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49404] = { ["id"] = 49404, ["name"] = "Fairwind's \"Friends\"", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47489, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49400, 49401, 49404 }, ["series"] = { 49399, 49401, 49405, 49869, 52431 }, ["description"] = "Someone must have recognized Flynn and ratted him out! A bunch of Irontide thugs dragged him off to the Ring of Booty for a \"special audience\" with Captain Harlan Sweete. Flynn doesn't like to talk about this, but he used to captain his own crew. With Harlan as his First Mate. The two had a falling out after a messy job and Flynn lost all taste for freebooting. Just disappeared one day. Harlan took the nastiest of the crew and formed the Irontide Raiders. In other words; it's personal.", ["objectivesText"] = "Rescue Flynn from the Ring of Booty.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 152719, 152720, 152721, 152722, 153509, 153680, 153681, 153682, 155040, 155041, 155042, 155043, 160858, 160859, 160860, 160861 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128927, ["x"] = 0.772, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130159, ["x"] = 0.77, ["y"] = 0.828 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 587, ["name"] = "Freehold", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 28, ["flags"] = 0 } } },
[49405] = { ["id"] = 49405, ["name"] = "Defenders of Daelin's Gate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["series"] = { 49399, 49401, 49404, 49869, 52431 }, ["description"] = "Daelin's Gate has protected the southern channel for decades. If it falls, the pirate fleet can sail straight into Tiragarde Sound ! The marines at Vigil Hill will need our help. Let's go!", ["objectivesText"] = "Ride with Taelia to Vigil Hill.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 156520 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130159, ["x"] = 0.77, ["y"] = 0.828 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 141078, ["x"] = 0.608, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.77, ["y"] = 0.828 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 29, ["flags"] = 0 } } },
[49406] = { ["id"] = 49406, ["name"] = "Zalamar Slaughter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49406 }, ["objectivesText"] = "Zalamar Disrupted", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Zalamar Disrupted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863 },
[49407] = { ["id"] = 49407, ["name"] = "Trixie Business", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49407 }, ["series"] = { 49290 }, ["description"] = "Usually this is the part where I hand you the scroll and send you on your way. Sadly, friend, these are unusual times. How's a man expected to run an honest business dealing in highly illegal goods when the Irontide Raiders are shaking down good folk like myself? I'm prepared to offer you a handsome sum - and the scroll for our shelled associate - if you rid me of the damnable woman who collects these tributes. You'll surely find her at Harlan's table at the bar, getting drunk on MY gold!", ["objectivesText"] = "Slay First Mate Trixie Tornsail . Progress: Stay your hand, friend! If you harm me, you'll never find the scroll!", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128903, ["x"] = 0.768, ["y"] = 0.86 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128903, ["x"] = 0.768, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.768, ["y"] = 0.86 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49408] = { ["id"] = 49408, ["name"] = "Pirate Dice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 49408 }, ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49409] = { ["id"] = 49409, ["name"] = "Missing Treasure!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["storyline"] = { 49409 }, ["description"] = "Which one o' you scurvy dogs dug up me treasure?! Was it you, Ned ? I know you was in the Dead Man's Tale when I were talkin' about it! Or maybe it was ol' Nance Barmy , huh? Yer the one what fed me all them drinks in the first place! Oh and don't think I forgot about you, Nub Nub ! I ain't trust a hozen as far as I can throw 'em... which I guess is PRETTY FAR, but-- <Several lines are scratched out here.> Someone stole me damn treasure! <Signed with an X.>", ["objectivesText"] = "Ask Ned , Nance Barmy , and Nub Nub about the treasure, then find it.", ["rewardGold"] = 295000, ["rewardXP"] = 1415, ["rewardItems"] = { 161083 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49412] = { ["id"] = 49412, ["name"] = "Helping Henry", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "The Roughnecks told me to clear the rocks in the forest. I didn't know they meant THIS! You look tough, you have to help me! I'll get killed if I get anywhere near that thing. I'm also super allergic to bees...", ["objectivesText"] = "Kill Brawr . Progress: That thing sure hates bees...", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129392, ["x"] = 0.476, ["y"] = 0.176 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129392, ["x"] = 0.476, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.476, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49417] = { ["id"] = 49417, ["name"] = "Roughneck Riders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Rulf sent word that you're needed for another job. A rich house cat is willing to pay top dollar for a male aerie alpha and there is only one that fits the bill, Greatfeather. I gotta head back to camp to help train a particularly wild female, so this is going to be a solo job. Find Greatfeather and hit him with the Tether Shot . From there, you'll have to wing it.", ["objectivesText"] = "Capture Greatfeather.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 153679, 158228, 158238, 158239, 158240, 158241 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129578, ["x"] = 0.478, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49418] = { ["id"] = 49418, ["name"] = "Big Boss", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "With a performance like that, it's clear you're one of the top dogs here. Boss Tak will want to see you. He's up north checking on one of our camps in Waning Glacier. Head up that way and give him a hand. Oh, and I don't recommend looking him straight in the eye... or at his feet... or really anywhere near him. Best bet, close your eyes when you're talkin' to him.", ["objectivesText"] = "Meet Boss Tak at the Roughneck camp in Waning Glacier.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129291, ["x"] = 0.42, ["y"] = 0.197 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 9, ["flags"] = 0 } } },
[49419] = { ["id"] = 49419, ["name"] = "Frozen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Hurp me pwease! Oh, it's woo. I can sill muv my wips a wittle. Fin me sumfin to 'et me owdda 'ere.", ["objectivesText"] = "Find the source of heat in Longdrop Hot Springs. Progress: Woo 'ave somefin?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 39772, 39783, 39786, 39835, 127853, 128949, 133315, 154171, 226193, 226194, 232877, 237812, 247820, 247821 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130424, ["x"] = 0.436, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130424, ["x"] = 0.436, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49427] = { ["id"] = 49427, ["name"] = "Not Our Purple Elves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49427 }, ["description"] = "Ye know, <name>, these elves might be purple, but they're no' with the Alliance. Leastwise, they're a lot more aggressive than this ol' Dark Iron is comfortable with. On the off chance it'll piss off the Horde, ye mind killin' a few of them?", ["objectivesText"] = "Slay 8 Horde forces on the eastern shores of Xibala.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.429333, ["y"] = 0.732667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49428] = { ["id"] = 49428, ["name"] = "Grand Theft Telemancy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49428 }, ["series"] = { 49282 }, ["description"] = "I'm not opposed to honest competition, <name>. But teleportin' it right out from under our noses leaves me feelin' dirty. Go teach that thievin' elf what it means t'steal from the Alliance. If they're fightin' dirty, then so will we.", ["objectivesText"] = "Slay Third Telemancer Syranel and recover the Breath of Xibala . Progress: Ye get the Breath of Xibala back?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 155310, 158419, 158420, 158421, 158422, 159743 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.429333, ["y"] = 0.732667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49431] = { ["id"] = 49431, ["name"] = "Warm and Cozy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Heya! Isn't this place a dream? I couldn't be more relaxed. Well, I could be if these annoying cloud jerks would leave me alone. Why don't you go punch some in their cloud faces. Oh, and bring back their essences, they help keep my tub warm.", ["objectivesText"] = "Collect 99 Steamy Essences . Progress: I need more steam! Hurry, the tub is getting chilly!", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 153697, 158288, 158289, 158290, 158291, 160082 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130478, ["x"] = 0.448, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130478, ["x"] = 0.448, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.448, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49433] = { ["id"] = 49433, ["name"] = "Wendies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "It's a mystery where these boys were taken, but it ain't much of a mystery who did it. Roughnecks believe an eye for an eye and then some. Let's put down some of those monstrosities.", ["objectivesText"] = "Kill 10 wendigo.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129291, ["x"] = 0.42, ["y"] = 0.197 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.197 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 10, ["flags"] = 0 } } },
[49435] = { ["id"] = 49435, ["name"] = "Where'd They Go?", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "My boys are missing. You're going to help me find 'em. Got it?", ["objectivesText"] = "Locate clues regarding the missing Roughnecks. Progress: Find anythin'?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129291, ["x"] = 0.42, ["y"] = 0.197 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.197 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 11, ["flags"] = 0 } } },
[49437] = { ["id"] = 49437, ["name"] = "Tattered Note", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "<The short, hand-written note is scrawled in blood.> They captured me soon after I was exiled. I was too weak to be a slave and too starved to be food for the beasts. They were going to kill me, but one called Shath'kar intervened. He said it would be amusing to watch me starve to death among his prisoners. I have not lived a good life. I deserve nothing. But, to any fellow Zandalari who finds this, I have one request... Stick a blade in Shath'kar 's belly and twist it until the snake is dead!", ["objectivesText"] = "Slay Shath'kar in the Slithering Gulch.", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135355, ["x"] = 0.48, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49439] = { ["id"] = 49439, ["name"] = "Boss' Revenge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Revenge has never really been my thing, but whatever is in there killed my crew and I am not going to let it stand. Everybody fights, nobody quits.", ["objectivesText"] = "Kill Whompus .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 12, ["flags"] = 0 } } },
[49443] = { ["id"] = 49443, ["name"] = "A Lesson in Witch Hunting", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48986, 49443, 49803, 49804, 49805, 49806, 49807 }, ["description"] = "While I appreciate the dedication that went into compiling this tome, this thing reads like engineering instructions for a siege engine! I'll need some time to comb through this information for anything that might be useful to us. I wouldn't mind some assistance, if you have a moment. For starters, I could use some more light in here...", ["objectivesText"] = "Assist Lucille Waycrest as she studies the Tome of Ash and Silver. Progress: Did you find it?", ["rewardGold"] = 128700, ["rewardXP"] = 1385, ["rewardItems"] = { 156515, 156518, 156532, 163607 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 597, ["name"] = "Arom's Stand", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 34, ["flags"] = 0 } } },
[49444] = { ["id"] = 49444, ["name"] = "Underfoot", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 1165, ["storyline"] = { 49444 }, ["objectivesText"] = "Fragile Cargo recovered", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 152467 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Fragile Cargo recovered", ["amount"] = 8, ["type"] = 0, ["objectID"] = 129646, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[49449] = { ["id"] = 49449, ["name"] = "Leather - Rank 1 Unlock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 49449 }, ["description"] = "Amazed that anything so pure could continue to grow on this planet, you pick flower from the ground. You feel a small power radiate from it and then vanish. As it falls apart in your hands, you wonder if anyone on this Light-forsaken place knows how to handle this precious herb.", ["objectivesText"] = "Find someone on Argus who might be able to train you on how to handle Astral Glory.", ["rewardItems"] = { 151856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49450] = { ["id"] = 49450, ["name"] = "Incident Reports", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["description"] = "No wonder our workers are terrified to go into these woods. Generally the bears and spiders stay out of the way of humans... But these are no ordinary beasts! Father would be furious if productivity came to a halt. Please, cull these beasts so that the ridge can be safe once more!", ["objectivesText"] = "Kill 10 Enthralled beasts in Fernwood Ridge.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49451] = { ["id"] = 49451, ["name"] = "Time Off Requests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["description"] = "My father is incapable of seeing what's in front of his very nose. He holes himself up in his office, not leaving to go home until late at night... Here I am, his only son, trapped out here along with all of his workers. Are they in trouble? Yes! But father will never believe them. If he won't try to get to the bottom of this attack, I will do it myself!", ["objectivesText"] = "Free 5 Entangled Lumberjacks in Algerson Lumber Yard.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49452] = { ["id"] = 49452, ["name"] = "Inventory Deficit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["description"] = "My employees say we're under attack. They say our workers are falling to beasts and men made of wood. I say we're losing precious inventory! Do you know how many company-issued axes must be getting dropped out there? That's a waste of my hard-earned money! I'm going to need you to get those back for me.", ["objectivesText"] = "Collect 5 Reclaimed Axes from dead Algerson Lumberjacks. Progress: I spend my own money to get these workers the supplies they need and they just go ahead and lose them! How much more generous must I be?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 158063 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.689333, ["y"] = 0.180667 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49453] = { ["id"] = 49453, ["name"] = "Give a Dam", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49453 }, ["description"] = "These loggers are destroying the forest, and harming the wildlife! Beavers need this wood for their dams, but have had to resort to scrounging for scraps. It's not safe for them anymore! Please, help me chase them back to the safety of the water.", ["objectivesText"] = "Shoo 6 Woodchewing Beavers back to the water.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129670, ["x"] = 0.666, ["y"] = 0.172 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129670, ["x"] = 0.666, ["y"] = 0.172 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.172 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49454] = { ["id"] = 49454, ["name"] = "Pest Prevention", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["description"] = "These woods have never been so densely littered with spider eggs. If these are recent... they must also be corrupted! We cannot allow them to hatch into more of these aggressive spiders. While you are in the woods, destroy those eggs. Any more spiders could lead to an uncontainable infestation!", ["objectivesText"] = "Destroy 12 Mossfang Eggs . Progress: I will admit to not being the biggest fan of spiders. Fewer spiders sounds pretty good to me.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 5, ["flags"] = 0 } } },
