[49464] = { ["id"] = 49464, ["name"] = "Saurolisk Tails", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["storyline"] = { 49464 }, ["description"] = "Among the upper echelons of Kul Tiran society, there is one cuisine that escapes all but the most determined of chefs. Nobles will pay exorbitant amounts to have just a taste of this delicacy, spiced and cooked to one's delight. I speak, of course, of the saurolisk tail . I must discover the finest method of cooking this sought after comestible! Boiled? Braised? Poached? Perhaps steamed or blanched is the most appropriate method! I will, of course, need a few tails to test.", ["objectivesText"] = "Collect 5 Saurolisk Tails from Lichenjaw Saurolisks.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 155663 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49465] = { ["id"] = 49465, ["name"] = "Maximizing Resources", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["series"] = { 50699 }, ["description"] = "Let me tell you a thing about my employees. They're always blowing things out of proportion! I give them a good job with a steady wage and what do they do? They try to make excuses as to why they can't work! They say the trees have come alive. Trees? Walking and fighting? If you're going to lie, at least make it more believable. If they want to convince me, I'm going to need cold hard proof.", ["objectivesText"] = "Collect 5 Wood-Adorned Skulls in Algerson Lumber Yard. Progress: I give them an honest job with good pay. This is the thanks I get?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 154993 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.689333, ["y"] = 0.180667 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49467] = { ["id"] = 49467, ["name"] = "Witch of the Woods", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["series"] = { 49468 }, ["description"] = "A... a witch?! I uh... I would love to help you, truly I would but... I must report to my father. Why don't you go stop the witch yourself? For a brave adventurer like you, a witch should be no problem. I'm sure my father would reward you greatly!", ["objectivesText"] = "Kill the Witch of the Woods in Fernwood Ridge. Progress: My son told me about the witch, <name>. I've come up here to take care of her! If you want something done right, you need to do it yourself.", ["rewardGold"] = 339600, ["rewardXP"] = 1770, ["rewardItems"] = { 155586, 158219 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49468] = { ["id"] = 49468, ["name"] = "Required Webinar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 48369, 49450, 49451, 49452, 49454, 49465, 49467, 49468 }, ["series"] = { 49467 }, ["description"] = "I'm not surprised some of the workers stayed in the woods, even amidst the beasts. While he won't admit it, some of father's workers are extremely dedicated. And now they're trapped by the spiders! Perhaps they have information about what is going on here. Free them from their webbings and see what they know!", ["objectivesText"] = "Free 5 Webbed Lumberjacks .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.696, ["y"] = 0.189333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5436, ["name"] = "A Lumbering Mess", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49477] = { ["id"] = 49477, ["name"] = "Surprise Backup", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49477 }, ["series"] = { 48492 }, ["description"] = "<You find a torn Horde missive on the ground... It appears that a group of forsaken, led by a man named Chadwick Paxton , were sent here to investigate Nazmir . You're unable to discern why they were sent here, but there are coordinates that indicate where they were going. You may be able to find the scouts at the coordinates and enlist their aid in fighting the blood trolls.>", ["objectivesText"] = "Find Chadwick Paxton , leader of the Forsaken Scouting Party.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126289, ["x"] = 0.285333, ["y"] = 0.436667 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.285333, ["y"] = 0.436667 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["startItems"] = { 154890 } },
[49479] = { ["id"] = 49479, ["name"] = "Didn't Stop to Think if They Should", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 48492, 48496, 48497, 48498, 48499, 49479 }, ["description"] = "The sethrak seem to believe there's something in Nazmir that can unlock the destructive power of this gem. We don't have that, but we have the next best thing. An insane warlock who is willing to experiment with magic. Speak with Ingrid and have her begin the process to unlock the true power of this gem.", ["objectivesText"] = "Have Ingrid empower the Skycaller Gem . Progress: Just be careful around Ingrid, she can get a little carried away.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 154892 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 126346, ["x"] = 0.272, ["y"] = 0.399 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.399 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5418, ["name"] = "Cooking with Sethrak", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49522] = { ["id"] = 49522, ["name"] = "Carentan's Payment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49522 }, ["series"] = { 49523 }, ["description"] = "Well done, my friend. Well done, indeed. You see that dusty crate in the corner of the room? You'll find it contains the ancient scroll and a generous purse of gold, as we agreed. Please, take your reward. You've certainly earned it.", ["objectivesText"] = "Open the Dusty Crate.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128903, ["x"] = 0.768, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.768, ["y"] = 0.86 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49523] = { ["id"] = 49523, ["name"] = "A Bad Deal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 1161, ["storyline"] = { 49523 }, ["series"] = { 49522 }, ["description"] = "<Carentan escaped! Roko , the tortollan merchant who set up this deal in the first place, will want to know what happened. When you last spoke, Roko said he would be heading to Boralus.>", ["objectivesText"] = "Speak with Roko in Tradewinds Market.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 129940, ["x"] = 0.722667, ["y"] = 0.095467 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.722667, ["y"] = 0.095467 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49529] = { ["id"] = 49529, ["name"] = "Spring Cleaning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49529 }, ["objectivesText"] = "Fizzsprings Resort cleaned Kill Hissing Swells", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Fizzsprings Resort cleaned", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Kill Hissing Swells", ["amount"] = 20, ["type"] = 0, ["objectID"] = 128768, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895 },
[49531] = { ["id"] = 49531, ["name"] = "The Beauty of Marketing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49531 }, ["series"] = { 50542 }, ["description"] = "While us Fizzbrackets may not be goblins, we still know a business opportunity when we see one! The resort staff is getting trained, the place is getting cleaned up, now all we need is some quality marketing! <Wulferd holds up a familiar looking box.> Behold! The wondrous Gnomish engineering feat that is the S.E.L.F.I.E. Camera! Now, if only there was a generous <race> willing to capture the radiance of this place. Make sure you look like you're enjoying yourself out there!", ["objectivesText"] = "Take S.E.L.F.I.E.s with the resort's sights and wildlife. Progress: If your smile isn't at least half of the picture, I don't want to see it!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 155009, 158225 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129858, ["x"] = 0.675, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129858, ["x"] = 0.675, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49545] = { ["id"] = 49545, ["name"] = "Warchief's Command: Frostfire Ridge!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6720, ["mapID"] = 525, ["storyline"] = { 49545 }, ["series"] = { 33815, 33868, 34364, 34375, 34377, 34378, 34402, 34461, 34462, 34592, 34765, 34775, 34822, 34823, 34824, 34844, 34861 }, ["description"] = "All able-bodied members of the Horde are hereby ordered to report to Farseer Drek'Thar in Frostfire Ridge . The destruction of the Dark Portal has stopped the Iron Horde invasion of Azeroth, but now we must to take the fight to them. With Farseer Drek'Thar 's aid, we will be able to establish a strategic position in Draenor to fight against our enemies. For the Horde!", ["objectivesText"] = "Speak to Farseer Drek'Thar in Frostfire Ridge .", ["rewardGold"] = 200, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 525, ["npcID"] = 76411, ["x"] = 0.447, ["y"] = 0.661 } }, ["coords"] = { ["mapID"] = 525, ["source"] = "quest_giver", ["x"] = 0.447, ["y"] = 0.661 }, ["mapCandidates"] = { ["npc"] = { 525 }, ["zone"] = { 6720 } }, ["questType"] = "standard" },
[49570] = { ["id"] = 49570, ["name"] = "A Rocky Start", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49571, 49574, 49577 }, ["description"] = "<As you thumb through the book, the pages are unusually thick and embedded on their surface are runic-shaped jewels. Samuel Colton notices you looking and approaches.> Ah, now that's a treasure I've had for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at the thought of something being transcribed in jewels. Come to think of it, I wonder if Zooey Inksprocket would be able to decipher it. Say, <name>, would you mind taking it over to her and see if she can translate it?", ["objectivesText"] = "Bring the book to Zooey Inksprocket and see if she can translate the text. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 153716, 155676 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49571] = { ["id"] = 49571, ["name"] = "Digging Through the Past", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49570, 49574, 49577 }, ["description"] = "Let's see, Jane Hudson probably still has her book on ancient runes and carvings. And I believe Tal'ana has a few scrolls he picked up from Ulduar. OH! And Toopa found what appeared to be some type of codex the last time he ventured out. I remember seeing the runes on it and they bear a striking resemblance to the ones in this book. If you could convince them to uh... lend us those items for a bit, I believe I just might be able to create a translation for you. I won't even charge you for it!", ["objectivesText"] = "Ask Jane Hudson for her book of Primordial Races: Runes and Writings . Ask Tal'ana for his Scrolls of the Stonefather . And ask Toopa for the The Dungard Codex . Progress: How goes the translation?", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["rewardItems"] = { 155587, 155588, 155589, 155678 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49572] = { ["id"] = 49572, ["name"] = "The Shrine of the Sea", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49575 }, ["description"] = "This next shrine is right here, in Tiragarde Sound. According to the journal, the earthen mentions creating bluish hued jewels. I wonder if that's anything like the kyanite we have here. Go and see if the shrine still stands. Hopefully it's still in a usable state. I'll continue to study the journal for more information.", ["objectivesText"] = "Investigate the Shrine of the Sea in Tiragarde Sound.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49573] = { ["id"] = 49573, ["name"] = "The Shrine of the Eventide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 896, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49576 }, ["description"] = "There are two more shrines here on Kul Tiras. I believe this next one resides within Drustvar, near the Bleak Hills Mine, southeast of Corlain. Here are the notes on that shrine. Should it also need mending, I'm positive your skills with jewels can meet the challenge of repairing it.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49574] = { ["id"] = 49574, ["name"] = "The Shrine of Storms", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 942, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49570, 49571, 49577 }, ["description"] = "Yes, I believe there are a few here in Kul Tiras. You should visit them, <name>, investigate them. See if what this book says is true. This particular shrine he mentions sounds like it may reside near Brennadam, in Stormsong Valley. It should be fairly easy to find. If my calculations are correct, it should be just north of that town. Here are the notes on that one. And I've marked its location for you on your map. Good luck, <name>.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49575] = { ["id"] = 49575, ["name"] = "Tol Dagor: Jewel of the Tides", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9327, ["mapID"] = 895, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49572 }, ["description"] = "<An absence you assume to be a mistake, you quickly survey the area for something that might fit there yet you find nothing. However, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", ["objectivesText"] = "Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece. Progress: <Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 153716, 155648 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9327 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 9, ["flags"] = 0 } } },
[49576] = { ["id"] = 49576, ["name"] = "High Prospects", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49573 }, ["description"] = "<Checking your notes, you find that the earthen had extracted the gems from some earth elementals to the south. Looking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead. Perhaps investigating there will yield some clues as to where to find these jewels.>", ["objectivesText"] = "Investigate Gol Osigr for clues about the jewels that were used to construct the shrine. Progress: <All of the cracked jewels will definitely need to be replaced.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 153716, 155661, 155830 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49577] = { ["id"] = 49577, ["name"] = "Cracking the Surface", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 942, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49570, 49571, 49574 }, ["description"] = "<Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest. Perhaps you can prospect the earth in that area to find more of those jewels and repair the shrine.>", ["objectivesText"] = "Go to the Windshorn Hills and gather 20 Shard of Golden Beryl . Progress: <The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 153716, 155590 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49581] = { ["id"] = 49581, ["name"] = "Sun-Speckled Dunes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 864, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49588 }, ["description"] = "<Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area. Checking your notes, it appears that these dunes were located south of your current location.>", ["objectivesText"] = "Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough. Progress: <These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 153716, 155664, 155665 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49582] = { ["id"] = 49582, ["name"] = "Atal'Dazar: Not All That Glitters...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9028, ["mapID"] = 862, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49587 }, ["description"] = "<You reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\". Given your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", ["objectivesText"] = "Travel to Atal'Dazar and find a replacement for the broken jewel. Progress: <When you're done replacing the central gem, you think you might still be able to sell the old one.>", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 155666 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9028 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 9, ["flags"] = 0 } } },
[49583] = { ["id"] = 49583, ["name"] = "Out With the Old", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 863, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49585, 49586, 49589 }, ["description"] = "<It's clear though that time has had its way with these gems, some eroded and chipped in places. Repairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", ["objectivesText"] = "Cut 4 Natant Rubellites and replace the old ones with the new. Progress: <Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 153714, 153716, 158639, 158640, 158642, 158643, 158644, 158645, 158648, 158649, 160207 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49584] = { ["id"] = 49584, ["name"] = "The Missing Chapter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["series"] = { 49578 }, ["description"] = "<Samuel puts down the journal and looks back up at you.> While trying to figure out where the shrines reside, I came across an entry that mentioned him exploring an area that sounds very similar to Dustwallow Marsh. He mentions hiding something of great importance there. It's a long shot, given when this earthen roamed Azeroth, but perhaps if you were to retrace his final steps you may find something. I'll mark the location on your map.", ["objectivesText"] = "Travel to the location marked on your map and see what you can find. Progress: Who knows what you may find out there. Hopefully something...", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 5996, 155668, 155669 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 11, ["flags"] = 0 } } },
[49585] = { ["id"] = 49585, ["name"] = "A Rocky Start", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49583, 49586, 49589 }, ["description"] = "<As you thumb through the book, you see odd-looking runes carved out of jewels embedded in the stone pages. Seshuli notices you looking and approaches you.> Ah, dat's been a treasure of mine for many years. Beautiful, isn't it? No clue what it says, but I've always reveled at de thought of something being written in jewels. Come to think of it, I wonder if Grazzul would know what it says. <name>, would you mind taking it over to him and see if he can translate it?", ["objectivesText"] = "Bring the book to Grazzul and see if he can translate the text. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 153716, 155676 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 130901, ["x"] = 0.422, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49586] = { ["id"] = 49586, ["name"] = "Digging Through the Past", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49583, 49585, 49589 }, ["description"] = "Let's see, Examiner Alerinda has a book on ancient runes and carvings. I think Koatini has a few scrolls he brought with him from Ulduar. OH! And Chronicler Shoopa found a codex de last time he ventured out. I remember seeing de runes on it and dey look a lot like de ones in dis book. Maybe you can convince dem to lend us dose books for a bit, and I think I can create a translation for you.", ["objectivesText"] = "Ask Examiner Alerinda for her book of Primordial Races: Runes and Writings . Ask Koatini for his Scrolls of the Stonefather . And ask Chronicler Shoopa for the The Dungard Codex . Progress: How is de translation going?", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["rewardItems"] = { 155587, 155588, 155589, 155678 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 130901, ["x"] = 0.422, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49587] = { ["id"] = 49587, ["name"] = "The Shrine of Nature", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49582 }, ["description"] = "Another shrine resides right here in Zuldazar. According to de journal, de earthen talks about creating green hued jewels dere. I wonder if dat's anything like de viridium we find in de ore we mine. Go and see if de shrine still stands. Hopefully, we can still make use of it. I'll continue to study de journal for more information.", ["objectivesText"] = "Investigate the Shrine of Nature in Zuldazar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49588] = { ["id"] = 49588, ["name"] = "The Shrine of the Sands", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49581 }, ["description"] = "Dere are two more shrines here on Zandalar. Dis next one resides within Vol'dun, near Bonetrail Gulch. Hopefully de Faithless haven't defiled de shrine. Here are de notes on dat location. Should dat shrine also need fixing, I think your skills with jewels will probably be enough to fix it.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Vol'dun. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49589] = { ["id"] = 49589, ["name"] = "The Shrine of the Dawning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["series"] = { 49583, 49585, 49586 }, ["description"] = "Yea, I believe there are a few here on Zandalar. You should find dem, <name>, investigate dem. See if what dis book says is true. Dis particular shrine sounds like it might be in Nazmir. If my calculations are correct, it should be just south of Torga's Rest. Dat loa was a mighty one. It is truly sad dat it is no longer with us. Here are de notes on dat one. And I've marked its location for you on your map. Loa be with you, <name>.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Nazmir. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49599] = { ["id"] = 49599, ["name"] = "The Missing Chapter", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["description"] = "< Seshuli puts down the journal and looks back up at you.> While trying to figure out where de shrines reside, I came across an entry dat mentioned him exploring an area dat sounds very similar to Dustwallow Marsh. It could be a long shot, given when dis earthen roamed Azeroth, but maybe if you retrace his final steps, you may find something. I'll mark his last location for you on your map.", ["objectivesText"] = "Travel to the location marked on your map and see what you can find. Progress: Who knows what you'll find out dere. Hopefully something...", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 155668, 155669 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 11, ["flags"] = 0 } } },
[49661] = { ["id"] = 49661, ["name"] = "Locally Sourced Eggs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 49661 }, ["description"] = "There is nothing in the world greater than food made from the best, freshest ingredients! My good friend I am on a hunt. A hunt for the perfect eggs! I have heard tale of eel eggs. A delicate texture, a slight undersea saltiness... such a unique flavor profile! I must have them! The eels here lay their eggs on the land before returning to the sea. Please, gather these eggs for me so that I may create only the most elegant of omelets!", ["objectivesText"] = "Collect 10 Coilscale Eggs from Coilscale Nests.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 155660 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49662] = { ["id"] = 49662, ["name"] = "The Missing Key", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["series"] = { 49664, 50745 }, ["description"] = "Korthek has grown spiteful and arrogant over the years, but I realize now that he has grown mad as well. Mythrax will kill all of us if he is released. For too long, I've held out hope that I could convince Korthek peacefully to abandon his heresy. I was wrong. All of Zandalar is at risk while Korthek and his allies hold even one key to Mythrax's prison. Meet me outside his fortress in the north. We will confront my old friend \"Emperor\" Korthek and end this together.", ["objectivesText"] = "Meet Vorrik at Bwoljin's Fall.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128694, ["x"] = 0.2692, ["y"] = 0.5252 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137970, ["x"] = 0.428, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.2692, ["y"] = 0.5252 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 47, ["flags"] = 0 } } },
[49664] = { ["id"] = 49664, ["name"] = "Allies in Anarchy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["series"] = { 49662, 50745 }, ["description"] = "Even after all these years, I can feel the ancient power of Sethraliss in this place. My loa endures. Our task ahead is great and I will need a clear, focused mind to accomplish it. Allow me a few moments to meditate here, like I did in ages past. In the meantime, you should help the vulpera stir up trouble however you can. They seem to know you, and a large enough disturbance will distract the Faithless from our mission. Meet me back here when you're done and we'll proceed together.", ["objectivesText"] = "Speak with Nisha .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135172, ["x"] = 0.4524, ["y"] = 0.3524 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135090, ["x"] = 0.462, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.4524, ["y"] = 0.3524 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 49, ["flags"] = 0 } } },
[49665] = { ["id"] = 49665, ["name"] = "Ready to Riot", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Do you remember how we met, $p? You were trapped in a Faithless cage, just like the ones in the crater below. Together, we slaughtered Faithless and earned your freedom in blood. The vulpera trapped in shackles below can do the same. They just need to be given the chance. Steal Faithless weapons and give them to the vulpera slaves below. They'll rise up and help you fight the Faithless. We're going to start a revolt right under their arrogant noses.", ["objectivesText"] = "Free and arm 8 Vulpera Slaves in cages.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 159470 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135090, ["x"] = 0.462, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135090, ["x"] = 0.462, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 50, ["flags"] = 0 } } },
[49666] = { ["id"] = 49666, ["name"] = "Make Them Fear Us", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "I carry this banner into every battle because I want the Faithless to fear it. To fear my people. If I die in the battlefield, surrounded by Faithless, I will die happy. On that day, I will not need a burial or prayers. But I will need someone to pick up my banner and carry it into the next battle. If you are of the same mind, plant these banners into the corpse of every Faithless you slay. Let the survivors know who's coming for them.", ["objectivesText"] = "Plant 12 Vulpera Banners into dead Faithless.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 158884 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135090, ["x"] = 0.462, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135090, ["x"] = 0.462, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 51, ["flags"] = 0 } } },
[49667] = { ["id"] = 49667, ["name"] = "The Little Ones", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "Just when I thought the Faithless couldn't get any worse, I find out that they're keeping vulpera children trapped down in that crater! The other vulpera we rescued told me that a big sethrak, Appraiser Versik , is inspecting them on the central platform to determine what he can sell them for. Selling vulpera kids! Oooh, those Faithless make me so angry! Please, $p. I'm no fighter. I can't rescue those kids. But if you bring them up here to me, I promise I'll get them out of here safely.", ["objectivesText"] = "Kill Appraiser Versik and lead the vulpera kids back to Meerah .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 71083, 159992, 159993, 159994, 159995, 160017, 160018, 160019, 160020 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135355, ["x"] = 0.48, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135355, ["x"] = 0.48, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49668] = { ["id"] = 49668, ["name"] = "Light Up the Gulch", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "Don't mistake my caution for hesitance, $p. I will defend the vulpera with my dying breath... I'd just prefer to avoid taking that breath today. While Nisha rushes to the front line, I work behind them to ensure our success. Meet me at the Faithless beast pens if you'd like to help. Oh, and take this torch. You'll be going through their marketplace, where they auction off slaves. Starting a few well-placed and metaphorically poignant fires along your route will make things easier for all of us.", ["objectivesText"] = "Torch the slave auction sites in Slithering Gulch.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 158896 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137981, ["x"] = 0.46, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135099, ["x"] = 0.554, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49669] = { ["id"] = 49669, ["name"] = "Unleash the Beasts", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "The Faithless are arrogant hoarders, capturing people and beasts that can never be truly tamed. All to fuel their endless lust for war. I've even seen their slavers dragging blood trolls and other dark monsters from the swamps of Nazmir. I heard terrible noises coming out of a cave while I was scouting the feeding pits up ahead. Whatever monsters they are hiding in there, find a way to free them and let them exact revenge on the Faithless.", ["objectivesText"] = "Kill Tamer Traskniss to release the crawgs.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 161182 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135099, ["x"] = 0.554, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135099, ["x"] = 0.554, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49676] = { ["id"] = 49676, ["name"] = "Dressed for Battle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Kiro's the leader of my caravan. He's always been far too passive. I warned him we needed to make a preemptive strike against the sethrak, but he insisted that we keep our heads down and continue to quietly do business. Look where that got us. Our caravan was completely unprepared for their attack. Now I'm ready to fight for what's ours, but I'm not exactly dressed for battle. Help me scavenge some suitable equipment here among our enemies. We will use their own tools against them.", ["objectivesText"] = "Help Nisha find a war banner, a helmet, and explosives . Progress: Killing an enemy with their own sword is an even bigger insult, no?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 155413, 155414, 155415, 155416, 159980, 159981, 159982, 159983 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 130455, ["x"] = 0.66, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49677] = { ["id"] = 49677, ["name"] = "Plans for Attack", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Before we were attacked, I had a plan to take the fight to the sethrak. It was devised with flawless intel. I know, because I gathered the information myself. I surveyed their entire compound and created a map based on my findings. My plan relies on that map, but it's now in the hands of Fangcaller Sraka, the brute who's leading this assault on my home. Help me kill her so I can take back what's mine!", ["objectivesText"] = "Recover Nisha's Attack Plans from Fangcaller Sraka. Progress: My plan for attack is both detailed and dangerous.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 35232, 158651 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49678] = { ["id"] = 49678, ["name"] = "I Spy a Spire", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49678 }, ["description"] = "It is good you have come. Dol'watha be under attack by these snake-men. Soon as they arrived they started pulling these weird spire-things out de ground. I seen a bunch of snake-mons with feathers in their caps getting zapped by them, but they not be dying. If it not be bad for them, that means it's good for them. And that be bad for us. Destroy those spires. Hopefully whatever boon they be getting will go away and they will be easier to kill.", ["objectivesText"] = "Destroy 4 Sethrak Spires .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130450, ["x"] = 0.472, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130450, ["x"] = 0.472, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49679] = { ["id"] = 49679, ["name"] = "The Sethrak Incursion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49679 }, ["description"] = "Dol'watha be a small village. Got a few farms, some beasts, and a decent view of a swamp. Loa know we not be ready for this... De snake-men popped out of de ground by de hundreds. Slaughtered my beasts, my family, my friends. One minute de earth rumbling, de next we be running for our lives. I heard about snake-men from de deserts of Vol'dun but I never believed I would see them in my life... Help us fight back. Kill as many of them as you can. Dol'watha won't be beaten that easily!", ["objectivesText"] = "Slay 12 sethrak in Sandscar Breach.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131354, ["x"] = 0.472, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131354, ["x"] = 0.472, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49680] = { ["id"] = 49680, ["name"] = "Skycaller Soltok", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49680 }, ["description"] = "As if snake-men with swords not be bad enough, they brought a powerful skycaller along. I hear skycallers can tempt great storms into being. They be to blame for de spires and lightning flying everywhere. There be one who wear a bigger feather than most, likely de leader. Calls herself Soltok or something equally hissy. Don't care. Kill her.", ["objectivesText"] = "Slay Skycaller Soltok .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 155309, 155311 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130450, ["x"] = 0.472, ["y"] = 0.25 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130450, ["x"] = 0.472, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49681] = { ["id"] = 49681, ["name"] = "Lil' Tika", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49681 }, ["description"] = "<The tiny armored raptor scratches pitifully at the cage's wooden bars. As you approach, the miniscule reptile wiggles frantically and issues a piercing screech for help! Perhaps you can open the cage and let it free.>", ["objectivesText"] = "Rescue Lil' Tika . Progress: My poor beasts...", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 161016, 163036, 163502 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130468, ["x"] = 0.467, ["y"] = 0.242 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131354, ["x"] = 0.472, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.467, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49694] = { ["id"] = 49694, ["name"] = "Turn to Drust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 896, ["storyline"] = { 40537, 49694, 49876 }, ["series"] = { 40537 }, ["description"] = "There are blood scribe masters all over the place who'll teach you what you need to know. The first master I'd recommend seeking out is Kronah . She's a bit... eccentric to say the least. One of the few tortollan who've experienced a thing or two. She's the one who taught me the blood contract I know how to invoke! She likes to hang out at the Smuggler's Cove on the western coast of Drustvar. Oh, and could you say hi for me when you see her?!", ["objectivesText"] = "Seek out Kronah at the Smuggler's Cove in Drustvar.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131386, ["x"] = 0.206, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 901, ["name"] = "8.1.5 Inscription - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49710] = { ["id"] = 49710, ["name"] = "An Offering of Eggs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Our work isn't only to capture and tame gryphons, it's also to preserve them. Rescue any eggs remaining in nearby abandoned nests. Set them in one of the new nests we've built for the displaced gryphons. I am sure one of the gryphon females will adopt them.", ["objectivesText"] = "Collect 4 Spotted Gryphon Eggs . Progress: You find a safe nest.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 155828 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129170, ["x"] = 0.425, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 7, ["flags"] = 0 } } },
[49715] = { ["id"] = 49715, ["name"] = "Trouble at Greystone Keep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49715 }, ["series"] = { 49733 }, ["description"] = "A friend of mine, a fellow military courier, had a job at Greystone Keep. The fort lies just outside of Boralus, so I would've expected him to be back by now. I have another job lined up, so could you go check out the fort for me? I'm probably just being paranoid.", ["objectivesText"] = "Speak with Tallis Skyheart .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 130377, ["x"] = 0.694, ["y"] = 0.112 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.694, ["y"] = 0.112 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[49716] = { ["id"] = 49716, ["name"] = "A Lesson on Trust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49716, 49720, 49733, 49734, 50249, 51226 }, ["description"] = "The men in the fort were once under my command, and so, they are now my responsibility. Each of them should have a badge we use for identifying individuals under certain circumstances. I would ask you to bring back a number of these as proof of thinning their ranks. These men are no longer soldiers of Boralus, and as such, no longer deserve to carry the Proudmoore anchor.", ["objectivesText"] = "Retrieve 8 Marine Identification Badges . Progress: Did you bring me those badges?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 156599 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.81, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5431, ["name"] = "Greystone Keep", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49719] = { ["id"] = 49719, ["name"] = "Getting Paid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Now that we got our mitts good and bloody, I think it's time we head back to camp. I'll run ahead, so you can finish up whatever business you got. Just remember to meet Tagart for your pay.", ["objectivesText"] = "Meet with Tagart at the Roughneck Camp.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 13, ["flags"] = 0 } } },
[49720] = { ["id"] = 49720, ["name"] = "Free Bird", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49716, 49720, 49733, 49734, 50249, 51226 }, ["description"] = "Skyheart invited me here to teach some of his city boys how to train the local sea hawks. Some of my students went and sided with the mutiny force. Seems these soft marines have forgotten what the consequence is for betraying a Drustvar soldier. Worse yet, they've locked up quite a few of the younger birds we were training. I've got my hands full with these hawks, so if you could free a few of the young'uns while you're in the fort, I'd appreciate it.", ["objectivesText"] = "Free 5 Juvenile Seahawks. Progress: Any luck? Hopefully they didn't nip you too much.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 132720, ["x"] = 0.806, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 132720, ["x"] = 0.806, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5431, ["name"] = "Greystone Keep", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49730] = { ["id"] = 49730, ["name"] = "WANTED: Thundersnout", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49730 }, ["description"] = "Thundersnout is the largest of the boars in the valley. She is wreaking havoc on the nearby farms and their crops. Mayor Roz of Brennadam has issued a bounty for proof of her demise. Thundersnout's location is near Briarback kraul, so be on the look out for quilboar!", ["objectivesText"] = "Deliver Thundersnout's Snout to Mayor Roz . Progress: Yes?", ["rewardGold"] = 772200, ["rewardXP"] = 6175, ["rewardItems"] = { 158300 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 }, { ["mapID"] = 942, ["npcID"] = 134752, ["x"] = 0.494, ["y"] = 0.664667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "group" },
[49731] = { ["id"] = 49731, ["name"] = "Fond Farewells", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49731 }, ["description"] = "Dis is where we part ways, <name>. I'm going to take de name Akunda, and start a new life here. Rakera saved my life, and I'm going to make sure to live a life dat was worth saving. If you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.", ["objectivesText"] = "Deliver Jorak 's Note to B'wizati in Zuldazar. Progress: What is dis?", ["rewardGold"] = 169800, ["rewardXP"] = 2060, ["rewardItems"] = { 153016 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128339, ["x"] = 0.528, ["y"] = 0.892 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 127664, ["x"] = 0.402, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.892 }, ["mapCandidates"] = { ["npc"] = { 864, 1165 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[49733] = { ["id"] = 49733, ["name"] = "Patching Up the Rear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49716, 49720, 49733, 49734, 50249, 51226 }, ["series"] = { 49715 }, ["description"] = "Most of my men were injured when we were escaping the fort, those that weren't were injured holding this position. <Tallis hands you a stack of stained cloth.> All of our better supplies are behind those walls, so we've been forced to make do with what we have. Everything that's not being worn on a soldier's person as we speak has been shredded for use as bandages. We don't have the staffing to take care of everyone. Head out and replace the worst of our injured's bandages.", ["objectivesText"] = "Bandage 5 injured marines. Progress: My gratitude, that should help alleviate some of the soldiers' pain.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.81, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5431, ["name"] = "Greystone Keep", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49734] = { ["id"] = 49734, ["name"] = "Targeting a Turncoat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49716, 49720, 49733, 49734, 50249, 51226 }, ["description"] = "The instigator of this mutiny is a man named Fernn. He has always shown discontent with House Proudmoore and his position here. But to betray the men he works with? That seems beyond even my expectations of him. Take him out, and show this mutiny the mistake of crossing truly loyal marines.", ["objectivesText"] = "Slay Fernn the Turncoat .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 155090, 158266, 158330 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.81, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5431, ["name"] = "Greystone Keep", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49735] = { ["id"] = 49735, ["name"] = "Protect the Nests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49393, 49394, 49395, 49412, 49417, 49418, 49419, 49431, 49433, 49435, 49439, 49710, 49719, 49735 }, ["description"] = "Now that Tagart is done with your hazing... I mean... trials, you can start helping us with some of the work around here. Some of the nearby gryphon nests have been overrun with saurolisk. I fear that the gryphons will make new roosts elsewhere if we don't clear them out. Head up the road towards the waterfall and take out those saurolisks. Report to Shawn when you're done. He's posted as a lookout there.", ["objectivesText"] = "Kill 7 Hungry Dewscale . Progress: Get bit?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129170, ["x"] = 0.425, ["y"] = 0.226 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129578, ["x"] = 0.478, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5435, ["name"] = "A Mountain of Ice", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49736] = { ["id"] = 49736, ["name"] = "For Kul Tiras!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["series"] = { 49738 }, ["description"] = "Listen, I'll be frank with you; we're not at full strength here. Many of our soldiers recently left for Boralus on new orders. It's like they knew just when to hit us... But we're going to hit back! Every able-bodied man and woman in town has stepped up to mount a defense. Take this battle standard and remind them what they're fighting for!", ["objectivesText"] = "Use the Proudmoore Battle Standard to inspire 15 Vigil Hill Marines or Militia.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 141605, 155085, 156520, 158234, 158235, 158236, 158237, 164762, 252403 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 35, ["flags"] = 0 } } },
[49737] = { ["id"] = 49737, ["name"] = "Air Raid", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["description"] = "Those pirates have air support! They're torching our farms and splitting our attention away from the front lines. Take 'em outta the sky!", ["objectivesText"] = "Slay 6 Irontide Skyriders .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 156520 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 33, ["flags"] = 0 } } },
[49739] = { ["id"] = 49739, ["name"] = "Enemies at the Gate", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49739 }, ["objectivesText"] = "Defend Daelin's Gate", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["rewardItems"] = { 156570 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 130697, ["x"] = 0.585, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130697, ["x"] = 0.585, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Defend Daelin's Gate", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895 },
[49740] = { ["id"] = 49740, ["name"] = "Cease Fire!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["description"] = "The enemy has turned our forward cannons around on us. Scuttle that equipment to stop the bombardments!", ["objectivesText"] = "Destroy 4 Captured Cannons .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 156520 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 36, ["flags"] = 0 } } },
[49741] = { ["id"] = 49741, ["name"] = "Righteous Retribution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47181, 47186, 47189, 47485, 47486, 47487, 47488, 47489, 47960, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49401, 49404, 49405, 49736, 49737, 49738, 49740, 49741, 49869, 50110, 50531, 50573, 50787, 50788, 50789, 50790, 50795, 50972, 51341, 52128, 52431, 52750, 52787, 53041, 59641 }, ["series"] = { 50110, 50787, 50788, 50789, 50790, 50795 }, ["description"] = "Cyrus taught me how to deal with thugs, bullies, and scum like pirates. When they hit us, we hit back twice as hard. < Taelia 's hand finds the haft of her hammer and grips it tight.> It's time to hit back.", ["objectivesText"] = "Help Taelia destroy the pirate ships in Daelin's Gate.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 162522 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 142393, ["x"] = 0.564, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 142393, ["x"] = 0.564, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 38, ["flags"] = 0 } } },
[49744] = { ["id"] = 49744, ["name"] = "Bombs, Away", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49744, 49745, 49746, 49755 }, ["description"] = "By the sea's foamy beard, what a blast! They've brought goblins, and if there's one thing I know about goblins it's that they like to blow things up. I saw a few of them carrying large bombs, and I presume that they are going to blow up the town. I would like to keep the town, so how about you head out there and steal as many of those explosives as you can find? After that, let's blow up their demolishers and stop this infernal bombardment!", ["objectivesText"] = "Retrieve 8 Horde Explosives and use them against the Demolishers . Progress: Don't forget to check inside the buildings too!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 33226, 57434, 57435, 57436, 57437, 131881, 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130190, ["x"] = 0.576, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130190, ["x"] = 0.576, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 582, ["name"] = "Reclaiming Brennadam", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49745] = { ["id"] = 49745, ["name"] = "You Have Their Orders", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49744, 49745, 49746, 49755 }, ["description"] = "The Horde is an army, make no mistake. And armies need orders. Someone must be giving orders here. They know the plan, and I want to know the plan too. Look for the people who seem to be in charge and see if you can uncover any intelligence so we know what to do next.", ["objectivesText"] = "Find the Warchief's Orders . Progress: You find those orders?", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 582, ["name"] = "Reclaiming Brennadam", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49746] = { ["id"] = 49746, ["name"] = "Dousing the Flames", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49744, 49745, 49746, 49755 }, ["description"] = "The Horde have set fire to my town, <class>. I will make them pay for this. Stormsong Valley is the breadbasket of Kul Tiras, and our people need to be fed. The first thing we must do is damage control. Grab some buckets and help put those fires out!", ["objectivesText"] = "Use the Water Bucket to put out 15 fires around the Ruins of Brennadam.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 65281, 65301, 65320, 65337, 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 582, ["name"] = "Reclaiming Brennadam", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49754] = { ["id"] = 49754, ["name"] = "Not \"Only Zul\"", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49754 }, ["series"] = { 49758, 49775 }, ["description"] = "Our enemies here either follow de name of Zul, or dey want to use him to take Zandalar. He has the ego to allow either. Dey claim only Zul can lead us. Dissuade dem.", ["objectivesText"] = "Purge Zul's forces. Progress: Did ya leave any breathing?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130821, ["x"] = 0.489, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130821, ["x"] = 0.489, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49755] = { ["id"] = 49755, ["name"] = "Heavy Artillery", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49744, 49745, 49746, 49755 }, ["description"] = "Bad news, friend. They're bringing in serious firepower now. We've spotted a tank on the northern hill by the windmill. They can reach the other side of the town from there. We can't let them set it up. What do you say to giving them a taste of their own medicine? If you can take out their commander, you'd have a fancy new tank all to yourself. Imagine the mayhem you could unleash on their invasion!", ["objectivesText"] = "Slay Captain Wormwood and commandeer the Experimental War Machine . Progress: If that cannon can reach Brennadam, it can reach those zeppelins!", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 158689, 158690, 158691, 158692, 160361, 160364, 160367, 160370, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 582, ["name"] = "Reclaiming Brennadam", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49757] = { ["id"] = 49757, ["name"] = "Cat on a Hot Copper Roof", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49757 }, ["description"] = "My parents said we have to go, but I won't leave Scratchy behind! She's so gentle and precious and pure and kind and soft and cuddly! She must be so scared up there on the balcony! Please help her!", ["objectivesText"] = "Climb the burning house and rescue Scratchy . Progress: We can't leave Scratchy here!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 118244, 155858, 163036 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131654, ["x"] = 0.586, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131654, ["x"] = 0.586, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49758] = { ["id"] = 49758, ["name"] = "Send the Signal!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49758 }, ["series"] = { 49754, 49775 }, ["description"] = "My crew is not on board with de word of Zul. We saw too much of who he really is. Far out in de harbor, Zul's traitors have joined with de mogu to try to take my ships! If we lose de fleet and de harbor, we lose de city! We must let Zuldazar know we stand strong. We take back de ships. We drive de villains out. You must light de towers with loa-blessed flame. Dey will always see dat de Bay of Kings belongs to Zandalar!", ["objectivesText"] = "Get to the ship.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 140590, ["x"] = 0.46, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135576, ["x"] = 0.544, ["y"] = 0.87 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[49766] = { ["id"] = 49766, ["name"] = "Your Next Move", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 47332, 49766, 49767 }, ["description"] = "We have some thoughts on the best way to win over the Zandalari. The princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father. General Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here. We should also keep working on winning over the King here in Zuldazar . This city is vast and has many secrets.", ["objectivesText"] = "Choose your next move in Zandalar.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 793, ["name"] = "Zandalar Zone Choice", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49767] = { ["id"] = 49767, ["name"] = "Your Next Move", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 47332, 49766, 49767 }, ["description"] = "We have some thoughts on the best way to win over the Zandalari. The princess is heading to Nazmir to take the fight to the blood trolls. Her voice carries much weight with the council and her father. General Jakra'zet detests the Horde. Removing his voice from the Zanchuli Council will greatly improve our chances here. We should also keep working on winning over the King here in Zuldazar . This city is vast and has many secrets.", ["objectivesText"] = "Choose your next move in Zandalar.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 793, ["name"] = "Zandalar Zone Choice", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49768] = { ["id"] = 49768, ["name"] = "Nesingwary's Trek", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49768 }, ["series"] = { 47586, 50466 }, ["description"] = "De greatest hunter from your lands, de dwarf Nesingwary, has come to participate in de Great Hunt. If you are enough of a hunter to join him, den travel to de Nesingwary Trek along de northeastern region of Zuldazar .", ["objectivesText"] = "Speak with Hemet Nesingwary at Nesingwary's Trek.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 130785, ["x"] = 0.519, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 123005, ["x"] = 0.674, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.519, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[49769] = { ["id"] = 49769, ["name"] = "Wreckage of the Cataclysm", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 49769 }, ["series"] = { 48015 }, ["description"] = "In recent years one of the greatest Zandalari loa temples mysteriously fell into the sea. It is a topic of some debate what caused this, and what treasures might have been lost in the catastrophe. My cousin Rokor was in charge of the salvaging efforts. Within the temple were many great items of knowledge and power. I am sure he will have need of the services of someone like yourself with strong arms and working knees.", ["objectivesText"] = "Find Rokor at Scavenger's Strand.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49774] = { ["id"] = 49774, ["name"] = "Won't Leaf Him to Die", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49774, 49776, 49777, 49778, 49779, 49780, 49781 }, ["description"] = "I may have done some wicked things in my past, but I won't leave dis guard to die. Zulajin has taken a nasty bite outta Zaluto... and has also infected him with some weird voodoo. But don't worry, because today is our lucky day. I have a plan to cure him. Dere are sweetleaf bushes nearby! De leaves of dis bush are known for their healing properties. You get me some, and I will be able to save dis Zaluto. It's de only chance we have!", ["objectivesText"] = "Gather 8 Sweetleaf . Progress: Did you get de sweetleaf ?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 155912 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5419, ["name"] = "This is the Pits", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49775] = { ["id"] = 49775, ["name"] = "Key to the Brig", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49775 }, ["series"] = { 49754, 49758 }, ["description"] = "You can tell a lot about a troll by what they do when they learn who Zul truly is. That Garza is a mutinous, foul-tusked, ship stealin' traitor. She is the kind of zealot dat will follow de heretic into the maw of an Old God. I am more de type to rip out her tusks and beat her with dem. I'd settle for ya taking her key and getting our wavemaster and crew free!", ["objectivesText"] = "Get the key from Quartermaster Garza. Progress: Did ya relieve her of de key?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 155882, 159942 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135576, ["x"] = 0.544, ["y"] = 0.87 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130821, ["x"] = 0.489, ["y"] = 0.685 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.87 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49776] = { ["id"] = 49776, ["name"] = "No Problem Tar Can't Solve", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49774, 49776, 49777, 49778, 49779, 49780, 49781 }, ["description"] = "I'm not going to lie... I did wicked things in my youth and I've been living with de shame ever since. But Zaluto is going to die without my healing, and we're all going to die if dat dino isn't taken care of. Dere is a lot of tar in dis area. I need it to cure Zaluto of whatever is infecting him here. Get me dat tar, and I'll be able to save Zaluto from dis fate.", ["objectivesText"] = "Collect 6 Sticky Tar . Progress: We will need plenty of dat sticky tar !", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 155913 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5419, ["name"] = "This is the Pits", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49778] = { ["id"] = 49778, ["name"] = "Don't Go into the Light", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49774, 49776, 49777, 49778, 49779, 49780, 49781 }, ["description"] = "Okay, dis is de moment of truth! We will see if my voodoo can cure Zaluto . I should have been honest with you... dere is a chance dis won't work. Voodoo isn't a science, you know. I need you to hold Zaluto down, because dis here is going to hurt. A lot.", ["objectivesText"] = "Hold Zaluto down while Jin'Tiki cures him. Progress: We can't leave Zaluto to die.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 156519 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5419, ["name"] = "This is the Pits", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49779] = { ["id"] = 49779, ["name"] = "Bad To The Bone", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49774, 49776, 49777, 49778, 49779, 49780, 49781 }, ["description"] = "I will not leave here without killing Zulajin, or else it will just go after de next caravan dat comes through. I have a plan, but we must work together to pull it off. Dere are skeletal raptors roaming in de area. I do not know what voodoo brought dem here, but we need dem gone. We are going to need as much space as possible for my plan to kill Zulajin.", ["objectivesText"] = "Slay 10 Bone Raptors . Progress: Did you take care of de skeletal raptors yet?", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 130930, ["x"] = 0.242, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 130930, ["x"] = 0.242, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5419, ["name"] = "This is the Pits", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49780] = { ["id"] = 49780, ["name"] = "Recovering Ancient Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49774, 49776, 49777, 49778, 49779, 49780, 49781 }, ["description"] = "Zaluto has a crazy plan to kill Zulajin. Never thought a guard could come up with something so clever. Dere is ancient mojo throughout dis place... who knows what it used to be? But I sense something I can use. De statues sinking in de tar pits have de fire mojo still burning in dem. We will need it to kill Zulajin. Take my fetish and use it to absorb what's left of de fire in dese statues. Just don't get dat fire too close to de tar!", ["objectivesText"] = "Absorb fire mojo from 4 Nazmani statues. Progress: Do you have de fire yet?", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 156480 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 131231, ["x"] = 0.242, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5419, ["name"] = "This is the Pits", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49781] = { ["id"] = 49781, ["name"] = "Catch Me if You Can", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 49774, 49776, 49777, 49778, 49779, 49780, 49781 }, ["description"] = "Alright, de time has come for you to face Zulajin yourself! Jin'Tiki 's fetish has de power of some ancient fire in it now. You will ride my raptor here to lure Zulajin into de tar pits. After dat... you will use de fetish to light de tar pits on fire! Dat should be enough to kill Zulajin. ...and if not, well, den you will have to improvise. Good luck!", ["objectivesText"] = "Ride Zulato's raptor to lure Zulajin into the tar pits and set it on fire.", ["rewardGold"] = 339600, ["rewardXP"] = 3455, ["rewardItems"] = { 155556, 156481, 159045, 159046, 159047, 159048 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 130930, ["x"] = 0.242, ["y"] = 0.532 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 130928, ["x"] = 0.282, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.532 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 5419, ["name"] = "This is the Pits", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49785] = { ["id"] = 49785, ["name"] = "Destroy the Weapon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49785 }, ["series"] = { 49884 }, ["description"] = "I did scout de next island. Rezan's Claw has a mighty weapon on board. I don't know what it is, but dey are confident in its ability to break de defenses of our home. Get to de ship. Destroy that weapon before dey can use it on Zuldazar !", ["objectivesText"] = "Investigate the weapon.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 211279 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130750, ["x"] = 0.546, ["y"] = 0.898 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130833, ["x"] = 0.578, ["y"] = 0.766 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.898 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49801] = { ["id"] = 49801, ["name"] = "Aggressive Mating Strategy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["description"] = "Aggression is good. I agree with Jangalar that Ben'jin needs to be a lot less passive to succeed and I can prove science is the way to do it by making an injection for him. Alchemy tells us that, for this type of beast, aggression comes from a substance in their bile sacs. The local razorwings are invasive and, as such, have more than enough aggression for our purposes. Harvest some of their bile sacs and I'll make a treatment that will have our big boy ready to go again in no time.", ["objectivesText"] = "Harvest 8 Bile Sacs from Invasive Razorwings. Progress: Did you get all of the bile sacs I need yet? Science is not supposed to be safe...", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 155904 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130905, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130905, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49803] = { ["id"] = 49803, ["name"] = "Changing of the Guard", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48986, 49443, 49803, 49804, 49805, 49806, 49807 }, ["description"] = "I have no doubt that you're a quite capable <class>, mainlander, but we will need some help if we want to make it to Waycrest Manor in one piece. A small group would be ideal; strong enough to face the coven's threats, but small enough to remain largely unnoticed. <Reade produces a bundle of letters.> I have written new orders to some of my finest soldiers to join your Order of Embers. They will report to you and the lady Waycrest. Please deliver these to them, so they can be prepared to move out.", ["objectivesText"] = "Deliver recruitment orders to Captain Cleardawn, Ensign Yorrick , Ensign Mace , Lieutenant Sterntide , and Falconer Notley in Arom's Stand. Progress: You will need to gather your recruits before we venture forth.", ["rewardGold"] = 140450, ["rewardXP"] = 1385, ["rewardItems"] = { 156515, 156518, 156532, 163607 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 129643, ["x"] = 0.368, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129643, ["x"] = 0.368, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 597, ["name"] = "Arom's Stand", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 36, ["flags"] = 0 } } },
[49804] = { ["id"] = 49804, ["name"] = "Sharp Thinking", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48986, 49443, 49803, 49804, 49805, 49806, 49807 }, ["description"] = "I have reason to believe that the coven has already infiltrated Arom's Stand. There are many unfamiliar faces here, with the refugees from Corlain, and we know they can use their magic to appear like one of us. This needle is fashioned of solid silver. If the witches are indeed vulnerable to silver, then a prick from this may be enough to break their spell. The refugees may not be keen on being prodded, but they must understand that this is for the good of the town... and perhaps all of Drustvar .", ["objectivesText"] = "Use Lucille's Sewing Needle on 10 Corlain Refugees to reveal the hidden witches in Arom's Stand. Progress: I really hope this works...", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 156515, 156517, 156518, 156532, 163607 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 597, ["name"] = "Arom's Stand", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 35, ["flags"] = 0 } } },
[49805] = { ["id"] = 49805, ["name"] = "Implements of Ill Intent", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48986, 49443, 49803, 49804, 49805, 49806, 49807 }, ["description"] = "<It looks like some careless witch made a poor attempt to hide this grimoire from sight. No good could come of leaving the possessions of the coven for a hapless villager to find. It would probably be a good idea to destroy any trappings of the coven that you find in Arom's Stand.>", ["objectivesText"] = "Destroy 12 Heartsbane objects in Arom's Stand.", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 }, { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 597, ["name"] = "Arom's Stand", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49806] = { ["id"] = 49806, ["name"] = "Hidden Dealings", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48986, 49443, 49803, 49804, 49805, 49806, 49807 }, ["description"] = "<Among her possessions, the witch carried a crudely drawn map of Arom's Stand. A symbol marks what looks like the entrance to a cellar beneath one of the buildings. If this location is important to the coven, it might be worth scouting out.>", ["objectivesText"] = "Explore the location marked on the Crude Map. Progress: What's this? A map?", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 156515, 156517, 156518, 156532, 163607 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 }, { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 597, ["name"] = "Arom's Stand", ["orderIndex"] = 5, ["flags"] = 0 } }, ["startItems"] = { 156517 } },
[49807] = { ["id"] = 49807, ["name"] = "A New Order", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48986, 49443, 49803, 49804, 49805, 49806, 49807 }, ["description"] = "Before we leave, I have one more task to ask of you. While you were busy recruiting our inquisitors and driving the coven away from Arom's Stand, I took the liberty of placing an order with the local tailor. Using some of the sketches within the tome, I had him put together some uniforms reminiscent of those worn by the ancient order. Since you will be leading our inquisitors, I think it's only fitting that you present them with their new regalia.", ["objectivesText"] = "Give the Inquisitors Regalia to the recruits in Arom's Stand. Progress: You should be inducting them, not me!", ["rewardGold"] = 128700, ["rewardXP"] = 1385, ["rewardItems"] = { 156515, 156518, 156532, 163607 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 597, ["name"] = "Arom's Stand", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 37, ["flags"] = 0 } } },
[49810] = { ["id"] = 49810, ["name"] = "Monstrous Matchmaker", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["description"] = "We have a problem, a matter of love, and you've come just in time. Two white brutosaurs, de male Ben'jin and de female Maka'fon, are de last of their kind. De rest have passed on. Dese two are not in de mood for love. If you can help my new friend Cala and myself, dis may be de only chance to give dem a future. Place my voodoo totem close to each one so dat I can feel what dey feel and learn how we can help.", ["objectivesText"] = "Place Witch Doctor Jangalar's Voodoo Totem near both brutosaurs. Progress: Place de voodoo totem close to both of de brutosaurs and I will be able to sense what dey feel.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 155911 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49814] = { ["id"] = 49814, ["name"] = "The Scent for a Brutosaur", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["series"] = { 50150, 50154 }, ["description"] = "Mood is everything for love, and Maka'fon is not in de mood. Voodoo incense, specially formulated for brutosaurs by an expert witch doctor like myself, will surely spark de fire of de mother spirit in her heart. Certain fragrant rushes work best, and de jungle will provide. Zandalari rushes grow near de waters here. Get a good amount for me and I will make an incense bundle big enough to set de mood.", ["objectivesText"] = "Find 7 Fragrant Rushes to make incense for Irritable Maka'fon. Progress: Look for de rushes near de life-giving waters dat I might use my voodoo to make incense for de brutosaurs.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 155916 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49818] = { ["id"] = 49818, ["name"] = "Trouble at Fort Daelin", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49818 }, ["description"] = "I was sent to Brennadam by my commanding officer to find a tidesage to help us at Fort Daelin to the west. The naga have started another attack on the bastion, and it's larger than any we have seen. Lieutenant Bauer is in the middle of helping out civilians at the village near the fort, and she could use any help possible.", ["objectivesText"] = "Report to Lieutenant Bauer at Seabreeze Village.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131004, ["x"] = 0.594, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[49831] = { ["id"] = 49831, ["name"] = "From the Depths", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "We must prepare for an attack. Man the cannons! Defend the levee at all costs!", ["objectivesText"] = "Defend the levee from the Azshara's assault.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 155198, 155211, 155212, 155217, 155219, 155226, 156472, 156482, 158181, 158183, 158200, 158332, 159752, 160519, 160521 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131000, ["x"] = 0.34, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131000, ["x"] = 0.34, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 14, ["flags"] = 0 } } },
[49832] = { ["id"] = 49832, ["name"] = "An Illegible Scroll", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49832 }, ["description"] = "<Resting within the waterproof container is an illegible scroll of undetermined age and origin. Perhaps the tortollans along the coast will be able to decipher what is written upon the parchment?>", ["objectivesText"] = "Take the scroll to the tortollans along the Windswept Coast.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135794, ["x"] = 0.405333, ["y"] = 0.426667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.426667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[49869] = { ["id"] = 49869, ["name"] = "A Desperate Defense", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["series"] = { 49399, 49401, 49404, 49405, 52431 }, ["description"] = "The soldiers garrisoned here are doing their best to hold out, but they're struggling. Pirates haven't dared attack this gate in years, and never with such a large force. If you're handy in a fight, Lieutenant Tarenfold will want to meet you. He's organizing the militia up ahead.", ["objectivesText"] = "Report to Lieutenant Tarenfold .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 156520 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 141078, ["x"] = 0.608, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 31, ["flags"] = 0 } } },
[49870] = { ["id"] = 49870, ["name"] = "Size Matters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["series"] = { 50268 }, ["description"] = "So the unintended side-effect of Gentle Ben'jin being, shall we say 'fun-sized' is that he is now small enough to get into the cave where the alpha wind serpent is! The beast is called Gloomtail and if Ben'jin defeats it, he will feel like this territory is his and will want to fill it with little brutosaurs. So he will seek out a mate. If Maka'fon is receptive, everyone wins! Go give him another hit of the formula!", ["objectivesText"] = "Administer the 'voodoo'-ed Aggression Formula to Ben'jin. Progress: Size isn't all dat matters. Ben'jin can get to more places if he's small... and fight dere!", ["rewardGold"] = 500760, ["rewardXP"] = 1770, ["rewardItems"] = { 156867, 156922 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130905, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 8, ["flags"] = 0 } } },
[49871] = { ["id"] = 49871, ["name"] = "Against the Tide", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49871 }, ["description"] = "De mogu are growin' desperate. Ha! Maybe dey hope to get away from here before de fury of de loa rain down on dem! De warlord's pet sorcerer set up blockers and dey have taken de tower. If you can avoid the sting, de lightning rods can have ya feelin' pretty good. One could even say energized. Get to Warlord Xiar and relieve him of his life privileges. Then let our people know we have taken back de Breath of Pa'ku! Dis mojo is empowered to ignite de tower with a mighty blast.", ["objectivesText"] = "Kill Warlord Xiar , and light the signal fire.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 52640, 52644, 52673, 156473 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130821, ["x"] = 0.489, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130750, ["x"] = 0.546, ["y"] = 0.898 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.489, ["y"] = 0.685 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49873] = { ["id"] = 49873, ["name"] = "Sacrificial Writes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49873, 49874, 49877, 49878, 49879, 49881, 49882 }, ["description"] = "<As you peer inside the tome, you find a verse appear, glowing bright red.> \"For blood to bond, one strikes a deal, A sacrifce which will appeal. Seek out the lame, and never yield, For in return, you shall be healed.\" <As you finish reading the verse, you notice that a scroll has appeared in your hand. Written across the top it's titled, \" Writ of Sacrifice \". Various runes, unknown to you, appear on the rest of the scroll. Yet, there's no explanation as to what to do with the scroll...>", ["objectivesText"] = "Ask Kronah about the Writ of Sacrifice . Follow her directions after she gives you the information you need.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156549, 168046 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131386, ["x"] = 0.206, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 903, ["name"] = "8.1.5 Inscription - Alliance/Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49874] = { ["id"] = 49874, ["name"] = "By the Book", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49873, 49874, 49877, 49878, 49879, 49881, 49882 }, ["description"] = "As you open the book, you stare at a blank page, waiting for something to happen. Instinctively you flip to the next page only to find it blank as well. Perhaps your trial awaits you further into the book?", ["objectivesText"] = "Investigate the Bloodshed Compendium further to begin your trial. Progress: I trust you to be careful inside the Bloodshed Compendium . I don't want to find any ripped pages from that weapon you wield.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 94207, 138840, 138841, 138842, 138843, 138844, 138845, 138846, 138847, 156509, 166846, 166970, 166971, 204985, 205188, 208888, 237812, 246697 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131386, ["x"] = 0.206, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 903, ["name"] = "8.1.5 Inscription - Alliance/Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49876] = { ["id"] = 49876, ["name"] = "Lines In the Sand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 40537, 49694, 49876 }, ["description"] = "This was all I had to offer you, young scribe. But your journey is not yet at an end. If you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar. Once there, seek out a sethrak by the name of Veriss in an area known as Vol'dun. < Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.> Pickled crocolisk eggs are my favorite. Would you like some?", ["objectivesText"] = "Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131386, ["x"] = 0.206, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 150318, ["x"] = 0.276, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 864, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 901, ["name"] = "8.1.5 Inscription - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49877] = { ["id"] = 49877, ["name"] = "Temple of Sethraliss: Booking on a Favor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49873, 49874, 49877, 49878, 49879, 49881, 49882 }, ["description"] = "When the Faithless came to power, we Devoted fled our sacred temple and took shelter here. However, in the midst of our exodus, many of us were forced to abandon some of our belongings. I myself left a tome that is used to learn the Oblivion contract. If you wish to proceed with the trials, you must retrieve that book for me, <name>. I trust you won't disappoint me.", ["objectivesText"] = "Recover the Tome of Oblivion from the Temple of Sethraliss. Progress: I'll admit, I'm a bit embarrassed to have left it behind. An oversight that I still regret to this day.", ["rewardGold"] = 1029600, ["rewardXP"] = 2830, ["rewardItems"] = { 156512, 158075 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 150318, ["x"] = 0.276, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 150318, ["x"] = 0.276, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 903, ["name"] = "8.1.5 Inscription - Alliance/Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49878] = { ["id"] = 49878, ["name"] = "Penning In Protection", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49873, 49874, 49877, 49878, 49879, 49881, 49882 }, ["series"] = { 49875, 49879, 49880, 49881, 49882, 49945, 49947, 49948 }, ["description"] = "<As you open the book, you turn each page and see portraits of champions standing alongside a large beast. Eventually you come to a blank portrait, and touch the page. Runes begin to appear in an ancient language, and quickly translate into words you can read.> \"The creature within, a guardian of men, A mixture of blood and of bone inked with pen. The blood from the scribe, the bone from the land, Milled to perfection, and signed by the hand.\"", ["objectivesText"] = "Collect bones from Zem'lan pirates and mill them into a fine powder. Mix the powder with your blood to create a Vial of Ossein Ink . Then sign the Bloodguard Chronicles . Progress: You would think with all the blood you have to give up for these trials, that you would be white as a ghost at the end of them. Or maybe just passed out for a week.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156598, 156600, 156601 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 150318, ["x"] = 0.276, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 903, ["name"] = "8.1.5 Inscription - Alliance/Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49879] = { ["id"] = 49879, ["name"] = "Brush With Death", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49873, 49874, 49877, 49878, 49879, 49881, 49882 }, ["series"] = { 49875, 49878, 49880, 49881, 49882, 49945, 49947, 49948 }, ["description"] = "<As you open the book, a sudden chill comes over you. You shake the sensation off as you read the verse.> \"A fatal bargain, in blood is struck, One inks their pledge, with strokes of luck. Stay true your lines, keep still your breath, Lest you stray too far, and summon death.\" <As you finish reading the incantation, a quill appears next to the book.>", ["objectivesText"] = "Pick up the quill and begin your trial.", ["rewardGold"] = 64350, ["rewardXP"] = 355, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 150318, ["x"] = 0.276, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 903, ["name"] = "8.1.5 Inscription - Alliance/Horde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49881] = { ["id"] = 49881, ["name"] = "The Final Verse", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 49873, 49874, 49877, 49878, 49879, 49881, 49882 }, ["series"] = { 49875, 49878, 49879, 49880, 49882, 49945, 49947, 49948 }, ["description"] = "It appears you are finished here, <name>. Thank you again for getting my book back. But between you and I, this was the easy part. Just wait till you meet the grandmaster. If you haven't noticed already, you'll need a special quill to invoke those contracts. And he'll be the one who shows you how to craft it. His name is Miju and he lives out on an island off the southern coast of Zuldazar. Good luck, <name>!", ["objectivesText"] = "Seek out Miju in southern Zuldazar to begin your final trial.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 81354 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 150318, ["x"] = 0.276, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131397, ["x"] = 0.326, ["y"] = 0.86 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 862, 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 903, ["name"] = "8.1.5 Inscription - Alliance/Horde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[49882] = { ["id"] = 49882, ["name"] = "A Test of Quills", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49873, 49874, 49877, 49878, 49879, 49881, 49882 }, ["series"] = { 49875, 49878, 49879, 49880, 49881, 49945, 49947, 49948 }, ["description"] = "The recipe you're after, young one, is that of the Sanguine Feather Quill of Lana'thel. I... < Miju motions to a pile of stuff.> Am the only other person I know of who has one... err... somewhere. But be warned, this trial may be your undoing! I shall have to invoke all four contracts against you. You must defeat each of the creatures, and from each one learn the rune needed to carve into your quill. Once you've learned all four runes, your trial shall be completed.", ["objectivesText"] = "Speak with Miju to begin your final trial and collect the knowledge to craft your quill.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131397, ["x"] = 0.326, ["y"] = 0.86 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 152261, ["x"] = 0.33, ["y"] = 0.856 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.326, ["y"] = 0.86 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 903, ["name"] = "8.1.5 Inscription - Alliance/Horde", ["orderIndex"] = 6, ["flags"] = 0 } } },
[49884] = { ["id"] = 49884, ["name"] = "Hope's Blue Light", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49884 }, ["series"] = { 49785 }, ["description"] = "There is but one step left! De second tower means the fleet is ours again! Climb aboard and we will finish dis thing!", ["objectivesText"] = "Fly with Captain Grez'ko to light the signal fire on the tower.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 156473, 158667, 159124, 159152, 159153, 159154, 159155 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130833, ["x"] = 0.578, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 123000, ["x"] = 0.445, ["y"] = 0.955 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49886] = { ["id"] = 49886, ["name"] = "Follow Your Nose", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49886 }, ["description"] = "You there! I could use your help! The ground isn't safe. The quilboar have established a network of tunnels below us, allowing them to spring up to ambush people who aren't walking carefully. Luckily for us, Humphrey here has a nose for the Briarback, and can sniff 'em out even when they're underground. Root a few of them out and let's make the farms a little safer to walk through. There's a particularly large clump of them in the northeastern fields. Good hunting!", ["objectivesText"] = "Use Humphrey to find and slay 5 Panicked Tunnelers .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131656, ["x"] = 0.509, ["y"] = 0.703 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131656, ["x"] = 0.509, ["y"] = 0.703 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.509, ["y"] = 0.703 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[49890] = { ["id"] = 49890, ["name"] = "Drustfall", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48184, 48504, 48517, 49890, 49896 }, ["description"] = "I believe I see more carvings at the entrance to that cave over there. Come, we should see what else was left behind.", ["objectivesText"] = "Investigate the ice cavern.", ["rewardGold"] = 607600, ["rewardXP"] = 3455, ["rewardItems"] = { 155573, 158581 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 600, ["name"] = "Gol Osigr", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49896] = { ["id"] = 49896, ["name"] = "To Falconhurst!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48184, 48504, 48517, 49890, 49896 }, ["description"] = "Our time here was well spent. The guards in Arom's Stand can handle what few Drust forces remain and I suspect the Drust leader and his magic might have some greater part to play here. However we must continue on the mission to Falconhurst. The path on the far side of these ruins will take us there. I will ride ahead and meet you outside of town!", ["objectivesText"] = "Meet Inquisitor Cleardawn outside of Falconhurst.", ["rewardGold"] = 28090, ["rewardXP"] = 2765, ["rewardItems"] = { 156710, 156828 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.257, ["y"] = 0.6775 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 600, ["name"] = "Gol Osigr", ["orderIndex"] = 4, ["flags"] = 0 } } },
[49897] = { ["id"] = 49897, ["name"] = "Making Mysteries", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49897 }, ["description"] = "Do you know what people love? The unexplained! Problem is, everything here is explainable. So I have a plan to create our own phe-gnome-enon. There are stories that talk about some weird chicken-snake hybrids that can turn you to stone. I've already released the chickens, now we just need the snakes. The first problem can be solved easily. Just chase down the chickens, and stick one of these robotic tails on them.", ["objectivesText"] = "Catch 5 Unassuming Chickens . Progress: How do my petrifyingly scary chickens look?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 129858, ["x"] = 0.675, ["y"] = 0.558 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129858, ["x"] = 0.675, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.558 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[49898] = { ["id"] = 49898, ["name"] = "Clear Victory", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49898 }, ["description"] = "<The ghostly captain continues to fight as she speaks, once more locked into the heat of battle, unaware the war has been over for centuries.> What are you doing standing around? We've ground them down to their final warriors and those damnable runic constructs, but the war isn't over yet! Colonel Waycrest needs us to hold this line! Kill as many of those Drust as you can and we might see the end of this war, today. Get back out there!", ["objectivesText"] = "Slay 15 Drust Skeletons.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 135085, ["x"] = 0.396, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135085, ["x"] = 0.396, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[49901] = { ["id"] = 49901, ["name"] = "Atal'Dazar: Yazma the Fallen Priestess", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 49901 }, ["description"] = "Zul knows dat we cannot let de first king rise from his grave. Dazar would be more than a figure head for Zul's dream troll empire, he would be a force dat could rival de very loa. But I cannot just let Zul get away. I and mine will follow Zul, but I want you and yours to enter Atal'Dazar. Yazma is trying to buy time and keep de tombs sealed away. You will need to fight your way through to her and you will need some allies to do so. Slay her.", ["objectivesText"] = "Defeat Yazma in Atal'Dazar. Progress: And here I always thought Yazma was just rude. I never expected just how far she had fallen.", ["rewardGold"] = 1029600, ["rewardXP"] = 2830, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 129757, ["x"] = 0.426, ["y"] = 0.376 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "dungeon" },
[49908] = { ["id"] = 49908, ["name"] = "Back to Brennadam", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49908 }, ["description"] = "The naga are mostly cleared out thanks to your help. They'll think twice before attacking again. Can you return to Brennadam and tell Squire Augustus III to return to his normal station?", ["objectivesText"] = "Report back to Squire Augustus III at Brennadam.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131000, ["x"] = 0.34, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131004, ["x"] = 0.594, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[49917] = { ["id"] = 49917, ["name"] = "Kaja'mite? Kaja'must!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49917 }, ["series"] = { 49919 }, ["description"] = "I been waitin' to talk to the King for a while now, but he not be seein' me! And this pompous lackey not be listenin' either. We got a problem brewin' in the Village of the Vines, just outside de city. With all the Horde landin' in the Harbor, some goblins got wind of our old kaja'mite quarry. They split outta here like the teeth of Deathwing himself behind 'em. But that quarry be dangerous. Wicked dangerous. Think you can go to de village an' talk some sense into them goblins?", ["objectivesText"] = "Travel to Village in the Vines.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 132267, ["x"] = 0.516, ["y"] = 0.505 }, { ["mapID"] = 862, ["npcID"] = 132617, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[49918] = { ["id"] = 49918, ["name"] = "Gorilla Gorge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49918 }, ["objectivesText"] = "Slay Da'kani gorillas", ["rewardGold"] = 4000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Slay Da'kani gorillas", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[49919] = { ["id"] = 49919, ["name"] = "Kaja'mite Ore Bust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49919, 49920, 49922 }, ["series"] = { 49917 }, ["description"] = "Kaja'mite! Just saying the name gives my big beautiful ears a buzz. These Zandalari were sitting on a huge deposit of it all these years. And they abandoned it just because of a few talking gorillas. By goblin law it's ours for the taking! Let's see how concentrated a deposit we're talking about. Get a good peek at those vents that are steaming out kaja'mite vapors. Go into the gorge and plant my scanners on those steam vents. They'll do the rest.", ["objectivesText"] = "Scan Kaja'mite Steam Vents in Gorilla Gorge.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 132267, ["x"] = 0.516, ["y"] = 0.505 }, { ["mapID"] = 862, ["npcID"] = 132617, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 132267, ["x"] = 0.516, ["y"] = 0.505 }, { ["mapID"] = 862, ["npcID"] = 132617, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5400, ["name"] = "Gorilla Greatness", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49920] = { ["id"] = 49920, ["name"] = "Gorilla Warfare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49919, 49920, 49922 }, ["description"] = "Your timing is most fortuitous, stranger. I thank you for your assistance. Things are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. My brethren are those who do not wish to fight. Neither the Zandalari trolls nor each other. But for our passivity we have been persecuted. Please free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!", ["objectivesText"] = "Rescue 6 Pacifist Gorillas.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130947, ["x"] = 0.502, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131258, ["x"] = 0.474, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5400, ["name"] = "Gorilla Greatness", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49922] = { ["id"] = 49922, ["name"] = "King Da'ka", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49919, 49920, 49922 }, ["description"] = "These Zandalari won't go near Gorilla Gorge. All because they're afraid! It's just a few talking gorillas. And one 'big mon' in particular as the Zandalari call him. All we need to do is take out King Da'ka and the villagers will probably throw us a parade! Or at least let us mine that kaja'mite. Think you can handle one big gorilla, chum?", ["objectivesText"] = "Slay King Da'ka .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 414, 17005, 17006, 30009, 30010, 30011, 30012, 39676, 39678, 39679, 39680, 44358, 44359, 44360, 44361, 56706, 56707, 58984, 58985, 58986, 65927, 65935, 65952, 65959, 65976, 65983, 65997, 66018, 66019, 66027, 66028, 66036, 66037, 66043, 79869, 87342, 87343, 87344, 87345, 87346, 87347, 87348, 87349, 87350, 87399, 89125, 91806, 111660, 114695, 114696, 114697, 114698, 118776, 118777, 118778, 118779, 118780, 128870, 131234, 131490, 147442, 156688, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776, 197381, 201294, 211279, 237812, 242386, 244858, 245631, 246727 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 132267, ["x"] = 0.516, ["y"] = 0.505 }, { ["mapID"] = 862, ["npcID"] = 132617, ["x"] = 0.516, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 132267, ["x"] = 0.516, ["y"] = 0.505 }, { ["mapID"] = 862, ["npcID"] = 132617, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5400, ["name"] = "Gorilla Greatness", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49926] = { ["id"] = 49926, ["name"] = "The Road to Corlain", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "Lord and Lady Waycrest lay trapped in Waycrest Manor. Before we can reach them, however, we must brave through the city of Corlain... which is firmly in the grasp of the Heartsbane. Our first course of action should be to set up a forward outpost. Our scouts have found that the tower at Watchman's Rise is only lightly guarded. I recommend we take the tower from them. This is now your command, Inquisitor. Say the word, and we ride.", ["objectivesText"] = "Meet with Marshal Reade at Watchman's Rise in Drustvar .", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 129643, ["x"] = 0.368, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 38, ["flags"] = 0 } } },
[49939] = { ["id"] = 49939, ["name"] = "So Long, Sister", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "We have given the defenders some breathing room, but these creatures continue to lay siege to the barricade! The witch behind the attack fled from the field when we defeated her forces. I saw her go into the mansion on the hill. I will help keep the defenses going here. You must go into the mansion and slay the witch!", ["objectivesText"] = "Slay Sister Noella Briarwood . Progress: The witch must be slain!", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 156710, 156828 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131442, ["x"] = 0.258667, ["y"] = 0.707333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.257, ["y"] = 0.6775 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 3, ["flags"] = 0 } } },
[49940] = { ["id"] = 49940, ["name"] = "Sandscar Breach", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 862, ["storyline"] = { 49940 }, ["description"] = "I heard some mutterings about sand and snakes. The plea comes from a tiny village on the very fringes of Zuldazar - hardly more than a few farms. Dol-something I think it was called. Don't know what they be calling it now. Go see what the fuss is about. Bladeguard Sonji was sent ahead some time ago. She should be able to get you up to speed on that... situation.", ["objectivesText"] = "Meet Bladeguard Sonji at Sandscar Breach.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130450, ["x"] = 0.472, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9598 } }, ["questType"] = "standard" },
[49943] = { ["id"] = 49943, ["name"] = "Drawing Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49943, 49944, 49946 }, ["series"] = { 49944 }, ["description"] = "Hey, <name>! I have something exciting to tell you about, but I need you to keep it secret. Just between us scribes. <Grazzul gives you a nod and pulls out a large tome.> Dis is de Bloodbound Ledger. Signing your name in it let's you learn how to craft \"blood contracts\" which are rather dangerous, but worth de risk. I only know one of dem and it is quite de rush when I use it because it... well, you'll see. So what do you say? Interested?", ["objectivesText"] = "Sign the Bloodbound Ledger.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 130901, ["x"] = 0.422, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 130901, ["x"] = 0.422, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 902, ["name"] = "8.1.5 Inscription - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[49944] = { ["id"] = 49944, ["name"] = "Turn to Drust", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49943, 49944, 49946 }, ["series"] = { 49943 }, ["description"] = "Dere are blood scribe masters all over de place who'll teach you what you need to know. De first master I'd recommend seeking out is Kronah . She's a bit... eccentric to say de least. One of de few tortollan who've experienced a thing or two. She's de one who taught me de blood contract I know how to invoke! She prefers to hang out at de Smuggler's Cove on de western coast of Drustvar.", ["objectivesText"] = "Seek out Kronah at the Smuggler's Cove in Drustvar.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 130901, ["x"] = 0.422, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131386, ["x"] = 0.206, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 896, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 902, ["name"] = "8.1.5 Inscription - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[49946] = { ["id"] = 49946, ["name"] = "Lines In the Sand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "inscription" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49943, 49944, 49946 }, ["description"] = "This was all I had to offer you, young scribe. But your journey is not yet at an end. If you're up for some traveling, and interested in some of the deadlier blood contracts, you're going to have to travel to Zandalar. Once there, seek out a sethrak by the name of Veriss in an area known as Vol'dun. < Kronah grabs an odd-looking jar and opens it. The foulest odor you've ever smelled emanates from it and you reel in disgust.> Pickled crocolisk eggs are my favorite. Would you like some?", ["objectivesText"] = "Seek out Veriss at the Terrace of the Devoted in Vol'dun to begin your blood trials there.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131386, ["x"] = 0.206, ["y"] = 0.44 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 150318, ["x"] = 0.276, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.44 }, ["mapCandidates"] = { ["npc"] = { 864, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 902, ["name"] = "8.1.5 Inscription - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49952] = { ["id"] = 49952, ["name"] = "The Essence of G'huun", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["storyline"] = { 49952 }, ["description"] = "Analysis of blood-infused bones complete. Will be able to create synthetic essence similar to G'huun. Will take a moment to apply essence, allow you to walk past undead without combat. Must hurry. More forces of G'huun are around temple. Must get inside to reactivate containment protocols.", ["objectivesText"] = "Have Titan Keeper Hezrel apply Synthetic Essence to allow safe passage past undead.", ["rewardGold"] = 25740, ["rewardXP"] = 345, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[49960] = { ["id"] = 49960, ["name"] = "Sic 'Em!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49960 }, ["description"] = "Humphrey's a good tracker, to be sure. He's also the orneriest, angriest, most dogged dog if he sets his eyes on a quilboar. This will certainly be useful. Below our very noses, the foreman organizes and directs the tunnelers to cause the most mayhem and destruction. If you can put an end to him, it should make things a lot easier for us to move around the farmlands. Humphrey looks a bit hungry, wouldn't you say? Why don't you bring him with you to take care of business?", ["objectivesText"] = "Defeat Foreman Razorgnarl . Progress: If I could rate Humphrey, I'd give him at least a twelve out of ten.", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["rewardItems"] = { 21392, 87399, 154990, 188658, 211279 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131656, ["x"] = 0.509, ["y"] = 0.703 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131656, ["x"] = 0.509, ["y"] = 0.703 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.509, ["y"] = 0.703 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[49969] = { ["id"] = 49969, ["name"] = "Awaken a God", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 48014, 48015, 48025, 48026, 49969, 51538 }, ["description"] = "You see the sinking ruins to the east? They were, not long ago, a temple to the shark loa, Gral. The naga tore down his temple and are stealing his secrets. If it is for something good, I'll be a rock's uncle. It would be wise to let Gral know what's going on here. I do not think he would approve. Gral was quite powerful, and when it came to his knowledge of the sea, none could compare. It never hurts to have a fellow like that on your side. Some fresh, bloody naga meat may just lure him out.", ["objectivesText"] = "Gather chunks of naga flesh as an offering to Gral. Progress: <There is a feeling of anticipation emanating from the bowl.>", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 156539, 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 125039, ["x"] = 0.792, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5410, ["name"] = "The Sunken City", ["orderIndex"] = 2, ["flags"] = 0 } } },
[49991] = { ["id"] = 49991, ["name"] = "Featherfeet's Fun Falling's Fun Fee!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 49991 }, ["description"] = "Welcome to Zuldazar , my fine $pr friend! I've explored every inch of this wonderful city with my own two feet. And let me tell you, they're tired! That's why I've decided to provide a service to my powerful friends in the Horde: Featherfeet's Fun Falling! Now, I know what you're thinking. You nomrally associate falling with screams, pain, and an untimely death. BUT NOT WITH FEATHERFEET! For a small one-time fee, I'll make sure you always float down this ziggurat shrouded in safety and fun.", ["objectivesText"] = "Pay 100 gold to Quinsy Featherfeet and he'll cast Slow Fall on you whenever you're nearby.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[50001] = { ["id"] = 50001, ["name"] = "Breaking Hag", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "The town is overrun! The guards have fallen back and what is worse, some of the villagers have been twisted by the witches' magic. They are little more than wretched beasts blindly following orders. We must release these poor souls and slay the monsters that twisted them! See what you can do to cut down the numbers of monsters in town!", ["objectivesText"] = "Kill 15 Briarwood Creatures and Witches. Progress: We have a little breathing room.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 156710, 156828 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.257, ["y"] = 0.6775 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50002] = { ["id"] = 50002, ["name"] = "A Very Precious Cargo", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47755, 50002, 50005, 50026, 50059 }, ["description"] = "We weren't the only ship in our convoy to get caught up in this mess. Our flagship ran aground to the east. It was holding a very precious cargo and I need you to bring it back here.", ["objectivesText"] = "Find the \"Precious\" cargo in Fogcliff Strand.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 123415, ["x"] = 0.502, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131684, ["x"] = 0.528, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5437, ["name"] = "A Sirens Song", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50003] = { ["id"] = 50003, ["name"] = "The First Watch", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "As you can see, the coven has conscripted my own guardsmen into their service. Though I am loath to battle my own, these men are too corrupted by the coven's magic to be saved. For them, death is the only mercy we can give. The Inquisitors and I can handle the regiment stationed outside. We will need you to find and take out their leader. Your Inquisitors await your command, <class>. Are you ready to take the tower?", ["objectivesText"] = "Defeat Sister Adela at Watchman's Rise. Progress: We assault the tower at your command.", ["rewardGold"] = 561800, ["rewardXP"] = 3455, ["rewardItems"] = { 155155, 155156, 155163, 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.314667, ["y"] = 0.271333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 39, ["flags"] = 0 } } },
[50005] = { ["id"] = 50005, ["name"] = "Hold My Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47755, 50002, 50005, 50026, 50059 }, ["description"] = "Take me to my daddy this instant! Waaaait! You have to hold my hand...", ["objectivesText"] = "Escort Penny back to her father. Progress: Where is she? Don't tell me you lost her.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 151135, 158262, 158263, 158264, 158265, 160087 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131684, ["x"] = 0.528, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 123415, ["x"] = 0.502, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5437, ["name"] = "A Sirens Song", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50009] = { ["id"] = 50009, ["name"] = "Shipwreck Recovery Crew", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50009 }, ["description"] = "Fogcliff Strand is swarming with Sirens and Saurolisks! Clear them out and grab any remaining cargo from the ships.", ["objectivesText"] = "Kill Creatures and Collect Cargo", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Kill Creatures and Collect Cargo", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895 },
[50026] = { ["id"] = 50026, ["name"] = "Save Our Shipmates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47755, 50002, 50005, 50026, 50059 }, ["description"] = "Oh, thank the stars! Our ship ran aground and our men are in desperate need of help. Find Henry Hardwick down the hill at the shipwreck. He stayed behind to try and help the others.", ["objectivesText"] = "Find Henry Hardwick in Fogcliff Strand.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131627, ["x"] = 0.494, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 123415, ["x"] = 0.502, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.494, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5437, ["name"] = "A Sirens Song", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50036] = { ["id"] = 50036, ["name"] = "A Weapon of Old", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "I've been studying the parchment Lady Lucille sent with you and have translated some of the older language. They called it \"Liquid Fire\" and it was used to \"burn away the Drust\". Using this as a basis I believe we can adapt it to our needs. This is a complex recipe, but it just so happens I have everything we need to make this potent alchemical weapon! I will need your assistance in creating this. Would you be so kind as to help?", ["objectivesText"] = "Help Master Ashton create the Liquid Fire potion. Progress: We'd better get cooking!", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156710, 156828, 237812 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131448, ["x"] = 0.252, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131448, ["x"] = 0.252, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 8, ["flags"] = 0 } } },
[50041] = { ["id"] = 50041, ["name"] = "A Pocketful of Shells", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50041, 50065, 50069, 50088 }, ["series"] = { 50157 }, ["description"] = "You see the problem? No you don't. Problem isn't all these dang quilboar. Quilboar I can shoot all day. Been shootin' em all my life, since my pappy gave me my first gun. Problem is these pigs are tough. Tougher'n they've been before. Can't kill em like I used to, see? My new modified bullets just get stuck in them and they refuse to die! Here, take my knife. Go out there and kill some of the quilboar and get my ammo back. Then I can shoot the rest! I won't stop 'till there's none left to shoot!", ["objectivesText"] = "Collect 20 Salvaged Azerite Ammunition . Progress: Pretty sure I'll have to start shootin' my dinnerware, and I only have three sets. Hurry up, will you?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156583, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.507, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 738, ["name"] = "Goldfield's War", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50043] = { ["id"] = 50043, ["name"] = "Archaeological Efficiency", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47228, 47235, 47329, 48317, 48399, 48400, 50043 }, ["description"] = "Miss Tae'shara and I share a passion for uncovering hidden secrets and a deep, abiding respect for this ancient land. That said! If we were to continue at the pace to which she is accustomed, the Alliance would overtake us before we could make a single discovery. It is time to expedite our survey. The ruins hide many fossils. Take a beacon and use it to summon one of my sweepers. It will clear away the topsoil and allow you to collect samples. Gather what you can- we can assemble them later.", ["objectivesText"] = "Collect 50 Xibalan fossil fragments . Progress: I simply see no reason to dirty our hands, <name>.", ["rewardGold"] = 292100, ["rewardXP"] = 1415, ["rewardItems"] = { 156596, 156597 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131580, ["x"] = 0.413333, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.413333, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5403, ["name"] = "Fossil Extraction", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50044] = { ["id"] = 50044, ["name"] = "Archaeological Efficiency", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50044 }, ["description"] = "Suppose I owe the lass her bones if I'm tae be monopolizin' yer time. And I will be. Go on out into the ruins an' use this here stone to call one of my rumbly elemental friends. They'll blast away any dirt 'tween you an' the fossils. We could go about this the ol' fashion way, but do you really want to spend all day digging? Course ye don't. Acadia will see that a little efficiency gets everyone what they want.", ["objectivesText"] = "Use the Elemental Summoning Stone to expose Xibalan fossils. Bring 50 Xibalan Fossil Fragments to Acadia Chistlestone . Progress: <Acadia eyes Morgrum sourly.> I don't think he cares one lick about our expedition, <name>.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 156597, 159640 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 131763, ["x"] = 0.429333, ["y"] = 0.732667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131777, ["x"] = 0.412, ["y"] = 0.714 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.429333, ["y"] = 0.732667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50054] = { ["id"] = 50054, ["name"] = "The Seething Shore", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 49977, 49982, 50052, 50053, 50054, 50055, 50057, 50230, 50231, 50232, 50300, 50341, 50358, 50360, 50364 }, ["description"] = "We've received reports of an island off the coast of Silithus that is ripe with Azerite deposits. It is vital that we secure the island before the Alliance learns of its existence. Nathanos Blightcaller is personally leading the expedition force and has requested that you report for duty. Go with honor!", ["objectivesText"] = "Complete the Seething Shore battleground.", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132147, ["x"] = 0.658, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 576, ["name"] = "Silithus: The Wound", ["orderIndex"] = 13, ["flags"] = 0 } } },
[50058] = { ["id"] = 50058, ["name"] = "The Witch's Pet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50058 }, ["description"] = "I've seen her! The witch! Every once in a while she comes down to the cave, checking on her pet. I've never seen a spider so large! She spreads her spell, cursing all of the animals in these woods to follow her command and attack us. The broodmother laid all these eggs, and they're hatching into more possessed beasts! Take her out, and perhaps the infestation will stop.", ["objectivesText"] = "Kill the Mossfang Matriarch .", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 134325, ["x"] = 0.728, ["y"] = 0.175 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129669, ["x"] = 0.696, ["y"] = 0.189333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[50059] = { ["id"] = 50059, ["name"] = "Can't Hear A Thing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47755, 50002, 50005, 50026, 50059 }, ["description"] = "These snake wenches show up and everyone loses their minds! All my men are head over heels for these things. Personally, I don't see it. I mean, I sort of get the appeal, but the wings for arms and snake tails are a big turn off. There's a big one in a cave to the east. She's got a whole heap of suitors. I need them back to work. Go give her a wallop and get everyone back here.", ["objectivesText"] = "Kill Anthemusa .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 160452 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131775, ["x"] = 0.51, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131775, ["x"] = 0.51, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5437, ["name"] = "A Sirens Song", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50063] = { ["id"] = 50063, ["name"] = "Fighting With Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "Excellent! Now that we have these lovely Liquid Fire flasks prepared we have one last thing to do: Test them out! There are some of those large abominations lurking about in the woods above my home. I think they would make excellent test subjects for our little alchemical experiment, wouldn't you say?", ["objectivesText"] = "Test the Liquid Fire flasks on 3 Briarwood Bulwarks . Progress: Help!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 155159, 155162, 156710, 156828 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131448, ["x"] = 0.252, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131469, ["x"] = 0.253333, ["y"] = 0.691333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50064] = { ["id"] = 50064, ["name"] = "Don't Go in the Basement", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "We checked everywhere... well, <gulps> everywhere except the basement. B-b-but, dad told me never to go down there. He said it's dark, scary, and dangerous to go alone... I could be eaten by a brue! I don't even know what that is, but I don't wanna be eaten! <name>, do you think you could go down first?", ["objectivesText"] = "Enter the basement.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160331, 160346 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132647, ["x"] = 0.71, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50065] = { ["id"] = 50065, ["name"] = "A Reason to Stay", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50041, 50065, 50069, 50088 }, ["description"] = "<You find a pocketwatch on the ground. It is dirty, but still works. It was taken care of well. Perhaps there are other objects that Goldfield wasn't able to grab before he had to hole up in his house. He might appreciate it if you brought them to him.>", ["objectivesText"] = "Search the Goldfield Farmstead for additional keepsakes. Progress: For the last time, I'm not leaving! I was here first, THEY can leave!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 142555, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561, 237812 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.507, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 738, ["name"] = "Goldfield's War", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50069] = { ["id"] = 50069, ["name"] = "Goldfield's War", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50041, 50065, 50069, 50088 }, ["description"] = "I'm not leaving. I'm never leaving. Those quilboar, they killed them. I gave her the watch, told her to hurry. Grab our boy and get to the house while I got the gun... <Goldfield is choking back tears.> I won't leave. Our family has our roots here. They would want me to stay, don't you understand? This is our farm. My boy, he wanted to join the militia. I made him a sword... <Goldfield takes a deep breath.> Now you know. Help me retake my farm. Grab a gun and let's kill every last one.", ["objectivesText"] = "Defeat the quilboar invaders. Progress: This is MY home!", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.507, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 738, ["name"] = "Goldfield's War", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50070] = { ["id"] = 50070, ["name"] = "Detective Mildenhall", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "Hmm... okay, okay, let's think. If you were my dad and you accidentally set loose a bunch of honey monsters all over the place, what would you do? Well, okay, you would probably beat all of them up. But he probably ran away. If he left in a hurry, maybe he left something for us to find.", ["objectivesText"] = "Search the Mildenhall Meadery for clues. Progress: Did you find anything else?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 156628 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50074] = { ["id"] = 50074, ["name"] = "Brutal Boost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["description"] = "The Aggression Formula is ready and I need you to inject Ben'jin with it. Let's show the world, and the witch doctor, that well researched, dramatically overpowered, double-blind, peer-reviewed, super goblin science is the right way to do, uh, pretty much anything!", ["objectivesText"] = "Administer the Aggression Formula to Gentle Ben'jin. Progress: This is exciting, isn't it?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 156475 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130905, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130905, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50080] = { ["id"] = 50080, ["name"] = "Raiding the Raiders", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50080 }, ["objectivesText"] = "Assault Koramar", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["rewardItems"] = { 157029, 159827 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Assault Koramar", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863 },
[50083] = { ["id"] = 50083, ["name"] = "The Crawg Ma'da", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50083 }, ["series"] = { 50085 }, ["description"] = "No matter what we do, as long as dem blood trolls have their village here, dey gonna be a threat. We gonna put an end to dat threat! Amaka be da strongest blood troll I ever seen, and she be right across da way there. She be feedin' da bodies of da Zandalari ta her pet crawgs, makin' dem big, fat, and deadly. It be time for revenge, and we be doin' it wit' da help of her own pets. Go kill a crawg and cut its poison gland out of its belly. With it, ya can weaken Amaka and put an end to her.", ["objectivesText"] = "Obtain a Crawg Poison Gland and slay Amaka the Crawg Ma'da .", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 156868, 159827 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 133471, ["x"] = 0.454, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 133338, ["x"] = 0.482, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[50084] = { ["id"] = 50084, ["name"] = "Back On Your Feet, Soldier", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["storyline"] = { 50084 }, ["description"] = "I figured any soldiers we be coming across might be wantin' some revenge, so I brought along some extra weapons just in case. See up ahead? Dem cages be full of trolls awaitin' der turn ta die. We gonna swoop in der and be da answers to der prayers! Go and arm as many of dem as ya can, revenge gonna be sweet!", ["objectivesText"] = "Give weapons to 10 Zandalari Captives .", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[50085] = { ["id"] = 50085, ["name"] = "A Message of Blood and Fire", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50085 }, ["series"] = { 50083 }, ["description"] = "Look at what I be findin' here. Dis one had a magic wand in his hand. < Rokhan shuts his eyes for a moment.> Mmmmm... it be warm. Mojo of fire be within. Perfect! Take dis ting an' give 'em a taste of their own firepower. Burn da whole village down!", ["objectivesText"] = "Use the Wand of Embers to set ablaze 8 Blood Troll huts in Agwamar.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156931, 159827 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 133338, ["x"] = 0.482, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 133475, ["x"] = 0.44, ["y"] = 0.543 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["startItems"] = { 156939 } },
[50088] = { ["id"] = 50088, ["name"] = "Golden Fields Forever", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50041, 50065, 50069, 50088 }, ["description"] = "I can take care of the rest. That ettin would have given me trouble if I was by myself, so you have my thanks. I would ask you for one more favor. My wife, she loved the carnations that grow by the water's edge. If you could gather some, there's a nice spot under a tree by the river. We loved to go there when the sun set after our days in the fields. Our boy would run around, catching bugs, making reed whistles...", ["objectivesText"] = "Lay Farmer Goldfield 's family to rest. Progress: That's that, then.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.507, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 738, ["name"] = "Goldfield's War", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50090] = { ["id"] = 50090, ["name"] = "Building Defenses", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "We'll be able to push those monsters back now, but my defenders won't stand a chance unless we build a forward barricade for protection. There should be plenty of lumber to build a barricade near the entrance to town.", ["objectivesText"] = "Collect lumber to build forward barricades. Progress: We've pushed the front line out. That will give us some room.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 158611, 158612, 158613, 158614, 160189, 160190, 160191, 160192 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131442, ["x"] = 0.258667, ["y"] = 0.707333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131442, ["x"] = 0.258667, ["y"] = 0.707333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.258667, ["y"] = 0.707333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50091] = { ["id"] = 50091, ["name"] = "Village Repair", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50091 }, ["objectivesText"] = "Destroy signs of witchcraft", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["rewardItems"] = { 156710, 156828 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Destroy signs of witchcraft", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896 },
[50092] = { ["id"] = 50092, ["name"] = "Curiously Strong", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "I imagine the fires spread while I was down here, yes? First order of business then; making sure the town doesn't burn down! Help solve that problem and I shall be free to assist you in... whatever it is? Let's see... Yes! Here! Take these. They proved to be bit too... intense for most people, but you seem like a stout sort. Just be sure you're facing the fires when you use them, and I'm certain those fires will be out in no time!", ["objectivesText"] = "Use the Frost Breath Potion to put out the fires. Progress: If we don't stop the fires, they could spread!", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 156710, 156828 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131448, ["x"] = 0.252, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131448, ["x"] = 0.252, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50110] = { ["id"] = 50110, ["name"] = "Bearers of Bad News", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["series"] = { 49741, 50787, 50788, 50789, 50790, 50795 }, ["description"] = "We must report this attack to Lord Admiral Katherine Proudmoore and prove to her that Lady Ashvane is behind it. It won't be easy... Lady Ashvane and Katherine Proudmoore have been close friends for years. Quickly, let us make for Boralus!", ["objectivesText"] = "Return to Boralus with Taelia .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 162522 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 142393, ["x"] = 0.564, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135259, ["x"] = 0.4904, ["y"] = 0.8232 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 39, ["flags"] = 0 } } },
[50111] = { ["id"] = 50111, ["name"] = "Totems, Totems, Totems!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50111 }, ["description"] = "<This totem pulses with energy, releasing it into the nearby idols and thorns. It looks rather fragile... It would be a shame if something happened to it.>", ["objectivesText"] = "Destroy the Brambleguard Totems in Briarback Kraul.", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 175199, 175200, 175201, 175202, 175231, 175232, 175233, 175238 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130190, ["x"] = 0.576, ["y"] = 0.665 }, { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[50112] = { ["id"] = 50112, ["name"] = "Casting the First Stone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["description"] = "Hey dere <name>, gimme a hand with dis, would ya? <Kumali motions you over to her.> I got dis recipe dat I've been trying to remember de rest of, but I'm having de hardest time coming up with de right ingredients. Ya see, my partner ran off with de other half of de recipe on account of a disagreement we had. But dis stone, it's a treasure like no other. Grab some vials and start mixing dese ingredients together. Let's see if dey are de right ones.", ["objectivesText"] = "Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Kumali's shop. Progress: I will never ask for de other half of de recipe back from dat... dat... imbecile. I'll figure it out, ya see.", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["rewardItems"] = { 156653, 156654, 166371, 166372, 166373, 166374 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50113] = { ["id"] = 50113, ["name"] = "Ocular Extracts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 1165, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["series"] = { 50115, 50116 }, ["description"] = "So dere's a creature in dese lands whose eyes are perfect for alchemical recipes. Dey might just be de thing we need to finish dis project. Although, I don't remember seeing dem on de full recipe list de last time I saw it, ya see... But my memory isn't quite what it used to be. Gah! I'm rambling too much. Get me some eyes, will ya, <name>?", ["objectivesText"] = "Gather 10 Razorwing Eyes and return them to Kumali. Then observe as she tries to make the stone with them. Progress: Make sure to gather de eyes after de creature is dead, otherwise dey make de most horrible sound when ya try to take dem out.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156806 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50114] = { ["id"] = 50114, ["name"] = "Hammering Out Information", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50114, 50123, 50270, 50275 }, ["series"] = { 50270 }, ["description"] = "I guess you noticed it requires a special anvil to make it. And I suppose you want to know where to find a Khaz'gorian Smithing Anvil? Well, I don't know where you can find one, not to mention I never said you'd be able to actually craft the dang thing. Now if you wouldn't mind, I have more of these recipes to sell.", ["objectivesText"] = "Press Grix Barlow for more information about where to find a Khaz'gorian Smithing Anvil. Progress: That recipe really is worth what you paid for it, regardless of whether you can craft it or not.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 896, ["name"] = "8.1.5 Blacksmithing - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50115] = { ["id"] = 50115, ["name"] = "Changing the Scenery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["series"] = { 50113, 50116 }, ["description"] = "Or maybe de problem is dat we don't need regular reagents. Maybe we need something dat only comes from being transmuted. Anything's worth a shot at dis point. Here is a recipe my old partner left behind. He used to go out to de Slough and change de shrubs into bubbles, ya see. Why, you might ask? 'Cause he loved transmuting everything. Part of de reason we never saw eye to eye. Anyways, bring me back some of dose bubbles and we'll see if we can use dem to make dis stone.", ["objectivesText"] = "Go to The Slough and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them. Bring them back to Kumali and observe as she tries to use them to make the stone. Progress: I've seen him using dem in lots of his projects, so there has to be some alchemical qualities to dem.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156660 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50116] = { ["id"] = 50116, ["name"] = "A Possible Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["series"] = { 50113, 50115 }, ["description"] = "None of dese things are working. I can't believe I'm saying dis, but I think you're gonna have to find Zukashi . Maybe you could convince him to give up de other half of de recipe. He's pretty full of himself, but he isn't unreasonable. Last time I heard, he's staying in Nazmir near Gloom Hollow. Maybe it's best to tell him dis isn't about me.", ["objectivesText"] = "Travel to Nazmir and seek out Zukashi .", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 132680, ["x"] = 0.64, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 863, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50117] = { ["id"] = 50117, ["name"] = "A Deathly Draught", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["series"] = { 50118, 50119, 50120 }, ["description"] = "De first thing I'd like you to do for me is to gather some deathshroom . Don't worry if you're not skilled at herbalism, they're very easy to pick. Dey typically grow where death lingers in the air. I'd try to de Frogmarsh to de southeast. De trolls dere have been making sacrifices of de creature dat inhabit de area.", ["objectivesText"] = "Collect 15 Deathshrooms . Progress: Have you finally acquired my mushrooms? It's a simple task, even for someone like you.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156658 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 132680, ["x"] = 0.64, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 132680, ["x"] = 0.64, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50118] = { ["id"] = 50118, ["name"] = "A Stone's Throw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["series"] = { 50117, 50119, 50120 }, ["description"] = "Now dis ingredient you might have some fun getting, little mixah. I'm gonna give you dese stones. They're able to turn things into other things. Dose blood trolls, de ones giving de rest of us a bad name? Dey drink de weirdest things and it taints their bodies. I need their blood to finish my work here, but without de taint. Dese stones will turn dem into weaker creatures. Although, sometimes de stones turn dem into other things... Be careful with dem.", ["objectivesText"] = "Use the Bag of Transmutation Stones on blood trolls and kill them. Collect 8 Vials of Altered Blood from them. Progress: Ya never know what you'll get with transmuting things until ya try. Ain't dat right?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156664, 156831 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 132680, ["x"] = 0.64, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 132680, ["x"] = 0.64, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50119] = { ["id"] = 50119, ["name"] = "Chemically Compounded", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["series"] = { 50117, 50118, 50120 }, ["description"] = "Now dat I have everything I need, I can finish dis project. My latest transmuation will be my finest yet! But dis is not de place to test it. It could draw too much attention. If you want to see it for yourself, little mixah, meet me to de north. Dere is a cave dere dat should be a safe spot for testing dis out.", ["objectivesText"] = "Meet Zukashi at the cave he mentioned. And be ready for anything to happen.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 132680, ["x"] = 0.64, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50120] = { ["id"] = 50120, ["name"] = "A Recipe for Success", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 1165, ["storyline"] = { 50112, 50113, 50115, 50116, 50117, 50118, 50119, 50120 }, ["series"] = { 50117, 50118, 50119 }, ["description"] = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for. An odd signature completes the recipe, signed, \"Silas Darkmoon\". Kumali should be very pleased to see this once again.", ["objectivesText"] = "Bring the torn paper back to Kumali.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122703, ["x"] = 0.422, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 900, ["name"] = "8.1.5 Alchemy - Horde", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50121] = { ["id"] = 50121, ["name"] = "Casting the First Stone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["description"] = "Would you mind helping me out with something, <name>? <Elric motions you over to him.> You see, I have this recipe that, well, I only have half of currently. I've been trying to remember the other half but just can't seem to recall it. My EX-partner tore the recipe and ran off with the other half over a disagreement we were having. But the stone it makes is invaluable. How about you grab some vials and start mixing the ingredients on this list. Perhaps together we can figure this out.", ["objectivesText"] = "Craft a Potion of Durability and a Potion of Shifting States using the recipes given to you. You can find the ingredients you need in Elric's shop. Progress: I wouldn't dare ask for the other half back, not after what Quintin said to me. I'll get this mystery figured out, you'll see.", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["rewardItems"] = { 156653, 156654, 166371, 166372, 166373, 166374 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50122] = { ["id"] = 50122, ["name"] = "Ocular Extracts", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 1161, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["series"] = { 50124, 50125 }, ["description"] = "My next idea involves a creature whose eyes are useful for certain alchemical recipes. At least for potions they are. Hopefully they're just what we need for this and there aren't any further... miscalculations. Although, I don't entirely recall seeing them on the recipe's ingredient list... but my memory isn't exactly as good as it used to be. Oh, you caught me rambling. How about you get those eyes and I'll start making the preparations for them.", ["objectivesText"] = "Gather 10 Highlands Mauler Eyes and return them to Elric. Progress: Oh, I do hope you gathered the eyes post mortem. Those creatures make the most awful sound if you try to extract them while they're still alive.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156657 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50123] = { ["id"] = 50123, ["name"] = "A Recipe For the Ages", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 1161, ["storyline"] = { 50114, 50123, 50270, 50275 }, ["description"] = "Yo, <name>, over here! You've look like you've been hammering away for a while. I can smell the flux on ya! <Grix gives you a wide grin.> Listen, I've got a recipe for the most amazing blacksmith hammer you've ever laid your eyes on. And I'd be willing to let it go for a bit of ore. Revlis ore to be exact. It's a little rare, but you can find plenty of it over in Gol Koval in Drustvar. The elementals there are practically made of it. Bring me back a haul of it, and the recipe's yours!", ["objectivesText"] = "Bring Grix Barlow back 30 pieces of Revlis Ore from Gol Koval in Drustvar. Progress: This recipe is probably worth a thousand, no TEN thousand gold! Blacksmiths all over will be envious of you, you'll see.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 152839, 156875 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 896, ["name"] = "8.1.5 Blacksmithing - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50124] = { ["id"] = 50124, ["name"] = "Changing the Scenery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["series"] = { 50122, 50125 }, ["description"] = "The stone this recipe becomes is a transmutation stone. What if the missing reagents to make it come from something that's gone through the transmutation process? I'm willing to try anything at this point. Here's an old recipe my ex-partner devised. He used to go out to Stormsong Valley, just south of the Highland Flats and change the shrubs there into bubbles. Bring back some of those bubbles and we'll see if they're what we've been missing.", ["objectivesText"] = "Go to Stormsong Valley and transmute Barberry Shrubs into Shrubbery Bubbles and gather 6 of them. Bring them back to Elric and observe as he tries to use them to make the stone. Progress: I've seen him use those globes in some of his projects in the past, so there is clearly some alchemical properties to them.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156660 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50125] = { ["id"] = 50125, ["name"] = "A Possible Solution", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["series"] = { 50122, 50124 }, ["description"] = "Nothing appears to be working. I can't believe I'm proposing this but I actually think we need to contact Quintin. Well, you should, as I doubt he'll speak to me. Perhaps you could convince him to part with the other half of the recipe? Last time I heard, he was staying in Drustvar near Arom's Stand. There's a lot of alchemists in those parts, but he shouldn't be too hard to find. Best not to tell him I sent you. He may not be as forthcoming with the recipe.", ["objectivesText"] = "Travel to Drustvar and seek out Quintin Whalgrene .", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132347, ["x"] = 0.3645, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 896, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50126] = { ["id"] = 50126, ["name"] = "A Deathly Draught", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["series"] = { 50127, 50128, 50129 }, ["description"] = "The first thing I'd like you to do for me is to gather some deathshroom . Don't worry if you're not skilled at herbalism, they're very easy to pick. They typically grow where death lingers in the air. I'd try to the Crimson Forest to the south. The creatures that have overrun it seem to be covered in deathly magics.", ["objectivesText"] = "Collect 15 Deathshrooms . Progress: Have you finally acquired my mushrooms? It's a simple task, even for someone like you.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156658 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132347, ["x"] = 0.3645, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132347, ["x"] = 0.3645, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3645, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50127] = { ["id"] = 50127, ["name"] = "A Stone's Throw", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["series"] = { 50126, 50128, 50129 }, ["description"] = "You may enjoy getting this next reagent for me. I have some special stones that have transmutative qualities, especially on living things. It's not too unlike the one you're trying to make. The witches that plague these lands are imbued with magic. As is their blood. I need their blood to finish my latest project, but in an altered form. These stones should turn them into weaker creatures. Although, sometimes the opposite occurs... I'd recommend handling them with care.", ["objectivesText"] = "Use the Bag of Transmutation Stones on witches and kill them. Collect 8 Vials of Altered Blood from them. Progress: You never truly know what a transmutation will yield until you try it. Wouldn't you agree, apprentice?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156665, 156687 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132347, ["x"] = 0.3645, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132347, ["x"] = 0.3645, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3645, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50128] = { ["id"] = 50128, ["name"] = "Chemically Compounded", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["series"] = { 50126, 50127, 50129 }, ["description"] = "That appears to be everything. This latest transmutation will be my finest yet. And your prize waits at its completion, apprentice. But I don't believe this is an appropriate place to test it out. It may draw too much attention. There's a cave not terribly far from here which would prove to be a more suitable setting for such a test. Meet me there when you're ready to witness why transmutation is the only branch of alchemy worth learning.", ["objectivesText"] = "Meet Quintin at the cave he mentioned. And be ready for anything to happen. Progress: This seems to contain some of Quintin's things.", ["rewardGold"] = 510120, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132347, ["x"] = 0.3645, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3645, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50129] = { ["id"] = 50129, ["name"] = "A Recipe for Success", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "alchemy" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 1161, ["storyline"] = { 50121, 50122, 50124, 50125, 50126, 50127, 50128, 50129 }, ["series"] = { 50126, 50127, 50128 }, ["description"] = "Looking it over more closely, you're convinced that this must be the missing half of the recipe you came for. An odd signature completes the recipe, signed, \"Silas Darkmoon\". Elric should be very pleased to see this once again.", ["objectivesText"] = "Bring the torn paper back to Elric.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 132228, ["x"] = 0.741, ["y"] = 0.065 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.741, ["y"] = 0.065 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 899, ["name"] = "8.1.5 Alchemy - Alliance", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50133] = { ["id"] = 50133, ["name"] = "Weed Whacking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50133 }, ["objectivesText"] = "Farmlands cleared", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Farmlands cleared", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942 },
[50134] = { ["id"] = 50134, ["name"] = "Gadgets and Gizmos Aplenty", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50134, 50135, 50136 }, ["description"] = "The militia may have given up on us, but we haven't given up on me! I'm a bit of a tinker, and I find that my harvest golems are better than any hired help I've ever had. They just need regular maintenance to keep running. Of course the Briarback are now taking over my fields, and my farmhands have gone into disrepair. If you head out into the fields, can you grab the inner mechanisms from any of them that you find? That will stop them from exploding as well as help me plan my revenge.", ["objectivesText"] = "Collect 10 Harvester Gizmos . Progress: Do you have the parts yet?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 739, ["name"] = "A Collapsing Crisis", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50135] = { ["id"] = 50135, ["name"] = "Stop Vining!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50134, 50135, 50136 }, ["description"] = "You may have noticed that the fields are a little... unstable right now. The Briarback have been busy, growing those large bramble vines and boring tunnels underneath the farm. The vines have always been an important part of their borders, and they're expanding! Go down into the lower area and see if you can find who or what is making those vines grow. There's no way that they're growing like that naturally. If we can stop the vines we can retake this area!", ["objectivesText"] = "Slay the three Vinemasters.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 739, ["name"] = "A Collapsing Crisis", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50136] = { ["id"] = 50136, ["name"] = "Farming Stimulator", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50134, 50135, 50136 }, ["description"] = "The plants have gone amok since you defeated their masters! Don't worry though, I've got a plan. I've been busy fixing up one of the farmhands that didn't go completely haywire. It should have enough juice for one more trip through the fields. We've got some serious technology in these harvesters. Their tools should be more than enough to take care of some small plants and even a couple quilboar. What do you say? You up for some farming the Stormsong way? Hop on in and get to work!", ["objectivesText"] = "Use the Piloted Farmhand to slay 30 enemies. Progress: Take out as many of them as you can!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155194, 155195, 155196, 155197, 155235, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 739, ["name"] = "A Collapsing Crisis", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50149] = { ["id"] = 50149, ["name"] = "A Weather Eye", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "It would be wise to get a lay of the land before we put together a plan of action. Inquisitor Notley is an expert falconer, and a reliable scout. He utilizes an ancient relic to see through the eyes of his falcon, allowing him to survey great distances. Unfortunately, Notley was injured during the fighting. Nothing serious, but it's left him unable to concentrate enough to control his falcon. Perhaps you could help?", ["objectivesText"] = "Speak with Inquisitor Notley at Watchman's Rise to scout the areas surrounding Corlain. Progress: What news do you bring?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.314667, ["y"] = 0.271333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 40, ["flags"] = 0 } } },
[50150] = { ["id"] = 50150, ["name"] = "Setting the Mood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["series"] = { 49814, 50154 }, ["description"] = "De voodoo love incense and romantic meal are ready, <name>. Take dem and place dem at de feet of Maka'fon. Quickly, if you could. Dat smell is... overwhelmingly, horribly, disgusting. Could you move any faster? Away. From us. For de sake of de brutosaurs, of course.", ["objectivesText"] = "Place and light the Voodoo Love Incense near Irritable Maka'fon and offer her the Romantic Brutosaur Meal. Progress: Best get dese stinking things over to Maka'fon soon, <name>. I guarantee it will get her in de mood.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50151] = { ["id"] = 50151, ["name"] = "A Steady Ballast", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "The Armory presents us a ripe opportunity, <class>... one I suggest we take. If this battle were to draw out, we have little means to repair our arms and armor. A blacksmith is invaluable to any war effort, and Ballaster is one of our best. The Armory is but a short ride from here. I suggest you get to Ballaster before it's too late!", ["objectivesText"] = "Find Angus Ballaster at the Corlain Armory. Progress: The blacksmith won't survive long with the coven hunting him down. I'd recommend leaving posthaste.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.314667, ["y"] = 0.271333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 41, ["flags"] = 0 } } },
[50152] = { ["id"] = 50152, ["name"] = "Digging for Scraps", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "Well met, <class>. I hope you don't mind that I took the liberty to scout ahead and assess the situation at the armory. The good news is that there still seems to be some salvageable arms left in the armory. The bad news, of course, is that the coven is after them as well. Additional weapons could be a great boon to our cause. I recommend we take all we can carry.", ["objectivesText"] = "Collect 10 Quality Salvage from the Corlain Armory. Progress: What did you find at the armory?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156663 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131641, ["x"] = 0.250667, ["y"] = 0.366667 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.250667, ["y"] = 0.366667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50154] = { ["id"] = 50154, ["name"] = "They Say It's a Delicacy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["series"] = { 49814, 50150 }, ["description"] = "A romantic meal is de way to set up an evening for love. Dis is true for us, so why not for Maka'fon? Bring her something rare and pleasing to her palate. Diemetrodons near de water eat hard seed pods and partially digest them. With a little voodoo, something magical can happen to de pods. It may be disgusting to you and I, but de brutosaurs consider it a rare delicacy. Such is life. Dere are plenty of diemetradons, so some must die dat de brutosaurs might live. Such is de purpose of death.", ["objectivesText"] = "Obtain 25 Partially Digested Pods from the bellies of nearby diemetradons. Progress: De pods we need become edible only in de belly of de diemetradons. Watch your fingers in dere... de scales are sharp.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 155917 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50157] = { ["id"] = 50157, ["name"] = "There's Gold in Them There Fields", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50157 }, ["series"] = { 50041 }, ["description"] = "We've still got some folks missing, and I could use your help finding them. While Brennadam is now secure, I worry for some of our farms closer to the quilboar kraul. We relied on the militia in the past to keep the quilboar back, but now that they've retreated to the east I worry that our outlying farms are in danger. Goldfield's farm is almost directly south of us, up the hill by the falls. While it's not surprising that he hasn't left, I would feel better if you checked in.", ["objectivesText"] = "Find Farmer Goldfield at his farm.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[50158] = { ["id"] = 50158, ["name"] = "Checking Out the Collapse", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50158 }, ["description"] = "If you've got a minute, there's a farmer out there who hasn't made it back yet. Name's Burton and he's out by a farm right next to Briarback Kraul. If the quilboar were to strike out, his farm is one of the first in their way. I haven't heard anything from Burton. He mostly relied on his mechanical farmers to help him, so we don't know the situation out there. Head to the west and keep an eye out for him, would you?", ["objectivesText"] = "Find Farmer Burton at his farm.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130694, ["x"] = 0.576, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[50161] = { ["id"] = 50161, ["name"] = "Recovering Raimond", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "The map we found earlier had some red markings, near the flower field. Do you think you could go up there and look for dad? I'm going to stay here and check out the rest of this stuff. I'd go with you... but, I'm sort of allergic to bees. Oh, and take his boot. Just in case!", ["objectivesText"] = "Find Raimond Mildenhall . Progress: It is about time someone came looking for me!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 156717, 156808 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 132647, ["x"] = 0.71, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132292, ["x"] = 0.74, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50162] = { ["id"] = 50162, ["name"] = "Sticky Situation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "The scientific breakthroughs I've made, marvelous, absolutely marvelous... I'm so close to perfecting the formula! The way the honey grows and crystallizes, simply beautiful. Well, as you can see, that's also part of my current predicament. Perhaps you can lend me a hand? Just fetch some royal jelly from the hives outside. Oh, don't worry about the bees, they are sweet, gentle things. They don't sting... much.", ["objectivesText"] = "Collect 60 Royal Jelly . Progress: You get all the jelly yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156709 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 132292, ["x"] = 0.74, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132292, ["x"] = 0.74, ["y"] = 0.726 }, { ["mapID"] = 942, ["npcID"] = 132355, ["x"] = 0.74, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50164] = { ["id"] = 50164, ["name"] = "Polly Want A Cracker?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50164 }, ["objectivesText"] = "Runaway Macaw fed", ["rewardItems"] = { 154878 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Runaway Macaw fed", ["amount"] = 6, ["type"] = 0, ["objectID"] = 132339, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50165] = { ["id"] = 50165, ["name"] = "The Bee Team", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "We need to put things in order, and the next item on the list is these blasted wendigos terrorizing the farm. If we can cull their numbers, it should be enough to drive them off! I've synthesized a superb solution that might be just what we need to solvent this sticky situation! Toss these bottles at your foes and our friendly little apoideas should come to help. Whatever you do, please don't spill any on yourself...", ["objectivesText"] = "Kill 12 Highland Maulers.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 157851 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134447, ["x"] = 0.74, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134447, ["x"] = 0.74, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 8, ["flags"] = 0 } } },
[50168] = { ["id"] = 50168, ["name"] = "Royal Succession", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "I know, I know, okay... the farm is overrun by living honey and the bees have grown to massive proportions. I'll admit, things didn't quite go according to plan, but, extraordinary advancements in science do not come without some risk! I've been up here attempting to reduce aggression in the hive, an unfortunate side effect of my miscalculation, but I need another favor... You're going to have to kill the Hive Mother and retrieve her stinger for me.", ["objectivesText"] = "Retrieve the Hive Mother's Stinger . Progress: Oooh, ooh, do you have it!?", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["rewardItems"] = { 157839 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 132292, ["x"] = 0.74, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132292, ["x"] = 0.74, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50172] = { ["id"] = 50172, ["name"] = "Into the Crimsonwood", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["series"] = { 50265 }, ["description"] = "Master Ashton has been taken into the forest. He isn't the only one. Mayor Royston's headcount came up short. It seems our next steps are clear. We must go into the woods and save Master Ashton. Marten and I will sneak into the forest and meet you near some ruins further in.", ["objectivesText"] = "Meet Inquisitor Cleardawn in the Crimson Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.257, ["y"] = 0.6775 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 10, ["flags"] = 0 } } },
[50173] = { ["id"] = 50173, ["name"] = "Precious Metals", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "<class>, I have another objective we should consider. The Bleak Hills Mine is not too far from our location. Though the miners there principally extract iron, they do on occasion find silver among the veins. We do not know the current state of the mine, but it's unlikely that the coven has passed it over. However, it would be worth braving whatever dangers lie there to recover some silver to use against them.", ["objectivesText"] = "Collect 10 Silver Nuggets from the Bleak Hills Mine. Progress: Did you have any luck with the mine?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.2415 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 42, ["flags"] = 0 } } },
[50174] = { ["id"] = 50174, ["name"] = "All Wrapped Up", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50174 }, ["description"] = "While I was able to get out of the mine, some of my friends weren't so lucky. I saw those spiders wrap them up in their webs... probably to save them for a snack. It was terrible, but all I could do was run. Will you help them?", ["objectivesText"] = "Destroy Writhing Cocoons to rescue 8 Bleak Hills Miners in the Bleak Hills Mine.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 21191, 21310 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132374, ["x"] = 0.345, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132374, ["x"] = 0.345, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[50175] = { ["id"] = 50175, ["name"] = "An Eight-Legged Curse", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50175 }, ["description"] = "Some terrible old hag unleashed a swarm of these horrible spiders in the mine! I was barely able to make it out alive, but they've got me surrounded! You can't leave me here! Please kill those things!", ["objectivesText"] = "Kill 20 Bilefang spiders in the Bleak Hills Mine.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132374, ["x"] = 0.345, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132374, ["x"] = 0.345, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[50177] = { ["id"] = 50177, ["name"] = "Hold The Barricade!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "<name> they're rallying for a heavy assault! We'll need to defend these barricades from attack! Are you with me?", ["objectivesText"] = "Defend the barricades from attack! Progress: That earned us some breathing room.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 156710, 156828, 158623, 158624, 158625, 158626, 160201, 160202, 160203, 160204 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.257, ["y"] = 0.6775 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50178] = { ["id"] = 50178, ["name"] = "Trouble in the Rootway", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50178 }, ["objectivesText"] = "Cull aggressive wildlife Feathered Viper slain Feathered Viper Eggs destroyed Feathered Viper Hatchling slain Wild Ravasaur slain", ["rewardGold"] = 4000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cull aggressive wildlife", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Feathered Viper slain", ["amount"] = 17, ["type"] = 0, ["objectID"] = 132410, ["orderIndex"] = 2 }, { ["text"] = "Feathered Viper Eggs destroyed", ["amount"] = 200, ["type"] = 0, ["objectID"] = 132413, ["orderIndex"] = 3 }, { ["text"] = "Feathered Viper Hatchling slain", ["amount"] = 67, ["type"] = 0, ["objectID"] = 132412, ["orderIndex"] = 4 }, { ["text"] = "Wild Ravasaur slain", ["amount"] = 17, ["type"] = 0, ["objectID"] = 123135, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862 },
[50195] = { ["id"] = 50195, ["name"] = "Bilgemaul's Brigade", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 50195 }, ["description"] = "<According to these orders, these assassins are being hired by a Sea Dog captain who is establishing a beachhead in Drustvar . Taking him out would deal a great blow to the Horde�s war effort, and might just put a halt to these ambushes.>", ["objectivesText"] = "Defeat Captain Bilgemaul in the Brackish Coast and loot his War Spoils.", ["rewardGold"] = 234000, ["rewardXP"] = 200, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 156736 } },
[50229] = { ["id"] = 50229, ["name"] = "A Wee Bit O' Cloth", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1377, ["storyline"] = { 50229 }, ["description"] = "<name>, is that you I hear rustlin' about out there? It's me, Angus Stormbrew! There are cultists everywhere, so ye best keep yer voice down. Lean in close and cover yer nose while we talk! This is the only outhouse in all o' Silithus! Trust me I spent hours lookin' all through the night. I decided to sneak in for a wee drop-off before the cultists woke up, but I've got a uhh problem... There's no cloth to... you know... See if ye can find me a wee bit o' cloth and sneak it in through the door!", ["objectivesText"] = "Collect 8 scraps of Twilight Silk . Progress: Did ye acquire \"the goods?\"", ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["rewardItems"] = { 156797 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[50234] = { ["id"] = 50234, ["name"] = "Crews of Freehold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50234 }, ["rewardItems"] = { 153680, 153681, 153682 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50238] = { ["id"] = 50238, ["name"] = "Bramblethorn", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "I was playing with Lord and Lady Sharptooth when Papa made me come with him. I dropped poor Lord Sharptooth and one of those big mean monsters grabbed him! Papa said he'd try to get him back but he's been gone a long time. I think he got busy. Mama and all the adults are busy doing stuff for Mayor Royston. Lady Sharptooth and I are really sad. Can you beat up that mean monster and save my dino?", ["objectivesText"] = "Slay Bramblethorn and retrieve Lord Sharptooth . Progress: Did you find Lord Sharptooth ? I think one of the really big monsters has him.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 156710, 156830 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132966, ["x"] = 0.27, ["y"] = 0.712 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132966, ["x"] = 0.27, ["y"] = 0.712 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.712 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50240] = { ["id"] = 50240, ["name"] = "A Slip of the Tongue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 50240 }, ["description"] = "<As you approach, the blind Zandalari motions at you impatiently.> It sounds like ya be headed somewhere in a hurry, little weed! Sit down and share a tale with an old troll before ya head out on ya next adventa. I went on many adventas with my pterrordax when I was young. Explored dis whole valley! My pterrordax died many years ago, but... < Blind Tra'wala smiles mischievously.> Sometimes at night, I steal da guards' snacks to trick dese old pterrordaxes into lettin' me ride again. Ha!", ["objectivesText"] = "Steal a Pack of Pterrordax Snacks and use them to ride a pterrordax deeper into the city.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 156839 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 132989, ["x"] = 0.535333, ["y"] = 0.094667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.535333, ["y"] = 0.094667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[50249] = { ["id"] = 50249, ["name"] = "A Boralus Triple Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49716, 49720, 49733, 49734, 50249, 51226 }, ["description"] = "If Tallis honestly thinks that offing a few random soldiers is going to force us to give up Southwatch, he's in for a surprise. The reason why we haven't chased out the sorry troops in this camp is simply because we have more pressing plans. Fernn has his lieutenants facing the Watch's cannons straight at Boralus as we speak. Those three are the real driving force of the attack. <The marine gives you a concerned look as he realizes what he said.>", ["objectivesText"] = "Take out Fernn's three lieutenants. Progress: What is it?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 133035, ["x"] = 0.81, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 130375, ["x"] = 0.81, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.81, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5431, ["name"] = "Greystone Keep", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50251] = { ["id"] = 50251, ["name"] = "Spell Bound", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49939, 50001, 50036, 50063, 50090, 50092, 50172, 50177, 50238, 50251, 50903 }, ["description"] = "<The villager is held captive by a binding rune. Destroying the rune should free the villager.>", ["objectivesText"] = "Destroy 8 Binding Runes to free captive villagers .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131579, ["x"] = 0.260182, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131879, ["x"] = 0.257, ["y"] = 0.6775 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.260182, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5442, ["name"] = "Falconhurst", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50252] = { ["id"] = 50252, ["name"] = "Mating Season Halftime", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["description"] = "Cala and I have both failed. Voodoo and science did not work. I am at a loss. I hope dat you can help us find a better path forward. De brutosaurs deserve a chance! Please spend a little time with both of us. Perhaps you can find de way dat we cannot.", ["objectivesText"] = "Strategize with Cala Cruzpot and Witch Doctor Janagalar on how to use voodoo and science to get the endangered brutosaurs to mate. Progress: Please strategize with both Cala and myself to find a new plan to help de brutosaurs.", ["rewardGold"] = 77400, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50253] = { ["id"] = 50253, ["name"] = "An Improvised Arsenal", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "I don't know much about blacksmithing, but I'm pretty sure this won't be enough silver to outfit all of the Inquisitors. We will need to find another way to use this. Let us hope that Ballaster can come up with something... creative.", ["objectivesText"] = "Speak with Angus Ballaster to create a silver weapon at Watchman's Rise. Progress: What can ol' Angus do fer ye?", ["rewardGold"] = 128700, ["rewardXP"] = 1385, ["rewardItems"] = { 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132193, ["x"] = 0.268667, ["y"] = 0.345333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.2415 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 43, ["flags"] = 0 } } },
[50264] = { ["id"] = 50264, ["name"] = "Free the Farmhands", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "We were running around trying to get the farm under control, but the bees, oh my goodness, the bees! The giant monstrosities came out of nowhere and started dousing everyone in honey. I came up here to find Raimond, but before I knew it, I was covered too. Then, the strangest thing happened, the honey started growing around me! Please, the other farmhands are still in trouble, you've got to help them!", ["objectivesText"] = "Rescue the Honey Encased Farmhands.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134028, ["x"] = 0.719, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133204, ["x"] = 0.71, ["y"] = 0.692 }, { ["mapID"] = 942, ["npcID"] = 134447, ["x"] = 0.74, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.719, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50265] = { ["id"] = 50265, ["name"] = "Saving Master Ashton", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["series"] = { 50172 }, ["description"] = "I believe I see Master Ashton in a cage. He must be freed! Those witches with the long masks appear to be in charge. I bet they would have the means to open his cage. I will remain here to protect Apprentice Webb and keep the area secure.", ["objectivesText"] = "Take a key from a Hexwood Binder and free Master Ashton.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.2188, ["y"] = 0.5576 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50266] = { ["id"] = 50266, ["name"] = "Bittersweet", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50266 }, ["description"] = "Hey! I need to get out of here and get back to Falconhurst! My husband and I were looking for my daughter's favorite toy when I was taken. Please, I need to get out of here! I need to know my family is safe. They took my gear. It's all around camp. Get me out of here then bring back my gear, please!", ["objectivesText"] = "Free Samantha Sweet then recover her gear.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133101, ["x"] = 0.212, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133252, ["x"] = 0.205333, ["y"] = 0.574667 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.212, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[50268] = { ["id"] = 50268, ["name"] = "Give it a Little Juice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["series"] = { 49870 }, ["description"] = "Well, I admit that I feel a little better about this. If Witch Doctor Jangalar's voodoo can make Ben'jin react correctly, as the science says he should, then what do we have to lose? Bless my formula or hex it or whatever they call it with Jangalar's voodoo cauldron.", ["objectivesText"] = "Put some voodoo on Cala's formula using Witchdoctor Jangalar's cauldron. Progress: Will voodoo make it smell funny? Nevermind, idle musings.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 156860, 160752 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130905, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130905, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50270] = { ["id"] = 50270, ["name"] = "Deep In the Core", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 207, ["storyline"] = { 50114, 50123, 50270, 50275 }, ["series"] = { 50114 }, ["description"] = "Look, you're gonna have to travel to some place called Deepholm and find an earthen down there. The guy who sold the recipe to me said he got it from an earthen called...Ormhun! Ormhun something. I don't know too much about that place, but maybe you can ask the locals or something where he lives. Now if you don't mind, I have more recipes to sell.", ["objectivesText"] = "Travel to Stormwind and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 896, ["name"] = "8.1.5 Blacksmithing - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50271] = { ["id"] = 50271, ["name"] = "Smash and Grab", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 50271, 50272, 50274, 50288 }, ["series"] = { 50272, 50273, 50274 }, ["description"] = "Most of the materials we'll need can be found right down here in the Deepholm. We just need ta be discreet about it. If old Therazane catches wind of what we're up to, she might try ta put a stop ta it. But let's not worry 'bout that. The first thing you'll need is diaminium . There are pillars that grow in the Alabaster Shelf rich with 'em. Just use yer old blacksmithin' hammer and smash those pillars ta bits. Don't worry about breaking the diaminium . We'll meld it all back tagether.", ["objectivesText"] = "Go to the Alabaster Shelf and smash Diaminium Pillars. Collect 60 Diaminium . Progress: This'll be fun! I haven't made one of those anvils in ages!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156887 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 898, ["name"] = "8.1.5 Blacksmithing - Alliance/Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50272] = { ["id"] = 50272, ["name"] = "An Ear to the Ground", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 50271, 50272, 50274, 50288 }, ["series"] = { 50271, 50273, 50274 }, ["description"] = "The next reagent ya need comes from the bellies of worms that burrow through this realm. While ya can find plenty o' worms all over, there's a certain type you'll need ta find. They're rarely seen above ground, but there are ways of coaxing 'em out. Namely making enough racket to piss 'em off! Ha ha! When ya see 'em rumblin' around beneath ya, use this thumper to draw 'em out. Deliver a killin' blow and get that metal from their wee bellies!", ["objectivesText"] = "Go to the Jagged Wastes and look for signs of worms. They usually kick up lots of dirt as they move around. Drop a thumper to make them surface, then kill them and collect 30 Endurite from them. Progress: It's been a while since I went worm huntin'. We used ta jump up and down ta rile them up before we made tha thumpers.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156886, 157556 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 898, ["name"] = "8.1.5 Blacksmithing - Alliance/Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50273] = { ["id"] = 50273, ["name"] = "Atal'Dazar: Locking Horns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9028, ["storyline"] = { 50273 }, ["series"] = { 50271, 50272, 50274 }, ["description"] = "We've got tha metal for tha base and tha body, but there's one last part... Tha horn of tha anvil was ta be made of ukrite. But that metal's been gone for ages. There is another metal tha's very close ta it in terms of its durability. A type of gold tha trolls mined in abundance. And I know where ye can find it. Tha trolls control an area called Atal'Dazar, a great city made o' tha stuff. If ye can find something horn-shaped in there, that'll save us tha trouble of shaping it from scratch.", ["objectivesText"] = "Go to Atal'Dazar and recover The Golden Horn of Rezan .", ["rewardGold"] = 257400, ["rewardItems"] = { 156920 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9028 } }, ["questType"] = "dungeon" },
[50274] = { ["id"] = 50274, ["name"] = "Titanic Forging", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 50271, 50272, 50274, 50288 }, ["series"] = { 50271, 50272, 50273 }, ["description"] = "Are ya ready, <lad/lass>? You'll be doing the hammerin' while I take care of the last reagent we'll need.", ["objectivesText"] = "Meet Ormhun near the Shuddering Spires and help him craft a Khaz'gorian Anvil.", ["rewardGold"] = 63180, ["rewardXP"] = 355, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.409, ["y"] = 0.499 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 898, ["name"] = "8.1.5 Blacksmithing - Alliance/Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50275] = { ["id"] = 50275, ["name"] = "Anvil's Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 50114, 50123, 50270, 50275 }, ["description"] = "Take your anvil, and never speak of its methods of creation to anyone. Should I find out otherwise, you may find your next visit to my realm an unpleasant one.", ["objectivesText"] = "Bring the anvil back to Grix Barlow in Boralus.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 133796, ["x"] = 0.276, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 896, ["name"] = "8.1.5 Blacksmithing - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50276] = { ["id"] = 50276, ["name"] = "A Recipe For the Ages", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 1165, ["storyline"] = { 50276, 50277, 50278, 50279 }, ["description"] = "Say, ya look like you been swingin' da hammah around quite a bit, <brudda/sista>. I can smell da flux on ya! <Zak'aal gives you a wide grin.> Listen, I've got a recipe for da most amazin' blacksmit hammah ya ever be layin' ya eyes on. And I'd be willing ta let it go for a bit of ore. Revlis ore ta be exact. It be a little rare, but ya can find some of it over at Atal'Gral. Da naga dere use it ta make deir weapons. Bring me back a haul of it, and da recipe be yours!", ["objectivesText"] = "Bring Forgemaster Zak'aal 30 pieces of Revlis Ore from Atal'Gral in Zuldazar. Progress: Dis recipe probably be wort a tousand, no TEN tousand gold! Blacksmits all over will be envious of ya, brudda.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 156875 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 127112, ["x"] = 0.435, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 127112, ["x"] = 0.435, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 897, ["name"] = "8.1.5 Blacksmithing - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50277] = { ["id"] = 50277, ["name"] = "Hammering Out Information", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 50276, 50277, 50278, 50279 }, ["series"] = { 50278 }, ["description"] = "Let me guess. You be lookin' at da recipe and noticed it require a Khaz'gorian Anvil ta make it. So now you be wantin' ta know where ta find a Khaz'gorian Smithing Anvil? Look, <brudda/sista>, I never said anyting about bein' able ta craft da hamma. Now if ya don't mind, I have more of dese recipes ta be sellin'.", ["objectivesText"] = "Press Forgemaster Zak'aal for more information about where to find a Khaz'gorian Smithing Anvil. Progress: Dat recipe really be wort what ya paid for it, no mindin' if ya be able ta craft it or not.", ["rewardGold"] = 22130, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 127112, ["x"] = 0.435, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 127112, ["x"] = 0.435, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 897, ["name"] = "8.1.5 Blacksmithing - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50278] = { ["id"] = 50278, ["name"] = "Deep In the Core", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 50276, 50277, 50278, 50279 }, ["series"] = { 50277 }, ["description"] = "Look, ya gonna have ta travel ta Deepholm and convince dem ta be givin' up deir secrets. Dat's where da last anvil was made, or so I be hearin'. And I only be knowin' of one earten down dere who might be willin' ta work wit ya. His name be Ormhun Stonehamma'. He be kind of an outcast, but not too hard ta find.", ["objectivesText"] = "Travel to Orgrimmar and take the portal to Deepholm. Seek out Ormhun Stonehammer when you arrive.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 127112, ["x"] = 0.435, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 133489, ["x"] = 0.409, ["y"] = 0.499 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 207, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 897, ["name"] = "8.1.5 Blacksmithing - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
