[50288] = { ["id"] = 50288, ["name"] = "Therazane's Choice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "blacksmithing" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5042, ["mapID"] = 207, ["storyline"] = { 50271, 50272, 50274, 50288 }, ["description"] = "<You explain that you meant no disrespect to Therazane or to steal their secrets.> Interesting... I have a wonderful idea on how to solve this issue. Would you like to hear it?", ["objectivesText"] = "Listen to Therazane 's proposition. Progress: To think a creature such as yourself would be freely given our secrets. I suppose I'll have to keep a closer eye on the goings on within my realm.", ["rewardGold"] = 22130, ["rewardXP"] = 175, ["rewardItems"] = { 60816, 167021 }, ["starts"] = { { ["mapID"] = 207, ["npcID"] = 133796, ["x"] = 0.276, ["y"] = 0.506 } }, ["ends"] = { { ["mapID"] = 207, ["npcID"] = 133796, ["x"] = 0.276, ["y"] = 0.506 } }, ["coords"] = { ["mapID"] = 207, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.506 }, ["mapCandidates"] = { ["npc"] = { 207 }, ["zone"] = { 5042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 646, ["db2PoiUiMapID"] = 207, ["questLines"] = { { ["id"] = 898, ["name"] = "8.1.5 Blacksmithing - Alliance/Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
