[50297] = { ["id"] = 50297, ["name"] = "The Head of Her Enemy", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49801, 49810, 49814, 49870, 50074, 50150, 50154, 50252, 50268, 50297 }, ["description"] = "You have done a wonderful thing, <name>. With de destruction of Gloomtail, Maka'fon is no longer bothered by de presence of de razorwings. It seems dat Gloomtail destroyed her eggs some time ago. Take Gloomtail's head to Maka'fon as proof dat he is gone. When she finds de scent of Ben'jin on it, she will once again seek a worthy mate. When Ben'jin senses dat, he will approach and nature will take over.", ["objectivesText"] = "Place Gloomtail's head in front of Maka'fon so that she knows her territory is safe and that Ben'jin is the reason. Progress: Take Gloomtail's head and offer it to Maka'fon. Let us see what happens next.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 156925, 158666, 159123, 159147, 159148, 159149, 159150, 163036 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 130929, ["x"] = 0.64, ["y"] = 0.354 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.64, ["y"] = 0.354 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5401, ["name"] = "The Last of Their Kind", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50299] = { ["id"] = 50299, ["name"] = "Gryphon Wranglin'", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 895, ["storyline"] = { 50299 }, ["objectivesText"] = "Wild Gryphon wrangled", ["rewardItems"] = { 156928 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Wild Gryphon wrangled", ["amount"] = 1, ["type"] = 0, ["objectID"] = 133323, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50306] = { ["id"] = 50306, ["name"] = "Odds and Ends", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "Master Ashton's going to probably need something bracing once we get him free. I know of a quick potion guaranteed to get anyone to snap out of it, but I'm going to need a few things first. Those wicker dogs down there have some organic parts I can use and the witches are carrying bags of reagents. They'll almost certainly have what I need. Bring those to me and I'll handle the rest once we get Master Ashton back.", ["objectivesText"] = "Collect 4 Organic Matter Samples and 3 Bags of Reagents. Progress: Did you have any luck?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175, 158593, 158595, 160193, 160194, 160195, 160196 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133126, ["x"] = 0.256, ["y"] = 0.5564 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133126, ["x"] = 0.256, ["y"] = 0.5564 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.5564 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50318] = { ["id"] = 50318, ["name"] = "A Timely Summons from Northrend", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7502, ["storyline"] = { 50318 }, ["description"] = "The blazing wanes in the shadow of a celestial mass, striking fear in to the seers. Seek out the sage Vormu in Dalaran , and lend her your aid. No, not this Dalaran , the other one. Yes I know, it's terribly confusing.", ["objectivesText"] = "Meet with Vormu in Dalaran above Crystalsong Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[50321] = { ["id"] = 50321, ["name"] = "Mojo Mischief", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 50321 }, ["description"] = "De soldiers you rescued spoke of de raids on Zandalar. Blood troll raiders, frothing at de mouth and possessing supernatural strength, overwhelmed de defenders. Dey say dat their strength came from flasks of mojo dat de raiders drink before going into combat. We cannot allow de blood trolls to continue to possess them. Go down into de camp and destroy any of their flasks you may find.", ["objectivesText"] = "Destroy 6 Flasks of Viscous Mojo.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[50322] = { ["id"] = 50322, ["name"] = "A Feathery Fad", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50322 }, ["rewardItems"] = { 157538 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50324] = { ["id"] = 50324, ["name"] = "Picturesque Fizzsprings Resort", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 895, ["storyline"] = { 50324 }, ["objectivesText"] = "Enriched Rockshell captured Resort Lodge captured Midland Fawn captured Secluded Spring captured", ["rewardItems"] = { 122674, 157540 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Enriched Rockshell captured", ["amount"] = 1, ["type"] = 0, ["objectID"] = 133479, ["orderIndex"] = 0 }, { ["text"] = "Resort Lodge captured", ["amount"] = 1, ["type"] = 0, ["objectID"] = 133481, ["orderIndex"] = 1 }, { ["text"] = "Midland Fawn captured", ["amount"] = 1, ["type"] = 0, ["objectID"] = 133484, ["orderIndex"] = 2 }, { ["text"] = "Secluded Spring captured", ["amount"] = 1, ["type"] = 0, ["objectID"] = 133485, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50325] = { ["id"] = 50325, ["name"] = "Stopping the Grand Rite", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "The witches of the Crimsonwood are planning a Grand Rite, a powerful ritual. They intend to rip open reality and bring their dark master through! I suspect they may be in communion with Gorak Tul. We cannot allow their ritual to succeed. I need you to be the tip of the spear while I protect Master Ashton and Marten. Cause havoc and disrupt their rituals!", ["objectivesText"] = "Destroy the Ritual Foci. Progress: Destroy the Ritual Foci.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.2188, ["y"] = 0.5576 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50327] = { ["id"] = 50327, ["name"] = "A Little 'Pick Me Up'", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "Now to mix this up. <Marten begins to combine the components in a mug> I'm using some rather strong grog as a base, a drop of chilli extract and a handful of hearthbloom... There! <Marten hands you a mug> It will taste worse than it smells, but it will bring Master Ashton to his senses. Please give this mug to him.", ["objectivesText"] = "Give the mug to Master Ashton. Progress: <Ashton stares into the distance, eyes wide, muttering under his breath.>", ["rewardGold"] = 30900, ["rewardXP"] = 2765, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133126, ["x"] = 0.256, ["y"] = 0.5564 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133105, ["x"] = 0.242, ["y"] = 0.558286 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.256, ["y"] = 0.5564 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50328] = { ["id"] = 50328, ["name"] = "Unconventional Aromatics", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "A deal's a deal. You got the stingers for me, so here's that big batch of honey I promised. I hope you and Rhan'ka enjoy it... slowly. Seriously, do not eat this all at once. Oh, and I'm always looking to trade. Swing by anytime you got something to sell or want to pick up some more honey!", ["objectivesText"] = "Deliver the Batch of Bilewing \"Honey\" to Rhan'ka at the Goldtusk Inn. Provided item:", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["rewardItems"] = { 160665 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 133833, ["x"] = 0.404, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50329] = { ["id"] = 50329, ["name"] = "Matrons of the Crimsonwood", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "The witches in charge, the matrons... <Ashton shudders for a moment then composes himself.> The matrons are the ones leading the Grand Rite. They are fearsome but not invulnerable. Removing some of them from the equation will bolster our chances of stopping this. Take this potion. It will be able to weaken the matrons so you might have a better chance of dispatching them.", ["objectivesText"] = "Kill Matrons Elsbeth Garrick, Stefania Denholm, and Wilona Blackwood. Progress: Did you kill them?", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133105, ["x"] = 0.242, ["y"] = 0.558286 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133105, ["x"] = 0.242, ["y"] = 0.558286 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.558286 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50331] = { ["id"] = 50331, ["name"] = "A Different Outcome", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50331 }, ["description"] = "There is no way to know when these orders were sent, or received. Rokor took some Seekers north some time ago. They must be in that region by now. If the temple still stands, warn Gral and his followers. If it is lost, we must do what we can.", ["objectivesText"] = "Find Rokor near Atal'Gral, to the north.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 129717, ["x"] = 0.705, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 125047, ["x"] = 0.803, ["y"] = 0.44 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["startItems"] = { 157544 } },
[50332] = { ["id"] = 50332, ["name"] = "Big Hunter Mon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50332 }, ["description"] = "In these valleys, the Mon be kepin' beasts alive only to serve as sport. For his entertainment. The lives of others not be so cheap. Even the smallest creature can cause a whole lotta trouble. The Mon gonna be learnin' to respect that. I think this be a good time to teach this Big Hunter Mon a lesson, don't you? Be you my faithful messenger?", ["objectivesText"] = "Survive Jani 's prank on Nesingwary. If you lose your saurid disguise, return to Jani for another. Progress: You taken my present to that big hunter mon yet, richmon?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 133490, ["x"] = 0.662, ["y"] = 0.166 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133490, ["x"] = 0.662, ["y"] = 0.166 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.166 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50340] = { ["id"] = 50340, ["name"] = "Steal Them Back", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50340 }, ["description"] = "<This empty crate of supplies is clearly marked with Kul Tiran signage. These must be the spoils of their raids on the farms of the valley. The citizens would probably like their supplies back if there are any left.>", ["objectivesText"] = "Retrieve 5 Stolen Crates . Progress: Keep an eye out for anything useful. This place is very dangerous.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 158735 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130190, ["x"] = 0.576, ["y"] = 0.665 }, { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[50343] = { ["id"] = 50343, ["name"] = "Mayhem at Mildenhall Meadery", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "Ahhhh! <Sir/Miss>, please, I need some help! My dad hasn't come back from the meadery and, and... well, when I went to look, there were giant globs of honey everywhere. But... but, somehow, they were moving on their own. I even saw one eat a bunny, I swear! I'm scared to go back by myself, but I think dad is in trouble. Can you go with me?", ["objectivesText"] = "Investigate the Mildenhall Meadery.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131793, ["x"] = 0.688, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50349] = { ["id"] = 50349, ["name"] = "An Overrun Mine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50349, 50351, 50352, 50356 }, ["description"] = "It was horrible! I was in the mine nearby, just picking away at a rock and it jumped up and bit me in the neck! Since when can rocks walk around and bite people? I hightailed it outta there, but some crazy fools are sticking around trying to take the mine back. If you're eager to punch rocks you can find them down the road to the south.", ["objectivesText"] = "Find Chief Miner Theock at Winterdeep Mining Camp.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 133550, ["x"] = 0.756, ["y"] = 0.505 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 133551, ["x"] = 0.78, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.756, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5434, ["name"] = "It's Mine", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50350] = { ["id"] = 50350, ["name"] = "We Need a Chemist", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 50350 }, ["description"] = "All this chaos started when we were picking at a large Azerite node deep in the mine. The mine began to rumble and all of these blasted creatures burst from the ground. If we could just get rid of that vein, I am sure we could retake the mine. First, we need a chemist. The best one we got is in his lab across the river. Find him and he'll give you more instructions.", ["objectivesText"] = "Find Head Chemist Walters.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[50351] = { ["id"] = 50351, ["name"] = "Miner Operation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50349, 50351, 50352, 50356 }, ["description"] = "The mine is in real trouble. We've been excavating for a short while, but never seen anything like this. Azerite doesn't just get up and walk around. If we are going to take the mine back, we're going to need more help. We'll need an engineer and an explosives expert. I have two in mind, sisters actually, but they are caught behind the river in all the chaos. Locate the sisters and they'll help you with the next phase of the plan.", ["objectivesText"] = "Locate Civil Technician Alena and Ordnance Handler Prim .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 133551, ["x"] = 0.78, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 133621, ["x"] = 0.755, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5434, ["name"] = "It's Mine", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50352] = { ["id"] = 50352, ["name"] = "Pinch of Azerite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50349, 50351, 50352, 50356 }, ["description"] = "I don't have time for idle chit chat! If you haven't noticed, rocks are running around doing who knows what?! How about you help out and retrieve my chemistry kit. While you're out, smash some of those creatures and collect their dust. Prim will need both of those for the next step of the plan. Maybe we can figure out what has animated the Azerite.", ["objectivesText"] = "Collect 45 Azerite Dust and Walters' Chemistry Kit . Progress: Did you bring the dust?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 157778, 157857 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 133552, ["x"] = 0.78, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 133621, ["x"] = 0.755, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.78, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5434, ["name"] = "It's Mine", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50353] = { ["id"] = 50353, ["name"] = "Boaring Company", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50353, 50354, 50363, 50365, 50368, 50622, 50640, 51354 }, ["description"] = "I don't see her body anywhere. That means she could still be alive. The Briarback have been taking prisoners, and anyone who has ever been taken by them was never seen again. We have a single chance here and we need to take it! Come with me into the kraul and free as many of the survivors as you can. And if you can, find Farmer Deal . See if she's still alive.", ["objectivesText"] = "Find and rescue 7 Captured Farmers and Farmer Deal . Progress: Please, find the prisoners!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.487, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 583, ["name"] = "Storming the Kraul", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50356] = { ["id"] = 50356, ["name"] = "Rock Meet Dynamite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50349, 50351, 50352, 50356 }, ["description"] = "Thanks for your help out there, but we have to ask another favor from you. These elementals must be coming from somewhere in the mine and we need you to locate that source. You seem more than capable of handling yourself in there, but just for extra security I am going to send you with some of Prim's special dynamite. It has an extra kick from the Azerite dust that you gathered. Get in. Find the source. Put a stop to these elementals.", ["objectivesText"] = "Eliminate the source of the Azerite creatures.", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 134628, ["x"] = 0.755, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 133551, ["x"] = 0.78, ["y"] = 0.56 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.755, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5434, ["name"] = "It's Mine", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50359] = { ["id"] = 50359, ["name"] = "Cleanup Duty", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["objectivesText"] = "Kill 4 Flowing Honey and 4 Bubbling Mead .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50363] = { ["id"] = 50363, ["name"] = "War Pigs", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9562, ["mapID"] = 942, ["storyline"] = { 50353, 50354, 50363, 50365, 50368, 50622, 50640, 51354 }, ["description"] = "They look cute enough now, but that's a new herd of battleboars in training. Farmers don't like waste, and it would be a shame to get rid of such useful creatures. Either way, we could use those pigs, and I'd rather have them with us rather than face a bloodthirsty one in a few years. You should find them up on top of the cliffs overlooking the center of the kraul. Go round up as many piglets as you can take with you and we'll make good use of them.", ["objectivesText"] = "Collect 8 Grazing Battle-Piglets .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.487, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9562 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 583, ["name"] = "Storming the Kraul", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50365] = { ["id"] = 50365, ["name"] = "Run For the Hills", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9562, ["mapID"] = 942, ["storyline"] = { 50353, 50354, 50363, 50365, 50368, 50622, 50640, 51354 }, ["description"] = "The quilboar are up to something, something big. You need to stop it! They've been busy bringing supplies up to the caves above their sanctum. Preserved thorns, cauldrons of venom, giant totems... They're preparing for war. Get up there and destroy those stockpiles before they can be used against the citizens of the valley!", ["objectivesText"] = "Destroy the stockpiles of supplies.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.487, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9562 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 583, ["name"] = "Storming the Kraul", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50367] = { ["id"] = 50367, ["name"] = "Anger in a Bottle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9562, ["mapID"] = 942, ["storyline"] = { 50367 }, ["description"] = "<The bottle the quilboar was carrying contains a foul-smelling, orange liquid. You're not sure if it's safe to drink, but it can't hurt to gather some samples to bring back to the citizens of Brennadam. Maybe their alchemist can come up with an antidote to counter its effects.>", ["objectivesText"] = "Collect 10 Foul-Smelling Samples . Progress: Do you have something for me?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.487, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9562 } }, ["questType"] = "standard", ["startItems"] = { 157849 } },
[50368] = { ["id"] = 50368, ["name"] = "Terror of the Kraul", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9562, ["mapID"] = 942, ["storyline"] = { 50353, 50354, 50363, 50365, 50368, 50622, 50640, 51354 }, ["description"] = "By all the gods of the sea, what a monster! I can barely believe what I am seeing, <name>. This ettin has undergone the same ritual that the brutes do, and it seems even angrier! If he gets out of here, we won't stand a chance. I know I ask the impossible, but I must: kill this monstrosity and save the whole valley from its wrath! Here, take one of the potion samples you brought me. It's probably dangerous, but you might need it to defeat this beast.", ["objectivesText"] = "Defeat Bramblefist the Maddened . Progress: We have to kill that thing!", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 133510, 155200, 155203, 155205, 155210, 155218, 155223, 155225, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160520, 160522, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.487, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9562 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1183, ["questLines"] = { { ["id"] = 583, ["name"] = "Storming the Kraul", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50369] = { ["id"] = 50369, ["name"] = "Bruin Potions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50369 }, ["objectivesText"] = "Bear Heart collected", ["rewardItems"] = { 157545, 157546, 160442 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Bear Heart collected", ["amount"] = 6, ["type"] = 1, ["objectID"] = 157545, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50370] = { ["id"] = 50370, ["name"] = "Deeper into the Woods", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "We need to go deeper into the forest. The witches are clearly up to something even worse than I'd imagined. As much as I have a duty to return to Lady Lucille with Master Ashton, I also have a duty to find out more about this threat to our people, and stop it if I can. Going further into the forest is not without risk, but I believe it is one worth taking.", ["objectivesText"] = "Travel with Cleardawn, Ashton, and Webb deeper into the forest. Progress: The risk has paid off", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.2188, ["y"] = 0.5576 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50375] = { ["id"] = 50375, ["name"] = "Ride With Me", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 50375 }, ["description"] = "I have hunted many powerful foes, $p. My pack has defended this island and its people from countless outside threats and foreign invaders. But there is a darkness growing in Zandalar. A corruption so deep and relentless that it consumes the minds of the Zandalari. I cannot hunt intangible darkness, but I can hunt those who wield it against my people. Come, ride with me and my pack. I smell the foul stench of blood trolls nearby. We will see how well you hunt with the pack.", ["objectivesText"] = "Ride Gonk as he investigates the source of corruption nearby.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[50376] = { ["id"] = 50376, ["name"] = "Deadliest Cache: Reel Big Fish", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50376, 50391, 50418, 52130 }, ["description"] = "Can ye believe the nerve of these scallywags? Questioning the very Coxswain of this here wharf? Bah! Lend me your ear for a moment or three. I've got a tale that'll put brew in your mug and a quiver in your boots! It was the biggest, deadliest cache I ever did loot on these seas...", ["objectivesText"] = "Listen to Coxswain Hook 's tale. Progress: Want to hear more?", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133576, ["x"] = 0.26, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133576, ["x"] = 0.26, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5450, ["name"] = "Deadliest Cache", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50381] = { ["id"] = 50381, ["name"] = "The Great Hat Robbery", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50381 }, ["description"] = "Along this road the merchants ride. Taking dere wares from one place to another and lining them own pockets. One Big Mon named Tik'su be the worst of all. He charge arms and legs outright and it even take trolls some time to regrow them parts. His biggest pride? His hat. Go be my messenger, Rich-mon. Scare his burdened beast and knock off Tik'su . Then bring me his hat.", ["objectivesText"] = "Successfully steal Tik'su 's Hat. If you lose your saurid disguise, return to Jani for another. Progress: You had a chat with Tik'su about his hat yet, richmon?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 133612, ["x"] = 0.618, ["y"] = 0.468 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133612, ["x"] = 0.618, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50385] = { ["id"] = 50385, ["name"] = "Indefatigable Purpose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50385, 50386, 50387, 50388, 50389, 50417, 53099, 53105 }, ["description"] = "Its grip weakens, if only briefly. We must claim this place anew! Flopping, nightmarish horrors have infested the caves amongst the cove. Take the sacred blessings. Venture forth into the dark and find their altars. Purge their blasphemous constructions from our lands!", ["objectivesText"] = "Cleanse 3 Drowned Altars .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 157771 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.787, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 577, ["name"] = "The Forgotten Cove", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50386] = { ["id"] = 50386, ["name"] = "Flush Them Out", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50385, 50386, 50387, 50388, 50389, 50417, 53099, 53105 }, ["series"] = { 50417 }, ["description"] = "They lurk in the shadows, in the salt-soaked caverns. The dark brine beneath the pure gleam of the surface. I have seen them. They plague my dreams, their whispers are maddening. They speak of their master, clawing at the barrier... Search the cliffs for their warrens. Find what lurks within and obliterate them all.", ["objectivesText"] = "Investigate and defeat what lies within 4 structures in the Forgotten Cove. Progress: Ignorance of our enemy will invariably lead to defeat.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.787, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 577, ["name"] = "The Forgotten Cove", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50387] = { ["id"] = 50387, ["name"] = "Trinkets and Baubles", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50385, 50386, 50387, 50388, 50389, 50417, 53099, 53105 }, ["description"] = "Beneath the tides, these terrors do not see fit to stay within their warrens. They have emerged in the night, stealing away to the villages and indulging in their avarice. They will use the provisions against us, to serve in their rituals. Rituals of summoning and communion with powers too terrible to comprehend. The populace is no concern of mine anymore, but I would not see these briny thieves to have their way. Relieve them of their plunder, and let them learn a bitter lesson.", ["objectivesText"] = "Recover 3 crates of Stolen Supplies . Progress: Where there is no peril, there can be no glory!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 9172, 116268, 127840, 152496, 157784 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.787, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 577, ["name"] = "The Forgotten Cove", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50388] = { ["id"] = 50388, ["name"] = "The Weight of My Ambition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50385, 50386, 50387, 50388, 50389, 50417, 53099, 53105 }, ["description"] = "As with the other settlements, I too relied on the services of sailors and watercraft to deliver supplies. They proved very useful in their diligence, and their silence. Predictably, they drew the attention of enemies, including those below the waves. Their anchor was hexed, dragging them beneath the ocean before they could so much as cry out. I have seen them, hoisting ethereal sails and singing shanties of the damned. If these waters are to be safe again, they must be silenced again. For good.", ["objectivesText"] = "Defeat the Drowned Captain .", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.787, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 577, ["name"] = "The Forgotten Cove", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50389] = { ["id"] = 50389, ["name"] = "Malign Inspiration", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50385, 50386, 50387, 50388, 50389, 50417, 53099, 53105 }, ["description"] = "A long time ago, there was a maiden. A precocious child fond of song, she made it her hobby to shadow my every move. Charming at first. Walking on the pier's edge, she became entangled within the ropes surrounding a leering idol. At that time a tremor ran through the waves, giving the small push needed to send them both beneath the surface. I can hear her song still. At first I thought it a passing fancy, music upon the waves. I realize now the voice comes with sinister purpose. She must die.", ["objectivesText"] = "Kill the Enchanting Siren .", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.787, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 577, ["name"] = "The Forgotten Cove", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50391] = { ["id"] = 50391, ["name"] = "Deadliest Cache: Gun Fishin'", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50376, 50391, 50418, 52130 }, ["description"] = "Hook's got a screw loose in her head, I tell ya. Sharks workin' together on somethin'... phooey! It does remind me of one of my favorite tales, though. Have I ever told ya 'bout the time I caught THE single largest, deadliest, most tentacled beast in all o' Azeroth?! Aye, I thought not. It's not a story I'd tell ya sober. It was a day unlike any other...", ["objectivesText"] = "Listen to Master Gunner Line 's tale. Progress: Aye, lad?", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 157783 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133577, ["x"] = 0.258, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133577, ["x"] = 0.258, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.258, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5450, ["name"] = "Deadliest Cache", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50393] = { ["id"] = 50393, ["name"] = "A Child of Pa'ku", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50393 }, ["series"] = { 50394 }, ["description"] = "<The pterrordax egg is warm and trembling. It will hatch soon.> Perhaps a certain pterrordax loa can help you.", ["objectivesText"] = "Take the Pterrordax Egg to Pa'ku at Pterror Rise. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 54981, 54982, 57277, 57278, 57279, 57280, 57458, 57459, 57460, 66894, 66896, 66897, 118938, 128659, 131351, 131455, 157782, 159146, 211279, 237812, 242386 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.711, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["startItems"] = { 157782 } },
[50394] = { ["id"] = 50394, ["name"] = "Your Problem Now", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50394 }, ["series"] = { 50393 }, ["description"] = "Hm. This egg does not belong to one of my brood, and I have no broodlings that need another sibling. < Pa'ku might be smiling or snarling. She is showing an awful lot of teeth.> You will care for this little one. And you had better hurry. It will hatch very soon. Oh, and a little advice. If you want the little one to like you, you had better be the first thing it sees upon hatching.", ["objectivesText"] = "Place the Pterrordax Egg at the empty nest and wait for it to hatch.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.711, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50395] = { ["id"] = 50395, ["name"] = "The Call of the Skies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50395 }, ["series"] = { 50401, 50412 }, ["description"] = "< Kua'fon turns his head toward the cliff and chirps eagerly. He spreads his tiny wings and flaps vigorously.> It is time to leave the nest.", ["objectivesText"] = "Watch your hatchling take its first leap into the great unknown. Progress: What do you need, grounded one?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50396] = { ["id"] = 50396, ["name"] = "A Pterrible Fate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50396 }, ["description"] = "< Kua'fon peers longingly toward the horizon and gives a keening cry. You can take the pterrordax from the sky, but not the sky from the pterrordax. It's time to do something. Perhaps Pa'ku could offer some advice.>", ["objectivesText"] = "Ask Pa'ku for help.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 133679, ["x"] = 0.706, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.706, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50397] = { ["id"] = 50397, ["name"] = "Aerial Aspirations", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50397 }, ["description"] = "< Kua'fon studies you intensely. One single golden eye is trained on you, unwavering.> Skree. <He then turns his maw toward the horizon and spreads his wings wide.> Skree! <Is it finally time?>", ["objectivesText"] = "Fly?", ["rewardGold"] = 33100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 133682, ["x"] = 0.7376, ["y"] = 0.4972 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133682, ["x"] = 0.7376, ["y"] = 0.4972 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.7376, ["y"] = 0.4972 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50401] = { ["id"] = 50401, ["name"] = "Fear of Falling", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50401 }, ["series"] = { 50395, 50412 }, ["description"] = "Some young find their wings sooner than others. At least yours had the sense to keep them open. I would not worry too much about its safety- little ones tend to bounce. As for this failure... the young must keep trying, and they must learn not to fear falling. It is now your task to teach it. <The loa smiles at you, all teeth.> If it is reluctant to learn, you might consider bribery.", ["objectivesText"] = "Find your hatchling and convince it to return to the nest. Progress: < Kua'fon quivers in fear and chirps at you in distress. Perhaps a treat could soothe your hatchling?>", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 109076, 157782, 158885, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.711, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50402] = { ["id"] = 50402, ["name"] = "SKREEEEE!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50402 }, ["description"] = "< Kua'fon stares at you for a moment, then opens his maw and unleashes a continuous screech. You need help.>", ["objectivesText"] = "Find out what is distressing your hatchling and address it. Progress: <The hatchling's gaze scours your person in search of anything edible. It may be best to keep your fingers out of reach.> Skree!? Skree!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 141605, 157779, 157780, 157781, 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50412] = { ["id"] = 50412, ["name"] = "Back to the Nest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50412 }, ["series"] = { 50395, 50401 }, ["description"] = "< Kua'fon peers up at you trustingly.> Now would be a good time to take him back to the nest.", ["objectivesText"] = "Return Kua'fon to his nest in Pterror Rise.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.726, ["y"] = 0.513 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[50417] = { ["id"] = 50417, ["name"] = "Ruin Has Come", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50385, 50386, 50387, 50388, 50389, 50417, 53099, 53105 }, ["series"] = { 50386 }, ["description"] = "There is a terror beneath the waves. It seeks to destroy my family, my house, and my legacy. You must come, claim your destiny and deliver us from the terrors of the deep! Find our estate to the east, among the isles. We lived opulently in the shadow of the great fortress. We believed the priests would deliver us from the darkness below. Now that darkness has bubbled to the surface, whispering madness in our dreams. Hurry. The air turns the darkest I have seen in my cursed existence.", ["objectivesText"] = "Find the author of the Mysterious Letter.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 163017 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133640, ["x"] = 0.787, ["y"] = 0.546 }, { ["mapID"] = 942, ["npcID"] = 143565, ["x"] = 0.787, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.787, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 577, ["name"] = "The Forgotten Cove", ["orderIndex"] = 0, ["flags"] = 0 } } },
