[50443] = { ["id"] = 50443, ["name"] = "Down to the Roots", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50443 }, ["objectivesText"] = "Bloodlasher Seedling destroyed", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 209910 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Bloodlasher Seedling destroyed", ["amount"] = 15, ["type"] = 0, ["objectID"] = 133855, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50444] = { ["id"] = 50444, ["name"] = "Taking the Loa Road", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50444 }, ["description"] = "This road not be traveled much anymore. Except by those that serve the blood Loa. They be fools. I be wantin' my fun from those fools. Go to the spot I be markin' for you and plant this cursed coin . The silly blood trolls be seein' it and give us a laugh when they try to pick it up. Just be makin' sure that no other creature see you. Or else it be a quick trip back to the arms of Jani .", ["objectivesText"] = "Survive Jani 's prank on the Amaki trolls. If you lose your saurid disguise, return to Jani for another. Progress: You taken that cursed coin to the pranking-place yet, richmon?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136608, ["x"] = 0.54, ["y"] = 0.742 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136608, ["x"] = 0.54, ["y"] = 0.742 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.742 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
[50445] = { ["id"] = 50445, ["name"] = "Controlling the Situation", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "I have been observing this macabre army of, wood, flesh, and bone and how the witches and servitors control the lesser creations with charms. I believe I can craft an even more powerful charm - one we can use. In the hearts of the servitors are the very strongest charms. They are used to anchor the Ancient Drust into their physical forms. They are precisely what we need. Good luck. It is doubtful that they will part with them easily.", ["objectivesText"] = "Collect 5 Control Charms from the Haunted Servitors. Progress: Were you able to collect enough charms?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175, 158557 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133105, ["x"] = 0.242, ["y"] = 0.558286 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133105, ["x"] = 0.242, ["y"] = 0.558286 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.558286 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50446] = { ["id"] = 50446, ["name"] = "Witchrending", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "A blunderbuss? I'd have to say, I wasn't quite expecting that. Nonetheless, now that we have a weapon, we have an advantage. I think it's time we take the fight directly to the coven. Marshal Reade informed me that several of their Matrons have been spotted throughout Corlain. Let's show them what happens to an enemy of House Waycrest.", ["objectivesText"] = "Use Witchrend to defeat Matrons Ceridwen , Adeline, and Letitia in Corlain.", ["rewardGold"] = 107000, ["rewardXP"] = 3455, ["rewardItems"] = { 156722, 156853, 156855, 157800, 158584, 158585, 158586, 158587, 158627, 158628, 158629, 158630 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.2415 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 44, ["flags"] = 0 } } },
[50447] = { ["id"] = 50447, ["name"] = "Remembering the Fallen", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "<This villager died clutching a brooch with what looks like a family crest. It looks like several villagers didn't survive the coven's occupation of Corlain. It might be possible to identify the fallen by the keepsakes they carried. The survivors would likely be grateful to learn the fate of their loved ones.>", ["objectivesText"] = "Collect 8 Personal Keepsakes from fallen Corlain Villagers in Corlain. Progress: What's this?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 157806 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 134009, ["x"] = 0.292, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 }, { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.292, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50448] = { ["id"] = 50448, ["name"] = "Reclaiming Corlain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50448 }, ["objectivesText"] = "Combat the Heartsbane Coven", ["rewardGold"] = 455280, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Combat the Heartsbane Coven", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896 },
[50449] = { ["id"] = 50449, ["name"] = "Reeking Refuge", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "Oh good, maybe you can make sense of this. I was just carving through a swath of the coven's lackeys when I stumbled across this field. Something here has knocked these guys completely out of commission! I can't seem to find the source, but maybe you'll have better luck. I'm more used to hitting things than investigating them.", ["objectivesText"] = "Investigate what is disabling the coven's minions in Hocking's Plot.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131639, ["x"] = 0.2992, ["y"] = 0.2608 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133839, ["x"] = 0.27, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.2992, ["y"] = 0.2608 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50450] = { ["id"] = 50450, ["name"] = "An Offensive Harvest", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "So you're takin the fight to the coven with the Waycrest girl, eh? Ya might just be able to take advantage of their apparent onion aversion. While you're out rootin' in the field, keep an eye out for any onions bulging out of the ground. Those ones should be particularly aromatic, and should cause some fits in the coven's minions if you keep it on ya. Just try not to take too much, right? I need enough left in the fields to keep the farm safe.", ["objectivesText"] = "Collect 7 Aromatic Onions from Hocking's Plot. Progress: Did ya find any good ones?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 157807 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133839, ["x"] = 0.27, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133839, ["x"] = 0.27, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50451] = { ["id"] = 50451, ["name"] = "Eating Through the Defenses", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "Not sure why and don't rightly care, but for some reason the coven can't come near my onion field. So long as my crop doesn't give out, I can hole up in here as long as it takes. Unfortunately, those boars got the same idea and now they're eatin' up my harvest! If they keep that up, soon there'll be nothin' keepin' the coven at bay! If you can do me a favor and thin them out, I'd be happy to let you take some of these onions with you.", ["objectivesText"] = "Kill 8 Scavenging Boars in Hocking's Plot. Progress: How's the boar situation?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133839, ["x"] = 0.27, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133839, ["x"] = 0.27, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50452] = { ["id"] = 50452, ["name"] = "Potent Protection", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "Here ya go, I got them onions bundled up nicely for ya. Give my regards to Miss Waycrest, will ya? Her allies are welcome on my farm anytime.", ["objectivesText"] = "Deliver the Sack of Aromatic Onions to Lucille Waycrest at Watchman's Rise. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 155564, 157846 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133839, ["x"] = 0.27, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 }, { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50453] = { ["id"] = 50453, ["name"] = "Barrier Buster", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "Oy, <name>! I think I might have a solution te that pesky barrier keepin ye out of Corlain proper! I took the silver we had left 'ere an' doctored up one o' these cannonballs. The walls surroundin' Corlain are festooned with defensive cannons. Get one pointed at the gate, ye can send this beauty right into the barrier! Ye'll need a hefty pinch of powder te get this thing movin', though - it's a bit on the heavy side. Ye can likely find some in the camp outside the walls.", ["objectivesText"] = "Collect 5 Blasting Powder from Pikeman's Ridge and bring them to Inquisitor Sterntide outside the gate into Upper Corlain. Progress: I don't think these guys will be needin' this cannon anymore.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132193, ["x"] = 0.268667, ["y"] = 0.345333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131642, ["x"] = 0.303333, ["y"] = 0.202667 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.268667, ["y"] = 0.345333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 45, ["flags"] = 0 }, { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50454] = { ["id"] = 50454, ["name"] = "A Traitor's Death", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "It has come to my attention that you intend to assault the camp outside of the walls. If this is so, I have a request. Though most of the guardsmen who fight against us were turned to the coven against their will, Captain Goodspeed and his brigade of halberdiers gave their souls willingly to the Heartsbane. They are traitors and an affront to the Waycrest Guard. You will find Goodspeed and his men stationed at the camp. I would consider it a personal favor if you would cut them down to the last.", ["objectivesText"] = "Kill Captain Goodspeed . Progress: Is it done?", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 44358, 44359, 44360, 44361, 155462, 155471, 155479, 155487, 158599, 158600, 158601, 158602 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 }, { ["mapID"] = 896, ["npcID"] = 137368, ["x"] = 0.315, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.314667, ["y"] = 0.271333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50455] = { ["id"] = 50455, ["name"] = "Leaving the Nest", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "It looks like the coven hasn't managed to enthrall all of our falcons. I can see some untainted ones still in cages in the training yard. Our falcons are well trained, and should know to fly to one of our other yards if something happens to their handlers. If you can just release them from their cages, they should be able to make it to safety.", ["objectivesText"] = "Open 5 Falcon Cages in the Corlain Aviary.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 157840 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131640, ["x"] = 0.3095, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131640, ["x"] = 0.3095, ["y"] = 0.2545 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3095, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50456] = { ["id"] = 50456, ["name"] = "Hexed Hatchlings", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50152, 50447, 50449, 50450, 50451, 50452, 50453, 50454, 50455, 50456 }, ["description"] = "I've found where those evil witches have been tainting our falcons! You see those charms? <Notley motions toward the high perches and roofs nearby.> They're using those to infect our flock with their evil magic as they hatch. I think Winston can get up there to take out the charms, but someone will need to direct him. I'm not quite healed up enough to take on a whole camp of falconers. Can you help?", ["objectivesText"] = "Use the Falconer's Whistle to destroy 7 bewitching charms in the Corlain Aviary. Progress: Have you taken care of the charms?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 157845 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131640, ["x"] = 0.3095, ["y"] = 0.2545 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131640, ["x"] = 0.3095, ["y"] = 0.2545 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3095, ["y"] = 0.2545 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5445, ["name"] = "Caring about Corlain", ["orderIndex"] = 8, ["flags"] = 0 } } },
[50457] = { ["id"] = 50457, ["name"] = "Break On Through", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457 }, ["description"] = "Cannon's ready, boss. Care to do the honors?", ["objectivesText"] = "Use the Ramparts Cannon to break the barrier at the gate to Upper Corlain.", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["rewardItems"] = { 156722, 156853, 156855, 157800 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131642, ["x"] = 0.303333, ["y"] = 0.202667 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.303333, ["y"] = 0.202667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 598, ["name"] = "Corlain", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 46, ["flags"] = 0 } } },
[50466] = { ["id"] = 50466, ["name"] = "He's Gone Mad!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50466 }, ["series"] = { 47586, 49768 }, ["description"] = "Ol' Wildtusk has withstood years of attacks by young hunters that are overeager and underskilled. None could take him. His wounds have finally done him in. He just won't go down. Find that crazy riverbeast bull, and help him let go of his mortal shell.", ["objectivesText"] = "Kill Wildtusk .", ["rewardGold"] = 619600, ["rewardXP"] = 1770, ["rewardItems"] = { 158423, 158424, 158425, 158426, 158444, 158445, 158446, 158447 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 123005, ["x"] = 0.674, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 123019, ["x"] = 0.674, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
