[50493] = { ["id"] = 50493, ["name"] = "Fetching Wrex", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "When all the commotion started, Ancel's pup ran off. The poor thing was terrified! A couple farmhands went to look for him, but with all of these monsters terrorizing the farm, I fear the worst! Can you keep an eye out for Wrex while you're up in the hills? He might have gotten trapped in the honey too.", ["objectivesText"] = "Crack open Crystallized Honey to search for Wrex .", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134028, ["x"] = 0.719, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133204, ["x"] = 0.71, ["y"] = 0.692 }, { ["mapID"] = 942, ["npcID"] = 134447, ["x"] = 0.74, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.719, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 10, ["flags"] = 0 } } },
