[50530] = { ["id"] = 50530, ["name"] = "Witch Way Out?", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "There are other Falconhurst citizens to be freed before they become sacrifices. Free anyone you come across. The key used to free Master Ashton should still work. Good luck!", ["objectivesText"] = "Free 10 Captive Villagers .", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 133098, ["x"] = 0.2188, ["y"] = 0.5576 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.2188, ["y"] = 0.5576 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50531] = { ["id"] = 50531, ["name"] = "Under Their Noses", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 47181, 47485, 47486, 47487, 47488, 50531, 50573, 53041 }, ["series"] = { 47485, 47486, 47488, 47489, 50573, 53041 }, ["description"] = "Figures they wouldn't just put the destination on the crates for us. Nothing's ever easy, is it? If the weapons aren't moving on Cagney's ferry, they must be passing through Bridgeport, the shipping hub just up the road. Bridgeport is protected by a garrison of Proudmoore marines. The Ashvane Company has a lot of nerve moving illegal weapons right under their noses. Come on, let's check it out.", ["objectivesText"] = "Speak with Flynn Fairwind in Bridgeport.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 158065, 158066, 163032, 163034 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 134166, ["x"] = 0.758, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.6892, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 585, ["name"] = "The Ashvane Trading Company", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 16, ["flags"] = 0 } } },
[50533] = { ["id"] = 50533, ["name"] = "Stick It To 'Em!", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50265, 50306, 50325, 50327, 50329, 50370, 50445, 50481, 50530, 50533 }, ["description"] = "We have been able to stop the Grand Rite but the witches will try again unless we act. We have to destroy them. Utterly. <Cleardawn smiles.> How kind of them to give us the means. You've helped us get this far, <name>. You control the Demolisher. Destroy everything you see! Once we've finished we can signal for help out of here!", ["objectivesText"] = "Use the Crimsonwood Demolisher to destroy witch forces in the Crimson Forest.", ["rewardGold"] = 607600, ["rewardXP"] = 3455, ["rewardItems"] = { 156859, 156950, 156951, 157821, 158064, 158175 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135021, ["x"] = 0.37, ["y"] = 0.504667 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.504667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 602, ["name"] = "Crimson Forest", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50534] = { ["id"] = 50534, ["name"] = "Wendigo Away", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50064, 50070, 50161, 50162, 50165, 50168, 50264, 50343, 50359, 50493, 50504, 50534, 50553 }, ["description"] = "If the unearthly howls coming from the Highlands at night are any indication, the wendigos must have some sort of leader or alpha. I tell you, it's the sort of sound that could only come from some sort of massive, hulking, flesh-eating abomination. Definitely something that could tear us limb from limb, and munch on our frail bones, all without breaking a sweat. How exhilarating! I'm sure it'll be no problem for us to handle though.", ["objectivesText"] = "Kill Bonerender .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134447, ["x"] = 0.74, ["y"] = 0.726 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134447, ["x"] = 0.74, ["y"] = 0.726 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.726 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5451, ["name"] = "Not the Bees!", ["orderIndex"] = 11, ["flags"] = 0 } }, ["startItems"] = { 157860 } },
[50535] = { ["id"] = 50535, ["name"] = "Power of the Overseer", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50535 }, ["series"] = { 48871, 50536 }, ["description"] = "Overseer Nerzet is very cruel, and oh so easy to provoke! It makes her very angry when things go missing, or move, or change... my crew and I are having a yip of a time! That you got this device to work was certainly a bonus! It will be much easier for us to finish up what we need to do here, with her out of the way. Um, and maybe go ahead and grab that neat power rock she carries. It could come in handy.", ["objectivesText"] = "Kill Overseer Nerzet and take her power rock. Progress: Were you able to end her reign?", ["rewardGold"] = 514800, ["rewardXP"] = 5145, ["rewardItems"] = { 157855 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134148, ["x"] = 0.472, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134148, ["x"] = 0.472, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[50536] = { ["id"] = 50536, ["name"] = "Magic Decoder Device", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50536 }, ["series"] = { 48871, 50535 }, ["description"] = "We retrieved this device from the sethrak in the ruins to the east, but have not been able to use it. When you approached, it started to glow. Something about you... < Maaz pauses and eyes the stone on your neck.> ...or on you... is waking it up! Please, <class>, use the scepter and examine the statues of the Keepers, in the central courtyard of the ruins. Something there got their overseer very excited.", ["objectivesText"] = "Examine the Keeper statues in the ruins. Progress: What did you discover?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134148, ["x"] = 0.472, ["y"] = 0.728 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134148, ["x"] = 0.472, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.472, ["y"] = 0.728 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[50538] = { ["id"] = 50538, ["name"] = "The Missing Handler", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 862, ["storyline"] = { 50538 }, ["description"] = "I just received word from Warbeast Kraal dat one of their handlers is missing. Dis is not usually a problem, but dey are expecting a large hatching dis year. Dey will need all de hands dey can get! Go on and see if you can find de handler, name of Bazo or something, and tell him to get back to de Kraal.", ["objectivesText"] = "Look for Handler Bazkoji near Warbeast Kraal.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 139311, ["x"] = 0.6552, ["y"] = 0.4192 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.6552, ["y"] = 0.4192 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9598 } }, ["questType"] = "standard" },
[50539] = { ["id"] = 50539, ["name"] = "The Secrets of Zul'Ahjin", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47716, 48313, 48314, 48315, 48896, 50539, 50561, 50770 }, ["description"] = "You're not the only one who came to Zul'Ahjin looking for answers. The place is crawling with looters and assassins, all searching for something... So far, they've come up empty handed, but that's because they don't know where to look. I do. Investigate the statue at the center of the ruins. It is the key to uncovering the city's ancient secrets.", ["objectivesText"] = "Investigate the statue.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134533, ["x"] = 0.47, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 608, ["name"] = "A City of Secrets", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 39, ["flags"] = 0 } } },
