[50542] = { ["id"] = 50542, ["name"] = "An Explosive Opportunity", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50542 }, ["series"] = { 49531 }, ["description"] = "You there! Do I have the most AMAZING opportunity for you? A gnome named Wulferd Fizzbracket is on the eve of a breakthrough and could use an intrepid business partner that's on the brawnier side. Such as a <class> like yourself. Just follow the road east until you reach Fizzsprings Resort, the most fantastical wonder of nature. Wulferd is the type that stands out from the crowd.", ["objectivesText"] = "Speak with Wulferd Fizzbracket at the Fizzsprings Resort.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 134509, ["x"] = 0.666, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129858, ["x"] = 0.675, ["y"] = 0.558 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.666, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[50544] = { ["id"] = 50544, ["name"] = "The Hunters of Kennings Lodge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50544 }, ["description"] = "HELP WANTED! As we turn into the busy season, Kennings Lodge is looking for recreational hunters to assist with fulfilling the ever growing list of orders from Boralus. These are short term positions which will be paid relative to performance. Kennings Lodge can be found by following the south road past the mining yard. Report to Alanna Holton on arrival.", ["objectivesText"] = "Speak with Alanna Holton .", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 127161, ["x"] = 0.758, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
