[50550] = { ["id"] = 50550, ["name"] = "The Fall of Emperor Korthek", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Korthek finally approaches. It's been many years since I've faced him in battle. When he first rose to power, I failed my people. I will not falter again. I am prepared to do what must be done. What I should have done long ago. We must kill Korthek and take his key to prevent him, Jakra'zet, or anyone else from ever resurrecting Mythrax. When you are prepared, we will face him together.", ["objectivesText"] = "Defeat Emperor Korthek .", ["rewardGold"] = 772200, ["rewardXP"] = 6175, ["rewardItems"] = { 155417, 155418, 155434, 155440, 155444, 160032, 160033, 160034 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 138411, ["x"] = 0.518, ["y"] = 0.286 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135390, ["x"] = 0.52, ["y"] = 0.274 }, { ["mapID"] = 864, ["npcID"] = 138519, ["x"] = 0.519, ["y"] = 0.283 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.286 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 58, ["flags"] = 0 } } },
[50551] = { ["id"] = 50551, ["name"] = "Temple of Sethraliss: Avatar of the Loa", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50551 }, ["description"] = "We cannot let Mythrax bring his destruction upon this world once more. We need our loa now more than ever, but she has yet to return to us. The time of her rebirth has passed. Someone, or something, must be preventing her awakening. Enter her resting place and see what you can uncover.", ["objectivesText"] = "Enter the Temple of Sethraliss and heal the avatar of the loa. Progress: We cannot let Mythrax bring his destruction upon this world once more.", ["rewardGold"] = 1029600, ["rewardXP"] = 8230, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129588, ["x"] = 0.27, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129588, ["x"] = 0.27, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "dungeon" },
