[50583] = { ["id"] = 50583, ["name"] = "To the Other Side", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "It looks like the coven is using Corlain as a base of operations. There's no way we'll be able to cut through this many of them without the rest of the Inquisitors. They must still be stuck behind the wall. <class>, there are three smaller footmen gates along the walls into Corlain. See if you can get them open so our allies can make their way through.", ["objectivesText"] = "Open the Eastern, Southern, and Western Gates in Upper Corlain. Progress: What news of the other inquisitors?", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 1804, 1805, 1806, 1807, 184374, 184519 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.2415 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 599, ["name"] = "Upper Corlain", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 47, ["flags"] = 0 } } },
[50584] = { ["id"] = 50584, ["name"] = "Ruinous Rituals", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "Take a look in the city square, <class>. <Marshal Reade gestures toward a ritual being performed by some disciples in the distance.> It appears the coven has gone beyond dark constructs, and are now conjuring creatures of nightmare with their rituals. Let us not wait to see what these monsters are capable of. We should put an end to them right here. Fortunately, the disciples seem too focused on their spell to notice us. Maybe you can use that to your advantage.", ["objectivesText"] = "Kill 4 Blighted Horrors in Upper Corlain. Progress: Have the monsters been abolished?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.314667, ["y"] = 0.271333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 599, ["name"] = "Upper Corlain", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 49, ["flags"] = 