[50585] = { ["id"] = 50585, ["name"] = "Hexecutioner", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "It would appear that this is where the coven is training their new acolytes. Our efforts may be for naught if they continue to expand their numbers. I cannot leave Lucille's side in this place, but you have already shown yourself a formidable combatant. Cut them down.", ["objectivesText"] = "Kill 13 witches of the Heartsbane Coven in Upper Corlain.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131636, ["x"] = 0.314667, ["y"] = 0.271333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.314667, ["y"] = 0.271333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 599, ["name"] = "Upper Corlain", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 48, ["flags"] = 0 } } },
[50586] = { ["id"] = 50586, ["name"] = "The Fall of Corlain", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50586 }, ["description"] = "<This discarded journal looks like it belonged to one of the residents of upper Corlain. Within it details some early signs of the Heartsbane's appearance in Corlain. If you can find more writings like this, you might be able to piece together the events that led to Corlain's current state.>", ["objectivesText"] = "Examine 6 Corlain Citizen's Journals in Upper Corlain.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 160109 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 }, { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[50588] = { ["id"] = 50588, ["name"] = "Storming the Manor", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47961, 47968, 47978, 47979, 47981, 47982, 48108, 48109, 48110, 48111, 48113, 48165, 48170, 48171, 48198, 48283, 48518, 48519, 48520, 48521, 48522, 48523, 48538, 48622, 48941, 48942, 48943, 48944, 48945, 48946, 48963, 48986, 49259, 49295, 49443, 49803, 49804, 49807, 49926, 50003, 50149, 50151, 50173, 50253, 50446, 50453, 50457, 50583, 50584, 50585, 50588 }, ["description"] = "Now is our chance. Waycrest Manor is just up that hill, and hopefully inside we'll find my mother and father. If we also manage to find the \"Mother\" that's leading this horrible coven, then we will make her regret the day she ever set foot in Drustvar . Are you with me, <class>?", ["objectivesText"] = "Follow Lucille Waycrest toward Waycrest Manor in Upper Corlain.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 155093, 155094, 155095, 155112, 155113, 155114, 155115, 155116 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.2415 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5373, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 599, ["name"] = "Upper Corlain", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5373, ["name"] = "Darkness of Drustvar", ["orderIndex"] = 50, ["flags"] = 0 } } },
