[50596] = { ["id"] = 50596, ["name"] = "Exterminate the Vermin", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50596 }, ["series"] = { 48872 }, ["description"] = "On top of the fury of the overseer, and this \"key\" not being here, we have a pest problem. Sneaky little vulperan thieves keep ransacking our site. We have taken some prisoner. We have them around the upper level of the dig site, working off their misdeeds. However, I believe a more permanent solution would be preferred. Please, oh mighty cobra, give us the honor of getting rid of our prisoners with your most potent venom!", ["objectivesText"] = "Rescue 3 captive excavators. Progress: They had what?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134408, ["x"] = 0.4975, ["y"] = 0.753 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134164, ["x"] = 0.474, ["y"] = 0.728 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.4975, ["y"] = 0.753 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
