[50614] = { ["id"] = 50614, ["name"] = "Freedom for the Sea", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "The naga along this coast appear to be trying to push the shoreline up the hill here. We've been able to keep them back at the beach so far, but they've been binding more elementals than we can keep up with. Without a tidesage, we have no way to free the elementals from their bindings, but we cannot allow them to push forward anymore. The spirit of the sea should not be contained by anything. Slay them, and let them return to the ocean.", ["objectivesText"] = "Slay 6 Bound Seasurges . Progress: For a people that live in the sea, the naga seem to have little respect for it.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50616] = { ["id"] = 50616, ["name"] = "A Bit of a Bind", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "The naga sorceress leading this excursion seems to be in the process of binding a larger elemental. If she succeeds, we will no doubt lose our foothold here. Strike out at her, perhaps you can catch her off guard and interrupt the ritual. Remove the head from these snakes.", ["objectivesText"] = "Slay Binder Sa'thress . Progress: Is the seawitch dead?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752, 160345, 160371, 160374, 160377, 160380 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50617] = { ["id"] = 50617, ["name"] = "Atul'Aman", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50617, 50702, 50703, 50904 }, ["description"] = "Jakra'zet and his troops attacked while we were away. Serrik fought well, but it wasn't enough. The keys are gone, and it's only a matter of time before the barrier is broken. Your friends have already given chase. Jakra'zet must not be allowed to resurrect Mythrax the Unraveler. He must be stopped before it's too late! We don't have much time. Meet me at Atul'Aman! We must catch up with Kaja and Rakera and stop the ritual!", ["objectivesText"] = "Meet Vorrik at Atul'Aman.", ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129588, ["x"] = 0.27, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135625, ["x"] = 0.43, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 611, ["name"] = "Atul'Aman", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 60, ["flags"] = 0 } } },
[50621] = { ["id"] = 50621, ["name"] = "Caught in the Net", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "When the naga force first arrived, there were a handful of the local fishermen out on boats. One of our scouts reports that most of them have been captured and are currently being kept in cages around the beach. Free any of them you happen to find and point them back here. We'll get them armed and remind the naga that you don't mess with sailors!", ["objectivesText"] = "Free 5 villagers.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50622] = { ["id"] = 50622, ["name"] = "Deal's Off", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50353, 50354, 50363, 50365, 50368, 50622, 50640, 51354 }, ["description"] = "There's one more farm left, far to the west. They're real close to the kraul. Deal works the land by herself. If anyone got hit bad, it'd be her. It's just past the worst part of the collapse, so keep an eye out for the quilboar.", ["objectivesText"] = "Search the Deal Farmstead for any survivors.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 129808, ["x"] = 0.507, ["y"] = 0.75 }, { ["mapID"] = 942, ["npcID"] = 132118, ["x"] = 0.515, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134752, ["x"] = 0.494, ["y"] = 0.664667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.507, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 583, ["name"] = "Storming the Kraul", ["orderIndex"] = 0, ["flags"] = 0 } } },
