[50635] = { ["id"] = 50635, ["name"] = "The Shifting Tides", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "I'm no tidesage, but even I can tell that whatever you have there is probably not a good sign for the bastion. There's one of those Tortollans, Rikal , who's been helping us figure out a solution to whatever the naga are planning in front of the levee. He'd probably like to see this.", ["objectivesText"] = "Speak with Rikal at Fort Daelin.", ["rewardGold"] = 70225, ["rewardXP"] = 1030, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131014, ["x"] = 0.35, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.302, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 3, ["flags"] = 0 } } },
