[50639] = { ["id"] = 50639, ["name"] = "Waycrest Manor: The Fallen Mother", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50583, 50584, 50585, 50588, 50639 }, ["description"] = "This is all a lot to process... The Marshal... gone? My mother... the leader of the coven? It's just too much... ...but we have come too far to turn back now. It is clear that my mother and father, as I knew them, are gone. It is time we cleansed the taint from this land. We must take the inquisitors and find them in Waycrest Manor. We will end this, once and for all.", ["objectivesText"] = "Defeat Lady Waycrest in Waycrest Manor. Progress: This must be done.", ["rewardGold"] = 1029600, ["rewardXP"] = 5530, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.2415 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 599, ["name"] = "Upper Corlain", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50640] = { ["id"] = 50640, ["name"] = "A Question of Quillpower", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9562, ["mapID"] = 942, ["storyline"] = { 50353, 50354, 50363, 50365, 50368, 50622, 50640, 51354 }, ["description"] = "I can't believe you managed to kill that thing. You're quite impressive, you know that? Either way, we should be getting back to Roz with our report. We're stuck in the middle of the kraul, surrounded by angry quilboar. But I have a plan! Some of the boars seem reasonable enough. I gave them a bit of my rations and they've been following me around. I bet we can use them to hitch a ride out of this place. You in?", ["objectivesText"] = "Ride the Ornery Battleboar out of Briarback Kraul and report to Mayor Roz .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134752, ["x"] = 0.494, ["y"] = 0.664667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.487, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9562 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 583, ["name"] = "Storming the Kraul", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50641] = { ["id"] = 50641, ["name"] = "Break Their Ranks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "This temple is our last bastion against the Faithless. We need every able fighter to defend its walls. If you're offering to help, we won't turn you away. Head into battle and do what you can to break their ranks!", ["objectivesText"] = "Kill 10 Faithless attackers within the Temple Grounds. Progress: We must defend the temple at all costs!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128696, ["x"] = 0.272, ["y"] = 0.538 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128696, ["x"] = 0.272, ["y"] = 0.538 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.538 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 609, ["name"] = "The Three Keepers", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 44, ["flags"] = 0 } } },
[50642] = { ["id"] = 50642, ["name"] = "The Warchief Commands", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50476, 50646, 50647, 50738 }, ["description"] = "Silithus. That has been the name of the game... or rather, that is what I wanted the Alliance to believe. Make no mistake, Azerite is just as powerful as it is rumored to be but I have bigger plans in mind. High Overlord Saurfang is leading an army towards Silithus. By now, he should be in the Northern Barrens. I want you to intercept him and notify him that the preparations are complete. Preparations for what, you ask? Why, we are going to capture the World Tree.", ["objectivesText"] = "Find Saurfang in the Northern Barrens.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 140192, 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 134574, ["x"] = 0.508, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 10, 62 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 10, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50644] = { ["id"] = 50644, ["name"] = "Facing the Invaders", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "While we try to figure out what to do with those channelers, we'll have to take shots where we can get them. Our men could use some assistance retaking parts of the lower walls. Kill some naga for me, would you?", ["objectivesText"] = "Slay 15 of the naga forces invading Fort Daelin.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50645] = { ["id"] = 50645, ["name"] = "Eeling in a Big One", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "If you are up to it, I have an idea to give the naga an amusing surprise. < Rikal slowly pulls out a scroll and waves it in your face.> I need some teeth from marine predators to cast the spell though. Luckily, the naga brought some disgusting eels with them. Go gather their fangs, and bring them back to me.", ["objectivesText"] = "Collect 16 Abyssal Fangs . Progress: I can't wait to see how this goes.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131014, ["x"] = 0.35, ["y"] = 0.476 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131014, ["x"] = 0.35, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50646] = { ["id"] = 50646, ["name"] = "A Quick Diversion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 10, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50476, 50642, 50647, 50738 }, ["description"] = "I have halted our march until I received word that we were ready to divert. What comes next will be a coordinated, synchronized attack on key outposts in Ashenvale. If we act quickly, we will destroy the kaldorei's defenses and clear a path all the way to Darkshore. Stormwind will surely send reinforcements to stop us. We have to conquer Teldrassil before they arrive. I will divert the troops. Meet with our operative, Lorash , outside Astranaar for further instruction.", ["objectivesText"] = "Find Lorash in Astranaar.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 134574, ["x"] = 0.508, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 134573, ["x"] = 0.388, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 10, 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50647] = { ["id"] = 50647, ["name"] = "Everybody Has a Price", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50476, 50642, 50646, 50738 }, ["description"] = "Hundreds of rogues have already attacked kaldorei outposts in Ashenvale. On my signal, they will begin the next phase of this war: sowing chaos. My colleague died not far from here, <name>, so I could use your help. If we stay out of sight, the town won't even know it's under attack before we have all of its guards down. I have a poison that will kill them quickly and silently. If you signal to me which targets are safe to attack without being noticed, I will put them down. What do you say?", ["objectivesText"] = "Work with Lorash to disarm Astranaar.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158190, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 134573, ["x"] = 0.388, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 134573, ["x"] = 0.388, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50649] = { ["id"] = 50649, ["name"] = "Filching from Thieves", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "The naga oft take what they want with little care for who they are taking it from. Perhaps we should do the same for them. The sorceresses use powerful beacons to assist with their spellcasting. I could use these relics to strengthen my own ritual.", ["objectivesText"] = "Collect 7 Tidal Beacons . Progress: Make sure you don't drop any of the beacons. I cannot say I know what will happen.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131014, ["x"] = 0.35, ["y"] = 0.476 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131014, ["x"] = 0.35, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 6, ["flags"] = 0 } } },
