[50653] = { ["id"] = 50653, ["name"] = "Reclaiming our Defenses", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "We were holding off the naga up until the latest attack. A few of our forces are still out there. The tidemaidens seem to be slowly torturing them to death. If you could save as many as you can find, we'd be one step closer to gaining the upper ground again.", ["objectivesText"] = "Save 8 stranded battalion soldiers .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 155232, 156472, 156482, 158181, 158183, 158200, 158332, 159752, 160334, 160337, 160340, 160343 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50656] = { ["id"] = 50656, ["name"] = "Risky Rescue", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50656 }, ["description"] = "The Faithless incursion is just up ahead. We tried to get ahead of the siege by attacking their camp in the dead of night, but they knew we were coming. Our troops were quickly overwhelmed. We called for a retreat, but only a few of us made it out. The fate of those that didn't is unknown... We don't have the numbers to attempt a rescue ourselves. We can't afford to lose any more fighters. You're their only hope.", ["objectivesText"] = "Free 4 Temple Defenders.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134611, ["x"] = 0.326, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134611, ["x"] = 0.326, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.326, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
