[50672] = { ["id"] = 50672, ["name"] = "Any Ammo Will Do", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "I'll have some men move some cannons down to the sea wall in preparation of whatever ritual is going on down in that delta. We could use some extra ammo before we spread ourselves too thin though. Luckily, those naga harpoons work well enough with our mortars. Take down those lances and bring back any harpoons that you find.", ["objectivesText"] = "Collect 20 Zeth'jir Harpoons on the coast south of Fort Daelin. Progress: We can use the naga's weapons against them!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50674] = { ["id"] = 50674, ["name"] = "Two-Faced Pirate Scum", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["series"] = { 50675, 50810 }, ["description"] = "We've been holding the Irontide off for days, but now they've brought in an ettin for reinforcements. We can't let him attack the town. A few of my best men just went up the hill to try and kill him. You look pretty capable, they could sure use your help?", ["objectivesText"] = "Eliminate Two Face Tom. Progress: Hurry <name> you've got to kill the ettin.", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50675] = { ["id"] = 50675, ["name"] = "Treasure Hunting", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["series"] = { 50674, 50810 }, ["description"] = "The workers are digging day and night out there to find the lost treasure. You'd get an equal share like everyone else, if ya wanna help out. Talk to Nedly about joining up.", ["objectivesText"] = "Speak to Nedly.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134702, ["x"] = 0.444, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50679] = { ["id"] = 50679, ["name"] = "Piercing the Shield", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "I've been talking with Rikal, and the tortollan says that our problem in the delta can probably be solved by turning the naga's magic back on them. A few of the sorceresses on the south coast have a channeling wand that we may be able to use to break the head priestesses' ritual channeling. Find one, and bring it back here.", ["objectivesText"] = "Find an intact Zeth'jir Channeling Rod . Progress: We cannot allow this fort to fall!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752, 160360, 160363, 160366, 160369, 160885 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 10, ["flags"] = 0 } } },
[50689] = { ["id"] = 50689, ["name"] = "It's the Pits", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50689 }, ["objectivesText"] = "Goblin Prospector rescued", ["rewardGold"] = 1123600, ["rewardXP"] = 25, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Goblin Prospector rescued", ["amount"] = 4, ["type"] = 0, ["objectID"] = 134759, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50690] = { ["id"] = 50690, ["name"] = "A Flickering of Hope", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 14838, ["mapID"] = 2215, ["storyline"] = { 50690 }, ["description"] = "This pervasive darkness continues to cast shadows over our fields, hindering our harvests. Check with Keyrra Flamestonge and see if you can help restore some order.", ["objectivesText"] = "Check in with Keyrra Flamestonge .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 206350, 251719, 251720, 251721, 251722 }, ["starts"] = { { ["mapID"] = 2215, ["npcID"] = 206528, ["x"] = 0.612, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 2215, ["npcID"] = 215527, ["x"] = 0.654, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 2215, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 2215 }, ["zone"] = { 14838 } }, ["questType"] = "standard" },
[50691] = { ["id"] = 50691, ["name"] = "Not On Our Payroll", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "The workers are complaining about elementals coming into the area while they're digging for treasure. Just this morning, I had two people crushed to death! It's slowing down the hunt! You can earn your share by getting rid of those elementals!", ["objectivesText"] = "Eliminate 10 Restless Stones .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134702, ["x"] = 0.444, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134702, ["x"] = 0.444, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50696] = { ["id"] = 50696, ["name"] = "Fun With Magnets", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "My last time in Tol Barad I had to leave in a big hurry, but I grabbed a few gadgets on the way out. This device is one of my favorites, so don't break it! It'll suck the treasure right out of the mud. It may make you tingle some, that's just the radiation. Find lost coins using the metal collector near the signs I've placed.", ["objectivesText"] = "Collect 60 Lost Coins . Progress: I like gold, let's find some!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134710, ["x"] = 0.444, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50697] = { ["id"] = 50697, ["name"] = "Bomb Beats Rock", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "I stole an old treasure map off an Irontide pirate. The map marks several caves on it with circles. The caves are blocked by boulders, but now that you're here, we're going to open them up. You get to do all the dangerous stuff, plant explosives, kill things, and cave exploring. I'll supervise.", ["objectivesText"] = "East and West Caves blown open!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134710, ["x"] = 0.444, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50698] = { ["id"] = 50698, ["name"] = "Problem Solving with Gunpowder", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "Fort walls only go so far when it comes to defense. We've got cannons in position to fire if the naga get too close, but we need some fortifications further out. There should be a few good areas to set up some traps further down the beach. Those naga will never know what hit them!", ["objectivesText"] = "Set 5 Explosive Traps.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 11, ["flags"] = 0 } } },
[50699] = { ["id"] = 50699, ["name"] = "Worker's Rights", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50699 }, ["series"] = { 49465 }, ["description"] = "Hey, you! You lookin' for work? I ain't got a job for ya, but I can tell ya to stay away from Algerson Lumber! Algerson'll promise ya some solid labor work and decent pay, but it's a lie I tell ya! The conditions are terrible, we're gettin' attacked, and Algerson ain't even battin' an eye! He don't care 'bout us little people. I'd stay away if I were you!", ["objectivesText"] = "Talk to Maynard Algerson at Algerson Lumber Yard.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 134776, ["x"] = 0.674, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129613, ["x"] = 0.689333, ["y"] = 0.180667 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[50700] = { ["id"] = 50700, ["name"] = "Drust in Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 50700 }, ["series"] = { 49225, 51151 }, ["description"] = "A few days ago, a band of Alliance researchers that called themselves the \"Explorers' League\" took a contingent of Kul Tiran soldiers to the old Drust ruins down the road. We haven't really heard from them since, and I'm growing a bit concerned. I can't leave my post, so can you check up on the team?", ["objectivesText"] = "Find the Explorers' League members at the Thovas Base-Camp.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 139089, ["x"] = 0.663333, ["y"] = 0.247667 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128381, ["x"] = 0.626, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.663333, ["y"] = 0.247667 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[50702] = { ["id"] = 50702, ["name"] = "Defeat Jakra'zet", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50617, 50702, 50703, 50904 }, ["description"] = "Jakra'zet is summoning Mythrax the Unraveler! We cannot allow the ritual to continue. Jakra'zet must be stopped before it's too late! Lead the way, <name>. We'll be right behind you. Let's go!", ["objectivesText"] = "Defeat Jakra'zet.", ["rewardGold"] = 561800, ["rewardXP"] = 6175, ["rewardItems"] = { 155396, 155397, 155398, 155399, 161158, 161159, 161160, 161161 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135133, ["x"] = 0.27, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 611, ["name"] = "Atul'Aman", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 62, ["flags"] = 0 } } },
[50703] = { ["id"] = 50703, ["name"] = "Informing the Horde", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50617, 50702, 50703, 50904 }, ["description"] = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts. Were it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive. We must inform our allies of what has transpired in Vol'dun . I'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now. I'm sure our paths will cross again, <name>. It was an honor fighting with you.", ["objectivesText"] = "Speak with Baine Bloodhoof .", ["rewardGold"] = 16980, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135133, ["x"] = 0.27, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 611, ["name"] = "Atul'Aman", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 63, ["flags"] = 0 } } },
[50704] = { ["id"] = 50704, ["name"] = "Anchors Aweigh Too Much", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "I got a little deal on the side, selling used ship parts to Addington Shipyards. While you're out looking for the treasure, see what sort of useful parts you can salvage from the mud: anchors, cannons, whatever! We'll sell them to Addington and cut you in for a share of the profits.", ["objectivesText"] = "Find 12 Old Ship Parts . Progress: See what you can find out in the mud.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158682, 158684, 158724, 160332, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134702, ["x"] = 0.444, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134702, ["x"] = 0.444, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50705] = { ["id"] = 50705, ["name"] = "A Snake with Three Heads", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "Now that all of the preparation has been done, it's time to tackle the main threat. You can use the channeling rod you just found in conjunction with this scroll I got from Rikal to break the shields around the naga leaders in the delta. Hurry! Stop them before they finish their summoning!", ["objectivesText"] = "Slay the three naga channelers.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752, 160429 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131000, ["x"] = 0.34, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 12, ["flags"] = 0 } } },
[50706] = { ["id"] = 50706, ["name"] = "Clearing the Delta", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "The greatest of the Zeth'jir offensive sits within the delta as we speak, waiting for the summoning ritual to be finished. If we can clear out a number of them, we'll finally have the upper hand. Get down there and cause as much chaos as you can!", ["objectivesText"] = "Kill 15 naga forces in the Eventide Delta. Progress: This fort will always stand in defense of Kul Tiras!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 156472, 156482, 158181, 158183, 158200, 158332, 159752 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131003, ["x"] = 0.345, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131000, ["x"] = 0.34, ["y"] = 0.548 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 13, ["flags"] = 0 } } },
