[50738] = { ["id"] = 50738, ["name"] = "A Timely Arrival", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 63, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50476, 50642, 50646, 50647 }, ["description"] = "My end of the bargain is done, <race>. I am going to check on the other outposts to make sure none of my brothers and sisters are in trouble. Meet with the Warchief and inform her that Astranaar has been secured. If everything has gone according to plan, she should be well on her way. Oh, and try not to hog all the glory, yeah? < Lorash smirks at you>.", ["objectivesText"] = "Greet Warchief Sylvanas Windrunner in Astranaar.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 52613, 52637, 131279, 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 63, ["npcID"] = 134573, ["x"] = 0.388, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 135003, ["x"] = 0.432, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 63, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 62, 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50739] = { ["id"] = 50739, ["name"] = "Missing Business", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50739 }, ["description"] = "Poor little Coda has been in quite the tizzy since his friends vanished. I found him here, out cold, after a sting from one of those awful wasps. Just a tiny bit of our sandstinger remedy got Coda right up, though! Take some with you, and keep an eye out for other little ones out there.", ["objectivesText"] = "Rescue 7 Sable Polecats . Progress: Did you find them all?", ["rewardXP"] = 4115, ["rewardItems"] = { 158464, 159729 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135012, ["x"] = 0.56, ["y"] = 0.492 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135012, ["x"] = 0.56, ["y"] = 0.492 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.492 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[50740] = { ["id"] = 50740, ["name"] = "Zoram'gar Outpost", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50772, 50800 }, ["description"] = "Saurfang shall establish our troops here, now that Astranaar is ours. I shall continue my hunt for the only creature that can stop our march to victory: Malfurion Stormrage. Our next order of business will be to establish a foothold at the base of Darkshore. Commander Grimfang of the Zoram'gar Outpost should be able to accommodate an incoming army. Inform him of our arrival and ensure the necessary preparations are made.", ["objectivesText"] = "Make the necessary preparations at the Zoram'gar Outpost.", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 135003, ["x"] = 0.432, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 134574, ["x"] = 0.508, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 10, 62 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50741] = { ["id"] = 50741, ["name"] = "Don't Turtle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "There's a Tortollan who's trying to get our treasure! He's over on the west side of town. He's nosey and he may have found something! Talk to Moxie. Come up with a plan to get rid of him.", ["objectivesText"] = "Speak with Moxie. Progress: You deal with that Tortollan yet?", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134702, ["x"] = 0.444, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135067, ["x"] = 0.426, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 8, ["flags"] = 0 } } },
[50742] = { ["id"] = 50742, ["name"] = "All Laid Out For Us", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "<This is all the treasure Calico McGee's found so far. Packed up and ready to move out. More like all laid out for you to take! You'll need a few extra hands to carry this much loot. There should be some Treasure Hunters from Deadwash around. Ask Big Find Balor , Toothless Eddard , and Chopper Darry to help.>", ["objectivesText"] = "Get three treasure hunters to help you.", ["rewardGold"] = 339600, ["rewardXP"] = 5145, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 15, ["flags"] = 0 } } },
[50743] = { ["id"] = 50743, ["name"] = "The Immediate Problem", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 50743 }, ["description"] = "I sent one of my lieutenants, a woman by the name of Bauer, to the fishermen's hamlet just down the road. We received a few reports of naga activity spreading down the coast in that direction. We need those forces back as soon as possible. I would ask that you join her in assisting the villagers of the hamlet.", ["objectivesText"] = "Speak with Lieutenant Bauer.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[50745] = { ["id"] = 50745, ["name"] = "Infiltrating the Empire", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["series"] = { 49662, 49664 }, ["description"] = "The heart of the Faithless empire rests just beyond this ridge. We will need to move swiftly and quietly to avoid detection once inside. Thankfully, my former dwelling is nearby. I know a passage that should allow us to advance into the fortress with minimal resistance. When you are ready, speak with me and I will show you the way. < Vorrik looks around suspiciously.> I expected the Faithless to patrol this area... Keep your eyes open for anything suspicious along the path.", ["objectivesText"] = "Accompany Vorrik to his sanctum.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137970, ["x"] = 0.428, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135172, ["x"] = 0.4524, ["y"] = 0.3524 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 48, ["flags"] = 0 } } },
[50746] = { ["id"] = 50746, ["name"] = "Crater Conquered", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "I can take it from here, $p. I'll rally these vulpera and march through the trenches creating chaos. Korthek and his armies will be forced to deal with us! If you and Vorrik are going to make a move, you should do it now.", ["objectivesText"] = "Return to Vorrik .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135090, ["x"] = 0.462, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135172, ["x"] = 0.4524, ["y"] = 0.3524 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 52, ["flags"] = 0 } } },
[50748] = { ["id"] = 50748, ["name"] = "Don't Drop It... Yet", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "The Faithless are training pterrordaxes as mounts so that they can rain down death from the skies. Their skycallers have developed a means of storing volatile lightning magic into fragile crystals. Lightning bombs, in the simplest sense. The magic behind it is quite brilliant, really. The bombs will be exceptionally useful if we can secure the aid of Rakjan, the powerful and fierce pterrordax at the top of this mountain. Acquire as many as you can carry, while I will do my best to recruit Rakjan.", ["objectivesText"] = "Collect 6 Volatile Lightning Bombs from Faithless. Progress: There are no end to the Faithless, so grab as many as you can carry.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 154896 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135172, ["x"] = 0.4524, ["y"] = 0.3524 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135110, ["x"] = 0.476, ["y"] = 0.377 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.4524, ["y"] = 0.3524 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 54, ["flags"] = 0 } } },
[50749] = { ["id"] = 50749, ["name"] = "Free Ride", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "One thing I've learned during my time in Vol'dun is to not stay in one place for too long. And doubly so when the Faithless are involved. We've done our damage here. Let's move before we get caught. I procured a mount to take us back to Meerah and the others in Vorrik's Sanctum quickly. Don't worry, this Faithless won't be needing it anymore.", ["objectivesText"] = "Steal the Battle Krolusk mount and return to Meerah.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135099, ["x"] = 0.554, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137982, ["x"] = 0.479, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50750] = { ["id"] = 50750, ["name"] = "Infuriating the Emperor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "It seems I underestimated Korthek's cowardice. I expected him to be behind the barrier, ready to ambush us. Yet, still he hides. That allows us a few moments to prepare. We musn't waste them. While I siphon power off of these immense crystals, you must thin the numbers of the Faithless here. I will grant you a powerful boon to speed you in your task. When Korthek arrives, he will require our full attention.", ["objectivesText"] = "Use Vorrik 's Bulwark to defeat 75 Faithless within the Sacred Sands.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135111, ["x"] = 0.52, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135111, ["x"] = 0.52, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 56, ["flags"] = 0 } } },
[50751] = { ["id"] = 50751, ["name"] = "Sanctuary Under Siege", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "I fear that Emperor Korthek was not lying when he boasted of his foolish plan. If General Jakra'zet attacked the Sanctuary of the Devoted while we were away, there is a good chance that he now has everything needed to resurrect Mythrax. We must hurry to the Sanctuary and stop Jakra'zet. Mythrax must not be reborn!", ["objectivesText"] = "Meet Vorrik at the Sanctuary of the Devoted.", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135390, ["x"] = 0.52, ["y"] = 0.274 }, { ["mapID"] = 864, ["npcID"] = 138519, ["x"] = 0.519, ["y"] = 0.283 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129588, ["x"] = 0.27, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 59, ["flags"] = 0 } } },
[50752] = { ["id"] = 50752, ["name"] = "Relics of Sethraliss", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "It may surprise you to learn that the Faithless hoard ancient relics of Sethraliss. I assure you that they do not do so out of reverence or respect, as is proper. Korthek's brood is driven only by greed and an insatiable lust for power. They rip whatever magic they can from the relics, even if it means destroying them in the process. Rescue the ancient artifacts of Sethraliss in the Sacred Sands nearby. We will honor and preserve them in the Sanctuary of the Devoted.", ["objectivesText"] = "Recover the Skull of the First Skycaller , Rebirth Creed , Sethraliss Sight Stone , and Blood of the Fallen Loa . Progress: Do you have the artifacts?", ["rewardGold"] = 292100, ["rewardXP"] = 4115, ["rewardItems"] = { 158722, 160526, 160527, 160528 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135111, ["x"] = 0.52, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135111, ["x"] = 0.52, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 610, ["name"] = "Storming the Spire", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 57, ["flags"] = 0 } } },
[50753] = { ["id"] = 50753, ["name"] = "Earl-E Bot Gets the Worm", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "It could take you days to get that much meat, and I don't want to wait around. So, we'll use a Bot as bait! You send EARL-E towards any disturbances you see in the mud. He'll make enough noise to scare any worms out. Then kill the worms, get the meat. I'll watch from here.", ["objectivesText"] = "Get Mud Worm Meat for Maokka . Progress: Do you have the meat yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160514, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135067, ["x"] = 0.426, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135033, ["x"] = 0.425, ["y"] = 0.543 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50754] = { ["id"] = 50754, ["name"] = "To Have Loved and Lost", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50754, 50758, 50759, 50760, 50761, 50762, 50763 }, ["description"] = "I have a favor to ask you of a... personal nature. Whitegrove Chapel lies to the north, just past the town of Corlain. Someone... important to me rests in the graveyard on its grounds. I've been unable to visit his grave for some time, and I would like to pay my respects. If you come upon Whitegrove Chapel, could you lay these flowers next to his headstone? Just look for the most recent grave there...", ["objectivesText"] = "Lay the Crimson Bouquet next to the Simple Gravestone in Whitegrove Chapel.", ["rewardGold"] = 28090, ["rewardXP"] = 345, ["rewardItems"] = { 163603 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135200, ["x"] = 0.304667, ["y"] = 0.325333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.2415 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5444, ["name"] = "Drustvar Chapel", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50755] = { ["id"] = 50755, ["name"] = "A Meal for Birds", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50755 }, ["description"] = "I don't know why I agreed to this. We weren't supposed to be scavenging. Kiro gave me specific instructions to head to the basin and feed the buzzards. I can't go back to camp until they eat, but I'm not heading into that basin while the sethrak are still swarming. Have you ever fed a buzzard? It's easy, I promise. You kill it, they eat it. That simple.", ["objectivesText"] = "Kill wildlife within The Brine Basin so Mekaru 's buzzards can eat. Progress: They still look hungry to me.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137629, ["x"] = 0.548, ["y"] = 0.424 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137629, ["x"] = 0.548, ["y"] = 0.424 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.424 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[50756] = { ["id"] = 50756, ["name"] = "Subterranean Evacuation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50756 }, ["objectivesText"] = "Kul Tiran Captive freed", ["rewardItems"] = { 158652 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Kul Tiran Captive freed", ["amount"] = 10, ["type"] = 0, ["objectID"] = 135122, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50757] = { ["id"] = 50757, ["name"] = "Untame Slaughter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 48329, 49002, 49437, 49667, 49668, 49669, 50749, 50757 }, ["description"] = "The Faithless rely on their krolusks for everything. They are mounts, battle companions, beasts of burden, and often even food to fuel the sethrak empire. If we can disrupt their krolusks, we'll disrupt their whole empire. One broken wheel stops the caravan, eh? Take out as many of their krolusk tamers as you can. That'll have a longer impact than just killing the krolusks.", ["objectivesText"] = "Kill 8 Faithless within the Feeding Pits.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135099, ["x"] = 0.554, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135099, ["x"] = 0.554, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5428, ["name"] = "Sethrak Fortress", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50758] = { ["id"] = 50758, ["name"] = "Painful Memories", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50754, 50758, 50759, 50760, 50761, 50762, 50763 }, ["description"] = "A terrible thing happened in this place, and it has doomed me to an eternity of walking these grounds. All I remember is that Lucille and I were to be wed, but instead I met my end. If you have an ounce of sympathy in your heart, then I beg you to help me. Find out what happened that night, so I might leave here. I know my strongest memories are tied to the ring I bore for Lucy that day. Find it among my bones, and maybe it will lead you to the answer.", ["objectivesText"] = "Search the Forgotten Bones for Treadward's Ring in Whitegrove Chapel.", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 158654, 163603 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 135200, ["x"] = 0.304667, ["y"] = 0.325333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 134953, ["x"] = 0.232, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.325333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5444, ["name"] = "Drustvar Chapel", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50759] = { ["id"] = 50759, ["name"] = "Running Late", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50754, 50758, 50759, 50760, 50761, 50762, 50763 }, ["description"] = "I beg your pardon, but I am a little concerned at Lord Waycrest's tardiness. I'd hate to be a bother, but would you mind checking on him? The ceremony awaits his presence. You can find him in the bride's room, at the top of the tower.", ["objectivesText"] = "Speak with Lord Arthur Waycrest in Whitegrove Chapel. Progress: It must be around here somewhere...", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["rewardItems"] = { 116052, 151623, 158719, 163603 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 134953, ["x"] = 0.232, ["y"] = 0.126 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132994, ["x"] = 0.237, ["y"] = 0.139 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.232, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5444, ["name"] = "Drustvar Chapel", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50760] = { ["id"] = 50760, ["name"] = "From This Day Forward", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50754, 50758, 50759, 50760, 50761, 50762, 50763 }, ["description"] = "Lord Waycrest is on his way? Excellent! You have my thanks, <sir/madam>. Please, take a seat.", ["objectivesText"] = "Take a seat and observe the wedding ceremony in Whitegrove Chapel.", ["rewardGold"] = 84900, ["rewardXP"] = 1385, ["rewardItems"] = { 163603 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 134953, ["x"] = 0.232, ["y"] = 0.126 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132994, ["x"] = 0.237, ["y"] = 0.139 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.232, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5444, ["name"] = "Drustvar Chapel", ["orderIndex"] = 3, ["flags"] = 0 } } },
[50761] = { ["id"] = 50761, ["name"] = "Blood in the Chapel", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50754, 50758, 50759, 50760, 50761, 50762, 50763 }, ["description"] = "<Sir/Madam>, you have helped me before and I beseech you to do so again. My guards are clearly outnumbered by these brigands. I must stay here to protect Lucille, so I will need you to assist in protecting the guests. Are you able?", ["objectivesText"] = "Defeat 10 Red Hand Assassins in Whitegrove Chapel. Progress: We must rout these knaves!", ["rewardGold"] = 169800, ["rewardXP"] = 2765, ["rewardItems"] = { 163603 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132994, ["x"] = 0.237, ["y"] = 0.139 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 132994, ["x"] = 0.237, ["y"] = 0.139 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.237, ["y"] = 0.139 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5444, ["name"] = "Drustvar Chapel", ["orderIndex"] = 4, ["flags"] = 0 } } },
[50762] = { ["id"] = 50762, ["name"] = "The Lady's Fate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50754, 50758, 50759, 50760, 50761, 50762, 50763 }, ["description"] = "Meredith never joined the ceremony. She might be in trouble! Lucy is in shock, and I cannot leave her here. You must go in my stead to the tower, and ensure the safety of your Lady. Do this for me, and you will be rewarded.", ["objectivesText"] = "Find Lady Meredith Waycrest in Whitegrove Chapel. Progress: What have you found?", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 158914, 163603 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 132994, ["x"] = 0.237, ["y"] = 0.139 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135200, ["x"] = 0.304667, ["y"] = 0.325333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.237, ["y"] = 0.139 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5444, ["name"] = "Drustvar Chapel", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50763] = { ["id"] = 50763, ["name"] = "One Last Request", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50754, 50758, 50759, 50760, 50761, 50762, 50763 }, ["description"] = "I can feel my bonds to this place slipping, and I have you to thank. I would like to ask one more favor of you though. Please bring the ring you found to Lucille. It was meant for her to hold, not my dusty bones. And <class>, do not tell her what has transpired here. She has enough tragedy weighing down her heart. I do not wish to add to it.", ["objectivesText"] = "Bring Treadward's Ring to Lucille Waycrest at Watchman's Rise. Progress: What... what's this?", ["rewardGold"] = 28090, ["rewardItems"] = { 133997, 155564, 158585, 158587, 158628, 158630, 158654, 163603 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 135200, ["x"] = 0.304667, ["y"] = 0.325333 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 }, { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.304667, ["y"] = 0.325333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5444, ["name"] = "Drustvar Chapel", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50767] = { ["id"] = 50767, ["name"] = "The Scrimshaw Gang", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50767 }, ["rewardItems"] = { 141605, 158677 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50770] = { ["id"] = 50770, ["name"] = "Effective Antivenom", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47716, 48313, 48314, 48315, 48896, 50539, 50561, 50770 }, ["description"] = "The salve is ready. I work fast. Hopefully faster than the scorpid poison. Take this antivenom to your friend and see that he swallows every last drop. You should know within moments if it's been effective.", ["objectivesText"] = "Administer the Antivenom to Serrik .", ["rewardGold"] = 84900, ["rewardXP"] = 2060, ["rewardItems"] = { 158678 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135154, ["x"] = 0.47, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134533, ["x"] = 0.47, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 608, ["name"] = "A City of Secrets", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 38, ["flags"] = 0 } } },
[50771] = { ["id"] = 50771, ["name"] = "Calldown: Cleaner", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50771, 50775, 50812, 51991, 52129 }, ["description"] = "With these dust blowin' siro-ma-whosits all over this beach front, it's a pain to get our cleaners out onto the nodes. Some of the crew wanted to check somewhere else, but no way we're leaving without those rocks for Gallywix. Between you and me, <class>, we're gonna be gettin' some serious hazard pay for this gig.", ["objectivesText"] = "Identify and mark 5 Azerite deposits for the extraction team. Progress: All the resources been harvested?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158725 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135179, ["x"] = 0.262, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135179, ["x"] = 0.262, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5421, ["name"] = "For Profit", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50772] = { ["id"] = 50772, ["name"] = "On The Prowl", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 10, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50740, 50800 }, ["description"] = "Do you see all of the wisps about? I have seen this once before, when the demon Archimonde was felled by the sting of hundreds - no - thousands of wisps. This can mean only one thing. Malfurion is beckoning the aid of his ancestors. The Warchief has already taken a scouting party ahead to Darkshore to intercept him. Please, <name>. Find the Warchief and see if she has yet caught her prey. We have secured all of Ashenvale, but we must keep the pressure on.", ["objectivesText"] = "Find Warchief Sylvanas Windrunner in Darkshore. Progress: You may approach, <name>.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128, 211279 }, ["starts"] = { { ["mapID"] = 10, ["npcID"] = 134574, ["x"] = 0.508, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 10, 62 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 6, ["flags"] = 0 } } },
[50773] = { ["id"] = 50773, ["name"] = "You're a Shark", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 49831, 50614, 50616, 50621, 50635, 50644, 50645, 50649, 50653, 50672, 50679, 50698, 50705, 50706, 50773 }, ["description"] = "Have you ever been bitten by a shark? I have, numerous times. It stings. Murlocs don't usually survive shark attacks. The ritual I had in mind is ready to cast. Let me know when you're prepared.", ["objectivesText"] = "Kill 20 murlocs. Progress: I can't wait to see how this goes.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 52906, 52952, 156472, 156482, 158181, 158183, 158200, 158332, 158680, 159752, 211279 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131014, ["x"] = 0.35, ["y"] = 0.476 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131014, ["x"] = 0.35, ["y"] = 0.476 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.476 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 794, ["name"] = "Defense of Fort Daelin", ["orderIndex"] = 8, ["flags"] = 0 } } },
[50774] = { ["id"] = 50774, ["name"] = "No Bot Left Behind", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "You left Earl-E behind, and a giant worm ate him! He's got sentimental, uh... monetary value. We don't leave any bots behind! Kill that worm and get Earl-E back.", ["objectivesText"] = "Help Earl-E . Progress: What? Earl-E isn't going to help himself!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135067, ["x"] = 0.426, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135067, ["x"] = 0.426, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 10, ["flags"] = 0 } } },
[50775] = { ["id"] = 50775, ["name"] = "Get Us Some Beach", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50771, 50775, 50812, 51991, 52129 }, ["description"] = "These guys are running out of \"ammo\" faster than we can replace it! I tells 'em, we're on a beach, you're in a sandblaster, suck it up! They says it's against the cleaner driver rules for their local chapter. I'm not buyin' it. Grab us some more sand. Them sand monsters have gotta be full of the stuff! We'll make it worth your time.", ["objectivesText"] = "Collect 20 piles of sand. Progress: Ya get us the dirt yet?", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158707 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135179, ["x"] = 0.262, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135179, ["x"] = 0.262, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5421, ["name"] = "For Profit", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50787] = { ["id"] = 50787, ["name"] = "Make Our Case", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50787, 50788, 50789, 50790, 50795, 50972 }, ["series"] = { 49741, 50110, 50788, 50789, 50790, 50795 }, ["description"] = "Katherine has trusted Priscilla Ashvane as an advisor and a close friend for many years, even before they both lost their husbands at Theramore. She's heard the rumors about Ashvane, just like anyone. Whether by fear or loyalty, she's chosen to ignore them. It's time to finally open her eyes.", ["objectivesText"] = "Reveal Lady Ashvane's treason to Katherine Proudmoore .", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 162522 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135259, ["x"] = 0.4904, ["y"] = 0.8232 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.4904, ["y"] = 0.8232 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 590, ["name"] = "Enemies Within", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 41, ["flags"] = 0 } } },
