[50791] = { ["id"] = 50791, ["name"] = "Skree...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50791 }, ["description"] = "< Kua'fon rests with his head under his wing.> Skree... <Perhaps the little guy could use a display of affection to raise his spirits.>", ["objectivesText"] = "Soothe Kua'fon by picking him up.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135272, ["x"] = 0.708, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 }, { ["mapID"] = 862, ["npcID"] = 135272, ["x"] = 0.708, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2VignetteID"] = 2771, ["db2VignetteName"] = "Kua'fon" },
[50793] = { ["id"] = 50793, ["name"] = "Cave Commotion", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "Killing that worm stirred up a commotion in the caves below. The Irontide seem pretty excited. We better check it out. Nedly's on his way, meet us near the caves.", ["objectivesText"] = "Meet up with Nedly and Moxie near the caves.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135067, ["x"] = 0.426, ["y"] = 0.542 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135330, ["x"] = 0.412, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.426, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 11, ["flags"] = 0 } } },
[50794] = { ["id"] = 50794, ["name"] = "Seeking Shelter", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50794 }, ["description"] = "I must head back to de arena. Razgaji will want to know what happened here. If you seek shelter, you will find it at de outpost not too far from here. I will let our leader know you're coming. Be safe, <name>.", ["objectivesText"] = "Find Razgaji at the Scorched Sands Outpost.", ["rewardGold"] = 280900, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 134162, ["x"] = 0.47, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[50795] = { ["id"] = 50795, ["name"] = "Prepare for Trouble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50787, 50788, 50789, 50790, 50795, 50972 }, ["series"] = { 49741, 50110, 50787, 50788, 50789, 50790 }, ["description"] = "With the evidence you've gathered, we can prove that the Ashvane Company was behind the attack. I would have preferred to do this in private, but I don't think we'll have the luxury. Look around - company men everywhere. Priscilla's got something up her sleeve... Let's get some backup before we go in there and cause a scene.", ["objectivesText"] = "Speak with 4 Proudmoore Guards in Unity Square.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 162522 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135259, ["x"] = 0.4904, ["y"] = 0.8232 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.4904, ["y"] = 0.8232 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 590, ["name"] = "Enemies Within", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 40, ["flags"] = 0 } } },
[50796] = { ["id"] = 50796, ["name"] = "SKREEEEE!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50796 }, ["description"] = "< Kua'fon opens his maw and issues a continuous screech.> SKREEEEEEEEEEEEE!!! <You know what to do.>", ["objectivesText"] = "Feed Kua'fon . Progress: SKREEEEEEEEEEEEEEEEEEE!!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 141605, 157779, 157780, 157781, 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135279, ["x"] = 0.708, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 }, { ["mapID"] = 862, ["npcID"] = 135279, ["x"] = 0.708, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2VignetteID"] = 2772, ["db2VignetteName"] = "Kua'fon" },
[50797] = { ["id"] = 50797, ["name"] = "A Turtle's Invitation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50797 }, ["description"] = "You have been most helpful <race>. Please visit me and the other Tortollans along the Jeweled Coast. We'll discuss soup and other pressing matters.", ["objectivesText"] = "Visit Maokka and the other Tortollans at the Jeweled Coast.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135033, ["x"] = 0.425, ["y"] = 0.543 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136710, ["x"] = 0.406, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.543 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 158213 } },
[50798] = { ["id"] = 50798, ["name"] = "Out on a Limb", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50798 }, ["description"] = "Ah, there you are. Kua'fon ran off into de jungle. I saw him head down de western path out of the Kraal but beyond that I could not say where he may have gone. This kind of thing happens with the young. Our winged companions have a keen sense of adventure! It would be helpful if yours could fly, but it is not yet time. I would check any reasonably high place that he could climb to, as a start.", ["objectivesText"] = "Find and rescue Kua'fon in the Slough.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 }, { ["mapID"] = 862, ["npcID"] = 135296, ["x"] = 0.641333, ["y"] = 0.433333 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2VignetteID"] = 2773, ["db2VignetteName"] = "Kua'fon" },
[50800] = { ["id"] = 50800, ["name"] = "Into the Woods", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50740, 50772 }, ["description"] = "Careful, <name> -- the forest is still brimming with Stormrage's forces... Look out behind you!", ["objectivesText"] = "Defeat the Alliance ambush.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 7, ["flags"] = 0 } } },
[50801] = { ["id"] = 50801, ["name"] = "A Nose for Ptrouble", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50801 }, ["description"] = "Ah, yes, I was wondering when you would come to check on your little one. As you have likely noticed, he is not here. Little ones are very curious and often seek to leave the nest before they are ready. It is often the brooding mother's job to keep them from wandering. What, did you think I was going to stop him? < Wingminder Goja laughs.> I heard some screeching to de west. Best hurry, or you may not have a hatchling to look after!", ["objectivesText"] = "Find Kua'fon in the Slough and rescue him from danger.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 }, { ["mapID"] = 862, ["npcID"] = 135303, ["x"] = 0.644286, ["y"] = 0.449714 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2VignetteID"] = 2774, ["db2VignetteName"] = "Kua'fon" },
[50802] = { ["id"] = 50802, ["name"] = "Iron Low Tide", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "A few years ago I tried to join the Irontide. They said I wasn't \"Irontide material\", not cruel or heartless enough! So I teamed up with Nedly and Moxie here in Deadwash, and we started looking for treasure on our own. Let's show these Irontide they're not \"Deadwash material\".", ["objectivesText"] = "Kill 10 Irontide Pirates.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50803] = { ["id"] = 50803, ["name"] = "I Want It All Now", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "These Irontide Raiders think they can just come in and take the treasure we've been hunting for months! By rights, that treasure is ours! Get in there and get our share of it, before it's gone. By share, I mean all of it!", ["objectivesText"] = "Collect 12 Irontide Coin Bags . Progress: I want every piece of that treasure in there.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135330, ["x"] = 0.412, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135330, ["x"] = 0.412, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 12, ["flags"] = 0 } } },
