[50810] = { ["id"] = 50810, ["name"] = "Break 'Em Out", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["series"] = { 50674, 50675 }, ["description"] = "An Irontide captain \"Calico McGee\" has been trying to scare us off for days now, but it's not working. He's ordered his men to lock everyone up and sell us as slaves! They've brought enough chains for everyone! Break the chains and set our workers free.", ["objectivesText"] = "Free 10 workers.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 31312, 31313, 31314, 31315, 33226, 37959, 38001, 38044, 38105, 38230, 38231, 38232, 38665, 55004, 65277, 65297, 65316, 65335, 65683, 65703, 65721, 112591, 112592, 112593, 112594, 131699, 142054, 143498, 158226, 158635, 158636, 158724, 160481, 160668, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 202283, 203330, 211279, 237812, 248563, 248564, 248565, 248566 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50812] = { ["id"] = 50812, ["name"] = "Awakened Elements", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50771, 50775, 50812, 51991, 52129 }, ["description"] = "It seems that all of this infernal blasting and hammering has stirred up... something. I heard some screaming from over in that direction. <He gestures vaguely to the north.> If you could go take care of the situation, that would be most appreciated.", ["objectivesText"] = "Investigate the disturbance. Progress: Did you remove the impediment?", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135180, ["x"] = 0.262, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135180, ["x"] = 0.262, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5421, ["name"] = "For Profit", ["orderIndex"] = 4, ["flags"] = 0 } } },
