[50814] = { ["id"] = 50814, ["name"] = "A Horrible Place", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50814 }, ["description"] = "This town is a horrible place full of bad people. All they care about is money! No one cares about the turtles! The turtles are out there, thirsty, drying up, and getting stepped on by monsters! You have to save the turtles for me!", ["objectivesText"] = "Collect 6 Wetshell Turtles .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135367, ["x"] = 0.442, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135367, ["x"] = 0.442, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.442, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[50817] = { ["id"] = 50817, ["name"] = "A Charming Tail", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50817, 50818, 50979, 50980 }, ["series"] = { 50818 }, ["description"] = "I think they would make great guardians, when they get older... with the proper training. However, it seems some of my trainees have wandered off. There are so many things nearby that could harm them! Between the walking sandstorms and angry plants... it's been safer to hide out here and look at night. I'm so exhausted! Could you take this flute with you and play them a little tune? It will remind them to come back to me.", ["objectivesText"] = "Send 15 cobras to Jenoh .", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 158883, 160847 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5422, ["name"] = "Feeding the Hungry", ["orderIndex"] = 1, ["flags"] = 0 } } },
[50818] = { ["id"] = 50818, ["name"] = "A Lost Flute", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50817, 50818, 50979, 50980 }, ["series"] = { 50817 }, ["description"] = "<This little flute, while dusty, appears to be well cared for. Its owner can't be too far away.>", ["objectivesText"] = "Find the owner of the Desert Flute . Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 158882, 160847, 163036 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5422, ["name"] = "Feeding the Hungry", ["orderIndex"] = 0, ["flags"] = 0 } } },
[50823] = { ["id"] = 50823, ["name"] = "Ripe for the Picking", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["description"] = "The kaldorei have finally halted our progress. In a perfect world, we could have marched all the way to Auberdine and taken Teldrassil before they could even slow us down - but it matters little. Malfurion will try to hold us back until his fleet returns from Silithus. Until then, his army is too small - if only we could find a path through these damned wisps. I have an idea. Let's have a chat with Saurfang.", ["objectivesText"] = "Meet with Saurfang and Sylvanas in the Zoram'gar Outpost.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 63, ["npcID"] = 135443, ["x"] = 0.134667, ["y"] = 0.322667 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 62, 63 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 8, ["flags"] = 0 } } },
[50834] = { ["id"] = 50834, ["name"] = "Keep It Down!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50834 }, ["description"] = "There is a lot of noise and light coming from those filthy mechs down by the shore. No wonder my little hatchlings get so cranky! They are shaking up a coast that is already unstable. You never know what one might wake up that way! Let them know they should be careful.", ["objectivesText"] = "Warn the goblins of danger.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135179, ["x"] = 0.262, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[50837] = { ["id"] = 50837, ["name"] = "A Quick Flyover", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50878, 50879, 50880, 53604, 53605 }, ["description"] = "Malfurion knows that his wisp wall is a temporary measure. He is buying time for reinforcements to arrive in Teldrassil. It is imperative that we find a way through that wall, and quickly. I want you to take our explosive reserves and apply pressure. You will not be able to bring it down, but you may be able to find us an opening. I will have a squadron ready to strike once you break ground. Zarvik Blastwix should have a few bombardiers for the job.", ["objectivesText"] = "Use explosives to fend off the Alliance army in Darkshore. Progress: Done?", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 9, ["flags"] = 0 } } },
[50838] = { ["id"] = 50838, ["name"] = "A Nose for Ptrouble", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50838 }, ["description"] = "Ah, so you noticed he is missing again. I would check de east this time. I heard some screeching from that direction. I am sure he will be fine- after all, what sort of trouble could he get in with you looking after him? < Wingminder Goja smiles just a touch sarcastically.> Best find out.", ["objectivesText"] = "Find Kua'fon in Atal'Gral and rescue him from danger.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133679, ["x"] = 0.706, ["y"] = 0.51 }, { ["mapID"] = 862, ["npcID"] = 135464, ["x"] = 0.7948, ["y"] = 0.4084 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2VignetteID"] = 2782, ["db2VignetteName"] = "Kua'fon" },
