[50842] = { ["id"] = 50842, ["name"] = "Mast Effect", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50842 }, ["description"] = "Kua'fon was peering over de edge and managed to fall off de cliff again. Normally he gets back up here on his own, but it be taking too long this time. Best go down to de beach and find him. He is probably stuck up one of de ship masts out there. If he will not come down, you can try bribing him with more fish.", ["objectivesText"] = "Find Kua'fon in Talanji's Rebuke and bribe him down with fish.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 109076, 157782, 158885, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133679, ["x"] = 0.706, ["y"] = 0.51 }, { ["mapID"] = 862, ["npcID"] = 135481, ["x"] = 0.75925, ["y"] = 0.517 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2VignetteID"] = 2783, ["db2VignetteName"] = "Kua'fon" },
