[50860] = { ["id"] = 50860, ["name"] = "A Nose for Ptrouble", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 50860 }, ["description"] = "Kua'fon is getting very large. Perhaps he thinks himself equal to de beasts of this jungle. He may well learn that he is not. You should find him before that lesson costs him his life. I heard a commotion to de north. Start there.", ["objectivesText"] = "Find Kua'fon in the Savagelands and rescue him.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133680, ["x"] = 0.708, ["y"] = 0.506 }, { ["mapID"] = 862, ["npcID"] = 135504, ["x"] = 0.6904, ["y"] = 0.3756 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2VignetteID"] = 2786, ["db2VignetteName"] = "Kua'fon" },
