[50960] = { ["id"] = 50960, ["name"] = "Sweete's Orders", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50960 }, ["description"] = "<Tucked into the pages of the captain's logbook is a letter bearing the seal of Harlon Sweete. It looks like these pirates have been ordered by Sweete to cause further disruption to House Waycrest. Lucille should be notified of this immediately!>", ["objectivesText"] = "Bring Sweete's Orders to Lucille Waycrest in Drustvar . Progress: What have you brought, mainlander?", ["rewardGold"] = 6380, ["rewardItems"] = { 159156 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 129642, ["x"] = 0.368, ["y"] = 0.5 }, { ["mapID"] = 896, ["npcID"] = 131638, ["x"] = 0.318, ["y"] = 0.2415 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.368, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
