[50965] = { ["id"] = 50965, ["name"] = "Those Who Remain", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50965 }, ["description"] = "<The runes on the wooden plaque glow faintly with an ancient magic. It looks like it is a small piece of a larger record.> <One of the Thornspeakers at the Teller Farm would probably recognize what this is.>", ["objectivesText"] = "Collect 8 Ashenwood Relics . Progress: Is there something more you need?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 159350, 160027 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135976, ["x"] = 0.3, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["startItems"] = { 160027 } },
