[50967] = { ["id"] = 50967, ["name"] = "Lost in the Woods", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50967 }, ["description"] = "My student, Amalie, and I have taken it upon ourselves to act as the keepers of these woods. We were away from Drustvar briefly, and upon our return, found the grove infested and the surrounding land corrupted. Amalie decided that she could deal with the grove infestation alone. It's been some time since she ran off, could you look for her while you're in the Ashenwood?", ["objectivesText"] = "Find Amalie Oakseeker.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 211279 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 135976, ["x"] = 0.3, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135976, ["x"] = 0.3, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[50970] = { ["id"] = 50970, ["name"] = "A Farmer's Fate", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50970 }, ["description"] = "Old Jakob here was one of the few folks who were never wary of us. I have, on occasion, even helped him around his farm in return for supplies. It is an injustice just to ignore his plight even amidst our own problems. The corruption which holds him seems to be early in form. I believe I can cleanse it. Take this branch, and bring it to the three shrines around the Ashenwood. That should allow it to gather enough energy for the ritual.", ["objectivesText"] = "Empower the Everliving Branch.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 135976, ["x"] = 0.3, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135976, ["x"] = 0.3, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[50972] = { ["id"] = 50972, ["name"] = "Proudmoore's Parley", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 50787, 50788, 50789, 50790, 50795, 50972 }, ["description"] = "So, we meet again. I... apologize for how you were treated last time. I trusted Priscilla like a sister and-- <Katherine chokes up for a moment before regaining her composure.> Let us keep this brief, for I will make no promises nor any formal accords in this state. Return to your leaders. Tell them I wish to parley. That is all for now. My people have suffered a great deal today and I have much to reflect upon.", ["objectivesText"] = "Report to Genn Greymane in Boralus Harbor.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 155020, 155021, 155022, 155031, 155032, 155033, 155034, 155039, 162522, 245271, 252386, 252400, 252403, 252406, 252653, 252654, 252754 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 121144, ["x"] = 0.4915, ["y"] = 0.848 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 120788, ["x"] = 0.68, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.4915, ["y"] = 0.848 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 590, ["name"] = "Enemies Within", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 45, ["flags"] = 0 } } },
[50976] = { ["id"] = 50976, ["name"] = "An Ancient Curse", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["storyline"] = { 50976 }, ["description"] = "<The harsh conditions of Nazmir have not been kind to the stone tablet. Most of the inscriptions have been worn away but you are able to make out a picture that shows a chest surrounded by glyphs. Above the chest you noticed what appears to be a large floating skull. Below the images you find a single word \"Aiji\". The ruins ahead seem foreboding, and you may want to bring some friends to help you. With their help, perhaps you can find the secret of this \"Aiji\" and its treasure within.>", ["objectivesText"] = "Activate the braziers of Xal'vor and defeat Aiji the Accursed .", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 163506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "group" },
[50977] = { ["id"] = 50977, ["name"] = "Smuggler Shakedown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 50977 }, ["rewardItems"] = { 159673 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[50978] = { ["id"] = 50978, ["name"] = "Out With the Old Boss", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50978, 50988, 51001, 51018, 51019, 51020 }, ["description"] = "Right so I talked to some people. You talked to some people. No one likes the Irontide. They're cutting in to profits and scaring off good, honest scoundrel- er customers! We take out the guy in charge and we'll be able to run the rest outta town! So a little change of management is in order. I'm not usually one for stabbin' people, I'm a lover not a fighter, but I can pay. You do this for me and I'll make sure you're welcome here whenever ya want? Sound good?", ["objectivesText"] = "Slay Richard Tornsail .", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["rewardItems"] = { 158639, 158640, 158642, 158643, 158644, 158645, 158648, 158649, 160207 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 136234, ["x"] = 0.208667, ["y"] = 0.452667 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136234, ["x"] = 0.208667, ["y"] = 0.452667 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.208667, ["y"] = 0.452667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5449, ["name"] = "Smuggler's Cove", ["orderIndex"] = 5, ["flags"] = 0 } } },
[50979] = { ["id"] = 50979, ["name"] = "Just a Nip", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50817, 50818, 50979, 50980 }, ["description"] = "My tough-guys-in-training are quick learners! They do seem to get a bit... bitey... when they're grouchy, though. Too many, and I start to get a little light-headed. The nearby atrivax plants have a medicinal gel. It is great to treat fresh wounds and nullify venom. They don't like sharing it. Could you harvest a bit for me?", ["objectivesText"] = "Get 10 samples of Atrivax Gel. Progress: How goes the juicing?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 159675, 160847 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5422, ["name"] = "Feeding the Hungry", ["orderIndex"] = 2, ["flags"] = 0 } } },
[50980] = { ["id"] = 50980, ["name"] = "My Hungry Neighbor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50817, 50818, 50979, 50980 }, ["description"] = "There is an angry hydra that has decided to make a nearby ridge his home. He keeps getting bigger, and meaner, and hungrier! My cobras are terrified. Please, <name>, take care of him before he comes after us!", ["objectivesText"] = "Kill the Territorial Hydra .", ["rewardXP"] = 5145, ["rewardItems"] = { 160004, 160005, 160006, 160007, 160008, 160847 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135400, ["x"] = 0.295, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5422, ["name"] = "Feeding the Hungry", ["orderIndex"] = 3, ["flags"] = 0 } } },
