[51001] = { ["id"] = 51001, ["name"] = "Every Day I'm Smugglin'", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 50978, 50988, 51001, 51018, 51019, 51020 }, ["description"] = "Hey! Wanna make some quick gold? See, I had a mishap a few weeks ago with a shipment. Too much grog, dark seas, sudden rocks. You know, that old story. Anyway, my cargo's been floating out there and no one will get it back for me. Can you believe it? You bring my cargo back and I'll pay you a generous recovery fee. We got a deal? Great! Oh, uh, watch out for the sharks. Did I forget to mention the sharks?", ["objectivesText"] = "Collect 5 Smuggled Goods from the sea near the shipwreck close to Anyport. Progress: You get the goods?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 159680 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 136140, ["x"] = 0.208, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136140, ["x"] = 0.208, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.208, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5449, ["name"] = "Smuggler's Cove", ["orderIndex"] = 1, ["flags"] = 0 } } },
