[51053] = { ["id"] = 51053, ["name"] = "The Day the Port Fell", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 51054 }, ["description"] = "Dis be a cursed land, $pr. Feel it in your bones: de cold chill of death... and undeath. De Pirate-King Zem'lan rules dis port, with his crew of de eternal damned. If you be lookin' for honor or noble adventure, you won't find it here. But if you can settle for vengeance and treasure, I got an offer for you. But you should know who you be allying with. My hands are not clean in dis. Take de medallion from my cloak and use it to reveal a vision of my past at de end of de dock.", ["objectivesText"] = "Use First Mate Jamboya's Medallion to view a vision of his past. Progress: I've witnessed countless horrors through countless generations.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["rewardItems"] = { 159747 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128261, ["x"] = 0.354, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128261, ["x"] = 0.354, ["y"] = 0.838 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51054] = { ["id"] = 51054, ["name"] = "Overdue Mutiny", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 51053 }, ["description"] = "I used to be a Zandalari, $p. Long ago, before dis curse. We were all Zandalari pirates, proudly sailing under de black flag of our captain, Zem'lan. Now look at us... undead monsters, forced to serve our eternal captain like slaves. Well, I be done with dis. De curse can't be broken, but we can still mutiny! What say you? It gonna be tough, but I promise treasure and a chance to kill de notorious Pirate-King Zem'lan who murdered your vulpera friend. Help me down, and we be gettin' started.", ["objectivesText"] = "Free First Mate Jamboya .", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 128261, ["x"] = 0.354, ["y"] = 0.838 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.838 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 4, ["flags"] = 0 } } },
[51055] = { ["id"] = 51055, ["name"] = "The Yard Arm of the Law", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["description"] = "I'm not de only pirate Zem'lan has had strung up around de port. Hangin' on de yard arm is his favorite form of punishment for de crew. We can't feel pain and don't stay dead, so his options are limited. Look for more crewmates hangin' around town. Tell dem to meet me here after you free dem. After weeks of hanging helplessly while being mocked and abused by de rest of de crew, I bet dey be willin' to discuss mutiny.", ["objectivesText"] = "Free Quartermaster Tulmac, Gunner Bosanya, and Jukanga the Snitch.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 5, ["flags"] = 0 } } },
[51056] = { ["id"] = 51056, ["name"] = "My Last Day Alive", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["description"] = "De curse came one fateful day, in ages past, when de sethrak attacked. Dere was no end to dem. In our desperation, I helped Pirate-King Zem'lan do de unthinkable. We became monsters. Even worse, we became eternal slaves to Zem'lan. De curse weighs heavy on me, but my guilt is heavier. I led me crew into dis. Before we confront de Pirate-King himself, you need to understand what we be up against. You need to see what happened de day dat de Port of Zem'lan fell.", ["objectivesText"] = "Use First Mate Jamboya's Medallion to witness visions of his past.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 159757 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51057] = { ["id"] = 51057, ["name"] = "Maroon 'em with Fire", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 47499, 51059 }, ["description"] = "We gonna have to sail out to de Golden Isle to face Pirate-King Zem'lan. Let's make sure de rest of de crew can't follow us once we go. Burn their boats in de harbor.", ["objectivesText"] = "Use the Undying Torch to burn 8 Pillaging Canoes. Progress: Don't burn my boat, <name>. We be needin' dat one.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 159774 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136309, ["x"] = 0.354, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136310, ["x"] = 0.342, ["y"] = 0.824 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 7, ["flags"] = 0 } } },
[51060] = { ["id"] = 51060, ["name"] = "Our Share of the Plunder", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 48326, 51061, 51062 }, ["description"] = "Dis treasure belongs to de crew! We've fought every battle for Zem'lan, but he hoards all de booty for himself. And if ya try to take some for yourself, he turns ya into one of his goldslaves. Those be de mindless drones ya see tendin' to de treasure out here. We ain't leavin' here empty-handed after de mutiny. Collect all de treasure ya can! Beware de cursed bits. It don't hurt us, but I'm guessin' it'll hurt you.", ["objectivesText"] = "Collect 12 Cursed Treasures of Zem'lan . Progress: More treasure!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 152659 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136779, ["x"] = 0.312, ["y"] = 0.849333 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136779, ["x"] = 0.312, ["y"] = 0.849333 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.849333 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 10, ["flags"] = 0 } } },
[51061] = { ["id"] = 51061, ["name"] = "The First Time I Died", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 48326, 51060, 51062 }, ["description"] = "Dis be it. Where Zem'lan cursed us all. It began with me death. De first of countless deaths I've had since. Each of dem spent fighting and dying for Pirate-King Zem'lan and his selfish treasure hoard. I don't know if de idols he used to curse us can even be destroyed, but we gotta try. Let's take dem to de altar where de ritual occurred and try to smash one.", ["objectivesText"] = "Place the idols on the altar and try to destroy them.", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136779, ["x"] = 0.312, ["y"] = 0.849333 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.849333 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 11, ["flags"] = 0 } } },
[51062] = { ["id"] = 51062, ["name"] = "Escaping Zem'lan", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47499, 48324, 48326, 48327, 51053, 51054, 51055, 51056, 51057, 51059, 51060, 51061, 51062 }, ["series"] = { 48326, 51060, 51061 }, ["description"] = "Pirate-King Zem'lan was right about one thing: he won't stay dead for long. We gotta take our treasure and get out of here while we got de chance. We can take de boat, but we'll need a place to hide out for awhile. Are your vulpera friends open to housin' a few stowaways? < First Mate Jamboya motions to the piles of treasure in his boat.> Clearly, we can pay dem for their trouble.", ["objectivesText"] = "Ride Jamboya's boat to the shore and lead the pirates to Camp Lastwind.", ["rewardGold"] = 140450, ["rewardXP"] = 2060, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136779, ["x"] = 0.312, ["y"] = 0.849333 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 125904, ["x"] = 0.388, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.849333 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5427, ["name"] = "Port of Zem'lan", ["orderIndex"] = 13, ["flags"] = 0 } } },
[51068] = { ["id"] = 51068, ["name"] = "Raiding Their Stores", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 51068 }, ["description"] = "We're low on food supplies. Hit up Newstead and bring us whatever you can find.", ["objectivesText"] = "Obtain a Roast Boar , a Colossal Cheese Wheel , a Basket of Eggs , and a Keg of Applebrew .", ["rewardItems"] = { 159717, 159718, 159719, 159720, 159723, 159724, 159726, 159727, 163988, 163989, 163990, 163991 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "group" },
[51069] = { ["id"] = 51069, ["name"] = "WANTED: Darkspeaker Jo'la", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51069 }, ["description"] = "Wanted for atrocious crimes against the Zandalari: Darkspeaker Jo'la Defeat this powerful adherent of Zul, and a great reward shall be yours.", ["objectivesText"] = "Slay Darkspeaker Jo'la", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 123019, ["x"] = 0.674, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "group" },
[51070] = { ["id"] = 51070, ["name"] = "Raiding the Boulderfist", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 51070 }, ["description"] = "The Boulderfist have recently raided Drywhisker Mine, and are sitting on a large amount of iron ore. We want it back.", ["objectivesText"] = "Obtain 200 pieces of Unprocessed Iron Ore . Progress: We can't let the Alliance take Arathi. We'll use whatever iron we can get.", ["rewardItems"] = { 159721 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "group" },
[51071] = { ["id"] = 51071, ["name"] = "WANTED: Sabertusk Empress", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51071 }, ["description"] = "To any and all brave enough to seek the challenge: Find and defeat a ferocious Sabertusk Empress , the strongest and most vicious of all sabertusks in Zuldazar . They can be found up and down the road from the Village in the Vines. A reward for any that succeed!", ["objectivesText"] = "Slay a Sabertusk Empress Progress: The wanted poster stands with tasks etched on it.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 163047 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131187, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "group" },
[51072] = { ["id"] = 51072, ["name"] = "WANTED: Prime Thumpknuckle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51072 }, ["description"] = "To any and all brave enough to seek the challenge: Find and defeat a Prime Thumpknuckle , the largest and most dangerous of all the wild gorillas. They can be found up and down the road from the Village in the Vines. A reward for any that succeed!", ["objectivesText"] = "Slay a Prime Thumpknuckle", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 163047 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131187, ["x"] = 0.516, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "group" },
[51081] = { ["id"] = 51081, ["name"] = "Syrawon the Dominus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 1165, ["storyline"] = { 51081 }, ["rewardItems"] = { 161047 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "world", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[51082] = { ["id"] = 51082, ["name"] = "Iron Stores", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 51082 }, ["description"] = "While the mine is under Horde banners our peons ensure the iron supply never runs dry. This key provides access to the chest. Make sure it still works.", ["objectivesText"] = "Use the Heavy Iron Key to access the Iron Stores. Progress: Chest giving you trouble?", ["rewardItems"] = { 159728 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[51084] = { ["id"] = 51084, ["name"] = "Dark Chronicler", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51084 }, ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "world", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[51085] = { ["id"] = 51085, ["name"] = "WANTED: Dark Chronicler", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["storyline"] = { 51085 }, ["description"] = "Champion wanted for an expedition into the depths of Xibala. Strange noises and wails come from the bones at night and our workers are terrified. Seek out the source of the strange noises and destroy it, and a reward will be yours.", ["objectivesText"] = "Slay Dark Chronicler", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "group" },
[51086] = { ["id"] = 51086, ["name"] = "Break's Over", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 51086 }, ["description"] = "It's come to my attention a few of our peons have been caught sleeping instead of hauling iron from the mine. We can't let our supplies get low. Take this club and get those lazy peons back on track.", ["objectivesText"] = "Return 3 Lazy Peons to work.", ["rewardItems"] = { 159744 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[51087] = { ["id"] = 51087, ["name"] = "WANTED: Dark Chronicler", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51087 }, ["description"] = "Champion wanted for an expedition into the depths of Xibala. Strange noises and wails come from the bones at night and our workers are terrified. Seek out the source of the strange noises and destroy it, and a reward will be yours.", ["objectivesText"] = "Slay Dark Chronicler Progress: Something stirs in the ruins. I hope you can discover its source!", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 131582, ["x"] = 0.438, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "group" },
[51088] = { ["id"] = 51088, ["name"] = "Heart of Darkness", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "We sent troops with Captain Conrad ahead to Nazmir to gain a foothold in that hellish jungle. The reports we've been receiving of the local troll population are... disconcerting. They're in over their heads, <name>. I have Brann Bronzebeard prepped and ready to head out. Accompany Brann to Nazmir so we can secure our position. The Wind's Redemption is at your disposal.", ["objectivesText"] = "Accompany Brann to Fort Victory in Nazmir.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136432, ["x"] = 0.62, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 863, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 39, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 39, ["flags"] = 0 } } },
[51089] = { ["id"] = 51089, ["name"] = "WANTED: Tojek", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51089 }, ["description"] = "<This appears to be a list of threats in the immediate vicinity, a angry scribble grabs your attention.> A reward of gold be promised to de one dat slays da creature Tojek . You know what dey say, an eye for an eye! -Rovash", ["objectivesText"] = "Hunt down Tojek .", ["rewardGold"] = 772200, ["rewardXP"] = 4150, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 135740, ["x"] = 0.392, ["y"] = 0.798 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.798 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "group" },
