[51091] = { ["id"] = 51091, ["name"] = "WANTED: Ten'gor and Nol'ixwan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51091 }, ["description"] = "To any hunters worthy of the challenge: Find and defeat the dueling giant direhorn and devilsaur, named Nol'ixwan and Ten'gor . Their never-ending battle has disrupted travel throughout Zuldazar . Glory for any that succeed!", ["objectivesText"] = "Slay Nol'ixwan and Ten'gor Progress: Do you think you are de greatest hunter in all of Zandalar?", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 123019, ["x"] = 0.674, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.176 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "group" },
