[51159] = { ["id"] = 51159, ["name"] = "Bring out the Big Gun", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51159 }, ["description"] = "<The cannon here is still in good condition. It's a lot of firepower to slow down the Horde. Taking this to Lea Martinel at Eckhart Lodge would really help their defenses.>", ["objectivesText"] = "Cannon delivered.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 237812 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135874, ["x"] = 0.578, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51161] = { ["id"] = 51161, ["name"] = "WANTED: Za'roco", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51161 }, ["description"] = "To any with honor and a sharp blade: Find and kill the thief, Za'roco. Those that betray their fellow exile don't deserve to live. Any who can cross his name off this list will earn a fitting reward.", ["objectivesText"] = "Find and kill Za'roco the Grifter .", ["rewardGold"] = 929400, ["rewardXP"] = 6175, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "group" },
[51162] = { ["id"] = 51162, ["name"] = "WANTED: Taz'raka the Traitor", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51162 }, ["description"] = "To all caravans and travelers: Beware Taz'raka the Traitor , a skeleton ambushing travelers on the road near Port of Zem'lan. If you must travel on that road, move quickly, and avoid entering any of the ruins. Several caravans have combined resources to offer a reward for Taz'raka's death. To collect, speak with Norah in Camp Lastwind.", ["objectivesText"] = "Find and kill Taz'raka the Traitor . Progress: Be careful out there, <name>.", ["rewardGold"] = 929400, ["rewardXP"] = 6175, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 125904, ["x"] = 0.388, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.772 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "group" },
[51164] = { ["id"] = 51164, ["name"] = "WANTED: Cobra Excursion Participants", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51164 }, ["description"] = "Attention guests of the Goldtusk Inn: We're proud to announce a surprise new addition to our lineup of excursion activities! The new Giant Deadly Unstoppable Killer Cobra Experience is now available! There's no need to sign up, you've all been automatically volunteered for this activity. To participate, simply travel into the dunes north of the inn and try not to be killed by the massive cobra now patrolling the area. We are not currently offering guided tours for this activity. Have fun!", ["objectivesText"] = "Kill Sevriss . Progress: All of our excursion survivors receive a reward!", ["rewardGold"] = 929400, ["rewardXP"] = 6175, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 }, { ["mapID"] = 864, ["npcID"] = 129354, ["x"] = 0.434, ["y"] = 0.602 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "group" },
[51165] = { ["id"] = 51165, ["name"] = "WANTED: Sandscout Vesarik", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51165 }, ["description"] = "To any and all who wish to see the Faithless empire fall: Sandscout Vesarik was spotted patrolling the dunes to the east. Gather a formidable force and strike him down! Those who succeed will be granted a fitting reward.", ["objectivesText"] = "Find and kill Sandscout Vesarik . Progress: Sandscout Vesarik was last seen patrolling the dunes to the east.", ["rewardGold"] = 772200, ["rewardXP"] = 6175, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134613, ["x"] = 0.268, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.268, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "group" },
