[51167] = { ["id"] = 51167, ["name"] = "Blood of Hir'eek", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51129, 51150, 51168, 51169 }, ["description"] = "Spooky chantin' in the next room can only mean one thing: someone's askin' for the ol' what-fer! I'd give ya a hand but I gotta drink a couple-a potions before I'm back on me feet. Take out that blood witch and I bet the magic'll dissipate.", ["objectivesText"] = "Defeat Blood Witch Pakkala . Progress: Two things I can't abide in this world: witches an' tall chairs.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136641, ["x"] = 0.312, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136641, ["x"] = 0.312, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 42, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 42, ["flags"] = 0 } } },
[51168] = { ["id"] = 51168, ["name"] = "Zealots of Zalamar", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51129, 51150, 51167, 51169 }, ["description"] = "We're surrounded by the enemy, <name>, and it's got me blood ragin'! I'm fit as a fi... instrument... and ready to help get us outta this forsaken cavern. Let's show 'em the end o' their miserable lives, eh?", ["objectivesText"] = "Slay 10 Zalamar Zealots in The Fall. Progress: Smells like... Victory.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136641, ["x"] = 0.312, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 43, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 43, ["flags"] = 0 } } },
[51169] = { ["id"] = 51169, ["name"] = "Flight from the Fall", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51129, 51150, 51167, 51168 }, ["description"] = "Let's get outta this hole! Hairs on the back o' me neck won't settle down. Was hopin' I'd find some artifacts, or treasures, or haggis, or at least a few worthwhile trinkets down here. Those bats look like the ones that we came on... hopefully they'll take us back to Fort Victory and not some rotten grotto with no valuables inside.", ["objectivesText"] = "Take a bat to Fort Victory.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136432, ["x"] = 0.62, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 44, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 44, ["flags"] = 0 } } },
[51170] = { ["id"] = 51170, ["name"] = "Ooh Rah!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51229, 51283 }, ["description"] = "We're going to need a harbor for our base of operations. Those ruins across the way should be perfect for our needs. Unfortunately, it looks to be occupied by a hostile force so I'm sending the marines to secure the shore. As the most experienced soldier here I want you to go with them. I don't want to see a single hostile remain when our engineers arrive. Now, go take that harbor in the name of the Alliance!", ["objectivesText"] = "Capture Shatterstone Harbor.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137867, ["x"] = 0.328, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137008, ["x"] = 0.395, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 22, ["flags"] = 0 } } },
