[51177] = { ["id"] = 51177, ["name"] = "Lessons of the Damned", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51279, 51280, 51281, 51282 }, ["description"] = "When I arrived here in disguise, the blood trolls thought me some sort of messenger of their Blood God. I seized the advantage and played into their primitive beliefs. I came here intending to open trade and learn how we can work with them against the Horde. What I discovered was altogether more compelling. I will show you.", ["objectivesText"] = "Learn of Captain Conrad 's progress.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136568, ["x"] = 0.4528, ["y"] = 0.5864 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136432, ["x"] = 0.62, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.4528, ["y"] = 0.5864 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 49, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 45, ["flags"] = 0 } } },
[51179] = { ["id"] = 51179, ["name"] = "Azerite Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 862, ["storyline"] = { 51179 }, ["objectivesText"] = "Absorb Azerite from defeated elementals", ["rewardItems"] = { 109644, 158075, 159754 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Absorb Azerite from defeated elementals", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["db2QuestInfoID"] = 151, ["db2QuestInfoName"] = "Magni World Quest - Azerite" },
[51190] = { ["id"] = 51190, ["name"] = "Granting a Reprieve", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "Now, on to more pressing matters. The Forsaken have shown up and are preventing us from saving our people. All my soldiers are either injured, exhausted, or in no shape for fighting. It seems these trollish natives have joined them as well. I am spread too thin. Kill the Horde. Kill the Zandalari. Kill them all.", ["objectivesText"] = "Slay 8 Forsaken and 8 Zandalari in Talanji's Rebuke.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 9, ["flags"] = 0 } } },
[51191] = { ["id"] = 51191, ["name"] = "Save Them All", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "Reinforcements? Ah thank tha Light! We done the best we can triaging the injured, but we need help. We need more hands that can heal wounds or at the verra least apply bandages . How are yer hands? Here, take these bandages and do what ye can tae treat tha injured.", ["objectivesText"] = "Heal 8 injured sailors. Progress: We've done what we can. Now all we can do is rest.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136195, ["x"] = 0.772, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136195, ["x"] = 0.772, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 10, ["flags"] = 0 } } },
[51192] = { ["id"] = 51192, ["name"] = "A Lack of Surplus", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "Food, wood, cloth... we're short on everything. Of course, I'm always short, but that donna stop me. Heh. See what ya can salvage from tha shipwrecks.", ["objectivesText"] = "Collect supplies from the shipwreck. Progress: Did ya find anything useful?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136192, ["x"] = 0.772, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136192, ["x"] = 0.772, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 11, ["flags"] = 0 } } },
[51193] = { ["id"] = 51193, ["name"] = "That One's Mine", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "Yer here to help? I donna have anything... Well, maybe I do. I know it's just a simple hammer. I know it's not special. But it's mine. That disgustin undead, Alan Hawkins, is taunting me wi'it. I promised Feorea I wouldna run off tae fight him, but ye made no such promises. Kill him and retrieve me hammer.", ["objectivesText"] = "Retrieve Degdod's Hammer from Alan Hawkins. Progress: Donna judge me. This is me best hammer.", ["rewardGold"] = 619600, ["rewardXP"] = 5990, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136192, ["x"] = 0.772, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136192, ["x"] = 0.772, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.772, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 12, ["flags"] = 0 } } },
[51199] = { ["id"] = 51199, ["name"] = "The Glory of the Hunt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51199 }, ["series"] = { 48070, 48077 }, ["description"] = "You here for the festival, friend? We're still settin' up here, but the hunt should've started by now! If ya want to take part, go meet Abbey in Foxhollow Woods. She'll get you all set up. Happy huntin'!", ["objectivesText"] = "Meet Abbey Watkins at the edge of Foxhollow Woods.", ["rewardGold"] = 140450, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 125042, ["x"] = 0.521667, ["y"] = 0.280667 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 125309, ["x"] = 0.554, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.521667, ["y"] = 0.280667 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[51200] = { ["id"] = 51200, ["name"] = "The Black Sheep", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "I'll admit, Millie has never really been one to follow the herd. Usually, it's no problem. She'll wander off for a bit, do her own thing and eventually make her way back to the flock. The hills have grown increasingly more dangerous lately, especially with the wolves and giants about. She's been gone awhile and I'm starting to worry. Could you please help me look for her?", ["objectivesText"] = "Find and rescue Millie .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136414, ["x"] = 0.318, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136414, ["x"] = 0.318, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51201] = { ["id"] = 51201, ["name"] = "The Troll's Tale", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51308 }, ["description"] = "You've arrived at an... interesting time, <class>. All of my ships have been destroyed. Half of my men are feeding the fishes, and the rest aren't doing much better. We're as good as doomed. And still, the Alliance prevails. These Zandalari trolls are to blame for this carnage. I need to know how they did it before we kill them all and escape from this Light-forsaken island.", ["objectivesText"] = "Speak with the Captured Zandalari Troll to find out how the Alliance fleet was sunk. Progress: <Thom sneers at the Zandalari troll kneeling before him.> Talk, you filthy brute!", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136195, ["x"] = 0.772, ["y"] = 0.555 }, { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 13, ["flags"] = 0 } } },
[51203] = { ["id"] = 51203, ["name"] = "Cry Wolf", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "Lately, the wolves have been terrorizing my flock. They weren't an issue until the giants moved in and pushed them out of their normal hunting grounds. I feel bad asking you to do this, but could you thin their ranks a bit? If there are fewer wolves competing for food, maybe they'll leave us alone.", ["objectivesText"] = "Kill 10 Feral Razorclaws .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136414, ["x"] = 0.318, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136414, ["x"] = 0.318, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 7, ["flags"] = 0 } } },
[51204] = { ["id"] = 51204, ["name"] = "WANTED: Razorclaw Alpha", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51204 }, ["description"] = "Adventurers Needed! The wolves have been attacking my flock! I don't have the means to fight them back. I've seen one, much larger than the rest, leading a few of the attacks. Please, if anyone can help, I'll gladly offer whatever reward I can muster. - Shepherd Mary Ann Milbrooke", ["objectivesText"] = "Slay the Razorclaw Alpha .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136414, ["x"] = 0.318, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.318, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "group" },
[51205] = { ["id"] = 51205, ["name"] = "Aww, Rats!", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "I didn't sign up for this! I just want to get back to the simple things, like grinding wheat and drinking mead. As if things couldn't get any worse around here, there's an army of rats ransacking the shed and I don't have the stomach to exterminate them. Here, I got this off some crazy gnome that stopped into port recently. I thought maybe it'd help with the bees. Maybe you can try it on the rats?", ["objectivesText"] = "Collect 8 Bilge Rats .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 159882 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.333, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51207] = { ["id"] = 51207, ["name"] = "Ettin It Done", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "Okay, now here's a little something I whipped up for you with those extra ingredients. We don't have much around here in the way of weapons, but we've got gunpowder and plenty of flour. A surprisingly explosive combination! Toss one of these goodies at those nasty ettins, should disorient them long enough to give 'em a good whack upside the head! You thought I was just a sweet old lady, baking delicious cookies for any ol' passerby? Hah, I'll have you know I was quite the firecracker in my day.", ["objectivesText"] = "Use Flour Bombs to slay 8 Ettins.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160052, 160063, 160333, 160336, 160339, 160342, 160383, 160386, 160389, 160392 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 9, ["flags"] = 0 } } },
[51208] = { ["id"] = 51208, ["name"] = "Wheat A Minute", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "With the storage shed ransacked by rats and the giants pillaging our shipments, we've been running low on food. When I was making my way out here, I saw a bunch of grain sacks littered about, near the wrecked wagons. I'd appreciate it if you could retrieve whatever you find while you're out here.", ["objectivesText"] = "Collect 10 Grain Sacks .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.333, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 10, ["flags"] = 0 } } },
[51209] = { ["id"] = 51209, ["name"] = "Mighty Grokkfist", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "Grandma is always telling me I need to toughen up a little... how easy we've got it these days. I read a story about giants that are terrified of rats, so I thought, \"Hey Charles, here's a great idea, let's take all those rats $p gathered and let 'em loose on the ettins.\" I tried to be tough for once, but look how it turned out. Now, I'm stuck out here, just hoping I don't get squashed. Their leader is just up the hill there. Here, take the rats with you and let's hope I was right!", ["objectivesText"] = "Use the Pack of Rats to kill Grokkfist .", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 160063 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.333, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 11, ["flags"] = 0 } } },
[51211] = { ["id"] = 51211, ["name"] = "The Heart of Azeroth", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 81, ["storyline"] = { 51211, 52428 }, ["description"] = "Our world's dyin', <name>. Sargeras's sword has cut deep. Her pain is drivin' the elements into a frenzy! I can hear Azeroth's voice, but she needs more than her speaker. She needs her champion. Far below us lies an ancient titan vault called the Chamber of Heart. I sense she wishes tae speak tae ye there. Come with me into the chamber. It may be our only chance tae save her!", ["objectivesText"] = "Travel to the Chamber of Heart and commune with Azeroth. Progress: Ye need tae hear from Azeroth herself, <name>.", ["rewardGold"] = 25740, ["rewardXP"] = 685, ["rewardItems"] = { 33226, 158075, 158937, 159671, 160251, 160326, 163127, 163128 }, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 }, { ["mapID"] = 862, ["npcID"] = 137323, ["x"] = 0.576, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 81, 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 743, ["questLineOrder"] = 1 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 785, ["questLineOrder"] = 1 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5379, ["questLineOrder"] = 1 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5379, ["questLineOrder"] = 1 } }, ["db2DetailThemeID"] = 14, ["db2PoiMapID"] = 1929, ["db2PoiUiMapID"] = 1021, ["questLines"] = { { ["id"] = 743, ["name"] = "The Heart of Azeroth", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 785, ["name"] = "The Heart of Azeroth", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5379, ["name"] = "The Heart of Azeroth", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51214] = { ["id"] = 51214, ["name"] = "Be A Dear", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "As you can plainly see by the rocks falling from the sky, we are under siege by those terrible ettins! If you could be obliged to lend us a hand, I'd be most grateful. We can't possibly hope to defeat them unless we properly prepare you first. Could you be a dear and fetch a few things for me from around the Hamlet? Some water, a sack of flour , and a bundle of logs should help. I've already sent my grandson, Charles, off to fetch a few other items. I've not seen him for quite a while though.", ["objectivesText"] = "Collect a Water Bucket , Sack of Flour , and Logs , then return them to Marie Davenport . Progress: Did you have any trouble dear?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 59073, 59074, 59075, 131437 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51215] = { ["id"] = 51215, ["name"] = "Milking Goats", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "Unfortunately, Milbrooke's flock hasn't been producing lately. What with all the wolves about, the poor things must be terrified. Wild goats wander the hills, and they are quite fearless compared to the sheep. If you can find a few with young ones about, you may be able to persuade them to offer some fresh, delicious goat milk!", ["objectivesText"] = "Collect 6 Mountain Goat Milk . Progress: Were you able to collect enough milk?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 159781, 159782 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 4, ["flags"] = 0 } } },
[51217] = { ["id"] = 51217, ["name"] = "WANTED: Yarsel'ghun", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51217 }, ["description"] = "By the decree of the Storm's Wake. Find and kill the foreign spy, Yarsel'ghun . A foreigner agent hiding on our soil, she is responsible for acts of terrorism against the citizens of Stormsong. The individual that ends her existence will earn a fitting reward.", ["objectivesText"] = "Find and kill Yarsel'ghun . Progress: The wanted poster is nailed to the wall, with tasks etched on it.", ["rewardGold"] = 929400, ["rewardXP"] = 6175, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135874, ["x"] = 0.578, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "group" },
[51218] = { ["id"] = 51218, ["name"] = "Undelivered Package", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51218 }, ["description"] = "< The ransacked cart has obviously seen better days. A single package remains, obscured by the spilled grain. It's addressed to Marie Davenport of Millstone Hamlet. >", ["objectivesText"] = "Deliver the package to Marie Davenport .", ["rewardGold"] = 154900, ["rewardXP"] = 2060, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51220] = { ["id"] = 51220, ["name"] = "Deep Sea Venture", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51220 }, ["description"] = "As mighty as Ai'twen is, this Venture Company is still a threat to him. I need you to watch over Ai'twen and Toki as you continue your great adventure. Eliminate the Venture Company Seawrenches that lurk the waters you travel to.", ["objectivesText"] = "Eliminate 6 Seawrenches Progress: Hurry to it, Ai'twen's saftey is important.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 }, { ["mapID"] = 942, ["npcID"] = 137554, ["x"] = 0.344, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51221] = { ["id"] = 51221, ["name"] = "Response Required", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51221 }, ["description"] = "Time is short and more creatures will die without your help. The Venture Company prepares a huge digging machine to tear the reef apart and destroy this cave. They've assigned a special operative to be sure the job is done right. You must act now, $p. Take out the operative in charge of the camp; this should buy us some time.", ["objectivesText"] = "Eliminate Lithia Costcutter", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51222] = { ["id"] = 51222, ["name"] = "What's Yours is Mined", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51222 }, ["description"] = "During a visit to Pandaria, I witnessed the citizens of Halfhill defeat attacking hozen by flinging the hozen's excrement back at them. The hozen were unprepared to face the wrath of their own weaponry used against them. A similar strategy can be applied here. We will gather Venture Co. Sea Mines and use them against the invaders. You hook ropes to each mine, and Ai'twen and I will haul them up.", ["objectivesText"] = "Collect 10 Sea Mines", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 80783, 80784, 80785, 80786, 80787, 160429 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137554, ["x"] = 0.344, ["y"] = 0.262 }, { ["mapID"] = 942, ["npcID"] = 137677, ["x"] = 0.356, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137554, ["x"] = 0.344, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51223] = { ["id"] = 51223, ["name"] = "Walking on Broken Glass", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51223 }, ["objectivesText"] = "Sea Glass collected", ["rewardItems"] = { 159790 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Sea Glass collected", ["amount"] = 30, ["type"] = 1, ["objectID"] = 159790, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[51224] = { ["id"] = 51224, ["name"] = "Profit and Reconnaissance", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51985, 51987 }, ["series"] = { 51332, 51340 }, ["description"] = "This was supposed to be a covert operation. Unfortunately, our Trade Prince insisted on coming along... with the loudest, most conspicuous vehicle the Horde has ever conceived. At least you're here with me, <name>. Let's get going, then. We know next to nothing about the Drustvar territory. It's time to do some recon.", ["objectivesText"] = "Escort Gallywix and Eitrigg on Gallywix's War Trike. If you become separated from Gallywix and Eitrigg , you can find them at Anyport. Progress: Let's get this over with.", ["rewardGold"] = 514800, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 136725, ["x"] = 0.306, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136725, ["x"] = 0.306, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 604, ["questLineOrder"] = 5 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 604, ["name"] = "Drustvar Foothold", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 22, ["flags"] = 0 } } },
[51226] = { ["id"] = 51226, ["name"] = "Death from Two Sides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49716, 49720, 49733, 49734, 50249, 51226 }, ["description"] = "The overgrown lizards from down on the beach decided to swarm the camp suddenly. We're used to dealing with one or two each week, but it seems like the whole brood came up the cliff. Wonder if the smell of blood drew them in. They're putting our remaining men at risk, wipe them out!", ["objectivesText"] = "Kill 8 Brinefang Saurolisk . Progress: Have you thinned out those saurolisks yet?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 132720, ["x"] = 0.806, ["y"] = 0.42 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 132720, ["x"] = 0.806, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.806, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5431, ["name"] = "Greystone Keep", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51228] = { ["id"] = 51228, ["name"] = "Instant Meat, Ready to Eat", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51228 }, ["rewardItems"] = { 159794, 159795, 159796 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "world", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[51229] = { ["id"] = 51229, ["name"] = "Establish a Beachhead", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51170, 51283 }, ["description"] = "I won't allow Private Leonard's sacrifice to be in vain. Let's get our men out here and fortify this place up before those... \"sethrak\" decide to come back. Here, plant this banner somewhere visible so the ship knows its safe. That platform over next to the dock should do the trick.", ["objectivesText"] = "Plant the Alliance banner and establish your base in Vol'dun.", ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137008, ["x"] = 0.395, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137213, ["x"] = 0.378, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 23, ["flags"] = 0 } } },
[51230] = { ["id"] = 51230, ["name"] = "Emergency Transplants", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51230, 51243 }, ["description"] = "Riverbud is a precious resource for us. Not only does it have potent magical properties, but it also feeds many of de beasts we train or eat ourselves. However, de Blood Trolls have been dumping a lot of cursed blood in de rivers. It may not be their goal, but if we do not act soon, de pollution may wipe out all de riverbud. I need you to take dis handful of seeds, and plant dem in de rivermud. In exchange, I will teach you how to harvest it more effectively.", ["objectivesText"] = "Plant 10 Riverbud Seeds in rivermud.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 757, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Riverbud - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51231] = { ["id"] = 51231, ["name"] = "Wiccaphobia", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51985, 51987 }, ["description"] = "Do you see that... that shape up in the brambles up ahead? Is that... < Eitrigg shudders.> Is that goblin... wrapped up in that tree?", ["objectivesText"] = "Investigate the shape up ahead, then protect Eitrigg and Gallywix. Progress: Huh?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 136725, ["x"] = 0.306, ["y"] = 0.45 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136725, ["x"] = 0.306, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.45 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 604, ["questLineOrder"] = 5 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 604, ["name"] = "Drustvar Foothold", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 23, ["flags"] = 0 } } },
[51233] = { ["id"] = 51233, ["name"] = "I Hope There's No Witches in the Mountains", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51985, 51987 }, ["description"] = "<Gallywix looks flustered after his ordeal with the crone.> You know, ah... I think maybe we better set up our foothold somewhere else. Maybe, up in the mountains? You know, like... not here, where the witches are?", ["objectivesText"] = "Drive Eitrigg and Gallywix to the mountains. Progress: Yes, <name>?", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136725, ["x"] = 0.306, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 604, ["questLineOrder"] = 5 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 604, ["name"] = "Drustvar Foothold", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 24, ["flags"] = 0 } } },
[51234] = { ["id"] = 51234, ["name"] = "Krazzlefrazz Outpost", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51985, 51987 }, ["description"] = "I already did a bunch of the leg-work for settin' up our foothold. All we gotta do is finish deploying all the instant-base technology, and we'll be good to go here in Drustvar. Why don't you go finish the base building. I'm gonna see if I can salvage any wolfercycle parts.", ["objectivesText"] = "Use the goblin devices in Krazzlefrazz Outpost to build your foothold in Drustvar. Progress: What?", ["rewardGold"] = 772200, ["rewardXP"] = 7185, ["rewardItems"] = { 118411 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 137613, ["x"] = 0.346667, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.346667, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 862, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 604, ["questLineOrder"] = 5 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 604, ["name"] = "Drustvar Foothold", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 25, ["flags"] = 0 } } },
[51240] = { ["id"] = 51240, ["name"] = "WANTED: Anchorface", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51240 }, ["description"] = "Kill the blasted shark that ate me legs! And me crew! And me boat - even the anchor! He's been swimming around in the sea, looking for his next meal. Kill 'im. I've left a reward with Cesi Loosecannon if you do. <The poster is signed 'Captain Slagbolt'>", ["objectivesText"] = "Slay Anchorface in the waters near Anyport. Progress: Oh, did you kill that shark that almost got Ole Slaggy?", ["rewardGold"] = 929400, ["rewardXP"] = 4150, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136579, ["x"] = 0.192, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.192, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group", ["db2VignetteID"] = 2937, ["db2VignetteName"] = "Anchorface" },
[51243] = { ["id"] = 51243, ["name"] = "Breaking The Food Chain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51230, 51243 }, ["description"] = "De extra riverbud you planted has helped, but it has not been enough. Some of de local beasts are consuming de riverbud before dey can mature. We need dese plants to germinate, or we could risk losing it entirely. The largest group of young riverbud consumers are de jacunda. If we are going to give de riverbud a chance to survive dis, you will need to thin their numbers. Do dat and I will teach you everything I know about riverbud.", ["objectivesText"] = "Kill 12 Ravenous Jacunda .", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 757, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Riverbud - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51246] = { ["id"] = 51246, ["name"] = "The Wreckoning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51246 }, ["series"] = { 51555 }, ["description"] = "I can't believe any of them survived the wreck. We were told to prevent any survivors from gaining a foothold. There are far more of them than expected. We need to weaken their forces. Well? What are you waiting for? An engraved invitation?", ["objectivesText"] = "Kill 10 Shipwrecked 7th Legion.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 137075, ["x"] = 0.766, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 137075, ["x"] = 0.766, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[51247] = { ["id"] = 51247, ["name"] = "The Things They Carried", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51247 }, ["description"] = "We need to know more about these sailors before we report back. Ideally, we would invade their camp but there are too many for our small group to take on. Lucky for us, they are focused on their salvage operation over safety. See if you can find any intelligence on their leaders who are scavenging the derelicts.", ["objectivesText"] = "Acquire intelligence from the Alliance. Progress: What have you found?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 159835, 159836, 159837 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 137075, ["x"] = 0.766, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 137075, ["x"] = 0.766, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[51248] = { ["id"] = 51248, ["name"] = "Productive Pests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51248 }, ["description"] = "This jungle is a whole new habitat for creatures and critters. A shame we're here to deal with Alliance driftwood. I've got an idea and I think it's genius. Two words: Poison bugs. First, I need some bugs. Crawling and flying ones, just to be thorough for our test.", ["objectivesText"] = "Gather 5 bugs", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135855, ["x"] = 0.764, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135855, ["x"] = 0.764, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[51249] = { ["id"] = 51249, ["name"] = "Crabulous Feast", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51249 }, ["description"] = "The Forsaken didn't bring any food with them. I think they might be cannibals. At the very least, they don't need to eat! Teekay and I are going to starve out here! <name>, if you're not too busy, could you bring us something to eat? Maybe some fresh crab?", ["objectivesText"] = "Gather 7 lumps of crab meat from the Derelict Hexopods. Progress: My stomach is rumbling already.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 159934 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135803, ["x"] = 0.764, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135803, ["x"] = 0.764, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[51250] = { ["id"] = 51250, ["name"] = "Buzz Off!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51250 }, ["objectivesText"] = "Bonepicker Summit cleared", ["rewardGold"] = 105000, ["rewardXP"] = 925, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Bonepicker Summit cleared", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[51251] = { ["id"] = 51251, ["name"] = "Basement Dwellers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "Ever since the untimely passing of dear, sweet Lizzie, rest her soul, the pests have multiplied like crazy! In recent days, giant spiders have begun crawling out of the cellar underneath the southern mill. No one has been able to go down there, for fear of being wrapped in web and eaten alive! Would you mind squashing a few arachnids and collecting any silk you find?", ["objectivesText"] = "Collect 8 Spider Silk from the Cellar Crawlers. Progress: If only Lizzie were still here...", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 159839 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.333, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51279] = { ["id"] = 51279, ["name"] = "Nazmani Cultists", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51177, 51280, 51281, 51282 }, ["description"] = "The rumors o' the blood trolls from back in Boralus don't line up with the letters from Captain Conrad. Open to trade? Willin' to work with us against the Horde? Ready to teach us their magic? Hogwash. Only time worth spendin' with these evil trolls is time killin' 'em.", ["objectivesText"] = "Kill 15 Nazmani trolls in Koramar. Progress: That chantin' noise won't leave my head, draenei.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136675, ["x"] = 0.467, ["y"] = 0.5635 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136675, ["x"] = 0.467, ["y"] = 0.5635 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.467, ["y"] = 0.5635 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 46, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 46, ["flags"] = 0 } } },
[51280] = { ["id"] = 51280, ["name"] = "Offerings to G'huun", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51177, 51279, 51281, 51282 }, ["description"] = "Been watchin' these cultists with both good eyes. Those big glowin' jars o' theirs look important. Opened one up and it sent a shiver down me spine, but nothin' seemed worth the takin'. If it ain't worth stealin', I guess it's worth smashin'.", ["objectivesText"] = "Destroy 8 Offerings to G'huun in Zul'Nazman.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136675, ["x"] = 0.467, ["y"] = 0.5635 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136675, ["x"] = 0.467, ["y"] = 0.5635 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.467, ["y"] = 0.5635 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 47, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 47, ["flags"] = 0 } } },
[51281] = { ["id"] = 51281, ["name"] = "Zul'Nazman", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51177, 51279, 51280, 51282 }, ["description"] = "Not sure if I like this Harry fella. He's growin' on me, though. Got some wild ideas about the blood elves, but he's not all bad. What were we talkin' about? Ah, right. Captain Conrad. He said the Captain went to Zul'Nazman ta commune with the blood trolls there. Seems... less than well planned. Let's go see what there is to see, shall we?", ["objectivesText"] = "Meet Brann Bronzebeard at Zul'Nazman in Nazmir.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136432, ["x"] = 0.62, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136675, ["x"] = 0.467, ["y"] = 0.5635 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 45, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 48, ["flags"] = 0 } } },
[51282] = { ["id"] = 51282, ["name"] = "Captain Conrad", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51177, 51279, 51280, 51281 }, ["description"] = "Looks like there's couple o' guards posted by this hut. If I had ta guess, Captain Conrad 'll be in there. Somethin' still feels off about this place, though. Why don't ya go on ahead and I'll hang here in case things go south fast? I got yer back, <name>.", ["objectivesText"] = "Meet with Captain Conrad at Tul'vor in Nazmir.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 136675, ["x"] = 0.467, ["y"] = 0.5635 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 136568, ["x"] = 0.4528, ["y"] = 0.5864 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.467, ["y"] = 0.5635 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 48, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 49, ["flags"] = 0 } } },
[51283] = { ["id"] = 51283, ["name"] = "Voyage to the West", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51170, 51229 }, ["description"] = "Reconnaissance reports that the Horde has made inroads into the desert of Vol'dun. We can't allow the Horde to continue to work there unchecked, so we're preparing an expedition to establish a beachhead. <name>, as one of our most accomplished soldiers I'd appreciate if you joined us. Your help will be essential for the success of our mission. Wrap up your affairs here in the harbor and report to Grand Admiral Jes-Tereth. We will set sail when you're ready.", ["objectivesText"] = "Speak with Grand Admiral Jes-Tereth and travel to Vol'dun.", ["rewardGold"] = 30900, ["rewardXP"] = 600, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137867, ["x"] = 0.328, ["y"] = 0.348 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 864, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] =