[51286] = { ["id"] = 51286, ["name"] = "Stop the Evacuation", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51286 }, ["description"] = "This is a complete disaster. The intelligence you gathered seems to indicate that they already have footholds on this island and this is just another one. They have a boat and we need to stall them. Here's some seaforium. Plant it on their boat and sabotage their hopes of escape. If possible, take out their Captain leading the evacuation.", ["objectivesText"] = "Stop the Alliance evacuation efforts. Progress: I hope you have good news for me. For once.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 137075, ["x"] = 0.766, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 137075, ["x"] = 0.766, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
