[51302] = { ["id"] = 51302, ["name"] = "The Underrot: Sealing G'huun's Corruption", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 50808, 51244, 51302 }, ["description"] = "Massive leak of G'huun corruption located nearby. Substance surrounding us indicator of G'huun corruption, named underrot. Initial scans suggest a massive abomination composed of underrot is ahead, releasing more corruption into Nazmir. Must destroy Unbound Abomination , contain G'huun's corruption. Function clear. Proceed inside.", ["objectivesText"] = "Enter the Underrot and defeat the Unbound Abomination .", ["rewardGold"] = 1239200, ["rewardXP"] = 5530, ["rewardItems"] = { 159827 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 137112, ["x"] = 0.518, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 141539, ["x"] = 0.392, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 630, ["name"] = "The Altar of Rot", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51308] = { ["id"] = 51308, ["name"] = "Zuldazar Foothold", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51201 }, ["description"] = "King Wrynn passed along orders to dispatch our finest to establish a foothold in Zandalar. That means you. Fortunately, we have a few choices as to where we can set up camp. Stick around. I'll go over the battle plan.", ["objectivesText"] = "Listen to Commander Wyrmbane's battle plan, then speak with Grand Admiral Jes-Tereth to travel to Talanji's Rebuke in Zuldazar.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 }, { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 14, ["flags"] = 0 } } },
[51309] = { ["id"] = 51309, ["name"] = "Rocks of Ragnaros", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "With me shaman still in their conveyances, a vital component o' our upcomin' ritual remains scattered among the supplies. I can only hope the Horde haven't taken 'em. They're rare an' precious... If you see any glowin' objects out there, recover 'em. They're o' tremendous value.", ["objectivesText"] = "Recover 9 Firelands Slag from the beach in Xibala. Progress: I wasn't worried about 'em bein' broken. A little fire'd never hurt those rocks.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 15, ["flags"] = 0 } } },
[51310] = { ["id"] = 51310, ["name"] = "Raiders of the Lost Crop", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51310 }, ["description"] = "I could use a hand here! So there I was, mindin' my own business and collectin' my harvest when these big galoots show up on their wolves and start torching the town! Luckily I was delivering a sack o' grain, or they'd have caught me and run me down! I won't stand for having these orcs or their dogs chewing up my fields or my crop. What do you say, friend? Help a farmer run some looters off his land?", ["objectivesText"] = "Slay 6 Orc Raiders .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137094, ["x"] = 0.55, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137094, ["x"] = 0.55, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51311] = { ["id"] = 51311, ["name"] = "Energizing Extract", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51311 }, ["rewardItems"] = { 152849 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[51312] = { ["id"] = 51312, ["name"] = "Aromatic Pollenator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48755, 48758, 51312, 51313 }, ["series"] = { 51313 }, ["description"] = "While gathering the pollen, you found a dead bug absolutely covered in pollen. You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp. Maybe if you ask Declan about it, he might have an idea.", ["objectivesText"] = "Bring the Dead Pollen-Covered Bee to Declan Senal . Provided item:", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 754, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Siren's Pollen - SCS", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 159877 } },
[51313] = { ["id"] = 51313, ["name"] = "Learn From the Best", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48755, 48758, 51312, 51313 }, ["series"] = { 51312 }, ["description"] = "You want to learn how these bees are so good at harvesting pollen, but if you show up, they'll start swarming you. What you've got is a problem that can be solved with a little alchemy. I just so happen to have this potion that, once drunk, will turn the imbiber into a plant. Here's the deal: you go out and drink the potion, and you'll see firsthand how the bees do what they do. After the potion wears off, you tell me what happened. Oh, and don't ask why I have that potion on me.", ["objectivesText"] = "Drink Declan's potion and allow bees to harvest your pollen.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159881, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 754, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Siren's Pollen - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51314] = { ["id"] = 51314, ["name"] = "Grain Drain", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51314 }, ["description"] = "We've got to salvage what we can. This valley is the breadbasket of Kul Tiras. We feed the citizens, the militia, the army, you name it! Perhaps you've heard of our famous Kul Tiran sourdough bread? Goes great with sausages. More importantly, those blasted Horde are getting in the way of our harvest! Lucky for us, the golems work 'round the clock to package the grain. I just need you to go out to the fields and grab as many bags as you can carry. I'll pay you for your trouble, of course.", ["objectivesText"] = "Collect 8 Sacks of Grain . Progress: We need that grain!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 155878 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137094, ["x"] = 0.55, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137094, ["x"] = 0.55, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
