[51331] = { ["id"] = 51331, ["name"] = "Mole Machinations", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51359 }, ["description"] = "Seems the enemy's anticipated our moves. While we developed our refinin' techniques for Azerite, the goblins 'ave done the same. It wasn't five minutes after we established ourselves here that the Horde arrived to disrupt our progress. We've got several shaman of great import waitin' impatiently in the mole machines on that beach. You can take the key and clear the way so they arrive safely.", ["objectivesText"] = "Free 4 Dark Iron Earthbreakers from mole machines in Xibala. Progress: Ain't my fault those lads seem to hate small spaces.", ["rewardGold"] = 12300, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 16, ["flags"] = 0 } } },
[51332] = { ["id"] = 51332, ["name"] = "A Trip Across the Ocean", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51985, 51987 }, ["series"] = { 51224, 51340 }, ["description"] = "I understand you are to be establishing our foothold in Drustvar. You will be assisted on this mission by Trade Prince Gallywix . I know, a strange choice, but I am told that there is Azerite in Drustvar, and the Trade Prince was insistent.", ["objectivesText"] = "Report to Trade Prince Gallywix in Zuldazar.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 604, ["questLineOrder"] = 5 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 604, ["name"] = "Drustvar Foothold", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 20, ["flags"] = 0 } } },
[51339] = { ["id"] = 51339, ["name"] = "Cleaning Bills", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51339 }, ["description"] = "The Venture Company contaminates our pristine waters with toxic oil. My people are strong and will endure this until the time is right to strike back. The creatures with soft skins cannot wait. We must act now and save them from this danger. Collect and scrub clean any oily sandbill pipers you see. Quickly, before it's too late!", ["objectivesText"] = "Clean 8 Oily Sandbill Pipers", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 63688, 155237, 160384, 160387, 160390, 160393 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135794, ["x"] = 0.405333, ["y"] = 0.426667 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135794, ["x"] = 0.405333, ["y"] = 0.426667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.426667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51340] = { ["id"] = 51340, ["name"] = "Drustvar Ho!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51985, 51987 }, ["series"] = { 51224, 51332 }, ["description"] = "Azerite's in the air, <name>. Can ya smell it? Drustvar--way over in Kul Tiras--apparently has a real big seam o' Azerite beneath it. Azerite means profit, and profit means winning this war against the Alliance... which means even more profit. We gotta get that Azerite! Check in with Eitrigg an' Tattersail so we can get going soon. Time is money!", ["objectivesText"] = "Speak with Eitrigg and Dread-Admiral Tattersail.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 33226 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136725, ["x"] = 0.306, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 604, ["questLineOrder"] = 5 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 604, ["name"] = "Drustvar Foothold", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 21, ["flags"] = 0 } } },
[51341] = { ["id"] = 51341, ["name"] = "Daughter of the Sea", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47186, 47189, 51341 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 57766, 58983, 59641, 60362 }, ["description"] = "They're not letting us any closer to the keep. We'll have to walk from here. Returning to Boralus has stirred feelings I thought I'd left behind. Memories smoothed away by the years like stones in the tide. It all feels raw again. I do not know how this will end--only that we must try.", ["objectivesText"] = "Accompany Jaina Proudmoore to an audience with Katherine Proudmoore.", ["rewardGold"] = 210675, ["rewardXP"] = 1060, ["rewardItems"] = { 158075, 160326 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 120922, ["x"] = 0.655, ["y"] = 0.507 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.507 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 589, ["questLineOrder"] = 2 }, { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1169, ["questLines"] = { { ["id"] = 589, ["name"] = "A Nation Divided", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51342] = { ["id"] = 51342, ["name"] = "Battle for Stromgarde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 51342 }, ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 163578, 163579, 163644, 163645, 163646, 163648, 163650, 163652, 163677, 163684, 163689, 163690, 163691, 163698, 163700, 163701, 163706, 163711, 163712, 163713, 163735, 163736, 163738, 163741, 163744, 163745, 163750, 163775, 163828, 163829, 164577, 164578, 169196, 169197 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[51343] = { ["id"] = 51343, ["name"] = "Swimming Lessons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51343 }, ["description"] = "For millennia we have roamed Azeroth's depths, yet never has a land walker journeyed with us. In order to help us, you must learn to travel the waters as we do. The three scrolls of the sea shall grant you the energies to travel and survive underwater as we do. Bring me the Scrolls of Harmonious Fins, Endless Tides and Graceful Breaths.", ["objectivesText"] = "Collect the three scrolls. Progress: You must collect the Scroll of Harmonious Fins , Endless Tides and Graceful Breaths.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 160270, 160327, 160329 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135794, ["x"] = 0.405333, ["y"] = 0.426667 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135794, ["x"] = 0.405333, ["y"] = 0.426667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.426667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51344] = { ["id"] = 51344, ["name"] = "To Matters at Hand", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["storyline"] = { 51344 }, ["description"] = "Ye need te get back te Zuldazar, Princess Talanji 's people are in desperate need of help. Now that ye got the heart, ye can absorb Azerite from all kinds of sources. Use the teleporter pad behind ye te return te Zuldazar. I be disablin' it when yer done... no need te have the likes of Nathanos walkin' in here. Just remember. Ye got the Heart of Azeroth around yer neck. Whatever happens... we must save the planet.", ["objectivesText"] = "Use the Teleport Pad to return to Zuldazar", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 159671 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[51349] = { ["id"] = 51349, ["name"] = "Honor Bound", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51350, 51351, 51366 }, ["description"] = "Sergeant Ermey is a man of honor, he would never leave one of his men behind. But one of these days that sentiment is going to get himself killed. We don't even know what threats we face in this land. We certainly don't have the resources to spend searching for a missing private. I want you to go after him. Do whatever it takes to give up this fool's errand and return to the camp. He was last seen headed to the south-east, I'd start your search there.", ["objectivesText"] = "Find Sergeant Ermey in Vol'dun.", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137213, ["x"] = 0.378, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137337, ["x"] = 0.39, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 26, ["flags"] = 0 } } },
[51350] = { ["id"] = 51350, ["name"] = "Unexpected Aid", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51349, 51351, 51366 }, ["description"] = "I was shadowing those sethrak when I saw this one left for dead beside the trail. I don't think he's like the others. Looks like they roughed him up pretty bad. I made contact and before he passed out he said he knew where our man was being taken! We need to find out what this thing knows! I'll need to make a salve for these wounds. There's some cactus I saw growing around here that should make a good base for it.", ["objectivesText"] = "Harvest 8 Prickly Pear Roots in Bonetrail Gulch. Progress: Got the cactus for the salve?", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137337, ["x"] = 0.39, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137337, ["x"] = 0.39, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 27, ["flags"] = 0 } } },
[51351] = { ["id"] = 51351, ["name"] = "Poisoned Barbs", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51349, 51350, 51366 }, ["description"] = "I'm surprised this snake-man is alive, let alone able to speak. Look at this! <Ermey holds up a needle-like barb.> It looks like it came from one of those giant insects wandering about in the bottom of the gulch. I'll bet my stripes it's poisoned. You know what they say, that which kills can also cure. Go get a few more of these barbs. I bet if I mix it in with that cactus he's wanting we will get a good antivenom to treat his wounds.", ["objectivesText"] = "Collect 8 Saltspine Barbs in Bonetrail Gulch. Progress: Got those barbs for me?", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137337, ["x"] = 0.39, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137337, ["x"] = 0.39, ["y"] = 0.428 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 28, ["flags"] = 0 } } },
[51352] = { ["id"] = 51352, ["name"] = "Don't Play with Matches", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51352 }, ["description"] = "These Venture Co. thugs set flame to the very oils they harvest. They hope to drive us from this land. Their plan has a flaw. If a great wave extinguished every torch, their oil could not be lit. You can be our great wave! Extinguish all the flames here, and we shall be victorious this day.", ["objectivesText"] = "Eliminate 10 Venture Co. Flame Starters and 2 Venture Co. Oilers . Progress: Get to work, the battle is not won yet!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135795, ["x"] = 0.4045, ["y"] = 0.435 }, { ["mapID"] = 942, ["npcID"] = 137554, ["x"] = 0.344, ["y"] = 0.262 }, { ["mapID"] = 942, ["npcID"] = 137677, ["x"] = 0.356, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135795, ["x"] = 0.4045, ["y"] = 0.435 }, { ["mapID"] = 942, ["npcID"] = 137554, ["x"] = 0.344, ["y"] = 0.262 }, { ["mapID"] = 942, ["npcID"] = 137677, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.4045, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51353] = { ["id"] = 51353, ["name"] = "Cave of Ai'twen", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51353 }, ["description"] = "Toki has researched a strategy that is historically sound. However to defeat the Venture Company, we will have to awaken Ai'twen from the bubble of tranquil waters. Seek out Loroja in the Cave of Ai'twen and we shall begin the process.", ["objectivesText"] = "Seek out Loroja in the Cave of Ai'twen.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135794, ["x"] = 0.405333, ["y"] = 0.426667 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.405333, ["y"] = 0.426667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51354] = { ["id"] = 51354, ["name"] = "Anger in a Bottle", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9562, ["mapID"] = 942, ["storyline"] = { 50353, 50354, 50363, 50365, 50368, 50622, 50640, 51354 }, ["description"] = "These quilboar are tougher than normal and I think I found out why. They carry vials of some sort, filled with this nasty orange liquid. They'll quaff it and gain tremendous strength and stamina. I'll bet if we get some of it Hobbs could whip up a counter-agent, or whatever it is that alchemists do. Either way, deprive them of their strength potions and it'll make getting around here easier!", ["objectivesText"] = "Collect 10 Foul-Smelling Samples . Progress: Do you have the samples yet?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 157850 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133953, ["x"] = 0.487, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.487, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9562 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 583, ["name"] = "Storming the Kraul", ["orderIndex"] = 5, ["flags"] = 0 } } },
[51356] = { ["id"] = 51356, ["name"] = "WANTED: Sister Lilias", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51356 }, ["description"] = "The Waycrest Guard seeks an able-bodied soldier to eliminate a threat in Corlain. A witch by the name of Sister Lilias is wanted for the torture and killing of many of our townsfolk. Her end would prove a boon to all of Drustvar . Present her head to claim your reward.", ["objectivesText"] = "Collect Sister Lilias' head from Sister Lilias in Corlain. Progress: Inquisitor?", ["rewardGold"] = 929400, ["rewardXP"] = 4150, ["rewardItems"] = { 156926, 160026 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 137368, ["x"] = 0.315, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[51357] = { ["id"] = 51357, ["name"] = "Armed and Ready", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "You must be special if the sethrak didn't kill you right away. Either that, or you'd fetch a good price at the slave market. Don't worry though. We're getting out of here. I have a wagon at the entrance, but no weapon to fight with. Luckily, it seems the sethrak have plenty.", ["objectivesText"] = "Choose a weapon for Nisha . Progress: I'm good with whatever you pick, but let's hurry.", ["rewardGold"] = 315900, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 130455, ["x"] = 0.66, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 130455, ["x"] = 0.66, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 4, ["flags"] = 0 } } },
[51358] = { ["id"] = 51358, ["name"] = "WANTED: Gryphon 'Nappers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51358 }, ["description"] = "A warning to all gryphon owners! Do not let your feathered companions out of your sight. We have received numerous reports about gryphons in the area being stolen in the night. If anybody can track down and stop these thieves, a reward awaits!", ["objectivesText"] = "Kill Lindel the Snatcher and Silent Boris .", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 160452 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 133214, ["x"] = 0.662, ["y"] = 0.242 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.242 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[51359] = { ["id"] = 51359, ["name"] = "Fragment of the Firelands", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51331 }, ["description"] = "The rumors o' yer capabilities seemed overblown, but it appears yer indeed a competent one, aren't ye? I underestimated ye, <name>. For that, I apologize. Don't tell Thaelin. The components for the ritual are now prepared. All ye need to do is add the Firelands Slag to the Unstable Magma an' a great bein' from the Firelands will heed our call. You'll gain control o' it and can eliminate the nearby goblin threat with nigh invincibility.", ["objectivesText"] = "Stabilize the Unstable Magma then use the Magma Elemental to defeat 200 Bilgewater Goblins . Progress: Me shaman are gettin' better at this, aye? First couple o' summons and we had a hot fight on our hands.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160058, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 17, ["flags"] = 0 } } },
[51360] = { ["id"] = 51360, ["name"] = "Enormous Anchor Pod", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 51016, 51360, 51361 }, ["series"] = { 51361 }, ["description"] = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it. Your mind wanders back to Declan, and if there is anything about it in the book you picked up earlier.", ["objectivesText"] = "Bring the Enormous Anchor Pod to Declan Senal . Provided item:", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 750, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Anchor Weed  - SCS", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 160035 } },
[51361] = { ["id"] = 51361, ["name"] = "More Anchor Pods", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 51016, 51360, 51361 }, ["series"] = { 51360 }, ["description"] = "Everyone in Kul Tiras knows that anchor weed is a blight that was brought here by merchants. It thrives in this weather and it leechs nutrients from other plants, so we work to keep it from spreading, but it also has a strong magical essence, keeping us from just eradicating it. However, if it has mutated so it can disperse more seeds, we may need to finally purge it. Bring me the biggest seed pods you can find, we need to see if this is a unique case. I'll dissect this one and learn what I can.", ["objectivesText"] = "Harvest 9 Mature Anchor Pods from anchor weed. Progress: If the anchor weed is mutating, we may need to purge it from this land. Do you have the other seed pods for comparison?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160036, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 750, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Anchor Weed  - SCS", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51364] = { ["id"] = 51364, ["name"] = "An Explosive Exit", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "Alright, $p. I think it's time we make a run for it. Hopefully my wagon's still nearby. I'll steer us to our hideaway. I just need you to lob explosives onto any sethrak who are brave enough to follow us.", ["objectivesText"] = "Find Nisha's wagon and ride it to safety.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 155443, 161188, 161189, 161190, 161191, 161192, 161193, 161194, 161195 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 123586, ["x"] = 0.568, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 605, ["name"] = "Unlikely Allies", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 8, ["flags"] = 0 } } },
[51365] = { ["id"] = 51365, ["name"] = "Cultural Significance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 48769, 51365 }, ["description"] = "I've noticed your skill with harvesting plants has improved, but I also noticed that you just treat each flower and leaf as a commodity. The flora of these islands have a rich history, with a deep cultural significance to us. Take this sea stalk, go around town, and ask some of the men and women what it means to them. Humor me, and I'll make it worth your while.", ["objectivesText"] = "Learn the importance of sea stalks from people in Boralus.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 753, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Sea Stalk - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51366] = { ["id"] = 51366, ["name"] = "Antidote Application", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51349, 51350, 51351 }, ["description"] = "The antidote's ready. It smells like death and tastes worse, but it should be potent enough. Let's hope that we're not too late for it to do any good. Here, administer the salve to his wounds. It should work nearly instantly.", ["objectivesText"] = "Administer the Antivenom to Vorrik .", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137337, ["x"] = 0.39, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137434, ["x"] = 0.331, ["y"] = 0.484 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 29, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 29, ["flags"] = 0 } } },
[51367] = { ["id"] = 51367, ["name"] = "WANTED: Raging Earthguard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51367 }, ["description"] = "Be careful when traveling toward Anglepoint! An immense creature of the earth has spawned on one of the hills, threatening all who go near. Any adventurers who take down this earthen guardian shall be rewarded greatly.", ["objectivesText"] = "Kill the Raging Earthguard west of Norwington Estate.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 160452 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 124802, ["x"] = 0.515, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[51368] = { ["id"] = 51368, ["name"] = "WANTED: The Hornet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51368 }, ["description"] = "That's it, I'm putting a bounty on that blasted hornet. Every time I try to do some good old fashioned bare-handed fishing, that son of a bear comes after me. Somebody take that bug down!", ["objectivesText"] = "Kill The Hornet .", ["rewardGold"] = 36900, ["rewardXP"] = 2125, ["rewardItems"] = { 160452 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 129003, ["x"] = 0.424, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.424, ["y"] = 0.222 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[51369] = { ["id"] = 51369, ["name"] = "Friends in Strange Places", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "I saw a creature like your friend here. We both were being held captive by my ruthless kin, the Faithless. Before I was cast aside I gave him something to protect, something most precious. Naturally, I would also like to see your friend's safe return. My people will lend you their aid. Come, I will call for my pterrordax to take us. Together we shall find where your soldier friend was taken.", ["objectivesText"] = "Fly to the Sanctuary of the Devoted.", ["rewardGold"] = 128700, ["rewardXP"] = 2395, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137434, ["x"] = 0.331, ["y"] = 0.484 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137537, ["x"] = 0.272, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.331, ["y"] = 0.484 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"