[51371] = { ["id"] = 51371, ["name"] = "Flavorable Offering", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51371 }, ["description"] = "Ai'twen saved many Tortollans during the great purge of the Inky Grotto. He rests here in this tranquil bubble as a reward for his service. To entice him back to our world we'll need a flavorful offering. The seaweed that grows outside is Ai'twen's favorite meal. Its salty flavor will surely coax Ai'twen to leave the bubble for our world. Gather it from the creatures outside this cave, and where it grows wild on the reef.", ["objectivesText"] = "Gather 50 Seaweed . Progress: Search for the Seaweed outside and on Makrura Brineshells", ["rewardGold"] = 63800, ["rewardXP"] = 4115, ["rewardItems"] = { 160055 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51376] = { ["id"] = 51376, ["name"] = "Can't Teach on an Empty Stomach", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48762, 48763, 51376 }, ["series"] = { 48762, 51446 }, ["description"] = "I would love to teach you, but it's so hard for me to concentrate right now. I haven't eaten anything all day, so it's all I can think about. However, if a helpful adventurer were to fish up some lane snapper from the ocean just behind me, I would owe them a something in return. Perhaps something valuable, such as advice in regards to effectively picking the notorious winter's kiss. If you don't feel like fishing, you could just buy some on the auction house, I don't mind.", ["objectivesText"] = "Collect 7 Lane Snapper for Xun Xun Sweetflower . Lane Snapper can be fished from the ocean or purchased from the Auction House. Progress: Oh, do you have something for me?", ["rewardItems"] = { 6256, 152505, 152506, 152507, 152508, 152509, 152510, 152511, 152545, 152546, 154770, 154788, 154792, 154796, 154801, 156833, 159877, 159956, 160035, 160064, 160117, 160301, 160550, 160930, 168016 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 136141, ["x"] = 0.206, ["y"] = 0.456 }, { ["mapID"] = 896, ["npcID"] = 136269, ["x"] = 0.206, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136141, ["x"] = 0.206, ["y"] = 0.456 }, { ["mapID"] = 896, ["npcID"] = 136269, ["x"] = 0.206, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.206, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 756, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Winter's Kiss - SCS", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 761, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Winter's Kiss - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51379] = { ["id"] = 51379, ["name"] = "Temple of Sethraliss: Navigating Currents", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9527, ["mapID"] = 864, ["storyline"] = { 51379 }, ["objectivesText"] = "Wrest a Focus From a Faithless Sorcerer Gain 100 power from Flowing Current Restore the Avatar of Sethraliss", ["rewardItems"] = { 163681 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9527 } }, ["questType"] = "dungeon", ["db2Objectives"] = { { ["text"] = "Wrest a Focus From a Faithless Sorcerer", ["amount"] = 1, ["type"] = 1, ["objectID"] = 163681, ["orderIndex"] = 0 }, { ["text"] = "Gain 100 power from Flowing Current", ["amount"] = 1, ["type"] = 0, ["objectID"] = 137515, ["orderIndex"] = 1 }, { ["text"] = "Restore the Avatar of Sethraliss", ["amount"] = 1, ["type"] = 14, ["objectID"] = 66102, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 137, ["db2QuestInfoName"] = "Dungeon World Quest" },
[51380] = { ["id"] = 51380, ["name"] = "Back to Franklin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 48770, 51380, 51889 }, ["description"] = "Oh, good! You are still here! I heard you had built a rapport with Franklin. I'd be lying if I said talking about him didn't make me reminisce when we worked together. If you're not busy, could you go talk to him? Ask him if he can show you anything else. I'm sure he remembers more, if you're still looking for more information. And tell him that if he were to get his life sorted out, I'd like to talk to him about working together again.", ["objectivesText"] = "Speak with Franklin The Drunk .", ["rewardItems"] = { 152512, 152513, 152579, 160905, 161078, 161085 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 771, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Storm Silver Seam - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51384] = { ["id"] = 51384, ["name"] = "WANTED: Quartermaster Ssylis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51384 }, ["description"] = "Don't venture too far into the bay if you're not looking for a fight! A couple of Bilge Rats have taken up residence in a nearby cave, and they won't stand down from any challenge. They ain't harming anybody, 'long as you stay away. But if somebody wants to go take care of their leader, they will be rewarded.", ["objectivesText"] = "Kill Quartermaster Ssylis in Krakenbane Cove. Progress: <Alby nods at you.>", ["rewardGold"] = 929400, ["rewardXP"] = 2125, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 126308, ["x"] = 0.3915, ["y"] = 0.267 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.267 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
