[51386] = { ["id"] = 51386, ["name"] = "Battle Victorious", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51386 }, ["description"] = "We have everything necessary to strike a blow against this Venture Company. Our plan is sound, we are well prepared and we have the element of surprise. We shall ride atop Ai'twen and reign chaos upon them with their very own weapons.", ["objectivesText"] = "Ride Ai'twen and destroy the Venture Companies forces Progress: The Venture Companies defeat is at hand. Let's get to it!", ["rewardGold"] = 772200, ["rewardXP"] = 6175, ["rewardItems"] = { 160335, 160338, 160341, 160344, 160373, 160376, 160379, 160382 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137554, ["x"] = 0.344, ["y"] = 0.262 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135795, ["x"] = 0.4045, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51389] = { ["id"] = 51389, ["name"] = "Breaking Free", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "Look, these guys are in a tough spot but let's not lose track of the mission. We've got to rescue Private James ! I saw a bunch of cages down in the camp of those snakes that are besieging the temple. If James is going to be anywhere, then it'll be there!", ["objectivesText"] = "Find Private James and free him from his captors.", ["rewardGold"] = 295000, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137543, ["x"] = 0.272, ["y"] = 0.5235 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137559, ["x"] = 0.2728, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.5235 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 31, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 31, ["flags"] = 0 } } },
[51390] = { ["id"] = 51390, ["name"] = "WANTED: The Crimson Cutthroats", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51390 }, ["description"] = "For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments. A reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.", ["objectivesText"] = "Slay the Crimson Cutthroats near Falconhurst. Progress: The Crimson Cutthroats are a nasty bunch. I wouldn't be sad to see them go.", ["rewardGold"] = 772200, ["rewardXP"] = 4150, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 131442, ["x"] = 0.258667, ["y"] = 0.707333 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.258667, ["y"] = 0.707333 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[51391] = { ["id"] = 51391, ["name"] = "Defang the Faithless", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "Did you see them as we flew in? The Faithless are sieging the temple! Friend, I know we just met but I must ask for your aid once more. Please, help us break their ranks!", ["objectivesText"] = "Kill 12 Faithless attackers within the Temple Grounds.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137537, ["x"] = 0.272, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129519, ["x"] = 0.275333, ["y"] = 0.525333 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 32, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 32, ["flags"] = 0 } } },
[51394] = { ["id"] = 51394, ["name"] = "Break the Siege", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "This isn't the first time the Faithless have attacked us, nor will it be the last, but the temple must be protected! Please, do whatever you can to destroy their siege equipment and push them back.", ["objectivesText"] = "Disrupt the Faithless assault on the Sanctuary of the Devoted. Progress: We will not let them win!", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137537, ["x"] = 0.272, ["y"] = 0.54 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 129519, ["x"] = 0.275333, ["y"] = 0.525333 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 33, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 33, ["flags"] = 0 } } },
[51395] = { ["id"] = 51395, ["name"] = "The Keepers' Keys", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "It's good to see that your companion is back unharmed. But more importantly, let's see if he still has my stone hidden in his pockets.", ["objectivesText"] = "Speak to Private James and uncover the significance of Vorrik 's Stone.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 129519, ["x"] = 0.275333, ["y"] = 0.525333 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 128694, ["x"] = 0.2692, ["y"] = 0.5252 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.275333, ["y"] = 0.525333 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 34, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 34, ["flags"] = 0 } } },
[51397] = { ["id"] = 51397, ["name"] = "Up In Your Drill", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51397 }, ["description"] = "<The drill on the front of the machine is in good condition.> <This seems like the perfect type of work hazard.>", ["objectivesText"] = "Use the Goblin Mining Machine to disrupt the excavation camp.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Mining Machine commandeered", ["amount"] = 1, ["type"] = 0, ["objectID"] = 137518, ["orderIndex"] = 0 }, { ["text"] = "Horde drilled", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[51398] = { ["id"] = 51398, ["name"] = "An Unusual Mentor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 864, ["storyline"] = { 51398, 51399, 51404, 51408 }, ["series"] = { 51399, 51408, 51432 }, ["description"] = "Hey <name>, you look like you're ready to handle hostile territory. Far away in the desert of Vol'dun, on the continent of Zandalar, there grows a plant called akunda's bite. You couldn't pay me enough to go there myself, and there's almost no mention of them in any of the books I've read, but all is not lost. I know of an herbalist who lives there in the desert and studies that plant. Find him, and I'm sure he'll be able to teach you a thing or two. Oh, and do be warned... He is a bit... eccentric.", ["objectivesText"] = "Find Patu in Vol'dun.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137572, ["x"] = 0.622, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 748, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51399] = { ["id"] = 51399, ["name"] = "Foul Harvest", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51398, 51399, 51404, 51408 }, ["series"] = { 51398, 51408, 51432 }, ["description"] = "You have traveled far to find knowledge, but you have found me instead. I am curious though, how much further you would travel for it. I will teach you, if you do something for me first. Iron sharpens iron, as they say, so too does adversity strengthen the seed. Go out and find seeds, ones that have been consumed by the wild beasts and have returned to the earth unscathed. Only those seeds will be strong enough to survive the desert sands of Vol'dun.", ["objectivesText"] = "Collect 12 Digested Akunda's Bite Seeds . Progress: Were you able to get the seeds?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160108, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137572, ["x"] = 0.622, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137572, ["x"] = 0.622, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 748, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 749, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Akunda's Bite - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51402] = { ["id"] = 51402, ["name"] = "Reporting In", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "I can't believe what we got ourselves in the middle of here. Keystones, C'Thraxxi, there's even a snake-man civil war going on! All I know is Wyrmbane is going to want a full report and if there's anything I hate more than inept privates getting themselves captured it's paperwork. Let's get going.", ["objectivesText"] = "Report to High Commander Halford Wyrmbane .", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["rewardItems"] = { 159958, 160044, 160045 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137543, ["x"] = 0.272, ["y"] = 0.5235 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137213, ["x"] = 0.378, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.272, ["y"] = 0.5235 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 613, ["questLineOrder"] = 6 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 613, ["name"] = "The Sands of Vol'dun", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 36, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 36, ["flags"] = 0 } } },
[51404] = { ["id"] = 51404, ["name"] = "What Happens Next", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 51398, 51399, 51404, 51408 }, ["description"] = "After feeling the bite of Akunda so many times, static electricity causes your hair to stand on end as you hold in your hands an intact lightning pod. You noticed that by wrapping the lightning pod in it's own leaves, you were able to remove it without discharging it. If you manage to develop this technique, harvesting this plant would become significantly less hazardous and provide additional material in pristine condition.", ["objectivesText"] = "Harvest 10 Akunda's Bite without being shocked.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117, 160301, 160550 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 748, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 749, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Akunda's Bite - SCS", ["orderIndex"] = 3, ["flags"] = 0 } }, ["startItems"] = { 160117 } },
[51407] = { ["id"] = 51407, ["name"] = "Find Their Words", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 49284, 49285, 49286, 49287, 49288, 49289, 51407 }, ["description"] = "This portal will get you quickly back to the outpost. When there, present the orders to Akru . Her knowledge is vast, she will be able to discern the truth within.", ["objectivesText"] = "Deliver the Orders from Nazjatar to Akru at Seekers' Outpost. Progress: Ah. Deyon is correct. I know many things. What do you have there?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 156871, 157543 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 128925, ["x"] = 0.752, ["y"] = 0.615 }, { ["mapID"] = 862, ["npcID"] = 129717, ["x"] = 0.705, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 129717, ["x"] = 0.705, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.752, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5409, ["name"] = "Dreadpearl Tidings", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51408] = { ["id"] = 51408, ["name"] = "Giving Back to Nature", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51398, 51399, 51404, 51408 }, ["series"] = { 51398, 51399, 51432 }, ["description"] = "Perform one additional task, and I will give you the knowledge you seek. The seeds you have are strong, but they need time until they are ready to grow. However, one must always be prepared in the desert. This sapling is mature enough to live on its own, but it is frail. It needs the dry desert winds to build static so it may bite, but until it does, it is as helpless as grass. Plant it in the desert sands, near the fallen beast south of the Brine Basin, and protect it until it can defend itself.", ["objectivesText"] = "Plant the Akunda's Bite Sapling and defend it until it builds a static charge. Progress: Have you planted the sapling yet? Has it taken root?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159956, 160035, 160064, 160117, 160187 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 137572, ["x"] = 0.622, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137572, ["x"] = 0.622, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 748, ["name"] = "8.0 Professions - Gathering - Herbalism - Kul Tiras - Akunda's Bite - SCS", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 749, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Akunda's Bite - SCS", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51415] = { ["id"] = 51415, ["name"] = "Azerite Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 863, ["storyline"] = { 51415 }, ["objectivesText"] = "Absorb Azerite from defeated elementals", ["rewardItems"] = { 109644, 158075 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Absorb Azerite from defeated elementals", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["db2QuestInfoID"] = 151, ["db2QuestInfoName"] = "Magni World Quest - Azerite" },
[51418] = { ["id"] = 51418, ["name"] = "Xibala", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "<name>! How's things going over here? Oh. Wow. There's Horde soldiers everywhere. And Zandalari trolls. And hardly any machines at all. We should DEFINITELY head back to Xibala, with the dark iron dwarves. It's perfect for our foothold!", ["objectivesText"] = "Use the rowboat in Talanji's Rebuke to travel to Xibala.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135620, ["x"] = 0.652, ["y"] = 0.603333 }, { ["mapID"] = 862, ["npcID"] = 137400, ["x"] = 0.406, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 }, { ["mapID"] = 862, ["npcID"] = 137401, ["x"] = 0.406, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.652, ["y"] = 0.603333 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 18, ["flags"] = 0 } } },
[51421] = { ["id"] = 51421, ["name"] = "Shiver Me Timbers", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["series"] = { 51435, 51436 }, ["description"] = "It seems our resident shadow hunter has managed to seize a small pirate sloop. We have sent him to Tiragarde Sound in a search for a foothold, and it seems that he has concocted a plan. Ty'jin has requested your help, personally. Do not keep him waiting.", ["objectivesText"] = "Accompany Shadow Hunter Ty'jin to Tiragarde Sound.", ["rewardGold"] = 25740, ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137675, ["x"] = 0.882, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 9, ["flags"] = 0 } } },
[51422] = { ["id"] = 51422, ["name"] = "Azerite Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 864, ["storyline"] = { 51422 }, ["objectivesText"] = "Absorb Azerite from defeated elementals", ["rewardItems"] = { 109644, 158075 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Absorb Azerite from defeated elementals", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 151, ["db2QuestInfoName"] = "Magni World Quest - Azerite" },
[51425] = { ["id"] = 51425, ["name"] = "There's No Place Like Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 51425 }, ["description"] = "So, the Arathi Highlands. Quite a sprawl, isn't it? At some point, you may wish to return to this fair Stromgarde with haste. Might I offer a suggestion as to how...?", ["objectivesText"] = "Talk to Captain Roderick Brewston", ["rewardItems"] = { 160219 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[51426] = { ["id"] = 51426, ["name"] = "Inspection Gadget", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51426 }, ["description"] = "Some time ago, a good friend of mine who had a tinker shop in Boralus just stopped all correspondence. With the state of foreign affairs, I wasn't able to look for him myself until recently. It's not just him. It seems that all of the gnomes that were living in the city just up and vanished. I've decided to start my search with these ruins, but the machines here have gone haywire. Could you go get a good magnetic reading on the place?", ["objectivesText"] = "Survey the Rusted Vault.", ["rewardGold"] = 289300, ["rewardXP"] = 1415, ["rewardItems"] = { 160245, 163496 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137694, ["x"] = 0.65, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137694, ["x"] = 0.65, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[51427] = { ["id"] = 51427, ["name"] = "I Like Turtles", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51427 }, ["description"] = "Excellent work, $p. Present the offering to Ai'twen. He will accept it and come to our aid.", ["objectivesText"] = "Present the offering to Ai'twen. Progress: We are patient. When you are ready.", ["rewardGold"] = 128700, ["rewardXP"] = 2060, ["rewardItems"] = { 160349, 160352, 160355, 160358, 160395, 160396 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51430] = { ["id"] = 51430, ["name"] = "Reverse Tinkering", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51430 }, ["description"] = "The sentry bots here are definitely of gnomish make. If the creator had any sort of proper education, each machine should have some sort of serial code on it. And if they've been properly documented, I might be able to use those codes to track that gnome down. Do you think you could bring a few of them back to me?", ["objectivesText"] = "Gather 4 V-300 serial plates . Progress: Did you find anything interesting?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 160317, 163496 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137694, ["x"] = 0.65, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137694, ["x"] = 0.65, ["y"] = 0.606 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[51432] = { ["id"] = 51432, ["name"] = "An Unusual Mentor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51399, 51404, 51408, 51432 }, ["series"] = { 51398, 51399, 51408 }, ["description"] = "You have done well so far, <name>, but dere is still much more for you to learn. I think it is time for you to meet an old 'friend'. Dere is no better person I know of to teach you about akunda's bite, as his knowledge and respect for de plant is unrivaled. Head North beyond the desert of Vol'dun. Dere you will find a tortollan who will teach you more about de desert flower.", ["objectivesText"] = "Find Patu in Vol'dun.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 137572, ["x"] = 0.622, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 864, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 749, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Akunda's Bite - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51434] = { ["id"] = 51434, ["name"] = "Stone Golem", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite", "rare" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51434 }, ["rewardItems"] = { 153023 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 136, ["db2QuestInfoName"] = "Rare Elite World Quest" },
[51435] = { ["id"] = 51435, ["name"] = "Swashbuckling in Style", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["series"] = { 51421, 51436 }, ["description"] = "First ting's first, boss-mon. Ya can't parley with pirates unless ya got da appropriate clothes. I ain't big on fashion, mon, but what ya be wearin' won't work. Luckily I collected dis box of pirate clothes. No need ta ask how. Just need ta get piratey.", ["objectivesText"] = "Put on a pirate disguise from the chest of Pirate Garb. Progress: Pick whateva ya want, boss-mon. Dere be so many clothes in dat chest.", ["rewardGold"] = 128700, ["rewardXP"] = 2395, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137675, ["x"] = 0.882, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137675, ["x"] = 0.882, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.882, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 10, ["flags"] = 0 } } },
[51436] = { ["id"] = 51436, ["name"] = "Parleyin' Wit Pirates", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["series"] = { 51421, 51435 }, ["description"] = "Some a dese pirates be unhappy wit' da leadership. I been hearin' dey're da last truly free pirates. Da rest be sellin' out ta some lady named Ashvane. I don' really care 'bout dat, but da captain of dese Fogsail Freebootas is tinkin' 'bout sellin' out too. We gonna help stop it, and in return build a foothold here.", ["objectivesText"] = "Follow Shadow Hunter Ty'jin and meet First Mate Owings .", ["rewardGold"] = 128700, ["rewardXP"] = 2395, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137675, ["x"] = 0.882, ["y"] = 0.512 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137727, ["x"] = 0.872, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.882, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 11, ["flags"] = 0 } } },
[51437] = { ["id"] = 51437, ["name"] = "Spike the Punch", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["description"] = "Step one in causing a mutiny? Make it seem like leadership is incompetent. If the captain wants to sell our souls to the Ashvanes, we're going to need to get dirty. I hate to say it... but we've got to muck up the booze. That'll make the crew angry at the captain before you can even blink.", ["objectivesText"] = "Spike 6 Kegs of Grog. Progress: It's a dirty deed, but it's necessary.", ["rewardGold"] = 221280, ["rewardXP"] = 4790, ["rewardItems"] = { 119213 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137727, ["x"] = 0.872, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137727, ["x"] = 0.872, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 12, ["flags"] = 0 } } },
[51438] = { ["id"] = 51438, ["name"] = "Marking Our Territory", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["series"] = { 51975 }, ["description"] = "Dis could turn out ta be quite da foothold, boss-mon! I will help wit' da settlin', turnin' da place into a good base. I tink we need some spikes. Let's be makin' tings official.", ["objectivesText"] = "Plant the Horde Banner in Plunder Harbor. Progress: Dis place be feelin' like home in no time.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137742, ["x"] = 0.872, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137742, ["x"] = 0.872, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 17, ["flags"] = 0 } } },
[51439] = { ["id"] = 51439, ["name"] = "Cannonball Collection", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["description"] = "Walkin' through da harbor gave me some ideas, boss-mon. Ya see dem big guys wit' da cannonballs? Collect some a dat ammo and bring it ta me. I tink I be havin' a use for it.", ["objectivesText"] = "Collect 3 Fogsail Cannonballs from Fogsail Cannoneers. Progress: Did ya get da cannonballs?", ["rewardGold"] = 169800, ["rewardXP"] = 4790, ["rewardItems"] = { 160260 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137742, ["x"] = 0.872, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137742, ["x"] = 0.872, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 13, ["flags"] = 0 } } },
[51440] = { ["id"] = 51440, ["name"] = "A Change in Direction", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["description"] = "Whispers of dissent have been spreading through the harbor, <name>. You can hear the grumblings of pirates who do not want to give up their freedom! Rumor holds that some of the other authority figures have goals that align with mine. I forged some letters in the captain's hand. Deliver them... see who bites. Or who gets in our way.", ["objectivesText"] = "Deliver the forged orders to Boatswain Taryn , Quartermaster Killian , and Navigator Swink . Progress: Mutiny is about subversion. We must fly under the radar as long as we can!", ["rewardGold"] = 514800, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137727, ["x"] = 0.872, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137727, ["x"] = 0.872, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 14, ["flags"] = 0 } } },
[51441] = { ["id"] = 51441, ["name"] = "Thar She Blows!", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["description"] = "Our goblin engineers been workin' on modifyin' some cannons for our uses. Da cannonballs you been collectin' be perfect ammo for dem. Dere are rowboats in da harbor dat be readyin' ta bring loot to Owings's enemies. Take dis cannon and sink 'em before dey can get away!", ["objectivesText"] = "Use the Goblin-Engineered Hand Cannon to sink 3 Fogsail Rowboats . Progress: Sometimes ya gotta use da ammo of ya enemies against dem, mon.", ["rewardGold"] = 227640, ["rewardXP"] = 4790, ["rewardItems"] = { 160405 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137742, ["x"] = 0.872, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137742, ["x"] = 0.872, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 15, ["flags"] = 0 } } },
[51442] = { ["id"] = 51442, ["name"] = "I'm the Captain Now", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["description"] = "Alright <name>... It's time to take the mutiny to the captain. Rhenik sits in his cave, readying himself to sell our souls to the Ashvanes! Defeat him, and I will allow you to use my port as though it were your own.", ["objectivesText"] = "Kill Captain Rhenik . Progress: I cannot stand by and watch Rhenik sell our freedom.", ["rewardGold"] = 561800, ["rewardXP"] = 5990, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137727, ["x"] = 0.872, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 137727, ["x"] = 0.872, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 16, ["flags"] = 0 } } },
[51445] = { ["id"] = 51445, ["name"] = "Thros, the Blighted Lands", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "The Blighted Lands... If the legends are true then inside we will witness suffering and torment the likes of which we have never known. .. ...but if that is what I must endure to right what I have wronged, then I will cross that threshold gladly. Will you join me, <class>?", ["objectivesText"] = "Find Jaina in Thros, the Blighted Lands. Progress: I'm with you, champion.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 141785, ["x"] = 0.272667, ["y"] = 0.586667 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 141785, ["x"] = 0.272667, ["y"] = 0.586667 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.272667, ["y"] = 0.586667 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 23, ["flags"] = 0 } } },
[51446] = { ["id"] = 51446, ["name"] = "Meet Sweetflower", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 48763, 51376, 51446 }, ["series"] = { 48762, 51376 }, ["description"] = "You have seen and learned much from these islands, but Zandalar is not de only place where you can learn. I have heard of a flower dat cannot grow on dese islands. If you want to know more about it, you will need to find someone more knowledgeable dan myself. Fortunately for you, I know of someone who may be able to help you. Her name's Xun Xun Sweetflower , and last I heard she set up shop on the outskirts of Anyport over on de human island of Drustvar.", ["objectivesText"] = "Find Xun Xun Sweetflower in Drustvar.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 152546, 159877, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136141, ["x"] = 0.206, ["y"] = 0.456 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 896, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 761, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Winter's Kiss - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51447] = { ["id"] = 51447, ["name"] = "Aromatic Pollenator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51447, 51448, 51451, 51452 }, ["series"] = { 51448 }, ["description"] = "While gathering the pollen, you found a dead wasp absolutely covered in pollen. You know that this little creature is the secret to harvesting pollen easier, but the answer seems just out grasp. Maybe if you ask Jahden about it, he might have an idea.", ["objectivesText"] = "Bring the Dead Pollen-Covered Wasp to Jahden Fla . Provided item:", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160250, 160301, 160550, 252419 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 759, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Siren's Pollen - SCS", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 160250 } },
[51448] = { ["id"] = 51448, ["name"] = "Learn From the Best", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51447, 51448, 51451, 51452 }, ["series"] = { 51447 }, ["description"] = "You want to learn how these wasps are so good at harvesting pollen, but dey will defend their territory once you set foot inside it. Dis would be a problem, but I think I have a solution. Take dis potion and go to Vol'dun, to de Prickly Grove, and drink it to turn into a plant. Here's the deal: you go out and drink the potion, you'll see firsthand how the wasps do what they do. After the potion wears off, you tell me what happened.", ["objectivesText"] = "Drink Jahden's potion and allow wasps to harvest your pollen.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160252, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 759, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Siren's Pollen - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51451] = { ["id"] = 51451, ["name"] = "Disgustingly Damp Flower", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51447, 51448, 51451, 51452 }, ["series"] = { 51452 }, ["description"] = "Rummaging for pollen as usual, you use the harvesting technique you learned from the wasps. However, when you pull your hand away from the flower, you find that there is no pollen to be seen. Looking inside the swirl of petals, despite it being a mature flower, you see that there is no pollen at all. Upon closer inspection you see that the flower is filled with a viscous liquid. Could the flower have done this? While unpleasant to touch, you carefully pluck the flower to show Jahden.", ["objectivesText"] = "Take the Disgustingly Damp Flower to Jahden Fla . Provided item:", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160301, 160550 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 759, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Siren's Pollen - SCS", ["orderIndex"] = 2, ["flags"] = 0 } }, ["startItems"] = { 160301 } },
[51452] = { ["id"] = 51452, ["name"] = "Pollen Punching", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51447, 51448, 51451, 51452 }, ["series"] = { 51451 }, ["description"] = "It looks like some beast managed to lap up all de pollen with it's tongue. It is curious as to what creature could have done dis, I doubt it matters. You should be able to do dis yourself without needing any sort of rare or dangerous reagents. Next time you find a siren's sting, wet your glove so the pollen will stick to it. Water, wine, blood... It should not matter.", ["objectivesText"] = "Collect 12 Heaping Handfuls of Damp Pollen .", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159957, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 759, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Siren's Pollen - SCS", ["orderIndex"] = 3, ["flags"] = 0 } } },
