[51464] = { ["id"] = 51464, ["name"] = "Here In Spirit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51464, 51478 }, ["description"] = "If you are up to de challenge, I have a task dat I believe is up your alley. De spirits of dis land are screaming out in anguish. However, dey are either unwilling or unable to talk to me in their current state. I need you to get some fresh star moss , which will help anchor and calm their spirits. Once dey are calm, we will be able to give dem de help dey need. Do dis, and I will teach you how to harvest star moss more effectively.", ["objectivesText"] = "Collect 10 Fresh Star Moss . Progress: De spirits are restless. Have you managed to get de fresh star moss yet?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159830, 159877, 160064, 160117, 160301, 160550, 163835 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 760, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Star Moss - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51465] = { ["id"] = 51465, ["name"] = "A Load of Scrap", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51465 }, ["description"] = "Hey there stranger, you want the scoop on the latest invention of the century? It's called the Shred-Master Mk1 and this baby can triple, no QUADRUPLE your production capacity as a crafter of armor, weapons or other doohickeys you adventurers wander around with. Here, take these pants and use the Shred-Master on 'em. You'll get the gist of it.", ["objectivesText"] = "Use the Shred-Master Mk1 on the pair of Tattered Pants . Progress: This machine is gonna change everything.", ["rewardGold"] = 23400, ["rewardXP"] = 3410, ["rewardItems"] = { 152668, 160266, 160267 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 137818, ["x"] = 0.449, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 137818, ["x"] = 0.449, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
