[51472] = { ["id"] = 51472, ["name"] = "Life Preserver", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51472 }, ["description"] = "The Thornspeakers were assisting me but they have troubles of their own. I came in search of a powerful dragon who fell in battle many centuries ago. Melting snows have revealed Vadekius's final resting place. My Queen has tasked me with ensuring his body cannot be reanimated and enslaved. The ritual will require my full attention and my druid friends aren't fit for combat. Watch my back while I ensure my cousin's soul flies amid the branches of G'Hanir, safe from undeath.", ["objectivesText"] = "Protect Zallestrasza while she conducts the ritual. Progress: Will you watch my back as I complete the ritual?", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 154447, 155096, 155097, 155098, 155099, 155460, 155469, 155477, 155485 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 137732, ["x"] = 0.363333, ["y"] = 0.708 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 137732, ["x"] = 0.363333, ["y"] = 0.708 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.363333, ["y"] = 0.708 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[51474] = { ["id"] = 51474, ["name"] = "Forged in Fire an' Flame", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 51474, 51813, 53342, 53351, 53352, 53566 }, ["series"] = { 51813, 53342, 53351, 53352, 53566 }, ["description"] = "Ye've done more than I had any right tae ask, <name>. Recovered Ironfoe from our enemy, retrieved a fragment o' the Molten Core, an' exposed the enemy within our ranks at the Firelands. If ye'd do me the honor, would ye come with us tae Blackrock Depths one last time while we repair our most sacred anvil?", ["objectivesText"] = "Speak with Moira at the Stormwind Embassy to travel to Blackrock Depths and repair the Black Anvil. Progress: Ye've been a lifesaver, <name>.", ["rewardGold"] = 245700, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133197, ["x"] = 0.52, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133197, ["x"] = 0.52, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 781, ["name"] = "Allies of the Alliance: Dark Iron Dwarf", ["orderIndex"] = 4, ["flags"] = 0 } } },
[51478] = { ["id"] = 51478, ["name"] = "Ghost Busting", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51464, 51478 }, ["description"] = "I have spoken with de spirits. Most of dem were willing to bare their souls, calling for help from de living as dey are under attack from de blood trolls evil magic. Dere was one, however, who seemed more angry dan most. It was furious dat we had not acted yet, dat we allowed things to get dis bad. Go to de Spirits Be With You inn at de port north of here and put dis spirit down, and in return I will teach you everything else I know about gathering star moss.", ["objectivesText"] = "Put the Angry Spirit to rest.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160299, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 760, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Star Moss - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51479] = { ["id"] = 51479, ["name"] = "The Uncorrupted", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["description"] = "This world is... not what I expected. It is time for us to meet your warchief, <name>. There is no need to delay any further. We can lick our wounds once we have a roof over our heads.", ["objectivesText"] = "Return to Ji Firepaw in Orgrimmar to hear the end of this tale.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 161330 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 143845, ["x"] = 0.412, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 126065, ["x"] = 0.378, ["y"] = 0.81 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 9, ["flags"] = 0 } } },
[51480] = { ["id"] = 51480, ["name"] = "Enormous Anchor Pod", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51480, 51481, 51482 }, ["series"] = { 51481 }, ["description"] = "In all the gathering you've done, you have never come across an anchor pod of this size. Whatever the reason that it has gotten so large, there is much that can be learned from it. Your mind wanders back to Jahden, and if there is anything about it in the book you picked up earlier.", ["objectivesText"] = "Bring the Enormous Anchor Pod to Jahden Fla . Provided item:", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160301, 160550 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 751, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Anchor Weed  - SCS", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 160550 } },
[51481] = { ["id"] = 51481, ["name"] = "More Anchor Pods", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51480, 51481, 51482 }, ["series"] = { 51480 }, ["description"] = "I need you to bring me a handful of mature anchor pods . You see, dis seed pod is massive, but it is still just a seed pod. If we dissect it and take careful notes, we can learn about de normal, smaller seed pods and easily see how de anatomy works. I need you to bring me more of dese mature anchor pods . If my theory is correct, den we could actually have a factual record for de future.", ["objectivesText"] = "Collect 9 Mature Anchor Pods from anchor weed. Progress: I just finished with my notes from dissecting de massive seed pod. Do you have de other seed pods for comparison?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160036, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 751, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Anchor Weed  - SCS", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51482] = { ["id"] = 51482, ["name"] = "Seeking More Knowledge", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51480, 51481, 51482 }, ["description"] = "One of de most sacred plants on dis island is anchor weed. Legend says dat it was a gift from de Loa and it can do anything from regrow limbs to granting immortality. If you are looking for facts as to what it can do or how to harvest it, you will need to go elsewhere. The spirits tell me dat dere is a book, dat contains de information you seek. Look for it deep within the Waycrest Manor. Dey ask dat in exchange for dis knowledge, you kill whatever is causing a rift in de spirit world.", ["objectivesText"] = "Retrieve the Treatise on Anchor Weed from within Waycrest Manor. Progress: Have you retrieved de book?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 159960, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 751, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Anchor Weed  - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51483] = { ["id"] = 51483, ["name"] = "Heritage o' the Dark Iron", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1584, ["storyline"] = { 51483 }, ["description"] = "Ye've done us proud, <name>. I've heard tales o' yer bravery during yer journeys across the surface o' Azeroth. Return tae the mountain. We've got somethin' special fer ye.", ["objectivesText"] = "Meet Moira Thaurissan at Shadowforge City.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1584 } }, ["questType"] = "standard" },
[51484] = { ["id"] = 51484, ["name"] = "Heritage of the Mag'har", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 36 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 51484 }, ["description"] = "You have fought countless battles across the face of Azeroth. You have shown both our allies and enemies what it means to be Mag'har! Return to Orgrimmar that I may recognize your dedication to our people.", ["objectivesText"] = "Meet Overlord Geya'rah in Orgrimmar.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 143845, ["x"] = 0.412, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[51485] = { ["id"] = 51485, ["name"] = "For the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 10, 36 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 1, ["storyline"] = { 51485, 53502 }, ["description"] = "The Mag'har face a new future, <class>. Draenor has fallen. We cannot know if we will ever set eyes upon our homeland again. But this is not the time to wallow in past sorrows. Destiny is ours to decide. Orgrimmar is our home now, and we must make our mark upon this land! Show our allies in the Horde what it means to be Mag'har. Meet with the ambassador at the warchief's embassy, then go forth and claim victories across Azeroth. Strength and honor, <name>!", ["objectivesText"] = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 143845, ["x"] = 0.412, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 784, ["name"] = "Allies of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51486] = { ["id"] = 51486, ["name"] = "Fer the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1584, ["mapID"] = 84, ["storyline"] = { 51486, 53500 }, ["series"] = { 49788, 50305 }, ["description"] = "The mountain will always be home, but there's a whole world o' adventure up there on the surface. Ye look like just the sort o' <class> to find it. Fer a long time, the Dark Irons stood apart from the other kingdoms. The time has come tae show 'em that we fight fer Azeroth, too. There's an ambassador in Stormwind waitin' tae speak tae ye. He can help guide ye along on yer journey. The Alliance needs our strength, $p. Get out there and show 'em the might o' the mountain!", ["objectivesText"] = "Meet Ambassador Moorgard at the Stormwind Embassy.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 157022, 161329 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1584 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 783, ["name"] = "Allies of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
