[51492] = { ["id"] = 51492, ["name"] = "Gunpowder Plot", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "Granny has everyone out running errands trying to put our hamlet back in order. I don't know what to do. The rats have gotten into our stores, they're eating everything in sight. I tried prodding one of them to get it to move along, it started foaming at the mouth, then it exploded! Think I know where all the gunpowder went... If you recover any, can you please take it back to Marie?", ["objectivesText"] = "Collect 100 Gunpowder from Volatile Rats. Progress: Were you able to find any powder, dear?", ["rewardGold"] = 169800, ["rewardXP"] = 4115, ["rewardItems"] = { 159776, 160347, 160350, 160353, 160356, 160359, 160362, 160365, 160368 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.333, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 2, ["flags"] = 0 } } },
