[51498] = { ["id"] = 51498, ["name"] = "Cultural Significance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51498, 51503 }, ["description"] = "I have noticed dat your skill with harvesting plants has improved, but I have also noticed dat you just treat each flower and leaf as a commodity. De flora of dese islands have a rich history, with a deep cultural significance to us. Go down to the Port of Zandalar, and ask some of the men and women what a sea stalk means to them. Learn from us, and l will make it worth your while.", ["objectivesText"] = "Learn the importance of sea stalks from people in the Port of Zandalar.", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160301, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 758, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Sea Stalk - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51503] = { ["id"] = 51503, ["name"] = "Gathering Mementos", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "herbalism" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51498, 51503 }, ["description"] = "I have a task dat I can not really trust to anyone else, and I feel you could handle it with de reverence it deserves. An old friend came to me today, bringing a wilted sea stalk flower with her. Her husband was on a ship off the coast of Nazmir. I am unsure if de ship went down because of de naga, de Alliance, or a squall, but she said she did not want revenge. Only closure. If you could go get her something to remember him by, I will tell you everything I know about sea stalks.", ["objectivesText"] = "Search through patches of sea weed to find a memento of the lost sailor. Progress: Have you had a chance to search de wreckage?", ["rewardItems"] = { 152505, 152506, 152507, 152508, 152509, 152510, 152511, 159877, 160064, 160117, 160301, 160314, 160550 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122704, ["x"] = 0.422, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 758, ["name"] = "8.0 Professions - Gathering - Herbalism - Zandalar - Sea Stalk - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51504] = { ["id"] = 51504, ["name"] = "Cookie Delivery", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51200, 51203, 51205, 51207, 51208, 51209, 51214, 51215, 51251, 51335, 51492, 51504 }, ["description"] = "Before you head out, dear, I have one more favor to ask of you. Please take these cookies with you to Charles. What sort of grandmother would I be if I didn't bake some for him too!? A terrible one, that's what, and I've no wish to be accused of that!", ["objectivesText"] = "Deliver Box of Cookies to Charles Davenport in the Sprucewood. Progress: Are those cookies I smell!?", ["rewardGold"] = 33100, ["rewardXP"] = 515, ["rewardItems"] = { 160302 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 136658, ["x"] = 0.304, ["y"] = 0.668 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 136574, ["x"] = 0.333, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5452, ["name"] = "Milstone Hamlet", ["orderIndex"] = 8, ["flags"] = 0 } } },
