[51513] = { ["id"] = 51513, ["name"] = "Zalazane Returns", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 862, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["series"] = { 51514 }, ["description"] = "<name>, I have never needed your help as much as I do this day. My home be under attack. I only just heard myself. Master Gadrin be callin' for aid. Zalazane, an old enemy of da Darkspear, has returned to da Echo Isles and has brought with him an army of da dead. Zalazane be a traitor who has slain many Darkspear and defiled their souls. Will you come with me to defeat him? We can take da ship dat departs da Port of Zandalar.", ["objectivesText"] = "Reach Master Gadrin in the Echo Isles.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 238818 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 120171, ["x"] = 0.576, ["y"] = 0.624 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 137878, ["x"] = 0.595, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 463, 862 }, ["zone"] = { 9598 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51514] = { ["id"] = 51514, ["name"] = "Broken Bargain", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["series"] = { 51513 }, ["description"] = "These mindless undead just keep coming. They be far stronger than they were the last time Zalazane walked this world. Please, help us drive these undead back.", ["objectivesText"] = "Destroy 20 Mindless Trolls on Darkspear Isle.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 137878, ["x"] = 0.595, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 137878, ["x"] = 0.595, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51515] = { ["id"] = 51515, ["name"] = "Vengeance for Vol'jin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["description"] = "If we mean to destroy Zalazane then we gonna need something that can damage that spirit. Da Glaive of Vol'jin might be what we need to do this. Zalazane be hovering near where he fell so many years ago. Rokhan and Talanji have already gone to face him. Go, slay Zalazane , and then plunge da glaive into the spirit before it can escape. Let us hope de bargain Vol'jin made be powerful enough to destroy this enemy.", ["objectivesText"] = "Destroy Zalazane . Progress: Zalazane has plagued the Darkspear longer than any enemy we ever faced. His destruction must happen swiftly.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 160443 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 137878, ["x"] = 0.595, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 137878, ["x"] = 0.595, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51516] = { ["id"] = 51516, ["name"] = "Atal'Dazar: Ashes of a Warchief", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["series"] = { 51517, 52113 }, ["description"] = "I have learned much of de Darkspear lately. Truth is, I have quietly admired dem since I was a little girl, hearin' of Vol'jin's defiance of Zul's reckless call to action. Vol'jin was Warchief of the Horde, chieftain of de Darkspear, and more troll den most can claim to be. His ashes should be honored in a place of kings and queens. Take de ashes to Atal'Dazar with my blessing and honor your former Warchief as he deserves.", ["objectivesText"] = "Bring Vol'jin's ashes to Atal'Dazar. Progress: What you doin' my friend?", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["rewardItems"] = { 160479 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 138138, ["x"] = 0.438, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1763, ["db2PoiUiMapID"] = 934, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51517] = { ["id"] = 51517, ["name"] = "You Owe Me a Spirit", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9028, ["mapID"] = 863, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["series"] = { 51516, 52113 }, ["description"] = "Ya not leaving that here. Ol' Vol'jin not be dancin' in my house. I not be seein' his spirit for a long time. Its absence has broken de bonds dat held Zalazane in my control. So... I want you to lift dat heavy urn, and bring it to my necropolis. Vol'jin and I gonna have a face to face on my ground.", ["objectivesText"] = "Bring the Urn of Vol'jin to Bwonsamdi in Nazmir. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 160479 }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 9028 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 7, ["flags"] = 0 } } },
[51518] = { ["id"] = 51518, ["name"] = "The Lost Spirit", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51518, 51519, 51520, 51521 }, ["description"] = "It high time you an' I had a talk about ol' Vol'jin's missin' spirit. Dis goes beyond simple bargains and rights of passage. Spirits don' just go missin'. You gotta few friends dat are gonna help ya track Vol'jin's spirit down. Dem who was friends to him in life should have da strength to find him in death. And if not, Talanji gonna help ya. Go to Talanji's ship in da Port of Zandalar. It be dat banged up ship ya came in on. You gonna do a little seance.", ["objectivesText"] = "Speak with Princess Talanji in the Port of Zandalar.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 140907, ["x"] = 0.45, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140724, ["x"] = 0.576, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 735, ["name"] = "Justice For The Fallen", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51519] = { ["id"] = 51519, ["name"] = "Spirit Call", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 51518, 51519, 51520, 51521 }, ["series"] = { 51520, 51521 }, ["description"] = "We gonna be reachin' far into de Shadowlands for this. If Vol'jin has gone beyond Bwonsamdi's vision than either he be lost somewhere or hiding. Either way, I am hoping the bond he shares with de gathered Darkspear here can help bring him to us. Stay close and don't interrupt de ritual once it has begun.", ["objectivesText"] = "Observe Talanji's ritual.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 31437, 31711, 31712, 31713, 31714 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140724, ["x"] = 0.576, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140725, ["x"] = 0.576, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 735, ["name"] = "Justice For The Fallen", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51520] = { ["id"] = 51520, ["name"] = "Justice for the Fallen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 51518, 51519, 51520, 51521 }, ["series"] = { 51519, 51521 }, ["description"] = "Justice for da sons and daughters of lost loa. Justice for da heart of Zandalar. G'huun must be slain, and a symbol of his death displayed to those who need see it most. Take me glaive, drive it into da corpse of dat beast, and let Talanji show it to her people. Let peace be started in da hearts of da Zandalari.", ["objectivesText"] = "Bloody the Glaive of Vol'jin in G'huun's corpse. Progress: Madness and darkness be movin' on da other side. Da pain of so many be mighty.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 161452, 162451 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140725, ["x"] = 0.576, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140725, ["x"] = 0.576, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8670 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 735, ["name"] = "Justice For The Fallen", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51521] = { ["id"] = 51521, ["name"] = "The True Leader of Zandalar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 51518, 51519, 51520, 51521 }, ["series"] = { 51519, 51520 }, ["description"] = "Now, take me glaive and walk with Talanji. Let her present your victory to her people. Let da trolls know justice, and the strength of a leader.", ["objectivesText"] = "Present the Glaive of Vol'jin with Talanji to the people of Zandalar.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140725, ["x"] = 0.576, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140725, ["x"] = 0.576, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 735, ["name"] = "Justice For The Fallen", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51526] = { ["id"] = 51526, ["name"] = "The Warlord's Call", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["series"] = { 51532, 51536, 51587, 51643 }, ["description"] = "Warfang Hold is our best position on Kul Tiras. We can not allow it to fall! The Warchief has placed High Warlord Cromush in charge of our reinforcement efforts, you are ordered to report to him as soon as possible.", ["objectivesText"] = "Report to High Warlord Cromush in Zuldazar.", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 138352, ["x"] = 0.584, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 614, ["questLineOrder"] = 6 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 614, ["name"] = "Storming In", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 28, ["flags"] = 0 } } },
