[51532] = { ["id"] = 51532, ["name"] = "Storming In", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["series"] = { 51526, 51536, 51587, 51643 }, ["description"] = "Front and center, <name>! As of last night, we received word that Rexxar's force at Warfang Hold in Stormsong was surrounded by a Kul Tiran army and an attack is imminent. As soon as you have your things packed, go speak with Dread-Admiral Tattersail and we'll get underway. There's no time to waste!", ["objectivesText"] = "Speak with Dread-Admiral Tattersail.", ["rewardGold"] = 25740, ["rewardXP"] = 600, ["rewardItems"] = { 155093, 155094, 155095, 155112, 155113, 155114, 155115, 155116, 168442, 168578, 168920, 187175, 211279, 229365, 237812 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 138352, ["x"] = 0.584, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138365, ["x"] = 0.51, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 614, ["questLineOrder"] = 6 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 614, ["name"] = "Storming In", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 29, ["flags"] = 0 } } },
[51533] = { ["id"] = 51533, ["name"] = "The Glaive of Vol'jin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["description"] = "When fighting someone who has escaped the grasp of Bwonsamdi, as Zalazane has, it is best to bring weapons that can hurt him. In Darkspear Hold you will find the Glaive of Vol'jin . It should have enough bond with Vol'jin's spirit to aid us in this fight.", ["objectivesText"] = "Obtain the Glaive of Vol'jin . Progress: Did you find the glaive?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 160323 }, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 120173, ["x"] = 0.594, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 463, ["npcID"] = 120173, ["x"] = 0.594, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.594, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 463 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 463, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 2, ["flags"] = 0 } } },
