[51535] = { ["id"] = 51535, ["name"] = "A Veteran's Summons", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 51535 }, ["description"] = "<name>, we received word from Orgrimmar. Eitrigg has requested a meeting. Says it's important. He left a letter for you. I wouldn't keep him waiting or he might expire of old age before you find out what he wants.", ["objectivesText"] = "Meet Eitrigg at the Orgrimmar Embassy.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[51536] = { ["id"] = 51536, ["name"] = "On the Hunt", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["series"] = { 51526, 51532, 51587, 51643 }, ["description"] = "Looks like the magic the Kul Tirans used on our ships is beginning to dissipate, but I'm sure what happened to our ships here is only just the beginning. Get to the shore. We need to contact the survivors and find out just what we're up against.", ["objectivesText"] = "Search Seawatch Point for survivors.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 17687, 37226, 37382, 37435, 37513, 57316, 57317, 57318, 57319, 59256, 59257, 59258, 59259, 59284, 59285, 59286, 59287, 61124, 61125, 61126, 61127, 68644, 121802, 131202, 131518, 131546, 139902, 139932, 139962, 140002, 155383, 156945, 159038, 159039, 159040, 159041, 211279, 237812 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138365, ["x"] = 0.51, ["y"] = 0.21 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138131, ["x"] = 0.504, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.21 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 614, ["questLineOrder"] = 6 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 614, ["name"] = "Storming In", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 31, ["flags"] = 0 } } },
[51538] = { ["id"] = 51538, ["name"] = "Word from the Deep", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 48014, 48015, 48025, 48026, 49969, 51538 }, ["series"] = { 48026 }, ["description"] = "A dark soul has infiltrated the Zanchuli Council, seeking an accord with Queen Azshara. Some followed, through greed or fear. Others were too trusting and believed his lies. We fall, one by one. They will soon clear the path of resistance. Azshara's motives are hidden behind a vast darkness. She reaches into a place from where she cannot return. I would pity her, but she killed my followers... When the time comes, I will rip her apart.", ["objectivesText"] = "Share Gral's warning with the Seekers.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 156871 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 125041, ["x"] = 0.792, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5410, ["name"] = "The Sunken City", ["orderIndex"] = 7, ["flags"] = 0 } } },
[51539] = { ["id"] = 51539, ["name"] = "Inform the Horde!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51539 }, ["description"] = "This was all perpetrated by someone on the Zanchuli Council. They sacrificed their own people, Gral's followers, for Azshara. That is unconscionable! They weaken the foundation, so the kingdom will fall. One of your people must have direct access to the king. Anyone else could be the traitor.", ["objectivesText"] = "Warn Baine of the betrayal.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 125041, ["x"] = 0.792, ["y"] = 0.42 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.42 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[51540] = { ["id"] = 51540, ["name"] = "Explosive Situation", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51540 }, ["description"] = "<This crate has fallen into the water. It contains bombs built to take out large mechanical devices.> <If we had more of them, we could destroy the Venture Company's Reef Breaker.>", ["objectivesText"] = "Collect 5 Bot Buster Bombs . Progress: You'll need more of these bombs if we want to destroy the Reef Breaker.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160397, 160556 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
