[51543] = { ["id"] = 51543, ["name"] = "Saplings in the Snow", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51543 }, ["description"] = "Be wary mainlander, dangers lurk nearby. One such creature, Greenstalker, used to be an ally. In his corrupted, mindless rage he nearly killed my brother and I while we were trying to help someone in the wilds. There is something which might help but I must tend to my brother's wounds and cannot obtain the remaining item on my own. Please go onto the mountainside and pull some saplings out of the earth for me. The plants here are healthy and their roots run deep so they won't come easily.", ["objectivesText"] = "Collect 6 Mountain Saplings . Progress: Did you find the mountain saplings I need?", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 160406 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 135861, ["x"] = 0.334, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 135861, ["x"] = 0.334, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[51544] = { ["id"] = 51544, ["name"] = "Disarming the Cannons", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["description"] = "With your arrival, our salvation may have arrived. Your rowboats will serve as a way for us to evacuate the most critically injured. Unfortunately, the Horde have brought in a ship, and there's no way we can get our boats past their blockade. While the rest of us load our injured on the boats, we need you to infiltrate their ship and disable those cannons .", ["objectivesText"] = "Disable the cannons on the Horde ship. Progress: What's the status of those cannons ?", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 159779, 159910, 160249, 160433 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136197, ["x"] = 0.775, ["y"] = 0.546 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.775, ["y"] = 0.546 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 621, ["questLineOrder"] = 4 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 621, ["name"] = "Mole Machinations", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 19, ["flags"] = 0 } } },
[51545] = { ["id"] = 51545, ["name"] = "Breaker Bad", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51545 }, ["description"] = "The combined fire power of all the bombs you have collected should be able to destroy the Venture Companies Reef Breaker . It's time to act and protect the reef and this sacred cave.", ["objectivesText"] = "Destroy the Reef Breaker .", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160556 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.356, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
