[51547] = { ["id"] = 51547, ["name"] = "WANTED: Rindlewoe", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51547 }, ["description"] = "A monstrous beast of wood and flesh has been terrorizing the nearby river territories. If any adventurers are brave enough to vanquish this beast, the town of Fallhaven would gratefully proffer a reward. Please report to Mayor White if you wish to help.", ["objectivesText"] = "Defeat Rindlewoe outside of Fallhaven. Progress: Yes?", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 124417, ["x"] = 0.558, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[51552] = { ["id"] = 51552, ["name"] = "The Days Are Just Packed", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51552 }, ["description"] = "Hello there! Would you mind checking on someone for me? Sergeant Calvin was supposed to meet me here. We were going to go out looking for new alchemical reagents, but he hasn't shown up yet. I know the militia has been really busy lately so I guess he's busy, but he should still be in Brennadam Square. Would you mind checking in on him?", ["objectivesText"] = "Find Sergeant Calvin in Brennadam Square.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 133510, 155824, 155877, 156577, 156578, 156648, 157849, 157850, 160558, 160561 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130786, ["x"] = 0.639333, ["y"] = 0.611333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 130190, ["x"] = 0.576, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.639333, ["y"] = 0.611333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51554] = { ["id"] = 51554, ["name"] = "Reloading", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51554 }, ["description"] = "Daryl's making every shot count, but there's just too many Horde. We're going to need more ammo soon! I need you to take this note to my uncle Leo at Deadwash, he'll be able to help.", ["objectivesText"] = "Deliver the note to Leo Shealds .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135874, ["x"] = 0.578, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51555] = { ["id"] = 51555, ["name"] = "Keep Them On Task", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 862, ["storyline"] = { 51555 }, ["series"] = { 51246 }, ["description"] = "Princess Talanji's actions have thrown off our pursuers. Her loa is powerful indeed. We need to be certain if there were survivors, they do not gain a foothold on Zandalar. I am concerned that our Forsaken compatriots might get... overzealous. Please keep an eye on them, and remind them of what is honorable.", ["objectivesText"] = "Speak with Dennis Grimtale at Talanji's Rebuke.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 137075, ["x"] = 0.766, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.766, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9598 } }, ["questType"] = "standard" },
[51557] = { ["id"] = 51557, ["name"] = "Irontide Warning", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 51557 }, ["description"] = "Horde's taking this town! I'm not gonna stick around to watch! You could help me out though. Go see Leo Shealds in Deadwash. Tell him, Irontide is still coming and we're taking the gold!", ["objectivesText"] = "Speak to Leo Shealds at Deadwash.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
