[51582] = { ["id"] = 51582, ["name"] = "Make it Mildenhall", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51582 }, ["description"] = "You've no doubt enjoyed a mug or three of world-famous Mildenhall Mead in your local tavern. Today is your day to become a part of the official meadery of Stormsong Valley ! Ideal applicants have a hunger for craft mead, honey, and boundless innovation. Military experience recommended, but not required. Must not be allergic to bees. Mildenhall Mead - Make it Mildenhall.", ["objectivesText"] = "Speak with Ancel Mildenhall at the Mildenhall Meadery.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131793, ["x"] = 0.688, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
