[51674] = { ["id"] = 51674, ["name"] = "Douse the Flames", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["description"] = "Do you smell it, <name>? Smoke! They're burning down Warfang Hold! There is little point to our battle if our base burns to the ground! Their tidesages use wands to control their constructs of water. In our hands they may give us a chance to save the Hold! Get those wands and put out the fires before the camp burns to ash!", ["objectivesText"] = "Obtain a Fading Umbral Wand and use it to put out 4 flames around Warfang Hold. Progress: We're fortunate that the Kul Tirans have a greater affinity for water than they do for fire.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 160565 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138677, ["x"] = 0.516, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138867, ["x"] = 0.492, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 614, ["questLineOrder"] = 6 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 614, ["name"] = "Storming In", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 35, ["flags"] = 0 } } },
[51675] = { ["id"] = 51675, ["name"] = "Hunt Them Down", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["description"] = "These Kul Tirans, they don't seem normal. Humans can be a cruel bunch from what I've heard, but these ones seem to take pleasure in slaying the fallen. The worst of them was a woman wearing a peculiar mask. She seemed to be shouting orders to the others, so I guess she's their leader. Honor the fallen and ensure they and their leader don't survive.", ["objectivesText"] = "Slay Captain Ara and 8 Storm's Wake Footmen.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138688, ["x"] = 0.516, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138688, ["x"] = 0.516, ["y"] = 0.298 }, { ["mapID"] = 942, ["npcID"] = 138869, ["x"] = 0.492, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 614, ["questLineOrder"] = 6 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 614, ["name"] = "Storming In", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 33, ["flags"] = 0 } } },
