[51696] = { ["id"] = 51696, ["name"] = "Reclaiming What's Ours", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["description"] = "I'm impressed. You not only saved our people, but you also managed to kill the leader of the attacking forces. At the top of this tower is our warhorn. At the signal, our troops will come running and we'll get this hold back under our control. <name>, I think you've earned the honors.", ["objectivesText"] = "Sound the warhorn and retake control of Warfang Hold in Stormsong Valley.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138867, ["x"] = 0.492, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138876, ["x"] = 0.52, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 614, ["questLineOrder"] = 6 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 614, ["name"] = "Storming In", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 36, ["flags"] = 0 } } },
