[51711] = { ["id"] = 51711, ["name"] = "Having a Blast", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51711, 51712, 51720, 51723, 51728, 51752, 51881 }, ["description"] = "We're going to really hit 'em where it hurts, $p. They're carting tons of black powder right out of that mine. This could end very badly for all of us if we don't do something. The mines are relatively undefended, I bet you can get in and wipe out their workers before they realize what's happening. Keep an eye out for some explosives, if we can use their own tools against them, even better!", ["objectivesText"] = "Acquire a Bundle of Dynamite and use it to kill 16 Warfang Miners and 4 Mine Technicians . Progress: They won't stand a chance!", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160595, 160603, 160604, 160738 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.481333, ["y"] = 0.405333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 744, ["name"] = "Cycle of Hatred", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51712] = { ["id"] = 51712, ["name"] = "Eye for an Eye", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51711, 51712, 51720, 51723, 51728, 51752, 51881 }, ["description"] = "This is it, $p. Now is the time to strike. Take this shredder and destroy their stronghold. Burn everything to the ground! Show no mercy. They certainly didn't offer any to all of the innocent civilians they slaughtered in Brennadam!", ["objectivesText"] = "Use the Prototype Shredder to burn 8 Warfang Buildings and kill General Blackstone and 30 Horde Soldiers. Progress: Make them pay for what they've done to us.", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 160595, 160603, 160604 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.481333, ["y"] = 0.405333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 744, ["name"] = "Cycle of Hatred", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51714] = { ["id"] = 51714, ["name"] = "Mission from the King", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 47189, 51714, 51715, 52544, 52654, 53074, 53332 }, ["series"] = { 51715, 53074 }, ["description"] = "Och, good ta see ya! Feels great ta stretch me gryphon's wings above the seas. I'm here ta assist with the war effort. Happy to help! Let's go meet with Master Shaw, matey. Ha! Always wanted to say somethin' piratey. Did ya know they named a ship after me once? It was wild!", ["objectivesText"] = "Meet Spymaster Mathias Shaw on the Wind's Redemption.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135618, ["x"] = 0.702, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 615, ["name"] = "Mission from the King", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51715] = { ["id"] = 51715, ["name"] = "War of Shadows", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 47189, 51714, 51715, 52544, 52654, 53074, 53332 }, ["series"] = { 51714, 53074 }, ["description"] = "Every war is fought on multiple fronts, <class>. King Wrynn has tasked Halford Wyrmbane and his 7th Legion with securing our position in Kul Tiras as well as Zandalar. But they cannot succeed without us. We are the unseen hand. The shadows in the darkness. I have been charged with establishing an elite strike force, and I need you to act as liaison between Wyrmbane's efforts and my own. You will help direct our missions going forward. Let us begin.", ["objectivesText"] = "Send Falstad on a mission. Progress: Without us, this war would be lost easily.", ["rewardGold"] = 309800, ["rewardXP"] = 4790, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 615, ["name"] = "Mission from the King", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51717] = { ["id"] = 51717, ["name"] = "The Best Honey In Vol'dun", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "If you can handle rescuin' de others by yourself, Zulsan and I will head back to de inn and start cleanin' up de place. Don't worry, I still be cookin' up a special batch of my famous scorpid blood drinks for you. In fact, you gonna be runnin' right past my friend Rikati . He sells de best honey in all of Vol'dun ! Bring back a few bottles of it for me and let's add some sweetness to de drinks!", ["objectivesText"] = "Meet Rikati at The Four Stingers.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 163567 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 122723, ["x"] = 0.435, ["y"] = 0.602 }, { ["mapID"] = 864, ["npcID"] = 138749, ["x"] = 0.382, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 133833, ["x"] = 0.404, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.602 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 5, ["flags"] = 0 } } },
[51718] = { ["id"] = 51718, ["name"] = "Harvesting \"Honey\"", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47497, 47498, 47501, 47502, 47503, 47564, 47638, 48320, 48321, 48322, 48840, 50328, 51717, 51718 }, ["description"] = "I don't know what Rhan'ka's doing down in that oasis with all of the honey he's bought from me. Frankly, I suspect I don't even want to know. But whatever his reasons, Rhan'ka is my best customer. So even though my supply's getting low, because Rhan'ka sent you, I'll give you a special deal. The wasps here keep all their honey stored in their stingers. Bring some to me, so I can drain them for honey and I'll give you a big batch of the sticky stuff to take back to Rhan'ka.", ["objectivesText"] = "Collect 12 Bilewing Stingers . Progress: Don't fret if some sand gets mixed in. It'll taste the same either way.", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 157541 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 133833, ["x"] = 0.404, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 133833, ["x"] = 0.404, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5426, ["name"] = "Goldtusk Inn", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51720] = { ["id"] = 51720, ["name"] = "Get Shredded", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51711, 51712, 51720, 51723, 51728, 51752, 51881 }, ["description"] = "I was scouting ahead while you were wreaking havoc in the mine. Spotted a hulking, armored shredder in their lumber yard. Bet we could do some real damage with that thing! I tried to start it up, but looks like it might be out of juice. Maybe they forgot to charge it? See if you can grab a fresh power core from one of the other shredders nearby.", ["objectivesText"] = "Find an Energized Power Core and install it in the Prototype Shredder MK-03 . Progress: < Energized Core required.>", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160593, 160595, 160603, 160604 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138777, ["x"] = 0.512, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.481333, ["y"] = 0.405333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 744, ["name"] = "Cycle of Hatred", ["orderIndex"] = 4, ["flags"] = 0 } } },
[51723] = { ["id"] = 51723, ["name"] = "Saw Dusted", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51711, 51712, 51720, 51723, 51728, 51752, 51881 }, ["description"] = "If we want to keep them from expanding into Stormsong, we need to cripple their lumber production! They've only got so many lumberjacks running around. If we can cut some of them down, they'll be forced to reconsider their plans.", ["objectivesText"] = "Kill 10 Warfang Lumberjacks . Progress: How many d'ya get?", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 69777, 160595, 160603, 160604 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.481333, ["y"] = 0.405333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 744, ["name"] = "Cycle of Hatred", ["orderIndex"] = 5, ["flags"] = 0 } } },
[51726] = { ["id"] = 51726, ["name"] = "Get Out of Here", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9698, ["storyline"] = { 51726 }, ["description"] = "I can't believe you're here. Please, we need help! They've been forcing us to mine nonstop. The weakest among us have been steadily dropping. At this rate, we'll all be dead soon. The chains are weak. You may be able to pry the lock apart. I'll keep a lookout until the others are free. Don't worry about me!", ["objectivesText"] = "Free 6 Captured Miners . Progress: Did you free everyone?", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["rewardItems"] = { 37047, 37049, 37528, 57360, 57361, 57362, 160595, 160603, 160604, 181501, 181502, 181507, 181625, 181626, 181645, 181647, 181649, 181688, 181689, 181691, 181693, 181697, 181865, 183490, 184195, 184305, 184772, 184773, 184774, 184775, 184776, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9698 } }, ["questType"] = "standard" },
[51728] = { ["id"] = 51728, ["name"] = "Burn It All Down", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51711, 51712, 51720, 51723, 51728, 51752, 51881 }, ["description"] = "Alright, the flamethrower is all patched up. Now we're going to get a little payback for Brennadam! If it's flammable, it's a target. If not, well, it probably still needs to die anyway. And let's bring down those siege towers while we're at it. Burn it all to the ground!", ["objectivesText"] = "Burn 6 Lumber Piles and 2 Siege Towers . Progress: Well at least the flamethrower hasn't blown up on ya yet.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 160595, 160603, 160604, 211279 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.481333, ["y"] = 0.405333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 744, ["name"] = "Cycle of Hatred", ["orderIndex"] = 3, ["flags"] = 0 } } },
