[51770] = { ["id"] = 51770, ["name"] = "Mission from the Warchief", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47332, 51770, 51771, 52746, 52749, 53079, 53333 }, ["series"] = { 51771, 53079 }, ["description"] = "Lady Sylvanas issued orders for Garona Halforcen to take on a task of great import. She will orchestrate missions from the Banshee's Wail, and is to assemble a strong force to execute on our plans. This effort will be vital to our war against the Alliance, and your assistance will certainly be necessary.", ["objectivesText"] = "Walk with Garona Halforcen belowdecks on the Banshee's Wail.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 138708, ["x"] = 0.584, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 618, ["name"] = "Mission from the Warchief", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51771] = { ["id"] = 51771, ["name"] = "War of Shadows", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 862, ["storyline"] = { 47332, 51770, 51771, 52746, 52749, 53079, 53333 }, ["series"] = { 51770, 53079 }, ["description"] = "I have begun to assemble heroes for our cause. Perhaps you already know Arcanist Valtrois? We will need to recruit more in the future, but this is a promising beginning. Our missions will be those of subterfuge, reconnaissance, assassination, and other focused strikes against our enemies. Let us test the mettle of this nightborne, shall we?", ["objectivesText"] = "Send Arcanist Valtrois on a mission. Progress: I will not deviate from my mission.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 138708, ["x"] = 0.584, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 138708, ["x"] = 0.584, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 618, ["name"] = "Mission from the Warchief", ["orderIndex"] = 4, ["flags"] = 0 } } },
[51772] = { ["id"] = 51772, ["name"] = "The Tortaka Tribe", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51772 }, ["series"] = { 47577 }, ["description"] = "Have you ever met a tortollan before? Dey have all kinds of useful scrolls and artifacts for sale. We used to trade often with de Tortaka tribe, but we haven't seen or heard from dem in weeks. De tribe has a village in Darkwood Shoal. We need someone to make contact with dem and reestablish our trading partnership.", ["objectivesText"] = "Meet with Torka .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126108, ["x"] = 0.436, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 134098, ["x"] = 0.62, ["y"] = 0.222 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[51773] = { ["id"] = 51773, ["name"] = "The Ashvane Threat", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51773 }, ["series"] = { 47870 }, ["description"] = "De Ashvane Trading Company has a mining operation in Redrock Harbor. Don't let de fancy name fool you, dey are as dangerous a band of pirates as I've ever seen. Recently, one of their crew members has been trying to make contact with us. I need someone to meet with him and see what he wants. It might be a trap, but whatever information he has on de Ashvane Trading Company could prove useful to our survival.", ["objectivesText"] = "Meet with Randall Redmond .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126576, ["x"] = 0.434, ["y"] = 0.747 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 124468, ["x"] = 0.451, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.434, ["y"] = 0.747 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
