[51775] = { ["id"] = 51775, ["name"] = "Camp Lastwind", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 51775 }, ["series"] = { 48324 }, ["description"] = "A vulpera caravan recently set up camp not far from here. Dis could be a good opportunity to establish new trade partners with de tribe. De desert is a dangerous place, <name>. Go see if dey need any assistance. I'm sure dey could use experienced hands like yours. In exchange, perhaps dey'd be willing to offer de tribe a discount on goods and services.", ["objectivesText"] = "Speak with Norah .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 126085, ["x"] = 0.422, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 125904, ["x"] = 0.388, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
