[51784] = { ["id"] = 51784, ["name"] = "A Stroll Through a Cemetery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51784, 51785, 51786, 51787, 51788, 51789, 53065 }, ["series"] = { 53065 }, ["description"] = "Our next stop is in Drustvar. There, along with some help, we shall identify and extract the body of a Kul Tiran war hero. With his aid, we will learn much of the Kul Tiran fleet. Enough to break it with ease. We shall meet you outside Barrowknoll Cemetery. Do try not to waste time, would you?", ["objectivesText"] = "Meet Nathanos Blightcaller outside Barrowknoll Cemetery. Dread-Admiral Tattersail can bring you to Drustvar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 896 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 11 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 626, ["name"] = "The Marshal's Grave", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51785] = { ["id"] = 51785, ["name"] = "Examining the Epitaphs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51784, 51785, 51786, 51787, 51788, 51789, 53065 }, ["description"] = "Without Stone's knowledge, this mission shall require some extra legwork. Read the plaques in the cemetery. Find the corpse of the most import. The rest should be quite simple.", ["objectivesText"] = "Examine 4 Grave Plaques in Barrowknoll Cemetery.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 11 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 626, ["name"] = "The Marshal's Grave", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51786] = { ["id"] = 51786, ["name"] = "State of Unrest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51784, 51785, 51786, 51787, 51788, 51789, 53065 }, ["description"] = "There is one thing you should know about ghosts, <name>. They are a mockery of the dead. Spirits, holding on although they have no hope. In that form, they shall never truly live again. Not as long as they keep haunting our world. But if they return to their bodies, perhaps they will become of specific use to us someday down the line. Put those spirits down.", ["objectivesText"] = "Kill 8 Enraged Spirits .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 11 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 626, ["name"] = "The Marshal's Grave", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51787] = { ["id"] = 51787, ["name"] = "Our Lot in Life", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51784, 51785, 51786, 51787, 51788, 51789, 53065 }, ["description"] = "It seems that Amalia isn't taking to undeath well. I know an herb that may help. This cemetery is crawling with gravebloom . For the living, it grants the ability to see spirits. As for the undead... This may tie her back to reality just enough to be... sane.", ["objectivesText"] = "Collect 10 Gravebloom . Progress: What Amalia is going through... is familiar to me. She will learn how to embrace her new status as Forsaken. I will help.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 152480 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139062, ["x"] = 0.612, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139062, ["x"] = 0.612, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 11 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 626, ["name"] = "The Marshal's Grave", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51788] = { ["id"] = 51788, ["name"] = "The Crypt Keeper", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51784, 51785, 51786, 51787, 51788, 51789, 53065 }, ["series"] = { 51789 }, ["description"] = "I've been keeping my sights on the cemetery. There is one ghost that walks with a purpose, unlike the others. He is the crypt keeper, the keeper of the keys. If we want to get to Valentine's body, we will need to go through the ghost first.", ["objectivesText"] = "Collect Valentine's Key from Brutus Thornton. Progress: Nothing can stand in our way. Not today.", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 160736 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 11 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 626, ["name"] = "The Marshal's Grave", ["orderIndex"] = 4, ["flags"] = 0 } } },
[51789] = { ["id"] = 51789, ["name"] = "What Remains of Marshal M. Valentine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 51784, 51785, 51786, 51787, 51788, 51789, 53065 }, ["series"] = { 51788 }, ["description"] = "We have the key. We found the crypt. Next, Valentine's body shall be ours. No need to wait for Lilian and Stone. Let's finish this now.", ["objectivesText"] = "Assist Nathanos Blightcaller in retrieving Valentine's body. Progress: No time to dally. We have plans to enact.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 160939 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139061, ["x"] = 0.614, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 11 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 626, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 626, ["name"] = "The Marshal's Grave", ["orderIndex"] = 5, ["flags"] = 0 } } },
[51797] = { ["id"] = 51797, ["name"] = "Tracking Tidesages", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51797, 51798, 51805, 51818, 51819, 51830, 51837, 52122, 53066 }, ["series"] = { 51798, 53066 }, ["description"] = "Rexxar has been tracking a powerful tidesage to help us find the body of Marshal Valentine. He has sent word of a breakthrough. Travel to Stormsong. Help the half-ogre and Lilian find this tidesage, and bend him to the will of the Horde. Do not come back without a way to find Marshal Valentine.", ["objectivesText"] = "Meet Rexxar within Warfang Hold in Stormsong.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138876, ["x"] = 0.52, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 12 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 627, ["name"] = "Death of a Tidesage", ["orderIndex"] = 0, ["flags"] = 0 } } },
[51798] = { ["id"] = 51798, ["name"] = "No Price Too High", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51797, 51798, 51805, 51818, 51819, 51830, 51837, 52122, 53066 }, ["series"] = { 51797, 53066 }, ["description"] = "I have tracked a tidesage to a camp nearby. He has been staying there with his family. Be warned, tidesages are powerful foes. They have mastery over all the elements, and some even manipulate the Void. If this man is with his family, it means he may not give up so easily. Let us hope he's smart enough to keep them out of this. Come.", ["objectivesText"] = "Help Rexxar track down a tidesage.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138876, ["x"] = 0.52, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 139101, ["x"] = 0.579333, ["y"] = 0.318667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 12 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 627, ["name"] = "Death of a Tidesage", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51800] = { ["id"] = 51800, ["name"] = "Foothold: Tiragarde Sound", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["description"] = "Tiragarde Sound has lotsa pirates on da coastline. I made contact wit' a first mate of a crew, and she tinks we can take on da captain and get a nice outpost in de process. - Shadow Hunter Ty'jin", ["objectivesText"] = "Assist Shadow-Hunter Ty'jin in Tiragarde Sound.", ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 148, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51801] = { ["id"] = 51801, ["name"] = "Foothold: Drustvar", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["description"] = "It seems Drustvar has a big seam of Azerite underground. Do you like profit? I LOVE profit. This seems like a golden opportunity, if ya catch my meanin'. Time is money! - Trade Prince Gallywix", ["objectivesText"] = "Assist Gallywix and Eitrigg in Drustvar.", ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 149, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 8, ["flags"] = 0 } } },
[51802] = { ["id"] = 51802, ["name"] = "Foothold: Stormsong Valley", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "none", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["description"] = "We established and fortified an outpost in Stormsong Valley called Warfang Hold. The Kul Tiran forces have it surrounded and an attack is imminent. We need reinforcements. Do not delay. - Rexxar", ["objectivesText"] = "Assist Rexxar in Stormsong Valley.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2AdventureMapPoiID"] = 150, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 7, ["flags"] = 0 } } },
[51803] = { ["id"] = 51803, ["name"] = "The Kul Tiras Campaign", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["description"] = "Our enemy spreads its influence throughout Kul Tiras, recruiting new allies to fight against the Horde. We must establish footholds in these enemy lands if we are to win this war. The Warchief requires your assistance in securing outposts in Stormsong Valley, Drustvar, and Tiragarde Sound. Which location shall we secure first?", ["objectivesText"] = "Use the Kul Tiras Campaign Map to choose a foothold.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 1, ["flags"] = 0 } } },
[51805] = { ["id"] = 51805, ["name"] = "They Will Know Fear", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51797, 51798, 51805, 51818, 51819, 51830, 51837, 52122, 53066 }, ["description"] = "Finally, a chance to strike at the Alliance AND Kul Tirans! Sagehold is crawling with initiate tidesages studying magic and Kul Tirans trying to fortify the place against the Horde. Let's strike some fear into them. Make them rethink trying to help the Alliance fight the Horde. Take this horn. In my hands, it calls a val'kyr. In yours, it will sow terror amongst our enemies. I trust you above all others with this horn. Do not let me down.", ["objectivesText"] = "Terrorize 20 Kul Tiran Builders or Tidesage Recruits with the Val'kyr Horn .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 160901 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 139101, ["x"] = 0.579333, ["y"] = 0.318667 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 139101, ["x"] = 0.579333, ["y"] = 0.318667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.579333, ["y"] = 0.318667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 12 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 627, ["name"] = "Death of a Tidesage", ["orderIndex"] = 2, ["flags"] = 0 } } },
