[51810] = { ["id"] = 51810, ["name"] = "Captain Hartford", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 47870, 47871, 47873, 51810 }, ["description"] = "I'm almost ready to leave Vol'dun once and for all. There's just one thing left to be done... We need to murder the captain of the ship. If Captain Hartford finds out I've deserted, I won't be safe in Boralus or anywhere else. He'll hunt me to the Eastern Kingdoms and back if he has to! This will be dangerous. So you'll want to disguise yourself before boarding The Siren's Call. This will be our last job together. Do it and I'll give you the code to the captain's lockbox. A pirate's bounty!", ["objectivesText"] = "Slay Captain Hartford .", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["rewardItems"] = { 160735 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 124468, ["x"] = 0.451, ["y"] = 0.846 }, { ["mapID"] = 864, ["npcID"] = 139069, ["x"] = 0.446, ["y"] = 0.868 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139070, ["x"] = 0.432, ["y"] = 0.908 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.451, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5423, ["name"] = "Ashvane Antics", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51813] = { ["id"] = 51813, ["name"] = "Blackrock Depths", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 51474, 51813, 53342, 53351, 53352, 53566 }, ["series"] = { 51474, 53342, 53351, 53352, 53566 }, ["description"] = "Have you heard how the Dark Iron dwarves joined the Alliance? It was a most unusual turn of events. Brave heroes of the Alliance had been fighting the Dark Iron dwarves for years until a schism happened in their ranks. Moira Thaurissian, estranged daughter of the former dwarven king Magni Bronzebeard, was leading a faction of the Dark Iron dwarves. Moira wished to aid the Alliance. This began with an offer to help research Azerite and its potential uses within Blackrock Depths...", ["objectivesText"] = "Speak with Moira at the Stormwind Embassy to travel to Blackrock Depths. Progress: The mind o' a <race> is a glorious thing.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 142357, 174360, 232471, 232877 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 }, { ["mapID"] = 84, ["npcID"] = 133197, ["x"] = 0.52, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5235, ["y"] = 0.1355 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1932, ["db2PoiUiMapID"] = 1159, ["questLines"] = { { ["id"] = 781, ["name"] = "Allies of the Alliance: Dark Iron Dwarf", ["orderIndex"] = 0, ["flags"] = 0 } } },
