[51819] = { ["id"] = 51819, ["name"] = "Scattering Our Enemies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51797, 51798, 51805, 51818, 51819, 51830, 51837, 52122, 53066 }, ["description"] = "We've been scouting the area of Sagehold for some time now. It was recently retaken by a large force of Alliance and Kul Tirans. We have been waiting for an opportunity to strike when their defenses were weakened. Now is that time. Go down to Sagehold and show the forces that remain what happens to those who take up arms against the Horde.", ["objectivesText"] = "Kill 10 Alliance and Kul Tiran soldiers within Sagehold.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 139102, ["x"] = 0.61, ["y"] = 0.311 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 139102, ["x"] = 0.61, ["y"] = 0.311 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.311 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 12 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 627, ["name"] = "Death of a Tidesage", ["orderIndex"] = 4, ["flags"] = 0 } } },
