[51979] = { ["id"] = 51979, ["name"] = "The Ongoing Campaign", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["series"] = { 53050 }, ["description"] = "The Warchief wishes for us to continue spreading our influence throughout Kul Tiras. With our grip on Zandalar on the rise, now is the time to move forward with this objective in the lands of the enemy. Which location shall we secure next, <class>?", ["objectivesText"] = "Use the Kul Tiras Campaign Map to choose a foothold.", ["rewardGold"] = 280900, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 2, ["flags"] = 0 } } },
[51980] = { ["id"] = 51980, ["name"] = "WANTED: Jabra'kan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51980 }, ["description"] = "To any hunters worthy of the challenge: Find and defeat the troll known as Jabra'kan. His poaching ways have robbed Warbeast Kraal of valuable eggs, hides, and beasts for their pens. Seek out Wingrider Nivek for your reward.", ["objectivesText"] = "Slay Jabra'kan the Poacher . Progress: If I see dat thieving wretch, I will wear his tusks for a necklace. Is it done?", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 125486, ["x"] = 0.69, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.69, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "group" },
[51982] = { ["id"] = 51982, ["name"] = "Storm's Rage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51982 }, ["description"] = "Horde forces are pushing deeper into Stormsong Valley. We can not allow this aggression to go unchecked!", ["objectivesText"] = "Repel the Horde forces assaulting Stormsong Valley. Progress: We cannot rest until the people of Stormsong Valley are protected from the Horde!", ["rewardXP"] = 2125, ["rewardItems"] = { 165872, 166459, 166792 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135800, ["x"] = 0.592, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[51984] = { ["id"] = 51984, ["name"] = "Return to Zuldazar", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51975, 51984 }, ["description"] = "Look at dis place, boss-mon! We got da pirates, a location close to da Kul Tiran capital... I tink we should be bein' pretty proud of dis one. We should get goin' back and tell Nathanos about our success. Maybe we can even get him to crack a smile.", ["objectivesText"] = "Return to Nathanos Blightcaller on the Banshee's Wail. Erul Dawnbrook can give you a ride.", ["rewardGold"] = 25740, ["rewardXP"] = 600, ["rewardItems"] = { 163664, 163665, 163666, 163667, 163668, 163669, 163670, 163671, 163672, 163673, 163674, 163675, 245465 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 137742, ["x"] = 0.872, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.872, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 622, ["questLineOrder"] = 7 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 622, ["name"] = "A Pirate's Life for We", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 19, ["flags"] = 0 } } },
[51985] = { ["id"] = 51985, ["name"] = "Return to Zuldazar", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51985, 51987 }, ["description"] = "You know kid, I think I've got it all covered here. My guys will find all the Azerite they can here and make me rich! I mean, you know, make the Horde rich. With power! Anyway, you can go tell Nathanos we're done here. This base is the best place to launch any attacks against the Kul Tirans here in Drustvar -- that's a Gallywix guarantee!", ["objectivesText"] = "Return to Nathanos Blightcaller on the Banshee's Wail. Swellthrasher in Anyport can give you a ride.", ["rewardGold"] = 25740, ["rewardXP"] = 600, ["rewardItems"] = { 163664, 163665, 163666, 163667, 163668, 163669, 163670, 163671, 163672, 163673, 163674, 163675, 245475 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 604, ["questLineOrder"] = 5 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 604, ["name"] = "Drustvar Foothold", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 27, ["flags"] = 0 } } },
[51986] = { ["id"] = 51986, ["name"] = "Return to Zuldazar", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["series"] = { 51753 }, ["description"] = "Warfang Hold is our most secured of the footholds we hold in Kul Tiras. Kaga and her forces will be able to keep fortifications running, thanks to you. The Alliance will never see us coming! Tell Nathanos that we have succeeded in our mission. I will help here until I am needed.", ["objectivesText"] = "Return to Nathanos Blightcaller on the Banshee's Wail. Muka Stormbreaker can give you a ride.", ["rewardGold"] = 30900, ["rewardXP"] = 600, ["rewardItems"] = { 163664, 163665, 163666, 163667, 163668, 163669, 163670, 163671, 163672, 163673, 163674, 163675, 245473 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138876, ["x"] = 0.52, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 614, ["questLineOrder"] = 6 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 614, ["name"] = "Storming In", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 38, ["flags"] = 0 } } },
