[51990] = { ["id"] = 51990, ["name"] = "Wings for the Kraal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "It seems your little one needs a moment to rest after dat adventure. I will look after it. If you want to make yourself useful while you wait, I heard de pterrordaxes to de north have been laying lots of eggs recently. Go collect de ones dat are wiggling and making noises. Dey are about to hatch. Our beasts breed well, but we always need more wings for de kraal.", ["objectivesText"] = "Collect 8 Nearly-hatchling Pterrordax Eggs. Progress: Do you have de eggs I asked for?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 150272, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 6, ["flags"] = 0 } } },
[51991] = { ["id"] = 51991, ["name"] = "Charging the Batteries", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50771, 50775, 50812, 51991, 52129 }, ["series"] = { 52129 }, ["description"] = "These little fellas are ravenous whirlwinds of devouring destruction. When they get going, they consume anything in their path, without even stopping! When sated, they discharge power from them little 'lectric zingers on their heads! Then they nap. Lucky for us, we found just the right frequency to control their tiny bug brains. Hit that device, and you can take your own little zapper out for a spin... literally! Make sure ya bring it back full, so we can keep our rigs charged!", ["objectivesText"] = "Fill that ranishu's belly. Progress: All juiced up?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 140046, ["x"] = 0.285, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 140046, ["x"] = 0.285, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.285, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5421, ["name"] = "For Profit", ["orderIndex"] = 3, ["flags"] = 0 } } },
[51998] = { ["id"] = 51998, ["name"] = "DGH: Now With Real Direhorn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47226, 47259, 47261, 47272, 47310, 47311, 47312, 47418, 48527, 48581, 51990, 51998 }, ["description"] = "...Listen, <name>. I need one more thing to finish making this supplement of mine. Direhorn Growth Hormone can't exactly be made without, you know, actual direhorn. But I floated the idea of harvesting a few of their beasts and all of a sudden I got a bunch of spears pointed at me. So I came up with another plan. Those flying beasts eat direhorns, right? The big green flappy ones. I'm sure if you kill a few of them you'll find all the direhorn bits I need.", ["objectivesText"] = "Collect 8 Partially-Digested Direhorn Flesh. Progress: We'll keep this between you and me, okay?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 159146, 160975 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5402, ["name"] = "Warbeast Kraal", ["orderIndex"] = 7, ["flags"] = 0 } } },
