[52005] = { ["id"] = 52005, ["name"] = "Mission Report: The Wolf's Den", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52005 }, ["series"] = { 52127 }, ["description"] = "<Your followers have sent a report regarding the assault on Wolf's Den. It details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.>", ["objectivesText"] = "Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Tiragarde Sound?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 161121, 161152, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163507 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["startItems"] = { 160986 } },
