[52012] = { ["id"] = 52012, ["name"] = "Wolves For The Den", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 52012 }, ["description"] = "Our scouts have spotted a large pack of dire wolves not far from here. This is a good omen! We should send a beast master to capture the wolf pack and bring them to the outpost to be tamed. The dire wolves will make fine hunting companions and sniff out any Alliance spies that come poking around!", ["objectivesText"] = "Complete the mission, \"Wolves For The Den.\"", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 139561, ["x"] = 0.624, ["y"] = 0.125 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 139561, ["x"] = 0.624, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["startItems"] = { 160991 } },
[52013] = { ["id"] = 52013, ["name"] = "Champion: John J. Keeshan", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 139609, ["x"] = 0.565, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 139609, ["x"] = 0.565, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 603, ["questLineOrder"] = 5 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 603, ["name"] = "Heart of Darkness", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 50, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 51, ["flags"] = 0 } } },
[52014] = { ["id"] = 52014, ["name"] = "Ritualistic Preparations", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52014, 52015 }, ["series"] = { 51568, 51575 }, ["description"] = "I have received a request for a shipment of storm silver. It is a fine metal, lightweight and resistant to corrosion. We use it althroughout our ships. It is so strong even de naga use it in some of their weapons! However, any parts that go into de ship have to be blessed by a wavesinger. I can not be bothered with dat nonsense. I do not believe it needs these extra blessings, but what do I know? Harvest a bucketful of ore and get it blessed for me, and I will teach you how to mine it easier.", ["objectivesText"] = "Mine Unsanctified Storm Silver Ore , smelt it into Unsanctified Storm Silver Bars, and get them blessed by Wavesinger De'zan. Progress: Did you get those storm silver bars? Don't forget dat it needs to be blessed. Otherwise dey are 'land metal' and will curse a ship.", ["rewardItems"] = { 87216, 152512, 152513, 152579, 160440, 160974, 161078, 161088, 161133 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122694, ["x"] = 0.44, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122694, ["x"] = 0.44, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 765, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Deposit - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52015] = { ["id"] = 52015, ["name"] = "Brined Justice", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52014, 52015 }, ["description"] = "<name>, I just got word dat one of our ships was attacked and a large amount of storm silver stolen! De sacred materials can not be replaced. Once it is blessed by de wavesinger, it is buried underwater for a year. While I do not care for such nonsense, others do, and will not sail on dat ship. From what I heard, a group of naga followed de ship to see where the metal was buried on de sea floor before killing de crew and taking her cargo. Kill de naga, and get me dat metal!", ["objectivesText"] = "Collect 100 Stolen Storm Silver Bars . Progress: Loa damn de naga! Have you found de bars?", ["rewardItems"] = { 152512, 152513, 152579, 160453, 161078, 161088 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122694, ["x"] = 0.44, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122694, ["x"] = 0.44, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 765, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Deposit - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52016] = { ["id"] = 52016, ["name"] = "Three Sheets to the Wind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52016, 52017, 52043 }, ["description"] = "You want to know more about storm silver? Fine, if you are mining from a seam and make a mistake, you can make a deadly cloud of powderized metal. Now go. <After a moment Secott's face softens.> I am very busy, but if you insist on not dying, you should talk to my former apprentice, Biru. He is a drunk at Spirits Be With You, but he has some knowledge. Talk to Ximo, de Innkeeper, and buy him a drink. If he likes it, he'll talk, if not... well, I hope you have enough coin for more drinks.", ["objectivesText"] = "Bring Biru The Drunk a drink he likes to learn his mining secrets. Progress: <Secott's former apprentice, Biru, drunkenly stares at you.> Whadda you wan?", ["rewardItems"] = { 152512, 152513, 152579, 161078, 161088, 162574 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122694, ["x"] = 0.44, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 139634, ["x"] = 0.525, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 766, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Seam - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52017] = { ["id"] = 52017, ["name"] = "Back to Biru", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52016, 52017, 52043 }, ["description"] = "Oh, you are still here? Well, I wish I could help you but being de only goldsmith in de city of gold, I am unsurprisingly busy. I heard you had built a rapport with Biru. I'm sure he remembers more, if you're still looking for more information. Ask him if he can show you anything else. Tell him if he keeps you from bothering me for the rest of de day, I will stop sending fool hardy miners to him.", ["objectivesText"] = "Speak with Biru The Drunk .", ["rewardItems"] = { 152512, 152513, 152579, 161078, 161088 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122694, ["x"] = 0.44, ["y"] = 0.39 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 139634, ["x"] = 0.525, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 766, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Seam - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52023] = { ["id"] = 52023, ["name"] = "Informing the Horde", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts. Were it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive. We must inform our allies of what has transpired in Vol'dun . I'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now. I'm sure our paths will cross again, <name>. It was an honor fighting with you.", ["objectivesText"] = "Speak with Baine Bloodhoof .", ["rewardGold"] = 509400, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 64, ["flags"] = 0 } } },
[52024] = { ["id"] = 52024, ["name"] = "Informing the Horde", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 862, ["storyline"] = { 47313, 47314, 47315, 47316, 47317, 47319, 47320, 47321, 47324, 47327, 47513, 47716, 47874, 47959, 48313, 48314, 48315, 48549, 48550, 48684, 48715, 48887, 48888, 48889, 48894, 48895, 48896, 48987, 48988, 48991, 48992, 48993, 48996, 49003, 49005, 49141, 49327, 49334, 49340, 49662, 49664, 49665, 49666, 49676, 49677, 50539, 50550, 50561, 50617, 50641, 50702, 50703, 50745, 50746, 50748, 50750, 50751, 50752, 50770, 50904, 50913, 51357, 51364, 51574, 52023, 52024 }, ["description"] = "General Jakra'zet has been defeated, but his plan to summon Mythrax succeeded despite our best efforts. Were it not for the mercy of Sethraliss, I doubt we would have made it out of Atul'Aman alive. We must inform our allies of what has transpired in Vol'dun . I'll speak with princess Talanji myself. You should go and speak with the Horde. We need all the help we can get now. I'm sure our paths will cross again, <name>. It was an honor fighting with you.", ["objectivesText"] = "Speak with Baine Bloodhoof.", ["rewardGold"] = 509400, ["rewardXP"] = 515, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 226, ["title"] = "Battle for Azeroth", ["questLineID"] = 5391, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5391, ["name"] = "Dunes of Vol'dun", ["orderIndex"] = 65, ["flags"] = 0 } } },
[52026] = { ["id"] = 52026, ["name"] = "Overseas Assassination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "Ready to go to war, <name>? Mathias Shaw has assembled a list of priority Horde targets, and the first is an influential blood elf by the name of Arlethal Sunwatcher. Intelligence shows that he's the highest ranking member of the Reliquary, an elite blood elf excavation force. He's just standing out in the middle of the desert in Vol'dun, practically begging to be assassinated. Shall we?", ["objectivesText"] = "Speak with Grand Admiral Jes-Tereth to sail to Vol'dun.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 158075, 161086, 161087, 161240, 161241, 161333, 172812 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 864, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52027] = { ["id"] = 52027, ["name"] = "The Vol'dun Plan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "Our target: Arlethal Sunwatcher, High Examiner of the Reliquary. Before we charge off blindly into the dunes, however, I'd like to hold a quick strategy meeting with you and the others.", ["objectivesText"] = "Discuss strategy with Halford Wyrmbane and Shandris Feathermoon. Progress: Let's talk strategy, <name>.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.618667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52028] = { ["id"] = 52028, ["name"] = "Comb the Desert", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "It's time to mobilize, then. I'll stick with you, <name>. Keep an eye out for Horde activity.", ["objectivesText"] = "Search Vol'dun for Horde activity.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.618667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52029] = { ["id"] = 52029, ["name"] = "Dirty Work", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "That surveyor is wearing a Reliquary tabard. Sunwatcher must be hiring goblins to do his dirty work while he lounges somewhere in the shade. <Shandris nocks an arrow in her bow.> Let's find out what she knows.", ["objectivesText"] = "Slay Nazlara and find out what she knows. Progress: What is that goblin up to?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.38075, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52030] = { ["id"] = 52030, ["name"] = "Keep Combing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "Guzbert will be busy planting explosives for a while. We should continue south, looking for more signs of the Horde.", ["objectivesText"] = "Search for more signs of the Horde.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.618667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 4, ["flags"] = 0 } } },
[52031] = { ["id"] = 52031, ["name"] = "Classic Reliquary", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "Another goblin surveyor, and this one's reporting to a blood elf overseer of some sort. We're closing in on them, <name>. You know the drill.", ["objectivesText"] = "Help Shandris assassinate Elisa Veilsong and Daxx Bombhand, then find out what they know. Progress: Sunwatcher will be ours soon.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.38075, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 5, ["flags"] = 0 } } },
