[52033] = { ["id"] = 52033, ["name"] = "WANTED: The Rime Huntress", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 52033 }, ["description"] = "The Waycrest Guard is offering a reward for any hunter who can track down and eliminate the Rime Huntress from the vicinity of Highroad Pass. Track her with caution. She is a ferocious beast, and has been known to ambush even seasoned hunters.", ["objectivesText"] = "Defeat The Rime Huntress near Highroad Pass.", ["rewardGold"] = 619600, ["rewardXP"] = 3455, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139714, ["x"] = 0.372, ["y"] = 0.494 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.494 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[52034] = { ["id"] = 52034, ["name"] = "A Message to the Zandalari", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "I know we're here to hunt the Horde, but this is an opportunity. Exiles or not, these are Zandalari trolls, and the Zandalari have all but put in their lot with the Horde. Let's show them what we do to friends of the Horde.", ["objectivesText"] = "Slay 12 Zandalari Exiles .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.38075, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 7, ["flags"] = 0 } } },
[52035] = { ["id"] = 52035, ["name"] = "Improvised Survival", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "The entirety of our copter's hold was reserved for bombs. There's actually still a lot of bombs left inside. Unfortunately, that meant that we weren't able to pack sufficient water and rations for our survival. Desert natives hoard supplies efficiently. I'm certain the Zandalari trolls up ahead wouldn't miss a few lost supplies.", ["objectivesText"] = "Gather 15 Zandalari Water Jugs and 15 Zandalari Rations. Progress: <Halford nods sternly at you.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.618667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 8, ["flags"] = 0 } } },
[52036] = { ["id"] = 52036, ["name"] = "They Have Alpacas Here", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "Did you see? Did you see them? The floofy alpacas?! I'VE ALWAYS WANTED A... I mean, ahh, ahem! I would like to acquire an alpaca. To study. For scientific reasons. Nothing to do with floofiness at all. Here, this should help you wrangle one back here.", ["objectivesText"] = "Use the Ultra-Safe Electrified Alpaca Lasso to obtain a Lost Alpaca, then bring it back to Explosioneer Zoidfuse . Progress: So... floofy...", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139722, ["x"] = 0.398, ["y"] = 0.52 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139722, ["x"] = 0.398, ["y"] = 0.52 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.52 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 9, ["flags"] = 0 } } },
[52038] = { ["id"] = 52038, ["name"] = "Splitting Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "<Halford looks over the map again.> The final Reliquary digsite is southwest of here. <name>, you and Shandris are responsible for laying the explosives at the digsite. I'll work with Zoidfuse to establish a safe position to detonate from.", ["objectivesText"] = "Continue traveling southwest across the desert.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333, 232762, 232763 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.618667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 10, ["flags"] = 0 } } },
[52039] = { ["id"] = 52039, ["name"] = "Delayed Deathification", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "While we can handle the assassination portion on our own, I suppose there's no harm in distributing these gnomish bombs around the enemy's digsite. They're designed to be detonated remotely, so try to bury them in the sand where they won't be noticed.", ["objectivesText"] = "Bury 8 Remote-Detonation Deathbombs . Progress: I hope you left them somewhere inconspicuous.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.38075, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 11, ["flags"] = 0 } } },
[52040] = { ["id"] = 52040, ["name"] = "Full of Arrows", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "There's no need for Halford's overly-complicated desert explosion operation. We can take care of Arlethal Sunwatcher right here and now. He's right over there. We can just... kill him. You engage him. I'll join in when he least expects it. You ready?", ["objectivesText"] = "Slay Arlethal Sunwatcher with Shandris. Progress: Whenever you're ready, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.38075, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 12, ["flags"] = 0 } } },
[52041] = { ["id"] = 52041, ["name"] = "Report to Wyrmbane", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "Our work here is done. Halford and Zoidfuse should be further down the coast, to the east. If you don't mind, I'll meet you there.", ["objectivesText"] = "Report to Halford Wyrmbane in Vol'dun.", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139719, ["x"] = 0.38075, ["y"] = 0.66 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.38075, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 13, ["flags"] = 0 } } },
[52042] = { ["id"] = 52042, ["name"] = "The Big Boom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "Still, we've placed all those explosives, and there's nothing stopping us from detonating them and laying waste to the Horde's excavations. Speak with Zoidfuse when you're ready, and we'll get this explosive gnome tech going!", ["objectivesText"] = "Speak with Explosioneer Zoidfuse to initiate the Vol'dun Explosion Protocol. Progress: Whenever you're ready.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.618667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 14, ["flags"] = 0 } } },
[52043] = { ["id"] = 52043, ["name"] = "The Wrath of Grapes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52016, 52017, 52043 }, ["description"] = "You look familiar. Do you owe me money? Wait... no, that's not it. If you are here to learn, I could show you my secret mining technique, bu- Ugh... I am currently busy trying to see straight right now, amongst other things. Ugh... it feels like someone is swinging a pick at my skull. De best cure for a hangover is pickle juice and a big greasy breakfast. Tell you what, get me those things, preferably quickly and quietly, and I will teach you whatever want.", ["objectivesText"] = "Bring a Jar of Pickle Juice , a Mountain of Bacon , a Pile of Sausages , and a Hillock of Eggs to Biru The Drunk . Progress: Dese shadows are loud. Can you fix dat, too?", ["rewardItems"] = { 152512, 152513, 152579, 160995, 160996, 160997, 160998, 161078, 161088 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 139634, ["x"] = 0.525, ["y"] = 0.843 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 139634, ["x"] = 0.525, ["y"] = 0.843 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.843 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 766, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Storm Silver Seam - SCS", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52044] = { ["id"] = 52044, ["name"] = "An Exceptional Platinum Shard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52044, 52049, 52050 }, ["description"] = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks. You wonder to yourself if Myra could teach you to harvest this much every time.", ["objectivesText"] = "Bring the Exceptional Platinum Shard to Myra Cabot . Provided item:", ["rewardItems"] = { 152512, 152513, 152579, 153431, 160905, 161078, 161085 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 769, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Platinum Deposit - SCS", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 161078 } },
[52046] = { ["id"] = 52046, ["name"] = "An Exceptional Platinum Shard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52046, 52053, 52055 }, ["description"] = "Out of dumb luck, you've managed to extract an exceptionally large shard of platinum, instead of several smaller chunks. You wonder to yourself if Secott could teach you to harvest this much every time.", ["objectivesText"] = "Bring the Exceptional Platinum Shard to Secott the Goldsmith . Provided item:", ["rewardItems"] = { 152512, 152513, 152579, 161078, 161079, 161088 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122694, ["x"] = 0.44, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 764, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Platinum Deposit - SCS", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 161079 } },
[52049] = { ["id"] = 52049, ["name"] = "X Marks the Plat!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 52044, 52049, 52050 }, ["description"] = "You find a folded piece of aged paper next to the deposit Opening it up, you find a map of Drustvar with an X along the western coast. Several crude poems adorn the paper, with one in particular drawing your attention. \"Once I were a pirate, livin' for rum and pleasure. Since the mutiny, I've retired, an' now I mine for treasure.\" Whoever left this appears to have spent a significant time mining in these lands. They may have some insights you could benefit from.", ["objectivesText"] = "Find the Tattered Map 's maker in Drustvar. Provided item:", ["rewardItems"] = { 152512, 152513, 152579, 153431, 160905, 161078, 161085 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139746, ["x"] = 0.198, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 769, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Platinum Deposit - SCS", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 161085 } },
[52050] = { ["id"] = 52050, ["name"] = "A More Challenging Career", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 52044, 52049, 52050 }, ["description"] = "As ye can imagine, piratin' be in me blood. Spent many of the best years of me life lootin' and plunderin'. Me favorite part was when takin' a chest filled ta the brim with gold and jewels, and buryin' it where only ye know. Alas, that life be too chaotic for me nowadays. Swashbucklin' makes me tired, and grog makes me sick. But... I can still bury me treasure. Bring me some booty worth buryin', and I'll teach ya everythin' I've learned about minin' over the years. So, wanna be me scallywag?", ["objectivesText"] = "Collect 20 Platinum Nuggets . Progress: The winds be fine for adventure!", ["rewardItems"] = { 152512, 152513, 152579, 153431, 160905, 161078, 161082, 161085 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139746, ["x"] = 0.198, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139746, ["x"] = 0.198, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 769, ["name"] = "8.0 Professions - Gathering - Mining - Kul Tiras - Platinum Deposit - SCS", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52051] = { ["id"] = 52051, ["name"] = "LFGDungeons - BFA - Raid Finder - 1st", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 52051 }, ["rewardGold"] = 2340000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[52053] = { ["id"] = 52053, ["name"] = "The Platinum Map", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52046, 52053, 52055 }, ["description"] = "Nestled within the fissures of the deposit, you find a small disc of pure platinum. Dusting it off, you see etchings in its surface and recognize it as a map of Vol'dun. You also notice what appears to be a small cave in the south west that has been circled. Whoever left this apparently has a wealth of knowledge of the metal and wants to be found.", ["objectivesText"] = "Find the Platinum Map 's maker in Vol'dun. Provided item:", ["rewardItems"] = { 152512, 152513, 152579, 161078, 161088 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139792, ["x"] = 0.276, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 764, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Platinum Deposit - SCS", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 161088 } },
[52054] = { ["id"] = 52054, ["name"] = "Too Much To Bear", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52054 }, ["objectivesText"] = "Injured Hunters healed", ["rewardItems"] = { 161114 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Injured Hunters healed", ["amount"] = 7, ["type"] = 0, ["objectID"] = 139802, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52055] = { ["id"] = 52055, ["name"] = "An Ore for an Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52046, 52053, 52055 }, ["description"] = "I have one last request before I can go. I wish to see de sunset one last time. I have an enchantment in mind, and I have all the materials I need except de metal. I need you to bring me twenty platinum nuggets . I have asked de spirits to bring me de ore, but dey do not listen to me anymore. Dat is why I hid de map where only someone who could be of help would find it. If you help me out, I will teach you what I can about mining platinum.", ["objectivesText"] = "Collect 20 Platinum Nuggets . Progress: De elements beckon me. Do you have de platinum nuggets ?", ["rewardItems"] = { 152512, 152513, 152579, 161078, 161082, 161088 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139792, ["x"] = 0.276, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139792, ["x"] = 0.276, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.276, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 764, ["name"] = "8.0 Professions - Gathering - Mining - Zandalar - Platinum Deposit - SCS", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52058] = { ["id"] = 52058, ["name"] = "A Short-Lived Peace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52060, 52062, 52072, 52116, 53616 }, ["description"] = "<name>, As the Legion's presence wanes from our world, a new threat has risen. It is with a heavy heart that I must ask you to put your life on the line for the Alliance once more. I have received a disturbing message from our operatives stationed in Orgrimmar. I await your arrival at Stormwind Keep to discuss matters further.", ["objectivesText"] = "Report to King Anduin Wrynn in Stormwind Keep.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 157832 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.316667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 6, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52060] = { ["id"] = 52060, ["name"] = "The Horde Uprising", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52058, 52062, 52072, 52116, 53616 }, ["description"] = "Given the potential of Azerite to change the face of warfare, it comes as no surprise that the Warchief seeks to lay claim to it. Reports indicate that she is mobilizing an army to march on Silithus--the site of the great wound. Heroes of the Horde and the Alliance fought side-by-side during the Argus campaign. To think that Sylvanas is ready to cast that unity aside... Speak with Mathias Shaw. I want you to oversee our presence in Silithus.", ["objectivesText"] = "Report to Master Mathias Shaw for further instruction.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 157832 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 139798, ["x"] = 0.8505, ["y"] = 0.3255 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.316667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52061] = { ["id"] = 52061, ["name"] = "Taptaf the Pig!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 52061 }, ["rewardItems"] = { 161081 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139380, ["x"] = 0.65, ["y"] = 0.832 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139380, ["x"] = 0.65, ["y"] = 0.832 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.65, ["y"] = 0.832 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[52062] = { ["id"] = 52062, ["name"] = "A Disturbance in Ashenvale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52058, 52060, 52072, 52116, 53616 }, ["description"] = "The damned Horde! Clever bastards, I'll give them that. They diverted at the north fork of the Barrens and are now marching on Ashenvale. The kaldorei forces already set sail for Silithus--must be halfway there by now. The only defenders still in the area are the Darnassian City Guard. They are en route to Astranaar, but they won't last long against an army. Their commander goes by the name of Delaryn Summermoon. Find her, <name>, and buy us time. We will get our fleet there as soon as we can.", ["objectivesText"] = "Report to Captain Delaryn Summermoon in Astranaar.", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 139798, ["x"] = 0.8505, ["y"] = 0.3255 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8505, ["y"] = 0.3255 }, ["mapCandidates"] = { ["npc"] = { 57, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52065] = { ["id"] = 52065, ["name"] = "Worse Than It Looks", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52065 }, ["description"] = "As bad as things are here we're managing to hold on. Things are actually a lot worse at Beacon Hill. They're closer to the main attack, and will need all the help they can get. Head there and see if you can help.", ["objectivesText"] = "Speak to Felicia Gladstone at Beacon Hill", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135682, ["x"] = 0.578, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.554 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[52067] = { ["id"] = 52067, ["name"] = "Survivors", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52067 }, ["description"] = "Patrick and Daryl Eckhart have a place north of town. If I know them, they'll be taking in survivors from Brennadam. Check in with Patrick and see if they need any help.", ["objectivesText"] = "Speak to Patrick Eckhart at the Eckhart Lodge.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["rewardItems"] = { 23389, 25778, 25779, 25780, 211279 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 130190, ["x"] = 0.576, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135682, ["x"] = 0.578, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[52068] = { ["id"] = 52068, ["name"] = "Helping Out, Somewhere Else", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52068 }, ["description"] = "You've been a big help and now we've got a lot of gold to divvy up! You should go west to Seabreeze Village. Treat it like a vacation, keep your mind off the gold. We'll be fine here. When you come back later, we'll have your share all ready for you. You'd just be getting in the way here.", ["objectivesText"] = "Speak to Lieutenant Bauer at Seabreeze Village.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.565 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[52069] = { ["id"] = 52069, ["name"] = "More Fodder", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52069 }, ["description"] = "Leo Shealds at Deadwash is a crook, but he recognizes the threat the naga pose. He'll send men to help us if we ask, even if most are just fodder. Travel to Deadwash and ask for help.", ["objectivesText"] = "Speak to Leo Shealds at Deadwash.", ["rewardGold"] = 30900, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131343, ["x"] = 0.332, ["y"] = 0.456 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 134720, ["x"] = 0.43, ["y"] = 0.565 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.456 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[52070] = { ["id"] = 52070, ["name"] = "Bauer Backup", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52070 }, ["description"] = "We've not heard anything from the coast since the Horde attack started. I need you to check in on Lieutenant Bauer at Seabreeze Village and see that they're safe.", ["objectivesText"] = "Speak to Lieutenant Bauer at Seabreeze Village.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 138735, ["x"] = 0.481333, ["y"] = 0.405333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 131002, ["x"] = 0.302, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.481333, ["y"] = 0.405333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[52071] = { ["id"] = 52071, ["name"] = "Briarback Mountain", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52071 }, ["objectivesText"] = "Battle-Piglets borrowed", ["rewardItems"] = { 161123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Battle-Piglets borrowed", ["amount"] = 8, ["type"] = 0, ["objectID"] = 134014, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52072] = { ["id"] = 52072, ["name"] = "The Light of Elune", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1657, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52058, 52060, 52062, 52116, 53616 }, ["description"] = "My sisters lie slain on the soft earth of Ashenvale. We are trained to expect losses. Soldiers die in battle. But this... this was a despicable attack, even for the Horde. We have little time to grieve, but we are not savages like our enemy. Please, <name>. Help me say a prayer to Elune in honor of the fallen. Their wisps deserve the light of her blessing.", ["objectivesText"] = "Honor the bodies of the fallen soldiers in Astranaar.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 1657 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52074] = { ["id"] = 52074, ["name"] = "Deliverance", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48179, 48180, 48182, 48183, 52074, 52075, 53110 }, ["description"] = "Mainlander! Stop a moment, I could really use a hand! My team and I were hunting in the ruins of Gol Koval when the stones began to attack us! I've never seen anything like that before. Ranger Wons sent Duke and I to get some medical supplies for our injured. Duke didn't get hit by those possessed stone monsters but he wasn't as fortunate with the spiders nearby. He'll be okay if he rests here for awhile, but my team needs these medical supplies! Please take these to Ranger Wons !", ["objectivesText"] = "Bring supplies to Ranger Encampment in Gol Koval. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["rewardItems"] = { 67174, 67191, 67208, 67222, 161124 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 125457, ["x"] = 0.645, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139912, ["x"] = 0.618, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5441, ["name"] = "Drustvar Ruins", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52075] = { ["id"] = 52075, ["name"] = "Boned", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48179, 48180, 48182, 48183, 52074, 52075, 53110 }, ["description"] = "If the living rocks weren't bad enough, it seems the undead are hauling themselves out of the ground, too! This used to be a Drust settlement, so those are probably Drust bones. They hated us and the feeling is definitely mutual right now. I don't know what has them stirred up, but they're a danger to us and everyone else. Take them out and I'll reward you for the work.", ["objectivesText"] = "Defeat 8 Vengeful Bones .", ["rewardGold"] = 303800, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139912, ["x"] = 0.618, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139912, ["x"] = 0.618, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5441, ["name"] = "Drustvar Ruins", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52113] = { ["id"] = 52113, ["name"] = "Vol'jin, Son of Sen'jin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["series"] = { 51516, 51517 }, ["description"] = "Even in da Echo Isles we have heard of da traditions of da Golden Road. We must walk in da presence of royalty and hail da accomplishments of Vol'jin so dat his spirit be welcome here amongst da ancient kings. I shall carry da ashes, if you light da fires. Know that any member of any other tribe may contest us. As our champion, we will need you to fend them off if they do.", ["objectivesText"] = "Escort Vol'jin's Ashes to Atal'Dazar.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 139928, ["x"] = 0.4465, ["y"] = 0.3765 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 138138, ["x"] = 0.438, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.4465, ["y"] = 0.3765 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52114] = { ["id"] = 52114, ["name"] = "Honoring a True Leader", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6453, ["mapID"] = 463, ["storyline"] = { 51513, 51514, 51515, 51516, 51517, 51533, 52113, 52114 }, ["description"] = "Vol'jin. I have often felt our old chieftain's spirit whisperin' to me. His strength was da lifeblood of da Darkspear tribe. Some would even say he was da spirit of da true Horde. Princess Talanji's offer is a great one. I shall travel with Vol'jin's ashes to Atal'Dazar. If ya be wishin' to join us for dis procession, meet us upon da famed Golden Road.", ["objectivesText"] = "Meet Master Gadrin at the Golden Road in Zuldazar.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 463, ["npcID"] = 137878, ["x"] = 0.595, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 139928, ["x"] = 0.4465, ["y"] = 0.3765 } }, ["coords"] = { ["mapID"] = 463, ["source"] = "quest_giver", ["x"] = 0.595, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 463, 862 }, ["zone"] = { 6453 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 734, ["name"] = "The Fallen Chieftain", ["orderIndex"] = 4, ["flags"] = 0 } } },
[52116] = { ["id"] = 52116, ["name"] = "A Soft Glow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52058, 52060, 52062, 52072, 53616 }, ["description"] = "The wisps... they sing with sorrow, but also with purpose. The forest stirs, aglow with their light. That sound... in the distance. Could it be our Shan'do? Quickly, <name>! Malfurion beckons!", ["objectivesText"] = "Find Malfurion in Ashenvale.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 133693, ["x"] = 0.4384, ["y"] = 0.7188 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57, 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52117] = { ["id"] = 52117, ["name"] = "Briarback Mountain", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52117 }, ["objectivesText"] = "Battle-Piglets borrowed", ["rewardItems"] = { 161123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Battle-Piglets borrowed", ["amount"] = 8, ["type"] = 0, ["objectID"] = 134014, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52118] = { ["id"] = 52118, ["name"] = "Cutting Out the Competition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 52118 }, ["description"] = "I've never cared much for battle, but I'll be damned if those fiends think they're gettin' this mill. Best if we clear the area quickly. Grab an axe and show me what you got.", ["objectivesText"] = "Pick up a Sturdy Axe , then gather 5 Freshly-Chopped Wood from the nearby Sapling. Progress: What're you waiting for?", ["rewardGold"] = 105000, ["rewardXP"] = 3410, ["rewardItems"] = { 156531, 161130 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
