[52122] = { ["id"] = 52122, ["name"] = "To Be Forsaken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51797, 51798, 51805, 51818, 51819, 51830, 51837, 52122, 53066 }, ["description"] = "Let's move. Zelling is probably with his family now. Either they're happily reunited and he helps us find Valentine... or he just helps us find Valentine. Let's go.", ["objectivesText"] = "Go with Lilian Voss to find Thomas Zelling.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 245469 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 139101, ["x"] = 0.579333, ["y"] = 0.318667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.579333, ["y"] = 0.318667 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 12 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 627, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 627, ["name"] = "Death of a Tidesage", ["orderIndex"] = 7, ["flags"] = 0 } } },
