[52127] = { ["id"] = 52127, ["name"] = "The Wolf's Den", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 862, ["storyline"] = { 52127 }, ["series"] = { 52005 }, ["description"] = "The raid you planned on Wolf's Den in Tiragarde Sound was successful. Well done. The outpost is ready to be claimed. Make your way to Wolf's Den in Tiragarde Sound and establish fortifications there. Wolf's Den will be an essential outpost in our campaign against the Alliance. Go with honor!", ["objectivesText"] = "Claim Wolf's Den for the Horde.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 161121, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163507 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 139561, ["x"] = 0.624, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
