[52129] = { ["id"] = 52129, ["name"] = "Power Problems", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 50771, 50775, 50812, 51991, 52129 }, ["series"] = { 51991 }, ["description"] = "Rozzy , part of the extraction crew, headed out with some gear to work on a plan to keep these reconfigulators all charged up. Go see see if she could use some help!", ["objectivesText"] = "Check in with Rozzy .", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 135179, ["x"] = 0.262, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 140046, ["x"] = 0.285, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 5421, ["name"] = "For Profit", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52130] = { ["id"] = 52130, ["name"] = "Deadliest Cache: Carpe Diem", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50376, 50391, 50418, 52130 }, ["description"] = "Bah, don't listen to these landlubbers. They haven't fished an honest day in their lives! Before they met me they were as dry as the sands o' the shoreline at low tide. I'll spin ye the tale o' the day we met. 'Twas also the day I saved the wharf from the biggest, meanest, largest monster o' the briny deep ye could imagine!", ["objectivesText"] = "Listen to Coxswain Hook 's tale. Progress: These landlubbers owe me their lives, if ye ask me!", ["rewardGold"] = 619600, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 133576, ["x"] = 0.26, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133576, ["x"] = 0.26, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5450, ["name"] = "Deadliest Cache", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52131] = { ["id"] = 52131, ["name"] = "We Need Each Other", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9598, ["storyline"] = { 52131 }, ["description"] = "My father believes he is indulging me. He has ruled for two hundred years, many lifetimes of trolls. In his mind, de threats dat face our kingdom are minor. I have seen too much to believe dat. So since my father and his advisors would not help, I turned to someone who would. Your warchief needs our fleet, and I need her champions. So here is what we need to do.", ["objectivesText"] = "Listen to Princess Talanji .", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9598 } }, ["questType"] = "standard" },
[52132] = { ["id"] = 52132, ["name"] = "The Proof of Piracy", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 50674, 50675, 50691, 50696, 50697, 50704, 50741, 50742, 50753, 50774, 50793, 50802, 50803, 50810, 50955, 52132 }, ["description"] = "One thing pirates love more than gold is rum. So we're going to find their rum stashes and blow them up. With the rum all gone, a lot of the pirates should move on. Use my special barrel busting bombs to destroy the pirates' hidden rum stashes.", ["objectivesText"] = "Destroy 6 pirate Rum Stashes. Progress: Let's blow up some rum!", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 158226, 158635, 158636, 158724, 160481, 160668 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135946, ["x"] = 0.412, ["y"] = 0.54 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 740, ["name"] = "Deadwash Line", ["orderIndex"] = 14, ["flags"] = 0 } } },
