[52146] = { ["id"] = 52146, ["name"] = "Blood on the Sand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 52026, 52027, 52028, 52029, 52030, 52031, 52032, 52034, 52035, 52036, 52038, 52039, 52040, 52041, 52042, 52146 }, ["description"] = "And with that, our mission is done. Let's verify that Guzbert and Kelsey return safely from their demo sites, and then we can head back to friendlier shores.", ["objectivesText"] = "Wait for Guzbert Gizmoflank and Kelsey Steelspark to return. Progress: Shouldn't be long now!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 161086, 161087, 161240, 161241, 161333 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 139705, ["x"] = 0.408, ["y"] = 0.618667 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.618667 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 9 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 628, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 628, ["name"] = "Blood on the Sand", ["orderIndex"] = 15, ["flags"] = 0 } } },
[52147] = { ["id"] = 52147, ["name"] = "Crippling the Horde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["series"] = { 53069 }, ["description"] = "Our scouts report that one of Sylvanas's dark ranger captains is in Nazmir. The dark rangers are Sylvanas's deadliest fighters and scouts. Killing one of their leaders will cripple Horde operations. Shandris Feathermoon will be leading the operation in Nazmir. Head there now and strike before we lose this chance.", ["objectivesText"] = "Speak with Grand Admiral Jes-Tereth to sail to Nazmir.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 863, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52148] = { ["id"] = 52148, ["name"] = "Freehold: A Pirate's End", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52148 }, ["description"] = "Hey, uh, I don't usually ask for help with personal business, but I know when I'm outmatched. Someone's gotta take down Harlan. He's a maniac. The things I saw him do back in the day... that's why I left Freehold in the first place. H-hey don't think of it as a favor for me--even though it would be a HUGE favor--think of it as making the seas safer for everyone, or something noble like that. <Flynn leans in and whispers.> Plus there's a big fat bounty on his head!", ["objectivesText"] = "Slay Harlan Sweete in the Freehold dungeon. Progress: What's say sixty-forty split on the bounty? Eh? Seventy-thirty? How about a finder's fee?", ["rewardGold"] = 1239200, ["rewardXP"] = 2830, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 }, { ["mapID"] = 1161, ["npcID"] = 131290, ["x"] = 0.6665, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 121239, ["x"] = 0.6892, ["y"] = 0.516 }, { ["mapID"] = 1161, ["npcID"] = 131290, ["x"] = 0.6665, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.6892, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "dungeon" },
[52150] = { ["id"] = 52150, ["name"] = "How to Kill a Dark Ranger", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["description"] = "Let's go over the plan. We don't get many chances to kill a captain of Sylvanas's dark rangers.", ["objectivesText"] = "Listen to Shandris Feathermoon 's plan. Progress: Well? Let's go over the plan.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52151] = { ["id"] = 52151, ["name"] = "A Nation United", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52151 }, ["description"] = "You've done a fine job here, $p. With the city secure and Jaina in command of the fleet, the time has come for Kul Tiras to formally join the Alliance. King Anduin has already departed for Unity Square to meet with Jaina, Katherine and the heads of the major Kul Tiran houses. They are waiting for you.", ["objectivesText"] = "Attend the council meeting at Unity Square.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 120788, ["x"] = 0.68, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121144, ["x"] = 0.4915, ["y"] = 0.848 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[52153] = { ["id"] = 52153, ["name"] = "Siege of Boralus: Lady Ashvane's Return", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52153 }, ["description"] = "If Ashvane thinks we will sit idly by as she attempts a coup, she is sorely mistaken. The citizens of Boralus will fight her to a man. I'll need you on the front lines to aid them, <class>. Go with Taelia to the docks and engage the enemy. With a little luck, we may just make it out of this alive.", ["objectivesText"] = "Complete the Siege of Boralus dungeon.", ["rewardGold"] = 1029600, ["rewardXP"] = 2830, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 141785, ["x"] = 0.446, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "dungeon" },
