[52156] = { ["id"] = 52156, ["name"] = "Tortollans in Distress", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["description"] = "Our first task is to rescue the tortollans captured by the blood trolls. Keeshan's report indicates the tortollans are familiar with all things Nazmir. They should know about the Horde's operations here. The tortollans tend to stay neutral in most matters. They'll give us details on the Horde's plans if we make a fair trade. We'll meet afterwards at our other outpost, Redfield's Watch, north of Torga's Rest.", ["objectivesText"] = "Rescue 6 Tortollan Captives from the blood trolls. Progress: What else do you need to know?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 2, ["flags"] = 0 } } },
