[52170] = { ["id"] = 52170, ["name"] = "Ending Areiel", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["description"] = "The tortollans have given us Captain Areiel's location, as well as new information. She carries a missive from the Horde. Any missive the Horde would send to Areiel must be extremely important. We must recover it and deliver the information to Halford. Areiel and I once fought side by side. She's incredibly powerful, Keeshan and I will be there to help you bring her down. Good luck, <name>.", ["objectivesText"] = "Recover the Horde Missive from Captain Areiel. Progress: Did you retrieve the missive?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 4, ["flags"] = 0 } } },
[52171] = { ["id"] = 52171, ["name"] = "One Option: Fire", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["description"] = "Here I thought things couldn't get worse, but now we have the Horde making camp around the home of some death god. I've got a good idea of what they've brought, thanks to my time in the first three wars. Medicine, armor, food... And probably offerings for this Bwonsamdi fella. Destroy all of these supplies to let the Horde know we won't let them stay here.", ["objectivesText"] = "Burn Bwonsamdi Offerings , Armory Supplies , Food Cache , and Medicinal Supplies in the Necropolis.", ["rewardGold"] = 331700, ["rewardXP"] = 6815, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 139609, ["x"] = 0.565, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 139609, ["x"] = 0.565, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52172] = { ["id"] = 52172, ["name"] = "They Can't Stay Here", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["description"] = "Can't believe the Horde already have a foothold in the Necropolis. We have to stop them. This one's simple. Kill as many Horde as you find in that cursed place, but keep your eye out for a fella named Bwonsamdi. Seems like he's some sort of death god. He's way beyond anything we can handle, but why not send a few of his followers his way? Better they rot in his necropolis than bother the living.", ["objectivesText"] = "Kill 12 Horde soldiers within the Necropolis.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 139609, ["x"] = 0.565, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 139609, ["x"] = 0.565, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.565, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 6, ["flags"] = 0 } } },
[52173] = { ["id"] = 52173, ["name"] = "The Void Elves Stand Ready", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "Bal'a dash, $p. Alleria and the others have informed me of your many accomplishments here in Kul Tiras. I'm honored to join you on this mission. As a representative for the void elves, I am eager to prove to King Anduin that his trust in us was well-placed. Forgive me, do not allow me to delay you. Alleria and the others can brief me on the mission as we travel. You may tell the Grand Admiral that we are ready to set sail whenever you like.", ["objectivesText"] = "Speak with Grand Admiral Jes-Tereth and travel to Xibala.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 161422 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 140348, ["x"] = 0.694667, ["y"] = 0.266 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.694667, ["y"] = 0.266 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 1, ["flags"] = 0 } } },
