[52183] = { ["id"] = 52183, ["name"] = "When a Plan Comes Together", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["series"] = { 53068 }, ["description"] = "Having Derek Proudmoore's body in our possession is a greater boon than we had planned for. Valentine is risen, but I think it best to allow Derek to lay dead for a bit longer. It's time to use our new allies to our advantage.", ["objectivesText"] = "Listen to Nathanos' plan, then travel to Plunder Harbor.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140485, ["x"] = 0.87, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52184] = { ["id"] = 52184, ["name"] = "Relics of Ritual", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["description"] = "There is a reason why I am accompanying you on this mission, and it's more than familiarity. The Abyssal Scepter is locked behind a ritual, the components for which are held by three separate lieutenants spread across the compound. You get the relics, I perform the ritual, we grab the Scepter and we get out.", ["objectivesText"] = "Collect the Compass of Clarity , the Curio of the Depths , and the Key of the Sea in Stormsong Monastery. Progress: Have you collected the relics yet?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 161334, 161335, 161336 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.869, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 4, ["flags"] = 0 } } },
[52185] = { ["id"] = 52185, ["name"] = "A Well Placed Portal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["series"] = { 52186 }, ["description"] = "We have the front here under control. I am sending you and Zelling into Boralus to acquire the Abyssal Scepter. Oculeth has managed to pinpoint a safe location for a portal. Get moving.", ["objectivesText"] = "Use the Portal to Boralus and meet with Thomas Zelling in Stormsong Monastery.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140485, ["x"] = 0.87, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.87, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52186] = { ["id"] = 52186, ["name"] = "The Bulk of the Guard", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["series"] = { 52185 }, ["description"] = "If all has gone according to plan, Proudmoore has sent her elite forces to recapture her son's body. Let's make sure they stay out of the way of our real mission, hmm?", ["objectivesText"] = "Kill 12 Proudmoore Guard on The Siren's Daughter and The Valorous Rose. Hobart Grapplehammer can fly you out to the ships. Progress: Oh, Katherine. You play right into our trap.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140485, ["x"] = 0.87, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140485, ["x"] = 0.87, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.87, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52187] = { ["id"] = 52187, ["name"] = "Old Colleagues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 862, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["description"] = "The people in charge of those two ships are old colleagues of mine, <name>. They did not achieve their rank through hard work as I did, but rather through deception and blackmail. I think they deserve the hammer of karma. Or whatever weapon you prefer.", ["objectivesText"] = "Kill Captain Gastrod and Guard-Commander Trunksal on The Siren's Daughter, and Helmsman Miria on the Valorous Rose. Hobart Grapplehammer can fly you out to the ships. Progress: I am not a vengeful person... but appropriate punishment? Consider me a fan.", ["rewardGold"] = 24600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140484, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140484, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52188] = { ["id"] = 52188, ["name"] = "Tidesage Teachings", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["description"] = "These people are not tidesages anymore. They do not deserve to bear our title, our prestige, or our knowledge. So many of our teachings lay scattered around this monastery, potentially lost to those of us that remain. We must reclaim these writings. Better in my hands than theirs.", ["objectivesText"] = "Collect 5 Tomes of Tidesage Research in Stormsong Monastery. Progress: I will not stand for my people's research to be used for evil.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 162106 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.869, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52189] = { ["id"] = 52189, ["name"] = "Forfeit Souls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["description"] = "The tidesages here have given in to dark magics. They have submitted themselves to powers they do not understand, and my people have suffered for it. I knew them once, my brothers and sisters in the tides. But now they are lost. I guess I am too. Redeem the name of the tidesages! Kill these betrayers!", ["objectivesText"] = "Kill 8 Tidesage Archvists or Tidesage Summoners in Stormsong Monastery.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.869, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 6, ["flags"] = 0 } } },
[52190] = { ["id"] = 52190, ["name"] = "Gaining the Upper Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["series"] = { 52191, 52192, 52990, 53003 }, ["description"] = "We need to retrieve the Abyssal Scepter and get out of here before the Kul Tirans break our line in Plunder Harbor. I did some research while you were gone. I believe I uncovered the location where the ritual must take place. When you are ready to go, we can make our way over.", ["objectivesText"] = "Aid Zelling in retrieving the Abyssal Scepter from Stormsong Monastery. Progress: Nathanos and I believe scepter will help us gain the upper hand on the Kul Tiran fleet. If you wish to win this war, the Abyssal Scepter is key.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 162579 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140487, ["x"] = 0.869, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.869, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 7, ["flags"] = 0 } } },
[52191] = { ["id"] = 52191, ["name"] = "Life Held Hostage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["series"] = { 52190, 52192, 52990, 53003 }, ["description"] = "As Lilian has pointed out, it seems we have a final visitor. Shall we go pay him a visit?", ["objectivesText"] = "Help Nathanos Blightcaller with the last of Proudmoore's forces. Progress: There is nothing left for us here. Let us return.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140485, ["x"] = 0.87, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140485, ["x"] = 0.87, ["y"] = 0.526 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.87, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 9, ["flags"] = 0 } } },
[52192] = { ["id"] = 52192, ["name"] = "The Aid of the Tides", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 52183, 52184, 52185, 52186, 52187, 52188, 52189, 52190, 52191, 52192, 52861, 52990, 53003 }, ["series"] = { 52190, 52191, 52990, 53003 }, ["description"] = "With Derek's body and the Abyssal Scepter in stow, our undertaking here today is complete. Let us escape under their noses. When you are ready, let us return to Zuldazar. Sylvanas will want to hear of our victories.", ["objectivesText"] = "Talk to Nathanos Blightcaller and return to Zuldazar.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140485, ["x"] = 0.87, ["y"] = 0.526 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.87, ["y"] = 0.526 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 14 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 629, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 629, ["name"] = "The Strike on Boralus", ["orderIndex"] = 10, ["flags"] = 0 } } },
[52194] = { ["id"] = 52194, ["name"] = "What You May Regret", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "<name>, Genn Greymane left this letter for you. He indicated it was urgent. I was just about to send for you. <Upon opening it, the letter reads as follows.> \"<name>, You have helped to unite the Kul Tirans and gained their support for the Alliance. Perhaps now you might be able to help reunite a mother with her daughter. Meet me at the family memorial by Proudmoore Keep. With luck we can convince Lord Admiral Proudmoore to grant her daughter a stay of execution. - Genn Greymane \"", ["objectivesText"] = "Meet with Genn Greymane at the memorial by Proudmoore Keep. Progress: My daughter... My Jaina...", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140495, ["x"] = 0.67, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52197] = { ["id"] = 52197, ["name"] = "Long Away", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["description"] = "For every foe we slay, two more take their place. We are too few in number to stand toe to toe. We must fall back, <name>. Strategy can yet overcome numbers. We will regroup at Darnassus. I will send for Delaryn.", ["objectivesText"] = "Regroup with Malfurion and Delaryn at Darnassus.", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 133693, ["x"] = 0.4384, ["y"] = 0.7188 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.7188 }, ["mapCandidates"] = { ["npc"] = { 57, 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 89, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 16, ["flags"] = 0 } } },
[52199] = { ["id"] = 52199, ["name"] = "Rum- Paaaage!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52199 }, ["objectivesText"] = "Irontide Rum Stash destroyed", ["rewardItems"] = { 161197 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Irontide Rum Stash destroyed", ["amount"] = 8, ["type"] = 0, ["objectID"] = 140365, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52203] = { ["id"] = 52203, ["name"] = "Find the Paper Trail", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "The High Commander's intelligence was confident that Trade Prince Gallywix is currently in Zuldazar, but my trackers could not locate him within the Bilgewater camp. He's most likely somewhere nearby. Goblins do not work for free. Someone is bound to be bossing around the rest of those miners. Locate whoever is in charge, eliminate them, and search for anything that might tell us where Gallywix is.", ["objectivesText"] = "Collect Orders From Gallywix . Progress: Did you find anything useful?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 161420, 161422 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52204] = { ["id"] = 52204, ["name"] = "The Void Solution", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "The Bilgewater Cartel are serious about protecting their investment at the mining site. My trackers have reported a heavy presence of large mech suits used for breaking rocks and suppressing attackers. I am certain that you could deal with the mechs yourself, but you need not waste your time doing so. Take this void shard and use it to cast the large mechs into the Void, where they won't be able to bother anyone again.", ["objectivesText"] = "Use Magister Umbric's Void Shard to destroy 4 Bilgewater Frackers .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161422 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52205] = { ["id"] = 52205, ["name"] = "Bilgewater Bonanza Go Boom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "I have met very few goblins that I respect, but I must give them universal credit for one thing: they are persistent. The Bilgewater Cartel, Trade Prince Gallywix's gang, has already sent a full set of replacement miners to extract Azerite from the beach site nearby. I am certain the Alliance will be pleased if you interrupt their mining operations again. My regiment is available to aid you, but our combat tactics are unconventional. When you wish our help, call into the Void and we will answer.", ["objectivesText"] = "Kill 12 Bilgewater goblins and open Void Tears to summon void elf allies.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161422 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 4, ["flags"] = 0 } } },
[52207] = { ["id"] = 52207, ["name"] = "The Azerite Stuff", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52207 }, ["rewardItems"] = { 164382 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 148 } }, ["questType"] = "world", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52208] = { ["id"] = 52208, ["name"] = "Meeting of the Minds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["description"] = "We're in luck. The missive details a meeting in Zo'bal Ruins between Talanji, Rokhan, Areiel, and Blood Prince Dreven. This is our chance to gain more intel on Dreven and his next move. He killed our soldiers in Vol'dun, it's time for him to pay. Meet me outside of Zo'bal Ruins. We're going to sneak into the ruins, listen to their plans, and decide what to do next.", ["objectivesText"] = "Meet Shandris Feathermoon outside of Zo'bal Ruins. Progress: Let's move.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 140519, ["x"] = 0.422, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 7, ["flags"] = 0 } } },
[52210] = { ["id"] = 52210, ["name"] = "Sending Out An SOS", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52210 }, ["description"] = "I noticed an exodus from the fleet, far out in the harbor. Flyers were sent out, they seek something, or someone. Those ships made a great journey, and they have much work ahead. Please check in with Captain Grez'ko . I am sure he could use a hand!", ["objectivesText"] = "Speak to the Captain.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 140590, ["x"] = 0.46, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[52212] = { ["id"] = 52212, ["name"] = "Battle for Stromgarde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 52212 }, ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 163578, 163579, 163644, 163645, 163646, 163648, 163650, 163652, 163677, 163684, 163689, 163690, 163691, 163698, 163700, 163701, 163706, 163711, 163712, 163713, 163735, 163736, 163738, 163741, 163744, 163745, 163750, 163775, 163828, 163829, 164577, 164578, 169196, 169197 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[52213] = { ["id"] = 52213, ["name"] = "Ancient Skinning Knife", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 51575, 52213 }, ["description"] = "Within the scarred flesh of the beast, you find a notched golden blade embedded under its skin. Carefully extracting the blade, you can't help but feel like this is an old Zandalari skinning knife. You should show this to Rana the Cutta .", ["objectivesText"] = "Return the Ancient Skinning Knife to Rana the Cutta . Provided item:", ["rewardItems"] = { 152541, 153050, 161431 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 776, ["name"] = "8.0 Professions - Gathering - Skinnin - Zandalar - Leather - SCS", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 161431 } },
[52214] = { ["id"] = 52214, ["name"] = "Ceremonial Vestments", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52214, 52215 }, ["description"] = "Xanjo asked dat I gather de materials for him to make some ceremonial armor. He requested several pieces of crocolisk hide, but all de hides I have are flawed or scarred. I need you to bring me a handful of fresh crocolisk hides dat are pristine. De best source dat I know of are de primal snapjaws in Nazmir, as their hide is usually thick enough to avoid getting scarred when dey fight. If you do dat for me, I will show you how to better harvest scales from, well... scaly creatures.", ["objectivesText"] = "Collect 3 Pristine Skins from Primal Snapjaws in Nazmir. Progress: Have you got de skins?", ["rewardItems"] = { 152541, 153050, 161431, 161432 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 777, ["name"] = "8.0 Professions - Gathering - Skinnin - Zandalar - Scale - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52215] = { ["id"] = 52215, ["name"] = "A Thicker Thread", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52214, 52215 }, ["description"] = "<name>! I was hoping you would show up! Xanjo is nearly finished with de suit of ceremonial armor he has been working on, but dere is a problem. He says dat de thread he used is too thin, and dat de weight of de leather is ripping out de stitching. He asked me to get something dat will hold, and de best thing I can think of is de thick webbing of jungleweb crawlers. You can find dem in northern Vol'dun. Bring me back some strands of their thick webbing , and my knowledge of scales is yours.", ["objectivesText"] = "Loot 5 Strands of Thick Webbing from Jungleweb Crawlers in Vol'Dun. Progress: So, did you get de silk?", ["rewardItems"] = { 152541, 153050, 161431, 161433 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 777, ["name"] = "8.0 Professions - Gathering - Skinnin - Zandalar - Scale - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52216] = { ["id"] = 52216, ["name"] = "Hexoskeleton", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 1165, ["storyline"] = { 52216, 52217 }, ["description"] = "I have a bet going with Xanjo over what leather is de best for armor in regards to resisting piercing and slashing attacks. He says scales are the best, but I have something better in mind. I feel de makrura's exoskeleton could be treated to act as a natural plate armor. Bring me de carapace of a bittertide makrura, and I will teach you how to harvest bones more effectively from creatures you're skinning.", ["objectivesText"] = "Collect an Unbroken Makrura Carapace . Progress: Do you have de carapace?", ["rewardItems"] = { 152541, 153050, 161431, 161434 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 775, ["name"] = "8.0 Professions - Gathering - Skinnin - Zandalar - Bone - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52217] = { ["id"] = 52217, ["name"] = "Loa Fit For A King", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9028, ["mapID"] = 1165, ["storyline"] = { 52216, 52217 }, ["description"] = "Hey, <name>! Come here. Shh. Closer. <Rana's voice drops to a whisper.> I have something I want you to do for me. It may be just a touch sacreligous, but... well... Rezan was once de loa of kings, but he has been taken to Atal'Dazar, and it grieves me what has happened to him. I want you to go dere, and bring me back a bone of his. Not even a whole bone. A splinter. I don't care how small. Please do dis for me, and I will teach you everything I know about gathering bones while skinning.", ["objectivesText"] = "Collect Rezan's Bone Fragment. Progress: Did you get it?", ["rewardItems"] = { 152541, 153050, 161431, 161435 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122699, ["x"] = 0.437, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.437, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 9028 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 775, ["name"] = "8.0 Professions - Gathering - Skinnin - Zandalar - Bone - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52218] = { ["id"] = 52218, ["name"] = "Night Horrors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 52218 }, ["objectivesText"] = "Defeat Grixis Tinypop in a pet battle.", ["rewardItems"] = { 60955, 166499 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Defeat Dilbert McClint", ["amount"] = 1, ["type"] = 11, ["objectID"] = 140461, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 115, ["db2QuestInfoName"] = "Battle Pet World Quest" },
[52219] = { ["id"] = 52219, ["name"] = "Target: Blood Prince Dreven", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 52147, 52150, 52156, 52158, 52170, 52171, 52172, 52208, 52219, 53069 }, ["description"] = "We must kill Blood Prince Dreven and his followers. I know of the place where they intend to go. Here is the plan. You and Keeshan will make your way to the tunnels and act as bait, lure Dreven into a false sense of security. Myself and the sentinels will seal the entrance to trap him and his allies shortly thereafter. Then we kill them all. I'll send word to the others to get moving. Let's go.", ["objectivesText"] = "Meet Keeshan within the Collapsed Tunnels in Nazmir.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 161332, 163196 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 140519, ["x"] = 0.422, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 140258, ["x"] = 0.566, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 10 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 632, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 632, ["name"] = "Chasing Darkness", ["orderIndex"] = 8, ["flags"] = 0 } } },
[52221] = { ["id"] = 52221, ["name"] = "Mission Report: Stonefist Watch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52221 }, ["series"] = { 52222 }, ["description"] = "Your followers have sent a report regarding the assault on Stonefist Watch. It details that victory was hard-fought, but all of the bandits previously living in the outpost have been slain. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Tiragarde Sound?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 161385, 161386, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163184 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[52222] = { ["id"] = 52222, ["name"] = "Stonefist Watch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 862, ["storyline"] = { 52222 }, ["series"] = { 52221 }, ["description"] = "The raid you planned for Stonefist Watch in Tiragarde Sound was successful. Well done. The outpost is ready to be claimed. Make your way to Stonefist Watch in Tiragarde Sound and establish fortifications there. Stonefist Watch will be an essential outpost in our campaign against the Alliance. Go with honor!", ["objectivesText"] = "Claim Stonefist Watch for the Horde.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 161385, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163184 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140531, ["x"] = 0.535, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[52223] = { ["id"] = 52223, ["name"] = "Brinepinch", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52223, 52224 }, ["description"] = "You! <name>! I have a business proposition for you. There is a monstrous crab nesting in some of my favorite hunting grounds. I've already been forced out of some areas because of the sirens, I'm not about to lose more to a CRAB! Bring me the head of Brinepinch! In return I'll teach you how to get more leather when skinning. <Camilla pauses for a second before clarifying her thought.> Sorry, most creatures that wrong me have heads. Just bring me some part of it as proof of its death.", ["objectivesText"] = "Kill Brinepinch, and bring its \"head\" to Camilla Darksky . Progress: Have you slain the beast yet?", ["rewardItems"] = { 152541, 153050, 161423, 161424 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 773, ["name"] = "8.0 Professions - Gathering - Skinnin - Kul Tiras - Leather - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52224] = { ["id"] = 52224, ["name"] = "Ivory Handled Dagger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52223, 52224 }, ["description"] = "While skinning the beast, you feel a lump within the beast's stomach. Investigating further, you find what appears to be a dagger with a beautifully etched ivory handle. Carefully extracting it, you wonder if Camilla Darksky might know something about this.", ["objectivesText"] = "Return the Ivory Handled Dagger to Camilla Darksky . Provided item:", ["rewardItems"] = { 152541, 153050, 153434, 161424 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 773, ["name"] = "8.0 Professions - Gathering - Skinnin - Kul Tiras - Leather - SCS", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 161424 } },
[52225] = { ["id"] = 52225, ["name"] = "In Pursuit of Fashion", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52225, 52226 }, ["description"] = "Despite me REPEATEDLY stating that I'm not a leatherworker, one of the fat nobles of this city has commissioned me to make him a belt of 'the finest saurolisk' hide. So... I'm just going to get the materials together, give them and some of the gold to Cassandra to make the actual belt, and pocket the difference. That said, I need you to bring me saurolisk leather, enough to circle a very wide lord. For your efforts, I'll look at the skins and see if I can give you pointers on how to harvest more.", ["objectivesText"] = "Loot 3 Pristine Saurolisk Skins from Shallows Saurolisks in Drustvar. Progress: Have ya got the hides? My employer is becoming... incessant.", ["rewardItems"] = { 152541, 153050, 153434, 161424, 161425 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 774, ["name"] = "8.0 Professions - Gathering - Skinnin - Kul Tiras - Scale - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52226] = { ["id"] = 52226, ["name"] = "Turtle Soup", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52225, 52226 }, ["description"] = "I cannot believe that I'm constantly stuck in this city! You'd help me out, right? You see, I've heard about these turtles that have been living in hot springs. What makes it interesting is that some of the sulphur from the water has soaked into their scales to give them interesting patterns. I'm too busy to go check myself, but if you could go get me some of their skins, I'd be more than willing to teach you everything else I know about skinning anything with scales in exchange.", ["objectivesText"] = "Loot 5 Sulphur Speckled Skins from Enriched Rockshells. Progress: Please tell me you've got the skins.", ["rewardItems"] = { 152541, 153050, 153434, 161424, 161426 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 774, ["name"] = "8.0 Professions - Gathering - Skinnin - Kul Tiras - Scale - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52227] = { ["id"] = 52227, ["name"] = "Bone Needle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 52227, 52228 }, ["description"] = "<You see Camilla sucking blood from a wound on her hand.> Hey, can you do me a favor? I was sewing shut a battle wound in this skin, when my last bone needle broke, and now I need to get a new one. I've seen quilrats on the coast of Drustvar, one of their spines should do the trick. Bring me one in perfect condition, and I'll teach you how to harvest more bones when skinning. <Camilla looks at her hand.> Now, if you'll excuse me, I need to go see a healer before this gets infected.", ["objectivesText"] = "Collect an Immaculate Quill . Progress: I've got a lot of work backed up, waiting on a new needle. Have you got it yet?", ["rewardItems"] = { 152541, 153050, 153434, 161424, 161427 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 772, ["name"] = "8.0 Professions - Gathering - Skinnin - Kul Tiras - Bone - SCS", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52228] = { ["id"] = 52228, ["name"] = "Atal'Dazar: An Unbreakable Bone Needle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9028, ["mapID"] = 895, ["storyline"] = { 52227, 52228 }, ["description"] = "Hey, <name>, lookin' for work? I've heard through Alliance Intelligence that the trolls have a dead god or something similar. 'Rezan' I think was the name, over in Atal'Dazar. After the last time I broke a bone needle, I can't help but think that one made from the bone of a god has got to be indestructible, right? I want you to retrieve one of his bones. Or at least something big enough that I can carve an eye in and use. In return, I'll show you everything that I know about harvesting bones.", ["objectivesText"] = "Travel to Atal'Dazar and collect Rezan's Bone Fragment. Progress: I hope this works. Going the rest of my life without needing to replace that damn needle... Have ya got it?", ["rewardItems"] = { 152541, 153050, 161424, 161429, 161435 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9028 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 772, ["name"] = "8.0 Professions - Gathering - Skinnin - Kul Tiras - Bone - SCS", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52229] = { ["id"] = 52229, ["name"] = "Too Much To Bear", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52229 }, ["rewardItems"] = { 161114 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52230] = { ["id"] = 52230, ["name"] = "Loose Change", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 942, ["storyline"] = { 52230 }, ["objectivesText"] = "Lost Coins Found", ["rewardItems"] = { 158226, 160668 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Lost Coins Found", ["amount"] = 60, ["type"] = 1, ["objectID"] = 160668, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52234] = { ["id"] = 52234, ["name"] = "Hidden Amongst the Leaves", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52240, 53617 }, ["description"] = "When the Horde invaded, I did my best to thwart them but it is unknown how many forces have made passage already. This wall will slow them down, but it will not halt their attack entirely. <Malfurion's ears perk.> Do you hear that, hero? The Ancients call to us! We must protect them at all costs, <name>! They see what our eyes cannot see, and hear what our ears cannot perceive. I have druids in the Twilight Vale. Find them. Send them to the Grove of the Ancients. I will reinforce the wall.", ["objectivesText"] = "Find 8 hidden Druids of the Claw .", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 133693, ["x"] = 0.4384, ["y"] = 0.7188 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.7188 }, ["mapCandidates"] = { ["npc"] = { 57, 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 6, ["flags"] = 0 } } },
[52239] = { ["id"] = 52239, ["name"] = "Loose Change", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 942, ["storyline"] = { 52239 }, ["objectivesText"] = "Lost Coins Found", ["rewardItems"] = { 158226, 160668 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Lost Coins Found", ["amount"] = 60, ["type"] = 1, ["objectID"] = 160668, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52240] = { ["id"] = 52240, ["name"] = "Garden Grove", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52234, 53617 }, ["description"] = "Curse those goblins and their infernal machines! They are using a shredder to desecrate our sacred grove. We need that monstrosity taken down!", ["objectivesText"] = "Defeat the Monstrous Shredder .", ["rewardGold"] = 4000, ["rewardXP"] = 1770, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 8, ["flags"] = 0 } } },
[52241] = { ["id"] = 52241, ["name"] = "A Greedy Goblin's Paradise", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "The Zandalari have many powerful and ancient artifacts tucked away on this island, hidden from view. But some of their treasures are more... conspicuous. It is no surprise that Trade Prince Gallywix was unable to resist the allure of Atal'Dazar, a massive city made entirely of gold. Come with me and we will hunt him down together.", ["objectivesText"] = "Use the Magister Umbric 's Void Portal to join him in Atal'Dazar.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 161422 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140477, ["x"] = 0.406, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140712, ["x"] = 0.404, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52242] = { ["id"] = 52242, ["name"] = "The Wake of Something New", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52245 }, ["description"] = "< Onu bellows in pain.> The disturbance has become more severe. I am sensing a powerful force in our midst. It is unlike anything I have felt before. It comes from the earth itself. You and Delaryn Summermoon must seek it out, <name>. Go to the water's edge, to the place you call Nazj'vel.", ["objectivesText"] = "Find the source of Onu 's pain. Progress: Keep your head down!", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 33072, ["x"] = 0.454, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 57, 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 11, ["flags"] = 0 } } },
[52243] = { ["id"] = 52243, ["name"] = "Fuel for the Demolishers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52243 }, ["rewardGold"] = 280900, ["rewardXP"] = 3440, ["rewardItems"] = { 161436 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 148 } }, ["questType"] = "world", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[52245] = { ["id"] = 52245, ["name"] = "Enraged Furbolgs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52242 }, ["description"] = "The ancients of the forest are all connected to one another. We can sense a disturbance from deep within our roots. I can feel it now, <name>... the rumble of their footsteps in the distance, the thundering clamor of war. With every branch they break, they awaken the ancients. Soon my brethren will answer in kind, for nothing shall disrupt the balance of nature. A disturbance is near. Our kindred spirits cry for help. Seek it out and restore balance.", ["objectivesText"] = "Find those who cry for help within the Blackwood Den.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 33072, ["x"] = 0.454, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 33072, ["x"] = 0.454, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 9, ["flags"] = 0 } } },
[52246] = { ["id"] = 52246, ["name"] = "Lost Shipment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "I let grief cloud my judgment and Jaina may have already paid the ultimate price for my mistake. Yet, I hold out hope she lives. I do not know where Jaina was taken after Ashvane's people took her from the Keep. The records in their offices here in Boralus will surely tell you where they took her. <name>, you helped my people when I thought I did not need it. I ask for your help again now. Save my daughter's life!", ["objectivesText"] = "Search the Ashvane Offices for information on where Jaina was taken. Progress: Did you find what happened to Jaina?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140495, ["x"] = 0.67, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140495, ["x"] = 0.67, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52247] = { ["id"] = 52247, ["name"] = "Chasing Gallywix", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "Look at this... The goblins are looting ancient ornamentation like they're hoarding food at a buffet. What a disgrace. But we do not have time to get bogged down in everything happening here. Gallywix will soon know that we have arrived. We should not hesitate in ascending these stairs and locating Gallywix. I am certain that he will be wherever the thieves are carrying their treasure. Oh, and please do take care. The Zandalari do not typically leave places like this unguarded.", ["objectivesText"] = "Find and chase Trade Prince Gallywix. Progress: Gallywix's greed will be his undoing.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161422 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140712, ["x"] = 0.404, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 6, ["flags"] = 0 } } },
[52252] = { ["id"] = 52252, ["name"] = "An Explosive Entrance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "A hat and some smooth talking won't get us in to Freehold this time, so I'm thinking explosives. And I'm thinking we steal them from Ashvane. Fair's fair, right? She takes something from Lady Katherine, we take some Azerite empowered grenades from Ashvane. Okay, so it's not really the same, but you get where I'm going with this. Head over to Ashvane's Foundry. Grab the biggest Azerite Grenades you can get your hands on. While you do that I'm going to get us some air support.", ["objectivesText"] = "Collect 100 Large Azerite Grenades from the Ashvane Foundry. Progress: Nicely done! These are going to make quite an impact, if you'll forgive the pun.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 161438 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.757333, ["y"] = 0.697333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52253] = { ["id"] = 52253, ["name"] = "The Keys to Success in Freehold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "I've been known to be a betting man, and I'd place good odds on the information we need being in Harlan Sweete's Strongbox. This would be far too valuable to put anywhere else. I bet they haven't even moved the chest. The problem is the security features. See, the chest is locked by three keys and he gave each one to a different lieutenant. We'll need to get those. But between your skills, my finesse and Taelia's air support this will be easy.", ["objectivesText"] = "Collect the keys from Irontide Lieutenants. Progress: Nicely done! See? I knew those Irontide wouldn't be a problem for you.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 161476, 161477, 161478 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.757333, ["y"] = 0.697333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 4, ["flags"] = 0 } } },
[52256] = { ["id"] = 52256, ["name"] = "Malfurion Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52257, 52279 }, ["description"] = "Do you hear his voice? Malfurion seeks our aid! Keep your head high, <name>. The ancients stand with you this day.", ["objectivesText"] = "Find Malfurion at the Wildbend River.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 133693, ["x"] = 0.4384, ["y"] = 0.7188 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57, 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 14, ["flags"] = 0 } } },
[52257] = { ["id"] = 52257, ["name"] = "\"Rock\" The World", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52256, 52279 }, ["description"] = "We do not fight alone, <name>. This day, the ancients will bear you in their branches. Hold back nothing in your defense of our forests!", ["objectivesText"] = "Join the Ancients to slay Horde enemies. Progress: We must hold them back!", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 133693, ["x"] = 0.4384, ["y"] = 0.7188 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 133693, ["x"] = 0.4384, ["y"] = 0.7188 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.7188 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 15, ["flags"] = 0 } } },
[52258] = { ["id"] = 52258, ["name"] = "She Sells Seashells", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 52258 }, ["description"] = "Papa wanted to go fishing, and mum is working, so he brought me along. But I'm bored! I'm trying to sell some of the shells I found washed up on the beach, but nobody seems to be stopping. I don't think my shells are pretty enough... You don't seem like you're afraid of those big snakes on the beach. Can you bring me back some prettier shells? Only the shiniest please!", ["objectivesText"] = "Gather shells for Jenny. Progress: Come, let us parley... How was that? I'm trying to sound like a proper shell seller.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 71076, 161439, 161440 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140752, ["x"] = 0.61, ["y"] = 0.308 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140752, ["x"] = 0.61, ["y"] = 0.308 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.308 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[52259] = { ["id"] = 52259, ["name"] = "I Take No Pleasure In This", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "I knew that Gallywix was selfish and wasteful, but this... this is too much. His bloated pride has blacked out the sun of good leadership. He hoards the wealth of his people to satiate his gluttony, greed, and lust while his people toil under his calloused heel. And, maybe worse, opportunistic socialites from all across the Horde revel in the depravity. All people of Azeroth deserve better than this. We must teach these spoiled cowards a lesson.", ["objectivesText"] = "Crash Gallywix's party. Progress: How can they live like this while their people suffer?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 161422 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 7, ["flags"] = 0 } } },
[52260] = { ["id"] = 52260, ["name"] = "We Have Him Cornered", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 16, ["mapID"] = 76, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "Did you hear Gallywix barking orders to his servants and thugs? Still concerned with frivolities as we edge ever closer. He feels safe in his petulant palace of profits. He should not. Even here, we will strike down Trade Prince Gallywix . For the Alliance!", ["objectivesText"] = "Kill Trade Prince Gallywix . Progress: Gallywix will not be missed.", ["rewardGold"] = 929400, ["rewardXP"] = 10225, ["rewardItems"] = { 161422 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 16 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 76, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 8, ["flags"] = 0 } } },
[52261] = { ["id"] = 52261, ["name"] = "Gallywix Got Away", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52154, 52173, 52203, 52204, 52205, 52241, 52247, 52259, 52260, 52261, 53070 }, ["description"] = "I must confess my disappointment that we were not able to bring an end to Gallywix's greedy reign today. But I blame no one but myself, and will report the same to the High Commander. Your performance was exemplary, just as I expected. I hope the Alliance will not lose faith in the void elves because of this. We have much to offer. When you're ready, I will open a final Void portal to take us back to Boralus.", ["objectivesText"] = "Return to High Commander Halford Wyrmbane on the Wind's Redemption in Boralus.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 161422 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 11 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 633, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 633, ["name"] = "A Golden Opportunity", ["orderIndex"] = 9, ["flags"] = 0 } } },
