[52275] = { ["id"] = 52275, ["name"] = "Mission Report: Swiftwind Post", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52275 }, ["series"] = { 52276 }, ["description"] = "Your followers have sent a report regarding the assault on Swiftwind Post. It details that victory was hard-fought, but all of the wicker beasts previously infesting the outpost have been slain. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Drustvar?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 161449, 161483, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163193 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[52276] = { ["id"] = 52276, ["name"] = "Swiftwind Post", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 862, ["storyline"] = { 52276 }, ["series"] = { 52275 }, ["description"] = "The raid you planned for Swiftwind Post in Drustvar was successful. Well done. The outpost is ready to be claimed. Make your way to Swiftwind Post in Drustvar and establish fortifications there. Swiftwind Post will be an essential outpost in our campaign against the Alliance. Go with honor!", ["objectivesText"] = "Claim Swiftwind Post for the Horde.", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["rewardItems"] = { 161449, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163193 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 140778, ["x"] = 0.662, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[52278] = { ["id"] = 52278, ["name"] = "Rogue Azerite", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 52278 }, ["objectivesText"] = "Defeat Grixis Tinypop in a pet battle.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Defeat Fizzie Sparkwhistle", ["amount"] = 1, ["type"] = 11, ["objectID"] = 140813, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 115, ["db2QuestInfoName"] = "Battle Pet World Quest" },
[52279] = { ["id"] = 52279, ["name"] = "A Looming Threat", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1657, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52256, 52257 }, ["description"] = "If we hope to push the Horde out of our lands, we must call upon all the strength our people have to offer. Go, seek out the druids, the priestesses, our sentinels! Make the call to arms, and watch as the kaldorei rise to action. Only together can we hope to end the stalemate at the Wildbend River. When you are finished, report to Malfurion Stormrage . He awaits our fleet in Rut'theran Village.", ["objectivesText"] = "Rally the kaldorei forces in Darnassus.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 140877, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 1657 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 57, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 17, ["flags"] = 0 } } },
