[52281] = { ["id"] = 52281, ["name"] = "Under the Cover of Swiftwing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "Aye! So we be the first in this crazy operation. We'll be hitchin' a ride on Swiftwing to tha Isle of Fangs. The Zandalari got one of their main ships there, called the Breath of Pa'ku, whatever that is. Hop on ta Swiftwing when yer ready te go. It's gonna get real cozy on there with all of ye comin' aboard.", ["objectivesText"] = "Ride Swiftwing to the Isle of Fangs. Progress: Hop on!", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141287, ["x"] = 0.378, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 141290, ["x"] = 0.519333, ["y"] = 0.819333 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52282] = { ["id"] = 52282, ["name"] = "How to Sink a Zandalari Battleship", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "Let's go over our plan of attack, but remember above all things, the Zandalari cannot know our full forces are here. If they were to discover an Alliance base within the shadow of their empire... we would be wiped out in an instant.", ["objectivesText"] = "Go over the plan to weaken the Zandalari naval fleet with Halford. Progress: Let's go over the plan.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140257, ["x"] = 0.386, ["y"] = 0.728667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140257, ["x"] = 0.386, ["y"] = 0.728667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.728667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52283] = { ["id"] = 52283, ["name"] = "Sabotaging the Pa'ku", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "Our first job is to plant some bombs along these ships. I'll take care of the smaller ships, you deal with the Breath of Pa'ku. Whatever that means. Kelsey says these bombs are the latest in gnome technology. We plant 'em and she can detonate them at any time. Let's get moving, and remember, this whole plan works as long as they don't see us plantin' these bombs.", ["objectivesText"] = "Plant 4 Remote-Detonation Deathbombs beneath the Breath of Pa'ku.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141289, ["x"] = 0.525, ["y"] = 0.8265 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 141289, ["x"] = 0.525, ["y"] = 0.8265 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.8265 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52284] = { ["id"] = 52284, ["name"] = "Ship Logs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "We've got mogu and Zandalari working together on the Breath of Pa'ku. They've got records on the Zandalari fleet's ships. We've been making educated guesses regarding the Zandalari fleet. It's time to upgrade our intel. Go in there and get the naval records from anyone on board that ship. Oh, and take these jet boots. You'll need them to reach the boat if you're planting bombs on the hull.", ["objectivesText"] = "Recover 6 Naval Records from Zandalari and Mogu. Progress: Did you get those naval records ? We'll need them to better plan against the Zandalari.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 162253, 162264, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141290, ["x"] = 0.519333, ["y"] = 0.819333 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 141290, ["x"] = 0.519333, ["y"] = 0.819333 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.519333, ["y"] = 0.819333 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 4, ["flags"] = 0 } } },
[52285] = { ["id"] = 52285, ["name"] = "The Enlarged Miniaturized Submarine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "Our next target is a ship docked in a place across from here, the Warport Rastari. Lucky for you, I can get us all there in my enlarged miniaturized submarine . Shandris Feathermoon and Magister Umbric should be waiting for you on the coast of Warport Rastari. Let's get going!", ["objectivesText"] = "Ride Kelsey's Enlarged Miniaturized Submarine to Warport Rastari.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141290, ["x"] = 0.519333, ["y"] = 0.819333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.519333, ["y"] = 0.819333 }, ["mapCandidates"] = { ["npc"] = { 84, 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52286] = { ["id"] = 52286, ["name"] = "Right Beneath Their Nose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 84, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "We must continue with our primary goal, plant bombs on major Zandalari ships. There is one docked within the Warport. You know what to do. Get beneath the boat, plant the bombs, and ensure no one sees... a blood troll using bombs. My invisibility flask will give you the stealth you need, and Umbric believes the ritual will give you some other power to tap into.", ["objectivesText"] = "Plant 3 Remote-Detonation Deathbombs within the main warship in Warport Rastari. Progress: Good luck, <name>, and stay safe.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 7, ["flags"] = 0 } } },
[52287] = { ["id"] = 52287, ["name"] = "Intelligence Denial", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 84, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "There are three Horde spymasters stationed within Warport Rastari. They are giving the Zandalari information on the Alliance fleet. We need these targets killed. We cannot allow the Zandalari to get any advantageous information on our fleet. Luckily for us, your blood troll disguise means any witnesses will believe this to be a bold attack by the blood trolls.", ["objectivesText"] = "Kill Spymaster Stormhorn , Spymaster Bloodsnarl , and Spymaster Bilespreader .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 8, ["flags"] = 0 } } },
[52288] = { ["id"] = 52288, ["name"] = "Void Vacation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "The Horde have sent emissaries to help with their potential alliance with the Zandalari. These emissaries are also sharing secrets that the Horde have regarding the Alliance. We need to put a stop to this. Take this orb. It will create a void portal above the target and pull them... somewhere else.", ["objectivesText"] = "Use the Portal Orb on 6 Horde Emissaries.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141288, ["x"] = 0.4325, ["y"] = 0.71 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 141288, ["x"] = 0.4325, ["y"] = 0.71 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.4325, ["y"] = 0.71 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 9, ["flags"] = 0 } } },
[52289] = { ["id"] = 52289, ["name"] = "Victory is Assured", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 84, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "Our task is finished. You've planted the bombs on two of the Zandalari's major flagships, and Keeshan has helped with the remainder. Let's return to Halford, the sooner we're done here, the better. It's far too risky for us to be at the Zandalari's doorstep.", ["objectivesText"] = "Meet Halford Wyrmbane at Xibala in Zuldazar.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 141605, 162253, 162450 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140257, ["x"] = 0.386, ["y"] = 0.728667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = { 84, 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 10, ["flags"] = 0 } } },
[52290] = { ["id"] = 52290, ["name"] = "My Enemy's Enemy is My Disguise", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 84, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "We need you to kill several targets within Warport Rastari, but we also cannot reveal that the Alliance is here. Umbric has uncovered a ritual from Nazmir that will grant you a blood troll disguise. It is grim, but it must be done. You will go through with the ritual, then use my invisibility flask to sneak into the Warport. If discovered, the Zandalari and Horde will think it's a bold attack from the blood trolls... and not from the Alliance.", ["objectivesText"] = "Speak with Magister Umbric to be disguised as a blood troll. Progress: I know this is unpleasant, but it must be done.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 141291, ["x"] = 0.855, ["y"] = 0.319 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.855, ["y"] = 0.319 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 6, ["flags"] = 0 } } },
[52291] = { ["id"] = 52291, ["name"] = "Victory Was Assured", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "Kelsey brought back the records you retrieved on the Isle of Fangs, but it was too late. What you see before you is Gral's Call, the missing Zandalari flagship, and they've spotted us. If they make it back to port, we will have the full fury of the Zandalari empire brought down upon us. We must board the ship and eliminate every Zandalari on board. Falstad will get us there. Let's move.", ["objectivesText"] = "Fly to Gral's Call on Swiftwing .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140257, ["x"] = 0.386, ["y"] = 0.728667 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 141719, ["x"] = 0.35, ["y"] = 0.772 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.728667 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 11, ["flags"] = 0 } } },
[52297] = { ["id"] = 52297, ["name"] = "What's the Buzz?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 52297 }, ["objectivesText"] = "Defeat Grixis Tinypop in a pet battle.", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 8498, 178021, 178022, 178023, 178024, 178025, 178027, 178030, 180473, 180474 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Defeat Michael Skarn", ["amount"] = 1, ["type"] = 11, ["objectID"] = 140880, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 115, ["db2QuestInfoName"] = "Battle Pet World Quest" },
