[52301] = { ["id"] = 52301, ["name"] = "Vinespeaker Ratha", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "rare" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52301 }, ["rewardItems"] = { 158299 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[52305] = { ["id"] = 52305, ["name"] = "Nature Versus Nurture", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52305 }, ["description"] = "Greetings, <name>. I am Wingminder Goja . I overheard the ordeal that Pa'ku has laid at your feet. I can help you. I oversee this roost at my loa's pleasure. I have seen many eggs become glorious beasts of war. It will be a long road ahead, with many trials to overcome, but de companionship of a pterrordax be a worthy reward. For now, de little one is young. Simply tend to his needs while he stays in de nest. When he is ready to take on de world he will let you know. Good luck, <name>.", ["objectivesText"] = "Tend to Kua'fon until he is ready to fly.", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133678, ["x"] = 0.726, ["y"] = 0.513 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
