[52311] = { ["id"] = 52311, ["name"] = "Sweete's Strongbox", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "You've got the keys, and Taelia's still watching our backs. So let's head up to Sweete's, ah, \"office\" and liberate the documents in that strongbox. Come on, it's across the bridge with the rest of his treasure.", ["objectivesText"] = "Open Harlan Sweete's Strongbox.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.757333, ["y"] = 0.697333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 5, ["flags"] = 0 } } },
[52313] = { ["id"] = 52313, ["name"] = "Mission Report: Mudfisher Cove", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52313 }, ["series"] = { 52314 }, ["description"] = "Your followers have sent a report regarding the assault on Mudfisher Cove. It details that victory was hard-fought, but all of the guards previously defending the outpost have been slain. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Drustvar?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 161482, 161484, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163334 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
