[52428] = { ["id"] = 52428, ["name"] = "Infusing the Heart", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51211, 52428 }, ["description"] = "Azeroth's voice is growin' fainter and fainter. If the seal on this chamber shatters, her soul will be lost! We've got one chance tae save us all. Absorb the Azerite around the chamber into the Heart of Azeroth. Then unleash the amulet's power tae seal that crack in the center of the seal. Azerite can be a destructive force, but if it's channeled through yer amulet, it can heal the world!", ["objectivesText"] = "Absorb Azerite to empower the Heart of Azeroth. Progress: What are ye waitin' fer?", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 33226, 158075, 158937, 159671, 159901, 159902, 159903, 159904, 159905, 159906, 159907, 159908, 160251, 160326, 160906, 160907, 160908, 160909, 160910, 160911, 160912, 160913, 160914, 160915, 160916, 160917, 160918, 160919, 160920, 160921, 163127, 163128, 168611 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 137323, ["x"] = 0.576, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.438 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 743, ["questLineOrder"] = 1 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 785, ["questLineOrder"] = 1 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5379, ["questLineOrder"] = 1 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5379, ["questLineOrder"] = 1 } }, ["db2DetailThemeID"] = 14, ["db2PoiMapID"] = 1929, ["db2PoiUiMapID"] = 1021, ["questLines"] = { { ["id"] = 743, ["name"] = "The Heart of Azeroth", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] =