[52431] = { ["id"] = 52431, ["name"] = "No-Landing Zone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["series"] = { 49399, 49401, 49404, 49405, 49869 }, ["description"] = "These pirates are ruthless - they're bringing in landing boats to cut off our escape! The guards are down at the riverside holding them off, but I'm afraid they'll be overrun before my family and I can get away!", ["objectivesText"] = "Slay Burnsy the Blade , Wiley Jaki , and Skullcrusher Cotner . Progress: Please help the guards fend off those pirates!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 156520 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 141078, ["x"] = 0.608, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 141078, ["x"] = 0.608, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 30, ["flags"] = 0 } } },
