[52436] = { ["id"] = 52436, ["name"] = "The Blackwood Den", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["description"] = "We have not moved all of our troops into Darkshore yet, but I think we have enough to justify establishing a foothold somewhere. I know just the place. Just south of here is the Blackwood Den. Its inhabitants, the Furbolgs, have been driven in to a hysteria. With our enemies pouring from the North, the Furbolg threat is a nuisance we cannot afford. I will lead another squad past the wall while you... negotiate with the Furbolgs.", ["objectivesText"] = "Drive the furbolgs out of the Blackwood Den.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 135003, ["x"] = 0.432, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 15, ["flags"] = 0 } } },
[52437] = { ["id"] = 52437, ["name"] = "The Start of Something Good", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 53608, 53609 }, ["description"] = "While the rest of our army sets up camp -- you should follow me. I spotted something... interesting... on my way back from Zoram'gar. I'll admit, not even I could have predicted such fortuitous happenstance. Come with me, <name>. And bring a pickaxe.", ["objectivesText"] = "Follow Sylvanas to Nazj'vel.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 144346, ["x"] = 0.358, ["y"] = 0.848 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 17, ["flags"] = 0 } } },
[52438] = { ["id"] = 52438, ["name"] = "A Wild Ride", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 52806, 52967, 52970, 52971, 52981, 53610 }, ["description"] = "Let me tell ya, kid... this may be some of the best work I've ever done! Now that the upgrades are in place, there's no time to waste. The battle is raging over at Wildbend River. Take the modified hellion into battle and give 'em hell!", ["objectivesText"] = "Join the battle at Wildbend River.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 52919, 52964, 57518, 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 135501, ["x"] = 0.445333, ["y"] = 0.864667 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.445333, ["y"] = 0.864667 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 21, ["flags"] = 0 } } },
[52439] = { ["id"] = 52439, ["name"] = "Iron Stores", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 52439 }, ["description"] = "While the mine is under Alliance banners our workers ensure the iron supply never runs dry. This key will provide access to the stores. Take what you need.", ["objectivesText"] = "Use the Heavy Iron Key to access the Iron Stores. Progress: These old chests can be quite the bother.", ["rewardItems"] = { 159728 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[52440] = { ["id"] = 52440, ["name"] = "Resource Recruitment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 52440 }, ["description"] = "If we're to maintain our iron supply we'll need a bit of help. See if you can wrangle us up a few fresh recruits for the mine.", ["objectivesText"] = "Recruit 3 Highlands Peasants to work.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[52443] = { ["id"] = 52443, ["name"] = "The Final Foothold", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 53055 }, ["description"] = "We have established two critical footholds in Zandalar. The time has come to establish the third. Let's review the battle plan when you're ready.", ["objectivesText"] = "Use the Zandalar Campaign Map to review the final foothold.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 624, ["questLineOrder"] = 3 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 624, ["name"] = "The Zandalar Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5374, ["name"] = "The Zandalar Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52444] = { ["id"] = 52444, ["name"] = "The Final Foothold", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["series"] = { 53056 }, ["description"] = "We have established two critical footholds in Kul Tiras. The time has come to establish the third. Let's review the battle plan when you're ready.", ["objectivesText"] = "Use the Kul Tiras Campaign Map to review the final foothold.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 3, ["flags"] = 0 } } },
[52445] = { ["id"] = 52445, ["name"] = "Tol Dagor: The Fourth Key", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "Hey, wait a second. I know the type of key our fourth lock needs. This is the same sort of lock the Ashvane company uses. Resists lockpicks like nothing else, but they have a standard skeleton key. There was a set hanging on the wall in the Tol Dagor Armory. Given the state we left it in, it'd be easy to grab it. Taelia and I will take the chest back to the Harbormaster's office for safe keeping. You go in to Tol Dagor and get that last key!", ["objectivesText"] = "Enter the Tol Dagor dungeon, recover the Ashvane Skeleton Key and kill Overseer Korgus , then return to Flynn Fairwind in the Harbormaster's Office in Boralus. Progress: I knew securing that last key wouldn't be a problem for you, <name>!", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 162008 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.757333, ["y"] = 0.697333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 6, ["flags"] = 0 } } },
