[52447] = { ["id"] = 52447, ["name"] = "Room To Grow", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52447 }, ["description"] = "Ah, I would not worry too much about de little one. Some beasts take longer than others to find their way, and Kua'fon is no exception. For now, continue to help him grow. Keep him fed, keep him out of danger, and strengthen your bond. He will let you know when he is ready to try again.", ["objectivesText"] = "Tend to Kua'fon until he is ready to attempt another flight.", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133679, ["x"] = 0.706, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[52449] = { ["id"] = 52449, ["name"] = "The Mysterious Island", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "Fate's End is just that. It's where the very worst criminals are sent. No one ever comes back. I'm sorry Lady Katherine will have to hear this, but I'm glad it isn't my job to tell her. <Flynn hands you the document solemnly.> I'm certain she'll want an update, even if the news is as bad as this.", ["objectivesText"] = "Report to Katherine Proudmoore in Boralus.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140495, ["x"] = 0.67, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.757333, ["y"] = 0.697333 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 7, ["flags"] = 0 } } },
