[52467] = { ["id"] = 52467, ["name"] = "Battlefield Scavenging", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 52467 }, ["description"] = "Our efforts to reclaim the keep have left our supplies a bit lighter than we anticipated. If our forces are to continue, we'll need to restock. Check the enemy camps for anything of value. We'll make use of what you find.", ["objectivesText"] = "Gather supplies from Newstead, High Perch and the Circle of Elements. Progress: Find anything of interest?", ["rewardItems"] = { 158174, 158179, 162031, 162140, 162141, 162142, 162143, 163129, 163130 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "group" },
[52468] = { ["id"] = 52468, ["name"] = "Raiding Their Stores", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 52468 }, ["description"] = "Our rations are low. We need to keep our forces fed if we're to continue our efforts. Before it was overrun, Newstead had plenty of food in their stores. I only hope there's something left.", ["objectivesText"] = "Obtain a Roast Boar , a Colossal Cheese Wheel , a Basket of Eggs , and a Keg of Applebrew .", ["rewardItems"] = { 159717, 159718, 159719, 159720, 159723, 159724, 159726, 159727, 163988, 163989, 163990, 163991 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "group" },
