[52472] = { ["id"] = 52472, ["name"] = "Make Loh Go", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 52472 }, ["description"] = "Hello, <name>! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure. Care to give it a try?", ["objectivesText"] = "Learn how to guide Loh.", ["rewardXP"] = 1415, ["rewardItems"] = { 156871 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 134346, ["x"] = 0.562, ["y"] = 0.915 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 125312, ["x"] = 0.56, ["y"] = 0.888 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[52473] = { ["id"] = 52473, ["name"] = "Bringing Down the Fleet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["series"] = { 53072 }, ["description"] = "This is it, <name>. We've weakened the Horde enough to make a daring strike on Zuldazar itself. Our forces in Zuldazar still remain hidden, thanks to the help of the Dark Iron dwarves. That gives us our chance to strike. Set sail to Zuldazar. We will be gathering our forces there for a coordinated strike to weaken their harbor defenses.", ["objectivesText"] = "Speak with Grand Admiral Jes-Tereth to sail to Zuldazar.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 140257, ["x"] = 0.386, ["y"] = 0.728667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 0, ["flags"] = 0 } } },
