[52508] = { ["id"] = 52508, ["name"] = "Ritual Effects", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "I will need some assistance in conducting the ritual to allow us to gain passage to Fate's End. To help me with that, you will require the proper items and attire. Normally I have free access to these things, but the recent upheaval has blocked myself and many of my brothers and sisters from obtaining them easily. However, the fallen tidesages across the span have all you will need. Collect a ritual knife , lantern and robes from the fallen and these so-called prophets.", ["objectivesText"] = "Collected a Ritual Knife , Ritual Lantern and Ritual Robes from the Fallen Hullwardens and Abyssal Prophets in Tempest's Edge. Progress: It warms my heart to see these used for good once more.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 162423, 162425, 162429 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137691, ["x"] = 0.782, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.2528, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 9, ["flags"] = 0 } } },
[52509] = { ["id"] = 52509, ["name"] = "The Strength of the Storm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "The ritual I must conduct is written on a scroll. To gain access to it, you'll have to break through the dark energies the fallen tidesages have placed around it, with the power of the storm. This relic can be used to pull purified power from the enslaved elementals. Not only will you be gaining the means to our end, you will ultimately be freeing these spirits from corruption. Defeat the enslaved elementals and then call their power into the relic.", ["objectivesText"] = "Collected motes of Stormsurge from defeated elementals.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 162446 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137691, ["x"] = 0.782, ["y"] = 0.288 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.2528, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 10, ["flags"] = 0 } } },
[52510] = { ["id"] = 52510, ["name"] = "Shrine of the Storm: The Missing Ritual", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "The ritual which allows safe passage to Fate's End is a closely guarded secret to keep the curious from venturing there and suffering the same fate as the condemned. I have never conducted it before, but there is a scroll with instructions. It is held in the Shrine of the Storms. To access the scroll, use the staff you have empowered to break the dark energy surrounding it. Collect the Ritual of Safe Passage and bring it to me.", ["objectivesText"] = "Go into the Shrine of the Storms, recover the Ritual of Safe Passage and defeat Vol'zith the Whisperer . Progress: Were you able to recover the Ritual of Safe Passage ?", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 162456, 162462 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 137691, ["x"] = 0.782, ["y"] = 0.288 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.782, ["y"] = 0.288 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 11, ["flags"] = 0 } } },
[52511] = { ["id"] = 52511, ["name"] = "Opening the Way", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "Hmm. This ritual is a bit... tricky. No matter, together we will be able to complete it. I shall begin to channel. You will need to activate the runes in the proper order. I shall leave the scroll here so you may consult it.", ["objectivesText"] = "Complete the ritual. Progress: There we are. The clouds clear and the sea calms. Our way is open.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.2528, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 12, ["flags"] = 0 } } },
[52512] = { ["id"] = 52512, ["name"] = "Fate's End", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "Fate's End is a place in turmoil. The seas froth, the air cracks with thunder. We tried to settle there once, but each settlement disappeared into the mists, every soul never to be seen again. The island did not want inhabitants. Now we send our most vile exiles there. They never return and no one knows why. Should we find and recover Jaina, she will be the first. I hope we are not too late.", ["objectivesText"] = "Travel to Fate's End and search for signs of Jaina. Progress: By the Tides, I thought we were done for.", ["rewardGold"] = 482040, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.2528, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 13, ["flags"] = 0 } } },
[52513] = { ["id"] = 52513, ["name"] = "Lost in Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "If people are being pulled somewhere else, it would explain why no one has ever returned. I also choose to believe it means Lady Jaina might be able to be saved as well. Go back to Lady Katherine with all speed! She will want to know of this development.", ["objectivesText"] = "Return to Katherine Proudmoore in Boralus.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141223, ["x"] = 0.2528, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140495, ["x"] = 0.67, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.2528, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 895, 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 14, ["flags"] = 0 } } },
[52544] = { ["id"] = 52544, ["name"] = "The War Cache", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 47189, 51714, 51715, 52544, 52654, 53074, 53332 }, ["series"] = { 52654, 53332 }, ["description"] = "<name>. Let's talk. This war won't be won simply by adding the Kul Tirans to our ranks. We eventually need to crush the Horde. You and I will be leading an expedition to... disrupt the Horde operations in Zandalar. But first, we need resources.", ["objectivesText"] = "Gather 100 War Resources. War Resources can be obtained from many sources, including quests and treasure chests. Progress: Ready to sail when you are, <name>.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 127715, ["x"] = 0.4416, ["y"] = 0.28 }, { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 896, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 615, ["name"] = "Mission from the King", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52654] = { ["id"] = 52654, ["name"] = "The War Campaign", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 52544, 53332 }, ["description"] = "<name>, a moment of your time. Before you leave Boralus, speak with Halford Wyrmbane , High Commander of the 7th Legion. He specifically requested you by name. You can find him aboard the Wind's Redemption, which should be parked in the first slip right outside.", ["objectivesText"] = "Report to Halford Wyrmbane on the Wind's Redemption.", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 120788, ["x"] = 0.68, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.68, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 615, ["name"] = "Mission from the King", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5374, ["name"] = "The Zandalar Campaign", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52746] = { ["id"] = 52746, ["name"] = "The War Cache", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 47332, 51770, 51771, 52746, 52749, 53079, 53333 }, ["series"] = { 52749, 53333 }, ["description"] = "First things first. Remember... this is a war. We accomplish nothing by simply adding the Zandalari to our ranks. We eventually need to crush the Alliance. You and I will be leading operations in Kul Tiras. But first, we need resources.", ["objectivesText"] = "Gather 100 War Resources. War Resources can be obtained from many sources, including quests and treasure chests.", ["rewardGold"] = 257400, ["rewardXP"] = 4790, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 618, ["name"] = "Mission from the Warchief", ["orderIndex"] = 1, ["flags"] = 0 } } },
[52748] = { ["id"] = 52748, ["name"] = "Eyes on the Skies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52748 }, ["description"] = "You have made a great deal of progress with Kua'fon . He may not yet possess de power of flight, but he is healthy and growing. Take de success you have made and build upon it, <name>. Do not let Pa'ku 's lesson dishearten you. Continue to do as you have been. Nurture Kua'fon , build his confidence in his wings. Show him de way forward and he will reward you with a bond stronger than any you have ever known. When his wings are large enough to shade you, we will try again.", ["objectivesText"] = "Tend to Kua'fon until he is fully grown.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 157782, 159146 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135308, ["x"] = 0.708, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 133682, ["x"] = 0.7376, ["y"] = 0.4972 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
