[52750] = { ["id"] = 52750, ["name"] = "Farmers Who Fight", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 49405, 49736, 49737, 49738, 49740, 49869, 50110, 52431, 52750 }, ["description"] = "I was hoping for a squad of Proudmoore Academy's finest, but I guess you'll have to do. What we lack in manpower we make up for in courage! Even the farmers here won't give up their land without a fight. Send the bravest of them to me. They will fight better alongside our marines than by themselves out in the fields!", ["objectivesText"] = "Recruit 6 Vigil Hill Farmers into the militia.", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 156520 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 131048, ["x"] = 0.566, ["y"] = 0.612 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.612 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 588, ["name"] = "Defenders of Daelin's Gate", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 32, ["flags"] = 0 } } },
