[52762] = { ["id"] = 52762, ["name"] = "A Local Guide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 51445, 52194, 52246, 52252, 52253, 52311, 52445, 52449, 52453, 52481, 52482, 52483, 52484, 52485, 52486, 52487, 52488, 52508, 52509, 52510, 52511, 52512, 52513, 52762 }, ["description"] = "I've spent a lot of time as a guest of the Harbormaster and I've come to understand a few things about Flynn Fairwind . If anyone can quickly help you to sort out any clues in Freehold, it will be him. Flynn's been doing work for Cyrus and can be found in the Harbormaster's office. Show him the contract and recruit him to our cause. Hurry, <name>.", ["objectivesText"] = "Find Flynn Fairwind at the Harbormaster's office in Boralus. Progress: You fight monsters, unite kingdoms and now you're going to save a princess? You really do take on a lot of this 'hero' stuff. I just hope it doesn't catch.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 161437 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 140649, ["x"] = 0.672, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 140732, ["x"] = 0.757333, ["y"] = 0.697333 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.672, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 745, ["name"] = "The Pride of Kul Tiras", ["orderIndex"] = 2, ["flags"] = 0 } } },
[52764] = { ["id"] = 52764, ["name"] = "Journey to the Middle of Nowhere", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067 }, ["description"] = "Our tidesage, Thomas Zelling, claims to have found the wreckage of Marshal Valentine's ship. Took him long enough. Marshal Valentine's body is the final piece of our plan, and it lies within that shipwreck. When you're ready, let us depart for his resting place.", ["objectivesText"] = "Speak with Dread-Admiral Tattersail to sail to the Great Sea.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2066, ["db2PoiUiMapID"] = 1157, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 0, ["flags"] = 0 } } },
[52765] = { ["id"] = 52765, ["name"] = "Deep Dive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9937, ["mapID"] = 1157, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52764, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067 }, ["description"] = "We need you to retrieve Marshal M. Valentine's body at the ocean floor below. I should warn you: this part of the ocean is going to be very deep, and very dark, and very cold. Speak with Hobart at the starboard side of the ship. He's brought all the machinery you'll need to get to the ocean floor.", ["objectivesText"] = "Speak with Hobart Grapplehammer to dive to the ocean floor, then test your headlamp.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 133755, 166704 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9937 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2066, ["db2PoiUiMapID"] = 1157, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 1, ["flags"] = 0 } } },
