[52767] = { ["id"] = 52767, ["name"] = "Checking Dog Tags", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9937, ["mapID"] = 1157, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52764, 52765, 52766, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067 }, ["description"] = "You are no longer able to hear Hobart's voice over the static. You can make out the outlines of several floating bodies nearby. They have significantly decomposed, but their dog tags should still be intact. Hopefully the dog tags can help identify Marshal Valentine.", ["objectivesText"] = "Find and identify the captain of the shipwreck.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9937 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2066, ["db2PoiUiMapID"] = 1157, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 3, ["flags"] = 0 } } },
