[52769] = { ["id"] = 52769, ["name"] = "Captain By Captain", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9937, ["mapID"] = 1157, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52764, 52765, 52766, 52767, 52768, 52770, 52772, 52773, 52774, 52978, 53067 }, ["description"] = "Seems like you're on your own. More shipwrecks lie along the bottom of the sea. This must have been the location of a major battle. Time to start checking dog tags to find Marshal Valentine.", ["objectivesText"] = "Identify the captains of the three nearby ships.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 2842, 3342, 3343, 23405, 28144, 28153, 56867, 56868, 56869, 56870, 56871, 56872, 56873, 56874, 61484, 61495, 61500, 118736, 131242, 163633, 166704, 176116, 211279, 232771, 232775, 232779, 232787, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9937 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2066, ["db2PoiUiMapID"] = 1157, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 5, ["flags"] = 0 } } },
