[52772] = { ["id"] = 52772, ["name"] = "The Undersea Ledge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 1157, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52773, 52774, 52978, 53067 }, ["description"] = "So, now that we can hear each other again, lemme tell you what's been goin' on up here. Apparently we were off by like, a league. Somethin' about undersea currents, somethin' about the tides of time, yadda yadda. I think Zelling is getting rusty. Point is, you're not far off now. We're SURE that Marshal Valentine is right to the east of ya, in a shipwreck up on a ledge. Zelling says there's something else big up there too, but he can't tell what it is.", ["objectivesText"] = "Find Marshal Valentine's shipwreck on the undersea ledge nearby.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2066, ["db2PoiUiMapID"] = 1157, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 7, ["flags"] = 0 } } },
[52773] = { ["id"] = 52773, ["name"] = "Water-Breathing Dragon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9937, ["mapID"] = 1157, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52774, 52978, 53067 }, ["description"] = "Huh. A dragon, you say? I suppose that makes sense. I mean, the Horde did utilize red dragons as part of their army during the second war, but... well, we don't talk about that very much anymore. Still, Valentine is on that ship. You're gonna have to get past that dragon one way or another.", ["objectivesText"] = "Slay Daenistrasz .", ["rewardGold"] = 169800, ["rewardXP"] = 6815, ["rewardItems"] = { 2944 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9937 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2066, ["db2PoiUiMapID"] = 1157, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 8, ["flags"] = 0 } } },
[52774] = { ["id"] = 52774, ["name"] = "Grab and Go", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9937, ["mapID"] = 1157, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52978, 53067 }, ["description"] = "Nothin' left to do but grab that Marshal and bring him back up to the surface, then. Though I guess you might as well search the shipwreck for anything else of value. You spent all that time gettin' down there, and time is money.", ["objectivesText"] = "Grab Marshal M. Valentine's body, as well as the body of the other sailor aboard his ship.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 7298, 109258, 111921, 186201, 228658, 228741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9937 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 2066, ["db2PoiUiMapID"] = 1157, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 9, ["flags"] = 0 } } },
[52776] = { ["id"] = 52776, ["name"] = "Mission Report: Stonetusk Watch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52776 }, ["series"] = { 52777 }, ["description"] = "Your followers have sent a report regarding the assault on Stonetusk Watch. It details that victory was hard-fought, but the outpost has been secured. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Stormsong Valley?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 162512, 162530, 162531, 162532, 162533, 162534, 162535, 162536 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
