[52782] = { ["id"] = 52782, ["name"] = "Call to Arms: Stormsong Valley", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52782 }, ["description"] = "We've discovered a spike of Horde activity within Stormsong Valley . We cannot allow them to get the upper hand.", ["objectivesText"] = "Slay Horde within Stormsong Valley .", ["rewardItems"] = { 167744, 169614 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143559, ["x"] = 0.562, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 141698, ["x"] = 0.565, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "pvp" },
[52784] = { ["id"] = 52784, ["name"] = "The Horde Slayer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 52784 }, ["description"] = "Wow! Keep it up, soldier! Slay a bit more Horde and you will go down in the record books among the Alliance. But it won't be easy, the Horde have put a bounty on your head, so watch it! For the Alliance!", ["objectivesText"] = "While being hunted by the Horde, slay 10 Horde without dying.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[52786] = { ["id"] = 52786, ["name"] = "The Alliance Slayer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 52786 }, ["description"] = "Yes! Keep going, keep slaying those Alliance dogs! Slay a bit more Alliance and you may set a new record, <class>. But it won't be easy, the Alliance have put a bounty on your head, so watch it! For the Horde!", ["objectivesText"] = "With a bounty on your head, slay 10 Alliance without dying.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[52787] = { ["id"] = 52787, ["name"] = "Numbing the Pain", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 46727, 46728, 46729, 47098, 47099, 47181, 47186, 47189, 47485, 47486, 47487, 47488, 47489, 47960, 48419, 48505, 48539, 48558, 48773, 49239, 49398, 49399, 49401, 49404, 49405, 49736, 49737, 49738, 49740, 49741, 49869, 50110, 50531, 50573, 50787, 50788, 50789, 50790, 50795, 50972, 51341, 52128, 52431, 52750, 52787, 53041, 59641 }, ["description"] = "The medics here are doing their best, but they've suffered heavy casualties and are strapped for healing supplies. With a few clumps of evermoss I could mix a painkilling tincture to ease the suffering of the injured. Can you forage some from the nearby trees? I'll help get Flynn stabilized. The last thing these people need is another wounded man howling in pain.", ["objectivesText"] = "Gather 5 Evermoss Clumps . Progress: Did you find any evermoss?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 162522 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 142393, ["x"] = 0.564, ["y"] = 0.615 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 121235, ["x"] = 0.731333, ["y"] = 0.23 }, { ["mapID"] = 895, ["npcID"] = 142393, ["x"] = 0.564, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.564, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 215, ["title"] = "Battle for Azeroth", ["questLineID"] = 5372, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 5372, ["name"] = "Trouble in Tiragarde Sound", ["orderIndex"] = 37, ["flags"] = 0 } } },
[52789] = { ["id"] = 52789, ["name"] = "Silencing the Advisor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 875, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "The ship's captain is nowhere to be found. Shandris and Falstad will handle locating him. We must go after the ship's advisor. Kelsey's logs indicate her name is Ko'jan. She may have methods to reach out to the mainland. We have to move before she tries to use any of them.", ["objectivesText"] = "Kill Advisor Ko'jan . Progress: Let's get moving.", ["rewardGold"] = 584200, ["rewardXP"] = 8520, ["rewardItems"] = { 162253, 162450 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 875, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 13, ["flags"] = 0 } } },
[52790] = { ["id"] = 52790, ["name"] = "An End to the Killing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52281, 52282, 52283, 52284, 52285, 52286, 52287, 52288, 52289, 52290, 52291, 52473, 52788, 52789, 52790, 53072, 53098 }, ["description"] = "Let's return to the upper decks and see what our current status is. Shandris should be there by now. I know Shandris and Falstad well enough that they will be there with the captain of this ship, dead or alive.", ["objectivesText"] = "Meet Shandris Feathermoon on the deck of Gral's Call.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 162253, 162450 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 140257, ["x"] = 0.386, ["y"] = 0.728667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.728667 }, ["mapCandidates"] = { ["npc"] = { 84, 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 13 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 737, ["questLineOrder"] = 6 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 737, ["name"] = "The Strike on Zuldazar", ["orderIndex"] = 14, ["flags"] = 0 } } },
