[52793] = { ["id"] = 52793, ["name"] = "Circle the Wagons", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52793 }, ["description"] = "Darion and the girls should have been back by now. Maybe they had trouble on the road, that old wagon is always breaking down. I need to be sure they are safe! Can you check on them for me?", ["objectivesText"] = "Find Darion, Lorraine, and Mallory. Progress: I'm getting worried, they should have been here hours ago.", ["rewardGold"] = 257400, ["rewardXP"] = 3085, ["rewardItems"] = { 55121, 63550, 63551, 63552, 63553, 63554, 63555, 63556, 63557, 131434, 131435 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141769, ["x"] = 0.602, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 141769, ["x"] = 0.602, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
