[52795] = { ["id"] = 52795, ["name"] = "A Saur Point", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52795 }, ["description"] = "That saurolisk has been a folktale in these hills for years. \" Sourtooth , you can smell his breath from miles away\". Today that folktale attacked my family, almost killed my father and sister. It's time for it to die.", ["objectivesText"] = "Slay Sourtooth Progress: I'm not leaving till Sourtooth is dead!", ["rewardGold"] = 561800, ["rewardXP"] = 5145, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141603, ["x"] = 0.648, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 141603, ["x"] = 0.648, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[52796] = { ["id"] = 52796, ["name"] = "Sometimes Less Is More", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 52796 }, ["description"] = "I don't really hate saurolisk, but there seem to be a lot more around lately. Stormsong's military used to thin out the population, but they didn't show up this year. Maybe you could do the job they didn't!", ["objectivesText"] = "Eliminate 8 Saurolisk.", ["rewardGold"] = 309800, ["rewardXP"] = 3085, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 141769, ["x"] = 0.602, ["y"] = 0.705 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 141769, ["x"] = 0.602, ["y"] = 0.705 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.705 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
