[52800] = { ["id"] = 52800, ["name"] = "Tol Dagor: The Ashvane Overseer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["storyline"] = { 52800 }, ["description"] = "Tol Dagor stands as a well fortified thorn in this nation's side. As you are no doubt aware, Ashvane has taken every opportunity she could to throw any opposition into those cells. Among those in the jail are members of the Alliance that arrived alongside you and Jaina. We now have permission and the needed muscle to free them. Meet up with Taelia on the eastern shore of the island, find the overseer, and take his key. With it, we will have access to the weapon vault and cells.", ["objectivesText"] = "Retrieve the Tol Dagor Master Key from Overseer Korgus . Progress: Well?", ["rewardGold"] = 1029600, ["rewardXP"] = 2830, ["rewardItems"] = { 163161 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "dungeon" },
