[52834] = { ["id"] = 52834, ["name"] = "Seal of Wartorn Fate: Gold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1165, ["storyline"] = { 52834 }, ["objectivesText"] = "Progress: Do you ever wish to retry your fate? Perhaps, for a special armor piece, a weapon or a trinket of great power? For a price, I will provide you a seal that twists fate and grants an extra result at a past chance. Once you possess a seal, it will activate after defeating powerful foes in difficult dungeons and raids. Choose how you want to pay wisely, for two seals a week is all the power you can manage.", ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 141584, ["x"] = 0.539, ["y"] = 0.885 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.539, ["y"] = 0.885 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
