[52855] = { ["id"] = 52855, ["name"] = "Alchemy is an Inexact Science", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 52855 }, ["description"] = "Hey, look. It worked, right? Mostly. I mean, it DID get bigger. Don't look at me like that! So there are some... weird side effects going on. When has that ever gotten in the way of science before? Okay, okay, okay! I have an idea. Go and get me everything on this list. And be quick about it! I think these Zandalari might do something to me if you-- if WE-- don't fix this. <Alexxi hastily pens a list of ingredients and hands it to you.> Do me a solid, eh?", ["objectivesText"] = "Gather 1 Crown of Torcali and 8 Glowfly Incandescence for Trader Alexxi in Warbeast Kraal. Progress: Those claws look really sharp, <name>. Do you have what I need?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 162586, 162587 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 122129, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
