[52943] = { ["id"] = 52943, ["name"] = "Calling Out the Clans", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9786, ["mapID"] = 1170, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["description"] = "This Overlord Geya'rah has a fire inside her. I may come to like her... if she doesn't kill us. We have but one chance. You pay homage to the symbol of each clan, and I will speak of it. Show respect--or they will show us the executioner's blade.", ["objectivesText"] = "Pay homage to the orc clan symbols. Progress: I do not have time for this.", ["rewardGold"] = 331700, ["rewardXP"] = 5465, ["rewardItems"] = { 161330 }, ["starts"] = { { ["mapID"] = 1170, ["npcID"] = 142422, ["x"] = 0.432, ["y"] = 0.5332 } }, ["ends"] = { { ["mapID"] = 1170, ["npcID"] = 142109, ["x"] = 0.447, ["y"] = 0.6195 } }, ["coords"] = { ["mapID"] = 1170, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.5332 }, ["mapCandidates"] = { ["npc"] = { 1170 }, ["zone"] = { 9786 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1917, ["db2PoiUiMapID"] = 1170, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 6, ["flags"] = 0 } } },
