[52945] = { ["id"] = 52945, ["name"] = "Bonds Forged Through Battle", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9786, ["mapID"] = 1170, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["description"] = "Geya'rah has a fiery spirit... like her mother. Perhaps facing a common foe will ease her wariness. We subdued the ogre clans long ago. But every so often, one of their bravest--and stupidest--stirs the embers of rebellion. Today is such a day. You and Eitrigg will join Geya'rah in putting down the ogre uprising. Prove yourself in battle and you may earn her respect.", ["objectivesText"] = "Assist Geya'rah in putting down the ogre uprising. Progress: Don't slow me down.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 161330, 162025 }, ["starts"] = { { ["mapID"] = 1170, ["npcID"] = 142275, ["x"] = 0.449, ["y"] = 0.617 } }, ["coords"] = { ["mapID"] = 1170, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.617 }, ["mapCandidates"] = { ["npc"] = { 1170 }, ["zone"] = { 9786 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1917, ["db2PoiUiMapID"] = 1170, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 7, ["flags"] = 0 } } },
