[52955] = { ["id"] = 52955, ["name"] = "Tyranny of the Light", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["description"] = "If it is not an uprising of ogres or the promise of starvation, it's the constant threat of the Lightbound. Should the reports prove true, this is the closest they have dared approach our stronghold in quite some time. Come or stay, but make your decision quickly.", ["objectivesText"] = "Assist Geya'rah against the Tyranny of the Light.", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 161330 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 143845, ["x"] = 0.412, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 8, ["flags"] = 0 } } },
