[52962] = { ["id"] = 52962, ["name"] = "Mission Report: Mistvine Ledge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 52962 }, ["series"] = { 52963 }, ["description"] = "Your followers have sent a report regarding the assault on Mistvine Ledge. It details that victory was hard-fought, but the enemies surrounding the outpost have been slain. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", ["objectivesText"] = "Deliver the victory report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Zuldazar?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 162646, 163044 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
