[52967] = { ["id"] = 52967, ["name"] = "Saurfang Returns", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 52438, 52806, 52970, 52971, 52981, 53610 }, ["description"] = "Saurfang! It's about time. Look around you, hero! What a lovely sight -- the wisps are scattering. One by one, the walls come crashing down. Now is the time. The World Tree is ours for the taking! Find Saurfang. We shall finish this once and for all.", ["objectivesText"] = "Find Saurfang in Lor'danel.", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 142310, ["x"] = 0.513333, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 23, ["flags"] = 0 } } },
