[52971] = { ["id"] = 52971, ["name"] = "Seaside Rendezvous", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 52438, 52806, 52967, 52970, 52981, 53610 }, ["description"] = "Lor'danel has mustered significant reinforcements on its shore. Enough to drive us back. One swift strike and we can end this threat! You will break through their lines and slay the two commanders. Without leadership this force will crumble.", ["objectivesText"] = "Kill Caranne Briarbow and Ariel Stagguard", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 142310, ["x"] = 0.513333, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 142310, ["x"] = 0.513333, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.513333, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 26, ["flags"] = 0 } } },
