[52973] = { ["id"] = 52973, ["name"] = "A Threat from the North", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 141, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52974, 52975, 52977, 53622 }, ["description"] = "The Horde must have scaled the mountains of Felwood in the North. The wisp wall is failing, it is only a matter of time before the Horde breaks through. They will attack us from both sides. We must weather this attack together.", ["objectivesText"] = "Find Malfurion Stormrage in Lor'danel.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 163127 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 140877, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 141 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["db2QuestSortName"] = "Paladin", ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 18, ["flags"] = 0 } } },
[52974] = { ["id"] = 52974, ["name"] = "Rescue Effort", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52973, 52975, 52977, 53622 }, ["description"] = "The suddenness of the Horde's attack gave citizens here little time to flee. Many are hiding in Lor'danel, waiting for help. Locate these civilians and send them to safety. We're counting on you, <name>.", ["objectivesText"] = "Rescue 8 Lor'danel citizens .", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 163127 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 140877, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 19, ["flags"] = 0 } } },
[52975] = { ["id"] = 52975, ["name"] = "Action This Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52973, 52974, 52977, 53622 }, ["description"] = "Two of the Horde's strongest warriors have led a charge to try and capture our fleet. We cannot allow this, <name>. If they take our ships, they will use them to sail to Darnassus! Slay the two warriors leading the attack, and the rest of them will give up the fight.", ["objectivesText"] = "Eliminate Gormok Axefall , and Ragash Bloodwish .", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 163127 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 21, ["flags"] = 0 } } },
[52977] = { ["id"] = 52977, ["name"] = "The Guidance of Our Shan'do", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1657, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52973, 52974, 52975, 53622 }, ["description"] = "Lor'danel is overrun. The Horde... they -- they just don't relent. There is nothing we can do, <name>. We must find our Shan'do and ask for his guidance. He is the only one who can save us.", ["objectivesText"] = "Find Malfurion Stormrage in Darkshore.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 163127 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 89, ["npcID"] = 142978, ["x"] = 0.432667, ["y"] = 0.784 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57, 89 }, ["zone"] = { 1657 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 89, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 22, ["flags"] = 0 } } },
[52978] = { ["id"] = 52978, ["name"] = "With Prince in Tow", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9937, ["mapID"] = 862, ["storyline"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 52978, 53067, 53121 }, ["series"] = { 52764, 52765, 52766, 52767, 52768, 52769, 52770, 52772, 52773, 52774, 53067 }, ["description"] = "Let's set sail for Zandalar. In case you hadn't noticed, we've been dealing with a bit of Alliance interference while you were gone.", ["objectivesText"] = "Speak with Dread-Admiral Tattersail to return to Zuldazar.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 245470 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9937 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 13 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 736, ["questLineOrder"] = 5 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 736, ["name"] = "At the Bottom of the Sea", ["orderIndex"] = 11, ["flags"] = 0 } } },
