[53028] = { ["id"] = 53028, ["name"] = "A Dying World", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 85, ["storyline"] = { 51211, 52428, 53028 }, ["description"] = "Champion. Magni Bronzebeard needs your help. Azeroth is dying. Before this war, a massive demon called Sargeras stabbed the planet with a sword. Our planet cries out in pain while the Horde and Alliance fight amongst each other. Magni Bronzebeard believes you can help heal the planet's wounds. Meet him in Silithus. He has set up camp where Sargeras's sword impacted our world.", ["objectivesText"] = "Meet Magni Bronzebeard in Silithus, located within Kalimdor.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128, 166556 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 140176, ["x"] = 0.49, ["y"] = 0.915 }, { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 }, { ["mapID"] = 1165, ["npcID"] = 154465, ["x"] = 0.506, ["y"] = 0.6505 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.915 }, ["mapCandidates"] = { ["npc"] = { 81, 85, 1161, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 785, ["questLineOrder"] = 1 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5379, ["questLineOrder"] = 1 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5379, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 785, ["name"] = "The Heart of Azeroth", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5379, ["name"] = "The Heart of Azeroth", ["orderIndex"] = 0, ["flags"] = 0 } } },
