[53043] = { ["id"] = 53043, ["name"] = "Mission Report: Vulture's Nest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53043 }, ["series"] = { 53044 }, ["description"] = "Your followers have sent a report regarding the mission to capture Vulture's Nest in Vol'dun. It details that the mission was a success and that the troops holding the outpost have requested reinforcements. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", ["objectivesText"] = "Deliver the victory report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Vol'dun?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 163039, 163041 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53044] = { ["id"] = 53044, ["name"] = "Vulture's Nest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 1161, ["storyline"] = { 53044 }, ["series"] = { 53043 }, ["description"] = "The mission to take Vulture's Nest in Vol'dun was successful. Well done. The outpost is ready to be claimed. Make your way to Vulture's Nest and establish fortifications there. It will be an essential outpost in our campaign against the Horde. For the Alliance!", ["objectivesText"] = "Claim Vulture's Nest for the Alliance.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 162553, 162577, 162604, 162646, 162977, 163039, 163041, 163043, 163044, 163046, 163047, 163048 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 142555, ["x"] = 0.536, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 864, 1161 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[53045] = { ["id"] = 53045, ["name"] = "Surveying the Wharf", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53045 }, ["description"] = "Thresher's Wharf is a bustling fishing hub just across the delta from Fort Daelin. It was also in the direct war path of the naga -- who knows what remains now. If you could stop in and check in on its leader, Coxswain Hook , you'd have my gratitude. I must focus on tending to the wounded here and preparing for the naga's next assault.", ["objectivesText"] = "Speak to Coxswain Hook in Thresher's Wharf.", ["rewardGold"] = 28090, ["rewardXP"] = 515, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131001, ["x"] = 0.347, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 133576, ["x"] = 0.26, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.347, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[53050] = { ["id"] = 53050, ["name"] = "Deeper Into Kul Tiras", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51224, 51231, 51233, 51234, 51332, 51340, 51421, 51435, 51436, 51437, 51438, 51439, 51440, 51441, 51442, 51526, 51532, 51536, 51587, 51643, 51674, 51675, 51691, 51696, 51753, 51800, 51801, 51802, 51803, 51916, 51975, 51979, 51984, 51985, 51986, 51987, 52444, 52451, 52749, 53050, 53056, 53064 }, ["series"] = { 51979 }, ["description"] = "It is time for us to further our hold on Kul Tiras. Return to the Banshee's Wail. From there we shall plan our next course of action.", ["objectivesText"] = "Meet with Nathanos Blightcaller on the Banshee's Wail in the Port of Zandalar.", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5388, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5388, ["name"] = "Gaining a Foothold", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53052] = { ["id"] = 53052, ["name"] = "Deeper Into Zandalar", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 51088, 51129, 51150, 51167, 51168, 51169, 51170, 51177, 51190, 51191, 51192, 51193, 51201, 51229, 51279, 51280, 51281, 51282, 51283, 51308, 51309, 51331, 51349, 51350, 51351, 51359, 51366, 51369, 51389, 51391, 51394, 51395, 51402, 51418, 51544, 51569, 51570, 51571, 51572, 51918, 51961, 51967, 51968, 51969, 52003, 52008, 52013, 52443, 52450, 52654, 53052, 53055, 53063 }, ["series"] = { 51961 }, ["description"] = "Our advisors have decided that now is the correct time to further our hold on Zandalar. Return to the Wind's Redemption posthaste. We shall leave for new lands immediately.", ["objectivesText"] = "Meet with Halford Wyrmbane on the Wind's Redemption in Boralus Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 600, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 624, ["questLineOrder"] = 3 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5378, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 624, ["name"] = "The Zandalar Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5374, ["name"] = "The Zandalar Campaign", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5378, ["name"] = "Gaining a Foothold", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5380, ["name"] = "Gaining a Foothold", ["orderIndex"] = 4, ["flags"] = 0 } } },
