[53073] = { ["id"] = 53073, ["name"] = "Hook Point Investigation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53073 }, ["description"] = "I'm sure you've heard the constant sound of battle coming from Hook Point. We sent scouts over to find out why the fighting never seems to end, and discovered an unexpected training ground. Daniel Poole at Hook Point is running some sort of fight circuit near the Tradewind Market. Seek out Grand Marshal Tremblade at our War Headquarters and find out what they've learned.", ["objectivesText"] = "Speak with Grand Marshal Tremblade at Hook Point.", ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143559, ["x"] = 0.562, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "pvp" },
[53074] = { ["id"] = 53074, ["name"] = "Reinforcements", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 47189, 51714, 51715, 52544, 52654, 53074, 53332 }, ["series"] = { 51714, 51715 }, ["description"] = "The resources you gather can be used to recruit new troops for the war effort. Return to me periodically to issue new recruitment orders for your missions. If you have available resources, you should use them now to issue your first recruitment order. The war effort rages on even as we speak. We have need of fresh recruits.", ["objectivesText"] = "Speak with Mathias Shaw to issue a recruitment order. Progress: Have you issued the recruitment order?", ["rewardGold"] = 140450, ["rewardXP"] = 2395, ["rewardItems"] = { 29927, 29932, 29935, 29939, 29946, 63909, 63910, 63911, 175414, 175427, 175428, 175429, 211279, 237812 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 615, ["name"] = "Mission from the King", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53075] = { ["id"] = 53075, ["name"] = "Dueler's Guild", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53075 }, ["description"] = "I figured a war-torn <race> such as your self would benefit from training in the Dueler's Guild. Speak with a nearby bouncer to participate in the carnage.", ["objectivesText"] = "Speak with a nearby bouncer .", ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143559, ["x"] = 0.562, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143559, ["x"] = 0.562, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "pvp" },
