[53110] = { ["id"] = 53110, ["name"] = "The High Thornspeaker", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 48179, 48180, 48182, 48183, 52074, 52075, 53110 }, ["description"] = "My teacher, Ulfar , the High Thornspeaker, must be informed of what's been going on here. I can't leave just yet. There are too many wounded and we'll need to handle the last few remaining constructs. You have proven trustworthy, friend. Take a few of these runic cores to Ulfar for me. Arthur will meet you at the head of the path to Ulfar 's den.", ["objectivesText"] = "Take the Runic Power Cores to Ulfar . Progress: What do you have there, mainlander?", ["rewardGold"] = 280900, ["rewardXP"] = 2765, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 141159, ["x"] = 0.452, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5441, ["name"] = "Drustvar Ruins", ["orderIndex"] = 6, ["flags"] = 0 } } },
