[53122] = { ["id"] = 53122, ["name"] = "A Season for Celebration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Hallow's End", ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 94, ["storyline"] = { 53122 }, ["series"] = { 29376, 29400 }, ["description"] = "Well met, <class>. Hallow's End is a time for celebration and reflection, though some have no idea why. The burning of the Wickerman in particular is a mystery to many outside the Forsaken. Travel to the Ruins of Lordaeron and speak to Darkcaller Yanka . She can tell you more about the Wickerman ceremony.", ["objectivesText"] = "Speak with Darkcaller Yanka in the Ruins of Lordaeron.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 94, ["npcID"] = 19169, ["x"] = 0.542, ["y"] = 0.508 }, { ["mapID"] = 85, ["npcID"] = 19175, ["x"] = 0.545667, ["y"] = 0.709667 }, { ["mapID"] = 85, ["npcID"] = 19176, ["x"] = 0.402, ["y"] = 0.5615 }, { ["mapID"] = 85, ["npcID"] = 19177, ["x"] = 0.440857, ["y"] = 0.667714 }, { ["mapID"] = 90, ["npcID"] = 19178, ["x"] = 0.648923, ["y"] = 0.442154 }, { ["mapID"] = 10, ["npcID"] = 20102, ["x"] = 0.6805, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 15197, ["x"] = 0.62, ["y"] = 0.678 } }, ["coords"] = { ["mapID"] = 94, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 10, 18, 85, 90, 94 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[53125] = { ["id"] = 53125, ["name"] = "Mission Report: Into The Wicker", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53125 }, ["series"] = { 53126 }, ["description"] = "Your followers have sent a report regarding the mission at Mudfisher Cove. It details that the mission was a success and the druids there have upgraded their druidic knowledge as a result. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the victory report to Nathanos Blightcaller . Progress: Do you have news regarding the mission at Fairwind Post?", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 161482, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163334, 163335 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53126] = { ["id"] = 53126, ["name"] = "The Wicker Totem", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53126 }, ["series"] = { 53125 }, ["description"] = "The defense of Mudfisher Cove was successful. Well done, <name>. A mysterious totem was found in the aftermath of the battle that may prove useful to you during your adventures in Drustvar. Travel to Mudfisher Cove in Drustvar and see what power this totem contains.", ["objectivesText"] = "Speak with Garn Blackwolf .", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["rewardItems"] = { 161482, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163334 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 140947, ["x"] = 0.624, ["y"] = 0.17 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 896 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53127] = { ["id"] = 53127, ["name"] = "The Lord Admiral's Lament", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53127 }, ["description"] = "The footlocker contains a number of Lord Admiral Daelin Proudmoore's personal effects. Among them is a rolled letter, sealed with sea-green wax and stamped with the Proudmoore crest. The parchment tears easily and requires careful handling and it appears that the ink has been largely washed away by tide and time. Perhaps someone can restore the letter and reveal its contents.", ["objectivesText"] = "Take the Illegible Correspondence to someone in Orgrimmar . Progress: What's this?", ["rewardXP"] = 6815, ["rewardItems"] = { 163336 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 139093, ["x"] = 0.48, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
