[53129] = { ["id"] = 53129, ["name"] = "Bloodied Sentinel's Glaive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 85, ["storyline"] = { 53129 }, ["description"] = "The glaive rests inches from the sentinel's outstretched fingertips. Her eyes stare, sightless, at the ashen husk of Teldrassil on the horizon. Perhaps someone in Orgrimmar can tell you what happened here.", ["objectivesText"] = "Take the Bloodied Sentinel's Glaive to Isabella in Orgrimmar . Progress: Yes?", ["rewardXP"] = 6815, ["rewardItems"] = { 163386 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 139093, ["x"] = 0.48, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 148 } }, ["questType"] = "standard" },
