[53146] = { ["id"] = 53146, ["name"] = "Boulderfist Beatdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53146 }, ["description"] = "The Boulderfist ogres have plagued Arathi since the Second War, and they still remain. You know what must be done.", ["objectivesText"] = "Kill 20 Boulderfist clan ogres in Arathi Highlands . Progress: Boulderfist ogres still plague Arathi.", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.203, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53148] = { ["id"] = 53148, ["name"] = "Boulderfist Beatdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53148 }, ["description"] = "If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi. You know what must be done.", ["objectivesText"] = "Kill 20 Boulderfist clan ogres in Arathi Highlands .", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.267333, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 14, 1165 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53149] = { ["id"] = 53149, ["name"] = "Wiping Out the Witherbark", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53149 }, ["description"] = "The Witherbark tribe has a long and bloody history in the highlands of Arathi. Show them how much bloodier it can get.", ["objectivesText"] = "Kill 20 Witherbark tribe trolls in Arathi Highlands . Progress: Witherbark drums still echo across the Highlands.", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.203, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53150] = { ["id"] = 53150, ["name"] = "Wiping Out the Witherbark", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53150 }, ["description"] = "The bloodthirsty Witherbark tribe has always refused to join the Horde... and now that the Horde holds Arathi, we will succeed where the Alliance has failed. Drive the forest trolls from the Highlands.", ["objectivesText"] = "Kill 20 Witherbark tribe trolls in Arathi Highlands .", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.267333, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 14, 1165 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53151] = { ["id"] = 53151, ["name"] = "Mission Report: Wolves For The Den", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53151 }, ["series"] = { 53152 }, ["description"] = "Your followers have sent a report regarding the mission at Wolf's Den. It details that the mission was a success and that a pack of direwolves now guard the outpost. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the mission report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Tiragarde Sound?", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 161121, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163507, 163519 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53152] = { ["id"] = 53152, ["name"] = "Wolves for the Den", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53152 }, ["series"] = { 53151 }, ["description"] = "The mission at Wolf's Den in Tiragarde Sound was a success. Well done, <name>. A pack of direwolves now patrols the area surrounding the outpost. Travel to Wolf's Den and see that the training of the wolves is up to our standard.", ["objectivesText"] = "Speak with Mukkral Blackvein .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 161121, 162530, 162531, 162532, 162533, 162534, 162535, 162536, 163507 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 139561, ["x"] = 0.624, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53153] = { ["id"] = 53153, ["name"] = "Death to The Defilers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53153 }, ["description"] = "Even with the destruction of Undercity, the Defilers continue to combat our hold on the Arathi Highlands . The farmland at Go'Shek will belong to the Alliance once more. Go, and defeat the Forsaken.", ["objectivesText"] = "Kill 20 Defilers at Go'Shek Farm. Progress: The Defilers still hold Go'Shek Farm.", ["rewardXP"] = 850, ["rewardItems"] = { 164578 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.203, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53154] = { ["id"] = 53154, ["name"] = "The League Will Lose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53154 }, ["description"] = "Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands. The northern farmland will belong to the Horde. Go, and defeat the humans.", ["objectivesText"] = "Kill 20 League of Arathor at Dabyrie's Farmstead.", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.267333, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 14, 1165 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53155] = { ["id"] = 53155, ["name"] = "Notched Coin", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 53155 }, ["description"] = "<This old, worn coin has clearly changed hands many times. The edges are rusty from years in the salty air of the Great Sea, and it features an unusual design. You saw a number of these coins scattered around the island, they appear to be quite commonly used.>", ["objectivesText"] = "Bring the Notched Coin to Mili Wanderbrew in Jade Forest. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163466 }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 64365, ["x"] = 0.552, ["y"] = 0.192 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.192 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["startItems"] = { 163466 } },
[53159] = { ["id"] = 53159, ["name"] = "Arathi Donations: Coarse Leather", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53159 }, ["description"] = "It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come. Let's make sure our allies are well prepared.", ["objectivesText"] = "Donate 60 Coarse Leather to Charlane in Boralus Harbor. Progress: Should you find any additional leather in your hunt, you know where to find me.", ["rewardItems"] = { 152541 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53161] = { ["id"] = 53161, ["name"] = "Ring of the Reefs", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 53161 }, ["description"] = "<A light mist twists and curls around this ring as if caressing it. Holding this object makes you uneasy, deep within your soul. It feels as if invisible, icy hands from the lands of the dead are pulling at you. There is no mistaking Helya's power. The Valarjar will want to hear about this.>", ["objectivesText"] = "Solve the riddle. Provided item:", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 163471 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 106904, ["x"] = 0.602, ["y"] = 0.512 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.602, ["y"] = 0.512 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["startItems"] = { 163471 } },
[53162] = { ["id"] = 53162, ["name"] = "Sins of the Syndicate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53162 }, ["description"] = "As if the Defilers were not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Alliance farmers. Punish them.", ["objectivesText"] = "Kill 20 Syndicate members at Dabyrie's Farmstead.", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.203, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53163] = { ["id"] = 53163, ["name"] = "Bloodwake Drinking Horn", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 53163 }, ["description"] = "<A large drinking horn taken from one of the Bloodwake vrykul. The sturdy craftsmanship has allowed it to survive many years of hard travel on the Great Sea. As you hold the horn, you remember how fervently the vrykul you encountered were after the Azerite , but to what end? Other vrykul tribes may know more about the Bloodwake and their motivations.>", ["objectivesText"] = "Bring the horn to the wise Vydhar . Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 140192, 163472 }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 93231, ["x"] = 0.685, ["y"] = 0.542 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.685, ["y"] = 0.542 }, ["mapCandidates"] = { ["npc"] = { 634 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["startItems"] = { 163472 } },
[53164] = { ["id"] = 53164, ["name"] = "Sonic Stone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5842, ["mapID"] = 388, ["storyline"] = { 53164 }, ["description"] = "<The stone vibrates to your touch. The frequency resonates throughout your body, and you feel refreshed. The mantid likely use these stones to allow them to fly great distances across the sea. To see them on the island was strange, the mantid took a heavy blow when Shek'zeer was destroyed, they should not be swarming now. The denizens of Pandaria may have more information.>", ["objectivesText"] = "Show the stone to Sentinel Commander Qipan in Townlong Steppes. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163473 }, ["ends"] = { { ["mapID"] = 388, ["npcID"] = 61584, ["x"] = 0.394, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 388, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 388 }, ["zone"] = { 5842 } }, ["questType"] = "standard", ["startItems"] = { 163473 } },
[53165] = { ["id"] = 53165, ["name"] = "Stopping Antiquities Theft", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53165 }, ["objectivesText"] = "Goblin Treasure Thieves", ["rewardItems"] = { 163048 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Goblin Treasure Thieves", ["amount"] = 10, ["type"] = 0, ["objectID"] = 140716, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[53167] = { ["id"] = 53167, ["name"] = "Icetusk Fur Cloak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 53167 }, ["description"] = "<The fur on this cloak is worn and tattered, but it is still warm. It has seen many years in the harsh, unforgiving blizzards of the north. The icetusk tribe has not been seen on Azeroth until now, someone in Northrend might know more about them.>", ["objectivesText"] = "Show the fur to Tua'kea in Dragonblight. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163474 }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26245, ["x"] = 0.478, ["y"] = 0.763 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.763 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["startItems"] = { 163474 } },
[53168] = { ["id"] = 53168, ["name"] = "Magical Spyglass", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 53168 }, ["description"] = "<This spyglass allows you to see far off into the distance, but looking through it for too long gives you a headache. The lens appears to have been specifically crafted for someone else's eyes. Given the intricate detail on the spyglass, they'd likely provide a hefty reward for its return.>", ["objectivesText"] = "Return the spyglass. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163475, 163482 }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 2496, ["x"] = 0.41, ["y"] = 0.73 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.73 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["startItems"] = { 163475 } },
[53169] = { ["id"] = 53169, ["name"] = "Elemental Core", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 53169 }, ["description"] = "<A burned-out core from the elementals you encountered. When you concentrate, you can sense that some elemental energy still exists, deep within the core. They were clearly after the Azerite , but why? It might be time to call in an old favor.>", ["objectivesText"] = "Bring the core to Duke Hydraxis in Azshara. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163476 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 163476 } },
[53170] = { ["id"] = 53170, ["name"] = "Unscarred Black Scale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5785, ["mapID"] = 371, ["storyline"] = { 53170 }, ["description"] = "<An utterly pristine black dragon scale taken from the dragons you recently encountered. The black dragonflight was completely decimated following Deathwing's demise and Wrathion's rise to power. Yet the size indicates a younger dragon. There is one person, one dragon, that you know will want to hear of this, but where IS Wrathion? You surmise he may be some place familiar, fortified, and abandoned.>", ["objectivesText"] = "Attempt to find Wrathion in Blackrock Mountain. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163477 }, ["ends"] = { { ["mapID"] = 371, ["npcID"] = 66306, ["x"] = 0.470667, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 371, ["source"] = "quest_giver", ["x"] = 0.470667, ["y"] = 0.451 }, ["mapCandidates"] = { ["npc"] = { 371 }, ["zone"] = { 5785 } }, ["questType"] = "standard", ["startItems"] = { 163477 } },
[53171] = { ["id"] = 53171, ["name"] = "Battered Twilight Scale", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53171 }, ["description"] = "<The worn scale of a twilight dragon, it has seen many years of fighting. The twilight dragons were thought to have been defeated with the fall of Sinestra, how were there so many on the island? And who is leading the flight?>", ["objectivesText"] = "Solve the riddle. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163478 }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 132888, ["x"] = 0.202, ["y"] = 0.545 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.202, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["startItems"] = { 163478 } },
[53172] = { ["id"] = 53172, ["name"] = "Venture Co. Business Plan", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 17, ["mapID"] = 10, ["storyline"] = { 53172 }, ["description"] = "<An enormous volume, and printed in very small print. You can't make it through even a few sentences before the words begin to swim before your eyes. The Venture Company's long-term plan appears to be quite complex and nearly impossible to understand. One thing is for certain: a competing enterprise would likely pay well to get their hands on this tome.>", ["objectivesText"] = "Confront Lizzarik in Ratchet. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163479 }, ["ends"] = { { ["mapID"] = 10, ["npcID"] = 3658, ["x"] = 0.612667, ["y"] = 0.681333 } }, ["coords"] = { ["mapID"] = 10, ["source"] = "quest_giver", ["x"] = 0.612667, ["y"] = 0.681333 }, ["mapCandidates"] = { ["npc"] = { 10 }, ["zone"] = { 17 } }, ["questType"] = "standard", ["startItems"] = { 163479 } },
[53173] = { ["id"] = 53173, ["name"] = "Sins of the Syndicate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53173 }, ["description"] = "As if the League of Arathor was not trouble enough, Syndicate agents still slither down from the Alterac mountains to drive off honest Horde laborers. Punish them.", ["objectivesText"] = "Kill 20 Syndicate members at Go'Shek Farm.", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.267333, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 14, 1165 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53174] = { ["id"] = 53174, ["name"] = "Murloc Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 53174 }, ["description"] = "<The murloc eye appears to have no magical properties of its own, but is still quite damp to the touch. You have seen naga sorcerers use similar objects in their casting rituals, but rarely do they dismember their murloc slaves for this purpose. This is unsettling, even for the naga.>", ["objectivesText"] = "Solve the riddle. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 730, 163480 }, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 98067, ["x"] = 0.4775, ["y"] = 0.1435 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.4775, ["y"] = 0.1435 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["startItems"] = { 163480 } },
[53175] = { ["id"] = 53175, ["name"] = "The Warfront Looms", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53175, 53185, 53194, 53197, 53198, 53414 }, ["description"] = "We cannot myopically focus all our efforts on Zandalar. Horde treachery simmers all across the globe. One particular hot spot lies in the Arathi Highlands, near the storied citadel of Stromgarde. The Horde has set up an encampment nearby, and intends to capture our territory. Speak with Ralston Karn , the recruitment officer for the division in charge of this particular warfront. He could use a good <class> like you.", ["objectivesText"] = "Report to Ralston Karn in Boralus Harbor.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 746, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53176] = { ["id"] = 53176, ["name"] = "Glittering Scarab", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5034, ["mapID"] = 249, ["storyline"] = { 53176 }, ["description"] = "<A magical trinket found on a tol'vir spellcaster, it appears to augment their casting abilities. It seems to be very old, but is nearly pristine in form. The tol'vir of Uldum may know more about the sudden appearance of the Amathet.>", ["objectivesText"] = "Bring the scarab to High Commander Kamses in Uldum. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163481 }, ["ends"] = { { ["mapID"] = 249, ["npcID"] = 46134, ["x"] = 0.373, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 249, ["source"] = "quest_giver", ["x"] = 0.373, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 249 }, ["zone"] = { 5034 } }, ["questType"] = "standard", ["startItems"] = { 163481 } },
[53177] = { ["id"] = 53177, ["name"] = "Broken Compass", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 53177 }, ["description"] = "<A compass found on a stranded pirate, it no longer functions. The metal and craftsmanship indicate an origin in Stormwind.>", ["objectivesText"] = "Find the owner of the compass. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163482 }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 908, ["x"] = 0.42, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["startItems"] = { 163482 } },
[53178] = { ["id"] = 53178, ["name"] = "Razorfin Hunting Spear", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6134, ["mapID"] = 418, ["storyline"] = { 53178 }, ["description"] = "<This spear is razor sharp, though it has clearly seen many years of hunting in the open sea. The shaft has been broken in several places and repaired with what materials were available at the time. From the variety of repair materials, you surmise that the jinyu tribe you recently faced must travel extensively. The friendly jinyu of Pandaria might know more about this strange tribe.>", ["objectivesText"] = "Take the spear to Tired Shushen in Krasarang Wilds. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163483 }, ["ends"] = { { ["mapID"] = 418, ["npcID"] = 58278, ["x"] = 0.296, ["y"] = 0.39 } }, ["coords"] = { ["mapID"] = 418, ["source"] = "quest_giver", ["x"] = 0.296, ["y"] = 0.39 }, ["mapCandidates"] = { ["npc"] = { 418 }, ["zone"] = { 6134 } }, ["questType"] = "standard", ["startItems"] = { 163483 } },
[53179] = { ["id"] = 53179, ["name"] = "Executing Exorcisms", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53179 }, ["description"] = "Even in death, the Horde foolishly clings to Alliance territory. Drive their vengeful ghosts from the ruins of Ar'gorok before their foulness spreads.", ["objectivesText"] = "Kill 20 Vengeful Ghosts in Ar'gorok. Progress: Vengeful ghosts remain in Ar'gorok.", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.203, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53180] = { ["id"] = 53180, ["name"] = "Vorus'arak's Carapace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 53180 }, ["description"] = "<The carapace from the nerubian lord Vorus'arak, it looks ancient. It appears that Vorus'arak did not want to shed his shell, and instead wore the same scarred carapace for a very long time. All across the carapace, strange markings have been carved. It seems to be a language of some kind.>", ["objectivesText"] = "Bring the carapace to Kilix the Unraveler in Dragonblight. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163484 }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 26653, ["x"] = 0.262, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["startItems"] = { 163484 } },
[53181] = { ["id"] = 53181, ["name"] = "Druidic Fur", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 53181 }, ["description"] = "<This fur teems with natural magic. The beasts you fought on the island were clearly not beasts at all, but druids. At least they were before. What could have caused them to become feral? You did not want to slay them, but they gave you no choice, didn't they?>", ["objectivesText"] = "Bring the fur to Loganaar in Moonglade. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163485 }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 12042, ["x"] = 0.525, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["startItems"] = { 163485 } },
[53182] = { ["id"] = 53182, ["name"] = "Strangling Root", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 493, ["mapID"] = 80, ["storyline"] = { 53182 }, ["description"] = "<The root twists and struggles in your grip, attempting to wrap itself around your arm. The keepers you encountered must be powerfully attuned to nature to imbue their creations with such longetivity. Remembering the ferocity with which they fought against you makes you suddenly uneasy. Why would these guardians of nature behave this way? Surely, someone must have the answers.>", ["objectivesText"] = "Take the root to Keeper Remulos in Moonglade. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163486 }, ["ends"] = { { ["mapID"] = 80, ["npcID"] = 11832, ["x"] = 0.362, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 80, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 80 }, ["zone"] = { 493 } }, ["questType"] = "standard", ["startItems"] = { 163486 } },
[53183] = { ["id"] = 53183, ["name"] = "Wriggling Mass", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 53183 }, ["description"] = "<The tendril writhes and pulsates in your hand as your mind is assailed by all manner of vicious thoughts. One vision in particular surfaces in your mind again and again. In your mind's eye, you picture a many-eyed goat laying in a pool of black water. As you approach, its eyes burst open, and in an instant you find yourself looking upward at the goat from deep within the puddle. As you sink into the icy darkness, everything goes black. You pocket the mass and shake the thoughts from your head.", ["objectivesText"] = "Locate someone who can explain the visions. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163487 }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 132886, ["x"] = 0.4, ["y"] = 0.765 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.765 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["startItems"] = { 163487 } },
[53184] = { ["id"] = 53184, ["name"] = "Weathered Pamphlet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 53184 }, ["description"] = "<This pamphlet appears to be a mass-produced flier advertising an Azerite -buying service. You can make out a few faded but colorful phrases like \"Your fortune awaits in the Great Sea!\" and \"Everyone's getting rich, isn't it your time?\" There is no mention of any of the dangers involved. There is some information about who to contact at the bottom, however.>", ["objectivesText"] = "Find the pamphlet's originator. Provided item:", ["rewardGold"] = 84900, ["rewardXP"] = 710, ["rewardItems"] = { 163488 }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 132832, ["x"] = 0.52, ["y"] = 0.3 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.3 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 163488 } },
[53185] = { ["id"] = 53185, ["name"] = "Warfront Contribution", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53175, 53185, 53194, 53197, 53198, 53414 }, ["description"] = "A well-trained army will only get us so far, <name>. We also need money, food, and supplies to keep our army funded, fed, and ready to fight. Alliance coffers fund most of the war effort, but the rest is paid for by the hard work of citizens like you and me. Loosen up those purse strings and do what you can. For the Alliance!", ["objectivesText"] = "If you are looking for what contributions are up as of September 16th, please go to our list of Alliance Warfront Contribution Quests . Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 152875 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 746, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53186] = { ["id"] = 53186, ["name"] = "Mission Report: Ambush at Grimwatt's Crash", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53186 }, ["series"] = { 53187 }, ["description"] = "Your followers have sent a report regarding the mission at Grimwatt''s Crash. It details that the mission was a success and the attacking blood trolls were defeated. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", ["objectivesText"] = "Deliver the mission report to Halford Wyrmbane . Progress: Do you have news regarding the mission for Grimwatt's Crash?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 163043, 163547 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53187] = { ["id"] = 53187, ["name"] = "An Unexpected Guest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53187 }, ["series"] = { 53186 }, ["description"] = "The mission to defend Grimwatt's Crash was a success. Well done, <name>. In addition to successfully holding the outpost, the troops at Grimwatt's Crash have captured a blood crawg. Noella Davenport is handling the beast's training. Make your way to Grimwatt's Crash in Nazmir and check-in with Noella on the crawg training.", ["objectivesText"] = "Speak with Noella Davenport .", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 142478, ["x"] = 0.342, ["y"] = 0.632 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 863, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53190] = { ["id"] = 53190, ["name"] = "Executing Exorcisms", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53190 }, ["description"] = "Even in death, the Alliance foolishly clings to Horde territory. Drive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.", ["objectivesText"] = "Kill 20 Vengeful Ghosts in Stromgarde. Progress: Vengeful ghosts remain in Stromgarde.", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143381, ["x"] = 0.267333, ["y"] = 0.338 }, { ["mapID"] = 1165, ["npcID"] = 143388, ["x"] = 0.518, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.267333, ["y"] = 0.338 }, ["mapCandidates"] = { ["npc"] = { 14, 1165 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
[53192] = { ["id"] = 53192, ["name"] = "Twice-Exiled", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53192 }, ["description"] = "Elementals of all sorts are bursting free of their bonds across the Highlands. Return them to the primordial chaos from whence they came.", ["objectivesText"] = "Kill 20 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands .", ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143172, ["x"] = 0.203, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.203, ["y"] = 0.608 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard" },
