[53194] = { ["id"] = 53194, ["name"] = "To the Front", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53175, 53185, 53194, 53197, 53198, 53414 }, ["description"] = "I need you to see the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front. Yvera Dawnwing maintains a portal directly to Stromgarde. She can help you.", ["objectivesText"] = "Speak with Yvera Dawnwing to teleport to Stromgarde, then report to Captain Roderick Brewston .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 858, 33792, 34583, 34584, 57523, 57524, 57525, 62837, 62838, 62839, 131193, 163280, 163282, 163283, 163424, 163426, 163432, 163435, 163441, 163446, 163453, 163456, 163459, 208067, 210050, 211279, 237812, 257352 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143018, ["x"] = 0.192, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 14, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 746, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53195] = { ["id"] = 53195, ["name"] = "Arathi Donations: Akunda's Bite", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9391, ["mapID"] = 1161, ["storyline"] = { 53195 }, ["description"] = "Greetings! With the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you! Now, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.", ["objectivesText"] = "Gather 20 Siren's Pollen for Chelsea Strand in Boralus Harbor. Progress: Have some herbs for me?", ["rewardItems"] = { 152507 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 9391 } }, ["questType"] = "standard" },
[53197] = { ["id"] = 53197, ["name"] = "Touring the Front", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53175, 53185, 53194, 53197, 53198, 53414 }, ["description"] = "The Horde haven't attacked for a while now. Neither have we, honestly. It should be safe to head on out and do some scouting. Check in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't off and gotten themselves killed, and the trip should give you a bit of a lay of the land. Speaking of which, you might also talk to Grayson Bell , the flight master, who can give you a quick look at our enemy's base. \"Ar'gorok,\" or some other such orcish nonsense.", ["objectivesText"] = "Report to Foreman Tully , Lumbering Leo , and Grayson Bell . Progress: Cheers!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143018, ["x"] = 0.192, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143018, ["x"] = 0.192, ["y"] = 0.592 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.192, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 746, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53198] = { ["id"] = 53198, ["name"] = "Back to Boralus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53175, 53185, 53194, 53197, 53198, 53414 }, ["description"] = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. No doubt it'll be any day now.", ["objectivesText"] = "Speak with Yvera Dawnwing to return to Boralus.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143018, ["x"] = 0.192, ["y"] = 0.592 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.192, ["y"] = 0.592 }, ["mapCandidates"] = { ["npc"] = { 14, 1161 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 746, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53205] = { ["id"] = 53205, ["name"] = "Arathi Donations: Monelite Ore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53205 }, ["description"] = "Ye look like the kind o' <lad/lass> that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort. Have ye any ore ta spare?", ["objectivesText"] = "Gather 20 Monelite Ore to Brandal Darkbeard in Boralus Harbor. Progress: Ye look like the kind o' lad that ought ta be carryin' loads o' ore around with ye! Got any ta spare?", ["rewardItems"] = { 152512 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142994, ["x"] = 0.662, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53207] = { ["id"] = 53207, ["name"] = "The Warfront Looms", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53207, 53208, 53209, 53210, 53212, 53416 }, ["description"] = "Our focus must expand beyond Kul Tiras. The Alliance still presses against our forces in other parts of the globe. We are most interested in the Arathi Highlands, near Stromgarde. We've set up an encampment in the area, with the intent of capturing Stromgarde. Speak with Throk , the recruitment officer for the division in charge of this particular warfront. He could use a good <class> like you.", ["objectivesText"] = "Report to Throk in Zuldazar.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 747, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53208] = { ["id"] = 53208, ["name"] = "To the Front", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53207, 53208, 53209, 53210, 53212, 53416 }, ["description"] = "We're at war in the Arathi Highlands. The battle has died down for now, but when it flares up again, we'll need you on the front. Druza Netherfang maintains a portal directly to Ar'gorok. She can help you.", ["objectivesText"] = "Speak with Druza Netherfang to teleport to Ar'gorok, then report to Wistel Silversnitch .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 858, 33792, 34583, 34584, 57523, 57524, 57525, 62837, 62838, 62839, 131193, 163280, 163282, 163283, 163424, 163426, 163432, 163435, 163441, 163446, 163453, 163456, 163459, 208067, 210050, 211279, 237812, 257352 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143019, ["x"] = 0.2675, ["y"] = 0.3365 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 14, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 747, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53209] = { ["id"] = 53209, ["name"] = "Warfront Contribution", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53207, 53208, 53209, 53210, 53212, 53416 }, ["description"] = "A well-trained army will only get us so far, <name>. We also need money, food, and supplies to keep our army funded, fed, and ready to fight. Show some pride and give what you can. For the Horde!", ["objectivesText"] = "Make a donation to the war effort. You can donate gold, War Resources, or crafted equipment. Only some NPCs will accept donations each day.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 747, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53210] = { ["id"] = 53210, ["name"] = "Touring the Front", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53207, 53208, 53209, 53210, 53212, 53416 }, ["description"] = "The Alliance haven't attacked for a while now. Neither have we, actually. It should be safe to head on out and do some scouting. Check in with our foremen at the mine and the lumber mill. It'd be good to know that they haven't gone and gotten themselves killed, and the trip should give you a bit of a lay of the land. Speaking of which, you might also talk to Flightgineer Krazzle . He can give you a quick look at Stromgarde, so you can see what we're up against.", ["objectivesText"] = "Report to Foreman Drogg , Graul , and Flightgineer Krazzle . Progress: Hey hey.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143019, ["x"] = 0.2675, ["y"] = 0.3365 } }, ["ends"] = { { ["mapID"] = 14, ["npcID"] = 143019, ["x"] = 0.2675, ["y"] = 0.3365 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.2675, ["y"] = 0.3365 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 14, ["questLines"] = { { ["id"] = 747, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53211] = { ["id"] = 53211, ["name"] = "Arathi Donations: Coastal Healing Potion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53211 }, ["description"] = "I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.", ["objectivesText"] = "Gather 10 Coastal Healing Potions for Chelsea Strand in Boralus Harbor. Progress: I don't suppose you have any healing potions to spare. I'm trying to maintain a healthy supply for the battle to come.", ["rewardItems"] = { 152494 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53212] = { ["id"] = 53212, ["name"] = "Back to Zuldazar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 53207, 53208, 53209, 53210, 53212, 53416 }, ["description"] = "That should just about do it for now, then. We'll be in touch if the fighting heats back up again. Should be any day now, honestly.", ["objectivesText"] = "Speak with Druza Netherfang to return to Zuldazar.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 143019, ["x"] = 0.2675, ["y"] = 0.3365 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.2675, ["y"] = 0.3365 }, ["mapCandidates"] = { ["npc"] = { 14, 1165 }, ["zone"] = { 45 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 747, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53213] = { ["id"] = 53213, ["name"] = "Arathi Donations: Coastal Mana Potion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53213 }, ["description"] = "One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota. You wouldn't happen to know where one can acquire additional mana potions, would you?", ["objectivesText"] = "Bring 10 Coastal Mana Potions to Chelsea Strand in Boralus Harbor. Progress: I'm looking to acquire a few potions to sustain our allies in a long-fought battle. Have anything of the kind?", ["rewardItems"] = { 152495 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53216] = { ["id"] = 53216, ["name"] = "Arathi Donations: Shimmerscale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53216 }, ["description"] = "I'll keep it simple: we need more Shimmerscale ! I apologize for being so forward with you, but there's little time to waste. If you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?", ["objectivesText"] = "Donate 100 Shimmerscale to Charlane in Boralus Harbor. Progress: Outfitting our allies is of the utmost importance. This provides us the necessary materials to ensure no one is left unprotected on the battlefield.", ["rewardItems"] = { 153050 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53217] = { ["id"] = 53217, ["name"] = "Arathi Donations: Coarse Leather Barding", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53217 }, ["description"] = "It's not just our allies we need to protect in the upcoming battle, but our equine friends as well! Can you lend a hand and ensure our allies receive the best possible armor for the battle ahead?", ["objectivesText"] = "Gather 5 Coarse Leather Barding for Charlane in Boralus Harbor. Progress: It's not just our allies needing protection in the battle to come, but our beasts as well.", ["rewardItems"] = { 154166 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53218] = { ["id"] = 53218, ["name"] = "Arathi Donations: Monel-Hardened Hoofplates", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53218 }, ["description"] = "Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", ["objectivesText"] = "Gather 2 Monel-Hardened Hoofplates for Brandal Darkbeard in Boralus Harbor. Progress: Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies who're needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", ["rewardItems"] = { 152812 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142994, ["x"] = 0.662, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53219] = { ["id"] = 53219, ["name"] = "Arathi Donations: Monel-Hardened Stirrups", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53219 }, ["description"] = "In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.", ["objectivesText"] = "Gather 2 Monel-Hardened Stirrups for Brandal Darkbeard in Boralus Harbor. Progress: In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.", ["rewardItems"] = { 152813 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142994, ["x"] = 0.662, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53221] = { ["id"] = 53221, ["name"] = "Mission Report: Missing Supplies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53221 }, ["series"] = { 53222 }, ["description"] = "Your followers have sent a report regarding the mission at Vulture's Nest. It details that the mission was a success and the lost supply shipment has been recovered. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", ["objectivesText"] = "Deliver the mission report to Halford Wyrmbane . Progress: Do you have news regarding the mission for Vulture's Nest?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 163572, 163709 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53222] = { ["id"] = 53222, ["name"] = "Necessary Supplies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53222 }, ["series"] = { 53221 }, ["description"] = "The mission to recover the supplies was a success. Well done, <name>. The supply shipment in question was ordered by Buzz Crankchug at Vulture's Nest. You should check in with the outpost in Vol'dun and ensure that all of the missing supplies have been accounted for. Make your way to Vulture's Nest in Vol'dun and speak with Buzz Crankchug .", ["objectivesText"] = "Speak with Buzz Crankchug .", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["rewardItems"] = { 163709 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 138256, ["x"] = 0.534, ["y"] = 0.375333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 864, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53223] = { ["id"] = 53223, ["name"] = "Arathi Donations: Grilled Catfish", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53223 }, ["description"] = "Greetings, traveler. I was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?", ["objectivesText"] = "Gather 5 Grilled Catfish for Senedras in Boralus Harbor. Progress: I was asked to ensure our food supplies are never left wanting, though lately our fish supplies have been running low. Have any fish you would care to donate?", ["rewardItems"] = { 154889 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53224] = { ["id"] = 53224, ["name"] = "Arathi Donations: Seasoned Loins", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53224 }, ["description"] = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", ["objectivesText"] = "Gather 20 Seasoned Loins for Senedras in Boralus Harbor. Progress: A hearty meat provides the nourishment our allies deserve. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", ["rewardItems"] = { 154891 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53225] = { ["id"] = 53225, ["name"] = "Arathi Donations: Great Sea Catfish", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1161, ["storyline"] = { 53225 }, ["description"] = "Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish. If we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", ["objectivesText"] = "Gather 40 Great Sea Catfish for Senedras in Boralus Harbor. Progress: If we're going to keep our allies well fed and full of fish, we'll need to make sure our stockpile is ready. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", ["rewardItems"] = { 152547 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[53226] = { ["id"] = 53226, ["name"] = "Arathi Donations: Tidespray Linen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53226 }, ["objectivesText"] = "Gather 40 Tidespray Linen for Faella in Boralus Harbor. Progress: There is no such thing as too much linen. It is better to maintain a strong supply than be left wanting.", ["rewardItems"] = { 152576 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53227] = { ["id"] = 53227, ["name"] = "Arathi Donations: Battle Flag: Spirit of Freedom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53227 }, ["objectivesText"] = "Gather 2 Battle Flag: Spirit of Freedom for Faella in Boralus Harbor. Progress: I have a keen eye for quality when it comes to handcrafted items. I'm looking for one item in particular that may be of use to us on the field of battle.", ["rewardItems"] = { 154707 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53228] = { ["id"] = 53228, ["name"] = "Arathi Donations: Battle Flag: Phalanx Defense", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53228 }, ["objectivesText"] = "Gather 2 Battle Flag: Phalanx Defense for Faella in Boralus Harbor. Progress: Threading and craftsmanship are not all that matter. Our work speaks to the heart of our dedication, providing a beacon of hope on the field of battle. I am looking for such an item, one that is crafted by a highly skilled tailor. Have you seen anything of the sort?", ["rewardItems"] = { 154706 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53229] = { ["id"] = 53229, ["name"] = "Arathi Donations: Enchant Ring - Seal of Critical Strike", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53229 }, ["objectivesText"] = "Gather 2 Enchant Ring - Seal of Critical Strike for Mae Wagglewand in Boralus Harbor. Progress: I was just about done filling orders for the next shipment then realized I was out of materials! Do you think you can help me fill the remaining orders?", ["rewardItems"] = { 153438 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.253333 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53230] = { ["id"] = 53230, ["name"] = "Arathi Donations: Enchant Ring - Seal of Versatility", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53230 }, ["objectivesText"] = "Gather 2 Enchant Ring - Seal of Versatility for Mae Wagglewand in Boralus Harbor. Progress: I know it's short notice, but I'm trying to find a few more enchantments to add to our next shipment.", ["rewardItems"] = { 153441 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.253333 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53231] = { ["id"] = 53231, ["name"] = "Arathi Donations: Gloom Dust", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53231 }, ["objectivesText"] = "Gather 20 Enchant Weapon - Stalwart Navigation for Mae Wagglewand in Boralus Harbor. Progress: I've been able to keep pace with our orders until recently. Now I'm afraid I won't be able to keep up without help. Would you be willing to donate a few supplies?", ["rewardItems"] = { 152875 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.253333 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53232] = { ["id"] = 53232, ["name"] = "Arathi Donations: Incendiary Ammunition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53232 }, ["description"] = "Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by. Today I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.", ["objectivesText"] = "Gather 2 Incendiary Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: Though our ammunition supplies are faring well, it's my duty to maintain a stockpile of additional resources, especially those that are harder to come by. Would you let me know if you stumble upon munitions with incendiary properties?", ["rewardItems"] = { 158203 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53233] = { ["id"] = 53233, ["name"] = "Arathi Donations: Frost-Laced Ammunition", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53233 }, ["description"] = "Hey there! Transmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected! From what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic! Maybe they'd even let me keep one to examine!", ["objectivesText"] = "Gather 2 Frost-Laced Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few of these I'm sure our munitions officers would be ecstatic!", ["rewardItems"] = { 158377 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53234] = { ["id"] = 53234, ["name"] = "Arathi Donations: F.R.I.E.D.", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53234 }, ["description"] = "You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected! We've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.", ["objectivesText"] = "Gather 3 F.R.I.E.D. for Norber Togglesprocket in Boralus Harbor. Progress: We've started a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.", ["rewardItems"] = { 153490 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53235] = { ["id"] = 53235, ["name"] = "Arathi Donations: War-Scroll of Intellect", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53235 }, ["description"] = "Enlightenment guides our path to victory. In battle, we fight as one. Share your knowledge and skills with me. Generosity is never forgotten.", ["objectivesText"] = "Gather 3 War-Scroll of Intellect for Liao in Boralus Harbor. Progress: Enlightenment presents opportunity for victory.", ["rewardItems"] = { 158201 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143005, ["x"] = 0.674, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
