[53347] = { ["id"] = 53347, ["name"] = "Bumbles the Bee", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53347 }, ["description"] = "Hey $p, thanks for delivering Mom's letter. I was really starting to worry about her! Dad and I have been having a few problems running the farm after she left on her trip. If you didn't show up when you did, we'd still be in real trouble! I was hoping you would be willing to help Bumbles out too. He was hurt when his hive was destoyed. If we feed him some of Dad's special formula, hopefully he will heal up faster. First we need to find the secret ingredient, try looking around at his other lab.", ["objectivesText"] = "Locate Raimond's Secret Ingredient . Progress: Were you able to find it? I think it's in a purple bottle.", ["rewardGold"] = 309800, ["rewardXP"] = 4115, ["rewardItems"] = { 163699, 163780 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131793, ["x"] = 0.688, ["y"] = 0.652 }, { ["mapID"] = 942, ["npcID"] = 132647, ["x"] = 0.71, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132647, ["x"] = 0.71, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[53348] = { ["id"] = 53348, ["name"] = "WANTED: Thundersnout", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53348 }, ["description"] = "Thundersnout is the largest of the boars in the valley. She poses a serious threat to our troop movements in the south. As such, Centurion Kaga Warmstone has issued a bounty for proof of her demise. Thundersnout's location is near the Briarback kraul, so beware the local quilboar!", ["objectivesText"] = "Deliver Thundersnout's Snout to Centurion Kaga Warmstone . Progress: Yes?", ["rewardGold"] = 772200, ["rewardXP"] = 6175, ["rewardItems"] = { 158300 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138886, ["x"] = 0.52, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "group" },
[53351] = { ["id"] = 53351, ["name"] = "The MOTHERLODE!!: Ironfoe", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1584, ["mapID"] = 84, ["storyline"] = { 51474, 51813, 53342, 53351, 53352, 53566 }, ["series"] = { 51474, 51813, 53342, 53352, 53566 }, ["description"] = "Mogul Razdunk has always been a jealous sort, wishin' he was Gallywix or better. But he's the worst sort o' greedy. He won't stop at anythin' tae achieve his ends, nae matter the cost. It was a bold move even fer him tae strike at us in Blackrock Depths. He should've knaewn he was goin' too far. Kill that covetous wretch an' bring the hammer back where it belongs. You'll find him in Kezan. Somewhere he calls \"The Motherlode,\" likely with too many exclamation points.", ["objectivesText"] = "Recover Ironfoe from Mogul Razdunk. Progress: I wish I could see look on his face as ye rip the hammer away from his cold hands.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 154166, 163708 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133197, ["x"] = 0.52, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133197, ["x"] = 0.52, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1584 } }, ["questType"] = "dungeon", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 781, ["name"] = "Allies of the Alliance: Dark Iron Dwarf", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53352] = { ["id"] = 53352, ["name"] = "Firelands", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 51474, 51813, 53342, 53351, 53352, 53566 }, ["series"] = { 51474, 51813, 53342, 53351, 53566 }, ["description"] = "Alright, the hard part should be behind us, <name>. Now, we just need tae take that Molten Core fragment ye recovered into Firelands an' charge it up by Ragnaros' old swimmin' pool. Dinna worry! I'm sendin' Anvil-Thane Thurgaden with ye. Just give me a nudge when ye're ready.", ["objectivesText"] = "Speak with Moira at the Stormwind Embassy to travel to the Firelands and empower the Fragment of the Molten Core. Progress: I hope ye're nae afraid o' a little bit o' fire.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 208095, 209931, 237812 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133197, ["x"] = 0.52, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133197, ["x"] = 0.52, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 781, ["name"] = "Allies of the Alliance: Dark Iron Dwarf", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53353] = { ["id"] = 53353, ["name"] = "Echo of Warlord Zaela", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 17, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["series"] = { 53354 }, ["description"] = "Warlord Zaela... another name that stains the tongue just to speak it... She was instrumental in freeing Garrosh during his trial when she and her Dragonmaw clan attacked the Temple of the White Tiger. I am ashamed to say that the dragon Kairozdormu was also involved. We will speak of this no more. The temple in Kun Lai Summit is our next destination.", ["objectivesText"] = "Defeat the Echo of Warlord Zaela at the Temple of the White Tiger in Kun Lai Summit. Progress: Some of my kin invite shame upon our name.", ["rewardItems"] = { 6948, 63379, 65274, 65360, 140192, 161330 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 143692, ["x"] = 0.543, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 143692, ["x"] = 0.543, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.543, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53354] = { ["id"] = 53354, ["name"] = "Echo of Gul'dan", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4, ["mapID"] = 17, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["series"] = { 53353 }, ["description"] = "To attune this shard to the place you wish to go, we must follow some of its history. The first location we will visit is the Dark Portal in the Blasted Lands. It was there that Gul'dan used a piece of the Vision of Time to travel between realities. Join me there when you are ready.", ["objectivesText"] = "Defeat the Echo of Gul'dan at the Dark Portal in Blasted Lands. Progress: The Vision of Time still holds power, it just needs to be unlocked.", ["rewardItems"] = { 6948, 63379, 65274, 65360, 118246, 128318, 140192, 153709, 161330 }, ["ends"] = { { ["mapID"] = 17, ["npcID"] = 143692, ["x"] = 0.543, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.543, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 17 }, ["zone"] = { 4 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 17, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53355] = { ["id"] = 53355, ["name"] = "Echo of Garrosh Hellscream", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 17, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["description"] = "Our final destination will take us to the depths beneath your city of Orgrimmar. The way there is barred, but I can get us inside. Meet me outside the gates of Orgrimmar and we will descend together.", ["objectivesText"] = "Meet Anachronos outside the gates of Orgrimmar, then defeat the Echo of Garrosh within the Siege of Orgrimmar.", ["rewardItems"] = { 6948, 63379, 65274, 65360, 140192, 161330 }, ["starts"] = { { ["mapID"] = 17, ["npcID"] = 143692, ["x"] = 0.543, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 131443, ["x"] = 0.67, ["y"] = 0.734909 } }, ["coords"] = { ["mapID"] = 17, ["source"] = "quest_giver", ["x"] = 0.543, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 17, 1165 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53358] = { ["id"] = 53358, ["name"] = "Test of Hyphen Tech", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 53358 }, ["description"] = "This is--a test of--our new hyphen--breaking technology which--we are getting--to help sentences--read better. If you--are datamining this--then I am--sorry, but--you are sure--to be disappointed. Okay--FINE--Jaina really is--a dreadlord--oh and so--are Sylvanas--Anduin--and Khadgar--I mean--who ISN'T a--dreadlord, really?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53359] = { ["id"] = 53359, ["name"] = "Arathi Donations: Steelskin Potion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53359 }, ["objectivesText"] = "Progress: Some o' da best potions give ya allies a fightin' chance. If ya find any, come an' see me.", ["rewardItems"] = { 152557 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 142159, ["x"] = 0.512, ["y"] = 0.954 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142159, ["x"] = 0.512, ["y"] = 0.954 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.954 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[53360] = { ["id"] = 53360, ["name"] = "Arathi Donations: Steelskin Potion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53360 }, ["objectivesText"] = "Gather 2 Steelskin Potions for Chelsea Strand in Boralus Harbor. Progress: Steelskin Potions are a great source of protection. If you should find any in your travels, I'd gladly take them off your hands.", ["rewardItems"] = { 152557 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53361] = { ["id"] = 53361, ["name"] = "Arathi Donations: Meaty Haunch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53361 }, ["description"] = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", ["objectivesText"] = "Gather 2 Seasoned Loins for Senedras in Boralus Harbor. Progress: Fresh meat goes a long way. If we're to endure the battle, we've got to be prepared.", ["rewardItems"] = { 154898 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53362] = { ["id"] = 53362, ["name"] = "Arathi Donations: Meaty Haunch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53362 }, ["objectivesText"] = "Progress: Delicious food provides the nourishment needed to endure what is to come.", ["rewardItems"] = { 154898 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 142973, ["x"] = 0.538, ["y"] = 0.942 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142973, ["x"] = 0.538, ["y"] = 0.942 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.538, ["y"] = 0.942 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[53363] = { ["id"] = 53363, ["name"] = "Arathi Donations: Drums of the Maelstrom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53363 }, ["objectivesText"] = "Donate 2 Drums of the Maelstrom to Charlane in Boralus Harbor. Progress: In battle, those who are victorious march to the beat of the same drum. What say we provide our allies with a little drumming of our own?", ["rewardItems"] = { 154167 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53364] = { ["id"] = 53364, ["name"] = "Arathi Donations: Drums of the Maelstrom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53364 }, ["objectivesText"] = "Progress: Soldiers rely upon each other in battle. What do say we provide them with a little boost on the battlefield?", ["rewardItems"] = { 154167 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 142970, ["x"] = 0.534, ["y"] = 0.925 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142970, ["x"] = 0.534, ["y"] = 0.925 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.925 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[53365] = { ["id"] = 53365, ["name"] = "Arathi Donations: Battle Flag: Rallying Swiftness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53365 }, ["objectivesText"] = "Progress: Our allies rally beneath our banners on the battlefield. Help us provide them the speed and precision necessary to break the frontline.", ["rewardItems"] = { 154705 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 142975, ["x"] = 0.524667, ["y"] = 0.934667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142975, ["x"] = 0.524667, ["y"] = 0.934667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.934667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[53366] = { ["id"] = 53366, ["name"] = "Arathi Donations: Battle Flag: Rallying Swiftness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53366 }, ["objectivesText"] = "Gather 2 Battle Flag: Phalanx Defense for Faella in Boralus Harbor. Progress: The finest threading and craftsmanship create the most beautiful standards. Have you any to offer?", ["rewardItems"] = { 154705 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53367] = { ["id"] = 53367, ["name"] = "Arathi Donations: Organic Discombobulation Grenade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53367 }, ["objectivesText"] = "Progress: Nothing provides an advantage like the ability to spot your enemies from a great distance. You got anything of the kind?", ["rewardItems"] = { 153487 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 142983, ["x"] = 0.529, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142983, ["x"] = 0.529, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.529, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[53368] = { ["id"] = 53368, ["name"] = "Arathi Donations: Organic Discombobulation Grenade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53368 }, ["objectivesText"] = "Progress: Distance, accuracy, quality metal, and top-notch craftsmanship--nothing else will do. I don't suppose you're able to get your hands on a few of these?", ["rewardItems"] = { 153487 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53369] = { ["id"] = 53369, ["name"] = "Make Loh Go", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53369 }, ["description"] = "Hello, <name>! We tortollans grow up hearing the stories of Loh, a tortollan who had many adventures. These stories help to challenge a young tortollan's mind as they try to figure out how Loh would make his way through any given adventure. Care to give it a try?", ["objectivesText"] = "Learn how to guide Loh.", ["rewardXP"] = 4115, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135795, ["x"] = 0.4045, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 137453, ["x"] = 0.356, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.4045, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
[53370] = { ["id"] = 53370, ["name"] = "Battle for Azeroth: Hour of Reckoning", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 51795, 53370 }, ["description"] = "Champions of the Alliance, At last the time has come for us to reclaim what is rightfully ours! Our final push to retake Lordaeron Keep shall commence at dawn. The Horde and their Warchief must answer for their crimes!", ["objectivesText"] = "Meet Master Mathias Shaw in Stormwind Harbor.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["rewardItems"] = { 158075, 160326, 163526, 163533, 163534, 163536, 163537, 163538, 163539, 163540, 163541, 163542 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 144095, ["x"] = 0.225, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 635, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 6, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 635, ["name"] = "The Battle for Lordaeron", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53371] = { ["id"] = 53371, ["name"] = "Let's Bee Friends", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53371 }, ["description"] = "We just need to collect some slime from the animated honey creatures that are still roaming around the farm. If you can bring back a few vials of that, we can put all our ingredients together and give the mixture to Bumbles. We should only feed him once a day, or he might get sick like some of the other bees. We're gonna have him all healed up in no time!", ["objectivesText"] = "Collect 8 Vials of Honey Slime and mix them with Raimond's Secret Ingredient to make Mildenhall's Growth Formula, then feed it to Bumbles. Progress: Did you collect enough of the slime?", ["rewardGold"] = 257400, ["rewardXP"] = 4115, ["rewardItems"] = { 156825, 163699, 163720, 163776 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 131793, ["x"] = 0.688, ["y"] = 0.652 }, { ["mapID"] = 942, ["npcID"] = 132647, ["x"] = 0.71, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 132647, ["x"] = 0.71, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.688, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard" },
