[53414] = { ["id"] = 53414, ["name"] = "Warfront: The Battle for Stromgarde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53175, 53185, 53194, 53197, 53198, 53414 }, ["description"] = "If the Horde thinks it can assault Stromgarde, it is sorely mistaken! We will not let Arathi fall! Prepare yourself for battle.", ["objectivesText"] = "Defeat the Horde at the Battle for Stromgarde. Progress: We must do what we can to claim Arathi for the Alliance.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 158075, 163578, 163579, 163644, 163645, 163646, 163648, 163650, 163652, 163677, 163684, 163689, 163690, 163691, 163698, 163700, 163701, 163706, 163711, 163712, 163713, 163735, 163736, 163738, 163741, 163744, 163745, 163750, 163775, 163828, 163829, 164577, 164578, 169196, 169197 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 746, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53416] = { ["id"] = 53416, ["name"] = "Warfront: The Battle for Stromgarde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53207, 53208, 53209, 53210, 53212, 53416 }, ["description"] = "Our enemies are relentless in their quest to seize Arathi for themselves. We will never allow it to fall into their hands! We must stop them before the keep is rebuilt! Take up arms. The Alliance is upon us.", ["objectivesText"] = "Defeat the Alliance at the Battle for Stromgarde. Progress: We will claim Arathi as our own!", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 163578, 163579, 163644, 163645, 163646, 163648, 163650, 163652, 163677, 163684, 163689, 163690, 163691, 163698, 163700, 163701, 163706, 163711, 163712, 163713, 163735, 163736, 163738, 163741, 163744, 163745, 163750, 163775, 163828, 163829, 164577, 164578, 169196, 169197 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 747, ["name"] = "The Battle for Stromgarde", ["orderIndex"] = 4, ["flags"] = 0 } } },
