[53434] = { ["id"] = 53434, ["name"] = "The Vanishing Lord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53434 }, ["description"] = "Whoa there! What business do you have in Drustvar ? Lookin' for someone from House Waycrest? Best of luck to ye. Even us in their guard haven't heard a word from them of late. Why, if it weren't for Marshal Reade takin' command, I doubt there'd even be a Waycrest Guard anymore. I think ye'd be better off on yer way, but if yer bent on stayin' I'd head over to Fallhaven. The mayor there is probably the only welcomin' soul left around here. Watch yer back, mainlander. There's dark workings about.", ["objectivesText"] = "Meet with Cyril White in Fallhaven in Drustvar .", ["rewardGold"] = 30900, ["rewardXP"] = 345, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 143745, ["x"] = 0.716, ["y"] = 0.405 }, { ["mapID"] = 896, ["npcID"] = 143746, ["x"] = 0.608, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[53435] = { ["id"] = 53435, ["name"] = "Azerite for the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53435 }, ["description"] = "Assist the Horde by collecting Azerite on Island Expeditions.", ["objectivesText"] = "Collect Azerite on Island Expeditions. Progress: Return to me when you have finished aiding de Horde, <name>.", ["rewardXP"] = 2830, ["rewardItems"] = { 151557, 166883, 168615, 169765 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 123000, ["x"] = 0.445, ["y"] = 0.955 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.955 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2QuestInfoID"] = 261, ["db2QuestInfoName"] = "Island Weekly Quest" },
[53436] = { ["id"] = 53436, ["name"] = "Azerite for the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53436 }, ["description"] = "Assist the Alliance by collecting Azerite on Island Expeditions.", ["objectivesText"] = "Collect Azerite on Island Expeditions. Progress: Return to me when you have finished aiding the Alliance, <name>.", ["rewardXP"] = 2830, ["rewardItems"] = { 151557, 166883, 168615, 168617, 169764 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 131290, ["x"] = 0.6665, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6665, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2QuestInfoID"] = 261, ["db2QuestInfoName"] = "Island Weekly Quest" },
[53437] = { ["id"] = 53437, ["name"] = "The MOTHERLODE!!: Raw Deal", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 862, ["storyline"] = { 53437 }, ["description"] = "Nobody, and I mean NOBODY double-crosses me and gets away with it! The Venture Co. betrayed us in a deal for Azerite refining techniques. We need pay 'em what we owe 'em. If you're not pickin' up what I'm puttin' down, I mean we need to kill that backstabbin' upstart Mogul Razdunk . You take care of him; I'll take care of gettin' what we're owed. I s'pose we oughta tell Blightcaller about this, huh? When he tells us what to do, just smile and nod. We'll handle it our way.", ["objectivesText"] = "Send a permanent--fatal--message to Mogul Razdunk in The MOTHERLODE!! Progress: I'm mad as a... as a... I'm just MAD, okay?! Look, I realize Blightcaller told you to get the refining techniques, but I'll take care of that. You just kill Razdunk, got it?", ["rewardGold"] = 1029600, ["rewardXP"] = 2830, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8721 } }, ["questType"] = "dungeon" },
[53438] = { ["id"] = 53438, ["name"] = "WANTED: Wyvern Poachers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53438 }, ["description"] = "Soldiers of the Horde! A few nights ago some foolish human soundrels snuck off with one of our strongest wyverns. If anybody can track down and stop these thieves, a reward awaits!", ["objectivesText"] = "Kill Lindel the Snatcher and Silent Boris . Progress: Is this about the wanted sign? You better hurry, a good number of hunters are after it as well.", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 162530 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 139561, ["x"] = 0.624, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[53439] = { ["id"] = 53439, ["name"] = "Blood in the Tides", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53439, 53442, 53443, 53445, 53446 }, ["description"] = "We do not have sirens in Zandalar, but our sailors know of dem. In Zandalari, we call dem bwon'tulak - de death singers. My ship was run aground and my fellow sailors all murdered by de death singers. Jane saved my life, so now I help to protect dese people. Sirens are a plague on da seas, no matter who ya serve. Run the tides red wit dere blood!", ["objectivesText"] = "Slay 8 Wailing Sirens .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 155023, 155024, 155025, 155026, 155086 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 143777, ["x"] = 0.852, ["y"] = 0.805 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 143777, ["x"] = 0.852, ["y"] = 0.805 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.852, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53440] = { ["id"] = 53440, ["name"] = "WANTED: The Hornet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53440 }, ["description"] = "That's it, I'm putting a bounty on that blasted hornet. Somebody take that bug down!", ["objectivesText"] = "Kill The Hornet .", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["rewardItems"] = { 162530 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 139561, ["x"] = 0.624, ["y"] = 0.125 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.624, ["y"] = 0.125 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[53442] = { ["id"] = 53442, ["name"] = "The Castaways", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53439, 53442, 53443, 53445, 53446 }, ["description"] = "You don't look like you're from around here. You're lucky the sirens haven't stripped your bones yet. If you need to trade supplies or just warm yourself by the fire, there's a camp up the hill behind me. Everyone there washed up in the tides. Figure we've got folks from at least four or five shipwrecks now. All banded together, just tryin' to survive. Talk to Stabby Jane . Don't worry about her nickname, she's actually real nice.", ["objectivesText"] = "Speak with Stabby Jane at Castaway Point.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128377, ["x"] = 0.8555, ["y"] = 0.835 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.8555, ["y"] = 0.835 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53443] = { ["id"] = 53443, ["name"] = "My Favorite Things", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53439, 53442, 53443, 53445, 53446 }, ["description"] = "It's tough out here. Pirates. Deadly monsters. Hungry Sam 's seemingly endless battle with indigestion. Nothing sets the nerves at ease like an old keepsake. Somethin' to remind you of home. Somethin' to keep you going. Ask around the camp. Find out what folks might have lost out there in the tideways. If you can bring any of it back, it'd be a mighty kind gesture. Me? Oh... I had a locket... Never mind, it's too small, you'd never find it. It's nothing. Don't worry about it.", ["objectivesText"] = "Ask Friendly Pete , Hungry Sam and Handy Bill about their missing keepsakes, then collect those items from the Wailing Tideway. Progress: We've all lost something in the tides. Some more than others.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 153185, 153186, 153187 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53444] = { ["id"] = 53444, ["name"] = "Glimmering Locket", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53444 }, ["description"] = "<A glint of metal catches your eye among the gently bobbing flotsam. Digging into the tangled seaweed, you discover a locket of simple, yet sturdy design. Opening the locket reveals a hand-drawn picture of a woman with fiery red bangs. Her arm is around a woman with short-cropped auburn hair, and the two are proudly displaying warm smiles for the artist.>", ["objectivesText"] = "Return the Glimmering Locket to Stabby Jane . Progress: Hm? What's that you've got there?", ["rewardGold"] = 289300, ["rewardXP"] = 1415, ["rewardItems"] = { 153184 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[53445] = { ["id"] = 53445, ["name"] = "Silencing the Sisters", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53439, 53442, 53443, 53445, 53446 }, ["description"] = "The sirens in this tideway have drawn countless ships to their doom. Wiping them out would be a boon to all seafaring folk. But you can't very well kill all of them. Only a fool would try that. The real dangerous ones are the elders. The \"sisters\" as they're known. Bigger, smarter, and stronger than the younger ones. Their voices carry far out to sea and bring in all the big \"catches.\" I managed to track two of them to a den at the northern end of the tideway, but I can't take them alone.", ["objectivesText"] = "Slay Patheope and Nolpe .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128229, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53446] = { ["id"] = 53446, ["name"] = "Local Flavor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53439, 53442, 53443, 53445, 53446 }, ["description"] = "I'm STARVING. Not actually starving, like when I first got here, but you know... Emotionally starving. Haven't had any luck with the oysters lately, and seaweed soup really upsets my guts. If I eat any more of that stuff, I think the other castaways might actually feed me to the sharks. How about them tidelurkers? They look pretty juicy. Bet you could steam those up real nice. Can you get me some? I'm not much of a hunter. But I'll share it with you!", ["objectivesText"] = "Gather 5 Juicy Lurker Tails . Progress: <Sam's stomach growls audibly.>", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 153348, 154888, 202268 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 128228, ["x"] = 0.854, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 128228, ["x"] = 0.854, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.854, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 586, ["name"] = "Castaways and Cutouts", ["orderIndex"] = 9, ["flags"] = 0 } } },
[53449] = { ["id"] = 53449, ["name"] = "Apes of Wrath", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53449 }, ["series"] = { 53453 }, ["description"] = "Alliance, just what I need. Down for performing a deed? Zandalari are afraid, of new gorillas that raid. These gorillas are mocking, these gorillas are talking. Gorillas are dookering, I hear they follow bad king. It is important to lead, but this guy fails to succeed. I shall send Flap-Flap ahead. Make ookin' wikket King dead.", ["objectivesText"] = "Travel to Gorilla Gorge.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 40727 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 129589, ["x"] = 0.57, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143787, ["x"] = 0.515, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.57, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53450] = { ["id"] = 53450, ["name"] = "King Da'ka", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53450 }, ["description"] = "King Da'ka ? More like King Dooker. My king sent me to talk to this new king. This new king took my things and tried to take my wings. Negotiations are ooked. Go, sticket to that angry wikket.", ["objectivesText"] = "Slay King Da'ka .", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 414, 17005, 17006, 30009, 30010, 30011, 30012, 39676, 39678, 39679, 39680, 44358, 44359, 44360, 44361, 56706, 56707, 58984, 58985, 58986, 65927, 65935, 65952, 65959, 65976, 65983, 65997, 66018, 66019, 66027, 66028, 66036, 66037, 66043, 79869, 87342, 87343, 87344, 87345, 87346, 87347, 87348, 87349, 87350, 87399, 89125, 91806, 111660, 114695, 114696, 114697, 114698, 118776, 118777, 118778, 118779, 118780, 128870, 131234, 131490, 147442, 156688, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776, 197381, 201294, 211279, 237812, 242386, 244858, 245631, 246727 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 143787, ["x"] = 0.515, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143787, ["x"] = 0.515, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53451] = { ["id"] = 53451, ["name"] = "WANTED: Raging Earthguard", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53451 }, ["description"] = "I have been receiving formal complaints about some big earth elemental in the middle of our scouting path. Normally I'd elect to ignore these, but the sooner we get done here, the better. Nobody wants to be stuck in this frozen hill any longer than we need to. Payment goes to the person who brings it down!", ["objectivesText"] = "Kill the Raging Earthguard west of Norwington Estate.", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 143785, ["x"] = 0.39, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[53452] = { ["id"] = 53452, ["name"] = "Gorilla Warfare", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53452 }, ["description"] = "Your timing is most fortuitous, stranger. I thank you for your assistance. Things are not peaceful in Gorilla Gorge. The kaja'mite has given us great intelligence and wit. With intelligence has come war. My brethren are those who do not wish to fight. But for our passivity we have been persecuted. Please free my comrades. They will be in cages all throughout the gorge and under guard. Make haste!", ["objectivesText"] = "Rescue 6 Pacifist Gorillas.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 143792, ["x"] = 0.502, ["y"] = 0.545 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143885, ["x"] = 0.474, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.545 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53453] = { ["id"] = 53453, ["name"] = "To Stomp or Not To Stomp", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53453 }, ["series"] = { 53449 }, ["description"] = "Like grandpapaook always say: if a wikket gonna huff the swoof from a dookerhole then plug the dookerhole. These Da'kani wikkets huffing the green smoke from their dookerholes in the ground. Makes 'em smart and mean. Smart not so bad, mean is bad. Go into Gorilla Gorge and plug those dookerholes!", ["objectivesText"] = "Collapse Kaja'mite Steam Vents in Gorilla Gorge.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 175728, 181398, 181413, 181430, 181457, 181477, 181479, 181541, 182488, 182497, 182506, 182515, 183744, 184378, 184381, 184382, 184383, 184384, 184519, 184843, 198606, 211279 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 143787, ["x"] = 0.515, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143787, ["x"] = 0.515, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53454] = { ["id"] = 53454, ["name"] = "WANTED: Quartermaster Ssylis", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53454 }, ["description"] = "Some pirates took off with a supply crate that landed further away from this site then intended. I don't think there was anything valuable in there, but now the pirates know we're here. The leader was one of those big lizard men. The worker that kills him will get double pay for the week!", ["objectivesText"] = "Kill Quartermaster Ssylis in Krakenbane Cove.", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 143785, ["x"] = 0.39, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "group" },
[53455] = { ["id"] = 53455, ["name"] = "WANTED: The Crimson Cutthroats", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53455 }, ["description"] = "For numerous and sinister crimes against the Lord Admiral: smuggling, forgery, sailing under false colors, looting, poaching, brigandage, sacking, pillaging, vandalism, impersonating Kul Tiran Naval officers, arson, kidnapping, torture, piracy, perjury, theft and ransacking multiple mead shipments. A reward is placed on the heads of The Crimson Cutthroats to be paid in full upon proof of their demise.", ["objectivesText"] = "Slay the Crimson Cutthroats near Falconhurst. Progress: Ugh. That lot. Glad someone finally took care of them.", ["rewardGold"] = 772200, ["rewardXP"] = 4150, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 136579, ["x"] = 0.192, ["y"] = 0.435 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.192, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[53456] = { ["id"] = 53456, ["name"] = "WANTED: The Rime Huntress", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53456 }, ["description"] = "Attention Interested Parties! A Moneymaking Opportunity Awaits!!!!! There's a big wolf hunting people in the pass. She's taken a liking to the taste of goblin. Nobody got time for being eaten by a wolf, so take out the Rime Huntress and I'll pay you for your trouble. - Suzie Boltwrench", ["objectivesText"] = "Defeat The Rime Huntress near Highroad Pass.", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 143800, ["x"] = 0.376, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[53457] = { ["id"] = 53457, ["name"] = "Quartermaster's Bounty", ["level"] = 26, ["requiredLevel"] = 26, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53457 }, ["objectivesText"] = "Progress: To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", ["rewardItems"] = { 163827 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143555, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53458] = { ["id"] = 53458, ["name"] = "WANTED: Rindlewoe", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53458 }, ["description"] = "A monstrous beast of wood and flesh has been terrorizing the nearby river territories. Knowing more about how the creature fights may yield interesting data! Please report any and all findings to Suzie Boltwrench in Krazzlefrazz.", ["objectivesText"] = "Defeat Rindlewoe outside of Fallhaven.", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 143800, ["x"] = 0.376, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[53459] = { ["id"] = 53459, ["name"] = "WANTED: Sister Lilias", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53459 }, ["description"] = "The Krazzlefrazz Peacekeepers are looking for an able-bodied warrior to eliminate a threat in nearby Corlain. A witch by the name of Sister Lilias is wanted for the torture and killing of many of our people. Her end would prove a boon to the Horde. Present her head to claim your just reward.", ["objectivesText"] = "Collect Sister Lilias' head from Sister Lilias in Corlain. Progress: Hey, we got some witch problems. Mind taking care of it?", ["rewardGold"] = 772200, ["rewardXP"] = 4150, ["rewardItems"] = { 160026 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 143800, ["x"] = 0.376, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.376, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "group" },
[53461] = { ["id"] = 53461, ["name"] = "Precious Metals", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53461 }, ["description"] = "Hey you! I got a business proposition for ya.The locals here seem to have a thing for silver, and we hit the jackpot with a mine just west of here. Unfortunately, it's got a bit of a spider problem... Now, the miners we sent down there are probably goners by now, but there's still some silver left down there. If you can go and fetch it for me, we'll mark it up and make a fortune! What do you say?", ["objectivesText"] = "Collect 10 Silver Nuggets from the Bleak Hills Mine. Progress: Did you find the silver?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 156722 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 143878, ["x"] = 0.364, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 143878, ["x"] = 0.364, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[53462] = { ["id"] = 53462, ["name"] = "All Wrapped Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53462 }, ["description"] = "I'm not the only one trapped here in this mine. Grimelock left all of the other miners to the spiders, too. There might be some of them still alive out there. Could you help? I'd appreciate it if not all of my friends died.", ["objectivesText"] = "Destroy Writhing Cocoons to rescue 8 Bleak Hills Miners in the Bleak Hills Mine.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 21191, 21310 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 143871, ["x"] = 0.345, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 143871, ["x"] = 0.345, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[53463] = { ["id"] = 53463, ["name"] = "An Eight-Legged Curse", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53463 }, ["description"] = "That jerk Grimelock sent us down here to the mines, only to pack up and leave us behind when these spiders showed up! Now I'm stuck here with about a million legs and eyes in all directions. You look like the tough sort. Can you clear a path for me? I'll make it worth your while.", ["objectivesText"] = "Kill 20 Bilefang spiders in the Bleak Hills Mine.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 143871, ["x"] = 0.345, ["y"] = 0.306 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 143871, ["x"] = 0.345, ["y"] = 0.306 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.306 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[53464] = { ["id"] = 53464, ["name"] = "The Village of Glenbrook", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47289, 47428, 53464, 53465 }, ["description"] = "<The book is a register of the inhabitants of Glenbrook. All but a few of the names are crossed out.>", ["objectivesText"] = "Discover the fate of the Glenbrook villagers.", ["rewardGold"] = 257400, ["rewardXP"] = 2765, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 143908, ["x"] = 0.546, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5447, ["name"] = "A Tea Party", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53465] = { ["id"] = 53465, ["name"] = "Tea Party", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 47289, 47428, 53464, 53465 }, ["description"] = "<You hear footsteps behind you.>", ["objectivesText"] = "Find Abby Lewis.", ["rewardGold"] = 514800, ["rewardXP"] = 3455, ["rewardItems"] = { 155565, 155567, 155569, 176134 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 143908, ["x"] = 0.546, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 5447, ["name"] = "A Tea Party", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53466] = { ["id"] = 53466, ["name"] = "Vision of Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 85, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["description"] = "You wish to hear how the Mag'har orcs joined the Horde? It may be one of the strangest ways we gained an ally! It all began with a plan from Eitrigg . He had a fragment of the Vision of Time that Garrosh Hellscream used to travel to Draenor. Chief Telemancer Oculeth believed there would be a way to go back to Draenor and get the Mag'har orcs to join the Horde. This tale begins with a visit to Oculeth in Zuldazar...", ["objectivesText"] = "Meet with Chief Telemancer Oculeth in Zuldazar.", ["rewardXP"] = 4115, ["rewardItems"] = { 6948, 63379, 65274, 65360, 140192, 161330, 211279 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 126066, ["x"] = 0.378, ["y"] = 0.805 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 131443, ["x"] = 0.67, ["y"] = 0.734909 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.805 }, ["mapCandidates"] = { ["npc"] = { 85, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53467] = { ["id"] = 53467, ["name"] = "Caverns of Time", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 1165, ["storyline"] = { 51479, 52942, 52943, 52945, 52955, 53353, 53354, 53355, 53466, 53467 }, ["description"] = "Were the shard of the Vision of Time not depleted, I could use it to send you on your way. But my specialty is teleportation, not chronomancy. Time magic was the province of our former leader, Grand Magistrix Elisande. Much of her knowledge died with her. It is said Elisande had mastered incantations known only to the bronze dragons. Perhaps they would be willing to aid your cause.", ["objectivesText"] = "Meet with Anachronos in the Caverns of Time.", ["rewardXP"] = 260, ["rewardItems"] = { 217110 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 131443, ["x"] = 0.67, ["y"] = 0.734909 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.734909 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 9598 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 75, ["questLines"] = { { ["id"] = 780, ["name"] = "Allies of the Horde: Mag'har Orc", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53476] = { ["id"] = 53476, ["name"] = "The Great Sea Scrolls", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53476 }, ["description"] = "<Dust falls from the scroll case as you retrieve it, revealing an ornate etching. The artwork, rendered with obvious care and skill, depicts a scene from a tortollan pilgrimage. The container has spaces for twelve rolled scrolls, only one of which is occupied. A complete set would likely be quite valuable to a tortollan collector.>", ["objectivesText"] = "Collect a set of scrolls depicting the tortollan pilgrimage.", ["rewardItems"] = { 163852, 163853, 163855, 163856, 163862, 163863, 163864, 163865 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 134345, ["x"] = 0.714, ["y"] = 0.302 }, { ["mapID"] = 942, ["npcID"] = 135793, ["x"] = 0.404667, ["y"] = 0.364667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["startItems"] = { 163856 } },
[53497] = { ["id"] = 53497, ["name"] = "Break Free", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 53497 }, ["objectivesText"] = "Darnassian Archer healed Horde occupiers slain", ["rewardGold"] = 295000, ["rewardXP"] = 4790, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 148 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Darnassian Archer healed", ["amount"] = 8, ["type"] = 0, ["objectID"] = 143976, ["orderIndex"] = 0 }, { ["text"] = "Horde occupiers slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 143631, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[53500] = { ["id"] = 53500, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 34 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 51486, 53500 }, ["description"] = "Welcome to Stormwind, <race>. I invite you to explore our fair city. Say, you look like someone who enjoys caves and such! We have many dark corners in Stormwind to explore. Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of yours is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!", ["objectivesText"] = "Talk to Chromie in Stormwind City. Progress: Greetings.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 143978, ["x"] = 0.608, ["y"] = 0.278857 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 783, ["name"] = "Allies of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53502] = { ["id"] = 53502, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 36 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 51485, 53502 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Talk to Chromie in Orgrimmar. Progress: Another world... another time... this is an age of wonder.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 143979, ["x"] = 0.466667, ["y"] = 0.777333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 784, ["name"] = "Allies of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53550] = { ["id"] = 53550, ["name"] = "A Change in Leadership", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 53550 }, ["description"] = "In my experience people do not like to be driven from their homes. While normally we would crush them with the might of the Horde, we do not have time to carry out a lengthy campaign against these creatures. They will look to their leaders for hope, inspiration, and guidance. They will find none. You are the instrument of my will, <name>. Make them submit to it.", ["objectivesText"] = "Defeat Elder Brolg , Gren Tornfur and Elder Brownpaw .", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53551] = { ["id"] = 53551, ["name"] = "Elves in the Machine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["description"] = "The Horde have already set up camp here. But we can still strike back. Their war machines are terrible to behold, but they are still machines. And machines do not work well when you go in and hack up a bunch of their inner workings. If we can sabotage but a few of them, that could mean dozens of lives saved. Let us make the most of this opportunity.", ["objectivesText"] = "Sabotage 5 Horde Demolishers in Blackwood Den. Progress: We need to destroy those demolishers!", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 10, ["flags"] = 0 } } },
