[53566] = { ["id"] = 53566, ["name"] = "Dark Iron Dwarves", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 51474, 51813, 53342, 53351, 53352, 53566 }, ["series"] = { 51474, 51813, 53342, 53351, 53352 }, ["description"] = "I can't thank ye enough, <name>. Without yer help, Ironfoe would be lost tae us and the Black Anvil could've ne'er been made whole. But even more than that, ye've proven to every Dark Iron in the mountain what it means tae be part o' somethin' bigger. Tae be part o' the Alliance. The time has come tae let King Anduin know that my people stand with him.", ["objectivesText"] = "Speak with Aysa Cloudsinger at the Stormwind Embassy to hear the end of this tale.", ["rewardGold"] = 280900, ["rewardXP"] = 5465, ["rewardItems"] = { 161331, 245427 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 126301, ["x"] = 0.521, ["y"] = 0.135 }, { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.135 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1932, ["db2PoiUiMapID"] = 1159, ["questLines"] = { { ["id"] = 781, ["name"] = "Allies of the Alliance: Dark Iron Dwarf", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53583] = { ["id"] = 53583, ["name"] = "Adapting Our Tactics", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 51569, 51570, 51571, 51572, 51961, 52443, 53052, 53055, 53583 }, ["description"] = "For our best chance to win this war, we must continue to learn and adapt new strategies. There are opportunities for advancement all around us, but they require dedication and perseverance. I've collected a list of potential research opportunities for you to review. Any one of these might feel small on its own, but together they might just be all the advantage we need. Let me know which ones you would like us to pursue.", ["objectivesText"] = "Talk to Alleria Windrunner to start researching an upgrade. Progress: Did you make a decision yet?", ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143846, ["x"] = 0.705, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143846, ["x"] = 0.705, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 624, ["questLineOrder"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 624, ["name"] = "The Zandalar Campaign", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5374, ["name"] = "The Zandalar Campaign", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53602] = { ["id"] = 53602, ["name"] = "Adapting Our Tactics", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 51800, 51801, 51802, 51803, 51979, 52444, 53050, 53056, 53602 }, ["description"] = "This war will not be won with strength and might alone. Take in your surroundings while you fight and turn it into an advantage against the enemy. I have a list of modifications for you to choose from. Any one of these might feel small on its own, but together they might just be all the advantage we need. Let me know what you would like us to pursue.", ["objectivesText"] = "Talk to Eitrigg to start researching an upgrade. Progress: What is your decision?", ["starts"] = { { ["mapID"] = 862, ["npcID"] = 143913, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143913, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 623, ["questLineOrder"] = 4 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 623, ["name"] = "The Kul Tiras Campaign", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53604] = { ["id"] = 53604, ["name"] = "Clearing Them Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50837, 50878, 50879, 50880, 53605 }, ["description"] = "They have amassed an army before us, <name>. But it is no matter. The Horde war machine will not be stopped. Go into The Master's Glaive and dispatch their warriors. Their sentinels. Any who would raise a blade against my soldiers. Clear out the petty rabble that seeks to delay the inevitable.", ["objectivesText"] = "Slay Night Elf forces in The Master's Glaive.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 11, ["flags"] = 0 } } },
[53605] = { ["id"] = 53605, ["name"] = "A Glaive Misunderstanding", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1497, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 50837, 50878, 50879, 50880, 53604 }, ["description"] = "The kaldorei have brought their siege weaponry to the field. They are currently using it to oppose mine. We need these demolishers to reach Teldrassil if we hope to stand any chance of capturing it. Go and destroy their glaive throwers as swiftly as you are able. They think they will stop my advance here. They are mistaken. Show them the gravity of their error, <name>.", ["objectivesText"] = "Destroy glaive throwers in The Master's Glaive.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.42425, ["y"] = 0.84275 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 1497 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 12, ["flags"] = 0 } } },
[53606] = { ["id"] = 53606, ["name"] = "Aggressive Inspiration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["description"] = "Nothing rallies the Horde more than their banner standing in the ruin of an enemy stronghold. Go to Blackwood Den, take the territory there, raise the Horde banners and let none question our dominance over this land.", ["objectivesText"] = "Plant 3 Horde Banners in Blackwood Den.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 135003, ["x"] = 0.432, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 134554, ["x"] = 0.42425, ["y"] = 0.84275 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 16, ["flags"] = 0 } } },
[53608] = { ["id"] = 53608, ["name"] = "Fueling the Horde War Machine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 52437, 53609 }, ["description"] = "You heard the warchief! We got Azerite shooting outta those ruins over there and night elves tryin' to snag it. Get to those ruins and collect some of the stuff. This whole attack is done for if the night elves get their hands on that Azerite!", ["objectivesText"] = "Collect Azerite from 6 Azerite Deposits .", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 144346, ["x"] = 0.358, ["y"] = 0.848 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 144346, ["x"] = 0.358, ["y"] = 0.848 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.848 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 18, ["flags"] = 0 } } },
[53609] = { ["id"] = 53609, ["name"] = "A Very Clear Message", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 52437, 53608 }, ["description"] = "The Alliance got to the Azerite here before us, the place is crawling with night elves! Kill as many of them as you can see, we gotta make sure none of them deliver even an ounce of Azerite to the Alliance!", ["objectivesText"] = "Kill 10 night elf forces.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 144346, ["x"] = 0.358, ["y"] = 0.848 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 144346, ["x"] = 0.358, ["y"] = 0.848 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.848 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 19, ["flags"] = 0 } } },
[53610] = { ["id"] = 53610, ["name"] = "Driving Them Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["series"] = { 52438, 52806, 52967, 52970, 52971, 52981 }, ["description"] = "This is it, <name>. Lor'danel is all that stands in our way before we capture Darnassus and reclaim Kalimdor. Rout the defenders. We cannot risk allowing a single enemy to escape until we have secured control over the World Tree. I want this place in order by the time the Warchief arrives.", ["objectivesText"] = "Slay 15 Lor'danel defenders.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 142310, ["x"] = 0.513333, ["y"] = 0.224667 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 142310, ["x"] = 0.513333, ["y"] = 0.224667 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.513333, ["y"] = 0.224667 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 25, ["flags"] = 0 } } },
[53616] = { ["id"] = 53616, ["name"] = "Knives of the Forsaken", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52058, 52060, 52062, 52072, 52116 }, ["description"] = "Tread carefully. All is not as it seems. The butchers who did this still skulk within Astranaar. If you find them, give them what they deserve, <name>.", ["objectivesText"] = "Slay 8 Forsaken Assassins in Astranaar. Progress: Has justice been served upon Sylvanas's assassins?", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53617] = { ["id"] = 53617, ["name"] = "Mercy for the Mad", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52234, 52240 }, ["description"] = "The ruin wrought by the Horde is driving the children of the forest mad. Chief among them are Blackwood furbolgs. They have given into the madness and are a threat to everyone. If left to their madness they could strike us from behind while our forces engage the Horde. It pains me to ask this, but please, when you are in the Twilight Vale, put these creatures out of their misery before they endanger anyone else.", ["objectivesText"] = "Slay 10 frenzied Blackwood furbolgs .", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 133693, ["x"] = 0.4384, ["y"] = 0.7188 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.7188 }, ["mapCandidates"] = { ["npc"] = { 57, 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53619] = { ["id"] = 53619, ["name"] = "Azerite Denial", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1657, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["description"] = "This substance, Azerite, is hurting Onu... and the Horde seem eager to collect it for themselves. We must not let that happen. Collect as much Azerite as you can find. Ensure the Horde do not retrieve it.", ["objectivesText"] = "Collect Azerite from 6 Azerite Deposits .", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 1657 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 12, ["flags"] = 0 } } },
[53621] = { ["id"] = 53621, ["name"] = "No Horde Allowed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["description"] = "The Horde forces in this area are trying to collect as much Azerite as possible. No doubt they intend to weaponize it. Slay any Horde forces you can find. They must not be allowed to get their hands on this Azerite!", ["objectivesText"] = "Kill 10 Horde soldiers in Nazj'vel.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 13, ["flags"] = 0 } } },
[53622] = { ["id"] = 53622, ["name"] = "Defending Lor'danel", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 57, ["storyline"] = { 52058, 52060, 52062, 52072, 52116, 52197, 52234, 52240, 52242, 52245, 52256, 52257, 52279, 52973, 52974, 52975, 52977, 53095, 53310, 53551, 53616, 53617, 53619, 53621, 53622 }, ["series"] = { 52973, 52974, 52975, 52977 }, ["description"] = "The Horde have invaded from the North! You must protect Lor'danel, <name>. Help our forces push back this attack! I will try to intercept the Warchief. This is our final chance to stop her. Report to Commander Summermoon in my absence.", ["objectivesText"] = "Take out Horde forces in Lor'danel.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 163127 }, ["starts"] = { { ["mapID"] = 57, ["npcID"] = 140877, ["x"] = 0.584, ["y"] = 0.895 } }, ["ends"] = { { ["mapID"] = 57, ["npcID"] = 134578, ["x"] = 0.584, ["y"] = 0.895 } }, ["coords"] = { ["mapID"] = 57, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.895 }, ["mapCandidates"] = { ["npc"] = { 57 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 637, ["name"] = "The Warchief's Command", ["orderIndex"] = 20, ["flags"] = 0 } } },
[53627] = { ["id"] = 53627, ["name"] = "A Gift of Azerite", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 50476, 50642, 50646, 50647, 50738, 50740, 50772, 50800, 50823, 50837, 50878, 50879, 50880, 52436, 52437, 52438, 52806, 52967, 52970, 52971, 52981, 53604, 53605, 53606, 53608, 53609, 53610, 53627 }, ["description"] = "I think we got a handle on things here. You gotta bring all this Azerite back to Zarvik Blastwix at the main camp! He's gonna know just how to use this stuff to really take down the Alliance.", ["objectivesText"] = "Deliver Azerite to Zarvik Blastwix in Blackwood Den.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["rewardItems"] = { 158075, 158937, 160251, 163127, 163128 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 144346, ["x"] = 0.358, ["y"] = 0.848 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 135501, ["x"] = 0.445333, ["y"] = 0.864667 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.358, ["y"] = 0.848 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 584, ["name"] = "The Warchief's Command", ["orderIndex"] = 20, ["flags"] = 0 } } },
[53641] = { ["id"] = 53641, ["name"] = "LFGDungeons - BFA - Stromgarde (Arathi)", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 53641 }, ["rewardGold"] = 936000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53665] = { ["id"] = 53665, ["name"] = "Ready for Battle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 53665 }, ["description"] = "Greetings, <name>. Our recruits are eager to join you on the battlefield.", ["objectivesText"] = "Speak with Throk to recruit an ally from the Barracks. Progress: Looking for a few recruits?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[53666] = { ["id"] = 53666, ["name"] = "Armor Up!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["mapID"] = 14, ["storyline"] = { 53666 }, ["description"] = "Ah, <name>. Word spreads quickly around here. Unfortunately, with all these orders coming in I can't afford to talk right now. If you're interested in learning more about the armory Fennick can help you with that. He's just outside.", ["objectivesText"] = "Speak with Fennick to learn what the Armory has to offer.", ["rewardGold"] = 280900, ["rewardXP"] = 50, ["rewardItems"] = { 1171, 2237, 57520, 131194, 139676, 139757, 211279, 237812 }, ["starts"] = { { ["mapID"] = 14, ["npcID"] = 133374, ["x"] = 0.252, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 14, ["source"] = "quest_giver", ["x"] = 0.252, ["y"] = 0.322 }, ["mapCandidates"] = { ["npc"] = { 14 }, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[53667] = { ["id"] = 53667, ["name"] = "Welcome to the Workshop", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 53667 }, ["description"] = "You must be the new <guy/gal> around here. Name's Margie. And that over there, that's Pixy. We run a tight crew here at the workshop. So, if you ever need anything, you know where to find us. Now, I suggest you head on over and check in with Pixy. She can show you what we have to offer.", ["objectivesText"] = "Speak with Pixy Hackwrench to learn what the Workshop has to offer. Progress: I'm workin' here.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[53668] = { ["id"] = 53668, ["name"] = "Flightgineer's Network", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 53668 }, ["description"] = "Now that we control High Perch the skies are ours! I've laid out a few plans for expanding our routes in this here note. If you'd be so kind as to deliver it to our commander, I'm sure they'll be pleased with our progress. Let me know when you're ready and l'll send ya on your way.", ["objectivesText"] = "Deliver Flightgineer Krazzle 's Note to your commander in Ar'gorok.", ["rewardItems"] = { 164598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[53669] = { ["id"] = 53669, ["name"] = "The Altar's Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 53669 }, ["description"] = "Looks like construction on the Altar of Storms is complete. I'm sure Meredith would be more than happy to show you what mysterious powers lie within.", ["objectivesText"] = "Speak with Meredith the Crone to learn what the Altar of Storms has to offer. Progress: Yea?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[53670] = { ["id"] = 53670, ["name"] = "Beasts of Newstead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 53670 }, ["description"] = "Nothing penetrates an enemy's front line like a fierce rider and a well-trained beast. Now that we control Newstead, one of our riders in particular has focused his efforts on training us a few kodos. Go, check in with Tanauk and find out what these beasts are capable of.", ["objectivesText"] = "Speak with Kodo Rider Tanauk to learn about the beasts he's been training. Progress: What are you waiting for?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[53671] = { ["id"] = 53671, ["name"] = "The Circle's Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9439, ["storyline"] = { 53671 }, ["description"] = "With the Circle of Elements under our control there are opportunities to harness the powers of the elements. Kraga understands these powers quite well. I suggest speaking with her.", ["objectivesText"] = "Speak with Kraga Tidefury to learn what she has to offer. Progress: Have you found what you were looking for?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9439 } }, ["questType"] = "standard" },
[53672] = { ["id"] = 53672, ["name"] = "Ready for Battle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 53672 }, ["description"] = "Welcome to the warfront, <name>. Our recruits are eager to join you on the battlefield. A good place to start would be Ralston. I'm sure he's got a few who could learn much fighting by your side.", ["objectivesText"] = "Speak with Ralston Karn to recruit an ally from the Barracks. Progress: Looking for a few recruits?", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[53673] = { ["id"] = 53673, ["name"] = "Armor Up!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 53673 }, ["description"] = "What've we got 'ere? A fresh, young <lad/lass> lookin' ta help better prepare our allies fer battle? Well then, Jonathan's always lookin' for a bit o' help ta keep our armory orders in full swing. I'd offer ta walk ya over, but I've got me hands full here. Ye can find him just over yonder.", ["objectivesText"] = "Speak with Jonathan Flynn to learn what the Armory has to offer.", ["rewardGold"] = 280900, ["rewardXP"] = 50, ["rewardItems"] = { 1171, 2237, 57520, 131194, 139676, 139757, 211279, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[53674] = { ["id"] = 53674, ["name"] = "The Altar's Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 53674 }, ["description"] = "With contributions in full swing it's no surprise the Altar of Kings was built with such haste. I suggest wandering over that way. You might be surprised to see what the Altar has to offer.", ["objectivesText"] = "Speak with Altarite Jesse Taylor to learn what the Altar of Kings has to offer. Progress: Yes?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[53675] = { ["id"] = 53675, ["name"] = "Welcome to the Workshop", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 53675 }, ["description"] = "Welcome to the workshop! I told Grumble I thought it best for me ta protect him from unnecessary distractions, but I think it may benefit all of us if ye get a peek at what we're doin' 'round here. Why don't ye head on over and see what we have ta offer.", ["objectivesText"] = "Speak with Grumble to learn what the Workshop has to offer. Progress: How can I help ye?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[53676] = { ["id"] = 53676, ["name"] = "The Circle's Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 53676 }, ["description"] = "The Circle of Elements presents us with an opportunity to harness great power. One of our allies, Justine, has great knowledge into what this might mean for our efforts. Seek her out. It's time you discovered the power of the elements.", ["objectivesText"] = "Speak with Justine Frost to learn what she has to offer. Progress: Discover anything?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[53677] = { ["id"] = 53677, ["name"] = "Beasts of Newstead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 53677 }, ["description"] = "Control of Newstead has allowed our forces to advance. It's also provided Vindicator Banra ample room to continue training his elekk for battle. I suggest you speak with him to learn more about what these magnificent beasts are capable of.", ["objectivesText"] = "Speak with Vindicator Banra to learn about the beasts he's been training. Progress: Remain vigilant.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
[53678] = { ["id"] = 53678, ["name"] = "Establishing a Connection", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9734, ["storyline"] = { 53678 }, ["description"] = "Now that we control High Perch the skies are ours! I've drafted plans for a flight network that provides our allies safe passage. Please, take these notes and deliver them to our commander at once. I'm happy to provide you with a gryphon that will deliver you to the base when you are ready.", ["objectivesText"] = "Deliver Grayson's Note to your commander in Stromgarde Keep.", ["rewardGold"] = 232300, ["rewardXP"] = 1060, ["rewardItems"] = { 164622, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9734 } }, ["questType"] = "standard" },
