[53719] = { ["id"] = 53719, ["name"] = "Allegiance of the Zandalari", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "It is decided, <name>. De Zandalari will join de Horde. Our path together has been a long and difficult one. We have lost much together. De Horde has sacrificed for de Zandalari, and vice versa. I can do nothing to honor that commitment except pledge our loyalty. Collect your Warchief and send them to my throne. I will extend de offer myself.", ["objectivesText"] = "Bring the Zandalari into the Horde.", ["rewardGold"] = 929400, ["rewardXP"] = 8200, ["rewardItems"] = { 157870 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145374, ["x"] = 0.4355, ["y"] = 0.1945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.473333, ["y"] = 0.340667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 16, ["flags"] = 0 } } },
[53720] = { ["id"] = 53720, ["name"] = "Allegiance of Kul Tiras", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "It is time for her maiden voyage, <name>. This aptly named vessel will carry us and her crew across the vast sea to Stormwind Harbor. There we will meet Anduin and I will seal the pact we made so many moons ago. Kul Tiras will stand with the Alliance so long as I am Lord Admiral. Thank you for your assistance in this endeavor.", ["objectivesText"] = "Sail to Stormwind Harbor and present Anduin with his gift.", ["rewardGold"] = 842700, ["rewardXP"] = 8200, ["rewardItems"] = { 164762, 245271, 252386, 252400, 252403, 252406, 252653, 252654, 252754 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 148798, ["x"] = 0.422667, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 149518, ["x"] = 0.225, ["y"] = 0.1845 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.422667, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53721] = { ["id"] = 53721, ["name"] = "Heritage of the Zandalari", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 31 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53721 }, ["description"] = "You have faced many challenges in your time among de Horde. You carried de pride of de Zandalari on your shoulders and triumphed! Return to me. I wish to recognize de example you have set for us all.", ["objectivesText"] = "Meet Queen Talanji at the Golden Throne in Zuldazar City.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.473333, ["y"] = 0.340667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[53722] = { ["id"] = 53722, ["name"] = "Heritage of the Kul Tiran", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53722 }, ["description"] = "Gossip in Boralus has oft reached my ears of your exceptional conduct, <name>. Meet me before the keep. I wish to commend your efforts on behalf of Kul Tiras.", ["objectivesText"] = "Meet Katherine Proudmoore in Boralus.", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 150941, ["x"] = 0.519333, ["y"] = 0.489333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.519333, ["y"] = 0.489333 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
