[53725] = { ["id"] = 53725, ["name"] = "A People Shattered", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9318, ["mapID"] = 110, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "While the monument here was intended to honor the fallen members of the Shattered Sun, it quickly took on a second meaning for the sin'dorei. It was not far from here that we lost one of our greatest heroes: Anasterian Sunstrider, the last king of Quel'Thalas. He led our final effort against the Scourge and personally crossed blades with Arthas himself. As we remember the sacrifices it took to reclaim this land, we also remember the sacrifices made in its defense.", ["objectivesText"] = "Light the final flame. Progress: Yes?", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 166896 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 145793, ["x"] = 0.6028, ["y"] = 0.2836 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 145793, ["x"] = 0.6028, ["y"] = 0.2836 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.6028, ["y"] = 0.2836 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 9318 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 122, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
