[53734] = { ["id"] = 53734, ["name"] = "Walk Among Ghosts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["series"] = { 53791 }, ["description"] = "Every year, we ask a champion of our people to perform an act of remembrance in honor of those who fell to the Scourge. Lady Liadrin has performed this ritual, as have I, among others. This year, I am honored to give the task to you. <The Regent Lord hands you an ornate lantern.> This lantern carries a flame born of the Sunwell. I would ask that you bring it to locations that were significant to the fall of the Sunwell and of Quel'Thalas, and to light the memories we cannot forget.", ["objectivesText"] = "Meet Lor'themar in Tranquillien.", ["rewardGold"] = 31500, ["rewardXP"] = 850, ["rewardItems"] = { 166896 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 145015, ["x"] = 0.462, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.618667, ["y"] = 0.301 }, ["mapCandidates"] = { ["npc"] = { 95, 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53735] = { ["id"] = 53735, ["name"] = "The First to Fall", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "Arthas cut through the land itself to get to the Sunwell. The Dead Scar is a constant reminder of that desecration. Where it starts is where our first line of defense attempted to hold the Scourge at bay. It is where the first blood was spilled. It was a slaughter. Take the lantern to the base of the Dead Scar, and use its light to reveal the memories of what happened there.", ["objectivesText"] = "Witness the fall of the first defenders. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 166896 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3433 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53736] = { ["id"] = 53736, ["name"] = "Lament of the Highborne", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "The next memory... Forgive me. For many of our people, it was when we realized death was coming for us. A memorial to a particular defender lies to the west, in the place of her home. The light there has no doubt attracted some of the area's lingering souls. Clear them out, and then relight the flame.", ["objectivesText"] = "Light the second memorial flame.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 166896 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3433 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53737] = { ["id"] = 53737, ["name"] = "The Day Hope Died", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 4, 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3430, ["mapID"] = 95, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "The Ranger-General fell just east of Fairbreeze Village, where she was holding the line to protect the civilians as they retreated to Silvermoon. If it wasn't for her, our people would number even less than we do now. Shine the lantern upon the battlefield, and witness how her forces ultimately broke under Arthas's personal assault.", ["objectivesText"] = "Witness the fall of the Ranger-General. Progress: <Lor'themar is silent.>", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 166896 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 3430 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53738] = { ["id"] = 53738, ["name"] = "Defense of Quel'Danas", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "With our best defenders defeated and the line broken, Arthas made quick work of Silvermoon's remaining forces and tore through the city. This is where we part ways. I must return to Silvermoon before Halduron starts sending rangers to search for me. The dragonhawk master in Fairbreeze Village has orders to fly you to Quel'Danas. Someone much more familiar with the events on the island will meet you there.", ["objectivesText"] = "Meet with Lady Liadrin in Quel'Danas.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 166896 }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 145793, ["x"] = 0.6028, ["y"] = 0.2836 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.6028, ["y"] = 0.2836 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 122, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } } },
