[53759] = { ["id"] = 53759, ["name"] = "Look Out Below!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 1161, ["storyline"] = { 53759 }, ["objectivesText"] = "Use the Siege Cannon Boralus Defenders slain Buildings destroyed", ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Use the Siege Cannon", ["amount"] = 1, ["type"] = 3, ["objectID"] = 144930, ["orderIndex"] = 0 }, { ["text"] = "Boralus Defenders slain", ["amount"] = 40, ["type"] = 0, ["objectID"] = 145241, ["orderIndex"] = 1 }, { ["text"] = "Buildings destroyed", ["amount"] = 8, ["type"] = 0, ["objectID"] = 145253, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["db2QuestInfoID"] = 259, ["db2QuestInfoName"] = "Faction Assault World Quest" },
[53760] = { ["id"] = 53760, ["name"] = "Unintended Consequences", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 896, ["storyline"] = { 53760, 53761, 53762, 53763, 53765, 53766, 54058, 54113, 54114, 54117, 54118, 54126, 54141, 54144, 54172, 54174, 54265, 54433, 54438, 54439, 54682, 54683 }, ["series"] = { 53761, 53762, 54058, 54113, 54114, 54117, 54118, 54144, 54174, 54265, 54433 }, ["description"] = "< Xal'atath speaks once more.> The servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers. The particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean. Even now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea. Come, <class>. We can find a much better use for such a prize.", ["objectivesText"] = "Find the Void Stone in Drustvar. Progress: Yes... this form should do nicely.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164761, 164911, 165605, 168123 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 144773, ["x"] = 0.198, ["y"] = 0.362 }, { ["mapID"] = 896, ["npcID"] = 152589, ["x"] = 0.2, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 10, ["flags"] = 0 } } },
[53761] = { ["id"] = 53761, ["name"] = "The Pirate's Treasure", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53760, 53761, 53762, 53763, 53765, 53766, 54058, 54113, 54114, 54117, 54118, 54126, 54141, 54144, 54172, 54174, 54265, 54433, 54438, 54439, 54682, 54683 }, ["series"] = { 53760, 53762, 54058, 54113, 54114, 54117, 54118, 54144, 54174, 54265, 54433 }, ["description"] = "I sense another relic. A trident thought lost to the depths. It calls to me, <name>. Do you hear it too? Its song takes form. I see a harbor to the east. An ambitious pirate, greedy and proud. Completely unaware of the power hidden within her hoard of gold. The would-be-captain's hubris will not permit her to simply hand over her prize. I fear she must be taught a rather harsh lesson. But that is your specialty, is it not?", ["objectivesText"] = "Find the second relic. Progress: Is the trident in your possession?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164761, 164763, 164976, 165605, 168123 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 144773, ["x"] = 0.198, ["y"] = 0.362 }, { ["mapID"] = 896, ["npcID"] = 152589, ["x"] = 0.2, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145396, ["x"] = 0.75, ["y"] = 0.776 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 895, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53762] = { ["id"] = 53762, ["name"] = "The Tempest Crown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53760, 53761, 53762, 53763, 53765, 53766, 54058, 54113, 54114, 54117, 54118, 54126, 54141, 54144, 54172, 54174, 54265, 54433, 54438, 54439, 54682, 54683 }, ["series"] = { 53760, 53761, 54058, 54113, 54114, 54117, 54118, 54144, 54174, 54265, 54433 }, ["description"] = "< Xal'atath breathes in deeply and smiles.> My strength grows. I can see it clearly now... the third relic we seek. The crown known as Tempest Caller . How fitting that after the fall of Atal'Gral, the gluttonous Toatana would be the one to find the artifact. He was always scuttling about the depths, seeking treasures for his collection. Toatana 's greed has left him trapped within a cave he can never leave. The crown awaits us there.", ["objectivesText"] = "Retrieve the third relic. Progress: The crown is far more useful in our hands than in the claws of an oversized bottom-feeder.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164761, 165018, 165605, 168123 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145396, ["x"] = 0.75, ["y"] = 0.776 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 146384, ["x"] = 0.524, ["y"] = 0.136 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.75, ["y"] = 0.776 }, ["mapCandidates"] = { ["npc"] = { 864, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53763] = { ["id"] = 53763, ["name"] = "Twist the Knife", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 53760, 53761, 53762, 53763, 53766, 54058, 54117, 54118, 54172, 54174, 54433, 54439, 54683 }, ["description"] = "The relics are ours... as it was meant to be. There is but one more step needed for the great truths to be revealed. The naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion. I will go on ahead and begin preparations. Join me there.", ["objectivesText"] = "Meet Xal'atath at the Precipice of Oblivion. Progress: We are so close now... to the end.", ["rewardGold"] = 683200, ["rewardXP"] = 8520, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 146384, ["x"] = 0.524, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 }, { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 84, 864, 1165 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53765] = { ["id"] = 53765, ["name"] = "His Eye Upon You", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53760, 53761, 53762, 53765, 54058, 54113, 54114, 54126, 54141, 54144, 54265, 54438, 54682 }, ["description"] = "Something dark has taken root within you, <name>. The tendrils of N'Zoth are burrowing into your mind and soul, eager to consume everything you are. I can perform a rite of cleansing, but only in a place that resonates with the very power that grips you. Meet me near the Crucible of Storms. The ritual will be perilous and painful, but it is your only chance to be free. The Old God has eyes everywhere. I do not wish you to become one of them.", ["objectivesText"] = "Meet Brother Pike near the Crucible of Storms to cleanse your \"gift\". Progress: There can be no treating with the darkness, <name>.", ["rewardGold"] = 202200, ["rewardXP"] = 850, ["rewardItems"] = { 6286, 21134, 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 146902, ["x"] = 0.675333, ["y"] = 0.212667 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 148134, ["x"] = 0.852, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.675333, ["y"] = 0.212667 }, ["mapCandidates"] = { ["npc"] = { 942, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 16, ["flags"] = 0 } } },
