[53774] = { ["id"] = 53774, ["name"] = "Wisdom of the Warchief", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 1165, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53775 }, ["description"] = "Champion. For a brief moment after the battle with G'huun, the spirit of our old warchief, Vol'jin, appeared in view of all in Zuldazar. I had a hundred questions to ask my old friend, but his spirit faded before I could muster my voice. I have asked Talanji to perform her seance once more, so that I might speak with the spirit of Vol'jin. Will you collect the Glaive of Vol'jin from its resting place at the base of the pyramid and then join us at Zanchul?", ["objectivesText"] = "Meet Princess Talanji in the Hall of High Priests at Zanchul. Progress: Have you brought the glaive?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 140192, 164944, 238818 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9598 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53775] = { ["id"] = 53775, ["name"] = "Shades of Disruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8726, ["mapID"] = 1167, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53774 }, ["description"] = "Vol'jin's spirit is a slippery one. I have asked Master Gadrin and Spiritwalker Ebonhorn to aid us in calling him forth. Dis ritual will not be easy, and I ask you to be on your guard should anything other than Vol'jin appear.", ["objectivesText"] = "Assist in the ritual to summon Vol'jin's spirit.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8726 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1167, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53776] = { ["id"] = 53776, ["name"] = "To the Broken Shore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8726, ["mapID"] = 646, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["description"] = "Da Broken Shore be where I fell in battle. We were overrun, demons everywhere. Sylvanas was doing what she could, but Thrall was down and I had fallen. It was horror. And now I need ya to take me back dere. Take me glaive to da battlefield, call to me, and I will come. Perhaps if I be in da spot where me blood was spilled, we might shine some light on dis mystery.", ["objectivesText"] = "Take the Glaive of Vol'jin to Spiritwalker Ebonhorn at the Broken Shore.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 136582, 136583, 136584, 136586, 136587, 136588, 136589, 136590, 136591, 136595, 138764, 138765, 138766, 138767, 138768, 138769, 138770, 138771, 138772, 139292, 165401, 237812, 246812, 246814 }, ["ends"] = { { ["mapID"] = 646, ["npcID"] = 146734, ["x"] = 0.632, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 8726 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53777] = { ["id"] = 53777, ["name"] = "Where He Died", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53779, 54145 }, ["description"] = "Dis time, I need to bring ya to my side. We gonna walk da shadows between life and death, see if we can't uncover some clues. Be careful, $p, and be armed. Not everything on dis side wants us to find answers. Prepare yourself, den speak with me when ya be ready.", ["objectivesText"] = "Walk the shadows with Vol'jin. Progress: I not be scared away so easily. What dey gonna do, kill me again?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 146290, ["x"] = 0.46, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53778] = { ["id"] = 53778, ["name"] = "Where He Fell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 646, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 54120 }, ["description"] = "Dis be da spot, mon. Dis be where da Legion led our forces into a trap and drove a blade into me belly. Sylvanas pulled me from da ruin of da battlefield. She saved da Horde dat day. Come, let us walk around dis place and see what we can learn from da echoes of da past.", ["objectivesText"] = "Search the Screaming Cliffs with the Spirit of Vol'jin .", ["rewardGold"] = 169800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 646, ["npcID"] = 145965, ["x"] = 0.632, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 646, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 646 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 646, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53779] = { ["id"] = 53779, ["name"] = "The Lies of a Loa", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53777, 54145 }, ["description"] = "Hidden memories, spirits attackin' us for investigating, and a long road of bodies in da wake of me makin' Sylvanas warchief. I be thinkin' it time ya speak with Ol' Bwonsamdi. Odd as it sounds, dis don't seem like his style. Dat don't mean he not be behind it. Ya best work with Talanji. From what little I been seein', da death loa got a soft spot for her highness. You can confront Bwonsamdi at his necropolis in Nazmir. Just... be respectful.", ["objectivesText"] = "Meet Talanji at the Necropolis in Nazmir.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 146824, ["x"] = 0.394667, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53780] = { ["id"] = 53780, ["name"] = "Jailor of the Damned", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["description"] = "I be havin' many rivals when it comes to claimin' souls. But it takes some serious mojo to do to Vol'jin what ya describe. Dat kind of power smells of old magic. Icecrown. It be more dan a pretty throne. It be an anchor dat holds dis world to da next, ya might say. I gonna open a death gate, and ya can go through and ask da Lich King if he be treadin' on Ol' Bwonsamdi 's ground.", ["objectivesText"] = "Confront the Lich King . Progress: Mind ya step. Ya be dancin' between powers dat may do more dan just kill ya.", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 10, ["flags"] = 0 } } },
[53781] = { ["id"] = 53781, ["name"] = "Eyir", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53782, 54147 }, ["description"] = "Not many got da stones or da mojo to take what be mine. Ol' Bwonsamdi always be gettin' his share. Da way Talanji be tellin' it, Vol'jin's spirit may be gettin' help from some other power. And dere be few who love to mess with souls like Eyir. A meddlin' one she be, with her wings and her valor. Ya best be seein' her in person. She be found in her vault at Skold-Ashil. And ya best not mention me name, or she might be sendin' ya back to me faster dan any death gate.", ["objectivesText"] = "Meet Talanji at Skold-Ashil in Stormheim.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 634, ["npcID"] = 146877, ["x"] = 0.612, ["y"] = 0.68 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 634, 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 634, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53782] = { ["id"] = 53782, ["name"] = "Mysteries of Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53781, 54147 }, ["description"] = "Hmph. Well, da Lich King and dat bossy val'kyr not be me only rivals. But dey were da ones most likely ta be behind all dis. Someone be playin' with very ancient mojo. Tell Vol'jin's spirit dat da answers he be lookin' for not be found in da world of da living. He gonna need to go beyond da veil ta learn what needs knowin'. Dere be some places on dat side only he can go.", ["objectivesText"] = "Speak with the Spirit of Vol'jin .", ["rewardGold"] = 929400, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147216, ["x"] = 0.395, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 11, ["flags"] = 0 } } },
[53783] = { ["id"] = 53783, ["name"] = "In the Dunes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53783, 53802, 53806, 53833, 53848, 53937, 54930, 55031 }, ["description"] = "This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data. However, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix . If I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. Anyways, I am sure you can convince him to help you.", ["objectivesText"] = "Find Dataguru Gryzix at The Forgotten Marsh in Vol'dun. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 164740, 164919, 253179, 253700 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 131840, ["x"] = 0.45, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 864, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 1, ["flags"] = 0 } } },
