[53787] = { ["id"] = 53787, ["name"] = "Modular Construction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 53787 }, ["description"] = "The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen! You look like the adventurous type, <name>. Can you go scrap up some mechs? Don't forget your Arclight Spanner!", ["objectivesText"] = "Kill mechanical constructs in the Abandoned Junkheap and salvage 8 Mecha-Cores with an Arclight Spanner.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164768 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53791] = { ["id"] = 53791, ["name"] = "The Pride of the Sin'dorei", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["series"] = { 53734 }, ["description"] = "<name>, Lor'themar Theron has requested your presence in Silvermoon. He's asking for your assistance with a ceremony of great importance.", ["objectivesText"] = "Speak with Lor'themar in Silvermoon City.", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardItems"] = { 166896, 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 146939, ["x"] = 0.391, ["y"] = 0.793 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.391, ["y"] = 0.793 }, ["mapCandidates"] = { ["npc"] = { 85, 110 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
