[53802] = { ["id"] = 53802, ["name"] = "Sethrak Persuasion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 53783, 53802, 53806, 53833, 53848, 53937, 54930, 55031 }, ["description"] = "Let me see the schematic... Yeah, yeah, alright. I can help you. I am going to need a few things to power my decoder. I need a way to channel electricity from the air around us. What better than to steal...I mean borrow some lightning rods from the sethrak that have been trying to steal my tech for weeks now! I'm sure you'll have to do some \"convincing\", but you seem like a pretty convincing <race>.", ["objectivesText"] = "Collect Faithless Lightning Rods in the Scalefang Outpost. Progress: I need those rods to do my work, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164740, 164770 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 2, ["flags"] = 0 } } },
