[53805] = { ["id"] = 53805, ["name"] = "A Friend in Needle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53805, 53807, 53881, 55177 }, ["description"] = "You can see me? Oh, thank goodness! I thought I was lost in the folds of time...again! But for one to see through the folds of time's fabric... you must be a very talented tailor, indeed. Would you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.", ["objectivesText"] = "Collect 5 Tidespray Linen and 5 Deep Sea Satin . Progress: When in Azeroth am I...?", ["rewardGold"] = 77400, ["rewardXP"] = 1705, ["rewardItems"] = { 152576, 152577, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 145022, ["x"] = 0.765, ["y"] = 0.116 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 145022, ["x"] = 0.765, ["y"] = 0.116 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.116 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 904, ["name"] = "8.1.5 Tailoring - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53806] = { ["id"] = 53806, ["name"] = "Heavy is the Head", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 53783, 53802, 53806, 53833, 53848, 53937, 54930, 55031 }, ["description"] = "Okay, I am going to need one more thing from you. The sethrak leader, Warlord Surgios, has been a real pain for me. He stole my mind enhancer. I can't do my work without it. It will make me be able to think much more clearly, and make less...deadly mistakes.", ["objectivesText"] = "Collect the Goblin \"Mind Enhancer\" from Warlord Surgios in the Scalefang Outpost. Progress: Do you have my mind enhancer?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164740, 166882 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53807] = { ["id"] = 53807, ["name"] = "A Stitch in Time", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 115, ["storyline"] = { 53805, 53807, 53881, 55177 }, ["series"] = { 55177 }, ["description"] = "Hm...I don't know that I've ever been to this time, before. I suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors . We make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up. In fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?", ["objectivesText"] = "Assist Delormi in repairing the Tears in Time. Progress: Something strange is happening. These tears have become too frequent as of late.", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["rewardItems"] = { 152576, 152668, 159959, 164733, 167231, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 904, ["name"] = "8.1.5 Tailoring - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
