[53810] = { ["id"] = 53810, ["name"] = "The Severed Thread", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 115, ["storyline"] = { 53810, 53813, 53858, 53866, 53868, 53869, 55214 }, ["description"] = "Do you see that? There's a corpse just ahead. To think the caverns have been so badly overrun... We should look at the bodies. Maybe there will be something of use to us.", ["objectivesText"] = "Investigate the corpses in the Caverns of Time.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131, 225247 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 75, ["db2QuestSortName"] = "Nightborne", ["questLines"] = { { ["id"] = 906, ["name"] = "8.1.5 Tailoring - Alliance/Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53811] = { ["id"] = 53811, ["name"] = "Children's Week", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53811 }, ["description"] = "Thank you for coming by to celebrate Children's Week, <class>. You are going to make one little boy very happy! Take this whistle. With it, you will be able to call for the child you have agreed to take care of this week. It will serve no use after Children's Week ends, as is custom. When you are ready, use the whistle and meet your new ward! I know he is ecstatic to meet you.", ["objectivesText"] = "Use the Kul Tiran Orphan Whistle to call for the ward that you will be looking after during Children's Week. Provided item:", ["rewardItems"] = { 23022, 116202, 164772, 166445, 167008, 167009, 167010, 167011 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 145291, ["x"] = 0.48, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
