[53813] = { ["id"] = 53813, ["name"] = "Rolling Up the Sleeves", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 115, ["storyline"] = { 53810, 53813, 53858, 53866, 53868, 53869, 55214 }, ["description"] = "The Caverns of Time? Strange... I spent many timelines in this very place. What's special about here-- now? We'll have to discern as much later on. It looks like we aren't the only ones who've been affected by these rifts... Let's do the Bronze Dragonflight a favor and clear out these anomalies.", ["objectivesText"] = "Kill 12 Chronal Anomalies .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 75, ["db2QuestSortName"] = "Nightborne", ["questLines"] = { { ["id"] = 906, ["name"] = "8.1.5 Tailoring - Alliance/Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53814] = { ["id"] = 53814, ["name"] = "First Sergeant Steelfang", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53814 }, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 260, ["db2QuestInfoName"] = "Faction Assault Elite World Quest", ["db2VignetteID"] = 3422, ["db2VignetteName"] = "First Sergeant Steelfang" },
[53815] = { ["id"] = 53815, ["name"] = "Whatever Happened to Saffy Flivvers?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53815 }, ["description"] = "When Azerite was discovered, my friend Saffy was sent to investigate what it could do. There was an attack and we all thought she'd died. Then it turns out she was forced to work in some kind of goblin think tank in Tanaris! But before we could get her out, the whole place exploded. Now, my bosses have written her off as dead. But she wasn't dead the first time so I'm not sure she is now. I've been told not to go looking for her, but you could take a look. Find Saffy, or what's left of her?", ["objectivesText"] = "Search for signs of Sapphronetta Flivvers in Tanaris", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 165845 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143851, ["x"] = 0.678, ["y"] = 0.265 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 151132, ["x"] = 0.446, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.678, ["y"] = 0.265 }, ["mapCandidates"] = { ["npc"] = { 71, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[53816] = { ["id"] = 53816, ["name"] = "Some Reassembly Required", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 53816 }, ["description"] = "<The word \" Feathers \" has been etched onto the broken mechanical creature -- the sort of thing the person you are looking for might have created. Collecting the pieces and recreating the mechanical construct will surely give you a clue as to their fate. The area is crawling with Venture Co. scavengers and goons. Their pockets are probably filled with mechanical bits you could use to fix Feathers .>", ["objectivesText"] = "Collect Mechanical Parts from Venture Co. personnel. Progress: <You seem to have collected all the pieces.>", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 165845, 167232 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 151132, ["x"] = 0.446, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 151132, ["x"] = 0.446, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[53817] = { ["id"] = 53817, ["name"] = "Whatever Happened to Grizzek Fizzwrench?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 862, ["storyline"] = { 53817 }, ["description"] = "When this whole Azerite mess began I had a goblin named Grizzek Fizzwrench do some research for me. He was bad for business and had to be removed from the picture. I thought it was a done deal, only now I'm hearing maybe he's not so dead. I need you to hunt this guy down and see what happened. If he's alive, eliminate him and I'll add the standard mercenary fee to your reward.", ["objectivesText"] = "Search for signs of Grizzek Fizzwrench in Tanaris.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 18986, 165845 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 136683, ["x"] = 0.584, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 151132, ["x"] = 0.446, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 71, 862 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
[53818] = { ["id"] = 53818, ["name"] = "Re-parrot", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 53818 }, ["description"] = "<Though very damaged, and filled with insects, you can tell Feathers seems to have some sort of recall program. Fixing the mechanical bird and following it back to the source may bring you to the person you seek. You were able to put the thing back together. How hard could debugging a mechanical parrot be?>", ["objectivesText"] = "Debug Feathers ' recall program.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 165845 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 151132, ["x"] = 0.446, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 151132, ["x"] = 0.446, ["y"] = 0.527 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[53819] = { ["id"] = 53819, ["name"] = "Return to the Nest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 53819 }, ["description"] = "<You decide to activate the recall subroutine. Perhaps the parrot will lead you to the person you are looking for.>", ["objectivesText"] = "Activate the recall subroutine.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 165845 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 151132, ["x"] = 0.446, ["y"] = 0.527 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 151129, ["x"] = 0.27, ["y"] = 0.6 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.527 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[53820] = { ["id"] = 53820, ["name"] = "She's in a Happier Place", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 53820 }, ["description"] = "Aww, Kelsey...she's been such a good friend. I meant to let her know I was alive eventually, but I got distracted. Azerite, the war, the near-death experience... We've been really busy. Being presumed dead has some advantages, though. We've done a lot of research and we just need a better lab- Okay. New plan. Tell Kelsey we'll be in touch, but only Kelsey. Tell everyone else I'm dead - for now. If you keep quiet about Grizzek, you- you can have Feathers . Do we have a deal?", ["objectivesText"] = "Return to Kelsey Steelspark in Boralus.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 165845 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 151129, ["x"] = 0.27, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143851, ["x"] = 0.678, ["y"] = 0.265 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 71, 1161 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[53821] = { ["id"] = 53821, ["name"] = "He's Dead, Jastor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 53821 }, ["description"] = "Hey, uh, so I got a good thing goin' on here, and I really don't want Gallywix to know I'm alive. I'll make you a deal. You spin some story about how you only found tiny pieces of me spread across Tanaris and that I am totally dead, and... And you can keep the bird. Deal?", ["objectivesText"] = "Return to Gazlowe in Zandalar Harbor.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 165845 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 151130, ["x"] = 0.27, ["y"] = 0.6 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 137313, ["x"] = 0.4455, ["y"] = 0.8975 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.27, ["y"] = 0.6 }, ["mapCandidates"] = { ["npc"] = { 71, 1165 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[53823] = { ["id"] = 53823, ["name"] = "A Queen's Entourage", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["series"] = { 53831 }, ["description"] = "Princess Talanji was very clear in her orders. You, <name>, are to join her at de steps of Zanchul. She wishes to have you at her side while she undergoes de rite of queens and kings. I hope you can comprehend what an honor that is. De queen-to-be will explain what it is you are to do. Now go, and Pa'ku's winds make you swift.", ["objectivesText"] = "Meet Princess Talanji at the Zocalo.", ["rewardGold"] = 34100, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145414, ["x"] = 0.485778, ["y"] = 0.238593 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.485778, ["y"] = 0.238593 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53824] = { ["id"] = 53824, ["name"] = "The Rite of Kings and Queens", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "Now that you are here, we can begin this sacred rite. Take your place beside Talanji, <name>. She has chosen you for an important task. I will explain while we make our way to Zanchul.", ["objectivesText"] = "Ride in procession with Princess Talanji . Progress: Your have more than earned such an honor, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 148096, ["x"] = 0.421333, ["y"] = 0.184667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 148096, ["x"] = 0.421333, ["y"] = 0.184667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.184667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53825] = { ["id"] = 53825, ["name"] = "The New Zanchuli Council", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8726, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "These are sobering developments <name>. I wish to speak to my priests about what has transpired. I would like you to continue into de depths of Zanchul and up de steps into de Council Chambers. There you will find de new council I have assembled. Greet them, and make note of my choices. I hope you will find them adequate.", ["objectivesText"] = "Greet the Zanchuli Council. Progress: What do you think of my choices, <name>?", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.4172, ["y"] = 0.1564 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8726 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1166, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53826] = { ["id"] = 53826, ["name"] = "The Instigator Among Us", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "This situation can be swiftly dealt with if we take out de one that incited this violence. I heard reports of an enforcer rousing de vagrants and drudges against de shopkeepers and guards in de Zocalo. One of my own would not do this without cause. See if you can determine de reason for this sudden change. I am told her name is Malzon. I hope for her sake that she surrenders.", ["objectivesText"] = "Confront Enforcer Malzon in the Zocalo.", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145360, ["x"] = 0.404, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53827] = { ["id"] = 53827, ["name"] = "The Council Has Spoken", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8726, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "Now that you see who I have chosen for my council, it is time to receive their blessing. It is a symbolic demonstration of support, but I believe there is power in words as well as deeds. When they declare themselves to me, de eyes of de loa are also upon them. I hope they like what they see, <name>. I know I do.", ["objectivesText"] = "Receive the Zanchuli Council's blessing.", ["rewardGold"] = 482040, ["rewardXP"] = 6830, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.4172, ["y"] = 0.1564 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8726 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1166, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 9, ["flags"] = 0 } } },
[53828] = { ["id"] = 53828, ["name"] = "Gaze of the Loa", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "My council has given their blessing and we have dealt with an enemy. All that remains is to face de judgment of my loa. I do not know what this part will be like. My father never spoke of it, at least not to me. Walk with me. I will explain what is expected of you through this final trial.", ["objectivesText"] = "Follow Talanji.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146263, ["x"] = 0.446889, ["y"] = 0.118222 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.4172, ["y"] = 0.1564 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 10, ["flags"] = 0 } } },
[53830] = { ["id"] = 53830, ["name"] = "Queen of the Zandalari", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "De loa have seen fit to grant me de crown. My council accepts me. My priests have given their blessing. My people have expressed their displeasure, but I am determined to right those wrongs. It is time to accept de responsibility of leadership. I will address them and speak on our future. I would be honored if you would take a place at my side while I do so.", ["objectivesText"] = "Witness Talanji's ascension to Queen of the Zandalari.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.4172, ["y"] = 0.1564 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 15, ["flags"] = 0 } } },
[53831] = { ["id"] = 53831, ["name"] = "A Royal Occasion", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["series"] = { 53823 }, ["description"] = "You wish to hear how the Zandalari joined the Horde? My people have had a... difficult history with the Zandalari. However, I believe we dealt with the Zandalari of the past. The now Queen Talanji is much different from her father. I'm rambling, my apologies. Our tale begins after the Alliance sacked the city of Zuldazar and killed King Rastakhan. The Horde had been invited by the then Princess Talanji to witness her coronation in Zuldazar...", ["objectivesText"] = "Meet the Zandalari emissary at The Great Seal in Dazar'alor.", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133519, ["x"] = 0.376667, ["y"] = 0.807333 }, { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145414, ["x"] = 0.485778, ["y"] = 0.238593 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.376667, ["y"] = 0.807333 }, ["mapCandidates"] = { ["npc"] = { 85, 1165 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53832] = { ["id"] = 53832, ["name"] = "Counter-Sabotage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53832 }, ["objectivesText"] = "Pick up Hide-No-More 2000 Alliance saboteurs slain", ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Pick up Hide-No-More 2000", ["amount"] = 1, ["type"] = 0, ["objectID"] = 145355, ["orderIndex"] = 0 }, { ["text"] = "Alliance saboteurs slain", ["amount"] = 6, ["type"] = 0, ["objectID"] = 145410, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 259, ["db2QuestInfoName"] = "Faction Assault World Quest" },
[53833] = { ["id"] = 53833, ["name"] = "Vengeful Venture", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 1165, ["storyline"] = { 53783, 53802, 53806, 53833, 53848, 53937, 54930, 55031 }, ["description"] = "<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen. You need to retrieve his decoder and the schematic and bring them back to Shuga Blastcaps to have any hope of crafting the Ub3r-Spanner. That mech you have following you should prove itself useful.>", ["objectivesText"] = "Locate the Venture Co. camp, then retrieve Gryzix's Decoder and the Encrypted Ub3r-Spanner schematic . Progress: What's up, <name>? Did Gryzix handle that schematic for you?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164740, 164773, 164919, 166886 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 131840, ["x"] = 0.45, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53835] = { ["id"] = 53835, ["name"] = "Something Valuable, Perhaps?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "<The tablet is too worn to be read. While some of the characters are legible, reading the tablet will be impossible without assistance. You can discern only a single word: Aegrim.>", ["objectivesText"] = "Bring the tablet to Brann Bronzebeard in the Hall of Explorers in Ironforge.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 48933, 164946, 164960 }, ["ends"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["db2QuestSortName"] = "Epic", ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53836] = { ["id"] = 53836, ["name"] = "Ancient Armor, Ancient Mystery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8161, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "By my beard! Do you know what this is?! It's an ancient tablet that describes how to forge the Bulwark of the Mountain King! The last one to wear that armor was Aegrim Bronzebeard, my ancestor and thane of the Bronzebeard clan. Talk to Advisor Belgrum . He'll know more about Aegrim's past, and might be able to shine some light on the legends of his armor.", ["objectivesText"] = "Speak to Advisor Belgrum in Old Ironforge.", ["rewardGold"] = 34100, ["rewardXP"] = 850, ["rewardItems"] = { 48933, 164946, 164960 }, ["starts"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 8161 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 1361, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53837] = { ["id"] = 53837, ["name"] = "Watch Yer Back", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 1361, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "Aegrim, you say? Bulwark of the Mountain King? Well, if we are going to start anywhere, it has to be Aegrim's study. The entrance lies below us in the depths of Old Ironforge. The only trouble is the troggs in our way. How about you take the lead?", ["objectivesText"] = "Kill 8 Trogg Invaders and Roc'maw the Burrower in Old Ironforge.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 48933, 164946, 164960 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiUiMapID"] = 1361, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53838] = { ["id"] = 53838, ["name"] = "Keep Yer Feet On The Ground", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "<name>! The Explorers League is setting up a new exhibit in the Hall of Explorer. A team of dwarves went in search of new artifacts to display in it. They headed off to Gol'Bolar Quarry in Dun Morogh, but haven't returned. Would you mind checking in on them?", ["objectivesText"] = "Search Gol'Bolar Quarry for the missing excavation crew.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 48933, 164946, 164960, 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 146988, ["x"] = 0.545, ["y"] = 0.18 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 31, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53839] = { ["id"] = 53839, ["name"] = "Aegrim's Study", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1537, ["mapID"] = 1361, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "This leads to Aegrim's study. I still have some scrolls to sort, so I will leave you to search the study at your leisure. I'm sure Brann would be most interested in any of your findings.", ["objectivesText"] = "Search Aegrim's study for the Bulwark of the Mountain King.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 48933, 164946, 164960 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1537 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 1361, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53840] = { ["id"] = 53840, ["name"] = "Interest Yah In A Pint?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 38, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "The armor may be shattered, but there's still hope. With the fragments you found, we might be able to forge it anew. This is far outside my area of expertise, but there may be someone who can help. We should speak with Grumnus Steelshaper . He retired to Thelsamar in Loch Modan. Go on ahead, I'll meet you there.", ["objectivesText"] = "Find Grumnus Steelshaper in Loch Modan.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 48933, 164946, 164960 }, ["starts"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 48, ["npcID"] = 5164, ["x"] = 0.35, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 38 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 48, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53841] = { ["id"] = 53841, ["name"] = "Shards of the Past", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1537, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "<The armor that once was here has mysteriously shattered. Pieces of the ancient armor are scattered around the room.>", ["objectivesText"] = "Collect the shattered pieces of armor. Progress: What do ye have here?", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 48933, 164946, 164960 }, ["ends"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 1537 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53842] = { ["id"] = 53842, ["name"] = "Earthen Blessing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 38, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "Ignis will help with smelting the metal, but the heat from the forge will cook you in yer boots! Our ancestors, the dwarves who forged Aegrim's armor, could sustain their stoneform for far longer than we can today. That's how they could forge the bulwark in the first place. Luckily, my friend Bouldercrag can help us with that. He'll need some materials for the ritual.", ["objectivesText"] = "Find the Remnant of the Earthen Ritual in Old Ironforge. Progress: Do you have it?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 48933, 164946, 164960 }, ["starts"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 48, ["npcID"] = 145866, ["x"] = 0.35, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 38 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53844] = { ["id"] = 53844, ["name"] = "Recruiting the Furnace Master", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8161, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "Grumnus says we're going to need some help smelting this metal. I just happen to know someone who's perfect for the job. We're heading to Ulduar! Years ago, we fought against a construct named Ignis the Furnace Master. I've heard tell that the titan keepers brought him back, and Ulduar's furnace is alive once more.", ["objectivesText"] = "Recruit Ignis the Furnace Master to help smelt the metal. Progress: It's been a long time since I've been in Ulduar.", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["rewardItems"] = { 48933, 164946, 164960 }, ["starts"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 8161 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 48, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53845] = { ["id"] = 53845, ["name"] = "Forging the Armor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1537, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "It's time to begin. Bouldercrag, Ignis, and I are here to assist you. You'll be the first dwarf to forge the Bulwark of the Mountain King in generations. This ol' blacksmith is honored to be able to witness this. Are ye ready?", ["objectivesText"] = "Forge the Bulwark of the Mountain King. Progress: Is it done?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 48933, 164946, 164960, 165704 }, ["starts"] = { { ["mapID"] = 48, ["npcID"] = 5164, ["x"] = 0.35, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 48, ["npcID"] = 5164, ["x"] = 0.35, ["y"] = 0.488 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48 }, ["zone"] = { 1537 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[53846] = { ["id"] = 53846, ["name"] = "Legacy of the Bronzebeard", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1537, ["mapID"] = 48, ["storyline"] = { 53835, 53836, 53837, 53838, 53839, 53840, 53841, 53842, 53844, 53845, 53846 }, ["description"] = "You must present this armor to Muradin at once! This is an historic day for the dwarven people. This isn't just a suit of armor, it's a symbol of our heritage.", ["objectivesText"] = "Present the Bulwark of the Mountain King to Muradin Bronzebeard in the High Seat.", ["rewardGold"] = 1024800, ["rewardXP"] = 10225, ["rewardItems"] = { 48933, 164946, 164960, 224449 }, ["starts"] = { { ["mapID"] = 48, ["npcID"] = 145462, ["x"] = 0.35, ["y"] = 0.488 } }, ["ends"] = { { ["mapID"] = 87, ["npcID"] = 42928, ["x"] = 0.395667, ["y"] = 0.558667 } }, ["coords"] = { ["mapID"] = 48, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.488 }, ["mapCandidates"] = { ["npc"] = { 48, 87 }, ["zone"] = { 1537 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 87, ["questLines"] = { { ["id"] = 804, ["name"] = "Dwarven Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[53847] = { ["id"] = 53847, ["name"] = "On Whispered Winds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "<name>, I have need of you. Maiev and Shandris are en route to Stormwind to petition King Wrynn for aid in retaking Darkshore. You have proven a loyal ally to my people in times past. I ask that you join their audience with the king and lend your voice to our cause. I suspect we shall meet again soon. -Tyrande", ["objectivesText"] = "Meet Maiev Shadowsong and Shandris Feathermoon in Stormwind Keep.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 165232, 165233, 165250 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 152000, ["x"] = 0.705, ["y"] = 0.269 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 146050, ["x"] = 0.8632, ["y"] = 0.3516 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.269 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53848] = { ["id"] = 53848, ["name"] = "Tooling Around Vol'dun", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 53802, 53806, 53848, 53947, 53948, 53949, 54930, 55028 }, ["description"] = "Okay, <name>. We got almost everything we need. Almost. You see, I lost my toolbox. I must have dropped it while running from the sethrak a couple days ago. Can ya fetch it for me? I'm not a very good engineer without my tools! And take a mech with ya. I've spied some mysterious dwarven and troll figures lurking around... better not be the Venture Co. One whiff of the schematic being here and we got trouble. You'll need the mind enhancer for it to follow you. Just put it on and you'll be good to go!", ["objectivesText"] = "Put on the Goblin \"Mind Enhancer,\" then retrieve Gryzix's toolbox . Progress: <Gryzix appears to be dead.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164740, 166881 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 145279, ["x"] = 0.262, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53849] = { ["id"] = 53849, ["name"] = "Waning Hope", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "The kaldorei have been steadfast members of the Alliance since the end of the Third War. We have fought on distant shores and even on different worlds without protest. It is curious that in our moment of need, their resources are stretched too thin to lend so much as a single blade. Wrynn has already denied Tyrande aid. Witness it for yourself.", ["objectivesText"] = "View Tyrande's audience with Anduin Wrynn. Progress: This will not stand.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 165232, 165233, 165250 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 146050, ["x"] = 0.8632, ["y"] = 0.3516 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 146050, ["x"] = 0.8632, ["y"] = 0.3516 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8632, ["y"] = 0.3516 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53850] = { ["id"] = 53850, ["name"] = "Our War Continues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53850 }, ["description"] = "The work to stop the Alliance is far from over, <name>. But thanks to you, we have the methods necessary to break them. The Abyssal Scepter has been delivered to King Rastakhan, earning us more of his favor. There is a matter of greater importance that I would speak to you about... but not here. Meet me aboard the Banshee's Wail within Zuldazar.", ["objectivesText"] = "Speak with Sylvanas Windrunner aboard the Banshee's Wail in Zuldazar.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164778 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 134711, ["x"] = 0.485, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85, 862 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[53851] = { ["id"] = 53851, ["name"] = "Our War Continues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "The work to stop the Alliance is far from over, <name>. King Rastakhan now possesses the Abyssal Scepter that you recovered from the Kul Tirans. He has placed it... in his treasury. The Dark Lady wishes to speak with you regarding the corpse you found at the bottom of the ocean. Derek Proudmoore.", ["objectivesText"] = "Speak with Sylvanas Windrunner aboard the Banshee's Wail.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164778, 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53852] = { ["id"] = 53852, ["name"] = "Azerite Denied", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "The Kul Tirans and Alliance are amassing a vast amount of their Azerite and Azerite weapons within Tiragarde Sound. They have a new supply of the resource, thanks to the Kul Tirans' conquest over Lady Ashvane and her company. We must strike at their supplies of Azerite and destroy these weapons, or else we will be behind in this war. You and Zelling will travel to Tiragarde Sound and meet with Rexxar . Lead the assault on their Azerite supply. And do not return until you are victorious.", ["objectivesText"] = "Meet Rexxar in Tiragarde Sound.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164778, 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53853] = { ["id"] = 53853, ["name"] = "The Setting Sun", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4080, ["mapID"] = 110, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "Remember the Sunwell. We ride into battle with those words for a reason. We lost so much that day... I lost so much that day. Shine the lantern on the southern side of the island, where the Dead Scar meets the sea. There you will see how the fall of the Sunwell began. And with it, the last act of the High Elves.", ["objectivesText"] = "Witness the fall of Anasterian. Progress: Is it done, champion?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 5232, 19004, 166896, 194885, 211279 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 145793, ["x"] = 0.6028, ["y"] = 0.2836 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 145793, ["x"] = 0.6028, ["y"] = 0.2836 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.6028, ["y"] = 0.2836 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 4080 } }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 122, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53856] = { ["id"] = 53856, ["name"] = "The Fury of the Horde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "The Norwington Estate has a large cache of Azerite, along with the Alliance's latest Azerite weapons. We need to steal these weapons and all of their Azerite. Every weapon stolen is a Horde life saved. When you are ready to strike, let me know. I shall signal our warriors to begin the assault. The Alliance and Kul Tirans will see the true might of the Horde!", ["objectivesText"] = "Command the Horde army to attack Norwington Manor. Progress: The Alliance will see our might.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164778, 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.5055, ["y"] = 0.2695 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53857] = { ["id"] = 53857, ["name"] = "Cap'n Gorok", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53857 }, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 260, ["db2QuestInfoName"] = "Faction Assault Elite World Quest", ["db2VignetteID"] = 3446, ["db2VignetteName"] = "Cap'n Gorok" },
[53858] = { ["id"] = 53858, ["name"] = "Step Into Her Shoes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 115, ["storyline"] = { 53810, 53813, 53858, 53866, 53868, 53869, 55214 }, ["series"] = { 53866, 55214 }, ["description"] = "Another one of those rifts. Normally I'd repair it, but given the circumstances I wish to see where it leads. It isn't often I commune with versions of myself from other threads of time. But one particular self has been a dear friend for some time. I feel myself growing weaker. If she perishes... We don't have much time. We need to enter this rift now.", ["objectivesText"] = "Enter the Time Rift with Timeweaver Delormi . Progress: We must hurry--I fear the worst, otherwise.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 906, ["name"] = "8.1.5 Tailoring - Alliance/Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53859] = { ["id"] = 53859, ["name"] = "The Mountain Folk", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53859 }, ["description"] = "All Kul Tirans are really tough, but the Roughnecks are the roughest and toughest of them all! They can wrestle gryphons with their bare hands! They can knock down a yeti with a single punch! I wanna meet a Roughneck and prove that I can be really strong like them! Can you take me to their camp? I've heard it's up in the mountains by Anglepoint.", ["objectivesText"] = "Take Liam to meet the Roughnecks at the Roughneck Camp in Tiragarde Sound. Make sure to call for him if he is not present when you get there. Progress: I'm gonna be big and strong and eat raw goat with my teeth!", ["rewardItems"] = { 23022, 116202, 164772, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53861] = { ["id"] = 53861, ["name"] = "Yo Ho, Yo Ho!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53861 }, ["description"] = "The orphan matron is always telling us what to do! Study your books, practice your words, behave in public... What if I want to be a pirate when I grow up? A scourge of the high seas! Finding buried treasure, dueling my enemies on the mast, wearing cool hats! Pirates never come into Boralus, so I've only ever heard stories. I wanna meet a real one! Can you take me to Freehold? I'll practice my pirate voice on the way. YARRRRR!", ["objectivesText"] = "Take Liam to meet a pirate outside of Freehold in Tiragarde Sound. Make sure to call for him if he is not present when you get there. Progress: Yo ho, yo ho!", ["rewardItems"] = { 23022, 116202, 164772, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53862] = { ["id"] = 53862, ["name"] = "The Squid Shrine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53862 }, ["description"] = "Sometimes tidesages come to the orphanage and tell us about the sea and how they can talk to it. I wanna talk to water! We've gone on field trips to their monastery here in Boralus, but I heard their home in Stormsong is much more impressive. Can you take me to go see it? I heard there's a great view from the Brineworks!", ["objectivesText"] = "Take Liam to see Shrine of the Storms from the beach near Mariner's Strand in Stormsong Valley. Make sure to call for him if he is not present when you get there. Progress: The tidesages always say that the water talks to them. How does it talk without a mouth?", ["rewardItems"] = { 23022, 116202, 164772, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53863] = { ["id"] = 53863, ["name"] = "Bird Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53863 }, ["description"] = "My best friend at the orphanage is named Billy. He's just a kid like me, though. I heard that some people in Drustvar have FALCONS as their best friend. How cool is that?! Can we go meet a falconer? Pretty please? I want to have a bird friend too. I hear there's a big statue in Arom's Stand of some dead guy who was friends with birds. Maybe we can find a falconer there!", ["objectivesText"] = "Take Liam to see the statue of Arom Waycrest at Arom's Stand in Drustvar. Make sure to call for him if he is not present when you get there. Progress: I wish I had feathers like a bird!", ["rewardItems"] = { 23022, 116202, 164772, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53864] = { ["id"] = 53864, ["name"] = "Shapeshifters!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53864 }, ["description"] = "Being a human is alright and all, but what if I could be a BEAR? Druids can be bears. And cats! And who knows what else! I've heard rumors of druids in the mountains of Drustvar. It would be so cool to meet one. I wanna see them turn into animals! Maybe they can teach me, too!", ["objectivesText"] = "Take Liam to meet a druid at Ulfar's Den in Drustvar. Make sure to call for him if he is not present when you get there. Progress: Roar! Growl! Bear sounds!", ["rewardItems"] = { 23022, 116202, 164772, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53865] = { ["id"] = 53865, ["name"] = "Return to the Orphanage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53865 }, ["description"] = "This has been the best Children's Week ever! I was scared to grow up, but now I'm really excited! There are so many cool things I can be! But how can I choose? I think it's time for you to take me back to the orphanage , <name>. I'll think about what I want to be when I grow up on the way.", ["objectivesText"] = "Bring Liam back to the orphanage in Boralus. Make sure to call for him if he is not present when you get there. Progress: What a great trip!", ["rewardItems"] = { 23022, 116202, 164772, 167008, 167009, 167010, 167011, 241215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53866] = { ["id"] = 53866, ["name"] = "If The Shoe Fits...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 115, ["storyline"] = { 53810, 53813, 53858, 53866, 53868, 53869, 55214 }, ["series"] = { 53858, 55214 }, ["description"] = "That thing is killing her...it's killing *me*! We need to stop it! Please, I need your help to save my self!", ["objectivesText"] = "Stop the Shade of Delormi from killing Magistrix Delormi . Progress: Please, we need your help!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 906, ["name"] = "8.1.5 Tailoring - Alliance/Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53867] = { ["id"] = 53867, ["name"] = "Engineer Bolthold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53867 }, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 260, ["db2QuestInfoName"] = "Faction Assault Elite World Quest", ["db2VignetteID"] = 3456, ["db2VignetteName"] = "Engineer Bolthold" },
[53868] = { ["id"] = 53868, ["name"] = "Saving Nine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 115, ["storyline"] = { 53810, 53813, 53858, 53866, 53868, 53869, 55214 }, ["series"] = { 53869 }, ["description"] = "I saw her in there, destroying another part of my timeline. With every thread she severs, I lose myself more and more... Perhaps I will perish, but I won't let her ruin the fabric of time. I need you to join me one last time. I can only end this with your support.", ["objectivesText"] = "Enter the Time Rift. Progress: We can't fail. Not with what's at stake.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 906, ["name"] = "8.1.5 Tailoring - Alliance/Horde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53869] = { ["id"] = 53869, ["name"] = "Killing Time", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 53810, 53813, 53858, 53866, 53868, 53869, 55214 }, ["series"] = { 53868 }, ["description"] = "Now, <name>, stand with me. I am weak. So many threads have been severed. I'll use what power I have left to mend the rift. Please...make sure the fabric of time is safe from her.", ["objectivesText"] = "Kill the Infinite Shade of Delormi . Progress: Please...I need your help!", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 906, ["name"] = "8.1.5 Tailoring - Alliance/Horde", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53870] = { ["id"] = 53870, ["name"] = "Guests at Grommash Hold", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "$p, I've received word that a vulpera caravan has arrived at Grommash Hold. They wish to address the Horde and have requested your presence. I'm afraid it is not the best time for guests, so please see them as soon as you are able.", ["objectivesText"] = "Meet your guests within Grommash Hold.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133523, ["x"] = 0.378667, ["y"] = 0.809333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 145416, ["x"] = 0.4856, ["y"] = 0.7184 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.378667, ["y"] = 0.809333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 0, ["flags"] = 0 } } },
