[53879] = { ["id"] = 53879, ["name"] = "Cleaning Out the Estate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "We must keep moving forward. Our goal is to weaken the Alliance, destroy their weapons, and steal their Azerite . The three of us will carve a path of destruction through our enemies. Let us go!", ["objectivesText"] = "Weaken the Norwington Estate defenders. Progress: Do not give in to the Alliance!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.5055, ["y"] = 0.2695 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53880] = { ["id"] = 53880, ["name"] = "Machines of War and Azerite", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "The Norwington Estate... I remember taking walks here with my wife and children. Sorry, this isn't the time for remembering an old life. The Alliance have Azerite bombs and rifles scattered throughout the estate. I believe our goal is to recover them. If only the Alliance hadn't chosen to use the estate as a testing ground... this was meant to be a place of peace.", ["objectivesText"] = "Recover 4 Azerite bombs and 3 Azerite rifles . Progress: Is it done?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164778, 164917, 164987, 165225, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145423, ["x"] = 0.4795, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4795, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53881] = { ["id"] = 53881, ["name"] = "Cut from the Same Cloth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 115, ["storyline"] = { 53805, 53807, 53881, 55177 }, ["description"] = "My Infinite self was right. I can no longer mend time. Too many of my threads have been purged. I can feel no others. I'm alone now. And my thread is gone. But not you. Take this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more. The fabric of time needs your hands to mend it. I trust you with that responsibility. Talk to me when you're ready. I'll take you back to when this all began.", ["objectivesText"] = "Ask Timeweaver Delormi to return you to your time.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 904, ["name"] = "8.1.5 Tailoring - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53882] = { ["id"] = 53882, ["name"] = "Writing on the Wall", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredRaces"] = { 4, 10, 28 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "Long has the southern wall separated Quel'Thalas from the once great kingdom of Lordaeron. We did not believe that anyone could breach it. That overconfidence was our undoing. When the Scourge arrived, the gate was not conquered by force. It was willingly opened by a traitor. Though caught unaware, every Farstrider, soldier, and magister in the area rushed to the defense of our homeland. Very few of them returned home. The gates now stand as a memorial in their name.", ["objectivesText"] = "Light the first memorial's flame. Progress: Take the time you need.", ["rewardGold"] = 280900, ["rewardXP"] = 850, ["rewardItems"] = { 166896 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 145015, ["x"] = 0.462, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.462, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53883] = { ["id"] = 53883, ["name"] = "Shores of Zuldazar", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53883 }, ["description"] = "Alliance forces are attacking Zuldazar. Make them regret every step taken on our soil!", ["objectivesText"] = "Repel the Alliance forces assaulting Zuldazar. Progress: The Alliance dares to assault us in Zuldazar?! We must crush these fools so cruelly and so swiftly that they never consider this again.", ["rewardXP"] = 2125, ["rewardItems"] = { 152813, 165871, 166792, 168419 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135447, ["x"] = 0.58, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[53885] = { ["id"] = 53885, ["name"] = "Isolated Victory", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 53885 }, ["description"] = "Alliance forces are pushing deeper into Vol'dun. We can not allow this aggression to go unchecked!", ["objectivesText"] = "Repel the Alliance forces assaulting Vol'dun. Progress: The vulpera appreciate the Horde's protection here. I didn't realize the Alliance could be so... relentless.", ["rewardXP"] = 2125, ["rewardItems"] = { 165871 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 135804, ["x"] = 0.566, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
