[53887] = { ["id"] = 53887, ["name"] = "War Marches On", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "I hope the Horde will think twice about attacking Kul Tiras in the future, but given the actions of its leadership, it is a faint hope at best. Still, what matters most is my people are safe now. The fleet and marines should be here soon to help the Outriggers clear out what remains of the Horde forces. Please return to High Commander Wyrmbane and let him know I will join everyone as soon as I am able. Thank you for your swift actions today, <name>.", ["objectivesText"] = "Return to Halford Wyrmbane on the Wind's Redemption.", ["rewardGold"] = 28090, ["rewardXP"] = 1705, ["rewardItems"] = { 164921, 164968, 166280, 166682, 245271, 252386, 252400, 252403, 252406, 252653, 252654, 252754 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.3024 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 14, ["flags"] = 0 } } },
[53888] = { ["id"] = 53888, ["name"] = "To Anglepoint", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "An attack on Anglepoint Wharf can only mean one thing: the Horde seeks to destroy the seagate there. This is my home. These are my people. I cannot turn my attention to our operations in Zandalar until we've routed the Horde. The military will take a little time to mobilize, but in the meantime you and I can face these monsters. If we can't stop them, we can slow them down. War has come to my shores once more. I will not stand aside.", ["objectivesText"] = "Accompany Jaina Proudmoore to Anglepoint Wharf and assist her there. Progress: The Horde has overrun the area. We cannot let this continue.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.3024 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53889] = { ["id"] = 53889, ["name"] = "A Declaration of Intent", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Our caravan is ready to explore the world beyond the sands, but Nisha's blade can't be our only defense against the dangers we know await us. This is why we've come. To declare our intent to join the Horde.", ["objectivesText"] = "Witness Kiro 's declaration to join the Horde.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 145416, ["x"] = 0.4856, ["y"] = 0.7184 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 145416, ["x"] = 0.4856, ["y"] = 0.7184 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.4856, ["y"] = 0.7184 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53890] = { ["id"] = 53890, ["name"] = "New Allies, New Problems", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Baine certainly has his hands full. Taking on new allies means taking on new problems. Let us find out what troubles those within the Horde and see what we can do to help. Perhaps when Baine isn't so overwhelmed, he'll be able see our true value.", ["objectivesText"] = "Find out what troubles Commander Dresh , Bladeguard Sonji , and First Arcanist Thalyssra . Progress: Let us find out what troubles those within the Horde and see what we can do to help.", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 145416, ["x"] = 0.4856, ["y"] = 0.7184 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 145416, ["x"] = 0.4856, ["y"] = 0.7184 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.4856, ["y"] = 0.7184 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53891] = { ["id"] = 53891, ["name"] = "No Problem Too Small", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "These problems might seem small, but they will eat away at the Horde over time if they remain unaddressed. We must offer our help. The vulpera are skilled at solving problems, no matter their size. I will investigate the outpost. Nisha and Meerah will see to the others. Meet me in the Twilight Highlands when you're ready.", ["objectivesText"] = "Meet Kiro in Twilight Highlands.", ["rewardGold"] = 26445, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 145416, ["x"] = 0.4856, ["y"] = 0.7184 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 163488, ["x"] = 0.44, ["y"] = 0.735 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.4856, ["y"] = 0.7184 }, ["mapCandidates"] = { ["npc"] = { 85, 241 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53892] = { ["id"] = 53892, ["name"] = "Where Are the Workers?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Look at this axe, $p. There's still sweat on the hilt. The workers were here not too long ago. Let's see if Sasha can track their scent.", ["objectivesText"] = "Find out where the Crushblow Peons went. Progress: This must be the place.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 163488, ["x"] = 0.44, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53893] = { ["id"] = 53893, ["name"] = "A Little Goodwill", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "It sounds like the peons are feeling undervalued. They do important work for the Horde, but their diligence is often overlooked. A little goodwill would go a long way. Let's plan a feast in their honor. We'll need quite a bit of meat to sate their enormous appetites, luckily, I have a totem that can help with that. You acquire the ingredients, and I will make a meal guaranteed to boost morale.", ["objectivesText"] = "Collect 100 Saber Flanks , 100 Worg Meat , and 100 Clucker Tidbits . Progress: Did you bring the meat?", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 164926, 171356, 171357, 171358, 173727, 174066 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53894] = { ["id"] = 53894, ["name"] = "Worthwhile Repairs", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "The peons are right. These tools are inexcusable. How can they be expected to complete a job without the proper tools for their trade? I can make the needed repairs, but I'll need some ore first.", ["objectivesText"] = "Collect 15 Twilight Ore so Kiro can repair the peon's tools. Progress: Have you found any ore?", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 164927, 173727, 174066 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53895] = { ["id"] = 53895, ["name"] = "Peon Promotions!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "I agree with the plight of the peons. They should be rewarded for the work they do. It's unlikely that the Horde will agree to increase their wages, but there's no reason they can't be given a promotion. Any title other than peon would help build some confidence.", ["objectivesText"] = "Give promotions to a few of the Crushblow Peons at Peon Hideout. Progress: Have the peons been promoted yet?", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53896] = { ["id"] = 53896, ["name"] = "Stand Fast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "The Horde will pay for what it has done, but first I have to attend to the people here. <name>, I need to hold a portal open so the injured can evacuate to Boralus. Keep the Horde's forces off me while the wounded get to safety. We can deal with them once the civilians are safe.", ["objectivesText"] = "Protect Jaina Proudmoore. Progress: That's the last of the wounded.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.3024 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53897] = { ["id"] = 53897, ["name"] = "A Party in Your Honor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "I think I have everything needed to make tonight a success. We just need to make sure the peons show up. Tell their leader that the Horde is throwing a party in their honor. I'm sure they won't decline a night of free food and drink.", ["objectivesText"] = "Inform Foreman Magrok that the Horde is throwing a party for the peons.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 145641, ["x"] = 0.455, ["y"] = 0.7 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 163489, ["x"] = 0.45, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.7 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53898] = { ["id"] = 53898, ["name"] = "Strength and Honor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Those peons certainly look happy, don't they? I have no doubt they'll return to work in the morning. However, if their leader goes unchallenged, there will always be risk of revolt. You need to face him to battle. Show him the true strength of the Horde, but also the honor that comes with showing mercy.", ["objectivesText"] = "Battle Foreman Magrok , showing both strength and honor. Progress: Why don't you go show Foreman Magrok the true strength of your Horde?", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 163489, ["x"] = 0.45, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 241, ["npcID"] = 163489, ["x"] = 0.45, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 9, ["flags"] = 0 } } },
[53899] = { ["id"] = 53899, ["name"] = "On the Outskirts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "If things are settled for the Commander, you should check in on Nisha . I'm sure she could use your help.", ["objectivesText"] = "Find Nisha on the southern coast of Zuldazar.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 146261, ["x"] = 0.49, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 85, 862 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 11, ["flags"] = 0 } } },
[53900] = { ["id"] = 53900, ["name"] = "We'll Use Their Weapons", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "We're going to need special weapons to take down Tidecaller Nezara. Good thing it looks like the naga have plenty. We'll use their weapons against them. You and I know a thing or two about that. Grab an assortment. We'll need more than one.", ["objectivesText"] = "Collect 10 Nazeshi Weaponry from forces within Dreadpearl Shallows. Progress: You got those weapons?", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 171968, 173727, 174066 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 13, ["flags"] = 0 } } },
[53901] = { ["id"] = 53901, ["name"] = "Explosions Always Work", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "The area surrounding Tidecaller Nezara is heavily guarded, so I'll need you to create a distraction. Take these explosives. Plant them on the naga's harpoon launchers. Once they've been detonated, the blast should be more than enough to send the guards running!", ["objectivesText"] = "Place Volatile Explosives on naga Harpoon Launchers, and then detonate them to create a distraction. Progress: A fiery distraction is just what we need!", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 12, ["flags"] = 0 } } },
[53902] = { ["id"] = 53902, ["name"] = "Taking Out the Tidecaller", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Nezara's shield might be down, but that doesn't mean she's defenseless. There's a brute by her side that may cause trouble. I'll take a stab at him so you can take down the Tidecaller.", ["objectivesText"] = "Kill Tidecaller Nezara .", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 15, ["flags"] = 0 } } },
[53903] = { ["id"] = 53903, ["name"] = "Meet with Meerah", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "It appears we're making good progress. Would you meet up with Meerah ? I want to be sure she's found her way to the vintner in Suramar.", ["objectivesText"] = "Find Meerah within Suramar's Twilight Vineyards.", ["rewardGold"] = 34100, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 146261, ["x"] = 0.49, ["y"] = 0.735 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 146264, ["x"] = 0.59, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.735 }, ["mapCandidates"] = { ["npc"] = { 85, 680 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 17, ["flags"] = 0 } } },
[53904] = { ["id"] = 53904, ["name"] = "The Vintner's Assistants", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Vintner Iltheux oversees all arcwine production for the Horde. He's used to making wine himself, but the Horde sent in help to speed up the process. It's had the opposite effect. We need to get to the bottom of this. How about you tour the vineyards and see how things are running? I have a few more questions for the vintner.", ["objectivesText"] = "Speak to Micah Broadhoof , Boss Mida , and Nomi . Progress: Have you had a chance to see how things are running?", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 146264, ["x"] = 0.59, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 146264, ["x"] = 0.59, ["y"] = 0.55 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 18, ["flags"] = 0 } } },
[53905] = { ["id"] = 53905, ["name"] = "Playing to Their Strengths", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Iltheux isn't properly utilizing the help he's been given. Let's fix that. Assign new roles to the workers, ones more suited to their strengths. If you need suggestions, I'm happy to help.", ["objectivesText"] = "Assign new roles to Micah Broadhoof , Boss Mida , and Nomi .", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 146264, ["x"] = 0.59, ["y"] = 0.55 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 157668, ["x"] = 0.588, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.55 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 19, ["flags"] = 0 } } },
[53906] = { ["id"] = 53906, ["name"] = "Fermented for the Horde", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Vintner Iltheux's recipe doesn't need much improvement. Some unique ingredients and slight modifications to the winemaking process is all that's needed. I'm thinking adding fermented firebloom should do the trick. Then, filter it though a special cloth made from silkwing fibers . There are plenty of silkwings roaming the vineyard, and I have no doubt that Boss Mida can acquire the flowers, for a price.", ["objectivesText"] = "Collect the needed ingredients to create a wine worthy of the Horde. Progress: Together, we will make a wine worthy of the Horde.", ["rewardGold"] = 387250, ["rewardXP"] = 5465, ["rewardItems"] = { 165012, 165013, 173727, 174066 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 146301, ["x"] = 0.606, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 146301, ["x"] = 0.606, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 21, ["flags"] = 0 } } },
[53907] = { ["id"] = 53907, ["name"] = "Sip and Savor", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "I think we're making wine, $p! Let's see if the vintner approves of our vintage. Take a sample to Iltheux and see what he thinks.", ["objectivesText"] = "Deliver a sample of Nomi's Wine to Vintner Iltheux and gain his approval. Progress: I hope he likes the wine.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["rewardItems"] = { 165014, 173727, 174066 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 146301, ["x"] = 0.606, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 157668, ["x"] = 0.588, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 22, ["flags"] = 0 } } },
[53908] = { ["id"] = 53908, ["name"] = "Awaiting Our Arrival", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Let's head back to Orgrimmar. I'm sure Kiro's expecting us. We really shouldn't make him wait.", ["objectivesText"] = "Return to Grommash Hold within Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 157668, ["x"] = 0.588, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 145424, ["x"] = 0.485, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 85, 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 23, ["flags"] = 0 } } },
[53909] = { ["id"] = 53909, ["name"] = "Besieged Allies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "Seawalls can be rebuilt, but lives are lost for good. We need to secure the rest of the people here first. The Outriggers have been known as some of the fiercest hunters in these waters. Find their leader, Rosaline Madison , and enlist her aid in liberating Anglepoint. Together, clear the north shore of the Horde, save anyone in danger, and rally the dock workers. You handle the north shore, <name>. I will handle the south. We'll meet in the middle and crush the Horde between us.", ["objectivesText"] = "Find Rosaline Madison .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.3024 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53910] = { ["id"] = 53910, ["name"] = "Repel the Horde!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "The Horde has overrun Anglepoint, killing my people and destroying their livelihoods. Its raiders have come to Kul Tiras with killing on their minds. I cannot allow that to happen. Slay any Horde Axe Throwers or Berserkers you see on the north shore. I will do the same on the south. Together we will stop this invasion.", ["objectivesText"] = "Defeat Horde Axe Throwers or Berserkers on the north shore of Anglepoint Wharf.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.3024 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 4, ["flags"] = 0 } } },
[53912] = { ["id"] = 53912, ["name"] = "The Hunt Never Ends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "We have our victory, but we must move quickly to take the remaining Azerite from the estate. Our forces should already be moving the Azerite from the manor into our gyrocopter support. Let us move and ensure we get every ounce of Azerite away from the Alliance.", ["objectivesText"] = "Travel to the Norwington manor.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.5055, ["y"] = 0.2695 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53913] = { ["id"] = 53913, ["name"] = "With Honor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "The Alliance and Kul Tiran forces are in disarray. I can hear the Azerite tank powering up. Lieutenant Cole intends to fight us... now that his forces are destroyed. Let me know when you are ready to fight. The three of us shall destroy this tank while our warriors watch on!", ["objectivesText"] = "Defeat Lieutenant Cole . Progress: Are you ready?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 114687, 114688, 114689, 114690, 114691, 114692, 114693, 114694, 164987, 165702, 165734, 166309, 234744, 234745, 234746, 235262 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53914] = { ["id"] = 53914, ["name"] = "Murder at the Brawl'gar Arena", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53914 }, ["series"] = { 53915, 53917, 53918, 53920, 53921 }, ["description"] = "The Brawl'gar quartermaster lies dead in front of you. He was murdered in broad daylight! He must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights. Perhaps there are some clues nearby as to who might have killed him.", ["objectivesText"] = "Investigate the scene of the crime.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53915] = { ["id"] = 53915, ["name"] = "Put Up Your Dukes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53915 }, ["series"] = { 53914, 53917, 53918, 53920, 53921 }, ["description"] = "You know what? <The commander puts his notebook away.> I COULD use a good <class> on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get. But first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?", ["objectivesText"] = "Win any 3 fights in the Brawl'gar Arena.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53916] = { ["id"] = 53916, ["name"] = "Outrigger Outfitters", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "My people met the Horde head on when they arrived, but we've been scattered over the wharf. The Horde has been relentless. We haven't been able to form a solid resistance force using just our fists as weapons. But now the Lord Admiral is here with the champion of the Alliance. That's just the spark we need to rise up and kick these sorry mongrels out of our lands. If you can get my men some weapons, they'll join the fight! Find those weapons and meet me back here. I'm working on a plan.", ["objectivesText"] = "Recover 10 Outrigger Weapons . Progress: For Kul Tiras! For the Lord Admiral!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53917] = { ["id"] = 53917, ["name"] = "Undercover Agent: Sharisanda", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53917 }, ["series"] = { 53914, 53915, 53918, 53920, 53921 }, ["description"] = "Pit Boss Buxdoggle is one of our primary suspects in this case. Buxdoggle is an infamously aggressive speculator, and has a list of debts a mile long. He may be in need of money, which is consistent with the evidence you found earlier. Sharisanda has taken point on the case. I'd like you to assist her. I think you'll work well together.", ["objectivesText"] = "Report to Sharisanda in the Brawl'gar Arena.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53918] = { ["id"] = 53918, ["name"] = "The Financial Participation Incentive", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53918 }, ["series"] = { 53914, 53915, 53917, 53920, 53921 }, ["description"] = "I see Buxdoggle running some sort of game over dere. Getting people to guess de fight's winner in exchange for Brawler's Gold. See if you can figure out how his game works. If you win enough money from him, he might start talking...", ["objectivesText"] = "Win 100 Brawler's Gold from Pit Boss Buxdoggle 's guessing game. If the game is not currently active, anyone can activate it by purchasing a High Roller's Contract from Tiana Nevermorn. Progress: Lookin' to make some gold, bub?", ["rewardGold"] = 315900, ["rewardXP"] = 11765, ["rewardItems"] = { 142318, 143762, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53919] = { ["id"] = 53919, ["name"] = "Shots Fired", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "Horde invaders keep sailing in through the seagate, but we have a nasty surprise for them! The Outriggers are good at fighting monsters of any sort, the Horde included. We'll keep them off you while you take out their boats. Send 'em to the bottom of the harbor! For Kul Tiras! For the Lord Admiral!", ["objectivesText"] = "Destroy Horde Motorboats. Progress: That will hold the Horde for now.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 11, ["flags"] = 0 } } },
[53920] = { ["id"] = 53920, ["name"] = "A Favor for Your Ol' Pal Buxdoggle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53920 }, ["series"] = { 53914, 53915, 53917, 53918, 53921 }, ["description"] = "Hey, listen, I was thinkin' about somethin'... You know how you won all that money from me? Well, funny story, that may have been slightly more money than I actually have, and now some very powerful people want to break my elbows and my knees. I can't pay 'em! I'm broke! Heh heh! All I need to get out of this hole is for you to lose your next fight. Flop like a fish. Please.", ["objectivesText"] = "Lose a fight in Brawl'gar Arena. Progress: Please, ya gotta help me! They said they're gonna break my money bone! I don't even know where that is!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53921] = { ["id"] = 53921, ["name"] = "The Pit Boss's Debts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53921 }, ["series"] = { 53914, 53915, 53917, 53918, 53920 }, ["description"] = "I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money! Only one person's won more gold from me than you have, and his name's Lord Sylysthrel. Real skeezy guy. I think he was cheating. Sure would be nice if I could get that gold back...", ["objectivesText"] = "Obtain a Huge Pile of Legitimately-Earned Brawler's Gold from Lord Sylysthrel. You can challenge Lord Sylysthrel by purchasing his Challenge Card from Card Trader Ami. Progress: Once I get back the gold I lost, then I can REALLY start gambling!", ["rewardGold"] = 315900, ["rewardXP"] = 11765, ["rewardItems"] = { 164935, 164939, 164941, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53922] = { ["id"] = 53922, ["name"] = "Evidence Packet: Pit Boss Buxdoggle", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53922 }, ["series"] = { 53923 }, ["description"] = "I heard everything. That goblin sure does talk loudly about his crimes and debts, doesn't he? It sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Ravenhide to review. Good job out dere.", ["objectivesText"] = "Bring the Evidence Packet to Commander Arlu Ravenhide . Progress: Find anything on Buxdoggle?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 164962, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53923] = { ["id"] = 53923, ["name"] = "Undercover Agent: Stone Guard Mollivox", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53923 }, ["series"] = { 53922 }, ["description"] = "I believe you've met one of my other agents: Stone Guard Mollivox . She's investigating our second suspect: Shadowmaster Skrizzik. You'll find Mollivox near the arena's entrance.", ["objectivesText"] = "Speak with Stone Guard Mollivox at the Brawl'gar Arena.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53924] = { ["id"] = 53924, ["name"] = "Soul Splinters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53924 }, ["series"] = { 53925 }, ["description"] = "<Skrizzik mumbles to himself.> Oh dear, oh dear... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses... <He notices you.> Oh! Hello there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!", ["objectivesText"] = "Search inside Brawler's Purses for something \"soul\"-related. Brawler's Purses are awarded to victors in the Brawl'gar Arena. Some types of purses may be more lucrative than others. Progress: Oh dear, oh dear... must not let it get too hungry...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 92718, 164928, 164931, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53925] = { ["id"] = 53925, ["name"] = "Super Soul Splinters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53925 }, ["series"] = { 53924 }, ["description"] = "<Skrizzik mutters to himself again:> Will these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Orgrimmar. Oh dear, oh dear... <He notices you lingering.> Oh! The <race> is still here! Heh heh. Never mind me! Nothing evil going on here!!", ["objectivesText"] = "Obtain 3 Super Soul Splinters from Rumbler's Purses, which are rewarded from winning rumbles. Rumbles are large group fights that pit all players in the Brawl'gar Arena queue against a challenging enemy. Anyone can start a rumble by purchasing a Rumble Card from Tiana Nevermorn. Progress: <Skrizzik looks around the arena in a panic.> Where can I find more souls? Maybe the quartermaster sells some? Oh, right, he's dead. Hmm...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 164929, 164931, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53926] = { ["id"] = 53926, ["name"] = "Cause for Concern", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53926 }, ["series"] = { 53927, 53928, 53929, 53930 }, ["description"] = "Shadowmaster Skrizzik's behavior was unusual. His repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation. You should report back to Stone Guard Mollivox .", ["objectivesText"] = "Report to Stone Guard Mollivox .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53927] = { ["id"] = 53927, ["name"] = "The Precious 13-Tooth Gogglegear", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53927 }, ["series"] = { 53926, 53928, 53929, 53930 }, ["description"] = "We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes. That's right, I'm talking about goggles. I already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Ami has their challenge card.", ["objectivesText"] = "Obtain a 13-Tooth Gogglegear from G.G. Engineering. You can purchase their challenge card from Card Trader Ami. Progress: Are you ready to goggle up?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 94178, 164937, 164938, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53928] = { ["id"] = 53928, ["name"] = "The Mollivox Goggle Experiment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53928 }, ["series"] = { 53926, 53927, 53929, 53930 }, ["description"] = "Okay, before we start, I've got a few rules: First, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them. Second rule: if you feel something starting to explode, try to blink real hard. Lastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence. Alright, go get in that arena and try them out!", ["objectivesText"] = "Put on Mollivox's Goggles while fighting in the Brawl'gar Arena and look for evidence against Shadowmaster Skrizzik.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 164943, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53929] = { ["id"] = 53929, ["name"] = "Evidence Packet: Shadowmaster Skrizzik", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53929 }, ["series"] = { 53926, 53927, 53928, 53930 }, ["description"] = "Sounds like we've found our perp, <name>. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier. Bring this packet to Arlu, and we can bring him in. Good work out there!", ["objectivesText"] = "Bring the Evidence Packet to Commander Arlu Ravenhide . Progress: Any news on Skrizzik?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 164963, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53930] = { ["id"] = 53930, ["name"] = "Undercover Agent: Nugg Lumbo", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53930 }, ["series"] = { 53926, 53927, 53928, 53929 }, ["description"] = "I've got one more suspect I'm investigating: Libbiara Blightrunner. She's a wealthy blood elf death knight socialite who spends most of her time spectating the arena from the zeppelin up above. I've got my best agent on the case: Nugg Lumbo . Check in with him to see how his report is coming along.", ["objectivesText"] = "Report to Nugg Lumbo aboard the Skybag, the zeppelin above Brawl'gar Arena. The Skybag teleporter is located just outside of the Brawl'gar Arena bar. To use the teleporter, you must either be Rank 6 in Brawl'gar Arena, or someone must purchase a Zeppelin Rental Form from Tiana Nevermorn.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53931] = { ["id"] = 53931, ["name"] = "Flaunt It If You Got It", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53931 }, ["series"] = { 53952 }, ["description"] = "Sigh... so dull... Oh, it's you! <name>, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately. Let's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns off the boat?", ["objectivesText"] = "Drink a bottle of Moneybrau, purchase a round of drinks at the bar in Brawl'gar Arena, and hit a fighting player with an Amberseed Bun while standing on the deck of the Skybag. Progress: <The death knight socialite sighs.>", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 98121, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53932] = { ["id"] = 53932, ["name"] = "Evidence Packet: Libbiara Blightrunner", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53932 }, ["series"] = { 53933, 53934, 53935 }, ["description"] = "Nugg got what Nugg need. Give stupid blood elf one drink and she start getting all self-incriminatey. You bring packet to Commander. Nugg gonna buy some expensive snacks.", ["objectivesText"] = "Bring the Evidence Packet to Commander Arlu Ravenhide . Provided item:", ["rewardGold"] = 331700, ["rewardXP"] = 11765, ["rewardItems"] = { 164964, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53933] = { ["id"] = 53933, ["name"] = "The Brawl'gar Trial", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53933 }, ["series"] = { 53932, 53934, 53935 }, ["description"] = "I've issued three warrants. Nugg, Mollivox, and Sharisanda are apprehending the suspects as we speak. It's time to go to court. You may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.", ["objectivesText"] = "Reach a verdict in the Brawl'gar Trial.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53934] = { ["id"] = 53934, ["name"] = "A Clue from Area 52", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["mapID"] = 109, ["storyline"] = { 53934 }, ["series"] = { 53932, 53933, 53935 }, ["description"] = "We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in Brawl'gar\". They don't say more than that. I'm tied to my paperwork here. Go check out this lead and see if anything turns up.", ["objectivesText"] = "Investigate Area 52 in Netherstorm for a sign of the letter's writer.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 30542, 30544, 166724 }, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 149808, ["x"] = 0.312, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53935] = { ["id"] = 53935, ["name"] = "Solving the Mystery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 53935 }, ["series"] = { 53932, 53933, 53934 }, ["description"] = "<Bazzelflange produces a challenge card from her pocket.> I grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!", ["objectivesText"] = "Bring the Mysterious Challenge Card to Brawl'gar Arena to confront Boss Bazzelflange 's captor.", ["rewardGold"] = 1366400, ["rewardXP"] = 23530, ["rewardItems"] = { 164936, 164942, 166724 }, ["starts"] = { { ["mapID"] = 109, ["npcID"] = 149808, ["x"] = 0.312, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard" },
[53936] = { ["id"] = 53936, ["name"] = "Stopping the Sappers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "The ice should keep the Horde out while we handle the sapper teams gathered on the beach. I'm going to keep those Horde galleons busy. I need you to handle whoever is in charge and bring all the Azerite bombs you find back to me. Then we'll handle disposing of their weapons.", ["objectivesText"] = "Kill Nebbik Megafuel , collect Azerite bombs, and bring them to Jaina on top of the seagate. Progress: Were you able to recover the bombs?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.3024 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 12, ["flags"] = 0 } } },
[53937] = { ["id"] = 53937, ["name"] = "The Ub3r-Spanner", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53783, 53802, 53806, 53833, 53848, 53937, 54930, 55031 }, ["description"] = "It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad! At least we can still decode the Ub3r-Spanner schematic. Here, hand me that schematic and his decoder and I'll get this whipped up in just a second.", ["objectivesText"] = "Wait for Shuga Blastcaps to decode the schematic.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164740 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 131840, ["x"] = 0.45, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 131840, ["x"] = 0.45, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53938] = { ["id"] = 53938, ["name"] = "A Friend in Needle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53938, 53940, 53962, 55188 }, ["description"] = "You can see me? Oh, thank goodness! I thought I was lost in the folds of time...again! But for one to see through the folds of time's fabric... you must be a very talented tailor, indeed. Would you bring me some cloth, then, tailor? I believe I'll be able to place just when I am with your help and right myself.", ["objectivesText"] = "Collect 5 Tidespray Linen and 5 Deep Sea Satin . Progress: When in Azeroth am I...?", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["rewardItems"] = { 152576, 152577 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 145022, ["x"] = 0.765, ["y"] = 0.116 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 145022, ["x"] = 0.765, ["y"] = 0.116 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.116 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 905, ["name"] = "8.1.5 Tailoring - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53939] = { ["id"] = 53939, ["name"] = "Breaching Boralus", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 862, ["storyline"] = { 53939 }, ["description"] = "Finally! There's no place on Kul Tiras with a stronger Alliance presence. We must be bold and unrelenting if we're going to drive them out here. Lok-tar ogar!", ["objectivesText"] = "Lead the Horde assault into Tiragarde Sound. Progress: What are you doing here? The Horde needs you in Tiragarde Sound!", ["rewardXP"] = 2125, ["rewardItems"] = { 165871, 166792 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135447, ["x"] = 0.58, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8567 } }, ["questType"] = "standard" },
[53940] = { ["id"] = 53940, ["name"] = "A Stitch in Time", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 115, ["storyline"] = { 53938, 53940, 53962, 55188 }, ["series"] = { 55188 }, ["description"] = "Hm...I don't know that I've ever been to this time, before. I suppose I should explain myself. My name is Delormi, and I'm the last remaining member of the Synchronous Tailors . We make sure the fabric of time stays, well, mended. But I've found a number of new tears cropping up. In fact, I believe that's why I've arrived here in this time. Perhaps you could assist me in tracking them down and repairing them?", ["objectivesText"] = "Assist Delormi in repairing the Tears in Time. Progress: Something strange is happening. These tears have become too frequent as of late.", ["rewardGold"] = 58500, ["rewardXP"] = 1705, ["rewardItems"] = { 167231 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 905, ["name"] = "8.1.5 Tailoring - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53941] = { ["id"] = 53941, ["name"] = "A Mech for a Goblin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "Gallywix has a plan to deal with the Alliance and has requested your help. It involves the Azerite you reclaimed. Speak with him down at Bilgewater Bonanza, and do whatever you can to help him... when it comes to the interest of the Horde. Oh, and make sure Gallywix stays alive. The Alliance already tried to kill him.", ["objectivesText"] = "Meet Gallywix at Bilgewater Bonanza.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 145751, ["x"] = 0.362, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53942] = { ["id"] = 53942, ["name"] = "The Right Mech for the Job", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "Okay, <name>, we're good to go. The G.M.O.D has plenty of Azerite to cause some trouble! We gotta head to my, er, OUR base in Drustvar. Mekkatorque, that freakin' king of the gnomes, is attacking our Azerite supply! After we take care of the base, we're gonna take care of him! You get what I'm sayin'?", ["objectivesText"] = "Fly in the G.M.O.D to Drustvar and defend Krazzlefrazz Outpost.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 145751, ["x"] = 0.362, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 145786, ["x"] = 0.372, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 862, 896 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53943] = { ["id"] = 53943, ["name"] = "Modular Construction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 53943 }, ["description"] = "The Abandoned Junkheap is home to some seriously deadly gnomish constructs. These constructs contain Mecha-Cores which could come in handy for crafting the Ub3r-Spanner. Legend has it that it could forge creations unlike anything we've ever seen! You look like the adventurous type, <name>. Can you go scrap up some mechs? Don't forget your Arclight Spanner!", ["objectivesText"] = "Kill mechanical constructs in the Abandoned Junkheap and salvage 8 Mecha-Cores with an Arclight Spanner.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164768 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53945] = { ["id"] = 53945, ["name"] = "Naga Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 942, ["storyline"] = { 53945 }, ["objectivesText"] = "Repel the naga invaders Rescue prisoners Banners removed Supplies Destroyed", ["rewardXP"] = 2125, ["rewardItems"] = { 165605, 168003, 168123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Repel the naga invaders", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Rescue prisoners", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145214, ["orderIndex"] = 1 }, { ["text"] = "Banners removed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145856, ["orderIndex"] = 2 }, { ["text"] = "Supplies Destroyed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145855, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[53947] = { ["id"] = 53947, ["name"] = "In the Dunes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 864, ["storyline"] = { 53802, 53806, 53848, 53947, 53948, 53949, 54930, 55028 }, ["description"] = "This schematic you found is encrypted. My tools are no good on it, not without risking the integrity of the data. However, I do know a guy who can definitely crack this cookie: Mr. Dataguru Gryzix . If I remember correctly, he's been vacationing on a beach in Vol'dun since the war broke out. Something about not getting the recognition he deserves. Anyways, I am sure you can convince him to help you.", ["objectivesText"] = "Find Dataguru Gryzix at The Forgotten Marsh in Vol'dun. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 164740, 164919, 253179, 253700 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53948] = { ["id"] = 53948, ["name"] = "Vengeful Venture", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 1161, ["storyline"] = { 53802, 53806, 53848, 53947, 53948, 53949, 54930, 55028 }, ["description"] = "<You pick up the note and deduce that the Venture Co. are the killers of Dataguru Gryzix. You search his corpse, and find that his decoder and the Ub3r-Spanner schematic have been stolen. You need to retrieve his decoder and the schematic and bring them back to Layla Evenkeel to have any hope of crafting the Ub3r-Spanner. That mech you have following you should prove itself useful.>", ["objectivesText"] = "Locate the Venture Co. camp, then retrieve Gryzix's Decoder and the Encrypted Ub3r-Spanner Schematic . Progress: What's up, <name>? Did Gryzix handle that schematic for you?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164740, 164773, 164919, 166886 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 6, ["flags"] = 0 } } },
[53949] = { ["id"] = 53949, ["name"] = "The Ub3r-Spanner", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53802, 53806, 53848, 53947, 53948, 53949, 54930, 55028 }, ["description"] = "It's a shame that Gryzix had to die. Those Venture Co. make all of us enterprising types look bad! At least we can still decode the Ub3r-Spanner schematic. Here, hand me that recipe and his decoder and I'll get this whipped up in just a second.", ["objectivesText"] = "Wait for Layla Evenkeel to decode the schematic.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164740 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53950] = { ["id"] = 53950, ["name"] = "Explosive Relief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53950 }, ["objectivesText"] = "Alliance soldiers slain", ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Alliance soldiers slain", ["amount"] = 10, ["type"] = 0, ["objectID"] = 144959, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 259, ["db2QuestInfoName"] = "Faction Assault World Quest" },
[53951] = { ["id"] = 53951, ["name"] = "Explosive Relief", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53951 }, ["objectivesText"] = "Horde soldiers slain", ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Horde soldiers slain", ["amount"] = 10, ["type"] = 0, ["objectID"] = 144958, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 259, ["db2QuestInfoName"] = "Faction Assault World Quest" },
[53952] = { ["id"] = 53952, ["name"] = "Simply Dying of Boredom", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53952 }, ["series"] = { 53931 }, ["description"] = "Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Boss Bazzelflange can be so stingy with her invitations, can't she? I've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house near Grommash Hold...", ["objectivesText"] = "Use the Brawl'gar Arena Sign in Orgrimmar's Valley of Strength.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardItems"] = { 164947, 166724 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53953] = { ["id"] = 53953, ["name"] = "Brawl'gar Awaits!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6298, ["storyline"] = { 53953 }, ["description"] = "Tired of standing around in the boring old Valley of Strength? Come on over to the Brawl'gar Arena, and fight for the amusement of others! You might win, or you might get killed, but either way, you're going to have a great time. Grab an invitation and bring it to Skuglor , near the front door. Brawl'gar awaits!", ["objectivesText"] = "Bring an invitation to the Brawl'gar Arena. Provided item:", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 164949 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6298 } }, ["questType"] = "standard" },
[53955] = { ["id"] = 53955, ["name"] = "Warfront: The Battle for Darkshore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor. Prepare yourselves. Battle awaits!", ["objectivesText"] = "Defeat the Alliance at the Battle for Darkshore. Progress: We must do what we can to claim Darkshore for the Horde.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 166369, 166370 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 10, ["flags"] = 0 } } },
[53957] = { ["id"] = 53957, ["name"] = "Darkshore Recruits", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53957 }, ["description"] = "We've got a few recruits that can help us take back Darkshore! But first, we need our Ancient of War to be back up to good health. To help him, contribute resources to him and he'll perk right up! Once the Ancient of War is restored, talk to Jarod Shadowsong and recruit a troop. I'm sure they could learn a lot from fighting alongside you.", ["objectivesText"] = "Restore the Ancient of War, then speak with Jarod Shadowsong to recruit an ally. Progress: Did you get those recruits?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53959] = { ["id"] = 53959, ["name"] = "Armor for Armies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53959 }, ["description"] = "We need to make sure our soldiers have the best equipment possible in the battle against the Horde. Once the Hunter's Hall is constructed, speak with Cordressa Briarbow about how to improve the weapons and armor of our troops.", ["objectivesText"] = "Speak with Cordressa Briarbow to learn what the Hunter's Hall has to offer. Progress: I regret many things that took us to this moment, but we will do what needs to be done.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53960] = { ["id"] = 53960, ["name"] = "The Altar of Elders", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53960 }, ["description"] = "Now that contributions are in full swing, the Altar of Elders has been rebuilt. Go, speak with Moon Priestess Lasara to see what the Altar has to offer.", ["objectivesText"] = "Speak with Moon Priestess Lasara to learn what the Altar of Elders has to offer. Progress: Have you visited the Altar of Elders yet?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53961] = { ["id"] = 53961, ["name"] = "Glaiveworks For Me", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53961 }, ["description"] = "We've all been on edge since Teldrassil, but Erion took it hard. He jumped at the chance to help out. Why don't you talk to him and see what he's got going at the Glaiveworks?", ["objectivesText"] = "Speak with Erion to learn what the Glaiveworks has to offer. Progress: How may I help?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53962] = { ["id"] = 53962, ["name"] = "Cut from the Same Cloth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 115, ["storyline"] = { 53938, 53940, 53962, 55188 }, ["description"] = "My Infinite self was right--I can no longer mend time. Too many of my threads have been purged. I can feel no others. I'm alone now. And my thread is gone. But not you. Take this recipe. You've proven yourself a talented tailor in your own time, and a savior in so many more. The fabric of time needs your hands to mend it. I trust you with that responsibility. Talk to me when you're ready. I'll take you back to when this all began.", ["objectivesText"] = "Ask Timeweaver Delormi to return you to your time.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 115, ["questLines"] = { { ["id"] = 905, ["name"] = "8.1.5 Tailoring - Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53963] = { ["id"] = 53963, ["name"] = "Naga Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53963 }, ["objectivesText"] = "Repel the naga invaders Prisoners freed War supplies destroyed", ["rewardXP"] = 2125, ["rewardItems"] = { 165605, 168003, 168123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Repel the naga invaders", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Prisoners freed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145891, ["orderIndex"] = 1 }, { ["text"] = "War supplies destroyed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145875, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[53965] = { ["id"] = 53965, ["name"] = "Children's Week", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53965 }, ["description"] = "Thank you for offering your help with Children's Week, <name>. We have a little girl who is excited to explore Zandalar! Take dis whistle. With it, you will be able to call de child you have agreed to take care of dis week. It will serve no use after Children's Week ends. When you are ready, use de whistle and meet your new ward! She is a feisty one.", ["objectivesText"] = "Use the Zandalari Orphan Whistle to call for the ward that you will be looking after during Children's Week. Provided item:", ["rewardItems"] = { 23022, 116202, 164965, 167008, 167009, 167010, 167011 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 131346, ["x"] = 0.5396, ["y"] = 0.846 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.5396, ["y"] = 0.846 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[53966] = { ["id"] = 53966, ["name"] = "Loa of Winds", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53966 }, ["description"] = "I heard dat Pa'ku lives somewhere in Zuldazar. Her priests tell stories about her when dey come to de Hall of Castes. She's a pretty popular loa. I mean, she's in charge of de sky AND de sea! Dat's a lot of blue, and blue is my favorite color! Maybe I could be one of her followers?", ["objectivesText"] = "Take Azala to Pterror Rise in Zuldazar. Make sure to call for her if she is not present when you get there. Progress: Do you think dat I'll get wings if I follow Pa'ku?", ["rewardItems"] = { 23022, 116202, 164965, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53967] = { ["id"] = 53967, ["name"] = "The Frogmarsh", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53967 }, ["description"] = "De caretakers are always telling us stories in de Hall of Castes. Sometimes dey warn us about danger, sometimes dey're about de loa... dere's usually a point to dem. One time, dey told us about Krag'wa, and how blood trolls killed his followers, and how he hasn't been seen since. But I heard dat he's back! He's in Nazmir again, and he's plotting his revenge against de blood trolls. Can we go see him?", ["objectivesText"] = "Take Azala to Krag'wa's Burrow in the Frogmarsh in Nazmir. Make sure to call for her if she is not present when you get there. Progress: Where do loa go when dey don't have followers? I hope dey aren't too sad.", ["rewardItems"] = { 23022, 116202, 164965, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53968] = { ["id"] = 53968, ["name"] = "The Shifting Pack", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53968 }, ["description"] = "Dere's one loa I'm extra interested in seeing: Gonk! I've heard de priests say dat he's de most welcoming of de loa. He even lets his followers worship other loa as well! But de best thing about him is dat he and his followers can change into many forms. I want to do dat! Will you take me to meet him?", ["objectivesText"] = "Take Azala to the Lair of Gonk at the Garden of the Loa in Zuldazar. Make sure to call for her if she is not present when you get there. Progress: Gonk's followers can turn into lots of different things. I think dey're pretty great.", ["rewardItems"] = { 23022, 116202, 164965, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53969] = { ["id"] = 53969, ["name"] = "Hunting for Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53969 }, ["description"] = "I know dis trip is supposed to focus on de loa... But I want to see de island of gold! I heard stories of undead pirates and an island covered in gold coins and treasure! Can we go see it?! Pleeeease?", ["objectivesText"] = "Take Azala to The Golden Isle in Vol'dun. Make sure to call for her if she is not present when you get there. Progress: An island made entirely of gold? I gotta see it!", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 23022, 85500, 116202, 164965, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53970] = { ["id"] = 53970, ["name"] = "The Sethrak Queen", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53970 }, ["description"] = "De caretakers are always talking about how de sethrak attack caravans... but dey say dat de sethrak and de Zandalari used to be friends! I heard dat dere are some sethrak who still want to be friends, and dat dey have a loa who wants peace more dan anything! Can you take me to meet de sethrak and deir loa? I want to meet dem for myself!", ["objectivesText"] = "Take Azala to the Terrace of the Devoted in Vol'dun. Make sure to call for her if she is not present when you get there. Progress: Do you think de sethrak queen is pretty? Do you think she has shinies?", ["rewardItems"] = { 23022, 116202, 164965, 167008, 167009, 167010, 167011 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53971] = { ["id"] = 53971, ["name"] = "Return to the Hall of Castes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 53971 }, ["description"] = "I can't believe I got to visit so many places. I've never even left Zuldazar before! I may be casteless, but now dat I've met so many loa, maybe I can follow one and have a future off of de streets. But for now, we should go back to de Hall of Castes. De caretakers must be waiting for me.", ["objectivesText"] = "Take Azala back to the Hall of Castes in Zuldazar. Make sure to call for her if she is not present when you get there. Progress: Wait til de others hear about my trip!", ["rewardItems"] = { 23022, 116202, 164965, 167008, 167009, 167010, 167011, 241215 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[53973] = { ["id"] = 53973, ["name"] = "Ride Out to Meet Them", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "We must defend our warriors from the Alliance army while we recover this Azerite. Take the Azerite weapons you stole and load them onto one of these gyrocopters. Misha and I will ride out and fight the reinforcements from the ground, while you provide air support. We need to hold them off until our warriors can retreat with the Azerite.", ["objectivesText"] = "Ride the Goblin Gyrocopter and fend off the Alliance army.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.5055, ["y"] = 0.2695 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53974] = { ["id"] = 53974, ["name"] = "Druids of Gloomtide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53974 }, ["description"] = "The latent power at Gloomtide Strand presents us with an opportunity to harness great power. One of our allies, Edgard, has great knowledge into what this might mean for our efforts. Seek him out and discover the power of nature.", ["objectivesText"] = "Capture Gloomtide Strand, then speak with Edgard to learn what he has to offer. Progress: Discover anything?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53975] = { ["id"] = 53975, ["name"] = "Flying at Night", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53975 }, ["description"] = "Now that we control Ashwood Depot, it will be much more convenient to travel about the battlefield. I've drafted plans for a flight network. It's a rather brilliant plan, if I do say so myself. You don't seem busy. Take my notes and deliver them to our commander at once. Speak to Fidelio and he will provide you with a hippogryph.", ["objectivesText"] = "Deliver Evenshade's Note to your commander in Bashal'Aran.", ["rewardItems"] = { 164991 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53976] = { ["id"] = 53976, ["name"] = "Iron in Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53976 }, ["description"] = "This won't work at all! We need to gather iron if we want to make any kind of headway against the Horde. Go down to the ruins at Lornesta and grab that iron . We need it!", ["objectivesText"] = "Gather Iron from a nearby Ore Crate. Progress: We need to collect that iron !", ["rewardXP"] = 3410, ["rewardItems"] = { 165659 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53977] = { ["id"] = 53977, ["name"] = "The War Chest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 53977 }, ["description"] = "Welcome to the warfront, <name>! We finally get to see some action. Any resources we've collected will go to the War Chest. Once enough has been gathered there, you can grab it! Why don't you pay it a visit and see what you get?", ["objectivesText"] = "Collect resources from the War Chest in Bashal'Aran. Progress: Got any of those resources from the War Chest?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[53978] = { ["id"] = 53978, ["name"] = "Gunpowder Plots", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "Since the Lord Admiral iced all of their zeppelins, the Horde are rowing in through the seagate. The nice, narrow seagate entrance that makes for a great choke point. I'll have my people haul over a cannon and some ammunition. If you collect some gunpowder, we'll set up behind the gate where they won't expect the attack. We'll blast the Horde to the bottom of the harbor!", ["objectivesText"] = "Collect 6 Kegs of Gunpowder. Progress: Did you find enough gunpowder?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 8, ["flags"] = 0 } } },
[53979] = { ["id"] = 53979, ["name"] = "Naga Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53979 }, ["objectivesText"] = "Repel the naga invaders Captives freed Banners removed War Supplies destroyed", ["rewardXP"] = 2125, ["rewardItems"] = { 165605, 168003, 168123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Repel the naga invaders", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Captives freed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145950, ["orderIndex"] = 1 }, { ["text"] = "Banners removed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145974, ["orderIndex"] = 2 }, { ["text"] = "War Supplies destroyed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 145959, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[53981] = { ["id"] = 53981, ["name"] = "The Day is Won", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53851, 53852, 53856, 53879, 53880, 53912, 53913, 53973, 53981 }, ["description"] = "The majority of our warriors survived and we have the Alliance's Azerite and weapons. Be proud of yourself, <name>. You fought with honor today. Go and inform Nathanos of our victory here. The Azerite should reach them shortly.", ["objectivesText"] = "Return to Nathanos Blightcaller on the Banshee's Wail.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145422, ["x"] = 0.5055, ["y"] = 0.2695 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.5055, ["y"] = 0.2695 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 15 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 838, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 838, ["name"] = "Norwington Assault", ["orderIndex"] = 9, ["flags"] = 0 } } },
[53982] = { ["id"] = 53982, ["name"] = "Supplies From The Unshackled", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 53982 }, ["description"] = "Your aid has given us hope. Your courage has given us strength. You have given us an entirely new vision of our future, <name>. For that we will be forever grateful. I hope we can continue to repay you for all you have done!", ["objectivesText"] = "Speak with Atolia Seapearl in Newhome for your reward.", ["rewardItems"] = { 169940 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2374, ["threshold"] = 10000 } } } },
