[53986] = { ["id"] = 53986, ["name"] = "The Calm Before", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "A word, <name>. There was a raid on the Norwington Estate, where we were testing some new designs of Azerite systems. Lady Jaina asked SI:7 to look into the matter. I have the report here. I know the Proudmoore family wants a moment together before they're pulled apart again, but the war is still ongoing. You have been a friend to her family. Take the report to Jaina. I believe they went to pay respects at the family memorial.", ["objectivesText"] = "Take the SI:7 report to Lady Jaina Progress: The Horde cannot be allowed to think it can come to our lands without resistence.", ["rewardGold"] = 23400, ["rewardXP"] = 1705, ["rewardItems"] = { 158075, 164921, 164968, 166280, 166682, 197649, 197650, 197651, 197652 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53988] = { ["id"] = 53988, ["name"] = "Shores of Fate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "So be it. You are more trustworthy an ally than any army Wrynn would have sent. We will reclaim Darkshore together, but first we must find Tyrande. Without her at the front, our forces will crumble against the Horde. She left for the Zoram Strand with a small force not long ago. If we move now, we may be able to find her before the Horde does.", ["objectivesText"] = "Take the Stormwind portal to Darnassus and meet Maiev Shadowsong at the Zoram Strand in Ashenvale.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 18230, 113364, 165232, 165233, 165250 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 146050, ["x"] = 0.8632, ["y"] = 0.3516 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 146373, ["x"] = 0.306, ["y"] = 0.982 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8632, ["y"] = 0.3516 }, ["mapCandidates"] = { ["npc"] = { 62, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53989] = { ["id"] = 53989, ["name"] = "Hope", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 62, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "No... it is not possible. She would not have died like this! Search for signs of her departure along the strand. Personal effects. Weapons. Anything! Tyrande is still out there, <name>. We must not lose hope.", ["objectivesText"] = "Search for signs of Tyrande. Progress: Anything?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 11475, 13444, 13446, 28168, 28169, 28172, 28173, 28175, 57247, 59741, 59742, 59743, 59744, 59745, 59746, 131717, 140235, 140244, 155117, 155118, 155119, 155120, 155158, 158667, 159124, 159152, 159153, 159154, 159155, 165232, 165233, 165250, 166525, 168436, 168573, 175713, 175740, 177633, 177634, 177646, 177648, 177650, 177651, 177652, 179532, 179562, 181402, 181407, 181408, 181409, 181410, 181429, 181458, 181477, 181479, 181541, 183486, 184378, 184381, 184382, 184383, 184384, 184487, 184519, 194338, 194381, 194382, 194383, 206350, 206960, 208047, 208067, 209900, 210180, 210774, 210916, 211131, 211279, 219459, 219920, 237812, 237864, 237869, 237877, 237885, 242713, 246863, 246936, 249400, 251719, 251720, 251721, 251722, 251821, 253035, 253443, 254267, 254579, 258264, 260450, 260451, 263467, 265995 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 146374, ["x"] = 0.306, ["y"] = 0.982 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 146374, ["x"] = 0.306, ["y"] = 0.982 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.982 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 3, ["flags"] = 0 } } },
[53990] = { ["id"] = 53990, ["name"] = "In Darkest Night", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 62, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "<name>, I will not mince words. Tyrande foolishly risks her life with the ritual she intends to perform. If she falls, our entire war effort will fall with her. We must set off for Darkshore and come to her aid. Only then can we march forward and reclaim our homeland. We have lost Teldrassil. Fool or not, our people cannot afford to lose Tyrande as well.", ["objectivesText"] = "Find Tyrande in Darkshore and lend her aid.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 165232, 165233, 165250 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 146373, ["x"] = 0.306, ["y"] = 0.982 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 149612, ["x"] = 0.695, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.982 }, ["mapCandidates"] = { ["npc"] = { 62, 1161 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 5, ["flags"] = 0 } } },
[53992] = { ["id"] = 53992, ["name"] = "Warfront: The Battle for Darkshore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "We will not tolerate further Horde aggression in our territories. The night elves will not stand alone this day. Darkshore will be theirs once more. For the Alliance!", ["objectivesText"] = "Defeat the Horde at the Battle for Darkshore. Progress: Darkshore will be ours.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 158075, 166369, 166370 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 7, ["flags"] = 0 } } },
[53993] = { ["id"] = 53993, ["name"] = "A Voice on the Wind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53993, 54005 }, ["description"] = "<A distant, mysterious voice fills your mind.> My enchantments are not lost... Find me... Drustvar... Fallhaven...", ["objectivesText"] = "Seek out the source of the mysterious voice in Drustvar.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 152668, 152876, 152877, 164766, 168125, 168126, 168127 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 146053, ["x"] = 0.534, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 909, ["name"] = "8.1.5 Enchanting - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53994] = { ["id"] = 53994, ["name"] = "Naga Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 895, ["storyline"] = { 53994 }, ["objectivesText"] = "Repel the naga invaders Prisoners freed Banners removed War supplies destroyed", ["rewardXP"] = 2125, ["rewardItems"] = { 165605, 168003, 168123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8500 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Repel the naga invaders", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Prisoners freed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 146055, ["orderIndex"] = 1 }, { ["text"] = "Banners removed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 146056, ["orderIndex"] = 2 }, { ["text"] = "War supplies destroyed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 146057, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[53995] = { ["id"] = 53995, ["name"] = "The Tauren Tanner", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53995, 55216, 55221, 55222, 55223 }, ["description"] = "Hey, rich mon. One of ya Tauren stopped by and asked who was de best leatherworker I knew who doesn't mind gettin' their hands dirty. I give 'im ya name, and he asked for an introduction. Said dat he would be in de Bazaar, by de docks. He did not say what he needed ma best student for, but de way he was actin' makes me think it is somedin' big. Head on down to de docks and find dis Tauren. Show 'im what I taught ya. And focus! Needn't be havin' ya make me look bad!", ["objectivesText"] = "Meet the Tauren Leatherworker in the Port of Zandalar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122698, ["x"] = 0.44, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.44, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 908, ["name"] = "8.1.5 Leatherworking - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53996] = { ["id"] = 53996, ["name"] = "Pick Up Sticks", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53996, 53997, 53998, 53999, 54000, 54001, 54002 }, ["description"] = "In order for my enchantment to work, we'll need wood from these forests. When I was alive, I would wander these woods and tend to the trees. While those trees are long gone, perhaps their grandseeds have heard their stories and would be willing to help me. But don't cut down any of the trees! Please! There are loggers that cut and hew without care for the wilds. Take their hard work so that they will think twice before felling another tree. Bring me as much wood as you can muster.", ["objectivesText"] = "Collect 9 Bundles of Hard Wood Progress: I miss the voices of the old forest.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 152668, 152876, 152877, 164766, 164979, 168125, 168126, 168127 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 146053, ["x"] = 0.534, ["y"] = 0.402 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 146053, ["x"] = 0.534, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 911, ["name"] = "8.1.5 Enchanting - Alliance/Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[53997] = { ["id"] = 53997, ["name"] = "The Sixth Sense", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53996, 53997, 53998, 53999, 54000, 54001, 54002 }, ["description"] = "For my plan to work, we need to break the spell on my body that is anchoring my spirit to this place. However, my mortal remains are buried deep within this forest. There are wards within it that are designed to trap spirits who are still attached to the material world. Once my remains are cleansed, I will be able to move freely through the woods. Until then, I'll need you to disenchant the wards we come across. Speak to me when you are ready, and I will lead you to my grave.", ["objectivesText"] = "Escort Sef Iwen to her grave.", ["rewardGold"] = 68950, ["rewardXP"] = 1415, ["rewardItems"] = { 152668, 152876, 152877, 164766, 168125, 168126, 168127 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 146053, ["x"] = 0.534, ["y"] = 0.402 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 146091, ["x"] = 0.552, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 911, ["name"] = "8.1.5 Enchanting - Alliance/Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[53998] = { ["id"] = 53998, ["name"] = "Exhumed", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53996, 53997, 53998, 53999, 54000, 54001, 54002 }, ["description"] = "As I've said, I'm unable to interact with the material world. I am able to dominate a creature to control its body, but I find it deplorable. In essence, it is enslaving the poor creature. What I want is a body of my own. If you build and animate a golem, it would be devoid of intelligence. A shell. One that I could inhabit without issue. Doing so will require that my soul is not anchored to anything else in this world, so I need you to remove the spell binding my spirit to my physical remains.", ["objectivesText"] = "Cleanse Sef Iwen 's remains. Progress: Seeing my old self brings back memories.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 152668, 152876, 152877, 164766, 168125, 168126, 168127 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 146091, ["x"] = 0.552, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 146091, ["x"] = 0.552, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 911, ["name"] = "8.1.5 Enchanting - Alliance/Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[53999] = { ["id"] = 53999, ["name"] = "The Threads That Bind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53996, 53997, 53998, 53999, 54000, 54001, 54002 }, ["description"] = "Our destination is near Gol Koval, but there is something else you could pick up along the way. I don't want to ask because I hate them, but you cannot dispute the resilience of that horrible webbing that they manage to get everywhere. <Sef grimaces at the thought.> There are spiders to the southeast. As a guardian of nature, I don't want to say kill them, but if you could... 'obtain' some fresh silk from their bodies, we could use it to bind the limbs of the golem together.", ["objectivesText"] = "Collect 55 Durable Spider Silk . Progress: Did you get the silk?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 152668, 152876, 152877, 164766, 164985, 168125, 168126, 168127 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 146091, ["x"] = 0.552, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 146093, ["x"] = 0.63, ["y"] = 0.595 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 911, ["name"] = "8.1.5 Enchanting - Alliance/Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54000] = { ["id"] = 54000, ["name"] = "The Beat Goes On", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53996, 53997, 53998, 53999, 54000, 54001, 54002 }, ["description"] = "We have most of the materials we need, but we require one final item. A heart. Don't worry. I don't mean one of flesh, but of stone; to bind the materials of the body into a single form. Find a smooth stone, and enchant it to hold a life force. It will require some reagents, but I would expect a powerful enchanter such as yourself to have some on hand or know where to find them. Once that's done, it will need to be powered. The souls animating the elementals and undead here should do the trick.", ["objectivesText"] = "Create a runic power core and charge it from the corpses of Awoken Guardians and Vengeful Bones.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 152668, 152876, 152877, 164766, 165022, 165023, 168125, 168126, 168127 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 146093, ["x"] = 0.63, ["y"] = 0.595 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 146094, ["x"] = 0.588, ["y"] = 0.628 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.595 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 911, ["name"] = "8.1.5 Enchanting - Alliance/Horde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54001] = { ["id"] = 54001, ["name"] = "We're Going In", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53996, 53997, 53998, 53999, 54000, 54001, 54002 }, ["description"] = "This used to be a Drust shrine. There is a series of sigils that, once invoked, will allow us to teleport to my old sanctum. <Sef looks around somewhat confused and clears her throat.> It has been centuries since I've been here, I'm having a bit of trouble remembering the order in which the sigils need to be activated to open the portal. I hope you're feeling adventurous. Oh, and be cautious. I enchanted the runes to keep would be intruders out by force.", ["objectivesText"] = "Activate the teleportation runes to enter Sef's Retreat.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["rewardItems"] = { 3316, 37223, 37391, 37427, 37507, 61517, 61518, 61519, 61520, 61521, 61522, 63151, 63152, 63153, 63154, 63155, 84281, 84282, 84283, 84284, 84285, 121440, 121441, 121442, 121443, 131530, 131531, 132936, 141386, 152668, 152876, 152877, 164766, 168125, 168126, 168127, 169903, 175713, 175728, 175740, 179562, 181398, 181411, 181412, 181413, 181457, 181458, 181459, 181477, 181479, 181541, 182559, 184378, 184381, 184382, 184383, 184384, 184519, 211279, 237812, 246458, 246812, 248583, 251783, 251784, 251786, 251788, 251791, 259085, 259896, 269010, 274069, 274070, 274071 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 146094, ["x"] = 0.588, ["y"] = 0.628 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 152255, ["x"] = 0.578, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.628 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 911, ["name"] = "8.1.5 Enchanting - Alliance/Horde", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54002] = { ["id"] = 54002, ["name"] = "Putting It All Together", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53996, 53997, 53998, 53999, 54000, 54001, 54002 }, ["description"] = "Hmm... Everything seems untouched. We can begin construction of my new body over here. Afterwards, I'll teach you how to make my enchanting rod. <Sef smiles at you, beaming with joy.>", ["objectivesText"] = "Assemble the golem for Sef Iwen . Progress: This has been a long time coming.", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 55924, 55925, 55926, 55927, 55928, 55929, 152668, 152876, 152877, 164766, 168125, 168126, 168127, 180935, 181377, 181572, 181573, 181581, 181599, 181609, 181610, 181703, 181843, 181866, 182127, 182385, 182470, 182667, 183132, 183480, 183506, 184294, 184362, 184363, 184766, 184767, 184768, 184839 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 152255, ["x"] = 0.578, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 152255, ["x"] = 0.578, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 911, ["name"] = "8.1.5 Enchanting - Alliance/Horde", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54005] = { ["id"] = 54005, ["name"] = "What the Drust Knew", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 895, ["storyline"] = { 53993, 54005 }, ["description"] = "Ahoy, <name>! If you have a moment, I could use your assistance. I've recently received a large shipment of Drust relics that I've been processing. Most of them have been nothing out of the ordinary, but there is this one that is special. Just holding it makes my hair stand on end. With you being my best pupil, I was thinking that it would be fun if we disenchanted it together, to see how it was made. What do you say?", ["objectivesText"] = "Carefully remove the enchantment from the Ancient Drust relic to learn about its construction.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 152668, 152876, 152877, 164766, 168125, 168126, 168127 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 909, ["name"] = "8.1.5 Enchanting - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54006] = { ["id"] = 54006, ["name"] = "A New Hope", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "Darkshore belongs to our people once more, in no small part due to your efforts. And, while I disagree with her methods, we would not have succeeded without Tyrande as well. Differences aside, she is our leader--and an incarnation of the Night Warrior herself. She is about to begin. You may stand here beside me.", ["objectivesText"] = "Witness Tyrande's address to the kaldorei.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 166525, 219459, 258264 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 149418, ["x"] = 0.475, ["y"] = 0.342 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 147255, ["x"] = 0.475, ["y"] = 0.337 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54007] = { ["id"] = 54007, ["name"] = "Insurance Policy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "Mekkatorque called us idiots, can you believe that? Well, if I'm an idiot, then why did I buy an insurance policy on my mech, huh? I bet that radioactive dimwit doesn't have an insurance policy on HIS mech! We're gonna be outta here in no time. I just gotta give a quick call for roadside assistance to come out and fix this thing up. I need you to go hit the button for roadside assistance on my mech. Just, uh, don't hit the wrong one.", ["objectivesText"] = "Activate the roadside assistance button on the G.M.O.D. Progress: You gonna call these guys up or what?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54008] = { ["id"] = 54008, ["name"] = "Insurance Renewal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "You know, all I wanna do is blow up Mekkatorque and whatever airship he's ridin' in. Of course it ain't gonna be easy! I need you to go rescue my roadside assistance so they can fix this mech! They're probably in the Alliance camp near here. Meanwhile, I'm gonna cook us up a plan. We're gonna give Mekkatorque a real nice surprise! And by real nice surprise, I mean we're gonna blow him up. Oh, and also his airship.", ["objectivesText"] = "Rescue Gallywix's Roadside Assistance", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54009] = { ["id"] = 54009, ["name"] = "Killing on the Side", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "Those annoying Alliance nearby are definitely takin' orders from Mekkatorque. That means they gotta die! And any of their Kul Tiran friends, too. They gotta know the Horde is number one. And that you don't kidnap someone's roadside assistance!", ["objectivesText"] = "Kill 15 Alliance and Kul Tiran soldiers in Vigil Hill.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 8, ["flags"] = 0 } } },
