[54012] = { ["id"] = 54012, ["name"] = "Fortunate Souls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55481, 56063, 56429 }, ["description"] = "$p, I am glad to see that you survived the wreck. Many were not as fortunate... I am capable of stalling the enemy here for now, but this position is not defensible long term. We need to find somewhere safe for our forces. Once we have taken measure of the wounded we will push on. In the meantime, find as many survivors as you can. Nazjatar will claim no more Horde lives today!", ["objectivesText"] = "Rescue 7 captive soldiers in Spears of Azshara. Progress: Save as many as you can. We are sorely outnumbered here.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.396667, ["y"] = 0.775333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 886, ["questLineOrder"] = 23 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 886, ["name"] = "Azshara's Trap", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 4, ["flags"] = 0 } } },
