[54021] = { ["id"] = 54021, ["name"] = "The First Arcanist", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55481, 56063, 56429 }, ["description"] = "Our situation is dire, $p. The Horde fleet was decimated by the attack on Dazar'alor. This naga trap has claimed much of what we had left. Survivors report seeing the naga taking captives. Thalyssra has gone on ahead to see what she can do to help them. I will finish up here while you aid the First Arcanist's efforts. My rangers will provide what little aid they can.", ["objectivesText"] = "Meet with First Arcanist Thalyssra in Nazjatar .", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150207, ["x"] = 0.3885, ["y"] = 0.7865 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.3885, ["y"] = 0.7865 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 886, ["questLineOrder"] = 23 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 886, ["name"] = "Azshara's Trap", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54022] = { ["id"] = 54022, ["name"] = "Mekkatorque's Battle Plans", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "<You find part of plans that indicate where Mekkatorque will be in Tiragarde Sound, along with his airship. If you could find the other half of these plans, you would be able to launch an ambush against the gnomish king.>", ["objectivesText"] = "Recover Mekkatorque's Battle Plans Progress: What're you lookin' into?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 164989, 165702, 165734, 166309 }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 9, ["flags"] = 0 } }, ["startItems"] = { 164987 } },
[54026] = { ["id"] = 54026, ["name"] = "Job's Done", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 241, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "I'll stick around here a bit longer to ensure the peons get back to work. You should return to Orgrimmar and let Commander Dresh know that he does not need to fret about the outpost any longer.", ["objectivesText"] = "Return to Commander Dresh at Grommash Hold in Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 241, ["npcID"] = 163489, ["x"] = 0.45, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 145532, ["x"] = 0.484, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 241, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 85, 241 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 10, ["flags"] = 0 } } },
[54027] = { ["id"] = 54027, ["name"] = "Threat Contained", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "That should keep those naga down! You can have the honor of telling Bladeguard Sonji that the threat to Zuldazar's coast has been contained.", ["objectivesText"] = "Return to Bladeguard Sonji at Grommash Hold in Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 145533, ["x"] = 0.485, ["y"] = 0.7155 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.7155 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 16, ["flags"] = 0 } } },
[54028] = { ["id"] = 54028, ["name"] = "Mech versus Airship", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "We're all set to go, thanks to them battle plans ya found. Looks like Mekko ain't gonna be at his airship right now. Here's the plan. We're gonna go seriously mess up his ship, then Mekko is gonna swing by to try to save his friends. But instead, he's gonna find you and me standin' on the deck of his burnin' ship, waitin' to take him out! Get in to the mech, <name>, we're blowin' up an airship and a gnome!", ["objectivesText"] = "Ride the G.M.O.D to blow up an Alliance airship and confront Mekkatorque.", ["rewardGold"] = 137900, ["rewardXP"] = 8520, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 146073, ["x"] = 0.546, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 146623, ["x"] = 0.876, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 10, ["flags"] = 0 } } },
[54031] = { ["id"] = 54031, ["name"] = "Gaze of the Loa: Krag'wa", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "Hello again, small one. I see Talanji has chosen a worthy witness. I must test Talanji's willingness to sacrifice for her people. I will weigh her commitment to defending the weak. Many great rulers have failed this challenge and still gone on to make powerful monarchs. But the most beloved, those that find themselves surrounded by loyal followers, always understand the value of devotion to their people. You will help me with this trial. Speak to me when you are ready to begin.", ["objectivesText"] = "\"Witness\" Krag'wa's trial. Progress: It is my hope that Talanji will honor your faith in her this day.", ["rewardGold"] = 221280, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 146208, ["x"] = 0.443333, ["y"] = 0.148667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146208, ["x"] = 0.443333, ["y"] = 0.148667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.443333, ["y"] = 0.148667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 11, ["flags"] = 0 } } },
[54032] = { ["id"] = 54032, ["name"] = "Gaze of the Loa: Pa'ku", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "Two more loa have declared their intent to test Talanji. The next is Pa'ku . She awaits you both at the top of these steps. I need not warn you about her tempestuous nature, nor her love for watching others fall from great heights. Good luck, <name>.", ["objectivesText"] = "Complete Pa'ku 's trial. Progress: I am not yet satisfied, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 146214, ["x"] = 0.465, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146209, ["x"] = 0.438, ["y"] = 0.090667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.465, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 13, ["flags"] = 0 } } },
[54033] = { ["id"] = 54033, ["name"] = "Gaze of the Loa: Gonk", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "The Lord of the Pack has requested to be the next to speak to Talanji. He is just up the steps on the next terrace. I do not think he will require quite as much of you as I did, but I believe his words will be relevant to your purposes here. <Krag'wa winks one massive eye.> Do not think we are not aware of your intentions, <name>.", ["objectivesText"] = "Complete Gonk 's trial. Progress: Hello again, <name>.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 146208, ["x"] = 0.443333, ["y"] = 0.148667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146214, ["x"] = 0.465, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.443333, ["y"] = 0.148667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 12, ["flags"] = 0 } } },
[54034] = { ["id"] = 54034, ["name"] = "Gaze of the Loa: Bwonsamdi", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "< Pa'ku 's levity subsides.> Ordinarily the final trial would be given by Rezan. But the loa of kings is no more. It seems ol' Rastakhan picked a new favorite to take his place. < Pa'ku sneers.> Enjoy that. Bwonsamdi waits for you in the temple.", ["objectivesText"] = "Complete Bwonsamdi 's trial.", ["rewardGold"] = 140450, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 146209, ["x"] = 0.438, ["y"] = 0.090667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.090667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 14, ["flags"] = 0 } } },
[54036] = { ["id"] = 54036, ["name"] = "A Particular Process", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7637, ["mapID"] = 680, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "As you might have noticed, Vintner Iltheux is very particular about his wine making process, but his ancient recipe was crafted with only the Nightborne in mind. We need something different to please the diverse palates of the Horde! Talk to Nomi and see what he has in mind to spice things up.", ["objectivesText"] = "Speak to Nomi .", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 680, ["npcID"] = 157668, ["x"] = 0.588, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 680, ["npcID"] = 146301, ["x"] = 0.606, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 680, ["source"] = "quest_giver", ["x"] = 0.588, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 680 }, ["zone"] = { 7637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 680, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 20, ["flags"] = 0 } } },
[54041] = { ["id"] = 54041, ["name"] = "No Survivors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 331, ["mapID"] = 62, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "Do you see the encampment on the beach below? The Horde followed Tyrande here. No doubt some of them have remained here in the shadows in case she returned. Kill them.", ["objectivesText"] = "Kill 8 Veiled Deathstalkers . Progress: The Horde will pay the ultimate price for crossing the kaldorei.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 23389, 25778, 25779, 25780, 165232, 165233, 165250, 211279 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 146375, ["x"] = 0.306, ["y"] = 0.982 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 146375, ["x"] = 0.306, ["y"] = 0.982 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.982 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 331 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 63, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54042] = { ["id"] = 54042, ["name"] = "Trouble in Darkshore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "We have received some disturbing reports from Darkshore . What was once a secure stronghold for the Horde is now beset by an unnatural darkness. The moon has turned completely black. The outposts there have yet to be reinforced with our main force and we are suddenly outnumbered. Nathanos wants you to meet him in Darkshore and find out what happened.", ["objectivesText"] = "Speak with Dread-Admiral Tattersail to travel to Darkshore and report to Nathanos. Progress: Have you traveled to Darkshore ?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 149471, ["x"] = 0.529, ["y"] = 0.944 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.529, ["y"] = 0.944 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54043] = { ["id"] = 54043, ["name"] = "Dark Ranger Round-Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "These night elf ambushes have left us undermanned. We need reinforcements if we are to hold Darkshore . Brynja, one of the Dark Lady's val'kyr, can provide us with those reinforcements. Slay the night elves and command her to raise them into our service. Should any prove unwilling... deal with them. Did I not make myself clear? Go. The Dark Lady has plans for these dark rangers.", ["objectivesText"] = "Slay Vindictive Sentinels and Archers and command Brynja to raise them as Dark Rangers.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 166544 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54044] = { ["id"] = 54044, ["name"] = "Black Moon Rising", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "Darkshore has never been known for being bright and sunny, but something strange has happened here. A black moon hangs over everything. None of the scouts I sent into the forest have returned. The night elves are up to something. And I need to know what it is. Their rank-and-file won't have the information we seek. Hunt down their lieutenants and get them to talk by any means necessary.", ["objectivesText"] = "Interrogate Lieutenants Golras, Ivyth, and Maliyra. Progress: <The wisp appears lost and disoriented. It follows you.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54045] = { ["id"] = 54045, ["name"] = "Quit Vining!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "This is terrible, <name>! We got harvesters that ain't harvestin'! We've been busting our rumps chopping down all these trees, but someone keeps tangling up our machines in the vines! I ain't going out there with those night elves stalkin' around. See if you can get in there and free up my equipment!", ["objectivesText"] = "Free Goblin Harvesters from vines.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54046] = { ["id"] = 54046, ["name"] = "We're Not Out of the Woods Yet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "<The wisp flickers at you in a confused manner. It seems to want to follow you. Perhaps it has the information Nathanos seeks.>", ["objectivesText"] = "Bring the Lost Wisp to Nathanos Blightcaller in Lor'danel Landing. Progress: Have you found anything useful?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54047] = { ["id"] = 54047, ["name"] = "Where Hope Dies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "We must carry out the Dark Lady's orders before we are overrun by these newly-invigorated elves. There is one night elf in particular that we seek. You may remember her from our last venture into Darkshore . Lucky for you, she is already dead... so she should prove less troublesome than the living ones you've already encountered. Signal me when you find her corpse.", ["objectivesText"] = "Find the body of Delaryn Summermoon. Progress: Have you found her yet?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54048] = { ["id"] = 54048, ["name"] = "To Kill A Warden", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["storyline"] = { 54048 }, ["description"] = "<The oppressive feeling of being hunted has reached a peak. You know there is someone behind you.>", ["objectivesText"] = "Defeat Sira Moonwarden .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard" },
[54049] = { ["id"] = 54049, ["name"] = "The Dead of Night", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "This is the crux of the Dark Lady's plan for Darkshore . We will raise new champions for the Forsaken and the Horde on this very spot. Guard the val'kyr. We cannot allow anything or anyone to interrupt them.", ["objectivesText"] = "Protect the val'kyr as they resurrect Delaryn and Sira.", ["rewardGold"] = 468000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54050] = { ["id"] = 54050, ["name"] = "Aftermath", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "We all have our reasons for accepting the val'kyr's gift. But now is not the time for those discussions. Sylvanas has been dealt a heavy blow today with the loss of Brynja. We will have no time to rest before the Alliance descends on this place. Nathanos has summoned you. There is something you must see.", ["objectivesText"] = "Speak to Nathanos Blightcaller . Progress: Have you spoken with Nathanos?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 86143, 116374, 116416, 116417, 116418, 116419, 116420, 116421, 116422, 116423, 116424, 116429, 127755, 163036, 166678 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54051] = { ["id"] = 54051, ["name"] = "Naga Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54051 }, ["objectivesText"] = "Repel the naga invaders Captives freed War supplies destroyed Banners removed", ["rewardXP"] = 2125, ["rewardItems"] = { 165605, 168003, 168123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Repel the naga invaders", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Captives freed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 146376, ["orderIndex"] = 1 }, { ["text"] = "War supplies destroyed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 146392, ["orderIndex"] = 2 }, { ["text"] = "Banners removed", ["amount"] = 34, ["type"] = 0, ["objectID"] = 146397, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[54052] = { ["id"] = 54052, ["name"] = "Questfall", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 40, ["storyline"] = { 54052 }, ["description"] = "Me apologies, matey! New to the bow! More of a sword arm, yeah?! Didn't mean ta give ya such a start! It's just that we're in a bit of a bind, me an' the crew here! Can ya give us a bit of a hand?! Some upright dogs attacked us in the dead of night! Chased us out of camp in our skivvies! Maybe ya can help?! They had some sort of big one as their boss! We've been callin' him Barkpaw on account of he was barkin' at us and had big ol' paws!", ["objectivesText"] = "Slay 8 Riverpaw Gnolls and defeat Barkpaw .", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 40 } }, ["questType"] = "standard" },
[54058] = { ["id"] = 54058, ["name"] = "Unintended Consequences", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 896, ["storyline"] = { 53760, 53761, 53762, 53763, 53765, 53766, 54058, 54113, 54114, 54117, 54118, 54126, 54141, 54144, 54172, 54174, 54265, 54433, 54438, 54439, 54682, 54683 }, ["series"] = { 53760, 53761, 53762, 54113, 54114, 54117, 54118, 54144, 54174, 54265, 54433 }, ["description"] = "< Xal'atath speaks once more.> The servants of N'Zoth prepare for their master's return. They intend to conjure a scouring storm to wash away all unbelievers. The particular ritual they will invoke requires three ancient artifacts. One of void, one of storm, and one of ocean. Even now, I hear the void relic calling to me. It is being empowered... or corrupted, I am not sure which. I see it upon a cliff, overlooking a vast sea. Come, priest. We can find a much better use for such a prize.", ["objectivesText"] = "Find the Void Stone in Drustvar. Progress: A change of pace can be invigorating, eh, High Priest?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 162011, 164911, 165605, 168123 }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 144773, ["x"] = 0.198, ["y"] = 0.362 }, { ["mapID"] = 896, ["npcID"] = 152589, ["x"] = 0.2, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.198, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54059] = { ["id"] = 54059, ["name"] = "The Night Warrior", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1333, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "It appears these night elves won't give up the information easily... but perhaps that wisp you captured will. See if you can get it to reveal what happened here. I don't care how you do it. Father Norlath will handle the wisp from there.", ["objectivesText"] = "Speak with the Lost Wisp to find out why the moon turned dark. Progress: Have you made that wisp cooperate?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2129, ["db2PoiUiMapID"] = 1333, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54060] = { ["id"] = 54060, ["name"] = "Naga Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54060 }, ["objectivesText"] = "Repel the naga invaders", ["rewardXP"] = 2125, ["rewardItems"] = { 165605, 168003, 168123 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8499 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Repel the naga invaders", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["db2QuestInfoID"] = 111, ["db2QuestInfoName"] = "Elite World Quest" },
[54082] = { ["id"] = 54082, ["name"] = "More Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54082 }, ["description"] = "Welcome back, dear test subject. My dear sister has kindly asked me to administer today's experiment, which falls below our typical standards of legality... You may, as always, choose not to participate and we will acquire sufficient replacement test subjects. Our new project requires more energy than our generator can manage. We must supercharge it with a jolt of power from the outside. Bondo's Yard has the best power line in Mechagon , so we shall siphon what we need from those rapscallions.", ["objectivesText"] = "Connect power lines from Bondo's Yard to the Quickcharge laboratory.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 129759, 166970, 169114 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.721, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[54083] = { ["id"] = 54083, ["name"] = "Grease The Wheels", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "Kerchunk said you guys was working on getting that mechaspider running again. Well I'm not gonna let you have all the fun! That rusty old thing's gonna need a lot of grease to get moving again. So I jury-rigged a special Grease Trap to help you gather grease from the slimes nearby.", ["objectivesText"] = "Use the Grease Trap to collect 12 Cog Grease from slimes around The Outflow.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 167076, 168827 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 149815, ["x"] = 0.71475, ["y"] = 0.363 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 149815, ["x"] = 0.71475, ["y"] = 0.363 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.71475, ["y"] = 0.363 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54086] = { ["id"] = 54086, ["name"] = "Right Bot for the Job", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "We don't waste anything around here. Every defeated bot gets a second chance! If I'm going to fix this mechaspider, I'm going to need a few extra wrenchbots working with me. Use my Bot Re-Energizer on three dead Repeating Wrenchbots and bring them to me, and I'll put them to work.", ["objectivesText"] = "Bring three Repeating Wrenchbots to Recycler Kerchunk Progress: Did you find those Repeating Wrenchbots yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 168827 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54087] = { ["id"] = 54087, ["name"] = "You Must be This Height", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "The moment is here <name>. For such a historic moment I feel a gnome, such as myself, should be the one to activate the device. Let me know when you think we should begin.", ["objectivesText"] = "Let me know when I can activate the device. Progress: This is quite an important discovery!", ["rewardGold"] = 257400, ["rewardXP"] = 1770, ["rewardItems"] = { 167039 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 149877, ["x"] = 0.658, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 152864, ["x"] = 0.658, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54088] = { ["id"] = 54088, ["name"] = "The Legend of Mechagon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["series"] = { 57009, 58708 }, ["description"] = "I came as soon as I heard! A mysterious vault has been discovered in Tiragarde. Centuries ago, the last king of the gnomes, King Mechagon, led his followers in search of a mythical land of technology. He left no clue as to where he was headed, and over time his legend faded into history. This vault could be the first step to discovering King Mechagon's true fate! I must examine it firsthand. Meet me there, Champion. I could use your assistance.", ["objectivesText"] = "Meet Tinkmaster Overspark outside the mysterious vault.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150208, ["x"] = 0.674, ["y"] = 0.155333 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 149864, ["x"] = 0.655, ["y"] = 0.65 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.155333 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54089] = { ["id"] = 54089, ["name"] = "Omgar Doombow", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 54089 }, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 260, ["db2QuestInfoName"] = "Faction Assault Elite World Quest", ["db2VignetteID"] = 3455, ["db2VignetteName"] = "Omgar Doombow" },
[54090] = { ["id"] = 54090, ["name"] = "Toys For Destruction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54090 }, ["description"] = "Ricket sent word that she was here in Mechagon , so I came right away to help with the uh... research. I had the peons scour the island for any technology they could find. With da stuff we got here, we gonna make some amazing weapons to fight King Mechagon . Then afterwards, we get rich selling 'em! Help me wrangle everyone's ideas into one perfect weapon!", ["objectivesText"] = "Help Rocket-Chief Fuselage build the perfect weapon. Progress: You build an amazing weapon yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151006, ["x"] = 0.698, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151006, ["x"] = 0.698, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 965, ["name"] = "Visit from B.O.O.M.", ["orderIndex"] = 0, ["flags"] = 0 } } },
