[54094] = { ["id"] = 54094, ["name"] = "A Goblin's Definition of Success", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "I'm all set here, I'm just gonna play around with the mech, I think I got a good idea how it works thanks to ya. Nathanos \"prince of all that's death and destruction\" Blightcaller is gonna want you back on that boat, the Banshee's Scream or whatever it is. He'll be happy to know we took care of business. Then again, I got no idea if he even feels happy anymore.", ["objectivesText"] = "Meet with Nathanos on the Banshee's Wail.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 146623, ["x"] = 0.876, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.876, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 11, ["flags"] = 0 } } },
[54096] = { ["id"] = 54096, ["name"] = "The Fall of the Sunwell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 10 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3487, ["mapID"] = 110, ["storyline"] = { 53725, 53734, 53735, 53736, 53737, 53738, 53791, 53853, 53882, 54096 }, ["description"] = "The flame of the lantern dims. Your final task is to rekindle it. In order to do so, you must walk one remaining path. While we are fortunate to hold the Sunwell once again, we must always remember that it was yet another part of us that Arthas took away... and that our late prince was forced to find us a new way of life. Enter the Sunwell Plateau, and witness its fall.", ["objectivesText"] = "Complete the Fall of the Sunwell scenario.", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 166896 }, ["starts"] = { { ["mapID"] = 110, ["npcID"] = 145793, ["x"] = 0.6028, ["y"] = 0.2836 } }, ["ends"] = { { ["mapID"] = 110, ["npcID"] = 16802, ["x"] = 0.618667, ["y"] = 0.301 } }, ["coords"] = { ["mapID"] = 110, ["source"] = "quest_giver", ["x"] = 0.6028, ["y"] = 0.2836 }, ["mapCandidates"] = { ["npc"] = { 110 }, ["zone"] = { 3487 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 274, ["title"] = "Lorewalking:Elves", ["questLineID"] = 5697, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 110, ["questLines"] = { { ["id"] = 811, ["name"] = "Blood Elf Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5697, ["name"] = "Lorewalking: Elves", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54097] = { ["id"] = 54097, ["name"] = "The Dark Lady Calls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "Champion, the Dark Lady has need of you. We cannot speak more of this here. Make haste to Orgrimmar at once. Best not to keep her waiting.", ["objectivesText"] = "Meet with Lady Sylvanas Windrunner in Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 146013, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 146654, ["x"] = 0.484667, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 85, 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54099] = { ["id"] = 54099, ["name"] = "The High Overlord", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "I have asked you here to discuss a matter of great importance to the Horde. Varok Saurfang is no longer in Stormwind. Let us discuss this turn of events.", ["objectivesText"] = "Discuss Saurfang's fate with Lady Sylvanas Windrunner in Orgrimmar. Progress: I trust your discretion in this matter.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 146654, ["x"] = 0.484667, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 146654, ["x"] = 0.484667, ["y"] = 0.715333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.484667, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54100] = { ["id"] = 54100, ["name"] = "A Way Out", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "My spies report that our High Overlord did not leave the way he entered, nor any other way we know of. No signs of him were seen at any of the known exits from the Stockades or the sewers. He simply was in his cell one moment, and gone the next. Begin your investigation around the city of Stormwind. There must be another way out that we do not know of. Dark Ranger Lyana will meet you there. Her tracking skills are second to none. Do not fail me, my champion.", ["objectivesText"] = "Meet with Dark Ranger Lyana in Elwynn Forest.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 2411, 12050, 12051, 25470, 25474, 25948, 25949, 25951, 26009, 26023, 26035, 31725, 49927, 52920, 52937, 52965, 61463, 61464, 61465, 66898, 66899, 66900, 66915, 66917, 66921, 81552, 81553, 81554, 81555, 81556, 81557, 81834, 81835, 81836, 81837, 81838, 88384, 90546, 90547, 90622, 112595, 112596, 112597, 112598, 131273, 131835, 140255, 142054, 153726, 153747, 153773, 153792, 153814, 153830, 153835, 153856, 153859, 153889, 153891, 153892, 153893, 153934, 153944, 153959, 153960, 153961, 153973, 153983, 154005, 154024, 154025, 154035, 154036, 160513, 165638, 165791, 170514, 170515, 170516, 170517, 170518, 170519, 170520, 170521, 170522, 170523, 170524, 170525, 170526, 170527, 170528, 170529, 170530, 170531, 170532, 170533, 170534, 170535, 170536, 170537, 173340, 173341, 173342, 173343, 175588, 179768, 179887, 180924, 180925, 180926, 180927, 181912, 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467, 191984, 191986, 191988, 191989, 191990, 191991, 191992, 191994, 191995, 191996, 191998, 191999, 192002, 192004, 192005, 192006, 192007, 192008, 192009, 192010, 192011, 192012, 192013, 192015, 192037, 194522, 197943, 198542, 211279, 231839, 237812, 245707, 245708, 245709, 245710, 247234, 254878 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 146654, ["x"] = 0.484667, ["y"] = 0.715333 } }, ["ends"] = { { ["mapID"] = 51, ["npcID"] = 146010, ["x"] = 0.805333, ["y"] = 0.776333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.484667, ["y"] = 0.715333 }, ["mapCandidates"] = { ["npc"] = { 51, 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54101] = { ["id"] = 54101, ["name"] = "On Track", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 12, ["mapID"] = 37, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "Keep your head down. We do not want to be seen out here. Our spies keep watch over Stormwind day and night, and saw no signs of Saurfang. Nor did we notice any oddly-oversized carts or strange ships in the night, if that was what you were thinking. How then, did he make his escape? Let's look around.", ["objectivesText"] = "Follow the trail of Varok Saurfang in Elwynn Forest. Progress: Let us keep investigating.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 165638, 165791, 211279 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 146010, ["x"] = 0.305333, ["y"] = 0.576 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.305333, ["y"] = 0.576 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 12 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 37, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54102] = { ["id"] = 54102, ["name"] = "Eastern Escape", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "It's not unusual to see SI:7 spies lurking around the city, but something about this doesn't feel right. We need to find where Saurfang's trail picks up. The last tracks were heading east, towards Redridge. The path to Redridge crosses the Three Corners, one of the Alliance's more well-defended towers. I have an idea. Meet me there.", ["objectivesText"] = "Meet Dark Ranger Lyana at Three Corners in Redridge Mountains.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 165638, 165791 }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 146806, ["x"] = 0.112, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.112, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54103] = { ["id"] = 54103, ["name"] = "Corner Crossing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "If Saurfang was headed in this direction, it would have been difficult for him to avoid the Three Corners watchpost. We could simply walk in there and demand information, but I have a feeling that they would not part with it willingly. So we will take another approach. I have procured this potion from our alchemists. It will turn us into--ugh--humans for a while. We can then question the guards. Perhaps someone saw something.", ["objectivesText"] = "Drink the Humanizing Potion , then question the citizens of Redridge Mountains. Progress: Let's find out everything we can.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 20576, 110505, 165638, 165791 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 146806, ["x"] = 0.112, ["y"] = 0.668 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.112, ["y"] = 0.668 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54104] = { ["id"] = 54104, ["name"] = "Signs of Saurfang", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "With the guards drunk at their posts, and others out of position, Saurfang would have had little trouble passing Three Corners undetected. The path splits just south of town. The back roads of Redridge are poorly patrolled, and are infested with gnolls and spiders. In other words, perfect for an orc trying not to be noticed. His most likely path is Lakeridge Highway. We should continue our investigation there.", ["objectivesText"] = "Follow the trail of Varok Saurfang in Redridge. Progress: Well? What are you waiting for?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 165638, 165791 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54105] = { ["id"] = 54105, ["name"] = "Ever Eastward", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "All signs point to our quarry heading farther east. To what end, I am not sure. But I have my suspicions. I am going to scout the area from the air. Let's meet up at Redridge Pass.", ["objectivesText"] = "Find Dark Ranger Lyana at Redridge Pass in Redridge Mountains.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 165638, 165791 }, ["ends"] = { { ["mapID"] = 49, ["npcID"] = 147210, ["x"] = 0.805, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.805, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54106] = { ["id"] = 54106, ["name"] = "Tracking Tipoff", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "Look there, down the hill. One of the Alliance hunters that roam the area. No one knows these pathways like them. If our quarry passed through here, that hunter would certainly have seen the tracks. His dogs may even have caught Saurfang's scent. Here is another dose of the potion. Let us question this one while he is alone.", ["objectivesText"] = "Drink the Humanizing Potion , then question Hunter McAlister at Redridge Pass in Redridge Mountains. Progress: Let's find out everything we can.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 165638, 165791 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 147210, ["x"] = 0.805, ["y"] = 0.468 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.805, ["y"] = 0.468 }, ["mapCandidates"] = { ["npc"] = { 49 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 49, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54107] = { ["id"] = 54107, ["name"] = "Grim Tidings", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 44, ["mapID"] = 49, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "Ey mon, dat dark ranger, she be lyin' to ya! Saurfang knew dey'd be comin' for him. He sent me to watch da pass, see who his assassins be. Try to warn him if I could. She not be reportin' back nothin'... she gonna kill him. Most likely got a whole buncha deathguards just waitin' for her signal. We gotta stop dem! Ya wit' me?", ["objectivesText"] = "Meet with Zekhan in Swamp of Sorrows.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 165638, 165791 }, ["starts"] = { { ["mapID"] = 49, ["npcID"] = 146012, ["x"] = 0.81, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 51, ["npcID"] = 147297, ["x"] = 0.802667, ["y"] = 0.764667 } }, ["coords"] = { ["mapID"] = 49, ["source"] = "quest_giver", ["x"] = 0.81, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 49, 51 }, ["zone"] = { 44 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 51, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54108] = { ["id"] = 54108, ["name"] = "A Warrior's Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8, ["mapID"] = 51, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "She gonna try an' take him in, and den no one ever gonna see Varok Saurfang again. Dis was never a rescue mission. Dis be about power, an' control, an' Sylvanas think she be holdin' all da cards. But she didn't count on us! Let's go!", ["objectivesText"] = "Defend Varok Saurfang in Swamp of Sorrows. Progress: Will you stand with us?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 165638, 165791 }, ["starts"] = { { ["mapID"] = 51, ["npcID"] = 147297, ["x"] = 0.802667, ["y"] = 0.764667 } }, ["ends"] = { { ["mapID"] = 51, ["npcID"] = 146011, ["x"] = 0.808667, ["y"] = 0.788667 } }, ["coords"] = { ["mapID"] = 51, ["source"] = "quest_giver", ["x"] = 0.802667, ["y"] = 0.764667 }, ["mapCandidates"] = { ["npc"] = { 51 }, ["zone"] = { 8 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiUiMapID"] = 51, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 11, ["flags"] = 0 } } },
[54109] = { ["id"] = 54109, ["name"] = "Queen's Favor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8, ["mapID"] = 51, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "I have two things to ask of you, and I do not ask them lightly. First, I need you to retain the favor of the warchief. She will undoubtedly have questions, and seeds of distrust may begin to grow, but she cannot lose you as an ally. Not now. She would not so willingly part with one of her greatest champions. In order to do so, it will have to look like you faced me in combat, and lost. I trust you can take a hit. Second, I ask you not to follow me further. I must make this journey alone.", ["objectivesText"] = "Take a hit from Varok Saurfang , then report to Warchief Sylvanas Windrunner in Orgrimmar.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 165638, 165791 }, ["starts"] = { { ["mapID"] = 51, ["npcID"] = 146011, ["x"] = 0.808667, ["y"] = 0.788667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 134711, ["x"] = 0.485, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 51, ["source"] = "quest_giver", ["x"] = 0.808667, ["y"] = 0.788667 }, ["mapCandidates"] = { ["npc"] = { 51, 85 }, ["zone"] = { 8 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 802, ["name"] = "Lost Honor", ["orderIndex"] = 12, ["flags"] = 0 } } },
