[54120] = { ["id"] = 54120, ["name"] = "To Orgrimmar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53778 }, ["description"] = "A darkness in me mind be keeping me from remembering what happened da day I named Sylvanas warchief. Take me glaive and travel to da pyre where I was cremated in Orgrimmar . Master Gadrin be packin' enough juju to call me to dat place. Go, and I be seein' ya dere.", ["objectivesText"] = "Take the Glaive of Vol'jin to Master Gadrin at Drannosh'ar Blockade, Durotar. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 23211, 23246, 23247, 23326, 23327, 23435, 34684, 111660, 118776, 118777, 118778, 118779, 118780, 165371 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 146268, ["x"] = 0.458, ["y"] = 0.158 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.158 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54121] = { ["id"] = 54121, ["name"] = "Breaking Out Ashvane", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54121, 54175, 54176, 54177, 54178, 54179 }, ["description"] = "The Dark Lady wishes to gain another potential ally in the fight against the Alliance. Lady Ashvane, head of the Ashvane Company, was one of the greatest enemies of Kul Tiras until her capture. We are going to release her. Meet Valtrois in Tiragarde Sound. She and Rexxar are working out a plan to break Ashvane out.", ["objectivesText"] = "Meet Valtrois in Tiragarde Sound.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 147088, ["x"] = 0.83, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 17 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 848, ["name"] = "Escape from Tol Dagor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54123] = { ["id"] = 54123, ["name"] = "It Belongs in My Mech!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "Check this out! It's my latest creation that someone else came up with and built, Gallywix's Mech of Death! I got it fueled with all that Azerite you found, but I still need more of the stuff to give it that extra kick. I was SUPPOSED to have the stuff from our operations here, but there's some sorta Azerite goop causin' a mess! My guy Patch made an Azerite vacuum device. I want you to suck the Azerite outta these slimes!", ["objectivesText"] = "Recover Azerite from Azerite slimes using the Azerite Vacuumizer .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 145751, ["x"] = 0.362, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 145751, ["x"] = 0.362, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54124] = { ["id"] = 54124, ["name"] = "Avoiding Lawsuits 101", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "Yo, <name>! I leave the A.M.O.D. for two seconds to deal with old Gallywix and now I'm knee-deep in Azerite goo! Listen, here's the deal. I need ya to rescue some of these goblins from these monsters. I'll be honest, I skimped on the money that covers their insurance in the event of Azerite-monster-related injuries. What? Who knew that these slimes would appear and attack these guys! Do me a solid and get these goblins outta there!", ["objectivesText"] = "Rescue 6 Uninsured Goblin Workers . Progress: Ya help those guys?", ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165702, 165734, 166309, 166850 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 148339, ["x"] = 0.362, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 148339, ["x"] = 0.362, ["y"] = 0.72 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54126] = { ["id"] = 54126, ["name"] = "Twist the Knife", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 53760, 53761, 53762, 53765, 54058, 54113, 54114, 54126, 54141, 54144, 54265, 54438, 54682 }, ["description"] = "The relics are ours... as it was meant to be. There is but one more step needed for the great truths to be revealed. The naga sought to summon their storm from a place that echoes with ancient power. Though this site has had countless names over the ages, you mortals know it as the Precipice of Oblivion. I will go on ahead and begin preparations. Join me there.", ["objectivesText"] = "Meet Xal'atath at the Precipice of Oblivion.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 146384, ["x"] = 0.524, ["y"] = 0.136 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 146902, ["x"] = 0.675333, ["y"] = 0.212667 }, { ["mapID"] = 84, ["npcID"] = 231891, ["x"] = 0.642, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.524, ["y"] = 0.136 }, ["mapCandidates"] = { ["npc"] = { 84, 864, 1161 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 266, ["title"] = "Lorewalking: Xal'atath", ["questLineID"] = 5673, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5673, ["name"] = "Lorewalking: Xal'atath", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54127] = { ["id"] = 54127, ["name"] = "Rocket Hop", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 54127 }, ["description"] = "Horde forces are attacking Tiragarde Sound. Make them regret every footstep upon our soil!", ["objectivesText"] = "Repel the Hordes forces attacking Tiragarde Sound.", ["rewardXP"] = 2125, ["rewardItems"] = { 165943 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Grizzek's Rocket Hop obtained", ["amount"] = 1, ["type"] = 1, ["objectID"] = 165943, ["orderIndex"] = 0 }, { ["text"] = "West Zeppelin destroyed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 147043, ["orderIndex"] = 1 }, { ["text"] = "East Zeppelin destroyed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 147042, ["orderIndex"] = 2 }, { ["text"] = "Siege Cannon destroyed", ["amount"] = 4, ["type"] = 0, ["objectID"] = 147050, ["orderIndex"] = 5 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 259, ["db2QuestInfoName"] = "Faction Assault World Quest" },
[54128] = { ["id"] = 54128, ["name"] = "Necessary Precautions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53941, 53942, 54004, 54007, 54008, 54009, 54022, 54028, 54094, 54123, 54124, 54128, 54635 }, ["description"] = "That was freakin' awesome! We decimated Mekkatorque's puny little army. We got a location on where that little punk and his airship is. That's where he's controllin' all his FORMER mechs. Here's the plan, we're gonna fly over there, blow up that freak, then destroy his airship! Now, I ain't no idiot, <name>, I'm the smartest goblin alive. First, we gotta take what they call necessary precautions. Take this manual, I want you to make sure the G.M.O.D is ready to go!", ["objectivesText"] = "Review the G.M.O.D 's systems. Progress: Well? This thing ain't gonna double check itself! Although... maybe it should.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 145816, ["x"] = 0.372, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 145816, ["x"] = 0.372, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.372, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 16 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 839, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 839, ["name"] = "Adventures of Gallywix and the G.M.O.D.", ["orderIndex"] = 4, ["flags"] = 0 } } },
