[54130] = { ["id"] = 54130, ["name"] = "Our New Friends", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 54130 }, ["description"] = "I heard that the Alliance is growing! More and more different kinds of people are joining all the time to fight the mean Horde. I'm not sure where the embassy is, but I heard it's somewhere here in Stormwind. Can you show me how to get there? I want to see all our new friends!", ["objectivesText"] = "Take your Human Orphan to the Stormwind Embassy. If your orphan is not present when you arrive, call for him. Progress: I bet all of our new friends came from really far away!", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 18598 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
