[54135] = { ["id"] = 54135, ["name"] = "Romp in the Swamp", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54135 }, ["description"] = "Alliance armies are landing on the shores of Nazmir. Drive them back to the sea. Zandalar is ours!", ["objectivesText"] = "Repel the Alliance forces assaulting Nazmir. Progress: Nazmir belongs to the Zandalari, and the Horde!", ["rewardXP"] = 2125, ["rewardItems"] = { 109076, 163857, 165871, 166792 }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 135459, ["x"] = 0.39, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard" },
