[54137] = { ["id"] = 54137, ["name"] = "In Every Dark Corner", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 862, ["storyline"] = { 54137 }, ["description"] = "The Alliance's hold on Drustvar is weak. We will conquer it for the Horde!", ["objectivesText"] = "Lead the Horde assault into Drustvar. Progress: What news do you bring from the front lines of Drustvar?", ["rewardXP"] = 2125, ["rewardItems"] = { 165871 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135447, ["x"] = 0.58, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8721 } }, ["questType"] = "standard" },
