[54139] = { ["id"] = 54139, ["name"] = "War Is Here", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "We need to move, <name>. We've received word that the Alliance have mounted an attack through Nazmir. Make for the Great Seal. King Rastakhan and Princess Talanji are there forming a plan of attack. Make no mistake, we will crush the Alliance. They are fools to attack us through Nazmir.", ["objectivesText"] = "Meet King Rastakhan within the Great Seal. Progress: Let's get moving.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54140] = { ["id"] = 54140, ["name"] = "Ride of the Zandalari", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "It is time de Alliance see de full fury of de Zandalari. Dey are fools to try an attack in Nazmir. We must tell de fleet, our warriors, and our flyers dat dey must move out and go to Nazmir at once. I will go aid our forces at de Blood Gate. Here is a list of dose you must speak with to mobilize our forces. Move as fast as you can, we must stop de Alliance as quickly as possible.", ["objectivesText"] = "Mobilize the Zandalari fleet, warriors, and flyers.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54141] = { ["id"] = 54141, ["name"] = "The Azsharan Medallion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 942, ["storyline"] = { 53760, 53761, 53762, 53765, 54058, 54113, 54114, 54126, 54141, 54144, 54265, 54438, 54682 }, ["description"] = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue. Perhaps someone with a knowledge of naga artifacts could translate the text.>", ["objectivesText"] = "Take the Medallion to Collector Kojo .", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164761, 165605, 168123 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 135793, ["x"] = 0.404667, ["y"] = 0.364667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.404667, ["y"] = 0.364667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 165605 } },
