[54144] = { ["id"] = 54144, ["name"] = "Orders from Azshara", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53760, 53761, 53762, 53765, 54058, 54113, 54114, 54126, 54141, 54144, 54265, 54438, 54682 }, ["series"] = { 53760, 53761, 53762, 54058, 54113, 54114, 54117, 54118, 54174, 54265, 54433 }, ["description"] = "<Kojo studies the medallion and grimaces.> Ugh... naga. This medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power. You know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me. I found it on an island in Stormsong Valley, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", ["objectivesText"] = "Take the Dagger to the Makeshift Altar. Progress: <As you place the dagger upon the altar, it seems to shudder and blink at you.>", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135793, ["x"] = 0.404667, ["y"] = 0.364667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.404667, ["y"] = 0.364667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54145] = { ["id"] = 54145, ["name"] = "The Loa of Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53777, 53779 }, ["description"] = "Bwonsamdi is a dangerous loa, but even I do not believe he whispered to Vol'jin on his deathbed. To appoint Sylvanas sounds, well... he is not fond of de undead. And from what I have seen of de warchief, she is no fan of death. We must be respectful when we speak to Bwonsamdi , or dere will be consequences. Come, stay close.", ["objectivesText"] = "Confront Bwonsamdi .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 146824, ["x"] = 0.394667, ["y"] = 0.262 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54146] = { ["id"] = 54146, ["name"] = "Strong New Allies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Children's Week", ["expansion"] = 7, ["storyline"] = { 54146 }, ["description"] = "I heard some adventurers saying that there are new members of the Horde, unlike all the rest! And the best part? They're right here in Orgrimmar! I don't know where the embassy is... but I bet you do! Can you take me? I heard there are orcs from another planet!", ["objectivesText"] = "Take your Orcish Orphan to the Orgrimmar Embassy. If your orphan is not present when you arrive, call for him. Progress: New friends in Orgrimmar! That means I can come back and visit them all the time.", ["rewardXP"] = 1415, ["rewardItems"] = { 18597 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[54147] = { ["id"] = 54147, ["name"] = "Confront The Val'kyr", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7541, ["mapID"] = 634, ["storyline"] = { 53774, 53775, 53776, 53777, 53778, 53779, 53780, 53781, 53782, 54120, 54145, 54147 }, ["series"] = { 53781, 53782 }, ["description"] = "Vol'jin's spirit is growing in power. I should no longer have to maintain a ritual to keep him here. Dis is fortunate, since Bwonsamdi warned me dat Eyir will likely not be pleased with my presence. Apparently she and Bwonsamdi have a past de loa was unwilling to discuss. We can proceed when you are ready.", ["objectivesText"] = "Escort the Spirit of Vol'jin to Eyir.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 634, ["npcID"] = 146877, ["x"] = 0.612, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 122688, ["x"] = 0.395, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 634, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.68 }, ["mapCandidates"] = { ["npc"] = { 634, 863 }, ["zone"] = { 7541 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 640, ["questLines"] = { { ["id"] = 805, ["name"] = "The Shadow Hunter", ["orderIndex"] = 9, ["flags"] = 0 } } },
