[54156] = { ["id"] = 54156, ["name"] = "A Path of Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "De main fleet of de Alliance and Kul Tirans are off de coast in Nazmir. But we cannot ignore de forces here. Dere seems to be a strange fog coming in from Nazmir. De Kul Tirans must be using some of their voodoo to weaken us. We must carve a path of blood through dese Alliance fools. Help our forces by weakening de Alliance.", ["objectivesText"] = "Slay 15 Alliance soldiers within the Blood Gate.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 264299, 264300, 264301, 264302 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147075, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147075, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54157] = { ["id"] = 54157, ["name"] = "No One Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "De warriors here tell me Rokhan made a heroic stand, holding off de Alliance and their champions before being defeated. Rokhan is still here within de Blood Gate, held captive by some strange creature called a Lightforged. I must stay here and help hold de line. I need you to rescue Rokhan!", ["objectivesText"] = "Rescue Rokhan.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54161] = { ["id"] = 54161, ["name"] = "What the Drust Knew", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54161, 55635 }, ["description"] = "Bal'a dash, <name>. If you have a moment, I could use your assistance. I've recently received a shipment of Drust relics that were smuggled out of Kul Tiras. Most have our usual enchantments, but there is one that is unique. Just holding it makes my hair stand on end. With you being my best pupil, I was thinking that it would be enlightening if we disenchanted it together, to see how it was made. What do you say?", ["objectivesText"] = "Carefully remove the enchantment from the Ancient Drust relic to learn about its construction.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 122702, ["x"] = 0.47, ["y"] = 0.358 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122702, ["x"] = 0.47, ["y"] = 0.358 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.358 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 910, ["name"] = "8.1.5 Enchanting - Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
