[54163] = { ["id"] = 54163, ["name"] = "As the Dust Settles", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54163, 54183 }, ["description"] = "We have achieved a great victory, <name>, though at a cost. King Wrynn is gathering the Alliance leadership in Unity Square to discuss matters. He has requested our presence as well. Go to Unity Square. I'll meet you there shortly.", ["objectivesText"] = "Meet with Anduin Wrynn in Unity Square.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 147885, ["x"] = 0.492, ["y"] = 0.854 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 847, ["questLineOrder"] = 18 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 847, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 847, ["name"] = "The Price of Victory", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54164] = { ["id"] = 54164, ["name"] = "The King's Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 54164, 54165 }, ["description"] = "King Rastakhan is dead, the Zandalari fleet has been decimated, and we have lost valuable soldiers. The Dark Lady is on her way from Orgrimmar to assess the situation. We must figure out our next move before the Alliance strike again. I believe protocol now would be to pay respects to the fallen king. We will determine our next move afterwards.", ["objectivesText"] = "Pay respects to King Rastakhan .", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 44358, 44359, 44360, 44361 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145411, ["x"] = 0.498, ["y"] = 0.388 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 842, ["questLineOrder"] = 19 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 842, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 842, ["name"] = "Diverging Paths", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54165] = { ["id"] = 54165, ["name"] = "The Return of Derek Proudmoore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 1165, ["storyline"] = { 54164, 54165 }, ["description"] = "I'll admit, I did not think the Little Lion had it in him to kill King Rastakhan. Blood has been spilled, and vengeance must be had. Give me a moment to express my condolences, then come with me. We have more to do to win this war.", ["objectivesText"] = "Observe Sylvanas's discussion with Princess Talanji.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145411, ["x"] = 0.498, ["y"] = 0.388 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.388 }, ["mapCandidates"] = { ["npc"] = { 862, 1165 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 842, ["questLineOrder"] = 19 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 842, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 842, ["name"] = "Diverging Paths", ["orderIndex"] = 1, ["flags"] = 0 } } },
