[54169] = { ["id"] = 54169, ["name"] = "The Treasury Heist", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54169, 54171, 54510 }, ["description"] = "The Abyssal Scepter is a powerful tidesage artifact and a serious threat to the fleet. The Horde stole it, but it is being held by the Zandalari in their treasury. The Storm's Wake has crafted a fake Scepter. Your first job is to obtain the real one without alerting suspicion. Speak to me when you are ready to go over the plan.", ["objectivesText"] = "Retrieve the Abyssal Scepter from the Zandalari Treasury. Progress: Were you successful?", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 146982, ["x"] = 0.406, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 146982, ["x"] = 0.406, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.406, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 849, ["questLineOrder"] = 16 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 849, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 849, ["name"] = "The Treasury Heist", ["orderIndex"] = 1, ["flags"] = 0 } } },
