[54171] = { ["id"] = 54171, ["name"] = "The Abyssal Scepter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54169, 54171, 54510 }, ["description"] = "The Lord Admiral has proposed our next move. It's something we don't think the Horde will expect, but it's dangerous: We're going to steal back the Abyssal Scepter. Your name came up as someone who could see it through, if you're willing to take the chance. Meet Lady Jaina at our base in Xibala. She'll have more information for you there.", ["objectivesText"] = "Meet with Jaina Proudmoore in Xibala in Zuldazar.", ["rewardGold"] = 28090, ["rewardXP"] = 1705, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 146982, ["x"] = 0.406, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 849, ["questLineOrder"] = 16 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 849, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 849, ["name"] = "The Treasury Heist", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54172] = { ["id"] = 54172, ["name"] = "The Azsharan Medallion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 862, ["storyline"] = { 53760, 53761, 53762, 53763, 53766, 54058, 54117, 54118, 54172, 54174, 54433, 54439, 54683 }, ["description"] = "<On the naga's body you find an ornate metal disc. The writing on its surface resembles elven script, but you cannot decipher it. You suspect the words are written in the Nazja tongue. Perhaps someone with a knowledge of naga artifacts could translate the text.>", ["objectivesText"] = "Take the Medallion to Collector Kojo .", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 164761, 165605, 165668, 168123 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 134345, ["x"] = 0.714, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 1, ["flags"] = 0 } }, ["startItems"] = { 165668 } },
[54174] = { ["id"] = 54174, ["name"] = "Orders from Azshara", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53760, 53761, 53762, 53763, 53766, 54058, 54117, 54118, 54172, 54174, 54433, 54439, 54683 }, ["series"] = { 53760, 53761, 53762, 54058, 54113, 54114, 54117, 54118, 54144, 54265, 54433 }, ["description"] = "<Kojo studies the medallion and grimaces.> Ugh... naga. This medallion is inscribed with orders. Looks like naga have been commanded to invade our shores and seize artifacts of great power. You know, I recently came upon one such object. See that dagger over there? Nasty thing. Gives me the willies. I swear I hear it whispering to me. I found it nearby at Atal'Gral, on a makeshift altar. Maybe if you take it there, you'll get an idea of how the naga intended to use it.", ["objectivesText"] = "Take the Dagger to the Makeshift Altar. Progress: <As you place the dagger upon the altar, it seems to shudder and blink at you.>", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 134345, ["x"] = 0.714, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54175] = { ["id"] = 54175, ["name"] = "Face Your Enemy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54121, 54175, 54176, 54177, 54178, 54179 }, ["description"] = "We have decided that our best course of action would be to enter the prison disguised as Proudmoore military. Rexxar will be our prisoner. We want to keep a low profile until we break Ashvane out. I find that I work better with reference when undertaking this type of endeavor. I have chosen some humans that interest me. I would like to examine their faces. Use the Shard of Vesara on them, and they will be... encouraged to find their way to me.", ["objectivesText"] = "Send the targets chosen by Valtrois back for examination.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 147088, ["x"] = 0.83, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 147088, ["x"] = 0.83, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.83, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 17 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 848, ["name"] = "Escape from Tol Dagor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54176] = { ["id"] = 54176, ["name"] = "Be More Uniform", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54121, 54175, 54176, 54177, 54178, 54179 }, ["description"] = "Head into the foundry. Proudmoore's guards have taken over there. They will provide excellent accessories for our disguises. I can recreate their faces, but without the clothing, we won't make it far. Gather enough gear to cover us. We'll need the Captain's jacket as well. There will be less of a challenge at the gate if we outrank them.", ["objectivesText"] = "Collect gear from Proudmoore forces in the foundry. Progress: Was the harvest successful?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165697, 165698, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 147088, ["x"] = 0.83, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 147088, ["x"] = 0.83, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.83, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 17 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 848, ["name"] = "Escape from Tol Dagor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54177] = { ["id"] = 54177, ["name"] = "A Brilliant Distraction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10272, ["mapID"] = 895, ["storyline"] = { 54121, 54175, 54176, 54177, 54178, 54179 }, ["description"] = "We plan to be cautious on entry to Tol Dagor. I imagine our exit will not be as... subtle. That foundry to the west... I hear they made Azerite explosives there. Stock up, we will need them.", ["objectivesText"] = "Retrieve the Volatile Azerite . Progress: Did you find them all?", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 164987, 165690, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 146931, ["x"] = 0.83, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 146931, ["x"] = 0.83, ["y"] = 0.495 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.83, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 10272 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 17 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 848, ["name"] = "Escape from Tol Dagor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54178] = { ["id"] = 54178, ["name"] = "Catching a Ride", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54121, 54175, 54176, 54177, 54178, 54179 }, ["series"] = { 54179 }, ["description"] = "Nathanos should have found a boat by now. Let us hasten to meet him in the harbor. It behooves us to take care of this business quickly. There are better ways for us to support the Horde's effort here.", ["objectivesText"] = "Find Nathanos at the dock in Plunder Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 147088, ["x"] = 0.83, ["y"] = 0.495 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 147135, ["x"] = 0.882, ["y"] = 0.508 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.83, ["y"] = 0.495 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 17 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 848, ["name"] = "Escape from Tol Dagor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54179] = { ["id"] = 54179, ["name"] = "Through the Front Door", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54121, 54175, 54176, 54177, 54178, 54179 }, ["series"] = { 54178 }, ["description"] = "We would like the least amount of risk during your retrieval of Priscilla Ashvane. You will arrive on the docks during a shift change. From there, you will prepare and enter the prison. Find me in Zuldazar when you are successful.", ["objectivesText"] = "Complete \"Escape from Tol Dagor\".", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 163280, 163282, 163283, 163424, 163426, 163432, 163435, 163441, 163446, 163453, 163456, 163459, 164987, 165702, 165734, 166309 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 147135, ["x"] = 0.882, ["y"] = 0.508 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.882, ["y"] = 0.508 }, ["mapCandidates"] = { ["npc"] = { 862, 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 17 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 848, ["questLineOrder"] = 9 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 848, ["name"] = "Escape from Tol Dagor", ["orderIndex"] = 5, ["flags"] = 0 } } },
