[54183] = { ["id"] = 54183, ["name"] = "Dead Reckoning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54163, 54183 }, ["description"] = "While I have some concerns, I cannot deny the bravery, heroism and sacrifices we have made. That you have made, <name>. Thank you for all the aid you have given to the Alliance. The future of our ongoing war campaign is why I have asked everyone here. I wish to look at what we've done, so we can decide on the best way forward.", ["objectivesText"] = "Attend the discussion in Unity Square. Progress: This war may have been necessary, but it is my hope it will be over soon. Then we can begin rebuilding.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 147885, ["x"] = 0.492, ["y"] = 0.854 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 147885, ["x"] = 0.492, ["y"] = 0.854 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.854 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 847, ["questLineOrder"] = 18 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 847, ["questLineOrder"] = 11 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 847, ["name"] = "The Price of Victory", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54184] = { ["id"] = 54184, ["name"] = "Trouble in Gnomeregan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54184 }, ["series"] = { 54185, 54276 }, ["description"] = "Some strange spikes of electric usage have been happening in Gnomeregan recently. We need you to investigate what is going in there as soon as possible. We've received contact from one of the chief engineers in charge of keeping things in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.", ["objectivesText"] = "Find Micro Zoox outside of Gnomeregan in Dun Morogh.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 147645, ["x"] = 0.503, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54185] = { ["id"] = 54185, ["name"] = "Gnomeregan's New Guardians", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1, ["storyline"] = { 54185 }, ["series"] = { 54184, 54276 }, ["description"] = "My personally-modified Mayhem Detection Device has been giving readings off the charts for the last few days. You might be thinking that mayhem and Gnomeregan are synonymous, and to an extent they are, but these readings are beyond anything I've seen before! I'm not totally sure what's going on inside of Gnomeregan, but something is different. If you are feeling brave enough, I can teleport you deep in there and you can see for yourself. Let me know when you are ready.", ["objectivesText"] = "Defeat Pulverizer Bot Mk 6001 in Gnomeregan. Progress: I can teleport you in. Getting out might be more of a challenge.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 103670, 122457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[54186] = { ["id"] = 54186, ["name"] = "Pet Battle Challenge: Gnomeregan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1, ["storyline"] = { 54186 }, ["description"] = "Gnomeregan's at Mayhem Level Maximum again. Those machines just don't give up, and keep coming back. I can teleport us in there again, but all of those crazy robots are back. You sure you want this? I don't. I mean, maybe I want to watch robots smash things for some entertainment. I'm sure you will be fine. Lets go!", ["objectivesText"] = "Defeat Pulverizer Bot Mk 6001 in Gnomeregan. Progress: I can teleport you in. Getting out might be more of a challenge.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 93351, 109076, 165835 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
