[54191] = { ["id"] = 54191, ["name"] = "Changing Course", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["series"] = { 54192 }, ["description"] = "Champion, the time for action is upon us. Developments are underway that will change the course of this war. Report to me aboard Wind's Redemption as soon as possible.", ["objectivesText"] = "Report to Halford Wyrmbane aboard Wind's Redemption in Boralus Harbor.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 43185, 43186 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 15, ["flags"] = 1 } } },
[54192] = { ["id"] = 54192, ["name"] = "Sensitive Intel", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["series"] = { 54191 }, ["description"] = "I've received a report from Kelsey Steelspark . She claims to have discovered something that will aid our war effort. She's refused to go into specifics, citing a need for secrecy with such sensitive intel. It looks like you'll need to speak to her in person. She's expecting you in Xibala.", ["objectivesText"] = "Meet Kelsey Steelspark in Zuldazar.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147151, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54193] = { ["id"] = 54193, ["name"] = "This is Huge!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "$p, allow me to introduce Megs and Morton, the gnomes who are going to shake things up for the Alliance in a big way! They've been perfecting a device that can take any ordinary animal and turn it into a humongous, unstoppable beast that we can then unleash on our enemies! I'll let Megs and Morton fill you in on the specifics, but I promise you, this tech is a game changer!", ["objectivesText"] = "Listen to Megs and Morton's plan. Progress: Wait until you hear their big plan. It's perfect!", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147151, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147151, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54194] = { ["id"] = 54194, ["name"] = "Real Big Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "We're still building a harness for the Embiggifier, but we need to test its core first. That's where the real power is! This technology is years ahead of the Horde's, but it's so easy to use that even an orc could do it! Just point and click!", ["objectivesText"] = "Test the Embiggifier on a Kul Tiran Clucker . Progress: I love this part! When we get to see all our hard work pay off in a big way!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 165723 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54195] = { ["id"] = 54195, ["name"] = "A Beast with Brains", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "For optimal results, the Embiggifier should be used on someone with substantial intellect. Good thing our partner is as smart as they come. He and his kind have been empowered by kaja'mite, granting them exceptional intelligence! Head up to the gorge and let Grong know we're ready to begin the embiggifying!", ["objectivesText"] = "Find Grong within Gorilla Gorge.", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147228, ["x"] = 0.475, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54196] = { ["id"] = 54196, ["name"] = "Out of Options", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "My kind are hunted like animals. We've tried to reach a resolution through civil discourse, but these poachers recoil from rational thought. They revel in brutality. I ask you, $p: Who are the real animals? It pains me to descend to their level, but I fear I've exhausted all other options.", ["objectivesText"] = "Kill 12 Bilgewater goblins within Gorilla Gorge. Progress: It pains me to descend to their level, but I fear I've exhausted all other options.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147228, ["x"] = 0.475, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54197] = { ["id"] = 54197, ["name"] = "Freedom for the Da'kani", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "Have you seen the barbaric conditions to which the Da'kani are subjected? Corralled and caged, awaiting slaughter, or worse... I cannot leave here in good faith without first seeing that my kind are liberated.", ["objectivesText"] = "Free 8 Da'kani Highbrows within Gorilla Gorge.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147228, ["x"] = 0.475, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54198] = { ["id"] = 54198, ["name"] = "Bittersweet Goodbyes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "You've helped me prepare my village for my departure, but now I must prepare myself. Meet me within the grotto, where I will say my farewells.", ["objectivesText"] = "Meet Grong within Grong 's Grotto.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147228, ["x"] = 0.475, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54199] = { ["id"] = 54199, ["name"] = "The Needs of the Many", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "Ever since the kaja'mite began bubbling around the gorge, I have been searching for meaning. Why was I burdened with intelligence? What is my purpose? I have found my answers in the Embiggifier. I was meant to help the Alliance defeat the Horde. If I can save lives by volunteering, then my choice is clear. The needs of the many outweigh the needs of one. I am ready, $p.", ["objectivesText"] = "Accompany Grong to Xibala.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147228, ["x"] = 0.475, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147149, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.475, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54200] = { ["id"] = 54200, ["name"] = "Bring the Base", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "We'll need to collect some baseline statistics before we use the Embiggifier. Grong will be asked to perform basic tasks pertaining to speed, intelligence, and strength. This will help us measure the increase once he's been embiggified.", ["objectivesText"] = "Help collect baseline stats for Grong's speed, intelligence, and strength.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147149, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147311, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54201] = { ["id"] = 54201, ["name"] = "Fit for Grong", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "Grong is already impressively large. In fact, I don't think our Embiggifier is going to fit around his noggin without some modification. I'll require an ample supply of ore to make the necessary adjustments, but we're in luck. The goblins nearby have already done the work of mining it; we just need to take it off their hands! Secure an ample amount of Azerite-infused ore, and we'll be back in business!", ["objectivesText"] = "Collect 12 Azerite Infused Ore . Progress: Have you acquired the ore?", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 165759 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147311, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147311, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54202] = { ["id"] = 54202, ["name"] = "Calibrate the Core", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "The Embiggifier is nearly ready! All that's left to do is calibrate its core. The best way to do that without catastrophic results is to use it on things that are already dead. This should be a simple task! I have a hunch you excel at making things dead.", ["objectivesText"] = "Calibrate the Embiggifier's core by using it on dead things within Bilgewater Bonanza. Progress: Have you calibrated the core yet?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 165762 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 10, ["flags"] = 0 } } },
[54203] = { ["id"] = 54203, ["name"] = "The Embiggining", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "I'll give you the quick rundown before we get started. The Embiggifier is remotely controlled. See this big red button? < Megs gestures to the device in her hand.> This jolts the wearer with a surge of power, making them bigger. For safety reasons, you should remain here at camp. I think that's it! Are you ready to science?", ["objectivesText"] = "Test Grong's stats while embiggified. Progress: Let's see what Grong can do once he's been embiggified!", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 11, ["flags"] = 0 } } },
[54204] = { ["id"] = 54204, ["name"] = "Total Temple Destruction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "Grong is our greatest achievement, and he's ready to be unleashed! The Horde is staging its troops at a temple to the north. Magister Umbric's portal will get you there fast. Then Grong can get to work!", ["objectivesText"] = "Command Grong to defeat the Horde at Temple of the Prophet.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147148, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147519, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 12, ["flags"] = 0 } } },
[54205] = { ["id"] = 54205, ["name"] = "A Nice Nap", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "I'm not sure how much longer those chains will hold. Grong 's going to have to take a little nap until he's ready to be deployed. Use this dart. It's been double-dipped in something potent enough to take down a direhorn, so it should do the trick. Grong would want you to be the one to do it.", ["objectivesText"] = "Use the Tranquilizer Dart on Grong . Progress: Go ahead, use the dart on Grong . He won't feel a thing, I promise.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 165815 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147519, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147519, ["x"] = 0.41, ["y"] = 0.706 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 13, ["flags"] = 0 } } },
[54206] = { ["id"] = 54206, ["name"] = "The Sleeper Agent", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54191, 54192, 54193, 54194, 54195, 54196, 54197, 54198, 54199, 54200, 54201, 54202, 54203, 54204, 54205, 54206 }, ["description"] = "Your work here is done, $p. Morton and Megs can take it from here. Head back to Boralus and let Halford know we've secured the weapon. Don't you worry one wink about Grong. Morton and Megs will make sure he's well looked after.", ["objectivesText"] = "Report back to Halford Wyrmbane in Boralus Harbor.", ["rewardGold"] = 867900, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147519, ["x"] = 0.41, ["y"] = 0.706 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.41, ["y"] = 0.706 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 15 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 810, ["questLineOrder"] = 8 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 810, ["name"] = "Serious Monkey Business", ["orderIndex"] = 14, ["flags"] = 0 } } },
[54207] = { ["id"] = 54207, ["name"] = "Retaking the Outpost", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "We can handle de rest of de Alliance. I received a report that Hexlord Raal 's forces are having issues up ahead. He claims dat dere is an even thicker fog enveloping Nazmir. De Alliance must be using some tricks to slow us down. Go to Nazmir to see what can be done to help Hexlord Raal . We must reach dat fleet and destroy de Alliance!", ["objectivesText"] = "Meet Hexlord Raal in Nazmir.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147075, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147139, ["x"] = 0.502, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862, 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54208] = { ["id"] = 54208, ["name"] = "Minesweeper", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredClasses"] = { 4 }, ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 863, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "The Alliance are stalling our efforts here with this irritating fog, as well as layering the entire area with traps. We will suffer too many casualties if we try marching our army through this trap-infested area. I've heard you're good at sneaking around. Use your talents to disarm the traps in this area. I'll deal with getting the goblin's parts back from the Alliance while you disarm those traps.", ["objectivesText"] = "Disarm 10 traps within the Fallen Outpost.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147145, ["x"] = 0.502, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147145, ["x"] = 0.502, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54211] = { ["id"] = 54211, ["name"] = "Putting the Gob in Gob Squad", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "Yo! We gotta get the rest of the Gob Squad back if we wanna fix the A.F.M.O.D.! So, our mech got trashed. It was rough. The rest of the Gob Squad are hidin' out there, waiting for word when it's safe. Take this tracker. It'll tell ya when you're getting close to one of the squad. When you get real close, you should see 'em. That'll tell any of the squad nearby that it's safe to come outta hidin' and come back here. With the right goblins and parts, we'll be killing Alliance in no time!", ["objectivesText"] = "Rescue the Gob Squad. Progress: You didn't blow up the Gob Squad tracker, did you?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147155, ["x"] = 0.502, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147155, ["x"] = 0.502, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54212] = { ["id"] = 54212, ["name"] = "Re-rebuilding the A.F.M.O.D.", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "Alright, so, we're goin' after the Alliance through this crazy fog. We gotta retake Zo'bal ruins up ahead. We can do that real easy if we fix up our mech, A.F.M.O.D. - a flying mech of death! The Alliance wrecked it in their initial attack and took a bunch of its parts. Get those parts back and we'll have this thing fixed in no time!", ["objectivesText"] = "Recover 10 A.F.M.O.D. parts from Gilnean Ambushers and Night Elf Sentinels. Progress: You got the parts? We'll figure out what goes where when it's all done.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 165710 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147155, ["x"] = 0.502, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147155, ["x"] = 0.502, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54213] = { ["id"] = 54213, ["name"] = "It's Alive!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "We got the A.F.M.O.D. repaired and it works perfectly! Eh, except that it's got no power. Princess Talanji seems like she can help us out with this. Ask her if she can give the mech a jumpstart! Once we're set, we can use this thing to mow down the Alliance, take back Zul'jan ruins, and push forward to blow up that fleet!", ["objectivesText"] = "Speak with Talanji to power up the A.F.M.O.D. Progress: Uh, can we get this thing started or what?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 30226, 30252, 36884, 36885, 36886, 36887, 58915, 58916, 58917, 131497, 211279, 237812 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147155, ["x"] = 0.502, ["y"] = 0.785 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147155, ["x"] = 0.502, ["y"] = 0.785 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.785 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54224] = { ["id"] = 54224, ["name"] = "The Battle of Zul'jan Ruins", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "General Rakera has pushed forward with de army. Raal and his forces are still grounded until we remove dis fog. You must pilot de A.F.M.O.D. and help our forces retake Zul'jan ruins. Only den can we move ahead to stop de Alliance and dis fog. Rokhan, and I will join you. De Alliance must see dat our victory is swift and decisive. I would have our enemies cower before us when dey meet dere ends. Such is de price for defiling our lands.", ["objectivesText"] = "Pilot the A.F.M.O.D. and retake Zul'jan ruins.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54225] = { ["id"] = 54225, ["name"] = "Mission Report: The Great Seal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54225 }, ["series"] = { 54231 }, ["description"] = "Your followers have sent a report regarding the mission at The Great Seal. It details that the mission was a success and that a Mission Command Table has been constructed. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the mission report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to The Great Seal?", ["rewardGold"] = 22130, ["rewardXP"] = 850, ["rewardItems"] = { 165726 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
