[54239] = { ["id"] = 54239, ["name"] = "Mission Report: Zul'jan Ruins", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54239 }, ["series"] = { 54240 }, ["description"] = "Your followers have sent a report regarding the mission at Zul'jan Ruins. It details that the mission was a success and that the power of the Loa has increased, allowing for Boons to persist longer. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the mission report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Zul'jan Ruins?", ["rewardItems"] = { 165752 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
