[54258] = { ["id"] = 54258, ["name"] = "Mission Report: Vulpera Hideaway", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54258 }, ["series"] = { 54260 }, ["description"] = "Your followers have sent a report regarding the mission at the Vulpera Hideaway. It details that the mission was a success and that a Caravan is now available for use. Deliver the report to Nathanos Blightcaller aboard The Banshee's Wail.", ["objectivesText"] = "Deliver the mission report to Nathanos Blightcaller . Progress: Do you have news regarding the mission to Vulpera Hideaway?", ["rewardItems"] = { 165803 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[54260] = { ["id"] = 54260, ["name"] = "Outpost Upgrade: Vulpera Hideaway", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54260 }, ["series"] = { 54258 }, ["description"] = "The mission at Vulpera Hideaway was a success. Well done, <name>. The Caravan Master is very thankful for our assistance and ready to return the favor. Travel to Vulpera Hideaway and speak with the Caravan Master to see what he can do for you.", ["objectivesText"] = "Talk with the Caravan Master at Vulpera Hideaway.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 147434, ["x"] = 0.568, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 864 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[54262] = { ["id"] = 54262, ["name"] = "Mission Report: Brennadam", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54262 }, ["series"] = { 54263 }, ["description"] = "Your followers have sent a report regarding the mission at Brennadam. It details that they were successful in gaining access to a Harvester mount. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", ["objectivesText"] = "Deliver the report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Brennadam?", ["rewardItems"] = { 165836, 165838 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54263] = { ["id"] = 54263, ["name"] = "Outpost Upgrade: Brennadam", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54263 }, ["series"] = { 54262 }, ["description"] = "The mission at Brennadam was a success. Well done, <name>. We now have access to what's rumored to be a very fast Harvester that you are able to ride. Sounds strange to me, but what do I know? Travel to Brennadam and enquire about this upgrade.", ["objectivesText"] = "Talk to Hank Harrison in Brennadam.", ["rewardItems"] = { 165836 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 147566, ["x"] = 0.588, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 942, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54265] = { ["id"] = 54265, ["name"] = "Orders from Azshara", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredClasses"] = { 5 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53760, 53761, 53762, 53765, 54058, 54113, 54114, 54126, 54141, 54144, 54265, 54438, 54682 }, ["series"] = { 53760, 53761, 53762, 54058, 54113, 54114, 54117, 54118, 54144, 54174, 54433 }, ["description"] = "This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power. <Kojo studies you thoughtfully.> I've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath ... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek. I'm told the naga have an altar on an island in Stormsong Valley. If you take Xal'atath there, the dagger may reveal crucial information.", ["objectivesText"] = "Retrieve Xal'atath and find the Makeshift Altar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 135793, ["x"] = 0.404667, ["y"] = 0.364667 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.404667, ["y"] = 0.364667 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 4, ["flags"] = 0 } } },
