[54269] = { ["id"] = 54269, ["name"] = "None Shall Escape", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "De Alliance are using de Dark Iron's mole machines to transport troops in and out of Zalamar. We need dose machines destroyed. We are going to establish Zalamar as our forward base to attack de Alliance's main fleet. Take out dem machines, den find Rokhan within Zalamar. He be tracking down where de Alliance general be hidin'.", ["objectivesText"] = "Destroy 4 Mole Machines.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147075, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147233, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 12, ["flags"] = 0 } } },
[54270] = { ["id"] = 54270, ["name"] = "Breaking Mirrors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "We have reports dat Telaamon, de Lightforged in charge of dis attack, can create mirror images of himself to strike us down. Two Zandalari, Witch Doctor Kejabu and Jo'chunga, have offered to go in and help fight his mirror images. I want you to ensure dey survive. Eliminating dese strange images should make Telaamon weaker, allowing you and Rokhan to slay him.", ["objectivesText"] = "Defeat Telaamon's mirror images within Zalamar. Progress: Are de Zandalari safe?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147075, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147233, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 13, ["flags"] = 0 } } },
[54271] = { ["id"] = 54271, ["name"] = "Telaamon's Purge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "Telaamon, de Lightbringer leadin' dis assault, be in Hir'eek's cave. He must be thinkin' he can take us all by himself. When he is dead, we be sendin' dis assault force into chaos, allowin' us ta be marchin' on de Alliance along de shore. And hopefully, we can be findin' de source of de fog and destroyin' it. Da three of us be ambushin' Telaamon once ya start fightin'. He ain't gettin' outta here alive.", ["objectivesText"] = "Defeat Telaamon.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147233, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 147233, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 14, ["flags"] = 0 } } },
