[54275] = { ["id"] = 54275, ["name"] = "Parting Mists", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "It be time ta face de main Alliance fleet. Dey be on da beachhead nearby. I can be feelin' da dark voodoo from dat fog nearby. Princess Talanji be wantin' ta destroy dat mojo as soon as we can. I can be gettin' us outta dis cave real fast, den we be ridin' with da princess and Rakera ta put an end ta all dis.", ["objectivesText"] = "Ride with Princess Talanji and destroy the Alliance fleet.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147233, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 15, ["flags"] = 0 } } },
[54276] = { ["id"] = 54276, ["name"] = "Trouble in Gnomeregan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54276 }, ["series"] = { 54184, 54185 }, ["description"] = "Our engineers have reported surges of electric usage in Gnomeregan recently. We need you to investigate what is going in there as soon as possible. We made contact with one of the chief engineers in charge of keeping the robots in Gnomeregan under control, and he has offered to assist us in getting inside to see what's going on.", ["objectivesText"] = "Find Micro Zoox outside of Gnomeregan in Dun Morogh.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 147641, ["x"] = 0.562, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[54280] = { ["id"] = 54280, ["name"] = "Fly Out to Meet Them", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 54139, 54140, 54156, 54157, 54207, 54208, 54211, 54212, 54213, 54224, 54244, 54249, 54269, 54270, 54271, 54275, 54280 }, ["description"] = "De Alliance scum will pay for dis! Our army is moving as fast as it can to defend our city. Ride with Raal to get back to de entrance to our city. We must stop de Alliance!", ["objectivesText"] = "Ride back to Zuldazar with Hexlord Raal .", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 147075, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 18 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 841, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 841, ["name"] = "The Fury of the Zandalari", ["orderIndex"] = 16, ["flags"] = 0 } } },
