[54282] = { ["id"] = 54282, ["name"] = "Battle of Dazar'alor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54282 }, ["description"] = "Zandalar is already under attack! My people are fleeing and de Alliance are infesting my streets. Rakera's scouts say dat Jaina Proudmoore is leading de assault. She and her kind will pay for dis brazen assault on my people. Gather your allies and push de Alliance back. We must protect my father and destroy de Alliance!", ["objectivesText"] = "Defeat Jaina Proudmoore in the Battle of Dazar'alor raid.", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 146921, ["x"] = 0.58, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "raid" },
[54284] = { ["id"] = 54284, ["name"] = "Mission Report: Castaway Point", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54284 }, ["series"] = { 54288 }, ["description"] = "Your followers have sent a report regarding the mission at Castaway Point. It details that they were successful in gaining access to an extremely large cannon. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", ["objectivesText"] = "Deliver the report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Castaway Point?", ["rewardItems"] = { 165873, 165875 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
