[54288] = { ["id"] = 54288, ["name"] = "Outpost Upgrade: Castaway Point", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54288 }, ["series"] = { 54284 }, ["description"] = "The mission at Castaway Point was a success. Well done, <name>. We now have access to a very large cannon which promises to be a fast way to travel to Tiragarde Sound. Glad that's not how I plan to get around. Travel to Castaway Point and enquire about this upgrade.", ["objectivesText"] = "Talk to Dynamite Jack in Castaway Point.", ["rewardItems"] = { 165873 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 147747, ["x"] = 0.862, ["y"] = 0.812 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
