[54300] = { ["id"] = 54300, ["name"] = "Breaking the Faith", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "De faithful are among de most revered in Zandalari society. They are an example for others to aspire to. This is not de example we want others to follow. We must respond in kind. Princess Talanji wishes for us to spare them that will see reason. Do so, if you can find any willing to surrender. For de rest, give them a swift death.", ["objectivesText"] = "Subdue 12 angered priests, druids, or prelates in the Terrace of the Chosen.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145360, ["x"] = 0.404, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145360, ["x"] = 0.404, ["y"] = 0.122 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54301] = { ["id"] = 54301, ["name"] = "Talanji's Mercy", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "I know my priests, <name>. Such an uproar did not appear out of thin air. There is much I have to atone for, but I am not yet ruler. I have not had de time to do what is needed for de faithful of Zandalar. That does not mean they deserve to suffer. Go into de Terrace of de Chosen and find them that refuse to fight. See that they get out safely. I will hold none of them accountable for de actions of others.", ["objectivesText"] = "Evacuate 10 innocent bystanders in the Terrace of the Chosen. Progress: De people of Zandalar are my first priority, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.4172, ["y"] = 0.1564 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54302] = { ["id"] = 54302, ["name"] = "The Fall of Zuldazar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "It's time, <name>. We have the Abyssal Scepter, along with confirmation that the bombs placed amongst the Zandalari fleet are still active. Unfortunately, even with everything at our disposal, we would still lose a frontal assault against the Zandalari empire. For that reason, we plan to lure the forces of the Horde and the Zandalari away from the harbor. Mathias Shaw is holding a meeting nearby, and he has requested your presence.", ["objectivesText"] = "Speak with Mathias Shaw in the garden within Proudmoore Keep. Progress: I take it you and the Lord Admiral were able to send the Horde packing?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 147798, ["x"] = 0.388, ["y"] = 0.774 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54303] = { ["id"] = 54303, ["name"] = "The March to Nazmir", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "Greetings, <name>. I am Blademaster Telaamon , and I have volunteered to lead this mission against the Horde. Our forces will be gathering off the coast of Nazmir. Go now and we shall all meet there. If all goes according to plan, we will lure the Horde away from Zandalar and bring an end to this war.", ["objectivesText"] = "Meet Jaina Proudmoore and the Alliance army in Nazmir.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 147819, ["x"] = 0.388, ["y"] = 0.766 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.766 }, ["mapCandidates"] = { ["npc"] = { 863, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54306] = { ["id"] = 54306, ["name"] = "Mission Report: Arom's Stand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54306 }, ["series"] = { 54307 }, ["description"] = "Your followers have sent a report regarding the mission at Arom's Stand. It details that they were successful in gaining access to a blessing from the Order of Embers. Deliver the report to High Commander Wyrmbane aboard the Wind's Redemption.", ["objectivesText"] = "Deliver the report to Halford Wyrmbane . Progress: Do you have news regarding the mission to Arom's Stand?", ["rewardItems"] = { 165880, 165882 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
