[54310] = { ["id"] = 54310, ["name"] = "Repurposing Their Village", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "Myself and Shaw will provide support for Telaamon's army until our distraction is set up. First, we need to clear the blood trolls out of their nearby village, Zalamar, in order to move our army forward. That's where you come in. We need you to assault the blood trolls there to weaken their forces, then our army will arrive. Telaamon will be on site to help you, meet with him once you've weakened their forces. I will be here with Shaw ensuring our forces aren't seen.", ["objectivesText"] = "Defeat 12 blood trolls within Zalamar. Progress: We must move, time is of the essence.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147844, ["x"] = 0.397, ["y"] = 0.5945 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.376333, ["y"] = 0.563 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54312] = { ["id"] = 54312, ["name"] = "Fog of War", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "Do not mind this, I am finishing off this insect. You have bigger matters to handle. Our army is moving within Zalamar as we speak. But the Horde will know our army's true size without aid. Speak with Brother Pike and have him perform the ritual with the Abyssal Scepter to cover Nazmir in a thick fog. He claims the illusion will also mimic an entire fleet off the beach. Let us hope he is right. I will join you once I finish with this stain upon Azeroth.", ["objectivesText"] = "Have Brother Pike use the Abyssal Scepter. Progress: We don't have time to discuss this, <name>. We must begin.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 81814, 81815, 81816, 81817, 81818 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147844, ["x"] = 0.397, ["y"] = 0.5945 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.5945 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 4, ["flags"] = 0 } } },
