[54346] = { ["id"] = 54346, ["name"] = "Darkshore Donations: Gold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54346 }, ["description"] = "Our friends here are accepting all kinds of donations on behalf of the war effort, but if ya ask me, no battle was ever won without proper funding. That's right, bub. I'm talking about money! And lots of it. If you got it, we need it!", ["objectivesText"] = "Donate 1000000 Gold to Paymaster Grintooth in the Port of Zandalar. Progress: A <class> like you's surely gotta have a little extra cash in your stash. Waddaya say? Lemme help lighten your load a bit?", ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142157, ["x"] = 0.515, ["y"] = 0.952 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.952 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
