[54348] = { ["id"] = 54348, ["name"] = "Darkshore Donations: Deep Sea Satin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54348 }, ["objectivesText"] = "Progress: If we're going to keep our casters clothed, we'll need to make sure our stockpile is ready. If you find yourself swimming in an abundance of deep sea satin I'd be happy to send them along to our stores.", ["rewardItems"] = { 152577 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 142975, ["x"] = 0.524667, ["y"] = 0.934667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142975, ["x"] = 0.524667, ["y"] = 0.934667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.934667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[54350] = { ["id"] = 54350, ["name"] = "Darkshore Donations: Tidespray Linen Net", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54350 }, ["objectivesText"] = "Progress: If we're going to handle our enemies rushing our allies, we'll need something sturdy to slow them down. I've heard tailors can produce some fine netting. Would you happen to have any?", ["rewardItems"] = { 159791 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 142975, ["x"] = 0.524667, ["y"] = 0.934667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 142975, ["x"] = 0.524667, ["y"] = 0.934667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.524667, ["y"] = 0.934667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
