[54365] = { ["id"] = 54365, ["name"] = "Darkshore Donations: Storm Silver Ore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54365 }, ["objectivesText"] = "Gather 30 Battle Flag: Spirit of Freedom for Faella in Boralus Harbor. Progress: Our miners work their hands down to the bone gathering materials fer us, but they can only find so much. Ye wouldn't happen ta have any spare storm silver, would ye?", ["rewardItems"] = { 152579 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142994, ["x"] = 0.662, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142994, ["x"] = 0.662, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54366] = { ["id"] = 54366, ["name"] = "Darkshore Donations: Winter's Kiss", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54366 }, ["objectivesText"] = "Gather 30 Battle Flag: Phalanx Defense for Faella in Boralus Harbor. Progress: Our winter's kiss supplies are running low. You wouldn't happen to be an herbalist? Or know an herbalist? Or have some winter's kiss with you?", ["rewardItems"] = { 152508 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54367] = { ["id"] = 54367, ["name"] = "Darkshore Donations: Platinum Ore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54367 }, ["objectivesText"] = "Gather 10 Battle Flag: Phalanx Defense for Faella in Boralus Harbor. Progress: Ore isn't easy ta come by nowadays and platinum ore is even harder. But if ye have any ta spare, it would go a long way.", ["rewardItems"] = { 152513 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142994, ["x"] = 0.662, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142994, ["x"] = 0.662, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.662, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54368] = { ["id"] = 54368, ["name"] = "Darkshore Donations: Unstable Temporal Time Shifter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54368 }, ["description"] = "It's time we snuff out the competition, don't you agree? With your help we can ensure our allies receive the necessary goods and armor to prepare for the battle to come. Let's make sure our allies are well prepared.", ["objectivesText"] = "Donate 2 Coarse Leather to Charlane in Boralus Harbor. Progress: Our healers are spread thin and we need alternative methods to handle our fallen troops.", ["rewardItems"] = { 158379 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54369] = { ["id"] = 54369, ["name"] = "Darkshore Donations: Electroshock Mount Motivator", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54369 }, ["description"] = "I'll keep it simple: we need more Shimmerscale! I apologize for being so forward with you, but there's little time to waste. If you happen upon this item throughout your travels I'd be more than happy to put it to good use. Outfitting our allies is of the utmost importance in the battle to come, don't you agree?", ["objectivesText"] = "Donate 2 Shimmerscale to Charlane in Boralus Harbor. Progress: Outfitting our allies is of the utmost importance. This provides us the necessary materials to ensure no one is left lagging behind on the battlefield.", ["rewardItems"] = { 153573 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54370] = { ["id"] = 54370, ["name"] = "Darkshore Donations: XA-1000 Surface Skimmer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54370 }, ["description"] = "Ye look like the kind o' <lad/lass> that ought ta be carryin' loads o' ore around with ya! If my assumption is right about ye, we could use yer help to gather a bit more ore for the war effort. Have ye any ore ta spare?", ["objectivesText"] = "Gather 2 Monelite Ore to Brandal Darkbeard in Boralus Harbor. Progress: The battle may take to the sea, and we need deployable means of dealing with our enemies.", ["rewardItems"] = { 153512 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54371] = { ["id"] = 54371, ["name"] = "Darkshore Donations: Thermo-Accelerated Plague Spreader", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54371 }, ["description"] = "It's not just our allies we need to protect in the upcoming battle, but our equine friends as well! Can you lend a hand and ensure our allies receive the best possible armor for the battle ahead?", ["objectivesText"] = "Gather 3 Coarse Leather Barding for Charlane in Boralus Harbor. Progress: Our allies are in need of offensive choices in the battle to come.", ["rewardItems"] = { 153494 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143008, ["x"] = 0.664667, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.254667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54372] = { ["id"] = 54372, ["name"] = "Darkshore Donations: Umbra Shard", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54372 }, ["objectivesText"] = "Donate 3 Drums of the Maelstrom to Charlane in Boralus Harbor. Progress: Battles are won by those with power. Power comes from within oneself. But enchantments help too and our supplies are running low.", ["rewardItems"] = { 152876 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143007, ["x"] = 0.664667, ["y"] = 0.253333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.664667, ["y"] = 0.253333 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
