[54376] = { ["id"] = 54376, ["name"] = "Darkshore Donations: Potion of Replenishment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54376 }, ["objectivesText"] = "Gather 2 War-Scroll of Battle Shout for Liao in Boralus Harbor. Progress: With preparation comes success.", ["rewardItems"] = { 152561 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54377] = { ["id"] = 54377, ["name"] = "Darkshore Donations: Crimson Ink", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54377 }, ["description"] = "Enlightenment guides our path to victory. In battle, we fight as one. Share your knowledge and skills with me. Generosity is never forgotten.", ["objectivesText"] = "Gather 20 War-Scroll of Intellect for Liao in Boralus Harbor. Progress: Enlightenment presents opportunity for victory.", ["rewardItems"] = { 158188 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143005, ["x"] = 0.674, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54378] = { ["id"] = 54378, ["name"] = "Darkshore Donations: Potion of Bursting Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54378 }, ["objectivesText"] = "Gather 2 War-Scroll of Fortitude for Liao in Boralus Harbor. Progress: The opportunity for strength and fortitude present themselves when facing difficult situations.", ["rewardItems"] = { 152560 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142993, ["x"] = 0.665, ["y"] = 0.238 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.238 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54379] = { ["id"] = 54379, ["name"] = "Darkshore Donations: Contract: 7th Legion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54379 }, ["description"] = "Greetings! With the war effort in full swing I'll be your point of contact for herbalism and alchemical donations! It's a pleasure to meet you! Now, let's see here... Ah, yes. Siren's Pollen. It appears our stockpiles reported a shortage as of late last night. It would be a great help to us all if you were able to donate to our efforts.", ["objectivesText"] = "Gather 3 Siren's Pollen for Chelsea Strand in Boralus Harbor. Progress: Have some contracts for me?", ["rewardItems"] = { 165016 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143005, ["x"] = 0.674, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54380] = { ["id"] = 54380, ["name"] = "Darkshore Donations: Gold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54380 }, ["description"] = "We've spent a great deal of time and resources preparing for the battle to come. As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?", ["objectivesText"] = "Donate 1000000 Gold to Paymaster Vauldren in Boralus Harbor. Progress: As we begin final preparations, we'll be setting aside additional funding to ensure further training and supplies are available at a moment's notice. Would you like to make a donation?", ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142685, ["x"] = 0.663, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.663, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54381] = { ["id"] = 54381, ["name"] = "Darkshore Donations: Ultramarine Ink", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54381 }, ["description"] = "Greetings, traveler. I was asked to ensure our food supplies are never left wanting and our fish supplies have been running low lately. Have anything you would care to donate?", ["objectivesText"] = "Gather 60 Grilled Catfish for Senedras in Boralus Harbor. Progress: I was asked to ensure our inscription supplies are never left wanting, though lately they have been running low. Have any ink you would care to donate?", ["rewardItems"] = { 158187 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143005, ["x"] = 0.674, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54382] = { ["id"] = 54382, ["name"] = "Darkshore Donations: Deep Sea Satin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54382 }, ["description"] = "Fish--it's what's for dinner! Or so say our supply officers. And this weeks meals are based around one delicious ingredient--catfish. If we're going to keep our allies well fed and full of fish we'll need to gather more stock and begin meal preparations soon. If you find yourself swimming in an abundance of catfish I'd be happy to send them along to our stores.", ["objectivesText"] = "Gather 30 Great Sea Catfish for Senedras in Boralus Harbor. Progress: If we're going to keep our casters clothed, we'll need to make sure our stockpile is ready. If you find yourself swimming in an abundance of deep sea satin I'd be happy to send them along to our stores.", ["rewardItems"] = { 152577 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54383] = { ["id"] = 54383, ["name"] = "Darkshore Donations: Shimmerscale Diving Suit", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54383 }, ["description"] = "Hey there! Transmission's come down from up top--we need more ammunition! Something with a bit more kick. Something really unexpected! From what I've heard there's a special frost-based ammunition crafted only by the most experienced engineers. If you were to bring me a few I'm sure our munitions officers would be ecstatic! Maybe they'd even let me keep one to examine!", ["objectivesText"] = "Gather 3 Frost-Laced Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: I've heard there's a special underwater suit that's crafted by the most experienced of leatherworkers. If you were to bring me a few of these I'm sure our aquatic forces would be ecstatic!", ["rewardItems"] = { 154168 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54384] = { ["id"] = 54384, ["name"] = "Darkshore Donations: Tidespray Linen Net", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54384 }, ["description"] = "Though our ammunition stockpiles are faring well, it's my duty to find additional resources, especially those that are harder to come by. Today I'm looking for a specific type of ammunition, one with incendiary properties. I could really use your help tracking a few of these down.", ["objectivesText"] = "Gather 5 Incendiary Ammunition for Norber Togglesprocket in Boralus Harbor. Progress: If we're going to handle our enemies rushing our allies, we'll need something sturdy to slow them down. I've heard tailors can produce some fine netting. Would you happen to have any?", ["rewardItems"] = { 159791 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54385] = { ["id"] = 54385, ["name"] = "Darkshore Donations: Tidespray Linen Bandage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54385 }, ["objectivesText"] = "Progress: Bandages go a long way on the battlefield, especially when our healers are spread thin. Do you have any to spare?", ["rewardItems"] = { 158381 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54386] = { ["id"] = 54386, ["name"] = "Darkshore Donations: Deep Sea Bandage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54386 }, ["description"] = "You never know when you'll need to deliver a big bang on the battlefield, if you know what I mean. Luckily we can plan for the unexpected! We've begun to store a special stockpile of explosives for scenarios where we'll need a little something extra to get our point across. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.", ["objectivesText"] = "Gather 10 F.R.I.E.D. for Norber Togglesprocket in Boralus Harbor. Progress: We've started a special stockpile of bandages for scenarios where we'll need a little something extra to keep our allies going. I've added one particular item to the list. If you have any to spare I'll make sure they're put to good use.", ["rewardItems"] = { 158382 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142998, ["x"] = 0.669, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.669, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54387] = { ["id"] = 54387, ["name"] = "Darkshore Donations: Blood-Stained Bone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54387 }, ["objectivesText"] = "Gather 20 Enchant Ring - Seal of Versatility for Mae Wagglewand in Boralus Harbor. Progress: I know it's short notice, but I'm trying to find a few more bones to add to our next shipment.", ["rewardItems"] = { 154164 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54388] = { ["id"] = 54388, ["name"] = "Darkshore Donations: Shimmerscale Diving Helmet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54388 }, ["objectivesText"] = "Gather 5 Enchant Ring - Seal of Critical Strike for Mae Wagglewand in Boralus Harbor. Progress: I was just about done filling orders for the next shipment then realized I was out of diving helmets! Do you think you can help me fill the remaining orders?", ["rewardItems"] = { 154169 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54389] = { ["id"] = 54389, ["name"] = "Darkshore Donations: Mistscale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54389 }, ["objectivesText"] = "Gather 100 Enchant Weapon - Stalwart Navigation for Mae Wagglewand in Boralus Harbor. Progress: I've been able to keep pace with our orders until recently. Now I'm afraid I won't be able to keep up without help. Would you be willing to donate a few supplies?", ["rewardItems"] = { 153051 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142995, ["x"] = 0.67, ["y"] = 0.287 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.287 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54390] = { ["id"] = 54390, ["name"] = "Darkshore Donations: Masterful Kubiline", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54390 }, ["description"] = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", ["objectivesText"] = "Gather 20 Seasoned Loins for Senedras in Boralus Harbor. Progress: Our jewelcrafters work night and day preparing gems for the battle to come. If you have any spare cut gems, it would help alleviate their burden.", ["rewardItems"] = { 153713 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143004, ["x"] = 0.675, ["y"] = 0.241 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.241 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54391] = { ["id"] = 54391, ["name"] = "Darkshore Donations: Quick Golden Beryl", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54391 }, ["description"] = "A nice, hearty meat provides the nourishment our allies deserve before shipping off to battle, not to mention it also makes quite a stew, something our troops seem to rather enjoy when the winds are at their best and the chill of night lingers in the air. If you bring me some freshly seasoned loins I would be more than happy to deliver it to our supply officers.", ["objectivesText"] = "Gather 20 Seasoned Loins for Senedras in Boralus Harbor. Progress: Enhancement gems go a long way. If we're to endure the battle, we've got to be prepared.", ["rewardItems"] = { 153711 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143004, ["x"] = 0.675, ["y"] = 0.241 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.241 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54392] = { ["id"] = 54392, ["name"] = "Darkshore Donations: Sand Shifter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54392 }, ["description"] = "In times like this it's important ta be ready fer battle at a moments notice. Outfittin' our beasts with proper stirrups is a step in the right direction. If yer able ta bring me a few I'll be sure they're put ta good use.", ["objectivesText"] = "Gather 30 Monel-Hardened Stirrups for Brandal Darkbeard in Boralus Harbor. Progress: Our food supplies are running low. Specifically our supply of fish. Would you happen to be a master angler?", ["rewardItems"] = { 152543 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54393] = { ["id"] = 54393, ["name"] = "Darkshore Donations: Scarlet Diamond", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54393 }, ["description"] = "Battles aren't decided by which side has the best armor, or the sharpest blades, but it sure does help! Matter o' fact is it's not just ye allies needin' help, but our beasts of battle as well. If ye can provide any additional hoofplates fer our brave beasts I'll be sure ta have our farriers take good care of 'em.", ["objectivesText"] = "Gather 20 Monel-Hardened Hoofplates for Brandal Darkbeard in Boralus Harbor. Progress: We have our own jewelcrafters hard at work, adoring armor with their special cuts. However, our supply of raw gems is rather low. Have you any to spare?", ["rewardItems"] = { 154121 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143004, ["x"] = 0.675, ["y"] = 0.241 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.675, ["y"] = 0.241 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54394] = { ["id"] = 54394, ["name"] = "Darkshore Donations: Stringy Loins", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54394 }, ["description"] = "One of our latest shipments of alchemical supplies was raided en route to storage. We're scrambling to get our stock back on track, but I'm worried we won't make our quota. You wouldn't happen to know where one can acquire additional mana potions, would you?", ["objectivesText"] = "Bring 30 Coastal Mana Potions to Chelsea Strand in Boralus Harbor. Progress: Our food stock has been running low trying to keep everyone fed. Do you have any supplies you can spare?", ["rewardItems"] = { 154897 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54395] = { ["id"] = 54395, ["name"] = "Darkshore Donations: Seasoned Steak and Potatoes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54395 }, ["description"] = "I've received word our allies are looking to stash away a few supplementary items for the battle to come. If you happen to stumble across a few Coastal Healing Potions I'd be more than happy to add them to our stores.", ["objectivesText"] = "Gather 40 Coastal Healing Potions for Chelsea Strand in Boralus Harbor. Progress: A hearty meal provides the nourishment our allies deserve. If you bring me some freshly seasoned steak and potatoes I would be more than happy to deliver it to our supply officers.", ["rewardItems"] = { 166344 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54396] = { ["id"] = 54396, ["name"] = "Darkshore Donations: Wild Berry Bread", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54396 }, ["objectivesText"] = "Gather 40 Steelskin Potions for Chelsea Strand in Boralus Harbor. Progress: Have you heard of this new dessert the chefs are making? I think it's called Wild Berry Bread . You wouldn't happen to have any, would you?", ["rewardItems"] = { 166343 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142997, ["x"] = 0.668, ["y"] = 0.274 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.274 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54402] = { ["id"] = 54402, ["name"] = "Shifting Gears", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54402, 54576, 54577, 54580, 54581, 54582, 54639, 54640, 54641, 54642, 54850 }, ["description"] = "<name>! The Alliance has made a new request for Gnomeregan's might. Captain Sparknozzle wishes for your expert assistance in the matter. He'll be waiting for you in New Tinkertown, outside of Gnomeregan.", ["objectivesText"] = "Meet Captain Tread Sparknozzle in New Tinkertown.", ["rewardGold"] = 157900, ["rewardXP"] = 3410, ["rewardItems"] = { 168862, 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 147939, ["x"] = 0.546, ["y"] = 0.184667 } }, ["ends"] = { { ["mapID"] = 469, ["npcID"] = 147943, ["x"] = 0.418, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.184667 }, ["mapCandidates"] = { ["npc"] = { 84, 469 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 858, ["name"] = "Gnome Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54403] = { ["id"] = 54403, ["name"] = "Tidesage Clarissa", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 54403 }, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 260, ["db2QuestInfoName"] = "Faction Assault Elite World Quest", ["db2VignetteID"] = 3434, ["db2VignetteName"] = "Tidesage Clarissa" },
[54404] = { ["id"] = 54404, ["name"] = "Dark Iron Machinations", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "We have some additional support for our plan to deceive the Horde and assault the Blood Gates, but we need your help. The Dark Iron dwarves have several mole machines waiting to erupt and supply fresh troops. I've determined several spots within Zalamar that would be perfect for them to use. Take this device and plant it in the following areas. It will send a message to the Dark Iron dwarves to erupt from there. They will stay safely in their machines until our army arrives.", ["objectivesText"] = "Mark 3 areas within Zalamar for mole machines to appear.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147843, ["x"] = 0.3915, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147844, ["x"] = 0.397, ["y"] = 0.5945 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54407] = { ["id"] = 54407, ["name"] = "Lurking in the Swamp", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "We have Zalamar, and we've got our fog. Now, we have to take the attack to the Horde. Our goal is to take as much land in Nazmir as possible to make the Horde think our main fleet is here. The first target is Zul'jan ruins, one of the Horde's main bases in Nazmir. We'll have to make our way through the swamps to our attack position. Meet us there.", ["objectivesText"] = "Meet with Jaina Proudmoore outside of Zul'jan ruins.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.376333, ["y"] = 0.563 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54412] = { ["id"] = 54412, ["name"] = "Zul'jan Deluge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "Through the mists is Zul'jan ruins, a major Horde outpost in Nazmir. We need to take it over to help our forces push forward. The Horde needs to believe a large Alliance army is here, so we're going to throw everything we've got at taking the ruins. Our army will charge forward to attack, while you join them using my water elemental . Meet me outside of the ruins when you're done, we'll need to keep pushing forward.", ["objectivesText"] = "Use Jaina's Water Elemental to clear out Zul'jan Ruins.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.376333, ["y"] = 0.563 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 6, ["flags"] = 0 } } },
