[54415] = { ["id"] = 54415, ["name"] = "Vulpera for a Day", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 54415 }, ["objectivesText"] = "Talk to Nisha Voldunai protected Pick Up Banner Use Banner Inspire Voldunai Extinguish Fires Free Prisoners Kill Alliance Small Kill Medium Alliance Kill Large Alliance", ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8501 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Talk to Nisha", ["amount"] = 1, ["type"] = 0, ["objectID"] = 148458, ["orderIndex"] = 0 }, { ["text"] = "Voldunai protected", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Pick Up Banner", ["amount"] = 20, ["type"] = 0, ["objectID"] = 148447, ["orderIndex"] = 2 }, { ["text"] = "Use Banner", ["amount"] = 50, ["type"] = 0, ["objectID"] = 148448, ["orderIndex"] = 3 }, { ["text"] = "Inspire Voldunai", ["amount"] = 100, ["type"] = 0, ["objectID"] = 148449, ["orderIndex"] = 4 }, { ["text"] = "Extinguish Fires", ["amount"] = 13, ["type"] = 0, ["objectID"] = 148503, ["orderIndex"] = 5 }, { ["text"] = "Free Prisoners", ["amount"] = 20, ["type"] = 0, ["objectID"] = 148461, ["orderIndex"] = 6 }, { ["text"] = "Kill Alliance Small", ["amount"] = 34, ["type"] = 0, ["objectID"] = 148462, ["orderIndex"] = 7 }, { ["text"] = "Kill Medium Alliance", ["amount"] = 20, ["type"] = 0, ["objectID"] = 148463, ["orderIndex"] = 8 }, { ["text"] = "Kill Large Alliance", ["amount"] = 13, ["type"] = 0, ["objectID"] = 148464, ["orderIndex"] = 9 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["db2QuestInfoID"] = 259, ["db2QuestInfoName"] = "Faction Assault World Quest" },
[54416] = { ["id"] = 54416, ["name"] = "Warfront Preparations", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10226, ["mapID"] = 1165, ["storyline"] = { 53955, 54042, 54043, 54044, 54045, 54046, 54047, 54049, 54050, 54059, 54416 }, ["description"] = "We must make our preparations. Return to Zandalar immediately and rally our forces. Any contributions to our cause must be made. Go. We will hold for now.", ["objectivesText"] = "Take the portal back to the Port of Zandalar to prepare for the Battle for Darkshore .", ["rewardGold"] = 23400, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 10226 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 856, ["name"] = "In Darkest Night", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54417] = { ["id"] = 54417, ["name"] = "Showing Our Might", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "We are within reach of the Blood Gate in Zandalar. Once we take that, the Horde and Zandalari will believe our full invasion has begun. Our forces have already engaged the Zandalari within the Fallen Outpost. We'll need your help to push them back. I'll be focusing on finishing off what remains of the Horde and Zandalari back in Zul'jan ruins.", ["objectivesText"] = "Defeat 12 Zandalari forces within the Fallen Outpost.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.376333, ["y"] = 0.563 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54418] = { ["id"] = 54418, ["name"] = "The Mech of Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "We have reports of a goblin machine causing havoc among our troops up ahead. They call it the A.M.O.D. It is a crude machine compared to what the Lightforged have aboard the Vindicaar. Together, you and I will bring down this machine. Go, I will await for you near the machine and engage it when you are ready.", ["objectivesText"] = "Defeat the A.M.O.D.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147844, ["x"] = 0.397, ["y"] = 0.5945 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147844, ["x"] = 0.397, ["y"] = 0.5945 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.397, ["y"] = 0.5945 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54419] = { ["id"] = 54419, ["name"] = "Quelling the Masses", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "One of my own in de Rastari has seen fit to rile de drudges and guards in de Zocalo. They threaten de stability of our empire with this foolishness. If they are angry, we can address it. But this wanton destruction will not stand. Go down into de market of de Zocalo and bring about calm however you can. Choose de method that works for you. I care only for de result: Peace, so Talanji can finally be crowned.", ["objectivesText"] = "Subdue 12 rioters in the Zocalo.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 145360, ["x"] = 0.404, ["y"] = 0.122 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 145359, ["x"] = 0.4172, ["y"] = 0.1564 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.404, ["y"] = 0.122 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54421] = { ["id"] = 54421, ["name"] = "Taming their Beasts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "Our goal is to assault the Blood Gate, but to be blunt, we don't have the force necessary for this. That's why we have gnomish technology. The Zandalari have battle beasts, direhorns mounted with powerful weapons. Several of these beasts are resting within the Fallen Outpost. This device, the Re-Discombobulator , will give us control over these animals. Take this device and use it on these battle beasts. We'll assault the Blood Gates once we have them under our control.", ["objectivesText"] = "Use the Re-Discombobulator to control 3 battle beasts.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 166230 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147843, ["x"] = 0.3915, ["y"] = 0.5545 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147843, ["x"] = 0.3915, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.3915, ["y"] = 0.5545 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54424] = { ["id"] = 54424, ["name"] = "A Shady Character", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54424 }, ["description"] = "Your followers tell of a smuggler of wit and guile, who was able to charm them with stories of lands far and wide. Though it cost a fair sum to retrieve, they managed to obtain a token which when displayed to the smuggler, will allow the bearer to purchase his wares.", ["objectivesText"] = "Deliver the token to the shady character under the bridge. Progress: Do you really think you should be talking to me?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 165946 }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 148024, ["x"] = 0.695333, ["y"] = 0.184 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.695333, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[54433] = { ["id"] = 54433, ["name"] = "Orders from Azshara", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53760, 53761, 53762, 53763, 53766, 54058, 54117, 54118, 54172, 54174, 54433, 54439, 54683 }, ["series"] = { 53760, 53761, 53762, 54058, 54113, 54114, 54117, 54118, 54144, 54174, 54265 }, ["description"] = "This medallion is inscribed with orders commanding the naga to invade our shores and seize artifacts of power. <Kojo studies you thoughtfully.> I've heard tales of a priest who used a horrifying dagger to fight the Burning Legion. It is said this blade... Xal'atath ... whispers secrets of the deep. It might be our best chance of uncovering what the naga seek. I recently came upon a makeshift naga altar in Atal'Gral. If you take Xal'atath there, the dagger may reveal crucial information.", ["objectivesText"] = "Retrieve Xal'atath and find the Makeshift Altar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 134345, ["x"] = 0.714, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54434] = { ["id"] = 54434, ["name"] = "Voidmaster Evenshade", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 54434 }, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 260, ["db2QuestInfoName"] = "Faction Assault Elite World Quest", ["db2VignetteID"] = 3433, ["db2VignetteName"] = "Voidmaster Evenshade" },
[54436] = { ["id"] = 54436, ["name"] = "Wisp'd Into Shape", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 54436 }, ["description"] = "We're off to a good start, but we're going to need more wood if we want to win this battle! The Horde has set up a lumber mill to the north of Bashal'Aran, past Forlorn Crossing. If we take it, we can stop them from destroying the forest while also getting the wisps to help us out. It's a two-for-one!", ["objectivesText"] = "Capture Cinderfall Grove and inspire the wisps to help you. Progress: We need that additional wood from Cinderfall!", ["rewardXP"] = 3410, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
[54437] = { ["id"] = 54437, ["name"] = "Owynn Graddock", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "elite" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 54437 }, ["rewardGold"] = 309800, ["rewardXP"] = 2125, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9042 } }, ["questType"] = "world", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["db2QuestInfoID"] = 260, ["db2QuestInfoName"] = "Faction Assault Elite World Quest", ["db2VignetteID"] = 3436, ["db2VignetteName"] = "Owynn Graddock" },
[54438] = { ["id"] = 54438, ["name"] = "Crucible of Storms: Relics of Shadow", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53760, 53761, 53762, 53765, 54058, 54113, 54114, 54126, 54141, 54144, 54265, 54438, 54682 }, ["description"] = "Your intention to stop the naga attacks was noble, <name>. But that shadowy dagger tricked you into delivering powerful relics into the hands of a great enemy. No doubt those artifacts will be well defended. Gather your allies, <class>, and return to the Crucible of Storms. Defeat any opponents that stand in your way. Ensure the relics cannot be used against the Alliance. The naga cannot be allowed to summon their storm... or to call forth something even worse.", ["objectivesText"] = "Stop Uu'nat within the Crucible of Storms.", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 146902, ["x"] = 0.675333, ["y"] = 0.212667 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 146902, ["x"] = 0.675333, ["y"] = 0.212667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.675333, ["y"] = 0.212667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 18, ["flags"] = 0 } } },
[54439] = { ["id"] = 54439, ["name"] = "Crucible of Storms: Relics of Shadow", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53760, 53761, 53762, 53763, 53766, 54058, 54117, 54118, 54172, 54174, 54433, 54439, 54683 }, ["description"] = "Your intention to stop de naga attacks was noble, <name>. But de talking dagger tricked you into delivering powerful relics into de hands of our enemies. No doubt dese artifacts will be well defended. Gather your allies, <class>, and return to de Crucible of Storms. Defeat any opponents dat stand in your way. Ensure dese relics cannot be used against de Horde. And if any shadowy weapons ask you to do favors for dem in de future... I suggest you decline.", ["objectivesText"] = "Stop Uu'nat within the Crucible of Storms.", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["rewardItems"] = { 164761, 165605, 168123 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.473333, ["y"] = 0.340667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 851, ["name"] = "Crucible of Storms", ["orderIndex"] = 19, ["flags"] = 0 } } },
[54441] = { ["id"] = 54441, ["name"] = "Taking the Blood Gate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54302, 54303, 54310, 54312, 54404, 54407, 54412, 54417, 54418, 54421, 54441, 54459 }, ["description"] = "We have our forces spread out throughout Nazmir, but we need to do something that will force Rastakhan into action. We must personally march into Zuldazar and take the Blood Gate. This will cause them to throw their full army at us. As you can see, we're the only ones left that can assault the Blood Gate. Shaw and Telaamon will stay behind to help the rest of the army move up. You and I will ride the battle beast into the Blood Gate and take it by force.", ["objectivesText"] = "Ride the battlebeast and defeat the Zandalari army at the Blood Gates.", ["rewardGold"] = 30300, ["rewardXP"] = 850, ["rewardItems"] = { 166230 }, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 147842, ["x"] = 0.376333, ["y"] = 0.563 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 147843, ["x"] = 0.3915, ["y"] = 0.5545 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.376333, ["y"] = 0.563 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 17 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 845, ["questLineOrder"] = 10 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 845, ["name"] = "Fog of War", ["orderIndex"] = 10, ["flags"] = 0 } } },
