[54451] = { ["id"] = 54451, ["name"] = "Baubles from the Seekers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54451 }, ["description"] = "We Tortollan's appreciate all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", ["objectivesText"] = "Speak with Collector Kojo .", ["rewardItems"] = { 166245 }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 134345, ["x"] = 0.714, ["y"] = 0.302 }, { ["mapID"] = 942, ["npcID"] = 135793, ["x"] = 0.404667, ["y"] = 0.364667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2387, ["threshold"] = 10000 } } } },
