[54576] = { ["id"] = 54576, ["name"] = "Gnomeregan's Finest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 54402, 54576, 54577, 54580, 54581, 54582, 54639, 54640, 54641, 54642, 54850 }, ["description"] = "The leaders of the Alliance have agreed to fund an elite gnomish aerial task force. And you have been chosen to lead the test team for the Gnomish Elite Aerial Rangers. I have assembled some of the finest tinkers and soldiers from Gnomeregan, who are now under your command. The three of them are already here in New Tinkertown. Introduce yourself and assemble them.", ["objectivesText"] = "Speak with the three members of your G.E.A.R. team. Progress: Speak up, soldier!", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 168862 }, ["starts"] = { { ["mapID"] = 469, ["npcID"] = 147943, ["x"] = 0.418, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 469, ["npcID"] = 147943, ["x"] = 0.418, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 469, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 858, ["name"] = "Gnome Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54577] = { ["id"] = 54577, ["name"] = "Shadowed Halls and Dusty Cogs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 54402, 54576, 54577, 54580, 54581, 54582, 54639, 54640, 54641, 54642, 54850 }, ["description"] = "An elite aerial unit wouldn't be complete without the newest innovations in flying machine technology. There's just one small problem. The innovative new engine we built was left behind when we evacuated Gnomeregan. We need that prototype if we want these bombers to safely get off the ground!", ["objectivesText"] = "Find the Prototype Arcane Engine within the Engineering Labs of Gnomeregan. Progress: Did you find the engine?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 168862 }, ["starts"] = { { ["mapID"] = 469, ["npcID"] = 147943, ["x"] = 0.418, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 469, ["npcID"] = 147943, ["x"] = 0.418, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 469, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 469, ["questLines"] = { { ["id"] = 858, ["name"] = "Gnome Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54579] = { ["id"] = 54579, ["name"] = "The Gnome Behind the Trogg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 54579 }, ["description"] = "If I just attach the core of this to the input module here... Amplify the matched frequency here... <Tinkerbow mumbles a few more things while she attaches the communication device to the console.> Flip the switch, Commander! Just make sure it's the right one. The left one is the self-destruct switch. Or was that reversed...", ["objectivesText"] = "Help Tinkerbow get the machine working. Progress: Yes?", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 147952, ["x"] = 0.554, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 147952, ["x"] = 0.554, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard" },
[54580] = { ["id"] = 54580, ["name"] = "A Tundra Conundrum", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6457, ["mapID"] = 469, ["storyline"] = { 54402, 54576, 54577, 54580, 54581, 54582, 54639, 54640, 54641, 54642, 54850 }, ["description"] = "While you were in Gnomeregan, we received a distress signal from Fizzcrank Airstrip in Borean Tundra. This seems like the perfect opportunity to show off what G.E.A.R. can do! I've sent the rest of your squad ahead. Meet them out there.", ["objectivesText"] = "Speak with Cog Captain Winklespring at Fizzcrank Airstrip in Borean Tundra.", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 469, ["npcID"] = 147943, ["x"] = 0.418, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 147950, ["x"] = 0.436667, ["y"] = 0.572667 } }, ["coords"] = { ["mapID"] = 469, ["source"] = "quest_giver", ["x"] = 0.418, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 120, 469 }, ["zone"] = { 6457 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 858, ["name"] = "Gnome Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54581] = { ["id"] = 54581, ["name"] = "Now With More Mechanical Fowl", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 54402, 54576, 54577, 54580, 54581, 54582, 54639, 54640, 54641, 54642, 54850 }, ["series"] = { 54582 }, ["description"] = "The gnomes here report that troggs came down from the north and started attacking everygnome and everything. So now it's our job to fix this situation! And luckily, I have the perfect plan for it. We need to calibrate the bomber's gun, and doing so on the ground is much less risky than up in the air. Give it a go, Commander!", ["objectivesText"] = "Kill 10 Ironbound Brutes or Scrapthrowers.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 147952, ["x"] = 0.554, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 858, ["name"] = "Gnome Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54582] = { ["id"] = 54582, ["name"] = "Smarter Than Your Average Trogg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3537, ["mapID"] = 114, ["storyline"] = { 54402, 54576, 54577, 54580, 54581, 54582, 54639, 54640, 54641, 54642, 54850 }, ["series"] = { 54581 }, ["description"] = "<Cog Captain Winklespring's voice springs to life over your personal communication system.> One of the recon pilots did a scouting run over the station. She reported that there seems to be a trogg on the top level that is larger and smarter than the others. He's somehow managed to get one of the Defendo-Tanks for the station working in his favor. Take him out!", ["objectivesText"] = "Kill Krugg the Smart . Progress: Have you found out anything?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 166584 }, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 147952, ["x"] = 0.554, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 3537 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 858, ["name"] = "Gnome Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
