[54610] = { ["id"] = 54610, ["name"] = "Paragon of the Tortollan Seekers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 54610 }, ["description"] = "Your allies among the Tortollan Seekers have requested your presence. They wish to reward you for your continued efforts on their behalf.", ["objectivesText"] = "Speak with Collector Kojo .", ["ends"] = { { ["mapID"] = 862, ["npcID"] = 134345, ["x"] = 0.714, ["y"] = 0.302 }, { ["mapID"] = 942, ["npcID"] = 135793, ["x"] = 0.404667, ["y"] = 0.364667 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[54611] = { ["id"] = 54611, ["name"] = "Paragon of the Champions of Azeroth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 54611 }, ["description"] = "A grateful Magni Bronzebeard has requested your presence. He wishes to reward you for your exceptional aid.", ["objectivesText"] = "Speak with Magni Bronzebeard in Silithus for your reward.", ["ends"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard" },
[54613] = { ["id"] = 54613, ["name"] = "Twice-Exiled", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 54613 }, ["description"] = "Elementals of all sorts are bursting free of their bonds across the Highlands. Return them to the primordial chaos from whence they came.", ["objectivesText"] = "Kill 12 Burning, Cresting, Rumbling, or Thundering Exiles or Guardians in Arathi Highlands .", ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 45 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Elementals slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 143269, ["orderIndex"] = 0 } }, ["db2PoiUiMapID"] = 14, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[54614] = { ["id"] = 54614, ["name"] = "Executing Exorcisms", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 54614 }, ["description"] = "Even in death, the Alliance foolishly clings to Horde territory. Drive their vengeful ghosts from the ruins of Stromgarde before their foulness spreads.", ["objectivesText"] = "Kill 12 Vengeful Ghosts in Stromgarde.", ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 45 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Vengeful Ghosts slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 142723, ["orderIndex"] = 0 } }, ["db2PoiUiMapID"] = 14, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[54615] = { ["id"] = 54615, ["name"] = "The League Will Lose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 54615 }, ["description"] = "Even with the fall of Stromgarde, the League of Arathor continues to operate in the Highlands. The northern farmland will belong to the Horde. Go, and defeat the humans.", ["objectivesText"] = "Kill 12 League of Arathor at Dabyrie's Farmstead.", ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 45 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "League of Arathor slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 143239, ["orderIndex"] = 0 } }, ["db2PoiUiMapID"] = 14, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[54616] = { ["id"] = 54616, ["name"] = "Boulderfist Beatdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 45, ["mapID"] = 14, ["storyline"] = { 54616 }, ["description"] = "If the Boulderfist ogres will not join the Horde, there is no place for them in Arathi. You know what must be done.", ["objectivesText"] = "Kill 12 Boulderfist clan ogres in Arathi Highlands .", ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 45 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Boulderfist clan ogres slain", ["amount"] = 12, ["type"] = 0, ["objectID"] = 143230, ["orderIndex"] = 0 } }, ["db2PoiUiMapID"] = 14, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
