[54652] = { ["id"] = 54652, ["name"] = "The War Chest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54652 }, ["description"] = "Welcome to the warfront, <name>. I am glad we have you fighting on our side. First things first: We need to collect resources in order to strengthen our hold on Bashal'Aran and bolster our troops. Any resources that we collect will go to the War Chest. Open the chest and see what you can use.", ["objectivesText"] = "Collect resources from the War Chest in Bashal'Aran. Progress: Have you collected those resources from the War Chest?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54654] = { ["id"] = 54654, ["name"] = "An Explosive Situation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54654 }, ["description"] = "We have some iron available, but we could always use more. Get down to the mine at the Ruins of Lornesta. Seize it from any enemies, and get those goblins to do their job. Giving them something suitably destructive should do the trick.", ["objectivesText"] = "Supply Goblin Extractors with explosives at Lornesta Mine. Progress: We need more iron if we want to win this battle!", ["rewardGold"] = 309800, ["rewardXP"] = 3410, ["rewardItems"] = { 166773 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54655] = { ["id"] = 54655, ["name"] = "Lumbering Along", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54655 }, ["description"] = "We will need more lumber if we're going to build up Bashal'Aran into a proper fortress. You should find an axe in the supplies we brought in for the effort. Grab it, and see what you can do with it to help us get our base rebuilt.", ["objectivesText"] = "Pick up a Sturdy Axe , then gather 5 Freshly-Chopped Wood from the nearby Darkwood Timber. Progress: We need that wood to accomplish our goals here.", ["rewardXP"] = 3410, ["rewardItems"] = { 166387, 166713 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54656] = { ["id"] = 54656, ["name"] = "Darkshore Recruits", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54656 }, ["description"] = "We will not win unless we have the power of numbers on our side. First, we need the Barracks restored so Signe can do her work. Signe is one of the Dark Lady's val'kyr, and she can raise forces for us. Once the Barracks is built, talk to Signe and recruit a troop. I'm sure they could learn a lot from fighting alongside you.", ["objectivesText"] = "Restore the Barracks, then speak with Signe to recruit an ally. Progress: Have you recruited those troops?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54657] = { ["id"] = 54657, ["name"] = "Arms and Armor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54657 }, ["description"] = "Keever knows troops need weapons. And armor. Armor and weapons. Keever wants Archibald to make armor and weapons for troops. You listen to Keever and talk to Archibald .", ["objectivesText"] = "Speak with Archibald to learn what the Armory has to offer. Progress: We are a long way from the Undercity, yet here is where I belong.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54658] = { ["id"] = 54658, ["name"] = "The Altar of Storms", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54658 }, ["description"] = "The Altar of Storms has been rebuilt. It is a unique kind of altar. The goblin kind. Keever is pleased. Keever wishes to wield that kind of power. Go, listen to Keever, talk to little goblin Mizzyk and find what the Altar can do.", ["objectivesText"] = "Speak with Mizzyk to learn what the Altar of Storms has to offer. Progress: Keever wonders if you have seen the Altar of Storms yet.", ["rewardGold"] = 842700, ["rewardXP"] = 3135, ["rewardItems"] = { 59387, 59388, 59389, 59390, 59391, 59425, 59426, 59427, 59428, 59429 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54659] = { ["id"] = 54659, ["name"] = "An Alchemist for Everything", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54659 }, ["description"] = "When we first conquered Darkshore, we set up an Alchemy Lab on the shore at Gloomtide Strand to tap into this area's latent power. Unfortunately, things did not go so well and the Alliance have overrun the lab. Would you see them off, and then speak with Professor Blightwell to see what he can do for you?", ["objectivesText"] = "Capture Gloomtide Strand, then speak with Professor Blightwell to learn what he has to offer. Progress: Did you find anything at Gloomtide Strand?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54660] = { ["id"] = 54660, ["name"] = "Throwing Blight", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10084, ["storyline"] = { 54660 }, ["description"] = "We need more firepower, and the goblins are oh so obliging, aren't they. Zarvik in particular has honed his craft ever since our conquest of Darkshore. Why don't you talk to him and see what he's got going at the Workshop?", ["objectivesText"] = "Speak with Zarvik Blastwix to learn what the Workshop has to offer. Progress: You got anything you need built?", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10084 } }, ["questType"] = "standard" },
[54661] = { ["id"] = 54661, ["name"] = "Echolocation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10058, ["storyline"] = { 54661 }, ["description"] = "Glad you're here! These bats have got to get up and start giving us some more air support. I've got a draft of a flight plan here in Darkshore. It's helped by the fact that our bats can see in the dark, when most of us can't. Talk to Avery and she'll make sure you get safely back to Bashal'Aran.", ["objectivesText"] = "Deliver Crankshot's Note to your commander in Bashal'Aran.", ["rewardItems"] = { 166389 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10058 } }, ["questType"] = "standard" },
