[54703] = { ["id"] = 54703, ["name"] = "Express Delivery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "The Horde appears to have misplaced some of its Azerite . It would be rude of us not to return it, don't you think? The most efficient way is for me to teleport it back. I've enchanted the harpoons in that launcher over there. Fire them onto the Horde ships in the bay. I can use them as beacons to return the Azerite to the Horde... and send its ships on their way.", ["objectivesText"] = "Mark locations on the Horde ships to direct Jaina's spell. Progress: Well done, <name>.", ["rewardGold"] = 241020, ["rewardXP"] = 6815, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145580, ["x"] = 0.4384, ["y"] = 0.3024 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.4384, ["y"] = 0.3024 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 13, ["flags"] = 0 } } },
[54706] = { ["id"] = 54706, ["name"] = "Made in Kul Tiras", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54708, 54721, 55039, 55043 }, ["description"] = "Are you curious about how the Kul Tirans joined the Alliance? It was assumed that Kul Tiras would rejoin the Alliance after everything that was done to stabilize their nation. Lady Jaina Proudmoore wanted to cement the allegiance by building King Anduin a ship worthy of the Kul Tiran navy. She wished for help in finding the best shipwright in Kul Tiras, Dorian Atwater. It wouldn't be easy, as Dorian was retired. It all began with a trip to see Cyrus in Boralus Harbor...", ["objectivesText"] = "Speak to Cyrus in Boralus Harbor. Progress: Yes?", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 }, { ["mapID"] = 84, ["npcID"] = 148798, ["x"] = 0.422667, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5235, ["y"] = 0.1355 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 1, ["flags"] = 0 } } },
