[54708] = { ["id"] = 54708, ["name"] = "Home, Home On the Range", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54706, 54721, 55039, 55043 }, ["description"] = "<Cyrus peruses a map.> Hmm... Along the road to Fort Daelin... to the north... somewhere in the Deadwash. <He points to a section of road on the map.> I've marked a spot on your map that seems likely. I think that will get you close enough. I'll report back to the Lord Admiral with what we've learned. Good luck, and I hope our shipwright is willing.", ["objectivesText"] = "Track down the shipwright in Stormsong Valley and deliver the Lord Admiral's Letter. Progress: Now what's this?", ["rewardGold"] = 157900, ["rewardXP"] = 2735, ["rewardItems"] = { 164762, 166462 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150515, ["x"] = 0.586, ["y"] = 0.704 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 895, 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 4, ["flags"] = 0 } } },
