[54721] = { ["id"] = 54721, ["name"] = "I'm Too Old for This Ship", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54706, 54708, 55039, 55043 }, ["description"] = "If I understood this correctly, the Lord Admiral of the Kul Tiran navy wants me to come out of retirement specifically to build a ship for the king of Stormwind. Can't say I've had THAT request before. <Dorian leans back in her chair for a moment and rubs at her eyes.> I'm getting too old for this nonsense. <Dorian heaves a long sigh.> Go on out back and saddle Hurricane for me while I pack my things. We will meet you at Port Fogtide. We're going to need a slip.", ["objectivesText"] = "Saddle Hurricane and meet Dorian Atwater at Port Fogtide. Progress: I don't go anywhere without my horse, <name>.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54723] = { ["id"] = 54723, ["name"] = "Covering Our Masts", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "When I was younger, I hid my ships out of vanity. I often went through a number of designs before I was satisfied. I didn't want anyone to see that. It might ruin the mystique, I reasoned. Now... I think it best to hide this ship from the likes of those tentacle-faced creeps. I don't think they intend to let us build unchallenged. Go into the port and place my wards around the main slip. You'll see what they do.", ["objectivesText"] = "Place 3 Fog Wards in Port Fogtide. Progress: Did you place the wards?", ["rewardGold"] = 295000, ["rewardXP"] = 5465, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54725] = { ["id"] = 54725, ["name"] = "The Deep Ones", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "I've spent my whole life on and around the sea. Until very recently I feel like I've always had one foot in the water. I knew there were... things... best left untouched. Now they're here. In Stormsong Valley. Occupying the slip I need to build your ship. Do I really need to tell you what to do about it?", ["objectivesText"] = "Slay 12 drowned forces in Port Fogtide. Progress: I never thought I would see such things in the flesh. Have you dealt with them?", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54726] = { ["id"] = 54726, ["name"] = "Frame Work", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "Now that I have a slip to work in, I'm going to need lumber. Lots of lumber. The only lumber mill that could handle this kind of volume at such short notice would be the Algerson Lumber Yard outside of Boralus. I know this because I've made this exact request of them before. I will meet you there. Algerson might need a little persuasion.", ["objectivesText"] = "Meet Dorian Atwater at the Algerson Lumber Yard in Tiragarde Sound.", ["rewardGold"] = 28090, ["rewardXP"] = 685, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54727] = { ["id"] = 54727, ["name"] = "Team Carry", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "Algerson is about as useful as a legless horse. We're going to do this ourselves. The mill is overrun with bizarre creatures. I'll handle those. You and these hearty volunteers will need to be the muscle of this operation. Don't look at me like that, <class>. It's just a little lifting. Once we have enough lumber, Sal will meet us for a pick up. Just stay close to me and focus on not dropping my wood, yes?", ["objectivesText"] = "Collect 4 heavy lumber and take it to the drop-off point.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54728] = { ["id"] = 54728, ["name"] = "This Lumber is Haunted", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54730 }, ["description"] = "I don't much believe in ghosts, or hauntings for that matter. That said, there is something wrong with this lumber. I can feel it in my bones. They're achier than normal. I only know of one group that would know what to do. They're reclusive, but we share a love of nature. Seek out Thornspeaker Birchgrove in Drustvar. I trust no one else with this.", ["objectivesText"] = "Seek out Thornspeaker Birchgrove in Gol Koval. Progress: There's a deep rend in the balance, and it is centered on you. Curious.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 164762, 166675 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 895, 896 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 10, ["flags"] = 0 } } },
[54729] = { ["id"] = 54729, ["name"] = "The Bleak Hills", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 895, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54732, 55136 }, ["description"] = "While you are visiting Drustvar, I need you to run another errand for me. The Wright family owned a mine up near Corlain. Years past, they supplied all the metal ore I used to build my ships. I can't imagine they're faring too well, based on what we've seen here. Find Chelsea Wright , the foreman's daughter, and see what they need to get another ore shipment together. Just tell her Dorian sent you.", ["objectivesText"] = "Find Chelsea Wright at the Bleak Hills Mine in Drustvar.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 150884, ["x"] = 0.332, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.683333, ["y"] = 0.178 }, ["mapCandidates"] = { ["npc"] = { 895, 896 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 11, ["flags"] = 0 } } },
[54730] = { ["id"] = 54730, ["name"] = "Gorak Tul's Influence", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54728 }, ["description"] = "Long have the Thornspeakers struggled against such magics. It is a conflict as old as the Drust themselves. Gorak Tul's influence, however, has vastly shifted the balance toward that of decay and death. It corrupts what would be an ordinary curse. I believe Ulfar can correct this. Go into Gol Koval. Slay our enemies, destroy their cairns, and collect their magics into this vessel. With it, Ulfar may be able to find a way to cleanse your materials.", ["objectivesText"] = "Fill the Drust Vessel in Gol Koval by killing enemies and destroying cairns. Progress: Be careful, <name>. Drust magic is older than most things that are, and older than some that were.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 15, ["flags"] = 0 } } },
[54731] = { ["id"] = 54731, ["name"] = "Balance in All Things", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "The confluence of energies around that vessel is truly disturbing. My skin crawls with the wrongness of it. We have reached the limit of my ability to help you, <name>. Go to Ulfar , the High Thornspeaker. Arthur will carry you, if you wish it. Only he knows enough about these ancient magics to undo the corruption that taints your materials. Go quickly. You do not want to hold that vessel longer than you must.", ["objectivesText"] = "Speak to Ulfar and cleanse the Filled Drust Vessel. Progress: I sense a terrible power emanating from that vessel, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 164762, 167200 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 139926, ["x"] = 0.618, ["y"] = 0.594 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 141159, ["x"] = 0.452, ["y"] = 0.458 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.594 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 16, ["flags"] = 0 } } },
[54732] = { ["id"] = 54732, ["name"] = "Drop It!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54729, 55136 }, ["description"] = "You must be the person Dorian sent to collect the ore. I got a message a short while ago requesting a rather large shipment, which in itself is a feat given the state of this place. I was on my way to our storehouse when that... beast!... cornered me. It took my keys. I can't get you that shipment without them. Find out where that mongrel took them and bring them back. Let it be known I wouldn't do this for anyone else.", ["objectivesText"] = "Retrieve Chelsea Wright 's keys. Progress: <The Wicker Beast stares blankly at you.>", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 53410, 53419, 62975, 62976, 62977, 63859, 63860, 63861, 139879, 147351, 156943, 156978, 156979, 167168, 167199, 211279, 237812 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 150884, ["x"] = 0.332, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 150885, ["x"] = 0.35, ["y"] = 0.2965 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 12, ["flags"] = 0 } } },
[54733] = { ["id"] = 54733, ["name"] = "Make it Wright", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "<Chelsea stares in horror at the Wicker Beast.> I don't know how this happened, or why... but I know this beast. <Chelsea hastily wipes away a tear.> I've unlocked our storage chest. Thank you. Thank you so much. Tell Dorian she can call upon us at any time.", ["objectivesText"] = "Collect Dorian's ore shipment .", ["rewardGold"] = 144600, ["rewardXP"] = 2735, ["rewardItems"] = { 164762, 167199 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 150884, ["x"] = 0.332, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 14, ["flags"] = 0 } } },
[54734] = { ["id"] = 54734, ["name"] = "Summons from Dorian", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "<The elemental has a piece of parchment whipping around madly inside its tornado.> HHsssssss. <The elemental ejects the page into your face.> HHHHSSSSSSsssshh.", ["objectivesText"] = "Return to Dorian Atwater at Port Fogtide. Progress: I see my little helper found you just fine.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["rewardItems"] = { 164762, 166674, 167168, 167199, 167200 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 149252, ["x"] = 0.392, ["y"] = 0.38 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 148870, ["x"] = 0.683333, ["y"] = 0.178 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 895, 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 17, ["flags"] = 0 } } },
[54735] = { ["id"] = 54735, ["name"] = "A Worthy Crew", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 84, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "If Dorian really can build this ship before the day is out, we need to find a crew for the new vessel. This crew should represent the best of Kul Tiran society, the highest naval prowess, and the faith of our people as we present this gift to Anduin. I have a captain in mind, but you'll want to speak to him yourself. I will let him decide who else he wants aboard. Seek out my brother, Tandred Proudmoore , in Boralus. He will help you fill out the ranks from there.", ["objectivesText"] = "Recruit a crew for the new vessel. Progress: Have you found a suitable crew?", ["rewardGold"] = 289300, ["rewardXP"] = 5465, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 148798, ["x"] = 0.422667, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 148798, ["x"] = 0.422667, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.422667, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 18, ["flags"] = 0 } } },
[54736] = { ["id"] = 54736, ["name"] = "Desecrate this Fire!", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = false, ["event"] = "Midsummer Fire Festival", ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54736 }, ["rewardGold"] = 234000, ["rewardXP"] = 200, ["rewardItems"] = { 23247 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895 },
