[54754] = { ["id"] = 54754, ["name"] = "For the Queen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 54097, 54099, 54100, 54101, 54102, 54103, 54104, 54105, 54106, 54107, 54108, 54109, 54754 }, ["description"] = "<You chose not to side with the traitor Saurfang and his troll lackey. Now that you know where Saurfang is, and who is with him, you should report to Sylvanas to see if she has any further orders.>", ["objectivesText"] = "Meet with Lady Sylvanas Windrunner in Orgrimmar.", ["rewardGold"] = 16980, ["rewardXP"] = 850, ["rewardItems"] = { 19971, 39346, 39387, 39436, 39450, 54996, 54997, 54998, 57492, 57493, 59269, 59270, 59271, 59272, 59306, 59307, 59308, 59309, 106143, 106153, 106176, 107314, 121482, 121488, 124124, 131369, 131526, 131527, 131549, 131550, 132269, 132279, 132280, 132281, 132282, 132283, 132284, 132285, 132286, 132287, 132288, 132289, 132290, 132294, 132295, 132296, 132297, 132298, 132299, 132302, 132303, 133803, 137865, 137866, 138855, 138856, 138857, 138858, 138859, 138860, 138861, 138862, 141387, 141403, 163128, 165638, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776, 198353, 224072, 225896, 236956, 237812, 260583 }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 134711, ["x"] = 0.485, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 20 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 802, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] =