[54756] = { ["id"] = 54756, ["name"] = "Garbage for the Garbage God", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54756 }, ["series"] = { 54757 }, ["description"] = "Richmon, you found a thing I been looking for for a long time. Bring it to me in the Port of Zandalar, and I will grant you my favor.", ["objectivesText"] = "Bring Jani's First Offering to Jani 's Trashpile in the Port of Zandalar. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 1415, ["rewardItems"] = { 166506, 166507 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 149006, ["x"] = 0.455, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["startItems"] = { 166507 } },
[54757] = { ["id"] = 54757, ["name"] = "The Loa of Scavengers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54757 }, ["series"] = { 54756 }, ["description"] = "Richmon, you bring me many shiny things. You helped some of those that no one else would. And ya dumb enough to keep comin' back to me trash piles. I like ya style. Now for da big one. Go to the steps of Dazar'alor, and find the Chronicler Ash'tari . Her chisel makes da shrines there. Tell her to build me a shrine and I will grant you my boon. Unlike the flappy Pa'ku or running Gonk, I just gonna let ya scrap your trash in my pile and I'll give ya stuff back. Anywhere my trash piles be.", ["objectivesText"] = "Speak with Chronicler Ash'tari at Dazar'alor.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 149006, ["x"] = 0.455, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 137510, ["x"] = 0.502667, ["y"] = 0.346667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.455, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[54759] = { ["id"] = 54759, ["name"] = "When Spirits Whisper", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["series"] = { 54760 }, ["description"] = "Ah, <name>! I have a message for you. Baine Bloodhoof asks that you join him in Thunder Bluff at once. I suggest you hurry.", ["objectivesText"] = "Meet with Baine Bloodhoof in Thunder Bluff.", ["rewardGold"] = 31900, ["rewardXP"] = 850, ["rewardItems"] = { 166899, 167860, 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 149088, ["x"] = 0.3935, ["y"] = 0.7895 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.3935, ["y"] = 0.7895 }, ["mapCandidates"] = { ["npc"] = { 85, 88 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54760] = { ["id"] = 54760, ["name"] = "The Spiritwalkers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["series"] = { 54759 }, ["description"] = "As you know, the spiritwalkers commune with our ancestors and maintain balance within the spirit realm. It is a sacred duty that links our present to our past. But lately the spiritwalkers have been troubled by visions of chaos and turmoil. Of a rising darkness. They tell me that the spirits have whispered your name. We are unsure why, but Spiritwalker Ussoh means to find out. Seek Ussoh on Fargaze Mesa to the south. Good luck, <name>. I believe you may need it.", ["objectivesText"] = "Speak with Spiritwalker Ussoh at Fargaze Mesa in Camp Narache.", ["rewardGold"] = 31500, ["rewardXP"] = 850, ["rewardItems"] = { 166899, 167860 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 149084, ["x"] = 0.468, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.568667, ["y"] = 0.477 }, ["mapCandidates"] = { ["npc"] = { 1, 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54761] = { ["id"] = 54761, ["name"] = "Spirit Guide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6452, ["mapID"] = 1, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["description"] = "The ancestors have whispered your name, <name>. Now it is time for you to reach out to them. Here in this sacred place, we spiritwalkers commune with those who came before us. Sit within the circle and light the incense. If you open your heart, a spirit guide will present itself to you. Let us hope it will lead you to the answers we seek.", ["objectivesText"] = "Light the Spiritwalker's Incense at Fargaze Mesa in Camp Narache. Progress: Have you found your guide?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 166899, 167860 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 149084, ["x"] = 0.468, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 149084, ["x"] = 0.468, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 462, ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54762] = { ["id"] = 54762, ["name"] = "A Small Retreat", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6452, ["mapID"] = 1, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["description"] = "I believe your guide was delivering a warning. The unrest within the spirit realm may be even more dire than first feared. We must cross over at once, from a place with a strong bond to the spirit realm. In ages past, tauren made pilgrimages to Sun Rock Retreat to engage in such a ritual. It is said that long ago, An'she himself kissed the mountain where the retreat now stands. Meet me there and we will begin the crossing.", ["objectivesText"] = "Meet with Spiritwalker Ussoh at Sun Rock Retreat in Stonetalon Mountains.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 166899, 167860 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 149084, ["x"] = 0.468, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 65, ["npcID"] = 149529, ["x"] = 0.492, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 1, 65 }, ["zone"] = { 6452 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 65, ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54763] = { ["id"] = 54763, ["name"] = "Crossing Over", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 406, ["mapID"] = 65, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["description"] = "We are ready to begin. You will be crossing into the spirit realm. Take caution, for it can be a place of both tranquility and danger. Make contact with your spirit guide. There must be a reason it was in pain when it revealed itself to you. When you are ready, raise this vessel to enter the spirit realm.", ["objectivesText"] = "Enter the spirit realm and make contact with your spirit guide. Progress: Are you ready to enter the spirit realm?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 166899, 167860 }, ["starts"] = { { ["mapID"] = 65, ["npcID"] = 149529, ["x"] = 0.492, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 65, ["npcID"] = 149529, ["x"] = 0.492, ["y"] = 0.61 } }, ["coords"] = { ["mapID"] = 65, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 65 }, ["zone"] = { 406 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 65, ["db2QuestSortName"] = "Artifact", ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54764] = { ["id"] = 54764, ["name"] = "Storm in Bloodhoof", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 406, ["mapID"] = 65, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["description"] = "This is worse than I feared. The people of Bloodhoof Village are in grave danger. Even the brave young tauren who train there are woefully unprepared for the danger that is coming. Do what you can to stop this threat. I will go to Thunder Bluff to warn the High Chieftain.", ["objectivesText"] = "Travel to Bloodhoof Village in Mulgore and stop the spirit attack.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 166899, 167860 }, ["starts"] = { { ["mapID"] = 65, ["npcID"] = 149529, ["x"] = 0.492, ["y"] = 0.61 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 149528, ["x"] = 0.5836, ["y"] = 0.5192 } }, ["coords"] = { ["mapID"] = 65, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.61 }, ["mapCandidates"] = { ["npc"] = { 65, 88 }, ["zone"] = { 406 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["db2QuestSortName"] = "Artifact", ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54765] = { ["id"] = 54765, ["name"] = "Thank Your Guide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["series"] = { 54766 }, ["description"] = "The balance has been restored, and Thunder Bluff is safe. Thank you. We owe our victory to your spirit's guidance. We must honor the old ways by giving thanks to the ones who came before us. To the southwest lies a beautiful vista where my father once took me. It would be a fitting place to reflect upon all that has transpired. Please take this offering there to honor our ancestors.", ["objectivesText"] = "Deliver the offering to your spirit guide on the cliffs southwest of Thunder Bluff.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 166899, 167860 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.568667, ["y"] = 0.477 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54766] = { ["id"] = 54766, ["name"] = "Answer the Call", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 6 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 54759, 54760, 54761, 54762, 54763, 54764, 54765, 54766 }, ["series"] = { 54765 }, ["description"] = "It is fortunate that Spiritwalker Ussoh passed along your spirit guide's warning. We were able to evacuate most of the citizens. This cursed spirit is full of malevolence and hatred. It must be destroyed, <name>! We attack on your command.", ["objectivesText"] = "Stop the Malevolent Spirit .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 166899, 167030, 167860 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 149528, ["x"] = 0.5836, ["y"] = 0.5192 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.5836, ["y"] = 0.5192 }, ["mapCandidates"] = { ["npc"] = { 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["questLines"] = { { ["id"] = 860, ["name"] = "Tauren Heritage", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54781] = { ["id"] = 54781, ["name"] = "What's For Lunch?", ["level"] = 90, ["requiredLevel"] = 90, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 15458, ["mapID"] = 2405, ["storyline"] = { 54781 }, ["description"] = "My Shadowtrade Mercenaries will fight for Stormarion Cores , no questions asked, but they do get hungry also! Food is quite scarce here, so we need supplies! Take a mercenary out with you and find some food for them to eat. I'll make it worth your while!", ["objectivesText"] = "Slay Lurking Stormrays for 6 Stormray Fins and search Stormarion Supply crates for 6 Domanaar Snack Packs . Progress: Is that mercenary well fed?", ["rewardGold"] = 341600, ["rewardXP"] = 20540, ["rewardItems"] = { 246951, 248927, 248929 }, ["starts"] = { { ["mapID"] = 2405, ["npcID"] = 244749, ["x"] = 0.264, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 2405, ["npcID"] = 244749, ["x"] = 0.264, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 2405, ["source"] = "quest_giver", ["x"] = 0.264, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 2405 }, ["zone"] = { 15458 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2771, ["db2PoiUiMapID"] = 2405 },
