[54787] = { ["id"] = 54787, ["name"] = "Masking For a Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 53887, 53888, 53896, 53909, 53910, 53916, 53919, 53936, 53978, 53986, 54518, 54519, 54559, 54703, 54787 }, ["description"] = "The Outriggers have fought some pretty tough monsters and Horde savages aren't so much different. The Blight Specialists they brought weren't especially tough, but they were the most dangerous. Kill a few of them and bring back their face masks. Okri can work his mechanical wizardry and build us better masks of our own in case any Horde scum dare show their blight-spreading faces around here again.", ["objectivesText"] = "Collect 4 Blight Specialist Masks . Progress: Did you get rid of those blighted wretches?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164921, 164968, 166280, 166682 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 145593, ["x"] = 0.386, ["y"] = 0.2784 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.386, ["y"] = 0.2784 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 14 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 843, ["questLineOrder"] = 7 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 843, ["name"] = "Beware the Daughter of the Sea", ["orderIndex"] = 10, ["flags"] = 0 } } },
