[54843] = { ["id"] = 54843, ["name"] = "Remaining Threats", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 54843 }, ["description"] = "Though our forces maintain a steady hold on Darkshore , this land still festers with enemies at every turn. Do what you can to keep them at bay, and you will be well rewarded.", ["objectivesText"] = "Defeat 12 rare enemies in Darkshore . Progress: Is the deed done?", ["starts"] = { { ["mapID"] = 62, ["npcID"] = 149410, ["x"] = 0.47, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 149410, ["x"] = 0.47, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "group" },
[54844] = { ["id"] = 54844, ["name"] = "Tapping the Breach", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 54844 }, ["description"] = "Darkshore is home to several elemental breaches which hold massive amounts of power. The remnants of the Twilight's Hammer know this. While we were preoccupied with the Kaldorei, their elementalists have moved to exploit these locations of power, calling forth massive elementals to do their bidding. Their actions must not go unchecked.", ["objectivesText"] = "Defeat 20 Twilight elementalists in Darkshore . Progress: What of the cultist threat?", ["starts"] = { { ["mapID"] = 62, ["npcID"] = 149411, ["x"] = 0.478, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 149411, ["x"] = 0.478, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard" },
[54845] = { ["id"] = 54845, ["name"] = "Buzzkill", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 54845 }, ["description"] = "Some gnome's been goin about planting these strange machines in the woods here. I don't know what they do, but I'll be dead before I let gnomish machines sully goblin territory! Find these \"buzzboxes\" and reduce them to scrap. I'll make sure you're compensated for your troubles.", ["objectivesText"] = "Destroy 4 Buzzboxes in Darkshore . Progress: Did you take care of our gnomish problem?", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 178021, 178022, 178023, 178024, 178025, 178027, 178030, 180473, 180474 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 149412, ["x"] = 0.464, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 149412, ["x"] = 0.464, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard" },
[54850] = { ["id"] = 54850, ["name"] = "Operation: Troggageddon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 7 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 67, ["mapID"] = 114, ["storyline"] = { 54402, 54576, 54577, 54580, 54581, 54582, 54639, 54640, 54641, 54642, 54850 }, ["description"] = "Tinkerbow has finished installing the guns on our flying machines, so it's time to give them a trial by fire. We've got confirmation that our target is in fact within the Halls of Stone. Let's start clearing out the forces out in front. We'll take the earliest opportunity to bring the fight to Sparkspanner!", ["objectivesText"] = "Clear out Sparkspanner's army.", ["rewardGold"] = 524200, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 147950, ["x"] = 0.552, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 858, ["name"] = "Gnome Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[54851] = { ["id"] = 54851, ["name"] = "Blessing of the Tides", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 84, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["description"] = "Dorian certainly lives up to her reputation, <name>. This magnificent vessel is complete and now it has a crew. Two pieces remain. First, we must give the ship a name. Then it falls to Brother Pike to bless this vessel. As is tradition, a tidesage's blessing fortifies the ship against storms and encourages fair weather and smooth seas. It is as much ceremonial as it is practical. Once that is done, we will set sail for Stormwind.", ["objectivesText"] = "Choose a name for the new vessel, then witness Brother Pike 's blessing. Progress: I chose you for this honor to thank you for all you have done for my people, and all that you have done for me.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 148798, ["x"] = 0.422667, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 148798, ["x"] = 0.422667, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.422667, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 19, ["flags"] = 0 } } },
[54856] = { ["id"] = 54856, ["name"] = "Bilgewater Bandits", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 54856 }, ["rewardItems"] = { 166475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 148 } }, ["questType"] = "world", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 62, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[54871] = { ["id"] = 54871, ["name"] = "We Are Coming", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53847, 53849, 53988, 53989, 53990, 53992, 54006, 54041, 54871 }, ["description"] = "We must press our advantage before the Horde can further its hold on Darkshore. The kaldorei stand ready to fight for our home, and the Gilneans stand alongside us. We will show our enemies our fury. They will learn to fear us. Rally any you can. We march at once.", ["objectivesText"] = "Inform Ralston Karn to prepare for the assault on Darkshore.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 174292, 175063, 177053, 178156, 179942, 199680, 199681, 199682, 199683, 199684, 237812 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 149612, ["x"] = 0.695, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 797, ["name"] = "In Darkest Night", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54875] = { ["id"] = 54875, ["name"] = "Remaining Threats", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 54875 }, ["description"] = "We have managed to route the Horde presence in Darkshore , but several threats remain throughout the countryside. If we wish to hold this land, they must be eliminated.", ["objectivesText"] = "Defeat 12 rare enemies in Darkshore . Progress: How's your progress?", ["starts"] = { { ["mapID"] = 62, ["npcID"] = 149623, ["x"] = 0.468, ["y"] = 0.355 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 149623, ["x"] = 0.468, ["y"] = 0.355 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.355 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "group" },
[54876] = { ["id"] = 54876, ["name"] = "Tapping the Breach", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 54876 }, ["description"] = "We had thought the Twilight's Hammer's presence in Darkshore was snuffed out with the defeat of Deathwing. Apparently, we were mistaken. Remnants of their cult have used the conflict in Darkshore as an opportunity to re-establish their presence here. Darkshore is home to several breaches of elemental power, and it looks like they aim to use these to unleash powerful elementals to devastate the land. This must not stand.", ["objectivesText"] = "Defeat 20 Twilight elementalists in Darkshore .", ["starts"] = { { ["mapID"] = 62, ["npcID"] = 149624, ["x"] = 0.464, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 149624, ["x"] = 0.464, ["y"] = 0.365 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard" },
[54878] = { ["id"] = 54878, ["name"] = "Buzzkill", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 148, ["mapID"] = 62, ["storyline"] = { 54878 }, ["description"] = "Some nefarious no-goodnik is tampering with my Buzzboxes! I've been trying to get the Buzzbox network back online since we were able to drive the Horde out of Darkshore , but I'm getting no reading from boxes 456, 627, 111, and 854! I'd be willing to bet that some stragglers from the Bilgewater Cartel are to blame! See if you can get those Buzzboxes back online, will you? We'll need their readings if we ever want to permanently fix the corruption problem here.", ["objectivesText"] = "Repair 4 Buzzboxes in Darkshore .", ["rewardGold"] = 464700, ["rewardXP"] = 1415, ["rewardItems"] = { 178021, 178022, 178023, 178024, 178025, 178027, 178030, 180473, 180474 }, ["starts"] = { { ["mapID"] = 62, ["npcID"] = 149631, ["x"] = 0.464, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 62, ["npcID"] = 149631, ["x"] = 0.464, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 62, ["source"] = "quest_giver", ["x"] = 0.464, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 62 }, ["zone"] = { 148 } }, ["questType"] = "standard" },
[54913] = { ["id"] = 54913, ["name"] = "Spark of Genius", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1161, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["description"] = "<name>, I have wondrous news! A recent energy signature tripped several detection relays I installed after that unfortunate incident with Sargeras. I require further data to know for certain, but initial diagnostics suggest that these energies are coming from Hati! We might still be able to save him! Hati's spirit is still bound to your own, so I'll need your help. Meet me at my library in the Storm Peaks right away!", ["objectivesText"] = "Meet Mimiron at the Inventor's Library in the Storm Peaks.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 152002, ["x"] = 0.728, ["y"] = 0.14 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 149736, ["x"] = 0.375, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.14 }, ["mapCandidates"] = { ["npc"] = { 120, 1161 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54915] = { ["id"] = 54915, ["name"] = "Telemetry Online", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 67, ["mapID"] = 120, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["description"] = "When Titanstrike's power was expended in Silithus, Hati's essence managed to sever itself from the Thunderspark just in time to avoid destruction. The only problem is that his essence was then scattered across Azeroth, and we don't know where. Now that we've locked onto his energy signature, we should be able to triangulate Hati's position!", ["objectivesText"] = "Assist Mimiron in locating Hati's essence. Progress: Everything is possible with science!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 120, ["npcID"] = 149736, ["x"] = 0.375, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 149799, ["x"] = 0.375, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54916] = { ["id"] = 54916, ["name"] = "The Huntsman's Creed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 67, ["mapID"] = 120, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["description"] = "Through the glorious wonder of science, I have managed to keep the Thunderspark powered precisely for this purpose. All you need to do is get to the Temple of Storms and absorb Hati's essence into it. Just... kind of point it in his general direction. Oh, and do keep in mind that this is only one part of Hati. You may run into a few... technical difficulties before he's subdued enough for the absorption protocol.", ["objectivesText"] = "Absorb Hati's essence into the Thunderspark at the Temple of Storms.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 166895 }, ["starts"] = { { ["mapID"] = 120, ["npcID"] = 149736, ["x"] = 0.375, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 149870, ["x"] = 0.336, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.375, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54917] = { ["id"] = 54917, ["name"] = "Paid in Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1377, ["mapID"] = 120, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["description"] = "If Mimiron's fancy gadgets be right, then the other half o' Hati is near the wound in Silithus. We'll have tae move quickly. Even with part o' his essence contained, I can feel him fadin' away fast! 'Tis a long trip, <lad/lass>. Let's get movin'!", ["objectivesText"] = "Absorb Hati's essence into the Thunderspark at the Wound in Silithus. Progress: Yes?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 46874, 64457, 167061 }, ["starts"] = { { ["mapID"] = 120, ["npcID"] = 149870, ["x"] = 0.336, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 81, ["npcID"] = 150391, ["x"] = 0.392, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.336, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 81, 120 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 81, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54918] = { ["id"] = 54918, ["name"] = "Spark of Imagination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1377, ["mapID"] = 81, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["series"] = { 54919 }, ["description"] = "I've diverted all non-essential power to prepare for Hati's reformation, so I cannot teleport you to Ulduar from here. Be extremely careful with the Thunderspark on your way. It is charged with highly volatile energy. One wrong bump could lead to serious complications!", ["objectivesText"] = "Use the Teleportation Pad outside Ulduar to rendezvous with Mimiron in his workshop.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 150391, ["x"] = 0.392, ["y"] = 0.715 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.392, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 81 }, ["zone"] = { 1377 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1579, ["db2PoiUiMapID"] = 745, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54919] = { ["id"] = 54919, ["name"] = "Bonds of Thunder", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8161, ["mapID"] = 745, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["series"] = { 54918 }, ["description"] = "While you infused Hati's essence into the Thunderspark, I have concocted a flawless plan the likes of which the scientific world has never seen! I'll spare you the technical details. Just follow my instructions and Hati will be back in one piece in no time at all! ...Or we will all explode. But risks must be taken in the pursuit of knowledge and the well-being of our furry companions, wouldn't you agree?", ["objectivesText"] = "Reform Hati. Progress: I know how long you have been waiting for this day, <name>.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 167799, 167800 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8161 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1579, ["db2PoiUiMapID"] = 745, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54920] = { ["id"] = 54920, ["name"] = "Homeward Bound", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8161, ["mapID"] = 120, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["description"] = "The reformation procedure went positively flawlessly! Most excellent results indeed--and plenty of data to analyze! I'm not sure what it is Thorim has to show you, but I suggest you get to the Temple of Storms right away. He gets a bit destructive when he's kept waiting. Take my teleporter pad directly out of Ulduar. I'm afraid the normal route to the entrance is... inoperable at the moment.", ["objectivesText"] = "Meet Thorim at the Temple of Storms.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 142054, 233056, 237812 }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 29445, ["x"] = 0.334, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 8161 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54922] = { ["id"] = 54922, ["name"] = "The Nuts and Bolts of It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "I started working on the leg gearing. Most the gearing around here is built from spare parts we find in the scrap heaps. We're going to need a lot of spare parts to fix this thing. See what you can find.", ["objectivesText"] = "Collect 1000 spare parts . Progress: Bring me those spare parts !", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 168827, 169610 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54925] = { ["id"] = 54925, ["name"] = "Heresy!", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53719, 53823, 53824, 53825, 53826, 53827, 53828, 53830, 53831, 54031, 54032, 54033, 54034, 54300, 54301, 54419, 54925 }, ["description"] = "My own prelates are among them that revolted against Talanji. This is an unspeakable heresy. I will not tolerate it! <She gestures to the prelate before her with her spear.> This one has wisely told me who is to blame. My second, Kaj'ra. I would have heard her, had she used any other means to make her concerns known. Now she must be disposed of. You will find her in de Terrace of de Chosen.", ["objectivesText"] = "Slay Prelate Kaj'ra . Progress: Death is too good for that heretic.", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 148096, ["x"] = 0.421333, ["y"] = 0.184667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 148096, ["x"] = 0.421333, ["y"] = 0.184667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.421333, ["y"] = 0.184667 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 919, ["name"] = "Allies of the Horde: Zandalari", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54929] = { ["id"] = 54929, ["name"] = "Ready to Rumble", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "We're going to need a new Sixteen-Servo-Actuator if we're going to fix the controls on this thing. Bondo's gang at the yard probably has one, but they usually aren't too helpful. Talk to Bondo, see if you can get us one.", ["objectivesText"] = "Acquire a Sixteen-Servo-Actuator from Bondo Bigblock. Progress: Did you head over to the yard yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167175, 167176, 168827 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54930] = { ["id"] = 54930, ["name"] = "Mechanical Liberation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 53783, 53802, 53806, 53833, 53848, 53937, 54930, 55031 }, ["description"] = "Since you successfully interrupted my nap, my defenses are obviously lacking to say the least. That's because the sethrak, in addition to stealing my gadgets and gizmos, stole my mechs! Those morons don't even have the keys! <Gryzix laughs> Here, take my keys and get my mechs back.", ["objectivesText"] = "Free Mecha-Golems in the Scalefang Outpost.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 164740 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 145131, ["x"] = 0.262, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.262, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54938] = { ["id"] = 54938, ["name"] = "A Brother's Help", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 81, ["storyline"] = { 54938, 54939, 54940, 54964 }, ["description"] = "We're gonna need all the help we can get te save the planet. I've got an idea. Meet me in Nazmir, outside the Heart of Darkness. Together, we'll seek guidance from someone who may be able to help.", ["objectivesText"] = "Travel to Nazmir and meet Magni outside Uldir.", ["rewardGold"] = 28090, ["starts"] = { { ["mapID"] = 81, ["npcID"] = 130216, ["x"] = 0.422, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 863, ["npcID"] = 149867, ["x"] = 0.578, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 81, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 81, 863 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 880, ["name"] = "The Speaker's Resolve", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54939] = { ["id"] = 54939, ["name"] = "Stubborn as a Bronzebeard", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 863, ["storyline"] = { 54938, 54939, 54940, 54964 }, ["description"] = "It's kind o' Brann tae offer, but his flying machine would drop like a rock with me aboard. Best if it carry just the two of ye. Brann will fly ye down to Uldir. I'll find me own way and meet ye inside.", ["objectivesText"] = "Take Brann's Flying Machine to Uldir. If you get lost, use the teleporter pad outside the entrance to Uldir.", ["rewardGold"] = 154900, ["starts"] = { { ["mapID"] = 863, ["npcID"] = 149867, ["x"] = 0.578, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 863, ["source"] = "quest_giver", ["x"] = 0.578, ["y"] = 0.505 }, ["mapCandidates"] = { ["npc"] = { 863 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2169, ["db2PoiUiMapID"] = 1382, ["questLines"] = { { ["id"] = 880, ["name"] = "The Speaker's Resolve", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54940] = { ["id"] = 54940, ["name"] = "Necessity is the MOTHER", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 1382, ["storyline"] = { 54938, 54939, 54940, 54964 }, ["description"] = "I may be Azeroth's speaker, but Brann's the expert on titan archaeology. If he says that MOTHER can help us save Azeroth, then I'm more than willing tae place my faith in her. Come, champion. Let's hear what guidance she has tae offer.", ["objectivesText"] = "Take Magni to meet MOTHER and activate Waygate Consoles Progress: I'll never understand exactly how all these machines work. That's what Brann does!", ["rewardGold"] = 117000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 2169, ["db2PoiUiMapID"] = 1382, ["questLines"] = { { ["id"] = 880, ["name"] = "The Speaker's Resolve", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54941] = { ["id"] = 54941, ["name"] = "Scouting The Strand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 54941 }, ["description"] = "It has been a long time since we have heard from our scouts at the outpost. They may have been cut off from us due to the naga attack. I need to check in with them and get an update on the movements of the naga forces. You should come with me, this will be a good opportunity for you to meet more of the clan and get a closer look at our operation.", ["objectivesText"] = "Locate the Ankoan scouts at the Ashen Strand.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[54945] = { ["id"] = 54945, ["name"] = "Let's Get It Started", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "I theorize this to be a communication relay. It is non-operational, but gnomish ingenuity and your strong back shall soon solve that problem! I need you to help get this device functional.", ["objectivesText"] = "Repair the device. Progress: We need this device repaired.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 149877, ["x"] = 0.658, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 149877, ["x"] = 0.658, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54946] = { ["id"] = 54946, ["name"] = "Report to Gila", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "I was quite fortunate that King Mechagon found me worthy! I will send my assistant Gila Crosswires ahead to Boralus to gather a new team. Meet up with her and help out as you can. I will join both of you shortly.", ["objectivesText"] = "Meet up with Gila Crosswires in Boralus.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 152864, ["x"] = 0.658, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151100, ["x"] = 0.673333, ["y"] = 0.156667 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54947] = { ["id"] = 54947, ["name"] = "A Small Team", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "I've determined the single attribute that is most important for a team member to survive an expedition to Mechagon. That attribute is...being a gnome! Gather these gnomes and meet Tinkmaster Overspark and myself at the departure point.", ["objectivesText"] = "Gather the team members.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 151100, ["x"] = 0.673333, ["y"] = 0.156667 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 150145, ["x"] = 0.432, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.673333, ["y"] = 0.156667 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54949] = { ["id"] = 54949, ["name"] = "More Mouths To Feed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54949 }, ["description"] = "The naga attack us relentlessly, so there is precious little time to hunt for food and supplies. You have brought many soldiers to our camp, so we must hunt while we have the chance or we will soon run out of food.", ["objectivesText"] = "Collect 30 Snapshell Flesh . Progress: The meat from this hunt shall nourish our bones.", ["rewardGold"] = 292100, ["rewardItems"] = { 166904, 166905 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150123, ["x"] = 0.35, ["y"] = 0.49 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150123, ["x"] = 0.35, ["y"] = 0.49 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.49 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[54958] = { ["id"] = 54958, ["name"] = "Ships in the Night", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 70, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "Sylvanas has gone too far this time. We may be at war with the Alliance, but there are certain lines we cannot cross. I must right this situation, but I need your assistance. Derek Proudmoore is being held on the Swift Vengeance, which is moored in the harbor here for supplies. We must take him and bring him back to his family. Are you with me?", ["objectivesText"] = "Take the boat to the Swift Vengeance and find Derek Proudmoore. Progress: There's no time to waste.", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 150309, ["x"] = 0.765, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54959] = { ["id"] = 54959, ["name"] = "Under Lock and Keys", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "Three keys? It seems Sylvanas didn't trust any one member of this crew to have access to Proudmoore. We won't be able to rescue Derek Proudmoore if we can't get his cage open. We'll need to keep an eye out for keys while we clear the ship.", ["objectivesText"] = "Collect the Captain's Key , Apothecary's Key , and Navigator's Key on the Swift Vengeance, then use them to open the Reinforced Cage. Progress: This will all be for nothing if we can't open that lock...", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167072, 167073, 167074 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54960] = { ["id"] = 54960, ["name"] = "A Bitter Reunion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 15, ["mapID"] = 70, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "We've done it! Zelling will guide the ship to Theramore, and we can put an end to this foul business once and for all. Speak to Zelling when you are ready to leave, and we will set sail.", ["objectivesText"] = "Speak to Thomas Zelling to set sail to Theramore. Progress: We sail at your command, <class>.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 150309, ["x"] = 0.765, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.765, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 70 }, ["zone"] = { 15 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 70, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54961] = { ["id"] = 54961, ["name"] = "Righting Wrongs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "Champion! I come with an urgent request from Baine Bloodhoof . He asks that you meet him at Plunder Harbor to help him with a... sensitive situation. You must tell no one of this request, <class>. Ancestors watch over you.", ["objectivesText"] = "Meet with Baine Bloodhoof at Plunder Harbor in Tiragarde Sound. Progress: I see you've received my message.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 150433, ["x"] = 0.498, ["y"] = 0.957 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 150309, ["x"] = 0.765, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.957 }, ["mapCandidates"] = { ["npc"] = { 70, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54964] = { ["id"] = 54964, ["name"] = "A One-Way Ticket to the Heart", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1021, ["storyline"] = { 54938, 54939, 54940, 54964 }, ["description"] = "These titan facilities never cease tae amaze me. I can only imagine how many of their secrets Brann has yet tae uncover. I just hope that one o' them holds the answer tae saving Azeroth. It's time tae bring MOTHER tae the Chamber of Heart. Be prepared for anythin', champion. Ye can never be quite sure what will happen when ye activate a titan machine.", ["objectivesText"] = "Evacuate MOTHER from Uldir", ["rewardGold"] = 234000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1929, ["db2PoiUiMapID"] = 1021, ["questLines"] = { { ["id"] = 880, ["name"] = "The Speaker's Resolve", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54965] = { ["id"] = 54965, ["name"] = "Chopped Bots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54965 }, ["description"] = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us! Use the Bot-Energizer to bring me dead bots, and we'll break them into spare parts .", ["objectivesText"] = "12 Re-animated bots delivered to Bolten Springspark . Progress: Re-animate dead bots and bring them to me!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150086, ["x"] = 0.63, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150086, ["x"] = 0.63, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[54972] = { ["id"] = 54972, ["name"] = "A Way Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "We are only alive thanks to the ankoan and Azshara's desire to toy with us. We will learn more of Okani's people in the times ahead, I am sure. For now, we must establish a portal home. While Azshara is blocking our traditional methods of magical travel, I can sense a powerful convergence of energies nearby. I believe we can use it to open a way home.", ["objectivesText"] = "Help Jaina open a portal to Boralus.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 66898, 66899, 66900, 69217, 69223, 131709, 163337, 163339, 170514, 170515, 170516, 170517, 170518, 170519, 170520, 170521, 170522, 170523, 170524, 170525, 170526, 170527, 170528, 170529, 170530, 170531, 170532, 170533, 170534, 170535, 170536, 170537, 237812 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 9, ["flags"] = 0 } } },
[54975] = { ["id"] = 54975, ["name"] = "A Brief Respite", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 54975, 55095, 55175, 55361, 55363, 55374, 55400, 55407, 55425, 55497, 55533, 55558, 55561, 55570, 55573, 55574, 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55618, 55694, 55851, 55860, 55861, 55937, 56037, 56038, 56039, 56043, 56156, 56234, 56325, 56350, 56640, 56641, 56642, 56643, 56644, 56741, 57010 }, ["description"] = "We have much to do, <name>. However, we are all weary and require rest. Decisions made while fatigued are almost always the wrong ones to make. The Ankoan have offered their home to us, yet they are barely holding on themselves. We should do what we can to support them while we think about our next move. See what you can do to aid their hunting parties, it may be the only way we survive in this place.", ["objectivesText"] = "Support your allies in Nazjatar by getting one to rank 3.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 168846 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 1022, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 24, ["flags"] = 0 } } },
[54976] = { ["id"] = 54976, ["name"] = "The Shadow of Gilneas", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "Champion of Gilneas! I have a letter for you from Princess Tess Greymane . She requests your presence in Stormwind Keep.", ["objectivesText"] = "Meet with Tess Greymane at Stormwind Keep.", ["rewardGold"] = 33100, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 150200, ["x"] = 0.546667, ["y"] = 0.184 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155313, ["x"] = 0.826, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.546667, ["y"] = 0.184 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[54977] = { ["id"] = 54977, ["name"] = "Into Duskwood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "There is a night elf I met in Teldrassil, Vassandra Stormclaw , who may be able to teach Tess without resorting to such an extreme measure. She is the one who originally helped our people with their affliction. Vassandra is currently in Duskwood, assisting the residents of Raven Hill with their attempts to cure the feral worgen in the area. If anyone knows about the curse, it is her. As a more personal request, do not let my daughter do anything too rash. She takes after her father in that way.", ["objectivesText"] = "Speak with Vassandra Stormclaw in Duskwood.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 151784, ["x"] = 0.825, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.825, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 47, 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[54978] = { ["id"] = 54978, ["name"] = "Against Overwhelming Odds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54978 }, ["description"] = "We've received numerous reports of the Horde overwhelming our forces within both Kul Tiras and Zandalar. Brute forcing the Alliance with sheer numbers is an age-old tactic of the Horde, but we can't allow them to get the upper hand. Venture forth throughout and thin their numbers the best you can. I recommend bringing reinforcements.", ["objectivesText"] = "Slay 25 Level 50+ Horde anywhere within Kul Tiras, Zandalar, Nazjatar, Uldum or Vale of Eternal Blossoms.", ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143559, ["x"] = 0.562, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "pvp" },
[54979] = { ["id"] = 54979, ["name"] = "Against Overwhelming Odds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 862, ["storyline"] = { 54979 }, ["description"] = "It appears we've allowed the Alliance forces to fester. If these reports are correct, they're outnumbering us in nearly every bastion we hold. Arm yourself, grab a few of your most trusted allies and put them into the ground, <class>!", ["objectivesText"] = "Slay 25 Level 50+ Alliance anywhere within Kul Tiras, Zandalar, Nazjatar, Uldum or Vale of Eternal Blossoms.", ["starts"] = { { ["mapID"] = 862, ["npcID"] = 138708, ["x"] = 0.584, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 9042 } }, ["questType"] = "pvp" },
[54980] = { ["id"] = 54980, ["name"] = "Bane of the Nightbane", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "Princess Greymane has informed me of the situation and I do have an idea of how to help. But first, a favor for a favor. The residents of Duskwood have been plagued recently by a particularly ferocious member of the Nightbane pack that they call 'Bloodeyes'. Take Master Harris's sedative and bring the worgen back to me alive. She will be a perfect subject to test cures on.", ["objectivesText"] = "Subdue Bloodeyes and return with her to Raven Hill. Progress: If we can cure even the most feral of <race>, then the curse will mean nothing to us.", ["rewardGold"] = 683200, ["rewardXP"] = 8520, ["rewardItems"] = { 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.370667, ["y"] = 0.437333 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[54981] = { ["id"] = 54981, ["name"] = "Cry to the Moon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "Duskwood has a direct connection to the Emerald Dream. Through this connection, I may be able to call forth the Ancient Goldrinn. He will be able to give the princess a taste of the curse she so dangerously chases. A rare bloom grows on the east side of the woods, gather its bloom and meet me in Twilight Grove. It will help me with this ritual.", ["objectivesText"] = "Gather a bloom of Elune's Grace . Progress: Such flowers have been known to attract wolves, but I doubt you will have a problem with that.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 60928, 60929, 60930, 131597, 167032, 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006, 245624 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.370667, ["y"] = 0.437333 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[54982] = { ["id"] = 54982, ["name"] = "The Spirit of the Hunter", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "The other thing I may need for this ritual are the fangs of a wolf. There is a pack that has newly settled in around Manor Mistmantle. Bring me their fangs. I will await your return at Twilight Grove.", ["objectivesText"] = "Retrieve the fangs from Mistfang wolves. Progress: Did you claim your trophy?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 167031, 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.370667, ["y"] = 0.437333 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54983] = { ["id"] = 54983, ["name"] = "Waking a Dreamer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "This should be all I need to call upon the Ancient. Some unwanted visitors may answer the call first. Protect me as I perform the ritual!", ["objectivesText"] = "Defend Vassandra Stormclaw as she summons Goldrinn .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 151761, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 150106, ["x"] = 0.465333, ["y"] = 0.366667 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.370667, ["y"] = 0.437333 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54984] = { ["id"] = 54984, ["name"] = "Let Sleeping Wolves Lie", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "Tess's essence now wanders a section of the Emerald Dream I have twisted into her thoughts. And I have given her my gift, but she could still use a guide. Enter the Dream through the portal behind me. It will place you near where she sleeps. See if you can help show her how rage may blind a mortal.", ["objectivesText"] = "Enter the Dream Portal and guide Tess.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 150106, ["x"] = 0.465333, ["y"] = 0.366667 } }, ["ends"] = { { ["mapID"] = 47, ["npcID"] = 150115, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.465333, ["y"] = 0.366667 }, ["mapCandidates"] = { ["npc"] = { 47 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 47, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 6, ["flags"] = 0 } } },
[54990] = { ["id"] = 54990, ["name"] = "The New Guard", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10, ["mapID"] = 47, ["storyline"] = { 54976, 54977, 54980, 54981, 54982, 54983, 54984, 54990 }, ["description"] = "I need to speak with my parents again. I think my father and I have a bit to discuss. Meet me back at Stormwind Keep. I would like to thank you in a more formal manner.", ["objectivesText"] = "Meet Tess Greymane at Stormwind Keep. Progress: Yes?", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 122457, 173998, 173999, 174000, 174001, 174002, 174003, 174004, 174005, 174006 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 150115, ["x"] = 0.370667, ["y"] = 0.437333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155313, ["x"] = 0.826, ["y"] = 0.282 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.370667, ["y"] = 0.437333 }, ["mapCandidates"] = { ["npc"] = { 47, 84 }, ["zone"] = { 10 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 957, ["name"] = "Worgen Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[54992] = { ["id"] = 54992, ["name"] = "The Start of Something Bigger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "We have coordinates locked into the gyrocopters. You and Captain Winklespring will fly the lead. If we run into any trouble, Tinkmaster Overspark wants the most experienced pilots out front. Board whenever you are ready to go.", ["objectivesText"] = "Board the Expedition Gyrocopter .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 246701 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150145, ["x"] = 0.432, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152484, ["x"] = 0.776, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1161, 1462 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 5, ["flags"] = 0 } } },
[54996] = { ["id"] = 54996, ["name"] = "Remembrance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1638, ["mapID"] = 1, ["storyline"] = { 54996 }, ["description"] = "You may remember the day Thunder Bluff was attacked. It was your efforts and your guide who saved us. Now we take time to honor our ancestors and give thanks for the path they have set for us. Bring this offering to the cliffs overlooking Thunder Bluff and give thanks to your guide and all our ancestors. A simple gesture to commemorate our past. This is our way.", ["objectivesText"] = "Deliver the offering to your spirit guide on the cliffs overlooking Thunder Bluff.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 46325, 52641, 52645, 55132, 156966, 223439, 223444, 223450, 223462 }, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 149084, ["x"] = 0.468, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 36648, ["x"] = 0.568667, ["y"] = 0.477 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 1, 88 }, ["zone"] = { 1638 } }, ["questType"] = "standard" },
[54997] = { ["id"] = 54997, ["name"] = "Dead in the Water", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "Once Proudmoore is freed, we will need to commandeer this ship to transport him to Theramore, where his sister awaits us. Zelling's magic can guide the ship there, but first we'll need to take care of the crew.", ["objectivesText"] = "Defeat 6 crew members aboard the Swift Vengeance.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 4, ["flags"] = 0 } } },
[54999] = { ["id"] = 54999, ["name"] = "Under False Colors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 70, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. I will take the ship near Chandlery Wharf, which has recently been taken by Irontide pirates. There, I will leave it under the guise of a pirate raid gone wrong. Your task will be to ensure that Sylvanas' forces find this ship. You must report to Nathanos that you spotted a stolen Forsaken vessel in that area. You have no connection to Derek Proudmoore, so it should raise no suspicions.", ["objectivesText"] = "Start the mission \"Casting the Bait\" then report to Nathanos Blightcaller aboard the Banshee's Wail in the Port of Zandalar. Progress: Out with it, <class>.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 167228 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 150311, ["x"] = 0.764, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 70, 862 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 7, ["flags"] = 0 } } },
[55002] = { ["id"] = 55002, ["name"] = "Murder at the Brawlpub", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55002 }, ["series"] = { 55003, 55004, 55005, 55006, 55007 }, ["description"] = "The Brawlpub quartermaster lies dead in front of you. He was murdered in broad daylight! He must have been assassinated while someone was fighting in the arena. Maybe even during one of your fights. Perhaps there are some clues nearby as to who might have killed him.", ["objectivesText"] = "Investigate the scene of the crime.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 92718, 164931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55003] = { ["id"] = 55003, ["name"] = "Put Up Your Dukes", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55003 }, ["series"] = { 55002, 55004, 55005, 55006, 55007 }, ["description"] = "You know what? <The commander puts his notebook away.> I COULD use a good <class> on my investigations team. We've had some personnel issues lately and, frankly, I can use all the help I can get. But first: why don't you go hop into the arena for a few fights so I can get a good look at your skills?", ["objectivesText"] = "Win any 3 fights in Bizmo's Brawlpub.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55004] = { ["id"] = 55004, ["name"] = "Undercover Agent: Ann Dennyson", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55004 }, ["series"] = { 55002, 55003, 55005, 55006, 55007 }, ["description"] = "Lord Winifred Browne is one of our primary suspects in this case. Browne is an infamously aggressive speculator, and has a list of debts a mile long. He may be in need of money, which is consistent with the evidence you found earlier. My associate Ann has taken point on the case. I'd like you to assist her. I think you'll work well together.", ["objectivesText"] = "Report to Ann Dennyson in Bizmo's Brawlpub.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55005] = { ["id"] = 55005, ["name"] = "The Financial Participation Incentive", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55005 }, ["series"] = { 55002, 55003, 55004, 55006, 55007 }, ["description"] = "I see Lord Browne running some sort of game over there. Getting people to guess the fight's winner in exchange for Brawler's Gold. See if you can figure out how his game works. If you win enough money from him, he might start talking...", ["objectivesText"] = "Win 100 Brawler's Gold from Lord Winifred Browne 's guessing game. If the game is not currently active, anyone can activate it by purchasing a High Roller's Contract from Ulaani. Progress: Lookin' to make some gold, old chap?", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 143762 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55006] = { ["id"] = 55006, ["name"] = "A Favor for Your Old Chum Winifred", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55006 }, ["series"] = { 55002, 55003, 55004, 55005, 55007 }, ["description"] = "A moment of your time, <good sir/madam>. It's about all that money you won from me. Interestingly enough, that may have been slightly more money than I actually have, and now it would appear that some very powerful people want to break my elbows and my knees. I cannot pay them! I am quite broke! Ha ha! All I need to get back above water is for you to lose your next fight. Flop like a fish, as they say. Please.", ["objectivesText"] = "Lose a fight in Bizmo's Brawlpub. Progress: You must help me! Their threats were quite descriptive, and slightly scatological!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55007] = { ["id"] = 55007, ["name"] = "Lord Browne's Debts", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55007 }, ["series"] = { 55002, 55003, 55004, 55005, 55006 }, ["description"] = "I've always said that I'm not too proud to commit a few acts of violence to set a wrong right. And you know what's wrong? I'm out of money! Only one person's won more gold from me than you have, and his name's Lord Sylysthrel. Quite the scoundrel, that one. I believe he was cheating. It sure would be nice if I could get that gold back...", ["objectivesText"] = "Obtain a Huge Pile of Legitimately-Earned Brawler's Gold from Lord Sylysthrel. You can challenge Lord Sylysthrel by purchasing his Challenge Card from Card Trader Leila. Progress: Once I get back the gold I lost, then I can REALLY start gambling!", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["rewardItems"] = { 164935, 164941 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55008] = { ["id"] = 55008, ["name"] = "Evidence Packet: Lord Winifred Browne", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55008 }, ["series"] = { 55009 }, ["description"] = "I heard everything. That guy sure does talk loudly about his crimes and debts, doesn't he? It sounds like we have enough to bring him in for questioning. I've put together a packet of evidence for Commander Daalo to review. Good job out there.", ["objectivesText"] = "Bring the Evidence Packet to Commander Daalo . Progress: Find anything on Browne?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 167034 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55009] = { ["id"] = 55009, ["name"] = "Undercover Agent: Saralara Fizzlesprang", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55009 }, ["series"] = { 55008 }, ["description"] = "I believe you've met one of my other agents: Saralara Fizzlesprang . She's investigating our second suspect: Shadowmaster O'Flannerty. You'll find Saralara near the scene of the crime.", ["objectivesText"] = "Speak with Saralara Fizzlesprang at Bizmo's Brawlpub.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55010] = { ["id"] = 55010, ["name"] = "Soul Splinters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55010 }, ["series"] = { 55011 }, ["description"] = "<O'Flannerty mumbles to himself.> Achh, what a mess... it's getting hungry again. Where am I going to find enough souls to feed it? Ohh... if only I could get my hands on some of those brawler's purses... <He notices you.> Oh! Ahoy there! Pay no attention to the mindless babbling of an innocent warlock. Nothing suspicious going on here!", ["objectivesText"] = "Search inside Brawler's Purses for something \"soul\"-related. Brawler's Purses are awarded to victors in Bizmo's Brawlpub. Some types of purses may be more lucrative than others. Progress: Oh dear, oh dear... must not let it get too hungry...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 92718, 142289, 142290, 164928, 164931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55011] = { ["id"] = 55011, ["name"] = "Super Soul Splinters", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55011 }, ["series"] = { 55010 }, ["description"] = "<O'Flannerty mutters to himself again:> Will these be big enough, though? It gets SO hungry for souls, and when it doesn't get enough, it gets angry, and we definitely don't want to trigger a void apocalypse in the middle of Stormwind. Oh dear, oh dear... <He notices you lingering.> Oh! The <race> is still here! Heh heh. Never mind me! Nothing evil going on here!!", ["objectivesText"] = "Obtain 3 Super Soul Splinters from Rumbler's Purses, which are rewarded from winning rumbles. Rumbles are large group fights that pit all players in Bizmo's Brawlpub queue against a challenging enemy. Anyone can start a rumble by purchasing a Rumble Card from Ulaani. Progress: <O'Flannerty looks around the arena in a panic.> Where can I find more souls? Maybe the quartermaster sells some? Oh, right, he's dead. Hmm...", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 164929, 164931 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55012] = { ["id"] = 55012, ["name"] = "Cause for Concern", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55012 }, ["series"] = { 55013, 55014, 55015, 55016 }, ["description"] = "Shadowmaster O'Flannerty's behavior was unusual. His repeated mutterings about \"shadow magic\" and \"void apocalypses\" and \"ancient creatures hungering for the souls of the living\" certainly warrant further investigation. You should report back to Saralara Fizzlesprang .", ["objectivesText"] = "Report to Saralara Fizzlesprang .", ["rewardGold"] = 30900, ["rewardXP"] = 1470, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55013] = { ["id"] = 55013, ["name"] = "The Precious 13-Tooth Gogglegear", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55013 }, ["series"] = { 55012, 55014, 55015, 55016 }, ["description"] = "We're going to have to invent something. Something capable of seeing into alternate dimensions. Something explosive that you strap directly onto your eyes. That's right, I'm talking about goggles. I already have all the goggle parts except for one: a 13-tooth gear. They're nearly impossible to find, but I KNOW that the G.G. Engineering boys have one, and Card Trader Leila has their challenge card.", ["objectivesText"] = "Obtain a 13-Tooth Gogglegear from G.G. Engineering. You can purchase their challenge card from Card Trader Leila. Progress: Are you ready to goggle up?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 94178, 164937 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55014] = { ["id"] = 55014, ["name"] = "The Fizzlesprang Goggle Experiment", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55014 }, ["series"] = { 55012, 55013, 55015, 55016 }, ["description"] = "Okay, before we start, I've got a few rules: First, these goggles will only work at close range. We're looking for something INSIDE the arena, so you'll have to be inside the arena to use them. Second rule: if you feel something starting to explode, try to blink real hard. Lastly, remember, we're looking for an evil shadow monster. You don't need to kill it, we just need you to see it so we can report it as evidence. Alright, go get in that arena and try them out!", ["objectivesText"] = "Put on Saralara's Goggles while fighting in Bizmo's Brawlpub and look for evidence against Shadowmaster O'Flannerty.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 167033 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55015] = { ["id"] = 55015, ["name"] = "Evidence Packet: Shadowmaster O'Flannerty", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55015 }, ["series"] = { 55012, 55013, 55014, 55016 }, ["description"] = "Sounds like we've found our perp, <name>. This guy's sketchy, desperate, and his shadow magic is consistent with that shadowy scroll you found earlier. Bring this packet to Daalo, and we can bring him in. Good work out there!", ["objectivesText"] = "Bring the Evidence Packet to Commander Daalo . Progress: Any news on O'Flannerty?", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 167035 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55016] = { ["id"] = 55016, ["name"] = "Undercover Agent: Silent Jussho", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55016 }, ["series"] = { 55012, 55013, 55014, 55015 }, ["description"] = "I've got one more suspect I'm investigating: Grant Lazarby. He's a wealthy worgen death knight socialite who spends most of his time spectating the arena from the VIP area. I've got my best agent on the case: Silent Jussho . Check in with him to see how his report is coming along.", ["objectivesText"] = "Report to Silent Jussho in the Brawlpub VIP Lounge. To enter the VIP Lounge, you must either be Rank 6 in Bizmo's Brawlpub, or someone must purchase a VIP Room Rental Form from Ulaani.", ["rewardGold"] = 341600, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55017] = { ["id"] = 55017, ["name"] = "Flaunt It If You Got It", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55017 }, ["series"] = { 55018 }, ["description"] = "Sigh... so dull... Oh, it's you! <name>, was it? I've seen a few of your fights. They're slightly less tedious than the standard humdrum bloodsport this arena has been producing lately. Let's spice things up a bit. Maybe buy some expensive drinks for ourselves? Buy a round of the cheap stuff for the riffraff below? Maybe even toss a few amberseed buns at the combatants?", ["objectivesText"] = "Drink a bottle of Moneybrau, purchase a round of drinks at the bar in Bizmo's Brawlpub, and hit a fighting player with an Amberseed Bun while standing in the VIP Lounge.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 98117, 98121, 143758 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55018] = { ["id"] = 55018, ["name"] = "Simply Dying of Boredom", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55018 }, ["series"] = { 55017 }, ["description"] = "Up until now, I've been dying of boredom up here. I think maybe we need some new blood here in the arena. Bizmo can be so stingy with his invitations, can't he? I've had one of my servants write up a few slightly-counterfeit invitations to hand out. Maybe you could help me get them distributed? There's always plenty of tough-looking characters hanging out in front of the auction house in the Trade District...", ["objectivesText"] = "Use the Bizmo's Brawlpub Sign in Stormwind's Trade District.", ["rewardGold"] = 312800, ["rewardXP"] = 11765, ["rewardItems"] = { 167038 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55019] = { ["id"] = 55019, ["name"] = "Evidence Packet: Grant Lazarby", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55019 }, ["series"] = { 55020, 55021, 55022 }, ["description"] = "Good work. I never expected Lazarby to be so... self-incriminating. You may bring the packet to Commander. I'm going to go buy some expensive snacks at the VIP bar.", ["objectivesText"] = "Bring the Evidence Packet to Commander Daalo . Provided item:", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 167036 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55020] = { ["id"] = 55020, ["name"] = "The Brawlpub Trial", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55020 }, ["series"] = { 55019, 55021, 55022 }, ["description"] = "I've issued three warrants. Jussho, Saralara, and Anne are apprehending the suspects as we speak. It's time to go to court. You may be called on to testify. Just answer as honestly as you can, and let the wheels of justice do the rest.", ["objectivesText"] = "Reach a verdict in the Brawlpub Trial.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55021] = { ["id"] = 55021, ["name"] = "A Clue from Area 52", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["mapID"] = 109, ["storyline"] = { 55021 }, ["series"] = { 55019, 55020, 55022 }, ["description"] = "We've received a letter from Area 52, the goblin outpost in Netherstorm. The author claims to know details about what they call \"the situation in the Brawlpub\". They don't say more than that. I'm tied to my paperwork here. Go check out this lead and see if anything turns up.", ["objectivesText"] = "Investigate Area 52 in Netherstorm for a sign of the letter's writer.", ["rewardGold"] = 309800, ["rewardXP"] = 11765, ["rewardItems"] = { 162973 }, ["ends"] = { { ["mapID"] = 109, ["npcID"] = 150320, ["x"] = 0.324, ["y"] = 0.6556 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.324, ["y"] = 0.6556 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55022] = { ["id"] = 55022, ["name"] = "Solving the Mystery", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3523, ["mapID"] = 109, ["storyline"] = { 55022 }, ["series"] = { 55019, 55020, 55021 }, ["description"] = "< Bizmo produces a challenge card from his pocket.> I grabbed this challenge card from my attackers while we were fighting each other! I'm sure that you can use it to challenge my attacker to some sort of ultimate showdown!", ["objectivesText"] = "Bring the Mysterious Challenge Card to Bizmo 's Brawlpub to confront Bizmo 's captor.", ["rewardGold"] = 1239200, ["rewardXP"] = 23530, ["rewardItems"] = { 164936, 166724 }, ["starts"] = { { ["mapID"] = 109, ["npcID"] = 150320, ["x"] = 0.324, ["y"] = 0.6556 } }, ["coords"] = { ["mapID"] = 109, ["source"] = "quest_giver", ["x"] = 0.324, ["y"] = 0.6556 }, ["mapCandidates"] = { ["npc"] = { 109 }, ["zone"] = { 3523 } }, ["questType"] = "standard" },
[55023] = { ["id"] = 55023, ["name"] = "Bizmo's Brawlpub Awaits!", ["level"] = 80, ["requiredLevel"] = 80, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2257, ["storyline"] = { 55023 }, ["description"] = "Tired of standing around in the boring old Trade District? Come on over to Bizmo's Brawlpub, and fight for the amusement of others! You might win, or you might get killed, but either way, you're going to have a great time. Grab an invitation and bring it to Han Heavypaw , near the front door. The Brawlpub awaits!", ["objectivesText"] = "Bring an invitation to Bizmo's Brawlpub. Provided item:", ["rewardGold"] = 315900, ["rewardXP"] = 11765, ["rewardItems"] = { 164949 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 2257 } }, ["questType"] = "standard" },
[55028] = { ["id"] = 55028, ["name"] = "It's Scrap Work...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 53802, 53806, 53848, 53947, 53948, 53949, 54930, 55028 }, ["description"] = "<name>, I'm glad you stopped by. The Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap. You'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open! <Layla makes finger guns and explosion sounds> Up for some treasure huntin'?", ["objectivesText"] = "Use the Coiled Current Culler on dead V-300 SENTRIES at the Abandoned Junkheap, then use it to collect the Ub3r-Spanner schematic from the Reinforced Schematic Cache. Progress: Did you find the schematic?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164740, 167037, 167041, 168152 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 869, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55030] = { ["id"] = 55030, ["name"] = "Blueprint: Scrap Trap", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55030 }, ["description"] = "<This blueprint details how to build what appears to be some sort of land mine using little more than scrap metal. You should be able to upload the blueprint to Pascal-K1N6 's database in Rustbolt.>", ["objectivesText"] = "Upload the blueprint to Pascal-K1N6 's database. Provided item:", ["rewardGold"] = 169800, ["rewardItems"] = { 167042 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150359, ["x"] = 0.714, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 167042 } },
[55031] = { ["id"] = 55031, ["name"] = "It's Scrap Work...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53783, 53802, 53806, 53833, 53848, 53937, 54930, 55031 }, ["description"] = "<name>, I'm glad you stopped by. The Ub3r-Spanner, capable of crafting powerful constructs, and its schematic have been lost for years. Intel tells us that its schematic is located in a locked cache in The Abandoned Junkheap. You'll need to overcharge its electric barrier to gain access. Take my Current Culler and soak up some of the latent current from the sentries there and zap that chest open! <Shuga makes finger guns and explosion sounds> Up for some treasure huntin'?", ["objectivesText"] = "Use the Coiled Current Culler on dead V-300 SENTRIES at the Abandoned Junkheap, then use it to collect the Ub3r-Spanner schematic from the Reinforced Schematic Cache. Progress: Did you find the schematic?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 164740, 167037, 167041 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 131840, ["x"] = 0.45, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 131840, ["x"] = 0.45, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 868, ["name"] = "Tools of the Trade: The Ub3r-Spanner", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55032] = { ["id"] = 55032, ["name"] = "Unchained Resistance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55032 }, ["description"] = "The naga have enslaved a tribe of makrura and sent them to labor as mindless thralls. The naga forces may be more in number, but the makrura have an innate advantage in both size and strength. If we break the makrura from their chains, they will surely overwhelm their naga overseers and put a dent in Queen Azshara's plans.", ["objectivesText"] = "Free 6 Makrura Slaves. Progress: The makrura will make short work of their former masters.", ["rewardGold"] = 234000, ["rewardItems"] = { 167070 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150553, ["x"] = 0.484, ["y"] = 0.525 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150553, ["x"] = 0.484, ["y"] = 0.525 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.525 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55033] = { ["id"] = 55033, ["name"] = "Ashes to Ashvane", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55033, 55044, 55045, 55116, 55117, 55118, 55119 }, ["description"] = "This place is just crawling with Ashvane loyalists, <name>. How about we do the Kul Tirans a favor and get rid of some of them. <Kelsey grins.> I got a head start on the way here, but there's plenty to go around!", ["objectivesText"] = "Slay Ashvane Loyalists in Freehold.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 19 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 921, ["name"] = "My Brother's Keeper", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55034] = { ["id"] = 55034, ["name"] = "Under False Colors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 70, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "If we wish to stay the executioner's axe, we'll need to throw Sylvanas off of our scent. You'll need to have your men take the ship to Chandlery Wharf, where they can disguise it as a pirate's bounty. Your task will be to ensure that Sylvanas' forces find the ship there. You must report to Nathanos that you spotted a stolen Forsaken vessel in that area. You have no connection to Derek Proudmoore, so it should raise no suspicions.", ["objectivesText"] = "Start the mission \"Casting the Bait\" then report to Nathanos Blightcaller aboard the Banshee's Wail in the Port of Zandalar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 167228 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 150311, ["x"] = 0.764, ["y"] = 0.428 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.764, ["y"] = 0.428 }, ["mapCandidates"] = { ["npc"] = { 70, 862 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55036] = { ["id"] = 55036, ["name"] = "A Terrible Place", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 55036 }, ["description"] = "You may have noticed all the disturbances happening around Azeroth. The Old God is rising, and its bad news for all of us. On occasion, one of these Pillars of Endless Truth will appear. Wonderful name don't you think? I have a knack for naming things. Where was I? Oh yes, right, these Pillars grant one access to the very mind of the Old God himself. They will show you a hint of what might yet come, what this world will look like should we fail to defeat him. Are you willing to see for yourself?", ["objectivesText"] = "Complete a Vision of N'Zoth.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[55039] = { ["id"] = 55039, ["name"] = "The Master Shipwright", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 942, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54706, 54708, 54721, 55043 }, ["description"] = "Now I am starting to remember... Dorian Atwater was a very secretive builder. Their slips were famously warded against prying eyes until the vessel was complete. It made something of a stir any time one of their works was revealed. Last I heard, they retired in Stormsong Valley. I am not certain how reliable that information is. Hm. We should head to Brennadam. It is a crossroads of sorts. If anyone knows where to find our shipwright, they will be there.", ["objectivesText"] = "Acquire the Letter from the Lord Admiral and meet Cyrus Crestfall in Brennadam. Progress: You've got that letter? I have a feeling we'll be needing it before long.", ["rewardGold"] = 154900, ["rewardXP"] = 2735, ["rewardItems"] = { 164762, 166462 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150515, ["x"] = 0.586, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55040] = { ["id"] = 55040, ["name"] = "Looking Inside", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "This vault screams of ancient gnomish tech! I believe this could be the key that leads us to King Mechagon! I can't risk putting myself in danger though, so you will lead the way into the vault. Well, what are we waiting for? Let's see what's inside!", ["objectivesText"] = "Enter the vault.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 149864, ["x"] = 0.655, ["y"] = 0.65 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 149877, ["x"] = 0.658, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.655, ["y"] = 0.65 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55043] = { ["id"] = 55043, ["name"] = "Fish Tales and Distant Sails", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54706, 54708, 54721, 55039 }, ["description"] = "I have an idea where to start, but it couldn't hurt to ask the locals. I hope it goes without saying that you shouldn't believe everything you hear, <name>. My people are very fond of embellishing the truth. I will meet you in The Golden Flagon when you've had a chance to ask around .", ["objectivesText"] = "Ask for information about the shipwright in Brennadam. Progress: Did you learn anything useful?", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 164762 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150515, ["x"] = 0.586, ["y"] = 0.704 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150515, ["x"] = 0.586, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55044] = { ["id"] = 55044, ["name"] = "Don't Shoot the Messenger", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55033, 55044, 55045, 55116, 55117, 55118, 55119 }, ["description"] = "While he was the gladiator known as Lo'Gosh, King Varian fought beside Valeera Sanguinar . He trusted her and that allowed SI:7 to have a... cordial relationship with her. Valeera's loyalty has carried on to King Anduin. During the fight with the Legion, I came to know her as a capable if... independent operative. She can go where even some of my agents cannot. We should listen to whatever message she brings. I imagine the source will be interesting.", ["objectivesText"] = "Listen to Valeera's message. Progress: This is... surprising news.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 150574, ["x"] = 0.7, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 70, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 19 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 921, ["name"] = "My Brother's Keeper", ["orderIndex"] = 5, ["flags"] = 0 } } },
[55045] = { ["id"] = 55045, ["name"] = "My Brother's Keeper", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 70, ["storyline"] = { 55033, 55044, 55045, 55116, 55117, 55118, 55119 }, ["description"] = "While I trust Valeera believes she is not leading us into a trap, I do not trust this isn't a Horde manipulation. <name>, I want you to come with me. I will meet with Baine, but I will not do so alone.", ["objectivesText"] = "Sail with Jaina to meet Baine off the coast of Theramore. Progress: This is... surprising news.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 245271, 252386, 252400, 252403, 252406, 252653, 252654, 252754 }, ["starts"] = { { ["mapID"] = 70, ["npcID"] = 150574, ["x"] = 0.7, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 70, ["source"] = "quest_giver", ["x"] = 0.7, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 70, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 19 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 921, ["name"] = "My Brother's Keeper", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55047] = { ["id"] = 55047, ["name"] = "Securing Warfang Hold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55047, 55048, 55049, 55050, 55051, 55052 }, ["description"] = "The Dark Lady has important work for you, <name>. Preparations are beginning for a meeting of the Horde's leadership at Warfang Hold. I trust I don't need to emphasize that security is of the highest import for this gathering. The goblin, Gallywix, has sent his underlings to make sure the area is swept of any... unwanted guests. I need you to make sure they succeed in their task.", ["objectivesText"] = "Meet with Boss Mida at Warfang Hold in Stormsong Valley.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 146013, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150690, ["x"] = 0.51, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 22 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 881, ["name"] = "Dark Consequences", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55048] = { ["id"] = 55048, ["name"] = "Spy Games", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55047, 55048, 55049, 55050, 55051, 55052 }, ["description"] = "The Alliance must've got wind of this meeting and they've sent SI:7 spies to try to listen in. The problem is, they're using some kind of gnomish tech to sneak past our detectors. One of our techs was able to put together something that should be able to neutralize whatever they're using, but the range is short. I'll need you to take it out into the field and look for evidence of SI:7 activity. Just mash the button on that thing when you think they're close, and it should zap 'em back into view.", ["objectivesText"] = "Use the Electronic Mayhem Projector to reveal and kill 10 SI:7 spies in the Clearcut.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 167078 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150690, ["x"] = 0.51, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150690, ["x"] = 0.51, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 22 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 881, ["name"] = "Dark Consequences", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55049] = { ["id"] = 55049, ["name"] = "Communication Breakdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55047, 55048, 55049, 55050, 55051, 55052 }, ["description"] = "It looks like the stealth generators aren't the only tech that SI:7 is bringing into the field. Our scouts have reported what look like listening devices set up at key points around Warfang. Obviously, these things have to go, but the goons haven't been able to get close to them on account of the hidden spies. While you're out there, make sure to trash 'em.", ["objectivesText"] = "Destroy 3 SI:7 Listening Devices near Warfang Hold.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150690, ["x"] = 0.51, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150690, ["x"] = 0.51, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 22 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 881, ["name"] = "Dark Consequences", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55050] = { ["id"] = 55050, ["name"] = "Tickets, Please?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55047, 55048, 55049, 55050, 55051, 55052 }, ["description"] = "There's another problem we could use your help with, <class>. Gallywix knew this meeting was going to be a big deal, so naturally he decided to sell tickets. The thing is, I've done a headcount here, and we've got a lot more people here than tickets sold, so some of these spectators are trying to pull a fast one. Most of our muscle is out in the Clearcut getting killed by spies, so we could use the help. Care to make an honest wage?", ["objectivesText"] = "Eject 5 ticketless Visiting Spectators from Warfang Hold. Progress: The nerve of these people!", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 167096 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150691, ["x"] = 0.51, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150691, ["x"] = 0.51, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 22 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 881, ["name"] = "Dark Consequences", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55051] = { ["id"] = 55051, ["name"] = "A Display of Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55047, 55048, 55049, 55050, 55051, 55052 }, ["description"] = "It looks like all the big players are here. This thing's gonna be starting any moment now. You'll probably want to get a good seat.", ["objectivesText"] = "Speak to Nathanos Blightcaller to witness the meeting of leaders in Warfang Hold.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150690, ["x"] = 0.51, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150678, ["x"] = 0.506, ["y"] = 0.322 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 22 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 881, ["name"] = "Dark Consequences", ["orderIndex"] = 5, ["flags"] = 0 } } },
[55052] = { ["id"] = 55052, ["name"] = "Securing Warfang Hold", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55047, 55048, 55049, 55050, 55051, 55052 }, ["description"] = "<name>, the Dark Lady has need of your services once more. The traitor, Baine, is being brought before the leaders of the Horde at Warfang Hold. Preparations are underway as we speak to secure the area. The efforts are headed up by Gallywix's minions, who I wouldn't trust to secure a kennel. You will need to go to Warfang Hold and make sure the area is locked down. We are counting on you, <name>.", ["objectivesText"] = "Meet with Boss Mida at Warfang Hold in Stormsong Valley.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150690, ["x"] = 0.51, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 942 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 22 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 881, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 881, ["name"] = "Dark Consequences", ["orderIndex"] = 1, ["flags"] = 0 } } },
