[55087] = { ["id"] = 55087, ["name"] = "The Gathering Storm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "While I deal with the naga incursions, Lady Proudmoore is going to take on handling the Horde in Stormsong Valley and figuring out what happened to our spies there. You'll find her near Proudmoore Keep.", ["objectivesText"] = "Report to Jaina Proudmoore near Proudmoore Keep in Boralus.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 21398, 21399, 21400, 211279, 237812 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 150633, ["x"] = 0.5735, ["y"] = 0.4475 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55088] = { ["id"] = 55088, ["name"] = "Lost in the Field", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "When Shaw and I got here we discovered most of our operatives were dead. Most, but not all. Go into the field and get any of our operatives out of there. They might have more intel on what the Horde are planning here in Warfang Hold.", ["objectivesText"] = "Assist injured spies in Stormsong Valley.", ["rewardGold"] = 241020, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.407333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55089] = { ["id"] = 55089, ["name"] = "Shaw's Shank Redemption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "Hmm. Shaw said he'd check in when we got communications back but he hasn't. He's probably run into the same trouble the rest of our spies did. I'll stay here and guard the listening post. You find Shaw. He was headed for the cliff above Warfang Hold near the top of the waterfall. The peons called that area \"The Screaming Pit\" for some reason. I bet it's a real pleasant place. Stab whatever he's fighting for me, okay?", ["objectivesText"] = "Find Mathias Shaw in The Screaming Pit above Warfang Hold. Progress: Just in time, <name>.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150640, ["x"] = 0.482, ["y"] = 0.332 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.407333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 7, ["flags"] = 0 } } },
[55090] = { ["id"] = 55090, ["name"] = "A Gathering of Foes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "Before I was distracted, I was able to find out more about this Horde gathering. Sylvanas has summoned the leaders of the Horde and its allies. For what purpose, I cannot say. We aren't in a position to strike her down--she is too well-protected. But perhaps we can learn something that will prove useful in the ongoing war. Keep your head low and take a look. I'll keep an eye out for more guards.", ["objectivesText"] = "Witness the Horde gathering.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150640, ["x"] = 0.482, ["y"] = 0.332 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 150633, ["x"] = 0.5735, ["y"] = 0.4475 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.332 }, ["mapCandidates"] = { ["npc"] = { 942, 1161 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 8, ["flags"] = 0 } } },
[55092] = { ["id"] = 55092, ["name"] = "Disruption of Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55481, 56063, 56429 }, ["description"] = "The naga tap into the power within nearby ley lines and have found a way to harness it. Destroy their devices before they can put that power to use against us.", ["objectivesText"] = "Destroy 5 Ley Line Accumulators in Spears of Azshara.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.396667, ["y"] = 0.775333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 886, ["questLineOrder"] = 23 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 886, ["name"] = "Azshara's Trap", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 5, ["flags"] = 0 } } },
[55094] = { ["id"] = 55094, ["name"] = "Stay Low, Stay Fast!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55481, 56063, 56429 }, ["description"] = "It's a straight shot home. We just need to be careful. Neri's rule of survival number six: always be prepared! Let's go!", ["objectivesText"] = "Follow Neri Sharpfin .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150209, ["x"] = 0.367333, ["y"] = 0.676667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151849, ["x"] = 0.485, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.367333, ["y"] = 0.676667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 886, ["questLineOrder"] = 23 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 886, ["name"] = "Azshara's Trap", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 9, ["flags"] = 0 } } },
[55095] = { ["id"] = 55095, ["name"] = "Upheaval", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "So many lives lost... And the attacks from the naga are relentless! I apologize, $p. This attitude is unbecoming of a king. We have no time to lose musing of our own plight. Let us meet with Jaina and descend from this perilous place into the unknown.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore above the waterfall.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150087, ["x"] = 0.4696, ["y"] = 0.8276 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.4696, ["y"] = 0.8276 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55096] = { ["id"] = 55096, ["name"] = "Send My Father a Message", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "My people are once again safe... for now. King Mechagon won't stop sending his armies at us as long as he does not fear us. We must send him a message. Climb to the top of the ramparts, and hack one of my father's projectors to proudly shine the banner of the Rustbolt Resistance big enough for the whole island to see. I'm sure that'll attract the attention of my father, King Mechagon .", ["objectivesText"] = "Hack a projector to display the Rustbolt Resistance emblem and defend it.", ["rewardGold"] = 772200, ["rewardXP"] = 2125, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151947, ["x"] = 0.712, ["y"] = 0.36 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.36 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6062, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 6062, ["name"] = "Mechagon Intro - On Island", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55099] = { ["id"] = 55099, ["name"] = "TBD NOT USED", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 55099 }, ["description"] = "The fabled workbench of Rustbolt - MY workbench - has fallen into disrepair! This tragedy was no doubt caused by the same ruffians and miscreants who kidnapped me and Princess Wiggles. The VERY same ruffians and miscreants, in fact, who still show their faces in this very town on the regular. Their presence here is a veritable slap to our collective faces! Dispatch the snatchers quickly and recover my binder of blueprints. We may then commence crafting what we shall need to repair this.", ["objectivesText"] = "Collect the Junkyard Blueprint Book from Scrapthief Grillin.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167093 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[55101] = { ["id"] = 55101, ["name"] = "Junkyard Tinkering and You", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55101, 55103, 56181 }, ["description"] = "Behold, the fabled Pascal Workshop of Rustbolt -- MY workshop! Countless inventions have sprung forth into existence on this very spot, including my very finest invention, Pascal -K1N6! Pascal -K1N6 can craft anything... as long as you have the blueprints for it. And since I have you to thank for the K1N6's safe return to Rustbolt, would you like to learn how to access his blueprints database?", ["objectivesText"] = "Use Pascal -K1N6 to craft a Scrap Grenade. Progress: Remember, you can collect Spare Parts from almost anything on Mechagon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 167846 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152295, ["x"] = 0.712, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152295, ["x"] = 0.712, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 954, ["name"] = "Junkyard Tinkering", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55103] = { ["id"] = 55103, ["name"] = "Ideas Can Come from Anywhere", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55101, 55103, 56181 }, ["description"] = "I didn't notice the tinkerer's spark in you when we first met. But look at all of the blueprints you've recovered and uploaded to Pascal -K1N6's database. I was wrong. And happily so, my budding junkyard tinkering apprentice! But this is a dangerous moment in your creative development. You must avoid complacency! Take time off to find new ideas. Speak with builders that inspire you, reverse-engineer bots on the island, and be open to new ideas - no matter where they come from!", ["objectivesText"] = "Find people and things to inspire 1 new ideas in Mechagon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166972, 166973, 168057, 168222, 168496, 168497, 168821, 168843, 168907, 169224, 169225, 169226, 169227, 169228, 169229, 169230, 169231, 169232, 169233, 169235, 169236, 169237, 169238, 169239, 169240, 169246, 169247, 169248, 169249, 169250, 169251, 169252, 169253, 169255, 169257, 169383, 169384, 169649, 169874, 170541, 170542 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152295, ["x"] = 0.712, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152295, ["x"] = 0.712, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 954, ["name"] = "Junkyard Tinkering", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55111] = { ["id"] = 55111, ["name"] = "Creature Study: Zanj'ir Naga", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 55111 }, ["description"] = "<Scrawled upon the magical scroll are Maedin's incomplete notes on the Zanj'ir naga.>", ["objectivesText"] = "Use Maedin's Scroll to collect data from various creatures within Nazjatar .", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167091, 169444 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 167090 } },
[55116] = { ["id"] = 55116, ["name"] = "Getting a Clue", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55033, 55044, 55045, 55116, 55117, 55118, 55119 }, ["description"] = "I'm betting that one page of jibberish is a coded message. We can send it back to Stormwind to be cracked by our codebreakers or we could break some heads and find the cipher here. I'm thinking we'll just save some time and do that. The guy in charge here probably has what we're looking for. Why don't you take him out and see if you can't find it. Even if you don't, without a leader the loyalists won't be much trouble. It's a win-win! Well, for us I guess.", ["objectivesText"] = "Slay Haughton Francis and recover his cipher. Progress: Did you find a cipher? Or some kind of decoding gadget?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167155 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 19 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 921, ["name"] = "My Brother's Keeper", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55117] = { ["id"] = 55117, ["name"] = "Correspondence Conundrum", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55033, 55044, 55045, 55116, 55117, 55118, 55119 }, ["description"] = "I think Ashvane has been in contact with her loyalists, but I don't know what their orders are. Go into their camp and see if you can't read their mail. We might find something that leads back to where Lady Ashvane is hiding or what their next move is going to be.", ["objectivesText"] = "Discover information about Lady Ashvane's plans.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167065, 167149, 167151, 167153, 167154 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 19 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 921, ["name"] = "My Brother's Keeper", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55118] = { ["id"] = 55118, ["name"] = "Loose Ends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55033, 55044, 55045, 55116, 55117, 55118, 55119 }, ["description"] = "Our campaign against the Horde is going strong, but there are some loose threads to take care of. Lady Ashvane was broken out of Tol Dagor - by the Horde. We don't know where she's gone or what she is planning. I sent Kelsey out to track down some Ashvane Loyalists to get answers. She found them and has requested backup. She's waiting for you in Freehold.", ["objectivesText"] = "Meet Kelsey Steelspark in Freehold.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 202201, 237812 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 19 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 921, ["name"] = "My Brother's Keeper", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55119] = { ["id"] = 55119, ["name"] = "Reporting In!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55033, 55044, 55045, 55116, 55117, 55118, 55119 }, ["description"] = "Well it looks like Ashvane's been out of contact for some time but this 'Patron' thing could be a problem. You did excellent work today, <name>. Those Loyalists aren't going to be thinking about causing trouble for awhile, heh. I'll make my way back. You take the letter to the High Commander.", ["objectivesText"] = "Report to Halford Wyrmbane in Boralus. Progress: Did you find anything on Ashvane?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 167102 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 150796, ["x"] = 0.8, ["y"] = 0.75 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.8, ["y"] = 0.75 }, ["mapCandidates"] = { ["npc"] = { 895, 1161 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 19 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 921, ["questLineOrder"] = 12 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 921, ["name"] = "My Brother's Keeper", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55121] = { ["id"] = 55121, ["name"] = "The Laboratory of Mardivas", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["storyline"] = { 55121 }, ["description"] = "<Several pages are devoted to notes on an experiment, a hastily written journal entry follows.> At last, my research into the base elements has begun to bear fruit! With careful application of the right base reagents and some arcane power I've managed to combine the essence of the elements in such a way as to create life! Further investigation will be needed to determine what the various mixes of the elements will yield. <The writing ends here.>", ["objectivesText"] = "Activate the Elemental Essence Amalgamator in Mardivas's Laboratory. Progress: <The remaining pages are filled with gibberish and strange doodles.>", ["rewardGold"] = 234000, ["rewardItems"] = { 166888, 167012, 167059, 167077, 169332, 169333, 169334, 170068, 170124, 170125, 170126, 170127, 170128, 170129, 170130, 170131, 170132, 170137, 170138, 170166, 170192, 170383, 170477, 170512 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55124] = { ["id"] = 55124, ["name"] = "Righting Wrongs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 54958, 54959, 54960, 54961, 54997, 54999, 55034, 55124 }, ["description"] = "Champion! I come with an urgent request from Baine Bloodhoof . He asks that you meet him at Plunder Harbor to help him with a... sensitive situation. You must tell no one of this request, <class>. Ancestors watch over you.", ["objectivesText"] = "Meet with Baine Bloodhoof at Plunder Harbor in Tiragarde Sound.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 150433, ["x"] = 0.498, ["y"] = 0.957 } }, ["ends"] = { { ["mapID"] = 70, ["npcID"] = 150309, ["x"] = 0.765, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.498, ["y"] = 0.957 }, ["mapCandidates"] = { ["npc"] = { 70, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 21 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 873, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 873, ["name"] = "Testing Loyalties", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55136] = { ["id"] = 55136, ["name"] = "Her Dog Days Are Over", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 53720, 54706, 54708, 54721, 54723, 54725, 54726, 54727, 54728, 54729, 54730, 54731, 54732, 54733, 54734, 54735, 54851, 55039, 55043, 55136 }, ["series"] = { 54729, 54732 }, ["description"] = "<The Wicker Beast gently nudges the dog's body with its snout. The creature whines plaintively and moves to your side. It gives a hopeful twitch of its bony tail.>", ["objectivesText"] = "Walk the Wicker Beast . Progress: What's this...? I see you found my keys, but...", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 164762, 167168, 167172, 167173, 167174 }, ["starts"] = { { ["mapID"] = 896, ["npcID"] = 150885, ["x"] = 0.35, ["y"] = 0.2965 } }, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 150884, ["x"] = 0.332, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.2965 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 916, ["name"] = "Allies of the Alliance: Kul Tiran", ["orderIndex"] = 13, ["flags"] = 0 } } },
[55137] = { ["id"] = 55137, ["name"] = "For the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 31 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 55137, 55138 }, ["description"] = "Thank you for meeting me upon my throne, <name>. With our recent partnerin' with de Horde, I need worthy champions to represent the might of the Zandalari. I have chosen you to be among their ranks, <name>. Go and meet with the ambassador in Orgrimmar. We have prepared a portal just behind you. When you are ready, step through to a new world. Remember, you bow only to the throne of Zandalar. Hold your head high, <name>.", ["objectivesText"] = "Meet with Ambassador Blackguard in the Orgrimmar Embassy.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 146335, ["x"] = 0.473333, ["y"] = 0.340667 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.473333, ["y"] = 0.340667 }, ["mapCandidates"] = { ["npc"] = { 85, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 918, ["name"] = "Allies of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55138] = { ["id"] = 55138, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 31 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 55137, 55138 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Find the Warchief's Command Board in Orgrimmar. Progress: Dis land is much less... fertile than Zandalar.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 150909, ["x"] = 0.4735, ["y"] = 0.7745 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 918, ["name"] = "Allies of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55142] = { ["id"] = 55142, ["name"] = "For the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55142, 55146 }, ["description"] = "Thank you for meeting with me, <name>. I need representatives to go to Stormwind to represent our loyalty and commitment to our newly forged bond with the Alliance. I've had Yvia and her magi prepare a portal to the city for you in the Sanctum of the Sages. Once there, go to the Stormwind Embassy and meet with Ambassador Moorgard . You will face many challenges on the long journey ahead. Remember where you came from and make your people proud!", ["objectivesText"] = "Take the portal to Stormwind in the Sanctum of the Sages and meet with Ambassador Moorgard in the Stormwind Embassy. Progress: Welcome to Stormwind, <race>.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 37500, 42792, 42805, 42817, 42830, 65618, 65625, 65639, 65642, 66073, 94219, 108908, 108909, 108910, 108912, 108913, 108914, 108918, 108919, 116202, 151557, 157022, 157756, 157758, 161329, 165010, 165872, 166883, 168615, 168850, 169764, 174068, 174507, 204616, 204617, 204618, 204619, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150941, ["x"] = 0.519333, ["y"] = 0.489333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.519333, ["y"] = 0.489333 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 917, ["name"] = "Allies of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55146] = { ["id"] = 55146, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 55142, 55146 }, ["description"] = "Welcome to Stormwind, <race>. I invite you to explore our fair city. Since you hail from Kul Tiras, might I suggest visiting our lovely docks? They are home to our majestic fleet. I would be shocked if you were not impressed! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of Kul Tiras is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay.", ["objectivesText"] = "Find Chromie in Stormwind City. Progress: Enjoying your stay in Stormwind?", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 150947, ["x"] = 0.5988, ["y"] = 0.2484 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 917, ["name"] = "Allies of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55153] = { ["id"] = 55153, ["name"] = "Collaborative Construction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55153 }, ["description"] = "Construction projects can be found all over the island. You'll be able to build some of 'em yourself, but you're gonna need help with the bigger projects. Ask around and see what others are already working on, or just head out on your own and find a project you're interested in. Construction projects move around and even change day-to-day, so keep an eye out for new ones while you're exploring. If you're ever curious what construction projects are available on a given day, just ask me!", ["objectivesText"] = "Find a construction project in Mechagon and help build it.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 960, ["name"] = "Construction Projects", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55171] = { ["id"] = 55171, ["name"] = "Spy Versus Spy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "Naga attacks are on the rise, but that isn't all we have to deal with. We've received word of increased Horde activity near Warfang Hold in Stormsong Valley. Send some of our operatives to investigate what they are doing.", ["objectivesText"] = "Complete the mission \"Spy on Warfang Hold\" Progress: Hopefully we can gather information on what they're up to in Stormsong Valley.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 165748 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 135612, ["x"] = 0.6945, ["y"] = 0.2665 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6945, ["y"] = 0.2665 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55175] = { ["id"] = 55175, ["name"] = "Where the Road Leads", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "My people know many secrets about this place. If you prove yourselves worthy allies, you will be privy to them. First, we must regroup in Mezzamere. There, we at least have a foothold against the tide.", ["objectivesText"] = "Travel to Mezzamere with Okani.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151000, ["x"] = 0.5276, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.5276, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 8, ["flags"] = 0 } } },
[55177] = { ["id"] = 55177, ["name"] = "Tearing at the Seams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 53805, 53807, 53881, 55177 }, ["series"] = { 53807 }, ["description"] = "I feel odd... weak. As though something is affecting my very existence. Would you come with me, <name>? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", ["objectivesText"] = "Speak with Delormi when you're ready to leave and investigate the disturbance.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 152576, 152668, 159959, 164733, 168029, 168128, 168129, 168130, 168131 }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["questLines"] = { { ["id"] = 904, ["name"] = "8.1.5 Tailoring - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55179] = { ["id"] = 55179, ["name"] = "Retaliation Coordination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "Master Shaw deployed a number of Alliance spies near a base the Horde have made in Stormsong Valley. When our spies stopped checking in, he took Kelsey Steelspark and went to investigate. Now Master Shaw is the one who hasn't checked in. I need someone to go in and find our missing people and give them whatever help they clearly need.", ["objectivesText"] = "Find Kelsey Steelspark in Stormsong Valley.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150633, ["x"] = 0.5735, ["y"] = 0.4475 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.5735, ["y"] = 0.4475 }, ["mapCandidates"] = { ["npc"] = { 942, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55182] = { ["id"] = 55182, ["name"] = "Reassembly Required", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "Master Shaw wanted me to rebuild the listening posts the Horde destroyed when they started to clear the area in preparation for whatever they are planning. I managed to salvage most of the parts for one, but I'm missing a few. Fortunately for us, I've been watching the workers and they've been picking up the pieces of the destroyed machines. Go get our tech back and I can take care of the rest.", ["objectivesText"] = "Collect Spy Salvage from Horde Forces. Progress: I am so excited! I love getting to work with our spy tech! Did you find what we need?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 167216 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.407333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55183] = { ["id"] = 55183, ["name"] = "Seeking Higher Ground", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "We've only got one shot at reestablishing our communication network, so we've got to pick the right spot and I found just the right place! While you've been busy down here, I set up some camouflage and hauled the bulk of the machinery up there. What? Did you think I was just sitting here polishing my knives while you were gone? Well, okay I did that too. Anyway, I'll meet you up the hill!", ["objectivesText"] = "Meet Kelsey Steelspark on the hill south of Warfang Hold.", ["rewardGold"] = 30300, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.407333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 5, ["flags"] = 0 } } },
[55185] = { ["id"] = 55185, ["name"] = "Listen Up!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 55087, 55088, 55089, 55090, 55171, 55179, 55182, 55183, 55185 }, ["description"] = "Okay! Once we get this up and running we should be able to send messages! In the valley at least. It's gonna be a little bit tricky, but I've read the manual for these things cover to cover. <Kelsey slaps the top of the listening device.> I'm gonna put this thing back together. You watch out for the Horde.", ["objectivesText"] = "Protect Kelsey Steelspark in Stormsong Valley. Progress: Woohoo! We are up and operational!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 208929, 211279, 237812 }, ["starts"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 150637, ["x"] = 0.495333, ["y"] = 0.407333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.495333, ["y"] = 0.407333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 20 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 922, ["questLineOrder"] = 13 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 922, ["name"] = "The Gathering Storm", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55188] = { ["id"] = 55188, ["name"] = "Tearing at the Seams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 65, ["mapID"] = 115, ["storyline"] = { 53938, 53940, 53962, 55188 }, ["series"] = { 53940 }, ["description"] = "I feel odd... weak. As though something is affecting my very existence. Would you come with me, <name>? I may need your help. At the very least, you could be a witness to whatever happens should something dire occur.", ["objectivesText"] = "Speak with Delormi when you're ready to leave and investigate the disturbance.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 65 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 71, ["questLines"] = { { ["id"] = 905, ["name"] = "8.1.5 Tailoring - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55195] = { ["id"] = 55195, ["name"] = "Reverberation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredClasses"] = { 3 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 67, ["mapID"] = 120, ["storyline"] = { 54913, 54915, 54916, 54917, 54918, 54919, 54920, 55195, 55516 }, ["description"] = "Hati's spirit is bound to yours forevermore, hunter. But it also now carries a link to the Temple of Storms--as well as Silithus, I fear. The Thunderspark shares these same bonds. By physically linking it here, you can call upon the different aspects of Hati's spirit and bind them to yourself as well. Do not worry. Skoll and I will guard the Thunderspark with our very lives! It will be safe.", ["objectivesText"] = "Use the Thunderspark to summon an Essence of Hati. Progress: It warms my heart to see Hati by your side once more.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 167799, 167800 }, ["starts"] = { { ["mapID"] = 120, ["npcID"] = 29445, ["x"] = 0.334, ["y"] = 0.58 } }, ["ends"] = { { ["mapID"] = 120, ["npcID"] = 29445, ["x"] = 0.334, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 120, ["source"] = "quest_giver", ["x"] = 0.334, ["y"] = 0.58 }, ["mapCandidates"] = { ["npc"] = { 120 }, ["zone"] = { 67 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 120, ["questLines"] = { { ["id"] = 862, ["name"] = "Never Hunt Alone", ["orderIndex"] = 8, ["flags"] = 0 } } },
[55210] = { ["id"] = 55210, ["name"] = "Batteries Not Included", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55210, 55211, 56319, 56320 }, ["description"] = "You will not be sorry that you rescued my dear sister and me, $p. We are the vanguard of a new technological revolution, creating opportunities for all to enhance their lives with incredible technology! But, before we can do that, we need our laboratory to be fully powered. Those ruffians from Mechagon really did a number on our equipment. Fully charged energy cells are exceptionally rare around here, but I can make do with broken ones. Check around town, in the wreckage from the last attack.", ["objectivesText"] = "Collect 10 Damaged Energy Cells . Progress: Everything old can be made new again.", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 53270, 53281, 53285, 53303, 131400, 166971, 167233 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.721, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 953, ["name"] = "Rustbolt Energy", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 959, ["name"] = "Quickcharge Experiments", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55211] = { ["id"] = 55211, ["name"] = "Recharging Rustbolt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55210, 55211, 56319, 56320 }, ["description"] = "Our personal generator is worthless until we recharge its empty energy cells . As my dear brother says, energy cells are the lifeblood of innovation. Everything in Mechagon needs power, and energy cells deliver that power in a wonderfully universal format. But, once they're drained of power, most people toss the empty cells away. Most people are fools, dear test subject. We have perfected the technology to recharge small numbers of energy cells back to full power. Will you help us test it?", ["objectivesText"] = "Use the NRG-100 to charge 6 generator energy cells . Progress: We only test the best!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166970, 168122 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 959, ["name"] = "Quickcharge Experiments", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55213] = { ["id"] = 55213, ["name"] = "Energy Cells for Everyone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55213 }, ["description"] = "The wondrous scuttlebutt around town is that the charging station in Bondo's Yard is going to be repaired today! That charging station is the best way to recharge all the Empty Energy Cells that've been piling up in your bag. Or in other people's bag. Or inside the mechanical innards of robots you don't own but are legally allowed to destroy. After you've acquired Empty Energy Cells, help build the charging station in Bondo's Yard and charge all of your Empty Energy Cells!", ["objectivesText"] = "Find 5 Empty Energy Cells in Mechagon . Then, help build the Charging Station construction project and use it to charge your Empty Energy Cells. Progress: Empty Energy Cells can always be found on the island, but the Charging Station isn't always available. Chat with that wondrous Miss Gearhart if you want to know more.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard" },
[55214] = { ["id"] = 55214, ["name"] = "Seam Stress", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["requiredProfessions"] = { "tailoring" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 115, ["storyline"] = { 53810, 53813, 53858, 53866, 53868, 53869, 55214 }, ["series"] = { 53858, 53866 }, ["description"] = "I...I need a moment, <name>. <Delormi seems disoriented and grabs your shoulder for support. She presses her hand against her forehead and stands there for a minute. Finally shaking off whatever she was feeling, she stands up straight and faces you.> There are gaps in my memories. Things important to me, lost now. We must stop her at all costs, <name>.", ["objectivesText"] = "Follow Delormi through the Time Rift. Progress: I feel so weak...", ["rewardGold"] = 68950, ["rewardXP"] = 6815, ["rewardItems"] = { 152576, 152668, 159959, 164733, 167231, 168029, 168128, 168129, 168130, 168131 }, ["starts"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["ends"] = { { ["mapID"] = 115, ["npcID"] = 151134, ["x"] = 0.715, ["y"] = 0.397 } }, ["coords"] = { ["mapID"] = 115, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.397 }, ["mapCandidates"] = { ["npc"] = { 115 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 906, ["name"] = "8.1.5 Tailoring - Alliance/Horde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55215] = { ["id"] = 55215, ["name"] = "The Cycle of Life", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 55215 }, ["objectivesText"] = "Speak to Scrollsage Nola Stop Juvenile Turtles From Reaching the Ocean", ["rewardGold"] = 280900, ["rewardXP"] = 2090, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Speak to Scrollsage Nola", ["amount"] = 1, ["type"] = 3, ["objectID"] = 150759, ["orderIndex"] = 0 }, { ["text"] = "Stop Juvenile Turtles From Reaching the Ocean", ["amount"] = 20, ["type"] = 0, ["objectID"] = 150646, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["db2QuestInfoID"] = 152, ["db2QuestInfoName"] = "Tortollan World Quest - 8.0" },
[55216] = { ["id"] = 55216, ["name"] = "The Audition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53995, 55216, 55221, 55222, 55223 }, ["description"] = "Xanjo has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you. If you are willing, I would like to provide you with a test to see how well you can work leather. Bring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency. If your work is up to par, I will inform you of my plan.", ["objectivesText"] = "Craft 3 Drums of the Maelstrom and bring them to Atikka Moonchaser. Progress: <Atikka breathes audibly in anticipation of your return.> Have you got the drums?", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 154167 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.925333 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 908, ["name"] = "8.1.5 Leatherworking - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55217] = { ["id"] = 55217, ["name"] = "Repaying the Life Debt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 55217, 55218 }, ["description"] = "When I heard that the Alliance attacked Dazar'alor, I couldn't help but think of those lost when they attacked Camp Taurajo. No longer can I sit idly while they continue to slaughter us! I need you to go to Thunder Bluff, find Sheza Wildmane on the Elder Rise, and ask for some of her personal collection. I won't go into detail, but she owes me a life debt, and seeing her would... bring back too many painful memories... for both of us. Find her, tell her I sent you, and that this absolves her debt.", ["objectivesText"] = "Speak with Sheza Wildmane in Thunder Bluff.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["ends"] = { { ["mapID"] = 88, ["npcID"] = 3037, ["x"] = 0.695, ["y"] = 0.270667 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.925333 }, ["mapCandidates"] = { ["npc"] = { 88, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 88, ["questLines"] = { { ["id"] = 931, ["name"] = "8.1.5 Leatherworking - Horde - Classic Content", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55218] = { ["id"] = 55218, ["name"] = "Sheza's Prized Leather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1638, ["mapID"] = 88, ["storyline"] = { 55217, 55218 }, ["description"] = "I have a stash of extremely rare leathers, or... rather, I did. I don't know how, but the Venture Company must have heard how valuable my collection was because they stole it! And THEN they had the audacity to leave a note offering to sell it back to me for 1,000 gold! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\" The note states they'll be in the bluffs to the East until someone buys them. However you get the skins, consider them yours.", ["objectivesText"] = "Retrieve the Rare Hides . Progress: How was she?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167541, 167673 }, ["starts"] = { { ["mapID"] = 88, ["npcID"] = 3037, ["x"] = 0.695, ["y"] = 0.270667 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 88, ["source"] = "quest_giver", ["x"] = 0.695, ["y"] = 0.270667 }, ["mapCandidates"] = { ["npc"] = { 88, 1165 }, ["zone"] = { 1638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 931, ["name"] = "8.1.5 Leatherworking - Horde - Classic Content", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55219] = { ["id"] = 55219, ["name"] = "Dropping by the Base", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 55219, 55220 }, ["description"] = "When the Legion was attacking, I met with a member of the Highmountain Tauren who had a knack for making and playing drums. Torv usually keeps to himself, but he is as brilliant as he is insane. If there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him. Head to Thunder Totem, and ask Torv Dubstomp if he can think of a suitable source of scales. Preferably something still living, so its power is still fresh.", ["objectivesText"] = "Speak with Torv Dubstomp in Thunder Totem.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.925333 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 932, ["name"] = "8.1.5 Leatherworking - Horde - Legion Content", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55220] = { ["id"] = 55220, ["name"] = "Bass Fishing", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 1165, ["storyline"] = { 55219, 55220 }, ["description"] = "Have you heard of people taking small golden carp as pets? Well, if it is kept in a pond free of predators, over time it can grow enormous, only limited by the food present. Centuries ago, one of these fish lived in the pond atop a mountain. It ate everything and began to starve, so my people dug a river that connected the pond to the ocean so the fish could be free. Now, fishermen talk of being attacked by an enormous golden fish in the Rockaway Shelf. Kill it. Take his scales back to Atikka.", ["objectivesText"] = "Collect Brilliant Golden Scales . Progress: Did you meet with Torv yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167543 }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.925333 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 932, ["name"] = "8.1.5 Leatherworking - Horde - Legion Content", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55221] = { ["id"] = 55221, ["name"] = "Picking Bones", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 1165, ["storyline"] = { 53995, 55216, 55221, 55222, 55223 }, ["description"] = "When I was sailing in, I noticed the remains of an unbelievably large beast on the nearby peninsula. Whatever it was, it must have been strong, making it the perfect source for the bone elements of the drums. Go to the peninsula, 'Xibala' I've heard it called, and fill a bag with the bones you find. If you come across any of those damned Alliance, show them no mercy. They did this to themselves.", ["objectivesText"] = "Collect 18 Unwaning Bones . Progress: Did you get the bones? Did the Alliance give you any trouble?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 165231 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.925333 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 908, ["name"] = "8.1.5 Leatherworking - Horde", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55222] = { ["id"] = 55222, ["name"] = "Make Some Noise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53995, 55216, 55221, 55222, 55223 }, ["description"] = "We have everything we need to craft the drum, except the Earth Mother's blessing. The drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink. It will not be easy to convince her to assist us in creating a weapon of war, but I will implore her to protect her children. While I'm doing that, you will need to craft the drum itself. Not too big, though. The larger the vessel, the more power it can hold, but the harder it becomes to carry.", ["objectivesText"] = "Craft 6 Drums of Primal Might . Progress: <Clearly exhausted, Atikka is trying to remain composed.>", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 167558, 167559, 167560, 167561 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.925333 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 908, ["name"] = "8.1.5 Leatherworking - Horde", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55223] = { ["id"] = 55223, ["name"] = "Instruments of Destruction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 53995, 55216, 55221, 55222, 55223 }, ["description"] = "Our work is almost finished. These drums, while powerful, are practically useless here in port. If you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Kul Tiras, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines. Look for someplace centralized in each territory to place drums. Once you return, I'll show you how to make the mallet needed to utilize the drums.", ["objectivesText"] = "Place the Drums of Primal Might throughout Zandalar and Kul Tiras.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 151162, ["x"] = 0.534667, ["y"] = 0.925333 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.534667, ["y"] = 0.925333 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 908, ["name"] = "8.1.5 Leatherworking - Horde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55224] = { ["id"] = 55224, ["name"] = "Rank 2 - Poen test", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 55224 }, ["description"] = "Gather corrupted ink sacs from the Nazothian Brain squids. The naga use them to control us, let's see if it works the other way.", ["objectivesText"] = "Collect $1oa corrupted ink sacs.", ["rewardItems"] = { 156871 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[55225] = { ["id"] = 55225, ["name"] = "Special Juices", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 55225 }, ["series"] = { 55226 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[55226] = { ["id"] = 55226, ["name"] = "Drive the Enemy", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 55226 }, ["series"] = { 55225 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[55227] = { ["id"] = 55227, ["name"] = "The Aeonian Artisan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55227, 55228, 55233, 55234, 55235 }, ["description"] = "Good day, friend! A Night Elf woman stopped by and asked who was the best leatherworker I knew who didn't mind getting their hands dirty. I gave her your name, and she asked me to ask you to find her in Boralus Harbor. She didn't say what she needed my best student for, but the way she acted makes me think that it is for something big. Head on down to the docks and look for her. She has white hair, purple tattoos, and a pet turtle named \"Gouge\". Show her what I've taught you!", ["objectivesText"] = "Meet the Night Elf Leatherworker in Boralus Harbor.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 907, ["name"] = "8.1.5 Leatherworking - Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55228] = { ["id"] = 55228, ["name"] = "The Audition", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55227, 55228, 55233, 55234, 55235 }, ["description"] = "Cassandra has spoken highly of your skills, but I need to be certain of what you can do. I mean no offense, this is as much for your benefit as it is our own, as if you are not ready the task could kill you. If you are willing, I would like provide you with a test to see how well you can work leather. Bring me three Drums of the Maelstrom that you have crafted yourself. This will prove your skill and consistency. If your work is up to par, I will inform you of my plan.", ["objectivesText"] = "Craft 3 Drums of the Maelstrom and bring them to Daniss Ghostdancer . Progress: Do you have the drums?", ["rewardGold"] = 128700, ["rewardXP"] = 710, ["rewardItems"] = { 154167 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 907, ["name"] = "8.1.5 Leatherworking - Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55229] = { ["id"] = 55229, ["name"] = "Repaying the Debt", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55229, 55230 }, ["description"] = "I was in Teldrassil when it was set alight. Through the panic and chaos, I knew I could not rest as long as those who did this were unpunished. I need you to go to Stormwind, find Telonis near the Lion's Rest, and ask for some of his personal collection. I managed to save him from the fires, so he owes me a great deal. I would go myself, but the loss of Teldrassil is still a fresh wound. I still need to give it time to heal. Find him, tell him I sent you, and that this will absolve his debt to me.", ["objectivesText"] = "Speak with Telonis in Stormwind.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 151287, ["x"] = 0.425, ["y"] = 0.605 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 929, ["name"] = "8.1.5 Leatherworking - Alliance - Classic Content", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55230] = { ["id"] = 55230, ["name"] = "Telonis' Prized Leather", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 55229, 55230 }, ["description"] = "I have a stash of extremely rare leathers, or... rather, I did. A group of thieves must have heard how valuable my collection was because they stole it! And THEN they had the audacity to leave a note offering to sell it back to me! As the \"former owner\", I'm able to \"best appreciate the value of their new acquisition.\" The note states they'll be waiting in the foothills behind the castle, to the east, until they find another buyer. However you get the skins, consider them yours.", ["objectivesText"] = "Retrieve the Rare Hides . Progress: How is he holding up?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167541, 167550 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 151287, ["x"] = 0.425, ["y"] = 0.605 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.605 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 929, ["name"] = "8.1.5 Leatherworking - Alliance - Classic Content", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55231] = { ["id"] = 55231, ["name"] = "The Other Ghostdancer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55231, 55232 }, ["description"] = "When the Legion was attacking, my partner went to Val'sharah to fight the demons. Mevris may be cold and headstrong, but he's goal oriented, and willing to sacrifice to achieve them. That's part of why I fell in love with him. If there is anyone who would know where we could get the raw materials for something of this magnitude, it would be him. Head to Val'sharah, and look for him in the Temple of Elune. Tell him of our plan, and that we need his help securing scales.", ["objectivesText"] = "Speak with Mevris Ghostdancer in Val'sharah.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 151285, ["x"] = 0.535, ["y"] = 0.544 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 641, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 930, ["name"] = "8.1.5 Leatherworking - Alliance - Legion Content", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55232] = { ["id"] = 55232, ["name"] = "Mevris' Menace", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 55231, 55232 }, ["description"] = "There is a hydra that has been something of a nuisance for us as of late. It lives out on the Gloaming Reef, almost directly due west of here. It's been attacking ships that pass by, making it difficult to get supplies to and from Bradensbrook. I sent a team to handle it, but they haven't returned. Go out there, kill it, and take its scales to Daniss. And when you see her, tell her that I said... <Mevris pauses as he thinks of his words, and the meaning they carry.> Nothing.", ["objectivesText"] = "Collect Brilliant Azure Scales . Progress: Have you met with Mevris?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 167542 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 151285, ["x"] = 0.535, ["y"] = 0.544 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.544 }, ["mapCandidates"] = { ["npc"] = { 641, 1161 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 930, ["name"] = "8.1.5 Leatherworking - Alliance - Legion Content", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55233] = { ["id"] = 55233, ["name"] = "Picking Bones", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 1161, ["storyline"] = { 55227, 55228, 55233, 55234, 55235 }, ["description"] = "When I was sailing in, I heard some of the sailors talking about the Horde presence here in Tiragarde Sound. Apparently they're scrounging around the remains of a massive creature that has washed ashore. Whatever it was, if the Horde wants it, we need to make sure they don't get it. Find the Horde, keep them from taking anything, and see if there are any bones from the creature we can use for our drums. Show them no mercy, <name>.", ["objectivesText"] = "Collect 18 Unwaning Bones . Progress: Have you dealt with our mutual problem?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167549 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 907, ["name"] = "8.1.5 Leatherworking - Alliance", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55234] = { ["id"] = 55234, ["name"] = "Make Some Noise", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55227, 55228, 55233, 55234, 55235 }, ["description"] = "We have everything we need to craft the drum, except Elune's blessing. The drum is but a vessel, like a cup. We need her to imbue the drum with power, filling the cup so that we may drink. With Tyrande donning the mantle of the Night Warrior, much of Elune's power is taxed. Asking for another favor is not insignificant, but I must try. While I'm doing that, I need you to craft the drum. Try to keep it small. The larger the vessel, the more power it can hold, but the harder it becomes to move.", ["objectivesText"] = "Craft 6 Drums of Primal Might . Progress: <Clearly exhausted, Daniss is trying to remain composed.>", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["rewardItems"] = { 167558, 167559, 167560, 167561 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 907, ["name"] = "8.1.5 Leatherworking - Alliance", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55235] = { ["id"] = 55235, ["name"] = "Instruments of Destruction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredProfessions"] = { "leatherworking" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 55227, 55228, 55233, 55234, 55235 }, ["description"] = "There is one last thing we need to do. These drums, while powerful, are practically useless here in town. If you want to get the most benefit from them, you'll need to spread them out. I'd suggest one for each territory here and in Zandalar, to help you when you are on a quest and to keep you at your strongest when you're behind enemy lines. Look for someplace centralized in each territory to place drums. Once you return, I'll show you how to make the mallet needed to utilize the drums.", ["objectivesText"] = "Place the Drums of Primal Might throughout Zandalar and Kul Tiras.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 151173, ["x"] = 0.6948, ["y"] = 0.298 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.6948, ["y"] = 0.298 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 907, ["name"] = "8.1.5 Leatherworking - Alliance", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55243] = { ["id"] = 55243, ["name"] = "A Daughter of Torcali", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55243 }, ["description"] = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors. In this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time. Best find her before she gets hurt.", ["objectivesText"] = "Find the Child of Torcali in the Savagelands and rescue her from danger.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151319, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 152258, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55244] = { ["id"] = 55244, ["name"] = "Away From the Herd", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55244 }, ["description"] = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns. Perhaps she could use a distraction.>", ["objectivesText"] = "Play with your direhorn.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 168304 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 152258, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 152258, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55245] = { ["id"] = 55245, ["name"] = "Eat Like a Direhorn", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55245 }, ["description"] = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", ["objectivesText"] = "Feed the Child of Torcali . Progress: <The Child of Torcali wiggles impatiently.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 157780, 157781, 168408 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 152258, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 152258, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55246] = { ["id"] = 55246, ["name"] = "Even Greener Pastures", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55246 }, ["description"] = "Ever since Torcali gave her boon to de little one, she has been growing like a weed. Dat makes her very hungry. She got out again to look for more things to eat. Before you ask, it is not my role to stop her from doing what she wants. Only to ensure she is safe. She is probably fine. Bring her home, and if you have trouble bringing her home, you might try a bribe.", ["objectivesText"] = "Find the Child of Torcali and lead her back to her pen.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151319, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 152258, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55247] = { ["id"] = 55247, ["name"] = "The Trust You've Earned", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["description"] = "I believe my loa will agree with me when I say that you have proven yourself worthy of this one's companionship. She is large enough now that she can bear you wherever it is that you wish to go. I had de Beastlord craft a saddle for you. Go and get it and I will help you put it on your new steed's back. Congratulations, <name>.", ["objectivesText"] = "Retrieve the Direhorn Saddle in Warbeast Kraal. Progress: < Li'zal rubs her head and groans.>", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 168325, 168408 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151319, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 154673, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 10, ["flags"] = 0 } } },
[55248] = { ["id"] = 55248, ["name"] = "Greener Pastures", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55248 }, ["description"] = "You have done an adequate job keeping de little one fed, but sometimes they just want something else. I did not see where de hatchling went, but you should start where de grass is real green. You will likely find her eating it. If you have trouble bringing her home, you might try a bribe.", ["objectivesText"] = "Find the Child of Torcali and lead her back to her pen.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151319, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55249] = { ["id"] = 55249, ["name"] = "Away From the Herd", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55249 }, ["description"] = "<The Child of Torcali stares longingly out of her pen. Her gaze seems to be following the other nearby direhorns. Perhaps she could use a distraction.>", ["objectivesText"] = "Help your direhorn cheer up.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168304 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55250] = { ["id"] = 55250, ["name"] = "A Growing Appetite", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55250 }, ["description"] = "<The Child of Torcali investigates your hands for traces of food and makes a small sound of distress.>", ["objectivesText"] = "Feed the Child of Torcali . Progress: <The Child of Torcali wiggles impatiently.>", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55251] = { ["id"] = 55251, ["name"] = "A Daughter of Torcali", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55251 }, ["description"] = "It has long been remarked upon that a direhorn is de bravest beast in de jungle. That is why they are chosen as mounts for our warriors. In this case, that bravery may not be in your favor. De little one has run off and I do not think she is hungry this time. Best find her before she gets hurt.", ["objectivesText"] = "Find the Child of Torcali in the Slough and rescue her from danger.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151319, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard" },
[55252] = { ["id"] = 55252, ["name"] = "A Loa Without a Temple", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["series"] = { 55253, 55254, 55258 }, ["description"] = "I have given some thought about your situation, <name>. It is not your fault dat de goblin deceived us. I followed along with his scheme as well. From today, you have my forgiveness. But dat cannot help de little one. I fear we may lose it, if we do not act. We must ask de wanderer's loa, de mountain dat moves, de great bulwark, de greatmother of direhorns, to save her child. Take dis offering to her shrine and ask for her boon... and her forgiveness.", ["objectivesText"] = "Deliver L'kala's offering to Torcali . Progress: <The great direhorn looks down upon you.>", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 157779, 167545 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151257, ["x"] = 0.684, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.668, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55253] = { ["id"] = 55253, ["name"] = "A Show of Faith", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["series"] = { 55252, 55254, 55258 }, ["description"] = "< Torcali 's voice enters your mind.> I have watched your efforts from afar, small thing. You have made mistakes, and one of my young has suffered for it. I do not forget, but I can forgive. <The enormous direhorn touches the offering bundle with her nose.> As my people place faith in me, I place my faith in you. Take my blessing to my child and she will wake.", ["objectivesText"] = "Deliver the Blessed Offering to your direhorn hatchling in Warbeast Kraal.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 157779, 167546 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151257, ["x"] = 0.684, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55254] = { ["id"] = 55254, ["name"] = "An Unending Sleep", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["series"] = { 55252, 55253, 55258 }, ["description"] = "<The direhorn hatchling continues to sleep soundly, despite any efforts on your part to wake it. It's probably been too long. You should speak to Beastlord L'kala .>", ["objectivesText"] = "Speak to Beastlord L'kala in Warbeast Kraal.", ["rewardGold"] = 33100, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151283, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 121706, ["x"] = 0.668, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55258] = { ["id"] = 55258, ["name"] = "Sleep, Eat, Repeat", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["series"] = { 55252, 55253, 55254 }, ["description"] = "<The Child of Torcali pushes the sack of herbs around with her snout. She then looks to you and stomps eagerly in place.>", ["objectivesText"] = "Feed the Child of Torcali . Progress: <The Child of Torcali pushes her snout into your hand in search of food.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 157779 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151286, ["x"] = 0.682, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 3, ["flags"] = 0 } } },
