[55298] = { ["id"] = 55298, ["name"] = "Fishing For Something Bigger", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55055, 55298, 55339, 56305 }, ["description"] = "There's a huge fish lurking these waters, and it's been causing lots of problems! It eats other fish, fishermen, and a lot of expensive gear. I saw it swallow a beautiful Zigby 300 Fishing Rod along with its owner just the other day! I've got a plan, but I've lost a lot of my equipment in the waters around here. Can you help fish up some of these items for me?", ["objectivesText"] = "Find the Anodized Sentry Fish , Jarmouthed Goby and the Suction Tube . Progress: Did you get me the items?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167669, 167670, 167671 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 924, ["name"] = "Mechagon Fishing", ["orderIndex"] = 0, ["flags"] = 0 } } },
