[55339] = { ["id"] = 55339, ["name"] = "Tidying Up", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55055, 55298, 55339, 56305 }, ["description"] = "Ionized Minnows are a scourge of these waters. They strip the ocean floors of any food, making it difficult for other species to survive. These fish have little to offer other than being a food source for larger fish. I want to see these larger fish, so I have a plan to clear the waters of these minnows and lure the bigger fish out from its hiding place. Let's start by using my Minnow Vac to catch Ionized Minnows for me.", ["objectivesText"] = "Catch 200 Ionized Minnows . Progress: Did you catch any fish?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 85500, 167562, 169868 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 924, ["name"] = "Mechagon Fishing", ["orderIndex"] = 1, ["flags"] = 0 } } },
