[55348] = { ["id"] = 55348, ["name"] = "Supplies from the Rustbolt Resistance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55348 }, ["description"] = "The Resistance appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", ["objectivesText"] = "Speak with Prince Erazim in Rustbolt for your reward.", ["rewardItems"] = { 170061 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 149816, ["x"] = 0.72, ["y"] = 0.3495 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.3495 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2392, ["threshold"] = 10000 } } } },
[55350] = { ["id"] = 55350, ["name"] = "Assault: Amathet Advance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 55350 }, ["description"] = "The Amathet seek to claim the Forge of Origination for their own. We must not allow it to fall into their hands again! Our men are defending the entrance, but they will be overwhelmed if the entire might of the Amathet advances upon them. Do what you can to route their forces before its too late.", ["objectivesText"] = "Drive back the Amathet Assault in Uldum . Progress: The Amathet must be stopped!", ["rewardXP"] = 10225, ["rewardItems"] = { 168043, 168257, 174961 }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Drive back the Amathet", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Speak with Captain Hadan", ["amount"] = 1, ["type"] = 0, ["objectID"] = 161031, ["orderIndex"] = 15 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[55361] = { ["id"] = 55361, ["name"] = "The Lost Shaman", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55361, 55362, 55363 }, ["description"] = "Pardon me, <class>. I am in need of your assistance. Our shaman, Farseer Ori, left the camp some days ago to investigate a nearby disturbance in the elements. He took his apprentice with him, a young initiate named Odari. Neither have returned. I am leading an expedition to find them and return them here safely. Nazjatar is full of dangers. The skills of an accomplished <class> like yourself could prove most useful. Will you help me return the lost shaman to safety?", ["objectivesText"] = "Locate Apprentice Odari at Dragon's Teeth Basin.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151626, ["x"] = 0.394, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151741, ["x"] = 0.435, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 951, ["name"] = "Allies in Dark Places", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 20, ["flags"] = 0 } } },
[55362] = { ["id"] = 55362, ["name"] = "Elemental Fury", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55361, 55362, 55363 }, ["description"] = "The naga have angered the elements and disrupted the natural order. We must restore the balance before it is too late. A Farseer maintains a deep connection with the elements. When the naga forces imprisoned my master, the natural balance was disturbed. Take the Stone of Elements and use it to pacify the enraged water elementals throughout Dragon's Teeth Basin. Ultimately, our only solution is to rescue Farseer Ori and bring him back alive, but the Tidestone could buy us precious time...", ["objectivesText"] = "Pacify 8 Tide Surgers. Progress: We must restore the balance before it is too late!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 128024, 167748 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151741, ["x"] = 0.435, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151741, ["x"] = 0.435, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 951, ["name"] = "Allies in Dark Places", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55363] = { ["id"] = 55363, ["name"] = "Rescue The Farseer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55361, 55362, 55363 }, ["description"] = "My master, Farseer Ori , has been imprisoned by the forces of Queen Azshara. Farseer Ori was captured while performing a sacred ritual to call upon the elements for guidance. I managed to escape, but the ritual has been left unfinished. If we do not rescue my master soon, the elements will grow even more restless. The elemental balance must be maintained. I fear what may become of my clan and our bond with the elements if Farseer Ori is not returned to us.", ["objectivesText"] = "Rescue Farseer Ori .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 167784 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151741, ["x"] = 0.435, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 149805, ["x"] = 0.394, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 951, ["name"] = "Allies in Dark Places", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 21, ["flags"] = 0 } } },
[55373] = { ["id"] = 55373, ["name"] = "Knock 'Em Out The Box", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "Steelarm Pillagers have been taking all our parts and selling them to Bondo's gang. Last night they stole all our Spiderspring Gears . The parts are in a bunch of crates they're guarding. We need you to get our gears back, and show those Steelarm Pillagers they should pick on someone else.", ["objectivesText"] = "Take out those Steelarm Pillagers and get 10 Spiderspring Gears back. Progress: Get our gears back.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 167745, 168827 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55374] = { ["id"] = 55374, ["name"] = "A Disturbance Beneath the Earth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 650, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["description"] = "Manifestation of dragon essence detected. Location: Highmountain. Assuming successful retrieval, calculations indicate 92.7 percent probability of empowering Heart of Azeroth. Theory: By combining dragon essence with sufficient quantities of Azerite within Heart Forge, previously undiscovered abilities may manifest within Heart. As Speaker Magni would say: \"Get to work, champion.\"", ["objectivesText"] = "Travel to Highmountain and investigate the essence. Progress: What brings you here, <name>?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 650, ["npcID"] = 151641, ["x"] = 0.495, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 650, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 13, ["flags"] = 0 } } },
