[55384] = { ["id"] = 55384, ["name"] = "Settling In", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55384, 55385, 55500 }, ["description"] = "Whatever Azshara is up to, this *ahem* great new landscape we have found ourself in is terribly inconvenient. Too many getting too close to our home. We have moved most of the refugees deeper into the cave. Could you ask Telur to move our calling conch inside? Grab some of Slen's Elixir and check in with Vim. Once it is set up, test it out! I'm off to do a progress check!", ["objectivesText"] = "Set up the calling conch and make the rounds.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149904, ["x"] = 0.496, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 944, ["name"] = "Making a Friend", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 21, ["flags"] = 0 } } },
[55385] = { ["id"] = 55385, ["name"] = "Scouting the Pens", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55384, 55385, 55500 }, ["description"] = "Some of our scouts have not returned. They have been keeping an eye on the Zanj'ir Slave Pens. The naga there take our people. They break their minds. Our scouts watch them, and when there is a window, they rescue them. Something is going on. We need to get them home!", ["objectivesText"] = "Find the scouts. If you lose Neri, return to the conch to call her. Progress: Did we find everyone?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 944, ["name"] = "Making a Friend", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 22, ["flags"] = 0 } } },
[55390] = { ["id"] = 55390, ["name"] = "In Darkness, I Dream", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 641, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["description"] = "The green dragonflight calls for aid. The Emerald Dream, which they have watched over for eons, has been invaded by terrible creatures of the Void. Merithra of the Dream is attempting to combat the threat, but she cannot do so alone. If you seek to empower the Heart of Azeroth with the strength of the green dragonflight, you must first help Merithra save it. Meet her at the Temple of Elune in Val'sharah, and assist her however you can.", ["objectivesText"] = "Meet Merithra at the Temple of Elune in Val'sharah.", ["rewardGold"] = 23400, ["ends"] = { { ["mapID"] = 641, ["npcID"] = 151682, ["x"] = 0.516, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 641, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55392] = { ["id"] = 55392, ["name"] = "Enter the Dreamway", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 7558, ["mapID"] = 641, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55390, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["description"] = "We have little time, so I will be brief. The Emerald Dream is under attack. The shadows of the Void are on the rise, and not even the Dream is beyond their reach. Many of my kin have already been slain, and still more are at risk. We must enter the Dreamway and save what remains of my dragonflight before it is too late.", ["objectivesText"] = "Speak with Merithra to enter the Emerald Dreamway.", ["rewardGold"] = 23400, ["rewardItems"] = { 169768 }, ["starts"] = { { ["mapID"] = 641, ["npcID"] = 151682, ["x"] = 0.516, ["y"] = 0.572 } }, ["coords"] = { ["mapID"] = 641, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.572 }, ["mapCandidates"] = { ["npc"] = { 641 }, ["zone"] = { 7558 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2209, ["db2PoiUiMapID"] = 1471, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55393] = { ["id"] = 55393, ["name"] = "Null the Void", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10474, ["mapID"] = 1471, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55390, 55392, 55394, 55395, 55396, 55397, 55398, 55465 }, ["description"] = "The green dragonflight cannot stop this tide of Void creatures on our own. Not with our reduced strength. Please, lend us your might and drive them from the Dreamway before they can enter the waking realm.", ["objectivesText"] = "Slay Void invaders in the Emerald Dreamway.", ["rewardGold"] = 234000, ["rewardXP"] = 11895, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10474 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2209, ["db2PoiUiMapID"] = 1471, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55394] = { ["id"] = 55394, ["name"] = "Shards of Emerald", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10474, ["mapID"] = 1471, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55390, 55392, 55393, 55395, 55396, 55397, 55398, 55465 }, ["description"] = "Kalecgos tells me that you seek the power of the dragonflights in its most essential form. There may be something here that can help you. Fragments of our latent power have coalesced here in the Dream. They are scattered about the Dreamway, where my kin have fallen. Within the Dream, you should be able to wield those fragments in their raw state.", ["objectivesText"] = "Collect Emerald Shards in the Dreamway. Progress: Have you collected the shards?", ["rewardGold"] = 234000, ["rewardItems"] = { 167802 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10474 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2209, ["db2PoiUiMapID"] = 1471, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55395] = { ["id"] = 55395, ["name"] = "Don't Close Your Eyes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10474, ["mapID"] = 1471, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55390, 55392, 55393, 55394, 55396, 55397, 55398, 55465 }, ["description"] = "The Void assaults us as we sleep! Those who it ensnares may never wake again. They can only be roused by powerful magic native to our dragonflight. The shards that have formed near our fallen kin may be exactly what is needed. If we succumb to slumber in the Void, we will be lost forever. Please, aid us!", ["objectivesText"] = "Wake Thessera , Verdisa and Karkarius from Void dreams.", ["rewardGold"] = 234000, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10474 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2209, ["db2PoiUiMapID"] = 1471, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55396] = { ["id"] = 55396, ["name"] = "The Stuff Dreams Are Made Of", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10475, ["mapID"] = 1475, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55390, 55392, 55393, 55394, 55395, 55397, 55398, 55465 }, ["description"] = "All that remains is to throw the emerald fragments you collected into the lake. I will use my power to bind them together. If this works, they will be reforged into a powerful dragonscale that you can use to empower the Heart of Azeroth. I believe that my mother would be pleased that some of our power will go toward saving the world. I hope she would be proud of us.", ["objectivesText"] = "Toss the Emerald Shards into the lake and collect the Dreamglow Dragonscale . Progress: These waters may no longer be tainted by the Void, but the green dragonflight must remain vigilant lest it ever return.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 167831, 167875, 168612 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10475 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2209, ["db2PoiUiMapID"] = 1475, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 7, ["flags"] = 0 } } },
[55397] = { ["id"] = 55397, ["name"] = "Before I Wake", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10475, ["mapID"] = 1475, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55398, 55465 }, ["description"] = "It is as I feared. We cannot fuse the shards together until the Void has been driven from this place. Quickly, strike down these aberrations. I suspect the source of the corruption will not sit idle in response.", ["objectivesText"] = "Destroy all Grips of Horror and the Void Horror . Progress: The Void is at its strongest here. I feel at fault for allowing it to spread unhindered.", ["rewardGold"] = 23400, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10475 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2209, ["db2PoiUiMapID"] = 1475, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55398] = { ["id"] = 55398, ["name"] = "The Long Awake", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10475, ["mapID"] = 1473, ["storyline"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55398, 55465 }, ["series"] = { 55390, 55392, 55393, 55394, 55395, 55396, 55397, 55465 }, ["description"] = "There is nothing more you can do for us here, champion. You have the power you sought, and the Emerald Dream is fighting back against the Void. Bring this dragonscale back to Magni and the others. I will meet you in the Chamber of Heart to help infuse it into the Heart of Azeroth. As for my flight, our long vigil must continue... or we will be lost to the Void.", ["objectivesText"] = "Return to Merithra in the Chamber of Heart with the Dreamglow Dragonscale.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10475 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 912, ["name"] = "The Stuff Dreams Are Made Of", ["orderIndex"] = 8, ["flags"] = 0 } } },
[55400] = { ["id"] = 55400, ["name"] = "Take My Hand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7503, ["mapID"] = 650, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["series"] = { 55407 }, ["description"] = "Beneath us lies the former home of the dragon Neltharion. You may know him as Deathwing. If your titan watcher friend detected an essence of dragon magic coalescing nearby, it may be an echo of the power of the dragonflights. Such power will be coveted by others as well. This force is likely originating from the most potent area within the lair--the decaying bones of my kin slain in the throes of Deathwing's fury. We must go before the essence falls into the wrong hands.", ["objectivesText"] = "Speak to Navarrogg to travel to the Dragon's Spine in Neltharion's Lair.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 650, ["npcID"] = 151641, ["x"] = 0.495, ["y"] = 0.683 } }, ["coords"] = { ["mapID"] = 650, ["source"] = "quest_giver", ["x"] = 0.495, ["y"] = 0.683 }, ["mapCandidates"] = { ["npc"] = { 650 }, ["zone"] = { 7503 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2207, ["db2PoiUiMapID"] = 1472, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 14, ["flags"] = 0 } } },
[55407] = { ["id"] = 55407, ["name"] = "Calming the Spine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10477, ["mapID"] = 1472, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["series"] = { 55400 }, ["description"] = "It is plain that the situation here is dire. The power of the black dragonflight echoes around us, and the earth is reeling in response. I have heard tales of ruptures like these on Kul Tiras and Zandalar. The elementals have been driven into a frenzy, and they bar our way from seeking the essence. If we are to preserve the tenuous balance of the elements here, the wounds must be mended, <name>.", ["objectivesText"] = "Seal the Azerite Fissures in The Dragon's Spine. Progress: Are the wounds healed, <name>?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10477 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2207, ["db2PoiUiMapID"] = 1472, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 15, ["flags"] = 0 } } },
[55425] = { ["id"] = 55425, ["name"] = "Dominating the Indomitable", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10477, ["mapID"] = 1472, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["description"] = "With the wounds healed, I can clearly sense the dragon essence. Unfortunately, it seems to emanate from the earthen giant before us. I will address the creature. Let us hope it listens to reason... but be prepared for anything. When Deathwing shattered the World Pillar in Deepholm, he earned the ire of the Stonemother and her forces. I fear this being may blame me for my father's crimes.", ["objectivesText"] = "Confront Ma'haat the Indomitable in the Dragon's Spine. Progress: The essence of my flight is powerful indeed.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 167830 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10477 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2207, ["db2PoiUiMapID"] = 1472, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 16, ["flags"] = 0 } } },
[55426] = { ["id"] = 55426, ["name"] = "What Will It Grow?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55426 }, ["description"] = "<The small seed is starting to sprout. Perhaps there's a place nearby that it could be planted.>", ["objectivesText"] = "Plant the Germinating Seed within Fertile Soil . Progress: What have you brought me?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167785, 167786, 168487 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 }, { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 167786 } },
