[55528] = { ["id"] = 55528, ["name"] = "Playtime's Over", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55528 }, ["description"] = "The troggs have been raiding our supplies since we got here, but now that we got some fire power you're going to put a stop to that! Let's teach them troggs to stay away from our stuff!", ["objectivesText"] = "Eliminate 12 Troggs. Progress: Take out some troggs.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151006, ["x"] = 0.698, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151006, ["x"] = 0.698, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[55529] = { ["id"] = 55529, ["name"] = "No Backs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55529 }, ["description"] = "<The murloc seems hungry. Next to it is a series of crude drawings which seems like a shopping list. Perhaps you can help the creature.>", ["objectivesText"] = "Bring Mrrl a Sweet Sea Vegetable , an Unidentified Mass , a Flatulent Fish , and a Slimy Naga Eyeball . Progress: Locate murloc traders and obtain the items that Mrrl requires.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 167896, 167906, 167912, 167915, 170505 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152084, ["x"] = 0.4535, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152084, ["x"] = 0.4535, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.4535, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55530] = { ["id"] = 55530, ["name"] = "A Safer Place", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55530 }, ["description"] = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Newhome.>", ["objectivesText"] = "Escort Mrrl back to Newhome.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 141605 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152084, ["x"] = 0.4535, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152084, ["x"] = 0.4535, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.4535, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55531] = { ["id"] = 55531, ["name"] = "What Will It Mine?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55531 }, ["description"] = "<Although worn from repeated use, the pickaxe still seems salvageable. Perhaps there's something nearby that can be mined?>", ["objectivesText"] = "Complete the Brinestone Cove event. Progress: What have you brought me?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 167012, 168037, 168038, 168048, 168049, 168050, 168051, 168081, 168185, 169612, 169613 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 }, { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 168081 } },
[55533] = { ["id"] = 55533, ["name"] = "MOTHER Knows Best", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["series"] = { 55851 }, ["description"] = "Now that this chamber's not fallin' tae pieces anymore, we can focus on makin' the Heart stronger! MOTHER says she's finished her fancy calculations. Have a word with her, champion. See if we can further empower the amazin' gift Azeroth gave ye.", ["objectivesText"] = "Speak to MOTHER in the Chamber of Heart. Progress: Report: Ready for dissemination. Champion's response: Critical.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 12, ["flags"] = 0 } } },
[55534] = { ["id"] = 55534, ["name"] = "Rustbolt Gramophone", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55534 }, ["description"] = "<The large gramophone that you crafted is capable of blasting music across all of Rustbolt. Now, you just need to find a good place to install it.>", ["objectivesText"] = "Install the gramophone in the Rustbolt bar, The Tipsy Tinkerer. Provided item:", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 167069, 168047, 168062, 168063 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155181, ["x"] = 0.702, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 167069 } },
[55535] = { ["id"] = 55535, ["name"] = "The Tipsy Tinkerer", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 55535 }, ["description"] = "The massive kegerator that you built should be able to house all of the Rustbolt Resistance's beverages. Find a spot to set it up in Rustbolt, and let the town know it's ready for use!", ["objectivesText"] = "Install the Rustbolt Kegerator in Rustbolt's bar, The Tipsy Tinkerer.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 168047, 168063 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 168047 } },
[55558] = { ["id"] = 55558, ["name"] = "A Bolt Hole", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "<name>, we must seek out a powerful weapon to combat the naga who guard the Tidal Conflux. I am certain such an object would be in the hands of one of Azshara's minions. Thanks to our new allies, we've tracked down the location of one of her handmaidens within the ruins of Zin-Azshari. The journey will be quite dangerous. Thankfully our allies have a location nearby that we can use as a staging ground. I've marked the location on your map, meet with me there as soon as you can.", ["objectivesText"] = "Meet with Shandris Feathermoon at Utama's Stand.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 39, ["flags"] = 0 } } },
[55560] = { ["id"] = 55560, ["name"] = "Utama's Vengeance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "We Ankoan are a small tribe. There are not that many of us remaining. This place was once overrun with makrura, before Utama. They tried to hide here, from the naga, but found the makrura. They fell, in battle, to the Kil'karrok. If you wish to show your dedication to the Ankoan, become a force of vengeance in Utama's memory. Destroy the makrura.", ["objectivesText"] = "Kill 10 Makrura. Progress: We remember Utama. And honor their memory here.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151000, ["x"] = 0.5276, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151000, ["x"] = 0.5276, ["y"] = 0.4764 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.5276, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55561] = { ["id"] = 55561, ["name"] = "What Remains of Zin-Azshari", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "Zin-Azshari, once the capital of night elf civilization, was lost during the Sundering. Queen Azshara betrayed her people and allowed N'Zoth to corrupt them, turning them into naga. It has now fallen into ruin and chaos. We must see what it has become. Meet me by the statue of Azshara.", ["objectivesText"] = "Meet Shandris at the statue of Azshara.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 40, ["flags"] = 0 } } },
[55565] = { ["id"] = 55565, ["name"] = "Shoring Up Mana Reserves", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "Holding back the tide walls is not an easy task, even using the Tidestone. The ebb and flow of the magical energies in the area are too inconsistent. We need to shore up our magical reserves, which requires mana batteries, if you will. The befouled elementals along the canal here are created with exactly the elemental cores we need. The goal is two fold. Clearing out the befouled elementals, before their corruption spreads, but also retrieving their cores, so we can keep the water at bay.", ["objectivesText"] = "Collect 10 Elemental cores . Progress: How goes your hunt?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 168241 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55569] = { ["id"] = 55569, ["name"] = "Echoes of Pain", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "These spirits... they are the Highborne. They were those Azshara held close. Azshara often played favorites, but these people... they were her favorites. I do not know why their spirits are here. We should investigate further. See if you can communicate with them and find out why their spirits cling to these ruins. How could she abandon them?", ["objectivesText"] = "Speak with the spirits who wander around the Highborne Estates.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55570] = { ["id"] = 55570, ["name"] = "Secrets in the Ruins", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "This was once a place of great power. The highborne who lived here would host lavish parties, living in splendor. Zin-Azshari was once on the shores of the Well of Eternity and drew powerful mages from all over the empire to study here. I suspect, despite the many years at the bottom of the sea, there are still treasures and powerful artifacts hidden away here. Speak with the spirits that remain and see what you can find. There must be something to help us overcome the Guardian of the Tidestone.", ["objectivesText"] = "Search for items of power. Progress: What have you discovered, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 42, ["flags"] = 0 } } },
[55571] = { ["id"] = 55571, ["name"] = "Help Them See the Truth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["series"] = { 56739 }, ["description"] = "The information you have gleaned concerns me, <name>. These spirits cling to this place because they still, even now, believe in Azshara and her reign. She sold their lives to the void and they still believe in her. I know we have concerns that outweigh this, but I cannot leave them here like this. Show them. Confront them and tell them of Azshara's betrayal.", ["objectivesText"] = "Confront the spirits about Azshara. Progress: Have the spirits been put to rest?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1499, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55573] = { ["id"] = 55573, ["name"] = "Purging the Defilers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "Azshara always did need everything to be about her. Everything had to have her name on it. Everything was for her glory. She forgot our people's connection to Elune. Or perhaps she believed it did not matter? Azshara and her minions have too long defiled this place with their heresy. Let us show them Elune's vengeance.", ["objectivesText"] = "Purge the naga from Elun'alor.", ["rewardGold"] = 303800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 43, ["flags"] = 0 } } },
[55574] = { ["id"] = 55574, ["name"] = "The Javelins of Azshara", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["series"] = { 56325, 56741 }, ["description"] = "These spirits keep speaking of the Javelins of Azshara. At first, I believed it to be referring to the handmaidens, who are currently holed up in Elun'alor. But -- now I think they are referring to the Javelins of Suramar . They were powerful weapons -- long thought lost. Azshara does like to claim things as her own. We need to defeat her handmaiden in Elun'alor regardless. Seizing the Javelins would be an amazing stroke of fortune.", ["objectivesText"] = "Kill the Handmaiden of Azshara. Progress: Killing her handmaidens will drive the naga back and out of Zin-Azshari.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 168212 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 44, ["flags"] = 0 } } },
[55575] = { ["id"] = 55575, ["name"] = "One Gnome's Trash", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55575 }, ["description"] = "The garbage in these trash heaps is full of rare metals : Dalaranium, Suramarite, even Gnomeisium! I've not seen this much easy gold to be had, since they left the vault door open in Boralus! You help me collect some of the metal, and my friend Gao will sell it on the black market. I've got a device that can tear the metal right out of the trash!", ["objectivesText"] = "Collect 100 rare metals using the rare metal collector . Progress: There's gold to be made!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 168183, 168184, 168204, 170148, 174926, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152499, ["x"] = 0.735333, ["y"] = 0.344667 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152499, ["x"] = 0.735333, ["y"] = 0.344667 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.735333, ["y"] = 0.344667 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 963, ["name"] = "Visit from Moxie", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55578] = { ["id"] = 55578, ["name"] = "Tol Dagor: Jewel of the Tides", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9327, ["mapID"] = 895, ["storyline"] = { 55578 }, ["description"] = "<As you peer at the shrine in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point. A single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing. However, there appears to be a drunk here shouting at the shrine. Perhaps he might know the whereabouts of the shrine's missing piece.>", ["objectivesText"] = "Speak with \"Slippery\" Salton and learn what you can about the missing centerpiece. Progress: <Perhaps finding the missing centerpiece will give you a clue into the shrine's operation?>", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 153716, 155648 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9327 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 889, ["name"] = "8.1.5 Jewelcrafting - Shrine of the Sea", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55579] = { ["id"] = 55579, ["name"] = "Cracking the Surface", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 942, ["storyline"] = { 55579 }, ["description"] = "<Upon your investigation you discover that the shrine has a couple locations where jewels appeared to have been located, but no longer exist. Additionally, the center jewel appears to have several cracks in it as well. Checking your notes, the earthen mentions having prospected the jewels from a nearby mountain to the northwest. Perhaps you can prospect the earth in that area to find more of those jewels.>", ["objectivesText"] = "Go to the Windshorn Hills and gather 20 Shard of Golden Beryl . Progress: <The placement of the jewels on this shrine appear to be placed in a rather intricate fashion.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 153716, 155590 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 894, ["name"] = "8.1.5 Jewelcrafting - Shrine of Storms", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55580] = { ["id"] = 55580, ["name"] = "High Prospects", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 55580 }, ["description"] = "<Inspecting the shrine, you realize that several of the gems embedded on its surface are cracked and need to be replaced. Checking your notes, you find that the earthen had extracted the gems from some earth elementals to the south. Looking at your map, you wonder if he was referring to the now ruins of a once ancient settlement that has become littered with constructs and undead. Perhaps investigating there will yield some clues as to where to find these jewels.>", ["objectivesText"] = "Investigate Gol Osigir for clues about the jewels that were used to construct the shrine. Progress: <All of the cracked jewels will definitely need to be replaced.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 153716, 155661, 155830 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 890, ["name"] = "8.1.5 Jewelcrafting - Shrine of the Eventide", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55581] = { ["id"] = 55581, ["name"] = "Sun-Speckled Dunes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 864, ["storyline"] = { 55581 }, ["description"] = "<Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some. Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area. Checking your notes, it appears that these dunes were located south of your current location.>", ["objectivesText"] = "Go to the location on your map where you believe these gems to be and recover 8 of them. Polish and shape them when you've collected enough. Progress: <These gems have a very strong structure. Time, in addition to the winds, must have also taken its toll on them.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 153716, 155664, 155665 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 864, ["questLines"] = { { ["id"] = 892, ["name"] = "8.1.5 Jewelcrafting - Shrine of the Sands", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55582] = { ["id"] = 55582, ["name"] = "Atal'Dazar: Not All That Glitters...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9028, ["mapID"] = 862, ["storyline"] = { 55582 }, ["description"] = "<As you observe the shrine, it's quite clear that the central jewel is badly broken and in need of replacement. You reference your notes on the shrine and discover that these jewels came from a \"golden sanctuary\". Given your location, that can only mean Atal'Dazar. Perhaps you could find a replacement from that ancient city.>", ["objectivesText"] = "Travel to Atal'Dazar and find a replacement for the broken jewel. Progress: <When you're done replacing the central gem, you think you might still be able to sell the old one.>", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 153716, 155666 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9028 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 893, ["name"] = "8.1.5 Jewelcrafting - Shrine of Nature", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55583] = { ["id"] = 55583, ["name"] = "Out With the Old", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 863, ["storyline"] = { 55583 }, ["description"] = "<Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites. It's clear though that time has had its way with these gems, some eroded and chipped in places. Repairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.>", ["objectivesText"] = "Cut 4 Natant Rubellites and replace the old ones with the new. Progress: <Interesting that the cut should be so similar, you wonder how the design has persisted all these years.>", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 153714, 153716, 158639, 158640, 158642, 158643, 158644, 158645, 158648, 158649, 160207 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 895, ["name"] = "8.1.5 Jewelcrafting - Shrine of the Dawning", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55585] = { ["id"] = 55585, ["name"] = "A Promising Beginning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["description"] = "<The shrine now repaired, you find yourself eager to seek out the next shrine. Perhaps Samuel has come across more locations.>", ["objectivesText"] = "Return to Samuel D. Colton III in Boralus and report on your discovery.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55586] = { ["id"] = 55586, ["name"] = "Polished Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["description"] = "<Samuel will surely want to hear about your progress on this shrine. You feel as though you should report back to him as soon as you're able.>", ["objectivesText"] = "Return to Samuel D. Colton III in Boralus and report on your discovery.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 171828 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 7, ["flags"] = 0 } } },
[55590] = { ["id"] = 55590, ["name"] = "Setting Things Right", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 49570, 49571, 49572, 49573, 49574, 49575, 49576, 49577, 49584, 55585, 55586, 55590 }, ["description"] = "<Samuel will surely be interested to hear about your investigation into this shrine. Most assuredly the part where you had to fight your way through a prison.>", ["objectivesText"] = "Return to Samuel D. Colton III in Boralus and report on your discovery.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 887, ["name"] = "8.1.5 Jewelcrafting - Alliance", ["orderIndex"] = 10, ["flags"] = 0 } } },
[55592] = { ["id"] = 55592, ["name"] = "A Promising Beginning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["description"] = "<The shrine now repaired, you find yourself eager to seek out the next shrine. Perhaps Seshuli has come across more locations.>", ["objectivesText"] = "Return to Seshuli in Dazar'alor and report on your discovery.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55593] = { ["id"] = 55593, ["name"] = "Insight into Our Enemies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. Our new allies have long been embattled with the naga. They would know best how to navigate these waters. Speak with Blademaster Okani and see if they can provide some insight into how our enemies operate.", ["objectivesText"] = "Speak to Blademaster Okani to learn more about the naga within Nazjatar .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151000, ["x"] = 0.5276, ["y"] = 0.4764 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 25, ["flags"] = 0 } } },
