[55595] = { ["id"] = 55595, ["name"] = "Deteriorating Knowledge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "My clan came to Nazjatar , eager to destroy the naga queen. We were not prepared for the darkness that she commands. Our scouts knew this land best, but their knowledge now deteriorates as their minds are controlled by Azshara's forces. Find and free our scouts, and you may still have a chance to access their knowledge.", ["objectivesText"] = "Rescue Imara, Adaru , and Umai from the clutches of mind-leeching Zoatroids.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151000, ["x"] = 0.5276, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153496, ["x"] = 0.39, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.5276, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 26, ["flags"] = 0 } } },
[55596] = { ["id"] = 55596, ["name"] = "Setting Things Right", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 49581, 49582, 49583, 49585, 49586, 49587, 49588, 49589, 49599, 55592, 55594, 55596 }, ["description"] = "< Seshuli will surely be interested to hear about your investigation into this shrine. Most assuredly the part where you had to fight your way through Atal'Dazar.>", ["objectivesText"] = "Return to Seshuli in Dazar'alor and report on your discovery.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 122695, ["x"] = 0.47, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 888, ["name"] = "8.1.5 Jewelcrafting - Horde", ["orderIndex"] = 10, ["flags"] = 0 } } },
[55597] = { ["id"] = 55597, ["name"] = "Bound by Honor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "It is true that my clan has been battling the naga for generations, but it was only in recent times that we took the fight to Nazjatar . Our leader was slain by the vile queen, and now honor binds my clan to this deep ocean. We will avenge their death or die here trying. It is our way. Your mission aligns with our duty, so we will fight the naga together. Slay their forces and bring us one step closer to honoring our promise.", ["objectivesText"] = "Kill 10 naga within Zanj'ir Wash and the Deepsea Slave Pens.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151000, ["x"] = 0.5276, ["y"] = 0.4764 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153499, ["x"] = 0.39, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.5276, ["y"] = 0.4764 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 27, ["flags"] = 0 } } },
[55598] = { ["id"] = 55598, ["name"] = "What We Know of the Naga", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "I owe you a debt. That much is clear. My mind still reels from the zoatroid's influence, but I fear the others suffer more visible wounds. Apply this salve to their wounds, and I will do my best to share what I know of the naga.", ["objectivesText"] = "Tend to the Ankoan's wounds and hear what Adaru has to say about the naga. Progress: I will tell you what I know of the naga.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 168948, 169477, 169478, 169481 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153496, ["x"] = 0.39, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153496, ["x"] = 0.39, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 28, ["flags"] = 0 } } },
[55599] = { ["id"] = 55599, ["name"] = "Scouting Undercover", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "Entering the stronghold alone would be a death wish. The Zanj'ir slaughter outsiders on sight. The only way to get in without being killed is to appear to be under the effects of a zoatroid . Even then, the mind-shackled are put to work. You must obey all commands, or they will know your mind is still your own. Once the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", ["objectivesText"] = "Scout Zanj'ir Terrace while pretending to be mind-shackled.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153496, ["x"] = 0.39, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 29, ["flags"] = 0 } } },
[55600] = { ["id"] = 55600, ["name"] = "Sating Snapdragons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. The beasts will eat anything, including your arm if you don't move it away quickly enough. Luckily for you, they've developed a taste for Chitterspine Roe .", ["objectivesText"] = "Collect Chitterspine Roe and feed it to Savage Snapdragons.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168753 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 30, ["flags"] = 0 } } },
[55601] = { ["id"] = 55601, ["name"] = "Coveted Crystals", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "Locating the weapons cache should not be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all that is needed. It all seems rather simple, does it not? But the key is in the Deepsea Crystal used to refract the light. The Bloodfin tribe covets these crystals, so you should have no trouble obtaining one.", ["objectivesText"] = "Collect a Deepsea Crystal from Hoarder Moarrgl. Progress: Have you found the crystal?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 168540 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153385, ["x"] = 0.388, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153385, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 35, ["flags"] = 0 } } },
[55602] = { ["id"] = 55602, ["name"] = "What Will It Lure?", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55602 }, ["description"] = "<Putrid and pungent, this lump of bait is the preferred food of skittering eels. Perhaps you can find infested waters nearby?>", ["objectivesText"] = "Chum the Eel Infested Waters . Progress: What have you brought me?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 168155, 168157, 168159, 168650 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 }, { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 168155 } },
