[55608] = { ["id"] = 55608, ["name"] = "Shop Project", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "As a reward for all your help here, I was planning to fix this old mechaspider mount to give to you. I could use some more of your help though to get this project started! I'll need parts off a few of the bots nearby, and maybe you could talk to Cork Stuttgard at Bondo's Yard and see if you can get a Mechanobot Ignition system.", ["objectivesText"] = "Acquire Shellsteel Plating, Multi-Leg Chaindrive , and a Mechanobot Ignition . Progress: Did you find those parts yet?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 168113, 168114, 168115, 168327, 168827 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55609] = { ["id"] = 55609, ["name"] = "Operation: Mechagon - The Mechoriginator", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10225, ["mapID"] = 1462, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "My father's madness won't be contained to this island. King Mechagon is creating a massive device capable of reversing the Curse of Flesh across the entirety of Azeroth! Any races forged by the Titans will return to their original state. For us gnomes, that means fully mechanical. For dwarves and troggs, stone. Vrykul, iron. The list goes on, but most races aren't even ON the list. Anything not forged by the titans will be completely obliterated. We must stop King Mechagon before it's too late!", ["objectivesText"] = "Enter Mechagon and defeat King Mechagon . Progress: King Mechagon 's madness threatens all of us. We must stop my father!", ["rewardGold"] = 1029600, ["rewardXP"] = 2830, ["rewardItems"] = { 169610 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 149816, ["x"] = 0.72, ["y"] = 0.3495 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 149816, ["x"] = 0.72, ["y"] = 0.3495 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.3495 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10225 } }, ["questType"] = "dungeon", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 18, ["flags"] = 0 } } },
[55618] = { ["id"] = 55618, ["name"] = "The Heart Forge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["series"] = { 57010 }, ["description"] = "Rise in Heart Forge energy levels indicates presence of black dragon essence. Recommendation: Initiate Heart Forge activation sequence.", ["objectivesText"] = "Speak with MOTHER to activate the Heart Forge . Progress: Data calculations complete. Awaiting initiation of forge activation sequence.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 168611 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 18, ["flags"] = 0 } } },
[55622] = { ["id"] = 55622, ["name"] = "Drive It Away Today", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "The mount's all polished up and looking great. We are almost done! I gave the Powercore Schematics to PASCAL-K1N6. He's ready to build us a new 500S-Cybergenic Powercore , once you get him the parts. We install that powercore and you can drive this bot away today!", ["objectivesText"] = "500S-Cybergenic Powercore obtained. Progress: Did you get the core?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166970, 167064, 168327, 168823, 168827, 169610 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 11, ["flags"] = 0 } } },
[55630] = { ["id"] = 55630, ["name"] = "Let's Get It Started", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "Those gnomes think busting up machinery is gonna stop a goblin like me from figuring out what all the tech in this place does? I ain't never seen a hunk of junk so busted up that ol' Skaggit and I can't get running smoother than the day it was made. Tell ya what. You head around with Skaggit and see what you can piece back together. Meanwhile, I'll have a chat with our gnome friend here and see what she knows about all this tech.", ["objectivesText"] = "Repair the vault's machinery. Progress: We'll have this place up and running in no time.", ["rewardGold"] = 143880, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 149809, ["x"] = 0.658, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 149809, ["x"] = 0.658, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55632] = { ["id"] = 55632, ["name"] = "You Must be This Height", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "You and the Greasemonkeys got this machine up and running even faster than I expected. The gnome we captured is keeping her mouth shut, but that shouldn't be a problem. I can take it from here. Let me know when you're ready. I'll crank up this machine to max and we'll finally see what it can do. I hope it prints gold coins...", ["objectivesText"] = "Tell Gazlowe to activate the device. Progress: That's the best use of a gnome I've ever seen!", ["rewardGold"] = 257400, ["rewardXP"] = 1770, ["rewardItems"] = { 168218 }, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 149809, ["x"] = 0.658, ["y"] = 0.662 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 152652, ["x"] = 0.658, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55633] = { ["id"] = 55633, ["name"] = "The Sunken Chest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55633 }, ["description"] = "<This waterlogged chest appears to be in salvageable condition, but it is too heavy to move due to the contents within. The lock on the device appears to be operational. Perhaps there is a key nearby...>", ["objectivesText"] = "Locate the Brass Key at the bottom of the lagoon. Progress: <The chest is locked and requires a key.>", ["rewardGold"] = 262100, ["rewardItems"] = { 168167 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55635] = { ["id"] = 55635, ["name"] = "A Voice on the Wind", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8721, ["mapID"] = 896, ["storyline"] = { 54161, 55635 }, ["description"] = "<A distant, mysterious voice fills your mind.> My enchantments are not lost... Find me... Drustvar... Fallhaven...", ["objectivesText"] = "Seek out the source of the mysterious voice in Drustvar.", ["rewardGold"] = 16980, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 896, ["npcID"] = 146053, ["x"] = 0.534, ["y"] = 0.402 } }, ["coords"] = { ["mapID"] = 896, ["source"] = "quest_giver", ["x"] = 0.534, ["y"] = 0.402 }, ["mapCandidates"] = { ["npc"] = { 896 }, ["zone"] = { 8721 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 896, ["questLines"] = { { ["id"] = 910, ["name"] = "8.1.5 Enchanting - Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55637] = { ["id"] = 55637, ["name"] = "Poor, Unfortunate Souls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55637 }, ["description"] = "Countless lives were lost in the Great Sundering when this great city was plunged into the depths of the abyss. The fortunate among us died quickly in the explosion, but some survived only to cling onto dear life as the cold, unforgiving ocean waves crashed down upon them. Those poor, unfortunate souls suffer a fate worse than death to this day. They drown endlessly, forced to relive the torture of their death. Put them to rest so that they may have peace at last.", ["objectivesText"] = "Put 8 Tortured Souls to rest. Progress: I hear them as we speak... crying out for help. Yet, I am powerless to save them...", ["rewardGold"] = 234000, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152494, ["x"] = 0.742, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152494, ["x"] = 0.742, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55638] = { ["id"] = 55638, ["name"] = "Making Kelpberry Wine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55638 }, ["description"] = "<This is an empty kelpberry juice cask. There is someone nearby that may appreciate a refill.>", ["objectivesText"] = "Deliver Kelpberry Wine to Maedin in Maedin 's Challenge. Progress: Did you bring me something?", ["rewardGold"] = 234000, ["rewardItems"] = { 168173, 168174 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150344, ["x"] = 0.582, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55640] = { ["id"] = 55640, ["name"] = "Vision of Stormwind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "weekly", "rare" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10488, ["mapID"] = 37, ["storyline"] = { 55640 }, ["description"] = "Weaken N'Zoth by delving into his mind.", ["objectivesText"] = "Complete the Vision of Stormwind.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10488 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Vision of Stormwind completed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 152112, ["orderIndex"] = 0 } }, ["db2PoiUiMapID"] = 37, ["db2QuestInfoID"] = 135, ["db2QuestInfoName"] = "Rare World Quest" },
[55645] = { ["id"] = 55645, ["name"] = "Princely Visit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "This is it! The fabled Mechagon! The greatest discovery of our age, and you're here to witness me accomplish it! < Tinkmaster Overspark puffs out his chest, brushes off his robes, and smiles confidently.> I am ready to address the Mechagon people. You may accompany me.", ["objectivesText"] = "Explore the nearby town with Tinkmaster Overspark . Progress: Mechagon is not like the legends you were told.", ["rewardGold"] = 514800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152484, ["x"] = 0.776, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152851, ["x"] = 0.712, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.776, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6060, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6060, ["name"] = "Mechagon Intro", ["orderIndex"] = 7, ["flags"] = 0 } } },
[55646] = { ["id"] = 55646, ["name"] = "The Legend of Mechagon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "Heya, $p. I was just tellin' Skaggit that I was hoping I'd run into you up here! I caught wind of an Alliance operation into some old vault that opened in Tiragarde Sound. In typical gnomish fashion, Tinkmaster Overspark is overreacting like crazy, claiming it's some lost connection to the gnome fairytale land of Mechagon . < Gazlowe scoffs.> I don't buy that for a second, but I am very interested in getting my hands on whatever tech's in that vault. You in?", ["objectivesText"] = "Meet Gazlowe at the Abandoned Junkheap in Tiragarde Sound.", ["rewardGold"] = 143880, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 152522, ["x"] = 0.53, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 152578, ["x"] = 0.656, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 895, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55647] = { ["id"] = 55647, ["name"] = "A Quick Ear Hustle", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "Bad news. We're late. The Alliance was already crawling all over the vault when we got here. Lucky for us, some big commotion inside sent some of 'em running for the hills. Most of 'em are still down in that vault, though, including that crazy braggart Tinkmaster Overspark. Let's give 'em a few more minutes to clear out, so we don't have to go in guns blazing.", ["objectivesText"] = "Wait for the Alliance to leave the vault. Progress: What'd they find down there?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 152578, ["x"] = 0.656, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 152578, ["x"] = 0.656, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55648] = { ["id"] = 55648, ["name"] = "This is Our Vault Now", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "Looks like the coast is clear with Overspark gone. Let's get inside that vault and see what's really going on here. Mechagon or not, there'd better be some quality hardware in there to make this trip worth our time.", ["objectivesText"] = "Lead Gazlowe 's crew into the vault.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 152578, ["x"] = 0.656, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 895, ["npcID"] = 149809, ["x"] = 0.658, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.656, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 895 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 895, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55649] = { ["id"] = 55649, ["name"] = "Machinations for Mechagon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8567, ["mapID"] = 895, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "So Mechagon ain't just a fairy tale? Gotta admit I'm surprised. But, if the tech on that king is any indication of what they've got out there for us to swipe, I am very, very happy to be wrong! We can't rush into this. A good crew died today. That ain't happening again on my watch. Meet me and Skaggit back in Zuldazar Harbor, and we'll build this expedition up right.", ["objectivesText"] = "Ride the Greasemonkey Skysneaker to Zuldazar Harbor.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 895, ["npcID"] = 152652, ["x"] = 0.658, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 152504, ["x"] = 0.42, ["y"] = 0.876 } }, ["coords"] = { ["mapID"] = 895, ["source"] = "quest_giver", ["x"] = 0.658, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 895, 1165 }, ["zone"] = { 8567 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 5, ["flags"] = 0 } } },
[55650] = { ["id"] = 55650, ["name"] = "Only the Best Will Do", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "You heard Gazlowe. The boss wants this expedition to go smoothly. No cutting corners, no slush. I know you've worked with Gallywix in the past. We don't run our operations like that. We expect the best from our crews, so we pay 'em what they're worth and treat 'em well. In return, we got the best goblin crews on the planet, and they ain't goin' over to any competition. Here's a list of who and what we're gonna need to pull this off. Don't worry, Gazlowe'll cover all the costs.", ["objectivesText"] = "Get everything needed to launch the expedition for Mechagon . Progress: Look, <name>, I ain't got time to hold your hand through all this. Figure it out or I'll find someone else who will.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 200551 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 152505, ["x"] = 0.422, ["y"] = 0.878 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 152505, ["x"] = 0.422, ["y"] = 0.878 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.422, ["y"] = 0.878 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 6, ["flags"] = 0 } } },
[55651] = { ["id"] = 55651, ["name"] = "To Mechagon!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "Whatever's waiting for us on the shores of Mechagon , we're going to be ready for it with this crew. I don't hold any misconceptions about how that crazy king is going to welcome us. Guns blazin', I'm sure. So we're going in quietly on this submarine. Low profile'll keep us all safe. When you're ready to go, talk to Captain Krooz.", ["objectivesText"] = "Talk with Captain Krooz to travel to Mechagon .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 246701 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 152504, ["x"] = 0.42, ["y"] = 0.876 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152783, ["x"] = 0.76, ["y"] = 0.152 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.42, ["y"] = 0.876 }, ["mapCandidates"] = { ["npc"] = { 1165, 1462 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 7, ["flags"] = 0 } } },
[55652] = { ["id"] = 55652, ["name"] = "Prospectus Bay", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55096, 55609, 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "Looks like we made it in unnoticed. Skaggit's crew can set up shop on that beach, but we gotta make sure it's safe for 'em to land first. Let's do a quick flyover to scout out how we're going to crack this place wide open. That town up on the hill looks promising...", ["objectivesText"] = "Jetpack into Prospectus Bay with Gazlowe and the crew.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152783, ["x"] = 0.76, ["y"] = 0.152 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152845, ["x"] = 0.736, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.152 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 8, ["flags"] = 0 } } },
[55657] = { ["id"] = 55657, ["name"] = "In the Shadow of Crimson Wings", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 4922, ["mapID"] = 114, ["storyline"] = { 55657, 56167 }, ["description"] = "It is unlike Alexstrasza to remain out of contact for so long, particularly when the very essences of the dragonflights' power are being made manifest. While our allies here tend to the injured, we must seek out the Life-Binder at once. When you are ready, we shall ride to the Vermillion Redoubt together.", ["objectivesText"] = "Speak with Kalecgos to fly to the Vermillion Redoubt, locate Alexstrasza and discover the source of the threat. Progress: We must rely on your aid once more, champion.", ["rewardXP"] = 10225, ["rewardItems"] = { 168280, 168613 }, ["starts"] = { { ["mapID"] = 114, ["npcID"] = 152720, ["x"] = 0.28, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 4922 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 958, ["name"] = "In the Shadow of Crimson Wings", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55658] = { ["id"] = 55658, ["name"] = "Clues Abound", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55658 }, ["description"] = "Before King Mechagon claimed this island, someone else lived here. Buried beneath this filth and garbage is the history of a forgotten people. With your help, we shall learn about these previous inhabitants. Sir Finley has marked a location where he's seen unusual artifacts. Meet him there and see if you can discover any clues.", ["objectivesText"] = "Discover a clue about the island's history. Progress: Get to it, history is waiting for you!", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 152813, 166846, 168223, 168234, 168235, 168236, 168256, 169864 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152501, ["x"] = 0.705, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 964, ["name"] = "Visit from Explorer's League", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55659] = { ["id"] = 55659, ["name"] = "Relics of the Sundering", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55659 }, ["description"] = "It's not every day that you encounter the remnants of a lost civilization beneath the ocean! I never would have imagined that I'd have the opportunity to explore the lost city of Nazjatar ... and on solid ground at that! There are many secrets here to uncover. If you come across any ancient highborne artifacts, please bring them to me. These relics could provide us with valuable clues regarding the mysteries of the Great Sundering. I feel as though we are barely scratching the surface so far...", ["objectivesText"] = "Collect 10 Highborne Relics . Progress: Whatever mysteries were hidden here beneath the ocean are now waiting to be revealed!", ["rewardGold"] = 309800, ["rewardItems"] = { 124640, 168186, 170187, 204370 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152532, ["x"] = 0.788, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152532, ["x"] = 0.788, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.788, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55661] = { ["id"] = 55661, ["name"] = "Fighting Venomous With Venom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55661 }, ["description"] = "There are many uses for the poison of the snapdragons. Immediate use would be to create antivenin for healing, or harvesting poison for attacking the naga. Let's get to the root of the issue, literally. Use some collected venom against a Terrormaw to weaken it. Kill one and bring me their fangs. I think we can come up with something handy from there.", ["objectivesText"] = "Use collected venom to weaken and kill a Snapdragon Terrormaw for their fangs. Progress: Did you get the fangs?", ["rewardGold"] = 309800, ["rewardItems"] = { 168198, 168404, 168525 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153777, ["x"] = 0.645, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153777, ["x"] = 0.645, ["y"] = 0.486 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.645, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55662] = { ["id"] = 55662, ["name"] = "Arcane Cache", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55662 }, ["description"] = "<The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind. Magical reinforcement aside, the cache still requires a key to unlock. The key is most likely being held by one of the nearby naga soldiers.>", ["objectivesText"] = "Locate the key to the Arcane Cache . Progress: <The chest is locked and requires a key.>", ["rewardGold"] = 234000, ["rewardItems"] = { 168199 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55663] = { ["id"] = 55663, ["name"] = "Broken Controller", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55663 }, ["description"] = "It is too late for me, my friends. The Controllers work us and work us and we have no rest. We have lost so many. Please, free the others! Don't let them share my fate!", ["objectivesText"] = "Free the slaves and destroy the Merciless Controller .", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152717, ["x"] = 0.58, ["y"] = 0.56 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.56 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55664] = { ["id"] = 55664, ["name"] = "A Blow to Morale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55664 }, ["description"] = "This place is the source of all of our corruption. The kelfin are taken and broken here. Hit them where it hurts. Break their power, kill every naga you see, wreak havoc! Every little crack we make, weakens their foundation.", ["objectivesText"] = "Disrupt all activities in the Shirakess Repository. Progress: Did you damage their morale?", ["rewardGold"] = 234000, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154064, ["x"] = 0.59, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154064, ["x"] = 0.59, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55665] = { ["id"] = 55665, ["name"] = "The Dark Garden", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55665 }, ["description"] = "Look, <name>, I know we have bigger battles ahead, but these gardens are horrific. Innocent creatures captured and imprisoned for the naga's amusement. They bring them out, torture them, change them, break them... you get the idea. Help me free those the naga have taken, and punish them for their hubris!", ["objectivesText"] = "Kill naga and release the poor tortured creatures held in the Imperial Garden. Progress: Were you able to wreak some havoc in there?", ["rewardGold"] = 309800, ["rewardItems"] = { 169345 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152787, ["x"] = 0.56, ["y"] = 0.185 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152787, ["x"] = 0.56, ["y"] = 0.185 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.56, ["y"] = 0.185 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
