[55751] = { ["id"] = 55751, ["name"] = "The Heart of the Water", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55751 }, ["description"] = "You see a lot up here. Even the water is a slave to the will of the naga. I believe we can help them reform away from here. Bring back what you can!", ["objectivesText"] = "Collect 15 Living Droplets from water elementals in Azsh'ari Terrace. Progress: Did you free them?", ["rewardGold"] = 309800, ["rewardItems"] = { 168809 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153685, ["x"] = 0.608, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153685, ["x"] = 0.608, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55752] = { ["id"] = 55752, ["name"] = "We Stand United", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 114, ["storyline"] = { 55752 }, ["description"] = "The work ye've done tae empower the Heart o' Azeroth cannae be understated! With this power, we might just stand a chance o' savin' the world. It's been a long fight fer certain, an' there is still more tae do. But fer now, we've got a little gift fer ye! Let me know when yer ready, champion.", ["objectivesText"] = "Speak to Magni. Progress: Ain' it incredible, champion? There's no tellin' how powerful the Heart may yet become!", ["rewardGold"] = 23400, ["rewardItems"] = { 158075, 168614, 169292, 169768 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 114, ["questLines"] = { { ["id"] = 976, ["name"] = "8.2 Heart - HoA Progression - Level III", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55753] = { ["id"] = 55753, ["name"] = "Knock His Bot Off", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "I need to rebuild the main powercore. It's a 500S Mekronic so I'll need the operational schematics to get the work done. Only person I know who has a copy of that is Bondo Bigblock. We're going to need Bondo's help to finish this. Maybe if you ask him, he'll lend us his schematics.", ["objectivesText"] = "Acquire the powercore schematics from Bondo Bigblock. Progress: Did you make a deal with Bondo?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 168305, 168827 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 10, ["flags"] = 0 } } },
[55765] = { ["id"] = 55765, ["name"] = "Bugs, Lots of 'Em!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55765 }, ["description"] = "You got a problem with mechanical bugs, so the Roughriders are here to sort this mess out! In my experience, this big of an outbreak must have some sort of queen bug behind it all. We gonna go in, kill a lot of bugs till we find the leader of 'em all. Horde or Alliance don't matter, you're with the Roughriders today. Let's kill some bugs!", ["objectivesText"] = "Exterminate 20 motospiders . Progress: Do your job!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152932, ["x"] = 0.758, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152932, ["x"] = 0.758, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.758, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 966, ["name"] = "Visit from Razak's Roughriders", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55766] = { ["id"] = 55766, ["name"] = "She Sells These Shells", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55766 }, ["description"] = "Suva is so proud of her seashells. After everything she has done for our people, helping her supplies is the least we can do! Head down the hill and pick up some of the shiniest seashells you can find! You will make her day.", ["objectivesText"] = "Collect 8 seashells. Progress: <Excited clicks and squeaks.>", ["rewardGold"] = 309800, ["rewardItems"] = { 167538 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153006, ["x"] = 0.38, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153024, ["x"] = 0.502, ["y"] = 0.64 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55767] = { ["id"] = 55767, ["name"] = "Misdirection", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55767 }, ["description"] = "We came in friendship and those pesky murlocs jumped us and stole my treasure. They threw it in one of those big clams and ran off into the village. They keep moving them around and I have no idea where it is now! Can you please help?", ["objectivesText"] = "Find Dani's Treasure . Progress: Any luck?", ["rewardGold"] = 309800, ["rewardItems"] = { 168300 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152985, ["x"] = 0.312, ["y"] = 0.32 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152985, ["x"] = 0.312, ["y"] = 0.32 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.32 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55768] = { ["id"] = 55768, ["name"] = "Emergent Sea Weeds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55768 }, ["description"] = "There is a special kind of kelp that only grows near the vents. Our healers use these to help treat our friends in Newhome. My kind don't have much of a chance down there, but you do! Gather up some of the vent kelp sprouts in the Dragon's Teeth Basin and bring them to Nevin.", ["objectivesText"] = "Gather 10 vent kelp sprouts . Progress: Were you able to find the special vent kelp?", ["rewardGold"] = 280900, ["rewardItems"] = { 168433 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153006, ["x"] = 0.38, ["y"] = 0.486 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.486 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
