[55778] = { ["id"] = 55778, ["name"] = "Visions of Danger", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55778, 55779, 55780, 55781, 55782 }, ["description"] = "<name>, Spiritwalker Ussoh has revealed a disturbing vision to me regarding Baine Bloodhoof. He has asked that you speak with him as soon as you can. Return to me after. We will have much to discuss.", ["objectivesText"] = "Speak with Spiritwalker Ussoh.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 25 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 973, ["name"] = "Stay of Execution", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55779] = { ["id"] = 55779, ["name"] = "Stay of Execution", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 1355, ["storyline"] = { 55778, 55779, 55780, 55781, 55782 }, ["description"] = "Come. It is time to save a friend.", ["objectivesText"] = "Complete the \"Stay of Execution\" Scenario.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 25 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 15 }, { ["id"] = 319, ["title"] = "Lorewalking: Thrall", ["questLineID"] = 6016, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 973, ["name"] = "Stay of Execution", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 6016, ["name"] = "Lorewalking: Thrall", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55780] = { ["id"] = 55780, ["name"] = "Old Allies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55778, 55779, 55780, 55781, 55782 }, ["description"] = "Sylvanas was my Ranger-General. I have respected her for millennia. Making this choice is something I have been wrestling with for some time. Baine's death will tear the Horde apart. The Tauren will not stand for it and if they leave, I know they will not be the last. We must save Baine. Not just for his life, but for the Horde. I can only hope once the time pressure is gone we may be able to reason with her but... I have contacted allies who will help. Meet them in the Cleft of Shadows.", ["objectivesText"] = "Meet with allies in the Cleft of Shadows.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 25 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 86, ["questLines"] = { { ["id"] = 973, ["name"] = "Stay of Execution", ["orderIndex"] = 2, ["flags"] = 0 } } },
[55781] = { ["id"] = 55781, ["name"] = "Old Allies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55778, 55779, 55780, 55781, 55782 }, ["description"] = "Sylvanas Windrunner was once my ranger-general. Now she is my warchief. Through peacetime and war, I followed her orders. Until now. Baine is a noble soul. His execution would drive a blade into the very heart of the Horde. We must save him, <name>. It is the only way to preserve who we are. What we stand for. I have reached out to allies who will help you. But in siding with them, you will put your own life in peril. If you feel as I do, then meet them in the Cleft of Shadows. Good luck.", ["objectivesText"] = "Meet with allies in the Cleft of Shadows in Orgrimmar. Progress: Once again, we face dark times, <name>.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 25 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 86, ["questLines"] = { { ["id"] = 973, ["name"] = "Stay of Execution", ["orderIndex"] = 3, ["flags"] = 0 } } },
[55782] = { ["id"] = 55782, ["name"] = "Stay of Execution", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 1355, ["storyline"] = { 55778, 55779, 55780, 55781, 55782 }, ["description"] = "Baine's time is short. We must act now.", ["objectivesText"] = "Complete the \"Stay of Execution\" Scenario.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153949, ["x"] = 0.508, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 25 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 973, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 973, ["name"] = "Stay of Execution", ["orderIndex"] = 4, ["flags"] = 0 } } },
[55783] = { ["id"] = 55783, ["name"] = "Stay of Execution", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 55783, 55784 }, ["description"] = "When I was younger, Baine Bloodhoof and I began exchanging letters. Through our unlikely friendship, I learned that there was nobility in the Horde. He proved that by defying Sylvanas when she planned to strip the free will from Derek Proudmoore. That act of nobility will cost him his life... unless we intervene. If there is to be peace in Azeroth, our hope depends upon good people doing the right thing. People like Baine. People like you. Please, go with Jaina. Save my friend and see him home.", ["objectivesText"] = "Complete the \"Stay of Execution\" Scenario.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.316667 }, ["mapCandidates"] = { ["npc"] = { 84, 1355 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 972, ["questLineOrder"] = 23 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 972, ["questLineOrder"] = 14 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 972, ["name"] = "Stay of Execution", ["orderIndex"] = 1, ["flags"] = 0 } } },
[55784] = { ["id"] = 55784, ["name"] = "Payment in Kind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55783, 55784 }, ["description"] = "<name>, King Anduin has requested our presence in Stormwind. We've sent him reports on our situation here in Nazjatar, and he understands the severity of the threat we're facing. For him to pull both of us back from the front lines, it must be a matter of grave importance. I will meet you in Stormwind Keep.", ["objectivesText"] = "Meet with Anduin Wrynn in Stormwind Keep. Progress: Thank you for coming, <name>.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 84, 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 972, ["questLineOrder"] = 23 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 972, ["questLineOrder"] = 14 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 972, ["name"] = "Stay of Execution", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55785] = { ["id"] = 55785, ["name"] = "Requisition: More Starfish", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55785 }, ["description"] = "Our forward scouts have been using starfish scales as camouflage. The trouble is that the scales deteriorate too quickly. We are going to need more scales if we want to keep tabs on naga movements. If you happen upon any Angel Scale Starfish , please deliver them to the quartermaster as soon as possible.", ["objectivesText"] = "Collect 5 Angel Scale Starfish .", ["rewardXP"] = 6815, ["rewardItems"] = { 168242 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151633, ["x"] = 0.492, ["y"] = 0.615 }, { ["mapID"] = 1355, ["npcID"] = 154436, ["x"] = 0.38, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55786] = { ["id"] = 55786, ["name"] = "Requisition: More Seaweed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55786 }, ["description"] = "We have so many wounded and we are dangerously low on seaweed bandages. If you find Sticky Seaweed , please give it to the quartermaster.", ["objectivesText"] = "Collect 5 Sticky Seaweed .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 }, { ["mapID"] = 1355, ["npcID"] = 151763, ["x"] = 0.378, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55787] = { ["id"] = 55787, ["name"] = "Requisition: More Kelp Buds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55787 }, ["description"] = "We need rations for our forces. While kelp buds do not have the same delicious taste as other options, it is nutritious and plentiful near any kelp forests. This makes it our first choice for making rations. If you happen to find any around Nazjatar , please leave your stores with the quartermaster. The ones freshly fallen from kelp are best.", ["objectivesText"] = "Collect 5 Fallen Kelp Buds .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151635, ["x"] = 0.508, ["y"] = 0.648 }, { ["mapID"] = 1355, ["npcID"] = 153591, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55789] = { ["id"] = 55789, ["name"] = "Requisition: More Carp", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55789 }, ["description"] = "Our local sea life is in danger! If you spot a fish out of water, please return it to the nearest lake, stream, or river. Conservation is everyone's responsibility!", ["objectivesText"] = "Return 5 Struggling Carps to water.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151352, ["x"] = 0.474, ["y"] = 0.62 }, { ["mapID"] = 1355, ["npcID"] = 155941, ["x"] = 0.395333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55790] = { ["id"] = 55790, ["name"] = "Requisition: More Deepcoral Buds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55790 }, ["description"] = "Many species feed on the deepcoral buds from the tall columns that grow in the east. Fathom rays feed on these buds especially. We use the buds as lures for fathom rays to use as mounts. But with our stores so low, we will not be able to provide the air support we need across Nazjatar . If you could gather more deepcoral buds and return them to the quartermaster, you will surely be rewarded.", ["objectivesText"] = "Collect 5 Deepcoral Buds .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151772, ["x"] = 0.398, ["y"] = 0.54 }, { ["mapID"] = 1355, ["npcID"] = 153772, ["x"] = 0.475, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55791] = { ["id"] = 55791, ["name"] = "Requisition: More Spiral Leaf", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55791 }, ["description"] = "We are dangerously low on our medicine stores. If you find any Spiral Leaf, please leave your stores with the quartermaster. I should warn you, Spiral Leaf is immensely poisonous. Make sure to handle it with care. Some symptoms of spiral leaf poisoning include bouts of rage, immense bursts of strength, and murderous impulses. If you are exposed, find some naga and use your murderous energy for good.", ["objectivesText"] = "Collect 5 Poisonous Spiral Leaf .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 }, { ["mapID"] = 1355, ["npcID"] = 151763, ["x"] = 0.378, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55792] = { ["id"] = 55792, ["name"] = "Requisition: More Cone Shells", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55792 }, ["description"] = "If we are going to arm ourselves against the naga, we will need far more supplies and armaments. Cone Shells make most of our armor and weapons. It's light, it's strong, and it's plentiful in this region. However, our supplies are running short and our forces need support. If you find yourself carrying Impregnable Cone Shells , please leave your stores with the quartermaster.", ["objectivesText"] = "Collect 5 Impregnable Cone Shell .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151633, ["x"] = 0.492, ["y"] = 0.615 }, { ["mapID"] = 1355, ["npcID"] = 154436, ["x"] = 0.38, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55793] = { ["id"] = 55793, ["name"] = "Requisition: More Flotsam", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55793 }, ["description"] = "I have seen piles of flotsam in the sands to the west. If you could go out and scrounge anything useful from the debris, it could prove useful. Beware, that area is a hydra breeding ground and they have been growing more aggressive since the water receded. Once you've gathered some supplies, return to the quartermaster for your reward.", ["objectivesText"] = "Collect 5 Piles of Flotsam.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 }, { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55795] = { ["id"] = 55795, ["name"] = "Mountain On the Move", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["description"] = "I have seen such fervor only once before. In times of peril, Torcali may call upon her children to defend her and those she looks after. It is likely she called your beast away. Go to her and see how you can help.", ["objectivesText"] = "Speak to Torcali .", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 168408 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 154673, ["x"] = 0.682, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151257, ["x"] = 0.684, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 11, ["flags"] = 0 } } },
[55796] = { ["id"] = 55796, ["name"] = "Heresy at the Crossroad", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["description"] = "< Torcali 's voice enters your mind.> My followers undertook a pilgrimage to a place called the Antul'Mita Plateau. It is regarded as the crossroads of Zandalar among my faithful and is the site of a Greater Wayshrine. I sense some great peril has fallen upon them. I have sent my children and my champion, Jo'nok, to their aid. Your charge is among them. Go to her and ensure that my acolytes reach the shrine safely. Let nothing stand in your way.", ["objectivesText"] = "Meet Jo'nok at the Antul'Mita Plateau in Nazmir.", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 168408 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151257, ["x"] = 0.684, ["y"] = 0.295 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151999, ["x"] = 0.682, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.684, ["y"] = 0.295 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 12, ["flags"] = 0 } } },
[55797] = { ["id"] = 55797, ["name"] = "The Direhorn Mother's Fury", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8500, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["description"] = "This one protects de faithful who still seek de shrine. You will take your companion and show them de fury of a mother direhorn. Trust in your young friend. She has always known how to fight. Open de way. Slay de heretics that defile our loa's shrine.", ["objectivesText"] = "Clear a path to the Greater Wayshrine in the Antul'Mita Plateau. Progress: A direhorn is gentle until it is provoked. Their mistake.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 168408 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151999, ["x"] = 0.682, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151999, ["x"] = 0.682, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8500 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 13, ["flags"] = 0 } } },
[55798] = { ["id"] = 55798, ["name"] = "Wander Not Alone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 55247, 55252, 55253, 55254, 55258, 55462, 55503, 55504, 55505, 55506, 55507, 55795, 55796, 55797, 55798 }, ["description"] = "She is here. I can feel her eyes upon us. My loa is generous. She will reward you for de service you have given her. Great Wanderer guide your path, <name>.", ["objectivesText"] = "Speak to Torcali .", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 168408 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 151999, ["x"] = 0.682, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 151257, ["x"] = 0.684, ["y"] = 0.295 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.682, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 863, ["questLines"] = { { ["id"] = 935, ["name"] = "How to Train Your Direhorn", ["orderIndex"] = 14, ["flags"] = 0 } } },
[55799] = { ["id"] = 55799, ["name"] = "The Tide Turns", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55469, 55482, 55485, 55486, 55488, 55489, 55490, 55799, 56356 }, ["series"] = { 55490 }, ["description"] = "The time to strike is now. We must take the Tidestone of Golganneth and the Javelin of Suramar is our best chance of piercing the barrier around it. Every minute we wait is another minute when the sea can come crashing down on us. What forces we have will be arrayed below, just outside their encampment. We will need your strength in addition to the Javelin, <name>. We do not have enough forces to take it on our own.", ["objectivesText"] = "Assault the naga camp and seize control of the Tidestone of Golganneth.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153183, ["x"] = 0.503667, ["y"] = 0.273667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 938, ["name"] = "Turning the Tide", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 46, ["flags"] = 0 } } },
[55801] = { ["id"] = 55801, ["name"] = "Requisition: We Need It All", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55801 }, ["description"] = "We are dangerously low on all of our supplies. Please, you must go out and collect as much as you can. Please return with any resources you find to the quartermaster!", ["objectivesText"] = "Collect resources from around Nazjatar .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151618, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 155940, ["x"] = 0.378, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55813] = { ["id"] = 55813, ["name"] = "Aim High", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55813 }, ["description"] = "This conspiracy of ravens is preying on citizens of Rustbolt, it's unacceptable! Prince Erazmin has asked me to reduce their numbers, but I could really use your help. Can you help me kill some of them? Use my marker gun if you need it. I'll blast the ones you mark, and help bring them down.", ["objectivesText"] = "12 Rustwing Ravens slain. Progress: Let's get to it!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 169279, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154568, ["x"] = 0.622, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154568, ["x"] = 0.622, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[55815] = { ["id"] = 55815, ["name"] = "Other Interests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55815 }, ["description"] = "Madam Goya is interested in many unusual items other than just rare metals. Keep an eye out for these particular items during your travels in Nazjatar. Deliver them to me and Madam Goya will consider you for special access.", ["objectivesText"] = "Deliver 5 Particularly Dense Rock to Steelsage Gao . Progress: Have you found these items?", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 167902, 167906, 167910, 167914, 168222, 202046 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152575, ["x"] = 0.735, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152575, ["x"] = 0.735, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[55816] = { ["id"] = 55816, ["name"] = "The Other Place", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55816 }, ["description"] = "In my travels of the many possible futures, I discovered another place much like Rustbolt, but different. In this other time and place, very little is alive, everything is machines. You must travel to this other place. You will scan the memory banks of the Clockwork Giants you find there. Then we will use that data to ensure that our Rustbolt never becomes the other place.", ["objectivesText"] = "Scan 10 Clockwork Giants. Progress: You must accomplish this task, for all of our sakes.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 104304, 153594, 166846, 166970, 166971, 168491, 168813, 169114, 169870, 170147, 186974, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153993, ["x"] = 0.702, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153993, ["x"] = 0.702, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 968, ["name"] = "Visit from Chromie", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55818] = { ["id"] = 55818, ["name"] = "Bounty: A Few Naga", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55818 }, ["description"] = "The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here. When you have completed your task, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 15 naga. Progress: I know it is dirty work, but someone must do it.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 }, { ["mapID"] = 1355, ["npcID"] = 152942, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55819] = { ["id"] = 55819, ["name"] = "Bounty: A Few Murlocs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55819 }, ["description"] = "While murlocs are often only a nuisance, certain factions are becoming more of a danger to our people. It is time we work together to preserve our safety while moving about Nazjatar . Put an end to some of the more aggressive murlocs and the quartermaster will award you.", ["objectivesText"] = "Kill 15 murlocs.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151352, ["x"] = 0.474, ["y"] = 0.62 }, { ["mapID"] = 1355, ["npcID"] = 155941, ["x"] = 0.395333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55820] = { ["id"] = 55820, ["name"] = "Bounty: A Few Hydras", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55820 }, ["description"] = "Our forces are desperately outmatched when it comes to the hydras. They are ferocious, tenacious, and deadly. We have retreated almost entirely out of the western region of Nazjatar . If we are going to hold the line against the naga, we need to make sure the western region is safe for our forces. Destroy as many hydras as you can manage, then report to the quartermaster.", ["objectivesText"] = "Kill 10 hydras.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 }, { ["mapID"] = 1355, ["npcID"] = 152942, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55821] = { ["id"] = 55821, ["name"] = "Bounty: A Few Coral Ancients", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55821 }, ["description"] = "Coral ancients are beginning to awaken from their long slumber. I warn you, these are very dangerous creatures of immense size and power. If more of them begin to awaken, our forces will be in great danger. Once you have defeated some of these ancients, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 3 Coral Ancients.", ["rewardXP"] = 6815, ["rewardItems"] = { 169377 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 }, { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55822] = { ["id"] = 55822, ["name"] = "Bounty: A Few Makrura", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55822 }, ["description"] = "The makrura have been a thorn in our side for too long. They are aggressive towards almost all species in Nazjatar and are very dangerous in groups. Less of them in our waters would certainly benefit our cause. Once you are done, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 10 makrura.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151352, ["x"] = 0.474, ["y"] = 0.62 }, { ["mapID"] = 1355, ["npcID"] = 155941, ["x"] = 0.395333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55823] = { ["id"] = 55823, ["name"] = "Bounty: A Few Crabs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55823 }, ["description"] = "The crab population is expanding too quickly within Nazjatar , endangering local plant life. Cull their numbers in our conservation effort. Report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 15 crabs.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151635, ["x"] = 0.508, ["y"] = 0.648 }, { ["mapID"] = 1355, ["npcID"] = 153591, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55824] = { ["id"] = 55824, ["name"] = "Bounty: A Few Snapdragons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55824 }, ["description"] = "Snapdragons are one of the most dangerous species on Nazjatar . The naga breed them for the viciousness and their ability as trackers. If we hope to keep our positions hidden from the naga, we must take out these groups of snapdragons immediately. After you are done, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 10 snapdragons.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151618, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 155940, ["x"] = 0.378, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55825] = { ["id"] = 55825, ["name"] = "Bounty: A Few Fathom Rays", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55825 }, ["description"] = "The fathom ray population is eating all of the coral buds to the east. If we do not cull their numbers, we may have an environmental catastrophe on our hands. Once you have finished, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 10 fathom rays .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151772, ["x"] = 0.398, ["y"] = 0.54 }, { ["mapID"] = 1355, ["npcID"] = 153772, ["x"] = 0.475, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55827] = { ["id"] = 55827, ["name"] = "Bounty: More Naga", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55827 }, ["description"] = "The naga are our true enemy. All other efforts in Nazjatar are second to disrupting the naga's operations. If you want to be an asset to our cause then destroying the enemy is a quick way to earn your way here. When you have completed your task, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 25 naga.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 }, { ["mapID"] = 1355, ["npcID"] = 152942, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55828] = { ["id"] = 55828, ["name"] = "Bounty: More Murlocs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55828 }, ["description"] = "While murlocs are often only a nuisance, certain factions are becoming more of a danger to our people. It is time we work together to preserve our safety while moving about Nazjatar . Put an end to some of the more aggressive murlocs and the quartermaster will award you.", ["objectivesText"] = "Kill 25 murlocs.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151352, ["x"] = 0.474, ["y"] = 0.62 }, { ["mapID"] = 1355, ["npcID"] = 155941, ["x"] = 0.395333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55829] = { ["id"] = 55829, ["name"] = "Bounty: More Hydras", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55829 }, ["description"] = "Our forces are desperately outmatched when it comes to the hydras. They are ferocious, tenacious, and deadly. We have retreated almost entirely out of the western region of Nazjatar . If we are going to hold the line against the naga, we need to make sure the western region is safe for our forces. Destroy as many hydras as you can manage, then report to the quartermaster.", ["objectivesText"] = "Kill 15 hydras.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 }, { ["mapID"] = 1355, ["npcID"] = 152942, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55830] = { ["id"] = 55830, ["name"] = "Bounty: More Coral Ancients", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55830 }, ["description"] = "Coral ancients are beginning to awaken from their long slumber. I warn you, these are very dangerous creatures of immense size and power. If more of them begin to awaken, our forces will be in great danger. Once you have defeated some of these ancients, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 7 coral ancients.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 }, { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55831] = { ["id"] = 55831, ["name"] = "Bounty: More Makrura", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55831 }, ["description"] = "The makrura have been a thorn in our side for too long. They are aggressive towards almost all species in Nazjatar and are very dangerous in groups. Less of them in our waters would certainly benefit our cause. Once you are done, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 15 makrura.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151352, ["x"] = 0.474, ["y"] = 0.62 }, { ["mapID"] = 1355, ["npcID"] = 155941, ["x"] = 0.395333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55832] = { ["id"] = 55832, ["name"] = "Bounty: More Crabs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55832 }, ["description"] = "The crab population is expanding too quickly within Nazjatar , endangering local plant life. Cull their numbers in our conservation effort. Report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 25 crabs.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151635, ["x"] = 0.508, ["y"] = 0.648 }, { ["mapID"] = 1355, ["npcID"] = 153591, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55833] = { ["id"] = 55833, ["name"] = "Bounty: More Snapdragons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55833 }, ["description"] = "Snapdragons are one of the most dangerous species on Nazjatar . The naga breed them for the viciousness and their ability as trackers. If we hope to keep our positions hidden from the naga, we must take out these groups of snapdragons immediately. After you are done, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 15 snapdragons.", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151618, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 155940, ["x"] = 0.378, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55834] = { ["id"] = 55834, ["name"] = "Bounty: More Fathom Rays", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55834 }, ["description"] = "The fathom ray population is eating all of the coral buds to the east. If we do not cull their numbers, we may have an environmental catastrophe on our hands. Once you have finished, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 15 fathom rays .", ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151772, ["x"] = 0.398, ["y"] = 0.54 }, { ["mapID"] = 1355, ["npcID"] = 153772, ["x"] = 0.475, ["y"] = 0.632 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.398, ["y"] = 0.54 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55836] = { ["id"] = 55836, ["name"] = "Bounty: Elite Naga Forces", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55836 }, ["description"] = "Strike at the elite naga forces within Nazjatar . Once we remove some of their leadership, our people will be able to move about more freely. Report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 5 elite naga. Progress: I know it is dirty work, but someone must do it.", ["rewardXP"] = 6815, ["rewardItems"] = { 170476 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151614, ["x"] = 0.502, ["y"] = 0.662 }, { ["mapID"] = 1355, ["npcID"] = 152942, ["x"] = 0.4, ["y"] = 0.555 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.662 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55837] = { ["id"] = 55837, ["name"] = "Bounty: Dangerous Creatures", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55837 }, ["description"] = "There are creatures in Nazjatar that are far more dangerous than their peers. I leave it to you to find them and defeat them. When you've done your part, report to the quartermaster to claim your reward.", ["objectivesText"] = "Kill 1 rare creature in Nazjatar . Progress: I know it is dirty work, but someone must do it.", ["rewardXP"] = 6815, ["rewardItems"] = { 167059 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151352, ["x"] = 0.474, ["y"] = 0.62 }, { ["mapID"] = 1355, ["npcID"] = 155941, ["x"] = 0.395333, ["y"] = 0.554667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 }, { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.474, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55845] = { ["id"] = 55845, ["name"] = "Plans of Attack", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55845 }, ["description"] = "<The attack plans are written on the parchment in fluorescent squid-ink and bound together with Azshara's seal.> Orders from our queen: Queen Azshara has commanded that all naga forces prepare for a full assault upon the Alliance invaders in our land. Details for the attack have been distributed to your various unit commanders. The Alliance shall tremble at the might of our queen!", ["objectivesText"] = "Collect 8 Assault Plans . Progress: What news do you bring from the front?", ["rewardGold"] = 234000, ["rewardXP"] = 1415, ["rewardItems"] = { 35232, 168396 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152942, ["x"] = 0.4, ["y"] = 0.555 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.555 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55851] = { ["id"] = 55851, ["name"] = "Essential Empowerment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["series"] = { 55533 }, ["description"] = "Champion, excitin' news! I know yer busy dealin' with the naga threat right now, but we need ye to come back tae the Chamber of Heart! MOTHER's finally finished her calculations and she's got an idea of what tae do next! Hurry back tae Silithus as quick as ye can. Azeroth needs ye!", ["objectivesText"] = "Meet Magni in the repaired Chamber of Heart in Silithus. Progress: There ye are! Chamber's lookin' better, eh?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 158075 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154166, ["x"] = 0.4, ["y"] = 0.552 }, { ["mapID"] = 1355, ["npcID"] = 154167, ["x"] = 0.482, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 11, ["flags"] = 0 } } },
[55860] = { ["id"] = 55860, ["name"] = "Sea Slug Liquidation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "My brief studies have shown that the refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. The sea floor is littered with creatures that produce just what we need to track down this weapons cache.", ["objectivesText"] = "Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village. Progress: Do you have the ooze?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168539 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153385, ["x"] = 0.388, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153385, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 34, ["flags"] = 0 } } },
[55861] = { ["id"] = 55861, ["name"] = "Let the Residue Lead You", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "I have fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. It should give you a clear trail to the weapons cache. Good luck, <name>.", ["objectivesText"] = "Follow the residue trail to locate the Azerite Weapons Cache .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 168541 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153385, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 36, ["flags"] = 0 } } },
[55862] = { ["id"] = 55862, ["name"] = "Insight into Our Enemies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "There's no telling what awaits us within this land. We cannot press forward without first knowing exactly what we're up against. Although our new allies have suffered greatly at the hands of the naga, their hardships will not be in vain. The kelfin should have invaluable knowledge of Azshara's forces. With their help, we might be able to learn more about how our enemies operate. Speak with Neri and see what insight she can provide.", ["objectivesText"] = "Speak to Neri to learn more about the naga within Nazjatar .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 149904, ["x"] = 0.496, ["y"] = 0.645 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 25, ["flags"] = 0 } } },
[55863] = { ["id"] = 55863, ["name"] = "Deteriorating Knowledge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "The kelfin are no strangers to Azshara's cruelty. She commands creatures of darkness that entrap my kind and warp their minds. They eat away at their memories until nothing's left but an empty husk. If you can get to them soon, perhaps they'll still be in a state worth saving.", ["objectivesText"] = "Rescue Fenn , Kono, and Esma from the clutches of mind-leeching Zoatroids.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149904, ["x"] = 0.496, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153492, ["x"] = 0.39, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 26, ["flags"] = 0 } } },
[55864] = { ["id"] = 55864, ["name"] = "The Price is Death", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "We've long believed that the ocean is big enough for all that wish to call it home. Unfortunately, the naga don't see it that way. They kill and capture our kind without remorse, and it's about time they paid the price.", ["objectivesText"] = "Kill 10 naga within Zanj'ir wash and the Deepsea Slave Pens.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 149904, ["x"] = 0.496, ["y"] = 0.645 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153495, ["x"] = 0.39, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.496, ["y"] = 0.645 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 27, ["flags"] = 0 } } },
[55865] = { ["id"] = 55865, ["name"] = "What We Know of the Naga", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "It feels good to be me again. I have you to thank for that. My head still hurts from the zoatroid's influence, but I think the others are worse off. Put some of this salve on their wounds, and I'll do my best to tell you what I know about the naga.", ["objectivesText"] = "Tend to the Kelfin's wounds and hear what Fenn has to say about the naga. Progress: You're interrupting.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["rewardItems"] = { 168948, 169477, 169478, 169481 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153492, ["x"] = 0.39, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153492, ["x"] = 0.39, ["y"] = 0.304 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 28, ["flags"] = 0 } } },
[55866] = { ["id"] = 55866, ["name"] = "Scouting Undercover", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "Entering the stronghold alone would be a death wish. The Zanj'ir slaughter outsiders on sight. The only way to get in without being killed is to appear to be under the effects of a zoatroid . Even then, the mind-shackled are put to work. You must obey all commands, or they will know your mind is still your own. Once the Zanj'ir believe you are mind-shackled, it should be easier to navigate their domain and uncover their secret.", ["objectivesText"] = "Scout Zanj'ir Terrace while pretending to be mind-shackled.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153492, ["x"] = 0.39, ["y"] = 0.304 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.304 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 29, ["flags"] = 0 } } },
[55867] = { ["id"] = 55867, ["name"] = "Coveted Crystals", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "Locating the weapons cache shouldn't be a problem once we have the proper tools. A little light and a lot of bioluminescent fluid is all we need! It all seems rather simple, doesn't it? But the key is in the Deepsea Crystal used to refract the light. I am told that the Bloodfin tribe covets these crystals, so it shouldn't be too much trouble to get your hands on one.", ["objectivesText"] = "Collect a Deepsea Crystal from Hoarder Moarrgl. Progress: Have you found the crystal?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 168540 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153422, ["x"] = 0.388, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153422, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 35, ["flags"] = 0 } } },
[55868] = { ["id"] = 55868, ["name"] = "Let the Residue Lead You", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "I've fashioned a device that will emit bioluminescent light when toggled on, allowing you to see any Azerite residue that lingers. It should give you a clear trail to the weapons cache. Good luck, <name>.", ["objectivesText"] = "Follow the residue trail to locate the Azerite Weapons Cache .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 168541 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153422, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 36, ["flags"] = 0 } } },
[55869] = { ["id"] = 55869, ["name"] = "Clearing Out the Cache", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["series"] = { 56236 }, ["description"] = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", ["objectivesText"] = "Deal with Priscilla Ashvane and her minions.", ["rewardGold"] = 929400, ["rewardXP"] = 10225, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 37, ["flags"] = 0 } } },
[55870] = { ["id"] = 55870, ["name"] = "Sea Slug Liquidation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "The Azerite refinement process creates a byproduct that is invisible to the naked eye, but is easily seen with refracted bioluminescent light. The sea floor is littered with creatures that produce just what we need to track down this weapons cache.", ["objectivesText"] = "Collect 8 Bioluminescent Ooze from Luminescent Sea Slugs within Bloodfin Village. Progress: Do you have the ooze?", ["rewardGold"] = 295000, ["rewardXP"] = 6815, ["rewardItems"] = { 168539 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153422, ["x"] = 0.388, ["y"] = 0.305 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153422, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 34, ["flags"] = 0 } } },
[55871] = { ["id"] = 55871, ["name"] = "Gather Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55871 }, ["description"] = "Outside is dangerous. It is safe in the Kelfin Pocket. We find the lost crabs, and slugs, and other friends. Here they get a new name and a new home. Find friends like these, and bring them home.", ["objectivesText"] = "Collect Sandclaw Crabs and Muck Creepers for Narm . Progress: Did you bring us friends?", ["rewardGold"] = 309800, ["rewardItems"] = { 168406, 168407 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151311, ["x"] = 0.265, ["y"] = 0.422 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151311, ["x"] = 0.265, ["y"] = 0.422 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.265, ["y"] = 0.422 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55872] = { ["id"] = 55872, ["name"] = "Where They Hide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55872 }, ["description"] = "Those sneaky snakes have started to send assassins. They hide nearby and kill those they cannot take away to the slave pens. Even the sponges want to be rid of them! The spores will reveal the naga treachery... and then you can go ahead and kill them. We must keep our people safe!", ["objectivesText"] = "Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins . Progress: Did you find them all?", ["rewardGold"] = 309800, ["rewardItems"] = { 168432 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153364, ["x"] = 0.456, ["y"] = 0.585 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153364, ["x"] = 0.456, ["y"] = 0.585 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.585 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55873] = { ["id"] = 55873, ["name"] = "Kill the Kritch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55873 }, ["description"] = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. < Rlgmrr jumps around anxiously and points toward the cave.> Grrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr. <He makes a scary face and pinching motions with his hands.> Mrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", ["objectivesText"] = "Kill the Kritch . Progress: Mrgglrmr grm?", ["rewardGold"] = 292100, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153537, ["x"] = 0.45, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153537, ["x"] = 0.45, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55874] = { ["id"] = 55874, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55874 }, ["description"] = "We're getting a geyser hit any minute now. The effects of the Tidestone are far-reaching. We have to do what we can to prevent any further destruction. Use this sealant to stall off the next round of eruptions!", ["objectivesText"] = "Seal all of the unstable geysers. Progress: Did you take care of all of them?", ["rewardGold"] = 208560, ["rewardItems"] = { 168482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153524, ["x"] = 0.605, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153524, ["x"] = 0.605, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55875] = { ["id"] = 55875, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55875 }, ["description"] = "Just keep watching this spot... any second now... Once those geysers start firing, get in there and seal them up. The more they shake, the more everything breaks apart! We have to keep these things under control.", ["objectivesText"] = "Seal all of the unstable geysers. Progress: Is it all sealed up?", ["rewardGold"] = 234000, ["rewardItems"] = { 168482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153834, ["x"] = 0.335, ["y"] = 0.48 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153834, ["x"] = 0.335, ["y"] = 0.48 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.48 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55876] = { ["id"] = 55876, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55876 }, ["description"] = "Earthquakes! Snakes! Water coming from every direction. What is going on around here? Neri said to plug some holes in the defenses - didn't think she'd mean it literally. Take some of this goo, next eruption, stick it in the hole.", ["objectivesText"] = "Seal all of the unstable geysers. Progress: Goop them all up?", ["rewardGold"] = 58650, ["rewardItems"] = { 168482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153833, ["x"] = 0.484, ["y"] = 0.738 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153833, ["x"] = 0.484, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55877] = { ["id"] = 55877, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55877 }, ["description"] = "We have been keeping an eye out for these unstable geysers. Since the water went away, the ocean has been trying to find a way back in. If we let it burst up just anywhere, we could all be doomed! Help me plug these up! Be careful, though, I found out the hard way they have a bit of a kick.", ["objectivesText"] = "Seal all of the unstable geysers. Progress: Did you prevent the disaster?", ["rewardGold"] = 309800, ["rewardItems"] = { 168482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153522, ["x"] = 0.48, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153522, ["x"] = 0.48, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55878] = { ["id"] = 55878, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55878 }, ["description"] = "Have you heard about the geysers? All over the newly exposed areas, water trying to fill where it was pulled away. The ocean, she is angry. I don't think she likes Azshara either. We will keep filling this in until we can find a permanent fix.", ["objectivesText"] = "Seal all of the unstable geysers. Progress: Get them stopped up for now?", ["rewardGold"] = 221280, ["rewardItems"] = { 168482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153819, ["x"] = 0.714, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153819, ["x"] = 0.714, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55880] = { ["id"] = 55880, ["name"] = "Redistribution of Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55880 }, ["description"] = "Welcome back, dear test subject. Today's experiment is... <Pristy flips through some papers and smiles.> ...My pet project, the NRG-100 ! I am quite pleased with the potential improvements I've made to efficiency, potency, and destructivity. And the only thing I had to sacrifice was stability! When you're ready to proceed, strap on the NRG-100 .", ["objectivesText"] = "Use the NRG-100 to charge 6 energy cells . Progress: Let's experiment!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166970, 168122 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
