[55885] = { ["id"] = 55885, ["name"] = "Rico's Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55885 }, ["description"] = "Some of our Roughriders are missing, I tried to find them, but got pinned down here by the bugs! I could really use your help, <name>. See if you can save my missing troopers.", ["objectivesText"] = "Rescue Trooper Levy , Katrin, and Bybee.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153324, ["x"] = 0.828, ["y"] = 0.234 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152932, ["x"] = 0.758, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.828, ["y"] = 0.234 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
