[55905] = { ["id"] = 55905, ["name"] = "Abduction Reduction", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55905 }, ["description"] = "We got actual ABDUCTIONS happenin' here, <name>! Honest to gold, flying robots are swoopin' into town and snatchin' up people like it's closin' time at Gallywix's buffet! Lucky for the Rustbolt Resistance, Gazlowe called in me and my explosives to save the day. You wanna pitch in? Take one of my rocket launchers and blast those containment crates outta the sky. Whatever they've got trapped inside will come tumblin' down real fast, so you gotta run underneath and catch 'em.", ["objectivesText"] = "Free 6 captured Mechagnomes and catch them before they hit the ground.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 168052, 168430, 169868, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153373, ["x"] = 0.71, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153373, ["x"] = 0.71, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 969, ["name"] = "Visit from Penny Clobberbottom", ["orderIndex"] = 0, ["flags"] = 0 } } },
[55937] = { ["id"] = 55937, ["name"] = "Clearing Out the Cache", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "<While inspecting the crate, a commotion can be heard within the cavern. A familiar voice, shouting orders.>", ["objectivesText"] = "Deal with Priscilla Ashvane and her minions.", ["rewardGold"] = 929400, ["rewardXP"] = 10225, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 37, ["flags"] = 0 } } },
[55967] = { ["id"] = 55967, ["name"] = "Sating Snapdragons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "It's time for the snapdragons to feed, but it's a job best left to someone a little more expendable. The beasts will eat anything, including your arm if you don't move it away quickly enough. Luckily for you, they've developed a taste for Chitterspine Roe .", ["objectivesText"] = "Collect Chitterspine Roe and feed it to Savage Snapdragons.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168753 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 30, ["flags"] = 0 } } },
