[55976] = { ["id"] = 55976, ["name"] = "Supplies From the Waveblade Ankoan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55976 }, ["description"] = "The Waveblade Ankoan appreciate all the aid you've provided. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", ["objectivesText"] = "Speak with Speaker Utia in Mezzamere for your reward.", ["rewardItems"] = { 169939 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154140, ["x"] = 0.38, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2401, ["threshold"] = 10000 } } } },
[55979] = { ["id"] = 55979, ["name"] = "Iteration is Key", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredProfessions"] = { "engineering" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55979 }, ["description"] = "You've been holding out on me! Here I was, thinking that we're friends now and yet you neglected to tell me about your magnificient wrench! <Christy inspects it closely.> Well, not too magnificient... I recognize the Ub3r-Spanner from its blueprints, but whoever built this lacks a certain level of craftsmanship. I will upgrade it for you. Bring me the Overcharged Mecha-core from a mechanocrawler. No excuses. I will fix your mistakes.", ["objectivesText"] = "Collect an Overcharged Mecha-core from the Overcharged Mechanocrawler. Progress: Imagine crafting an Ub3r-Spanner without an overcharged mecha-core ... Ha!", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 164740, 168532, 168533, 168534, 168535 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152747, ["x"] = 0.698, ["y"] = 0.325 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152747, ["x"] = 0.698, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard" },
[55980] = { ["id"] = 55980, ["name"] = "Turn the Scale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55980 }, ["description"] = "I have been trying to gather some of the scales from the young hydra nearby. Their flexibility and strength makes them incredibly versatile. With all the cranky old hydra tromping around, I don't stand much of a chance. Can you gather some up for me?", ["objectivesText"] = "Collect 20 Hydra Scales from nearby hydra. Progress: Do you have enough?", ["rewardGold"] = 234000, ["rewardItems"] = { 168519 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153543, ["x"] = 0.345, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153543, ["x"] = 0.345, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.345, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55983] = { ["id"] = 55983, ["name"] = "A Safer Place", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55983 }, ["description"] = "<The murloc seems to be in rough shape. Perhaps it would be safer with your allies in Mezzamere.>", ["objectivesText"] = "Escort Mrrl back to Mezzamere.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 152084, ["x"] = 0.4535, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 152084, ["x"] = 0.4535, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.4535, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[55984] = { ["id"] = 55984, ["name"] = "A Good Offense", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55984 }, ["description"] = "Korl was told to watch the naga, so watching the naga I am. They're bad, friend, you know... just... terrible, horrible, bad monsters. I don't think I can just watch any more. They say the best defense is.. something... Help me teach them being being bad gets you smashed!", ["objectivesText"] = "Kill 50 naga. Progress: Did you have fun?", ["rewardGold"] = 262100, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153623, ["x"] = 0.362, ["y"] = 0.302 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153623, ["x"] = 0.362, ["y"] = 0.302 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.302 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55985] = { ["id"] = 55985, ["name"] = "Extra Shiny", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55985 }, ["description"] = "In the pools below are some small, lovely pearls. They were tossed in during some Azsh'ari ritual. Do they mean something? I have no idea. But I would like to have some of them. Be a lovely heavyfoot and go grab some for me, please!", ["objectivesText"] = "Collect 10 Imbued Pearls . Progress: Did you find all of the pearls?", ["rewardGold"] = 309800, ["rewardItems"] = { 168577 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153685, ["x"] = 0.608, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153685, ["x"] = 0.608, ["y"] = 0.31 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55986] = { ["id"] = 55986, ["name"] = "Break a Few Eggs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55986 }, ["description"] = "This chamber is lovely and terrifying. What is born here will ruin the lives of so many. We cannot hurt the pods, but we can destroy the eggs of the serpents that guard them. Take out the eggs, every little bit helps. Poor eggs...", ["objectivesText"] = "Destroy 10 Deepcoil Eggs . Progress: Did you destroy the eggs?", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153684, ["x"] = 0.708, ["y"] = 0.232 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153684, ["x"] = 0.708, ["y"] = 0.232 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.232 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55993] = { ["id"] = 55993, ["name"] = "A Little Edge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55993 }, ["description"] = "In the darkest cavern. Below the naga city. You will find them. Creepy little crabs with sharp and pointy spines. I think we can find a way to use them. Projectiles didn't work so well in water, but now... Harvest some for us! Be careful, some of them are much sneakier than they have any right to be.", ["objectivesText"] = "Collect 12 Chitterspine Spines . Progress: Did you gather the spines?", ["rewardGold"] = 309800, ["rewardItems"] = { 168605 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153743, ["x"] = 0.261333, ["y"] = 0.421333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153743, ["x"] = 0.261333, ["y"] = 0.421333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.261333, ["y"] = 0.421333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[55994] = { ["id"] = 55994, ["name"] = "Do Not Drink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55994 }, ["description"] = "These troggs watch everything we do. They see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines! We need that oil back, before they drink it all!", ["objectivesText"] = "Recover 12 containers of Stolen Oil . Progress: Get that oil back quick!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 4536, 64588, 64598, 64607, 64616, 64622, 64639, 157012, 166846, 166970, 166971, 168608, 181802, 183744, 184843, 211279, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153750, ["x"] = 0.59, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153750, ["x"] = 0.59, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[55995] = { ["id"] = 55995, ["name"] = "We Can Fix It", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 1462, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55609, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 56131 }, ["description"] = "<This drill rig looks capable of breaking through the nearby debris, but is clearly broken. If you can collect the parts required, Prince Erazmin should be able to show you how to repair it.>", ["objectivesText"] = "Collect 40 Spare Parts and 1 Energy Cell from enemies in Junkwatt Depot. Progress: Us mechagnomes are always building something. Mechagon is littered with broken or half-completed construction projects.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 170500 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 }, { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6062, ["questLineOrder"] = 1 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 940, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 941, ["name"] = "Expedition to Mechagon", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 6062, ["name"] = "Mechagon Intro - On Island", ["orderIndex"] = 6, ["flags"] = 0 } } },
[56000] = { ["id"] = 56000, ["name"] = "We've Got Crabs!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56000 }, ["description"] = "<name>, you're just in time. Everything's ready for the crab hunt! Okay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting? I'm going to level with you, <name>. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people. If that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population! How many innocent grub worms need to die before we do something, <name>?", ["objectivesText"] = "Collect 12 Crackleclaw Crabs . Progress: How many innocent grub worms need to die before we do something, <name>?", ["rewardGold"] = 309800, ["rewardItems"] = { 168628 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56001] = { ["id"] = 56001, ["name"] = "Drunk Angry Murlocs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56001 }, ["description"] = "Those no-good Bloodfins ran off with all of the beer! I've been experimenting with brews that only use ingredients native to Nazjatar , but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck. My supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back. Please recover the stolen lager from Bloodfin Village before it's too late!", ["objectivesText"] = "Collect 12 Ocean \"Infused\" Lagers . Progress: Those no-good Bloodfins ran off with all of the beer!", ["rewardGold"] = 234000, ["rewardItems"] = { 168629, 169280, 170075 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
