[56030] = { ["id"] = 56030, ["name"] = "The Warchief's Order", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 56030, 56044 }, ["series"] = { 56044 }, ["description"] = "Champion, the Dark Lady summons you. The time has come to set her plan into motion. Our warships are ready to embark. The key to victory over the Alliance is within our grasp. Meet me in Zuldazar, aboard the Banshee's Wail. What we do next... we do for the Horde.", ["objectivesText"] = "Meet with Nathanos Blightcaller on The Banshee's Wail.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 11, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 2, ["flags"] = 0 } } },
[56031] = { ["id"] = 56031, ["name"] = "The Wolf's Offensive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56031, 56043 }, ["series"] = { 56043 }, ["description"] = "Champion, Spymaster Shaw reports that the remains of the Horde fleet is preparing to depart. They will be easy pickings for our superior forces. Let us seize this opportunity to eliminate their threat once and for all! Preparations are underway to set sail. Come to Boralus Harbor and meet with me upon the Wind's Redemption with all haste!", ["objectivesText"] = "Meet with Genn Greymane on the Wind's Redemption.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 18230, 113364 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 153932, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 153932, ["x"] = 0.705, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 12, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56035] = { ["id"] = 56035, ["name"] = "Most Delicious Clams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56035 }, ["description"] = "This pool is filled with creepy fish. It is also the home of some of the most delicious clams you will ever eat. Fresh water somehow mixes into the ocean water in this one part of Nazjatar , and that gives the meat a totally new flavor. Every now and then, we come down here and collect them for our friends in Newhome. We could sure use some help with all these extra mouths to feed!", ["objectivesText"] = "Collect 10 Neptulian Clams . Progress: Did you find enough?", ["rewardGold"] = 309800, ["rewardItems"] = { 168658, 168672 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153900, ["x"] = 0.486, ["y"] = 0.2305 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153900, ["x"] = 0.486, ["y"] = 0.2305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.486, ["y"] = 0.2305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56036] = { ["id"] = 56036, ["name"] = "A Steamy Situation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56036 }, ["objectivesText"] = "Steam Fissures plugged", ["rewardItems"] = { 168666 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Steam Fissures plugged", ["amount"] = 8, ["type"] = 0, ["objectID"] = 153916, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[56037] = { ["id"] = 56037, ["name"] = "Stealing the Naga's Secrets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite . Weapons of this power should never be in the hands of the naga.>", ["objectivesText"] = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace! Progress: I recognize the craftsmanship. This is Priscilla Ashvane's work. She must have taught the naga how to forge Azerite weaponry, but why?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168515 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153384, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 33, ["flags"] = 0 } } },
[56038] = { ["id"] = 56038, ["name"] = "Working with Purpose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. Before you came along, it was my job to crawl around the cavern, cracking open clams. So you see, you have some purpose, other than being a mindless sack of flesh.", ["objectivesText"] = "Collect 6 Iridescent Pearls from Chittershell Clams. Progress: Do you have them all?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 168810 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 31, ["flags"] = 0 } } },
[56039] = { ["id"] = 56039, ["name"] = "We Can't Have Dull Weapons", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "For a squid head, you sure are making my life easier. I guess you get to live long enough to complete another task. Our new weapons are forged from some foreign material that I don't quite trust. You won't catch me sharpening any blades, but the work still needs to get done. Get to it!", ["objectivesText"] = "Find the special weaponry within Zanj'ir Terrace.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 32, ["flags"] = 0 } } },
[56043] = { ["id"] = 56043, ["name"] = "Send the Fleet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56031, 56043 }, ["series"] = { 56031 }, ["description"] = "This war has cost us dearly, but victory will soon be in our grasp. What remains of the Horde fleet has departed Zuldazar and our spies say that the Banshee Queen's hand sails at their helm. This is our chance, <name>! With one strike we can eliminate what remains of their fleet and rid Azeroth of Blightcaller's filth once and for all! The fleet is preparing to depart, report to the Harbormaster when you are ready to set sail.", ["objectivesText"] = "Speak to Harbormaster Cyrus Crestfall to set sail.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 153932, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150087, ["x"] = 0.4696, ["y"] = 0.8276 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1161, 1355 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56044] = { ["id"] = 56044, ["name"] = "Send the Fleet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 56030, 56044 }, ["series"] = { 56030 }, ["description"] = "The Warchief has entrusted me with a mission of the highest priority, <name>. The mission will succeed, of this there is no question, but to ensure that any obstacles I encounter are dealt with swiftly I once again have need of your particular skills. The Zandalari have offered us use of their ships for this endeavor. Clear out whatever affairs you have remaining and report to Captain Rez'okun when you are ready to set sail.", ["objectivesText"] = "Speak to Captain Rez'okun to set sail.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150187, ["x"] = 0.368, ["y"] = 0.935 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862, 1355 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 939, ["name"] = "The Depths of Nazjatar", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56045] = { ["id"] = 56045, ["name"] = "Stealing the Naga's Secrets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "<Upon closer inspection, it becomes clear that the blades have been forged from Azerite . Weapons of this power should never be in the hands of the naga.>", ["objectivesText"] = "Steal the Azerite weaponry and fight your way out of Zanj'ir Terrace! Progress: I recognize the craftsmanship. This is Priscilla Ashvane's work. She must have taught the naga how to forge Azerite weaponry, but why?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168516 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153421, ["x"] = 0.388, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.388, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 33, ["flags"] = 0 } } },
[56046] = { ["id"] = 56046, ["name"] = "Working with Purpose", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["description"] = "It seems the Shirakess are never satisfied with the number of pearls we source for them. They're always demanding more. Before you came along, it was my job to crawl around the cavern, cracking open clams. So you see, you have some purpose, other than being a mindless sack of flesh.", ["objectivesText"] = "Collect 6 Iridescent Pearls from Chittershell Clams. Progress: Do you have them all?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 168810 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153936, ["x"] = 0.37, ["y"] = 0.27 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 31, ["flags"] = 0 } } },
