[56063] = { ["id"] = 56063, ["name"] = "Dark Tides", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55481, 56063, 56429 }, ["description"] = "A Tidemistress leads the naga in this area. She is performing some damnable ritual outside, demanding sacrifices of our soldiers. Stop her before more of our own meet a cruel fate.", ["objectivesText"] = "Slay Tidemistress Ethendriss .", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 64594, 64604, 64613, 64620, 64625, 64629, 64632, 64634, 157013, 163866, 163867, 163868, 163869, 163871, 163872, 163874, 163876, 163878, 163880, 163881, 163882, 163885, 163886, 163887, 163890, 163892, 163894, 163895, 166336, 170274, 170275 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150196, ["x"] = 0.396667, ["y"] = 0.775333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.396667, ["y"] = 0.775333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 886, ["questLineOrder"] = 23 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 886, ["name"] = "Azshara's Trap", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 6, ["flags"] = 0 } } },
[56064] = { ["id"] = 56064, ["name"] = "Assault: The Black Empire", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56064 }, ["description"] = "I cannot believe my eyes. The Black Empire is materializing right here in the Vale! We must spring to action!", ["objectivesText"] = "Drive back the N'Zoth Assault in the Vale of Eternal Blossoms .", ["rewardXP"] = 10225, ["rewardItems"] = { 173372 }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cleanse N'Zoth's corruption", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 }, { ["text"] = "Large Treasure", ["amount"] = 10, ["type"] = 0, ["objectID"] = 156551, ["orderIndex"] = 12 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
