[56075] = { ["id"] = 56075, ["name"] = "Stolen Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56075 }, ["description"] = "From the void these naga pull their strength. Each scroll they record, shared knowledge -- that knowledge is power. It stands to reason, if we take away their knowledge, we steal their power. My logic may be flawed, but let's do it anyway!", ["objectivesText"] = "Collect 8 Scrolls of Shirakess . Progress: Did you get all of the scrolls?", ["rewardGold"] = 309800, ["rewardItems"] = { 142054, 168841 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154064, ["x"] = 0.59, ["y"] = 0.19 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154064, ["x"] = 0.59, ["y"] = 0.19 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.19 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56082] = { ["id"] = 56082, ["name"] = "Bot Rampage", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56082 }, ["description"] = "Those bots have been attacking us from the moment we landed. We've got to hold this beach! My expedition guards could use your help, <name>. Lend a hand, destroy bots on the beach and in the nearby woodlands.", ["objectivesText"] = "15 attacking bots slain. Progress: The expedition guards could use your help!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154101, ["x"] = 0.778, ["y"] = 0.396 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154101, ["x"] = 0.778, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.778, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56083] = { ["id"] = 56083, ["name"] = "Unsafe Work Conditions", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56083 }, ["description"] = "Those rampaging bots ain't lettin' up! We're payin' good money for the best and brightest goblins on the planet, and I ain't gonna let some malfunctionin' machinery take 'em outta the shift schedule. This is textbook unsafe working conditions, and the Greasemonkey Union reps are givin' me an earful for it. Protect the workers!", ["objectivesText"] = "15 attacking bots slain. Progress: The greasemonkeys could use your help!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150563, ["x"] = 0.738, ["y"] = 0.258 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150563, ["x"] = 0.738, ["y"] = 0.258 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.738, ["y"] = 0.258 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
