[56091] = { ["id"] = 56091, ["name"] = "Usurper's Scent Gland", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 56091 }, ["description"] = "When a new queen is born and old enough to start proliferating her own hive, she will leave the nest. Her scent will attract some of the hive to fly with her to their new home. This one likely never got the chance to do so, thanks to you. The Hivemother will be interested in this item.", ["objectivesText"] = "Take the Usurper's Scent Gland to the Honeyback Hivemother for a reward. Provided item:", ["rewardItems"] = { 169658, 172142 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 153365, ["x"] = 0.626667, ["y"] = 0.263333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.263333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 169658 } },
