[56095] = { ["id"] = 56095, ["name"] = "Legacy of Nar'anan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56095 }, ["series"] = { 56118, 56143 }, ["description"] = "Hey there, <race>. Mind helping me out? You see, I found these pylons here and it seems they contain memories from a notable Highborne who lived here long ago. I can't get any closer to the rest of em' because of the snapdragons. Especially the terrormaws... Can you go and activate the pylons for me? We Tortollans love old things, and this is a potential goldmine! Oh, and be sure to write down what you see!", ["objectivesText"] = "Activate the Memory Pylons in Nar'anan and witness what happened.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
