[56141] = { ["id"] = 56141, ["name"] = "Security First", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56141 }, ["description"] = "Many dangerous creatures and allies of my father still seek to destroy us. Help secure this island, seek out and and eliminate five of our most powerful enemies.", ["objectivesText"] = "Defeat Rare enemies on the island of Mechagon .", ["rewardXP"] = 1415, ["rewardItems"] = { 168832 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10290 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Rare Enemies slain in Mechagon", ["amount"] = 3, ["type"] = 0, ["objectID"] = 154198, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[56142] = { ["id"] = 56142, ["name"] = "Adapt, Improve, Overcome!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56142 }, ["description"] = "Izira Gearsworn is still alive, she is Rustbolt's strongest fighter, but her legs are broken. If we're going to survive I need parts to repair and upgrade her. There are machines all over with parts we can salvage. With some perseverance we should be able to fix Izira's legs. Help me obtain the following parts.", ["objectivesText"] = "20 Pristine Hound Bolts , 4 Steel Tibia XS, and 2 Machined Heel Nut. Progress: We need to start searching!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 167062, 169114, 169212, 169213, 169214 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154214, ["x"] = 0.721333, ["y"] = 0.35 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154214, ["x"] = 0.721333, ["y"] = 0.35 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.721333, ["y"] = 0.35 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56143] = { ["id"] = 56143, ["name"] = "The Fate of Professor Elryna", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56143 }, ["series"] = { 56095, 56118 }, ["description"] = "From the looks of it, Elryna's story should have a very interesting end. This pylon here has been acting up, but I think I know why! These things use memory cores , little crystals found within the center of the orb. I bet there's one in that old magi tower. There's a snapdragon that's bigger than the terrormaws in there so here, keep the scroll for now. It should help in your fight. She's a big one!", ["objectivesText"] = "Defeat the Snapdragon Matriarch , collect the Memory Core , and activate the Memory Pylon to witness the fate of Professor Elryna. Progress: What happened that fateful day?", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 169207, 169209 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154143, ["x"] = 0.665, ["y"] = 0.474 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.665, ["y"] = 0.474 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56144] = { ["id"] = 56144, ["name"] = "Old Nasha's Paw", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 56144 }, ["description"] = "The old bear's paw is sticky with honey. She likely ransacked a number of hives before you stopped her. The Hivemother will be interested in this item.", ["objectivesText"] = "Take Old Nasha's paw to the Honeyback Hivemother for a reward. Provided item:", ["rewardItems"] = { 169659, 172146 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 153365, ["x"] = 0.626667, ["y"] = 0.263333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.263333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 169659 } },
[56145] = { ["id"] = 56145, ["name"] = "Blueprint: Advanced Adventurer Augment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56145 }, ["description"] = "<This blueprint details how to condense even more power into a ring or trinket! You should be able to upload the blueprint to Pascal-K1N6 's database in Rustbolt.>", ["objectivesText"] = "Upload the blueprint to Pascal-K1N6 's database. Provided item:", ["rewardGold"] = 169800, ["rewardItems"] = { 169112 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150359, ["x"] = 0.714, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169112 } },
[56146] = { ["id"] = 56146, ["name"] = "Making Kelpberry Wine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56146 }, ["description"] = "<This is an empty kelpberry juice cask. There is someone nearby that may appreciate a refill.>", ["objectivesText"] = "Deliver Kelpberry Wine to Maedin in Maedin 's Challenge. Progress: Did you bring me something?", ["rewardGold"] = 234000, ["rewardItems"] = { 168173, 168174 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150344, ["x"] = 0.582, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.582, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56148] = { ["id"] = 56148, ["name"] = "Call to Arms: Nazjatar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 862, ["storyline"] = { 56148 }, ["description"] = "Our objectives in Nazjatar are being interrupted by the influx of Alliance scum. Clear as many of them out of the area that you find, then report back.", ["objectivesText"] = "Slay Alliance within Nazjatar .", ["rewardItems"] = { 167744, 169614 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 143536, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1355, ["npcID"] = 154641, ["x"] = 0.486, ["y"] = 0.608 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143536, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1355, ["npcID"] = 154641, ["x"] = 0.486, ["y"] = 0.608 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.582 }, ["mapCandidates"] = { ["npc"] = { 862, 1355 }, ["zone"] = { 10052 } }, ["questType"] = "pvp" },
[56149] = { ["id"] = 56149, ["name"] = "Feed Them All", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56149 }, ["description"] = "I am grateful for the help that your Alliance has given my people, but we are desperately short on food and supplies. If we do not gather enough supplies to take care of both the Alliance and my clan, we will run out of food within the week. Thankfully, there appears to be an abundance of fathom rays in the area, but I will need help hunting them in order to gather enough food for our camp. Take this fathom hook and use it to pull down the fathom rays from above.", ["objectivesText"] = "Collect 10 Fathom Flesh . Progress: Have you returned from the hunt?", ["rewardGold"] = 309800, ["rewardItems"] = { 168253, 168254 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154235, ["x"] = 0.556, ["y"] = 0.47 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154235, ["x"] = 0.556, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56150] = { ["id"] = 56150, ["name"] = "Kill the Kritch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56150 }, ["description"] = "Mrgglrr! Mrlg rmglr grlmrrgrr, grmm mrgl grrmrrgllrr. < Rlgmrr jumps around anxiously and points toward the cave.> Grrmrlgr mrg lrglgllmrrglm mlr mrlglmrgm mrl Kriiitchrglgr. <He makes a scary face and pinching motions with his hands.> Mrglrmgr lrg, mrgglmmmr! Mrlg grrrrml lrg.", ["objectivesText"] = "Kill the Kritch . Progress: Mrgglrmr grm?", ["rewardGold"] = 309800, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153537, ["x"] = 0.45, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153537, ["x"] = 0.45, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56151] = { ["id"] = 56151, ["name"] = "Poen's Favorite Dish", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56151 }, ["description"] = "Poen is always helping us take care of every rescue we find. Can you collect some meat from the eels south of here? I like to make his favorite dish every now and then, to repay him. It also has a great effect on the ones recovering. The power of deliciousness, I tell you!", ["objectivesText"] = "Collect 15 Fresh Unagi . Progress: Did you get enough meat?", ["rewardGold"] = 309800, ["rewardItems"] = { 169234, 169280 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151635, ["x"] = 0.508, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151635, ["x"] = 0.508, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56152] = { ["id"] = 56152, ["name"] = "Turn the Scale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56152 }, ["description"] = "I am in need of your help, <class>. I have been hunting the nearby hydras for their scales, but my weapon was broken in the melee. The scales of the hydra make durable and resilient armor for our warriors. Our clan requires the scales to craft and repair our armor. If we do not resupply soon, we will be ill-equipped in our fight against the naga.", ["objectivesText"] = "Collect 20 Hydra Scales . Progress: Have you completed the hunt?", ["rewardGold"] = 309800, ["rewardItems"] = { 168519 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154238, ["x"] = 0.312, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154238, ["x"] = 0.312, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56153] = { ["id"] = 56153, ["name"] = "Most Delicious Clams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56153 }, ["description"] = "Neptulian clams are an important part of the ankoan diet. Many forget how important proper nutrition is during a time of war. A warrior can be armed with the finest weapons and training, but if she is not healthy and well-nourished she will be ineffective in battle. Now that Mezzamere is home to your Alliance, we must work hard to gather enough food to feed our soldiers. Gather as many Neptulian clams as you can find and I will see that they make it back to camp safely.", ["objectivesText"] = "Collect 10 Neptulian Clams . Progress: Have you gathered the Neptulian clams ?", ["rewardGold"] = 234000, ["rewardItems"] = { 168658, 168672 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154239, ["x"] = 0.456, ["y"] = 0.195 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154239, ["x"] = 0.456, ["y"] = 0.195 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.456, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56154] = { ["id"] = 56154, ["name"] = "Where They Hide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56154 }, ["description"] = "The naga are sending assassins to eliminate our forces. They hide nearby and murder those they cannot steal away to the slave pens. Take this special sea sponge with you. The spores will reveal the naga in all their treachery. Once revealed, slay the assassins before they can flee for reinforcements. Azshara will fall!", ["objectivesText"] = "Use the Fresh Sponge to reveal and kill 5 Zanj'ir Assassins . Progress: Have the naga assassins been eliminated?", ["rewardGold"] = 309800, ["rewardItems"] = { 168432 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154241, ["x"] = 0.412, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154241, ["x"] = 0.412, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56156] = { ["id"] = 56156, ["name"] = "A Tempered Blade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 54975, 55095, 55175, 55361, 55363, 55374, 55400, 55407, 55425, 55497, 55533, 55558, 55561, 55570, 55573, 55574, 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55618, 55694, 55851, 55860, 55861, 55937, 56037, 56038, 56039, 56043, 56156, 56234, 56325, 56350, 56640, 56641, 56642, 56643, 56644, 56741, 57010 }, ["description"] = "These blades that I wield are newly forged. The time has come to temper them in the blood of my enemies. I have heard that you are skilled in the ways of battle. I too am proficient in the business of death and I would be honored to fight at your side. Accompany me, <class>, and together we will spill the blood of our enemies.", ["objectivesText"] = "Slay 15 naga with Bladesman Inowari . Progress: A blade is not worthy of a warrior until it is tempered in the blood of the enemy.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 170512 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154248, ["x"] = 0.394667, ["y"] = 0.534667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154248, ["x"] = 0.394667, ["y"] = 0.534667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.394667, ["y"] = 0.534667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 22, ["flags"] = 0 } } },
[56160] = { ["id"] = 56160, ["name"] = "Plug the Geysers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56160 }, ["description"] = "There are several geysers nearby that will be erupting soon. Unfortunately, the elements in this area are not stable enough to handle the force of the eruptions. I need someone to plug the geysers while I use the elements to redirect the pressure to a safer area of Nazjatar . Take this sealant and use it to plug the geysers while I work to restore the elemental balance.", ["objectivesText"] = "Seal 6 Unstable Geysers. Progress: Have the geysers been sealed?", ["rewardGold"] = 309800, ["rewardItems"] = { 168482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154243, ["x"] = 0.716, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154243, ["x"] = 0.716, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56161] = { ["id"] = 56161, ["name"] = "Back Out to Sea", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1355, ["storyline"] = { 56161 }, ["description"] = "Now that things're under control here, I'm sure they could use your help back in Nazjatar ! Why don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", ["objectivesText"] = "Return to Newhome in Nazjatar .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[56162] = { ["id"] = 56162, ["name"] = "Back Out to Sea", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1355, ["storyline"] = { 56162 }, ["description"] = "Now that things're under control here, I'm sure they could use your help back in Nazjatar ! Why don't ye head back out tae sea, err, or under the sea, tae lend a hand with the new folk there?", ["objectivesText"] = "Return to Mezzamere in Nazjatar .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[56165] = { ["id"] = 56165, ["name"] = "Blueprint: Extraordinary Adventurer Augment", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56165 }, ["description"] = "<This blueprint details how to condense an extraordinary amount of power into a ring or trinket! You should be able to upload the blueprint to Pascal-K1N6 's database in Rustbolt.>", ["objectivesText"] = "Upload the blueprint to Pascal-K1N6 's database. Provided item:", ["rewardGold"] = 169800, ["rewardItems"] = { 161374, 161375, 169007, 169112, 169134 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150359, ["x"] = 0.714, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.714, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169134 } },
[56166] = { ["id"] = 56166, ["name"] = "The Needs of the People", ["level"] = 26, ["requiredLevel"] = 26, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["storyline"] = { 56166 }, ["description"] = "There are others in the camp that may be in need of aid. Ask around and see if there are any duties that you could take up. Be sure to report what you find to Speaker Utia.", ["objectivesText"] = "Speak to people in Mezzamere about things they need.", ["rewardGold"] = 234000, ["rewardXP"] = 3575, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56167] = { ["id"] = 56167, ["name"] = "Investigating the Highlands", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 114, ["storyline"] = { 55657, 56167 }, ["description"] = "When I first sensed these essences, I did not anticipate the importance of the role they would play. It is only a matter of time before all of the dragonflights are brought into the fold. Though I have reached out to the other Aspects, I have yet to hear from Alexstrasza. It is odd that she would be silent while these powers manifest. She was last seen in the Vermillion Redoubt in Twilight Highlands. I fear she may be in trouble. We must hurry.", ["objectivesText"] = "Meet Kalecgos in the Twilight Highlands.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 114, ["npcID"] = 152720, ["x"] = 0.28, ["y"] = 0.262 } }, ["coords"] = { ["mapID"] = 114, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.262 }, ["mapCandidates"] = { ["npc"] = { 114 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 241, ["questLines"] = { { ["id"] = 958, ["name"] = "In the Shadow of Crimson Wings", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56168] = { ["id"] = 56168, ["name"] = "Factory Refurbished", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "I need you to get us a Recycled Crawler Manifold . You should be able to get one up at Junkwatt Depot if you recycle parts found there.", ["objectivesText"] = "Recycled Crawler Manifold obtained. Progress: Head up to the Junkwatt Depot and get working!", ["rewardGold"] = 12300, ["rewardXP"] = 1415, ["rewardItems"] = { 168258, 168264, 168266, 168823, 168827, 168950, 168951, 168952, 168961, 169153 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 6, ["flags"] = 0 } } },
[56172] = { ["id"] = 56172, ["name"] = "Other Interests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56172 }, ["description"] = "Madam Goya is interested in many unusual items other than just rare metals. Keep your eyes out for these particular items during your travels in Nazjatar. Deliver them to me and Madam Goya will consider you for special access.", ["objectivesText"] = "Deliver 5 Curious Murloc Horn to Steelsage Gao . Progress: Have you found these items.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 167905, 168222 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152575, ["x"] = 0.735, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152575, ["x"] = 0.735, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
