[56174] = { ["id"] = 56174, ["name"] = "Other Interests", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56174 }, ["description"] = "Madam Goya is interested in many unusual items other than just rare metals. Keep your eyes out for these particular items during your travels in Nazjatar. Deliver them to me and Madam Goya will consider you for special access.", ["objectivesText"] = "Deliver 5 Disintegrating Sand Sculpture to Steelsage Gao . Progress: Have you found these items.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 167903, 167905, 167915, 168222 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 152575, ["x"] = 0.735, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152575, ["x"] = 0.735, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56175] = { ["id"] = 56175, ["name"] = "Emission Free", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 54083, 54086, 54922, 54929, 55373, 55608, 55622, 55696, 55697, 55753, 56168, 56175 }, ["description"] = "We're going to need a few Empty Energy Cells to fill out the battery pack on the mount control assembly. See if you can find me these.", ["objectivesText"] = "Collect 20 Empty Energy Cells Progress: We need to fix this battery pack.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166971, 168827 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150573, ["x"] = 0.715, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 925, ["name"] = "Making a Mount", ["orderIndex"] = 8, ["flags"] = 0 } } },
[56181] = { ["id"] = 56181, ["name"] = "This One's on Me", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55101, 55103, 56181 }, ["description"] = "I'm sure you agree that Pascal -K1N6 is the greatest invention you've ever seen! If you're not convinced yet, try to push him to his limits. I don't mind! Bring him more resources and blueprints -- he'll craft anything you need!", ["objectivesText"] = "Speak to Pascal at Rustbolt in Mechagon .", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152295, ["x"] = 0.712, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 954, ["name"] = "Junkyard Tinkering", ["orderIndex"] = 1, ["flags"] = 0 } } },
[56184] = { ["id"] = 56184, ["name"] = "Pirates, Sea Monsters, Robots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56184 }, ["description"] = "I finally found it! This is the resting place of my father, after his crew mutinied and left him here to die. I've scouted the island, and found the locations of three chests that contain mementoes of my father. Do this for me and my family. Recover my father's sword , clothing, and bones from the three chests I've marked.", ["objectivesText"] = "Recover DeMeza's father's Sword , Clothing and Bones. Progress: Help my recover the remains of my father.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 169164, 169165, 169166, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154335, ["x"] = 0.716, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154335, ["x"] = 0.716, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 970, ["name"] = "Visit from Dread Captain Demeza", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56185] = { ["id"] = 56185, ["name"] = "Whispers of N'Zoth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1161, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56504 }, ["series"] = { 56186, 56187, 56188, 56189, 56267 }, ["description"] = "Are you curious how I came to be here, in the Chamber of Heart? Of course I arrived of my own volition, but there was quite a search for me, for a time. Kalecgos remembers how it went. Speak to him, if you wish to relive the details of how I thwarted discovery by both Speaker and Old God.", ["objectivesText"] = "Speak to Kalecgos in the Chamber of Heart.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 }, { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56186] = { ["id"] = 56186, ["name"] = "Spies to the Left and Right", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 433, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56187, 56188, 56189, 56267 }, ["description"] = "Ebonhorn cannot resist the whispers for long. The dark forces that once corrupted the black dragonflight seek to overwhelm the world once again. We need a way to fight back. While I am loathe to mention him, I do know of someone who has been studying the Old Gods in order to better combat their insidious power: Wrathion. The Black Prince has associates in Pandaria, in the Tavern of the Mists at the Veiled Stair. I suggest you begin your search there. Please hurry, $p.", ["objectivesText"] = "Seek out Wrathion at the Tavern in the Mists. Progress: The Black Prince isn't here. But we might be able to help you find him.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 170471 }, ["ends"] = { { ["mapID"] = 433, ["npcID"] = 154500, ["x"] = 0.545, ["y"] = 0.725 } }, ["coords"] = { ["mapID"] = 433, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 433 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 433, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 2, ["flags"] = 0 } } },
[56187] = { ["id"] = 56187, ["name"] = "Black Winged Shadow", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6006, ["mapID"] = 433, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56186, 56188, 56189, 56267 }, ["description"] = "Obviously, the Black Prince isn't here. Trust me when I say he's not an easy one to find. If I were you, I'd make my way to Blackrock Mountain. There's a terrace carved into its slopes, where Nefarian once made his lair. Wrathion has been monitoring that place for a long time. Even if he's not there himself, you might find someone who knows where to look. And <class>... it's clear you're not the only one searching for him. Watch your back.", ["objectivesText"] = "Seek out Wrathion outside the entrance to Blackwing Descent. Progress: My head is still spinning... they showed me... such terrible... tempting things...", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 37863, 170483 }, ["starts"] = { { ["mapID"] = 433, ["npcID"] = 154500, ["x"] = 0.545, ["y"] = 0.725 } }, ["ends"] = { { ["mapID"] = 36, ["npcID"] = 154874, ["x"] = 0.264, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 433, ["source"] = "quest_giver", ["x"] = 0.545, ["y"] = 0.725 }, ["mapCandidates"] = { ["npc"] = { 36, 433 }, ["zone"] = { 6006 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 36, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56188] = { ["id"] = 56188, ["name"] = "To the Catacombs!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 46, ["mapID"] = 13, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56186, 56187, 56189, 56267 }, ["description"] = "I held out as long as I could, but... the whispers were too strong. You must hurry to Karazhan. The Black Prince said he intended to study the artifacts stored within its catacombs. Please, do not allow my failure to bring about his doom!", ["objectivesText"] = "Seek out Wrathion outside the Karazhan Catacombs. Progress: <It seems the lookout gave his life in service to the Black Prince.>", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 23412, 23413, 23414, 131248, 142469, 170486 }, ["starts"] = { { ["mapID"] = 13, ["npcID"] = 154874, ["x"] = 0.482, ["y"] = 0.702 } }, ["ends"] = { { ["mapID"] = 42, ["npcID"] = 154870, ["x"] = 0.47, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 13, ["source"] = "quest_giver", ["x"] = 0.482, ["y"] = 0.702 }, ["mapCandidates"] = { ["npc"] = { 13, 42 }, ["zone"] = { 46 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 42, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 4, ["flags"] = 0 } } },
[56189] = { ["id"] = 56189, ["name"] = "On the Trail of the Black Prince", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 41, ["mapID"] = 42, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56185, 56186, 56187, 56188, 56267 }, ["description"] = "<It looks like a fight took place here. N'Zoth's agents must have already entered the catacombs beneath Karazhan. The dead lookout still has a set of keys on him. Perhaps they will unlock the door. With any luck, you can find Wrathion before N'Zoth's agents and gain something that can help Ebonhorn.>", ["objectivesText"] = "Enter the Karazhan Catacombs and search for a cure for Ebonhorn. Progress: <The note appears to have been left behind in a hurry, and deliberately placed where you would find it.>", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 170490 }, ["starts"] = { { ["mapID"] = 42, ["npcID"] = 154870, ["x"] = 0.47, ["y"] = 0.694 } }, ["coords"] = { ["mapID"] = 42, ["source"] = "quest_giver", ["x"] = 0.47, ["y"] = 0.694 }, ["mapCandidates"] = { ["npc"] = { 42 }, ["zone"] = { 41 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2232, ["db2PoiUiMapID"] = 1521, ["db2QuestSortName"] = "Day of the Dead", ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 5, ["flags"] = 0 } } },
[56190] = { ["id"] = 56190, ["name"] = "Save Ebonhorn", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10638, ["mapID"] = 1473, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56504 }, ["description"] = "<The potion appears to be powerful and chaotic. It changes color seemingly at random. This must be the concoction Wrathion wrote about in his journal. Just standing near it grants you a sense of peace and clarity. You may not have found the Black Prince himself, but perhaps what he left behind for you can help Ebonhorn.>", ["objectivesText"] = "Return to the Chamber of Heart and treat Ebonhorn with the Potion of Mental Clarity .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169653 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10638 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 6, ["flags"] = 0 } } },
[56205] = { ["id"] = 56205, ["name"] = "Just Ptrust Me On This", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 56205 }, ["description"] = "Ahhh, it is good to see you, <name>. How is de defective one? Still pleased to be at your side? I have given this some thought. Fear may still be what holds your not-so-little one back, but your love is what enables him to thrive without his wings. Perhaps that love will be what restores him to de skies. I am asking you to trust me. I wish to try something. If I am correct then de two of you will find yourselves airborne as nature intended!", ["objectivesText"] = "Place your faith in Pa'ku and Kua'fon.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 157782 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 127377, ["x"] = 0.711, ["y"] = 0.5 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.711, ["y"] = 0.5 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 945, ["name"] = "Wingless Redemption", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56206] = { ["id"] = 56206, ["name"] = "Heroic: Battle for Stromgarde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 56206 }, ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 169196, 169197 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56209] = { ["id"] = 56209, ["name"] = "The Halls of Origination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 84, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472 }, ["description"] = "It looks like the Halls of Origination have been claimed by a group o' tol'vir calling themselves the Amathet. I don't know much about them other than they're new in town and not the friendliest of types. We'll need tae get in there and re-activate the forge, or else Azeroth will be done for!", ["objectivesText"] = "Defeat the Amathet forces and reactivate the forge in the Halls of Origination. Progress: Azeroth's gonna be done for if we dun get this thing back online!", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 132514 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2187, ["db2PoiUiMapID"] = 1542, ["questLines"] = { { ["id"] = 950, ["name"] = "The Forge of Origination", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56210] = { ["id"] = 56210, ["name"] = "Scrying Stones", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56210 }, ["description"] = "I have a gift for you, <name>. It's a stone unlike anything you've seen before. To the uninformed, it may seem to be a simple rock, but it's far more precious than that. This is a scrying stone . It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. Use the stone to reveal treasure hidden away by ancient magic.", ["objectivesText"] = "Find treasures hidden away by magic within Nazjatar .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 167077, 169817 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153512, ["x"] = 0.49, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56211] = { ["id"] = 56211, ["name"] = "Scrying Stones", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56211 }, ["description"] = "I have a gift for you, <name>. This stone is unlike anything you may have seen before. To the uninformed, it appears to be a simple rock, but it is far more precious than that. This is a scrying stone . It reveals objects that have been hidden by magic. When near an anomaly, the runes etched within will begin to glow. Use the stone to reveal treasure hidden away by ancient magic.", ["objectivesText"] = "Find treasures hidden away by magic within Nazjatar . Progress: Have you found any treasure?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 167077, 169817 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56214] = { ["id"] = 56214, ["name"] = "Good Girl", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 56214 }, ["description"] = "I have learned so much by your side, I can't believe how many naga we've taken down! When you first arrived, I was skeptical that you'd make a difference. We've been down here, fighting, for so long. I had almost lost hope. But now, we see a way out of the darkness of the depths, finally! I took in a snapdragon pup when we formed Newhome, been training her ever since. I think... I think I'd like you to have her. She'll make a great mount... and loyal friend.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169199 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56215] = { ["id"] = 56215, ["name"] = "Glittering Shell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 56215 }, ["description"] = "Hi, friend. I just wanted you to know that traveling with you has been the best ever! I never thought I could learn so much about fighting, but now I feel like I can actually hold my own. I will protect all of the wee ones that can't protect themselves! <Poen produces a crab from somewhere, it has a bright shell.> Like this little one. I found him a while back, while we were out. He looked so scared. Hey, why don't you take him?", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56216] = { ["id"] = 56216, ["name"] = "Last Heirloom", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 56216 }, ["description"] = "We have encountered many foes together, and emerged victorious every time. I have you to thank for our safety this day, and my prowess in combat. I will be honest with you, friend. I did not think I would live this long. My people had families, once. Traditions. We would carve symbols into our talismans and pass them down from generation to generation of deep sea hunters. Charms for luck, or prowess, each family had their own. This is mine. I have none to pass it on to. I would like you to have it", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 170155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56217] = { ["id"] = 56217, ["name"] = "Wild Tame", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 56217 }, ["description"] = "In our time together, I have learned much. Both about my own abilities, and about your people. You are selfless in the face of challenge, much like our own. I consider us kin. For some time, I have been training a snapdragon I found as a pup. He is a worthy mount, and I have been waiting for a worthy hunter to ride him. I believe I have found that hunter. Here, he is yours.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169199, 169200 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56218] = { ["id"] = 56218, ["name"] = "Beauty in the Deeps", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 56218 }, ["description"] = "We have slain many enemies, spilled much blood on the sand. My skills have improved tenfold fighting at your side. Yet let us not forget that once, this was a place of peace. Once, my people walked amongst the caverns and reefs undisturbed. There is beauty, here, in the depths, all around us. Take a moment, sit, and enjoy your serene surroundings. Look here, a crab with a shell of brilliant colors. You see? There is beauty here, even now.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 169353, 169354 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56219] = { ["id"] = 56219, ["name"] = "Tome of Tears", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 56219 }, ["description"] = "We've been fighting side by side for a while now. I didn't think an old salt like me could get any better at killing naga, but here we are. I have something to show you... <Vim produces a book from his pack.> Worst thing we can do is forget. So many names I've written in this book, each and every one of them an Unshackled. All of them gone, now. I will never forget their names. I want you to have it. Tell people. Tell them who they were, and what we have done here.", ["objectivesText"] = "Accept a gift from your companion.", ["rewardItems"] = { 170154, 170155 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56222] = { ["id"] = 56222, ["name"] = "WANTED: Lady Naz'jess", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56222 }, ["description"] = "Wanted for attacks against the people of Nazjatar . Lady Naz'jess has been driving the weapon masters to create crueler devices. Last seen skulking about Zanj'ir Terrace. She is vicious, proceed with caution. Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Lady Naz'jess. Progress: Has her command come to an end?", ["rewardGold"] = 619600, ["rewardItems"] = { 168265 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56223] = { ["id"] = 56223, ["name"] = "WANTED: Commander Sarj'eth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56223 }, ["description"] = "Wanted for attacks against the people of Nazjatar . Commander Sarj'eth has attempted to enslave many Horde survivors. He commands slavers in Zanj'ir Terrace. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Commander Sarj'eth. Progress: Did the brave commander reach the end of his days?", ["rewardGold"] = 468000, ["rewardItems"] = { 168317 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56224] = { ["id"] = 56224, ["name"] = "WANTED: Lord Ha'kass", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56224 }, ["description"] = "Wanted for attacks against the people of Nazjatar . Lord Ha'kass has attempted to enslave many Horde survivors. He commands slavers in Zanj'ir Wash. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Lord Ha'kass. Progress: Was the villain found?", ["rewardGold"] = 584200, ["rewardItems"] = { 168318 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56225] = { ["id"] = 56225, ["name"] = "WANTED: Lady Narjiss", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56225 }, ["description"] = "Wanted for attacks against the Horde! Lady Narjiss is responsible for leading several raids and ambushes against our soldiers. Last seen on the outskirts of Zanj'ir Terrace. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Lady Narjiss. Progress: Did you silence her?", ["rewardGold"] = 468000, ["rewardItems"] = { 168319 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56226] = { ["id"] = 56226, ["name"] = "WANTED: Gler'thogg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56226 }, ["description"] = "Gler'thogg is responsible for the death and torture of many of the Unshackled. They have shared with us their pain. Bring back his eye. He dwells in the Deepcoil Tunnels. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the Eye of Gler'thogg . Progress: Is this your first enucleation?", ["rewardGold"] = 468000, ["rewardItems"] = { 168321 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56227] = { ["id"] = 56227, ["name"] = "WANTED: Inquisitor Ithriza", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56227 }, ["description"] = "Wanted for attacks against the Horde! Inquisitor Ithriza is responsible for leading several raids and ambushes against our soldiers. Last seen in the vicinity of Dragon's Teeth Basin. Extreme caution advised! Upon completion of the mission, report to Seacaller Unow for commendation.", ["objectivesText"] = "Retrieve the head of Inquisitor Ithriza. Progress: Did you knock him down a peg?", ["rewardGold"] = 468000, ["rewardItems"] = { 168322 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154450, ["x"] = 0.48, ["y"] = 0.615 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.615 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56231] = { ["id"] = 56231, ["name"] = "Reinforced Cache", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56231 }, ["description"] = "The heavily reinforced chest is of naga construction and appears to be reinforced with a heavy-duty lock of some kind. Reinforcement aside, the cache still requires a key to unlock. The key is most likely being held by one of the nearby naga commanders.", ["objectivesText"] = "Locate the key to the Naga Cache. Progress: The chest is locked and requires a key.", ["rewardGold"] = 309800, ["rewardItems"] = { 168261 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56232] = { ["id"] = 56232, ["name"] = "Void Cache", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56232 }, ["description"] = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind. Magical reinforcement aside, the cache still requires a key to unlock. The key is most likely being held by one of the nearby naga commanders.", ["objectivesText"] = "Locate the key to the Naga Cache. Progress: The chest is locked and requires a key.", ["rewardGold"] = 234000, ["rewardItems"] = { 168260 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56233] = { ["id"] = 56233, ["name"] = "Arcane Cache", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56233 }, ["description"] = "The heavily reinforced chest is of naga construction and appears to be reinforced with a magical lock of some kind. Magical reinforcement aside, the cache still requires a key to unlock. The key is most likely being held by one of the nearby naga commanders.", ["objectivesText"] = "Locate the key to the Naga Cache. Progress: The chest is locked and requires a key.", ["rewardGold"] = 280900, ["rewardItems"] = { 168199 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56234] = { ["id"] = 56234, ["name"] = "Friends In Need", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55593, 55595, 55597, 55598, 55599, 55600, 55601, 55860, 55861, 55937, 56037, 56038, 56039, 56234 }, ["description"] = "I doubt that will be the last we've seen of Priscilla, but at least she is no longer one of our immediate concerns. We must think carefully before making our next move. In the meantime we should continue to build upon our relationship with our new allies, the Ankoan. Work with them to secure the area and hone their skills, we're not out of the woods yet. I fear the biggest battle is still to come. Let's show them that together we can take on Azshara's forces and succeed!", ["objectivesText"] = "Support your allies in Nazjatar by gaining 3000 experience combined between Farseer Ori, Hunter Akana, and Bladesman Inowari.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 168847, 169489, 169910, 170153, 170161 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 942, ["name"] = "Secrets in the Sea", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 38, ["flags"] = 0 } } },
[56235] = { ["id"] = 56235, ["name"] = "Down Into Nazjatar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54012, 54015, 54018, 54021, 55053, 55054, 55092, 55094, 55374, 55384, 55385, 55400, 55407, 55425, 55469, 55481, 55482, 55485, 55486, 55488, 55489, 55490, 55497, 55500, 55533, 55618, 55799, 55851, 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56044, 56045, 56046, 56047, 56063, 56235, 56236, 56429, 57010 }, ["description"] = "We have much to do <name>. However our troops are weary and need rest. Decisions made when tired are often the wrong ones. These \"Unshackled\" have offered to aid us with what forces they have. If we hope to survive down here against Azshara's forces, we will need to support our new allies. Join one of their hunters and aid them in their tasks, we will remain here and discuss our next move.", ["objectivesText"] = "Support your allies in Nazjatar by getting one to rank 3.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168846 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 1023, ["name"] = "Azshara's Trap", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 24, ["flags"] = 0 } } },
[56236] = { ["id"] = 56236, ["name"] = "Down But Not Out", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55862, 55863, 55864, 55865, 55866, 55867, 55868, 55869, 55870, 55967, 56045, 56046, 56047, 56236 }, ["series"] = { 55869 }, ["description"] = "Ashvane won't trouble us for now, but our situation remains perilous. I must consider our next move, <name>. In the meantime we should continue to build upon our relationship with our new allies, the Unshackled. Test them in combat, train them while you can, we will need their aid in the battles to come. We will show them that through unity there are no obstacles that can stand in our way.", ["objectivesText"] = "Support your allies in Nazjatar by gaining 2400 experience combined between Vim Brineheart, Poen Gillbrack, and Neri Sharpfin.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 29792, 29793, 29794, 30394, 30395, 30396, 30399, 30522, 31312, 31313, 31314, 31315, 33226, 35925, 35926, 35927, 35928, 35932, 35933, 35934, 35935, 37829, 38711, 39015, 39044, 39076, 39777, 39788, 39790, 39836, 52596, 52622, 54213, 59050, 59051, 59052, 63542, 63543, 63544, 63545, 63546, 63547, 63548, 63549, 88704, 88705, 88706, 88707, 88708, 112867, 112868, 112869, 112870, 112871, 112872, 112873, 112874, 131285, 131432, 131433, 131516, 142054, 143740, 143741, 147838, 159146, 159827, 167077, 168053, 168846, 168847, 169489, 170085, 170100, 170103, 170153, 170167, 170171, 170176, 170183, 170184, 181368, 181377, 181569, 181576, 181577, 181589, 181591, 181603, 181612, 181703, 182180, 182484, 182493, 182502, 182511, 183744, 184294, 184363, 184765, 184767, 184768, 184839, 184843, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467, 211279, 237812, 242241, 242386, 244846, 244888, 249620, 249627 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 943, ["name"] = "Secrets in the Sea", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 38, ["flags"] = 0 } } },
[56239] = { ["id"] = 56239, ["name"] = "Strange Silver Knife", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56239 }, ["series"] = { 56241, 56243, 56246, 56247 }, ["description"] = "<This silver knife is small and lightly decorated, you found it inside of a chest. It was more likely used for eating or preparing food than combat. What would the naga need with such a thing? One of the Ankoan may know more...>", ["objectivesText"] = "Ask the Ankoan about the knife. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 167077, 169215 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169215 } },
[56240] = { ["id"] = 56240, ["name"] = "Strange Silver Knife", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56240 }, ["series"] = { 56242, 56244, 56245, 56248 }, ["description"] = "<This silver knife is small and lightly decorated, you found it inside of a chest. It was more likely used for eating or preparing food than combat. What would the naga need with such a thing? One of the Unshackled may know more...>", ["objectivesText"] = "Ask the Unshackled about the knife. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 167077, 169215, 169216 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169216 } },
[56241] = { ["id"] = 56241, ["name"] = "Preserved Clues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56241 }, ["series"] = { 56239, 56243, 56246, 56247 }, ["description"] = "We have found similar chests, as you describe. We believe they were left behind by one that came before the naga. Some are even locked by odd arcane runes, the naga seem most interested in those. I know little about them, save that we find them most often in the city ruins. If you seek to decipher their history, I would begin there.", ["objectivesText"] = "Search in Zin-Azshari for information about the strange arcane chests.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56242] = { ["id"] = 56242, ["name"] = "Preserved Clues", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56242 }, ["series"] = { 56240, 56244, 56245, 56248 }, ["description"] = "If you find anything else in those chests that you don't need, you feel free to bring it on over my way. Found a few of them myself. Don't look like they belong to the naga, probably someone that lived in the city. Some are locked tight by arcane magic, seen the naga taking those back with them. Probably got the good stuff in there. I don't know much more than that. If you want a history lesson, I'd snoop around the city ruins.", ["objectivesText"] = "Search in Zin-Azshari for information about the strange arcane chests.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 169216 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56243] = { ["id"] = 56243, ["name"] = "Diaries of the Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["storyline"] = { 56243 }, ["series"] = { 56239, 56241, 56246, 56247 }, ["description"] = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...> Then he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas. Of course, he was bitten on the leg by a lesser summon, and... <It continues -- not useful, but you surmise there may be more such tomes.>", ["objectivesText"] = "Search Zin-Azshari in Nazjatar for additional diaries. Progress: <A preserved tome.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56244] = { ["id"] = 56244, ["name"] = "Diaries of the Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["storyline"] = { 56244 }, ["series"] = { 56240, 56242, 56245, 56248 }, ["description"] = "<The enchantments preserving this journal are intact, but fading. It appears to be the diary of a citizen of the city. You turn to a random page...> Then he had the audacity to enter our summoning circle and demand we evict his study space at once. Who willingly steps into the chaos of a summoning ritual? He is mad. We call him that now -- Mad Mardivas. Of course, he was bitten on the leg by a lesser summon, and... <It continues -- not useful, but you surmise there may be more such tomes.>", ["objectivesText"] = "Search Zin-Azshari in Nazjatar for additional diaries. Progress: <A preserved tome.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56245] = { ["id"] = 56245, ["name"] = "Enchanted Lock", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["storyline"] = { 56245 }, ["series"] = { 56240, 56242, 56244, 56248 }, ["description"] = "<The lock appears to be secured by a magical mechanism. It is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle. You look around the room, and see something odd in the water.>", ["objectivesText"] = "Solve Mardivas' arcane puzzle to unlock the enchanted lock . Progress: <The lock hums.>", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56246] = { ["id"] = 56246, ["name"] = "Enchanted Lock", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["storyline"] = { 56246 }, ["series"] = { 56239, 56241, 56243, 56247 }, ["description"] = "<The lock appears to be secured by a magical mechanism. It is clearly one of Mardivas', and from what you can surmise from reading the journals, it is likely locked via an arcane puzzle. You look around the room, and see something odd in the water.>", ["objectivesText"] = "Solve Mardivas' arcane puzzle to unlock the enchanted lock . Progress: <The lock hums.>", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56247] = { ["id"] = 56247, ["name"] = "Treasure Tale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56247 }, ["series"] = { 56239, 56241, 56243, 56246 }, ["description"] = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar . From the sounds of it, he was not well-liked, which worked out for him, as he did not much like others. You also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey. Artisan Itanu will surely enjoy hearing the end of this tale.>", ["objectivesText"] = "Return to Artisan Itanu in Nazjatar .", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 167077, 169215 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153510, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56248] = { ["id"] = 56248, ["name"] = "Treasure Tale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56248 }, ["series"] = { 56240, 56242, 56244, 56245 }, ["description"] = "<You discovered the history of Mardivas, a sorcerer that once lived in the city and the crafter of the arcane chests scattered around Nazjatar . From the sounds of it, he was not well-liked, which worked out for him, as he did not much like others. You also found and unlocked one of his \"unsolvable\" arcane locks. This knowledge may prove useful on your journey. Finder Palta will surely enjoy hearing the end of this tale.>", ["objectivesText"] = "Return to Finder Palta in Newhome in Nazjatar .", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["rewardItems"] = { 167077, 169215 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56249] = { ["id"] = 56249, ["name"] = "I Am the Trashmaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 56249 }, ["description"] = "Whatcha got there, richmon? Ha! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted! So you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. You just give dat ol' thing to me, an Jani will be takin' care o' you...", ["objectivesText"] = "Give Jani the Trashmaster's Mantle .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 168970, 169394 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 126334, ["x"] = 0.355, ["y"] = 0.078 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 126334, ["x"] = 0.355, ["y"] = 0.078 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.355, ["y"] = 0.078 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[56250] = { ["id"] = 56250, ["name"] = "I Am the Trashmaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 56250 }, ["description"] = "Whatcha got there, richmon? Ha! You think you be de Trashmasta? You be talkin' to de God of Garbage! De Ruler of Rubbish! Master of all things Discarded an' Unwanted! So you not be wantin' that ol' trashy cloak, eh? Jani got somethin' better. You just give dat ol' thing to me, an Jani will be takin' care o' you...", ["objectivesText"] = "Give Jani the Trashmaster's Mantle .", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["rewardItems"] = { 168970, 169394 }, ["starts"] = { { ["mapID"] = 864, ["npcID"] = 136559, ["x"] = 0.362, ["y"] = 0.368 } }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 136559, ["x"] = 0.362, ["y"] = 0.368 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.362, ["y"] = 0.368 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[56256] = { ["id"] = 56256, ["name"] = "The Battle of Alterac", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 2597, ["mapID"] = 25, ["storyline"] = { 56256 }, ["description"] = "The Explorers' League believes there are artifacts in Alterac Valley , but the Frostwolf orcs won't let us explore. We can't allow the Horde to stop our scholarly pursuits! Defeat the Frostwolf general, Drek'Thar . With him dead, the orcs will lose their edge. Drek'Thar is in Frostwolf Keep, in the south of Alterac Valley . Vanquish him, and then return to me.", ["objectivesText"] = "Enter Alterac Valley , defeat the Horde general Drek'thar .", ["rewardGold"] = 929400, ["rewardXP"] = 4150, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 13816, ["x"] = 0.452, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.452, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 2597 } }, ["questType"] = "pvp" },
[56257] = { ["id"] = 56257, ["name"] = "The Battle for Alterac", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["mapID"] = 25, ["storyline"] = { 56257 }, ["description"] = "The Stormpike dwarves and their allies have invaded Alterac Valley , and we must drive them out! To win the battle for Alterac, we must defeat their general, Vanndar Stormpike ! You will find Vanndar in Dun Baldar, in the north of Alterac Valley . Destroy him, <name>, and then return to me.", ["objectivesText"] = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike .", ["rewardGold"] = 929400, ["rewardXP"] = 4150, ["ends"] = { { ["mapID"] = 25, ["npcID"] = 13817, ["x"] = 0.585, ["y"] = 0.342 } }, ["coords"] = { ["mapID"] = 25, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.342 }, ["mapCandidates"] = { ["npc"] = { 25 }, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[56258] = { ["id"] = 56258, ["name"] = "Ivus the Forest Lord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 56258 }, ["description"] = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked. The damage has grown too great for the Circle to control! Ivus must be called to our aid. The Frostwolf soldiers carry elemental charms called storm crystals . We can use the charms to conjure Ivus. Venture forth and claim the crystals, <name>!", ["objectivesText"] = "Slay Horde and loot a Storm Crystal and return it to Archdruid Renferal in Alterac Valley . Progress: Have you brought us some crystals, <name>?", ["rewardItems"] = { 17423 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[56259] = { ["id"] = 56259, ["name"] = "Lokholar the Ice Lord", ["level"] = 20, ["requiredLevel"] = 20, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 56259 }, ["description"] = "I come from Thunder Bluff, <race>. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times. But let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin. Victory will be assured when the elemental lord is loosed upon the Stormpike army.", ["objectivesText"] = "Slay Alliance and loot Stormpike Blood and return it to Primalist Thurloga within Frostwolf Village in Alterac Valley . Progress: Have you come with an offering?", ["rewardItems"] = { 17306 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[56260] = { ["id"] = 56260, ["name"] = "Unlocking the Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 56260 }, ["description"] = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion. I won't spoil it, but ye best get back there as quick as ye can.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["rewardItems"] = { 169768 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 154465, ["x"] = 0.506, ["y"] = 0.6505 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.6505 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[56261] = { ["id"] = 56261, ["name"] = "Return to the Heart", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56261 }, ["description"] = "Greetings, Champion of Azeroth. MOTHER's been monitorin' yer progress with the Heart of Azeroth, and is mighty pleased with the work you've done tae make it stronger. At least, we think she's pleased. It's difficult tae tell at times. Regardless, come back tae the Chamber of Heart when ye've got a chance. There's more that needs doin'.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[56262] = { ["id"] = 56262, ["name"] = "Back to the Chamber", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56262 }, ["description"] = "The Heart o' Azeroth is gettin' stronger every day, and it's makin' a difference. Make yer way tae the Chamber o' Heart, champion. Yer talents are needed.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[56263] = { ["id"] = 56263, ["name"] = "Unlocking the Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56263 }, ["description"] = "There's somethin' special waitin' fer ye back in the Chamber of Heart, champion. I won't spoil it, but ye best get back there as quick as ye can.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 23400, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 154464, ["x"] = 0.749, ["y"] = 0.153 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.749, ["y"] = 0.153 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[56264] = { ["id"] = 56264, ["name"] = "We've Got Crabs!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56264 }, ["description"] = "<name>, you're just in time. Everything's ready for the crab hunt! Okay, okay... I know what you're thinking. A founding member of D.E.H.T.A. that condones hunting? I'm going to level with you, <name>. I've got a bar full of hungry murlocs that only eat three things: crabs, fish, and people. If that's not reason enough, crabs are overpopulated in this region and they're decimating the local grub worm population! How many innocent grub worms need to die before we do something, <name>?", ["objectivesText"] = "Collect 12 Crackleclaw Crabs . Progress: How many innocent grub worms need to die before we do something, <name>?", ["rewardGold"] = 309800, ["rewardItems"] = { 168628 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56265] = { ["id"] = 56265, ["name"] = "Drunk Angry Murlocs", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56265 }, ["description"] = "Those no-good Bloodfins ran off with all of the beer! I've been experimenting with brews that only use ingredients native to Nazjatar , but it's still a work in progress. For now, I must rely on whatever I can scrounge up from the shipwreck. My supply of beer was already limited, but now it's all gone thanks to those thieving Bloodfin murlocs! We're going to have some very angry customers here if we don't get it back. Please recover the stolen lager from Bloodfin Village before it's too late!", ["objectivesText"] = "Collect 12 Ocean \"Infused\" Lagers . Progress: Please tell me you found the beer.", ["rewardGold"] = 309800, ["rewardItems"] = { 168629, 169280, 170075 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56266] = { ["id"] = 56266, ["name"] = "Mgglurky's Mugglrgl", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56266 }, ["description"] = "My cook, Mgglurky, lost his mugglrgl and he's refusing to work until he gets it back. I've got a bar full of hungry murlocs and nothing to feed them until Mgglurky starts cooking. If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands! I don't know about you, but I definitely don't want to be the main course tonight. There were some Bloodfins lurking around earlier. Search Bloodfin Village for the mugglrgl and bring it back to me once you find it.", ["objectivesText"] = "Retrieve Mgglurky's Mugglrgl from Bloodfin Village. Progress: If Mgglurky doesn't find his mugglrgl soon, we're going to have a riot on our hands!", ["rewardGold"] = 234000, ["rewardItems"] = { 168647 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153884, ["x"] = 0.254667, ["y"] = 0.265333 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.254667, ["y"] = 0.265333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["db2QuestInfoID"] = 266, ["db2QuestInfoName"] = "Combat Ally Quest" },
[56301] = { ["id"] = 56301, ["name"] = "Go For The Gold", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56301 }, ["description"] = "I've heard lot's of stories about dead fathers, mothers, and family treasures. Don't believe any of it. We're all here to get any pirate gold, before these mecha-fools get it first! If there's gold to be had here, it's in that fat chest the murlocs are guarding. Kill their chief, empty out the chest, and we'll split it fifty-fifty, since I'm telling ya about it.", ["objectivesText"] = "Recover the Murloc Treasure Bag. Progress: Go get the gold!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 169221, 169222 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154485, ["x"] = 0.215, ["y"] = 0.818 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154485, ["x"] = 0.215, ["y"] = 0.818 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.215, ["y"] = 0.818 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56304] = { ["id"] = 56304, ["name"] = "The High Life", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56304, 56321, 56422 }, ["description"] = "You there, I require some help. Everyone where I once called home lost their lives to the flood. I still don't know what became of my father, Corin. It pains me to return to the estates, and there are vengeful spirits who haunt the once pristine grounds. Will you help me find out what happened to my father?", ["objectivesText"] = "Accompany Kelya Moonfall into the Highborne Estates to search for the spirit of her father.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154574, ["x"] = 0.742, ["y"] = 0.25 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.742, ["y"] = 0.25 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 948, ["name"] = "Kelya Moonfall", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56305] = { ["id"] = 56305, ["name"] = "Let's Fish!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55055, 55298, 55339, 56305 }, ["description"] = "We may need the help of some friends to land this fish! Use the Hundred-Fathom Lure when you're ready to start.", ["objectivesText"] = "Catch and kill the Deepwater Maw . Progress: Let's fish!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151462, ["x"] = 0.37, ["y"] = 0.472 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.472 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "group", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 924, ["name"] = "Mechagon Fishing", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56306] = { ["id"] = 56306, ["name"] = "The Family Jewels", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56306 }, ["description"] = "Darn pirates stole my jewels... err, I mean my sister's... uh, mom's jewelry. Yeah, that's the story! Point is, they stole it, and it's all out there strewn around in the mud, and treasure chests. Maybe on a few of the robots and murlocs. My mom's not greedy, she just wants a few of the necklaces with gold and lots of diamonds. I'd pay ya for those.", ["objectivesText"] = "Recover 75 Family Jewels Progress: Go steal those jewels back for my brother!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 169241 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154511, ["x"] = 0.242, ["y"] = 0.754 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154511, ["x"] = 0.242, ["y"] = 0.754 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.242, ["y"] = 0.754 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56308] = { ["id"] = 56308, ["name"] = "Assault: Aqir Unearthed", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56308 }, ["description"] = "Our position is being overrun. The aqir are surging in greater numbers than I've ever seen! I'm not sure how long we'll be able to hold the line. We need you to drive them back!", ["objectivesText"] = "Drive back the Aqir Assault in Uldum . Progress: Our men can only hold out so long.", ["rewardXP"] = 10225, ["rewardItems"] = { 169432, 174960 }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Drive back the Aqir", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[56309] = { ["id"] = 56309, ["name"] = "City of Drowned Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56309 }, ["series"] = { 56311, 56313, 56315 }, ["description"] = "Champion, I have a personal favor to ask of you that I do not feel I can ask of any of my sentinels. This... this is not on behalf of the Alliance, or the war, or even our battle against Azshara. This is a favor for me. When I was a little girl, my city was attacked by the Legion. Many of the survivors fled here only to drown or worse. I must know their fate. Will you help me search for signs?", ["objectivesText"] = "Help Shandris Feathermoon search the Drowned Market.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154522, ["x"] = 0.76, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154660, ["x"] = 0.74, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.76, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56310] = { ["id"] = 56310, ["name"] = "City of Drowned Friends", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56310 }, ["series"] = { 56312, 56314, 56316 }, ["description"] = "Champion, I have a personal favor to ask of you. This is not on behalf of the Horde or the war effort. It has been over ten thousand years since I last walked these streets. I knew many of these people, even trained some of them. Will you walk with me as I learn their fates? The road is dangerous, and I do not trust myself to maintain calm as I try to resurface old grief.", ["objectivesText"] = "Help First Arcanist Thalyssra search the Drowned Market.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154520, ["x"] = 0.735, ["y"] = 0.478 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154661, ["x"] = 0.74, ["y"] = 0.418 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.735, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56311] = { ["id"] = 56311, ["name"] = "The Ever Drowning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56311 }, ["series"] = { 56309, 56313, 56315 }, ["description"] = "Stay close, Champion. I have some magical items that might help us defend briefly against magic attacks, but Azshara was the greatest mage our kind has ever known. I do not feel confident that these trinkets will hold back her power for long, or even be usable afterward. Speak with me when you are ready.", ["objectivesText"] = "Escort Shandris Feathermoon through the Drowned Market.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154660, ["x"] = 0.74, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56312] = { ["id"] = 56312, ["name"] = "The Ever Drowning", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56312 }, ["series"] = { 56310, 56314, 56316 }, ["description"] = "Queen Azshara has her eye on us now. We must proceed with caution. I do not know what she may try but stay close to me. Whatever this threat is we must pass through it if we are to find Sivara. Speak with me when you are ready to proceed.", ["objectivesText"] = "Escort First Arcanist Thalyssra through the Drowned Market.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154661, ["x"] = 0.74, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56313] = { ["id"] = 56313, ["name"] = "The Warbringer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56313 }, ["series"] = { 56309, 56311, 56315 }, ["description"] = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago. If you are feeling brave enough to commune with this echo, I will stand guard as you do.", ["objectivesText"] = "Commune with the Memory of the Pact . Progress: Be ready for anything.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 82589, 82590, 82591, 82592, 82593, 82594, 82595, 82596, 82597, 82598, 211279 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.791, ["y"] = 0.447 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56314] = { ["id"] = 56314, ["name"] = "The Warbringer", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56314 }, ["series"] = { 56310, 56312, 56316 }, ["description"] = "We are standing in the center of some very powerful magics. An echo of something Azshara did long ago. If you are feeling brave enough to commune with this echo, I will stand guard as you do.", ["objectivesText"] = "Commune with the Memory of the Pact . Progress: Be ready for anything.", ["rewardGold"] = 22130, ["rewardXP"] = 850, ["rewardItems"] = { 82589, 82590, 82591, 82592, 82593, 82594, 82595, 82596, 82597, 82598, 211279 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.789333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56315] = { ["id"] = 56315, ["name"] = "They Made Their Choice", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56315 }, ["series"] = { 56309, 56311, 56313 }, ["description"] = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well! Those who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. I am almost afraid of what we will find if we do find my friend. Wait, did you hear something?", ["objectivesText"] = "Aid Shandris Feathermoon . Progress: Thrice damned Azshara. Her evil knows no bounds.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155071, ["x"] = 0.791, ["y"] = 0.447 }, { ["mapID"] = 1355, ["npcID"] = 155237, ["x"] = 0.798, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.791, ["y"] = 0.447 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56316] = { ["id"] = 56316, ["name"] = "They Made Their Choice", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56316 }, ["series"] = { 56310, 56312, 56314 }, ["description"] = "It wasn't enough for Azshara to break the world. She had to doom the rest of our people here as well! Those who didn't choose to become naga were stuck in this horrifying half death, left to haunt these drowned ruins. I am almost afraid to find Sivara. Wait, did you hear something?", ["objectivesText"] = "Aid First Arcanist Thalyssra . Progress: Thrice damned Azshara. Her evil knows no bounds.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 155325, ["x"] = 0.789333, ["y"] = 0.446667 }, { ["mapID"] = 1355, ["npcID"] = 155342, ["x"] = 0.798, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.789333, ["y"] = 0.446667 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56319] = { ["id"] = 56319, ["name"] = "The Quickcharge Contract", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55210, 55211, 56319, 56320 }, ["description"] = "Wondrous news, dear test subject! My dear brother and I have restored 65% of the functionality of our research laboratory. We are hoping to resume our regular research schedule shortly, but require a fresh batch of brave test subjects to help us push the laws of nature and science to their limits! If you're interested, you'll just need to agree to our standard verbal contract first...", ["objectivesText"] = "Agree to the Quickcharge Contract. Progress: How can I help you, dear test subject?", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["questLines"] = { { ["id"] = 959, ["name"] = "Quickcharge Experiments", ["orderIndex"] = 2, ["flags"] = 0 } } },
[56320] = { ["id"] = 56320, ["name"] = "Your First Charge is Free!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 55210, 55211, 56319, 56320 }, ["description"] = "Do you feel the energy rippling through the ground here, my dear test subject? <Flip inhales deeply.> Without that constant bristle of electricity, nothing of any meaning would exist. My dear sister and I have tapped into a high-voltage power line buried here, but the real juice is over in Bondo's Yard. He selfishly hoards access to the heftiest power line in Mechagon ! If you want to recharge your empty energy cells, you're going to have to get access to the Charging Station from Flux.", ["objectivesText"] = "Gain access to the Charging Station in Bondo's Yard, then use it to charge an Empty Energy Cell.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.721, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 953, ["name"] = "Rustbolt Energy", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 959, ["name"] = "Quickcharge Experiments", ["orderIndex"] = 1, ["flags"] = 0 } } },
[56321] = { ["id"] = 56321, ["name"] = "Saving Corin", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56304, 56321, 56422 }, ["description"] = "My father is being tortured by that naga! <name>, I need you to help me save him. We can't let his spirit be a slave to the naga. Hurry, if we don't act now he will end up like the rest of them!", ["objectivesText"] = "Defeat Shadowcaster Vixtris .", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154601, ["x"] = 0.802, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.802, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 948, ["name"] = "Kelya Moonfall", ["orderIndex"] = 1, ["flags"] = 0 } } },
[56322] = { ["id"] = 56322, ["name"] = "Contained Alemental", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 7, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 56322 }, ["description"] = "<As the brew is returned to its natural, dormant form, a strange keg appears. Perhaps Brewmaster Tsing knows more about such a strange occurrence.>", ["objectivesText"] = "Talk to Brewmaster Tsing in the Brewfest grounds.", ["rewardGold"] = 234000, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 73913, ["x"] = 0.554, ["y"] = 0.38 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.38 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Epic" },
[56324] = { ["id"] = 56324, ["name"] = "Your First Charge Ain't Free!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56324 }, ["description"] = "You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? < Flux spits behind her.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. Deal? You ain't gettin' any other offers.", ["objectivesText"] = "Pay Flux 's access fee, then use the Charging Station to charge an Empty Energy Cell. Progress: You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? < Flux spits over her shoulder.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. You ain't gettin' any other offers.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154534, ["x"] = 0.612, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard" },
[56325] = { ["id"] = 56325, ["name"] = "Changing Tides", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["series"] = { 55574, 56741 }, ["description"] = "We are out of time. We must gain control the Tidestone of Golganneth and the Javelin is our best shot at piercing the barrier surrounding it. The guardian is formidable, but must be defeated if we are to take the fight to Azshara. What forces we have will be arrayed below, just outside their encampment. I would trust you with the Javelin of Suramar, <name>. We will need your strength in the coming battle.", ["objectivesText"] = "Assault the naga camp and seize control of the Tidestone of Golganneth. Progress: If we do not take the Tidestone, we are finished.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 152813, 175246 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153193, ["x"] = 0.500857, ["y"] = 0.326 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 46, ["flags"] = 0 } } },
[56326] = { ["id"] = 56326, ["name"] = "Ravenous Rescue", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56326 }, ["description"] = "A conspiracy of ravens is preying on citizens of Rustbolt! It's most unacceptable! Prince Erazmin has asked me to rescue as many citizens as I can, but I could use your help. I've tracked the ravens to this hill. We blast the ravens out of the sky, and you rescue the mechagnomes. Use my marker gun if you need help bringing the ravens down.", ["objectivesText"] = "Rescue 8 injured mechagnomes . Progress: Let's get to it!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154568, ["x"] = 0.622, ["y"] = 0.768 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154568, ["x"] = 0.622, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56327] = { ["id"] = 56327, ["name"] = "Chopped Bots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56327 }, ["description"] = "Chopping up bots is my business. Any bots you bring to my scrapper will be broken up into useful parts. It's a win for both of us! Use the Bot-Energizer to bring me dead bots, and we'll break them into spare parts .", ["objectivesText"] = "12 Re-animated bots delivered to Bolten Springspark . Progress: Re-animate dead bots and bring them to me!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150086, ["x"] = 0.63, ["y"] = 0.392 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150086, ["x"] = 0.63, ["y"] = 0.392 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.392 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56328] = { ["id"] = 56328, ["name"] = "Do Not Drink", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56328 }, ["description"] = "These troggs watch everything we do. They see us pouring oil into various machines, so now they're stealing the oil and drinking it. I think they believe it's going to turn them into machines! We need that oil back, before they drink it all!", ["objectivesText"] = "Recover 12 containers of Stolen Oil . Progress: Get that oil back quick!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 4536, 64588, 64598, 64607, 64616, 64622, 64639, 157012, 166846, 166970, 166971, 168608, 181802, 183744, 184843, 211279, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153750, ["x"] = 0.59, ["y"] = 0.315 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153750, ["x"] = 0.59, ["y"] = 0.315 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.315 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56334] = { ["id"] = 56334, ["name"] = "Bots Gone Wild", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56334 }, ["description"] = "It's loose up there! I told them not to do it, but they didn't listen. Now it's gone out of control and killed everyone up there. It's an experimental Whirlbot. They never should have built it! You need to stop it before it comes down here looking for more victims! Kill the Whirling Zap-O-Matic .", ["objectivesText"] = "Whirling Zap-O-Matic slain Progress: You need to stop it.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154655, ["x"] = 0.6, ["y"] = 0.695 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154655, ["x"] = 0.6, ["y"] = 0.695 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.695 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[56335] = { ["id"] = 56335, ["name"] = "Wanna Charge? Gotta Pay!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56335 }, ["description"] = "You lookin' to charge some energy cells off of our tower of power? I ain't surprised - everyone is. And everyone PAYS. You got that or I got ta say it again? < Flux spits behind her.> I can tell you're a first-timer. Bondo's got a special deal for you flashfoots. Small access fee, one charge only. Deal? You ain't gettin' any other offers.", ["objectivesText"] = "Pay Flux 's access fee, then use the Charging Station to charge an Empty Energy Cell . Progress: You lookin' to charge some energy cells off our tower of power? Save your sob stories. Everyone pays. < Flux spits over her shoulder.> No exceptions.", ["rewardItems"] = { 166846, 166970, 166971, 169868 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154534, ["x"] = 0.612, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard" },
[56336] = { ["id"] = 56336, ["name"] = "Uncovering the Artifact Fragments", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 56336 }, ["description"] = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran . Go out and kill any you find and bring at least fifty to Ecilam the Mage near the campfire in Stormshield Stronghold.", ["objectivesText"] = "Ecilam in Stormshield Stronghold wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments . Progress: Are those Artifact Fragments , I see?", ["rewardGold"] = 341600, ["starts"] = { { ["mapID"] = 588, ["npcID"] = 82966, ["x"] = 0.446, ["y"] = 0.745 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 82966, ["x"] = 0.446, ["y"] = 0.745 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.446, ["y"] = 0.745 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "pvp" },
[56337] = { ["id"] = 56337, ["name"] = "Uncovering the Artifact Fragments", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 56337 }, ["description"] = "The Artifact Fragments seem to come from any creature we've found in the outskirts of Ashran . Go out and kill any you find and bring at least fifty Artifact Fragments to Fura the Mage in Warspear Outpost.", ["objectivesText"] = "Fura in Warspear Outpost wants you to go kill creatures in the outskirts of Ashran outside of the main road and bring back 50 Artifact Fragments . Progress: Are those Artifact Fragments , I see?", ["rewardGold"] = 341600, ["starts"] = { { ["mapID"] = 588, ["npcID"] = 83995, ["x"] = 0.449, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 83995, ["x"] = 0.449, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.449, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "pvp" },
[56338] = { ["id"] = 56338, ["name"] = "Volrath Must Die", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 56338 }, ["description"] = "The Horde are getting in our way of completing our mission here in Ashran . Their leader is High Warlord Volrath. He must be put down. Push forth through the center road, enter Warspear and slay Volrath.", ["objectivesText"] = "Slay High Warlord Volrath found in the Horde base Warspear within Ashran .", ["starts"] = { { ["mapID"] = 588, ["npcID"] = 84173, ["x"] = 0.445, ["y"] = 0.74 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 84173, ["x"] = 0.445, ["y"] = 0.74 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.445, ["y"] = 0.74 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "pvp" },
[56339] = { ["id"] = 56339, ["name"] = "Tremblade Must Die", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8485, ["mapID"] = 588, ["storyline"] = { 56339 }, ["description"] = "This battle in Ashran has waged on long enough. It appears they're being led by Grand Marshal Tremblade. If she falls, the Alliance will crumble. Push forward through the center road, make your way into their keep and take down Tremblade. For the Horde!", ["objectivesText"] = "Slay Grand Marshal Tremblade found in the Alliance base Stormshield Keep within Ashran .", ["starts"] = { { ["mapID"] = 588, ["npcID"] = 84473, ["x"] = 0.45, ["y"] = 0.278 } }, ["ends"] = { { ["mapID"] = 588, ["npcID"] = 84473, ["x"] = 0.45, ["y"] = 0.278 } }, ["coords"] = { ["mapID"] = 588, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.278 }, ["mapCandidates"] = { ["npc"] = { 588 }, ["zone"] = { 8485 } }, ["questType"] = "pvp" },
[56341] = { ["id"] = 56341, ["name"] = "Direbrew Cog", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 7, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 56341 }, ["description"] = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines. Perhaps your Dark Iron allies would be interested in hearing of your victory.>", ["objectivesText"] = "Talk to Verra Fireblood in the Brewfest grounds.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 152941, ["x"] = 0.562, ["y"] = 0.376 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.376 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
[56346] = { ["id"] = 56346, ["name"] = "Ancient Technology", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "<Given the experience you've had with the naga and the power they wield, you wonder if using their own power against them might not garner you a powerful advantage. Perhaps Instructor Ulooaka back at Mezzamere could help you repair this core and put it to use against the naga invasion.>", ["objectivesText"] = "Bring the Broken Power Core to Instructor Ulooaka in Mezzamere. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 169320 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56347] = { ["id"] = 56347, ["name"] = "An Abyssal Opportunity", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "I believe, <name>, we can use this thing to make our armor stronger. By redirecting its power, we can take the strength of our crafts to a new level. But we're getting ahead of ourselves. The first thing we need to do is repair this device. It'll require some powerful materials to fix it, and those are usually carried by the stronger creatures of this region. However, Artisan Okata is great at collecting materials like the ones we need. I'd check with him to see what he's got.", ["objectivesText"] = "Acquire 15 Abyssal Shards from Artisan Okata. Progress: How goes the hunt for the materials?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169326, 171247 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 1, ["flags"] = 0 } } },
[56348] = { ["id"] = 56348, ["name"] = "The Eternal Palace: We Can Make It Stronger...", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "Now that it's functioning, it occurred to me while repairing it that it has the capability to output even more energy. Of course that will require stronger materials to upgrade and the only place I can think of is in the Eternal Palace. Azshara's army and even herself carry items of extraordinary power. If you could bring some of those back, I could at the very least test my theory and see if it's viable.", ["objectivesText"] = "Collect 20 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: How goes the search for those items?", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 169329 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 2, ["flags"] = 0 } } },
[56349] = { ["id"] = 56349, ["name"] = "The Eternal Palace: Pushing the Limits", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56346, 56347, 56348, 56349 }, ["description"] = "Now that we know how to increase the potency of this tool, I think we can push its capabilities even further. Bring me back more of those ornaments. LOTS of them. Let's see just how far we can make this go.", ["objectivesText"] = "Collect 200 Eternal Ornaments from the most powerful creatures of the Eternal Palace. Progress: Any luck on retrieving more of those ornaments?", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 169329 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154257, ["x"] = 0.38, ["y"] = 0.53 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.38, ["y"] = 0.53 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 955, ["name"] = "8.2 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56350] = { ["id"] = 56350, ["name"] = "Scouting the Palace", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "We cannot hide here forever, <name>. Azshara must be dealt with. It would be an act of folly to assault her palace without knowing what defenses she has in place. I dispatched a scouting team while you were gone, but they have not reported back. I'm getting concerned, <name>. Let me know when you're ready and I'll perform a ritual to see what has happened to our scouts.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore to observe the scouting party. Progress: Are you ready?", ["rewardXP"] = 10225, ["rewardItems"] = { 169482, 169483, 169485 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 19, ["flags"] = 0 } } },
