[56355] = { ["id"] = 56355, ["name"] = "Battle Tested", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56355 }, ["description"] = "A weapon like this could really turn the tide against King Mechagons Troops. Let's go see how their gear matches up against our new toy. Take out King Mechagon 's Sentries wherever you can find them", ["objectivesText"] = "Eliminate 10 Upgraded, Anodized, or Corroded Sentry wherever you find them. Progress: Go kill something!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 151006, ["x"] = 0.698, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151006, ["x"] = 0.698, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.698, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56356] = { ["id"] = 56356, ["name"] = "The Eternal Palace: Queen's Gambit", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55469, 55482, 55485, 55486, 55488, 55489, 55490, 55799, 56356 }, ["description"] = "The way is clear. The palace awaits, <name>. Within the Vainglorious holds court with an old god. Defeating her will be no small feat. Make no mistake, Azshara is one of the most powerful sorceresses alive. We cannot underestimate her power or her planning, for she has had thousands of years to prepare for us. Nevertheless, she must be defeated. We are ready when you are. Shall we finally accept her invitation?", ["objectivesText"] = "Defeat Queen Azshara in the Eternal Palace . Progress: We cannot rest easy knowing that she still holds power here.", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153251, ["x"] = 0.505, ["y"] = 0.241 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153251, ["x"] = 0.505, ["y"] = 0.241 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.505, ["y"] = 0.241 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 938, ["name"] = "Turning the Tide", ["orderIndex"] = 8, ["flags"] = 0 } } },
[56358] = { ["id"] = 56358, ["name"] = "The Eternal Palace: Queen's Gambit", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["description"] = "We have opened the way to the palace. We must end this. Queen Azshara is the most powerful sorceress in existence. She mastered magics thousands of years before our archmagi were even born. Still, we must prevail. If not, she and her dark patron will remake all of Azeroth to their desires. Champion, we must defeat Azshara. Are you with us?", ["objectivesText"] = "Defeat Queen Azshara in the Eternal Palace . Progress: Such power, brought to ruin....", ["rewardGold"] = 1239200, ["rewardXP"] = 13630, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153253, ["x"] = 0.504, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153253, ["x"] = 0.504, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "raid", ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 12, ["flags"] = 0 } } },
