[56410] = { ["id"] = 56410, ["name"] = "Discs of Norgannon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56410 }, ["description"] = "King Mechagon unit in possession of Norgannon disk. Data is corrupted, possession of such data is dangerous. Please aid in the recovery of Corrupted Disk Fragments that have been discarded via Mechagon waste systems. Deliver recovered Corrupted Disc Fragment to Data Analyzer R33-DR for purging.", ["objectivesText"] = "Recover Corrupted Disc Fragment Progress: Recover Corrupted Disc Fragment.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 168215, 168217, 168258, 168264, 168266, 168395, 168496, 168631, 168906, 168907, 168951, 169169, 169474, 169591, 169593, 169594, 169595, 169610, 169690, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 154982, ["x"] = 0.718, ["y"] = 0.365 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 154122, ["x"] = 0.634, ["y"] = 0.568 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.365 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 971, ["name"] = "Visit from Archivist Bitbyte", ["orderIndex"] = 0, ["flags"] = 0 } } },
