[56459] = { ["id"] = 56459, ["name"] = "Half-Digested Deepcoral Pod", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56459 }, ["description"] = "<Upon inspection of this oddly-aggressive fathom ray, you find several halfway-digested pods. You've seen similar pods on the coral of this region, it appears to be one of the foods of the fathom rays. This may explain their strange ability to fly. Finder Palta might know more.>", ["objectivesText"] = "Show the Half-Digested Deepcoral Pod to Finder Palta in Newhome in Nazjatar . Provided item:", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["rewardItems"] = { 169644 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153514, ["x"] = 0.492, ["y"] = 0.62 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.62 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 169644 } },
