[56469] = { ["id"] = 56469, ["name"] = "Pirates? I Hate Those Guys!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56469 }, ["description"] = "<An old pirate hat . Seems out of place on this island, perhaps Reno Jackson will know what to make of it>", ["objectivesText"] = "Deliver the old pirate hat to Reno Jackson . Provided item:", ["rewardGold"] = 89550, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 168223, 168234, 168236, 168256, 169864 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152502, ["x"] = 0.705, ["y"] = 0.312 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.312 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["startItems"] = { 169864 } },
[56470] = { ["id"] = 56470, ["name"] = "Give A Dog A Bone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 56470 }, ["description"] = "Louison lent me Dog Bone to help uncover some marrowgrubs, but I'm busy here with the stoves. Could you be a dear and go hunting for me? Dog Bone loves to pounce on the smaller nibblers and makes a lot of noise doing it. That'll scare the larger marrowgrubs into making a run for it. That's when you'll need to make your move. Just use this bone to lure Dog Bone near the nibblers. Oh, and don't forget to harvest the flesh from the marrowgrubs! That's what you're really after.", ["objectivesText"] = "Collect 12 Marrowgrub Flesh from Giant Marrowgrubs. Progress: Did you collect the meat?", ["rewardXP"] = 8165, ["rewardItems"] = { 174270, 181809, 183744, 183796, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161678, ["x"] = 0.552, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[56471] = { ["id"] = 56471, ["name"] = "Unprofitable Ventures", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56471 }, ["description"] = "This land is already a monumental disaster, but it could get worse! The Venture Company is here, and will exploit this land for every ounce of profit they can make. We must make their venture here unprofitable, so they will leave. Destroy the three expensive security units with them, and they may leave for more profitable ventures.", ["objectivesText"] = "Destroy Pummeller Red , Pummeller Orange , and Pummeller Grey", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155187, ["x"] = 0.72, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155187, ["x"] = 0.72, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 974, ["name"] = "Visit from Tortollans", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56472] = { ["id"] = 56472, ["name"] = "The Uldum Accord", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472 }, ["description"] = "You seek assistance defending the Forge of Origination? It would seem that our goals align. The Halls of Origination are but a small portion of the forge's true scope. Any threat to Uldum would be a potential threat to the forge, and Uldum has found itself with many new enemies of late. We were about to convene the High Council when these Wastewanders arrived unannounced. Perhaps you could join us in learning about these threats?", ["objectivesText"] = "Learn about the threats facing Uldum in Ramkahen. Progress: We should learn all we can about the threats facing Uldum before we proceed.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 174484 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 950, ["name"] = "The Forge of Origination", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 8, ["flags"] = 0 } } },
[56473] = { ["id"] = 56473, ["name"] = "Envenomed Spider Fang", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 56473 }, ["description"] = "Even wary bees have been known to fall prey to these enormous spiders. They lie in wait near flowerbeds and ambush them while they collect their harvest. Thanks to you, they have one less spider to worry about. The Hivemother will be interested in this item.", ["objectivesText"] = "Take the Envenomed Spider Fang to the Honeyback Hivemother for a reward. Provided item:", ["rewardItems"] = { 169656, 172145 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 153365, ["x"] = 0.626667, ["y"] = 0.263333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.263333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 169656 } },
[56474] = { ["id"] = 56474, ["name"] = "Hivekiller Stinger", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 56474 }, ["description"] = "Wasps are a bee's natural enemy, and none are more deadly than this highly specialized killer. It will terrorize the hive no longer, thanks to you. The Hivemother will be interested in this item.", ["objectivesText"] = "Take the Hivekiller Stinger to the Honeyback Hivemother for a reward. Provided item:", ["rewardItems"] = { 169655, 172144 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 153365, ["x"] = 0.626667, ["y"] = 0.263333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.263333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 169655 } },
[56475] = { ["id"] = 56475, ["name"] = "Spiral Yeti Horn", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 56475 }, ["description"] = "All manner of creatures are attracted to the sweet smell of fresh honey, but relatively few are willing to withstand the painful and often deadly stings of the largest of bees. This yeti, however, has been a persistent thorn in the hive's side, until now. The Hivemother will be interested in this item.", ["objectivesText"] = "Take the Spiral Yeti Horn to the Honeyback Hivemother for a reward. Provided item:", ["rewardItems"] = { 169654, 172143 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 153365, ["x"] = 0.626667, ["y"] = 0.263333 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.626667, ["y"] = 0.263333 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 169654 } },
[56489] = { ["id"] = 56489, ["name"] = "Restless Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56489 }, ["series"] = { 56490, 56491 }, ["description"] = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there. We have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", ["objectivesText"] = "Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 43832, 43833, 43834, 43835 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 147645, ["x"] = 0.503, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 150987, ["x"] = 0.432, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 23, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[56490] = { ["id"] = 56490, ["name"] = "Restless Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 56490 }, ["series"] = { 56489, 56491 }, ["description"] = "Rumors are spreading of some new evil business happening in Stratholme of all places. We need you to head to Eastern Plaguelands and put an end to any new evil threats that may have taken residence there. We have received contact from a member of the Argent Crusade who has offered their assistance to get you into Stratholme and find the source of this new evil.", ["objectivesText"] = "Find Sean Wilkers outside of the service entrance of Stratholme in Eastern Plaguelands.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 43832, 43833, 43834, 43835 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 147641, ["x"] = 0.562, ["y"] = 0.31 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 150987, ["x"] = 0.432, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.31 }, ["mapCandidates"] = { ["npc"] = { 23, 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[56491] = { ["id"] = 56491, ["name"] = "Tiny Terrors of Stratholme", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 56491 }, ["series"] = { 56489, 56490 }, ["description"] = "Scourge activity inside of Stratholme has increased dramatically in the recent days. The air is thick with the stink of necromancy, and there are screams and shrieks coming from within these walls that will send chills down your spine for weeks to come. I haven't ventured in there yet myself, but there is definitely some new evil stirring from within. I have the keys to this entrance, and can bring you in there to see for yourself. Let me know when you are ready.", ["objectivesText"] = "Defeat Blackmane . Progress: I can open these gates and bring us in, but it will be up to you to get out safely.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 122457, 170102 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 150987, ["x"] = 0.432, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 150987, ["x"] = 0.432, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[56492] = { ["id"] = 56492, ["name"] = "Pet Battle Challenge: Stratholme", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 139, ["mapID"] = 23, ["storyline"] = { 56492 }, ["description"] = "The evil presence has returned to Stratholme yet again. That's the problem with necromancy and scourge, they keep reanimating themselves and coming right back! I can bring us in there again, but I suspect all of those evil forces have returned. Are you sure you want to go back in there? That place gives me the creeps. If you really want to head back in there, I will let you back in.", ["objectivesText"] = "Defeat Blackmane. Progress: I can open this service entrance, but it is up to you to safely get out of Stratholme.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169665 }, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 150987, ["x"] = 0.432, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 150987, ["x"] = 0.432, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.432, ["y"] = 0.198 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 139 } }, ["questType"] = "standard" },
[56493] = { ["id"] = 56493, ["name"] = "A Direct Approach", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56493 }, ["description"] = "Maokka has such a gentle heart. He is so good with the little ones, always playing games and telling stories. We do however really dislike these Venture Co. individuals, so I suggest a more direct approach. Try killing them all.", ["objectivesText"] = "Eliminate 12 Venture Co. employees", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155188, ["x"] = 0.72, ["y"] = 0.372 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155188, ["x"] = 0.72, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56494] = { ["id"] = 56494, ["name"] = "The Eve of Battle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "<name>. The time has come. We may have defeated Azshara, but we still have to deal with Sylvanas. Though our position is not ideal, we have mobilized our available forces and stand ready to finish this war. King Wrynn wanted me to brief you on the situation before we join him. There have been some... interesting developments.", ["objectivesText"] = "Speak with Mathias Shaw.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 1, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56495] = { ["id"] = 56495, ["name"] = "They Move Against Us", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The Dark Lady requests your presence in Orgrimmar, <name>. It seems the rats have finally come out of hiding. Which will make it all the easier to exterminate them. Do not delay. We have waited for this moment long enough.", ["objectivesText"] = "Meet with Sylvanas in Orgrimmar. Progress: The pathetic fools.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 135691, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56496] = { ["id"] = 56496, ["name"] = "The Eve of Battle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1165, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "<name>, we must speak of the Horde... and the warchief. The war has proven costly, and the battle against Azshara drained what little resources we had left. The Horde is divided once more and the Alliance fares little better than we do. Sylvanas is now in a position to destroy everyone she considers an enemy. That means us, as well. I had hoped that my old friend would see reason, but now... High Overlord Saurfang is rallying those of us who remain--including some unlikely allies.", ["objectivesText"] = "Speak with Lor'themar.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.96 }, ["mapCandidates"] = { ["npc"] = { 1, 1165 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 9, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 9, ["flags"] = 0 } } },
