[56501] = { ["id"] = 56501, ["name"] = "Taking The Air Out", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56501 }, ["description"] = "<This box of rockets could just be used to take out the Venture Co. Balloons. That would really motivate Venture Co. to go somewhere else.>", ["objectivesText"] = "Eliminate 5 Venture Co. Transports", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 168492, 169681, 169682 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155188, ["x"] = 0.72, ["y"] = 0.372 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.372 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["startItems"] = { 169682 } },
[56504] = { ["id"] = 56504, ["name"] = "Wrathion's Journal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 56185, 56186, 56187, 56188, 56189, 56190, 56267, 56504 }, ["series"] = { 56190 }, ["description"] = "The whispers ceased as soon as I drank the potion. Thank you, $p. Still, it is gravely concerning that N'Zoth's influence could reach me even within the Chamber of Heart. If Wrathion has found a way to resist the power of the Old Gods, then we can use it to reinforce the Chamber's defenses. Perhaps MOTHER can glean more information from Wrathion's journal .", ["objectivesText"] = "Deliver Wrathion's incomplete journal to MOTHER . Progress: Awaiting information interface.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 170493 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 947, ["name"] = "On the Trail of the Black Prince", ["orderIndex"] = 7, ["flags"] = 0 } } },
