[56515] = { ["id"] = 56515, ["name"] = "Vinyl: Gnomeregan Forever", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56515 }, ["description"] = "<This pressed vinyl is surprisingly still intact. Its label says it contains the recording of a song called \"Gnomeregan Forever.\" You should be able to install this vinyl into the gramophone back in Rustbolt.>", ["objectivesText"] = "Install the vinyl into the Rustbolt Gramophone . Provided item:", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 169688 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151201, ["x"] = 0.702, ["y"] = 0.305 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.305 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["startItems"] = { 169688 } },
