[56523] = { ["id"] = 56523, ["name"] = "My Chickens are Not for Eating!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56523 }, ["description"] = "If you've spent any time with that arrogant nitwit, Overspark, you know why I'm here. To silence his boasting and finally prove that my inventions are better! I've released countless mechanical chickens across this island to analyze the technology here, adopt it, and evolve their own circuitry. One of them will become my ultimate battle chicken! But those idiot troggs think my chickens are edible and keep bashing them. Protect them, so my techno-evolutionary experiment can run its course.", ["objectivesText"] = "Collect 20 Mechanical Giblets and repair the OOX-Bomber/MG. Progress: Imagine being so dumb that you try to eat a mechanical chicken...", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 168492, 169381, 169695, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155254, ["x"] = 0.728, ["y"] = 0.378 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155254, ["x"] = 0.728, ["y"] = 0.378 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.728, ["y"] = 0.378 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 979, ["name"] = "Visit from Oglethorpe", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56532] = { ["id"] = 56532, ["name"] = "Nuke 'Em Norbit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56532 }, ["description"] = "These motospiders continue to multiply unchecked. If we don't slow them down they'll overrun Rustbolt soon. I've modified Norbit here with adequate firepower to take the spiders head on! Would you pilot Norbit and destroy the Reinforced Sparkweave Eggs ?", ["objectivesText"] = "Eliminate the 5 Reinforced Sparkweave Eggs Progress: Norbit needs a skilled pilot!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 153701, ["x"] = 0.81, ["y"] = 0.188 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 153701, ["x"] = 0.81, ["y"] = 0.188 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.81, ["y"] = 0.188 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
