[56572] = { ["id"] = 56572, ["name"] = "Toys Like Us", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56572 }, ["description"] = "I must share the wonders of this place with all of Azeroth in a way that will entertain young and old alike. I will use the technology here to create a new line of toys unlike anything seen before! My Quasi-Faceted scanner can help construct perfect replicas of things here on the island. I just need a helpful individual such as yourself to scan a few things around this area.", ["objectivesText"] = "Quasi-Facet scan creatures in Mechagon", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 166970, 166971, 169816, 169838, 169848, 169850, 169876, 246697 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 155450, ["x"] = 0.702, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 155450, ["x"] = 0.702, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 981, ["name"] = "Visit from Jepetto Joybuzz", ["orderIndex"] = 0, ["flags"] = 0 } } },
[56573] = { ["id"] = 56573, ["name"] = "Certified Pre-Owned", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56573 }, ["description"] = "First, let me say that you will ALWAYS be our favorite test subject. But our experiments require far more sacrifice than a single test subject can offer. And, from time to time, some of those test subjects require new limbs. My dear brother and I have a nascent concept for expanding the average lifespan of mechanical appendages. But we've run out of components to experiment on. Salvage some appendages from the heap outside town so we can continue our experiments.", ["objectivesText"] = "Collect 15 Salvaged Mechagnome Appendages . Progress: Don't worry about any malfunctioning or missing parts. Gill will help us repair whatever you find.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166970, 169807, 169868 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150631, ["x"] = 0.708, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56574] = { ["id"] = 56574, ["name"] = "Reflections in Amber", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "<A viscous dark ooze drips from this large chunk of amber. Attempting to wipe it off is futile, as the ooze is seemingly created by the amber itself. As you hold it, unintelligible whispers fill the back of your mind. The Shado-Pan will surely want to examine it.>", ["objectivesText"] = "Bring the Ooze-Covered Amber to the Shado-Pan at the Serpent's Spine.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 169888 }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 155487, ["x"] = 0.1316, ["y"] = 0.7916 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.1316, ["y"] = 0.7916 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 169888 } },
[56575] = { ["id"] = 56575, ["name"] = "Once More Into Kor'vess", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "You found this on a member of the swarm? It seeps with corruption... and with power. We could be faced with a serious threat if the rest of the mantid's amber is similarly corrupted. Far to the west in the Dread Wastes lies Kor'vess, a large kypari tree that provides the swarm with most of its amber. From there, we can determine just how much of their stores have been infused with the energy of the Old Gods. I will meet you closer to the tree.", ["objectivesText"] = "Investigate Kor'vess.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 155487, ["x"] = 0.1316, ["y"] = 0.7916 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.1316, ["y"] = 0.7916 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 1, ["flags"] = 0 } } },
[56576] = { ["id"] = 56576, ["name"] = "Aqir Extermination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "There are too many of these things flyin' around for us to make a clean getaway. We're liable to get swarmed the second we start up them plane engines! These bugs are going straight back into the ground... one way or another. May as well expedite the process, know what I mean?", ["objectivesText"] = "Kill 10 Aqir Impalers .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 10, ["flags"] = 0 } } },
[56577] = { ["id"] = 56577, ["name"] = "Crippling the Hive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "The mantid here are working feverishly to harvest amber from the tree. Perhaps killing a pawful of them will slow their efforts.", ["objectivesText"] = "Kill 12 Kor'thik mantid in Kor'vess.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 2, ["flags"] = 0 } } },
[56578] = { ["id"] = 56578, ["name"] = "Rotten at the Roots", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "Underneath Kypari Kor is a large chamber where the mantid tend to the tree. That must be where the source of the corruption lies. We need to get into that chamber and stop them. N'Zoth must not be allowed to empower the swarm.", ["objectivesText"] = "Stop the source of the corruption within the Morrowchamber.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["ends"] = { { ["mapID"] = 422, ["npcID"] = 155582, ["x"] = 0.454, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 422, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 422 }, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56580] = { ["id"] = 56580, ["name"] = "Amber Secrets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "The Morrowchamber houses a small section of the Zara'thik, mantid under immediate directive of the new empress. Some of them may have been given pieces of amber like the one you found. The Shado-Pan would be interested in any extra pieces we can acquire.", ["objectivesText"] = "Collect 8 pieces of Corrupted Amber. Progress: We always feared this day would come...", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 169866 }, ["starts"] = { { ["mapID"] = 422, ["npcID"] = 155582, ["x"] = 0.454, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 422, ["npcID"] = 155582, ["x"] = 0.454, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 422, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 422 }, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 4, ["flags"] = 0 } } },
[56616] = { ["id"] = 56616, ["name"] = "Old Faces, New Problems", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "One of N'Zoth's minions appears to have taken note of our presence. Shall we pay them a visit?", ["objectivesText"] = "Kill Watcher Vl'thax . Progress: Is it done?", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 422, ["npcID"] = 155582, ["x"] = 0.454, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 422, ["npcID"] = 155582, ["x"] = 0.454, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 422, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 422 }, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 5, ["flags"] = 0 } } },
[56617] = { ["id"] = 56617, ["name"] = "A Unified Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "It seemed as though the mantid had been producing the corrupted amber for some time before our... intervention. It stands to reason that they are keeping a stockpile of it somewhere. The Shado-Pan's scouts have been reporting an increased presence of the swarm's warriors in Klaxxi'vess. I would wager that they are guarding the corrupted amber . Meet me there. If we have a chance to destroy that amber, then we need to take it.", ["objectivesText"] = "Infiltrate Klaxxi'vess.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 422, ["npcID"] = 155582, ["x"] = 0.454, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 422, ["npcID"] = 155707, ["x"] = 0.548, ["y"] = 0.345 } }, ["coords"] = { ["mapID"] = 422, ["source"] = "quest_giver", ["x"] = 0.454, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 422 }, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 422, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 6, ["flags"] = 0 } } },
[56621] = { ["id"] = 56621, ["name"] = "Real Ultimate Power", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56621 }, ["description"] = "When I say that power is life, I'm not speaking figuratively, my dear test subject. Properly harnessed, power can create life itself--or at least a close enough facsimile for our purposes. There is a massive reserve of discarded technology lurking deep in the mucky depths of the Outflow. As usual, Mechagon 's trash is our treasure. I've finally perfected my device that will animate the sludge to bring that technology up to the surface for you. All you have to do is pop 'em and grab the tech!", ["objectivesText"] = "Collect 15 discarded technologies from techno-animated sludge. Progress: Please thoroughly document any adverse side effects you experience while using the Spark-7143 .", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166970, 169824, 169839 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150630, ["x"] = 0.721, ["y"] = 0.356 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.721, ["y"] = 0.356 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 } },
[56622] = { ["id"] = 56622, ["name"] = "Ashran Dominance", ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6941, ["storyline"] = { 56622 }, ["description"] = "The Alliance refuse to back down in Ashran . Teach them that the Horde will not stand aside while they plunder the power of the ancient ogre empire to use for their own schemes.", ["objectivesText"] = "Defeat the Alliance at all event locations in Ashran and kill Grand Marshal Tremblade .", ["rewardXP"] = 200, ["rewardItems"] = { 126924 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6941 } }, ["questType"] = "standard" },
[56623] = { ["id"] = 56623, ["name"] = "Ashran Dominance", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 6941, ["storyline"] = { 56623 }, ["description"] = "As we feared the Horde are trying to consolidate their position here on the island by looting it, just like we feared. Get out there and show them the Alliance won't put up with their aggression.", ["objectivesText"] = "Defeat the Horde at all event locations in Ashran and kill High Warlord Volrath .", ["rewardXP"] = 200, ["rewardItems"] = { 126924 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 6941 } }, ["questType"] = "standard" },
[56640] = { ["id"] = 56640, ["name"] = "Fortunate Souls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "You and I survived the attack and have thus far evaded capture by the enemy. Not all were as fortunate. There are many of our allies now under the control of the naga. We must free them before they are killed or suffer an even worse fate.", ["objectivesText"] = "Rescue 7 captive soldiers in Spears of Azshara. Progress: We are outnumbered, but we are not outclassed.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56641] = { ["id"] = 56641, ["name"] = "Disruption of Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "The naga are tapping into some latent power, infusing the energy into some manner of device. I do not know what purpose they have for this power, but it is surely in our interest to destroy the objects before they can be used against us.", ["objectivesText"] = "Destroy 5 Ley Line Accumulators in Spears of Azshara. Progress: Can you feel the magic in this place?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 4, ["flags"] = 0 } } },
[56642] = { ["id"] = 56642, ["name"] = "Dark Tides", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "A tidemistress leads some nefarious ritual above a pool. Do not look in the pool when we approach it, or you will be rewarded with a view of our drowned allies. We must put a stop to this ritual. The tidemistress is key.", ["objectivesText"] = "Slay Tidemistress Ethendriss . Progress: We must not underestimate this tidemistress.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 64594, 64604, 64613, 64620, 64625, 64629, 64632, 64634, 157013, 163866, 163867, 163868, 163869, 163871, 163872, 163874, 163876, 163878, 163880, 163881, 163882, 163885, 163886, 163887, 163890, 163892, 163894, 163895, 166336, 170274, 170275 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 5, ["flags"] = 0 } } },
[56644] = { ["id"] = 56644, ["name"] = "Up Against It", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 54969, 54972, 55095, 55175, 56350, 56640, 56641, 56642, 56643, 56644 }, ["description"] = "We must move quickly if we are to find safety for our people. This cave is barely defensible, and much of our army is in an even more precarious position. Let's search deeper.", ["objectivesText"] = "Move deeper into Nazjatar with Jaina and Genn.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 29333, 29334, 29335, 29336, 52593, 52617, 52640, 52644, 52673, 62210, 62211, 62212, 62213, 131283, 131655, 140255, 142054, 211279, 237812 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 151000, ["x"] = 0.5276, ["y"] = 0.4764 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 949, ["questLineOrder"] = 21 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 949, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 7, ["flags"] = 0 } } },
[56645] = { ["id"] = 56645, ["name"] = "Heart of the Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 6138, ["mapID"] = 422, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "We need to know what we're up against. Before we return to the Serpent's Spine, we should take the opportunity to scout the swarm. I will fly us over the Heart of Fear. We should be able to survey Empress Shek'zara's forces from above. Then we can determine the extent to which N'Zoth has bolstered their ranks with his own.", ["objectivesText"] = "Fly with Taoshi on the Shado-Pan Kite .", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 422, ["npcID"] = 155707, ["x"] = 0.548, ["y"] = 0.345 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 155487, ["x"] = 0.1316, ["y"] = 0.7916 } }, ["coords"] = { ["mapID"] = 422, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.345 }, ["mapCandidates"] = { ["npc"] = { 422, 1530 }, ["zone"] = { 6138 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 390, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 7, ["flags"] = 0 } } },
[56647] = { ["id"] = 56647, ["name"] = "The Mantid Threat", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 56574, 56575, 56577, 56578, 56580, 56616, 56617, 56645, 56647 }, ["description"] = "The mantid have been corrupting their kypari trees to imbue their amber with power from N'Zoth. The swarm is enough of a menace on its own. N'Zoth could transform them into something even more dire. The Shado-Pan need to hear about this. I suggest you bring this information to your other allies as well.", ["objectivesText"] = "Return to Stormspeaker Qian at the Silent Sanctuary.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 155487, ["x"] = 0.1316, ["y"] = 0.7916 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.1316, ["y"] = 0.7916 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["questLines"] = { { ["id"] = 1009, ["name"] = "The Mantid Threat", ["orderIndex"] = 8, ["flags"] = 0 } } },
[56648] = { ["id"] = 56648, ["name"] = "Call to Arms: Nazjatar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1161, ["storyline"] = { 56648 }, ["description"] = "Our mission in Nazjatar is being compromised by the Horde incursion. Get into Nazjatar and take out as many as you can.", ["objectivesText"] = "Slay Horde within Nazjatar .", ["rewardItems"] = { 167744, 168802, 169614 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143559, ["x"] = 0.562, ["y"] = 0.26 }, { ["mapID"] = 1355, ["npcID"] = 154640, ["x"] = 0.38, ["y"] = 0.554 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 143559, ["x"] = 0.562, ["y"] = 0.26 }, { ["mapID"] = 1355, ["npcID"] = 154640, ["x"] = 0.38, ["y"] = 0.554 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161, 1355 }, ["zone"] = { 10052 } }, ["questType"] = "pvp" },
