[56714] = { ["id"] = 56714, ["name"] = "Contained Alemental", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 56714 }, ["description"] = "<As the brew is returned to its natural, dormant form, a strange keg appears. Perhaps Brewmaster Tao knows more about such a strange occurrence.>", ["objectivesText"] = "Talk to Brewmaster Tao in the Brewfest grounds.", ["rewardGold"] = 99850, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 73914, ["x"] = 0.412, ["y"] = 0.175 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.175 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[56715] = { ["id"] = 56715, ["name"] = "Hozen Totem", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 56715 }, ["description"] = "<The hozen have been successfully chased away, and Brewfest saved once again. The question asks itself, though: How did hozen get to Durotar? Perhaps somebody in the Brewfest grounds has experience with them.>", ["objectivesText"] = "Talk to Zenda in the Brewfest grounds.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 152780, ["x"] = 0.408, ["y"] = 0.182 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.182 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[56716] = { ["id"] = 56716, ["name"] = "Direbrew Cog", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "horde", ["categories"] = { "seasonal" }, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 56716 }, ["description"] = "<Direbrew's Dark Iron have fled, leaving behind a small piece of one of their mole machines. You know they have attacked Brewfest before. Perhaps one of the goblins would be interested in hearing of your victory.>", ["objectivesText"] = "Talk to Blix Fixwidget in the Brewfest grounds.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 37829 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 24495, ["x"] = 0.5076, ["y"] = 0.2316 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.5076, ["y"] = 0.2316 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 } },
[56719] = { ["id"] = 56719, ["name"] = "This Ain't Mine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "Your arrival is timely, <name>. Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. We are cut off from our vanguard and I fear that they will be destroyed if we cannot reinforce them quickly. Our forces are few in number. We cannot afford to leave them stranded for long. Tinkmaster Overspark and Gazlowe believe they have a solution. Hurry and aid them however you can.", ["objectivesText"] = "Clear the pass of boulders , mines, and other obstructions between Razor Hill and Orgrimmar. Progress: Thank the Light you were able to open the pass.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 1, ["flags"] = 0 } } },
[56739] = { ["id"] = 56739, ["name"] = "The Power of Worship", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 56739 }, ["series"] = { 55571 }, ["description"] = "I was once like them, stuck in a loop and waiting for Azshara to come and save me. Our spirits are locked to this place. There are naga in the other parts of these ruins. They have these magical orbs... I think they are using us to fuel their arcane experiments. They draw power from our spirits and our worship of Azshara. This keeps us weakened and unable to break free. Destroy the orbs. Breaking the connection will allow us to gain strength and move on.", ["objectivesText"] = "Destroy 3 Arcane Energy Transmuters . Progress: Have you found them all?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[56740] = { ["id"] = 56740, ["name"] = "S.P.A.R.E. Crates", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56740 }, ["description"] = "I'm sure you agree that Pascal -K1N6 is the greatest invention you've ever seen! If you're not convinced yet, try to push him to his limits. I don't mind! Bring him more resources and blueprints -- he'll craft anything you need!", ["objectivesText"] = "Craft $1oa Junkyard Tinkering items with Pascal -K1N6.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["rewardItems"] = { 166846 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 152295, ["x"] = 0.712, ["y"] = 0.325 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.325 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard" },
[56741] = { ["id"] = 56741, ["name"] = "The Spear of Destiny", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55558, 55560, 55561, 55565, 55569, 55570, 55571, 55573, 55574, 55694, 56325, 56358, 56741 }, ["series"] = { 55574, 56325 }, ["description"] = "The Javelins are some of the most powerful magical creations of Suramar, before the Sundering. This is just what we need to bring down the wards on the protector and the Tidestone. We must hurry back to Mezzamere, Lady Proudmoore needs to know of our success. This will change the entire course of our campaign here in Nazjatar , <name>.", ["objectivesText"] = "Return to Jaina Proudmoore in Mezzamere.", ["rewardGold"] = 31500, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153617, ["x"] = 0.604667, ["y"] = 0.459333 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.604667, ["y"] = 0.459333 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1718, ["db2PoiUiMapID"] = 1355, ["questLines"] = { { ["id"] = 975, ["name"] = "Turning the Tide", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 45, ["flags"] = 0 } } },
