[56756] = { ["id"] = 56756, ["name"] = "My Punkin, the Action Figure", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 56756 }, ["description"] = "Heya, <name>. <Grizzek leans in close and whispers.> I'm workin' on a surprise for Saffy. Hopin' you can help me out. I overheard her beggin' Jepetto Joybuzz to make her into one of his fancy new action figures. That ol' jerk told her no. Can you believe it? My Punkin! Well, we don't need him. I reverse engineered a few of his toys and found out what makes them tick. I got a blueprint ready to go. We can make Saffy's action figure ourselves and surprise her with it!", ["objectivesText"] = "Craft the Sapphronetta Flivvers Action Figure at Pascal-K1N6. Progress: You've got the spark of discovery in your eyes!", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 169610, 169876, 169882 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 149815, ["x"] = 0.71475, ["y"] = 0.363 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 151010, ["x"] = 0.716, ["y"] = 0.3228 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.71475, ["y"] = 0.363 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard" },
