[56764] = { ["id"] = 56764, ["name"] = "Brewfest Chowdown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["categories"] = { "seasonal" }, ["flags"] = {}, ["sharable"] = true, ["event"] = "Brewfest", ["expansion"] = 7, ["zoneID"] = 1, ["mapID"] = 27, ["storyline"] = { 56764 }, ["description"] = "Welcome, <class>! I hope you came with an empty stomach! What's better, or more Brewfest, than sausage and brew? The Brewfest Chowdown is our new celebration of the things that make this festival great. Take a seat and show us what you can eat. If you want more details before jumping in, just ask!", ["objectivesText"] = "Participate in the Brewfest Chowdown. Progress: Eat a sausage, drink some brew, then eat some more!", ["rewardGold"] = 169800, ["rewardXP"] = 200, ["rewardItems"] = { 37829, 169599, 169865 }, ["starts"] = { { ["mapID"] = 27, ["npcID"] = 153574, ["x"] = 0.548, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 27, ["npcID"] = 153574, ["x"] = 0.548, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 27, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 27 }, ["zone"] = { 1 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 2751 }, ["db2QuestSortName"] = "Epic" },
