[56771] = { ["id"] = 56771, ["name"] = "Time-Lost Warriors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 84, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "According to the scouting report ye found, the Rajani are holed up in the Silent Sanctuary, overlooking Mistfall Village. They are described in the report as seclusive and dangerous, so we'd had best take caution when approaching them. I'll meet ye there.", ["objectivesText"] = "Meet with the Rajani at the Silent Sanctuary. Progress: What is it, outsider?", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84, 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 17, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 16, ["flags"] = 0 } } },
