[56973] = { ["id"] = 56973, ["name"] = "Giant Crab Leg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 56973 }, ["objectivesText"] = "Progress: Yes? What is it?", ["rewardGold"] = 23400, ["rewardItems"] = { 170171 }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 149902, ["x"] = 0.5, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[56979] = { ["id"] = 56979, ["name"] = "Saving the Siege", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "In the chaos of the rockslides, Sylvanas dispatched her saboteurs to sneak past our sentries and plant bombs on our siege weaponry. Several of them have already been lost. We cannot afford to lose more.", ["objectivesText"] = "Remove 8 Suspicious Crates.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 } } },
[56980] = { ["id"] = 56980, ["name"] = "Already Among Us", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "While some of the Horde have joined forces with us, many within Orgrimmar remain loyal to Sylvanas. Her saboteurs have infiltrated our ranks and are posing as our technicians. Her assassins are lurking in the shadows. Stop any loyalists you encounter, before they can cause any harm.", ["objectivesText"] = "Slay 10 Suspicious Technicians or Loyalist Assassins .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 } } },
[56981] = { ["id"] = 56981, ["name"] = "Strategic Deployment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "Saurfang maintains that the key to taking Orgrimmar is to exploit its multiple points of entry. He led the city's defenses for years, and knows its vulnerabilities better than anyone. We are spread thin as it is, but I trust his judgment in this matter. We must also fortify Thunder Bluff in case Sylvanas plans to assault it while our forces are committed here. Deliver these deployment orders to our officers. We will assail all of Orgrimmar's gates at once while also defending Thunder Bluff.", ["objectivesText"] = "Deliver Anduin's deployment orders.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 } } },
[56982] = { ["id"] = 56982, ["name"] = "Before the Gates of Orgrimmar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "We have prepared for this battle as best we can, $p. I pray that we all survive what is to come.", ["objectivesText"] = "Begin the battle at the gates of Orgrimmar.", ["rewardGold"] = 289300, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155784, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 } } },
[56993] = { ["id"] = 56993, ["name"] = "The Price of Victory", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "Saurfang... how could this have happened.... <Jaina takes a moment to compose herself.> The Alliance has known High Overlord Saurfang as both a sworn enemy and an invaluable ally. Anduin will want to honor his memory. Recall our forces and inform them of what has happened. Genn's soldiers were dispatched to the western gate. You should be able to find him there.", ["objectivesText"] = "Recall the Alliance forces and inform them of what has transpired. Progress: He died a warrior's death, as he always wanted. I suppose there is some comfort in that.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57002] = { ["id"] = 57002, ["name"] = "Old Soldier", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002 }, ["description"] = "No matter what doubts he harbored, Saurfang was an honorable soldier. He prevented both a civil war within the Horde and the potential destruction of the Alliance. He brought an end to Sylvanas's reign and saved many lives at the cost of his own. We shall honor his sacrifice.", ["objectivesText"] = "Speak with Jaina in front of the gates of Orgrimmar. Progress: Thank you for coming.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155785, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 1004, ["questLineOrder"] = 24 }, { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 1004, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57003] = { ["id"] = 57003, ["name"] = "Create Your Own Strength", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57003 }, ["description"] = "For something that has been sitting on the ocean floor, there is still power to be found in this item. Take your piece of Benthic armor to Voidbinder Zorlan. He has been eyeing it with great curiosity. Go ahead and humor the ethereal and let him have a look. Maybe he has something to offer.", ["objectivesText"] = "Upgrade a piece of Benthic armor through Voidbinder Zorlan.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 151848, ["x"] = 0.485, ["y"] = 0.622 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.622 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[57004] = { ["id"] = 57004, ["name"] = "Create Your Own Strength", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57004 }, ["description"] = "That Benthic armor you carry has been lost beneath the tides for too long. There is still power within it. Voidbinder Sturzah may be able to provide insight. Take your find to our intrepid ethereal friend, and see what he can do with it.", ["objectivesText"] = "Upgrade a piece of Benthic armor through Voidbinder Sturzah. Progress: Were you successful?", ["rewardGold"] = 154900, ["rewardXP"] = 3410, ["rewardItems"] = { 169482 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 150101, ["x"] = 0.458, ["y"] = 0.7655 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.458, ["y"] = 0.7655 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[57005] = { ["id"] = 57005, ["name"] = "Becoming a Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57005 }, ["description"] = "Some of our bravest kelfin have volunteered to join you on your adventures, should you ever need a friend. You will find they each have their own special interests and they will mark your map with different opportunities every day. Use the conch when you're ready, choose who you would like to join you, and explore Nazjatar ! Choose wisely! You may only select one friend per day.", ["objectivesText"] = "Use the Calling Conch , choose an ally, and complete 3 ally quests.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 154002, ["x"] = 0.508, ["y"] = 0.652 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.508, ["y"] = 0.652 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[57006] = { ["id"] = 57006, ["name"] = "A Worthy Ally", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 57006 }, ["description"] = "Some of our bravest ankoan have volunteered to join you on your expedition. You will find each have their own special interests and they will mark your map with different opportunities every day. Use the Deepflame Campfire when you are ready. Choose a noble ally to join you, and explore what remains of Nazjatar . Choose wisely! You may only select one friend per day.", ["objectivesText"] = "Use the Deepflame Campfire , choose an ally, and complete 3 ally quests.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 205983, 205985, 210421, 210872 }, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1355, ["npcID"] = 153509, ["x"] = 0.378, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.378, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard" },
[57008] = { ["id"] = 57008, ["name"] = "Assault: The Warring Clans", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57008 }, ["description"] = "The opportunistic mogu clans seek to take the Vale while its defenders are recovering from N'Zoth's attack. They are both cowardly and foolish. Show them the error of their ways.", ["objectivesText"] = "Drive back the Mogu Assault in the Vale of Eternal Blossoms . Progress: Yes?", ["rewardXP"] = 10225, ["rewardItems"] = { 170497, 174958 }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Push back the mogu forces", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[57009] = { ["id"] = 57009, ["name"] = "Fame Waits for Gnome One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 57009, 58708 }, ["series"] = { 54088, 58708 }, ["description"] = "Tinkmaster Overspark requests your assistance on an important research expedition. Working with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", ["objectivesText"] = "Meet with Tinkmaster Overspark in Boralus.", ["rewardGold"] = 25740, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 150208, ["x"] = 0.674, ["y"] = 0.155333 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.674, ["y"] = 0.155333 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57010] = { ["id"] = 57010, ["name"] = "Harnessing the Power", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 55374, 55400, 55407, 55425, 55497, 55533, 55618, 55851, 57010 }, ["series"] = { 55618 }, ["description"] = "Heart Forge online. Initiate final attunement sequence. Awaiting input from champion unit <name>.", ["objectivesText"] = "Use the Petrified Ebony Scale atop the Heart Forge to infuse its power into the Heart of Azeroth. Progress: Standing by.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 168611 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 1, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 22 }, { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 923, ["questLineOrder"] = 24 }, { ["id"] = 217, ["title"] = "Nazjatar", ["questLineID"] = 5375, ["questLineOrder"] = 0 }, { ["id"] = 223, ["title"] = "Nazjatar", ["questLineID"] = 5385, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 923, ["name"] = "Empowering the Heart", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5375, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5385, ["name"] = "Welcome to Nazjatar", ["orderIndex"] = 19, ["flags"] = 0 } } },
