[57024] = { ["id"] = 57024, ["name"] = "Rumors of Mechagon", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["mapID"] = 1355, ["storyline"] = { 55630, 55632, 55646, 55647, 55648, 55649, 55650, 55651, 55652, 55685, 57024 }, ["description"] = "I knew I should've taken that gig with the Greasemonkeys... Gazlowe 's crew always get paid, and no dumb risks. I heard they got somethin' big comin' up too...", ["objectivesText"] = "Meet Gazlowe outside the Great Seal in Dazar'alor.", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 1355, ["npcID"] = 156187, ["x"] = 0.484, ["y"] = 0.606 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 152522, ["x"] = 0.53, ["y"] = 0.432 } }, ["coords"] = { ["mapID"] = 1355, ["source"] = "quest_giver", ["x"] = 0.484, ["y"] = 0.606 }, ["mapCandidates"] = { ["npc"] = { 1165, 1355 }, ["zone"] = { 10052 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 222, ["title"] = "Mechagon", ["questLineID"] = 5384, ["questLineOrder"] = 0 }, { ["id"] = 328, ["title"] = "Mechagon Passport Control", ["questLineID"] = 6061, ["questLineOrder"] = 2 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 5384, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 6061, ["name"] = "Mechagon Intro", ["orderIndex"] = 10, ["flags"] = 1 } } },
[57043] = { ["id"] = 57043, ["name"] = "Old Friends, New Opportunities", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = { "important" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Greetings, <name>. I have a... strange message for you from a group of goblins. Someone named Sassy Hardwrench is asking for your help for what was described as a, \"big job\". The word \"big\" was mentioned several times, followed by murmuring about time and money. Sassy is waiting for you over in Stranglethorn Vale.", ["objectivesText"] = "Speak with Sassy Hardwrench in Stranglethorn Vale.", ["rewardGold"] = 32200, ["rewardXP"] = 850, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 156358, ["x"] = 0.395, ["y"] = 0.801 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.801 }, ["mapCandidates"] = { ["npc"] = { 85, 210 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57045] = { ["id"] = 57045, ["name"] = "A Special Delivery", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "I'm glad you're finally here, <name>. I've got an important delivery to make and you're the goblin I trust most. Yeah, yeah. I know that's not sayin' much, but it's hard to find good help these days! This package is for Hobart Grapplehammer . He's got a workshop in Crapopolis and I need you to deliver it to him. He's been working on somethin' big lately! Deliver the package and for the love of money... DON'T DROP IT! You have no idea how long it took me to locate this thing!", ["objectivesText"] = "Deliver the package to Hobart Grapplehammer . Progress: Gallywix sure has some nerve threatening me in my own laboratory! He thinks he can just do whatever he wants to whoever he wants...", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 30256, 30257, 30258, 142054, 170538, 237812 }, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57047] = { ["id"] = 57047, ["name"] = "A Simple Experiment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Now that you've delivered the necessary parts, I can begin testing my latest prototype! I call it the X-52 Personnel Armor! It will be nearly indestructible! Gallywix has always coveted my inventions and now that he knows about the X-52 I'm sure he'll be up to no good. I've gotta complete the prototype before Gallywix comes up with a way to steal it out from under me! I could really use an extra set of hands with the experiments. Can I count on you, <name>?", ["objectivesText"] = "Assist Hobart Grapplehammer . Progress: We need to complete the X-52 Personnel Armor before Gallywix finds a way to steal the prototype!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57048] = { ["id"] = 57048, ["name"] = "Shopping For Parts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "I'm going to need some additional components in order to complete the next phase of testing. Right now, what we need most are thermoplugs and thermoplug adaptors! I'll explain what they're for later... Crank Greasefuse runs a shop near the entrance of the town. Go speak with Crank and get him to fork over the necessary parts. I don't care what they cost, just tell him to bill me later! I can't be bothered to negotiate right now. I need to prepare the modifications to the X-52 Personnel Armor!", ["objectivesText"] = "Speak with Crank Greasefuse .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57051] = { ["id"] = 57051, ["name"] = "Debt Collection!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "You need thermoplugs? Well, you came to the right place, kid. But I ain't giving 'em to you on credit. There's way too many shlubs who haven't paid me back the money they owe. I'm in over my head here, if I don't get paid fast, I'll be out of business in no time. < Crank Greasefuse thinks for a moment.> Look, I tell you what... If you can muscle those no-good goons into paying me my money, I'll give you the thermoplugs as payment. You won't find a better deal than that!", ["objectivesText"] = "Collect 8 Unpaid Debts . Progress: You got my money?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 171089 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57052] = { ["id"] = 57052, ["name"] = "I've Got What You Need", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "A deal's a deal, <name>. Here's the thermoplugs you ordered! Be sure to let that ol' grouch Grapplehammer know that I won't be giving out anymore handouts. If he needs more thermoplugs he'd better be ready to pay up. Anyway, it was a pleasure doing business with you... Now get lost!", ["objectivesText"] = "Deliver the package to Hobart Grapplehammer .", ["rewardGold"] = 29500, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57058] = { ["id"] = 57058, ["name"] = "Fun With Landmines", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "The prototype X-52 Personnel Armor is ready for the final test! How are you with loud noises and sudden bursts of concussive energy, <name>? For the final test, we're going to strap you into the X-52 Personnel Armor and have you traverse a minefield! I have placed a refreshing coconut beverage in the center of the minefield. Consider the drink a fitting reward for reaching the oasis and surviving the inevitable explosions in the process!", ["objectivesText"] = "Retrieve the refreshing coconut beverage from the minefield. Progress: Ballistic testing... IS MY FAVORITE!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174059 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57059] = { ["id"] = 57059, ["name"] = "Let's Rumble!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11455, ["mapID"] = 1532, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "This is bad, <name>! Real bad! Gallywix and his goons are destroying my workshop, but he's got another thing coming if he thinks I'm gonna hand over the X-52 Personnel Armor! You've gotta get down there and clear out his goon squad before this place--AND ALL MY INVENTIONS--go up in flames!", ["objectivesText"] = "Defeat 8 Hired Scoundrels . Progress: Hurry, <name>! Gallywix and his goons are destroying my worskshop!", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11455 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2263, ["db2PoiUiMapID"] = 1532, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57067] = { ["id"] = 57067, ["name"] = "Mogu at the Gates", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57068, 57069 }, ["description"] = "The time has come. The other mogu clans have set their sights on the Vale of Eternal Blossoms . They will not conquer it. Some of your kind have already gone to the gate to scout out the size of their force. If you think yourself worthy for such a mission, meet them there.", ["objectivesText"] = "Meet Chen and Li Li Stormstout at the Gate of the August Celestials.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156297, ["x"] = 0.555, ["y"] = 0.911 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 379, 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1795, ["db2PoiUiMapID"] = 1530, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57068] = { ["id"] = 57068, ["name"] = "Kite Surveillance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57067, 57069 }, ["description"] = "We heard for ourselves that there were mogu attacking, but I had no idea it would be this many! There must be a way to stop them before they completely overrun the Vale. Quickly, let us fly over and scout out their numbers. We just so happen to have a kite that can carry three people. Usually it's more, but I had a big lunch.", ["objectivesText"] = "Ride Chen's Kite to scout the Mogu armies.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156297, ["x"] = 0.555, ["y"] = 0.911 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.911 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57069] = { ["id"] = 57069, ["name"] = "Cut Off the Heads", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57067, 57068 }, ["description"] = "Okay. We're stuck in the middle of three mogu armies, and Uncle Chen is too hurt to move yet. It's not hopeless though. We have the chance to take out the leaders of these armies. Maybe that will slow them down or distract them long enough for us to get back to the gate! See if you can get out there and take down the biggest, baddest mogu you can find. Those will be the commanders.", ["objectivesText"] = "Slay mogu commanders.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 237812 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57070] = { ["id"] = 57070, ["name"] = "Mogu Massacre", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["description"] = "I think this is what my friends would call a \"target rich environment.\" As a nicer way of saying \"we're surrounded and probably doomed.\" You know what this means. We have to kill as many of these mogu as possible! It doesn't matter how you do it, just take them out!", ["objectivesText"] = "Slay mogu in Kun-Lai Summit .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156391, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57071] = { ["id"] = 57071, ["name"] = "No Brew Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["description"] = "My head is... hurting. There can be only one solution. We flew over an abandoned brew caravan. You must go find it, and save that brew! That should help bring me back to full strength. Plus, it would do wonders for the morale of those fighting in the Vale, if we can recover it.", ["objectivesText"] = "Locate the abandoned brew barrels in Kun-Lai Summit .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156390, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 157180, ["x"] = 0.585, ["y"] = 0.84 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57072] = { ["id"] = 57072, ["name"] = "Yak of All Trades", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["description"] = "<The brew barrels are too heavy and numerous to carry alone. Perhaps you can find something, or someone, to help you.>", ["objectivesText"] = "Find something to help you carry the brew back to Chen in Mogujia.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 157180, ["x"] = 0.585, ["y"] = 0.84 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156390, ["x"] = 0.6, ["y"] = 0.756 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.585, ["y"] = 0.84 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57074] = { ["id"] = 57074, ["name"] = "Our Backs to the Gate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57075, 57076 }, ["description"] = "It is most fortuitous that you found this brew, and a yak to carry it on! But we cannot remain here. Li Li has healed me up enough to travel. We can ride the yak back to the gate and hope that the mogu do not notice our passing. Let me know when you are ready to leave.", ["objectivesText"] = "Ride Mobi with Chen and Li Li to the Gate of August Celestials.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156390, ["x"] = 0.6, ["y"] = 0.756 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156938, ["x"] = 0.555, ["y"] = 0.912 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.756 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57075] = { ["id"] = 57075, ["name"] = "Liquid Courage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57074, 57076 }, ["description"] = "We have to do something about all these mogu. At least to thin their ranks before they invade the Vale! As much as Uncle Chen loves his brew, I think we can put it to better use. Let's hop onto that yak and give the mogu something to fear!", ["objectivesText"] = "Mount Mobi and defeat the mogu armies with the power of brew. Progress: Something must be done about all these mogu, or we will lose the Vale.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156938, ["x"] = 0.555, ["y"] = 0.912 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 156937, ["x"] = 0.554, ["y"] = 0.91 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.555, ["y"] = 0.912 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 379, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57076] = { ["id"] = 57076, ["name"] = "Return to Mistfall", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 57067, 57068, 57069, 57070, 57071, 57072, 57074, 57075, 57076 }, ["series"] = { 57074, 57075 }, ["description"] = "We have done all we can here. We know how much the mogu are a clear threat. The forge is in great danger of falling into their hands if we lose our hold on the Vale. Let us return to Mistfall and report to the Rajani. They will want to know what we are up against.", ["objectivesText"] = "Return to Stormspeaker Qian in the Silent Sanctuary in the Vale of Eternal Blossoms.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 156937, ["x"] = 0.554, ["y"] = 0.91 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.554, ["y"] = 0.91 }, ["mapCandidates"] = { ["npc"] = { 379, 1530 }, ["zone"] = { 5841 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["questLines"] = { { ["id"] = 992, ["name"] = "Mogu at the Gates", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57077] = { ["id"] = 57077, ["name"] = "Buyers Wanted!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11455, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "The X-52 Personnel Armor is finally complete and Gallywix has been sent packing with his tail between his legs! I've got you to thank for this, <name>! But we're still not done... the best part is yet to come. We're going to hold an auction and sell the X-52 Personnel Armor to the highest bidder! Sassy Hardwrench should have a list of interested buyers ready to go. Head over to Hardwrench Hideaway and let her know we're ready for the auction!", ["objectivesText"] = "Speak with Sassy Hardwrench in Stranglethorn Vale.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 11455 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57078] = { ["id"] = 57078, ["name"] = "The VIP List", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "While you've been assisting Grapplehammer with his newest invention, I've been hard at work finding potential buyers! This is going to be a private auction, so we're only inviting the best and the brightest, the cream of the crop, the creme de la creme... got it? I've narrowed the potential buyers down to an 'A' list of only the wealthiest, classiest, most connected goblins around... minus Gallywix, of course! Head out and deliver these invitations while I finish up preparations for the auction!", ["objectivesText"] = "Deliver the invitations to Grapplehammer's private auction. Progress: This will be an 'A' list event. Only Kezan's finest will be in attendance!", ["rewardGold"] = 341600, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["ends"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 210, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57079] = { ["id"] = 57079, ["name"] = "Beat The Crapopolis Outta Him!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5287, ["mapID"] = 210, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Boy am I glad to see you! We've got a bad situation on our hands... While you were away delivering the invitations, Gallywix and his goons took over Crapopolis! They're holding Hobart Grapplehammer hostage until he hands over the X-52 Personnel Armor! You have to stop Gallywix before it's too late!", ["objectivesText"] = "Complete the Crapopolis scenario.", ["rewardGold"] = 561800, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 210, ["npcID"] = 156396, ["x"] = 0.346, ["y"] = 0.285 } }, ["coords"] = { ["mapID"] = 210, ["source"] = "quest_giver", ["x"] = 0.346, ["y"] = 0.285 }, ["mapCandidates"] = { ["npc"] = { 210 }, ["zone"] = { 5287 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2258, ["db2PoiUiMapID"] = 1531, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57080] = { ["id"] = 57080, ["name"] = "A Fitting Reward", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 9 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 1531, ["storyline"] = { 57043, 57045, 57047, 57048, 57051, 57052, 57053, 57058, 57059, 57077, 57078, 57079, 57080 }, ["description"] = "Although the X-52 Personnel Armor's power-core was destroyed during the battle with Gallywix, the invention was a success! I doubt anyone will be interested in purchasing the rights to the X-52 without a working power-core, so why don't you hang onto the armor instead? It is quite stylish after all! Now that Crapopolis is saved and Gallywix is conveniently trapped inside of his own mechanical pummeler, I think I'm going to renegotiate that \"contract\" of his. He is a \"captive audience\" after all!", ["rewardGold"] = 573000, ["rewardXP"] = 8520, ["rewardItems"] = { 173978, 174077 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 2258, ["db2PoiUiMapID"] = 1531, ["questLines"] = { { ["id"] = 997, ["name"] = "Goblin Heritage Armor", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57086] = { ["id"] = 57086, ["name"] = "Legacy of the Mad Mage", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10052, ["storyline"] = { 57086 }, ["description"] = "<This rather large jewel has an inscription etched on its base: Property of Mardivas. If found please return to my laboratory. Perhaps this laboratory can still be found somewhere?>", ["objectivesText"] = "Investigate Mardivas's Laboratory. Progress: <The chest appears to be simply constructed, but the locking mechanism hums with arcane energy.>", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 170489, 170512, 170547 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10052 } }, ["questType"] = "standard", ["startItems"] = { 170512 } },
[57088] = { ["id"] = 57088, ["name"] = "This Ain't Mine", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Sylvanas's loyalists have collapsed part of the canyon path to Orgrimmar. Our forces are now cut off from each other. We need to reinforce our front line or the Banshee will pick us off at her leisure. We have come too far to be slain by a thousand cuts. Gazlowe and one of the Alliance's gnomes believe they have an answer. You'd best ensure that their plan does not backfire.", ["objectivesText"] = "Clear the pass of boulders , mines, and other obstructions between Razor Hill and Orgrimmar. Progress: Hmm. Maybe that goblin's gadgets have some use.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 10, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57090] = { ["id"] = 57090, ["name"] = "Saving the Siege", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The Banshee's spies were able to sneak past our guards in the chaos of the rockslides. They've been planting bombs on our siege weaponry. Get rid of those bombs.", ["objectivesText"] = "Remove 8 Suspicious Crates.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 11, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57091] = { ["id"] = 57091, ["name"] = "Already Among Us", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Sylvanas still commands the loyalty of many within the Horde. The war she started has blinded them with rage and hatred. She exploits that to maintain her support. <Saurfang scowls.> They do not yet see she will lead us to ruin, that her so-called victories are all hollow. Some of her agents have been spotted lurking within our ranks. Kill them. They will show us no mercy, and will have none in return.", ["objectivesText"] = "Slay 10 Suspicious Technicians or Loyalist Assassins .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 12, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 12, ["flags"] = 0 } } },
[57092] = { ["id"] = 57092, ["name"] = "Strategic Deployment", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "For years, I guarded the gates of Orgrimmar. The city's greatest weakness has always been its multiple entrances. We should strike at all of them to seize victory. Wrynn and I have drawn up orders for deployment. The mages will cover our flank. Greymane will close in from the west, and the elves will take the north. We will send Mayla to reinforce Thunder Bluff's defenses in case Sylvanas launches a counterattack. Bring the orders to our commanders.", ["objectivesText"] = "Deliver Saurfang's deployment orders.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 13, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 13, ["flags"] = 0 } } },
[57093] = { ["id"] = 57093, ["name"] = "Before the Gates of Orgrimmar", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "It is time. We have done all that we can to prepare. All that remains is the battle itself. I am not one for speeches. So I will say only this. Lok-tar ogar, <name>. Victory. Or death.", ["objectivesText"] = "Begin the battle at the gates of Orgrimmar.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1, 1165 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 14, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 14, ["flags"] = 0 } } },
[57094] = { ["id"] = 57094, ["name"] = "The Price of Victory", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11403, ["mapID"] = 1165, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Saurfang... I... <Lor'themar takes a moment to compose himself.> ...Thrall will wish to honor Saurfang's sacrifice. And so shall the rest of us. Recall our forces. Let them know what has transpired. Tell them that the great warrior Varok Saurfang is dead and that the warchief has abandoned us. Speak to Baine when you arrive in Thunder Bluff. You will find him on the Elder Rise. I am certain he will want to pay his respects to Saurfang as well. Let us stand as a united Horde once more.", ["objectivesText"] = "Inform Baine Bloodhoof of what has transpired. Progress: He earned the warrior's death he always sought. There is honor in that.", ["rewardGold"] = 68950, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.96 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 11403 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1535, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 15, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 15, ["flags"] = 0 } } },
[57095] = { ["id"] = 57095, ["name"] = "Old Soldier", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 1165, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "No matter what anyone says, he was an honorable orc. A legend in his own right, the ideal to which all warriors of the Horde aspired. He gave his life to heal the rift in the Horde and give us the chance to forge a new path forward. His was more than a death befitting a warrior. It was the death of a hero. We shall honor his sacrifice.", ["objectivesText"] = "Honor High Overlord Saurfang.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 165791 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 155789, ["x"] = 0.5, ["y"] = 0.96 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155787, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.5, ["y"] = 0.96 }, ["mapCandidates"] = { ["npc"] = { 1, 1165 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 16, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 16, ["flags"] = 0 } } },
[57112] = { ["id"] = 57112, ["name"] = "Test Shared Quest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 57112 }, ["description"] = "None", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57126] = { ["id"] = 57126, ["name"] = "...And Following Seas", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "My brother Derek died in the Second War, only to be raised against his will by the Banshee Queen. If not for Baine Bloodhoof's courageous act of defiance, Derek would have been turned into a weapon against my family. He's lived in torment since his awakening. I feared he would be lost to us, but he has received help from an old friend of mine who has also been recently raised-- Calia Menethil . She has guided him back from the brink of despair. I am on my way to pay them a visit. Care to join me?", ["objectivesText"] = "Visit Derek Proudmoore and Calia Menethil .", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150633, ["x"] = 0.5735, ["y"] = 0.4475 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 156513, ["x"] = 0.6295, ["y"] = 0.5985 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.5735, ["y"] = 0.4475 }, ["mapCandidates"] = { ["npc"] = { 18, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57130] = { ["id"] = 57130, ["name"] = "Traitors In Our Midst", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11402, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "There is a difference between loyalty and blind obedience. I am done following the Banshee's orders!", ["objectivesText"] = "Deal with this traitor.", ["rewardGold"] = 262100, ["rewardXP"] = 6815, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57147] = { ["id"] = 57147, ["name"] = "Not My Warchief", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11402, ["mapID"] = 1, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "There is little time. Sylvanas likely knows of my intentions and sent you to deal with me accordingly. I doubt she will be pleased with your decision. We must make our way to the wyverns and take to the skies.", ["objectivesText"] = "Escape with Eitrigg and meet up with Saurfang in Razor Hill.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 25808, 25809, 25810, 25811, 52901, 52947, 98133, 211279, 237812 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 155786, ["x"] = 0.54, ["y"] = 0.425 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57148] = { ["id"] = 57148, ["name"] = "Siegebreakers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11402, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The fools who follow Saurfang have grown bold enough to launch a direct assault. We cannot allow these pests to swarm before our gates. Our operatives are collapsing the pass between Razor Hill and Orgrimmar as we speak. Saurfang's treasonous forces will be cut in half. Your task is to sneak into their ranks and sabotage their siege engines. Wear this disguise, but know that it will not hold up under close examination. Slay anyone who discovers you.", ["objectivesText"] = "Covertly place Suspicious Crates and slay guards.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 171365 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57149] = { ["id"] = 57149, ["name"] = "Propaganda Takedown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11402, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Recently, dissidents have been posting propaganda around the city and spreading all manner of lies. This is no time to entertain delusion. An army of traitors and sworn enemies assembles at our gates. These ingrates would see us become pin cushions for the Alliance's archers. <Nathanos rolls his eyes.> Tear down the rubbish. It can only lead to panic in the streets. And should you encounter any... resistance... you are hereby authorized to respond with force.", ["objectivesText"] = "Burn Dissident Propaganda in Orgrimmar.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57150] = { ["id"] = 57150, ["name"] = "Militia", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11402, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The war has proven costly and our ranks have been steadily depleted. But the Horde is nothing if not strong. Each and every citizen of Orgrimmar is worth ten Alliance weaklings on the battlefield. Rally the citizens and form a militia! Remind them of their slain brothers and sisters!", ["objectivesText"] = "Rally the citizens of Orgrimmar.", ["rewardGold"] = 262100, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57151] = { ["id"] = 57151, ["name"] = "A Line in the Sand", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 11402, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "Now that we have put our house in order, it is time to purge the filth before our gates. How thoughtful of those traitors to gather themselves in one place, so that we may slay them all in one fell swoop. Let us end this pitiful rebellion.", ["objectivesText"] = "Speak with Nathanos.", ["rewardGold"] = 339600, ["rewardXP"] = 8520, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156440, ["x"] = 0.188, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156425, ["x"] = 0.186, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.188, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 11402 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 2237, ["db2PoiUiMapID"] = 1534, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57152] = { ["id"] = 57152, ["name"] = "Most Loyal", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 3433, ["mapID"] = 95, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152 }, ["description"] = "The Dark Lady anticipated this as a possible outcome. She has prepared a contingency plan to deal with it accordingly. You are to rendezvous with her in the Ghostlands. Take this hearthstone. It is good for one more use. She will meet you near Windrunner Spire.", ["objectivesText"] = "Speak with Sylvanas Windrunner.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 172203 }, ["starts"] = { { ["mapID"] = 95, ["npcID"] = 156425, ["x"] = 0.186, ["y"] = 0.584 } }, ["ends"] = { { ["mapID"] = 95, ["npcID"] = 156425, ["x"] = 0.186, ["y"] = 0.584 } }, ["coords"] = { ["mapID"] = 95, ["source"] = "quest_giver", ["x"] = 0.186, ["y"] = 0.584 }, ["mapCandidates"] = { ["npc"] = { 95 }, ["zone"] = { 3433 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 2, ["title"] = "War Campaign", ["questLineID"] = 1003, ["questLineOrder"] = 26 }, { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 95, ["questLines"] = { { ["id"] = 1003, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57155] = { ["id"] = 57155, ["name"] = "Blinding the Eye", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 57155 }, ["description"] = "Ah yes, just the <class> I wanted to see. I can still sense his touch lingering upon you. Our victory over the god of the deep will not be complete until we remove all traces of his infection. Through my research I have learned a less painful way of removing the infection. Speak with me, and let's put an end to this nightmare.", ["objectivesText"] = "Speak with Brother Pike to cleanse your \"gift\".", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57157] = { ["id"] = 57157, ["name"] = "Assault: The Black Empire", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 57157 }, ["description"] = "It is just as the visions fortold. Dark forces have come to claim the Forge of Origination. They must be stopped, or all of Azeroth will meet its end!", ["objectivesText"] = "Drive back the N'Zoth Assault in Uldum . Progress: The madness... it consumes!", ["rewardXP"] = 10225, ["rewardItems"] = { 173372 }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Drive back N'Zoth's Forces", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[57198] = { ["id"] = 57198, ["name"] = "Sense of Obligation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "Derek is free. I have to atone for much with him. There is a rumor of a meeting with Jaina and her brother. Head to Seabreeze Village in Stormsong Valley . I hope there you will be able to find out... well, let's just say I am trying to keep the bigger picture in focus. If you find out anything of interest, I would be most appreciative. For now, let's keep this between the two of us.", ["objectivesText"] = "Eavesdrop on Jaina Proudmoore's meeting.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141961, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 141961, ["x"] = 0.584, ["y"] = 0.626 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 17, ["flags"] = 0 } } },
[57220] = { ["id"] = 57220, ["name"] = "Power Protocol Initiation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57221, 57222, 57290 }, ["description"] = "We've come a long way, <name>. Once the power from the auxiliary systems are brought online MOTHER will be able tae run diagnostics. All that's left is settin' the final pieces in place.", ["objectivesText"] = "Relay power from the Chamber of Heart, Engine of Nalak'sha and Forge of Origination auxiliary systems, then speak with MOTHER to power up the Forge of Origination. Progress: Quite the journey so far.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 19, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 18, ["flags"] = 0 } } },
[57221] = { ["id"] = 57221, ["name"] = "Re-Origination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57220, 57222, 57290 }, ["description"] = "If the Ramkahen haven't reached out tae sound any alarms then the anomaly must be contained within the Halls of Origination. We best get back tae investigate, <name>.", ["objectivesText"] = "Meet Magni Bronzebeard outside the Halls of Origination in Uldum.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 20, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 19, ["flags"] = 0 } } },
[57222] = { ["id"] = 57222, ["name"] = "Investigating the Halls", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57220, 57221, 57290 }, ["description"] = "Whatever's happenin' has tae be comin' from deep within the inner chamber. If we can get tae the forge maybe we'll find some answers. Best check yer gear 'fore headin' in, <name>. Who knows what's waitin' fer us in there.", ["objectivesText"] = "Investigate the anomaly in the Halls of Origination.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 21, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 20, ["flags"] = 0 } } },
