[57249] = { ["id"] = 57249, ["name"] = "A Timely Invitation", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 440, ["storyline"] = { 57249 }, ["description"] = "The time has arrived to remember the past and celebrate our adventures across Azeroth and Beyond. To commemorate the occasion the Bronze Dragonflight is throwing a celebration and you are invited! Come to the Caverns of Time and present this ticket to gain entry to the party!", ["objectivesText"] = "Bring the Invitation from the Timewalkers to Chromie within the Caverns of Time.", ["rewardGold"] = 26210, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne", ["startItems"] = { 171177 } },
[57274] = { ["id"] = 57274, ["name"] = "Quartermaster's Bounty", ["level"] = 26, ["requiredLevel"] = 26, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 57274 }, ["objectivesText"] = "Progress: To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", ["rewardItems"] = { 171198 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143555, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[57275] = { ["id"] = 57275, ["name"] = "Something in Your Mind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 57275, 57462, 57464 }, ["description"] = "<Looking into the crystal, the light around you is slowly drowned in inky smoke. An imposing presence crushes down on you, whispering unintelligibly in your ear. Looking for the source, you see nothing, but the sensation grows. Your head begins to swim as the darkness deepens and the noise becomes deafening. Summoning all your willpower to steel your resolve... The light has returned, the noise silenced, and you stand with a humble crystal in your hand. Perhaps Wrathion knows more about it...>", ["objectivesText"] = "Bring the Void Focus to Wrathion in the Chamber of Heart. Provided item:", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 169223, 170553, 171176, 171312, 171320 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "profession", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1031, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 1032, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (H)", ["orderIndex"] = 0, ["flags"] = 0 } }, ["startItems"] = { 171320 } },
[57276] = { ["id"] = 57276, ["name"] = "Maintaining Focus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57275, 57276, 57462 }, ["series"] = { 57462, 57464 }, ["description"] = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him. N'Zoth's influence is everywhere, <name>, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", ["objectivesText"] = "Acquire 20 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: We are embarking upon a dangerous gambit, <name>. Caution is of the utmost importance.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 170553, 171176, 171312, 171320 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "profession", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1032, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (H)", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57290] = { ["id"] = 57290, ["name"] = "Beginning the Descent", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "legendary", "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57220, 57221, 57222 }, ["description"] = "Protecting one's mind against the old gods requires an object of pure corruption. Unbeknownst to many, one such object exists--dormant beneath the molten pits of Blackwing Descent. Until recently, one of my agents stood watch over the area, keeping detailed records of suspicious activities. Unfortunately, this agent has gone silent. It is now clear we are not the only ones with this knowledge. If we are to find answers, there is one place to look. Our journey continues, <name>. Blackrock awaits.", ["objectivesText"] = "Retrieve the Corrupt Black Dragonscale from Blackwing Descent atop Blackrock Mountain in Burning Steppes. Progress: Have you recovered what we discussed?", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 37863, 63379, 142469, 169223, 171219, 172072 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 22, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 21, ["flags"] = 0 } } },
[57298] = { ["id"] = 57298, ["name"] = "How Things \"Really\" Happened...", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 440, ["storyline"] = { 57298 }, ["description"] = "You've come a long way over the years, <name>. From humble beginnings doing odd jobs to saving Azeroth's very existence, you've done so much to ensure the safety of our world. But why should we just stand around trying to remember things? Let's just go back in time and relive all of the exciting bits again! Don't worry, in all of the millions upon millions of timeways I'm sure I'll find one where you never die.", ["objectivesText"] = "Embark from the Caverns of Time with Chromie to defeat villains of the past. Progress: Hey, did we win yet? Or have we begun? I'm maybe not yet sure. Keeping the timelines straight gets a bit difficult.", ["rewardItems"] = { 172012 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2QuestSortName"] = "Nightborne" },
[57300] = { ["id"] = 57300, ["name"] = "Soldier of Time", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 57300 }, ["description"] = "Long ago, the land of Alterac Valley was peaceful. However, when the Frostwolves moved in it became highly contested real estate between them and the Stormpikes. Battles used to rage for days. Well, actually the battle is still ongoing, the bronze dragons have figured out a way for you to revisit those early days.", ["objectivesText"] = "Earn 500 honor in Korrak's Revenge. Progress: Did you have fun exploring Alterac Valley as it used to be?", ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 137642, 169298, 172022, 172023, 172121, 172135, 172136, 172137, 212289, 212292, 212295, 212298, 224556, 232877, 233014 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "pvp", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
[57302] = { ["id"] = 57302, ["name"] = "Alterac Valley Graveyards", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57302 }, ["description"] = "The graveyards in Alterac Valley are prized territories. Both the Horde and the Alliance fight savagely for these sacred grounds. Are you, <name>, ready to join that fight? I want you to assault an enemy graveyard. Find a graveyard with a Horde banner in its midst, and pull it from the ground! Do that, and your task will be complete.... But if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", ["objectivesText"] = "Assault a graveyard, then return to Sergeant Durgen Stormpike in Dun Baldar.", ["rewardGold"] = 341600, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57303] = { ["id"] = 57303, ["name"] = "The Quartermaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57303 }, ["description"] = "<name>, our quartermaster charged me to direct new recruits to him. He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them. Follow the road. You'll find our quartermaster to the west.", ["objectivesText"] = "Speak with the Stormpike Quartermaster .", ["rewardGold"] = 929400, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57304] = { ["id"] = 57304, ["name"] = "Capture a Mine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57304 }, ["description"] = "The mines in Alterac Valley hold more than just minerals. Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them! Capture a mine, then return to me. To capture a mine, enter one that we do not control and kill its leader. When you do that, the mine will be ours, and we'll send troops to protect it!", ["objectivesText"] = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", ["rewardGold"] = 638000, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57305] = { ["id"] = 57305, ["name"] = "Armor Scraps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57305 }, ["description"] = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops. If you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", ["objectivesText"] = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar. Progress: Did you bring any armor scraps , <name>?", ["rewardXP"] = 1415, ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 169298, 172022, 172023, 172121, 172135, 172136, 172137 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57306] = { ["id"] = 57306, ["name"] = "More Armor Scraps", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57306 }, ["objectivesText"] = "Progress: <name>, we need more armor scraps to supply our troops!", ["rewardItems"] = { 17422 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57307] = { ["id"] = 57307, ["name"] = "Towers and Bunkers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57307 }, ["description"] = "Towers and bunkers are key defensive positions, and so we must hold as many as possible! I want you to attack a tower or a bunker in Alterac Valley. To do that, enter a tower with a Horde banner atop it. You will see another enemy banner inside. Pull out that banner, and a white Alliance banner will appear in its place. Well done! At that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", ["objectivesText"] = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Dun Baldar.", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57309] = { ["id"] = 57309, ["name"] = "Begin the Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57309 }, ["objectivesText"] = "Progress: My troops are supplied and ready to assault. We just need orders from Noreg Stormpike and I'll send them into the fray!", ["rewardItems"] = { 17353 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57310] = { ["id"] = 57310, ["name"] = "Irondeep Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57310 }, ["description"] = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine. The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep. We need the supplies in Irondeep, <name>. Enter the mine and bring me a load of them.", ["objectivesText"] = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Do you have the supplies, <name>? We can never have enough!", ["rewardGold"] = 170800, ["rewardItems"] = { 17522 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57311] = { ["id"] = 57311, ["name"] = "Coldtooth Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57311 }, ["description"] = "The Coldtooth mine is a storage depot for the Horde. I can't stomach the food they give their troops, and the state of their arms and armor is atrocious! But... in times like these when supplies are so important, we can use what they have. Enter the Coldtooth mine and bring me back their supplies. That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors. Good luck, <name>. The mine is to the distant south, deep in Horde territory.", ["objectivesText"] = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar. Progress: Did you enter the Coldtooth mine in Horde territory, <name>? Did you raid their supplies?", ["rewardGold"] = 341600, ["rewardItems"] = { 17542 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57312] = { ["id"] = 57312, ["name"] = "The Graveyards of Alterac", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57312 }, ["description"] = "The battle lines of Alterac Valley are ever shifting. Territories swing back and forth as we meet our opponents in deadly combat. And graveyards, <name>, are where battles rage most fierce. I want you to attack an Alliance held graveyard! Find a graveyard with an Alliance banner in its midst and pull it from the ground. Do that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", ["objectivesText"] = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57313] = { ["id"] = 57313, ["name"] = "Speak with our Quartermaster", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57313 }, ["description"] = "<name>, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley. Speak with him; he will tell you more. Follow the road west into the bunker, then take the west exit and you'll find our quartermaster.", ["objectivesText"] = "Speak with the Frostwolf Quartermaster .", ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57314] = { ["id"] = 57314, ["name"] = "Capture a Mine", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57314 }, ["description"] = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines. Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued! Help our war effort, <name>! Capture one of the mines for the Horde! To capture a mine, enter one that we do not control and kill its leader. When that is done, the mine will be ours and we'll send troops to protect it!", ["objectivesText"] = "Capture a mine, then return to Corporal Teeka Bloodsnarl in Frostwolf Village. Progress: You haven't yet captured a mine, <name>! Find one that we do not control and defeat it's leader!", ["rewardGold"] = 619600, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57315] = { ["id"] = 57315, ["name"] = "Towers and Bunkers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57315 }, ["description"] = "Towers and bunkers are important positions, and we must capture and hold them all! So to that end, I want you to attack a bunker that is controlled by the enemy. To do that, enter one with an Alliance banner. You will see another banner inside. Pull out that banner, and a white Horde banner will appear in its place. Well done! At that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", ["objectivesText"] = "Capture an enemy tower or bunker, then return to Corporal Teeka Bloodsnarl in Frostwolf Village.", ["rewardGold"] = 315900, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57317] = { ["id"] = 57317, ["name"] = "Enemy Booty", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57317 }, ["description"] = "When you fight the enemy, gather the scraps of their armor and bring them to me. I'll use those scraps to make armor for our own troops!", ["objectivesText"] = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village. Progress: How goes the hunting, <name>. Do you have any armor scraps for me?", ["rewardXP"] = 1415, ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 169298, 172022, 172023, 172121, 172135, 172136, 172137 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57318] = { ["id"] = 57318, ["name"] = "More Booty!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57318 }, ["objectivesText"] = "Progress: I need more armor scraps , <name>! Do you have any?", ["rewardItems"] = { 17422 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57320] = { ["id"] = 57320, ["name"] = "Launch the Attack!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57320 }, ["objectivesText"] = "Progress: My warriors are eager to attack! All I need are the assault orders...", ["rewardItems"] = { 17442 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57321] = { ["id"] = 57321, ["name"] = "Coldtooth Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57321 }, ["description"] = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it. And so, control of the mine often falls to the Alliance, or to underground denizens... But we still need our supplies, <name>! Go to the Coldtooth mine and bring me a load of them. And be wary of enemies as you go; the tides of battle shift quickly in that place...", ["objectivesText"] = "Bring 10 Coldtooth Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Have you been to the Coldtooth mine, <name>? Do you have the supplies I asked for?", ["rewardGold"] = 154900, ["rewardItems"] = { 3575, 3860, 12359, 17411, 17422, 17542, 169298, 172022, 172023, 172121, 172135, 172136, 172137 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57322] = { ["id"] = 57322, ["name"] = "Irondeep Supplies", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57322 }, ["description"] = "The Stormpike dwarves are using the Irondeep mine as a storage depot. I want you to raid that mine and bring me its supplies. This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment! Be wary, <name>. The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", ["objectivesText"] = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep. Progress: Did you enter the Irondeep mine, <name>? Did you raid its supplies?", ["rewardGold"] = 309800, ["rewardItems"] = { 17522 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57324] = { ["id"] = 57324, ["name"] = "Sail With the Tide", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "Hello, $p. I have received word from Calia asking that we meet with her once again. She has so much to offer those who feel lost, those seeking a better way. Once she is free of doubt, she will know what must be done. Will you join me?", ["objectivesText"] = "Meet with Calia Menethil and Derek Proudmoore.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 150633, ["x"] = 0.5735, ["y"] = 0.4475 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 156513, ["x"] = 0.6295, ["y"] = 0.5985 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.5735, ["y"] = 0.4475 }, ["mapCandidates"] = { ["npc"] = { 18, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 942, ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57326] = { ["id"] = 57326, ["name"] = "Prototypes for Profit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57326 }, ["description"] = "< Gazlowe pulls you in close and whispers.> Lookit here, <name>. I gotta keep my nose clean here in front of the prince. But I trust you know what's gotta be done outside of town, yeah? Outside of town... where all the tech is... Tech that Alliance grubs are tryin' to get their clumsy mitts on... which we could use for the Horde... to build big weapons... and scary robots... and other lucrative products...? I don't gotta spell this out for you, right?", ["objectivesText"] = "Collect 150 Prototype Implants in Mechagon , while in War Mode. Progress: This place is teemin' with tech. Betcha can find prototypes anywhere.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 168258, 169610, 171248 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150567, ["x"] = 0.74, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150567, ["x"] = 0.74, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.74, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
[57327] = { ["id"] = 57327, ["name"] = "Prototypes for Inspiration", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57327 }, ["description"] = "<Overspark pulls you in close and whispers.> As the leader of this momentous expedition, I must stay with Prince Erazmin to ensure he's not swindled by this Horde hooligan. But I cannot stop my research, or the Horde will gain the advantage! Underlings like yourself must collect the technology samples required to fuel my legendary brainstorms. Bring me prototypes from the island, and I will turn them into groundbreaking new innovations for the Alliance!", ["objectivesText"] = "Collect 150 Prototype Implants in Mechagon , while in War Mode. Progress: I don't care where you get the prototypes from. Take them from Gazlowe's thugs if you have to.", ["rewardGold"] = 257400, ["rewardXP"] = 1415, ["rewardItems"] = { 166846, 169114, 169610, 171248 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150282, ["x"] = 0.739, ["y"] = 0.366 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150282, ["x"] = 0.739, ["y"] = 0.366 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.739, ["y"] = 0.366 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 5672 }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462 },
