[57362] = { ["id"] = 57362, ["name"] = "Deeper Into the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57373, 57374, 58634 }, ["description"] = "This recent change of events allows us to continue our journey to discover what darkness lies beyond the sands. It will not be easy, <name>. We stand on the precipice of the unknown, but now the tables have turned. < Wrathion glances at your new attire.> You do dress the part. Let's see what insights your return to the Halls of Origination bring to light.", ["objectivesText"] = "Speak with MOTHER to return to the Halls of Origination in Uldum to discover the source behind the anomaly. Progress: I await your return.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 62849, 62850, 62851, 131640, 169223 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 23, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 22, ["flags"] = 0 } } },
