[57373] = { ["id"] = 57373, ["name"] = "Descending Into Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57362, 57374, 58634 }, ["description"] = "As unfortunate as the spreading corruption may seem, I believe it provides us the opportunity to prepare for what lies ahead. Locate one of these incursions and see what happens when you peer beyond the dark veil.", ["objectivesText"] = "Seek out a Vision of N'Zoth amidst the corruption in Vale of Eternal Blossoms or Uldum to discover what the future holds for Azeroth.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 49623, 169223, 171312, 173431, 173439, 173447, 173455, 173812, 173815, 173818, 173821, 174491 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 6, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 24, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 23, ["flags"] = 0 } } },
[57374] = { ["id"] = 57374, ["name"] = "Into the Darkest Depths", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57362, 57373, 58634 }, ["description"] = "With our connection secured, it is time for us to breach the veil and discover what lies beyond. What you find may provide us the key to unlocking our success.", ["objectivesText"] = "Enter a Horrific Vision to discover what dark manifestations await in a world ruled by N'Zoth. Progress: Your expertise in these matters are invaluable.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173363 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 7, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 26, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 25, ["flags"] = 0 } } },
[57376] = { ["id"] = 57376, ["name"] = "The Hidden Need", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 862, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "Because of Sylvanas, some members of the Horde are skeptical of the Forsaken. We must regain their trust. We cannot do that without accepting ourselves. So many feel lost, alone... abandoned. I have arranged a meeting. It could be a big step... or all go horribly wrong. Either way, you should bear witness. Meet me in Tirisfal Glades , at the Calston Estate.", ["objectivesText"] = "Meet Lilian Voss in Tirisfal Glades .", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 141961, ["x"] = 0.584, ["y"] = 0.626 } }, ["ends"] = { { ["mapID"] = 18, ["npcID"] = 157230, ["x"] = 0.435, ["y"] = 0.532 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.626 }, ["mapCandidates"] = { ["npc"] = { 18, 862 }, ["zone"] = { 8670 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiUiMapID"] = 18, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 18, ["flags"] = 0 } } },
[57378] = { ["id"] = 57378, ["name"] = "Remnants of a Shattered World", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57378 }, ["description"] = "The knowledge gained from these visions affords us a unique opportunity to further protect one's mind from corruption. To continue our research, we must investigate the deeper mysteries of these experiences. Seek out those of power within these visions. Should you come across anything of interest do not hesitate to share your findings. In the meantime, MOTHER and I shall continue our research here in the chamber. We await your return, <name>.", ["objectivesText"] = "Recover a copy of \" The Curse of Stone \" from a Horrific Vision for Wrathion in the Chamber of Heart. Progress: Find anything of interest?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 120257, 142406, 171335, 174777 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57391] = { ["id"] = 57391, ["name"] = "Reconstructing \"The Curse of Stone\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57391 }, ["description"] = "I came across several references to this book in my research of Ny'alotha. Penned by a neophyte cultist, it documents the \"lies of the Titans\" and the \"injustices\" they inflicted upon the denizens of Azeroth. Mad ravings, intended to erode the reader's acceptance of reality. Still, by studying this work, we can gain a better understanding of the Old God's power, and thus tailor the cloak to offer better protection against it. Bring as many pages from this tome as you can find.", ["objectivesText"] = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: What have you been able to find?", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171335, 171353 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57392] = { ["id"] = 57392, ["name"] = "Reconstructing \"The Curse of Stone\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57392 }, ["description"] = "Thus far, the contents of this book are unsettling to say the least. Nevertheless, I have been able to glean valuable information on the nature of N'Zoth's power, and have made alterations to your cloak accordingly. There remains much to learn, however. Continue your search for additional pages as you delve into the visions.", ["objectivesText"] = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: Urgent matters require a great deal of attention. Unless it is of the utmost importance, I must see to my work.", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 169223, 171335, 171353, 173363 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57393] = { ["id"] = 57393, ["name"] = "Stepping Through the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57393 }, ["description"] = "By now you've noticed the protection of your cloak wavering the deeper you delve into these visions. To further bolster your resistance to N'Zoth's influence, we will need to gain an even deeper understanding of his nefarious power. Seek out knowledge from manifestations deeper within the visions, and we shall have our answers soon enough.", ["objectivesText"] = "Recover a copy of \" Fear and Flesh \" from the depths of a Horrific Vision for Wrathion in the Chamber of Heart. Progress: Dark and deep are the shadows.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 171354, 174782 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57394] = { ["id"] = 57394, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57394 }, ["description"] = "Another tome written by one lost to N'Zoth's madness. I dread to think of what vile words await us within it. But if we are to strengthen your cloak, then we must know more of that which it was meant to resist. See if you can find the remaining pages so that we can complete this tome and make use of the knowledge it holds.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: The missing pages must reside deeper within these visions. As dark and difficult these times may seem, we mustn't forget the possibility remains of a time of great success and discovery.", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 173363, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57395] = { ["id"] = 57395, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57395 }, ["description"] = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing. Naturally, it omits any mention of what occurs when their corruption is allowed to run unfettered. Gather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Anything to share?", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57396] = { ["id"] = 57396, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57396 }, ["description"] = "Adherents of the Old Gods maintain that flesh is a gift, not a curse. This tome reflects on the Old Gods' supposed benevolence in granting us such a generous blessing. Naturally, it omits any mention of what occurs when their corruption is allowed to run unfettered. Gather more of these pages for me. As wretched as these words might be, studying them will allow us to increase the efficacy of your cloak.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Nearly halfway there, <name>. Have you found anything new?", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57397] = { ["id"] = 57397, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57397 }, ["description"] = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair. But you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy. Continue to collect the pages of this book. We have nearly finished piecing it back together.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: The darkness lingers. Never hurried. Never sleeping. Patiently waiting...", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 169223, 171354, 173363, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57398] = { ["id"] = 57398, ["name"] = "Walking in the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57398 }, ["description"] = "The end nears. The darkest corners of these visions await. Our work has ensured you are well equipped to seek out the most horrific manifestations these visions have to offer. The final answers lie just beyond. Our preparations for Ny'alotha are nearly complete.", ["objectivesText"] = "Recover a copy of \" The Final Truth \" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: I await your return.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 171355, 174784 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57399] = { ["id"] = 57399, ["name"] = "Reconstructing \"The Final Truth\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57399 }, ["description"] = "I know of this book. It is a sacred tome to those who worship the Old Gods, containing the deepest secrets and most incomprehensible mysteries of the Void. Only the most devout cultists are allowed to gaze upon its pages. Even incomplete, holding it makes my skin crawl. I must take care not to read too much of it in a single sitting. That being said, we must find its missing pages in order to continue our research. Retrieve them from the darkest corners of N'Zoth's visions.", ["objectivesText"] = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: I often find my own thoughts wandering, weary of what lies ahead. How are you faring, <name>? Have you any news?", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171355, 174785 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57400] = { ["id"] = 57400, ["name"] = "Reconstructing \"The Final Truth\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57400 }, ["description"] = "I dare not repeat aloud the horrors that are recorded in these pages. The words themselves seem to shift and morph as I read them, as if the book itself is attempting to induce a descent into madness. This is taxing work, but it is necessary if we are to fully prepare you for the dangers of Ny'alotha. For as disturbing as its descriptions might be, setting foot within it will prove more challenging by an order of magnitude. Keep looking for pages from the book, <name>. But... leave the reading to me.", ["objectivesText"] = "Collect Torn Pages of \"The Final Truth\" from Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Your success has brought us this far, <name>. Perhaps you have something to share?", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171355, 174785 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57402] = { ["id"] = 57402, ["name"] = "Reconstructing \"The Curse of Stone\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57402 }, ["description"] = "N'Zoth is nothing if not subtle and insidious. I can see how an impressionable mind could be turned against the Titans by reading these words. Thankfully, we are not so susceptible to such manipulation, are we? The book is nearly complete. Continue retrieving its pages from within the visions.", ["objectivesText"] = "Collect Torn Pages of \"The Curse of Stone\" from Horrific Visions for Wrathion in the Chamber of Heart. Progress: I believe we are on the precipice of a something grand.", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171335, 171353 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57403] = { ["id"] = 57403, ["name"] = "Reconstructing \"Fear and Flesh\"", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57403 }, ["description"] = "Perhaps the most insidious element of the Old Gods' whispers is that they contain within them the smallest kernel of truth. There is something to be said for the joy that comes with feeling the sun on one's skin and the wind in one's hair. But you have braved N'Zoth's visions. You have seen where their designs are ultimately meant to lead. The curse of flesh has nothing to do with bringing us joy. Continue to collect the pages of this book. We have nearly finished piecing it back together.", ["objectivesText"] = "Collect Torn Pages of \"Fear and Flesh\" from Corrupted or Lost Areas within Horrific Visions for Wrathion in the Chamber of Heart. Progress: Making progress?", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["rewardItems"] = { 171354, 174783 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
[57448] = { ["id"] = 57448, ["name"] = "New Allies Among Us", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Even in times of peace, the Horde is not without its problems. Although they can be overwhelming at times, our struggles should never stop us from remembering what it means to be a part of the Horde. We don't turn people away when times get tough; we band together and endure. For a moment I forgot this. Burdened by the troubles facing our new allies, I hastily dismissed the vulpera. My only hope is that they still see as much value in the Horde as I see in them.", ["objectivesText"] = "Witness Baine welcome the vulpera into the Horde.", ["rewardGold"] = 509400, ["rewardXP"] = 8200, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 145424, ["x"] = 0.485, ["y"] = 0.715 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 157693, ["x"] = 0.4848, ["y"] = 0.7172 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.715 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 24, ["flags"] = 0 } } },
[57462] = { ["id"] = 57462, ["name"] = "Dream Catcher", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57275, 57462, 57464 }, ["series"] = { 57276, 57464 }, ["description"] = "It appears that the focus remains stable, and its containment field remains intact. I daresay we can empower it even further. Hunt down and defeat formidable enemies to acquire additional remnants of N'Zoth's influence. This time, we will infuse the focus with even greater amounts of the Old God's power. I am confident that the containment field will continue to hold.", ["objectivesText"] = "Acquire 200 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: Fortune favors the bold, <name>. And few acts are as bold as wielding the power of an Old God.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 169223, 170553, 171176, 171312, 171320 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "profession", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1031, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 1032, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (H)", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57464] = { ["id"] = 57464, ["name"] = "Maintaining Focus", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57275, 57462, 57464 }, ["series"] = { 57276, 57462 }, ["description"] = "At present, the focus holds but a fraction of N'Zoth's true power. If we further empower it, we could craft even more effective weapons to wield against him. N'Zoth's influence is everywhere, <name>, and is most concentrated within powerful foes. Vanquish them and claim whatever vestiges of the Old God's power remain.", ["objectivesText"] = "Acquire 20 Shred of Insanity . These can be looted from bosses in Ny'alotha and World Bosses, obtained by winning Battlegrounds and Arenas, or from Honorable Kills. Progress: We are embarking on a dangerous gambit, <name>. Caution is of the utmost importance.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 171176 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "profession", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1031, ["name"] = "8.3 Professions - Tier Gear Spell Focus - (A)", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57486] = { ["id"] = 57486, ["name"] = "Waning Energy", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["series"] = { 57487, 58214 }, ["description"] = "Mekkatorque's pod is powering down. We are no longer able to hear him speak. His pulse has slowed, in spite of the best efforts of Kul Tiran healers. I have an idea, but I am going to need your help. Meet me at Proudmoore Keep. We must go soon.", ["objectivesText"] = "Meet Kelsey Steelspark at Proudmoore Keep.", ["rewardGold"] = 32800, ["rewardXP"] = 685, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 160101, ["x"] = 0.73, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 157997, ["x"] = 0.37, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57487] = { ["id"] = 57487, ["name"] = "Someone Who Can Help", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1161, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["series"] = { 57486, 58214 }, ["description"] = "I believe there is a way to help Mekkatorque, but some may not be a hundred percent on board... The mechagnomes have advanced techniques in biomechanical repair and improvements. If there is even a chance they can help him, we have to try! There are some mechagnomes sending supplies out to the island from a dock in Hook Point. No one will notice one more piece of cargo. We need to reroute one of their homing copters . Will you please help me get Mekkatorque's Pod to Mechagon?", ["objectivesText"] = "Help Kelsey move Mekkatorque's Escape Pod to Mechagon. Progress: How can I help?", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 157997, ["x"] = 0.37, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 149816, ["x"] = 0.72, ["y"] = 0.3495 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 1161, 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57488] = { ["id"] = 57488, ["name"] = "The Current Schematic", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "I think I can modify one of our existing devices to give us access to Gelbin Mekkatorque without disturbing his life preserving functions. There are some items I will need you to procure. From the nearby vector of the Heaps, you will find scrapbots and scraphounds. These would be a fine source of spare parts for my construction project. The Outflow is home to some particularly slimy friends. From them, you will find excellent ingredients for the heat resistant lubricant we need.", ["objectivesText"] = "Collect 4 Heat Tolerant Ooze and 6 Acquisitioned Machine Parts . Progress: Were all assets found?", ["rewardGold"] = 341600, ["rewardXP"] = 5465, ["rewardItems"] = { 172521, 172522 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.73, ["y"] = 0.335 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57490] = { ["id"] = 57490, ["name"] = "Voyage to Safety", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "One of our defenders saw the troggs take out the homing copter carrying Mekkatorque's pod. Since we started bringing goods in from Tiragarde, they have been a real thorn in our side. Piston, a very promising young inventor, has a vehicle able to handle this task. Meet his crew down in Bondo's yard. Please hurry and retrieve the pod! I am not sure what will happen to Gelbin, if they break it open. Ahem, we would not be upset if you did a little beach clean-up while you were there...", ["objectivesText"] = "Defeat the scavenging troggs and retrieve Mekkatorque's Escape Pod . Progress: Did everyone make it back in one piece?", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 150555, ["x"] = 0.73, ["y"] = 0.335 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.733333, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57491] = { ["id"] = 57491, ["name"] = "Better... Stronger... Less Dead", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "King Mechagon may have been crazy, but his minions did have exemplary robotic creation capabilities. There are a few residual creations wandering Mechagon. Refusing to accept King Mechagon's dethroning. The logical conclusion to defeat is withdrawal, if one remains operational. Some do not excel at logic. They currently bear the latest in technical advancement. I believe retrieving specific pieces from these units would greatly benefit our recovery endeavor.", ["objectivesText"] = "Collect the Neural Accelerator , Omni Electromagnetic Amplifier , and Flux Energized Servos from the erratic units. Progress: Did you acquire the parts we need?", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["rewardItems"] = { 172511, 173026, 173028 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.3275 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 5, ["flags"] = 0 } } },
[57492] = { ["id"] = 57492, ["name"] = "Him?", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "Speak to some of the gnomes in Mechagon, enhanced or otherwise. Of my people, ask what they hope for in a leader of our kind. Of our new friends, ask what they appreciate most about their current leader. From what I have learned thus far, the High Tinker has always led his people by necessity, he never sought or desired the crown. I believe the gnomes should be united once again. I seek a solution that will be most amenable to all. Will you gather the information I need?", ["objectivesText"] = "Gather data from gnomes and mechagnomes in Mechagon. Progress: Have your communications been productive?", ["rewardGold"] = 144600, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.733333, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57493] = { ["id"] = 57493, ["name"] = "Mental Attunement", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "We now have a baseline of who Mekkatorque is, looks like there could be some room for improvement. Your assistance is needed to get him stabilized and synchronized before removing him from his pod. Please position yourself by the Synchroscope . I will make adjustments, you will need to fire the machine when I call.", ["objectivesText"] = "Activate the Synchroscope when Christy tells you to fire. Progress: Did you successfully push the button?", ["rewardGold"] = 170800, ["rewardXP"] = 2735, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.3275 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57494] = { ["id"] = 57494, ["name"] = "A Strong Heart", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "We saw a flare near Junkwatt Depot. The retrieval team has made it out with the power source. We are now forever safe from King Mechagon's Annihilo-tron, its heart will serve a new purpose. This is great news! However, the flare means they have company. Your help will be needed to extricate the team and retrieve the Spark Reactor . Please move with haste, we are so close to completion.", ["objectivesText"] = "Retrieve the Spark Reactor and complete Mekkatorque's procedure. Progress: Are you ready?", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["rewardItems"] = { 173302 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 160232, ["x"] = 0.7325, ["y"] = 0.3275 } }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.3275 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1462, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57495] = { ["id"] = 57495, ["name"] = "The Future of Mechagon", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "Now that Mechagon City has been cleared of its remaining dangers, it may once again be a place of peace and prosperity for gnomes and mechagnomes alike. It is time for me to speak with Prince Erazmin regarding the future of our peoples. It is my sincere hope that we will forge an alliance that will last for generations to come! When you are ready, please join us at the High Tinkertory for a special address.", ["objectivesText"] = "Travel to the High Tinkertory in Mechagon City. Progress: When you are ready, please join us at the High Tinkertory for a special address.", ["rewardGold"] = 30900, ["rewardXP"] = 685, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 159587, ["x"] = 0.7325, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2268, ["db2PoiUiMapID"] = 1573, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 10, ["flags"] = 0 } } },
[57496] = { ["id"] = 57496, ["name"] = "Ascension", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "After everything the mechagnomes have done for us today, it is our duty to return the favor. Let us clear out the rogue creations that remain in Mechagon. With their home returned, Prince Erazmin and his people will have a brilliant path forward. With this team, we will make short work of the remaining King Mechagon loyalists. Let me know when you are ready to roll out!", ["objectivesText"] = "Clear the remaining Mechagon defenders.", ["rewardGold"] = 619600, ["rewardXP"] = 6830, ["rewardItems"] = { 1804, 1805, 1806, 1807, 35900, 35901, 35902, 35903, 124557, 170468, 181743, 184374, 184811, 184812 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 159587, ["x"] = 0.7325, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2268, ["db2PoiUiMapID"] = 1573, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 9, ["flags"] = 0 } } },
[57497] = { ["id"] = 57497, ["name"] = "Propagate the News", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1161, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["description"] = "We wanted to save a life and we have accomplished so much more! We really couldn't have done it without you, <name>. I am so excited about the future of all gnomekind. Head back to Stormwind and share the good news!", ["objectivesText"] = "Update Aysa Cloudsinger in Stormwind.", ["rewardGold"] = 867900, ["rewardXP"] = 8200, ["rewardItems"] = { 174067 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 157997, ["x"] = 0.37, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.37, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 11, ["flags"] = 0 } } },
[57524] = { ["id"] = 57524, ["name"] = "Accessing the Archives", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["description"] = "The information you've gathered has allowed us to better understand these manifestations. I believe MOTHER is waiting to share some of her findings with you.", ["objectivesText"] = "Speak with MOTHER to activate the Titanic Research Archive, then examine the archives. Progress: Do you require assistance?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 171212 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 8, ["flags"] = 0 } } },
[57581] = { ["id"] = 57581, ["name"] = "Plucking Plumes", ["level"] = 15, ["requiredLevel"] = 15, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 3703, ["mapID"] = 111, ["storyline"] = { 57581 }, ["objectivesText"] = "Progress: Skettis's lapdogs still keeps a close watch over us, outcasts. The moment any of us sets foot outside Shattrath we'll be as good as dead. Continue to bring me more feathers as proof of your victory over them.", ["rewardItems"] = { 25719, 28491, 28492, 28493, 28494, 31800 }, ["starts"] = { { ["mapID"] = 111, ["npcID"] = 22429, ["x"] = 0.467641, ["y"] = 0.197897 } }, ["ends"] = { { ["mapID"] = 111, ["npcID"] = 22429, ["x"] = 0.467641, ["y"] = 0.197897 } }, ["coords"] = { ["mapID"] = 111, ["source"] = "quest_giver", ["x"] = 0.467641, ["y"] = 0.197897 }, ["mapCandidates"] = { ["npc"] = { 111 }, ["zone"] = { 3703 } }, ["questType"] = "standard" },
[57620] = { ["id"] = 57620, ["name"] = "Summoning Ritual", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["mapID"] = 1527, ["storyline"] = { 57620 }, ["rewardItems"] = { 174874 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2PoiMapID"] = 2241, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
