[57637] = { ["id"] = 57637, ["name"] = "Disturbance Detected: Firelands", ["level"] = 35, ["requiredLevel"] = 35, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 5723, ["mapID"] = 84, ["storyline"] = { 57637 }, ["description"] = "You're early <name>, I hadn't even sent for you yet. Another temporal disturbance has flared up, this time in the Firelands . If Ragnaros hadn't been dealt with when he was, well, you've already seen one way the end time could turn out. Some intricate time weaving is required to be sure you catch Ragnaros early, but still after whatever is causing the disturbance. Whoever is doing this isn't messing around any more.", ["objectivesText"] = "Relive the siege of the Firelands . Progress: Bring me the temporal anomaly as soon as you can, so we can get back to yesterday's problems tomorrow.", ["rewardGold"] = 325300, ["rewardXP"] = 4790, ["rewardItems"] = { 77067, 77069, 152978, 171721, 172506, 208095 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 158276, ["x"] = 0.746667, ["y"] = 0.183333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 158276, ["x"] = 0.746667, ["y"] = 0.183333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.746667, ["y"] = 0.183333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 5723 } }, ["questType"] = "standard" },
[57638] = { ["id"] = 57638, ["name"] = "Korrak the Bloodrager", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57638 }, ["description"] = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew. We must show them our might! We have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager , tends to remain hidden until given a reason to make his presence known. Death to Korrak would mean death to Winterax Clan! Slay him and return.", ["objectivesText"] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Dun Baldar. Progress: Be warned, soldier: The Frostwolf also hunt for Korrak.", ["rewardGold"] = 842700, ["rewardXP"] = 2125, ["rewardItems"] = { 18150, 172119, 172121, 172122, 172123, 172125, 172135, 172139 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "raid" },
[57639] = { ["id"] = 57639, ["name"] = "The Legend of Korrak", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57639 }, ["description"] = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power. They are lead by Korrak the Bloodrager - a cruel and cunning beast. A strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!", ["objectivesText"] = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley. Should Korrak make himself known, destroy him and return to Warmaster Laggrond . Progress: Be warned, soldier, the Stormpike also hunt for Korrak.", ["rewardXP"] = 2125, ["rewardItems"] = { 18149, 172121, 172122, 172123, 172125, 172139 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "raid" },
[57640] = { ["id"] = 57640, ["name"] = "Master Ryson's All Seeing Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57640 }, ["description"] = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you. <Master Ryson grins.>", ["objectivesText"] = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57641] = { ["id"] = 57641, ["name"] = "Master Ryson's All Seeing Eye", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57641 }, ["description"] = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike. That, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region. Recover the Eye and our services shall be yours - for whatever time remains for your side. Return to me once you acquire the eye so that I may examine you. <Master Ryson grins.>", ["objectivesText"] = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson. Be warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", ["rewardItems"] = { 17224, 17363, 17364 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
