[57670] = { ["id"] = 57670, ["name"] = "Unbeelievable Quality", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9042, ["mapID"] = 942, ["storyline"] = { 57670 }, ["description"] = "<Now that your harvester has matured, the Honeyback hive is creating additional honey. Someone in Brennadam could certainly find a use for this honey.>", ["objectivesText"] = "Take the Collected Tidebloom Honey to \"Nasty\" Buck in Brennadam. Provided item:", ["rewardGold"] = 234000, ["rewardItems"] = { 159847, 168825, 168828, 169106, 172383 }, ["ends"] = { { ["mapID"] = 942, ["npcID"] = 138221, ["x"] = 0.586, ["y"] = 0.704 } }, ["coords"] = { ["mapID"] = 942, ["source"] = "quest_giver", ["x"] = 0.586, ["y"] = 0.704 }, ["mapCandidates"] = { ["npc"] = { 942 }, ["zone"] = { 9042 } }, ["questType"] = "standard", ["startItems"] = { 172383, 173533 } },
[57686] = { ["id"] = 57686, ["name"] = "The Eternal Traveler", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10413, ["mapID"] = 47, ["storyline"] = { 57686 }, ["description"] = "Hail, mortal. For untold ages, my kind has traversed the myriad realms of reality. We have beheld phenomena that you cannot begin to comprehend. But there is much you must learn of what awaits you on the horizon. The power of Death is on the rise. The veil weakens between your world and the Shadowlands. When a mortal life expires, an echo of it remains behind. The most powerful mortals leave the most resonant echoes. Bring these to me, that I might study them... to both our benefits.", ["objectivesText"] = "Gather Echoes of Mortality from living creatures. Progress: One can glean so much knowledge from the mortal realm.", ["rewardGold"] = 702000, ["rewardXP"] = 10225, ["rewardItems"] = { 46016, 172954 }, ["starts"] = { { ["mapID"] = 47, ["npcID"] = 158635, ["x"] = 0.6937, ["y"] = 0.3752 } }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 158635, ["x"] = 0.475625, ["y"] = 0.234687 } }, ["coords"] = { ["mapID"] = 47, ["source"] = "quest_giver", ["x"] = 0.6937, ["y"] = 0.3752 }, ["mapCandidates"] = { ["npc"] = { 1, 47 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[57718] = { ["id"] = 57718, ["name"] = "Bound in Stone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57718 }, ["description"] = "Some of our warriors were camped in the small settlement near Guo-Lai when the Baruk invaded the area. Some managed to escape, but they returned with tales of their brothers and sisters in arms being petrified by the mogu stoneshapers into living statues! We can't leave our warriors behind! The stoneshapers must carry some means to reverse the spell and free them from their stone prisons. Bring our soldiers back!", ["objectivesText"] = "Collect Stoneshaper Rods from Baruk Stoneshapers and use them to free 5 Petrified Warriors in the Ruins of Guo-Lai.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 170497 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[57720] = { ["id"] = 57720, ["name"] = "Champions of the Mogu", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57720 }, ["description"] = "These lesser clans warring with each other in the Vale need to be taught their place. Seek out their champions and eliminate them. Show them that only the Rajani have rightful claim here!", ["objectivesText"] = "Defeat 3 rare enemies while the Mogu are invading the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[57721] = { ["id"] = 57721, ["name"] = "Spoils of War", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57721 }, ["description"] = "The warring clans are relentless and our warriors are going through armor faster than I can keep it repaired. If you find yourself in battle with the other clans, see if you can salvage any undamaged armor pieces from their soldiers. We should not let good resources go to waste.", ["objectivesText"] = "Collect 12 pieces of Salvaged Mogu Armor from mogu enemies in the Vale of Eternal Blossoms . Progress: What have you managed to salvage, outsider?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 64569, 64570, 64571, 64572, 64573, 64574, 64575, 64576, 64577, 64578, 64579, 64580, 172463 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[57722] = { ["id"] = 57722, ["name"] = "Empty Stables", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57722 }, ["description"] = "Just look at the stables, <name>! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct. You must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable. When we have enough rams, the ram rider commander will be notified. With your help, the cavalry will be reborn!", ["objectivesText"] = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture. Progress: Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!", ["rewardItems"] = { 17689 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "standard" },
[57723] = { ["id"] = 57723, ["name"] = "Empty Stables", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57723 }, ["description"] = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces! If we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle. Take this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable. When we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", ["objectivesText"] = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master . Speak with the Frostwolf Stable Master to earn credit for the capture. Progress: Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!", ["rewardItems"] = { 17626 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "standard" },
[57728] = { ["id"] = 57728, ["name"] = "Assault: The Endless Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 57728 }, ["description"] = "The mantid swarm is surging! There's no way the Golden Lotus will be able to handle this many of them. We must do something to drive them back!", ["objectivesText"] = "Drive back the Mantid Assault in the Vale of Eternal Blossoms . Progress: Are you with me?", ["rewardXP"] = 10225, ["rewardItems"] = { 174959 }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2Objectives"] = { { ["text"] = "Cull the mantid swarm", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[57730] = { ["id"] = 57730, ["name"] = "Zinfizzlex's Portable Shredder Unit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57730 }, ["description"] = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.", ["objectivesText"] = "Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars . *50 Mithril Bars . *75 Iron bars . *1 Steamsaw . Progress: Mountain is a technical term. It's a goblin engineer thing...", ["rewardItems"] = { 3575, 3860, 12359, 17384, 17410, 17411 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57731] = { ["id"] = 57731, ["name"] = "Zinfizzlex's Portable Shredder Unit", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10458, ["storyline"] = { 57731 }, ["description"] = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials! To be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill. When I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.", ["objectivesText"] = "Master Engineer Zinfizzlex wants you to bring him the following: *30 Thorium Bars . *50 Mithril Bars . *75 Iron bars . *1 Steamsaw . Progress: Mountain is a technical term. It's a goblin engineer thing...", ["rewardItems"] = { 3575, 3860, 12359, 17384, 17410, 17411 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10458 } }, ["questType"] = "pvp" },
[57737] = { ["id"] = 57737, ["name"] = "Ramkahen Rescue", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 57737 }, ["description"] = "Mar'at was overrun by those foul K'thir before we could safely evacuate our citizens. I fear the worst has happened to them. Please, if anyone is left alive within the city, tell them to come to Ramkahen.", ["objectivesText"] = "Rescue 6 Mar'at Villagers .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57773] = { ["id"] = 57773, ["name"] = "Close to Tears", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 57773 }, ["description"] = "Our warriors have observed foul manifestations coming forth from numerous void tears within the surrounding jungle. They have been but mere weaklings, clearly intended to test our defenses before the real forces arrive. If we do not deal with this threat now, however, it will only be a matter of time until we are overrun by their fodder. Find a way to close those portals!", ["objectivesText"] = "Find and close 3 Void Tears in Uldum . Progress: Have you had any luck with the portals yet?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57774] = { ["id"] = 57774, ["name"] = "Nine Lives", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 57774 }, ["description"] = "Scouts have returned recently, nearly on the verge of death, with reports that I find... disconcerting. Neferset have been spotted wandering the streets of their city to the south. This would normally be no cause for alarm, except the Neferset were completely wiped out. I must ask you to investigate further... and if by some foul magic these reports turn out to be true, you must do whatever you can to contain this threat!", ["objectivesText"] = "Destroy 8 Neferset Denizens . Progress: Have you news of Neferset City?", ["rewardGold"] = 331700, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
