[57853] = { ["id"] = 57853, ["name"] = "Battleforged Team", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["storyline"] = { 57853 }, ["rewardItems"] = { 137642 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[57873] = { ["id"] = 57873, ["name"] = "Word from Orsis", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "As you can see, <name>, we have our hands full here dealing with these disgusting bugs. Our caravans from the south have stopped arriving and we have received disturbing news from the few who've made it back recently. I've sent a patrol toward Orsis to investigate; they are past due for a report back. Can I ask you to check in on them for me?", ["objectivesText"] = "Investigate the situation in Orsis.", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 154958, ["x"] = 0.408, ["y"] = 0.385 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 0, ["flags"] = 0 } } },
[57915] = { ["id"] = 57915, ["name"] = "Search for Survivors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "The bugs came from everywhere... There wasn't any time to react. Many of my friends died where they stood, while others tried to fight with our meager tools. I'm a coward. I fled in the commotion instead of trying to help. Now, here I am, out of food and water and too scared to look for survivors. Please, I beg you to help anyone you find left alive in Orsis...", ["objectivesText"] = "Check 8 Wastewanders in Orsis.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 154958, ["x"] = 0.408, ["y"] = 0.385 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159560, ["x"] = 0.4, ["y"] = 0.452 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.385 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 1, ["flags"] = 0 } } },
[57954] = { ["id"] = 57954, ["name"] = "Burn the Bodies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "The bugs seem to be indiscriminately laying eggs all over the nearby corpses. They are using them as food to spawn more of those horrible things. Disgusting! We can mourn the dead later, but if any more bugs are allowed to hatch we may not live long enough to do so. Burn the bodies and destroy those eggs!", ["objectivesText"] = "Burn 10 Egg-bearing corpses.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174323 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 3, ["flags"] = 0 } } },
[57955] = { ["id"] = 57955, ["name"] = "To Ankhaten Harbor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "I fear that I don't yet have the strength to ride out into the sands and face those monsters again. Ride to the south and find Tracker Samara in the excavation camp formerly known as Schnottz's Landing. Tell her to halt any caravans that plan to pass this way, lest others are ambushed and met with the same grisly fate. We must get the word out across Uldum before our forces are further divided!", ["objectivesText"] = "Find Tracker Samara in Ankhaten Harbor.", ["rewardGold"] = 140450, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159560, ["x"] = 0.4, ["y"] = 0.452 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.452 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 2, ["flags"] = 0 } } },
[57956] = { ["id"] = 57956, ["name"] = "Wastewander Hosts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "The bugs have been laying eggs in the corpses of our soldiers, it's absolutely terrifying! Some of them are rising from the ground as putrid, bloated, hideous monstrosities. We have to stop them before they continue to bolster their ranks with our fallen. It's not a pleasant task... but I have to ask you to help me destroy them. Completely. Grab some bombs behind me, if you'd like.", ["objectivesText"] = "Kill 6 Wastewander Hosts .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174325 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 4, ["flags"] = 0 } } },
[57959] = { ["id"] = 57959, ["name"] = "Heroic Warfront: The Battle for Darkshore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8670, ["mapID"] = 1165, ["storyline"] = { 57959 }, ["description"] = "Darkshore belongs to the Horde! We must hold that ground to maintain our dominance over Kalimdor. Prepare yourselves. Battle awaits!", ["objectivesText"] = "Defeat the Alliance at the Battle for Darkshore.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 166369, 166370 }, ["starts"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["ends"] = { { ["mapID"] = 1165, ["npcID"] = 138949, ["x"] = 0.528, ["y"] = 0.945 } }, ["coords"] = { ["mapID"] = 1165, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.945 }, ["mapCandidates"] = { ["npc"] = { 1165 }, ["zone"] = { 8670 } }, ["questType"] = "standard" },
[57960] = { ["id"] = 57960, ["name"] = "Heroic Warfront: The Battle for Darkshore", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 57960 }, ["description"] = "We will not tolerate further Horde aggression in our territories. The night elves will not stand alone this day. Darkshore will be theirs once more. For the Alliance!", ["objectivesText"] = "Defeat the Horde at the Battle for Darkshore.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 158075, 166369, 166370 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 142721, ["x"] = 0.66, ["y"] = 0.26 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.26 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
