[57968] = { ["id"] = 57968, ["name"] = "The Wastewandering Dead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 57968 }, ["description"] = "Is there no end to these foul monsters!? I cannot abide the desecration of our dead, especially not as fodder for this disgusting insect army. Destroy as many as you can, preferably with fire!", ["objectivesText"] = "Kill 6 Wastewander Hosts . Progress: I hope you've been keeping count of your kills.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[57969] = { ["id"] = 57969, ["name"] = "Tend the Wounded", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "My friend, as you can see here, we are besieged by these terrible creatures. Many of our comrades have fallen prey to the monsters, but fortunately, we have enough warriors here to keep the threat at bay... for now. If you are able to assist us, please, tend to our wounded and help clear a path for them to escape the ruins.", ["objectivesText"] = "Heal 8 Wastewander Laborers .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174326 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 6, ["flags"] = 0 } } },
[57970] = { ["id"] = 57970, ["name"] = "Ruinator Xok'nixx", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "Ar'kali and a group of our warriors are engaged with a most behemothic creature in the heart of the ruins. She can hold her own against nearly any foe, but I fear it is only a matter of time before this monster is able to wear them down. Although the creature is occupied for now, if our warriors fall, the ruins will be lost to us. Please, make haste, with your help they can surely fell this titanic foe.", ["objectivesText"] = "Kill Ruinator Xok'nixx .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2241, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 7, ["flags"] = 0 } } },
[57971] = { ["id"] = 57971, ["name"] = "Ruins of Ammon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "These things seem to be everywhere and all at once! Either this was an organized attack, or there are far more of them than we can even comprehend. Regardless, this is bad for us... really, really bad. $p, I need you to travel to the Ruins of Ammon and find out what the situation is like over there. If they need help, please try to lend a hand!", ["objectivesText"] = "Travel to the Ruins of Ammon.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159682, ["x"] = 0.245, ["y"] = 0.552 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.245, ["y"] = 0.552 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 5, ["flags"] = 0 } } },
