[57990] = { ["id"] = 57990, ["name"] = "Obelisk of the Sun", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "I have one more thing I must ask of you, my friend. Completion of this task is critical to our survival here. Our comrade, Zahra, has taken it upon herself to climb the plateau just east of us to secure one of the old bombers left up there. So far, our attempts to get word back to Arik have failed. However, if you can help her get one of those planes working, we might just have a chance. Hopefully they can send aid before we are overrun...", ["objectivesText"] = "Locate Exterminator Zahra at the Obelisk of the Sun.", ["rewardGold"] = 110640, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159820, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2241, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58008] = { ["id"] = 58008, ["name"] = "All Gassed Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "So, I was checkin' all these planes... and you are never gonna believe this, but none of them have any fuel in the tanks! Saw a few canisters scattered around nearby, surely some a' them have some gas left. Was gonna collect 'em myself, but these damned bugs came outta nowhere and started swarmin' the place. Too many here now to deal with on my own, think you'd be able to lend a hand?", ["objectivesText"] = "Collect 6 Fuel Canisters . Progress: Yo, you got them fuel cans yet?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 173366 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 9, ["flags"] = 0 } } },
[58009] = { ["id"] = 58009, ["name"] = "To the Moon", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 56576, 57873, 57915, 57954, 57955, 57956, 57969, 57970, 57971, 57990, 58008, 58009 }, ["description"] = "Alright! It's time to high tail it outta here. We gotta get back to camp and tell Arik what's been going on out here as soon as possible. Head for the bomber and let's fuel 'er up. I'll letcha have the gunner seat, but I'm drivin', so let's try to blow up a few bugs on the way back!", ["objectivesText"] = "Remove the Aqir threat from Obelisk of the Moon.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 6710, 21100, 21746, 24103, 24104, 24105, 27686, 58924, 58925, 58926, 60928, 60929, 60930, 106175, 107307, 107312, 107317, 131274, 131504, 131597, 140847, 141943, 142054, 176112, 237812, 245258, 245624 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1016, ["name"] = "Aqir Offensive", ["orderIndex"] = 11, ["flags"] = 0 } } },
[58010] = { ["id"] = 58010, ["name"] = "More Bits, More Bits!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58010 }, ["description"] = "We need more Aqir samples, $p. As many as you can get your hands on! I've made some fascinating discoveries already, but there's so much more to learn. With further study and a bit of good luck, perhaps we can slowly begin to uncover some of their weaknesses.", ["objectivesText"] = "Collect 16 Aqir Bits . Progress: Have you obtained any additional samples?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174356 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58087] = { ["id"] = 58087, ["name"] = "Destroying the Source", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 862, ["storyline"] = { 53870, 53889, 53890, 53891, 53892, 53893, 53894, 53895, 53897, 53898, 53899, 53900, 53901, 53902, 53903, 53904, 53905, 53906, 53907, 53908, 54026, 54027, 54036, 57448, 58087 }, ["description"] = "Tidecaller Nezara is running the show. If we take her out, the remaining naga will break rank, but getting to her won't be easy. She's protected by a magical barrier that's drawing power from powercells nearby. If we can destroy the source, we can destroy Nezara.", ["objectivesText"] = "Destroy 3 Nazeshi Powercells within Dreadpearl Shallows.", ["rewardGold"] = 309800, ["rewardXP"] = 5465, ["rewardItems"] = { 173727, 174066 }, ["starts"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 145980, ["x"] = 0.748, ["y"] = 0.63 } }, ["coords"] = { ["mapID"] = 862, ["source"] = "quest_giver", ["x"] = 0.748, ["y"] = 0.63 }, ["mapCandidates"] = { ["npc"] = { 862 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 862, ["questLines"] = { { ["id"] = 796, ["name"] = "Allies of the Horde: Vulpera", ["orderIndex"] = 14, ["flags"] = 0 } } },
[58096] = { ["id"] = 58096, ["name"] = "Supplies from the Rajani", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58096 }, ["description"] = "The Rajani appreciates all the help you've given us. Please take these supplies as a token of our gratitude, and a promise of more to come, should you continue to help us.", ["objectivesText"] = "Speak with Zhang Ku in Vale of Eternal Blossoms for your reward.", ["rewardItems"] = { 174483 }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 160711, ["x"] = 0.444, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.444, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2416, ["threshold"] = 10000 } } } },
