[58122] = { ["id"] = 58122, ["name"] = "For the Horde", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 35 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 58122, 58124 }, ["description"] = "What an adventure, <class>! There is so much to explore... so much to discover. These are such exciting times! We'll show our allies in the Horde the value of having some clever Vulpera around. Please meet with the ambassador at the Orgrimmar embassy. I'll meet you there, <name>!", ["objectivesText"] = "Meet Ambassador Blackguard at the Orgrimmar Embassy.", ["rewardGold"] = 28900, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 29928, 29930, 29931, 29934, 29938, 29941, 29943, 29945, 37956, 37964, 37998, 38006, 38041, 38048, 38081, 38102, 38110, 57509, 57510, 57511, 57512, 65680, 65701, 65719, 65728, 66073, 94220, 111535, 111536, 111537, 111538, 111539, 111540, 111541, 111542, 116202, 118761, 118762, 118763, 118764, 118765, 131486, 131696, 131697, 151557, 155662, 157028, 157757, 157759, 161328, 165001, 165871, 166883, 167169, 168615, 168850, 169765, 174069, 174508, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 160452, ["x"] = 0.566, ["y"] = 0.577333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.577333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1042, ["name"] = "Allies of the Horde", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58124] = { ["id"] = 58124, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredRaces"] = { 35 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 58122, 58124 }, ["description"] = "Hi. I'm Ambassador Blackguard . I am honored to welcome you to Orgrimmar, <race>. <He smiles unconvincingly.> As a lifetime of adventure unfolds before you, be assured that... uh... You know what? I've been saying this same greeting all day. Enough's enough. Talk to Chromie on top of the hourglass, then talk to your emissary. Run along.", ["objectivesText"] = "Talk to Chromie . Progress: This city is huge!", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 133407, ["x"] = 0.395, ["y"] = 0.794 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 160452, ["x"] = 0.566, ["y"] = 0.577333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.395, ["y"] = 0.794 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 1042, ["name"] = "Allies of the Horde", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58146] = { ["id"] = 58146, ["name"] = "For the Alliance", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 37 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 58146, 58147 }, ["description"] = "As High Tinker, and leader of both Gnomes and Mechagnomes, I am proud to welcome you to the Alliance! A world of adventure awaits you beyond the walls of Mechagon City. When you are ready, step on the teleporter. Ambassador Moorgard will be awaiting your arrival at the Stormwind Embassy. There will be many potential avenues of advancement available to you. Choose wisely, improve, and remember to share your data.", ["objectivesText"] = "Meet Ambassador Moorgard at the Stormwind Embassy. Progress: Welcome to Stormwind, <race>.", ["rewardGold"] = 34100, ["rewardXP"] = 175, ["rewardItems"] = { 23002, 23007, 23015, 23022, 37500, 42792, 42805, 42817, 42830, 65618, 65625, 65639, 65642, 66073, 94219, 108908, 108909, 108910, 108912, 108913, 108914, 108918, 108919, 116202, 151557, 157022, 157756, 157758, 161329, 165010, 165872, 166883, 168615, 168850, 169764, 174068, 174507, 204616, 204617, 204618, 204619, 211279, 223907, 237812, 241215 }, ["starts"] = { { ["mapID"] = 1462, ["npcID"] = 159587, ["x"] = 0.7325, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.7325, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 84, 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5405, ["name"] = "Allies of the Alliance", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58147] = { ["id"] = 58147, ["name"] = "Stranger in a Strange Land", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredRaces"] = { 37 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58146, 58147 }, ["description"] = "Welcome to Stormwind, <class>. I invite you to explore our fair city. Say, you look like someone who enjoys the night life. We have many popular taverns and a vibrant music scene! Ah, but that can wait, a bronze dragon has asked to talk to you. She is sitting under the nearby tree, on an hourglass of all things! After that, an emissary of the Mechagnomes is waiting to welcome you to the city. Sounds like a busy day for you! Have a pleasant stay, <name>!", ["objectivesText"] = "Find Chromie in Stormwind City. Progress: So, how does Stormwind suit you?", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 246740, 246795 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 133362, ["x"] = 0.530667, ["y"] = 0.150667 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 160600, ["x"] = 0.5988, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.530667, ["y"] = 0.150667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5405, ["name"] = "Allies of the Alliance", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58151] = { ["id"] = 58151, ["name"] = "Minions of N'Zoth", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1530, ["storyline"] = { 58151 }, ["description"] = "The howling winds that surround us may some day be drowned out, masked by these increasingly dark, yet familiar whispers. Something must be done. Enter the darkness, <name>, and strike down the enemy.", ["objectivesText"] = "Defeat 20 minions of N'Zoth within the vision. Progress: The winds envelop us, comforting, calming... but beneath it all lurks a great, ever-present darkness.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169223, 174288 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 160252, ["x"] = 0.842, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.842, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1527, 1530 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58155] = { ["id"] = 58155, ["name"] = "A Hand in the Dark", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58155 }, ["description"] = "Imagine being trapped in a world you didn't know existed--a reality unbeknownst to even yourself. Thoughts, fears, and dark desires cloud the mind, coupled with irresistible temptation. So many are lost to the darkness, unable to resist these temptations, but not all. Do what you can to preserve those that fight against the darkness. We mustn't allow them to fall.", ["objectivesText"] = "Rescue 8 souls from the vision. Progress: It is best not to linger in darkness.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169223, 174288 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58156] = { ["id"] = 58156, ["name"] = "Vanquishing the Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58156 }, ["description"] = "The darkness grows. The cycle continues. Do what you can to stay N'Zoth's efforts. If we do not stand against the corruption we may some day find ourselves drowning in darkness.", ["objectivesText"] = "Repel N'Zoth's corruption within the vision. Progress: We both know what must be done.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174288 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58167] = { ["id"] = 58167, ["name"] = "Preventative Measures", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58167 }, ["description"] = "Waves of darkness continue their assault on the shores of our world. I am afraid the waters at our feet may soon wash over us. Perhaps it is time for a different approach. Make your way into the twisted realm and seek out their dark portals. If we are able to slow their advance it might just buy us the time needed to expose a fatal weakness.", ["objectivesText"] = "Destroy 3 Void Portals within the vision. Progress: Darkness lurks beneath the waters.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169223, 169293, 173363, 174288 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58168] = { ["id"] = 58168, ["name"] = "A Dark, Glaring Reality", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58168 }, ["description"] = "Their eyes are upon us, <name>, watching every move from the shadows. It is no wonder our efforts thus far have felt... lacking. The fault is by no means your own. We should have suspected this was the case long ago. If we are to continue our efforts with meaningful expectations we must go undetected. Our old friend has offered an elixir to aide in exposing our enemy. While there may be a few... unknown side effects, the result provides the imbiber true sight in the darkness.", ["objectivesText"] = "Defeat 6 Darkglare Watchers within the vision. Progress: Seeing things more clearly?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173810, 174288 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160252, ["x"] = 0.566, ["y"] = 0.318 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.318 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58214] = { ["id"] = 58214, ["name"] = "Urgent Care", ["level"] = 40, ["requiredLevel"] = 40, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 84, ["storyline"] = { 57486, 57487, 57488, 57490, 57491, 57492, 57493, 57494, 57495, 57496, 57497, 58214 }, ["series"] = { 57486, 57487 }, ["description"] = "Excellent timing, <name>. Kelsey Steelspark has been sending communications to the capital cities looking for aid. Mekkatorque's condition is quite dire and time is of the essence. Hurry to Boralus Harbor, she will be watching for you.", ["objectivesText"] = "Find Kelsey Steelspark in Boralus Harbor.", ["rewardGold"] = 32800, ["rewardXP"] = 685, ["rewardItems"] = { 158075 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 126332, ["x"] = 0.5235, ["y"] = 0.1355 }, { ["mapID"] = 1462, ["npcID"] = 149816, ["x"] = 0.72, ["y"] = 0.3495 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 160101, ["x"] = 0.73, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.5235, ["y"] = 0.1355 }, ["mapCandidates"] = { ["npc"] = { 84, 1161, 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 1000, ["name"] = "Allies of the Alliance: Mechagnome", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58229] = { ["id"] = 58229, ["name"] = "A Rallying Cry", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58229 }, ["description"] = "Our lands have been infested by the minions of the Old Gods. They strike at every front, even assailing the very minds of our soldiers. Our forces cannot handle this for long. We must strike a decisive blow to try to salvage some of their morale. Find the biggest, slimiest, tentacle-faced monstrosities that you can and bring them down. My men will rally to your example.", ["objectivesText"] = "Kill 3 rare minions of N'Zoth in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 169303, 174478, 175140, 175142 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58230] = { ["id"] = 58230, ["name"] = "Blind the Eyes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58230 }, ["description"] = "Strange forces have been interfering with my visions of late. The ever-watching eyes pierce through the veil, shattering my clairvoyance. The eyes of our enemy peer into our very souls and pierce our minds. We must rip them out, if we truly wish to be rid of the curse on this land.", ["objectivesText"] = "Kill 6 Foul Observers in the Akhenet Fields in Uldum . Progress: Is it done?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58231] = { ["id"] = 58231, ["name"] = "Wisdom From Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58231 }, ["description"] = "In my visions I hear... voices... Their words are nonsense, but over time patterns arise. I believe there is something important behind what these voices say, but I have yet to decipher a word. We will need to learn from the source. Find any writings you can among the cultists who travel with these dark creatures. Their ramblings may be the key to understanding the message beneath this madness.", ["objectivesText"] = "Collect 10 Maddened Writings from Black Empire Cultists in Uldum . Progress: Have you found the writings?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173954 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58232] = { ["id"] = 58232, ["name"] = "Order Among Chaos", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58232 }, ["description"] = "It has been a long time since the tol'vir have squared off against the forces of an Old God, so our tactical knowledge of their forces is limited. However, one tenet of combat always holds true -- striking down those that issue the orders will weaken the foe much greater than the rank and file. I have observed that the larger faceless minions act as commanders of the Old Gods' forces. Silence them, and perhaps we can sow a different kind of chaos in their ranks.", ["objectivesText"] = "Kill 6 faceless minions of N'Zoth in Uldum .", ["rewardGold"] = 331700, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58233] = { ["id"] = 58233, ["name"] = "Twisted Corruptors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58233 }, ["description"] = "While the fleshbeasts that accompany the invading forces appear to be no more than a nuisance, they carry within themselves a deep connection to the corrupting powers of the Old Gods. Like a pestilence, they spread the N'Zoth's corruption wherever they tread, slowly twisting the very land to their form. They must be eradicated.", ["objectivesText"] = "Kill 10 fleshbeasts in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58234] = { ["id"] = 58234, ["name"] = "Questionable Sourcing", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58234 }, ["description"] = "My clairvoyance provides a great strategic asset to the people of Ramkahen. However, the potency of my visions of late has proven taxing to my health. I have devised a tonic that may serve to dull the harm these visions cause, but it will require the coalesced essence of the Old Gods' corruption. If you could retrieve some samples of this for me, it could prove invaluable in our efforts.", ["objectivesText"] = "Collect 8 Coalesced Corruption from slimes in Uldum . Progress: Have you acquired the reagent?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173956 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58235] = { ["id"] = 58235, ["name"] = "Anchors of the Black Empire", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58235 }, ["description"] = "This invasion struck us without warning, with structures reminiscent of the Black Empire materializing out of nothing, pouring out the forces of the Old Gods. We have no idea how they came to be or where they came from. However, whenever a new structure appears, it is preceded by malefic obelisks. We believe these obelisks act as anchors to usher in more of the Old Gods' forces. If we truly wish to stem the tide of this invasion, we must destroy the obelisks.", ["objectivesText"] = "Destroy 6 Black Empire Obelisks in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58236] = { ["id"] = 58236, ["name"] = "Symbolic Destruction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58236 }, ["description"] = "The cultists that follow this dark legion befoul our lands with symbols of the tyrants they follow. Their mindless followers flock to these banners, worshipping them as unholy idols. Burn them down, and cleanse their taint from our lands.", ["objectivesText"] = "Destroy 6 Banners of the Black Empire in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58237] = { ["id"] = 58237, ["name"] = "Cleansing Uldum", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58237 }, ["description"] = "Every moment that N'Zoth's forces remain in Uldum , his corruption seeps further into the land itself. Even if we were to drive back his minions, the damage he has done to Uldum may be irreversible. We must seek out his corruption where it festers and eliminate it.", ["objectivesText"] = "Destroy 6 Corruption Tumors in Uldum . Progress: We must put a stop to N'Zoth's Corruption.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58238] = { ["id"] = 58238, ["name"] = "Lost and Tormented", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58238 }, ["description"] = "Our citizens here in Ramkahen have managed to escape the brunt of N'Zoth's assault. Our brothers in the Lost City were not so fortunate. Those not immediately slain have been held captive only to be tortured by N'Zoth's minions. I know that you will be taking the fight to N'Zoth's forces. If you can free our allies as well, Ramkahen will be in your debt.", ["objectivesText"] = "Free 6 Ramkahen Citizens from Torment Cells within the Lost City of Tol'vir in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58239] = { ["id"] = 58239, ["name"] = "Lessons in Brigandry", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58239 }, ["description"] = "The Wastewanders have spent many generations as brigands, whether on land or sea. Though we have decided to hang up that life for a chance at a more peaceful existence, we have not forgotten the lessons we've learned in those days. One such lesson I feel is particularly relevant now -- when faced with a superior opponent, it often helps to use their weapons against them. Find their hidden caches and take whatever you can carry. You may just find something that can turn the tide of this battle.", ["objectivesText"] = "Loot 3 Black Empire Caches in Uldum . Progress: Found anything worthwhile?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174758, 174768 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160957, ["x"] = 0.546, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58273] = { ["id"] = 58273, ["name"] = "Servant of N'Zoth", ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 58273 }, ["description"] = "<class>... I have watched you... I have felt your bloodlust. But you serve false prophets... the Horde is an illusion... I am a god! Prove to me you are worthy of my gift... kill those who are to betray you... Kill... the Horde!", ["objectivesText"] = "Use the N'lyeth, Sliver of N'zoth to change your faction from Horde to become devoted to N'Zoth. Then slay 10 Horde players without dying.", ["rewardItems"] = { 174020, 175246 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[58274] = { ["id"] = 58274, ["name"] = "Servant of N'Zoth", ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 58274 }, ["description"] = "<class>... I have watched you... I have felt your bloodlust. But you serve false prophets... the Alliance is an illusion... I am a god! Prove to me you are worthy of my gift... kill those who are to betray you... Kill... the Alliance!", ["objectivesText"] = "Use the N'lyeth, Sliver of N'zoth to change your faction from Alliance to become devoted to N'Zoth. Then slay 10 Alliance players without dying.", ["rewardItems"] = { 174020, 175246 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "pvp" },
[58277] = { ["id"] = 58277, ["name"] = "Dark Deceivers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58277 }, ["description"] = "The Old Gods have many faceless minions at their disposal, but none so deceiving as the ones they call k'thir. Though not nearly as imposing as their brethren, the k'thir manipulate in the shadows, bending the wills of men and even reality itself. We must not allow their machinations to go unchecked.", ["objectivesText"] = "Kill 8 K'thir minions in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58279] = { ["id"] = 58279, ["name"] = "Quartermaster's Bounty", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 58279 }, ["objectivesText"] = "Progress: To defeat the enemy, you will need to keep your equipment in peak condition. If you have been unable to acquire more powerful arms, I can requisition from the quartermaster on your behalf.", ["rewardItems"] = { 172519 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["ends"] = { { ["mapID"] = 862, ["npcID"] = 143555, ["x"] = 0.515, ["y"] = 0.582 }, { ["mapID"] = 1161, ["npcID"] = 143560, ["x"] = 0.563, ["y"] = 0.256 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.563, ["y"] = 0.256 }, ["mapCandidates"] = { ["npc"] = { 862, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[58281] = { ["id"] = 58281, ["name"] = "Ancient Armaments", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58281 }, ["description"] = "Fighting a war on several fronts has taken its toll on our supplies. Our blacksmiths cannot repair and replace our soldiers' armor quickly enough, which is leaving us ill-equipped to face so many foes. Though the Amathet's armor is ancient, it is titan-forged and formidable. If we were able to salvage any, it could prove very useful to our defensive efforts. Can you help?", ["objectivesText"] = "Collect 10 pieces of Amathet Armor from armored Amathet tol'vir in Uldum . Progress: Have you returned with the armor?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 173985 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58282] = { ["id"] = 58282, ["name"] = "Down From the Sky", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58282 }, ["description"] = "The archers of Ramkahen are highly skilled, but the bows of the Amathet have the advantage of range. This makes our incursions into their territory highly dangerous. You have a knack for fighting behind enemy lines. If you could thin out their ranks, it could provide us an opportunity to push their lines back for once. Will you help?", ["objectivesText"] = "Kill 8 Amathet Bowmen in Uldum .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58283] = { ["id"] = 58283, ["name"] = "Blind Leading the Blind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58283 }, ["description"] = "The Sun Priests are an ancient order for the tol'vir who have walked among all of the tribes. Those that follow the Amathet, however, have twisted our beliefs and weaponized them to justify their crusade against Ramkahen. Their soldiers follow them blindly, never questioning. They must be stopped.", ["objectivesText"] = "Kill 8 Amathet priests in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155099, ["x"] = 0.546, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58284] = { ["id"] = 58284, ["name"] = "Writs of the Sun King", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58284 }, ["description"] = "Very little is known about the Sun King that leads the Amathet. Our observations suggest that those closest to him are the \"Suntouched,\" a unique caste of solar magic practitioners. I would like very much to learn more about this Sun King but, unlike some members of the Explorers' League, I'm not willing to risk the lives of my researchers to do so. You seem to be able to hold your own, though. If you happen upon any records about the Sun King, I'd gladly take them off your hands.", ["objectivesText"] = "Collect 6 Writs of the Sun King from Suntouched Amathet in Uldum . Progress: Have you found anything interesting?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 173986 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58285] = { ["id"] = 58285, ["name"] = "Unearthed Artifacts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58285 }, ["description"] = "Ever since the Amathet came out of their tombs, they've been busy unearthing titan relics from the surrounding areas. I'm not sure what they intend to do with them or if they're just hoarding it so we can't have them. Sufficed to say the Explorers' League would love to study some of what they found! Of course, we can't get anywhere close to them without the Amathet trying to stick an axe in us, but that's not a problem for you, is it? Care to help?", ["objectivesText"] = "Collect 6 Titan Artifacts in Uldum . Progress: Any luck with the titan artifacts ?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 168043 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58286] = { ["id"] = 58286, ["name"] = "Far From Home", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58286 }, ["description"] = "The Amathet's conquest of eastern Uldum was sudden, and we were unable to reach some of our farthest settlements in time. Fortunately, many of the tol'vir who lived in the conquered territories were not killed, instead being put to work under the Amathet's whip. We must take any opportunity we can to free them and return them to their homes.", ["objectivesText"] = "Free 6 Enslaved Tol'vir in Uldum .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58287] = { ["id"] = 58287, ["name"] = "A Smashing Plan", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58287 }, ["description"] = "Reports from my scouts mention various idols and monuments that the Amathet use to channel their solar magic. I don't know exactly what they're up to, but we should take away any possible advantage they have. So, I want you to go over there, and break anything that looks remotely magical. Just don't tell the Explorers' League. I'll never hear the end of it.", ["objectivesText"] = "Destroy 4 Amathet Idols and 2 Suntouched Obelisks in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58288] = { ["id"] = 58288, ["name"] = "The Sun King's Chosen", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58288 }, ["description"] = "On the surface the Amathet appear to be unwavering, but all soldiers have their breaking point. We need to send a message to their forces that we are not to be trifled with. Seek out the strongest of their numbers and bring them down in front of their eyes. We will show them the strength of Uldum !", ["objectivesText"] = "Defeat 3 rare Amathet enemies in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58289] = { ["id"] = 58289, ["name"] = "Guarded Secrets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58289 }, ["description"] = "From what we know about the Amathet, they must've been locked away in their tombs for thousands of years. Just think of what we could learn from them! Of course, that would be a lot easier if they weren't trying to kill us. If you happen upon any caches of Amathet relics in your travels, let me know. I'd love to see what sort of mysteries they contain!", ["objectivesText"] = "Loot 3 Amathet Caches in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58290] = { ["id"] = 58290, ["name"] = "Champions of the Amathet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58290 }, ["description"] = "The soldiers of Ramkahen are hearty and reliable. I would stand them up against any footman of the Amathet, but some of their higher-caste fighters are too much for even our toughest to handle. I don't think they'd be a problem for you, though. It would be a boon to our defense efforts if you could handle them while my soldiers engage the rank and file.", ["objectivesText"] = "Kill 6 elite Amathet enemies in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155096, ["x"] = 0.548, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58291] = { ["id"] = 58291, ["name"] = "Encroaching Poachers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58291 }, ["description"] = "The Wastewanders used the pelts of the local hyenas to construct our armor. Unfortunately since the Amathet arrived, their hunters have overrun our normal hunting grounds. We need those pelts, and will pay handsomely for them. Either take them from the hunters or skin the hyenas yourself, if you have the skill.", ["objectivesText"] = "Collect 6 Rugged Hyena Pelts from Amathet Hunters or by skinning hyenas in Uldum . Progress: Have you brought back the pelts?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174008 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 160957, ["x"] = 0.546, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 160957, ["x"] = 0.546, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.546, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58297] = { ["id"] = 58297, ["name"] = "Faceless Mask of the Daredevil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 58297 }, ["description"] = "The hunter never sought to lead yet sought a challenge in life at every turn. He directed his allies with a deft hand and never shied from diving in to the melee himself. The prowess he showed made him as well as my other minions much more deadly. Return this mask to the altar of the Daredevil to challenge your own resolve in battle as your foes attacks cut even more deep.", ["objectivesText"] = "Return the Faceless Mask of the Daredevil to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Daredevil on the altar.", ["rewardItems"] = { 173955, 174082 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174082 } },
[58314] = { ["id"] = 58314, ["name"] = "Faceless Mask of the Burned Bridge", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 58314 }, ["description"] = "The displaced warrior is always on uneasy footing, especially one who is removed from her home world. The void makes this unsteadiness a reality where one step can lead into the abyss or drain you to your core.", ["objectivesText"] = "Return the Faceless Mask of the Burned Bridge to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Burned Bridge on the altar.", ["rewardItems"] = { 173363, 174083 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174083 } },
[58316] = { ["id"] = 58316, ["name"] = "Faceless Mask of the Dark Imagination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 58316 }, ["description"] = "These magi, twisting their magic to manipulate and conquer the world. Imagining greater power, they tread along the lines of the Void's domain. In these pursuits, this magi came to the realization that in the depths of one's imagination lie truly dark and terrible things.", ["objectivesText"] = "Return the Faceless Mask of the Dark Imagination to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Dark Imagination on the altar.", ["rewardItems"] = { 174081 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174081 } },
[58317] = { ["id"] = 58317, ["name"] = "Faceless Mask of the Pained", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 58317 }, ["description"] = "Trading in secrets, trading in lies, operating on the fringes are all the Spymaster knows. His lost passions, lost loves are all gone, crushed under his own duty and loyalty to the crown. Nothing is left, nothing but the pain. Pain is an apt tutor and tool and one in which the void knows intimately. Return my mask if you dare to feel the many forms pain can take.", ["objectivesText"] = "Return the Faceless Mask of the Pained to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Pained on the altar.", ["rewardItems"] = { 172946, 174079 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174079 } },
[58318] = { ["id"] = 58318, ["name"] = "Faceless Mask of the Long Night", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["storyline"] = { 58318 }, ["description"] = "The endurance needed to make it this far is extraordinary and the feat of a long experienced adventurer. Yet, the longest night is nigh and with it our ultimate conquest. Those that fight the coming of eternal twilight know only futility, for in the Longest Night they will be on the edge of sanity forever.", ["objectivesText"] = "Return the Faceless Mask of the Long Night to the altar within a Horrific Vision. Progress: Place the Faceless Mask of the Long Night on the altar.", ["rewardItems"] = { 173363, 174080 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 174080 } },
[58321] = { ["id"] = 58321, ["name"] = "Uncommon Core", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58321 }, ["description"] = "Our scouts have reported that the Amathet are constructing new titanic watchers. We had long thought this art was lost to the sands of time. It would appear we were mistaken. I needn't tell you what a boon it would be to have the aid of watcher constructs in our battles for Uldum . We must unlock the secrets of their construction! The power of a titanic watcher lies in its core. I ask that you bring one to me, so that our artificers might divine its construction.", ["objectivesText"] = "Collect a Titanic Core from an Ivory Watcher in Uldum . Progress: Have you obtained the core?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174009 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155095, ["x"] = 0.548, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58373] = { ["id"] = 58373, ["name"] = "Ny'alotha: MOTHER's Guidance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10522, ["storyline"] = { 58373 }, ["description"] = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", ["objectivesText"] = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Normal Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 174063, 174910, 174913 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10522 } }, ["questType"] = "raid" },
[58374] = { ["id"] = 58374, ["name"] = "Ny'alotha: MOTHER's Guidance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10522, ["storyline"] = { 58374 }, ["description"] = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", ["objectivesText"] = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Heroic Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 174064, 174909, 174911 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10522 } }, ["questType"] = "raid" },
[58375] = { ["id"] = 58375, ["name"] = "Ny'alotha: MOTHER's Guidance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10522, ["storyline"] = { 58375 }, ["description"] = "Ny'alotha does not obey the rules of space and time, and we may be able to use this to our advantage. MOTHER theorizes that if we obtain specific objects from N'Zoth's chosen, we can utilize them to bend space and expedite our passage here in the future. Though, it is doubtful they will relinquish these items willingly.", ["objectivesText"] = "Collect 4 Titan Cores from Ra-Den, 4 Dragon Hearts from Vexiona and 4 Prophetic Eyes from Il'gynoth within Ny'alotha, the Waking City on Mythic Difficulty. Progress: Without the items MOTHER cannot guarantee safe passage.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 174065, 174908, 174912 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10522 } }, ["questType"] = "raid" },
[58420] = { ["id"] = 58420, ["name"] = "A Foul Annoyance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58420 }, ["description"] = "The Hozen are opportunistic and weak. It does not surprise me that some of their kind have thrown their lot in with the Old Gods. We should take care of them before they become more than a nuisance.", ["objectivesText"] = "Kill 7 Squidtail hozen in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58422] = { ["id"] = 58422, ["name"] = "Mark of the Conquerors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58422 }, ["description"] = "The invading minions of N'Zoth lay claim to lands they are not entitled to. The Vale will not be conquered while even one of the Rajani still draws breath. Burn down their banners as a reminder of this.", ["objectivesText"] = "Burn 6 Banners of the Black Empire in the Vale of Eternal Blossoms . Progress: Have you sent our message?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58423] = { ["id"] = 58423, ["name"] = "The Strongest Among Them", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58423 }, ["description"] = "You have shown great strength in your conquests, but new enemies assail the Vale with each day. Seek out the strongest that our foes have sent forth, and bring them down for their allies to see.", ["objectivesText"] = "Defeat 3 rare minions of N'Zoth in the Vale of Eternal Blossoms . Progress: Tell me of your victories.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58435] = { ["id"] = 58435, ["name"] = "Heritage of the Vulpera", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredRaces"] = { 35 }, ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 8501, ["mapID"] = 864, ["storyline"] = { 58435 }, ["description"] = "The Horde has come to truly value the Vulpera, thanks to your efforts. You are the most... vulperan vulpera that I know! Visit me in the Vulpera Hideaway in Vol'dun. Kiro had me put together a small memento in appreciation of your efforts.", ["objectivesText"] = "Meet Hagashi at the Vulpera Hideaway in Vol'dun.", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 864, ["npcID"] = 124108, ["x"] = 0.568, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 864, ["source"] = "quest_giver", ["x"] = 0.568, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 864 }, ["zone"] = { 8501 } }, ["questType"] = "standard" },
[58436] = { ["id"] = 58436, ["name"] = "Heritage of the Mechagnome", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["requiredRaces"] = { 37 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10290, ["mapID"] = 1462, ["storyline"] = { 58436 }, ["description"] = "<name>, we could not be more pleased with your progress. You represent us well with the Alliance. Return to Mechagon City at your earliest convenience. Waren has created a gift for you.", ["objectivesText"] = "Meet Prince Erazmin in Mechagon City.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 170063, 174077, 203176, 208476, 210054, 218105, 218118, 218119, 242520 }, ["ends"] = { { ["mapID"] = 1462, ["npcID"] = 158145, ["x"] = 0.733333, ["y"] = 0.346 } }, ["coords"] = { ["mapID"] = 1462, ["source"] = "quest_giver", ["x"] = 0.733333, ["y"] = 0.346 }, ["mapCandidates"] = { ["npc"] = { 1462 }, ["zone"] = { 10290 } }, ["questType"] = "standard" },
[58455] = { ["id"] = 58455, ["name"] = "Shadowy Showdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 58455 }, ["series"] = { 58456, 58457 }, ["description"] = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", ["objectivesText"] = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 37863 }, ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 147645, ["x"] = 0.503, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.503, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard" },
[58456] = { ["id"] = 58456, ["name"] = "Shadowy Showdown", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 51, ["storyline"] = { 58456 }, ["series"] = { 58455, 58457 }, ["description"] = "This is our time! We've found where these Shadowy Figures have been hiding, and it's time for us to take the fight to them and stop whatever their plans are. Their base of operations is in Blackrock Depths. It's all up to you.", ["objectivesText"] = "Find Burt Macklyn outside of the entrance to Blackrock Depths in Blackrock Mountain.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 51 } }, ["questType"] = "standard" },
[58457] = { ["id"] = 58457, ["name"] = "Shadows of Blackrock", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 51, ["storyline"] = { 58457 }, ["series"] = { 58455, 58456 }, ["description"] = "We've finally tracked those pesky Shadowy Figures down, they should all be in there. They seem highly skilled, you're going to need to bring your best teams in there if you have any chance of winning. Let me know when you are ready.", ["objectivesText"] = "Stop the Shadowy Figures. Progress: I can teleport you in, but after that, you're on your own.", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["rewardItems"] = { 122457 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 51 } }, ["questType"] = "standard" },
[58458] = { ["id"] = 58458, ["name"] = "Pet Battle Challenge: Blackrock Depths", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 51, ["storyline"] = { 58458 }, ["description"] = "Those Shadowy Figures are up to no good again, are you sure you want to face them? If you really want to go back in there, I'm not going to stop you.", ["objectivesText"] = "Stop the Shadowy Figures. Progress: I can teleport you back in there, but you're on your own once you're inside. Good luck.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174360 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 51 } }, ["questType"] = "standard" },
[58460] = { ["id"] = 58460, ["name"] = "Marshals of Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58460 }, ["description"] = "The n'raqi have long served as the commanders and taskmasters of the Old Gods' forces. Their presence on the field of battle shows that this invasion is a coordinated effort rather than a random outbreak of corruption. Led by these faceless masters, the chaotic forces of the Old Gods transform into capable military. We must make it a priority to fell these creatures. Only then might we take the upper hand against N'Zoth.", ["objectivesText"] = "Kill 6 faceless minions of N'Zoth in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58461] = { ["id"] = 58461, ["name"] = "Tomes of Ancient Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58461 }, ["description"] = "In times like these, it becomes necessary for all of the denizens of the Vale to pitch in and do their part. Unfortunately, I have never been much of a fighter, so my usefulness in times of war is limited. However, I may be able to do some good. You see, we know very little about the invaders we face, and knowledge can be a very powerful weapon. I think I have seen tomes carried by some of the k'thir. If you could bring some to me, I may be able to glean something useful from their writings.", ["objectivesText"] = "Collect 8 Tomes of Ancient Madness from k'thir enemies in the Vale of Eternal Blossoms . Progress: Have you managed to procure the tomes?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174196 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58462] = { ["id"] = 58462, ["name"] = "Windows to the Soul", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58462 }, ["description"] = "Were it not enough for our enemy to apply deadly force against us, their minions also strike into the very heart of our defenders. I speak, of course, of the eyes. They peer into the souls of our warriors and produce their darkest fears against them. If we have any hope to defeat this foe, they must be destroyed.", ["objectivesText"] = "Kill 6 Eyes of the Empire in the Vale of Eternal Blossoms . Progress: Is your task complete?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58463] = { ["id"] = 58463, ["name"] = "Spawns of Madness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58463 }, ["description"] = "To see the Vale of Eternal Blossoms recover from the Sha to its former beauty, only to see it tainted by the Old Gods once more, it makes the blood boil! We must root out the Old God's corruption before it can take hold of this land again. I have seen the fleshbeasts that accompany N'Zoth's forces spreading his corruption where they tread. Make sure they tread no longer.", ["objectivesText"] = "Kill 10 fleshbeasts in the Vale of Eternal Blossoms . Progress: I will not see the Vale fall again!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58464] = { ["id"] = 58464, ["name"] = "Deephive Decimation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58464 }, ["description"] = "A sect of the mantid swarm calling themselves the \"Deephive\" have taken hold of the Big Blossom mine. These mantid have fully given themselves up to the Old Gods' corruption, making them especially dangerous. We cannot allow the Deephive to run amok in the Vale. Do what must be done.", ["objectivesText"] = "Kill 10 Deephive mantid within the Big Blossom Mine in Vale of Eternal Blossoms . Progress: Have the Deephive been taken care of?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58465] = { ["id"] = 58465, ["name"] = "Corruption Manifest", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58465 }, ["description"] = "The corruption of the Old Gods is often so foul it manifests itself in physical form. We have seen this with the Sha. This time is no different. Cull this corruption wherever you see it spread. It must not be left to flourish.", ["objectivesText"] = "Kill 8 Putrid Ichors in Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58466] = { ["id"] = 58466, ["name"] = "Torment From Beyond", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58466 }, ["description"] = "As if it were not bad enough that N'Zoth seeks to dominate those living in the Vale, my scouts report they now seek to dominate the dead! The Shado-Pan have their hands full defending the living. Can we rely on you to put an end to this disgrace?", ["objectivesText"] = "Release 6 Ancient Pandaren Spirits in the Vale of Eternal Blossoms . Progress: N'Zoth must be stopped.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58467] = { ["id"] = 58467, ["name"] = "Prisoners of Mind and Body", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58467 }, ["description"] = "N'Zoth's forces struck the Vale suddenly. By the time I and my Shado-Pan arrived, many of the Golden Lotus had already been taken captive by the Old God's forces. Even with our combined might, we have only been able to hold off the invaders from taking more of our people. Those already taken, however, are still within the clutches of the Old God. I know we have had our differences, <name>, but if you could aid us in their recovery, the Shado-Pan would be in your debt.", ["objectivesText"] = "Rescue 6 captive pandaren in the Vale of Eternal Blossoms . Progress: Any news of the captives?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161404, ["x"] = 0.664, ["y"] = 0.405 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.405 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58468] = { ["id"] = 58468, ["name"] = "A Growing Darkness", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58468 }, ["description"] = "Shado-Pan scouts have spotted evidence of a new mantid hatchery within the Big Blossom mine. It seems these Deephive mantid are looking to create new corrupted spawn to serve N'Zoth. If these eggs were allowed to hatch, a new swarm empowered by the Old God could blacken the skies of the Vale and plunge Pandaria into darkness. We will not allow that to happen, will we?", ["objectivesText"] = "Destroy 6 Corrupted Incubators in the Big Blossom Mine in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58469] = { ["id"] = 58469, ["name"] = "Tears in the Vale", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58469 }, ["description"] = "As N'Zoth's influence spreads within the Vale, our very reality begins to break down. The Old God's power has created tears in the fabric our world, acting as doorways for his minions to invade from his dark realm. As long as these tears exist, we will never be free from N'Zoth's grasp. Close them, and stem the tide of his corruption!", ["objectivesText"] = "Close 3 Void Tears within the Vale of Eternal Blossoms . Progress: Our reality weakens with each passing day.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154261, ["x"] = 0.838, ["y"] = 0.487 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.838, ["y"] = 0.487 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58470] = { ["id"] = 58470, ["name"] = "Corrupted Curiosities", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58470 }, ["description"] = "I understand that the Black Empire poses a grave threat to Pandaria, but we may also use this as an opportunity! Though we've faced them several times before, very little is known about the Old Gods or N'Zoth's mysterious realm of Ny'alotha. When studying ancient civilizations, we often rely on artifacts to unlock the deepest mysteries lost to time. I wonder if some such artifacts could be found among the Old God's forces? It can't hurt to check, right?", ["objectivesText"] = "Collect 3 Artifacts of the Black Empire from Black Empire Caches in the Vale of Eternal Blossoms . Progress: Did you find anything interesting?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174744 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58471] = { ["id"] = 58471, ["name"] = "Aggressive Notation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58471 }, ["description"] = "Even given the Sha's origins with the Old Gods, we in Pandaria still know very little of them. I would like to take this opportunity to add whatever information I can about them to the archives of the Lorewalkers. Of course, that becomes a bit problematic when they're trying to kill us. That doesn't seem to be a problem for you, though. Could you do me a favor and jot down some notes about what you encounter out there? It could help a great deal towards understanding what we're fighting.", ["objectivesText"] = "Use the Lorewalker's Notebook to gather notes about the faceless, k'thir, and fleshbeasts in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 154200, 174197 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 156003, ["x"] = 0.836, ["y"] = 0.272 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.836, ["y"] = 0.272 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58476] = { ["id"] = 58476, ["name"] = "Bringing the Thunder", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58476 }, ["description"] = "All of the mogu clans are formidable, to be sure, but it is the Zan-Tien that pose the most direct threat to the Golden Lotus. Even now, their numbers are amassing outside the Golden Pagoda. Many of our warriors are fresh-faced and inexperienced. They would not withstand a mogu assault for long. An experienced <class> like you could serve to slow them down significantly. Care to help?", ["objectivesText"] = "Kill 12 Zan-Tien mogu in the Vale of Eternal Blossoms . Progress: What's the word from the front?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58477] = { ["id"] = 58477, ["name"] = "Through Blood and Dirt and Bone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58477 }, ["description"] = "The Dokani see themselves fit to wield the ancient magic of anima, but their golems and manifestations are but a fraction of anima's true power. Liberate them of their prized substance, so that the Rajani may put it to better use.", ["objectivesText"] = "Collect 100 Anima Globule from Dokani mogu and their allies in the Vale of Eternal Blossoms . Progress: What do you bring?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174210 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58478] = { ["id"] = 58478, ["name"] = "No Stone Unbroken", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58478 }, ["description"] = "When the warring clans came into the Vale, the Baruk deigned themselves worthy to lay claim to the ancient grounds of Guo-Lai. They are not. Show these usurpers their place, and you may earn a modicum of favor with the Rajani.", ["objectivesText"] = "Kill 10 Baruk mogu in the Vale of Eternal Blossoms .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58479] = { ["id"] = 58479, ["name"] = "Lightning Crashes", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58479 }, ["description"] = "The Zan-Tien like to claim mastery over the power of storms, yet they resort to machines to harness lightning from the sky. Show these pretenders that the true power of storm and thunder comes from within. Break their toys, and see how they fare without.", ["objectivesText"] = "Destroy 6 Lightning Rods in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58481] = { ["id"] = 58481, ["name"] = "Rituals of Blood", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58481 }, ["description"] = "Anji and I have fought in many battles, so we know how to handle a few mogu, but the blood magic used by these Dokani is just unsettling! As if it weren't bad enough for them to kill everyone in their path, but to use their corpses to fuel their unholy rituals? I just can't stomach it! Do me a favor. If you ever come across any of these rituals, put a stop to them! Even our enemies don't deserve to be defiled with their dark magic.", ["objectivesText"] = "Destroy 6 Blood Fonts in the Vale of Eternal Blossoms . Progress: I hope you were able to do something about those rituals.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58487] = { ["id"] = 58487, ["name"] = "Plunder the Plunderers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58487 }, ["description"] = "Our raids on Lei Shen's treasuries did much to ensure the Thunder King's downfall. I think we should employ the same strategy here. Seek out the hoarded plunder of the mogu clans and relieve them of it. We must do all we can to disrupt their advance.", ["objectivesText"] = "Loot 3 Mogu Plunder from the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58496] = { ["id"] = 58496, ["name"] = "An Unwelcome Advisor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 84, ["storyline"] = { 58496, 58498, 58502, 58506 }, ["description"] = "<The envelope contains a message from King Anduin Wrynn .> <name>, Even with the forces of the Horde and Alliance working together, we still have found no trace of N'Zoth's forces. Ever since his release, the Old God has evaded us at every turn. The Light only knows what ill he has in store for Azeroth. Meet me in Stormwind Keep. We must put a plan together to uncover N'Zoth's schemes before it is too late! Light grant you haste, King Anduin Wrynn", ["objectivesText"] = "Speak with King Anduin Wrynn in Stormwind Keep. Progress: What is it?", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 107574, ["x"] = 0.856, ["y"] = 0.316667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.856, ["y"] = 0.316667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 13, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58498] = { ["id"] = 58498, ["name"] = "Return of the Warrior King", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 84, ["storyline"] = { 58496, 58498, 58502, 58506 }, ["description"] = "Ye've done a great deal fer Azeroth, hero, but unfortunately I'm gonna have tae ask ye tae do more. N'Zoth is on the loose, an there's no tellin' when or where he'll strike. This battle is one ye can't face alone. When the time comes, ye'll have my hammer at yer side! But first, we'll need tae fetch it.", ["objectivesText"] = "Walk with Magni and retrieve Fearbreaker in Stormwind Keep. Progress: Need something, champion?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 175151 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 2, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58502] = { ["id"] = 58502, ["name"] = "Where the Heart Is", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 84, ["storyline"] = { 58496, 58498, 58502, 58506 }, ["description"] = "It's time we put Wrathion's plans in tae motion. He'll be headin' back tae the Chamber of Heart, so we should meet him there.", ["objectivesText"] = "Return to the Chamber of Heart.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 6948, 227669 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 154532, ["x"] = 0.8656, ["y"] = 0.3416 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.8656, ["y"] = 0.3416 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58506] = { ["id"] = 58506, ["name"] = "Network Diagnostics", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 58496, 58498, 58502, 58506, 58582, 58583 }, ["description"] = "Unfortunately, we've got no clue where N'Zoth has been lurking since his escape. We do, however have an idea where he might strike. Back when the keepers were imprisoning the Old Gods, they built defense mechanisms against their corruption into the titan forges. If N'Zoth wants tae corrupt Azeroth, he'll have tae go through them first. Fortunately, we've got ourselves hooked up tae them now, so we can monitor them from here. Go ahead an' take a look.", ["objectivesText"] = "Activate the Titan Consoles in the Chamber of Heart to check the status of the titan forges throughout Azeroth. Progress: The consoles should tell ye how the forges are holdin' up.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 3, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58582] = { ["id"] = 58582, ["name"] = "Return of the Black Prince", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8499, ["mapID"] = 84, ["storyline"] = { 58506, 58582, 58583 }, ["description"] = "<The envelope contains a message from Valeera Sanguinar .> <name>, I have just returned from a meeting with King Wrynn in Stormwind. We have much to discuss. Meet me at the Great Seal with haste. Al diel shala, Valeera", ["objectivesText"] = "Speak with Valeera Sanguinar at the Great Seal in Dazar'alor. Progress: Yes?", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["rewardItems"] = { 200710 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 161458, ["x"] = 0.850667, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.850667, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 8499 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2DetailThemeID"] = 5, ["db2PoiMapID"] = 1642, ["db2PoiUiMapID"] = 1165, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58583] = { ["id"] = 58583, ["name"] = "Where the Heart Is", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9598, ["mapID"] = 84, ["storyline"] = { 58506, 58582, 58583 }, ["description"] = "The Speaker has requested that I send you to aid him and Wrathion in their efforts. You have proven yourself a great ally to Azeroth, and I suspect you will have a big part to play in the coming battles. Let us hope that the rest of the Horde and Alliance can put aside their squabbles to face a common enemy.", ["objectivesText"] = "Meet Magni Bronzebeard in the Chamber of Heart.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 6948 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 161458, ["x"] = 0.850667, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.850667, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9598 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1030, ["name"] = "Return of the Black Prince", ["orderIndex"] = 4, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58595] = { ["id"] = 58595, ["name"] = "Pillars of Oblivion", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58595 }, ["description"] = "In ages past, the black obelisks of the Old Gods would herald the coming of their forces. The dark conjurers among the k'thir and n'raqi would utilize these monuments to establish footholds in our world and usher in more of the Old Gods' minions. Today, we see these very same obelisks littering the battlefields. So long as they stand, N'Zoth's forces will be without end. Make sure they do not.", ["objectivesText"] = "Destroy 6 Black Empire Obelisks in the Vale of Eternal Blossoms . Progress: Is your task complete?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58606] = { ["id"] = 58606, ["name"] = "A Bit of Investigation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58606 }, ["description"] = "$p, this may be the discovery of a lifetime! I cannot yet say with absolute certainty, but I have a suspicion that these insects are known as the aqir. The League has few intact records, but the last mention of these creatures describes a great war waged between the C'Thraxxi, aqir, and early troll civilizations. We had assumed they were driven to extinction, but they may have simply been... rebuilding. Could you please collect some samples for me to examine?", ["objectivesText"] = "Collect 16 Aqir Bits . Progress: Have you managed to acquire the samples?", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 174356 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 164196, ["x"] = 0.28, ["y"] = 0.634 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 164196, ["x"] = 0.28, ["y"] = 0.634 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.634 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58615] = { ["id"] = 58615, ["name"] = "Whispers in the Dark", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 12905, ["mapID"] = 1473, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472, 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 57220, 57221, 57222, 57290, 57362, 57373, 57374, 58496, 58498, 58502, 58506, 58615, 58631, 58634, 58737 }, ["description"] = "Did ye hear that as well? That cannae be good. If N'Zoth gains access tae this chamber, we'll all be done for! We need tae figure out where he's accessing the chamber and shut it down, before he does more than just whisper at us!", ["objectivesText"] = "Find the source of N'Zoth's whispers in the Chamber of Heart.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 119036, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12905 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1028, ["name"] = "Whispers in the Dark", ["orderIndex"] = 0, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 27, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 26, ["flags"] = 0 } } },
[58631] = { ["id"] = 58631, ["name"] = "Into Dreams", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 56209, 56374, 56375, 56376, 56377, 56472, 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 57220, 57221, 57222, 57290, 57362, 57373, 57374, 58496, 58498, 58502, 58506, 58615, 58631, 58634, 58737 }, ["description"] = "I cannae believe that Ra-den sacrificed himself to save us. We cannae give up on him! There must be a way tae find out where he went. Let's see if MOTHER can track him down!", ["objectivesText"] = "Speak with MOTHER in the Chamber of Heart to track Ra-den's location. Progress: We're runnin' outta time!", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 173363 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1028, ["name"] = "Whispers in the Dark", ["orderIndex"] = 1, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 28, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 27, ["flags"] = 0 } } },
[58632] = { ["id"] = 58632, ["name"] = "Ny'alotha, the Waking City: The Corruptor's End", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 58615, 58631, 58632 }, ["description"] = "Usin' the mogu's research, MOTHER and Ra-den found a way tae focus the forge's Origination Protocol through the Chamber of Heart. The only problem was findin' out where tae shoot it. That is, until now. Take these anchors and head through that portal. Ye'll need tae find some prominent landmarks tae place 'em so we can focus the weapon. Once they're set, we'll be ready tae fire. Ye'll only get one shot. Make it count!", ["objectivesText"] = "Defeat N'Zoth in Ny'alotha, the Waking City. Progress: It's time tae blast N'Zoth back tae the void he came from!", ["rewardGold"] = 936000, ["rewardXP"] = 13630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "raid", ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1028, ["name"] = "Whispers in the Dark", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58634] = { ["id"] = 58634, ["name"] = "Opening the Gateway", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 57220, 57221, 57222, 57290, 57362, 57373, 57374, 57524, 58634 }, ["series"] = { 57362, 57373, 57374 }, ["description"] = "The fabric of reality is torn. But there's no need for me to tell you that, <name>. You've seen it firsthand. It's only a matter of time before these realities become one, veiled in eternal darkness. Instead of hiding, perhaps it's time we embraced the darkness. With the help of our titan friend here we may be able to thread the needle of this reality through the fabric of another, creating a bridge of sorts. After all, the key to understanding an enemy's weakness is to understand their intentions.", ["objectivesText"] = "Speak with MOTHER to establish the Tenebrous Gateway in the Chamber of Heart. Progress: Uncertainty comes before discovery.", ["rewardGold"] = 175500, ["rewardXP"] = 5110, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 1012, ["name"] = "Through the Darkness", ["orderIndex"] = 5, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 25, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 24, ["flags"] = 0 } } },
[58636] = { ["id"] = 58636, ["name"] = "Eyes on the Amathet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "On behalf of the Explorers' League, I'd like tae thank ye for helping establish the Uldum Accord and buying us some cooperation from Ramkahen. In the interest of better understanding our foes, Ramkahen has allowed the exploring of the Amathet tombs. Unfortunately, though, their forces are spread too thin to provide protection. I was hopin' ye could help out with that. Think ye could spare some time tae see what they're all about? We can start with an aerial look.", ["objectivesText"] = "Scout the Amathet territories with High Explorer Dellorah in Uldum . Progress: To the skies!", ["rewardGold"] = 117000, ["rewardXP"] = 3410, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58638] = { ["id"] = 58638, ["name"] = "A Deeper Dive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "Something just isn't adding up about these Amathet. Why would protectors of titan works attack and damage the Forge of Origination? I think we need tae take a closer look. I think I saw a monument on the terrace over there. Perhaps the writings there could tell us more about these tol'vir.", ["objectivesText"] = "Defend High Explorer Dellorah as she deciphers the Amathet Monument at Sunstone Terrace. Progress: I'm ready when ye are, <class>.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58639] = { ["id"] = 58639, ["name"] = "Buried History", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "Since the Amathet came from this region, it would only stand to reason that artifacts from their civilization would be left behind here, hidden beneath the sands . It looks like it's time for a good old-fashioned dig! The dunes near here must have covered up a large swath of the Amathet's former territory. Let's see what we can dig up there!", ["objectivesText"] = "Uncover and collect 6 Amathet Artifacts in Uldum . Progress: What have ye turned up?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174450 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58640] = { ["id"] = 58640, ["name"] = "A Crack in the Armor", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "The artifacts you helped excavate show the Amathet as a tribe who prided themselves on protecting the works of the titans. This confirms our assumptions, and indicates that something drastic must have happened to them to cause them to damage the very works they swore to protect. We should continue to track down their writings. I think I saw a more recent monument outside the Halls of Origination.", ["objectivesText"] = "Defend High Explorer Dellorah as she deciphers the Amathet Monument outside the Halls of Origination. Progress: I cannae wait tae solve this mystery!", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 4, ["flags"] = 0 } } },
[58641] = { ["id"] = 58641, ["name"] = "Seekers of Corruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "If anyone would know more about the \"corruption\" the tablet spoke of, it would be the Suntouched that were put in charge of rooting it out. Of course, I doubt they'll be willing to turn over any information voluntarily. Luckily for me, you're a bit of a specialist at brute force investigation, aren't you?", ["objectivesText"] = "Collect the Sun King's Decree from Suntouched Amathet in Uldum . Progress: Found anything from the Suntouched?", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["rewardItems"] = { 174451 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 5, ["flags"] = 0 } } },
[58642] = { ["id"] = 58642, ["name"] = "Shared Goals", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "The decree you found made mention of a plan to defeat the Old Gods. I know that the Amathet aren't likely to work with us toward that goal, but if they have a plan tae take out N'Zoth, it's worthwhile for us tae look at it. The decree mentions the Engine of Ascension. I think that might be what they call that solar empowering device we saw earlier. We should take a peek underneath and see if we can figure out what they're planning!", ["objectivesText"] = "Defend High Explorer Dellorah as she deciphers the Amathet Tablets within the Chamber of the Stars. Progress: Let's see what we can find in the Chamber of the Stars.", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 6, ["flags"] = 0 } } },
[58643] = { ["id"] = 58643, ["name"] = "Mutually Assured Destruction", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "The Amathet want tae re-take the Forge of Origination so they can use it tae end all life on Azeroth, Old God or otherwise! They could strike at any moment. We have tae warn the defenders of the Forge!", ["objectivesText"] = "Warn the defenders of the Halls of Origination about the Amathet's plan.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161031, ["x"] = 0.72, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 7, ["flags"] = 0 } } },
[58645] = { ["id"] = 58645, ["name"] = "A World Worth Saving", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "We could not stand against them. Their warriors... wreathed in the sun's flames... They want the forge... to end all... Go... I will... endure...", ["objectivesText"] = "Stop the Amathet from taking the Halls of Origination.", ["rewardGold"] = 23400, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161031, ["x"] = 0.72, ["y"] = 0.522 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 155102, ["x"] = 0.55, ["y"] = 0.33 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 8, ["flags"] = 0 } } },
[58646] = { ["id"] = 58646, ["name"] = "Chew On This!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58636, 58638, 58639, 58640, 58641, 58642, 58643, 58645, 58646 }, ["description"] = "These mangy hyena will gnaw on anything they dig up, including priceless artifacts! We cannae allow the history of Uldum tae go tae the dogs, so tae speak. I'm afraid we're gonna have tae thin out their numbers.", ["objectivesText"] = "Kill 8 Scavenging Dunerunners in Uldum . Progress: Did ye take care of the hyenas?", ["rewardGold"] = 280900, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["questLines"] = { { ["id"] = 1029, ["name"] = "Mystery of the Amathet", ["orderIndex"] = 3, ["flags"] = 0 } } },
[58672] = { ["id"] = 58672, ["name"] = "A Gathering of Champions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "The leaders of the Horde are gathering together in Orgrimmar to nominate a new Warchief of the Horde. As a champion of the Horde, your presence at the meeting has been requested. The gathering will be held at the embassy in Orgrimmar. I will be going on ahead. Come speak with me when you arrive in Orgrimmar, I'll be waiting with the others. Make haste, champion. The future of the Horde is about to be decided...", ["objectivesText"] = "Speak with Valeera Sanguinar in Orgrimmar.", ["starts"] = { { ["mapID"] = 84, ["npcID"] = 161458, ["x"] = 0.850667, ["y"] = 0.33 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162190, ["x"] = 0.531, ["y"] = 0.143 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.850667, ["y"] = 0.33 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 19, ["flags"] = 0 } } },
[58673] = { ["id"] = 58673, ["name"] = "Warchief of the Horde", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1637, ["mapID"] = 84, ["storyline"] = { 56495, 56496, 56833, 57088, 57090, 57091, 57092, 57093, 57094, 57095, 57130, 57147, 57148, 57149, 57150, 57151, 57152, 57198, 57376, 58672, 58673 }, ["description"] = "The meeting to decide the next Warchief of the Horde is about to begin. The other leaders of the Horde have already arrived. They are waiting for you inside the embassy. Speak with me when you are ready, and we will greet the others together.", ["objectivesText"] = "Witness the gathering of champions.", ["starts"] = { { ["mapID"] = 84, ["npcID"] = 162190, ["x"] = 0.531, ["y"] = 0.143 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162190, ["x"] = 0.531, ["y"] = 0.143 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.531, ["y"] = 0.143 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 225, ["title"] = "War Campaign", ["questLineID"] = 5387, ["questLineOrder"] = 16 } }, ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5387, ["name"] = "Breaking the Cycle", ["orderIndex"] = 20, ["flags"] = 0 } } },
[58674] = { ["id"] = 58674, ["name"] = "A Gathering of Champions", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 8568, ["mapID"] = 1161, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "King Wrynn has called for an audience with the Alliance leaders in Stormwind. Your presence at the meeting has been specifically requested. The gathering will be held at the embassy. Come speak with me when you arrive in Stormwind, I'll be waiting with the others. Do hurry, <name>. It would be ill-advised to keep the king waiting...", ["objectivesText"] = "Speak with Master Mathias Shaw in Stormwind.", ["starts"] = { { ["mapID"] = 1161, ["npcID"] = 135614, ["x"] = 0.705, ["y"] = 0.27 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162178, ["x"] = 0.535, ["y"] = 0.149 } }, ["coords"] = { ["mapID"] = 1161, ["source"] = "quest_giver", ["x"] = 0.705, ["y"] = 0.27 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 8568 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 10, ["flags"] = 0 } } },
[58675] = { ["id"] = 58675, ["name"] = "The Price of Peace", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 56494, 56719, 56979, 56980, 56981, 56982, 56993, 57002, 57126, 57324, 58674, 58675 }, ["description"] = "The king will be addressing us shortly with news from his diplomatic mission to the Horde. The other leaders of the Alliance have already arrived. I am sure they are eager to hear what King Wrynn has to say. Speak with me when you are ready, and we will greet the king together.", ["objectivesText"] = "Witness King Wrynn's address.", ["rewardItems"] = { 90365 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 162178, ["x"] = 0.535, ["y"] = 0.149 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 162178, ["x"] = 0.535, ["y"] = 0.149 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.149 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 216, ["title"] = "War Campaign", ["questLineID"] = 5382, ["questLineOrder"] = 15 } }, ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5382, ["name"] = "Breaking the Cycle", ["orderIndex"] = 11, ["flags"] = 0 } } },
