[58708] = { ["id"] = 58708, ["name"] = "Fame Waits for Gnome One", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54087, 54088, 54945, 54946, 54947, 54992, 55040, 55096, 55645, 55729, 55730, 55731, 55734, 55736, 55995, 57009, 58708 }, ["series"] = { 54088, 57009 }, ["description"] = "Tinkmaster Overspark requests your assistance on an important research expedition. Working with the esteemed Tinkmaster will certainly be of benefit to your career. It's done wonders for mine!", ["objectivesText"] = "Meet with Tinkmaster Overspark in Boralus.", ["rewardGold"] = 2000, ["rewardXP"] = 1415, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 162393, ["x"] = 0.525, ["y"] = 0.141 } }, ["ends"] = { { ["mapID"] = 1161, ["npcID"] = 150208, ["x"] = 0.674, ["y"] = 0.155333 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.525, ["y"] = 0.141 }, ["mapCandidates"] = { ["npc"] = { 84, 1161 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 218, ["title"] = "Mechagon", ["questLineID"] = 5376, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 1643, ["db2PoiUiMapID"] = 1161, ["questLines"] = { { ["id"] = 5376, ["name"] = "Welcome to Mechagon", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58737] = { ["id"] = 58737, ["name"] = "Magni's Findings", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = { "campaign" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 1473, ["storyline"] = { 56536, 56537, 56538, 56539, 56540, 56541, 56542, 56771, 58737 }, ["description"] = "As if gettin' the Forge back up and runnin' wasn't good enough, I think we may have found the key tae takin' out N'Zoth once and for all in the archives of Mogu'shan Vaults! Ye might want tae be sittin' down for this one, champion.", ["objectivesText"] = "Learn Magni's findings. Progress: Pay attention, champion!", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 9667 } }, ["questType"] = "standard", ["campaigns"] = { { ["id"] = 219, ["title"] = "Visions of N'zoth", ["questLineID"] = 5377, ["questLineOrder"] = 0 }, { ["id"] = 224, ["title"] = "Visions of N'zoth", ["questLineID"] = 5386, ["questLineOrder"] = 0 } }, ["db2PoiMapID"] = 2215, ["db2PoiUiMapID"] = 1473, ["questLines"] = { { ["id"] = 983, ["name"] = "The Engine of Nalak'sha", ["orderIndex"] = 8, ["flags"] = 0 }, { ["id"] = 5377, ["name"] = "Visions of N'zoth", ["orderIndex"] = 18, ["flags"] = 0 }, { ["id"] = 5386, ["name"] = "Visions of N'zoth", ["orderIndex"] = 17, ["flags"] = 0 } } },
[58740] = { ["id"] = 58740, ["name"] = "Subjugated Serpents", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58740 }, ["description"] = "Where the Zan-Tien march, the warserpents are sure to follow. I cannot stress to you enough how dangerous these beasts are. It is a shame to see them subjugated by the mogu, but we cannot afford to let them run rampant. I need you to put them down before they can wreak havoc on our lines.", ["objectivesText"] = "Kill 4 Onyx Warserpents in the Vale of Eternal Blossoms . Progress: Have you taken care of the serpents?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58741] = { ["id"] = 58741, ["name"] = "Cutting Stone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58741 }, ["description"] = "One problem with waging war against other mogu is that weapons dull and break very quickly when used against foes of stone and metal. Being the sole blacksmith among the Rajani, it is sometimes difficult to keep up with our warriors needs. If you come across any weapons in your battles with the mogu, I'm sure I could put them to good use.", ["objectivesText"] = "Collect 10 Mogu Armaments in the Vale of Eternal Blossoms . Progress: What have you found?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 172463, 174747 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
