[58754] = { ["id"] = 58754, ["name"] = "Champions of the Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58754 }, ["description"] = "It is clear that Shek'zara is fully committed to this invasion. Our scouts have spotted some of her greatest champions among the battlefield. Any one of these mantid could prove too much for the soldiers of the Golden Lotus to overcome. We must hunt them down and eliminate them ourselves. Are you in?", ["objectivesText"] = "Defeat 3 rare mantid enemies in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58755] = { ["id"] = 58755, ["name"] = "Stashed Supplies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58755 }, ["description"] = "The invading mantid have been making off with the Golden Lotus' supplies lately. They're probably hoping they can starve us out. Well, they may be right if we can't get some of our supplies back. While you're taking the fight to the swarm, keep an eye out for anywhere they might have stashed our supplies. You'd be doing the Golden Lotus a big favor if you could recover some.", ["objectivesText"] = "Collect 3 Golden Lotus Supplies from Ambered Caches in the Vale of Eternal Blossoms . Progress: Did you manage to find our supplies?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174763 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58756] = { ["id"] = 58756, ["name"] = "Dread Menders", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58756 }, ["description"] = "The ambercasters are among the highest castes of mantid society. Through their magic, they can mend and form amber to their will, allowing hastened recovery of the mantid's forces after a battle. They are strategic targets, and we should seek them out. Care to join us?", ["objectivesText"] = "Kill 6 Mantid ambercasters in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58758] = { ["id"] = 58758, ["name"] = "Rampaging Destroyers", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58758 }, ["description"] = "The last mantid swarm is still very fresh in the memory of the Golden Lotus. Prior to the advancement of the swarm, the mantid would send their massive kunchong to soften up the defenders' lines. It would seem their tactics have not changed. We must stop those kunchong if the Golden Lotus hope to mount a defensive against the swarm. I'm counting on you to strike them down.", ["objectivesText"] = "Kill 4 Kunchong Destroyers in the Vale of Eternal Blossoms . Progress: Have the beasts been halted?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58759] = { ["id"] = 58759, ["name"] = "The Empress' Guard", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58759 }, ["description"] = "The Zara'thik are the empress' elite guard. Empowered with plundered Azerite , they will stop at nothing short of absolute conquest of all of Pandaria. If we allow them to advance past the Serpent's spine, the Golden Lotus will be no match for them. Stop them at the wall, <class>.", ["objectivesText"] = "Kill 8 Zara'thik mantid in the Vale of Eternal Blossoms . Progress: We must break the Zara'thik advance!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "group", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58760] = { ["id"] = 58760, ["name"] = "Blades of Amber", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58760 }, ["description"] = "The mantid are frail and easily broken, but the amber blades they wield are formidable. With a bit of work, they could be reshaped into something suitable for the mogu. Bring them to me, and I can see about repurposing them to service the Rajani.", ["objectivesText"] = "Collect 12 Amber Blades from Vil'thik mantid in the Vale of Eternal Blossoms . Progress: Have you brought me some blades?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174762 }, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154677, ["x"] = 0.438, ["y"] = 0.718 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.438, ["y"] = 0.718 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58761] = { ["id"] = 58761, ["name"] = "Crushed Underfoot", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58761 }, ["description"] = "In the past, the mantid would safeguard their hatchlings in incubation chambers until they were ready to be tested in the swarm. These Vil'thik are sloppy, however, allowing their larvae to scurry out in the open. Wouldn't it be a shame if someone crushed them? No, of course it wouldn't.", ["objectivesText"] = "Squash 10 Vil'thik Larvae in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 154444, ["x"] = 0.428667, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.428667, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58762] = { ["id"] = 58762, ["name"] = "Taken by the Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58762 }, ["description"] = "There's something different about this mantid swarm. Instead of just killing everything in sight like the mantid usually do, they've taken to capturing our defenders and holding them alive. I really don't want to know what they have in store for the captives. Why don't you go rescue them so we don't have to find out?", ["objectivesText"] = "Free 6 Golden Lotus prisoners from Hardened Amber Cages in the Vale of Eternal Blossoms .", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158673, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58763] = { ["id"] = 58763, ["name"] = "Halting Production", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58763 }, ["description"] = "The mantid use amber in nearly all aspects of their lives, from the structures they live in to the weapons they wield. Of course, I'm more interested in the latter. If we can deprive the mantid of their materials, we will deprive them of their means to create implements of war. Find where they keep their amber and make sure they are unable to use it.", ["objectivesText"] = "Destroy 6 Amber Vessels in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 161405, ["x"] = 0.521, ["y"] = 0.596 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.521, ["y"] = 0.596 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58764] = { ["id"] = 58764, ["name"] = "Standards of the Swarm", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58764 }, ["description"] = "The brazen mantid think they've already won. Even now, they fly banners along the Serpent's Spine, announcing their dominance. They must learn that Pandaria belongs to the pandaren. Burn their banners down.", ["objectivesText"] = "Burn 6 Zara'thik Banners within the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58765] = { ["id"] = 58765, ["name"] = "Siege Breaker", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1530, ["storyline"] = { 58765 }, ["description"] = "The Golden Lotus can hold their own against the mantid's warriors, of that I have no doubt. Their war wagons, on the other hand, have the capability of crippling an entire squad of our fighters in a single volley. If we wish to maintain the upper hand in this battle, we will need someone to infiltrate their positions and sabotage their siege engines. I would like you to volunteer.", ["objectivesText"] = "Sabotage 3 Vil'thik War Wagons in the Vale of Eternal Blossoms .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["ends"] = { { ["mapID"] = 1530, ["npcID"] = 158674, ["x"] = 0.385, ["y"] = 0.752 } }, ["coords"] = { ["mapID"] = 1530, ["source"] = "quest_giver", ["x"] = 0.385, ["y"] = 0.752 }, ["mapCandidates"] = { ["npc"] = { 1530 }, ["zone"] = { 9105 } }, ["questType"] = "standard", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530 },
[58776] = { ["id"] = 58776, ["name"] = "Hatching Problems", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58776 }, ["description"] = "The aqir are multiplying faster than we can put them down. If this pace continues, we will be outnumbered before long. The only way to slow down their assault is to attack their hives directly and destroy their eggs, but we have been unsuccessful in doing so. That's why I wish to conscript your services. Will you help?", ["objectivesText"] = "Destroy 6 Aqir Egg Clusters in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58777] = { ["id"] = 58777, ["name"] = "Put Your Foot Down", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58777 }, ["description"] = "<Zahra stomps on a slimy, slug-like creature as you approach.> You see that? Doesn't look like much, but believe it or not, those bugs grow out of these things. They're all over the places the aqir have taken over, feeding off of our dead and growing into these monstrosities. If you happen to see any of them, do the world a favor and take your boot to 'em.", ["objectivesText"] = "Squish 8 Aqir Larvae in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58778] = { ["id"] = 58778, ["name"] = "Getting Ahead", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58778 }, ["description"] = "Morale's been down at the camp lately. Funny how getting chewed on by some bugs can spoil the mood of a place. I've got an idea to perk the troops back up, though. We need a trophy! See if you can get me the head of one of those big tanky-looking ones so we can put it on display to show these bugs that we mean business! Just try to make sure it's not too mangled, okay?", ["objectivesText"] = "Collect 1 Goliath Trophy from Aqir Goliaths in Uldum . Progress: Show me what ya got!", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174776 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58779] = { ["id"] = 58779, ["name"] = "Taking the Skies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58779 }, ["description"] = "I'd like to see if we can get some more of these flyers in the air to drive back the aqir, but it's nearly impossible to get back to the Obelisk of the Sun with all these bugs in the air. I think we're going to have to thin them out on the ground before we can hope to gain aerial superiority. Can I count on you to lend a hand?", ["objectivesText"] = "Kill 15 flying Aqir in Uldum . Progress: How fares the bug smashing?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159920, ["x"] = 0.412, ["y"] = 0.386 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.412, ["y"] = 0.386 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58780] = { ["id"] = 58780, ["name"] = "Heralds of the Hive", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58780 }, ["description"] = "The aqir that have assaulted our camp seem to mainly consist of their shock troops. However, our scouts who dare venture behind their lines have spotted a different kind of creature -- tall and thin, wielding dangerous void magic. My instinct tells me that these creatures are the leaders behind this invasion. They should be seen as targets of opportunity, and cut down wherever they're met. Are you up to the task?", ["objectivesText"] = "Kill 5 Aqir Dominators in Uldum . Progress: What do you have to report?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 154443, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "group", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[58781] = { ["id"] = 58781, ["name"] = "Terrors from the Deep", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58781 }, ["description"] = "The Aqir threaten the livelihood of the Wastewanders with each passing day, but I have heard of greater terrors that have been unearthed with them. Our fighters are able, but I fear what might happen if one of these ancient terrors falls upon us. I know that you have experience putting down great foes. I would like to ask you to do the same for us. After all, we can hardly help protect the forge if we've been decimated by some long-buried monster.", ["objectivesText"] = "Defeat 3 rare Aqir enemies in Uldum .", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58782] = { ["id"] = 58782, ["name"] = "Things Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58782 }, ["description"] = "The invading aqir forced the Wastewanders to flee many of our settlements in Uldum . In our haste to escape, much was left behind. I understand you intend to take the fight to the beasts. While you're there, could you keep an eye out for any of the supplies we had to leave behind? You can keep anything of use to you, of course.", ["objectivesText"] = "Collect 3 Wastewander Supplies from Infested Caches in Uldum . Progress: Were you able to find anything?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174774 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 159544, ["x"] = 0.4, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.4, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 1527 },
[58801] = { ["id"] = 58801, ["name"] = "Enter the Void", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["storyline"] = { 58801 }, ["description"] = "<As your approach the idol, the dark shards you carry appear to melt into your hand. You are immediately overcome with unspeakable anguish. It quickly gives way to feelings of joy, serenity, and an overwhelming desire to... kill. A hissing voice creeps into your mind.> My faithful servant. I will grant you but a small taste of my unimaginable power, all I ask in return is that you complete one simple task. Kill any who would oppose me, spare no one. Do not fail me...", ["objectivesText"] = "Without dying or leaving Void Wraith form, sacrifice 10 players to N'Zoth.", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questType"] = "pvp" },
[58802] = { ["id"] = 58802, ["name"] = "The Incredible Egg", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58802 }, ["description"] = "<The aqir seem to have been in the process of empowering this egg with void magic. It looks to be far from hatching, so it should be safe to study to find out what they were planning to do with it. Someone in the Explorers' League might be interested in taking a look.>", ["objectivesText"] = "Bring the Voidtouched Egg to H'partho Adoros in Ramkahen.", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58803] = { ["id"] = 58803, ["name"] = "Match the Hatch", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58803 }, ["description"] = "Don't fret, I'm sure no ill will become of hatching this creature. After all, the aqir can't be born evil, can they? Of course, we have no idea how to take care of such an egg. I will need you to do some investigating. Head back to the aqir hives and see if you can find any other, similar eggs. If we can observe how they're being treated, we might be able to apply those learnings here.", ["objectivesText"] = "Investigate 7 Voidtouched Eggs in Uldum . Progress: What have you learned among the aqir?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58804] = { ["id"] = 58804, ["name"] = "Void Incubation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58804 }, ["description"] = "Well one thing is for certain with this egg, it requires great amounts of void energy in order to thrive. It is fortunate for us that an Old God is attacking Azeroth at this very moment, yes? No? Oh... In any case, there should be an abundance of void energy wherever N'Zoth's minions strike. You should head out and find some.", ["objectivesText"] = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces. Progress: Have you found a reliable source of void energy?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174993 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58805] = { ["id"] = 58805, ["name"] = "Continued Incubation", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58805 }, ["description"] = "The egg is doing well, but we're going to need more of those void crystals to keep it healthy. Could you go out and gather some?", ["objectivesText"] = "Collect 10 Crystallized Void in areas under assault by N'Zoth's forces. Progress: Did you bring more void crystals?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174771, 174993 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58806] = { ["id"] = 58806, ["name"] = "Warmth of the Sun", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58806 }, ["description"] = "The desert nights in Uldum can get awfully cold. I fear for our little egg's ability to withstand these temperatures. These Amathet to the East seem to have mastered the harnessing of the sun's energy. If we could borrow some of their expertise, we could use it to keep the egg nice and cozy. Keep your eyes open for something we can use.", ["objectivesText"] = "Collect an Amathet Solar Collector in Uldum . Progress: Did you find anything among the Amathet?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 174996 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58807] = { ["id"] = 58807, ["name"] = "Wrapping Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58807 }, ["description"] = "One oddity I have observed about this egg is that it lacks the protective webbing commonly found throughout the aqir hives. I believe this webbing has protective qualities, and could be beneficial to our egg if we can acquire some. While you're out fighting the insects, see if you can't bring back some of their webbing so we can make a proper cocoon for our growing egg.", ["objectivesText"] = "Collect 30 pieces of Aqir Webbing from aqir casters in Uldum . Progress: Did you find some suitable webbing?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 175001 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58808] = { ["id"] = 58808, ["name"] = "Encased in Amber", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58808 }, ["description"] = "You know who would probably know a lot about how to properly incubate this egg? The mantid! Of course, they're too busy trying to kill us to share their expertise, but there might be another way to benefit from their knowledge! Perhaps we could repurpose one of their incubation chambers. That could help speed up this process, I'm sure! If you could find and mark one for me, I could airlift it out of there.", ["objectivesText"] = "Mark an Amber Incubator for H'partho to airlift in the Vale of Eternal Blossoms.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58809] = { ["id"] = 58809, ["name"] = "A Shocking Technique", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58809 }, ["description"] = "I have heard tales that the mogu use lightning to speed up the growth of their cloud serpents. I wonder if the same principle could be used for our aqir friend? There's only one way to find out! Go to the Vale of Eternal Blossoms and see if you can get the parts together so we can create our own lightning rods. If they work the same as they do for the cloud serpents, it should speed up the hatching process significantly.", ["objectivesText"] = "Collect 8 Lightning Rod Components from the Vale of Eternal Blossoms. Progress: Were you able to collect the proper components?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 175003 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58810] = { ["id"] = 58810, ["name"] = "Coming Out of His Shell", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58810 }, ["description"] = "It looks like our egg is ready to hatch! Isn't this exciting! Come, let us welcome our new little friend to this world.", ["objectivesText"] = "Watch the Aqir Egg hatch in Ramkahen. Progress: Oh, the anticipation!", ["rewardGold"] = 468000, ["rewardXP"] = 8520, ["rewardItems"] = { 175063 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58811] = { ["id"] = 58811, ["name"] = "A Balanced Diet", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58811 }, ["description"] = "Now that our larva is hatched, we'll need to figure out what we can feed it to keep it healthy. It would seem that the aqir are carnivores, but the only things I've seen them eat are... well... us. Of course, we can't feed our little friend people, so we'll have to find an alternative. Perhaps we could substitute animal meat?", ["objectivesText"] = "Collect 12 Chunks of Meat from beasts in Uldum and the Vale of Eternal Blossoms. Progress: He looks hungry, I hope you brought a snack.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 175014 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58812] = { ["id"] = 58812, ["name"] = "Meat Alternatives", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58812 }, ["description"] = "In the wild it is actually fairly common for insects to eat others of their species. I wonder if this rings true for the aqir as well. Could you bring back some meat from the aqir or mantid? We'll see if that's more palatable for our friend here.", ["objectivesText"] = "Collect 12 pieces of Insectoid Meat from Aqir, Mantid, or other insects in Uldum or the Vale of Eternal Blossoms. Progress: I do hope this works.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175015 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58813] = { ["id"] = 58813, ["name"] = "Fetid Filets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58813 }, ["description"] = "You know, it occurred to me that since this creature has been imbued with void energy, it may prefer a more... corrupted food source. I speak, of course, of the Minions of N'Zoth. It's a long shot, but it's worth a try.", ["objectivesText"] = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions. Progress: Who knew aqir would be such picky eaters?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 175016 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58817] = { ["id"] = 58817, ["name"] = "Action Figures", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58817 }, ["description"] = "It occurs to me that our larva's current living situation is quite dull. We should try to find something to keep him entertained. After all, a happy larva is a healthy larva! I think the Amathet keep figures for worship of their gods. I'm sure they could also double as toys for our little friend here. See if you can find some!", ["objectivesText"] = "Collect 6 Amathet Figurines from Amathet creatures in Uldum . Progress: Did you find any suitable toys?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 175020 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58818] = { ["id"] = 58818, ["name"] = "Bug Buddies", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58818 }, ["description"] = "Is it just me or does our little friend look lonely? It would make sense that aqir are social creatures, coming from a hive and all. It must be difficult for him not being around any of his kind. You know, maybe you could find some friends for him. Nothing big and scary, of course, but perhaps some of the smaller scarabs could be safe enough to keep him company. What do you think?", ["objectivesText"] = "Catch 5 Docile Sandstone Hatchlings in Uldum .", ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58825] = { ["id"] = 58825, ["name"] = "Super Jelly", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58825 }, ["description"] = "My friends in the Golden Lotus have been telling me some interesting things about the new mantid swarm. Apparently they have developed a concentrated royal jelly that accelerates the growth of newly hatched mantid. If this jelly works on mantid, logic would suggest it would work on aqir as well! See if you can find a sufficient sample of this jelly to help with our larva's growth.", ["objectivesText"] = "Collect 8 Concentrated Royal Jelly in the Vale of Eternal Blossoms. Progress: This gets me thinking. After we've raised this one, I wonder if we could hatch a mantid as well?", ["rewardGold"] = 262100, ["rewardXP"] = 6815, ["rewardItems"] = { 175022 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58826] = { ["id"] = 58826, ["name"] = "A Bloody Treat", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 9105, ["mapID"] = 1527, ["storyline"] = { 58826 }, ["description"] = "I have heard that a clan of the mogu called the Dokani have mastered the harnessing of life force into a substance they call \"anima.\" If this stuff is indeed life condensed into a liquid form, then it could have spectacular properties when applied to our aqir larva. Go see if you can bring back some of this anima in a form that we can use. We'll see if our little friend here likes it!", ["objectivesText"] = "Collect 8 Vials of Purified Anima from Dokani mogu in the Vale of Eternal Blossoms. Progress: Have you returned with the anima?", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 175023 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 9105 } }, ["questType"] = "standard" },
[58829] = { ["id"] = 58829, ["name"] = "They Grow So Fast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58829 }, ["description"] = "Look! Our little larva friend has entered the pupa stage! Wait... it looks like he's ready to emerge. Go on, give him a hand!", ["objectivesText"] = "Help the Aqir Larva emerge from its cocoon in Ramkahen. Progress: Take care, our friend is likely still very fragile.", ["rewardGold"] = 619600, ["rewardXP"] = 8520, ["rewardItems"] = { 13086, 46102, 69986, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58830] = { ["id"] = 58830, ["name"] = "Aqir Instincts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58830 }, ["description"] = "In observing the aqir battling the Wastewanders, I have seen the newly hatched immediately join the aqiri assault. It would seem the need for combat is born into these creatures. We should exercise this in our new hatchling, under your supervision of course. Take him out with you and show him how to fight our enemies. He may not be able to fight for long, so don't call him until you're ready for training. With luck, he will come to see us as part of his hive.", ["objectivesText"] = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster. Progress: Take care of your hatchling. He will return here if he becomes too injured.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 175055 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58831] = { ["id"] = 58831, ["name"] = "Honing Instincts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58831 }, ["description"] = "It looks like our little friend is anxious and ready to practice more combat. Would you care to show him the ropes?", ["objectivesText"] = "Use H'partho's Whistle to summon your Aqir Hatchling and battle enemies in Uldum or Vale of Eternal Blossoms. Fighting tougher and rarer enemies will help your hatchling grow faster. Progress: How goes the training?", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["rewardItems"] = { 174771, 175055, 175140, 175142 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58858] = { ["id"] = 58858, ["name"] = "More Fetid Filets", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58858 }, ["description"] = "Our little guy is getting hungry again. Could you pick him up a quick bite to eat?", ["objectivesText"] = "Collect 12 pieces of Corrupted Flesh from creatures in areas under assault by N'Zoth's minions. Progress: My, this thing has an appetite.", ["rewardItems"] = { 175015, 175016, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58859] = { ["id"] = 58859, ["name"] = "Someone His Own Size", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58859 }, ["description"] = "While fighting alongside you no doubt provides excellent training for our hatchling, sometimes it is better to have him fight on his own against enemies his own size. I know of one such opponent nearby, observing the Amathet near the Obelisk of the Stars. You should seek it out.", ["objectivesText"] = "Defeat Retinus the Seeker in a pet battle with your Shadowbarb Hatchling in your party.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 33226, 71033, 151269, 172016, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58860] = { ["id"] = 58860, ["name"] = "Big Bad Beetle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58860 }, ["description"] = "It could do our hatchling some good to face off against another aqir, to learn what his kind are capable of. I have found an opponent who could provide a challenging fight.", ["objectivesText"] = "Defeat the Aqir Sandcrawler in a pet battle with your Shadowbarb Hatchling in your party.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 94126, 163819, 167054, 175049, 186549, 188679 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58861] = { ["id"] = 58861, ["name"] = "The Mantids' Mettle", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58861 }, ["description"] = "Observing the combat techniques of the mantid may prove helpful for our hatchling's training, offering a different way to use the natural weapons of an insect. I have found a mantid opponent that our hatchling could face in the Vale of Eternal Blossoms. Take him there and see how he does.", ["objectivesText"] = "Defeat the Vil'thik Hatchling in a pet battle with your Shadowbarb Hatchling in your party. Progress: How did our hatchling fare against the mantid?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 122457, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58862] = { ["id"] = 58862, ["name"] = "The Littlest Defender", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58862 }, ["description"] = "The Baruk mogu are known for animating ancient statues to serve as defenders of their territory. They are a resilient foe, and much can be learned from battling an enemy with such rigid defenses. Fortunately, it seems like one of their Stoneshapers mistakenly animated a small idol. It has been discarded as useless to the mogu who made it, but it could prove a valuable training opportunity for our hatchling. Find this miniature defender in the Vale of Eternal Blossoms.", ["objectivesText"] = "Defeat the Baruk Stone Defender in a pet battle with your Shadowbarb Hatchling in your party.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 71076, 113554, 163684, 163819, 175049 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58863] = { ["id"] = 58863, ["name"] = "A Custom Order", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58863 }, ["description"] = "I think it's safe to say that our little friend is no long a hatchling, but a fully grown aqir! He's grown so much, in fact, he could even carry you into battle. Wait, that's a marvelous idea! You should speak with Blacksmith Abasi about getting a saddle made.", ["objectivesText"] = "Speak with Blacksmith Abasi in Ramkahen. Progress: What do you need?", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.556, ["y"] = 0.352 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58865] = { ["id"] = 58865, ["name"] = "Otherworldly Armaments", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58865 }, ["description"] = "To craft a saddle for your beast, I'll need some special materials. Mainly, it will require metals much lighter than what we have available. I have noticed that the Black Empire cultists carry with them weapons made from otherworldly materials, which are impossibly light and strong. If you could retrieve some of their weapons for me, I may be able to melt down this metal and shape it into a saddle for the aqir.", ["objectivesText"] = "Collect 12 Black Empire Armaments from Black Empire cultists in Uldum and the Vale of Eternal Blossoms. Progress: Have you found my materials?", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["rewardItems"] = { 175058 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58866] = { ["id"] = 58866, ["name"] = "My Own Drone", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58866 }, ["description"] = "The saddle is complete. I can't say I enjoyed working with that corrupted metal, but in the end I can easily say this is the finest saddle I have ever crafted. I know it looks... aggressive, but I assure you that your aqir will find it quite comfortable. I hope it serves you well.", ["objectivesText"] = "Bring the Otherworldly Saddle to H'Partho Adoros in Ramkahen. Progress: Was the blacksmith able to help?", ["rewardGold"] = 524200, ["rewardXP"] = 8520, ["rewardItems"] = { 174771, 175059 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 164250, ["x"] = 0.54, ["y"] = 0.334 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 161738, ["x"] = 0.556, ["y"] = 0.352 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.54, ["y"] = 0.334 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58876] = { ["id"] = 58876, ["name"] = "Lost Flight", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58876 }, ["description"] = "<A small dragon emerges from one of the side chambers found within N'Zoth's great carapace. It appears confused. You surmise that such chambers must have been used to corrupt the dragons, exposing them directly to N'Zoth's dark whispers. At a young age, they would be driven mad, moreso than any other members of the twilight dragonflight that you had met before. There would be no turning back from such madness. But maybe it's not too late for this one...>", ["objectivesText"] = "Bring the Spawn of Vexiona to Wrathion in the Chamber of Heart. Provided item:", ["rewardItems"] = { 174862, 174863 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["startItems"] = { 174863 } },
[58877] = { ["id"] = 58877, ["name"] = "Death's Power Grows", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 12952, ["mapID"] = 1602, ["storyline"] = { 58877, 58902, 58903, 58989 }, ["description"] = "Listen closely, <name>. A time of great destruction lies on the horizon that will challenge our very existence. Now more than ever, we must rise to the defense of Azeroth. It is for this reason I have expanded the ranks of my champions to include your people. Your sacrifice sets you apart from all others. Hold your head high. Forevermore, you will be a death knight of the Ebon Blade. Now swear your fealty.", ["objectivesText"] = "Swear fealty to the Lich King . Progress: Swear your fealty, <name>.", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["rewardItems"] = { 174485, 174486, 174487, 174488, 174659, 174660, 174661, 174662 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12952 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2297, ["db2PoiUiMapID"] = 1602, ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 0, ["flags"] = 0 } } },
[58879] = { ["id"] = 58879, ["name"] = "Alpaca It Up", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58879 }, ["objectivesText"] = "Progress: <Sniffs curiously in the general direction of your backpack, eyeing it intently.>", ["rewardGold"] = 257400, ["rewardXP"] = 1705, ["rewardItems"] = { 174858, 174859 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 162765, ["x"] = 0.469814, ["y"] = 0.421349 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 162765, ["x"] = 0.469814, ["y"] = 0.421349 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.469814, ["y"] = 0.421349 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58887] = { ["id"] = 58887, ["name"] = "Alpaca It In", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1527, ["storyline"] = { 58887 }, ["rewardGold"] = 257400, ["rewardXP"] = 3410, ["rewardItems"] = { 174859 }, ["starts"] = { { ["mapID"] = 1527, ["npcID"] = 162765, ["x"] = 0.469814, ["y"] = 0.421349 } }, ["ends"] = { { ["mapID"] = 1527, ["npcID"] = 162765, ["x"] = 0.469814, ["y"] = 0.421349 } }, ["coords"] = { ["mapID"] = 1527, ["source"] = "quest_giver", ["x"] = 0.469814, ["y"] = 0.421349 }, ["mapCandidates"] = { ["npc"] = { 1527 }, ["zone"] = { 10833 } }, ["questType"] = "standard" },
[58902] = { ["id"] = 58902, ["name"] = "Defender of Azeroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 12952, ["mapID"] = 1602, ["storyline"] = { 58877, 58902, 58989 }, ["description"] = "An excellent choice. Troubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor. But also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done. Speak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", ["objectivesText"] = "Speak with Highlord Darion Mograine . Then, use the highlord's death gate to travel to Stormwind. Once there, visit Chromie .", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12952 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2297, ["db2PoiUiMapID"] = 1602, ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 1, ["flags"] = 0 } } },
[58903] = { ["id"] = 58903, ["name"] = "Defender of Azeroth", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 12952, ["mapID"] = 1602, ["storyline"] = { 58877, 58903, 58989 }, ["description"] = "An excellent choice. Troubling times come. As one of the chosen few, it is both your burden and privilege to defend our world. It is a great honor. But also know you will be met with the scorn of the ignorant. Oftentimes, mortals are incapable of seeing past our fearsome appearance. Ignore these fools and do what must be done. Speak with your commander. Then, use his death gate to travel to the land of the living and choose your destiny.", ["objectivesText"] = "Speak with Highlord Darion Mograine . Then, use the highlord's death gate to travel to Orgrimmar. Once there, talk to Chromie .", ["rewardGold"] = 1000, ["rewardXP"] = 710, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12952 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2297, ["db2PoiUiMapID"] = 1602, ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 2, ["flags"] = 0 } } },
[58904] = { ["id"] = 58904, ["name"] = "Shards of Corruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "daily", "repeatable" }, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["storyline"] = { 58904 }, ["description"] = "<You feel the pull of something dark and inhuman on your mind, it's writhing tendrils digging in, tugging at your sanity. You feel compelled to collect more shards... all of them.>", ["objectivesText"] = "Collect 20 Shards of Corruption . Progress: <The Idol tugs at your very being. Demanding you to touch it.>", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["rewardItems"] = { 174867 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questType"] = "pvp", ["startItems"] = { 174867 } },
[58952] = { ["id"] = 58952, ["name"] = "Purging Flames", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 10833, ["mapID"] = 1530, ["storyline"] = { 58952 }, ["rewardGold"] = 280900, ["rewardXP"] = 6140, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10833 } }, ["questType"] = "world", ["db2PoiMapID"] = 870, ["db2PoiUiMapID"] = 1530, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[58989] = { ["id"] = 58989, ["name"] = "Runeforging 101", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["requiredClasses"] = { 6 }, ["categories"] = {}, ["flags"] = { "class" }, ["sharable"] = true, ["expansion"] = 7, ["zoneID"] = 7543, ["mapID"] = 23, ["storyline"] = { 58877, 58902, 58903, 58989 }, ["description"] = "As knights of the Ebon Blade, we must always be prepared for a variety of martial situations. To this end, the dark art of runeforging is yours to command. With it, runes of great power can be engraved upon your weapons. Above us in the Heart of Acherus are runeforges. Visit one and use your power to imbue a weapon with a rune of power.", ["objectivesText"] = "Use the Runeforging ability in your spellbook to engrave a rune upon your weapon. You may freely replace the engraving at any time, so long as you are near a Runeforge. Progress: Have you emblazoned a rune upon your weapon, <name>?", ["rewardGold"] = 154900, ["rewardXP"] = 710, ["starts"] = { { ["mapID"] = 23, ["npcID"] = 29246, ["x"] = 0.82, ["y"] = 0.465 } }, ["ends"] = { { ["mapID"] = 23, ["npcID"] = 29246, ["x"] = 0.82, ["y"] = 0.465 } }, ["coords"] = { ["mapID"] = 23, ["source"] = "quest_giver", ["x"] = 0.82, ["y"] = 0.465 }, ["mapCandidates"] = { ["npc"] = { 23 }, ["zone"] = { 7543 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 648, ["questLines"] = { { ["id"] = 1035, ["name"] = "Death's Power Grows", ["orderIndex"] = 3, ["flags"] = 0 } } },
[59000] = { ["id"] = 59000, ["name"] = "Elements of Corruption", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 7, ["zoneID"] = 9667, ["mapID"] = 84, ["storyline"] = { 59000 }, ["description"] = "Corruption behaves in mysterious ways. It spreads beyond Azeroth herself, touching our most intimate thoughts and sometimes corrupting various relics, as you've seen firsthand. Though I cannot speak to the effects of these matters directly, I am sure MOTHER has information surrounding these so-called items of corruption.", ["objectivesText"] = "Speak with MOTHER to learn about corrupted items. Progress: What have you discovered?", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 155496, ["x"] = 0.846, ["y"] = 0.3295 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.846, ["y"] = 0.3295 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 9667 } }, ["questType"] = "standard" },
